void NodeSerializer::DefineDbNode(TqApiNodeDb& node) {
  AddDbChild<TqApiNodeDb, LoginContent>(node, "login");
  AddDbChild<TqApiNodeDb, Account>(node, "accounts");
  AddDbChild<TqApiNodeDb, Position>(node, "positions");
  AddDbChild<TqApiNodeDb, Order>(node, "orders");
  AddDbChild<TqApiNodeDb, Trade>(node, "trades");
  AddDbChild<TqApiNodeDb, Rate>(node, "rate");
  AddDbChild<TqApiNodeDb, Bank>(node, "bank");
  AddDbChild<TqApiNodeDb, TransferLog>(node, "transferLog");
  AddDbChild<TqApiNodeDb, BankBalance>(node, "bankbalance");
  AddDbChild<TqApiNodeDb, Notice>(node, "notice");
  AddDbChild<TqApiNodeDb, ExecOrder>(node, "exec_orders");
  AddDbChild<TqApiNodeDb, OptionSelfClose>(node, "option_self_closes");
  AddDbChild<TqApiNodeDb, Quote>(node, "quotes");
}

