/*
 * ServiceInterface 是业务组件接口。每个 Service 是一个业务组件，它可以实现 model 中定义的某种业务模型
 */
class ServiceInterface {
 public:
  ServiceInterface();
  enum class ServiceType {
    kMarketData,
    kFuture,
    kSecurity,
  };

  /**
   * 获取服务类型.
   */
  virtual ServiceType GetServiceType() = 0;

  /**
  向 Service 提交一个指令，这些指令不是立即执行，而是在以后的 RunOnce 时执行

  @param request: 需要发出的指令
  @return: 指令执行结果跟踪节点. 不能为空.
  */
  virtual void ExecuteCommand(std::shared_ptr<UserCommand> request) = 0;

  /**
  让 Service 运行一次，执行它现在应该做的任务，包括：
  - 执行指令队列中的指令 (如果条件不合适，也可能放到以后执行)
  - 尝试主动发出查询请求，以获取或更新本地数据
  - 处理业务流水通道中收到的数据包，用这些包更新数据截面

  @return: 0 表示本次RunOnce没有执行任何业务处理, 对内存状态没有产生任何修改. >0 表示有业务处理和数据变更,
  通常表示处理的数据包数量
  */
  virtual int RunOnce() = 0;

  virtual void ResponseCommand();

  virtual void CleanUp() = 0;

  /**
   * 注册指令处理器. 每种指令只能由一个处理器负责处理.
   *
   * @param tag: 指令类的AID.
   * @param processor: 指令处理函数.
   *
   * @todo: 本函数应当定义为纯虚函数, 要求所有 Service 都实现此接口.
   */
  virtual void RegisterCommandProcessor(int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor);
  std::shared_ptr<CommandManager> m_command_manager;
};

}  // namespace fclib

#endif  // FCLIB_BASE_SERVICE_H

