/**
 * 指令执行管理器
 *
 * 参见 https://shinnytech-fclib.readthedocs-hosted.com/en/latest/client_model/framework.html
 */
class CommandManager {
 public:
  /**
   * 要求 CommandManager 记录并跟踪一个指令.
   *
   * @param command: 一个指令.
   * @return: 指令跟踪节点.
   */
  void Store(std::shared_ptr<UserCommand> command);

  /**
   * 为指令设置一个唯一ID, 这个ID可以在之后用于调用 UpdateCommand.
   */
  void SetCommandId(std::shared_ptr<UserCommand> command, const std::string& command_id);

  /**
   * 更新 Command 进展.
   *
   * @param command_id: 指令ID
   * @return: 指令. 若 command_id 在存储中不存在, 返回 nullptr.
   */
  std::shared_ptr<UserCommand> Update(std::shared_ptr<UserCommand> command);
  std::shared_ptr<UserCommand> Update(const std::string& command_id);

  /**
   * 根据command_id返回command
   */
  std::shared_ptr<UserCommand> Get(const std::string& command_id);

  /**
   * 指令执行反馈提交记录, 通知所有监听方.
   */
  void CommitResponse();

 private:
  struct Item {
    std::shared_ptr<UserCommand> command;
    Timer process_expire_timer;
  };

  std::map<std::shared_ptr<UserCommand>, std::shared_ptr<Item>> m_all_commands; /** 完结的command将会被删除 */
  std::map<std::string, std::shared_ptr<Item>> m_command_id_map;                /** 现在尚未进行删除 */
  std::set<std::shared_ptr<Item>> m_changing_commands;
};

}  // namespace fclib

#endif  // FCLIB_COMMAND_MANAGER_H

/*******************************************************************************
 * @file command_manager.cpp
 * @brief 指令管理
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "command_manager.h"

#include <cassert>
#include <utility>
#include <memory>
#include <string>
#include <chrono>

namespace fclib {

void CommandManager::Store(std::shared_ptr<UserCommand> command) {
  if (!command)
    return;
  auto item = std::make_shared<Item>();
  item->command = command;
  m_all_commands[command] = item;
  m_changing_commands.insert(item);
}

void CommandManager::SetCommandId(std::shared_ptr<UserCommand> command, const std::string& command_id) {
  auto it = m_all_commands.find(command);
  if (it == m_all_commands.end())
    return;
  m_command_id_map[command_id] = it->second;
}

void CommandManager::CommitResponse() {
  // 有变的项重置超时定时器
  for (auto& item : m_changing_commands) {
    if (item->command->status == UserCommand::Status::kStarted) {
      item->process_expire_timer.Reset(std::chrono::milliseconds(item->command->time_out_interval));
    }
  }
  for (auto it = m_all_commands.begin(); it != m_all_commands.end();) {
    auto item = it->second;
    auto command = item->command;
    // 超时的项标记超时
    if (command->status == UserCommand::Status::kStarted && item->process_expire_timer.IsExpired()) {
      command->status = UserCommand::Status::kFinished;
      command->result_code = -9999;
      command->result_msg = u8"fclib: 指令执行超时";
    }
    // 已完结的项删除
    if (command->status == UserCommand::Status::kFinished) {
      it = m_all_commands.erase(it);
      continue;
    }
    ++it;
  }
  m_changing_commands.clear();
}

std::shared_ptr<UserCommand> CommandManager::Update(const std::string& command_id) {
  auto it = m_command_id_map.find(command_id);
  if (it == m_command_id_map.end())
    return nullptr;
  auto item = it->second;
  m_changing_commands.insert(item);
  return item->command;
}

std::shared_ptr<UserCommand> CommandManager::Update(std::shared_ptr<UserCommand> command) {
  if (!command)
    return nullptr;
  auto it = m_all_commands.find(command);
  if (it == m_all_commands.end())
    return nullptr;
  auto item = it->second;
  m_changing_commands.insert(item);
  return item->command;
}

std::shared_ptr<UserCommand> CommandManager::Get(const std::string& command_id) {
  auto it = m_command_id_map.find(command_id);
  if (it == m_command_id_map.end())
    return nullptr;
  auto item = it->second;
  return item->command;
}

}  // namespace fclib

