size_t WriteCallback(void* data, size_t size, size_t nmemb, void* userp) {
  ((std::string*)userp)->append(static_cast<char*>(data), size * nmemb);
  return size * nmemb;
}

std::tuple<CURLcode, int, std::string> HttpsPost(CURL* pSession, const std::string& url, const std::string& url_body) {
  std::string* pstr = new std::string();
  int status_code = 0;
  curl_easy_reset(pSession);
  curl_easy_setopt(pSession, CURLOPT_URL, url.c_str());
  curl_easy_setopt(pSession, CURLOPT_TIMEOUT, 10);  // 设置超时时间
  curl_easy_setopt(pSession, CURLOPT_SSL_VERIFYHOST, 2L);
  curl_easy_setopt(pSession, CURLOPT_SSL_VERIFYPEER, 0L);

  curl_easy_setopt(pSession, CURLOPT_POST, 1);
  if (!url_body.empty()) {
    curl_easy_setopt(pSession, CURLOPT_POSTFIELDS, url_body.c_str());
  }

  curl_easy_setopt(pSession, CURLOPT_WRITEFUNCTION, &WriteCallback);
  curl_easy_setopt(pSession, CURLOPT_WRITEDATA, pstr);

  CURLcode res = curl_easy_perform(pSession);
  if (res == CURLE_OK) {
    curl_easy_getinfo(pSession, CURLINFO_RESPONSE_CODE, &status_code);
  }

  std::string rsp(pstr->c_str());
  delete pstr;

  return {res, status_code, rsp};
}

ShinnyIdImpl::ShinnyIdImpl(structlog::Logger& parent_logger, const std::string& client_id,
  const std::string& client_secret, const std::string& auth_url, const std::filesystem::path& cache_file)
  : m_client_id(client_id)
  , m_client_secret(client_secret)
  , m_auth_url(auth_url)
  , m_logger(parent_logger.With("c2", "shinnyid").Clone()) {
  m_cache_file = cache_file;
  if (m_auth_url.empty())
    m_auth_url = "https://auth.shinnytech.com/auth/realms/shinnytech/protocol/openid-connect/token";
}

void ShinnyIdImpl::Init() {
  if (m_cache_file.empty())
    return;
  std::ifstream fin = std::ifstream(m_cache_file, std::ios_base::binary);
  if (!fin.is_open())
    return;
  std::stringstream fin_buffer;
  fin_buffer << fin.rdbuf();
  ParseCache(fin_buffer.str());
}

bool ShinnyIdImpl::PostToken(const std::string& name, const std::string& pwd, std::string& rsp_body) {
  CURL* pCurlSession = curl_easy_init();
  char* encoded_username = curl_easy_escape(pCurlSession, name.c_str(), 0);
  char* encoded_password = curl_easy_escape(pCurlSession, pwd.c_str(), 0);
  std::string url_body = "grant_type=password&client_id=" + m_client_id + "&client_secret=" + m_client_secret
    + "&username=" + encoded_username + "&password=" + encoded_password;

  auto [res, status_code, rsp] = HttpsPost(pCurlSession, m_auth_url, url_body);
  curl_free(encoded_username);
  curl_free(encoded_password);
  curl_easy_cleanup(pCurlSession);
  if (res != CURLE_OK) {
    rsp_body = curl_easy_strerror(res);
    return false;
  }
  if (status_code / 100 != 2) {
    ptree json_result;
    std::istringstream is(rsp);
    try {
      read_json(is, json_result);
    } catch (const boost::property_tree::json_parser::json_parser_error&) {
      rsp_body = "未知错误, 状态码: " + std::to_string(status_code);
      return false;
    }
    if (json_result.count("error_description")) {
      rsp_body = json_result.get<std::string>("error_description");
    }
    // 当密码不符合要求可能会被 apigateway 直接拒绝
    if (status_code == 422 && json_result.count("errors")) {
      ptree errors = json_result.get_child("errors");
      for (ptree::iterator it = errors.begin(); it != errors.end(); ++it) {
        std::string field = it->second.get<std::string>("field");
        if (field.compare("password") == 0) {
          rsp_body = "密码不符合规则要求, 仅支持大小写字母、数字和字符(~!@#$%^&*_-+='|(){}[]:;'<>,.?)";
        }
      }
    }
    m_logger.With("status_code", status_code)
      .With("error_description", structlog::make_json(rsp))
      .Warning("用户认证失败.");
    return false;
  }

  rsp_body = rsp;
  return true;
}

bool ShinnyIdImpl::RefreshToken() {
  if (!m_refresh_token_valid) {
    return false;
  }
  CURL* pCurlSession = curl_easy_init();
  auto url_body = "grant_type=refresh_token&client_id=" + m_client_id + "&client_secret=" + m_client_secret
    + "&refresh_token=" + m_refresh_token;
  auto [res, status_code, rsp] = HttpsPost(pCurlSession, m_auth_url, url_body);
  curl_easy_cleanup(pCurlSession);
  if (res != CURLE_OK || status_code / 100 != 2) {
    return false;
  }
  if (!ParseToken(rsp)) {
    return false;
  }
  TokenToCache();
  return true;
}

bool ShinnyIdImpl::Auth(
  const std::string& user_name, const std::string& password, std::string& msg, const std::string& token) {
  std::string jwt(token);

  if (jwt.empty()) {
    bool ok = PostToken(user_name, password, jwt);
    if (!ok) {
      msg = jwt;
      m_err_msg = jwt;
      return false;
    }
  }

  if (ParseToken(jwt)) {
    TokenToCache();
  } else {
    msg = m_err_msg;
  }
  return m_token_valid;
}

void ShinnyIdImpl::Logout() {
  ResetContent();
  if (!m_cache_file.empty())
    std::filesystem::remove(m_cache_file);
}

void ShinnyIdImpl::TokenToCache() {
  if (m_cache_file.empty())
    return;
  std::ofstream fout = std::ofstream(m_cache_file);
  if (fout.is_open()) {
    ptree root;
    root.put<std::string>("jwt", m_token_text);
    std::stringstream fout_buffer;
    write_json(fout_buffer, root);
    fout << fout_buffer.rdbuf();
  }
}

bool ShinnyIdImpl::ParseCache(const std::string& cache) {
  ptree root;
  std::istringstream is(cache);
  try {
    read_json(is, root);
  } catch (const boost::property_tree::json_parser::json_parser_error&) {
    return false;
  }

  if (!root.count("jwt"))
    return false;

  auto jwt = root.get<std::string>("jwt");
  return ParseToken(jwt);
}

bool ShinnyIdImpl::ParseToken(const std::string& jwt) {
  ResetContent();

  ptree root;
  std::istringstream is(jwt);
  try {
    read_json(is, root);
  } catch (const boost::property_tree::json_parser::json_parser_error&) {
    return false;
  }

  m_access_token = root.get<std::string>("access_token");
  m_refresh_token = root.get<std::string>("refresh_token");

  // 解析 access_token
  auto decoded = jwt::decode(m_access_token);
  for (auto& e : decoded.get_payload_json()) {
    if (e.first == "exp") {
      m_access_token_expiration = e.second.get<time_t>();
    }
    if (e.first.compare("id") == 0) {
      m_user_id = e.second.get<std::string>();
    }
    if (e.first.compare("username") == 0) {
      m_user_name = e.second.get<std::string>();
    }
    if (e.first.compare("grants") == 0) {
      auto grant_obj = e.second.get<picojson::object>();
      if (grant_obj.find("features") != grant_obj.end()) {
        auto features_array = grant_obj["features"].get<picojson::array>();
        for (size_t i = 0; i < features_array.size(); i++) {
          m_grant_features.insert(features_array.at(i).to_str());
        }
      }

      if (grant_obj.find("accounts") != grant_obj.end()) {
        auto accounts_array = grant_obj["accounts"].get<picojson::array>();
        for (size_t i = 0; i < accounts_array.size(); i++) {
          m_grant_accounts.insert(accounts_array.at(i).to_str());
        }
      }

      if (grant_obj.find("brokers") != grant_obj.end()) {
        auto brokers_array = grant_obj["brokers"].get<picojson::array>();
        for (size_t i = 0; i < brokers_array.size(); i++) {
          std::string broker_id = brokers_array.at(i).to_str();
          if (!broker_id.empty() && broker_id != "*")
            m_grant_brokers.insert(broker_id);
        }
      }

      if (grant_obj.find("expiry_date") != grant_obj.end()) {
        m_expiry_date = grant_obj["expiry_date"].to_str();
      }
    }
  }
  m_token_valid = ValidateAccessToken();

  // 解析 refresh_token
  auto decoded_refresh_token = jwt::decode(m_refresh_token);
  for (auto& e : decoded_refresh_token.get_payload_json()) {
    if (e.first == "exp") {
      m_refresh_token_expiration = e.second.get<time_t>();
    }
  }
  m_refresh_token_valid = ValidateRefreshToken();

  m_token_text = jwt;
  return m_token_valid;
}

bool ShinnyIdImpl::ValidateAccessToken() {
  if (m_access_token.empty() || m_access_token_expiration == 0) {
    return false;
  }
  time_t tmNow;
  time(&tmNow);
  if (tmNow > m_access_token_expiration) {
    return false;
  }
  return true;
}

bool ShinnyIdImpl::ValidateRefreshToken() {
  if (m_refresh_token.empty() || m_refresh_token_expiration == 0) {
    return false;
  }
  time_t tmNow;
  time(&tmNow);
  if (tmNow > m_refresh_token_expiration) {
    return false;
  }
  return true;
}

void ShinnyIdImpl::ResetContent() {
  m_token_valid = false;
  m_refresh_token_valid = false;
  m_access_token_expiration = 0;
  m_refresh_token_expiration = 0;
  m_token_text.clear();
  m_access_token.clear();
  m_refresh_token.clear();
  m_user_id.clear();
  m_user_name.clear();
  m_expiry_date.clear();
  m_grant_features.clear();
  m_grant_accounts.clear();
  m_grant_brokers.clear();
}

bool ShinnyIdImpl::IsValid() {
  return m_token_valid;
}

bool ShinnyIdImpl::HasGrant(const std::string& key) {
  return IsValid() && m_grant_features.find(key.c_str()) != m_grant_features.end();
}

std::string ShinnyIdImpl::GetUserId() {
  return m_user_id;
}

std::string ShinnyIdImpl::GetUsername() {
  return m_user_name;
}

std::string ShinnyIdImpl::GetAccessToken() {
  return m_access_token;
}

std::string ShinnyIdImpl::GetExpiryDate() {
  return m_expiry_date;
}

bool ShinnyIdImpl::HasAccountGranted(const std::string& account) {
  return IsValid() && m_grant_accounts.find(account.c_str()) != m_grant_accounts.end();
}

bool ShinnyIdImpl::HasBroker(const std::string& broker_id) {
  if (m_grant_brokers.empty()) {
    return true;
  }
  return m_grant_brokers.find(broker_id) != m_grant_brokers.end();
}

