md::EpochNano GetTradingDayEnd(md::EpochNano timestamp) {
  auto begin_mark = 631123200000000000;
  auto days = (timestamp - begin_mark) / 86400000000000;
  if ((timestamp - begin_mark) % 86400000000000 >= 64800000000000) {
    days++;
  }
  auto week_day = days % 7;
  if (week_day >= 5) {
    days = days + 7 - week_day;
  }
  return begin_mark + days * 86400000000000 + 64799999999999;
}

bool TradingDayChanged(md::EpochNano time_end) {
  return NowAsEpochNano() > time_end;
}

std::string GetDate(md::EpochNano datetime) {
  auto time_s = EpochNanoToLocalDateTime(datetime, 8);
  char trading_day[26];
  if (snprintf(trading_day, sizeof(trading_day), "%04d%02d%02d", (time_s.date_time.tm_year + 1900),
        (time_s.date_time.tm_mon + 1), time_s.date_time.tm_mday)
    <= 0)
    return "";
  return std::string(trading_day);
}

double GetDividendRatio(const std::map<std::string, double>& ratio_table, md::EpochNano datetime) {
  if (ratio_table.empty())
    return 0.0;
  auto date = GetDate((GetTradingDayEnd(datetime)));
  auto iter = ratio_table.find(date);
  return (iter != ratio_table.end()) ? iter->second : 0.0;
}

double GetStockDividend(std::shared_ptr<md::InstrumentNode> ins_node) {
  return GetDividendRatio(ins_node->Latest()->instrument_base->stock_dividend_ratio, NowAsEpochNano());
}

double GetCashDividend(std::shared_ptr<md::InstrumentNode> ins_node) {
  return GetDividendRatio(ins_node->Latest()->instrument_base->cash_dividend_ratio, NowAsEpochNano());
}

bool IsMarketOrder(std::shared_ptr<const Order> order) {
  return order->price_type == PriceType::kAny;
}

double GetOrderPrice(std::shared_ptr<Order> order) {
  if (IsMarketOrder(order) && order->ins_pointer) {
    return (order->direction == Direction::kBuy) ? order->ins_pointer->Latest()->ask_price[0]
                                                 : order->ins_pointer->Latest()->bid_price[0];
  }
  return order->limit_price;
}

double GetSecurityFee(const Direction& direction, int volume, double price) {
  // 买入费用 = 佣金;
  // 卖出费用 = 佣金 + 印花税
  // 万 2.5 佣金费率, 单笔佣金最低 5 元
  FCASSERT(direction != Direction::kInvalid);
  if (isnan(price))
    return NAN;
  double balance = volume * price;
  return std::max(balance * 0.00025, 5.0) + ((direction == Direction::kBuy) ? 0.0 : balance * 0.001);
}

bool IsOrderTraded(double trade_price, std::shared_ptr<const security::Order> order) {
  if (order->direction == Direction::kInvalid)
    return false;
  if (order->direction == Direction::kBuy && trade_price > order->limit_price)
    return false;
  if (order->direction == Direction::kSell && trade_price < order->limit_price)
    return false;
  return true;
}

bool IsAccountUpdated(std::shared_ptr<const Account> account, double market_value, double cost,
  double float_profit_today, double real_profit_today) {
  return std::fabs(account->market_value - market_value) > 1e-5 || std::fabs(account->cost - cost) > 1e-5
    || std::fabs(account->float_profit_today - float_profit_today) > 1e-5
    || std::fabs(account->real_profit_today - real_profit_today) > 1e-5;
}

bool IsPositionUpdated(std::shared_ptr<const Position> position) {
  FCASSERT(position->ins_pointer);
  auto last_price = isnan(position->ins_pointer->Latest()->last_price) ? position->ins_pointer->Latest()->pre_close
                                                                       : position->ins_pointer->Latest()->last_price;
  // 最新价发生更新, 需要刷新
  if (std::fabs(last_price - position->last_price) > 1e-5)
    return true;
  return false;
}

SecurityLocalSimServiceImpl::SecurityLocalSimServiceImpl(const std::string& user_key,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<ServiceInterface> md_service, structlog::Logger& parent_logger)
  : m_user_key(user_key)
  , m_node_db(node_db)
  , m_md_service(md_service)
  , m_logger(parent_logger.With("c2", "security").With("c3", "local-sim").Clone())
  , m_status(LocalSimStatus::kBeforeLogin) {
  FCASSERT(!m_user_key.empty());
  m_last_order_id = 0;
  m_last_order_seq_no = 0;
  m_last_trade_seq_no = 0;
  m_cnt = 0;
  m_alive_order_view = m_node_db->CreateView<security::Order>([=](std::shared_ptr<const security::Order> order) {
    return order->user_key == m_user_key && order->status == OrderStatus::kAlive;
  });
  m_position_view = m_node_db->CreateView<security::Position>([=](std::shared_ptr<const security::Position> position) {
    return position->user_key == m_user_key;
  });
  m_trading_day_end = GetTradingDayEnd(NowAsEpochNano());
}

void SecurityLocalSimServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  SetCommandStarted(command);
  switch (command->aid) {
    case security::ReqLogin::AID: {
      ReqLogin(command);
      break;
    }
    case security::InsertOrder::AID: {
      ReqInsertOrder(command);
      break;
    }
    case security::CancelOrder::AID: {
      ReqCancelOrder(command);
      break;
    }
    case security::ReqTransfer::AID: {
      ReqTransferMoney(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"找不到此指令实现");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

int SecurityLocalSimServiceImpl::RunOnce() {
  m_cnt = 0;
  if (m_status == LocalSimStatus::kBeforeInit) {
    RspLogin();
    m_cnt++;
  }
  // 非登录状态, 不执行任何指令
  if (m_status != LocalSimStatus::kLogined)
    return m_cnt;
  // 跨日结算
  if (TradingDayChanged(m_trading_day_end)) {
    Settle();
    m_cnt++;
  }
  // 处理所有的请求队列
  while (!m_command_queue.empty()) {
    ProcessCommand(m_command_queue.front());
    m_command_queue.pop();
    m_cnt++;
  }
  // 撮合成交
  auto alive_order_map = m_alive_order_view->GetNodes();
  for (auto& [key, alive_order] : alive_order_map) {
    ProcessAliveOrder(alive_order);
  }
  // 实时刷新持仓和账户盈亏
  double market_value = 0.0;
  double cost = 0.0;
  double float_profit_today = 0.0;
  double real_profit_today = 0.0;
  for (auto& [_, pos_node] : m_position_view->GetNodes()) {
    UpdatePosition(pos_node->Latest());
    market_value += pos_node->Latest()->market_value;
    cost += pos_node->Latest()->cost;
    float_profit_today += pos_node->Latest()->float_profit_today;
    real_profit_today += pos_node->Latest()->real_profit_today;
  }
  // 账户盈亏更新
  auto account_key = m_user_key + "|CNY";
  auto account = m_node_db->GetNode<Account>(account_key)->Latest();
  if (IsAccountUpdated(account, market_value, cost, float_profit_today, real_profit_today)) {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->market_value = market_value;
      account->cost = cost;
      account->float_profit_today = float_profit_today;
      account->real_profit_today = real_profit_today;
      UpdateAccountField(account);
    });
    m_cnt++;
  }
  return m_cnt;
}

void SecurityLocalSimServiceImpl::ReqLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::ReqLogin>(m_command_manager->Update(command));
  m_user_id = req->user_id;
  m_status = LocalSimStatus::kBeforeInit;
  m_command_manager->SetCommandId(req, "login");
}

void SecurityLocalSimServiceImpl::ReqInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::InsertOrder>(m_command_manager->Update(command));
  std::string check_msg;
  auto ins_node = CheckInsertOrderValidity(req, &check_msg);
  if (!check_msg.empty() || !ins_node) {
    SetCommandFinished(req, -1, check_msg);
    return;
  }
  req->order_id = std::to_string(m_last_order_id++) + "." + std::to_string(req->unit_id);
  m_command_queue.push(command);
}

void SecurityLocalSimServiceImpl::ReqCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::CancelOrder>(m_command_manager->Update(command));
  auto check_msg = CheckCancelOrderValidity(req);
  if (!check_msg.empty())
    SetCommandFinished(req, -1, check_msg);
  else
    m_command_queue.push(command);
}

void SecurityLocalSimServiceImpl::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::ReqTransfer>(m_command_manager->Update(command));
  if (isnan(req->amount))
    SetCommandFinished(req, -1, u8"未输入转账金额, 无法银期转账");
  else
    m_command_queue.push(command);
}

void SecurityLocalSimServiceImpl::ProcessCommand(std::shared_ptr<UserCommand> command) {
  switch (command->aid) {
    case InsertOrder::AID: {
      RspInsertOrder(command);
      break;
    }
    case CancelOrder::AID: {
      RspCancelOrder(command);
      break;
    }
    case ReqTransfer::AID: {
      RspTransferMoney(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"找不到此指令实现");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

void SecurityLocalSimServiceImpl::RspLogin() {
  auto req =
    std::static_pointer_cast<security::ReqLogin>(m_command_manager->Update(m_command_manager->Update("login")));
  SetCommandFinished(req, 0, u8"登录成功");
  m_status = LocalSimStatus::kLogined;
  auto login = std::make_shared<LoginContent>();
  // 设置本地模拟默认参数
  login->user_key = m_user_key;
  login->currency = "CNY";
  char trading_day[26];
  char login_time[26];
  auto time_s = EpochNanoToLocalDateTime(NowAsEpochNano(), 8);
  if (snprintf(trading_day, sizeof(trading_day), "%04d-%02d-%02d", (time_s.date_time.tm_year + 1900),
        (time_s.date_time.tm_mon + 1), time_s.date_time.tm_mday)
    > 0) {
    login->trading_day = trading_day;
  }
  if (snprintf(login_time, sizeof(login_time), "%02d:%02d:%02d", time_s.date_time.tm_hour, time_s.date_time.tm_min,
        time_s.date_time.tm_sec)
    > 0) {
    login->login_time = login_time;
  }
  login->backend = BackEnd::kLocalSim;
  login->user_id = req->user_id;
  login->investor_id = req->user_id;
  login->account_ready = true;
  login->position_ready = true;
  login->session_status = SessionStatus::kLogined;
  m_node_db->ReplaceRecord<LoginContent>(login);
  // 初始化账户资金
  auto account = std::make_shared<security::Account>();
  account->user_key = m_user_key;
  account->user_id = req->user_id;
  account->investor_id = req->user_id;
  account->currency = "CNY";
  account->available_his = 10000000.0;
  account->asset_his = 10000000.0;
  UpdateAccountField(account);
  m_node_db->ReplaceRecord<Account>(account);
}

void SecurityLocalSimServiceImpl::RspInsertOrder(std::shared_ptr<UserCommand> command) {
  auto insert_order = std::static_pointer_cast<security::InsertOrder>(command);
  auto order = CreateOrder(insert_order);
  if (!CheckOrderValidity(order)) {
    order->status = OrderStatus::kDead;
    order->frozen_balance = 0.0;
    order->frozen_fee = 0.0;
  } else {
    order->exchange_order_id = order->order_id;
  }
  // 存储委托单
  auto order_node = m_node_db->ReplaceRecord<Order>(order);
  insert_order->order_pointer = order_node;
  // 下单指令反馈
  if (order->status == OrderStatus::kDead) {
    SetCommandFinished(insert_order, -1, order->status_msg);
    return;
  }
  SetCommandFinished(insert_order, 0, order->status_msg);
  // 冻结账户和持仓
  if (order->direction == Direction::kBuy) {
    m_node_db->ReplaceRecord<Account>(m_user_key + "|CNY", [&](std::shared_ptr<Account> account) {
      account->buy_frozen_fee += order->frozen_fee;
      account->buy_frozen_balance += order->frozen_balance;
      UpdateAccountField(account);
    });
  } else {
    m_node_db->ReplaceRecord<Position>(m_user_key + "|" + order->Symbol(), [&](std::shared_ptr<Position> position) {
      position->sell_volume_frozen += order->volume_orign;
    });
  }
}

void SecurityLocalSimServiceImpl::RspCancelOrder(std::shared_ptr<UserCommand> command) {
  auto cancel_order = std::static_pointer_cast<security::CancelOrder>(command);
  // 更新委托单
  auto order_key = m_user_key + "|" + cancel_order->order_id;
  auto order_node = m_node_db->GetNode<Order>(order_key);
  if (order_node->Latest()->status == OrderStatus::kDead) {
    SetCommandFinished(cancel_order, 0, u8"对应id的委托单已成交或已撤销, 无法撤单");
    return;
  }
  // 解冻账户和持仓
  if (order_node->Latest()->direction == Direction::kBuy) {
    m_node_db->ReplaceRecord<Account>(m_user_key + "|CNY", [&](std::shared_ptr<Account> account) {
      account->buy_frozen_fee -= order_node->Latest()->frozen_fee;
      account->buy_frozen_balance -= order_node->Latest()->frozen_balance;
      UpdateAccountField(account);
    });
  } else {
    m_node_db->ReplaceRecord<Position>(
      m_user_key + "|" + order_node->Latest()->Symbol(), [&](std::shared_ptr<Position> position) {
        position->sell_volume_frozen -= order_node->Latest()->volume_orign;
      });
  }
  // 更新委托单状态
  m_node_db->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<Order> o) {
    o->frozen_balance = 0.0;
    o->frozen_fee = 0.0;
    o->status = OrderStatus::kDead;
    o->status_msg = u8"撤单成功";
  });
  SetCommandFinished(cancel_order, 0, u8"撤单成功");
}

void SecurityLocalSimServiceImpl::RspTransferMoney(std::shared_ptr<UserCommand> command) {
  auto account_key = m_user_key + "|CNY";
  auto transfer = std::static_pointer_cast<security::ReqTransfer>(command);
  if (transfer->is_deposit) {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->deposit += transfer->amount;
      UpdateAccountField(account);
    });
  } else {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->withdraw += transfer->amount;
      UpdateAccountField(account);
    });
  }
  SetCommandFinished(transfer, 0, u8"转账成功");
}

bool SecurityLocalSimServiceImpl::IsLogined() {
  return m_status == LocalSimStatus::kLogined;
}

void SecurityLocalSimServiceImpl::Settle() {
  // 撤销所有未成交的委托单
  auto alive_order_map = m_alive_order_view->GetNodes();
  for (auto&& [key, _] : alive_order_map) {
    auto order_node = m_node_db->ReplaceRecord<Order>(key, [&](std::shared_ptr<Order> o) {
      o->status = OrderStatus::kDead;
      o->status_msg = u8"交易日结束, 自动撤销当日有效的委托单(GFD)";
    });
  }
  double dividend_balance_today = 0.0;
  // position 持仓字段更新
  for (auto&& [key, position_node] : m_position_view->GetNodes()) {
    // todo: 分红和送股方案后续补充
    auto ins_node = position_node->Latest()->ins_pointer;
    double stock_dividend = GetStockDividend(ins_node);
    double cash_dividend = GetCashDividend(ins_node);
    m_node_db->ReplaceRecord<Position>(key, [&](std::shared_ptr<Position> position) {
      position->volume_his = position->volume;                                              // 期初持仓数量
      position->cost_his = position->cost;                                                  // 期初买入成本
      position->market_value_his = position->market_value;                                  // 期初市值
      position->shared_volume_today = static_cast<int>(stock_dividend * position->volume);  // 今送股数量
      position->devidend_balance_today = cash_dividend * position->volume;                  // 今分红金额
      dividend_balance_today += position->devidend_balance_today;

      position->buy_volume_his = position->buy_volume_today;
      position->buy_balance_his = position->buy_balance_today;
      position->buy_fee_his = position->buy_fee_today;
      position->sell_volume_his = position->sell_volume_today;
      position->sell_balance_his = position->sell_balance_today;
      position->sell_fee_his = position->sell_fee_today;

      position->buy_volume_today = 0;
      position->buy_balance_today = 0.0;
      position->buy_fee_today = 0.0;
      position->sell_volume_today = 0;
      position->sell_balance_today = 0.0;
      position->sell_fee_today = 0.0;
      position->sell_volume_frozen = 0;

      position->volume += position->shared_volume_today;
      position->float_profit_today = 0.0;
      position->real_profit_today = 0.0;
      position->profit_today = 0.0;
      position->profit_rate_today = 0.0;
      position->hold_profit = 0.0;
    });
  }
  // account 资金字段更新
  m_node_db->ReplaceRecord<Account>(m_user_key + "|CNY", [&](std::shared_ptr<Account> account) {
    account->deposit = 0.0;
    account->withdraw = 0.0;
    account->asset_his = account->asset;
    account->available_his = account->available;
    account->dividend_balance_today = dividend_balance_today;
    account->buy_frozen_balance = 0.0;
    account->buy_frozen_fee = 0.0;
    account->buy_balance_today = 0.0;
    account->buy_fee_today = 0.0;
    account->sell_balance_today = 0.0;
    account->sell_fee_today = 0.0;
    account->float_profit_today = 0.0;
    account->real_profit_today = 0.0;
    UpdateAccountField(account);
  });
  // 刷新交易日
  m_trading_day_end = GetTradingDayEnd(NowAsEpochNano());
}

void SecurityLocalSimServiceImpl::UpdateAccountField(std::shared_ptr<Account> account) {
  // 可用金额 = 期初可用 + 当日入金 - 当日出金 + 当日分红金额 - 当日买入金额 - 当日买入费用 + 当日卖出金额 -
  // 当日卖出费用 - 委托冻结金额 - 委托冻结手续费
  account->available = account->available_his + account->deposit - account->withdraw + account->dividend_balance_today
    - account->buy_balance_today - account->buy_fee_today + account->sell_balance_today - account->sell_fee_today
    - account->buy_frozen_balance - account->buy_frozen_fee;
  // 可取资金 = MAX( 期初可用 + 当日入金 – 当日出金 + MIN(0，当日卖出释放资金 - 当日卖出交易费用 - 当日买入占用资金 -
  // 当日买入费用 - 委托冻结金额 - 委托冻结费用) , 0)
  account->drawable = std::max(account->available_his + account->deposit - account->withdraw
      + std::min(account->sell_balance_today - account->sell_fee_today - account->buy_balance_today
          - account->buy_fee_today - account->buy_frozen_balance - account->buy_frozen_fee,
        0.0),
    0.0);
  // 总资产 = 可用资金 + 委托冻结金额 + 委托冻结费用 + 持仓市值
  account->asset = account->available + account->buy_frozen_balance + account->buy_frozen_fee + account->market_value;

  account->hold_profit = account->market_value - account->cost;
  account->profit_today = account->float_profit_today + account->real_profit_today;
  if (std::fabs(account->cost) > 0.000001) {
    account->profit_rate_today = account->profit_today / account->cost;
  } else {
    account->profit_rate_today = account->profit_today / account->asset_his;
  }
}

void SecurityLocalSimServiceImpl::UpdatePositionField(
  std::shared_ptr<Position> position, std::shared_ptr<const Order> order) {
  if (!position->ins_pointer) {
    position->user_key = m_user_key;
    position->exchange_id = order->exchange_id;
    position->instrument_id = order->instrument_id;
    position->investor_id = order->user_id;
    position->ins_pointer = m_node_db->GetNode<md::Instrument>(position->Symbol());
  }
  if (position->ins_pointer) {
    position->last_price = isnan(position->ins_pointer->Latest()->last_price)
      ? position->ins_pointer->Latest()->pre_close
      : position->ins_pointer->Latest()->last_price;
  }
}

std::shared_ptr<md::InstrumentNode> SecurityLocalSimServiceImpl::CheckInsertOrderValidity(
  std::shared_ptr<security::InsertOrder> req, std::string* msg) {
  if (!IsLogined()) {
    *msg = u8"当前未登录到交易服务器, 无法下单";
    return nullptr;
  }
  if (req->exchange_id.empty()) {
    *msg = u8"委托单交易所信息不存在, 无法下单";
    return nullptr;
  }
  if (req->instrument_id.empty()) {
    *msg = u8"委托单交易合约信息不存在, 无法下单";
    return nullptr;
  }
  if (req->direction == security::Direction::kInvalid) {
    *msg = u8"委托单交易方向无效, 无法下单";
    return nullptr;
  }
  if (req->price_type == security::PriceType::kInvalid) {
    *msg = u8"委托单价格类型无效, 无法下单";
    return nullptr;
  }
  if (req->volume <= 0) {
    *msg = u8"委托单数量小于等于0, 无法下单";
    return nullptr;
  }
  auto ins_node = m_node_db->GetNode<md::Instrument>(req->exchange_id + "." + req->instrument_id);
  if (!ins_node) {
    *msg = u8"下单合约不存在, 无法下单";
    return nullptr;
  }
  if (ins_node->Latest()->ProductClass() != md::ProductClass::kStock) {
    *msg = u8"下单合约非股票合约, 无法下单";
    return nullptr;
  }
  // double 强转 int32
  md::Volume buy_volume_unit = static_cast<int32_t>(ins_node->Latest()->instrument_base->buy_volume_unit);
  FCASSERT(buy_volume_unit > 0);
  // 检查下单数量合法性
  if (req->direction == security::Direction::kBuy) {
    if ((req->volume % buy_volume_unit) != 0) {
      *msg = u8"委托单数量不合法, 无法下单";
      return nullptr;
    }
  } else {
    auto pos_node = m_node_db->GetNode<Position>(m_user_key + "|" + req->exchange_id + "." + req->instrument_id);
    if (!pos_node) {
      *msg = u8"委托单数量不合法, 无法下单";
      return nullptr;
    }
    if (pos_node->Latest()->sell_volume_frozen != 0 && (req->volume % buy_volume_unit) != 0) {
      *msg = u8"委托单数量不合法, 无法下单";
      return nullptr;
    }
    auto available_vol =
      pos_node->Latest()->volume_his + pos_node->Latest()->shared_volume_today - pos_node->Latest()->sell_volume_today;
    if (req->volume != available_vol && (req->volume % buy_volume_unit) != 0) {
      *msg = u8"委托单数量不合法, 无法下单";
      return nullptr;
    }
  }
  return ins_node;
}

const std::string SecurityLocalSimServiceImpl::CheckCancelOrderValidity(std::shared_ptr<security::CancelOrder> req) {
  if (!IsLogined())
    return u8"当前未登录到交易服务器, 无法撤单";
  auto order_node = m_node_db->GetNode<Order>(m_user_key + "|" + req->order_id);
  if (!order_node)
    return u8"没有对应id的委托单, 无法撤单";
  if (order_node->Latest()->status != OrderStatus::kAlive)
    return u8"对应id的委托单已成交或已撤销, 无法撤单";
  return std::string();
}

bool SecurityLocalSimServiceImpl::CheckOrderValidity(std::shared_ptr<security::Order> order) {
  if (GetOrderPrice(order) <= 0 || isnan(GetOrderPrice(order))) {
    order->status_msg = (IsMarketOrder(order)) ? u8"市价委托单无对手盘, 已撤单" : u8"限价单价格小于等于0, 已撤单";
    return false;
  }
  if (GetOrderPrice(order) > order->ins_pointer->Latest()->upper_limit
    || GetOrderPrice(order) < order->ins_pointer->Latest()->lower_limit) {
    order->status_msg = u8"下单价格超出当日涨跌停范围, 已撤单";
    return false;
  }
  auto account = m_node_db->GetNode<Account>(m_user_key + "|CNY")->Latest();
  // 买入开仓检查金额
  if (order->direction == Direction::kBuy) {
    if (account->available < order->frozen_balance + order->frozen_fee) {
      order->status_msg = u8"账户可用余额不足, 无法买入";
      return false;
    }
  }
  // 卖出平仓检查持仓
  if (order->direction == Direction::kSell) {
    auto pos_node = m_node_db->GetNode<Position>(m_user_key + "|" + order->Symbol());
    if (!pos_node) {
      order->status_msg = u8"账户没有当前合约的持仓, 无法卖出";
      return false;
    }
    // T+1 不能卖出今开仓位
    auto pos = pos_node->Latest();
    auto available_vol = pos->volume_his + pos->shared_volume_today - pos->sell_volume_today - pos->sell_volume_frozen;
    if (available_vol < order->volume_orign) {
      order->status_msg = u8"账户持仓量不足, 无法平仓";
      return false;
    }
  }
  return true;
}

bool SecurityLocalSimServiceImpl::CheckAliveOrderValidity(std::shared_ptr<const security::Order> order) {
  // 排除状态为kDead的委托单
  if (order->status == OrderStatus::kDead)
    return false;
  // 合约信息不存在, 不做处理
  if (!order->ins_pointer)
    return false;
  // 委托单方向无效
  if (order->direction == Direction::kInvalid)
    return false;
  return true;
}

void SecurityLocalSimServiceImpl::ProcessAliveOrder(std::shared_ptr<security::OrderNode> order_node) {
  if (!CheckAliveOrderValidity(order_node->Latest()))
    return;
  auto order_id = order_node->Latest()->order_id;
  auto ins = order_node->Latest()->ins_pointer->Latest();
  double trade_price = (order_node->Latest()->direction == Direction::kBuy) ? ins->ask_price[0] : ins->bid_price[0];
  // 无行情, 不撮合
  if (isnan(trade_price))
    return;
  if (!IsMarketOrder(order_node->Latest())) {
    FCASSERT(!isnan(order_node->Latest()->limit_price));
    // 检验委托单是否可以成交
    if (!IsOrderTraded(trade_price, order_node->Latest()))
      return;
  }
  // 市价单对手盘在下单时已经检查过, 故直接撮合成交
  m_cnt++;
  // 成交记录更新
  auto trade = CreateTrade(order_node->Latest(), trade_price);
  auto trade_node = m_node_db->ReplaceRecord<Trade>(trade);
  NodePointer<Trade> trade_pointer(trade_node);
  // 持仓记录更新
  auto position_key = m_user_key + "|" + order_node->Latest()->Symbol();
  auto pos_node = m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
    UpdatePositionByTrade(position, trade);
    UpdatePositionProfit(position);
  });
  // 账户记录更新
  m_node_db->ReplaceRecord<Account>(m_user_key + "|CNY", [=](std::shared_ptr<Account> account) {
    UpdateAccountByTrade(account, trade);
  });
  // 委托单更新为全部成交
  m_node_db->ReplaceRecord<Order>(m_user_key + "|" + order_id, [=](std::shared_ptr<Order> o) {
    o->trade_set.insert(trade_pointer);
    o->volume_left = 0;
    o->frozen_fee = 0.0;
    o->frozen_balance = 0.0;
    o->status = OrderStatus::kDead;
  });
}

std::shared_ptr<security::Order> SecurityLocalSimServiceImpl::CreateOrder(std::shared_ptr<security::InsertOrder> req) {
  auto target = std::make_shared<security::Order>();
  target->user_key = m_user_key;
  target->user_id = m_user_key;
  target->investor_id = m_user_id;
  target->order_id = req->order_id;
  target->exchange_id = req->exchange_id;
  target->exchange_order_id = "";
  target->instrument_id = req->instrument_id;
  target->direction = req->direction;
  target->price_type = req->price_type;
  target->limit_price = req->limit_price;
  target->volume_orign = req->volume;
  target->volume_left = req->volume;
  target->ins_pointer = m_node_db->GetNode<md::Instrument>(target->Symbol());
  target->insert_date_time = NowAsEpochNano();
  target->unit_id = req->unit_id;
  target->status = security::OrderStatus::kAlive;
  target->status_msg = u8"下单成功";
  target->seq_no = ++m_last_order_seq_no;
  target->frozen_fee = GetSecurityFee(req->direction, req->volume, GetOrderPrice(target));
  target->frozen_balance = GetOrderPrice(target) * req->volume;
  return target;
}

std::shared_ptr<security::Trade> SecurityLocalSimServiceImpl::CreateTrade(
  std::shared_ptr<const security::Order> order, double trade_price) {
  std::string exchange_trade_id = std::to_string(m_last_trade_seq_no++);
  std::string trade_key = exchange_trade_id + "|" + order->exchange_order_id;
  auto trade = std::make_shared<security::Trade>();
  trade->seq_no = m_last_trade_seq_no;
  trade->user_key = m_user_key;
  trade->direction = order->direction;
  trade->exchange_id = order->exchange_id;
  trade->trade_id = exchange_trade_id;
  trade->exchange_trade_id = trade_key;
  trade->instrument_id = order->instrument_id;
  trade->investor_id = order->investor_id;
  trade->order_id = order->order_id;
  trade->user_id = order->user_id;
  trade->price = trade_price;
  trade->volume = order->volume_orign;
  trade->unit_id = order->unit_id;
  trade->ins_pointer = m_node_db->GetNode<md::Instrument>(trade->Symbol());
  trade->order_pointer = m_node_db->GetNode<Order>(order->GetKey());
  trade->trade_date_time = NowAsEpochNano();
  trade->fee = GetSecurityFee(order->direction, order->volume_orign, trade_price);
  return trade;
}

void SecurityLocalSimServiceImpl::UpdatePositionByTrade(
  std::shared_ptr<Position> position, std::shared_ptr<Trade> trade) {
  UpdatePositionField(position, trade->order_pointer->Latest());
  // 更新持仓手数/佣金/金额
  if (trade->direction == Direction::kBuy) {
    auto buy_balance = trade->volume * trade->price;
    position->buy_volume_today += trade->volume;
    position->buy_balance_today += buy_balance;
    position->buy_fee_today += trade->fee;
  } else {
    position->sell_volume_frozen -= trade->volume;
    position->sell_volume_today += trade->volume;
    position->sell_balance_today += trade->volume * trade->price;
    position->sell_fee_today += trade->fee;
  }
  position->volume =
    position->volume_his + position->buy_volume_today - position->sell_volume_today + position->shared_volume_today;
}

void SecurityLocalSimServiceImpl::UpdatePositionProfit(std::shared_ptr<Position> position) {
  FCASSERT(position->ins_pointer);
  position->last_price = isnan(position->ins_pointer->Latest()->last_price)
    ? position->ins_pointer->Latest()->pre_close
    : position->ins_pointer->Latest()->last_price;
  FCASSERT(!isnan(position->last_price));
  position->market_value = position->last_price * position->volume;
  // 当前成本 = 前买入成本 + 今买金额 + 今买费用 - 卖出数量 × (前买入成本 / 前数量)
  position->cost = position->cost_his + position->buy_balance_today + position->buy_fee_today;
  if (position->sell_volume_today > 0 && position->volume_his > 0)
    position->cost -= position->sell_volume_today * (position->cost_his / position->volume_his);
  // 当日浮动盈亏 = (期初数量 - 今卖数量) * (最新价 - 昨收盘价) + (当前数量 - (期初数量 - 今卖数量)) * (最新价 -
  // 买入均价)
  position->float_profit_today = position->volume_his > 0
    ? ((position->volume_his - position->sell_volume_today)
        * (position->last_price - position->ins_pointer->Latest()->pre_close))
    : 0.0;
  if (position->buy_volume_today > 0)
    position->float_profit_today += (position->volume - (position->volume_his - position->sell_volume_today))
      * (position->last_price - (position->buy_balance_today + position->buy_fee_today) / position->buy_volume_today);
  // 当日实现盈亏（日阶段） = 今卖金额 - 昨收盘 * 今卖数量 – 今卖交易费用 + 今派息金额
  if (!isnan(position->ins_pointer->Latest()->pre_close) && position->sell_volume_today > 0) {
    position->real_profit_today = position->sell_balance_today - position->sell_fee_today
      + position->devidend_balance_today - position->ins_pointer->Latest()->pre_close * position->sell_volume_today;
  }
  position->profit_today = position->float_profit_today + position->real_profit_today;
  // if 当前数量 == 0 并且 期初市值 不等于 0, 则: 当日盈亏 / 期初市值*100%
  // * else if 当前成本不为0, 则: 当期盈亏/ 当前成本*100%
  // * else 0.0
  if (position->volume == 0 && position->market_value_his != 0)
    position->profit_rate_today = position->profit_today / position->market_value_his;
  else if (std::fabs(position->cost) > 0.000001)
    position->profit_rate_today = position->profit_today / position->cost;
  else
    position->profit_rate_today = 0.0;
  // 持仓盈亏 = 当前市值 - 当前买入成本
  position->hold_profit = position->market_value - position->cost;
  position->real_profit_total = position->real_profit_total_his + position->real_profit_today;
  position->profit_total = position->real_profit_total + position->hold_profit;
  // 当前成本 == 0: 总盈亏 / 期初成本
  // 当前成本 != 0: 总盈亏 / 当前成本
  if (std::fabs(position->cost) > 0.000001)
    position->profit_rate_total = position->profit_total / position->cost;
  else
    position->profit_rate_total = position->profit_total / position->cost_his;
}

void SecurityLocalSimServiceImpl::UpdateAccountByTrade(std::shared_ptr<Account> account, std::shared_ptr<Trade> trade) {
  if (trade->direction == Direction::kBuy) {
    account->buy_frozen_balance -= trade->order_pointer->Latest()->frozen_balance;
    account->buy_frozen_fee -= trade->order_pointer->Latest()->frozen_fee;
    account->buy_balance_today += trade->volume * trade->price;
    account->buy_fee_today += trade->fee;
  } else {
    account->sell_balance_today += trade->volume * trade->price;
    account->sell_fee_today += trade->fee;
  }
}

void SecurityLocalSimServiceImpl::UpdatePosition(std::shared_ptr<const Position> position) {
  if (!IsPositionUpdated(position))
    return;
  m_cnt++;
  auto pos = std::make_shared<Position>(*(position));
  UpdatePositionProfit(pos);
  m_node_db->ReplaceRecord<Position>(pos);
}

