void SecurityOtgParser::DefineStruct(security::ReqTransfer& d) {
  if (!d.future_account.empty())
    AddItem(d.future_account, ("future_account"));
  if (!d.future_password.empty())
    AddItem(d.future_password, ("future_password"));
  if (!d.bank_id.empty())
    AddItem(d.bank_id, ("bank_id"));
  if (!d.bank_password.empty())
    AddItem(d.bank_password, ("bank_password"));
  if (d.currency.empty())
    d.currency = "CNY";
  AddItem(d.currency, ("currency"));
  double amount = NAN;
  if (!is_save) {
    AddItem(amount, ("amount"));
    d.amount = std::fabs(amount);
    if (!isnan(amount))
      d.is_deposit = (amount > 0) ? true : false;
  } else {
    amount = (d.is_deposit) ? d.amount : (d.amount * -1);
    AddItem(amount, ("amount"));
  }
}

SecurityOtgServiceImpl::SecurityOtgServiceImpl(const std::string& user_key, std::shared_ptr<TqApiNodeDb> node_db,
  structlog::Logger& parent_logger, const std::string& access_token)
  : m_node_db(node_db)
  , m_logger(parent_logger.With("c2", "security").With("c3", "otg").Clone())
  , m_ssl_context(boost::asio::ssl::context::sslv23_client)
  , m_access_token(access_token)
  , m_user_key(user_key)
  , m_login_ready(false) {
  m_websocket_connected = false;
  m_session_id = NowAsEpochNano();
  m_last_order_id = 0;
  m_order_view = m_node_db->CreateView<security::Order>([=](std::shared_ptr<const security::Order> order) {
    return order->user_key == m_user_key;
  });
}

void SecurityOtgServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case security::ReqLogin::AID: {
      ReqLogin(command);
      break;
    }
    case security::InsertOrder::AID: {
      ReqInsertOrder(command);
      break;
    }
    case security::CancelOrder::AID: {
      ReqCancelOrder(command);
      break;
    }
    case security::ReqTransfer::AID: {
      ReqTransferMoney(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"找不到此指令实现");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

int SecurityOtgServiceImpl::RunOnce() {
  if ((m_is_ssl_on && !m_wss_socket) || (!m_is_ssl_on && !m_ws_socket))
    return 0;
  if (m_login_ready) {
    auto login_node = m_node_db->GetNode<security::LoginContent>(m_user_key);
    if (login_node && !login_node->Latest()->account_ready && !login_node->Latest()->position_ready) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<security::LoginContent> session) {
        session->account_ready = true;
        session->position_ready = true;
        session->user_key = m_user_key;
        session->backend = BackEnd::kOtg;
      });
    }
  }
  // 处理接收到的数据包
  std::string msg;
  int msg_count = 0;
  for (msg_count = 0; m_recv_queue.pop(msg); msg_count++) {
    ProcessMsg(msg);
    // 每次处理数据包数量 <= 50000
    if (msg_count > 50000)
      break;
  }
  return msg_count;
}

std::vector<std::shared_ptr<UserCommand>> SecurityOtgServiceImpl::ProcessMsg(const std::string& json_str) {
  std::vector<std::shared_ptr<UserCommand>> command_response_list;
  SecurityOtgParser ss;
  ss.FromString(json_str.c_str());
  if (!ss.m_doc->HasMember("data"))
    return command_response_list;

  rapidjson::Value& datas = (*ss.m_doc)["data"];
  if (!datas.IsArray())
    return command_response_list;
  for (auto& data : datas.GetArray()) {
    if (data.HasMember("notify")) {
      rapidjson::Value& notice = data["notify"];
      for (auto& n : notice.GetObject()) {
        auto notice_id = n.name.GetString();
        auto notice_key = m_user_key + "|" + notice_id;
        m_node_db->ReplaceRecord<security::Notice>(notice_key, [&](std::shared_ptr<security::Notice> target) {
          ss.ToVar(target, &n.value);
          target->notice_id = notice_id;
          target->user_key = m_user_key;
        });
        // 转账请求以 Notify 设置是否完成, 指令完成时内存内 TransferLog 可能未就绪.
        auto notice_node = m_node_db->GetNode<Notice>(m_user_key + "|" + notice_id);
        auto req = std::static_pointer_cast<security::ReqTransfer>(m_command_manager->Update("ReqTransferMoney"));
        if (notice_node) {
          if (notice_node->Latest()->code != 421 && notice_node->Latest()->code != 422)
            continue;
          int result_code = (notice_node->Latest()->code == 421) ? 0 : 1;
          SetCommandFinished(req, result_code, notice_node->Latest()->content);
        }
      }
    }
    if (!data.HasMember("trade"))
      continue;
    rapidjson::Value& trade = data["trade"];
    if (!m_req_login)
      continue;
    if (!trade.HasMember(m_req_login->user_id))
      continue;
    rapidjson::Value& d = trade[m_req_login->user_id];
    /*
     * OTG 登录确认包格式
     * {"aid":"rtn_data","data":[{"trade":{"4c5047c0-5f2b-42bb-a316-f86193f8ab4f-sim-securities":
     * {"session":{"user_id":"4c5047c0-5f2b-42bb-a316-f86193f8ab4f-sim-securities","trading_day":"20211108"}}}}]}
     */
    if (d.HasMember("session") && d["session"].HasMember("user_id") && d["session"].HasMember("trading_day")) {
      m_node_db->ReplaceRecord<security::LoginContent>(
        m_user_key, [&](std::shared_ptr<security::LoginContent> session) {
          if (session->user_id.empty()) {
            session->user_key = m_user_key;
            session->user_id = m_req_login->user_id;
            session->investor_id = m_req_login->otg_user_name;
            session->trading_day = d["session"]["trading_day"].GetString();
            session->session_status = SessionStatus::kLogined;
            session->backend = BackEnd::kOtg;
          }
        });
      auto req = m_command_manager->Update("login");
      SetCommandFinished(req);
      continue;
    }
    // OTG 使用trademoredata 作为标志位确认业务信息截面完整
    if (d.HasMember("trade_more_data") && !d["trade_more_data"].GetBool())
      m_login_ready = true;

    if (d.HasMember("accounts")) {
      for (auto& c : d["accounts"].GetObject()) {
        auto currency = c.name.GetString();
        auto account_key = m_user_key + "|" + currency;
        m_node_db->ReplaceRecord<security::Account>(account_key, [&](std::shared_ptr<security::Account> account) {
          ss.ToVar(account, &c.value);
          account->user_key = m_user_key;
          account->investor_id = m_req_login->otg_user_name;
        });
      }
    }
    if (d.HasMember("orders")) {
      for (auto& c : d["orders"].GetObject()) {
        std::string order_id = c.name.GetString();
        auto order_key = m_user_key + "|" + order_id;
        m_node_db->ReplaceRecord<security::Order>(order_key, [&](std::shared_ptr<security::Order> order) {
          ss.ToVar(order, &c.value);
          if (order->order_id.empty())
            order->order_id = order_id;
          if (!order->ins_pointer) {
            auto n_pos = order_id.find_last_of(".");
            if (n_pos != order_id.npos) {
              auto unit_id = order_id.substr(order_id.find_last_of(".") + 1);
              order->unit_id = std::atoi(unit_id.c_str());
            } else {
              order->unit_id = -1;
            }
            order->ins_pointer = md::GetInstrumentNode(order->Symbol(), m_node_db);
            order->investor_id = m_req_login->otg_user_name;
            order->user_key = m_user_key;
          }
          if (order->status != OrderStatus::kDead || order->volume_orign != order->volume_left)
            order->exchange_order_id = order->order_id;
        });
      }
    }
    if (d.HasMember("trades")) {
      for (auto& c : d["trades"].GetObject()) {
        auto key = c.name.GetString();
        auto trade_key = m_user_key + "|" + key;
        auto trade_node =
          m_node_db->ReplaceRecord<security::Trade>(trade_key, [&](std::shared_ptr<security::Trade> trade) {
            ss.ToVar(trade, &c.value);
            trade->_raw_key = key;
            if (!trade->ins_pointer) {
              trade->ins_pointer = md::GetInstrumentNode(trade->Symbol(), m_node_db);
              auto trade_order_node = m_node_db->GetNode<security::Order>(m_user_key + "|" + trade->order_id);
              if (trade_order_node) {
                trade->order_pointer = trade_order_node;
                trade->unit_id = trade_order_node->Latest()->unit_id;
              }
              trade->investor_id = m_req_login->otg_user_name;
              trade->user_key = m_user_key;
            }
          });
        m_node_db->ReplaceRecord<Order>(
          m_user_key + "|" + trade_node->Latest()->order_id, [=](std::shared_ptr<Order> order) {
            NodePointer<Trade> trade_pointer(trade_node);
            order->trade_set.insert(trade_pointer);
          });
      }
    }
    if (d.HasMember("positions")) {
      for (auto& c : d["positions"].GetObject()) {
        std::string key = c.name.GetString();
        auto position_key = m_user_key + "|" + key;
        m_node_db->ReplaceRecord<security::Position>(position_key, [&](std::shared_ptr<security::Position> position) {
          ss.ToVar(position, &c.value);
          if (position->Symbol().empty()) {
            auto exchange_id = key.substr(0, key.find("."));
            auto instrument_id = key.substr(key.find(".") + 1);
            position->exchange_id = exchange_id;
            position->instrument_id = instrument_id;
          }
          if (!position->ins_pointer) {
            position->ins_pointer = md::GetInstrumentNode(position->Symbol(), m_node_db);
            position->investor_id = m_req_login->otg_user_name;
            position->user_key = m_user_key;
          }
        });
      }
    }
    if (d.HasMember("banks")) {
      for (auto& c : d["banks"].GetObject()) {
        auto key = c.name.GetString();
        auto bank_key = m_user_key + "|" + key;
        m_node_db->ReplaceRecord<security::Bank>(bank_key, [&](std::shared_ptr<security::Bank> bank) {
          ss.ToVar(bank, &c.value);
          bank->_raw_key = key;
          bank->user_key = m_user_key;
        });
      }
    }
    if (d.HasMember("transfers")) {
      for (auto& c : d["transfers"].GetObject()) {
        int key = std::atoi(c.name.GetString());
        auto transfer_key = m_user_key + "|" + std::to_string(10000000000 + key);
        m_node_db->ReplaceRecord<security::TransferLog>(
          transfer_key, [&](std::shared_ptr<security::TransferLog> transferlog) {
            ss.ToVar(transferlog, &c.value);
            transferlog->_raw_key = key;
            transferlog->user_key = m_user_key;
            if (transferlog->_raw_key >= 0 && transferlog->future_serial < 0)
              transferlog->future_serial = key;
            transferlog->trade_type = (transferlog->amount > 0) ? u8"入金" : u8"出金";
            transferlog->amount = std::fabs(transferlog->amount);
          });
      }
    }
    for (const auto& order_node : m_order_view->GetChangedNodes()) {
      auto order = order_node->Latest();
      auto req =
        std::static_pointer_cast<security::InsertOrder>(m_command_manager->Update("ReqInsertOrder" + order->order_id));
      if (req) {
        req->order_pointer = order_node;
      }
      if (order->status == OrderStatus::kDead && order->volume_orign == order->volume_left)
        // 下单失败
        SetCommandFinished(req, 1, order->status_msg);
      else
        SetCommandFinished(req);
      if (order->status == OrderStatus::kDead && !order->exchange_order_id.empty()) {
        auto request = m_command_manager->Update("ReqCancelOrder" + order->order_id);
        SetCommandFinished(request);
      }
    }
  }
  return command_response_list;
}

void SecurityOtgServiceImpl::ReqLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::ReqLogin>(m_command_manager->Update(command));
  m_req_login = req;
  if (m_req_login->otg_user_name.empty())
    m_req_login->otg_user_name = m_req_login->user_id;
  m_req_peek_message = "{\"aid\":\"peek_message\"}";

  std::regex regex("(wss|ws)://([^/ :]+):?([^/ ]*)(/?[^ #?]*)\\x3f?([^ #]*)#?([^  ]*)");
  std::smatch match;
  std::regex_search(m_req_login->otg.front_url, match, regex);
  m_otg_protocol = std::string(match[1]);
  m_otg_host = std::string(match[2]);
  m_otg_port = std::string(match[3]).empty() ? (m_otg_protocol == "ws" ? "80" : "443") : std::string(match[3]);
  m_otg_path = std::string(match[4]);
  m_is_ssl_on = m_otg_protocol == "wss" ? true : false;

  if (m_is_ssl_on) {
    m_wss_socket = new websocket::stream<beast::ssl_stream<boost::asio::ip::tcp::socket>>(m_ioc, m_ssl_context);
  } else {
    m_ws_socket = new websocket::stream<boost::asio::ip::tcp::socket>(m_ioc);
  }

  m_resolver = new boost::asio::ip::tcp::resolver(m_ioc);
  m_timer = new boost::asio::deadline_timer(m_ioc);

  // Look up the domain name
  DoResolve();

  // start thread
  m_thread = std::thread([&] {
    m_ioc.run();
  });
  m_command_manager->SetCommandId(command, "login");
}

void SecurityOtgServiceImpl::ReqInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::InsertOrder>(m_command_manager->Update(command));
  if (req->direction == Direction::kInvalid) {
    SetCommandFinished(req, -1, u8"未指定买卖方向");
    return;
  }
  if (req->price_type == PriceType::kInvalid) {
    SetCommandFinished(req, -1, u8"未指定价格类型");
    return;
  }
  auto order_id =
    std::to_string(m_session_id) + "." + std::to_string(m_last_order_id++) + "." + std::to_string(req->unit_id);
  m_command_manager->SetCommandId(command, "ReqInsertOrder" + order_id);
  req->order_id = order_id;
  // 发单
  SecurityOtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "insert_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("order_id", order_id, ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
}

void SecurityOtgServiceImpl::ReqCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::CancelOrder>(m_command_manager->Update(command));
  std::string command_id = "ReqCancelOrder" + req->order_id;
  // 发单
  SecurityOtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "cancel_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
  m_command_manager->SetCommandId(command, command_id);
}

void SecurityOtgServiceImpl::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<security::ReqTransfer>(m_command_manager->Update(command));
  std::string command_id = "ReqTransferMoney";
  // 发单
  SecurityOtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "req_transfer", ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
  m_command_manager->SetCommandId(command, command_id);
}

void SecurityOtgServiceImpl::DoResolve() {
  m_websocket_connected = false;
  m_resolver->async_resolve(m_otg_host, m_otg_port,
    std::bind(&SecurityOtgServiceImpl::OnResolve, this, std::placeholders::_1, std::placeholders::_2));
}

void SecurityOtgServiceImpl::OnResolve(
  boost::system::error_code ec, boost::asio::ip::tcp::resolver::results_type results) {
  if (ec) {
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("resolve fail");
    return;
  }

  if (m_is_ssl_on) {
    boost::asio::async_connect(m_wss_socket->next_layer().next_layer(), results.begin(), results.end(),
      std::bind(&SecurityOtgServiceImpl::OnConnect, this, std::placeholders::_1));
  } else {
    boost::asio::async_connect(m_ws_socket->next_layer(), results.begin(), results.end(),
      std::bind(&SecurityOtgServiceImpl::OnConnect, this, std::placeholders::_1));
  }
}

void SecurityOtgServiceImpl::OnConnect(boost::system::error_code ec) {
  if (ec) {
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("connect fail");
    return;
  }

  if (m_is_ssl_on) {
    m_wss_socket->next_layer().async_handshake(
      boost::asio::ssl::stream_base::client, beast::bind_front_handler(&SecurityOtgServiceImpl::OnSslHandshake, this));
  } else {
    m_ws_socket->set_option(
      boost::beast::websocket::stream_base::decorator([=](boost::beast::websocket::request_type& m) {
        m.insert(http::field::accept, "application/v1+json");
        m.insert(http::field::user_agent, "FC-0.1");
        m.insert(http::field::authorization, "Bearer " + m_access_token);
      }));
    m_ws_socket->async_handshake(
      m_otg_host, m_otg_path, std::bind(&SecurityOtgServiceImpl::OnHandshake, this, std::placeholders::_1));
  }
}

void SecurityOtgServiceImpl::OnSslHandshake(beast::error_code ec) {
  if (ec) {
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("ssl handshake fail");
    return;
  }

  m_wss_socket->set_option(websocket::stream_base::decorator([=](websocket::request_type& m) {
    m.insert(http::field::accept, "application/v1+json");
    m.insert(http::field::user_agent, "FC-0.1");
    m.insert(http::field::authorization, "Bearer " + m_access_token);
    m.insert(http::field::user_agent, std::string(BOOST_BEAST_VERSION_STRING) + " websocket-client-coro");
  }));
  m_wss_socket->async_handshake(
    m_otg_host, m_otg_path, std::bind(&SecurityOtgServiceImpl::OnHandshake, this, std::placeholders::_1));
}

void SecurityOtgServiceImpl::OnHandshake(boost::system::error_code ec) {
  if (ec) {
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("handshake fail");
    return;
  }
  m_logger.With("ec", LocalToUtf8(ec.message())).Info("got connection");
  m_websocket_connected = true;
  m_output_buffer_list.clear();

  std::string login_message;
  SecurityOtgParser ss;
  ss.FromVar(*m_req_login);
  ss.ToString(&login_message);
  SendTextMsg(login_message);
  SendTextMsg(m_req_peek_message);
  DoRead();
}

void SecurityOtgServiceImpl::DoRead() {
  if (m_is_ssl_on) {
    m_wss_socket->async_read(
      m_input_buffer, std::bind(&SecurityOtgServiceImpl::OnRead, this, std::placeholders::_1, std::placeholders::_2));
  } else {
    m_ws_socket->async_read(
      m_input_buffer, std::bind(&SecurityOtgServiceImpl::OnRead, this, std::placeholders::_1, std::placeholders::_2));
  }
}

void SecurityOtgServiceImpl::OnRead(boost::system::error_code ec, std::size_t bytes_transferred) {
  boost::ignore_unused(bytes_transferred);
  if (ec) {
    m_logger.With("err_code", ec.value()).With("err_msg", LocalToUtf8(ec.message())).Info("read error");
    if (m_is_ssl_on)
      m_wss_socket->next_layer().next_layer().shutdown(boost::asio::ip::tcp::socket::shutdown_both, ec);
    else
      m_ws_socket->next_layer().shutdown(boost::asio::ip::tcp::socket::shutdown_both, ec);
    m_timer->expires_from_now(boost::posix_time::seconds(10));
    m_timer->async_wait([this](const boost::system::error_code& ec) {
      if (!ec)
        DoResolve();
    });
    return;
  }
  OnMessage(beast::buffers_to_string(m_input_buffer.data()));
  m_input_buffer.consume(m_input_buffer.size());
  DoRead();
}

void SecurityOtgServiceImpl::OnMessage(const std::string& json_str) {
  m_logger.With("len", static_cast<int>(json_str.size()))
    .With("content", structlog::make_json(json_str))
    .Info("received message");
  SendTextMsg(m_req_peek_message);
  m_recv_queue.push(json_str);
}

void SecurityOtgServiceImpl::SendTextMsg(const std::string& json_str) {
  if (!m_websocket_connected)
    return;
  m_output_buffer_list.push_back(json_str);
  if (m_output_buffer_list.size() == 1)
    DoWrite();
}

void SecurityOtgServiceImpl::DoWrite() {
  auto& json_str = m_output_buffer_list.front();
  m_logger.With("len", static_cast<int>(json_str.size()))
    .With("content", structlog::make_json(json_str))
    .Info("send message");
  auto buf = boost::asio::buffer(json_str);
  if (m_is_ssl_on) {
    m_wss_socket->text(true);
    m_wss_socket->async_write(
      buf, std::bind(&SecurityOtgServiceImpl::OnWrite, this, std::placeholders::_1, std::placeholders::_2));
  } else {
    m_ws_socket->text(true);
    m_ws_socket->async_write(
      buf, std::bind(&SecurityOtgServiceImpl::OnWrite, this, std::placeholders::_1, std::placeholders::_2));
  }
}

void SecurityOtgServiceImpl::OnWrite(boost::system::error_code ec, std::size_t bytes_transferred) {
  if (ec) {
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("send message fail");
  }
  if (!m_output_buffer_list.empty())
    m_output_buffer_list.pop_front();
  if (!m_output_buffer_list.empty())
    DoWrite();
}

