const SubPosition* GetSubPosition(
  std::shared_ptr<PositionNode> node, const md::CusCombineParam& param, const Direction& direction) {
  auto dir = direction;
  if (param.ratio < 0) {
    dir = (direction == Direction::kBuy) ? Direction::kSell : Direction::kBuy;
  }
  if (nullptr == node || direction == Direction::kInvalid || param.hedge_type == PositionHedgeType::kInvalid)
    return nullptr;
  if (dir == Direction::kBuy)
    return (param.hedge_type == PositionHedgeType::kSpeculation) ? &node->Latest()->subpos_long_spec
                                                                 : &node->Latest()->subpos_long_other;
  return (param.hedge_type == PositionHedgeType::kSpeculation) ? &node->Latest()->subpos_short_spec
                                                               : &node->Latest()->subpos_short_other;
}

CusCombPositionMerge::CusCombPositionMerge(std::shared_ptr<TqApiNodeDb> node_db, structlog::Logger& logger)
  : m_node_db(node_db)
  , m_logger(logger.With("cus_comb_position_merge", reinterpret_cast<int64_t>(this)).Clone()) {
  m_login_view = m_node_db->CreateView<LoginContent>(ReuseViewKey::kLogin);
  m_login_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<LoginNode> node, bool) {
      m_user_keys.insert(node->Latest()->user_key);
    });
  // 不考虑交易单元
  m_position_view = m_node_db->CreateView<Position>([](std::shared_ptr<const Position> position) {
    return position->unit_id == 0;
  });
  m_position_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<PositionNode> node, bool) {
      auto it = m_leg_symbols.find(node->Latest()->Symbol());
      if (it == m_leg_symbols.end())
        return;
      for (const auto& comb_symbol : it->second) {
        PositionCombInfo info;
        info.user_key = node->Latest()->user_key;
        info.comb_symbol = comb_symbol;
        m_changed_comb_positions.insert(info);
      }
    });
}

/**
 * 析构CusCombPositionMerge
 */

CusCombPositionMerge::~CusCombPositionMerge() {}

void CusCombPositionMerge::SubscribeComboInstrument(std::shared_ptr<md::SubscribeComboInstrument> request) {
  for (const auto& [key, value] : request->combo_params) {
    // 记录变动组合
    m_changed_comb_symbols.insert(key);
    // 新增组合
    if (!value.empty()) {
      for (const auto& [symbol, param] : value) {
        // 主连转为主力合约
        auto new_symbol = ConvertInstrument(symbol);
        m_comb_params[key][new_symbol] = param;
        m_leg_symbols[new_symbol].insert(key);
      }
      continue;
    }
    // 删除组合
    auto it = m_comb_params.find(key);
    if (it == m_comb_params.end())
      continue;
    for (const auto& [leg, _] : it->second) {
      auto iter = m_leg_symbols.find(leg);
      if (iter != m_leg_symbols.end()) {
        m_leg_symbols[leg].erase(key);
        if (m_leg_symbols[leg].empty())
          m_leg_symbols.erase(leg);
      }
    }
    m_comb_params.erase(key);
  }
}

bool CusCombPositionMerge::CleanCusCombinePosition(
  const std::string& user_key, const std::string& symbol, const Direction& direction) {
  auto comb_position =
    m_node_db->GetNode<CusCombinePosition>(CusCombinePosition::MakeKey(user_key, 0, symbol, direction));
  if (nullptr == comb_position || comb_position->Latest()->shares == 0)
    return false;
  m_node_db->ReplaceRecord<CusCombinePosition>(
    comb_position->Latest()->GetKey(), [](std::shared_ptr<CusCombinePosition> position) {
      position->shares = 0;
      position->available_shares = 0;
      position->frozen_shares = 0;
      position->position_price = 0;
      position->position_profit = 0.0;
      position->open_price = 0.0;
      position->float_profit = 0.0;
    });
  return true;
}

std::string CusCombPositionMerge::ConvertInstrument(std::string symbol) {
  auto ins_node = m_node_db->GetNode<md::Instrument>(symbol);
  FCASSERT(ins_node);
  if (ins_node->Latest()->instrument_base->product_base->product_class == md::ProductClass::kCont) {
    return ins_node->Latest()->instrument_base->underlying_pointer->Latest()->symbol;
  }
  return symbol;
}

int CusCombPositionMerge::BuildCombinePosition(const std::string& user_key, const std::string& comb_symbol) {
  auto ret = 0;
  auto it = m_comb_params.find(comb_symbol);
  if (it == m_comb_params.end()) {
    // 清理组合持仓
    ret += CleanCusCombinePosition(user_key, comb_symbol, Direction::kBuy);
    ret += CleanCusCombinePosition(user_key, comb_symbol, Direction::kSell);
    return ret;
  }
  // 获取账户下的分腿持仓
  const auto& params = it->second;
  auto positions = GetLegPositionNodes(user_key, comb_symbol, params);
  auto ins_node = m_node_db->GetNode<md::Instrument>(comb_symbol);
  if (positions.empty() || nullptr == ins_node) {
    ret += CleanCusCombinePosition(user_key, comb_symbol, Direction::kBuy);
    ret += CleanCusCombinePosition(user_key, comb_symbol, Direction::kSell);
    return ret;
  }
  auto investor_id = positions.begin()->first->Latest()->investor_id;
  // 构建组合持仓
  for (const auto& direction : {Direction::kBuy, Direction::kSell}) {
    auto comb_position = InitCusCombinePosition(user_key, investor_id, ins_node, direction);
    CalculateShares(positions, direction, comb_position);
    FCASSERT(comb_position->shares != std::numeric_limits<int>::max());
    // 无法凑够一份自组合合约
    if (comb_position->shares <= 0) {
      ret += CleanCusCombinePosition(comb_position->user_key, comb_position->symbol, comb_position->direction);
      continue;
    }
    ++ret;
    CalculateProfit(positions, ins_node, comb_position);
    comb_position->frozen_shares = comb_position->shares - comb_position->available_shares;
    m_node_db->ReplaceRecord<CusCombinePosition>(comb_position);
  }
  return ret;
}

std::map<std::shared_ptr<PositionNode>, md::CusCombineParam> CusCombPositionMerge::GetLegPositionNodes(
  const std::string& user_key, const std::string& symbol, const std::map<std::string, md::CusCombineParam>& params) {
  std::map<std::shared_ptr<PositionNode>, md::CusCombineParam> ret;
  // 遍历单腿持仓
  for (const auto& [leg_symbol, param] : params) {
    auto position_node = m_node_db->GetNode<Position>(Position::MakeKey(user_key, 0, leg_symbol));
    if (position_node && position_node->Latest()->VolumeTotal() > 0) {
      ret[position_node] = param;
      continue;
    }
    ret.clear();
    break;
  }
  return ret;
}

std::shared_ptr<CusCombinePosition> CusCombPositionMerge::InitCusCombinePosition(const std::string& user_key,
  const std::string& investor_id, std::shared_ptr<md::InstrumentNode> ins_node, const Direction& direction) {
  FCASSERT(nullptr != ins_node);
  auto comb_position = std::make_shared<CusCombinePosition>();
  comb_position->user_key = user_key;
  comb_position->investor_id = investor_id;
  NodePointer<md::Instrument> ins_pointer(ins_node);
  comb_position->ins_pointer = ins_pointer;
  comb_position->float_profit = 0.0;
  comb_position->position_profit = 0.0;
  comb_position->position_price = 0.0;
  comb_position->open_price = 0.0;
  comb_position->direction = direction;
  comb_position->shares = std::numeric_limits<int>::max();
  comb_position->available_shares = std::numeric_limits<int>::max();
  comb_position->symbol = ins_node->Latest()->symbol;
  return comb_position;
}

void CusCombPositionMerge::CalculateShares(
  const std::map<std::shared_ptr<PositionNode>, md::CusCombineParam>& positions, const Direction& direction,
  std::shared_ptr<CusCombinePosition> comb_position) {
  for (const auto& [node, p] : positions) {
    auto sub = GetSubPosition(node, p, direction);
    FCASSERT(sub);
    FCASSERT(p.ratio != 0);
    comb_position->shares =
      std::min(comb_position->shares, static_cast<int>(std::floor(sub->Volume() * 1.0 / abs(p.ratio))));
    comb_position->available_shares =
      std::min(comb_position->available_shares, static_cast<int>(std::floor(sub->VolumeAvail() * 1.0 / abs(p.ratio))));
  }
}

std::shared_ptr<fclib::md::InstrumentNode> CusCombPositionMerge::ConvertLegMain(
  std::shared_ptr<fclib::md::InstrumentNode> leg) {
  if (leg->Latest()->instrument_base->main_in_series == false) {
    return leg;
  }
  const auto& derviate = leg->Latest()->instrument_base->derivate_pointer;
  for (const auto& [key, value] : derviate) {
    if (value->Latest()->ProductClass() == md::ProductClass::kCont) {
      return value;
    }
  }
  return leg;
}

void CusCombPositionMerge::CalculateProfit(
  const std::map<std::shared_ptr<PositionNode>, md::CusCombineParam>& positions,
  std::shared_ptr<md::InstrumentNode> ins_node, std::shared_ptr<CusCombinePosition> comb_position) {
  FCASSERT(nullptr != ins_node);
  comb_position->open_price = 0;
  comb_position->position_price = 0;
  for (const auto& [node, p] : positions) {
    auto sub = GetSubPosition(node, p, comb_position->direction);
    FCASSERT(sub);
    FCASSERT(sub->Volume() > 0);

    auto vol = comb_position->shares * abs(p.ratio);
    comb_position->float_profit += sub->float_profit * vol / static_cast<int>(sub->Volume());
    comb_position->position_profit += sub->position_profit * vol / static_cast<int>(sub->Volume());
    auto it = ins_node->Latest()->instrument_base->weight.find(node->Latest()->ins_pointer);
    if (it == ins_node->Latest()->instrument_base->weight.end()) {
      it = ins_node->Latest()->instrument_base->weight.find(ConvertLegMain(node->Latest()->ins_pointer));
    }
    if (it == ins_node->Latest()->instrument_base->weight.end()) {
      comb_position->position_price = NAN;
      continue;
    }
    comb_position->open_price += sub->open_price * it->second;
    comb_position->position_price += sub->position_price * it->second;
  }
  comb_position->open_price += ins_node->Latest()->instrument_base->constant_term;
  comb_position->position_price += ins_node->Latest()->instrument_base->constant_term;
}

int CusCombPositionMerge::RunOnce() {
  int ret = 0;
  // 遍历变动的组合合约
  for (const auto& comb_symbol : m_changed_comb_symbols) {
    for (const auto& user_key : m_user_keys) {
      ret += BuildCombinePosition(user_key, comb_symbol);
    }
  }
  // 遍历变动的持仓
  for (const auto& comb_position : m_changed_comb_positions) {
    const auto& comb_symbol = comb_position.comb_symbol;
    const auto& user_key = comb_position.user_key;
    // 避免重复计算
    if (m_changed_comb_symbols.find(comb_symbol) == m_changed_comb_symbols.end())
      ret += BuildCombinePosition(user_key, comb_symbol);
  }
  m_changed_comb_symbols.clear();
  m_changed_comb_positions.clear();
  return ret;
}

bool CusCombPositionMerge::PositionCombInfo::operator<(const PositionCombInfo& t) const {
  return (user_key + comb_symbol) < (t.user_key + t.comb_symbol);
}

