void NextTradingDay(LocalDateTime* time_s) {
  time_s->date_time.tm_mday++;
  auto now_datetime = LocalDateTimeToEpochNano(*time_s);
  md::EpochNano begin_mark = 631123200000000000;
  md::EpochNano delta_time = now_datetime - begin_mark;
  int week_day = (delta_time / 86400000000000) % 7;
  if (week_day >= 5) {
    now_datetime += 86400000000000 * (7 - week_day);
  }
  *time_s = EpochNanoToLocalDateTime(now_datetime, 8);
}

void GenerateRecord(DbOrder* record, std::shared_ptr<const Order> order, RecordType reocrd_type) {
  record->datetime = order->insert_date_time;
  if (order->status == OrderStatus::kDead) {
    record->datetime = order->dead_date_time;
  }
  record->record_type = reocrd_type;
  record->order = std::const_pointer_cast<Order>(order);
}

void GenerateRecord(DbTrade* record, std::shared_ptr<const Trade> trade, RecordType reocrd_type) {
  record->datetime = trade->trade_date_time;
  record->record_type = reocrd_type;
  record->trade = std::const_pointer_cast<Trade>(trade);
  if (!record->trade->ins_pointer) {
    return;
  }
  auto volume_multiple = record->trade->ins_pointer->Latest()->VolumeMultiple();
  record->amount = record->trade->price * record->trade->volume * volume_multiple;
  if (record->trade->direction == Direction::kBuy)
    record->amount *= -1;
}

void GenerateRecord(DbSnap* record, std::shared_ptr<TqApiNodeDb> node_db, md::EpochNano datetime,
  RecordType reocrd_type, bool is_end = false) {
  std::map<std::string, DbSingleSnap> snaps;
  snaps.clear();
  auto& account_node_map = node_db->GetNodeMap<Account>();
  for (auto& account_pair : account_node_map) {
    DbSingleSnap single_snap = {};
    auto account_node = account_pair.second;
    single_snap.account = (!is_end || !account_node->Snap())
      ? std::const_pointer_cast<Account>((account_node->Latest()))
      : std::const_pointer_cast<Account>((account_node->Snap()));
    auto user_key = account_node->Latest()->user_key;
    auto& position_map = node_db->GetNodeMap<Position>();
    for (auto& position_it : position_map) {
      auto pos =
        (!is_end || !position_it.second->Snap()) ? (position_it.second->Latest()) : (position_it.second->Snap());
      if (pos && pos->user_key == user_key)
        single_snap.position_map.insert(std::make_pair(pos->Symbol(), std::const_pointer_cast<Position>(pos)));
    }
    auto& order_map = node_db->GetNodeMap<Order>();
    for (auto& order_it : order_map) {
      auto order = (!is_end || !order_it.second->Snap()) ? (order_it.second->Latest()) : (order_it.second->Snap());
      if (order && order->user_key == user_key && order->status == OrderStatus::kAlive)
        single_snap.alive_order_map.insert(std::make_pair(order->order_id, std::const_pointer_cast<Order>(order)));
    }
    snaps.insert(std::make_pair(user_key, single_snap));
  }
  record->snaps = snaps;
  record->record_type = reocrd_type;
  record->datetime = datetime;
}

void GenerateRecord(DbOrderStatus* record, std::shared_ptr<const Order> order, RecordType reocrd_type) {
  record->datetime = order->dead_date_time + order_datetime_offset;
  if (reocrd_type == RecordType::kOrderBegin) {
    record->datetime = order->insert_date_time - order_datetime_offset;
  }
  record->record_type = reocrd_type;
  record->user_key = order->user_key;
  record->order_id = order->order_id;
  char trading_day[26];
  auto time_s = EpochNanoToLocalDateTime(record->datetime, 8);
  if (reocrd_type == RecordType::kOrderBegin && time_s.date_time.tm_hour >= 15 && time_s.date_time.tm_hour <= 23)
    NextTradingDay(&time_s);
  if (snprintf(trading_day, sizeof(trading_day), "%04d-%02d-%02d", (time_s.date_time.tm_year + 1900),
        (time_s.date_time.tm_mon + 1), time_s.date_time.tm_mday)
    > 0) {
    record->trading_day = trading_day;
  }
}

void GenerateRecord(DbPositionStatus* record, std::shared_ptr<const Trade> trade, RecordType reocrd_type) {
  record->datetime = trade->trade_date_time - position_datetime_offset;
  if (reocrd_type == RecordType::kPositionEnd) {
    record->datetime = trade->trade_date_time + position_datetime_offset;
  }
  record->record_type = reocrd_type;
  record->user_key = trade->user_key;
  record->symbol = trade->Symbol();
}

void GenerateRecord(
  DbTradingDayStatus* record, md::EpochNano datetime, RecordType reocrd_type, md::EpochNano trading_day_dt = 0) {
  record->datetime = datetime + trading_day_datetime_offset;
  if (reocrd_type == RecordType::kTradingDayBegin) {
    record->datetime = datetime - trading_day_datetime_offset;
  }
  record->record_type = reocrd_type;
  auto time_s = EpochNanoToLocalDateTime(trading_day_dt, 8);
  if (trading_day_dt <= 0) {
    time_s = EpochNanoToLocalDateTime(record->datetime, 8);
    if (reocrd_type == RecordType::kTradingDayBegin && time_s.date_time.tm_hour >= 15 && time_s.date_time.tm_hour <= 23)
      NextTradingDay(&time_s);
  }
  char trading_day[26];
  if (snprintf(trading_day, sizeof(trading_day), "%04d-%02d-%02d", (time_s.date_time.tm_year + 1900),
        (time_s.date_time.tm_mon + 1), time_s.date_time.tm_mday)
    > 0) {
    record->trading_day = trading_day;
  }
}

md::EpochNano GetTradingDayEnd(md::EpochNano timestamp) {
  auto begin_mark = 631123200000000000;
  auto days = (timestamp - begin_mark) / 86400000000000;
  if ((timestamp - begin_mark) % 86400000000000 >= 64800000000000) {
    days++;
  }
  auto week_day = days % 7;
  if (week_day >= 5) {
    days = days + 7 - week_day;
  }
  return begin_mark + days * 86400000000000 + 64799999999999;
}

bool IsRecordData(const AccountHisRecord& record) {
  if (record.record_type == RecordType::kOrder || record.record_type == RecordType::kTrade
    || record.record_type == RecordType::kSnap) {
    return true;
  }
  return false;
}

std::shared_ptr<future::AccountHisRecordService> AccountHisRecordService::Create(std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<NodeDbView<future::LoginContent>> login_view, std::shared_ptr<NodeDbView<future::Order>> order_view,
  std::shared_ptr<NodeDbView<future::Trade>> trade_view, structlog::Logger& parent_logger, const TqApiOptions options) {
  auto p =
    std::make_shared<AccountHisRecordServiceImpl>(node_db, login_view, order_view, trade_view, parent_logger, options);
  p->Init();
  return p;
}

AccountHisRecordServiceImpl::AccountHisRecordServiceImpl(std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<NodeDbView<future::LoginContent>> login_view, std::shared_ptr<NodeDbView<future::Order>> order_view,
  std::shared_ptr<NodeDbView<future::Trade>> trade_view, structlog::Logger& parent_logger, const TqApiOptions options)
  : m_current_datetime(0)
  , m_trading_day_end(0)
  , m_error_flag(false)
  , m_node_db(node_db)
  , m_login_view(login_view)
  , m_order_view(order_view)
  , m_trade_view(trade_view)
  , m_logger(parent_logger)
  , m_database_path(options.his_record_path)
  , m_backtest(options.backtest_end_dt > 0 && options.backtest_start_dt > 0)
  , m_running(options.his_record_mode)
  , m_database_ptr(nullptr) {}

void AccountHisRecordServiceImpl::Init() {
  if (!m_running)
    return;
  if (m_database_path.empty()) {
    m_database_path = ":memory:";
  }
  m_current_datetime = NowAsEpochNano();
  m_trading_day_end = GetTradingDayEnd(m_current_datetime);
  try {
    m_database_ptr = std::unique_ptr<SQLite::Database>(
      new SQLite::Database(m_database_path, SQLite::OPEN_READWRITE | SQLite::OPEN_CREATE));
    TryCreateTable();
  } catch (const std::exception& ex) {
    m_error_flag = true;
    m_logger.With("fun", "Init").With("errmsg", ex.what()).Error("open database exception");
  }
  if (!m_error_flag) {
    // 入库 trading_day_begin
    DbTradingDayStatus trading_day_begin = {};
    GenerateRecord(&trading_day_begin, m_current_datetime, RecordType::kTradingDayBegin);
    InsertRecord(trading_day_begin);
    m_login_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<LoginNode> node, bool is_last) {
        // 入库 snap 截面
        auto login_time = StringToEpochNano(node->Snap()->trading_day.c_str(), node->Snap()->login_time.c_str());
        DbSnap snap_record = {};
        GenerateRecord(&snap_record, m_node_db, login_time, RecordType::kSnap);
        InsertRecord(snap_record);
      });
  }
  m_order_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<OrderNode> content) {
    if (!m_error_flag)
      ProcessOrderData(content->Latest());
  });
  m_trade_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<TradeNode> content) {
    if (!m_error_flag)
      ProcessTradeData(content->Latest());
  });
}

void AccountHisRecordServiceImpl::TryCreateTable() {
  std::string str_sql =
    "CREATE TABLE record_table("
    "datetime BIGINT NOT NULL,"
    "record_type VARCHAR(64) NOT NULL,"
    "record_content VARCHAR(255) NOT NULL);";
  try {
    if (m_database_ptr->tableExists("record_table")) {
      return;
    }
    m_database_ptr->exec(str_sql);
  } catch (const std::exception& ex) {
    m_error_flag = true;
    m_logger.With("fun", "try_create_record_table")
      .With("sql", str_sql)
      .With("errmsg", ex.what())
      .Error("create record table exception");
  }
}

bool AccountHisRecordServiceImpl::TradingDayChanged() {
  auto current_quote_datetime = NowAsEpochNano();
  if (current_quote_datetime <= 0) {
    return false;
  }
  m_current_datetime = current_quote_datetime;
  if (m_current_datetime > m_trading_day_end) {
    return true;
  }
  return false;
}

void AccountHisRecordServiceImpl::ProcessTradingDayChange() {
  // 入库结算前 snap 截面
  DbSnap snap_record = {};
  GenerateRecord(&snap_record, m_node_db, m_trading_day_end + snap_datetime_offset, RecordType::kSnap, true);
  InsertRecord(snap_record);
  // 入库 trading_day_end
  DbTradingDayStatus trading_day_end = {};
  GenerateRecord(&trading_day_end, m_trading_day_end, RecordType::kTradingDayEnd);
  InsertRecord(trading_day_end);
  m_trading_day_end = GetTradingDayEnd(m_current_datetime);
  // 入库 trading_day_begin
  DbTradingDayStatus trading_day_begin = {};
  GenerateRecord(&trading_day_begin, trading_day_end.datetime + trading_day_datetime_offset + 1000,
    RecordType::kTradingDayBegin, m_trading_day_end);
  InsertRecord(trading_day_begin);
  // 入库结算后 snap 截面
  DbSnap snap_record_settled = {};
  GenerateRecord(&snap_record_settled, m_node_db, trading_day_begin.datetime + 100, RecordType::kSnap);
  InsertRecord(snap_record_settled);
}

int AccountHisRecordServiceImpl::RunOnce() {
  if (!m_running)
    return 0;
  if (nullptr == m_database_ptr)
    return -1;
  if (m_error_flag)
    return -1;
  if (TradingDayChanged())
    ProcessTradingDayChange();
  if (m_backtest) {
    if (!m_backtest_session)
      m_backtest_session = m_node_db->GetNode<md::Session>(md::Session::MakeKey());
    if (m_backtest_session && m_backtest_session->Latest()->session_status == md::SessionStatus::kBTFinished) {
      // 入库 snap()
      DbSnap snap_record = {};
      GenerateRecord(&snap_record, m_node_db, NowAsEpochNano(), RecordType::kSnap);
      InsertRecord(snap_record);
      // 入库 trading_day_end
      DbTradingDayStatus trading_day_end = {};
      GenerateRecord(&trading_day_end, NowAsEpochNano(), RecordType::kTradingDayEnd);
      InsertRecord(trading_day_end);
    }
  }
  return 0;
}

void AccountHisRecordServiceImpl::ProcessOrderData(std::shared_ptr<const Order> order) {
  if (order->status == future::OrderStatus::kAlive) {
    // 入库 order_begin
    DbOrderStatus order_begin = {};
    GenerateRecord(&order_begin, order, RecordType::kOrderBegin);
    InsertRecord(order_begin);
    // 入库 order
    DbOrder order_record = {};
    GenerateRecord(&order_record, order, RecordType::kOrder);
    InsertRecord(order_record);
  } else {
    // 入库 order
    DbOrder order_record = {};
    GenerateRecord(&order_record, order, RecordType::kOrder);
    InsertRecord(order_record);
    // 入库 order_end
    DbOrderStatus order_end = {};
    GenerateRecord(&order_end, order, RecordType::kOrderEnd);
    InsertRecord(order_end);
  }
}

void AccountHisRecordServiceImpl::ProcessTradeData(std::shared_ptr<const Trade> trade) {
  auto user_key = trade->user_key;
  auto symbol = trade->Symbol();
  auto position_node = m_node_db->GetNode<Position>(user_key + "|0|" + symbol);
  if (!position_node || !position_node->Latest() || position_node->Latest()->VolumeNet() == 0) {
    // 入库 position_begin
    DbPositionStatus position_begin = {};
    GenerateRecord(&position_begin, trade, RecordType::kPositionBegin);
    InsertRecord(position_begin);
  }
  // 入库 trade
  DbTrade trade_record = {};
  GenerateRecord(&trade_record, trade, RecordType::kTrade);
  InsertRecord(trade_record);
  int multiple = (trade->direction == Direction::kSell) ? 1 : -1;
  if (position_node && position_node->Latest() && position_node->Latest()->VolumeNet() != 0) {
    if (position_node->Latest()->VolumeNet() == trade->volume * multiple) {
      // 入库 position_end
      DbPositionStatus position_end = {};
      GenerateRecord(&position_end, trade, RecordType::kPositionEnd);
      InsertRecord(position_end);
    }
  }
}

void AccountHisRecordServiceImpl::CleanUp() {
  try {
    if (nullptr != m_database_ptr) {
      m_database_ptr.reset();
    }
  } catch (const std::exception& ex) {
    m_logger.With("fun", "CleanUp").With("errmsg", ex.what()).Error("close database exception");
  }
}

template <typename T>
void AccountHisRecordServiceImpl::InsertRecord(const T& record) {
  future::NodeSerializer ss;
  ss.FromVar(record);
  std::string str_msg = "";
  ss.ToString(&str_msg);
  try {
    if (str_msg.empty()) {
      return;
    }
    std::string insert_sql =
      "INSERT INTO record_table VALUES "
      "(?,?,?)";
    SQLite::Transaction transaction(*m_database_ptr);
    SQLite::Statement insert(*m_database_ptr, insert_sql.c_str());
    insert.bind(1, record.datetime);
    insert.bind(2, GetEnumValue(record.record_type));
    insert.bind(3, str_msg);
    insert.exec();
    transaction.commit();
  } catch (std::exception& ex) {
    m_error_flag = true;
    m_logger.With("fun", "InsertRecord").With("errmsg", ex.what()).Error("write order table exception");
  }
}

std::vector<AccountHisRecord> AccountHisRecordServiceImpl::GetAccountHisRecords(
  md::EpochNano begin_dt, md::EpochNano end_dt) {
  std::vector<AccountHisRecord> res;
  if (nullptr == m_database_ptr) {
    return res;
  }
  try {
    std::string query_sql =
      "SELECT * FROM record_table "
      "WHERE datetime>=? AND datetime<=? "
      "ORDER BY datetime;";
    SQLite::Statement query(*m_database_ptr, query_sql.c_str());
    query.bind(1, begin_dt);
    query.bind(2, end_dt);
    while (query.executeStep()) {
      AccountHisRecord record;
      record.datetime = query.getColumn("datetime").getInt64();
      GetEnumItem(query.getColumn("record_type").getString(), record.record_type);
      record.record_content = query.getColumn("record_content").getString();
      res.push_back(record);
    }
  } catch (const std::exception& ex) {
    m_error_flag = true;
    m_logger.With("fun", "get_account_his_records")
      .With("errmsg", ex.what())
      .Error("get account his records exception");
  }
  return res;
}

std::pair<RecordType, RecordType> GetRecordType(const future::GroupType& v) {
  std::pair<RecordType, RecordType> pair;
  switch (v) {
    case future::GroupType::kOrder: pair = std::make_pair(RecordType ::kOrderBegin, RecordType ::kOrderEnd); break;
    case future::GroupType::kPosition:
      pair = std::make_pair(RecordType ::kPositionBegin, RecordType ::kPositionEnd);
      break;
    case future::GroupType::kTradingDay:
      pair = std::make_pair(RecordType ::kTradingDayBegin, RecordType ::kTradingDayEnd);
      break;
    default: break;
  }
  return pair;
}

std::string GetBoundaryKey(const std::string& record_content, GroupType group_type) {
  std::string key_symbol = "";
  future::NodeSerializer ss;
  ss.FromString(record_content.c_str());
  switch (group_type) {
    case future::GroupType::kOrder: {
      DbOrderStatus order_record = {};
      ss.ToVar(order_record);
      key_symbol = order_record.user_key + order_record.trading_day + order_record.order_id;
      break;
    }
    case future::GroupType::kPosition: {
      DbPositionStatus pos_record = {};
      ss.ToVar(pos_record);
      key_symbol = pos_record.user_key + pos_record.symbol;
      break;
    }
    case future::GroupType::kTradingDay: {
      DbTradingDayStatus trading_begin = {};
      ss.ToVar(trading_begin);
      key_symbol = trading_begin.trading_day;
      break;
    }
    default: break;
  }
  return key_symbol;
}

std::vector<AccountHisRecordGroup> AccountHisRecordServiceImpl::GroupingHisRecords(std::vector<AccountHisRecord> src,
  GroupType group_type,
  std::function<bool(const AccountHisRecord& boundary, const AccountHisRecord& record)> filter_func) {
  std::vector<AccountHisRecordGroup> res;
  AccountHisRecordGroup record_group = {};
  auto record_start = GetRecordType(group_type).first;
  auto record_end = GetRecordType(group_type).second;
  for (auto iter = src.begin(); iter != src.end(); iter++) {
    auto record = *iter;
    if (record.record_type == record_start) {
      auto key_symbol = GetBoundaryKey(record.record_content, group_type);
      record_group.begin_dt = 0;
      record_group.end_dt = 0;
      record_group.records.clear();
      for (auto it = iter; it != src.end(); it++) {
        auto record_i = *it;
        if (record_i.record_type != record_end) {
          if (IsRecordData(record_i) && filter_func(record, record_i)) {
            record_group.records.push_back(record_i);
          }
          continue;
        }
        auto key_symbol_i = GetBoundaryKey(record_i.record_content, group_type);
        if (key_symbol != key_symbol_i) {
          continue;
        }
        record_group.begin_dt = record.datetime;
        record_group.end_dt = record_i.datetime;
        record_group.group_boundary.first = record;
        record_group.group_boundary.second = record_i;
        res.push_back(record_group);
        break;
      }
    }
  }
  return res;
}

std::vector<AccountHisRecord> AccountHisRecordServiceImpl::FilterLastInEachGroup(std::vector<AccountHisRecord> src,
  GroupType group_type,
  std::function<bool(const AccountHisRecord& boundary, const AccountHisRecord& record)> filter_func) {
  auto group_vec = GroupingHisRecords(src, group_type, filter_func);
  std::vector<AccountHisRecord> res;
  for (auto& group : group_vec) {
    if (!group.records.empty()) {
      res.push_back(group.records.back());
    }
  }
  return res;
}

