bool IsDoubleDiff(double left, double right) {
  if (isnan(left) && isnan(right))
    return false;
  if (isnan(left) || isnan(right))
    return true;
  return std::fabs(left - right) > 1e-5;
}

MdSharedMemory::MdSharedMemory(std::shared_ptr<TqApiNodeDb> db, structlog::Logger& logger)
  : m_db(db)
  , m_logger(logger.With("md_shared_memory", reinterpret_cast<int64_t>(this)).Clone()) {
  m_pid = std::to_string(GetCurrentPID());
  m_shm_name = m_pid + shm::ShmName;
  m_shm_instrument_name = m_pid + shm::ShmInstrumentName;
  m_shm_product_name = m_pid + shm::ShmProductName;
  m_shm_instrument_mutex = m_pid + shm::ShmInstrumentMutex;
  m_shm_product_mutex = m_pid + shm::ShmProductMutex;
}

bool MdSharedMemory::Init() {
  m_logger.With("fun", "Init")
    .With("shm_name", m_shm_name)
    .With("shm_instrument_mutex", m_shm_instrument_mutex)
    .With("shm_product_mutex", m_shm_product_mutex)
    .Info("Init");
  try {
#ifdef _WIN32
    std::wstring utf16_shm_name, utf16_shm_instrument_mutex, utf16_shm_product_mutex;
    StringToWString(m_shm_name, CP_UTF8, &utf16_shm_name);
    StringToWString(m_shm_instrument_mutex, CP_UTF8, &utf16_shm_instrument_mutex);
    StringToWString(m_shm_product_mutex, CP_UTF8, &utf16_shm_product_mutex);
    boost::interprocess::shared_memory_object::remove(utf16_shm_name.c_str());
    boost::interprocess::named_sharable_mutex::remove(utf16_shm_instrument_mutex.c_str());
    boost::interprocess::named_sharable_mutex::remove(utf16_shm_product_mutex.c_str());
    m_segment = new boost::interprocess::managed_shared_memory(
      boost::interprocess::create_only, utf16_shm_name.c_str(), 64 * 1024 * 1024 * 2);
    m_instrument_mutex = new boost::interprocess::named_sharable_mutex(
      boost::interprocess::create_only, utf16_shm_instrument_mutex.c_str());
    m_product_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::create_only, utf16_shm_product_mutex.c_str());
#else
    boost::interprocess::shared_memory_object::remove(m_shm_name.c_str());
    boost::interprocess::named_sharable_mutex::remove(m_shm_instrument_mutex.c_str());
    boost::interprocess::named_sharable_mutex::remove(m_shm_product_mutex.c_str());
    // 构造 instrument_map 和 product_map
    m_segment = new boost::interprocess::managed_shared_memory(
      boost::interprocess::create_only, m_shm_name.c_str(), 64 * 1024 * 1024 * 2);
    // 构造读写互斥
    m_instrument_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::create_only, m_shm_instrument_mutex.c_str());
    m_product_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::create_only, m_shm_product_mutex.c_str());
#endif
    m_alloc_inst = new shm::ShmStringAllocator(m_segment->get_segment_manager());
    m_shm_instrument_map = m_segment->construct<shm::ShmInstrumentMap>(m_shm_instrument_name.c_str())(
      shm::ShmStringComparer(), *m_alloc_inst);
    m_shm_product_map =
      m_segment->construct<shm::ShmProductMap>(m_shm_product_name.c_str())(shm::ShmStringComparer(), *m_alloc_inst);
    m_logger.With("fun", "Init").Info("md_shared_memory construct success");
  } catch (std::exception& ex) {
    m_error = true;
    m_logger.With("fun", "Init").With("errmsg", LocalToUtf8(ex.what())).Error("md_shared_memory construct fail");
    return false;
  }
  InitInsView();
  InitProductView();
  return true;
}

void MdSharedMemory::CleanUp() {
  // 清理视图
  if (nullptr != m_ins_view)
    m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  if (nullptr != m_product_view)
    m_product_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  try {
    // 清理共享内存指针
    if (nullptr != m_segment) {
      m_segment->destroy<shm::ShmInstrumentMap>(m_shm_instrument_name.c_str());
      m_shm_instrument_map = nullptr;
      m_segment->destroy<shm::ShmProductMap>(m_shm_product_name.c_str());
      m_shm_product_map = nullptr;
      if (nullptr != m_alloc_inst) {
        delete m_alloc_inst;
        m_alloc_inst = nullptr;
      }
      delete m_segment;
      m_segment = nullptr;
    }
    // 清理互斥指针
    if (nullptr != m_instrument_mutex) {
      delete m_instrument_mutex;
      m_instrument_mutex = nullptr;
    }
    if (nullptr != m_product_mutex) {
      delete m_product_mutex;
      m_product_mutex = nullptr;
    }
    // 清理共享内存真实数据
#ifdef _WIN32
    std::wstring utf16_shm_name, utf16_shm_instrument_mutex, utf16_shm_product_mutex;
    StringToWString(m_shm_name, CP_UTF8, &utf16_shm_name);
    StringToWString(m_shm_instrument_mutex, CP_UTF8, &utf16_shm_instrument_mutex);
    StringToWString(m_shm_product_mutex, CP_UTF8, &utf16_shm_product_mutex);
    boost::interprocess::shared_memory_object::remove(utf16_shm_name.c_str());
    boost::interprocess::named_sharable_mutex::remove(utf16_shm_instrument_mutex.c_str());
    boost::interprocess::named_sharable_mutex::remove(utf16_shm_product_mutex.c_str());
#else
    boost::interprocess::shared_memory_object::remove(m_shm_name.c_str());
    boost::interprocess::named_sharable_mutex::remove(m_shm_instrument_mutex.c_str());
    boost::interprocess::named_sharable_mutex::remove(m_shm_product_mutex.c_str());
#endif
    m_logger.With("fun", "CleanUp").Info("md_shared_memory cleanup success");
  } catch (std::exception& ex) {
    m_logger.With("fun", "CleanUp").With("errmsg", LocalToUtf8(ex.what())).Error("md_shared_memory cleanup fail");
  }
}

void MdSharedMemory::InitInsView() {
  if (m_error)
    return;
  m_ins_view = m_db->CreateView<Instrument>(ReuseViewKey::kInstrument);
  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<InstrumentNode> node, bool) {
      if (m_error || nullptr == m_shm_instrument_map || nullptr == m_alloc_inst || nullptr == m_instrument_mutex) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      auto ins = node->Snap();
      shm::ShmString key{};
      shm::AssignShmString(&key, ins->symbol);
      // 独占锁
      boost::interprocess::scoped_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);
      auto iter = m_shm_instrument_map->find(key);
      if (iter == m_shm_instrument_map->end()) {
        shm::ShmInstrument shm_instrument;
        UpdateShmInstrument(ins, &shm_instrument);
        m_shm_instrument_map->insert(std::make_pair(key, shm_instrument));
      } else {
        shm::ShmInstrument* shm_instrument_ptr = &(iter->second);
        FCASSERT(nullptr != shm_instrument_ptr);
        if (IsShmInstrumentUpdate(ins, shm_instrument_ptr))
          UpdateShmInstrument(ins, shm_instrument_ptr);
      }
    });
}

bool MdSharedMemory::IsShmInstrumentUpdate(std::shared_ptr<const Instrument> ins, const shm::ShmInstrument* ret) {
  if (std::string(ret->symbol.data()) != ins->symbol || std::string(ret->exchange_id.data()) != ins->ExchangeID()
    || ins->instrument_id != ret->instrument_id.data() || std::string(ret->product_id.data()) != ins->ProductID()
    || ins->instrument_base->leg1_pointer.Key() == ret->leg1_symbol.data()
    || ins->instrument_base->leg2_pointer.Key() == ret->leg2_symbol.data()
    || ins->instrument_base->underlying_pointer.Key() == ret->underlying_symbol.data())
    return true;
  if (ret->product_class != ins->ProductClass() || ret->option_class != ins->option_class
    || ret->trade_status != ins->_trade_status)
    return true;
  if (IsDoubleDiff(ret->volume_multiple, ins->VolumeMultiple()))
    return true;
  if (IsDoubleDiff(ret->margin, ins->instrument_base->margin))
    return true;
  if (IsDoubleDiff(ret->commission, ins->instrument_base->commission))
    return true;
  if (IsDoubleDiff(ret->price_tick, ins->PriceTick()))
    return true;
  if (IsDoubleDiff(ret->last_price, ins->last_price))
    return true;
  if (IsDoubleDiff(ret->upper_limit, ins->upper_limit))
    return true;
  if (IsDoubleDiff(ret->lower_limit, ins->lower_limit))
    return true;
  if (IsDoubleDiff(ret->pre_settlement, ins->pre_settlement))
    return true;
  if (IsDoubleDiff(ret->settlement, ins->settlement))
    return true;
  if (IsDoubleDiff(ret->ask_price1, ins->ask_price[0]))
    return true;
  if (IsDoubleDiff(ret->bid_price1, ins->bid_price[0]))
    return true;
  if (ret->ask_volume1 != ins->ask_volume[0] || ret->bid_volume1 != ins->bid_volume[0])
    return true;
  return false;
}

void MdSharedMemory::UpdateShmInstrument(std::shared_ptr<const Instrument> ins, shm::ShmInstrument* ret) {
  shm::AssignShmString(&ret->symbol, ins->symbol);
  shm::AssignShmString(&ret->exchange_id, ins->ExchangeID());
  shm::AssignShmString(&ret->product_id, ins->ProductID());
  shm::AssignShmString(&ret->instrument_id, ins->instrument_id);

  shm::AssignShmString(&ret->leg1_symbol, std::string(ins->instrument_base->leg1_pointer.Key()));
  shm::AssignShmString(&ret->leg2_symbol, std::string(ins->instrument_base->leg2_pointer.Key()));
  shm::AssignShmString(&ret->underlying_symbol, std::string(ins->instrument_base->underlying_pointer.Key()));

  ret->product_class = ins->ProductClass();
  ret->option_class = ins->option_class;
  ret->trade_status = ins->_trade_status;

  ret->volume_multiple = ins->VolumeMultiple();
  ret->margin = ins->instrument_base->margin;
  ret->commission = ins->instrument_base->commission;
  ret->price_tick = ins->PriceTick();

  ret->last_price = ins->last_price;
  ret->upper_limit = ins->upper_limit;
  ret->lower_limit = ins->lower_limit;
  ret->pre_settlement = ins->pre_settlement;
  ret->settlement = ins->settlement;
  ret->ask_price1 = ins->ask_price[0];
  ret->bid_price1 = ins->bid_price[0];
  ret->ask_volume1 = ins->ask_volume[0];
  ret->bid_volume1 = ins->bid_volume[0];
  ret->strike_price = ins->strike_price;
  ret->update_time = ins->exchange_time;
}

void MdSharedMemory::InitProductView() {
  if (m_error)
    return;
  m_product_view = m_db->CreateView<Product>(ReuseViewKey::kProduct);
  m_product_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<ProductNode> node, bool) {
      if (m_error || nullptr == m_shm_product_map || nullptr == m_alloc_inst || nullptr == m_product_mutex) {
        m_product_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      auto product = node->Snap();
      shm::ShmString key{};
      shm::AssignShmString(&key, product->GetKey());
      // 独占锁
      boost::interprocess::scoped_lock<boost::interprocess::named_sharable_mutex> lock(*m_product_mutex);
      auto iter = m_shm_product_map->find(key);
      if (iter == m_shm_product_map->end()) {
        shm::ShmProduct shm_product(*m_alloc_inst);
        UpdateShmProduct(product, &shm_product);
        m_shm_product_map->insert(std::make_pair(key, shm_product));
      } else {
        shm::ShmProduct* shm_product_ptr = &(iter->second);
        FCASSERT(nullptr != shm_product_ptr);
        if (IsShmProductUpdate(product, shm_product_ptr))
          UpdateShmProduct(product, shm_product_ptr);
      }
    });
}

bool MdSharedMemory::IsShmProductUpdate(std::shared_ptr<const Product> product, const shm::ShmProduct* ret) {
  if (product->exchange_id != ret->exchange_id.data() || product->product_id != ret->product_id.data())
    return true;
  return ret->instruments.size() != product->instrument_list.size();
}

void MdSharedMemory::UpdateShmProduct(std::shared_ptr<const Product> product, shm::ShmProduct* ret) {
  shm::AssignShmString(&ret->exchange_id, product->exchange_id);
  shm::AssignShmString(&ret->product_id, product->product_id);
  for (const auto& [k, _] : product->instrument_list) {
    shm::ShmString instrument{};
    shm::AssignShmString(&instrument, k);
    ret->instruments.insert(instrument);
  }
}

