namespace fclib::md {

static structlog::Logger s_logger = structlog::Logger::Root();
static structlog::Logger s_notify_logger = s_logger.With("rtq_service", "notify").Clone();
static structlog::Logger s_badhs_logger = s_logger.With("rtq_service", "bad_handshake").Clone();

int32_t RtqService::Init(const std::vector<MdAddress>& address, const std::string& agent, const std::string& token) {
  // use default address if not specified
  if (address.empty()) {
    return RTQInit("STOCK", nullptr, agent.c_str(), nullptr, nullptr, token.c_str(), RtqService::RtqLogger,
      RtqService::RtqNotify, RtqService::RtqBadHandShake, 1);
  }
  // serialize address
  std::string addrs;
  AddressSerializer rtq_ss;
  rtq_ss.FromVar(address);
  rtq_ss.ToString(&addrs);

  return RTQInit("STOCK", addrs.c_str(), agent.c_str(), nullptr, nullptr, token.c_str(), RtqService::RtqLogger,
    RtqService::RtqNotify, RtqService::RtqBadHandShake, 1);
}

void RtqService::ProcessRtqLogger(structlog::Logger& logger) {
  std::string log;
  while (s_rtq_log.pop(log)) {
    logger.With("len", static_cast<int>(log.size())).With("rtq", structlog::make_json(log)).Debug("rtq log");
  }
}

bool RtqService::ProcessRtqStatus(int32_t ctx, std::shared_ptr<TqApiNodeDb> node_db) {
  auto md_session_node = node_db->GetNode<Session>("md_session");

  // check bad hand shake
  if (GetRtqBadHs(ctx)) {
    if (!md_session_node || md_session_node->Latest()->error_msg.empty()
      || md_session_node->Latest()->session_status != SessionStatus::kDisconnected) {
      node_db->ReplaceRecord<Session>("md_session", [=](std::shared_ptr<Session> md_session) {
        md_session->session_status = SessionStatus::kDisconnected;
        md_session->error_msg = "Backtest Permission Denied";
      });
      return true;
    }
    return false;
  }

  // check notify
  SessionStatus status = GetRtqStatus(ctx);
  if (status == SessionStatus::kBeforeConnect)
    return false;

  if (!md_session_node || md_session_node->Latest()->session_status != status) {
    node_db->ReplaceRecord<Session>("md_session", [=](std::shared_ptr<Session> md_session) {
      md_session->session_status = status;
      if (status == SessionStatus::kLogined)
        md_session->error_msg = "";
    });
    return true;
  }
  return false;
}

void RtqService::RtqLogger(const char* p, size_t n) {
  std::lock_guard lk(s_rtq_logger_lock);
  s_rtq_log.push(std::string(p, n));
}

void RtqService::RtqNotify(int32_t ctx, const char* srv, const char* url, int status) {
  SessionStatus notify = (status == 0) ? SessionStatus::kDisconnected : SessionStatus::kLogined;

  std::lock_guard lk(s_rtq_notify_lock);
  s_notify_logger.With("ctx", ctx).With("srv", srv).With("url", url).With("status", status).Info("rtq notify");
  s_rtq_notify[ctx] = notify;
}

void RtqService::RtqBadHandShake(int32_t ctx, const char* url, const char* header) {
  std::lock_guard lk(s_rtq_bad_hs_lock);
  s_badhs_logger.With("ctx", ctx).With("url", url).With("header", header).Error("rtq bad hand shake");

  // already bad hand shake, return directly
  if (auto it = s_rtq_bad_hs.find(ctx); it != s_rtq_bad_hs.end() && it->second)
    return;

  // parse header to get X-Shinny-Auth-Check
  using InputStream = rapidjson::EncodedInputStream<rapidjson::UTF8<>, rapidjson::StringStream>;
  rapidjson::Document json_log;
  rapidjson::StringStream buffer(header);
  InputStream os(buffer);
  json_log.ParseStream<rapidjson::kParseNanAndInfFlag, rapidjson::UTF8<>>(os);
  if (json_log.HasParseError() || !json_log.HasMember("X-Shinny-Auth-Check"))
    return;

  // check backtest permission denied
  for (const auto& info : json_log["X-Shinny-Auth-Check"].GetArray()) {
    if (strcmp(info.GetString(), "Backtest Permission Denied") == 0) {
      s_rtq_bad_hs[ctx] = true;
      return;
    }
  }
}

SessionStatus RtqService::GetRtqStatus(int32_t ctx) {
  std::lock_guard lk(s_rtq_notify_lock);
  if (auto it = s_rtq_notify.find(ctx); it != s_rtq_notify.end()) {
    return it->second;
  }
  return SessionStatus::kBeforeConnect;
}

bool RtqService::GetRtqBadHs(int32_t ctx) {
  std::lock_guard lk(s_rtq_bad_hs_lock);
  if (auto it = s_rtq_bad_hs.find(ctx); it != s_rtq_bad_hs.end()) {
    return it->second;
  }
  return false;
}

