void MdServiceChart::ReqSubscribeChartLatest(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeChartLatest>(m_manager->Update(c));
  FCASSERT(command->view_width > 0);
  if (command->view_width > ChartMaxWidth) {
    SetCommandFinished(command, -1, u8"fclib: 历史数据请求长度不得超过" + std::to_string(ChartMaxWidth));
    return;
  }
  if (command->chart_id.size() > ChartIDMaxLength) {
    SetCommandFinished(command, -1, u8"fclib: 图表ID 长度不得超过" + std::to_string(ChartIDMaxLength));
    return;
  }

  std::string symbol_list = boost::algorithm::join(command->symbol_list, ",");

  if (!m_test_mode
    && RTQSetChartLatest(m_context_id, command->chart_id.data(), symbol_list.data(),
         static_cast<uint64_t>(command->dur_nano), static_cast<uint64_t>(command->view_width))
      < 0) {
    SetCommandFinished(command, -1, u8"fclib: 订阅最新图表请求未能正常发出");
  } else {
    AfterSubscribeChart({command->chart_id, u8"", symbol_list, {}, command->dur_nano}, command);
  }
}

