void MdServiceChart::ReqSubscribeComboChart(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeComboChart>(m_manager->Update(c));

  if (command->dur_nano == 0) {
    SetCommandFinished(command, -1, u8"fclib: 组合不支持 tick 数据");
    return;
  }

  std::string subscribe_id = command->chart_id + "_cat_" + command->comb_key;
  if (subscribe_id.size() > ChartIDMaxLength) {
    SetCommandFinished(command, -1, u8"fclib: chart_id 和 comb_key 长度超出限制");
    return;
  }

  ChartSerializer chart_ss;
  std::string weight;
  chart_ss.FromVar(command->weight);
  chart_ss.ToString(&weight);

  int result = 0;
  if (!m_test_mode) {
    result = command->view_width > 0
      ? RTQSetComboChartLatest(m_context_id, subscribe_id.data(), weight.data(),
        static_cast<uint64_t>(command->dur_nano), static_cast<uint64_t>(command->view_width))
      : RTQSetComboChartTradingDay(m_context_id, subscribe_id.data(), weight.data(),
        static_cast<uint64_t>(command->dur_nano), command->trading_day_start, command->trading_day_count);
  }
  if (result < 0) {
    SetCommandFinished(command, -1, u8"fclib: 订阅组合图表行情请求未能正常发出");
  } else {
    AfterSubscribeChart({command->chart_id, command->comb_key, u8"", command->weight, command->dur_nano}, command);
  }
}

void MdServiceChart::ReqSubscribeComboChartFocus(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeComboChartFocus>(m_manager->Update(c));

  if (command->dur_nano == 0) {
    SetCommandFinished(command, -1, u8"fclib: 组合不支持 tick 数据");
    return;
  }

  std::string subscribe_id = command->chart_id + "_cat_" + command->comb_key;
  if (subscribe_id.size() > ChartIDMaxLength) {
    SetCommandFinished(command, -1, u8"fclib: chart_id 和 comb_key 长度超出限制");
    return;
  }

  ChartSerializer chart_ss;
  std::string weight;
  chart_ss.FromVar(command->weight);
  chart_ss.ToString(&weight);

  if (!m_test_mode
    && RTQSetComboChartFocused(m_context_id, subscribe_id.data(), weight.data(),
         static_cast<uint64_t>(command->dur_nano), static_cast<uint64_t>(command->view_width),
         static_cast<uint64_t>(command->focus_datetime), command->focus_position)
      < 0) {
