void MdServiceChart::ProcessChartsMsg(rapidjson::Value& charts) {
  for (auto& c : charts.GetObject()) {
    // 普通合约: chart_id
    // 组合合约: chart_id + "_cat_" + comb_key
    std::string chart_id = c.name.GetString();
    if (auto pos = chart_id.find("_cat_"); pos != std::string::npos)
      chart_id = chart_id.substr(0, pos);

    auto chart_node = UpdateChartStatus(chart_id, c.value);
    auto it = m_chart_traits.find(chart_id);
    if (it == m_chart_traits.end())
      continue;

    const auto& chart_trait = it->second;
    const auto& chart_status = chart_node->Latest();
    // 跳过 退订请求
    if (chart_status->symbol_list.empty() && chart_status->weights.empty())
      continue;
    // 跳过 不一致请求
    if (!IsResponseSameAsChartTrait(chart_trait, *(chart_status)))
      continue;
    // chart 信息就绪, 请求置完成.
    if (chart_status->ready)
      SetCommandFinished(m_manager->Update(chart_id));
  }
}

void MdServiceChart::ProcessKlinesMsg(rapidjson::Document& message, rapidjson::Value& klines) {
  ChartSerializer ss(&message);

  for (auto& m : klines.GetObject()) {
    //@todo: 支持清空整个序列
    if (m.value.IsNull())
      continue;

    // 行情图表数据格式为: {"klines":{"{key_name}":{duration:{...}}}}.
    // * 普通合约: key_name 为合约 symbol, 例如: SHFE.au2201;
    // * 组合合约: key_name 为 图表 id + "_cat_" + comb_key.
    std::string key_name = m.name.GetString();

    //@todo: 使用 comb_key 会导致多个 chart 展示同一组合的同一周期时 data race
    if (auto pos = key_name.find("_cat_"); pos != std::string::npos) {
      key_name = key_name.substr(pos + 5);
    }

    for (auto& d : m.value.GetObject()) {
      std::string symbol = m.name.GetString();
      if (auto it = symbol.find("_cat_"); it != std::string::npos) {
        symbol.replace(it, 5, "_");
      }
      int64_t duration = std::atoll(d.name.GetString());
      m_node_db->ReplaceRecord<KlineInfo>(KlineInfo::MakeKey(symbol, duration), [&](std::shared_ptr<KlineInfo> kinfo) {
        ss.ToVar(kinfo, &d.value);
        kinfo->symbol = symbol;
        kinfo->duration = duration;
      });
      auto& kline = (*m_klines)[symbol][duration];
      auto mutator = KlineSeries::Mutator(kline);
      if (m_data_root) {
        m_data_root->UpdateChild<MdTreeKey::kKlines>()
          ->UpdateChild(key_name)
          ->UpdateChild(duration)
          ->UpdateChild<MdInfoDataKey::kInfo>()
          ->UpdateContent([&](std::shared_ptr<KlineSeriesInfo> kline_series_info) {
            ss.ToVar(*kline_series_info, &d.value);
          });
      }
      rapidjson::Value& kline_series = d.value;
      rapidjson::Value::MemberIterator itr = kline_series.FindMember("data");
      if (itr == kline_series.MemberEnd() || itr->value.IsNull())
        continue;
      auto& datas = itr->value;
      for (auto& data : datas.GetObject()) {
        rapidjson::Value& kdv = data.value;
        int32_t data_id = std::stoi(data.name.GetString());
        if (kdv.IsNull()) {
          mutator.reap(data_id);
          continue;
        }
        KlineData kd;
        ss.ToVar(kd, &kdv);
        mutator.write(data_id, id{data_id}, datetime{kd.datetime}, open{kd.open}, high{kd.high}, low{kd.low},
          close{kd.close}, volume{kd.volume}, open_oi{kd.open_oi}, close_oi{kd.close_oi});
        if (!m_data_root)
          continue;
        m_data_root->UpdateChild<MdTreeKey::kKlines>()
          ->UpdateChild(key_name)
          ->UpdateChild(duration)
          ->UpdateChild<MdInfoDataKey::kData>()
          ->UpdateChild(data_id)
          ->UpdateContent([&](std::shared_ptr<KlineData> kline_data) {
            *kline_data = kd;
          });
      }
    }
  }
}

void MdServiceChart::ProcessTicksMsg(rapidjson::Document& message, rapidjson::Value& ticks) {
  ChartSerializer ss(&message);

  for (auto& m : ticks.GetObject()) {
    //@todo: 支持清空整个序列
    if (m.value.IsNull())
      continue;
    std::string symbol = m.name.GetString();
    m_node_db->ReplaceRecord<TickInfo>(TickInfo::MakeKey(symbol), [&](std::shared_ptr<TickInfo> tinfo) {
      ss.ToVar(tinfo, &m.value);
      tinfo->symbol = symbol;
    });
    auto& tick = (*m_ticks)[symbol];
    auto mutator = TickSeries::Mutator(tick);
    if (m_data_root) {
      m_data_root->UpdateChild<MdTreeKey::kTicks>()
        ->UpdateChild(symbol)
        ->UpdateChild<MdInfoDataKey::kInfo>()
        ->UpdateContent([&](std::shared_ptr<KlineSeriesInfo> tick_series_info) {
          ss.ToVar(*tick_series_info, &m.value);
        });
    }
    rapidjson::Value& ticks_series = m.value;
    rapidjson::Value::MemberIterator itr = ticks_series.FindMember("data");
    if (itr == ticks_series.MemberEnd() || itr->value.IsNull())
      continue;
    auto& datas = itr->value;
    std::pair<int32_t, std::shared_ptr<md::TickData>> prev;
    for (auto& data : datas.GetObject()) {
      rapidjson::Value& tdv = data.value;
      int32_t data_id = std::stoi(data.name.GetString());
      if (tdv.IsNull()) {
        mutator.reap(data_id);
        continue;
      }
      TickData td;
      ss.ToVar(td, &tdv);
      mutator.write(data_id, id{data_id}, datetime{td.datetime}, last_price{td.last_price}, average{td.average},
        highest{td.highest}, lowest{td.lowest}, volume{td.volume}, open_interest{td.open_interest}, amount{td.amount},
        bid_price1{td.bid_price1}, ask_price1{td.ask_price1}, bid_price2{td.bid_price2}, ask_price2{td.ask_price2},
        bid_price3{td.bid_price3}, ask_price3{td.ask_price3}, bid_price4{td.bid_price4}, ask_price4{td.ask_price4},
        bid_price5{td.bid_price5}, ask_price5{td.ask_price5}, bid_volume1{td.bid_volume1}, ask_volume1{td.ask_volume1},
        bid_volume2{td.bid_volume2}, ask_volume2{td.ask_volume2}, bid_volume3{td.bid_volume3},
        ask_volume3{td.ask_volume3}, bid_volume4{td.bid_volume4}, ask_volume4{td.ask_volume4},
        bid_volume5{td.bid_volume5}, ask_volume5{td.ask_volume5});
      if (!prev.second) {
        auto prev_node = GetTickNode(symbol, data_id - 1);
        if (prev_node) {
          prev = std::make_pair(data_id - 1, prev_node->Snap());
        }
      }
      UpdateTickNode(symbol, data_id, [&](std::shared_ptr<md::TickData> tick_data) {
        *tick_data = td;
        if (prev.second && prev.first + 1 == data_id)
          UpdateTickChangeInfo(tick_data.get(), prev.second.get());
        prev = std::make_pair(data_id, tick_data);
      });
    }
    if (!prev.second || !GetTickNode(symbol, prev.first + 1))
      continue;
    UpdateTickNode(symbol, prev.first + 1, [&](std::shared_ptr<md::TickData> tick_data) {
      UpdateTickChangeInfo(tick_data.get(), prev.second.get());
    });
  }
}

