void MdServiceChart::AfterSubscribeChart(const ChartTrait& chart_trait, std::shared_ptr<UserCommand> command) {
  auto it = m_chart_traits.find(chart_trait.chart_id);
  // 处理退订请求
  if (chart_trait.IsUnSubscribed()) {
    SetCommandFinished(command);
    if (it != m_chart_traits.end()) {
      auto prev_command = m_manager->Update(chart_trait.chart_id);
      if (prev_command && prev_command->status != UserCommand::Status::kFinished)
        SetCommandFinished(prev_command, -1, u8"fclib: 订阅图表行情请求已被退订");
      m_chart_traits.erase(it);
    }
    return;
  }

  // 处理前一次请求
  if (it != m_chart_traits.end()) {
    bool need_unsubscribe = (it->second.comb_key != chart_trait.comb_key);
    auto result_msg = (need_unsubscribe) ? u8"fclib: 订阅图表行情请求已被退订" : u8"fclib: 订阅图表行情请求已被替换";
    auto prev_command = m_manager->Update(chart_trait.chart_id);
    if (prev_command && prev_command->status != UserCommand::Status::kFinished) {
      SetCommandFinished(prev_command, -1, result_msg);
    }
    // 退订
    if (need_unsubscribe) {
      if (!it->second.comb_key.empty()) {
        std::string subscribe_id = chart_trait.chart_id + "_cat_" + it->second.comb_key;
        RTQSetComboChartLatest(
          m_context_id, subscribe_id.data(), "{}", static_cast<uint64_t>(0), static_cast<uint64_t>(1));
      } else {
        RTQSetChartLatest(
          m_context_id, chart_trait.chart_id.data(), "", static_cast<uint64_t>(0), static_cast<uint64_t>(1));
      }
    }
  }

  m_chart_traits[chart_trait.chart_id] = chart_trait;
  m_manager->SetCommandId(command, chart_trait.chart_id);
}

std::shared_ptr<ChartNode> MdServiceChart::UpdateChartStatus(
  const std::string& chart_id, rapidjson::Value& chart_value) {
  auto ret = m_node_db->GetNode<ChartContent>(chart_id);
  bool need_update = nullptr == ret;

  auto chart_status = m_node_db->CreateRecord<ChartContent>(chart_id);
  chart_status->chart_id = chart_id;

  bool unsubscribe = false;

  if (chart_value.HasMember("state")) {
    // 获取合约列表
    if (chart_value["state"].HasMember("ins_list")) {
      if (!chart_status->weights.empty()) {
        chart_status->weights.clear();
        chart_status->ready = false;
        need_update = true;
      }
      const auto& ins_list = chart_value["state"]["ins_list"];
      if (ins_list.IsNull()) {
        unsubscribe = true;
        if (!chart_status->symbol_list.empty()) {
          chart_status->symbol_list.clear();
          need_update = true;
        }
      } else if (ins_list.IsString() && chart_status->symbol_list != ins_list.GetString()) {
        chart_status->symbol_list = ins_list.GetString();
        need_update = true;
      }
    }
    // 获取图表周期
    if (chart_value["state"].HasMember("duration")) {
      const auto& duration = chart_value["state"]["duration"];
      if (duration.IsNull() && -1 != chart_status->dur_nano) {
        chart_status->dur_nano = -1;
        need_update = true;
      } else if (duration.IsInt64() && chart_status->dur_nano != duration.GetInt64()) {
        chart_status->dur_nano = duration.GetInt64();
        need_update = true;
      }
    }
    // 获取自定义组合权重
    if (chart_value["state"].HasMember("weights")) {
      if (!chart_status->symbol_list.empty()) {
        chart_status->symbol_list.clear();
        chart_status->ready = false;
        need_update = true;
      }
      const auto& weights = chart_value["state"]["weights"];
      if (weights.IsNull()) {
        unsubscribe = true;
        if (!chart_status->weights.empty()) {
          chart_status->weights.clear();
          need_update = true;
        }
      } else {
        const rapidjson::Value& d = chart_value["state"]["weights"];
        rapidjson::StringBuffer buffer;
        rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
        d.Accept(writer);
        if (UpdateChartWeights(buffer.GetString(), &chart_status->weights)) {
          need_update = true;
        }
      }
    }
  }
  // 获取图表 left_id
  if (chart_value.HasMember("left_id")) {
    if (chart_value["left_id"].IsNull() && -1 != chart_status->left_id) {
      chart_status->left_id = -1;
      need_update = true;
    } else if (chart_value["left_id"].IsInt() && chart_status->left_id != chart_value["left_id"].GetInt()) {
      chart_status->left_id = chart_value["left_id"].GetInt();
      need_update = true;
    }
  }
  // 获取图表 right_id
  if (chart_value.HasMember("right_id")) {
    if (chart_value["right_id"].IsNull() && -1 != chart_status->right_id) {
      chart_status->right_id = -1;
      need_update = true;
    } else if (chart_value["right_id"].IsInt() && chart_status->right_id != chart_value["right_id"].GetInt()) {
      chart_status->right_id = chart_value["right_id"].GetInt();
      need_update = true;
    }
  }
  // 获取图表 ready
  if (chart_value.HasMember("ready")) {
    if (chart_value["ready"].IsNull()) {
      unsubscribe = true;
    } else if (chart_value["ready"].IsBool() && chart_status->ready != chart_value["ready"].GetBool()) {
      chart_status->ready = chart_value["ready"].GetBool();
      need_update = true;
    }
  }
  // 组合没有 ready 字段, 通过 response 和 request 是否一致判断
  auto it = m_chart_traits.find(chart_id);
  if (it != m_chart_traits.end() && IsResponseSameAsChartTrait(it->second, *chart_status) && !it->second.weights.empty()
    && !chart_status->ready) {
    // @todo: 等待后台增加 ready 字段
    chart_status->ready = (chart_status->left_id != -1 || chart_status->right_id != -1);
    if (chart_status->ready)
      need_update = true;
  }
  if (unsubscribe && !chart_status->ready) {
    chart_status->ready = true;
    need_update = true;
  }
  // 更新图表信息.
  if (need_update) {
    ret = m_node_db->ReplaceRecord<ChartContent>(chart_status);
  }
  return ret;
}

bool MdServiceChart::UpdateChartWeights(const std::string& weights, std::map<std::string, double>* ret) const {
  if (weights.empty())
    return false;
  rapidjson::Document document;
  document.Parse(weights.data());
  if (!document.IsObject())
    return false;

  // {"SHFE.au2203":3.5,"SHFE.cu2203":1.0}
  // {"SHFE.au2203":null,"SHFE.cu2203":null}
  // {"SHFE.au2203":null,"SHFE.cu2203":3.5}
  for (auto it = document.MemberBegin(); it != document.MemberEnd(); ++it) {
    const std::string& key = it->name.GetString();
    if (!it->value.IsDouble()) {
      ret->erase(key);
      continue;
    }
    ret->insert_or_assign(key, it->value.GetDouble());
  }
  return true;
}

bool MdServiceChart::IsResponseSameAsChartTrait(const ChartTrait& trait, const ChartContent& reponse) const {
  if (trait.chart_id != reponse.chart_id)
    return false;
  if (trait.symbol_list != reponse.symbol_list)
    return false;
  if (trait.weights != reponse.weights)
    return false;
  if (trait.dur_nano != reponse.dur_nano)
    return false;
  return true;
}

std::shared_ptr<TickDataNode> MdServiceChart::GetTickNode(const std::string& symbol, const int32_t data_id) const {
  if (!m_data_root)
    return nullptr;
  auto node = m_data_root->GetChild<MdTreeKey::kTicks>()->GetChild(symbol);
  if (!node)
    return nullptr;
  return node->GetChild<MdInfoDataKey::kTick>()->GetChild(data_id);
}

void MdServiceChart::UpdateTickNode(
  const std::string& symbol, const int32_t data_id, std::function<void(std::shared_ptr<TickData>)> func) {
  if (!m_data_root)
    return;
  m_data_root->UpdateChild<md::MdTreeKey::kTicks>()
    ->UpdateChild(symbol)
    ->UpdateChild<md::MdInfoDataKey::kTick>()
    ->UpdateChild(data_id)
    ->UpdateContent(func);
}

void MdServiceChart::UpdateTickChangeInfo(md::TickData* data, md::TickData* prev_data) const {
  if (!data || !prev_data)
    return;
  data->prev_ask_price1 = prev_data->ask_price1;
  data->prev_bid_price1 = prev_data->bid_price1;
  data->prev_ask_price2 = prev_data->ask_price2;
  data->prev_bid_price2 = prev_data->bid_price2;
  data->prev_ask_price3 = prev_data->ask_price3;
  data->prev_bid_price3 = prev_data->bid_price3;
  data->prev_ask_price4 = prev_data->ask_price4;
  data->prev_bid_price4 = prev_data->bid_price4;
  data->prev_ask_price5 = prev_data->ask_price5;
  data->prev_bid_price5 = prev_data->bid_price5;
  data->price_change = data->last_price - prev_data->last_price;
  data->volume_change = data->volume - prev_data->volume;
  data->oi_change = data->open_interest - prev_data->open_interest;
}

