#include <boost/algorithm/string.hpp>

namespace fclib {
namespace md {

QuoteAutoSubscriber::QuoteAutoSubscriber(
  structlog::Logger& parent_logger, std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<QuoteSubscriber> subscriber)
  : m_logger(parent_logger.With("QuoteAutoSubscriber", reinterpret_cast<int64_t>(this)).Clone())
  , m_node_db(node_db)
  , m_subscriber(subscriber) {
  m_order_view = m_node_db->CreateView<future::Order>(ReuseViewKey::kOrder);
  m_position_view = m_node_db->CreateView<future::Position>(ReuseViewKey::kPosition);

  m_order_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::OrderNode> node, bool) {
      if (node->Historical() || !node->Snap())
        return;
      SubQuote(node->Snap()->ins_pointer);
    });
  m_position_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::PositionNode> node, bool) {
      if (node->Historical() || !node->Snap())
        return;
      SubQuote(node->Snap()->ins_pointer);
    });
}

const std::set<std::shared_ptr<QuoteSubscriber::QuoteHandle>>& QuoteAutoSubscriber::GetQuoteHandles() const {
  return m_quote_handles;
}

void QuoteAutoSubscriber::SubQuote(const NodePointer<md::Instrument>& node_pointer) {
  std::shared_ptr<md::InstrumentNode> ins_node = node_pointer;
  if (!ins_node) {
    auto key = node_pointer.Key();
    if (key.empty())
      return;
    ins_node = m_node_db->GetNode<md::Instrument>(key);
  }
  if (!ins_node)
    return;

  // 订阅行情
  m_quote_handles.insert(m_subscriber->SubscribeQuote(ins_node.get()));
  if (ins_node->Latest()->ProductClass() != md::ProductClass::kOption)
    return;
  auto underlying_node = ins_node->Latest()->instrument_base->underlying_pointer;
  if (!underlying_node)
    underlying_node = m_node_db->GetNode<md::Instrument>(ins_node->Latest()->instrument_base->underlying_pointer.Key());
  if (underlying_node)
    m_quote_handles.insert(m_subscriber->SubscribeQuote(underlying_node.get()));
}

}  // namespace md
}  // namespace fclib

