 ******************************************************************************/
#ifndef FCLIB_MD_SERVICE_HELPER_H
#define FCLIB_MD_SERVICE_HELPER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <memory>
#include <string>
#include <map>
#include <set>
#include <functional>

#include "fclib/model/model_shm.h"
#include "structlog/structlog.h"
#include <boost/interprocess/sync/named_sharable_mutex.hpp>
#include <boost/interprocess/sync/sharable_lock.hpp>

namespace fclib {
namespace md {
class MdServiceShmHelper {
 public:
  MdServiceShmHelper(const std::string& pid, structlog::Logger& logger);
  virtual ~MdServiceShmHelper() {
    CleanUp();
  }

  bool Init();
  void CleanUp();

  /*
   * 获取共享内存合约行情信息
   *
   * @param symbol: 合约代码
   * @param fake: 是否需要虚构, 默认为false, 当共享内存内无法找到合约代码且fake = true时, 会虚构出一个合约信息供使用.
   *
   * @return: 共享内存合约行情, nullopt 表示未找到.
   */
  std::optional<shm::ShmInstrument> GetShmInstrument(const std::string& symbol, bool fake = false);
  // 只适用期货交易所
  std::optional<shm::ShmInstrument> GetShmInstrumentByInsID(const std::string& instrument_id);
  std::optional<shm::ShmProduct> GetShmProduct(const std::string& instrument_id);
  md::TradeStatus GetShmTradeStatus(const std::string& symbol);

  /*
   * 遍历共享内存合约行情信息
   *
   * @param apply_func: 遍历应用函数
   *
   * @return: 是否成功.
   */
  bool VisitShmInstrument(std::function<bool(const shm::ShmInstrument*)> apply_func);

  const std::set<const shm::ShmInstrument*>& GetStockIndexInsNodes();

  template <typename T>
  inline std::optional<T> GetShmInstrumentField(
    const std::string& symbol, T shm::ShmInstrument::*memberPtr, bool fake = false) {
    if (m_error || nullptr == m_shm_instrument_map || nullptr == m_instrument_mutex)
      return std::nullopt;
    shm::ShmString key{};
    shm::AssignShmString(&key, symbol);
    {
      boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);
      auto it = m_shm_instrument_map->find(key);
      if (it != m_shm_instrument_map->end())
        return it->second.*memberPtr;
    }
    if (!fake)
      return std::nullopt;
    auto fake_ins = GetFakeShmInstrument(symbol);
    if (nullptr == fake_ins)
      return std::nullopt;
    return fake_ins->*memberPtr;
  }

  template <typename T>
  inline std::optional<T> GetShmProductField(const std::string& instrument_id, T shm::ShmProduct::*memberPtr) {
    if (m_error || nullptr == m_shm_product_map || nullptr == m_product_mutex)
      return std::nullopt;
    auto pos = std::find_if(instrument_id.begin(), instrument_id.end(), ::isdigit);
    std::string product_id = std::string(instrument_id.begin(), pos);
    shm::ShmString product_id_prefix{};
    shm::AssignShmString(&product_id_prefix, product_id + ".");
    boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_product_mutex);
    for (auto it = m_shm_product_map->lower_bound(product_id_prefix); it != m_shm_product_map->end(); ++it) {
      if (std::string(it->second.product_id.data()) == product_id)
        return it->second.*memberPtr;
    }
    return std::nullopt;
  }
  /*
   * 获取合约对应的衍生合约
   *
   * @param ins_key: 合约key
   *
   * @return: set 合约key
   */
  inline std::set<std::string> GetDerivativeInstruments(std::string ins_key) {
    std::set<std::string> ret;
    if (m_error || nullptr == m_shm_instrument_map || nullptr == m_instrument_mutex)
      return ret;
    shm::ShmString instrument_id_prefix{};
    shm::AssignShmString(&instrument_id_prefix, ins_key);
    boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);

    for (auto it = m_shm_instrument_map->lower_bound(instrument_id_prefix); it != m_shm_instrument_map->end(); ++it) {
      std::string str(it->first.data());
      if (str.find(ins_key) == std::string::npos) {
        break;
      }
      if (it->second.product_class == md::ProductClass::kOption) {
        ret.insert(it->first.data());
      }
    }
    return ret;
  }

 private:
  shm::ShmInstrument* GetFakeShmInstrument(const std::string& symbol);

  structlog::Logger m_logger;

  std::string m_shm_name;
  std::string m_shm_instrument_name;
  std::string m_shm_product_name;
  std::string m_shm_instrument_mutex;
  std::string m_shm_product_mutex;

  boost::interprocess::managed_shared_memory* m_segment = nullptr;
  shm::ShmInstrumentMap* m_shm_instrument_map = nullptr;
  shm::ShmProductMap* m_shm_product_map = nullptr;
  boost::interprocess::named_sharable_mutex* m_instrument_mutex = nullptr;
  boost::interprocess::named_sharable_mutex* m_product_mutex = nullptr;

  bool m_error = false;

  std::map<std::string, shm::ShmInstrument> m_fake_instruments;

  std::set<const shm::ShmInstrument*> m_stock_index_instruments;
};

}  // namespace md
}  // namespace fclib

