 ******************************************************************************/
#include "ins_status_service.h"
#include <string>
#include <memory>
#include <boost/algorithm/string.hpp>
#include "fclib/utils/fcassert.h"

#ifdef GetObject
#undef GetObject
#endif

namespace fclib {
namespace md {
std::shared_ptr<md::InstrumentNode> GetInstrumentNode(const std::string& input, std::shared_ptr<TqApiNodeDb> node_db);

std::string GetExchangeIdAndProductId(const std::string& symbol) {
  std::string ret;
  auto pos = std::find_if(symbol.begin(), symbol.end(), ::isdigit);
  ret = std::string(symbol.begin(), pos);
  FCASSERT(!ret.empty());
  return ret;
}

TradeStatus GetStatus(const std::string& status) {
  if (status == "BEFORETRADING")
    return TradeStatus ::kBeforeTrading;
  if (status == "AUCTIONORDERING")
    return TradeStatus ::kAuctionOrdering;
  if (status == "AUCTIONBALANCE")
    return TradeStatus ::kAuctionBalance;
  if (status == "AUCTIONMATCH")
    return TradeStatus ::kAuctionMatch;
  if (status == "CONTINOUS")
    return TradeStatus ::kContinous;
  if (status == "NOTRADING")
    return TradeStatus ::kNoTrading;
  if (status == "CLOSED")
    return TradeStatus ::kClosed;
  return TradeStatus::kUnknown;
}

InsStatusService::InsStatusService(
  boost::asio::io_context* ioc, structlog::Logger& parent_logger, std::shared_ptr<TqApiNodeDb> node_db)
  : m_ioc(ioc)
  , m_logger(parent_logger.With("InsStatusService", reinterpret_cast<int64_t>(this)).Clone())
  , m_node_db(node_db) {
  m_ins_view = m_node_db->CreateView<Instrument>([](std::shared_ptr<const Instrument> ins) -> bool {
    // 仅股指/股指期权/ETF/ETF期权 的 instrument_id 为数字
    return std::all_of(ins->instrument_id.begin(), ins->instrument_id.end(), ::isdigit);
  });
}

void InsStatusService::Connect() {
  m_ws_client = WebsocketClient::Create(m_ioc, m_logger);
  m_ws_client->OnSessionBegin([=](std::weak_ptr<WebsocketSession> s) {
    m_is_connected = true;
    m_logger.With("connection_status", "connected").Info("ins_status_service_connected");
    m_subscribe_success = DoSubscribe();
  });
  m_ws_client->OnSessionEnd([=](std::weak_ptr<WebsocketSession> s) {
    m_is_connected = false;
    m_subscribe_success = false;
    m_logger.With("connection_status", "disconnected").Info("ins_status_service_disconnected");
  });
  m_ws_client->OnSessionReceivedMessage([=](std::weak_ptr<WebsocketSession> session, const std::string& msg) {
    m_logger.With("msg", msg).Info("ins_status_service_msg");
    ProcessMsg(msg);
    std::string json_req = u8R"raw({"aid":"peek_message"})raw";
    session.lock()->SendTextMsg(json_req);
  });
  m_ws_client->Connect("ws://trading-status.shinnytech.com/v2/status");
}

void InsStatusService::ProcessMsg(const std::string& msg) {
  InsStatusParser ss;
  ss.FromString(msg.c_str());
  if (!ss.m_doc->HasMember("data"))
    return;
  rapidjson::Value& datas = (*ss.m_doc)["data"];
  if (!datas.IsObject())
    return;
  for (auto& [k, v] : datas.GetObject()) {
    std::string key = k.GetString();
    if (!v.IsObject())
      continue;
    auto sub_obj = v.GetObject();
    if (!sub_obj.HasMember("status"))
      continue;
    std::string status = (sub_obj["status"]).GetString();
    if (key.find("efp") != std::string::npos)
      continue;
    if (key.find("_tas") != std::string::npos)
      continue;
    if (key.find("_o") != std::string::npos)
      continue;
    if (std::find_if(key.begin(), key.end(), ::isdigit) != key.end()) {
      m_special_status[key] = status;
      m_change_special_status.insert(key);
      continue;
    }
    m_status[key] = status;
    m_change_status.insert(key);
  }
}

void InsStatusService::UpdateInsStatusByInsNode(std::shared_ptr<md::InstrumentNode> ins_node) {
  auto it_s = m_special_status.find(ins_node->Latest()->symbol);
  if (it_s != m_special_status.end())
    return;
  auto ex_pro = GetExchangeIdAndProductId(ins_node->Latest()->symbol);
  // 股指/股指期权/ETF/ETF期权
  // 仅股指/股指期权/ETF/ETF期权 的 instrument_id 为数字
  if (std::all_of(ins_node->Latest()->instrument_id.begin(), ins_node->Latest()->instrument_id.end(), ::isdigit)) {
    ex_pro = "CFFEX.IF";
  }
  auto it = m_status.find(ex_pro);
  if (it == m_status.end())
    return;
  SetInstrumentStatus(ins_node, it->second);
}

bool InsStatusService::DoSubscribe() {
  std::string json_req = u8R"raw({"aid":"subscribe_product_trade_status"})raw";
  auto session = m_ws_client->GetSession().lock();
  if (!session) {
    FCASSERT(false);
    return false;
  }
  session->SendTextMsg(json_req);
  return true;
}

void InsStatusService::RunOnce() {
  if (m_is_connected && !m_subscribe_success) {
    m_subscribe_success = DoSubscribe();
  }
  if (!m_change_status.empty()) {
    UpdateInsStatus();
    m_change_status.clear();
  }
  if (!m_change_special_status.empty()) {
    UpdateSpecialInsStatus();
    m_change_special_status.clear();
  }
}

void InsStatusService::_Test_Interface_GetMsg(const std::string& msg) {
  ProcessMsg(msg);
}

void InsStatusService::UpdateInsStatus() {
  for (const auto& exchang_id_product_id : m_change_status) {
    std::string status = m_status.at(exchang_id_product_id);
    auto& ins_map = m_node_db->GetNodeMap<md::Instrument>();
    for (auto it = ins_map.lower_bound(exchang_id_product_id); it != ins_map.end(); ++it) {
      auto symbol = it->second->Latest()->symbol;
      auto ex_pro = GetExchangeIdAndProductId(symbol);
      if (ex_pro != exchang_id_product_id)
        break;
      SetInstrumentStatus(it->second, status);
    }
    // 股指/股指期权/ETF/ETF期权
    if (exchang_id_product_id == "CFFEX.IF") {
      for (const auto& [_, ins_node] : m_ins_view->GetNodes()) {
        SetInstrumentStatus(ins_node, status);
      }
    }
  }
}

void InsStatusService::UpdateSpecialInsStatus() {
  for (const auto& symbol : m_change_special_status) {
    std::string status = m_special_status.at(symbol);
    auto ins_status = GetStatus(status);
    auto ins_node = GetInstrumentNode(symbol, m_node_db);
    if (ins_node->Latest()->_trade_status != ins_status) {
      m_node_db->ReplaceRecord<Instrument>(ins_node->Latest()->symbol, [&](std::shared_ptr<md::Instrument> ins) {
        ins->_trade_status = ins_status;
      });
    }
  }
}

void InsStatusService::SetInstrumentStatus(
  std::shared_ptr<md::InstrumentNode> ins_node, const std::string& ins_status) {
  if (auto status = GetStatus(ins_status); ins_node->Latest()->_trade_status != status) {
    m_node_db->ReplaceRecord<md::Instrument>(ins_node->Latest()->symbol, [&](std::shared_ptr<md::Instrument> ins) {
      ins->_trade_status = status;
    });
  }
  // 中金所的国债期货收盘时间为15:15, 收盘状态应以国债期货为准
  if (ins_node->Latest()->_trade_status == md::TradeStatus::kClosed && ins_node->Latest()->IsCffexIndex())
    return;
  auto exchange_node = m_node_db->GetNode<md::Exchange>(ins_node->Latest()->ExchangeID());
  if (!exchange_node || exchange_node->Latest()->trade_status != ins_node->Latest()->_trade_status) {
    m_node_db->ReplaceRecord<md::Exchange>(
      ins_node->Latest()->ExchangeID(), [&](std::shared_ptr<md::Exchange> exchange_info) {
        exchange_info->exchange_id = ins_node->Latest()->ExchangeID();
        if (ins_node->Latest()->_trade_status != exchange_info->trade_status) {
          exchange_info->trade_status = ins_node->Latest()->_trade_status;
        }
      });
  }
}

