// 获取所有股指以及股指 ETF 的合约节点.
const std::set<std::shared_ptr<fclib::md::InstrumentNode>>& GetStockIndexInsNodes(
  std::shared_ptr<TqApiNodeDb> node_db) {
  static std::map<std::shared_ptr<TqApiNodeDb>, std::set<std::shared_ptr<md::InstrumentNode>>> db_to_ins_nodes;
  auto& stock_index_ins_nodes = db_to_ins_nodes[node_db];
  if (!stock_index_ins_nodes.empty())
    return stock_index_ins_nodes;
  for (auto& [_, ins_node] : node_db->GetNodeMap<md::Instrument>()) {
    if (ins_node->Latest()->ProductClass() == md::ProductClass::kOption
      && ins_node->Latest()->instrument_base->underlying_pointer
      && (ins_node->Latest()->instrument_base->underlying_pointer->Latest()->ProductClass() == md::ProductClass::kIndex
        || ins_node->Latest()->instrument_base->underlying_pointer->Latest()->ProductClass()
          == md::ProductClass::kFund)) {
      stock_index_ins_nodes.insert(ins_node->Latest()->instrument_base->underlying_pointer);
    }
  }
  return stock_index_ins_nodes;
}

// 计算期权保证金率
double CalcOptionMarginRate(std::shared_ptr<md::Instrument> ins, std::shared_ptr<TqApiNodeDb> node_db) {
  if (!ins)
    return NAN;
  if (ins->ProductClass() != md::ProductClass::kOption)
    return NAN;
  if (isnan(ins->strike_price) || isnan(ins->pre_settlement))
    return NAN;
  auto underlying_node = ins->instrument_base->underlying_pointer;
  if (!underlying_node && !ins->instrument_base->underlying_pointer.Key().empty())
    underlying_node = node_db->GetNode<md::Instrument>(ins->instrument_base->underlying_pointer.Key());
  if (!underlying_node || isnan(underlying_node->Latest()->pre_settlement))
    return NAN;
  // 期权保证金计算公式参考深交所文档
  // http://docs.static.szse.cn/www/disclosure/notice/general/W020191207433397366259.pdf
  if (ins->option_class == md::OptionClass::kCall) {
    // 认购期权义务仓开仓保证金＝[合约最新价 + Max（12% × 合约标的最新价 - 认购期权虚值， 7% × 合约标的最新价）] ×
    // 合约单位
    // 认购期权虚值＝Max（行权价 - 合约标的最新价，0）
    auto out_value = std::max(ins->strike_price - underlying_node->Latest()->pre_settlement, 0.0);
    return (ins->pre_settlement
             + std::max(0.12 * underlying_node->Latest()->pre_settlement - out_value,
               0.07 * underlying_node->Latest()->pre_settlement))
      * ins->VolumeMultiple();
  } else {
    // 认沽期权义务仓开仓保证金＝Min[合约最新价+ Max（12% × 合约标的最新价 - 认沽期权虚值，7% × 行权价），行权价] ×
    // 合约单位
    // 认沽期权虚值＝Max（合约标的最新价 - 行权价，0）
    auto out_value = std::max(underlying_node->Latest()->pre_settlement - ins->strike_price, 0.0);
    return std::min(ins->pre_settlement
               + std::max(0.12 * underlying_node->Latest()->pre_settlement - out_value, 0.07 * ins->strike_price),
             ins->strike_price)
      * ins->VolumeMultiple();
  }
}

