void MdServiceObjectInfo::ReqSubscribeObjectInfo(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeObjectInfo>(m_manager->Update(c));
  // 生成伪合约表
  if (command->local_ins_generator) {
    if (m_ins_generator) {
      SetCommandFinished(command, -1, u8"已有本地合约表正在生成");
      return;
    }
    m_ins_generator = command->local_ins_generator;
    return;
  }
  if (m_test_mode) {
    SetCommandFinished(command);
    return;
  }
  // 调用 RTQ 合约服务接口
  if (RTQQuerySymbol(m_context_id, command->subscribe_id.c_str(), GetQueryObjectInfoTemplate(command).c_str(),
        GetQueryObjectInfoVariable(command).c_str())
    < 0) {
    SetCommandFinished(command, -1, u8"订阅合约请求未能正常发出");
  } else {
    m_manager->SetCommandId(command, GetCommandID(command->subscribe_id));
  }
}

void MdServiceObjectInfo::ReqSubscribeOptionsByUnderlyingSymbol(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeOptionsByUnderlyingSymbol>(m_manager->Update(c));
  // 检查参数有效性
  if (command->symbol.empty()) {
    SetCommandFinished(command, -1, u8"未指定基础合约");
    return;
  }
  if (m_test_mode) {
    SetCommandFinished(command);
    return;
  }
  // 调用 RTQ 合约服务接口
  if (RTQQuerySymbol(m_context_id, command->subscribe_id.c_str(), GetOptionUnderlyingTemplate(command).c_str(),
        GetOptionUnderlyingVariable(command).c_str())
    < 0) {
    SetCommandFinished(command, -1, u8"订阅期权合约请求未能正常发出");
  } else {
    m_manager->SetCommandId(command, GetCommandID(command->subscribe_id));
  }
}

void MdServiceObjectInfo::ReqGenerateInsTable(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<GenerateInsTable>(m_manager->Update(c));
  if (m_ins_generator) {
    SetCommandFinished(command, -1, u8"已有本地合约表正在生成");
    return;
  }
  m_ins_generator = command;
}

void MdServiceObjectInfo::ReqSubscribeComboInstrument(std::shared_ptr<UserCommand> c) {
  // 本地计算
  auto command = std::static_pointer_cast<SubscribeComboInstrument>(m_manager->Update(c));
  m_combo_infos.insert(command->combo_infos.begin(), command->combo_infos.end());
  m_combo_commands.emplace_back(command);
}

