std::shared_ptr<InstrumentNode> MdServiceObjectInfo::GetInstrumentNode(
  const std::string& input, std::shared_ptr<TqApiNodeDb> node_db) {
  std::string key = input;
  if (!key.empty() && key.at(0) == '.')
    key = key.substr(1);

  std::string exchange_id;
  size_t index = key.find(".");
  std::string instrument_id = (index != std::string::npos) ? key.substr(index + 1) : key;

  for (const auto& possible_exchange_id : MockPossibleExchangeIDs(key, node_db)) {
    exchange_id = possible_exchange_id;
    auto n = node_db->GetNode<md::Instrument>(exchange_id + "." + instrument_id);
    if (n && n->Latest()) {
      return n;
    }
  }

  // Mock Instrument
  auto ins = std::make_shared<md::Instrument>();
  auto ins_base = ins->instrument_base;
  ins->instrument_id = instrument_id;
  ins->symbol = exchange_id + "." + instrument_id;
  ins->expired = true;

  std::string product_id = instrument_id;
  product_id.erase(std::remove_if(product_id.begin(), product_id.end(), ::isdigit), product_id.end());

  MockProductBase(exchange_id, product_id, ins);
  const auto& product_class = ins_base->product_base->product_class;
  if (product_class == ProductClass::kCombine) {
    MockCombineInstrument(ins, node_db);
  } else if (product_class == ProductClass::kOption) {
    MockOptionInstrument(ins, node_db);
  }
  return ReplaceMockInstrument(ins, node_db);
}

