void MdServiceObjectInfo::InsVaribaleSerializer::DefineStruct(InsQueryVariables& d) {
  if (!d.instrument_id.empty()) {
    AddItem(d.instrument_id, "instrument_id");
  }
  if (!d.product_class.empty()) {
    AddItem(d.product_class, "class");
  }
  if (!d.exchange_id.empty()) {
    AddItem(d.exchange_id, "exchange_id");
  }
  if (!d.product_id.empty()) {
    AddItem(d.product_id, "product_id");
  }
  if (!d.underlying_symbol.empty()) {
    AddItem(d.underlying_symbol, "underlying_symbol");
  }
  if (d.underlying_symbol.empty() && d.expired_type != ExpiredType::kBoth) {
    bool expired_type = (d.expired_type == ExpiredType::kExpired) ? true : false;
    AddItem(expired_type, "expired");
  }
  if (d.has_night != HasNight::kNotSet) {
    bool has_night = (d.has_night == HasNight::kHasNight) ? true : false;
    AddItem(has_night, "has_night");
  }
  if (d.timestamp > 0) {
    AddItem(d.timestamp, "timestamp");
  }
}

