void MdServiceObjectInfo::ProcessCommand(const std::string& subscribe_id, rapidjson::Value& symbol) {
  if (symbol.IsNull())
    return;
  auto request = m_manager->Update(GetCommandID(subscribe_id));
  if (!request)
    return;
  if (symbol.HasMember("error")) {
    SetCommandFinished(request, -1, symbol["error"].GetString());
  } else {
    SetCommandFinished(request);
  }
  // 退订请求
  if (request->aid == SubscribeObjectInfo::AID) {
    auto command = std::static_pointer_cast<SubscribeObjectInfo>(request);
    RTQQuerySymbol(m_context_id, command->subscribe_id.c_str(), "", "{}");
  } else if (request->aid == SubscribeOptionsByUnderlyingSymbol::AID) {
    auto command = std::static_pointer_cast<SubscribeOptionsByUnderlyingSymbol>(request);
    RTQQuerySymbol(m_context_id, command->subscribe_id.c_str(), "", "{}");
  }
}

void MdServiceObjectInfo::ProcessSymbols(InsSerializer& ss, rapidjson::Value& symbols) {
  if (symbols.IsNull())
    return;
  if (!symbols.HasMember("result") || symbols["result"].IsNull())
    return;
  rapidjson::Value& results = symbols["result"];
  if (!results.HasMember("multi_symbol_info") || results["multi_symbol_info"].IsNull())
    return;
  std::vector<rapidjson::Value*> symbol_caches;
  std::map<std::string, std::map<std::string, NodePointer<Instrument>>> future_list;
  for (auto& record : results["multi_symbol_info"].GetArray()) {
    if (record.IsNull())
      continue;
    md::ProductBase product_base;
    ss.ToVar(product_base, &record);
    // 预先处理期货和指数合约, 其他先缓存
    if (product_base.product_class != md::ProductClass::kFuture
      && product_base.product_class != md::ProductClass::kIndex) {
      symbol_caches.emplace_back(&record);
      continue;
    }
    auto ins_node = ProcessSingleSymbol(ss, record, product_base);
    if (ins_node && product_base.product_class == md::ProductClass::kFuture) {
      NodePointer<md::Instrument> pointer(ins_node);
      future_list[ins_node->Latest()->ProductID()][ins_node->Latest()->symbol] = pointer;
    }
  }
  for (auto record : symbol_caches) {
    ProcessSingleSymbol(ss, *record);
  }
  for (const auto& [_, ret] : future_list) {
    ProcessProductNode(ret);
  }
}

std::shared_ptr<md::InstrumentNode> MdServiceObjectInfo::ProcessSingleSymbol(
  InsSerializer& ss, rapidjson::Value& symbols) {
  FCASSERT(symbols.IsObject());
  md::ProductBase product_base;
  ss.ToVar(product_base, &symbols);
  return ProcessSingleSymbol(ss, symbols, product_base);
}

std::shared_ptr<md::InstrumentNode> MdServiceObjectInfo::ProcessSingleSymbol(
  InsSerializer& ss, rapidjson::Value& symbols, md::ProductBase& product_base) {
  if (symbols.IsNull() || !symbols.IsObject() || !symbols.HasMember("instrument_id"))
    return nullptr;

  auto ins_node =
    m_node_db->ReplaceRecord<Instrument>(symbols["instrument_id"].GetString(), [&](std::shared_ptr<Instrument> ins) {
      ss.ToVar(*ins, &symbols);

      ProcessInstrumentBase(ss, symbols, product_base, ins);
      ProcessProductBase(product_base, ins);
      ProcessLegPointer(ss, symbols, ins);

      ProcessOptionRelated(ins);
    });

  ProcessDerivatedSymbols(ss, symbols, ins_node);
  ProcessUnderlyingSymbols(ss, symbols, ins_node);

  // 刷新合约交易状态
  m_ins_status_service->UpdateInsStatusByInsNode(ins_node);
  return ins_node;
}

void MdServiceObjectInfo::ProcessProductNode(const std::map<std::string, NodePointer<Instrument>>& ins_list) {
  auto ins_node = ins_list.begin()->second;
  std::string product_key = ins_node->Latest()->ProductID() + "." + ins_node->Latest()->ExchangeID();
  m_node_db->ReplaceRecord<Product>(product_key, [&](std::shared_ptr<Product> product_info) {
    if (product_info->exchange_id.empty()) {
      product_info->exchange_id = ins_node->Latest()->ExchangeID();
      product_info->mmsa = ins_node->Latest()->instrument_base->product_base->mmsa;
      product_info->product_class = ins_node->Latest()->ProductClass();
      product_info->product_id = ins_node->Latest()->ProductID();
      product_info->product_short_name = ins_node->Latest()->instrument_base->product_base->product_short_name;
      product_info->trading_time = ins_node->Latest()->instrument_base->product_base->trading_time;
    }
    product_info->instrument_list.insert(ins_list.begin(), ins_list.end());
  });
}

void MdServiceObjectInfo::ProcessInstrumentBase(
  InsSerializer& ss, rapidjson::Value& symbols, const md::ProductBase& product_base, std::shared_ptr<Instrument> ins) {
  if (product_base.product_class == ProductClass::kOption
    && !std::all_of(ins->instrument_id.begin(), ins->instrument_id.end(), ::isdigit)) {
    // 期权复用 instrument_base
    // instrument_id 全部为数字的期权如ETF 期权无法复用,直接序列化
    std::string_view instrument_id = ins->instrument_id;
    auto pos = instrument_id.find_first_not_of("0123456789", 4);
    // 对于郑商所期权，由于系列期权的存在,形如 CZCE.SR503MSC5500，将 key 改为包含 MS, 即 SR503MS
    pos = instrument_id.find_first_of("PC-", pos);
    std::string underlying_ins = ins->instrument_id.substr(0, pos);
    auto iter = s_underlying_base.find(underlying_ins);
    if (iter != s_underlying_base.end()) {
      ins->instrument_base = iter->second;
      return;
    }
    s_underlying_base[underlying_ins] = ins->instrument_base;
  }
  // 序列化 instrument_base
  ss.ToVar(*(ins->instrument_base), &symbols);
}

void MdServiceObjectInfo::ProcessProductBase(md::ProductBase& product_base, std::shared_ptr<Instrument> ins) {
  // 处理 product_id
  if (product_base.product_class == ProductClass::kOption) {
    ProcessOptionProductID(product_base, ins);
  } else if ((product_base.product_class == ProductClass::kCont || product_base.product_class == ProductClass::kIndex)
    && product_base.product_id.empty()) {
    product_base.product_id = ins->instrument_id;
  }
  // 处理指针 instrument_base->product_base
  ProcessInsProductBase(product_base, ins);
  // 处理 ETF product_base
  ProcessETFProductBase(ins);
}

void MdServiceObjectInfo::ProcessOptionProductID(md::ProductBase& product_base, std::shared_ptr<Instrument> ins) {
  FCASSERT(product_base.product_class == ProductClass::kOption);
  if (!product_base.product_id.empty())
    return;
  // 赋值 product_id
  std::string_view instrument_id = ins->instrument_id;
  auto pos = instrument_id.find_first_of("0123456789");
  if (pos != 0) {
    product_base.product_id = ins->instrument_id.substr(0, pos);
    // 中金所: 直接使用截断字符串, 如 IO / HO / MO
    // 非中金所: 期权 product_id 为 标的 product_id + "_O", 如 cu_O
    if (product_base.exchange_id != "CFFEX")
      product_base.product_id = product_base.product_id + "_O";
  } else {
    product_base.product_id = product_base.product_short_name;
  }
}

void MdServiceObjectInfo::ProcessInsProductBase(md::ProductBase& product_base, std::shared_ptr<Instrument> ins) {
  // 外盘 / 主连 / 指数 -> 没有标的, 使用独立的 product_base
  if (product_base.exchange_id == "KQD" || product_base.product_class == ProductClass::kCont
    || product_base.product_class == ProductClass::kIndex) {
    ins->instrument_base->product_base = std::make_shared<md::ProductBase>(product_base);
    return;
  }
  // 上交所 / 深交所 -> 使用独立的 product_base, 因为 product_id 会重复
  if (product_base.exchange_id == "SSE" || product_base.exchange_id == "SZSE") {
    ins->instrument_base->product_base = std::make_shared<md::ProductBase>(product_base);
    return;
  }
  // 使用 s_product_base, 根据 product_id 复用 product_base
  if (!product_base.product_id.empty()) {
    auto iter1 = s_product_base.find(std::string(product_base.product_id + product_base.product_short_name));
    if (iter1 != s_product_base.end()) {
      ins->instrument_base->product_base = iter1->second;
    } else {
      ins->instrument_base->product_base = std::make_shared<md::ProductBase>(product_base);
      s_product_base[product_base.product_id + product_base.product_short_name] = ins->instrument_base->product_base;
    }
  } else {
    ins->instrument_base->product_base = std::make_shared<md::ProductBase>(product_base);
  }
}

void MdServiceObjectInfo::ProcessETFProductBase(std::shared_ptr<Instrument> ins) {
  static std::map<std::string_view, std::vector<std::string_view>> etf_map = {
    {u8"510050", {u8"上证50ETF", u8"50ETF", u8"50ETF"}},
    {u8"510300", {u8"沪深300ETF(沪)", u8"300ETF(沪)", u8"300ETF"}},
    {u8"159919", {u8"沪深300ETF(深)", u8"300ETF(深)", u8"300ETF"}},
    {u8"510500", {u8"中证500ETF(沪)", u8"500ETF(沪)", u8"500ETF"}},
    {u8"159922", {u8"中证500ETF(深)", u8"500ETF(深)", u8"500ETF"}},
    {u8"159915", {u8"创业板ETF", u8"创业板ETF", u8"创业板ETF"}},
    {u8"159901", {u8"深证100ETF", u8"100ETF(深)", u8"100ETF"}},
  };

  if (ins->instrument_name.empty()) {
    auto etf_iter = etf_map.find(ins->instrument_id);
    if (etf_iter != etf_map.end()) {
      ins->instrument_name = etf_iter->second[0];
      ins->instrument_base->product_base->product_id = ins->instrument_id;
      ins->instrument_base->product_base->product_short_name = etf_iter->second[1];
      ins->english_name = etf_iter->second[2];
      ins->instrument_base->product_base->price_decs = 4;
      ins->instrument_base->price_tick = 0.0001;
    }
  }
}

void MdServiceObjectInfo::ProcessLegPointer(
  InsSerializer& ss, rapidjson::Value& symbols, std::shared_ptr<Instrument> ins) {
  if (symbols.HasMember("leg1")) {
    if (symbols["leg1"].HasMember("instrument_id") && symbols["leg1"]["instrument_id"].IsString()) {
      auto leg_id = symbols["leg1"]["instrument_id"].GetString();
      ins->instrument_base->leg1_pointer = m_node_db->GetNode<Instrument>(leg_id);
      if (!ins->instrument_base->leg1_pointer)
        ins->instrument_base->leg1_pointer = ProcessSingleSymbol(ss, symbols["leg1"]);
    }
  }
  if (symbols.HasMember("leg2")) {
    if (symbols["leg2"].HasMember("instrument_id") && symbols["leg2"]["instrument_id"].IsString()) {
      auto leg_id = symbols["leg2"]["instrument_id"].GetString();
      ins->instrument_base->leg2_pointer = m_node_db->GetNode<Instrument>(leg_id);
      if (!ins->instrument_base->leg2_pointer)
        ins->instrument_base->leg2_pointer = ProcessSingleSymbol(ss, symbols["leg2"]);
    }
  }
}

void MdServiceObjectInfo::ProcessOptionRelated(std::shared_ptr<Instrument> ins) {
  if (ins->ProductClass() != ProductClass::kOption)
    return;
  // 更新保证金
  if (isnan(ins->instrument_base->margin))
    ins->instrument_base->margin = CalcOptionMarginRate(ins, m_node_db);
  if (ins->instrument_base->last_exercise_day_str.empty())
    return;
  // 更新交割年/月
  if (ins->instrument_base->delivery_year == 0)
    ins->instrument_base->delivery_year = std::atoi(ins->instrument_base->last_exercise_day_str.substr(0, 4).c_str());
  if (ins->instrument_base->delivery_month == 0)
    ins->instrument_base->delivery_month = std::atoi(ins->instrument_base->last_exercise_day_str.substr(4, 2).c_str());
}

void MdServiceObjectInfo::ProcessDerivatedSymbols(
  InsSerializer& ss, rapidjson::Value& symbols, std::shared_ptr<InstrumentNode> underlying_node) {
  if (!underlying_node || !underlying_node->Latest())
    return;
  if (!symbols.HasMember("derivatives") || symbols["derivatives"].IsNull())
    return;
  if (!symbols["derivatives"].HasMember("edges") || symbols["derivatives"]["edges"].IsNull())
    return;

  auto& derivative_edges = symbols["derivatives"]["edges"];
  FCASSERT(derivative_edges.IsArray());

  auto& underlying_symbol = underlying_node->Latest()->symbol;

  // 更新标的合约节点
  m_node_db->ReplaceRecord<Instrument>(underlying_symbol, [&](std::shared_ptr<Instrument> ins) {
    for (auto& r : derivative_edges.GetArray()) {
      auto derivate_node = ProcessSingleSymbol(ss, r["node"]);
      if (!derivate_node)
        continue;

      auto& derivate_symbol = derivate_node->Latest()->symbol;
      ins->instrument_base->derivate_pointer[derivate_symbol] = derivate_node;
      if (derivate_node->Latest()->ProductClass() == ProductClass::kCont)
        ins->instrument_base->main_in_series = true;

      // 更新衍生合约节点
      m_node_db->ReplaceRecord<Instrument>(derivate_symbol, [=](std::shared_ptr<md::Instrument> ins) {
        ins->instrument_base->underlying_pointer = underlying_node;
      });
    }
  });
}

void MdServiceObjectInfo::ProcessUnderlyingSymbols(
  InsSerializer& ss, rapidjson::Value& symbols, std::shared_ptr<InstrumentNode> derivate_node) {
  if (!derivate_node || !derivate_node->Latest())
    return;
  if (!symbols.HasMember("underlying") || symbols["underlying"].IsNull())
    return;
  if (!symbols["underlying"].HasMember("edges") || symbols["underlying"]["edges"].IsNull())
    return;
  auto& underlying_edges = symbols["underlying"]["edges"];
  if (underlying_edges.Size() != 1)
    return;
  if (!underlying_edges.Begin()->HasMember("node") || (*underlying_edges.Begin())["node"].IsNull())
    return;
  auto& t_node = (*underlying_edges.Begin())["node"];
  if (!t_node.HasMember("instrument_id") || !t_node["instrument_id"].IsString())
    return;

  std::string underlying_symbol = t_node["instrument_id"].GetString();
  auto underlying_node = m_node_db->GetNode<md::Instrument>(underlying_symbol);
  if (!underlying_node)
    underlying_node = ProcessSingleSymbol(ss, t_node);
  if (!underlying_node)
    return;

  auto& derivate_symbol = derivate_node->Latest()->symbol;

  // 更新衍生合约节点
  m_node_db->ReplaceRecord<Instrument>(derivate_symbol, [=](std::shared_ptr<md::Instrument> ins) {
    ins->instrument_base->underlying_pointer = underlying_node;
    if (ins->instrument_base->delivery_year == 0)
      ins->instrument_base->delivery_year = underlying_node->Latest()->instrument_base->delivery_year;
    if (ins->instrument_base->delivery_month == 0)
      ins->instrument_base->delivery_month = underlying_node->Latest()->instrument_base->delivery_month;
  });

  // 更新标的合约节点
  m_node_db->ReplaceRecord<Instrument>(underlying_symbol, [&](std::shared_ptr<Instrument> ins) {
    ins->instrument_base->derivate_pointer[derivate_symbol] = derivate_node;
    if (derivate_node->Latest()->ProductClass() == ProductClass::kCont)
      ins->instrument_base->main_in_series = true;
  });
}

int MdServiceObjectInfo::ProcessInsGenerator() {
  if (!m_ins_generator)
    return 0;
  auto ins_generator = std::make_shared<LocalInsGenerator>();
  ins_generator->Generate(m_node_db, m_ins_generator->start_year);
  SetCommandFinished(m_ins_generator);
  m_ins_generator = nullptr;
  return 1;
}

int MdServiceObjectInfo::ProcessComboInstrument() {
  int ret = static_cast<int>(m_combo_infos.size());
  for (const auto& [key, combo_info] : m_combo_infos) {
    if (combo_info.empty()) {
      m_node_db->DeleteRecord<md::Instrument>(key);
      continue;
    }
    auto ins = std::make_shared<md::Instrument>();
    ins->instrument_base->product_base->product_class = ProductClass::kCusCombine;
    ins->symbol = key;
    ins->instrument_base->expire_date_time = INT64_MAX;
    ins->instrument_base->product_base->price_decs = 0;
    ins->instrument_base->price_tick = 10000000.0;
    for (const auto& [leg_symbol, weight] : combo_info) {
      // "1" 对应常数项
      if ("1" == leg_symbol) {
        ins->instrument_base->constant_term = weight;
        continue;
      }
      auto leg_ins_node = m_node_db->GetNode<md::Instrument>(leg_symbol);
      FCASSERT(leg_ins_node);
      FCASSERT(fabs(weight) > 1e-5);
      if (ins->ExchangeID().empty())
        ins->instrument_base->product_base->exchange_id = leg_ins_node->Latest()->ExchangeID();
      ins->instrument_base->expire_date_time =
        std::min(ins->instrument_base->expire_date_time, leg_ins_node->Latest()->instrument_base->expire_date_time);
      int32_t weight_decs = 2;
      while (weight_decs > 0 && (static_cast<int32_t>(std::round(weight * std::pow(10, weight_decs))) % 10 == 0)) {
        --weight_decs;
      }
      ins->instrument_base->product_base->price_decs =
        std::max(ins->PriceDecs(), leg_ins_node->Latest()->PriceDecs() + weight_decs);
      ins->instrument_base->price_tick = std::min(ins->PriceTick(), leg_ins_node->Latest()->PriceTick());
      ins->instrument_base->weight[leg_ins_node] = weight;
    }
    m_node_db->ReplaceRecord<md::Instrument>(ins);
  }

  for (const auto& command : m_combo_commands) {
    SetCommandFinished(command);
  }
  m_combo_infos.clear();
  m_combo_commands.clear();
  return ret;
}

std::vector<std::string> MdServiceObjectInfo::MockPossibleExchangeIDs(
  std::string key, std::shared_ptr<TqApiNodeDb> node_db) {
  if (size_t index = key.find("."); index != std::string::npos) {
    return {key.substr(0, index)};
  }
  std::vector<std::string> ret;
  if (key.find("&") != std::string::npos) {
    char first_char = key[key.find(" ") + 1];
    if (first_char <= 'Z') {
      ret.emplace_back("CZCE");
    } else {
      ret.emplace_back("DCE");
      ret.emplace_back("GFEX");
    }
  } else if (std::all_of(key.begin(), key.end(), ::isdigit)) {
    ret.emplace_back("SZSE");
    ret.emplace_back("SSE");
  } else {
    if (key[0] < 'Z' && key.find('-') != std::string::npos) {
      ret.emplace_back("CFFEX");
    } else {
      if (auto product_node = GetProductNode(key, node_db))
        ret.emplace_back(product_node->Latest()->exchange_id);
    }
  }
  return ret;
}

ProductClass MdServiceObjectInfo::MockProductClass(const std::string& instrument_id) {
  ProductClass ret = ProductClass::kFuture;
  if (size_t index1 = instrument_id.find("&"); index1 != std::string::npos) {
    ret = ProductClass::kCombine;
  } else {
    // 数字后面仍有非数字, 判定为期权
    auto p0 = instrument_id.find_first_of("0123456789");
    if (instrument_id.find_first_not_of("0123456789", p0) != std::string::npos)
      ret = ProductClass::kOption;
  }
  return ret;
}

void MdServiceObjectInfo::MockProductBase(
  const std::string& exchange_id, const std::string& product_id, std::shared_ptr<Instrument> ins) {
  auto product_class = MockProductClass(ins->instrument_id);
  // 尝试复用 product_base
  if (!product_id.empty()) {
    if (s_product_base.find(product_id) == s_product_base.end()) {
      ins->instrument_base->product_base->exchange_id = exchange_id;
      ins->instrument_base->price_tick = 1;
      ins->instrument_base->product_base->price_decs = 0;
      ins->instrument_base->product_base->product_id = product_id;
      ins->instrument_base->product_base->product_class = product_class;
      s_product_base[product_id] = ins->instrument_base->product_base;
    } else {
      ins->instrument_base->product_base = s_product_base[product_id];
    }
  } else {
    ins->instrument_base->product_base->exchange_id = exchange_id;
    ins->instrument_base->price_tick = 1;
    ins->instrument_base->product_base->price_decs = 0;
    ins->instrument_base->product_base->product_id = product_id;
    ins->instrument_base->product_base->product_class = product_class;
  }
}

void MdServiceObjectInfo::MockCombineInstrument(std::shared_ptr<Instrument> ins, std::shared_ptr<TqApiNodeDb> node_db) {
  size_t index0 = ins->instrument_id.find(" ");
  size_t index1 = ins->instrument_id.find("&");

  std::string leg1 = ins->instrument_base->product_base->exchange_id + "."
    + ins->instrument_id.substr(index0 + 1, index1 - (index0 + 1));
  std::string leg2 = ins->instrument_base->product_base->exchange_id + "." + ins->instrument_id.substr(index1 + 1);
  ins->instrument_base->leg1_pointer = GetInstrumentNode(leg1, node_db);
  ins->instrument_base->leg2_pointer = GetInstrumentNode(leg2, node_db);
  if (ins->instrument_base->leg1_pointer && ins->instrument_base->leg2_pointer) {
    auto leg1_ins = ins->instrument_base->leg1_pointer->Latest();
    auto leg2_ins = ins->instrument_base->leg2_pointer->Latest();
    ins->pre_settlement = leg1_ins->pre_settlement - leg2_ins->pre_settlement;
    ins->pre_close = leg1_ins->pre_close - leg2_ins->pre_close;
    ins->instrument_base->price_tick = std::min(leg1_ins->PriceTick(), leg2_ins->PriceTick());
    ins->instrument_base->product_base->price_decs = std::max(leg1_ins->PriceDecs(), leg2_ins->PriceDecs());
    ins->expired = true;
  }
}

void MdServiceObjectInfo::MockOptionInstrument(std::shared_ptr<Instrument> ins, std::shared_ptr<TqApiNodeDb> node_db) {
  if (ins->instrument_id.empty()) {
    return;
  }
  std::string_view instrument_id = ins->instrument_id;
  auto p0 = instrument_id.find_first_of("0123456789");
  auto pos0 = instrument_id.find_first_not_of("0123456789", 4);
  auto pos1 = instrument_id.find_last_not_of("0123456789.");
  if (instrument_id.find_first_of("Pp", pos0) != std::string_view::npos)
    ins->option_class = md::OptionClass::kPut;
  else
    ins->option_class = md::OptionClass::kCall;
  ins->strike_price = atof(ins->instrument_id.substr(pos1 + 1).c_str());
  if (ins->ExchangeID() == "CFFEX") {
    auto iter_option = s_underlying_base.lower_bound(ins->instrument_id.substr(0, p0));
    if (iter_option != s_underlying_base.end()
      && strncmp(iter_option->first.c_str(), ins->instrument_id.c_str(), p0) == 0) {
      ins->instrument_base->underlying_pointer = iter_option->second->underlying_pointer;
    } else {
      auto underlying_id =
        ins->ExchangeID() + ".I" + ((ins->instrument_id.data()[0] == 'I') ? 'F' : ins->instrument_id.data()[0]);
      auto underlying_symbol = underlying_id + ins->instrument_id.substr(p0, pos0 - p0);
      ins->instrument_base->underlying_pointer = GetInstrumentNode(underlying_symbol, node_db);
    }
  } else {
    auto underlying_symbol = ins->ExchangeID() + "." + ins->instrument_id.substr(0, pos0);
    ins->instrument_base->underlying_pointer = GetInstrumentNode(underlying_symbol, node_db);
  }
}

std::shared_ptr<InstrumentNode> MdServiceObjectInfo::ReplaceMockInstrument(
  std::shared_ptr<Instrument> ins, std::shared_ptr<TqApiNodeDb> node_db) {
  auto ins_node = node_db->ReplaceRecord<md::Instrument>(ins);
  if (!ins->ProductID().empty()) {
    std::string product_key = ins->ProductID() + "." + ins->ExchangeID();
    node_db->ReplaceRecord<Product>(product_key, [ins_node, ins](std::shared_ptr<Product> product_info) {
      if (product_info->exchange_id.empty()) {
        product_info->exchange_id = ins->ExchangeID();
        product_info->mmsa = ins->instrument_base->product_base->mmsa;
        product_info->product_class = ins->ProductClass();
        product_info->product_id = ins->ProductID();
      }
      NodePointer<md::Instrument> pointer(ins_node);
      product_info->instrument_list[ins_node->Latest()->symbol] = pointer;
    });
  }
  return ins_node;
}

std::shared_ptr<InstrumentNode> GetInstrumentNode(const std::string& key, std::shared_ptr<TqApiNodeDb> node_db) {
  return MdServiceObjectInfo::GetInstrumentNode(key, node_db);
}

std::shared_ptr<md::ProductNode> GetProductNode(
  const std::string& instrument_id, std::shared_ptr<TqApiNodeDb> node_db) {
  auto pos = std::find_if(instrument_id.begin(), instrument_id.end(), ::isdigit);
  auto product_id = std::string(instrument_id.begin(), pos);
  const auto& node_map = node_db->GetNodeMap<md::Product>();
  for (auto it = node_map.lower_bound(product_id + "."); it != node_map.end(); ++it) {
    if (it->second->Latest()->product_id == product_id)
      return it->second;
  }
  return nullptr;
}

