    && (std::string(exchange_id.data()) == "SHFE" || std::string(exchange_id.data()) == "INE");
}

bool ShmInstrument::CheckQuote(const std::string& trading_day) const {
  // 若行情日期与交易日不同, 且更新时间在9.00~16.00之间, 则行情无效
  // 行情一旦有效,今日应当均有效,目前 fclib 不支持切换交易日
  if (_market_data_valid)
    return true;
  auto local_time = EpochNanoToLocalDateTime(update_time);
  local_time.date_time.tm_year += 1900;
  local_time.date_time.tm_mon += 1;
  std::string quote_date = std::to_string(
    local_time.date_time.tm_year * 10000 + local_time.date_time.tm_mon * 100 + local_time.date_time.tm_mday);
  if (trading_day != quote_date && local_time.date_time.tm_hour < 16 && local_time.date_time.tm_hour > 8)
    return false;
  _market_data_valid = true;
  return true;
}

bool ShmInstrument::IsCffexIndex() const {
  if (std::string(exchange_id.data()) == "CFFEX")
    return instrument_id[0] == 'I';
  return false;
}

