MdServiceShmHelper::MdServiceShmHelper(const std::string& pid, structlog::Logger& logger)
  : m_logger(logger.With("md_servive_shm_helper", reinterpret_cast<int64_t>(this)).Clone()) {
  m_shm_name = pid + shm::ShmName;
  m_shm_instrument_name = pid + shm::ShmInstrumentName;
  m_shm_product_name = pid + shm::ShmProductName;
  m_shm_instrument_mutex = pid + shm::ShmInstrumentMutex;
  m_shm_product_mutex = pid + shm::ShmProductMutex;
}

bool MdServiceShmHelper::Init() {
  m_logger.With("fun", "Init")
    .With("shm_name", m_shm_name)
    .With("shm_instrument_mutex", m_shm_instrument_mutex)
    .With("shm_product_mutex", m_shm_product_mutex)
    .Info("Init");
  try {
#ifdef _WIN32
    std::wstring wshm_name, wshm_instrument_mutex, wshm_product_mutex;
    StringToWString(m_shm_name, CP_UTF8, &wshm_name);
    StringToWString(m_shm_instrument_mutex, CP_UTF8, &wshm_instrument_mutex);
    StringToWString(m_shm_product_mutex, CP_UTF8, &wshm_product_mutex);
    m_segment = new boost::interprocess::managed_shared_memory(boost::interprocess::open_only, wshm_name.c_str());
    m_instrument_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::open_only, wshm_instrument_mutex.c_str());
    m_product_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::open_only, wshm_product_mutex.c_str());
#else
    m_segment = new boost::interprocess::managed_shared_memory(boost::interprocess::open_only, m_shm_name.c_str());
    m_instrument_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::open_only, m_shm_instrument_mutex.c_str());
    m_product_mutex =
      new boost::interprocess::named_sharable_mutex(boost::interprocess::open_only, m_shm_product_mutex.c_str());
#endif
    m_shm_instrument_map = m_segment->find<shm::ShmInstrumentMap>(m_shm_instrument_name.c_str()).first;
    m_shm_product_map = m_segment->find<shm::ShmProductMap>(m_shm_product_name.c_str()).first;
    return true;
  } catch (const std::exception& ex) {
    m_error = true;
    m_logger.With("fun", "Init").With("errmsg", LocalToUtf8(ex.what())).Error("open shared memory fail");
    return false;
  }
}

void MdServiceShmHelper::CleanUp() {
  try {
    if (nullptr != m_segment) {
      delete m_segment;
      m_segment = nullptr;
    }
    if (nullptr != m_instrument_mutex) {
      delete m_instrument_mutex;
      m_instrument_mutex = nullptr;
    }
    if (nullptr != m_product_mutex) {
      delete m_product_mutex;
      m_product_mutex = nullptr;
    }
    m_logger.With("fun", "CleanUp").Info("md_servive_shm_helper cleanup success");
  } catch (std::exception& ex) {
    m_error = true;
    m_logger.With("fun", "CleanUp").With("errmsg", LocalToUtf8(ex.what())).Error("md_servive_shm_helper cleanup fail");
  }
}

std::optional<shm::ShmInstrument> MdServiceShmHelper::GetShmInstrument(
  const std::string& symbol, bool fake /*= false*/) {
  if (m_error || nullptr == m_shm_instrument_map || nullptr == m_instrument_mutex || symbol.empty())
    return std::nullopt;
  shm::ShmString key{};
  shm::AssignShmString(&key, symbol);
  {
    // 共享锁
    boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);
    auto it = m_shm_instrument_map->find(key);
    if (it != m_shm_instrument_map->end())
      return it->second;
  }
  if (!fake)
    return std::nullopt;
  // fake 合约信息
  auto fake_ins = GetFakeShmInstrument(symbol);
  if (nullptr == fake_ins)
    return std::nullopt;
  return *fake_ins;
}

std::optional<shm::ShmInstrument> MdServiceShmHelper::GetShmInstrumentByInsID(const std::string& instrument_id) {
  auto product = GetShmProduct(instrument_id);
  if (product.has_value()) {
    return GetShmInstrument(std::string(product->exchange_id.data()) + "." + instrument_id);
  }
  for (const auto& ex_id : {"CFFEX", "CZCE", "DCE", "SHFE", "GFEX", "INE"}) {
    auto ins = GetShmInstrument(std::string(ex_id) + "." + instrument_id);
    if (ins.has_value())
      return ins;
  }
  return std::nullopt;
}

std::optional<shm::ShmProduct> MdServiceShmHelper::GetShmProduct(const std::string& instrument_id) {
  if (m_error || nullptr == m_shm_product_map || nullptr == m_product_mutex)
    return std::nullopt;
  auto pos = std::find_if(instrument_id.begin(), instrument_id.end(), ::isdigit);
  std::string product_id = std::string(instrument_id.begin(), pos);
  shm::ShmString product_id_prefix{};
  shm::AssignShmString(&product_id_prefix, product_id + ".");
  // 共享锁
  boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_product_mutex);
  for (auto it = m_shm_product_map->lower_bound(product_id_prefix); it != m_shm_product_map->end(); ++it) {
    if (std::string(it->second.product_id.data()) == product_id)
      return it->second;
  }
  return std::nullopt;
}

md::TradeStatus MdServiceShmHelper::GetShmTradeStatus(const std::string& symbol) {
  auto ins = GetShmInstrument(symbol);
  if (!ins.has_value())
    return md::TradeStatus::kUnknown;
  if (std::string(ins->exchange_id.data()) == "KQ") {
    if (!ins->underlying_symbol.empty()) {
      auto underlying_ins = GetShmInstrument(std::string(ins->underlying_symbol.data()));
      if (underlying_ins)
        return underlying_ins->trade_status;
    }
  } else if (ins->product_class == md::ProductClass::kCombine) {
    if (!ins->leg1_symbol.empty()) {
      auto leg1_ins = GetShmInstrument(std::string(ins->leg1_symbol.data()));
      if (leg1_ins) {
        auto status = leg1_ins->trade_status;
        if (status >= md::TradeStatus::kBeforeTrading && status <= md::TradeStatus::kAuctionMatch)
          return md::TradeStatus::kBeforeTrading;
        return status;
      }
    }
  }
  return ins->trade_status;
}

bool MdServiceShmHelper::VisitShmInstrument(std::function<bool(const shm::ShmInstrument*)> apply_func) {
  if (m_error || nullptr == m_shm_instrument_map || nullptr == m_instrument_mutex)
    return false;
  {
    boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);
    for (const auto& [_, ins] : *m_shm_instrument_map) {
      if (!apply_func(&ins))
        break;
    }
  }
  return true;
}

const std::set<const shm::ShmInstrument*>& MdServiceShmHelper::GetStockIndexInsNodes() {
  if (m_error || nullptr == m_shm_instrument_map || nullptr == m_instrument_mutex || !m_stock_index_instruments.empty())
    return m_stock_index_instruments;
  {
    boost::interprocess::sharable_lock<boost::interprocess::named_sharable_mutex> lock(*m_instrument_mutex);

    for (const auto& [_, ins] : *m_shm_instrument_map) {
      if (ins.product_class != md::ProductClass::kOption || ins.underlying_symbol.empty())
        continue;
      auto iter = m_shm_instrument_map->find(ins.underlying_symbol);
      if (iter == m_shm_instrument_map->end())
        continue;
      if (iter->second.product_class == md::ProductClass::kIndex
        || iter->second.product_class == md::ProductClass::kFund) {
        m_stock_index_instruments.insert(&iter->second);
      }
    }
  }
  return m_stock_index_instruments;
}

shm::ShmInstrument* MdServiceShmHelper::GetFakeShmInstrument(const std::string& symbol) {
  auto it = m_fake_instruments.find(symbol);
  if (it != m_fake_instruments.end())
    return &it->second;
  size_t index = symbol.find(".");
  if (index == std::string::npos)
    return nullptr;
  std::string exchange_id = symbol.substr(0, index);
  std::string instrument_id = symbol.substr(index + 1);

  shm::ShmInstrument shm_instrument;

  shm::AssignShmString(&shm_instrument.exchange_id, exchange_id);
  shm::AssignShmString(&shm_instrument.instrument_id, instrument_id);
  shm::AssignShmString(&shm_instrument.symbol, symbol);

  shm_instrument.price_tick = 1;
  size_t index0 = instrument_id.find(" ");
  index = instrument_id.find("&");
  if (index != std::string::npos) {
    shm_instrument.product_class = md::ProductClass::kCombine;
    std::string symbol1 = exchange_id + "." + instrument_id.substr(index0 + 1, index - (index0 + 1));
    std::string symbol2 = exchange_id + "." + instrument_id.substr(index + 1);
    shm::AssignShmString(&shm_instrument.leg1_symbol, symbol1);
    shm::AssignShmString(&shm_instrument.leg2_symbol, symbol2);
    auto leg1 = GetShmInstrument(symbol1, true);
    auto leg2 = GetShmInstrument(symbol2, true);
    if (leg1.has_value() && leg2.has_value()) {
      shm_instrument.pre_settlement = leg1->pre_settlement - leg2->pre_settlement;
      shm_instrument.settlement = leg1->settlement - leg2->settlement;
      shm_instrument.margin = (std::min)(leg1->margin, leg2->margin);
      shm_instrument.commission = (std::min)(leg1->commission, leg2->commission);
      shm_instrument.price_tick = (std::min)(leg1->price_tick, leg2->price_tick);
      shm_instrument.volume_multiple = (std::min)(leg1->volume_multiple, leg2->volume_multiple);
      std::string comb_product_id =
        instrument_id.substr(0, index0 + 1) + leg1->product_id.data() + "&" + leg2->product_id.data();
      shm::AssignShmString(&shm_instrument.product_id, comb_product_id);
    }
  } else {
    shm_instrument.price_tick = 1;
    auto pos_p = instrument_id.find('P', 4);
    auto pos_c = instrument_id.find('C', 4);
    auto pos = pos_p;
    if (pos_p != std::string::npos || pos_c != std::string::npos) {
      auto pos1 = std::find_if(instrument_id.begin(), instrument_id.end(), ::isdigit);
      std::string product_id = std::string(instrument_id.begin(), pos1);
      shm_instrument.product_class = md::ProductClass::kOption;
      shm::AssignShmString(&shm_instrument.product_id, product_id + "_O");
      if (pos_p != std::string::npos) {
        shm_instrument.option_class = md::OptionClass::kPut;
      } else {
        shm_instrument.option_class = md::OptionClass::kCall;
        pos = pos_c;
      }
      if (instrument_id[pos + 1] == '-') {
        shm_instrument.strike_price = atoi(instrument_id.substr(pos + 2).c_str());
        std::string underlying_symbol = exchange_id + "." + instrument_id.substr(0, pos - 1);
        shm::AssignShmString(&shm_instrument.underlying_symbol, underlying_symbol);
      } else {
        shm_instrument.strike_price = atoi(instrument_id.substr(pos + 1).c_str());
        std::string underlying_symbol = exchange_id + "." + instrument_id.substr(0, pos);
        shm::AssignShmString(&shm_instrument.underlying_symbol, underlying_symbol);
      }
    } else {
      shm_instrument.product_class = md::ProductClass::kFuture;
      auto pos = std::find_if(instrument_id.begin(), instrument_id.end(), ::isdigit);
      shm::AssignShmString(&shm_instrument.product_id, std::string(instrument_id.begin(), pos));
    }
  }
  m_fake_instruments.insert(std::make_pair(symbol, shm_instrument));
  return &(m_fake_instruments.at(symbol));
}

