bool LocalMdServiceImpl::IsLeapYear(int year) {
  if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0))
    return true;
  return false;
}

bool LocalMdServiceImpl::IsDateValid(int year, int month, int day) {
  if (year < 1 || month < 1 || month > 12 || day < 1 || day > 31)
    return false;
  // 30天的月份
  if (month == 4 || month == 6 || month == 9 || month == 11) {
    if (day > 0 && day < 31)
      return true;
    return false;
  }
  // 2月份
  if (month == 2) {
    if (IsLeapYear(year)) {
      if (day > 0 && day < 30)
        return true;
      return false;
    }
    if (day > 0 && day < 29)
      return true;
    return false;
  }
  // 31天的月份
  return true;
}

bool LocalMdServiceImpl::IsPatternPointValid(const PatternPoint& point, double price_adjust) {
  if (point.last_price <= 0.0 || point.ask_price <= 0.0 || point.bid_price <= 0.0 || point.repeat_cnt < 1)
    return false;
  if (price_adjust >= 0.0)
    return true;
  if (point.last_price <= std::fabs(price_adjust) || point.ask_price <= std::fabs(price_adjust)
    || point.bid_price <= std::fabs(price_adjust))
    return false;
  return true;
}

void LocalMdServiceImpl::SetBaseDateTime(const std::string& datetime /*= "2020-11-10 09:00:00"*/) {
  int year, month, day, hour, min, sec;
  if (sscanf(datetime.c_str(), "%04d-%02d-%02d %02d:%02d:%02d", &year, &month, &day, &hour, &min, &sec) != 6)
    return;
  if (year < 1900 || month < 1 || month > 12 || hour < 0 || hour > 23 || min < 0 || min > 59 || sec < 0 || sec > 59
    || day < 0 || day > 31)
    return;
  if (!IsDateValid(year, month, day))
    return;
  m_pkg.base_datetime = datetime;
}

void LocalMdServiceImpl::SetStepLength(int32_t step_milliseconds) {
  if (step_milliseconds < 0)
    return;
  m_pkg.step_length = step_milliseconds;
}

void LocalMdServiceImpl::SetPattern(
  const std::string& symbol, const std::vector<PatternPoint>& point_vector, double price_adjust) {
  m_local_md_mode = LocalMdMode::kPattern;
  for (auto&& point : point_vector) {
    if (!IsPatternPointValid(point, price_adjust))
      return;
  }
  m_pkg.pattern.clear();
  SymbolPattern sp = {};
  sp.price_adjust = price_adjust;
  sp.points = point_vector;
  m_pkg.pattern.insert(std::make_pair(symbol, sp));
  UpdatePattern();
}

void LocalMdServiceImpl::DateTimeUpdated() {
  char res[26];
  auto local_datetime = EpochNanoToLocalDateTime(m_exchange_time * 1000000, 8);
  auto time_s = local_datetime.date_time;
  if (snprintf(res, sizeof(res), "%04d-%02d-%02d %02d:%02d:%02d", (time_s.tm_year + 1900), (time_s.tm_mon + 1),
        time_s.tm_mday, time_s.tm_hour, time_s.tm_min, time_s.tm_sec)
    > 0) {
    m_pkg.base_datetime = res;
  }
}

void LocalMdServiceImpl::ExchangeTimeUpdated() {
  m_exchange_time += m_pkg.step_length;
  auto local_datetime = EpochNanoToLocalDateTime(m_exchange_time * 1000000, 8);
  auto& time_s = local_datetime.date_time;
  if (time_s.tm_hour < 9 || time_s.tm_hour > 14) {
    time_s.tm_mday = (time_s.tm_hour < 9) ? time_s.tm_mday : time_s.tm_mday + 1;
    time_s.tm_hour = 9;
    time_s.tm_min = 0;
    time_s.tm_sec = 0;
    m_exchange_time = LocalDateTimeToEpochNano(local_datetime) / 1000000;
  } else if ((time_s.tm_hour == 11 && time_s.tm_min >= 30) || time_s.tm_hour == 12
    || (time_s.tm_hour == 13 && time_s.tm_min < 30)) {
    time_s.tm_hour = 13;
    time_s.tm_min = 30;
    time_s.tm_sec = 0;
    m_exchange_time = LocalDateTimeToEpochNano(local_datetime) / 1000000;
  }
  DateTimeUpdated();
}

void LocalMdServiceImpl::UpdatePattern() {
  for (auto& point_pair : m_pkg.pattern) {
    auto symbol = point_pair.first;
    auto point_v = point_pair.second.points;
    std::queue<PatternPoint> pattern_point;
    for (auto& point : point_v) {
      auto cnt = point.repeat_cnt;
      while (cnt--) {
        pattern_point.push(point);
      }
    }
    auto iter = m_pattern_point.find(symbol);
    auto iter_a = m_pattern_adjust.find(symbol);
    if (iter != m_pattern_point.end()) {
      iter->second = pattern_point;
    } else {
      m_pattern_point.insert(std::make_pair(symbol, pattern_point));
    }
    if (iter_a != m_pattern_adjust.end()) {
      iter_a->second = point_pair.second.price_adjust;
    } else {
      m_pattern_adjust.insert(std::make_pair(symbol, point_pair.second.price_adjust));
    }
  }
}

void LocalMdServiceImpl::ProcessPattern(int& msg_cnt) {
  if (m_pattern_point.empty()) {
    return;
  }
  // 更新所有伪合约行情
  for (auto& it : m_pattern_point) {
    auto symbol = it.first;
    auto& pattern_point = it.second;
    auto& point = pattern_point.front();
    auto new_point = PatternPoint((std::max)(point.last_price + m_pattern_adjust[symbol], 0.0),
      (std::max)(point.ask_price + m_pattern_adjust[symbol], 0.0),
      (std::max)(point.bid_price + m_pattern_adjust[symbol], 0.0))
                       .AskVolume(point.ask_volume)
                       .BidVolume(point.bid_volume);
    pattern_point.push(new_point);
    pattern_point.pop();
    // 更新行情
    m_node_db->ReplaceRecord<Instrument>(symbol, [&](std::shared_ptr<Instrument> ins) {
      ins->symbol = symbol;
      ins->last_price = point.last_price;
      ins->ask_price[0] = point.ask_price;
      ins->ask_volume[0] = point.ask_volume;
      ins->bid_price[0] = point.bid_price;
      ins->bid_volume[0] = point.bid_volume;
      ins->highest = (ins->highest < point.last_price) ? point.last_price : ins->highest;
      ins->lowest = (ins->lowest > point.last_price) ? point.last_price : ins->lowest;
      // 更新时间
      ins->exchange_time = m_exchange_time * 1000000;
      ins->_trade_status = md::TradeStatus::kContinous;
      ins->expired = false;
    });
  }
  ExchangeTimeUpdated();
  msg_cnt++;
  return;
}

int LocalMdServiceImpl::RunOnce() {
  int msg_count = 0;
  // 处理合约表生成器指令
  if (m_ins_generator) {
    auto ins_generator = std::make_shared<LocalInsGenerator>();
    ins_generator->Generate(m_node_db, m_ins_generator->start_year);
    SetCommandFinished(m_ins_generator);
    m_ins_generator = nullptr;
    msg_count++;
  }
  /*待填充其他模式*/
  if (m_pkg.running == false) {
    return msg_count;
  }
  std::string date = m_pkg.base_datetime.substr(0, m_pkg.base_datetime.find(" "));
  std::string time = m_pkg.base_datetime.substr(m_pkg.base_datetime.find(" ") + 1);
  m_exchange_time = StringToEpochNano(date.c_str(), time.c_str(), 8) / 1000000;
  switch (m_local_md_mode) {
    case md::LocalMdMode::kPattern: ProcessPattern(msg_count); break;
    case md::LocalMdMode::kRandom: break;
    case md::LocalMdMode::kReal: break;
    default: break;
  }
  msg_count += m_comb_quote_calc->RunOnce();
  // 固定更新交易所交易时间, 不加入 msg_count 计数统计
  for (auto& [key, exchange_node] : m_node_db->GetNodeMap<md::Exchange>()) {
    m_node_db->ReplaceRecord<md::Exchange>(key, [](std::shared_ptr<md::Exchange> exchange) {
      exchange->exchange_date_time = exchange->GetDateTime();
    });
  }
  auto iter = m_command_cache.begin();
  while (iter != m_command_cache.end()) {
    SetCommandFinished(*iter);
    iter = m_command_cache.erase(iter);
  }
  return msg_count;
}

/*
 * 伪市场行情服务订阅总是成功
 */
void LocalMdServiceImpl::ReqSubscribeObjectInfo(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeObjectInfo>(m_command_manager->Update(c));
  SetCommandFinished(command);
}

void LocalMdServiceImpl::ReqSubscribeOptionsByUnderlyingSymbol(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeOptionsByUnderlyingSymbol>(m_command_manager->Update(c));
  SetCommandFinished(command);
}

void LocalMdServiceImpl::ReqMockQuote(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<MockQuote>(m_command_manager->Update(c));
  SetPattern(command->symbol,
    {PatternPoint(command->last_price, command->ask_price, command->bid_price)
        .AskVolume(command->ask_volume)
        .BidVolume(command->bid_volume)},
    command->price_adjust);
  m_command_cache.emplace_back(command);
}

void LocalMdServiceImpl::ReqSubscribeCombQuote(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeComboQuote>(m_command_manager->Update(c));
  m_comb_quote_calc->SubscribeCombQuote(command);
}

void LocalMdServiceImpl::ExecuteGenerateInsTable(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<GenerateInsTable>(m_command_manager->Update(c));
  if (m_ins_generator) {
    SetCommandFinished(command, -1, u8"已有本地合约表正在生成");
    return;
  }
  m_ins_generator = command;
}

void LocalMdServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case SubscribeObjectInfo::AID: {
      ReqSubscribeObjectInfo(command);
      break;
    }
    case SubscribeOptionsByUnderlyingSymbol::AID: {
      ReqSubscribeOptionsByUnderlyingSymbol(command);
      break;
    }
    case GenerateInsTable::AID: {
      ExecuteGenerateInsTable(command);
      break;
    }
    case SubscribeComboInstrument::AID:
    case SubscribeComboQuote::AID: {
      ReqSubscribeCombQuote(command);
      break;
    }
    case MockQuote::AID: {
      ReqMockQuote(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"找不到此指令实现");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

