LocalCombQuoteCalculator::LocalCombQuoteCalculator(std::shared_ptr<TqApiNodeDb> db) : m_db(db) {
  m_update_instruments.clear();
  m_ins_view = m_db->CreateView<md::Instrument>([=](std::shared_ptr<const md::Instrument> ins) {
    return m_instruments.find(ins->symbol) != m_instruments.end();
  });
  m_ins_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<md::InstrumentNode> ins) {
    m_update_instruments.insert(ins->Latest()->symbol);
  });
}

// 订阅的接口
void LocalCombQuoteCalculator::SubscribeCombQuote(std::shared_ptr<md::SubscribeComboQuote> command) {
  for (const auto& [comb_id, weights] : command->combo_infos) {
    m_weights[comb_id] = weights;
    if (weights.empty())
      m_weights.erase(comb_id);
  }
  for (const auto& [comb_id, combo_params] : command->combo_params) {
    m_vweights[comb_id] = combo_params;
    if (combo_params.empty())
      m_vweights.erase(comb_id);
  }
  m_instruments.clear();
  for (const auto& [_, weights] : m_weights) {
    for (const auto& [symbol, _] : weights) {
      m_instruments.insert(symbol);
    }
  }
  m_subscribe_commands.insert(command);
}

int LocalCombQuoteCalculator::RunOnce() {
  int cnt = 0;
  // 处理订阅请求
  for (const auto& command : m_subscribe_commands) {
    SetCommandFinished(command);
    for (const auto& weight : command->combo_infos) {
      if (weight.second.empty())
        continue;
      UpdateCombQuote(weight);
      ++cnt;
    }
  }
  m_subscribe_commands.clear();
  // 检查定时器
  if (m_update_timer.IsExpired()) {
    cnt += UpdateAllCombQuote();
  }
  return cnt;
}

// 检查weight里的合约是否有变化
bool LocalCombQuoteCalculator::IsWeightNeedUpdate(const std::map<std::string, double>& weight) {
  for (const auto& [symbol, _] : weight) {
    if (m_update_instruments.count(symbol))
      return true;
  }
  return false;
}

std::map<std::shared_ptr<md::InstrumentNode>, double> LocalCombQuoteCalculator::SetWeight(
  const std::map<std::string, double>& weight) {
  std::map<std::shared_ptr<md::InstrumentNode>, double> ret;
  for (const auto& [symbol, w] : weight) {
    auto ins_node = m_db->GetNode<md::Instrument>(symbol);
    ret.insert(std::make_pair(ins_node, w));
  }
  return ret;
}

static int32_t GetWeightDecimals(double weight) {
  int32_t decs = 2;
  while (decs > 0 && (static_cast<int32_t>(std::round(weight * std::pow(10, decs))) % 10 == 0)) {
    --decs;
  }
  return decs;
}

// 更新组合合约
void LocalCombQuoteCalculator::UpdateCombQuote(const std::pair<std::string, std::map<std::string, double>>& weight) {
  m_db->ReplaceRecord<md::Instrument>(weight.first, [this, &weight](std::shared_ptr<md::Instrument> ins) {
    auto it = weight.second.begin();
    while (it->first == "1") {
      ++it;
    }
    auto node = m_db->GetNode<md::Instrument>(it->first);
    FCASSERT(node);
    ins->instrument_base->product_base->exchange_id = node->Latest()->ExchangeID();
    ins->instrument_base->product_base->product_class = ProductClass::kCusCombine;
    ins->symbol = weight.first;
    ins->last_price = 0.0;
    ins->ask_price[0] = 0.0;
    ins->bid_price[0] = 0.0;
    ins->ask_volume[0] = INT32_MAX;
    ins->bid_volume[0] = INT32_MAX;
    ins->upper_limit = 0.0;
    ins->lower_limit = 0.0;
    ins->pre_settlement = 0.0;
    ins->pre_close = 0.0;
    ins->exchange_time = 0;
    ins->close = 0.0;
    ins->instrument_base->expire_date_time = INT64_MAX;
    ins->instrument_base->product_base->price_decs = 0;
    ins->instrument_base->price_tick = 10000000.0;
    if (ins->instrument_base->weight.empty()) {
      ins->instrument_base->weight = SetWeight(weight.second);
    }

    const auto& vweight = m_vweights[weight.first];

    for (const auto& [symbol, w] : weight.second) {
      auto v = 0;
      if (vweight.find(symbol) != vweight.end()) {
        v = vweight.at(symbol).ratio;
      }

      if (w == 0 || v == 0)
        continue;
      auto ins_node = m_db->GetNode<md::Instrument>(symbol);
      if ("1" == symbol) {
        ins->last_price += w;
        ins->ask_price[0] += w;
        ins->bid_price[0] += w;
        ins->upper_limit += w;
        ins->lower_limit += w;
        ins->pre_settlement += w;
        ins->pre_close += w;
        ins->close += w;
        continue;
      }
      if (!ins_node) {
        ins->last_price = NAN;
        ins->ask_price[0] = NAN;
        ins->bid_price[0] = NAN;
        ins->ask_volume[0] = 0;
        ins->bid_volume[0] = 0;
        ins->upper_limit = NAN;
        ins->lower_limit = NAN;
        ins->pre_settlement = NAN;
        ins->pre_close = NAN;
        ins->close = NAN;
        ins->instrument_base->expire_date_time = 0;
        ins->instrument_base->product_base->price_decs = 0;
        ins->instrument_base->price_tick = NAN;
        break;
      }

      ins->last_price += ins_node->Latest()->last_price * w;
      ins->ask_price[0] += ((w > 0) ? ins_node->Latest()->ask_price[0] : ins_node->Latest()->bid_price[0]) * w;
      ins->bid_price[0] += ((w > 0) ? ins_node->Latest()->bid_price[0] : ins_node->Latest()->ask_price[0]) * w;
      ins->ask_volume[0] = (std::min)(ins->ask_volume[0],
        (v > 0) ? static_cast<int32_t>(ins_node->Latest()->ask_volume[0] / v)
                : static_cast<int32_t>(ins_node->Latest()->bid_volume[0] / -v));
      ins->bid_volume[0] = (std::min)(ins->bid_volume[0],
        (v > 0) ? static_cast<int32_t>(ins_node->Latest()->bid_volume[0] / v)
                : static_cast<int32_t>(ins_node->Latest()->ask_volume[0] / -v));
      ins->upper_limit += (w > 0) ? ins_node->Latest()->upper_limit * w : ins_node->Latest()->lower_limit * w;
      ins->lower_limit += (w > 0) ? ins_node->Latest()->lower_limit * w : ins_node->Latest()->upper_limit * w;
      ins->pre_settlement += ins_node->Latest()->pre_settlement * w;
      ins->pre_close += ins_node->Latest()->pre_close * w;
      ins->exchange_time = (std::max)(ins->exchange_time, ins_node->Latest()->exchange_time);
      ins->close += ins_node->Latest()->close * w;
      ins->instrument_base->expire_date_time =
        (std::min)(ins->instrument_base->expire_date_time, ins_node->Latest()->instrument_base->expire_date_time);
      ins->instrument_base->product_base->price_decs = (std::max)(ins->instrument_base->product_base->price_decs,
        ins_node->Latest()->instrument_base->product_base->price_decs + GetWeightDecimals(w));
      ins->instrument_base->price_tick =
        (std::min)(ins->instrument_base->price_tick, ins_node->Latest()->instrument_base->price_tick);
    }
    if (ins->ask_volume[0] <= 0) {
      ins->ask_volume[0] = 0;
      ins->ask_price[0] = NAN;
    }
    if (ins->bid_volume[0] <= 0) {
      ins->bid_volume[0] = 0;
      ins->bid_price[0] = NAN;
    }
  });
}

int LocalCombQuoteCalculator::UpdateAllCombQuote() {
  int cnt = 0;
  // 更新前筛选, 若无需更新, 跳过
  if (m_update_instruments.empty())
    return cnt;
  for (const auto& weight : m_weights) {
    if (IsWeightNeedUpdate(weight.second)) {
      UpdateCombQuote(weight);
      ++cnt;
    }
  }
  m_update_instruments.clear();
  m_update_timer.Reset(std::chrono::milliseconds(500));
  return cnt;
}

