TradeStatus Instrument::TradeStatus() const {
  if (ExchangeID() == "KQ") {
    std::shared_ptr<md::InstrumentNode> underlying_node = instrument_base->underlying_pointer;
    if (underlying_node) {
      return underlying_node->Latest()->_trade_status;
    }
  } else if (ProductClass() == md::ProductClass::kCombine) {
    std::shared_ptr<md::InstrumentNode> leg1_node = instrument_base->leg1_pointer;
    if (leg1_node) {
      auto status = leg1_node->Latest()->_trade_status;
      if (status >= md::TradeStatus::kBeforeTrading && status <= md::TradeStatus::kAuctionMatch)
        return md::TradeStatus::kBeforeTrading;
      return status;
    }
  } else if (ProductClass() == md::ProductClass::kCusCombine) {
    auto res = TradeStatus::kContinous;
    for (const auto& [node, _] : instrument_base->weight) {
      const auto& status = node->Latest()->TradeStatus();
      if (status != TradeStatus::kAuctionOrdering && status != TradeStatus::kContinous) {
        return TradeStatus::kBeforeTrading;
      }
      if (status == TradeStatus::kAuctionOrdering) {
        res = TradeStatus::kAuctionOrdering;
      }
    }
    return res;
  }
  return _trade_status;
}

std::string Instrument::ExchangeTimeStr() const {
  return std::string(GetStringFromEpochNano(exchange_time)).substr(0, 19);
}

bool Instrument::IsTradingAllowed(bool only_continuious) const {
  auto status = TradeStatus();
  bool ret = status == TradeStatus::kContinous;
  // 如果只判断连续交易, 则直接返回
  if (only_continuious) {
    return ret;
  }
  // 除了官方组合合约, 其他合约在集合竞价阶段也可以交易
  // 郑商所第二次集合竞价不可交易
  if (instrument_base->product_base->product_class != md::ProductClass::kCombine) {
    ret |= (status == TradeStatus::kAuctionOrdering && (ExchangeID() == "CZCE" ? volume <= 0 : true));
  }
  return ret;
}

bool Instrument::CheckQuote(std::string_view trading_day) const {
  // 若行情日期与交易日不同, 且更新时间在9.00~16.00之间, 则行情无效
  // 行情一旦有效,今日应当均有效,目前 fclib 不支持切换交易日
  if (_market_data_valid)
    return true;
  auto local_time = EpochNanoToLocalDateTime(exchange_time);
  local_time.date_time.tm_year += 1900;
  local_time.date_time.tm_mon += 1;
  std::string quote_date = std::to_string(
    local_time.date_time.tm_year * 10000 + local_time.date_time.tm_mon * 100 + local_time.date_time.tm_mday);
  if (trading_day != quote_date && local_time.date_time.tm_hour < 16 && local_time.date_time.tm_hour > 8)
    return false;
  _market_data_valid = true;
  return true;
}

bool Instrument::IsCffexIndex() const {
  if (instrument_id.empty()) {
    return false;
  }
  if (ExchangeID() == "CFFEX")
    return instrument_id.data()[0] == 'I';
  return false;
}

bool Instrument::NightTrading() const {
  return !instrument_base->product_base->trading_time.night.empty();
}

bool Instrument::HasCloseToday() const {
  return instrument_base->product_base->product_class != ProductClass::kCusCombine
    && (ExchangeID() == "SHFE" || ExchangeID() == "INE");
}

double Instrument::GetAskPrice() const {
  if (ask_volume[0] > 0)  // 有卖
    return ask_price[0];
  if (bid_volume[0] == 0)  // 没有买也没有卖
    return NAN;
  return (std::min)(upper_limit, bid_price[0] + instrument_base->price_tick);  // 有买没卖
}

double Instrument::GetBidPrice() const {
  if (bid_volume[0] > 0)  // 有买
    return bid_price[0];
  if (ask_volume[0] == 0)  // 没有买也没有卖
    return NAN;
  return (std::max)(lower_limit, ask_price[0] - instrument_base->price_tick);  // 有卖没买
}

