md::TradeStatus Instrument::GetTradeStatus(std::shared_ptr<md::InstrumentNode> ins_node, bool prev) {
  if (!ins_node || !ins_node->Latest())
    return md::TradeStatus::kUnknown;
  if (!prev)
    return ins_node->Latest()->TradeStatus();

  if (ins_node->Latest()->ExchangeID() == "KQ") {
    std::shared_ptr<md::InstrumentNode> underlying_node = ins_node->Latest()->instrument_base->underlying_pointer;
    if (underlying_node && underlying_node->Historical())
      return underlying_node->Historical()->_trade_status;
    return md::TradeStatus::kUnknown;
  }
  if (ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
    std::shared_ptr<md::InstrumentNode> leg1_node = ins_node->Latest()->instrument_base->leg1_pointer;
    if (leg1_node && leg1_node->Historical()) {
      auto status = leg1_node->Historical()->_trade_status;
      if (status >= md::TradeStatus::kBeforeTrading && status <= md::TradeStatus::kAuctionMatch)
        return md::TradeStatus::kBeforeTrading;
      return status;
    }
    return md::TradeStatus::kUnknown;
  }
  if (ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine) {
    auto res = TradeStatus::kContinous;
    for (const auto& [node, _] : ins_node->Latest()->instrument_base->weight) {
      const auto& status = GetTradeStatus(node, true);
      if (status != TradeStatus::kAuctionOrdering && status != TradeStatus::kContinous)
        return TradeStatus::kBeforeTrading;
      if (status == TradeStatus::kAuctionOrdering)
        res = TradeStatus::kAuctionOrdering;
    }
    return res;
  }
  return ins_node->Historical() ? ins_node->Historical()->_trade_status : md::TradeStatus::kUnknown;
}

