void MdSerializer::DefineStruct(md::Instrument& data) {
  AddItem(data.amount, ("amount"));
  AddItem(data.ask_price[0], ("ask_price1"));
  AddItem(data.ask_volume[0], ("ask_volume1"));
  AddItem(data.bid_price[0], ("bid_price1"));
  AddItem(data.bid_volume[0], ("bid_volume1"));
  if (data.HasCloseToday()) {
    if (data.ask_volume.size() == 1) {
      data.ask_price.resize(5, NAN);
      data.ask_volume.resize(5, 0);
      data.bid_price.resize(5, NAN);
      data.bid_volume.resize(5, 0);
    }
    AddItem(data.ask_price[1], ("ask_price2"));
    AddItem(data.ask_volume[1], ("ask_volume2"));
    AddItem(data.bid_price[1], ("bid_price2"));
    AddItem(data.bid_volume[1], ("bid_volume2"));
    AddItem(data.ask_price[2], ("ask_price3"));
    AddItem(data.ask_volume[2], ("ask_volume3"));
    AddItem(data.bid_price[2], ("bid_price3"));
    AddItem(data.bid_volume[2], ("bid_volume3"));
    AddItem(data.ask_price[3], ("ask_price4"));
    AddItem(data.ask_volume[3], ("ask_volume4"));
    AddItem(data.bid_price[3], ("bid_price4"));
    AddItem(data.bid_volume[3], ("bid_volume4"));
    AddItem(data.ask_price[4], ("ask_price5"));
    AddItem(data.ask_volume[4], ("ask_volume5"));
    AddItem(data.bid_price[4], ("bid_price5"));
    AddItem(data.bid_volume[4], ("bid_volume5"));
  }
  AddItem(data.average, ("average"));
  AddItem(data.close, ("close"));
  AddItem(data.pre_close, ("pre_close"));
  std::string exchange_time_str;
  AddItem(exchange_time_str, ("datetime"));
  if (!exchange_time_str.empty()) {
    int year, month, day, hour, minute, second, millisecond;
    if (sscanf(exchange_time_str.c_str(), "%04d-%02d-%02d %02d:%02d:%02d.%06d", &year, &month, &day, &hour, &minute,
          &second, &millisecond)
      > 0) {
      LocalDateTime local_time = {};
      local_time.time_zone = 8;
      local_time.date_time.tm_year = year - 1900;
      local_time.date_time.tm_mon = month - 1;
      local_time.date_time.tm_mday = day;
      local_time.date_time.tm_hour = hour;
      local_time.date_time.tm_min = minute;
      local_time.date_time.tm_sec = second;
      local_time.nano_seconds = millisecond * 1000LL;
      data.exchange_time = LocalDateTimeToEpochNano(local_time);
    }
  }
  AddItem(data.highest, ("highest"));
  AddItem(data.last_price, ("last_price"));
  AddItem(data.lower_limit, ("lower_limit"));
  AddItem(data.lowest, ("lowest"));
  AddItem(data.open, ("open"));
  AddItem(data.open_interest, ("open_interest"));
  AddItem(data.pre_open_interest, ("pre_open_interest"));
  AddItem(data.settlement, ("settlement"));
  AddItem(data.pre_settlement, ("pre_settlement"));
  AddItem(data.upper_limit, ("upper_limit"));
  AddItem(data.volume, ("volume"));
}

std::shared_ptr<MdService> MdService::Create(boost::asio::io_context* ioc, std::shared_ptr<MdRootNode> data_root,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<KlinePartition> klines, std::shared_ptr<TickPartition> ticks,
  structlog::Logger& parent_logger, const TqApiOptions& options) {
  auto p = std::make_shared<MdServiceImpl>(ioc, data_root, node_db, klines, ticks, parent_logger, options);
  p->Start();
  return p;
}

MdServiceImpl::MdServiceImpl(boost::asio::io_context* ioc, std::shared_ptr<md::MdRootNode> data_root,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<KlinePartition> klines, std::shared_ptr<TickPartition> ticks,
  structlog::Logger& parent_logger, const TqApiOptions& options)
  : m_data_root(data_root)
  , m_node_db(node_db)
  , m_klines(klines)
  , m_ticks(ticks)
  , m_logger(parent_logger.With("md_service", reinterpret_cast<int64_t>(this)).Clone())
  , m_options(options)
  , m_access_token(options.access_token)
  , m_md_urls(options.md_urls)
  , m_strand(*ioc)
  , m_agent(options.agent) {
  m_md_object_info = std::make_shared<MdServiceObjectInfo>(
    m_context_id, IsBackTest(), options.test_mode, m_node_db, ioc, m_command_manager, m_logger);
  m_md_chart = std::make_shared<MdServiceChart>(
    m_context_id, m_data_root, m_node_db, m_klines, m_ticks, m_command_manager, m_logger);
}

void MdServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_context_id <= 0) {
    SetCommandFinished(command, -1, u8"行情服务发生不可恢复错误");
    return;
  }
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case SubscribeObjectInfo::AID: {
      m_md_object_info->ReqSubscribeObjectInfo(command);
      break;
    }
    case SubscribeOptionsByUnderlyingSymbol::AID: {
      m_md_object_info->ReqSubscribeOptionsByUnderlyingSymbol(command);
      break;
    }
    case SubscribeChartLatest::AID: {
      m_md_chart->ReqSubscribeChartLatest(command);
      break;
    }
    case SubscribeChartLeft::AID: {
      m_md_chart->ReqSubscribeChartLeft(command);
      break;
    }
    case SubscribeChartFocus::AID: {
      m_md_chart->ReqSubscribeChartFocus(command);
      break;
    }
    case SubscribeChartDay::AID: {
      m_md_chart->ReqSubscribeChartDay(command);
      break;
    }
    case GenerateInsTable::AID: {
      m_md_object_info->ReqGenerateInsTable(command);
      break;
    }
    case SubscribeComboInstrument::AID: {
      m_md_object_info->ReqSubscribeComboInstrument(command);
      break;
    }
    case SubscribeComboQuote::AID: {
      ReqSubscribeCombQuote(command);
      break;
    }
    case SubscribeComboChart::AID: {
      m_md_chart->ReqSubscribeComboChart(command);
      break;
    }
    case SubscribeComboChartLeft::AID: {
      m_md_chart->ReqSubscribeComboChartLeft(command);
      break;
    }
    case SubscribeComboChartFocus::AID: {
      m_md_chart->ReqSubscribeComboChartFocus(command);
      break;
    }
    case MockQuote::AID: {
      ReqMockQuote(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"找不到此指令实现");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

int MdServiceImpl::RunOnce() {
  int msg_count = 0;
  if (m_context_id <= 0)
    return msg_count;
  // 处理 RTQ 日志和状态信息
  RtqService::ProcessRtqLogger(m_logger);
  if (RtqService::ProcessRtqStatus(m_context_id, m_node_db))
    msg_count++;
  // 处理接收到的数据包
  std::string msg;
  while (!m_rtq_queue.empty()) {
    msg = m_rtq_queue.front();
    m_rtq_queue.pop();
    ProcessMsg(msg);
    msg_count++;
  }
  msg_count += m_md_object_info->RunOnce();

  // 固定更新交易所交易时间, 不加入 msg_count 计数统计
  for (auto& [key, exchange_node] : m_node_db->GetNodeMap<md::Exchange>()) {
    m_node_db->ReplaceRecord<md::Exchange>(key, [](std::shared_ptr<md::Exchange> exchange) {
      exchange->exchange_date_time = exchange->GetDateTime();
    });
  }

  return msg_count;
}

void MdServiceImpl::Start() {
  m_node_db->ReplaceRecord<Session>("md_session", [](std::shared_ptr<Session> md_session) {
    md_session->session_status = md::SessionStatus::kBeforeConnect;
    md_session->error_msg = "";
  });
  m_node_db->ReplaceRecord<md::Exchange>("SHFE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "SHFE";
  });
  m_node_db->ReplaceRecord<md::Exchange>("CZCE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "CZCE";
  });
  m_node_db->ReplaceRecord<md::Exchange>("DCE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "DCE";
  });
  m_node_db->ReplaceRecord<md::Exchange>("CFFEX", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "CFFEX";
  });
  m_node_db->ReplaceRecord<md::Exchange>("INE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "INE";
  });
  m_node_db->ReplaceRecord<md::Exchange>("GFEX", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "GFEX";
  });
  m_node_db->ReplaceRecord<md::Exchange>("SSE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "SSE";
  });
  m_node_db->ReplaceRecord<md::Exchange>("SZSE", [](std::shared_ptr<md::Exchange> exchange) {
    exchange->exchange_id = "SZSE";
  });
  m_context_id = RtqService::Init(m_md_urls, m_agent, m_access_token);

  m_thread_control.store(m_context_id > 0);
  m_thread = std::thread([&] {
    while (m_thread_control.load()) {
      // wait 100ms
      auto msg = RTQFetchUpdate(m_context_id, static_cast<int64_t>(100000000));
      if (msg) {
        std::string recv_msg = msg;
        m_strand.post([=]() {
          m_rtq_queue.push(recv_msg);
        });
      }
    }
  });
}

void MdServiceImpl::ReqMockQuote(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<MockQuote>(m_command_manager->Update(c));
  SetCommandFinished(command);
}

void MdServiceImpl::ReqSubscribeCombQuote(std::shared_ptr<UserCommand> c) {
  auto command = std::static_pointer_cast<SubscribeComboQuote>(m_command_manager->Update(c));
  /** 当前不区分订阅发起方. 因此如果 combo_id 对应的 weights map 为空, 将直接退订 combo_id 的行情,
   * 而不管其它发起方是否需要 combo_id 的行情.  */
  for (const auto& [combo_id, weights] : command->combo_infos) {
    RtqSerializer rtq_ss;
    std::string weights_json;
    std::string vweights_json;
    rtq_ss.FromVar(weights);
    rtq_ss.ToString(&weights_json);

    auto vweights_iter = command->combo_params.find(combo_id);
    if (vweights_iter != command->combo_params.end()) {
      std::map<std::string, int32_t> vweights_map;
      for (const auto& [symbol, params] : vweights_iter->second) {
        vweights_map[symbol] = params.ratio;
      }
      RtqSerializer ss;
      ss.FromVar(vweights_map);
      ss.ToString(&vweights_json);
    }

    if (RTQSubscribeCombo(
          m_context_id, combo_id.c_str(), weights_json.c_str(), vweights_json.empty() ? nullptr : vweights_json.c_str())
      < 0) {
      SetCommandFinished(command, -1, u8"订阅自定义组合行情请求未能正常发出");
      return;
    }
  }
  SetCommandFinished(command);
}

void MdServiceImpl::ProcessMsg(const std::string& json_str) {
  rapidjson::Document json_doc;
  rapidjson::StringStream buffer(json_str.c_str());
  typedef rapidjson::EncodedInputStream<rapidjson::UTF8<>, rapidjson::StringStream> InputStream;
  InputStream os(buffer);
  json_doc.ParseStream<rapidjson::kParseNanAndInfFlag, rapidjson::UTF8<>>(os);
  if (json_doc.HasParseError()) {
    return;
  }

  /*
  合约服务来的数据包结构，参见 https://shinnytech-eftrade.readthedocs-hosted.com/en/instrument_serve/ref/graphql.html
  行情服务来的数据包结构，参见 https://shinnytech.atlassian.net/wiki/spaces/TWG/pages/176619972
  */
  if (!json_doc.IsArray())
    return;

  for (auto& data : json_doc.GetArray()) {
    if (data.HasMember("symbols")) {
      rapidjson::Value& symbols = data["symbols"];
      m_md_object_info->ProcessObjectInfoMsg(json_doc, symbols);
    }
    if (data.HasMember("quotes")) {
      rapidjson::Value& quotes = data["quotes"];
      MdSerializer ss(&json_doc);
      ProcessQuotesMsg(ss, quotes);
    }
    if (data.HasMember("combo_quotes")) {
      rapidjson::Value& comb_quotes = data["combo_quotes"];
      MdSerializer ss(&json_doc);
      ProcessCombQuotesMsg(ss, comb_quotes);
    }
    if (data.HasMember("ex_combo_quotes")) {
      rapidjson::Value& ex_comb_quotes = data["ex_combo_quotes"];
      MdSerializer ss(&json_doc);
      ProcessExCombQuotesMsg(ss, ex_comb_quotes);
    }
    if (data.HasMember("klines")) {
      rapidjson::Value& klines = data["klines"];
      m_md_chart->ProcessKlinesMsg(json_doc, klines);
    }
    if (data.HasMember("ticks")) {
      rapidjson::Value& ticks = data["ticks"];
      m_md_chart->ProcessTicksMsg(json_doc, ticks);
    }
    if (data.HasMember("charts")) {
      rapidjson::Value& charts = data["charts"];
      m_md_chart->ProcessChartsMsg(charts);
    }
  }
}

void MdServiceImpl::ProcessQuotesMsg(MdSerializer& ss, rapidjson::Value& quotes) {
  std::map<std::string, std::shared_ptr<Exchange>> time_changed_exchanges;
  for (auto& m : quotes.GetObject()) {
    std::string symbol = m.name.GetString();
    auto quote_node = m_node_db->ReplaceRecord<Instrument>(symbol, [&](std::shared_ptr<md::Instrument> quote) {
      ss.ToVar(*quote, &m.value);
      quote->symbol = symbol;
    });
    if (m_options.enable_position_details) {
      m_logger.With("symbol", symbol)
        .With("last_price", quote_node->Latest()->last_price)
        .With("ask_price_1", quote_node->Latest()->ask_price[0])
        .With("bid_price_1", quote_node->Latest()->bid_price[0])
        .With("ask_vol_1", quote_node->Latest()->ask_volume[0])
        .With("bid_vol_1", quote_node->Latest()->bid_volume[0])
        .With("amount", quote_node->Latest()->amount)
        .With("exchange_time", quote_node->Latest()->exchange_time)
        .Info("quote_latest");
    }
    auto quote_info = quote_node->Latest();
    if (quote_info->ExchangeID().empty())
      continue;
    auto exchange_info = m_node_db->CreateRecord<md::Exchange>(quote_info->ExchangeID());
    if (exchange_info->exchange_id.empty())
      exchange_info->exchange_id = quote_info->ExchangeID();
    auto prev_quote = quote_node->Snap();
    if (prev_quote) {
      int64_t delta = quote_info->exchange_time - prev_quote->exchange_time;
      // 连续两笔行情的exchange_time不同且间隔小于2秒, 推断为连续交易状态
      if (delta > 0 && delta < 2000000000 && quote_info->exchange_time > exchange_info->last_exchange_date_time) {
        exchange_info->last_exchange_date_time = quote_info->exchange_time;
        time_changed_exchanges[quote_info->ExchangeID()] = exchange_info;
      }
    }
  }
  int64_t now = NowAsEpochNano();
  for (auto& [exchange_id, exchange_info] : time_changed_exchanges) {
    int64_t delta = exchange_info->last_exchange_date_time - now;
    // 交易所时间超前不能超过10分钟
    if (delta > exchange_info->exchange_date_time_delta && abs(delta) < 600000000000) {
      exchange_info->exchange_date_time_delta = exchange_info->last_exchange_date_time - now;
      m_node_db->ReplaceRecord<Exchange>(exchange_info);
    }
  }
}

void MdServiceImpl::ProcessCombQuotesMsg(MdSerializer& ss, rapidjson::Value& comb_quotes) {
  for (auto& m : comb_quotes.GetObject()) {
    std::string combo_id = m.name.GetString();
    auto quote_node = m_node_db->ReplaceRecord<Instrument>(combo_id, [&](std::shared_ptr<md::Instrument> quote) {
      ss.ToVar(*quote, &m.value);
      quote->symbol = combo_id;
    });
