void MdServiceImpl::SetAccessToken(const std::string& access_token) {
  m_access_token = access_token;
  // RTQUpdateToken 存在返回值, 目前没有对应的实现逻辑, 无需考虑返回失败
  // reconnect 置为1, 表征立刻切换新的token
  RTQUpdateToken(m_context_id, m_access_token.c_str(), 1);
}

bool MdServiceImpl::IsBackTest() const {
  // https://en.cppreference.com/w/cpp/algorithm/all_any_none_of
  // if range empty(), all_of () returns true, any_of() returns false
  if (m_md_urls.empty())
    return false;
  return std::all_of(m_md_urls.begin(), m_md_urls.end(), [](const MdAddress& addr) {
    return std::any_of(addr.tags.begin(), addr.tags.end(), [](const std::string& tag) {
      return tag == "backtest";
    });
  });
}

