  : m_context_id(context_id)
  , m_local_md_mode(local_md_mode)
  , m_test_mode(test_mode)
  , m_logger(parent_logger.With("quote_subscriber", reinterpret_cast<int64_t>(this)).Clone()) {}

std::shared_ptr<QuoteSubscriber::QuoteHandle> QuoteSubscriber::SubscribeQuote(InstrumentNode* node) {
  if (nullptr == node || nullptr == node->Latest() || m_local_md_mode)
    return nullptr;
  // subscribe cus-combine quote need to invoke SubscribeComboQuote
  if (node->Latest()->ProductClass() == md::ProductClass::kCusCombine)
    return nullptr;

  return node->Latest()->ProductClass() == md::ProductClass::kCombine
    ? ProcessSubscribe(node, &m_ex_add, &m_ex_handles)
    : ProcessSubscribe(node, &m_future_add, &m_future_handles);
}

void QuoteSubscriber::Subscribe() {
  if (m_local_md_mode)
    return;
  // if there is new data, subscribe immediately
  // otherwise, wait 1min to check if something deleted.
  if (m_future_handles.empty() && m_ex_handles.empty())
    return;
  if (!m_future_add && !m_ex_add && !m_timer.IsExpired())
    return;

  ProcessHandles(&m_future_add, &m_future_handles, [this](const std::string& ins_list) {
    if (m_test_mode) {
      m_test_caches.emplace_back(ins_list);
      return;
    }
    auto ret = RTQSubscribe(m_context_id, ins_list.c_str());
    if (ret != 0)
      m_logger.With("RTQSubscribe", ret).Error("RTQSubscribe failed");
  });
  ProcessHandles(&m_ex_add, &m_ex_handles, [this](const std::string& ins_list) {
    if (m_test_mode) {
      m_test_caches.emplace_back(ins_list);
      return;
    }
    auto ret = RTQSubscribeExCombo(m_context_id, ins_list.c_str());
    if (ret != 0)
      m_logger.With("RTQSubscribeExCombo", ret).Error("RTQSubscribeExCombo failed");
  });
  m_timer.Reset(std::chrono::minutes(1));
}

const std::vector<std::string>& QuoteSubscriber::GetTestCaches() const {
  return m_test_caches;
}

std::shared_ptr<QuoteSubscriber::QuoteHandle> QuoteSubscriber::ProcessSubscribe(
  InstrumentNode* node, bool* add, std::unordered_map<InstrumentNode*, std::weak_ptr<QuoteHandle>>* handles) {
  auto it = handles->find(node);
  if (it != handles->end() && it->second.lock())
    return it->second.lock();

  // there is only new data, add = true
  if (it == handles->end())
    *add = true;

  auto ret = std::make_shared<QuoteHandle>(node);
  handles->try_emplace(node, ret);
  return ret;
}

void QuoteSubscriber::ProcessHandles(bool* add,
  std::unordered_map<InstrumentNode*, std::weak_ptr<QuoteHandle>>* handles,
  std::function<void(const std::string& ins_list)> func) {
  if (handles->empty())
    return;
  bool something_changed = *add;
  if (!something_changed) {
    for (const auto& [_, handle] : *handles) {
      if (!handle.lock()) {
        something_changed = true;
        break;
      }
    }
  }
  if (!something_changed)
    return;
  std::string ins_str;
  for (auto it = handles->begin(); it != handles->end();) {
    if (!it->second.lock()) {
      it = handles->erase(it);
      continue;
    }
    if (!ins_str.empty())
      ins_str.append(",");
    ins_str.append(it->first->GetKey());
    ++it;
  }
  *add = false;
  func(ins_str);
}

