int BackTestService2::RunOnce() {
  m_msg_cnt = 0;
  if (m_md_service->m_context_id <= 0)
    return m_msg_cnt;

  m_md_service->RunOnce();
  m_md_db->CommitTransaction();
  m_md_service->ResponseCommand();
  m_tracker.NotifyAll();

  m_md_gc.gc();

  // backtest service is not running
  if (m_status != BTStatus::kRunning)
    return m_msg_cnt;
  // waiting for request response
  if (!m_pending_charts.empty())
    return m_msg_cnt;

  m_init_charts.empty() ? Advance() : ProcessInitChart();
  return m_msg_cnt;
}

