void BackTestService2::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case SubscribeObjectInfo::AID: {
      ReqSubscribeObjectInfo(command);
      break;
    }
    case SubscribeOptionsByUnderlyingSymbol::AID: {
      ReqSubscribeOptionsByUnderlyingSymbol(command);
      break;
    }
    case SubscribeQuote::AID: {
      ReqSubscribeQuote(command);
      break;
    }
    case SubscribeChartLatest::AID: {
      ReqSubscribeChartLatest(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"fclib: 回测暂不支持该指令");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

