      ++it;
  }
}

EpochNano BackTestService2::CalcBackTestStartTime(const EpochNano& dt) {
  auto ret = dt;
  auto tm_gmt = EpochNanoToLocalDateTime(dt, 8);
  // 631123200000000000 = 1990-01-01 00:00:00
  EpochNano begin_mark = 631123200000000000;
  if (ret > (begin_mark + 21600000000000) && tm_gmt.date_time.tm_hour == 0) {
    return CalcTradeDayStartTime(ret);
  }
  return ret;
}

EpochNano BackTestService2::CalcTradeDayStartTime(const EpochNano& dt) {
  // 631123200000000000 = 1990-01-01 00:00:00
  EpochNano begin_mark = 631123200000000000;
  // 21600000000000 = 6 hours
  EpochNano res = dt - 21600000000000;
  EpochNano delta_time = res - begin_mark;
  int week_day = (delta_time / 86400000000000) % 7;
  if (week_day >= 5) {
    res -= 86400000000000 * (week_day - 4);
  }
  return res;
}

EpochNano BackTestService2::CalcBackTestEndTime(const EpochNano& dt) {
  auto ret = dt;
  auto tm_gmt = EpochNanoToLocalDateTime(dt, 8);
  if (tm_gmt.date_time.tm_hour == 0) {
    // 64799999999999 = 17 hours + 59 minutes + 59 seconds + 999999999 nanoseconds
    return ret + 64799999999999;
  }
  return ret;
}

EpochNano BackTestService2::CalcTradeDayEndTime(const EpochNano& dt) {
  // 631123200000000000 = 1990-01-01 00:00:00
  auto begin_mark = 631123200000000000;
  auto days = (dt - begin_mark) / 86400000000000;
  // 64800000000000 = 18 hours
  if ((dt - begin_mark) % 86400000000000 >= 64800000000000) {
    days++;
  }
  auto week_day = days % 7;
  if (week_day >= 5) {
    days = days + 7 - week_day;
  }
  // 64799999999999 = 17 hours + 59 minutes + 59 seconds + 999999999 nanoseconds
  return begin_mark + days * 86400000000000 + 64799999999999;
}

