void BackTestService2::ReqSubscribeObjectInfo(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<SubscribeObjectInfo>(m_command_manager->Update(command));
  m_md_service->ExecuteCommand(request);
  if (request->status == UserCommand::Status::kFinished)
    return;
  // track command finished to process object info data.
  m_tracker.TrackCommand(command, [this](std::shared_ptr<UserCommand> c) {
    if (c->status == UserCommand::Status::kFinished)
      ProcessObjectInfo();
  });
}

void BackTestService2::ReqSubscribeOptionsByUnderlyingSymbol(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<SubscribeOptionsByUnderlyingSymbol>(m_command_manager->Update(command));
  m_md_service->ExecuteCommand(request);
  if (request->status == UserCommand::Status::kFinished)
    return;
  // track command finished to process object info data.
  m_tracker.TrackCommand(command, [this](std::shared_ptr<UserCommand> c) {
    if (c->status == UserCommand::Status::kFinished)
      ProcessObjectInfo();
  });
}

void BackTestService2::ProcessObjectInfo() {
  // cache for derivate and underlying instrument.
  std::set<md::InstrumentNode*> derivate_cache;
  std::set<md::InstrumentNode*> underlying_cache;
  for (const auto& ins_node : m_md_ins_view->GetCommitNodes()) {
    if (nullptr == ins_node->Latest())
      continue;
    const auto& ins = ins_node->Latest();
    m_node_db->ReplaceRecord<md::Instrument>(ins->symbol,
      [&ins, &ins_node, this, &derivate_cache, &underlying_cache](std::shared_ptr<md::Instrument> update_ins) {
        const auto& ins_base = update_ins->instrument_base;
        ins_base->product_base->exchange_id = ins->ExchangeID();
        ins_base->product_base->product_id = ins->ProductID();
        ins_base->product_base->product_class = ins->ProductClass();
        ins_base->product_base->trading_time = ins->TradingTime();
        ins_base->product_base->price_decs = ins->PriceDecs();
        ins_base->product_base->volume_multiple = ins->VolumeMultiple();
        ins_base->product_base->quote_multiple = ins->QuoteMultiple();
        ins_base->product_base->product_short_name = ins->instrument_base->product_base->product_short_name;
        ins_base->product_base->mmsa = ins->instrument_base->product_base->mmsa;

        ins_base->price_tick = ins->PriceTick();
        ins_base->max_limit_order_volume = ins->instrument_base->max_limit_order_volume;
        ins_base->max_market_order_volume = ins->instrument_base->max_market_order_volume;
        ins_base->expire_date_time = ins->instrument_base->expire_date_time;
        ins_base->last_exercise_day = ins->instrument_base->last_exercise_day;
        ins_base->last_exercise_day_str = ins->instrument_base->last_exercise_day_str;
        ins_base->exercise_type = ins->instrument_base->exercise_type;
        ins_base->delivery_year = ins->instrument_base->delivery_year;
        ins_base->delivery_month = ins->instrument_base->delivery_month;
        ins_base->margin = ins->instrument_base->margin;
        ins_base->commission = ins->instrument_base->commission;
        ins_base->main_in_series = ins->instrument_base->main_in_series;
        ins_base->buy_volume_unit = ins->instrument_base->buy_volume_unit;
        ins_base->sell_volume_unit = ins->instrument_base->sell_volume_unit;

        update_ins->symbol = ins->symbol;
        update_ins->instrument_id = ins->instrument_id;
        update_ins->instrument_name = ins->instrument_name;
        update_ins->english_name = ins->english_name;
        update_ins->option_class = ins->option_class;
        update_ins->strike_price = ins->strike_price;
        update_ins->expired = ins->expired;
        if (ins_base->product_base->product_class == md::ProductClass::kOption)
          update_ins->expired = ins->instrument_base->last_exercise_day <= NowAsEpochNano();

        // process derivate_pointer
        for (const auto& [key, node] : ins->instrument_base->derivate_pointer) {
          NodePointer<md::Instrument> pointer(m_node_db->GetNode<md::Instrument>(key));
          ins_base->derivate_pointer.emplace(std::make_pair(key, pointer));
          if (!pointer)
            derivate_cache.insert(ins_node.get());
        }
        // process underlying_pointer
        const auto& underlying_key = ins->instrument_base->underlying_pointer.Key();
        if (!underlying_key.empty()) {
          ins_base->underlying_pointer = m_node_db->GetNode<md::Instrument>(underlying_key);
          if (!ins_base->underlying_pointer)
            underlying_cache.insert(ins_node.get());
        }
        // process dividend info
        if (ins->ProductClass() == md::ProductClass::kStock) {
          for (const auto& r : GetDividendData(ins->symbol)) {
            update_ins->instrument_base->stock_dividend_ratio[r.dr_date] = r.share;
            update_ins->instrument_base->cash_dividend_ratio[r.dr_date] = r.cash;
          }
        }
      });
  }
  // process derivate cache
  for (const auto& cache_node : derivate_cache) {
    m_node_db->ReplaceRecord<md::Instrument>(cache_node->GetKey(), [&](std::shared_ptr<md::Instrument> update_ins) {
      for (auto&& [key, pointer] : update_ins->instrument_base->derivate_pointer) {
        if (!pointer && !key.empty())
          pointer = m_node_db->GetNode<md::Instrument>(key);
      }
    });
  }
  // process underlying cache
  for (const auto& cache_node : underlying_cache) {
    m_node_db->ReplaceRecord<md::Instrument>(cache_node->GetKey(), [&](std::shared_ptr<md::Instrument> update_ins) {
      if (update_ins->instrument_base->underlying_pointer)
        return;
      const auto& underlying_key = cache_node->Latest()->instrument_base->underlying_pointer.Key();
      if (!underlying_key.empty())
        update_ins->instrument_base->underlying_pointer = m_node_db->GetNode<md::Instrument>(underlying_key);
    });
  }
}

std::vector<BackTestService2::DividendInfo> BackTestService2::GetDividendData(const std::string& symbol) {
  const std::string start_date = DateTimeToDateStr(m_start_dt);
  const std::string end_date = DateTimeToDateStr(m_end_dt);
  if (start_date.empty() || end_date.empty())
    return {};
  std::string query_body = "/query?start_date=" + start_date + "&end_date=" + end_date + "&stock_list=" + symbol;
  try {
    int version = 11;
    const std::string host = "stock-dividend.shinnytech.com";
    const std::string port = "80";

    boost::asio::io_context io;

    boost::asio::ip::tcp::resolver resolver(io);
    boost::beast::tcp_stream stream(io);
    const auto results = resolver.resolve(host, port);
    stream.connect(results);

    boost::beast::http::request<boost::beast::http::string_body> req{
      boost::beast::http::verb::get, query_body, version};
    req.set(boost::beast::http::field::host, host);
    req.set(boost::beast::http::field::user_agent, "backtest_service");
    boost::beast::http::write(stream, req);
    boost::beast::flat_buffer buffer;
    boost::beast::http::response<boost::beast::http::string_body> ret;

    boost::beast::http::read(stream, buffer, ret);
    std::string s = ret.body();

    // parse response data.
    DividendRtnData rtn_data;
    DividendSerializer ss_rtn_data;
    ss_rtn_data.FromString(s.data());
    ss_rtn_data.ToVar(rtn_data);

    // close socket.
    stream.socket().shutdown(boost::asio::ip::tcp::socket::shutdown_both);
    return rtn_data.code == 200 ? rtn_data.result : std::vector<DividendInfo>{};
  } catch (const std::exception& ex) {
    m_logger.With("fun", "GetDividendData").With("errmsg", ex.what()).Error("dividend info update failed!");
    return {};
  }
}

void BackTestService2::ReqSubscribeQuote(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<SubscribeQuote>(m_command_manager->Update(command));
  if (request->node_set.empty()) {
    SetCommandFinished(request, -1, u8"fclib: 回测行情订阅未输入合约列表");
    return;
  }
  for (const auto& node : request->node_set) {
    SubscribeChartByNode(node, request);

    // subscribe underlying chart for option.
    if (node->Latest()->ProductClass() == ProductClass::kOption) {
      const auto& underlying_node = node->Latest()->instrument_base->underlying_pointer;
      if (underlying_node)
        SubscribeChartByNode(underlying_node, request);
    }
    if (request->status == UserCommand::Status::kFinished)
      return;
  }

  if (m_quote_derivates.empty()) {
    SetCommandFinished(command);
    return;
  }
}

void BackTestService2::SubscribeChartByNode(
  std::shared_ptr<InstrumentNode> node, std::shared_ptr<SubscribeQuote> request) {
  if (request->status == UserCommand::Status::kFinished)
    return;
  const auto& symbol = node->Latest()->symbol;
  // check if chart request is duplicated.
  if (auto iter = m_quote_charts.find(symbol); iter != m_quote_charts.end())
    return;
  // derivate chart request (kline duration = 60s).
  auto chart_request =
    DerivateChartRequest(symbol, request->subscribe_id + "_derivate_chart_" + std::to_string(++m_quote_cnt));
  ExecuteCommand(chart_request);

  if (chart_request->status == UserCommand::Status::kFinished) {
    if (chart_request->result_code != 0)
      SetCommandFinished(request, chart_request->result_code, chart_request->result_msg);
    return;
  }

  // manage request, waiting for response.
  m_quote_derivates.insert(chart_request);
  m_tracker.TrackCommand(chart_request, [this, request](std::shared_ptr<UserCommand> c) {
    if (c->status != UserCommand::Status::kFinished)
      return;
    m_status = BTStatus::kRunning;
    m_quote_derivates.erase(c);
    if (c->result_code != 0) {
      SetCommandFinished(request, c->result_code, c->result_msg);
      return;
    }
    if (m_quote_derivates.empty())
      SetCommandFinished(request);
  });
}

void BackTestService2::ReqSubscribeChartLatest(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<SubscribeChartLatest>(m_command_manager->Update(command));
  if (request->symbol_list.empty()) {
    SetCommandFinished(command, -1, u8"fclib: 回测订阅未输入合约列表");
    return;
  }
  if ((request->symbol_list).size() > 1 && request->dur_nano == 0) {
    SetCommandFinished(command, -1, u8"fclib: 回测订阅 Tick 数据不支持多合约");
    return;
  }
  // check if chart request is duplicated.
  const auto key = BTChartKey{request->symbol_list, request->dur_nano};
  if (m_chart_keys.find(key) != m_chart_keys.end()) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同订阅请求");
    return;
  }
  m_chart_keys.insert(key);
  if (request->dur_nano <= MinKlineDuration) {
    if (m_quote_charts.find(request->symbol_list[0]) != m_quote_charts.end()) {
      m_quote_charts[request->symbol_list[0]] = 1;
    } else {
      ++m_quote_charts[request->symbol_list[0]];
    }
  }
  // subscribe chart data.
  auto bt_request = DerivateChartRequest(request);
  m_md_service->ExecuteCommand(bt_request);
  if (bt_request->status == UserCommand::Status::kFinished) {
    if (bt_request->result_code != 0) {
      m_chart_keys.erase(key);
      --m_quote_charts[request->symbol_list[0]];
    }

    SetCommandFinished(command, bt_request->result_code, bt_request->result_msg);
    return;
  }
  // manage request, waiting for response.
  m_pending_charts.insert(request->chart_id);
  m_tracker.TrackCommand(bt_request, [this, request, key](std::shared_ptr<UserCommand> c) {
    if (c->status != UserCommand::Status::kFinished)
      return;
    m_status = BTStatus::kRunning;
    SetCommandFinished(request, c->result_code, c->result_msg);
    m_pending_charts.erase(request->chart_id);
    if (c->result_code != 0) {
      m_chart_keys.erase(key);
      --m_quote_charts[request->symbol_list[0]];
    } else {
      UpdateInitChart(request);
    }
  });
}

std::shared_ptr<UserCommand> BackTestService2::DerivateChartRequest(
  const std::string& symbol, const std::string& chart_id) const {
  auto ret = std::make_shared<md::SubscribeChartLatest>();
  ret->chart_id = chart_id;
  ret->symbol_list = {symbol};
  ret->dur_nano = MinKlineDuration;
  ret->view_width = MaxChartWidth;
  return ret;
}

std::shared_ptr<UserCommand> BackTestService2::DerivateChartRequest(
  std::shared_ptr<SubscribeChartLatest> command) const {
  // backtest need to specify position, view_width and datetime.
  auto ret = std::make_shared<md::SubscribeChartFocus>();
  ret->chart_id = command->chart_id;
  ret->dur_nano = command->dur_nano;
  ret->symbol_list = command->symbol_list;
  ret->view_width = MaxChartWidth;
  ret->focus_datetime = m_current_dt;
  ret->focus_position = MaxChartWidth;
  return ret;
}

std::string BackTestService2::DateTimeToDateStr(const EpochNano& dt) {
  auto time_s = EpochNanoToLocalDateTime(dt, 8);
  char ret[10];
  if (snprintf(ret, sizeof(ret), "%04d%02d%02d", (time_s.date_time.tm_year + 1900), (time_s.date_time.tm_mon + 1),
        time_s.date_time.tm_mday)
    <= 0)
    return "";
  return ret;
}

void BackTestService2::UpdateInitChart(std::shared_ptr<SubscribeChartLatest> request) {
  auto chart_node = m_md_db->GetNode<ChartContent>(request->chart_id);
  FCASSERT(chart_node);
  BTChartInfo chart_info;
  chart_info.chart_id = request->chart_id;
  chart_info.left_id = chart_node->Latest()->left_id;
  chart_info.right_id = chart_node->Latest()->right_id;
  chart_info.current_id = chart_info.left_id;
  chart_info.last_id = GetLastID(request->symbol_list[0], request->dur_nano);
  m_init_charts[{request->symbol_list, request->dur_nano}] = chart_info;
}

int32_t BackTestService2::GetLastID(const std::string& symbol, int64_t duration) {
  if (duration == 0) {
    auto tick_info = m_md_db->GetNode<TickInfo>(symbol);
    return nullptr == tick_info ? -1 : tick_info->Latest()->last_id;
  }
  auto kline_info = m_md_db->GetNode<KlineInfo>(KlineInfo::MakeKey(symbol, duration));
  return nullptr == kline_info ? -1 : kline_info->Latest()->last_id;
}

void BackTestService2::ProcessInitChart() {
  auto cnt = static_cast<int32_t>(m_init_charts.size());
  for (auto it = m_init_charts.begin(); it != m_init_charts.end();) {
    const auto& key = it->first;
    auto&& chart_info = it->second;
    // try to obtain last_id if it is not initialized.
    if (chart_info.last_id < 0) {
      chart_info.last_id = GetLastID(key.symbol_list[0], key.duration);
      if (chart_info.last_id < 0) {
        ++it;
        continue;
      }
    }
    // update chart init data
    while (chart_info.current_id <= chart_info.right_id) {
      KeepSubscribe(key, &chart_info);
      if (!UpdateInitData(key, chart_info))
        break;
      ++chart_info.current_id;
    }
    // check if chart is finished.
    if (chart_info.current_id > chart_info.last_id) {
      it = m_init_charts.erase(it);
      continue;
    }
    // check if chart needs advancing.
    if (chart_info.current_id > chart_info.right_id && UpdateAdvanceChart(key, chart_info)) {
      it = m_init_charts.erase(it);
      continue;
    }
    ++it;
  }
  if (cnt > 0 && m_init_charts.empty())
    ++m_msg_cnt;
  if (m_init_charts.empty() && m_advance_charts.empty()) {
    m_status = BTStatus::kFinished;
    UpdateSession(SessionStatus::kBTFinished, u8"fclib: 回测完成, 无可推进合约");
    return;
  }
}

void BackTestService2::KeepSubscribe(const BTChartKey& key, BTChartInfo* chart) {
  // check if chart has remaining data.
  int32_t remain_id = chart->last_id - chart->current_id;
  if (remain_id <= 0)
    return;
  const auto& symbol_list = key.symbol_list;
  const auto& duration = key.duration;
  if (chart->current_id >= 0 && chart->current_id - chart->left_id > NextChartWidth) {
    // update left id to avoid cyclic request.
    chart->left_id = chart->current_id;
    // next request need specify left_kline_id
    auto next_request = std::make_shared<md::SubscribeChartLeft>();
    next_request->chart_id = chart->chart_id;
    next_request->symbol_list = symbol_list;
    next_request->dur_nano = duration;
    next_request->left_kline_id = chart->current_id;
    int32_t view_width = (remain_id > MaxChartWidth - 1) ? MaxChartWidth : (remain_id + 1);
    next_request->view_width = view_width;
    m_md_service->ExecuteCommand(next_request);

    // try to erase binding info to improve performance.
    if (duration == 0 || symbol_list.size() == 1)
      return;

    // record next request to adjust binding info ready.
    m_next_requests[key] = next_request;
    m_md_db->ReplaceRecord<KlineInfo>(
      KlineInfo::MakeKey(symbol_list[0], duration), [&](std::shared_ptr<KlineInfo> info) {
        for (auto&& [_, binding] : info->binding) {
          if (auto it = binding.find(chart->current_id - 1); it != binding.end())
            binding.erase(binding.begin(), it);
        }
      });
  }
}

bool BackTestService2::UpdateInitData(const BTChartKey& key, const BTChartInfo& chart) {
  if (chart.current_id < 0)
    return true;
  const auto& main_symbol = key.symbol_list[0];
  const auto& symbol_list = key.symbol_list;
  const auto& duration = key.duration;
  if (duration == 0) {
    auto reader = TickSeries::Reader((*m_md_ticks)[main_symbol]);
    reader.update(chart.current_id, chart.current_id + 1);
    if (sdb::get<id>(reader)[0] != chart.current_id)
      return false;
    auto mutator = TickSeries::Mutator((*m_ticks)[main_symbol]);
    UpdateTickData(reader, 0, mutator, main_symbol, chart.current_id);
    if (chart.current_id == chart.right_id)
      UpdateQuoteByTick(reader, 0, main_symbol);
    return true;
  }
  auto kline_info = m_md_db->GetNode<KlineInfo>(KlineInfo::MakeKey(main_symbol, duration));
  FCASSERT(kline_info);
  for (const auto& symbol : symbol_list) {
    auto current_id = GetBindingID(symbol, chart.current_id, kline_info->Latest().get());
    if (current_id < 0)
      continue;
    auto reader = KlineSeries::Reader((*m_md_klines)[symbol][duration]);
    reader.update(current_id, current_id + 1);
    if (sdb::get<id>(reader)[0] != current_id)
      return false;
    auto mutator = KlineSeries::Mutator((*m_klines)[symbol][duration]);
    UpdateKlineDataClose(reader, 0, mutator, symbol, duration, current_id);
    if (chart.current_id == chart.right_id) {
      auto date_time = sdb::get<datetime>(reader)[0] + duration - 1000;
      if (duration >= DayLength)
        date_time = CalcTradeDayStartTime(date_time + 1000) - 1000;
      UpdateQuoteByKlineClose(reader, 0, symbol, date_time);
    }
  }
  return true;
}

void BackTestService2::UpdateQuoteByTick(const TickSeries::Reader& r, int offset, const std::string& symbol) {
  m_node_db->ReplaceRecord<Instrument>(symbol, [&](std::shared_ptr<Instrument> ins) {
    ins->exchange_time = sdb::get<datetime>(r)[offset];
    ins->ask_price[0] = sdb::get<ask_price1>(r)[offset];
    ins->ask_volume[0] = sdb::get<ask_volume1>(r)[offset];
    ins->bid_price[0] = sdb::get<bid_price1>(r)[offset];
    ins->bid_volume[0] = sdb::get<bid_volume1>(r)[offset];
    ins->last_price = sdb::get<last_price>(r)[offset];
    ins->average = sdb::get<average>(r)[offset];
    ins->highest = sdb::get<highest>(r)[offset];
    ins->lowest = sdb::get<lowest>(r)[offset];
    ins->amount = sdb::get<amount>(r)[offset];
    ins->volume = sdb::get<volume>(r)[offset];
    ins->open_interest = sdb::get<open_interest>(r)[offset];
    if (ins->symbol.empty()) {
      ins->symbol = symbol;
      if (auto pos = symbol.find("."); pos != std::string::npos) {
        ins->instrument_base->product_base->exchange_id = symbol.substr(0, pos);
        ins->instrument_id = symbol.substr(pos + 1);
      }
    }
  });
}

void BackTestService2::UpdateQuoteByKlineOpen(
  const KlineSeries::Reader& r, int offset, const std::string& symbol, int64_t date_time) {
  m_node_db->ReplaceRecord<Instrument>(symbol, [&](std::shared_ptr<Instrument> ins) {
    auto ins_node = m_node_db->GetNode<md::Instrument>(symbol);
    double price_tick = (nullptr == ins_node) ? 0.0 : ins_node->Latest()->PriceTick();

    ins->exchange_time = date_time;
    ins->ask_price[0] = sdb::get<open>(r)[offset] + price_tick;
    ins->ask_volume[0] = 1;
    ins->bid_price[0] = sdb::get<open>(r)[offset] - price_tick;
    ins->bid_volume[0] = 1;
    ins->last_price = sdb::get<open>(r)[offset];
    ins->volume = 0;
    ins->open_interest = sdb::get<open_oi>(r)[offset];

    if (ins->symbol.empty()) {
      ins->symbol = symbol;
      if (auto pos = symbol.find("."); pos != std::string::npos) {
        ins->instrument_base->product_base->exchange_id = symbol.substr(0, pos);
        ins->instrument_id = symbol.substr(pos + 1);
