int32_t BackTestService2::GetBindingID(const std::string& symbol, int32_t id, const KlineInfo* info) const {
  if (symbol == info->symbol)
    return id;
  const auto& binding = info->binding;
  if (binding.empty())
    return -1;
  auto binding_iter = binding.find(symbol);
  if (binding_iter == binding.end()) {
    return -1;
  }
  const auto& binding_id = binding_iter->second;
  auto id_iter = binding_id.find(id);
  if (id_iter == binding_id.end()) {
    return -1;
  }
  return static_cast<int32_t>(id_iter->second);
}

