bool BackTestService2::UpdateAdvanceChart(const BTChartKey& key, const BTChartInfo& chart) {
  BTChartInfo ad = chart;
  ad.left_id = chart.left_id;
  ad.current_id = chart.right_id;
  ad.right_id = chart.left_id + MaxChartWidth - 1;

  const auto& symbol_list = key.symbol_list;
  const auto& duration = key.duration;

  // tick data
  if (duration == 0) {
    auto reader = TickSeries::Reader((*m_md_ticks)[symbol_list[0]]);
    reader.update(chart.right_id, chart.right_id + 2);
    // try to obtain the next tick datatime.
    if (sdb::get<id>(reader)[0] != chart.right_id || sdb::get<id>(reader)[1] != chart.right_id + 1)
      return false;
    ad.current_dt = sdb::get<datetime>(reader)[0];
    ad.next_dt = sdb::get<datetime>(reader)[1];
    m_advance_charts[key] = ad;
    return true;
  }

  if (auto iter = m_next_requests.find(key); iter != m_next_requests.end()) {
    auto request = iter->second;
    if (request && request->status != UserCommand::Status::kFinished)
      return false;
  }

  // kline data
  auto reader = KlineSeries::Reader((*m_md_klines)[symbol_list[0]][duration]);
  reader.update(chart.right_id, chart.right_id + 2);
  // try to obtain the next kline datatime.
  if (sdb::get<id>(reader)[0] != chart.right_id || sdb::get<id>(reader)[1] != chart.right_id + 1)
    return false;
  if (duration < DayLength) {
    ad.current_dt = sdb::get<datetime>(reader)[0] + duration - 1000;
    ad.next_dt = sdb::get<datetime>(reader)[1];
  } else {
    ad.current_dt = CalcTradeDayStartTime(sdb::get<datetime>(reader)[0] + duration) - 1000;
    ad.next_dt = CalcTradeDayStartTime(sdb::get<datetime>(reader)[1]);
  }
  m_advance_charts[key] = ad;
  return true;
}

bool BackTestService2::ProcessAdvanceChart() {
  bool ret = false;
  for (auto it = m_advance_charts.begin(); it != m_advance_charts.end();) {
    auto&& chart = it->second;
    if (chart.current_id >= chart.last_id) {
      it = m_advance_charts.erase(it);
      continue;
    }
    if (chart.next_dt > m_next_dt) {
      ++it;
      continue;
    }
    if (chart.current_id == chart.right_id)
      chart.right_id = chart.left_id + MaxChartWidth - 1;
    UpdateAdvanceData(it->first, &chart);
    ret = true;
    ++it;
  }
  // update current datetime to next datetime.
  m_current_dt = m_next_dt;
  MockDateTime(m_current_dt);
  if (m_advance_charts.empty() && m_status != BTStatus::kFinished) {
    ret = true;
    m_status = BTStatus::kFinished;
    UpdateSession(SessionStatus::kBTFinished, u8"fclib: 回测完成");
  }
  return ret;
}

void BackTestService2::UpdateAdvanceData(const BTChartKey& key, BTChartInfo* chart) {
  const auto& main_symbol = key.symbol_list[0];
  const auto& symbol_list = key.symbol_list;
  const auto& duration = key.duration;

  if (duration == 0) {
    auto next_id = chart->current_id + 1;
    auto next_next_id = (next_id >= chart->last_id) ? chart->last_id : next_id + 1;
    auto next_tick_reader = TickSeries::Reader((*m_md_ticks)[main_symbol]);
    auto next_next_tick_reader = TickSeries::Reader((*m_md_ticks)[main_symbol]);
    next_tick_reader.update(next_id, next_id + 1);
    next_next_tick_reader.update(next_next_id, next_next_id + 1);
    // update next tick data.
    auto mutator = TickSeries::Mutator((*m_ticks)[main_symbol]);
    UpdateTickData(next_tick_reader, 0, mutator, main_symbol, next_id);
    UpdateQuoteByTick(next_tick_reader, 0, main_symbol);
    // update chart info to next tick.
    chart->current_id = next_id;
    chart->current_dt = chart->next_dt;
    chart->next_dt = sdb::get<datetime>(next_next_tick_reader)[0];
    return;
  }

  auto kline_info = m_md_db->GetNode<KlineInfo>(KlineInfo::MakeKey(main_symbol, duration));
  FCASSERT(kline_info);

  if (chart->next_dt % 1000000000 != 0) {
    for (const auto& symbol : symbol_list) {
      // finish current kline data.
      auto b_id = GetBindingID(symbol, chart->current_id, kline_info->Latest().get());
      if (b_id < 0)
        continue;
      auto reader = KlineSeries::Reader((*m_md_klines)[symbol][duration]);
      reader.update(b_id, b_id + 1);
      auto mutator = KlineSeries::Mutator((*m_klines)[symbol][duration]);
      UpdateKlineDataClose(reader, 0, mutator, symbol, duration, b_id);
      UpdateQuoteByKlineClose(reader, 0, symbol, chart->next_dt);
    }
    // update chart info to current kline end.
    auto reader = KlineSeries::Reader((*m_md_klines)[main_symbol][duration]);
    reader.update(chart->current_id + 1, chart->current_id + 2);
    chart->current_dt = chart->next_dt;
    // update datetime to next kline start.
    chart->next_dt = sdb::get<datetime>(reader)[0];
    if (duration >= DayLength)
      chart->next_dt = CalcTradeDayStartTime(chart->next_dt);
    return;
  }
  for (const auto& symbol : symbol_list) {
    // update to next kline data.
    auto b_id = GetBindingID(symbol, chart->current_id + 1, kline_info->Latest().get());
    if (b_id < 0)
      continue;
    auto reader = KlineSeries::Reader((*m_md_klines)[symbol][duration]);
    reader.update(b_id, b_id + 1);
    auto mutator = KlineSeries::Mutator((*m_klines)[symbol][duration]);
    UpdateKlineDataOpen(reader, 0, mutator, symbol, duration, b_id);
    UpdateQuoteByKlineOpen(reader, 0, symbol, chart->next_dt);
  }
  // update chart info to next kline.
  auto reader = KlineSeries::Reader((*m_md_klines)[main_symbol][duration]);
  reader.update(chart->current_id + 1, chart->current_id + 2);
  ++chart->current_id;
  chart->current_dt = chart->next_dt;
  // update datetime to next kline end.
  chart->next_dt = sdb::get<datetime>(reader)[0] + duration - 1000;
  if (duration >= DayLength)
    chart->next_dt = CalcTradeDayStartTime(chart->next_dt + 1000) - 1000;
}

bool BackTestService2::IsChartReady() {
  for (auto&& [key, chart] : m_advance_charts) {
    if (chart.current_id >= chart.last_id || chart.next_dt > m_next_dt)
      continue;

    const auto& main_symbol = key.symbol_list[0];
    const auto& symbol_list = key.symbol_list;
    const auto& duration = key.duration;

    KeepSubscribe(key, &chart);
    bool ret = (duration == 0) ? IsTickChartReady(main_symbol, chart) : IsKlineChartReady(symbol_list, key, chart);
    if (!ret)
      return false;
  }
  return true;
}

bool BackTestService2::IsTickChartReady(const std::string& symbol, const BTChartInfo& chart) {
  auto next_id = chart.current_id + 1;
  auto next_next_id = (next_id >= chart.last_id) ? chart.last_id : next_id + 1;
  auto next_tick_reader = TickSeries::Reader((*m_md_ticks)[symbol]);
  auto next_next_tick_reader = TickSeries::Reader((*m_md_ticks)[symbol]);
  next_tick_reader.update(next_id, next_id + 1);
  next_next_tick_reader.update(next_next_id, next_next_id + 1);
  return sdb::get<id>(next_tick_reader)[0] == next_id && sdb::get<id>(next_next_tick_reader)[0] == next_next_id;
}

bool BackTestService2::IsKlineChartReady(
  const std::vector<std::string>& symbol_list, const BTChartKey& key, const BTChartInfo& chart) {
  const auto& duration = key.duration;
  const auto& main_symbol = symbol_list[0];
  auto kline_info = m_md_db->GetNode<KlineInfo>(KlineInfo::MakeKey(main_symbol, duration));
  FCASSERT(kline_info);

  // try to check current / next kline data.
  auto check_id = chart.next_dt % 1000000000 != 0 ? chart.current_id : chart.current_id + 1;

  if (auto iter = m_next_requests.find(key); iter != m_next_requests.end()) {
    auto request = iter->second;
    if (request && check_id > request->left_kline_id && request->status != UserCommand::Status::kFinished)
      return false;
  }

  for (const auto& symbol : symbol_list) {
    auto b_id = GetBindingID(symbol, check_id, kline_info->Latest().get());
    if (b_id < 0)
      continue;
    auto reader = KlineSeries::Reader((*m_md_klines)[symbol][duration]);
    reader.update(b_id, b_id + 1);
    if (sdb::get<id>(reader)[0] != b_id)
      return false;
  }
  auto reader = KlineSeries::Reader((*m_md_klines)[main_symbol][duration]);
  reader.update(chart.current_id + 1, chart.current_id + 2);
  return sdb::get<id>(reader)[0] == chart.current_id + 1;
}

EpochNano BackTestService2::CalcNextDateTime() const {
  EpochNano ret = m_advance_charts.begin()->second.next_dt;
  for (const auto& [key, chart] : m_advance_charts) {
    if (chart.next_dt > 0 && chart.next_dt < ret)
      ret = chart.next_dt;
  }
  return ret;
}

void BackTestService2::Advance() {
  if (!m_alive_commands.empty() || m_status != BTStatus::kRunning || !m_init_charts.empty())
    return;
  if (m_advance_charts.empty() && m_status != BTStatus::kFinished) {
    m_status = BTStatus::kFinished;
    UpdateSession(SessionStatus::kBTFinished, u8"fclib: 回测完成");
    ++m_msg_cnt;
    return;
  }
  // search next datetime to advance
  if (m_current_dt == m_next_dt)
    m_next_dt = CalcNextDateTime();
  if (m_next_dt > m_end_dt && m_status != BTStatus::kFinished) {
    m_status = BTStatus::kFinished;
    UpdateSession(SessionStatus::kBTFinished, u8"fclib: 回测完成");
    ++m_msg_cnt;
    return;
  }
  if (IsChartReady() && ProcessAdvanceChart())
    ++m_msg_cnt;
}

