void TqApiController::StartDebugPort(int debug_port, structlog::Logger& parent_logger) {
  if (debug_port == 0)
    return;
  m_server = WebsocketServer::Create(&m_ioc, parent_logger);
  m_server
    ->OnSessionBegin([](std::weak_ptr<WebsocketSession> session) {
      printf("Connected\n");
    })
    ->OnSessionEnd([](std::weak_ptr<WebsocketSession> session) {
      printf("Disconnected!\n");
    })
    ->OnSessionReceivedMessage([&](std::weak_ptr<WebsocketSession> session, const std::string& msg) {
      printf("Received : %s\n", msg.c_str());
      ProcessInput(msg);
    })
    ->Listen("0.0.0.0", std::to_string(debug_port));
  m_thread = std::thread([&] {
    m_ioc.run();
  });
}

void TqApiController::ProcessInput(const std::string& req) {
  TqApiControlPkgSerializer ss;
  ss.FromString(req.c_str());
  ss.ToVar(m_control_pkg);
  TqApiControlPackage temp_pkg;
  ss.ToVar(temp_pkg);
  for (auto&& [symbol, point] : temp_pkg.local_md_control_pkg.pattern) {
    if (!point.points.empty())
      m_control_pkg.local_md_control_pkg.pattern[symbol].points = point.points;
  }
  UpdateControlPkg();
}

