void TqApiImpl::Init(const TqApiOptions& options) {
  m_options = options;
  FCASSERT(!m_options.config_directory.empty());
  DumpHelper::InitDumpHelper(m_options.config_directory);

  // 设置共享内存路径
#ifdef BOOST_INTERPROCESS_SHARED_DIR_FUNC
  if (u8SharedMemoryPath.empty() || u16SharedMemoryPath.empty()) {
    std::filesystem::path directory = std::filesystem::u8path(m_options.config_directory);
    directory.append("shm");

    std::filesystem::create_directories(directory);
    u8SharedMemoryPath = directory.u8string();
    u16SharedMemoryPath = directory.wstring();
  }
#endif  // BOOST_INTERPROCESS_SHARED_DIR_FUNC
  m_control_pkg.local_md_mode = options.local_md_mode;
  if (!options.disable_node1)
    m_root = std::make_shared<TqApiTreeRootNode>(true);
  m_db = std::make_shared<TqApiNodeDb>(true, options.addition_reader_count);
  m_klines = std::make_shared<md::KlinePartition>("", m_gc);
  m_ticks = std::make_shared<md::TickPartition>("", m_gc);

  if (!options.test_mode) {
    m_process_manager = std::make_shared<TradeProcessManager>(&m_api_ioc, m_db, m_options, m_logger);
    m_process_manager->Init();
    m_shm_release = std::make_unique<ShmRelease>(m_options.config_directory, m_logger);
  }

  // Views
  m_alive_order_view = m_db->CreateView<future::Order>(
    ReuseViewKey::kAliveOrder, true, [](std::shared_ptr<const future::Order> order) -> bool {
      return order->status == future::OrderStatus::kAlive;
    });
  m_db->CreateView<md::Instrument>(ReuseViewKey::kInstrument);
  m_db->CreateView<md::Product>(ReuseViewKey::kProduct);
  m_db->CreateView<md::Exchange>(
    ReuseViewKey::kSingleExchange, true, [](std::shared_ptr<const md::Exchange> exchange) -> bool {
      return exchange->exchange_id == "SHFE";
    });
  m_login_view = m_db->CreateView<future::LoginContent>(ReuseViewKey::kLogin);
  m_order_view = m_db->CreateView<future::Order>(ReuseViewKey::kOrder);
  m_trade_view = m_db->CreateView<future::Trade>(ReuseViewKey::kTrade);
  m_position_view = m_db->CreateView<future::Position>(ReuseViewKey::kPosition);
  m_account_view = m_db->CreateView<future::Account>(ReuseViewKey::kAccount);

  m_db->CreateView<security::Order>(ReuseViewKey::kSecurityOrder);
  m_db->CreateView<security::Order>(ReuseViewKey::kSecurityAliveOrder);
  m_db->CreateView<future::ExecOrder>(ReuseViewKey::kExecOrder);
  m_db->CreateView<future::OptionSelfClose>(ReuseViewKey::kSelfCloseOrder);

  m_cus_comb_position_merge = std::make_shared<future::CusCombPositionMerge>(m_db, m_logger);

  m_running = false;
  // 创建TqApi控制器
  if (m_options.debug_port != 0) {
    StartDebugPort(m_options.debug_port, m_logger);
  }
  auto md_node = m_root ? m_root->UpdateChild<ApiTreeKey::kMarketData>() : nullptr;
  // 创建 md_service
  m_local_md_service = md::LocalMdService::Create(m_db, m_logger);
  if (m_control_pkg.local_md_mode) {
    auto command = std::make_shared<md::GenerateInsTable>();
    AsyncRequest(command);
  }
  m_real_md_service = md::MdService::Create(&m_api_ioc, md_node, m_db, m_klines, m_ticks, m_logger, m_options);

  m_quote_subscriber = std::make_shared<md::QuoteSubscriber>(
    m_real_md_service->GetContextId(), m_control_pkg.local_md_mode, m_options.test_mode, m_logger);
  m_quote_auto_subscriber = std::make_shared<md::QuoteAutoSubscriber>(m_logger, m_db, m_quote_subscriber);

  // 创建合约行情共享内存
  if (!options.test_mode) {
    m_md_shared_memory = std::make_shared<md::MdSharedMemory>(m_db, m_logger);
    m_md_shared_memory->Init();
  }
  m_logger.Info("inited");
}

void TqApiImpl::UpdateControlPkg() {
  // 处理伪合约行情服务控制参数
  m_local_md_service->SetBaseDateTime(m_control_pkg.local_md_control_pkg.base_datetime);
  m_local_md_service->SetStepLength(m_control_pkg.local_md_control_pkg.step_length);
  for (auto& [symbol, pattern] : m_control_pkg.local_md_control_pkg.pattern) {
    if (!pattern.points.empty())
      m_local_md_service->SetPattern(symbol, pattern.points, pattern.price_adjust);
  }

  // 处理本地模拟交易控制参数
  if (!m_options.test_mode) {
    auto trade_service = m_process_manager->GetChildProcess(m_control_pkg.local_sim_control_pkg.user_key);
    if (trade_service) {
      // todo: 如果试图给非模拟账号发送debug指令，应该无效果，并得到反馈信息。
      auto req = std::make_shared<future::TransferMoney>(m_control_pkg.local_sim_control_pkg.user_key);
      req->is_deposit = m_control_pkg.local_sim_control_pkg.init_balance > 10000000.0;
      req->amount = std::abs(m_control_pkg.local_sim_control_pkg.init_balance - 10000000.0);
      trade_service->ExecuteCommand(req);
    }
    return;
  }
  auto trade_service = GetTradeService(m_control_pkg.local_sim_control_pkg.user_key);
  if (trade_service) {
    auto local_sim_service = std::static_pointer_cast<future::local_sim::LocalSimService>(trade_service);
    if (local_sim_service) {
      auto req = std::make_shared<future::TransferMoney>(m_control_pkg.local_sim_control_pkg.user_key);
      req->is_deposit = m_control_pkg.local_sim_control_pkg.init_balance > 10000000.0;
      req->amount = std::abs(m_control_pkg.local_sim_control_pkg.init_balance - 10000000.0);
      local_sim_service->ExecuteCommand(req);
      local_sim_service->SetNetworkConnection(m_control_pkg.local_sim_control_pkg.network_connection);
    }
  }
}

std::shared_ptr<ServiceInterface> TqApiImpl::GetMdService() {
  if (m_control_pkg.local_md_mode)
    return m_local_md_service;
  return m_real_md_service;
}

int TqApiImpl::RunOnce(int64_t block_timeout) {
  m_logger.Debug("runonce");

  int processed_msg = 0;
  if (m_running)
    return processed_msg;
  m_running = true;

  if (m_root)
    m_root->CommitTransaction();
  if (m_root)
    m_root->BeginTransaction();

  if (!m_api_ioc.poll() && block_timeout) {
    m_api_ioc.restart();
    m_api_ioc.run_one_for(std::chrono::milliseconds(block_timeout));
  }
  m_api_ioc.restart();
  m_quote_subscriber->Subscribe();
  if (int c1 = GetMdService()->RunOnce()) {
    processed_msg += c1;
    if (m_root)
      m_root->UpdateChild<ApiTreeKey::kMarketData>();
    m_gc.gc();
  }
  for (auto& [user_key, trade_service] : m_trade_service_map) {
    if (int msg_count = trade_service->RunOnce()) {
      processed_msg += msg_count;
    }
  }
  if (m_process_manager)
    processed_msg += m_process_manager->RunOnce();
  m_cus_comb_position_merge->RunOnce();

  m_logger.Debug("start commit transaction");
  if (m_root)
    m_root->CommitTransaction();
  m_db->CommitTransaction();
  m_logger.Debug("end commit transaction");

  // 各服务发出指令执行反馈
  GetMdService()->ResponseCommand();
  if (m_process_manager)
    m_process_manager->ResponseCommand();
  for (const auto& [_, trade_service] : m_trade_service_map) {
    trade_service->ResponseCommand();
  }
  m_command_tracker.NotifyAll();
  // 从这里开始执行外部代码. 外部代码对存储树的修改都累积在 commit 层, 不会导致存储树版本推进
  if (m_root)
    m_node_tracker.RunOnce();
  m_running = false;

  return processed_msg;
}

void TqApiImpl::RequestFutureCommand(std::shared_ptr<future::FutureCommand> request) {
  if (!m_options.test_mode) {
    auto trade_service = GetTradeService(request->user_key);
    trade_service = GetTradeService(request->user_key);
    if (trade_service) {
      trade_service->ExecuteCommand(request);
    } else {
      m_process_manager->ExecuteCommand(request);
    }
    return;
  }

  auto trade_service = GetTradeService(request->user_key);
  if (!trade_service) {
    if (request->aid == future::ReqLogin::AID) {
      auto req = std::static_pointer_cast<future::ReqLogin>(request);
      if (req->backend != future::BackEnd::kLocalSim) {
        SetCommandFinished(request, -1, u8"fclib: 测试模式仅可登录本地模拟柜台");
        return;
      }
      auto service = future::local_sim::LocalSimService::Create(&m_api_ioc, request->user_key, m_db, m_logger);
      AddTradeService(request->user_key, service);
    }
    trade_service = GetTradeService(request->user_key);
  }
  if (trade_service) {
    trade_service->ExecuteCommand(request);
  } else {
    SetCommandFinished(request, -1, u8"fclib: 交易服务未登录");
  }
}

void TqApiImpl::RequestSecurityCommand(std::shared_ptr<security::SecurityCommand> request) {
  switch (request->aid) {
    case security::ReqLogin::AID: {
      auto req = std::static_pointer_cast<security::ReqLogin>(request);
      switch (req->backend) {
        case security::BackEnd::kOtg: {
          auto trade_service = security::otg::SecurityOtgService::Create(req->user_key, m_db, m_logger,
            (req->otg_access_token.empty()) ? m_options.access_token : req->otg_access_token);
          AddTradeService(request->user_key, trade_service);
          break;
        }
        case security::BackEnd::kLocalSim: {
          auto trade_service =
            security::local_sim::SecurityLocalSimService::Create(request->user_key, m_db, GetMdService(), m_logger);
          AddTradeService(request->user_key, trade_service);
          break;
        }
        default: break;
      }
    }
    default: break;
  }
  auto trade_service = GetTradeService(request->user_key);
  if (trade_service)
    trade_service->ExecuteCommand(request);
}

void TqApiImpl::AsyncRequest(std::shared_ptr<UserCommand> command) {
  std::string command_json = command->ToJson();
  m_logger.With("command", structlog::make_json(command_json)).Info("async request");
  // 检查有效性
  std::string msg;
  if (!command->Check(&msg)) {
    SetCommandFinished(command, -1, msg);
    return;
  }
  if (command->aid == future::ReqChangeOptions::AID) {
    auto req = std::static_pointer_cast<future::ReqChangeOptions>(command);
    m_options.enable_position_details = req->enable_position_details;
    SetCommandFinished(command);
    return;
  }
  if (command->aid == future::ReqLogOut::AID) {
    auto req = std::static_pointer_cast<future::ReqLogOut>(command);
    if (req->user_key != "logout_all") {
      SetCommandFinished(command, -1, u8"fclib: 仅支持注销所有用户");
      return;
    }
    if (m_process_manager)
      m_process_manager->CleanUp();
    SetCommandFinished(command);
    return;
  }
  if ((command->aid >= future::MinUserCommand) && (command->aid <= future::MaxUserCommand)) {
    if (m_options.monitor_mode
      && (command->aid == future::InsertOrder::AID || command->aid == future::CancelOrder::AID
        || command->aid == future::InsertExecOrder::AID || command->aid == future::CancelExecOrder::AID
        || command->aid == future::InsertOptionSelfClose::AID || command->aid == future::CancelOptionSelfClose::AID
        || command->aid == future::InsertQuote::AID || command->aid == future::CancelQuote::AID
        || command->aid == future::PositionCombInsert::AID)) {
      SetCommandFinished(command, -1, u8"监控模式下无法交易");
      m_logger.With("command", structlog::make_json(command_json))
        .With("monitor_mode", m_options.monitor_mode)
        .Info("command canceled by monitor_mode");
      return;
    }
    RequestFutureCommand(std::static_pointer_cast<future::FutureCommand>(command));
    return;
  } else if ((command->aid >= security::MinUserCommand) && (command->aid <= security::MaxUserCommand)) {
    RequestSecurityCommand(std::static_pointer_cast<security::SecurityCommand>(command));
    return;
  } else if ((command->aid >= md::MinUserCommand) && (command->aid <= md::MaxUserCommand)) {
    if (command->aid == md::SubscribeComboInstrument::AID)
      m_cus_comb_position_merge->SubscribeComboInstrument(
        std::static_pointer_cast<md::SubscribeComboInstrument>(command));
    GetMdService()->ExecuteCommand(command);
    return;
  } else {
    FCASSERT(false);
  }
}

void TqApiImpl::AsyncRequest(
  std::shared_ptr<UserCommand> command, std::function<void(std::shared_ptr<UserCommand>)> notify_func) {
  m_command_tracker.TrackCommand(command, notify_func);
  AsyncRequest(command);
