#include "fclib/nstring/nstring.h"
#include <string>
namespace fclib {

std::size_t NString::npos = std::string_view::npos;

NString::operator bool() const {
  return nullptr != m_data;
}

NString::operator std::string() const {
  if (nullptr == m_data)
    return std::string();
  return std::string(m_data, size());
}

NString::operator std::string_view() const {
  if (nullptr == m_data)
    return std::string_view();
  return std::string_view(m_data, size());
}

NString& NString::operator=(const char* str) {
  m_data = str ? SSTable::Instance().Store(str, strlen(str)) : nullptr;
  return *this;
}

NString& NString::operator=(std::string_view str) {
  m_data = SSTable::Instance().Store(str.data(), str.length());
  return *this;
}

std::string NString::operator+(const NString& other) const {
  std::string result;
  if (m_data)
    result += m_data;
  if (other)
    result += other.data();
  return result;
}

std::string NString::operator+(const char* other) const {
  std::string result;
  if (m_data)
    result += m_data;
  if (other)
    result += other;
  return result;
}

std::string NString::operator+(std::string_view other) const {
  std::string result;
  if (m_data)
    result += m_data;
  result += other;
  return result;
}

bool NString::operator==(const NString& other) const {
  return m_data == other.m_data;
}

bool NString::operator==(const char* other) const {
  if (nullptr == m_data || nullptr == other)
    return m_data == other;
  auto sz = size();
  return std::strncmp(m_data, other, sz) == 0 && other[sz] == '\0';
}

bool NString::operator==(std::string_view other) const {
  return operator==(other.data());
}

bool NString::operator!=(const NString& other) const {
  return m_data != other.m_data;
}

bool NString::operator!=(const char* other) const {
  return !operator==(other);
}

bool NString::operator!=(std::string_view other) const {
  return !operator==(other.data());
}

bool NString::operator<(const NString& other) const {
  if (nullptr == m_data)
    return nullptr != other.m_data;
  if (nullptr == other.m_data)
    return false;
  return index() < other.index();
}

bool NString::empty() const {
  return nullptr == m_data;
}

const char* NString::c_str() const {
  return m_data;
}

const char* NString::data() const {
  return m_data;
}

std::size_t NString::size() const {
  if (nullptr == m_data)
    return 0;

  // each data uses 9 bytes to store information
  // 4 bytes in the first 8 bytes of the data are used to store the length.
  // 4 bytes are used to store the location.
  // then data stored in the location.
  // 1 byte after the data is padded with \0.
  unsigned int ret;
  std::memcpy(&ret, m_data - 8, 4);
  return static_cast<std::size_t>(ret);
}

unsigned int NString::index() const {
  if (nullptr == m_data)
    return -1;

  // each data uses 9 bytes to store information
  // 4 bytes in the first 8 bytes of the data are used to store the length.
  // 4 bytes are used to store the location.
  // then data stored in the location.
  // 1 byte after the data is padded with \0.
  unsigned int ret;
  std::memcpy(&ret, m_data - 4, 4);
  return ret;
}

std::string_view::const_iterator NString::begin() const {
  if (nullptr == m_data)
    return std::string_view().begin();
  return std::string_view(m_data, size()).begin();
}

std::string_view::const_iterator NString::NString::end() const {
  if (nullptr == m_data)
    return std::string_view().end();
  return std::string_view(m_data, size()).end();
}

std::string NString::substr(std::size_t start, std::size_t length) const {
  std::size_t str_size = size();
  if (start >= str_size || start < 0)
    return std::string();
  return std::string(std::string_view(m_data, str_size).substr(start, length));
}

std::size_t NString::find(const char* target, std::size_t pos) const {
  if (nullptr == m_data || nullptr == target || pos >= size() || pos < 0)
    return NString::npos;

  return std::string_view(m_data, size()).find(target, pos);
}

std::string operator+(std::string_view str, const NString& nstr) {
  std::string result(str);
  if (nstr.data())
    result += nstr.data();
  return result;
}

}  // namespace fclib

