const std::string GetEncryptKey(std::string_view key) {
  static const std::string s_encrypt_key = u8"7fclIB?En_kEY|1";
  std::string ret = "?" + std::string(key) + s_encrypt_key;
  if (ret.size() > 16) {
    ret = ret.substr(ret.size() - 16);
  }
  return ret;
}

std::string FormatNoticeTextContent(std::string_view content) {
  std::string ret = std::string(content);
#ifdef __linux__
  size_t pos = 0;
  while ((pos = ret.find("\r\n", pos)) != std::string::npos) {
    ret.replace(pos, 2, "\n");
    ++pos;
  }
#else
  if (ret.find("\r\n") != std::string::npos) {
    return ret;
  }
  size_t pos = 0;
  while ((pos = ret.find('\n', pos)) != std::string::npos) {
    ret.replace(pos, 1, "\r\n");
    pos += 2;
  }
#endif
  return ret;
}

void OrderBase::UpdateOrderByTrade(std::shared_ptr<const TradeBase> trade, std::shared_ptr<const md::Instrument> ins) {
  FCASSERT(trade);
  FCASSERT(ins);
  // 更新委托最后成交时间
  if (trade->trade_date_time > last_trade_date_time)
    last_trade_date_time = trade->trade_date_time;
  // 更新成交均价和成交手数
  bool is_combine =
    (ins->ProductClass() == md::ProductClass::kCombine || ins->ProductClass() == md::ProductClass::kCusCombine);
  if (!is_combine) {
    FCASSERT(trade->Symbol() == ins->symbol);
    if (trade_total_volume + trade->volume <= 0)
      return;
    if (isnan(trade_price))
      trade_price = 0.0;
    trade_price =
      (trade_price * trade_total_volume + trade->price * trade->volume) / (trade_total_volume + trade->volume);
    trade_total_volume += trade->volume;
    return;
  }
  auto leg1_symbol = ins->instrument_base->leg1_pointer.Key();
  auto leg2_symbol = ins->instrument_base->leg2_pointer.Key();
  if (trade->Symbol() != leg1_symbol && trade->Symbol() != leg2_symbol)
    return;
  if (trade->Symbol() == leg1_symbol) {
    if (isnan(_leg1_trade_price))
      _leg1_trade_price = 0.0;
    _leg1_trade_price = (_leg1_trade_price * _leg1_trade_total_volume + trade->price * trade->volume)
      / (_leg1_trade_total_volume + trade->volume);
    _leg1_trade_total_volume += trade->volume;
  } else {
    if (isnan(_leg2_trade_price))
      _leg2_trade_price = 0.0;
    _leg2_trade_price = (_leg2_trade_price * _leg2_trade_total_volume + trade->price * trade->volume)
      / (_leg2_trade_total_volume + trade->volume);
    _leg2_trade_total_volume += trade->volume;
  }
  trade_price = _leg1_trade_price - _leg2_trade_price;
  trade_total_volume = (std::min)(_leg1_trade_total_volume, _leg2_trade_total_volume);
}

void Order::UpdateOrderByTrade(std::shared_ptr<TradeNode> trade_node) {
  NodePointer<Trade> trade_pointer(trade_node);
  if (trade_set.find(trade_pointer) != trade_set.end())
    return;
  trade_set.insert(trade_pointer);
  FCASSERT(ins_pointer);
  OrderBase::UpdateOrderByTrade(trade_node->Latest(), ins_pointer->Latest());
}

