bool ReqLogin::Check(std::string* msg) {
  if (backend == BackEnd::kInvalid) {
    *msg = u8"fclib: API 类型填写错误";
    return false;
  }
  if (!replay_flow_file_name.empty() || mock_api.enable)
    return true;
  if (user_id.empty()) {
    *msg = u8"fclib: 用户名称填写错误";
    return false;
  }
  if (backend == BackEnd::kLocalSim)
    return true;
  if (password.empty()) {
    *msg = u8"fclib: 用户密码填写错误";
    return false;
  }
  if (otg.front_url.empty() && backend == BackEnd::kOtg) {
    *msg = u8"fclib: OTG 服务器信息填写错误";
    return false;
  }
  if (otg.bid.empty() && backend == BackEnd::kOtg) {
    *msg = u8"fclib: OTG 服务器中定义的期货公司名称填写错误";
    return false;
  }
  if (backend == BackEnd::kOtg)
    return true;
  if (xuntou.sub_user_type == -1 && backend == BackEnd::kXuntou) {
    *msg = u8"fclib: Xuntou 子账户类型填写错误";
    return false;
  }
  if (yida.group_id > 63 || yida.group_id < 1) {
    *msg = u8"fclib: YiDa 报单组 ID 范围 [1-63]";
    return false;
  }
  if (entrust_way == 'I' && backend == BackEnd::kUFX) {
    *msg = u8"fclib: 恒生登录委托方式填写错误";
    return false;
  }
  if (license_file_addr.empty() && backend == BackEnd::kUFX) {
    *msg = u8"fclib: 文件路径填写错误";
    return false;
  }
  if (broker.trading_fronts.empty()) {
    *msg = u8"fclib: 交易前置填写错误";
    return false;
  }
  if (broker.app_id.empty()) {
    *msg = u8"fclib: APPID 填写错误";
    return false;
  }
  if (broker.auth_code.empty() && backend != BackEnd::kDtp) {
    *msg = u8"fclib: 认证码填写错误";
    return false;
  }
  msg->clear();
  return true;
}

