  if (isnan(limit_price) && price_type == PriceType::kLimit) {
    *msg = u8"fclib: 报单限价填写错误";
    return false;
  }
  if (volume <= 0) {
    *msg = u8"fclib: 委托手数填写错误";
    return false;
  }
  if (volume_condition == OrderVolumeCondition::kInvalid) {
    *msg = u8"fclib: 成交量类型填写错误";
