TQ_EXPORT void DefineStruct(fclib::CommandSerializer* ss, fclib::future::ChangePassword& item) {
  DefineStruct(ss, static_cast<fclib::future::FutureCommand&>(item));
  ss->AddItem(item.password_type, "password_type");
  std::string cipher_old_passwd, cipher_new_passwd;
  if (ss->is_save) {
    fclib::AESEncrypt(&cipher_old_passwd, item.old_password, fclib::future::GetEncryptKey(item.user_key));
    fclib::AESEncrypt(&cipher_new_passwd, item.new_password, fclib::future::GetEncryptKey(item.user_key));
    ss->AddItem(cipher_old_passwd, "old_password");
    ss->AddItem(cipher_new_passwd, "new_password");
  } else {
    ss->AddItem(cipher_old_passwd, "old_password");
    ss->AddItem(cipher_new_passwd, "new_password");
    fclib::AESDecrypt(&item.old_password, cipher_old_passwd, fclib::future::GetEncryptKey(item.user_key));
    fclib::AESDecrypt(&item.new_password, cipher_new_passwd, fclib::future::GetEncryptKey(item.user_key));
  }
}

