/*******************************************************************************
 * @file node_release.cpp
 * @brief 节点释放机器人
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "node_release.h"
#include <memory>
namespace fclib {
NodeRelease::NodeRelease(
  std::shared_ptr<TqApiNodeDb> db, const NodeReleaseFunc& release_funcs, structlog::Logger& logger)
  : m_db(db)
  , m_release_funcs(release_funcs)
  , m_logger(logger.With("node_release", reinterpret_cast<int64_t>(this)).Clone()) {
  InitViews();
}

void NodeRelease::ReleaseNode() {
  for (const auto& k : m_finished_orders) {
    m_db->DeleteRecord<future::Order>(k);
  }
  for (const auto& k : m_finished_trades) {
    m_db->DeleteRecord<future::Trade>(k);
  }
  for (const auto& k : m_finished_quotes) {
    m_db->DeleteRecord<future::Quote>(k);
  }
  m_finished_orders.clear();
  m_finished_trades.clear();
  m_finished_quotes.clear();
}

void NodeRelease::InitViews() {
  if (m_release_funcs.order_release) {
    m_order_view = m_db->CreateView<future::Order>(ReuseViewKey::kOrder);
    m_order_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<future::OrderNode> node, bool) {
        if (m_release_funcs.order_release(node->Snap().get())) {
          m_finished_orders.insert(node->GetKey());
        }
      });
  }

  if (m_release_funcs.trade_release) {
    m_trade_view = m_db->CreateView<future::Trade>(ReuseViewKey::kTrade);
    m_trade_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<future::TradeNode> node, bool) {
        if (m_release_funcs.trade_release(node->Snap().get())) {
          m_finished_trades.insert(node->GetKey());
        }
      });
  }

  if (m_release_funcs.quote_release) {
    m_quote_view = m_db->CreateView<future::Quote>();
    m_quote_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<future::QuoteNode> node, bool) {
        if (m_release_funcs.quote_release(node->Snap().get())) {
          m_finished_quotes.insert(node->GetKey());
        }
      });
  }
}

}  // namespace fclib

