  /**
   * 跟踪一个指令, 在这个指令状态首次切换到 kFinished 时调用 notify_func 函数通知.
   */
  void TrackCommand(
    std::shared_ptr<UserCommand> command, std::function<void(std::shared_ptr<UserCommand>)> notify_func);

  /**
   * 取消某个指令的跟踪
   *
   * 在某些使用场景中，发出指令的对象会被释放，此时应该及时取消跟踪，不然会在回调函数处崩溃
   */
  void UntrackCommand(std::shared_ptr<UserCommand> command);
  /**
   * 遍历所有跟踪项, 发出通知.
   */
  void NotifyAll();

 private:
  std::map<std::shared_ptr<UserCommand>, std::function<void(std::shared_ptr<UserCommand>)>> m_track_items;
