/*******************************************************************************
 * @file query_planner.cpp
 * @brief 查询管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "query_planner.h"
#include <memory>
namespace fclib {

void QueryPlanner::SetQryRule(std::function<bool(void)> invalid_check_func,
  std::function<std::shared_ptr<UserCommand>()> query_func, bool run_once /*= false*/) {
  auto item = std::make_shared<Item>();
  item->invalid_check_func = invalid_check_func;
  item->query_func = query_func;
  item->run_once = run_once;
  m_items.push(item);
}

std::shared_ptr<UserCommand> QueryPlanner::GetQueryCommand() {
  for (size_t i = 0; i < m_items.size(); i++) {
    auto item = m_items.front();
    m_items.pop();
    if (item->invalid_check_func()) {
      if (!item->run_once) {
        m_items.push(item);
      }
      return item->query_func();
    } else {
      m_items.push(item);
    }
  }
  return nullptr;
}
}  // namespace fclib

﻿/*******************************************************************************
 * @file command_tracker.cpp
 * @brief 指令跟踪器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "command_tracker.h"
#include <memory>
namespace fclib {

void CommandTracker::TrackCommand(
  std::shared_ptr<UserCommand> command, std::function<void(std::shared_ptr<UserCommand>)> notify_func) {
  m_track_items[command] = notify_func;
}

void CommandTracker::UntrackCommand(std::shared_ptr<UserCommand> command) {
  m_track_items.erase(command);
}

void CommandTracker::NotifyAll() {
  for (auto it = m_track_items.begin(); it != m_track_items.end();) {
    auto command = it->first;
    auto notify_func = it->second;
    if (command->status == UserCommand::Status::kFinished) {
      notify_func(command);
      it = m_track_items.erase(it);
    } else {
      ++it;
    }
  }
}

}  // namespace fclib

/*******************************************************************************
 * @file timer_manager.cpp
 * @brief 定时器管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "timer_manager.h"
#include <memory>
#include <list>
namespace fclib {
TimerManager::TimerManager(boost::asio::io_context* ioc) : m_ioc(ioc), m_strand(*ioc) {}

void TimerManager::AddTimerTask(int milliseconds, std::function<void(void)> func) {
  m_strand.post([=]() {
    if (m_timer_map.find(milliseconds) != m_timer_map.end()) {
      m_func_map[milliseconds].push_back(func);
      return;
    }
    auto timer = std::make_shared<boost::asio::deadline_timer>(*m_ioc);
    m_timer_map[milliseconds] = timer;
    auto& func_list = m_func_map[milliseconds];
    func_list.push_back(func);
    OnTimer(milliseconds, timer, func_list);
  });
}

void TimerManager::OnTimer(int milliseconds, std::shared_ptr<boost::asio::deadline_timer> timer,
  std::list<std::function<void(void)>>& func_list) {
  for (const auto& func : func_list) {
    func();
  }
  timer->expires_from_now(boost::posix_time::milliseconds(milliseconds));
  timer->async_wait([milliseconds, timer, &func_list, this](const boost::system::error_code& error) {
    if (!error) {
      OnTimer(milliseconds, timer, func_list);
    }
  });
}

}  // namespace fclib

