   * @param run_once: 是否只查询一次.
   */
  void SetQryRule(std::function<bool(void)> invalid_check_func,
    std::function<std::shared_ptr<UserCommand>()> query_func, bool run_once = false);

  /**
   * 提取目前最需要执行的一条查询指令.
   *
   * @return: 目前最需要执行的查询指令. 如没有任何查询需要执行, 返回 nullptr.
   */
  std::shared_ptr<UserCommand> GetQueryCommand();

 private:
