/*******************************************************************************
 * @file aes.cpp
 * @brief aes 加解密
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/utils/aes.h"

#include <cryptopp/aes.h>
#include <cryptopp/modes.h>
#include <cryptopp/filters.h>

#include <string>

#include "fclib/utils/base64.h"

// https://cryptopp.com/wiki/Advanced_Encryption_Standard

namespace fclib {

bool AESEncrypt(std::string* cipherText, const std::string& plainText, const std::string& k) {
  cipherText->clear();
  if (plainText.empty())
    return true;
  std::string key = k;
  if (key.size() < CryptoPP::AES::DEFAULT_KEYLENGTH)
    key.append(CryptoPP::AES::DEFAULT_KEYLENGTH - key.size(), 'F');
  try {
    CryptoPP::SecByteBlock aesKey(
      reinterpret_cast<const CryptoPP::byte*>(key.data()), CryptoPP::AES::DEFAULT_KEYLENGTH);
    CryptoPP::CBC_Mode<CryptoPP::AES>::Encryption cbcEncryption;
    cbcEncryption.SetKeyWithIV(aesKey, CryptoPP::AES::DEFAULT_KEYLENGTH, aesKey);

    CryptoPP::StringSource s(
      plainText, true, new CryptoPP::StreamTransformationFilter(cbcEncryption, new CryptoPP::StringSink(*cipherText)));

    *cipherText = base64url_encode(cipherText->c_str(), cipherText->size());
    return true;
  } catch (...) {
    return false;
  }
}

bool AESDecrypt(std::string* decryptedText, const std::string& cipherText, const std::string& k) {
  decryptedText->clear();
  if (cipherText.empty())
    return true;
  std::string key = k;
  if (key.size() < CryptoPP::AES::DEFAULT_KEYLENGTH)
    key.append(CryptoPP::AES::DEFAULT_KEYLENGTH - key.size(), 'F');
  try {
    std::string cipher = base64url_decode(cipherText);

    CryptoPP::SecByteBlock aesKey(
      reinterpret_cast<const CryptoPP::byte*>(key.data()), CryptoPP::AES::DEFAULT_KEYLENGTH);
    CryptoPP::CBC_Mode<CryptoPP::AES>::Decryption cbcDecryption;
    cbcDecryption.SetKeyWithIV(aesKey, CryptoPP::AES::DEFAULT_KEYLENGTH, aesKey);

    CryptoPP::StringSource s(
      cipher, true, new CryptoPP::StreamTransformationFilter(cbcDecryption, new CryptoPP::StringSink(*decryptedText)));

    return true;
  } catch (...) {
    return false;
  }
}
}  // namespace fclib

﻿/*******************************************************************************
 * @file numset.cpp
 * @brief 数值工具函数
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/utils/numset.h"

#include <float.h>
