#include <cmath>
#include <string>
#include <cstdlib>
#include <limits>

bool IsZero(double x) {
  return (x > -DBL_EPSILON && x < DBL_EPSILON);
}

bool IsZero(int32_t x) {
  return x == 0;
}

bool IsZero(int64_t x) {
  return (x == static_cast<int64_t>(0));
}

bool IsValid(double x) {
  return (!std::isnan(x)) && (x < 1e20) && (x > -1e20);
}

bool IsValid(int32_t x) {
  return x != (std::numeric_limits<int32_t>::max)();
}

bool IsValid(int64_t x) {
  return x != (std::numeric_limits<int64_t>::max)();
}

void SetInvalid(double* x) {
  *x = NAN;
}

void SetInvalid(int32_t* x) {
  *x = (std::numeric_limits<int32_t>::max)();
}

void SetInvalid(int64_t* x) {
  *x = (std::numeric_limits<int64_t>::max)();
}

bool EqualDouble(double a, double b, int sigDigs) {
  double absa = std::fabs(a);
  double absb = std::fabs(b);
  double diff = std::fabs(a - b);
  double epsilon = std::pow(0.1, sigDigs);

  // shortcut, handles infinities
  if (a == b)
    return true;
  // a or b or both are zero
  // relative error is not meaningful here
  else if (a * b == 0)
    return diff < (epsilon * epsilon);
  // use relative error
  else
    return diff / (absa + absb) < epsilon;
}

int32_t RoundLeft(int32_t n, int32_t m) {
  int32_t x;
  if (n % m == 0)
    x = n;
  else if (n >= 0)
    x = n - n % m;
  else
    x = n - m - (n % m);
  return x;
}

int32_t RoundRight(int32_t n, int32_t m) {
  int32_t x;
  if (n % m == 0)
    x = n;
  else if (n >= 0)
    x = n + m - n % m;
  else
    x = n - n % m;
  return x;
}

int PriceTickToDecimal(double price_tick) {
  if (price_tick >= 1.0)
    return 0;
  else if (price_tick >= 0.1)
    return 1;
  else if (price_tick >= 0.01)
    return 2;
  else
    return 3;
}

double StrToNumber(const std::string& s) {
  char* end = nullptr;
  double val = strtod(s.c_str(), &end);
  if (end != s.c_str() && *end == '\0' && val != HUGE_VAL)
    return val;
  return NAN;
}

