namespace fclib {

bool ParseUrl(const std::string& url, std::string* scheme, std::string* host, std::string* port, std::string* path) {
  UriUriA uri;
  const char* errorPos;
  if (uriParseSingleUriA(&uri, url.c_str(), &errorPos) != URI_SUCCESS)
    return false;
  *scheme = std::string(uri.scheme.first, uri.scheme.afterLast - uri.scheme.first);
  *host = std::string(uri.hostText.first, uri.hostText.afterLast - uri.hostText.first);
  *port = std::string(uri.portText.first, uri.portText.afterLast - uri.portText.first);
  if (*port == "") {
    if (*scheme == "http" || *scheme == "ws")
      *port = "80";
    if (*scheme == "https" || *scheme == "wss")
      *port = "443";
  }
  if (!uri.pathHead || !uri.pathTail) {
    *path = "/";
  } else {
    *path = "/" + std::string(uri.pathHead->text.first, uri.pathTail->text.afterLast - uri.pathHead->text.first);
    if (*path == "")
      *path = "/";
  }
  uriFreeUriMembersA(&uri);
  return true;
}

