#ifdef _WIN32
#include <windows.h>
#include <dbghelp.h>
#pragma comment(lib, "dbghelp.lib")
#endif

namespace fclib {

int DumpHelper::InitDumpHelper(const std::string& path) {
  try {
    if (!std::filesystem::exists(std::filesystem::u8path(path)))
      return -1;
    s_dump_file_path = path + "/dump/";
    if (std::filesystem::exists(std::filesystem::u8path(s_dump_file_path)))
      return 0;
    if (!std::filesystem::create_directory(std::filesystem::u8path(s_dump_file_path))) {
      s_dump_file_path = "";
      return -2;
    }
    return 0;
  } catch (...) {
    s_dump_file_path = "";
    return -3;
  }
}

#ifdef _WIN32

int DumpHelper::CreateMinidump(const std::string& dumpfile_name) {
  if (s_dump_file_path.empty())
    return -1;
  try {
    auto full_path = std::filesystem::u8path(s_dump_file_path + dumpfile_name);
    HANDLE hFile = CreateFileW(full_path.wstring().c_str(), GENERIC_READ | GENERIC_WRITE, 0, nullptr,
      CREATE_NEW, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (hFile == nullptr || hFile == INVALID_HANDLE_VALUE)
      return -2;

    CONTEXT context;
    RtlCaptureContext(&context);

    EXCEPTION_POINTERS exceptionPointers;
    EXCEPTION_RECORD exceptionRecord;
    exceptionRecord.ExceptionCode = EXCEPTION_BREAKPOINT;
    exceptionRecord.ExceptionFlags = 0;
    exceptionRecord.ExceptionRecord = nullptr;
#ifdef _M_X64
    exceptionRecord.ExceptionAddress = (PVOID)context.Rip;
#elif _M_IX86
    exceptionRecord.ExceptionAddress = (PVOID)context.Eip;
#else
#error Unsupported platform
#endif
    exceptionRecord.NumberParameters = 0;
    exceptionPointers.ExceptionRecord = &exceptionRecord;
    exceptionPointers.ContextRecord = &context;

    MINIDUMP_EXCEPTION_INFORMATION mdei;
    mdei.ThreadId = GetCurrentThreadId();
    mdei.ExceptionPointers = &exceptionPointers;
    mdei.ClientPointers = FALSE;

    MINIDUMP_TYPE dumpType =
      static_cast<MINIDUMP_TYPE>(MiniDumpWithIndirectlyReferencedMemory | MiniDumpScanMemory | MiniDumpWithThreadInfo);
    auto ret = MiniDumpWriteDump(GetCurrentProcess(), GetCurrentProcessId(), hFile, dumpType, &mdei, nullptr, nullptr);
    CloseHandle(hFile);
    return ret ? 0 : -2;
  } catch (...) {
    return -3;
  }
}

#else

int DumpHelper::CreateMinidump(const std::string& dumpfile_name) {
  return -3;
}
