/*******************************************************************************
 * @file base64.cpp
 * @brief base64编码转换
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/

#include "fclib/utils/base64.h"
#include <cstring>
#include <string>

namespace fclib {
// RFC 4648 §5 Base 64 Encoding with URL and Filename Safe Alphabet
std::string base64url_encode(const void* data, const size_t& len) {
  static const char* B64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  std::string result((len + 2) / 3 * 4, '=');
  unsigned char* p = (unsigned char*)data;
  char* str = &result[0];
  size_t j = 0, pad = len % 3;
  const size_t last = len - pad;

  for (size_t i = 0; i < last; i += 3) {
    int n = static_cast<int>(p[i]) << 16 | static_cast<int>(p[i + 1]) << 8 | p[i + 2];
    str[j++] = B64chars[n >> 18];
    str[j++] = B64chars[n >> 12 & 0x3F];
    str[j++] = B64chars[n >> 6 & 0x3F];
    str[j++] = B64chars[n & 0x3F];
  }

  if (pad) {
    int n = --pad ? static_cast<int>(p[last]) << 8 | p[last + 1] : p[last];
    str[j++] = B64chars[pad ? n >> 10 & 0x3F : n >> 2];
    str[j++] = B64chars[pad ? n >> 4 & 0x03F : n << 4 & 0x3F];
    str[j++] = pad ? B64chars[n << 2 & 0x3F] : '=';
  }
  return result;
}

static unsigned char from_b64(unsigned char ch) {
  static const unsigned char s_tab[128] = {
    255, 255, 255, 255, 255, 255, 255, 255, /*  0 */
    255, 255, 255, 255, 255, 255, 255, 255, /*  8 */
    255, 255, 255, 255, 255, 255, 255, 255, /*  16 */
    255, 255, 255, 255, 255, 255, 255, 255, /*  24 */
    255, 255, 255, 255, 255, 255, 255, 255, /*  32 */
    255, 255, 255, 255, 255, 62, 255, 255,  /*  40 */
    52, 53, 54, 55, 56, 57, 58, 59,         /*  48 */
    60, 61, 255, 255, 255, 255, 255, 255,   /*  56  */
    255, 0, 1, 2, 3, 4, 5, 6,               /*  64 */
    7, 8, 9, 10, 11, 12, 13, 14,            /*  72 */
    15, 16, 17, 18, 19, 20, 21, 22,         /*  80 */
    23, 24, 25, 255, 255, 255, 255, 63,     /*  88 */
    255, 26, 27, 28, 29, 30, 31, 32,        /*  96 */
    33, 34, 35, 36, 37, 38, 39, 40,         /*  104 */
    41, 42, 43, 44, 45, 46, 47, 48,         /*  112 */
    49, 50, 51, 255, 255, 255, 255, 255,    /*  120 */
  };
  return s_tab[ch & 127];
}

std::string base64url_decode(const std::string& value) {
  std::string tmp_out;
  unsigned char a, b, c, d;
  size_t input_len = value.size();
  div_t res = div(static_cast<int>(input_len), 4);
  size_t output_len = res.quot * 3;
  if (res.rem != 0) {
    output_len += res.rem - 1;
  }

  tmp_out.reserve(output_len);
  for (size_t i = 0; i < input_len;) {
    a = from_b64(value[i]);
    if (i + 1 >= input_len)
      break;
    b = from_b64(value[i + 1]);
    tmp_out += a << 2 | b >> 4;
    if (i + 2 >= input_len)
      break;
    c = from_b64(value[i + 2]);
    tmp_out += b << 4 | c >> 2;
    if (i + 3 >= input_len)
      break;
    d = from_b64(value[i + 3]);
    tmp_out += c << 6 | d;
    i += 4;
  }

  if (value[input_len - 1] == '=') {
    output_len--;
    if (value[input_len - 2] == '=')
      output_len--;
  }

  const char* pData = tmp_out.data();
  std::string result;
  result.clear();
  result.append(pData, pData + output_len);
  return result;
}

static const char base64_chars[] =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
  "abcdefghijklmnopqrstuvwxyz"
  "0123456789+/";

// #pragma clang diagnostic push
// #pragma clang diagnostic ignored "-Wunused-function"
// static inline bool is_base64(unsigned char c) {
//   return (isalnum(c) || (c == '+') || (c == '/'));
// }
// #pragma clang diagnostic pop

std::string Base64_Encode(unsigned char const* buf, unsigned int bufLen) {
  std::string ret;
  int i = 0;
  int j = 0;
  unsigned char char_array_3[3];
  unsigned char char_array_4[4];

  while (bufLen--) {
    char_array_3[i++] = *(buf++);
    if (i == 3) {
      char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
      char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
      char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
      char_array_4[3] = char_array_3[2] & 0x3f;

      for (i = 0; (i < 4); i++)
        ret += base64_chars[char_array_4[i]];
      i = 0;
    }
  }

  if (i) {
    for (j = i; j < 3; j++)
      char_array_3[j] = '\0';

    char_array_4[0] = (char_array_3[0] & 0xfc) >> 2;
    char_array_4[1] = ((char_array_3[0] & 0x03) << 4) + ((char_array_3[1] & 0xf0) >> 4);
    char_array_4[2] = ((char_array_3[1] & 0x0f) << 2) + ((char_array_3[2] & 0xc0) >> 6);
    char_array_4[3] = char_array_3[2] & 0x3f;

    for (j = 0; (j < i + 1); j++)
      ret += base64_chars[char_array_4[j]];

    while ((i++ < 3))
      ret += '=';
  }

  return ret;
}

void Base64_Decode(const std::string& strIn, std::string& strOut, bool fCheckInputValid) {
  static char decode_map[256] = "\0";
  static bool decodemapinit = false;
  if (!decodemapinit) {
    memset(decode_map, -1, sizeof(decode_map));
    for (int i = 'A'; i <= 'Z'; ++i)
      decode_map[i] = 0 + (i - 'A');
    for (int i = 'a'; i <= 'z'; ++i)
      decode_map[i] = 26 + (i - 'a');
    for (int i = '0'; i <= '9'; ++i)
      decode_map[i] = 52 + (i - '0');
    decode_map[(unsigned char)'+'] = 62;
    decode_map[(unsigned char)'/'] = 63;
    decode_map[(unsigned char)'='] = 0;
    decodemapinit = true;
  }

  size_t nInlen = strIn.length();
  if (fCheckInputValid) {
    for (size_t i = 0; i < nInlen; ++i) {
      if (decode_map[(unsigned char)strIn[i]] == -1)
        return;
    }
  }

  div_t res = div(static_cast<int>(nInlen), 4);  // 某些编码字符串省略了末尾的"="
  if (res.rem == 1)
    return;  // rem只能为0, 2或3
  size_t nOutLen = res.quot * 3;
  if (res.rem != 0) {
    nOutLen += res.rem - 1;
  }
  std::string strTmpOut;
  strTmpOut.resize(nOutLen);
  int i = 0;
  for (; i < res.quot; ++i) {
    strTmpOut[i * 3] = ((decode_map[static_cast<unsigned char>(strIn[i * 4])] << 2) & 0xFC)
      | ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 1])] >> 4) & 0x03);
    strTmpOut[i * 3 + 1] = ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 1])] << 4) & 0xF0)
      | ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 2])] >> 2) & 0x0F);
    strTmpOut[i * 3 + 2] = ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 2])] << 6) & 0xC0)
      | (decode_map[static_cast<unsigned char>(strIn[i * 4 + 3])] & 0x3F);
  }
  if (res.rem == 2) {
    strTmpOut[i * 3] = ((decode_map[static_cast<unsigned char>(strIn[i * 4])] << 2) & 0xFC)
      | ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 1])] >> 4) & 0x03);
  } else if (res.rem == 3) {
    strTmpOut[i * 3] = ((decode_map[static_cast<unsigned char>(strIn[i * 4])] << 2) & 0xFC)
      | ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 1])] >> 4) & 0x03);
    strTmpOut[i * 3 + 1] = ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 1])] << 4) & 0xF0)
      | ((decode_map[static_cast<unsigned char>(strIn[i * 4 + 2])] >> 2) & 0x0F);
  }

  if (strIn[nInlen - 1] == '=') {
    nOutLen--;
    if (strIn[nInlen - 2] == '=')
      nOutLen--;
  }
  const char* pData = strTmpOut.data();
  strOut.clear();
  strOut.append(pData, pData + nOutLen);
}

}  // namespace fclib

/*******************************************************************************
 * @file encoding.cpp
 * @brief 字符编码转换
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/utils/encoding.h"
#include <vector>

#ifdef __linux__
#include <iconv.h>

#include <cstring>
#elif _WIN32
#include <winsock2.h>
#include <windows.h>

#include <codecvt>
#include <locale>
#include <string>
#endif

namespace fclib {
#ifdef __linux__
static std::string ConvertCharset(const std::string& input, const char* to_charset, const char* from_charset) {
  iconv_t cd = iconv_open(to_charset, from_charset);
  if (cd == (iconv_t)-1)
    return {};
  size_t in_left = input.size();
  const char* pin = input.data();

  size_t out_buffer_size = in_left * 4;
  std::vector<char> out_buffer(out_buffer_size);
  char* pout_base = out_buffer.data();

  size_t out_left = out_buffer.size();
  char* pout = pout_base;

  while (in_left > 0) {
    size_t result = iconv(cd, const_cast<char**>(&pin), &in_left, &pout, &out_left);
    if (result == static_cast<size_t>(-1)) {
      if (errno == E2BIG) {
        // 输出缓冲区不足，扩容
        size_t used = pout - pout_base;
        out_buffer_size *= 2;
        out_buffer.resize(out_buffer_size);
        pout_base = out_buffer.data();
        pout = pout_base + used;
        out_left = out_buffer_size - used;
      } else {
        // EILSEQ: 无效字符，EINVAL: 不完整字符序列
        iconv_close(cd);
        return {};
      }
    }
  }
  iconv_close(cd);
  return std::string(out_buffer.data(), pout - out_buffer.data());
}

std::string GbkToUtf8(const std::string& gbk_string) {
  return ConvertCharset(gbk_string, "UTF-8", "GBK");
}

std::string LocalToUtf8(const std::string& local_string) {
  return local_string;
}

std::string Utf8ToGbk(const std::string& utf8_string) {
  return ConvertCharset(utf8_string, "GBK", "UTF-8");
}

void Utf8ToGbk(char* char_array, int buf_len) {}

#elif _WIN32
void WStringToString(const std::wstring& unicode_string, UINT code_page, std::string* target_string) {
  if (!target_string)
    return;

  int required_size = ::WideCharToMultiByte(code_page, 0, unicode_string.c_str(), -1, nullptr, 0, nullptr, nullptr);
  if (required_size <= 0) {
    target_string->clear();
    return;
  }

  std::vector<char> buffer(required_size);
  ::WideCharToMultiByte(code_page, 0, unicode_string.c_str(), -1, buffer.data(), required_size, nullptr, nullptr);
  target_string->assign(buffer.data(), required_size - 1);  // 去掉 null 结尾
}

void StringToWString(const std::string& origin_string, UINT code_page, std::wstring* target_wstring) {
  if (!target_wstring)
    return;

  int required_size = ::MultiByteToWideChar(code_page, 0, origin_string.c_str(), -1, nullptr, 0);
  if (required_size <= 0) {
    target_wstring->clear();
    return;
  }

  std::vector<wchar_t> buffer(required_size);
  ::MultiByteToWideChar(code_page, 0, origin_string.c_str(), -1, buffer.data(), required_size);
  target_wstring->assign(buffer.data(), required_size - 1);  // 去掉 null 结尾
}

void Utf8ToGbk(char* char_array, int buf_len) {
  if (!char_array || buf_len <= 0) {
    return; // 输入参数无效
  }

  // 计算转换所需的宽字符缓冲区大小
  int wide_char_size = ::MultiByteToWideChar(CP_UTF8, 0, char_array, -1, nullptr, 0);
  if (wide_char_size <= 0) {
    return; // 转换失败
  }

  std::vector<wchar_t> buffer(wide_char_size);
  if (::MultiByteToWideChar(CP_UTF8, 0, char_array, -1, buffer.data(), wide_char_size) == 0) {
    return; // 转换失败
  }

  // 计算转换所需的 GBK 缓冲区大小
  int gbk_size = ::WideCharToMultiByte(936, 0, buffer.data(), -1, nullptr, 0, nullptr, nullptr);
  if (gbk_size <= 0) {
    return; // 转换失败
  }

  // 如果缓冲区不足，截断输出并保留最后一个字符为 \0
  if (gbk_size >= buf_len) {
    gbk_size = buf_len - 1;
  }

  if (::WideCharToMultiByte(936, 0, buffer.data(), -1, char_array, gbk_size, nullptr, nullptr) == 0) {
    return; // 转换失败
  }

  // 确保字符串以 \0 结尾
  char_array[gbk_size] = '\0';
}

std::string GbkToUtf8(const std::string& gbk_string) {
  std::wstring unicode_wstring;
  std::string utf8_string;
  StringToWString(gbk_string, 936, &unicode_wstring);
  WStringToString(unicode_wstring, CP_UTF8, &utf8_string);
  return utf8_string;
}

std::string Utf8ToGbk(const std::string& utf8_string) {
  std::wstring unicode_wstring;
  std::string gbk_string;
  StringToWString(utf8_string, CP_UTF8, &unicode_wstring);
  WStringToString(unicode_wstring, 936, &gbk_string);
  return gbk_string;
}

std::string LocalToUtf8(const std::string& local_string) {
  std::wstring unicode_wstring;
  std::string utf8_string;
  StringToWString(local_string, CP_ACP, &unicode_wstring);
  WStringToString(unicode_wstring, CP_UTF8, &utf8_string);
  return utf8_string;
}

std::string Utf8ToLocal(const std::string& utf8_string) {
  std::wstring unicode_wstring;
  std::string local_string;
  StringToWString(utf8_string, CP_UTF8, &unicode_wstring);
  WStringToString(unicode_wstring, CP_ACP, &local_string);
  return local_string;
}

#endif
