namespace fclib {

WebsocketServerImpl::WebsocketServerImpl(boost::asio::io_context* ioc, structlog::Logger& parent_logger)
  : m_ioc(ioc)
  , m_acceptor(*ioc)
  , m_logger(parent_logger.With("WebsocketServer", reinterpret_cast<int64_t>(this)).Clone()) {}

WebsocketServerImpl::~WebsocketServerImpl() {}

std::shared_ptr<WebsocketServer> WebsocketServerImpl::OnSessionBegin(
  std::function<void(std::weak_ptr<WebsocketSession>)> cb) {
  m_session_begin_callback = cb;
  return shared_from_this();
}

std::shared_ptr<WebsocketServer> WebsocketServerImpl::OnSessionEnd(
  std::function<void(std::weak_ptr<WebsocketSession>)> cb) {
  m_session_end_callback = cb;
  return shared_from_this();
}

std::shared_ptr<WebsocketServer> WebsocketServerImpl::OnSessionReceivedMessage(
  std::function<void(std::weak_ptr<WebsocketSession>, const std::string&)> cb) {
  m_session_recv_callback = cb;
  return shared_from_this();
}

std::set<std::weak_ptr<WebsocketSession>, std::owner_less<std::weak_ptr<WebsocketSession>>>
WebsocketServerImpl::GetSessionSet() {
  std::set<std::weak_ptr<WebsocketSession>, std::owner_less<std::weak_ptr<WebsocketSession>>> ret;
  for (const auto& session : m_session_set) {
    ret.insert(session);
  }
  return ret;
}

std::string WebsocketServerImpl::GetListenAddress() {
  return m_listen_address;
}

void WebsocketServerImpl::RemoveSession(std::shared_ptr<WebsocketSession> session) {
  m_session_set.erase(session);
}

void WebsocketServerImpl::Listen(const std::string& socket_file_path) {
  // 判断文件路径是否符合要求
  if (socket_file_path.empty()) {
    m_logger.Error("socket file path is empty");
    return;
  }

  // 创建 ec 和 endpoint
  boost::beast::error_code ec;
  // 删除已存在的 unix socket 文件，判断是否删除异常

  std::filesystem::remove(socket_file_path, ec);
  if (ec) {
    m_logger.With("ec_value", ec.value())
      .With("ec_message", LocalToUtf8(ec.message()))
      .Warning("remove unix socket file fail");
  }

  try {
    boost::asio::local::stream_protocol::endpoint ep(socket_file_path);
    m_unix_domain_socket_acceptor = std::make_shared<boost::asio::local::stream_protocol::acceptor>(*m_ioc, ep, false);
  } catch (const std::exception& e) {
    m_logger.With("error", e.what()).Error("create unix domain socket acceptor fail");
    return;
  }

  DoUnixDomainSocketAccept();
}

void WebsocketServerImpl::DoUnixDomainSocketAccept() {
  m_unix_domain_socket_acceptor->async_accept(boost::beast::net::make_strand(*m_ioc),
    boost::beast::bind_front_handler(&WebsocketServerImpl::OnUnixDomainSocketAccept, shared_from_this()));
}

void WebsocketServerImpl::OnUnixDomainSocketAccept(
  boost::beast::error_code ec, boost::asio::local::stream_protocol::socket socket) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("accept fail");
    return;
  }
  // Create the session and run it
  try {
    auto session = std::make_shared<WebsocketServerSessionImpl>(m_ioc, std::move(socket), m_session_begin_callback,
      m_session_end_callback, m_session_recv_callback, m_logger, shared_from_this());
    m_session_set.insert(session);
    session->AcceptHandshake();
  } catch (const std::exception& e) {
    m_logger.With("error", e.what()).Error("Failed to create session");
  }
  DoUnixDomainSocketAccept();
}

void WebsocketServerImpl::Listen(const std::string& ip, const std::string& port) {
  // 创建 ec 和 endpoint
  boost::beast::error_code ec;
  auto ip_address = boost::asio::ip::address::from_string(ip, ec);
  if (ec) {
    m_logger.With("ec_value", ec.value())
      .With("ec_message", LocalToUtf8(ec.message()))
      .Warning("prase ip address fail");
    return;
  }
  auto port_num = std::atoi(port.c_str());
  boost::asio::ip::tcp::endpoint endpoint(ip_address, port_num);
  // Open the acceptor
  m_acceptor.open(endpoint.protocol(), ec);
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("accept open fail");
    return;
  }
  // Allow address reuse
  m_acceptor.set_option(boost::beast::net::socket_base::reuse_address(true), ec);
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("set option fail");
    return;
  }
  // Bind to the server address
  m_acceptor.bind(endpoint, ec);
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("bind fail");
    return;
  }
  // Start listening for connections
  m_acceptor.listen(boost::beast::net::socket_base::max_listen_connections, ec);
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("listen fail");
    return;
  }

  auto local_endpoint = m_acceptor.local_endpoint();
  m_listen_address =
    local_endpoint.address().to_string() + ":" + std::to_string(static_cast<unsigned int>(local_endpoint.port()));

  DoAccept();
}

void WebsocketServerImpl::DoAccept() {
  // The new connection gets its own strand
  m_acceptor.async_accept(boost::beast::net::make_strand(*m_ioc),
    boost::beast::bind_front_handler(&WebsocketServerImpl::OnAccept, shared_from_this()));
}

void WebsocketServerImpl::OnAccept(boost::beast::error_code ec, boost::asio::ip::tcp::socket socket) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("accept fail");
    return;
  }
  // Create the session and run it
  auto session = std::make_shared<WebsocketServerSessionImpl>(m_ioc, std::move(socket), m_session_begin_callback,
    m_session_end_callback, m_session_recv_callback, m_logger, shared_from_this());
  m_session_set.insert(session);
  session->AcceptHandshake();

  DoAccept();
}

