namespace fclib {

WebsocketSessionImpl::WebsocketSessionImpl(boost::asio::io_context* ioc,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_begin_callback,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_end_callback,
  std::function<void(std::weak_ptr<WebsocketSession>, const std::string&)> session_recv_callback,
  structlog::Logger& parent_logger)
  : m_ioc(ioc)
  , m_session_begin_callback(session_begin_callback)
  , m_session_end_callback(session_end_callback)
  , m_session_recv_callback(session_recv_callback)
  , m_session_status(WebsocketSession::Status::kDisconnected)
  , m_logger(parent_logger.With("WebsocketSession", reinterpret_cast<int64_t>(this)).Clone()) {}

WebsocketSessionImpl::~WebsocketSessionImpl() {
  m_logger.With("~WebsocketSession", reinterpret_cast<int64_t>(this)).Info("session destruct");
}

WebsocketSession::Status WebsocketSessionImpl::GetSessionStatus() {
  return m_session_status;
}

// 定义通用session
void WebsocketSessionImpl::SendTextMsg(const std::string& json_str) {
  if (m_session_status != WebsocketSession::Status::kConnected)
    return;
  m_logger.With("len", static_cast<int>(json_str.size()))
    .With("content", structlog::make_json(json_str))
    .Debug("send message");
  m_output_buffer_list.push_back(json_str);
  if (m_output_buffer_list.size() == 1)
    DoWrite();
}

std::map<std::string, std::string> WebsocketSessionImpl::GetHeaders() {
  return m_headers;
}

void WebsocketSessionImpl::DoRead() {
  if (m_use_local_socket) {
    m_websocket_stream_local->async_read(
      m_input_buffer, boost::beast::bind_front_handler(&WebsocketSessionImpl::OnRead, shared_from_this()));
  } else {
    m_websocket_stream->async_read(
      m_input_buffer, boost::beast::bind_front_handler(&WebsocketSessionImpl::OnRead, shared_from_this()));
  }
}

void WebsocketSessionImpl::DoWrite() {
  auto buf = boost::asio::buffer(m_output_buffer_list.front());
  if (m_use_local_socket) {
    m_websocket_stream_local->text(true);
    m_websocket_stream_local->async_write(
      buf, boost::beast::bind_front_handler(&WebsocketSessionImpl::OnWrite, shared_from_this()));
  } else {
    m_websocket_stream->text(true);
    m_websocket_stream->async_write(
      buf, boost::beast::bind_front_handler(&WebsocketSessionImpl::OnWrite, shared_from_this()));
  }
}

void WebsocketSessionImpl::OnWrite(boost::beast::error_code ec, std::size_t bytes_transferred) {
  boost::ignore_unused(bytes_transferred);
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("write fail");
    return;
  }
  if (!m_output_buffer_list.empty())
    m_output_buffer_list.pop_front();
  if (!m_output_buffer_list.empty())
    DoWrite();
}

WebsocketClientSessionImpl::WebsocketClientSessionImpl(boost::asio::io_context* ioc,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_begin_callback,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_end_callback,
  std::function<void(std::weak_ptr<WebsocketSession>, const std::string&)> session_recv_callback,
  structlog::Logger& parent_logger, const std::map<std::string, std::string>& headers)
  : WebsocketSessionImpl(ioc, session_begin_callback, session_end_callback, session_recv_callback, parent_logger)
  , m_headers(headers)
  , m_tcp_socket(*ioc)
  , m_local_socket(*ioc) {
  m_ping_timer = std::make_shared<boost::asio::deadline_timer>(*m_ioc);
}

WebsocketClientSessionImpl::~WebsocketClientSessionImpl() {
  if (m_reconnect_timer) {
    m_reconnect_timer->cancel();
  }
}

// 定义客户端session
void WebsocketClientSessionImpl::Handshake(
  const std::string& host, const std::string& path, std::map<std::string, std::string> headers) {
  if (m_use_local_socket) {
    m_websocket_stream_local->read_message_max(0);
    m_websocket_stream_local->set_option(
      boost::beast::websocket::stream_base::decorator([&headers](boost::beast::websocket::request_type& m) {
        for (auto& [k, v] : headers) {
          m.insert(k, v);
        }
      }));
    m_websocket_stream_local->async_handshake(host, path,
      boost::beast::bind_front_handler(&WebsocketClientSessionImpl::OnHandshake,
        std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
  } else {
    m_websocket_stream->read_message_max(0);
    m_websocket_stream->set_option(
      boost::beast::websocket::stream_base::decorator([&headers](boost::beast::websocket::request_type& m) {
        for (auto& [k, v] : headers) {
          m.insert(k, v);
        }
      }));
    m_websocket_stream->async_handshake(host, path,
      boost::beast::bind_front_handler(&WebsocketClientSessionImpl::OnHandshake,
        std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
  }
}

void WebsocketClientSessionImpl::OnHandshake(boost::beast::error_code ec) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("handshake fail");
    // 重新连接
    Reconnect();
    m_session_status = WebsocketSession::Status::kDisconnected;
    return;
  }
  m_logger.Info("got connection");
  m_session_status = WebsocketSession::Status::kConnected;
  m_output_buffer_list.clear();
  if (m_session_begin_callback)
    m_session_begin_callback(shared_from_this());
  OnPingTimer();
  DoRead();
}

void WebsocketClientSessionImpl::OnPingTimer() {
  if (m_use_local_socket) {
    m_websocket_stream_local->async_ping(boost::beast::websocket::ping_data(),
      boost::beast::bind_front_handler(
        &WebsocketClientSessionImpl::OnPing, std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
  } else {
    m_websocket_stream->async_ping(boost::beast::websocket::ping_data(),
      boost::beast::bind_front_handler(
        &WebsocketClientSessionImpl::OnPing, std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
  }
  m_ping_timer->expires_from_now(boost::posix_time::seconds(5));
  m_ping_timer->async_wait([this](const boost::system::error_code& error) {
    if (!error) {
      OnPingTimer();
    }
  });
}

void WebsocketClientSessionImpl::OnPing(boost::beast::error_code ec) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("ping fail");
  }
}

void WebsocketClientSessionImpl::OnRead(boost::beast::error_code ec, std::size_t bytes_transferred) {
  boost::ignore_unused(bytes_transferred);
  if (ec) {
    std::string err_msg = LocalToUtf8(ec.message());
    m_logger.With("ec_value", ec.value()).With("ec_message", err_msg).Warning("read fail");
    if (m_ping_timer) {
      m_ping_timer->cancel();
    }
    // 重新连接
    Reconnect();
    if (m_session_status == WebsocketSession::Status::kConnected) {
      m_session_status = WebsocketSession::Status::kDisconnected;
      if (m_session_end_callback)
        m_session_end_callback(shared_from_this());
    }
    return;
  }
  auto msg = boost::beast::buffers_to_string(m_input_buffer.data());
  m_logger.With("len", static_cast<int>(msg.size()))
    .With("content", structlog::make_json(msg))
    .Debug("received message");
  if (m_session_recv_callback)
    m_session_recv_callback(shared_from_this(), msg);
  m_input_buffer.consume(m_input_buffer.size());
  DoRead();
}

void WebsocketClientSessionImpl::Reconnect() {
  m_reconnect_timer = std::make_shared<boost::asio::deadline_timer>(*m_ioc, boost::posix_time::seconds(10));
  auto s_ptr = shared_from_this();
  m_reconnect_timer->async_wait([s_ptr](const boost::system::error_code& ec) {
    if (!ec) {
      auto self = std::static_pointer_cast<WebsocketClientSessionImpl>(s_ptr);
      if (self->m_use_local_socket) {
        self->DoLocalConnect();
      } else {
        self->DoResolve();
      }
    }
  });
}

void WebsocketClientSessionImpl::DoResolve() {
  m_resolver->async_resolve(m_host, m_port,
    boost::beast::bind_front_handler(&WebsocketClientSessionImpl::OnResolve,
      std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
}

void WebsocketClientSessionImpl::OnResolve(
  boost::system::error_code ec, boost::asio::ip::tcp::resolver::results_type results) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("resolve fail");
    // 重新连接
    Reconnect();
    return;
  }
  m_tcp_socket = boost::asio::ip::tcp::socket(*m_ioc);
  boost::asio::async_connect(m_tcp_socket, results.begin(), results.end(),
    std::bind(&WebsocketClientSessionImpl::OnTcpConnect,
      std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this()), std::placeholders::_1));
}

void WebsocketClientSessionImpl::OnTcpConnect(boost::system::error_code ec) {
  if (ec) {
    m_logger.With("ec_value", ec.value()).With("ec_message", LocalToUtf8(ec.message())).Warning("connect fail");
    // 重新连接
    Reconnect();
    m_tcp_socket.shutdown(boost::asio::ip::tcp::socket::shutdown_both, ec);
    m_tcp_socket.close(ec);
    return;
  }
  m_websocket_stream =
    std::make_shared<boost::beast::websocket::stream<boost::asio::ip::tcp::socket>>(std::move(m_tcp_socket));
  boost::beast::websocket::permessage_deflate pmd;
  pmd.client_enable = true;
  pmd.server_enable = true;
  m_websocket_stream->set_option(pmd);
  Handshake(m_host, m_path, m_headers);
}

void WebsocketClientSessionImpl::OnLocalConnect(boost::system::error_code ec) {
  if (ec) {
    m_logger.With("ec_value", ec.value())
      .With("ec_message", LocalToUtf8(ec.message()))
      .Warning("local socket connect fail");
    // 重新连接
    Reconnect();
    return;
  }
  // 成功连接后，创建 WebSocket 流
  m_websocket_stream_local =
    std::make_shared<boost::beast::websocket::stream<boost::asio::local::stream_protocol::socket>>(
      std::move(m_local_socket));
  // 执行 WebSocket 握手
  Handshake("localhost", "/", m_headers);
}

void WebsocketClientSessionImpl::DoLocalConnect() {
  boost::asio::local::stream_protocol::endpoint endpoint(m_socket_path);
  m_local_socket.async_connect(endpoint,
    boost::beast::bind_front_handler(&WebsocketClientSessionImpl::OnLocalConnect,
      std::static_pointer_cast<WebsocketClientSessionImpl>(shared_from_this())));
}

void WebsocketClientSessionImpl::Connect(const std::string& ws_server_url) {
  ParseUrl(ws_server_url, &m_scheme, &m_host, &m_port, &m_path);
  m_resolver = std::make_shared<boost::asio::ip::tcp::resolver>(*m_ioc);
  DoResolve();
}

void WebsocketClientSessionImpl::ConnectLocal(const std::string& unix_socket_file_path) {
  try {
    m_use_local_socket = true;
    m_socket_path = unix_socket_file_path;
    boost::asio::local::stream_protocol::socket m_local_socket(*m_ioc);
    DoLocalConnect();
  } catch (const std::exception& e) {
    m_logger.With("error", e.what()).Error("create unix domain socket acceptor fail");
    return;
  }
}

void WebsocketClientSessionImpl::CloseSession() {}

const std::string WebsocketClientSessionImpl::GetClientAddress() {
  return "";
}

WebsocketServerSessionImpl::WebsocketServerSessionImpl(boost::asio::io_context* ioc,
  boost::asio::ip::tcp::socket&& socket, std::function<void(std::weak_ptr<WebsocketSession>)> session_begin_callback,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_end_callback,
  std::function<void(std::weak_ptr<WebsocketSession>, const std::string&)> session_recv_callback,
  structlog::Logger& parent_logger, std::shared_ptr<WebsocketServerImpl> server_impl)
  : WebsocketSessionImpl(ioc, session_begin_callback, session_end_callback, session_recv_callback, parent_logger)
  , m_server_impl(server_impl) {
  m_websocket_stream =
    std::make_shared<boost::beast::websocket::stream<boost::asio::ip::tcp::socket>>(std::move(socket));
  boost::system::error_code ec;
  boost::asio::ip::tcp::endpoint remote_ep = m_websocket_stream->next_layer().remote_endpoint(ec);
  if (ec) {
    m_logger.With("ec", ec.value()).With("message", LocalToUtf8(ec.message())).Warning("Failed to get remote endpoint");
  } else {
    m_address = remote_ep.address().to_string() + ":" + std::to_string(remote_ep.port());
  }
}

WebsocketServerSessionImpl::WebsocketServerSessionImpl(boost::asio::io_context* ioc,
  boost::asio::local::stream_protocol::socket&& socket,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_begin_callback,
  std::function<void(std::weak_ptr<WebsocketSession>)> session_end_callback,
  std::function<void(std::weak_ptr<WebsocketSession>, const std::string&)> session_recv_callback,
  structlog::Logger& parent_logger, std::shared_ptr<WebsocketServerImpl> server_impl)
  : WebsocketSessionImpl(ioc, session_begin_callback, session_end_callback, session_recv_callback, parent_logger)
  , m_server_impl(server_impl) {
  m_use_local_socket = true;
  m_websocket_stream_local =
    std::make_shared<boost::beast::websocket::stream<boost::asio::local::stream_protocol::socket>>(std::move(socket));
  boost::system::error_code ec;
  boost::asio::local::stream_protocol::endpoint remote_ep = m_websocket_stream_local->next_layer().remote_endpoint(ec);
  if (ec) {
    m_logger.With("ec", ec.value()).With("message", LocalToUtf8(ec.message())).Warning("Failed to get remote endpoint");
  } else {
    m_address = remote_ep.path();
  }
}

WebsocketServerSessionImpl::~WebsocketServerSessionImpl() {}

// 定义服务器的session
void WebsocketServerSessionImpl::AcceptHandshake() {
  if (m_use_local_socket) {
    m_websocket_stream_local->set_option(
      boost::beast::websocket::stream_base::timeout::suggested(boost::beast::role_type::server));
    m_websocket_stream_local->set_option(
      boost::beast::websocket::stream_base::decorator([](boost::beast::websocket::response_type& res) {
        res.set(boost::beast::http::field::server, std::string(BOOST_BEAST_VERSION_STRING) + " fclib_websocket");
      }));
    boost::beast::http::async_read(m_websocket_stream_local->next_layer(), m_buffer, m_upgrade_request,
      boost::beast::bind_front_handler(&WebsocketServerSessionImpl::OnUpgrade,
        std::static_pointer_cast<WebsocketServerSessionImpl>(shared_from_this())));
  } else {
    boost::beast::websocket::permessage_deflate pmd;
    pmd.client_enable = true;
    pmd.server_enable = true;
    m_websocket_stream->set_option(pmd);
    m_websocket_stream->set_option(
      boost::beast::websocket::stream_base::timeout::suggested(boost::beast::role_type::server));
    m_websocket_stream->set_option(
      boost::beast::websocket::stream_base::decorator([](boost::beast::websocket::response_type& res) {
        res.set(boost::beast::http::field::server, std::string(BOOST_BEAST_VERSION_STRING) + "fclib_websocket");
      }));
    boost::beast::http::async_read(m_websocket_stream->next_layer(), m_buffer, m_upgrade_request,
      boost::beast::bind_front_handler(&WebsocketServerSessionImpl::OnUpgrade,
        std::static_pointer_cast<WebsocketServerSessionImpl>(shared_from_this())));
  }
}

void WebsocketServerSessionImpl::CloseSession() {
  boost::system::error_code ec;
  m_websocket_stream->close(boost::beast::websocket::close_code::normal, ec);
  if (ec) {
    return;
  } else {
    m_session_status = WebsocketSession::Status::kDisconnected;
    m_server_impl->RemoveSession(shared_from_this());
  }
  return;
}

const std::string WebsocketServerSessionImpl::GetClientAddress() {
  return m_address;
}

void WebsocketServerSessionImpl::OnUpgrade(boost::beast::error_code ec, std::size_t) {
  if (ec) {
    m_logger.With("ec_value", ec.value())
      .With("ec_message", LocalToUtf8(ec.message()))
      .Warning("accept handshake fail");
    m_session_status = WebsocketSession::Status::kDisconnected;
    // session握手错误,抛弃session.
    m_server_impl->RemoveSession(shared_from_this());
    return;
  }
  for (auto iter = m_upgrade_request.base().begin(); iter != m_upgrade_request.base().end(); ++iter) {
    std::string key(iter->name_string());
    std::string value(iter->value());
    m_headers[key] = value;
  }
  bool f = (m_upgrade_request.base().count("X-Real-Port") > 0) && (m_upgrade_request.base().count("X-Real-Port") > 0);
  if (f) {
    std::string real_port = std::string(m_upgrade_request.base().at("X-Real-Port"));
    std::string real_ip = std::string(m_upgrade_request.base().at("X-Real-IP"));
    if (!real_ip.empty() && !real_port.empty())
      m_address = real_ip + ":" + real_port;
  }
  if (m_use_local_socket) {
    m_websocket_stream_local->async_accept(m_upgrade_request,
      boost::beast::bind_front_handler(&WebsocketServerSessionImpl::OnAcceptHandshake,
        std::static_pointer_cast<WebsocketServerSessionImpl>(shared_from_this())));
  } else {
    m_websocket_stream->async_accept(m_upgrade_request,
      boost::beast::bind_front_handler(&WebsocketServerSessionImpl::OnAcceptHandshake,
        std::static_pointer_cast<WebsocketServerSessionImpl>(shared_from_this())));
  }
}

void WebsocketServerSessionImpl::OnAcceptHandshake(boost::beast::error_code ec) {
  if (ec) {
    m_logger.With("ec_value", ec.value())
      .With("ec_message", LocalToUtf8(ec.message()))
      .Warning("accept handshake fail");
    m_session_status = WebsocketSession::Status::kDisconnected;
    // session握手错误,抛弃session.
    m_server_impl->RemoveSession(shared_from_this());
    return;
  }
  m_session_status = WebsocketSession::Status::kConnected;
  m_output_buffer_list.clear();
  if (m_session_begin_callback)
    m_session_begin_callback(shared_from_this());
  DoRead();
}

void WebsocketServerSessionImpl::OnRead(boost::beast::error_code ec, std::size_t bytes_transferred) {
  boost::ignore_unused(bytes_transferred);
  if (ec) {
    std::string err_msg = LocalToUtf8(ec.message());
    m_logger.With("ec_value", ec.value()).With("ec_message", err_msg).Warning("read fail");
    if (m_session_status == WebsocketSession::Status::kConnected) {
      m_session_status = WebsocketSession::Status::kDisconnected;
      if (m_session_end_callback)
        m_session_end_callback(shared_from_this());
    }
    // session read错误,抛弃session.
    m_server_impl->RemoveSession(shared_from_this());
    return;
  }
  auto msg = boost::beast::buffers_to_string(m_input_buffer.data());
  m_logger.With("len", static_cast<int>(msg.size()))
    .With("content", structlog::make_json(msg))
    .Debug("received message");
  if (m_session_recv_callback)
    m_session_recv_callback(shared_from_this(), msg);
  m_input_buffer.consume(m_input_buffer.size());
  DoRead();
}

