namespace fclib {
using namespace std::chrono;

LocalDateTime EpochNanoToLocalDateTime(int64_t epoch_nano_seconds, int time_zone) {
  LocalDateTime local_dt;
  local_dt.nano_seconds = epoch_nano_seconds % 1000000000LL;
  std::time_t epoch_time = epoch_nano_seconds / 1000000000LL;
  epoch_time += time_zone * 3600;
#ifdef _WIN32
  gmtime_s(&local_dt.date_time, &epoch_time);
#else
  gmtime_r(&epoch_time, &local_dt.date_time);
#endif
  local_dt.time_zone = time_zone;
  return local_dt;
}

int64_t LocalDateTimeToEpochNano(const LocalDateTime& dt) {
#ifdef _WIN32
  std::tm t = dt.date_time;
  auto timet = _mkgmtime(&t) - dt.time_zone * 3600;
#else
  std::tm t = dt.date_time;
  auto timet = timegm(&t) - dt.time_zone * 3600;
#endif
  return static_cast<int64_t>(timet) * 1000000000LL + dt.nano_seconds;
}

int64_t StringToEpochNano(
  const char* date_str, const char* time_str /*= nullptr*/, int time_zone /*= 8*/, int64_t nano_seconds /*= 0*/) {
  LocalDateTime dt;
  dt.time_zone = time_zone;
  dt.nano_seconds = nano_seconds;
  if (!date_str)
    return -1;
  if (sscanf(date_str, "%04d%*[/-]%02d%*[/-]%02d", &dt.date_time.tm_year, &dt.date_time.tm_mon, &dt.date_time.tm_mday)
    != 3)
    if (sscanf(date_str, "%04d%02d%02d", &dt.date_time.tm_year, &dt.date_time.tm_mon, &dt.date_time.tm_mday) != 3)
      return -1;
  dt.date_time.tm_year -= 1900;
  dt.date_time.tm_mon -= 1;
  if (time_str) {
    if (sscanf(time_str, "%02d:%02d:%02d", &dt.date_time.tm_hour, &dt.date_time.tm_min, &dt.date_time.tm_sec) != 3)
      if (sscanf(time_str, "%02d%02d%02d", &dt.date_time.tm_hour, &dt.date_time.tm_min, &dt.date_time.tm_sec) != 3)
        return -1;
  }
  return LocalDateTimeToEpochNano(dt);
}

TQ_EXPORT int64_t DateTimeStringToEpochNano(const char* date_time_str) {
  LocalDateTime dt;
  // 2021-12-28T20:55:19.273241100+08:00
  if (sscanf(date_time_str, "%04d-%02d-%02dT%02d:%02d:%02d.%" SCNd64 "+%02d:00", &dt.date_time.tm_year,
        &dt.date_time.tm_mon, &dt.date_time.tm_mday, &dt.date_time.tm_hour, &dt.date_time.tm_min, &dt.date_time.tm_sec,
        &dt.nano_seconds, &dt.time_zone)
    != 8)
    return -1;
  dt.date_time.tm_year -= 1900;
  dt.date_time.tm_mon -= 1;
  return LocalDateTimeToEpochNano(dt);
}

TQ_EXPORT const char* GetStringFromEpochNano(int64_t epoch_nano, int time_zone) {
  LocalDateTime local_time = EpochNanoToLocalDateTime(epoch_nano, time_zone);
  static char buff[128] = {0};
  local_time.date_time.tm_year += 1900;
  local_time.date_time.tm_mon += 1;
  snprintf(buff, sizeof(buff), "%04d-%02d-%02d %02d:%02d:%02d.%06d", local_time.date_time.tm_year,
    local_time.date_time.tm_mon, local_time.date_time.tm_mday, local_time.date_time.tm_hour,
    local_time.date_time.tm_min, local_time.date_time.tm_sec, static_cast<int>(local_time.nano_seconds / 1000));
  return buff;
}

static int64_t one_day_nano = 24LL * 3600 * 1000000000;

int64_t GetRealTradeTime(const char* date_str, const char* time_str, int time_zone /*= 8*/) {
  if (!date_str || !time_str)
    return -1;
  LocalDateTime dt;
  dt.time_zone = time_zone;
  if (sscanf(date_str, "%04d%*[/-]%02d%*[/-]%02d", &dt.date_time.tm_year, &dt.date_time.tm_mon, &dt.date_time.tm_mday)
    != 3)
    if (sscanf(date_str, "%04d%02d%02d", &dt.date_time.tm_year, &dt.date_time.tm_mon, &dt.date_time.tm_mday) != 3)
      return -1;
  dt.date_time.tm_year -= 1900;
  dt.date_time.tm_mon -= 1;
  std::string format;
  if (strlen(time_str) == 6) {
    format = "%02d%02d%02d";
  } else if (strlen(time_str) == 5) {
    format = "%01d%02d%02d";
  } else {
    format = "%02d:%02d:%02d";
  }
  if (sscanf(time_str, format.c_str(), &dt.date_time.tm_hour, &dt.date_time.tm_min, &dt.date_time.tm_sec) != 3)
    return -1;
  int64_t epoch_nano = LocalDateTimeToEpochNano(dt);
  dt = EpochNanoToLocalDateTime(epoch_nano, time_zone);
  if (dt.date_time.tm_wday == 1) {
    if (dt.date_time.tm_hour > 19)
      epoch_nano -= 3 * one_day_nano;
    else if (dt.date_time.tm_hour < 5)
      epoch_nano -= 2 * one_day_nano;
  } else {
    if (dt.date_time.tm_hour > 19)
      epoch_nano -= one_day_nano;
  }
  return epoch_nano;
}

/**
 * 伪时间值. 这是一个测试专用变量, 仅为构建测试用例使用.
 */
int64_t mock_epoch_nano = 0;

void MockDateTime(int64_t epoch_nano) {
  mock_epoch_nano = epoch_nano;
}

int64_t NowAsEpochNano() {
  if (mock_epoch_nano > 0)
    return mock_epoch_nano;
  return std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::system_clock::now().time_since_epoch())
    .count();
}

