 * @file timer.cpp
 * @brief 计时器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/utils/timer.h"

#include <chrono>

namespace fclib {
using namespace std::chrono;

static int64_t mock_adjust_milliseconds = 0;

Timer::Timer() {
  Reset();
}

void Timer::Reset(std::chrono::milliseconds duration /*= 0*/) {
  m_start_point = std::chrono::high_resolution_clock::now() + milliseconds(mock_adjust_milliseconds);
  m_duration = duration;
}

std::chrono::milliseconds Timer::GetTime() {
