/*******************************************************************************
 * @file femas_order_ref_helper.cpp
 * @brief Femas OrderRef 自增助手
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "femas_order_ref_helper.h"
#include <string>
#include "fclib/utils/fcassert.h"

namespace fclib {

// 实现数字递增,且不会生成非数字字符,返回值为是否进位
bool NumIncrease(char& num) {
  if (num < '0') {
    num = '1';
    return false;
  }
  if (num < '9') {
    num += 1;
    return false;
  }
  num = '0';
  return true;
}

// 实现非数字的字符递增,返回值为是否进位
bool CharIncrease(char& ch) {
  // 32-126是可见字符的ASCII码
  if (ch < 126) {
    ch += 1;
    return false;
  }
  ch = 32;
  return true;
}

FemasOrderRefHelper::FemasOrderRefHelper(const std::string& order_ref) : m_order_ref(order_ref) {
  FCASSERT(m_order_ref.size() <= 20);
  for (const char& ch : order_ref) {
    // "     123" 也认为是数字
    if (ch == ' ')
      continue;
    if (!std::isdigit(ch)) {
      m_all_digit = false;
      break;
    }
  }
  m_order_ref.resize(20, '0');
}

// 若order_ref中包含非数字字符,则递增时会生成非数字字符
// 若order_ref中只包含数字字符,则递增时未达上限不会生成非数字字符
// 若order_ref达到上限,则会产生非数字字符
std::string FemasOrderRefHelper::GetNextOrderRef() {
  bool carry = false;
  if (m_all_digit) {
    for (int i = 19; i >= 0; --i) {
      carry = NumIncrease(m_order_ref[i]);
      if (!carry) {
        return m_order_ref;
      }
    }
  }
  if (carry) {
    m_order_ref = "99999999999999999999";
    m_all_digit = false;
  }
  for (int i = 19; i >= 0; --i) {
    if (!CharIncrease(m_order_ref[i])) {
      break;
    }
  }
  return m_order_ref;
}

