}

bool IsProcessRunning(int pid) {
#ifdef _WIN32
  DWORD dwProcessId = static_cast<DWORD>(pid);
  HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION, FALSE, dwProcessId);
  if (nullptr == hProcess)
    return false;
  DWORD exitCode = 0;
  bool ret = GetExitCodeProcess(hProcess, &exitCode) && exitCode == STILL_ACTIVE;
  CloseHandle(hProcess);
  return ret;
#else
  return kill(pid, 0) == 0;
#endif
}
