MessageProcessor::MessageProcessor(std::shared_ptr<TqApiNodeDb> db, structlog::Logger& logger)
  : m_db(db)
  , m_logger(logger.With("message_processor", reinterpret_cast<int64_t>(this)).Clone()) {}

void MessageProcessor::ProcessOrder(std::shared_ptr<future::Order> order) {
  auto ins_node = md::GetInstrumentNode(order->Symbol(), m_db);

  // 处理做市衍生单
  std::shared_ptr<future::QuoteNode> quote_node = nullptr;
  auto it = m_quote_cache.find(order->GetKey());
  if (it != m_quote_cache.end()) {
    quote_node = m_db->GetNode<future::Quote>(it->second);
    m_quote_cache.erase(it);
  }

  std::set<std::string_view> trade_set;
  auto order_node = m_db->ReplaceRecord<future::Order>(order->GetKey(), [&](std::shared_ptr<future::Order> o) {
    o->ins_pointer = ins_node;
    auto tmp_last_trade_date_time = o->last_trade_date_time;
    auto tmp_trade_price = o->trade_price;
    auto tmp_trade_total_volume = o->trade_total_volume;
    auto tmp__leg1_trade_price = o->_leg1_trade_price;
    auto tmp__leg1_trade_total_volume = o->_leg1_trade_total_volume;
    auto tmp__leg2_trade_price = o->_leg2_trade_price;
    auto tmp__leg2_trade_total_volume = o->_leg2_trade_total_volume;
    auto tmp_seq_no = o->seq_no;
    auto base = std::static_pointer_cast<future::OrderBase>(order);
    (future::OrderBase&)(*o) = *base;
    o->last_trade_date_time = tmp_last_trade_date_time;
    o->trade_price = tmp_trade_price;
    o->trade_total_volume = tmp_trade_total_volume;
    o->_leg1_trade_price = tmp__leg1_trade_price;
    o->_leg1_trade_total_volume = tmp__leg1_trade_total_volume;
    o->_leg2_trade_price = tmp__leg2_trade_price;
    o->_leg2_trade_total_volume = tmp__leg2_trade_total_volume;
    o->seq_no = tmp_seq_no;
    auto it = m_trade_cache.find(order->exchange_order_id + order->exchange_id);
    if (it != m_trade_cache.end()) {
      for (auto& trade_node : it->second) {
        FCASSERT(trade_node->Latest()->user_key == order->user_key);
        o->UpdateOrderByTrade(trade_node);
        trade_set.insert(trade_node->GetKey());
      }
      m_trade_cache.erase(it);
    }
    // 处理做市衍生单
    if (quote_node) {
      o->quote_pointer = quote_node;
      o->is_quote = true;
    }
    if (tmp_seq_no == -1) {
      o->seq_no = m_order_seq_no++;
    }
  });
  for (auto& key : trade_set) {
    m_db->ReplaceRecord<future::Trade>(key, [=](std::shared_ptr<future::Trade> trade) {
      trade->order_pointer = order_node;
      trade->unit_id = order_node->Latest()->unit_id;
    });
  }
  if (quote_node) {
    m_db->ReplaceRecord<future::Quote>(quote_node->GetKey(), [=](std::shared_ptr<future::Quote> quote) {
      if (order->direction == future::Direction::kBuy)
        quote->bid_order_pointer = order_node;
      else if (order->direction == future::Direction::kSell)
        quote->ask_order_pointer = order_node;
    });
  }
}

void MessageProcessor::ProcessTrade(std::shared_ptr<future::Trade> trade) {
  auto ins_node = md::GetInstrumentNode(trade->Symbol(), m_db);
  FCASSERT(!trade->user_key.empty() && !trade->order_id.empty());
  FCASSERT(!trade->exchange_order_id.empty() && !trade->exchange_id.empty());
  auto order_key = future::Order::MakeKey(trade->user_key, trade->order_id);
  auto order_node = m_db->GetNode<future::Order>(order_key);
  auto trade_node = m_db->ReplaceRecord<future::Trade>(trade->GetKey(), [&](std::shared_ptr<future::Trade> t) {
    int tmp_seq_no = t->seq_no;
    if (tmp_seq_no == -1) {
      tmp_seq_no = m_trade_seq_no++;
    }
    auto base = std::static_pointer_cast<future::TradeBase>(trade);
    (future::TradeBase&)(*t) = *base;
    t->seq_no = tmp_seq_no;
    if (order_node) {
      t->order_pointer = order_node;
      t->unit_id = order_node->Latest()->unit_id;
    }
    t->ins_pointer = ins_node;
  });
  if (!order_node) {
    m_trade_cache[trade->exchange_order_id + trade->exchange_id].insert(trade_node);
    return;
  }
  // 更新委托
  m_db->ReplaceRecord<future::Order>(
    future::Order::MakeKey(trade->user_key, trade->order_id), [=](std::shared_ptr<future::Order> order) {
      FCASSERT(!order->user_key.empty());
      FCASSERT(!order->order_id.empty());
      order->UpdateOrderByTrade(trade_node);
    });
}

void MessageProcessor::ProcessQuote(std::shared_ptr<future::Quote> quote) {
  std::shared_ptr<future::OrderNode> ask_order_node = nullptr;
  std::shared_ptr<future::OrderNode> bid_order_node = nullptr;
  if (!quote->ask_order_id.empty()) {
    auto order_key = future::Order::MakeKey(quote->user_key, quote->ask_order_id);
    ask_order_node = m_db->GetNode<future::Order>(order_key);
    if (nullptr != ask_order_node) {
      quote->ask_order_pointer = ask_order_node;
    } else {
      m_quote_cache[order_key] = quote->GetKey();
    }
  }
  if (!quote->bid_order_id.empty()) {
    auto order_key = future::Order::MakeKey(quote->user_key, quote->bid_order_id);
    bid_order_node = m_db->GetNode<future::Order>(order_key);
    if (nullptr != bid_order_node) {
      quote->bid_order_pointer = bid_order_node;
    } else {
      m_quote_cache[order_key] = quote->GetKey();
    }
  }
  auto quote_node = m_db->ReplaceRecord(quote);
  if (nullptr != ask_order_node) {
    m_db->ReplaceRecord<future::Order>(ask_order_node->Latest()->GetKey(), [=](std::shared_ptr<future::Order> base) {
      base->quote_pointer = quote_node;
      base->is_quote = true;
    });
  }
  if (nullptr != bid_order_node) {
    m_db->ReplaceRecord<future::Order>(bid_order_node->Latest()->GetKey(), [=](std::shared_ptr<future::Order> base) {
      base->quote_pointer = quote_node;
      base->is_quote = true;
    });
  }
}

void MessageProcessor::ProcessConditionOrder(std::shared_ptr<future::ConditionOrder> condition_order) {
  m_db->ReplaceRecord<future::ConditionOrder>(
    condition_order->GetKey(), [&](std::shared_ptr<future::ConditionOrder> o) {
      int old_seq = o->seq_no;
      *o = *condition_order;
      o->seq_no = (old_seq == -1) ? ++m_condition_order_seq_no : old_seq;
    });
}

