int CrashCallback(CR_CRASH_CALLBACK_INFO* pInfo) {
  if (pInfo->nStage == CR_CB_STAGE_PREPARE) {
    structlog::SetOutput(nullptr);
    boost::iostreams::close(g_log_stream);
    g_log_file.close();
    MEMORYSTATUSEX memstat;
    memset(&memstat, 0, sizeof(memstat));
    memstat.dwLength = sizeof(memstat);
    if (GlobalMemoryStatusEx(&memstat)) {
      crAddProperty("PhysicalMemMB",
        std::string(
          std::to_string(memstat.ullAvailPhys / 1024 / 1024) + "/" + std::to_string(memstat.ullTotalPhys / 1024 / 1024))
          .c_str());
    }
  }
  return CR_CB_DODEFAULT;
}

bool InstallCrashHandler(const std::string& version) {
  CR_INSTALL_INFO info;
  memset(&info, 0, sizeof(CR_INSTALL_INFO));
  info.cb = sizeof(CR_INSTALL_INFO);
  info.pszAppName = GetTradeName().c_str();
  info.pszAppVersion = version.c_str();
  info.pszUrl = "http://fix.shinnytech.com/index.php/crashReport/uploadExternal";
  info.dwFlags |= CR_INST_ALL_POSSIBLE_HANDLERS;
  info.dwFlags |= CR_INST_AUTO_THREAD_HANDLERS;
  info.dwFlags |= CR_INST_HTTP_BINARY_ENCODING;
  info.dwFlags |= CR_INST_ALLOW_ATTACH_MORE_FILES;
  info.dwFlags |= CR_INST_NO_GUI;
  info.uMiniDumpType = (MINIDUMP_TYPE)(static_cast<int>(MiniDumpWithIndirectlyReferencedMemory)
    | static_cast<int>(MiniDumpWithDataSegs) | static_cast<int>(MiniDumpWithFullMemoryInfo));
