// 计算范围随机数
int CalcRangeRandom(int range) {
  int pid = fclib::GetCurrentPID();

  std::random_device rd;
  std::mt19937 gen(rd() ^ pid);

  std::uniform_int_distribution<int> distribution((range * -1), range);
  return distribution(gen);
}

int main(int argc, char* argv[]) {
  if (argc != 4)
    return FCEXIT_ARGV;
  // 获取进程启动时间,作为日志名称
  auto now = fclib::EpochNanoToLocalDateTime(fclib::NowAsEpochNano());
  char buf[20];
  snprintf(buf, sizeof(buf), "%04d%02d%02d_%02d%02d%02d", (now.date_time.tm_year + 1900) % 10000u,
    (now.date_time.tm_mon + 1) % 100u, now.date_time.tm_mday, now.date_time.tm_hour, now.date_time.tm_min,
    now.date_time.tm_sec);
  // 获取 user_key
  std::string user_key = argv[1];
  std::string pid = argv[2];
  // 获取 options
  fclib::future::FutureServiceOptions options;
  fclib::ProcessJsonSerializer ss;
  try {
    ss.FromString(fclib::base64url_decode(argv[3]).data());
    ss.ToVar(options);
  } catch (std::exception& ex) {
    std::cerr << GetTradeName() << ":" << argv[1] << " exception:" << fclib::LocalToUtf8(ex.what()) << std::endl;
    return FCEXIT_SERIALIZE;
  }
  assert(!options.config_directory.empty());
  // 设置共享内存路径
#ifdef BOOST_INTERPROCESS_SHARED_DIR_FUNC
  if (u8SharedMemoryPath.empty() || u16SharedMemoryPath.empty()) {
    std::filesystem::path directory = std::filesystem::u8path(options.config_directory);
    directory.append("shm");

    std::filesystem::create_directories(directory);
    u8SharedMemoryPath = directory.u8string();
    u16SharedMemoryPath = directory.wstring();
  }
#endif  // BOOST_INTERPROCESS_SHARED_DIR_FUNC

  // 设置输出日志
  if (!options.log_directory.empty()) {
    options.log_directory += "/";
    if (options.log_compression) {
      std::string log_path =
        options.log_directory + std::string(buf) + "_" + GetTradeName() + "_" + user_key + "_" + pid + ".log.xz";
      std::replace(log_path.begin(), log_path.end(), '|', '_');
      std::filesystem::path p = std::filesystem::u8path(log_path);
      g_log_file = std::ofstream(p, std::ios_base::out | std::ios::binary);
      g_log_file.rdbuf()->pubsetbuf(nullptr, 0);
      g_log_stream.push(boost::iostreams::lzma_compressor());
      g_log_stream.push(g_log_file);
      structlog::SetOutput(&g_log_stream);
      watchdog::WatchDog::SetAttachmentPath(log_path);
    } else {
      std::string log_path =
        options.log_directory + std::string(buf) + "_" + GetTradeName() + "_" + user_key + "_" + pid + ".log";
      std::replace(log_path.begin(), log_path.end(), '|', '_');
      std::filesystem::path p = std::filesystem::u8path(log_path);
      g_log_file = std::ofstream(p, std::ios_base::out | std::ios::binary);
      g_log_file.rdbuf()->pubsetbuf(nullptr, 0);
      structlog::SetOutput(&g_log_file);
      watchdog::WatchDog::SetAttachmentPath(log_path);
    }
  } else {
    structlog::SetOutput(nullptr);
  }
  structlog::SetLevel(structlog::LogLevel::Info);
  auto logger = structlog::Logger::Root().With("main", GetTradeName() + "_" + pid).Clone();
  fclib::DumpHelper::InitDumpHelper(options.config_directory);
  if (!options.watchdog_address.empty() && !options.watchdog_name.empty()) {
    watchdog::WatchDogOptions watchdog_options;
    watchdog_options.name = options.watchdog_name;
    watchdog_options.time_interval = CHECK_INTERVAL / 1000 + 6;
    watchdog_options.max_heartbeat_miss = 10;
    watchdog_options.max_msg_size = 1024;
    watchdog_options.max_msg_count = 1000;
    watchdog_options.sentry_url = options.watchdog_address;
    watchdog_options.db_path = options.config_directory;
    watchdog_options.version = options.version;
    watchdog_options.run_path = options.run_directory;
    watchdog_options.product_name = GetTradeName();
    watchdog_options.user_id = user_key + "_" + options.user_info;
    watchdog::WatchDog::Register(watchdog_options);
  }

#if !defined(_RELWITHDEBINFO) && !defined(_DEBUG)
#ifdef _WIN32
  // 初始化崩溃报告器
  logger.Info("start InstallCrashHandler");
  InstallCrashHandler(options.version);
  logger.Info("finish InstallCrashHandler");
#endif
#endif

  // 构建 TradeFuture
  boost::asio::io_context io_context;
  auto trade_future = std::make_shared<fclib::future::TradeFuture>(&io_context, user_key, pid, options, logger);
  logger.With("user_key", user_key).Info("trade future create");
  try {
    auto process_id = std::stoi(pid);
    if (!trade_future->Init()) {
      FCASSERT(false);
      logger.Error("trade future init fail");
      std::cerr << GetTradeName() << ":" << argv[1] << " error:" << u8"初始化失败" << std::endl;
      watchdog::WatchDog::Unregister();
      return FCEXIT_INIT;
    }
    logger.With("user_key", user_key).Info("trade future run");
    // 运行 trade_future
    fclib::Timer timer;
    int rd = CalcRangeRandom(500);
    timer.Reset(std::chrono::milliseconds(CHECK_INTERVAL + rd));
    while (true) {
      if (timer.IsExpired()) {
        if (!fclib::IsProcessRunning(process_id)) {
          logger.With("user_key", user_key).With("pid", process_id).Info("parent process exit");
          break;
        }
        watchdog::WatchDog::SendHeartbeat();
        timer.Reset(std::chrono::milliseconds(CHECK_INTERVAL + rd));
      }
      char ret_code = trade_future->RunOnce();
      if (ret_code == 'E') {
        logger.With("user_key", user_key).Info("trade future exit");
        break;
      }
      if (ret_code == 'F') {
        // flush log file
        if (!options.log_directory.empty() && options.log_compression) {
          boost::iostreams::filtering_ostream& log_stream = g_log_index == 0 ? g_log_stream : g_log_stream1;
          log_stream.push(boost::iostreams::lzma_compressor());
          log_stream.push(g_log_file);
          structlog::SetOutput(&log_stream);
          boost::iostreams::filtering_ostream& release_log_stream = g_log_index == 0 ? g_log_stream1 : g_log_stream;
          g_log_index = (g_log_index + 1) % 2;
          release_log_stream.pop();
          release_log_stream.pop();
        }
      }
      boost::this_thread::sleep_for(boost::chrono::milliseconds(10));
    }
    // 处理日志
    logger.With("user_key", user_key).Info("main exit");
    structlog::SetOutput(nullptr);
    if (options.log_compression) {
      boost::iostreams::close(g_log_stream);
      boost::iostreams::close(g_log_stream1);
    }
    g_log_file.close();
  } catch (std::exception& ex) {
    auto exmsg = fclib::LocalToUtf8(ex.what());
    std::cerr << "main:" << argv[1] << " exception:" << exmsg << std::endl;
    // 假定 logger; g_log_stream; g_log_file 未崩溃
    logger.With("user_key", user_key).With("exception", exmsg).Info("main exit with exception");
    // 处理日志
    structlog::SetOutput(nullptr);
    if (options.log_compression)
      boost::iostreams::close(g_log_stream);
    g_log_file.close();
    watchdog::WatchDog::Unregister();
    // 处理崩溃
    FCASSERT(false);
    return FCEXIT_EXCEPTION;
  }
  watchdog::WatchDog::Unregister();
  return FCEXIT_SUCCESS;
}

