static constexpr int MAX_IN_MSG_NUMS = 1000;
static constexpr int MAX_OUT_MSG_NUMS = 5000;

static std::string ExitCodeMsg(int exit_code, const std::string& user_key, const future::BackEnd& backend) {
  return "Process Exited Abnormally: " + std::to_string(exit_code) + ", " + user_key + ", "
    + GetBackendChineseName(backend);
}

TradeProcess::TradeProcess(boost::asio::io_context* io_context, const std::string& user_key, const std::string& pid,
  const future::FutureServiceOptions& options, structlog::Logger& logger)
  : m_io_context(io_context)
  , m_user_key(user_key)
  , m_pid(pid)
  , m_options(options)
  , m_logger(logger.With("trade_process", reinterpret_cast<int64_t>(this)).With("user_key", m_user_key).Clone())
  , m_thread_logger(m_logger.Clone()) {
  m_login_finished.store(false);
  m_process_init.store(false);
  m_options_str.clear();
  ProcessJsonSerializer ss;
  ss.FromVar(m_options);
  ss.ToString(&m_options_str);

  // 使用 base64url 编码, 避免中文编码问题
  m_options_str = base64url_encode(m_options_str.c_str(), m_options_str.size());
}

bool TradeProcess::StartProcess(std::string* msg /*= nullptr*/) {
  m_thread_logger.Info("start process");
  if (nullptr == m_req_login) {
    if (msg)
      *msg = u8"fclib: 启动进程失败: 缺少登录请求";
    m_thread_logger.With("fun", "StartProcess").Error("not login request");
    return false;
  }
  try {
    auto run_directory = m_options.run_directory.empty() ? "" : (m_options.run_directory + "/");
    switch (m_req_login->backend) {
      case future::BackEnd::kCtp: {
        return StartProcess(run_directory + "fclib_ctp/fclib_ctp", m_req_login->backend, msg);
      }
      case future::BackEnd::kCtpSopt: {
        return StartProcess(run_directory + "fclib_ctp_sopt/fclib_ctp_sopt", m_req_login->backend, msg);
      }
      case future::BackEnd::kCtpMini: {
        return StartProcess(run_directory + "fclib_ctp_mini/fclib_ctp_mini", m_req_login->backend, msg);
      }
      case future::BackEnd::kFemas2: {
        return StartProcess(run_directory + "fclib_femas2/fclib_femas2", m_req_login->backend, msg);
      }
      case future::BackEnd::kFemas: {
        return StartProcess(run_directory + "fclib_femas/fclib_femas", m_req_login->backend, msg);
      }
      case future::BackEnd::kRohon: {
        return StartProcess(run_directory + "fclib_rohon/fclib_rohon", m_req_login->backend, msg);
      }
      case future::BackEnd::kXOne: {
        return StartProcess(run_directory + "fclib_xone/fclib_xone", m_req_login->backend, msg);
      }
      case future::BackEnd::kX1: {
        return StartProcess(run_directory + "fclib_x1/fclib_x1", m_req_login->backend, msg);
      }
      case future::BackEnd::kUFX: {
        return StartProcess(run_directory + "fclib_ufx/fclib_ufx", m_req_login->backend, msg);
      }
      case future::BackEnd::kYiDa: {
        return StartProcess(run_directory + "fclib_yida/fclib_yida", m_req_login->backend, msg);
      }
      case future::BackEnd::kDstar: {
        return StartProcess(run_directory + "fclib_dstar/fclib_dstar", m_req_login->backend, msg);
      }
      case future::BackEnd::kLocalSim: {
        return StartProcess(run_directory + "fclib_local_sim/fclib_local_sim", m_req_login->backend, msg);
      }
      case future::BackEnd::kXuntou: {
        return StartProcess(run_directory + "fclib_xuntou/fclib_xuntou", m_req_login->backend, msg);
      }
      case future::BackEnd::kDtp: {
        return StartProcess(run_directory + "fclib_dtp/fclib_dtp", m_req_login->backend, msg);
      }
      case future::BackEnd::kOtg: {
        return StartProcess(run_directory + "fclib_otg/fclib_otg", m_req_login->backend, msg);
      }
      case future::BackEnd::kJees: {
        return StartProcess(run_directory + "fclib_jees/fclib_jees", m_req_login->backend, msg);
      }
      case future::BackEnd::kTap: {
        return StartProcess(run_directory + "fclib_tap/fclib_tap", m_req_login->backend, msg);
      }
      default: {
        if (msg)
          *msg = u8"fclib: 启动进程失败: 不支持的柜台类型";
        m_thread_logger.With("fun", "StartProcess")
          .With("backend", static_cast<int>(m_req_login->backend))
          .Error("req_login invalid backend");
        return false;
      }
    }
  } catch (const std::exception& ex) {
    auto errmsg = LocalToUtf8(ex.what());
    if (msg)
      *msg = u8"fclib: " + GetBackendChineseName(m_req_login->backend) + u8"启动进程失败(" + m_user_key + u8")";
    m_thread_logger.With("fun", "StartProcess").With("errmsg", errmsg).Warning("StartProcess() fail!");
    return false;
  }
}

void TradeProcess::StopProcess() {
  m_logger.Info("stop process");
  if ((nullptr != m_process_ptr) && (m_process_ptr->running())) {
    // 发送停止请求
    ProcessBinarySerializer bs;
    BinaryTypeID dummy = 0;
    m_in_mq_ptr->SendBuffer(bs.Serialize(future::EXIT_TYPE_ID, dummy));
    if (!m_in_mq_ptr->IsSending()) {
      // 发送成功等待进程结束
      while (m_process_ptr->running()) {
      }
    }
    auto native_exit_code = m_process_ptr->native_exit_code();
    if (native_exit_code != 0) {
      FCASSERT(nullptr != m_req_login);
      watchdog::WatchDog::SendMsg(ExitCodeMsg(native_exit_code, m_user_key + m_options.user_info, m_req_login->backend),
        watchdog::MessageLevel::kError);
    }
    m_logger.With("fun", "StopProcess")
      .With("child_pid", m_process_ptr->id())
      .With("exit_code", m_process_ptr->exit_code())
      .With("native_exit_code", native_exit_code)
      .Info("stop child process");
    m_process_ptr.reset();
  }
}

bool TradeProcess::IsRunning() {
  if (!m_process_init.load())
    return true;
  if (nullptr == m_process_ptr)
    return false;
  if (!m_running)
    return false;
  m_running = m_process_ptr->running();
  if (!m_running) {
    auto native_exit_code = m_process_ptr->native_exit_code();
    if (native_exit_code != 0) {
      FCASSERT(nullptr != m_req_login);
      watchdog::WatchDog::SendMsg(ExitCodeMsg(native_exit_code, m_user_key + m_options.user_info, m_req_login->backend),
        watchdog::MessageLevel::kError);
    }
    m_logger.With("fun", "IsRunning")
      .With("child_pid", m_process_ptr->id())
      .With("exit_code", m_process_ptr->exit_code())
      .With("native_exit_code", native_exit_code)
      .Info("process not running");
  }
  return m_running;
}

void TradeProcess::CleanUp() {
  if (m_login_thread.joinable()) {
    m_login_thread.join();
  }
  m_logger.Info("clean up");
  if (m_cleaned)
    return;
  m_cleaned = true;
  StopProcess();
  m_req_login.reset();
}

void TradeProcess::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_logger.With("fun", "ExecuteCommand").With("aid", command->aid).Info("execute command");
  // 非登录请求, 交易子进程必须运行中
  if ((command->aid != future::ReqLogin::AID && command->aid != future::ChangePasswordBeforeLogin::AID)
    && !IsRunning()) {
    SetCommandFinished(command, -1, u8"fclib: 交易子进程未运行, 无法执行请求");
    return;
  }
  // 启动子进程
  if (command->aid == future::ReqLogin::AID || command->aid == future::ChangePasswordBeforeLogin::AID) {
    if (m_req_login) {
      SetCommandFinished(command, -1, u8"fclib: 账户已登录");
      return;
    }
    if (command->aid == future::ReqLogin::AID) {
      m_req_login = std::static_pointer_cast<future::ReqLogin>(command);
    } else {
      m_req_login = std::static_pointer_cast<future::ChangePasswordBeforeLogin>(command)->req_login;
    }
    m_login_thread = std::thread([=]() {
      std::string result_msg;
      if (!StartProcess(&result_msg)) {
        SetCommandFinished(command, -1, result_msg);
        m_process_init.store(true);
        return;
      }
      if (!SendCommand(command, true)) {
        SetCommandFinished(command, -1, u8"fclib: 交易子进程请求发送失败");
      } else {
        m_login_finished.store(true);
      }
      m_process_init.store(true);
    });
    return;
  }
  // 发送请求
  if (!SendCommand(command))
    SetCommandFinished(command, -1, u8"fclib: 交易子进程请求发送失败");
}

bool TradeProcess::SendCommand(std::shared_ptr<UserCommand> command, bool new_thread) {
  auto& logger = new_thread ? m_thread_logger : m_logger;
  if (!new_thread) {
    if (!m_login_finished.load())
      return false;
  }
  if (nullptr == command) {
    logger.With("fun", "SendCommand").Warning("command is nullptr");
    return false;
  }
  if (nullptr == m_in_mq_ptr) {
    logger.With("fun", "SendCommand").Warning("m_in_mq_ptr is nullptr");
    return false;
  }
  if (nullptr == m_process_ptr) {
    logger.With("fun", "SendCommand").Warning("m_process_ptr is nullptr");
    return false;
  }
  logger.With("fun", "SendCommand").With("aid", command->aid).Info("send command");
  m_in_mq_ptr->SendBuffer(ProcessDataSerialize::CommandToBuffer(command, logger));
  return true;
}

std::shared_ptr<ProcessMessageQueue> TradeProcess::GetOutMessageQueue() {
  if (!m_login_finished.load())
    return nullptr;
  return m_out_mq_ptr;
}

bool TradeProcess::StartProcess(
  const std::string& path, const future::BackEnd& backend, std::string* msg /*= nullptr*/) {
  m_running = false;
  m_thread_logger.With("fun", "StartProcess").With("path", path).With("option", m_options_str).Info("start process");
  // 创建输入消息队列
  m_in_mq_name = m_pid + "_" + m_user_key + "_msg_in";
  m_in_mq_ptr = ProcessMessageQueue::Create(m_io_context, m_in_mq_name, MAX_IN_MSG_NUMS, m_thread_logger);
  if (nullptr == m_in_mq_ptr) {
    if (msg)
      *msg = u8"fclib: 启动进程失败: 创建输入消息队列失败";
    m_thread_logger.With("fun", "StartProcess").Error("StartProcess and create in message queue exception");
    return false;
  }
  // 创建输出消息队列
  m_out_mq_name = m_pid + "_" + m_user_key + "_msg_out";
  m_out_mq_ptr = ProcessMessageQueue::Create(m_io_context, m_out_mq_name, MAX_OUT_MSG_NUMS, m_thread_logger);
  if (nullptr == m_out_mq_ptr) {
    if (msg)
      *msg = u8"fclib: 启动进程失败: 创建输出消息队列失败";
    m_thread_logger.With("fun", "StartProcess").Error("StartProcess and create out message queue exception");
    return false;
  }

  // 修正子进程路径
  std::string child = path;
#ifdef _WIN32
  child += ".exe";
#endif

  // 创建子进程
  try {
    static std::mutex mutex;
    {
      std::lock_guard<std::mutex> lock(mutex);
#ifdef _WIN32
    std::filesystem::path p = std::filesystem::u8path(child);
      m_process_ptr = std::make_shared<boost::process::child>(
      p.wstring(), ::boost::process::windows::hide, m_user_key, m_pid, m_options_str);
#else
      m_process_ptr = std::make_shared<boost::process::child>(child.c_str(), m_user_key, m_pid, m_options_str);
#endif
    }
    if (nullptr == m_process_ptr) {
      if (msg)
        *msg = u8"fclib: " + GetBackendChineseName(backend) + u8"启动进程失败(" + m_user_key + u8")";
      return false;
    }
    m_running = m_process_ptr->running();
    if (!m_running) {
      auto native_exit_code = m_process_ptr->native_exit_code();
      if (native_exit_code != 0)
        watchdog::WatchDog::SendMsg(
          ExitCodeMsg(native_exit_code, m_user_key + m_options.user_info, backend), watchdog::MessageLevel::kError);
      m_thread_logger.With("fun", "StartProcess")
        .With("exit_code", m_process_ptr->exit_code())
        .With("native_exit_code", native_exit_code)
        .Error("start child process fail");
    }
    return m_running;
  } catch (std::exception& ex) {
    auto errmsg = LocalToUtf8(ex.what());
    if (msg)
      *msg = u8"fclib: " + GetBackendChineseName(backend) + u8"启动进程失败(" + m_user_key + u8")";
    m_thread_logger.With("fun", "StartProcess").With("errmsg", errmsg).Error("start child process fail");
    return false;
  }
}
