std::string ResolveFemas2LoginContent(std::shared_ptr<future::LoginContent> login) {
  std::string tmp = login->system_name;
  auto pos = tmp.find("_fclib_");
  if (pos == std::string::npos)
    return "";
  login->system_name = tmp.substr(0, pos);
  return tmp.substr(pos + 7);
}

MessageManager::MessageManager(std::shared_ptr<TqApiNodeDb> db, std::shared_ptr<CommandManager> manager,
  std::map<std::string, std::shared_ptr<ProcessCommandManager>>& child_command_manager, structlog::Logger& logger)
  : m_db(db)
  , m_command_manager(manager)
  , m_child_command_manager(child_command_manager)
  , m_logger(logger.With("message_manager", reinterpret_cast<int64_t>(this)).Clone()) {
  m_msg_processor = new MessageProcessor(db, logger);
}

MessageManager::~MessageManager() {
  delete m_msg_processor;
}

bool MessageManager::ProcessBuffer(const std::string& user_key, const std::vector<BinaryBufferType>& buffers) {
  if (buffers.empty())
    return true;
  BinaryTypeID type_id = ProcessBinarySerializer::DeserializeTypeID(buffers.at(0));
  if (type_id == future::EXIT_TYPE_ID)
    return false;
  if (ProcessDataSerialize::IsDataBuffer(type_id)) {
    return ProcessDataBuffer(type_id, buffers);
  } else {
    return ProcessRequestBuffer(user_key, buffers);
  }
  return false;
}

bool MessageManager::ProcessRequestBuffer(const std::string& user_key, const std::vector<BinaryBufferType>& buffers) {
  auto command = ProcessDataSerialize::BufferToCommand(user_key, buffers, m_logger);
  if (nullptr == command)
    return false;
  m_logger.With("user_key", user_key)
    .With("command", command->command_id)
    .With("aid", command->aid)
    .Info("ProcessRequestBuffer");
  // 处理报单
  if (command->aid == future::InsertOrder::AID) {
    auto insert = std::static_pointer_cast<future::InsertOrder>(command);
    auto order_node = m_db->GetNode<future::Order>(future::Order::MakeKey(user_key, insert->order_id));
    if (command->status == UserCommand::Status::kFinished) {
      auto request = m_command_manager->Update(insert->GetKey());
      if (request && order_node) {
        std::static_pointer_cast<future::InsertOrder>(request)->order_pointer = order_node;
      }
      SetCommandFinished(request, command->result_code, command->result_msg);
    }
    return true;
  }
  // 处理做市
  if (command->aid == future::InsertQuote::AID) {
    auto insert = std::static_pointer_cast<future::InsertQuote>(command);
    auto quote_node = m_db->GetNode<future::Quote>(user_key + "|" + insert->quote_id);
    if (command->status == UserCommand::Status::kFinished) {
      auto request = m_command_manager->Update(insert->GetKey());
      if (request && quote_node) {
        std::static_pointer_cast<future::InsertQuote>(request)->quote_pointer = quote_node;
      }
      SetCommandFinished(request, command->result_code, command->result_msg);
    }
    return true;
  }
  // 处理盘中自组合
  if (command->aid == future::PositionCombInsert::AID) {
    auto insert = std::static_pointer_cast<future::PositionCombInsert>(command);
    if (command->status == UserCommand::Status::kFinished) {
      auto request = m_command_manager->Update(command->GetKey());
      SetCommandFinished(request, command->result_code, command->result_msg);
    }
    if (command->status == UserCommand::Status::kStarted && insert->insert_id.empty()) {
      m_commands.push_back(command);
    }
    return true;
  }
  // 处理最大手数查询
  if (command->aid == future::QueryMaxVolume::AID) {
    auto qry = std::static_pointer_cast<future::QueryMaxVolume>(command);
    if (command->status == UserCommand::Status::kFinished) {
      auto request = m_command_manager->Update(qry->GetKey());
      std::static_pointer_cast<future::QueryMaxVolume>(request)->volume = qry->volume;
      SetCommandFinished(request, command->result_code, command->result_msg);
    }
    return true;
  }
  // 处理证券持仓锁定查询指令
  if (command->aid == future::QueryLockPosition::AID) {
    auto qry = std::static_pointer_cast<future::QueryLockPosition>(command);
    if (command->status == UserCommand::Status::kFinished) {
      auto request = m_command_manager->Update(qry->GetKey());
      auto req = std::static_pointer_cast<future::QueryLockPosition>(request);
      req->symbols = qry->symbols;
      req->frozen_volume = qry->frozen_volume;
      req->lock_volume = qry->lock_volume;
      SetCommandFinished(request, command->result_code, command->result_msg);
    }
    return true;
  }
  if (command->aid == future::ReqLogin::AID) {
    if (command->status != UserCommand::Status::kFinished)
      return true;
    auto req = std::static_pointer_cast<future::ReqLogin>(command);
    auto request = m_command_manager->Update(req->GetKey());
    SetCommandFinished(request, req->result_code, req->result_msg);
    if (req->result_code == 0)
      return true;
    auto login_node = m_db->GetNode<future::LoginContent>(user_key);
    if (login_node && login_node->Latest()->status_msg != req->result_msg) {
      m_db->ReplaceRecord<future::LoginContent>(user_key, [req](std::shared_ptr<future::LoginContent> l) {
        l->session_status = future::SessionStatus::kDisconnected;
        if (!req->result_msg.empty())
          l->status_msg = req->result_msg;
      });
    }
    return true;
  }
  if (command->status == UserCommand::Status::kFinished) {
    auto request = m_command_manager->Update(command->GetKey());
    SetCommandFinished(request, command->result_code, command->result_msg);
  }
  return true;
}

bool MessageManager::ProcessDataBuffer(const BinaryTypeID& type_id, const std::vector<BinaryBufferType>& buffers) {
  ProcessBinarySerializer bs;
  if (type_id == future::LOGIN_TYPE_ID) {
    auto login = std::make_shared<future::LoginContent>();
    bs.Deserialize(*login, buffers);
    if (login->backend == future::BackEnd::kFemas2) {
      std::string max_order_local_id = ResolveFemas2LoginContent(login);
      auto it = m_child_command_manager.find(login->user_key);
      if (it != m_child_command_manager.end()) {
        it->second->SetFemas2MaxOrderId(max_order_local_id);
      }
    }
    m_db->ReplaceRecord(login);
    return true;
  }
  if (type_id == future::ORDER_TYPE_ID) {
    auto order = std::make_shared<future::Order>();
    auto base = std::static_pointer_cast<future::OrderBase>(order);
    bs.Deserialize(*base, buffers);
    m_msg_processor->ProcessOrder(order);
    return true;
  }
  if (type_id == future::TRADE_TYPE_ID) {
    auto trade = std::make_shared<future::Trade>();
    auto base = std::static_pointer_cast<future::TradeBase>(trade);
    bs.Deserialize(*base, buffers);
    m_msg_processor->ProcessTrade(trade);
    return true;
  }
  if (type_id == future::POSITION_TYPE_ID) {
    auto position = std::make_shared<future::Position>();
    auto base = std::static_pointer_cast<future::PositionBase>(position);
    bs.Deserialize(*base, buffers);
    auto ins_node = md::GetInstrumentNode(position->Symbol(), m_db);
    position->ins_pointer = ins_node;
    auto node = m_db->GetNode<future::Position>(position->GetKey());

    if (node && node->Latest()) {
      for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
             &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
        (position.get()->*p).his_position_details = (node->Latest().get()->*p).his_position_details;
        (position.get()->*p).today_position_details = (node->Latest().get()->*p).today_position_details;
      }
    }
    m_db->ReplaceRecord(position);
    return true;
  }
  if (type_id == future::POSITION_DETAIL_TYPE_ID) {
    auto details =
      std::make_shared<std::pair<std::string, std::vector<std::shared_ptr<future::PositionDetailChange>>>>();
    bs.Deserialize(*details, buffers);
    FCASSERT(!details->first.empty());
    FCASSERT(details->second.size() == 4);
    FCASSERT(nullptr != m_db->GetNode<future::Position>(details->first));
    m_db->ReplaceRecord<future::Position>(details->first, [=](std::shared_ptr<future::Position> base) {
      future::PositionDetailCalculator::CalcPositionDetailByChange(base, details->second);
    });
    return true;
  }
  if (type_id == future::ACCOUNT_TYPE_ID) {
    auto account = std::make_shared<future::Account>();
    auto base = std::static_pointer_cast<future::AccountBase>(account);
    bs.Deserialize(*base, buffers);
    m_db->ReplaceRecord(account);
    return true;
  }
  if (type_id == future::RATE_TYPE_ID) {
    auto rate = std::make_shared<future::Rate>();
    auto base = std::static_pointer_cast<future::RateBase>(rate);
    bs.Deserialize(*base, buffers);
    m_db->ReplaceRecord(rate);
    return true;
  }
  if (type_id == future::BANK_TYPE_ID) {
    auto bank = std::make_shared<future::Bank>();
    bs.Deserialize(*bank, buffers);
    m_db->ReplaceRecord(bank);
    return true;
  }
  if (type_id == future::TRANSFER_TYPE_ID) {
    auto transfer = std::make_shared<future::TransferLog>();
    bs.Deserialize(*transfer, buffers);
    m_db->ReplaceRecord(transfer);
    return true;
  }
  if (type_id == future::BANK_BALANCE_TYPE_ID) {
    auto balance = std::make_shared<future::BankBalance>();
    bs.Deserialize(*balance, buffers);
    m_db->ReplaceRecord(balance);
    return true;
  }
  if (type_id == future::NOTICE_TYPE_ID) {
    auto notice = std::make_shared<future::Notice>();
    bs.Deserialize(*notice, buffers);
    m_db->ReplaceRecord(notice);
    return true;
  }
  if (type_id == future::EXEC_ORDER_TYPE_ID) {
    auto exec = std::make_shared<future::ExecOrder>();
    bs.Deserialize(*exec, buffers);
    auto ins_node = md::GetInstrumentNode(exec->Symbol(), m_db);
    exec->ins_pointer = ins_node;
    m_db->ReplaceRecord(exec);
    return true;
  }
  if (type_id == future::SELF_CLOSE_TYPE_ID) {
    auto self = std::make_shared<future::OptionSelfClose>();
    bs.Deserialize(*self, buffers);
    auto ins_node = m_db->GetNode<md::Instrument>(self->Symbol());
    if (ins_node)
      self->ins_pointer = ins_node;
    m_db->ReplaceRecord(self);
    return true;
  }
  if (type_id == future::QUOTE_TYPE_ID) {
    auto quote = std::make_shared<future::Quote>();
    bs.Deserialize(*quote, buffers);
    m_msg_processor->ProcessQuote(quote);
    return true;
  }
  if (type_id == future::CONDITION_ORDER_TYPE_ID) {
    auto cond = std::make_shared<future::ConditionOrder>();
    bs.Deserialize(*cond, buffers);
    m_msg_processor->ProcessConditionOrder(cond);
    return true;
  }
  return false;
}
