void ProcessBinarySerializer::DefineStruct(future::ReqLogin& item) {
  DefineStruct(static_cast<future::FutureCommand&>(item));
  AddItem(item.backend);
  AddItem(item.user_id);
  AddItem(item.async_login);
  AddItem(item.entrust_way);
  AddItem(item.license_file_addr);
  AddItem(item.broker);
  AddItem(item.client_ip);
  AddItem(item.client_port);
  AddItem(item.client_system_info);
  AddItem(item.client_app_id);
  AddItem(item.client_mac_address);
  AddItem(item.login_remark);
  AddItem(item.otg.front_url);
  AddItem(item.otg.bid);
  AddItem(item.otg.access_token);
  AddItem(item.otg.user_name);
  AddItem(item.xuntou.sub_user_type);
  AddItem(item.yida.group_id);
  AddItem(item.replay_flow_file_name);
  AddItem(item.mock_api.enable);
  AddItem(item.mock_api.pre_stored_quantity);
  AddItem(item.mock_api.trade_ratio);
  AddItem(item.user_desc);

  std::string cipher_passwd, cipher_pin;
  if (IsSerialize()) {
    fclib::AESEncrypt(&cipher_passwd, item.password, fclib::future::GetEncryptKey(item.user_key));
    fclib::AESEncrypt(&cipher_pin, item.pin, fclib::future::GetEncryptKey(item.user_key));
    AddItem(cipher_passwd);
    AddItem(cipher_pin);
    if (!item.submit_user_system_info)
      item.submit_user_system_info = std::make_shared<fclib::future::SubmitUserSystemInfo>(item.user_key);
    AddItem(*(item.submit_user_system_info));
  } else {
    AddItem(cipher_passwd);
    AddItem(cipher_pin);
    fclib::AESDecrypt(&item.password, cipher_passwd, fclib::future::GetEncryptKey(item.user_key));
    fclib::AESDecrypt(&item.pin, cipher_pin, fclib::future::GetEncryptKey(item.user_key));
    auto submit_user_system_info = std::make_shared<fclib::future::SubmitUserSystemInfo>(item.user_key);
    AddItem(*submit_user_system_info);
    if (!submit_user_system_info->client_system_info.empty())
      item.submit_user_system_info = submit_user_system_info;
  }
}

