    }
    case future::SetCommissionRate::AID: {
      return bs.Serialize(static_cast<BinaryTypeID>(future::SetCommissionRate::AID),
        *(std::static_pointer_cast<future::SetCommissionRate>(command)));
    }
    case future::ResetSimUser::AID: {
      return bs.Serialize(static_cast<BinaryTypeID>(future::ResetSimUser::AID),
        *(std::static_pointer_cast<future::ResetSimUser>(command)));
    }
    case future::SubmitUserSystemInfo::AID: {
      return bs.Serialize(static_cast<BinaryTypeID>(future::SubmitUserSystemInfo::AID),
        *(std::static_pointer_cast<future::SubmitUserSystemInfo>(command)));
    }
    case future::ReqSetMemo::AID: {
      return bs.Serialize(
        static_cast<BinaryTypeID>(future::ReqSetMemo::AID), *(std::static_pointer_cast<future::ReqSetMemo>(command)));
    }
    case future::QueryCFMMCToken::AID: {
