/*******************************************************************************
 * @file process_message_queue_impl.cpp
 * @brief 进程间通讯 - 消息队列
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "process_message_queue_impl.h"

#include <thread>
#include <utility>
#include <vector>
#include <string>
#include <memory>
#include "fclib/utils/fcassert.h"

namespace fclib {
#ifdef _WIN32
void StringToWString(const std::string& origin_string, UINT code_page, std::wstring* target_wstring);
#endif

static constexpr std::size_t TRY_SEND_INTERVAL = 10;  // 尝试发送间隔(毫秒)

ProcessMessageQueueImpl::ProcessMessageQueueImpl(
  boost::asio::io_context* io_context, const std::string& name, structlog::Logger& logger)
  : m_io_context(io_context)
  , m_mq_name(name)
  , m_logger(logger.With("process_message_queue", reinterpret_cast<int64_t>(this)).With("name", m_mq_name).Clone()) {}

void ProcessMessageQueueImpl::SendBuffer(const std::vector<BinaryBufferType>& buffer) {
  m_waiting_deque.insert(m_waiting_deque.end(), buffer.begin(), buffer.end());
  TrySend();
}

bool ProcessMessageQueueImpl::IsSending() {
  return !m_waiting_deque.empty();
}

bool ProcessMessageQueueImpl::TryReceive(std::vector<BinaryBufferType>* buffer, std::string* exception /*= nullptr*/) {
  if (nullptr == buffer)
    return false;
  unsigned int priority = 0;
  boost::interprocess::message_queue::size_type recvd_size = 0;
  while (true) {
    try {
      BinaryBufferType buf = {};
      if (!m_mq_ptr->try_receive(buf.data(), buf.size(), recvd_size, priority)) {
        return false;
      }
      m_received_cache.emplace_back(std::move(buf));
      if (BinaryDecoder::DecodeVectorSize(m_received_cache.at(0)) == m_received_cache.size())
        break;
    } catch (const std::exception& ex) {
      auto errmsg = LocalToUtf8(ex.what());
      if (exception)
        *exception = errmsg;
      m_logger.With("fun", "TryReceive").With("errmsg", errmsg).Error("try receive error");
      return false;
    }
  }
  FCASSERT(!m_received_cache.empty());
  *buffer = m_received_cache;
  m_received_cache.clear();
  return true;
}

bool ProcessMessageQueueImpl::TimedReceive(int timer, std::vector<BinaryBufferType>* buffer, std::string* exception) {
  buffer->clear();
  m_timer.Reset(std::chrono::milliseconds(timer));
  std::string t_exception;
  while (!m_timer.IsExpired()) {
    auto receive_success = TryReceive(buffer, &t_exception);
    if (receive_success) {
      return true;
    }
    if (!receive_success && !t_exception.empty()) {
      if (exception)
        *exception = t_exception;
      return false;
    }
    boost::this_thread::sleep_for(boost::chrono::milliseconds(10));
  }
  return false;
}

bool ProcessMessageQueueImpl::Empty() {
  return m_mq_ptr->get_num_msg() == 0;
}

void ProcessMessageQueueImpl::CleanUp() {
  m_logger.Info("clean up");
  if (m_max_count > 0) {
    if (!m_mq_name.empty()) {
#ifdef _WIN32
      std::wstring utf16_mq_name;
      StringToWString(m_mq_name, CP_UTF8, &utf16_mq_name);
      boost::interprocess::message_queue::remove(utf16_mq_name.c_str());
#else
      boost::interprocess::message_queue::remove(m_mq_name.c_str());
#endif
    }
  }
  if (m_send_timer) {
    m_send_timer->cancel();
  }
}

bool ProcessMessageQueueImpl::Create(int max_count) {
  m_logger.With("max_count", max_count).Info("Create");
  if (max_count <= 0)
    return false;
  m_max_count = max_count;
  std::replace(m_mq_name.begin(), m_mq_name.end(), '|', '_');
  m_send_timer = std::make_shared<boost::asio::deadline_timer>(*m_io_context);
  try {
#ifdef _WIN32
    std::wstring utf16_mq_name;
    StringToWString(m_mq_name, CP_UTF8, &utf16_mq_name);
    boost::interprocess::message_queue::remove(utf16_mq_name.c_str());
    m_mq_ptr = std::make_shared<boost::interprocess::message_queue>(
      boost::interprocess::create_only, utf16_mq_name.c_str(), m_max_count, BINARY_MAX_MESSAGE_SIZE);
#else
    boost::interprocess::message_queue::remove(m_mq_name.c_str());
    m_mq_ptr = std::make_shared<boost::interprocess::message_queue>(
      boost::interprocess::create_only, m_mq_name.c_str(), m_max_count, BINARY_MAX_MESSAGE_SIZE);
#endif
    return true;
  } catch (std::exception& ex) {
    m_logger.With("fun", "Create")
      .With("mq_name", m_mq_name)
      .With("errmsg", LocalToUtf8(ex.what()))
      .Error("create message queue exception");
    return false;
  }
}

bool ProcessMessageQueueImpl::Open() {
  m_logger.Info("Open");
  std::replace(m_mq_name.begin(), m_mq_name.end(), '|', '_');
  m_send_timer = std::make_shared<boost::asio::deadline_timer>(*m_io_context);
  try {
#ifdef _WIN32
    std::wstring utf16_mq_name;
    StringToWString(m_mq_name, CP_UTF8, &utf16_mq_name);
    m_mq_ptr =
      std::make_shared<boost::interprocess::message_queue>(boost::interprocess::open_only, utf16_mq_name.c_str());
#else
    m_mq_ptr = std::make_shared<boost::interprocess::message_queue>(boost::interprocess::open_only, m_mq_name.c_str());
#endif
    return true;
  } catch (const std::exception& ex) {
    m_logger.With("fun", "Open")
      .With("mq_name", m_mq_name)
      .With("errmsg", LocalToUtf8(ex.what()))
      .Error("open message queue exception");
    return false;
  }
}

void ProcessMessageQueueImpl::TrySend() {
  if (m_waiting_deque.empty())
    return;
  auto avail_capacity = m_mq_ptr->get_max_msg() - m_mq_ptr->get_num_msg();
  try {
    unsigned int priority = 0;
    while (!m_waiting_deque.empty() && avail_capacity > 0) {
      auto send_success = m_mq_ptr->try_send(m_waiting_deque.front().data(), m_waiting_deque.front().size(), priority);
      FCASSERT(send_success);
      m_waiting_deque.pop_front();
      --avail_capacity;
    }
  } catch (std::exception& ex) {
    auto errmsg = LocalToUtf8(ex.what());
    m_logger.With("fun", "TrySend").With("errmsg", errmsg).Error("try send exception");
    return;
  }
  if (!m_waiting_deque.empty()) {
    m_send_timer->expires_from_now(boost::posix_time::milliseconds(TRY_SEND_INTERVAL));
    m_send_timer->async_wait([this](const boost::system::error_code& ec) {
      if (!ec)
        TrySend();
    });
  }
}
