TradeProcessManager::TradeProcessManager(boost::asio::io_context* io_context, std::shared_ptr<TqApiNodeDb> db,
  const FutureServiceOptions& options, structlog::Logger& logger)
  : m_io_context(io_context)
  , m_db(db)
  , m_options(options)
  , m_logger(logger.With("trade_process_manager", reinterpret_cast<int64_t>(this)).Clone()) {
  m_pid = std::to_string(GetCurrentPID());
  m_command_manager = std::make_shared<CommandManager>();
  m_message_manager = std::make_shared<MessageManager>(m_db, m_command_manager, m_child_command_manager, m_logger);
}

bool TradeProcessManager::Init() {
  m_logger.Info("Init");
  if (m_cleaned) {
    m_logger.With("fun", "Init")
      .With("errmsg", "trade_process_manager cleaned")
      .Error("trade_process_manager init fail");
    return false;
  }
  return true;
}

int TradeProcessManager::RunOnce() {
  if (m_cleaned)
    return 0;
  int ret = 0;
  for (auto it = m_childs.begin(); it != m_childs.end(); /* no increment here */) {
    auto& user_key = it->first;
    auto& child = it->second;
    auto mq_ptr = child->GetOutMessageQueue();
    if (nullptr == mq_ptr) {
      ++it;
      continue;
    }
    if (!child->IsRunning() && mq_ptr->Empty()) {
      m_logger.With("fun", "RunOnce").With("user_key", user_key).Error("child process not running");
      auto req = m_command_manager->Update("ReqLogin|" + user_key);
      if (req && req->status != UserCommand::Status::kFinished) {
        SetCommandFinished(req, -1, u8"fclib: 进程异常退出");
      }
      auto login_node = m_db->GetNode<LoginContent>(user_key);
      if (login_node && login_node->Latest()->session_status != future::SessionStatus::kDisconnected
        && login_node->Latest()->status_msg.empty()) {
        m_db->ReplaceRecord<LoginContent>(user_key, [](std::shared_ptr<LoginContent> l) {
          l->session_status = future::SessionStatus::kDisconnected;
          l->status_msg = u8"fclib: 进程异常退出";
        });
      }
      child->CleanUp();
      m_child_command_manager.erase(user_key);
      it = m_childs.erase(it);
      continue;
    }
    ++it;
    int n = 0;
    // 每个 child 最多处理 5000 个数据包
    while (n < 5000) {
      std::vector<BinaryBufferType> buffers;
      std::string exception;
      ++n;
      if (mq_ptr->TryReceive(&buffers, &exception)) {
        m_message_manager->ProcessBuffer(user_key, buffers);
        ++ret;
        continue;
      }
      if (!exception.empty())
        m_logger.With("fun", "RunOnce").With("errmsg", exception).Error("RunOnce Error");
      break;
    }
  }
  for (const auto& command : m_message_manager->m_commands) {
    ExecuteCommand(command);
  }
  m_message_manager->m_commands.clear();
  if (m_child_process_map.empty())
    return ret;
  for (auto it = m_child_process_map.begin(); it != m_child_process_map.end();) {
    auto start_time = it->second;
    auto now = NowAsEpochNano();
    if (now - start_time < 180 * 1000000000LL) {  // 180 秒内的进程不清理
      ++it;
      continue;
    }
    it = m_child_process_map.erase(it);
  }
  return ret;
}

void TradeProcessManager::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_cleaned) {
    SetCommandFinished(command, -1, u8"管理器已注销");
    return;
  }
  auto request = std::static_pointer_cast<FutureCommand>(command);
  m_logger.With("aid", command->aid).With("command_id", command->command_id).Info("ExecuteCommand");
  m_command_manager->Store(command);
  if (command->aid == ReqLogin::AID) {
    auto t = std::static_pointer_cast<ReqLogin>(command);
    if (t->backend == BackEnd::kCtpReg) {
      ProcessRegister(t);
      return;
    }
    ProcessLogin(command);
    return;
  }

  // 目前改密码柜台仅有 Ctp / XOne / X1
  if (command->aid == ChangePasswordBeforeLogin::AID) {
    auto req = std::static_pointer_cast<ChangePasswordBeforeLogin>(command);
    if (req->req_login
      && (req->req_login->backend == BackEnd::kCtp || req->req_login->backend == BackEnd::kXOne
        || req->req_login->backend == BackEnd::kX1 || req->req_login->backend == BackEnd::kCtpSopt
        || req->req_login->backend == BackEnd::kDtp || req->req_login->backend == BackEnd::kFemas
        || req->req_login->backend == BackEnd::kTap)) {
      ProcessLogin(command);
    } else {
      SetCommandFinished(command, -1, u8"该柜台不支持登录前修改密码");
    }
    return;
  }
  auto iter = m_child_command_manager.find(request->user_key);
  if (iter != m_child_command_manager.end()) {
    iter->second->ProcessCommand(command);
    return;
  }
  SetCommandFinished(command, -1, u8"账户未登录");
  return;
}

void TradeProcessManager::ResponseCommand() {
  m_command_manager->CommitResponse();
}

std::shared_ptr<TradeProcess> TradeProcessManager::GetChildProcess(const std::string& user_key) {
  auto iter = m_childs.find(user_key);
  if (iter != m_childs.end()) {
    return iter->second;
  }
  return nullptr;
}

void TradeProcessManager::CleanUp() {
  m_logger.Info("clean up");
  if (m_cleaned)
    return;
  m_cleaned = true;
  m_child_command_manager.clear();
  m_childs.clear();
}

void TradeProcessManager::ProcessLogin(std::shared_ptr<UserCommand> command) {
  command->status = UserCommand::Status::kStarted;
  auto request = std::static_pointer_cast<FutureCommand>(m_command_manager->Update(command));
  FCASSERT(request);
  auto iter = m_childs.find(request->user_key);
  if (iter != m_childs.end()) {
    if (auto child = iter->second)
      child->CleanUp();
    m_childs.erase(request->user_key);
    m_child_command_manager.erase(request->user_key);
  }
  auto backend = BackEnd::kCtp;
  if (command->aid == ReqLogin::AID) {
    auto t = std::static_pointer_cast<ReqLogin>(command);
    FCASSERT(t);
    backend = t->backend;
  } else {
    auto t = std::static_pointer_cast<ChangePasswordBeforeLogin>(command);
    FCASSERT(t);
    backend = t->req_login->backend;
  }
  auto child = std::make_shared<TradeProcess>(m_io_context, request->user_key, m_pid, m_options, m_logger);
  child->ExecuteCommand(request);
  m_childs[request->user_key] = child;
  m_child_command_manager[request->user_key] =
    std::make_shared<ProcessCommandManager>(request->user_key, backend, child, m_db, m_command_manager, m_logger);
  if (command->aid == ReqLogin::AID) {
    auto t = std::static_pointer_cast<ReqLogin>(command);
    FCASSERT(t);
    m_command_manager->SetCommandId(request, t->GetKey());
    return;
  }
  if (command->aid == ChangePasswordBeforeLogin::AID) {
    auto t = std::static_pointer_cast<ChangePasswordBeforeLogin>(command);
    FCASSERT(t);
    m_command_manager->SetCommandId(request, t->GetKey());
    return;
  }
}

void TradeProcessManager::ProcessRegister(std::shared_ptr<future::ReqLogin> command) {
  std::string options_str;
  ProcessJsonSerializer ss;
  ss.FromVar(m_options);
  ss.ToString(&options_str);
  options_str = base64url_encode(options_str.c_str(), options_str.size());

  std::string req_str;
  CommandSerializer cmd_ss;
  cmd_ss.FromVar(*command);
  cmd_ss.ToString(&req_str);
  req_str = base64url_encode(req_str.c_str(), req_str.size());
  auto run_directory = m_options.run_directory.empty() ? "" : (m_options.run_directory + "/");
  std::string child = run_directory + "fclib_ctp_reg/fclib_ctp_reg";
#ifdef _WIN32
  child += ".exe";
#endif
  try {
#ifdef _WIN32
    std::filesystem::path p = std::filesystem::u8path(child);
    auto process_ptr = std::make_shared<boost::process::child>(
      p.wstring(), ::boost::process::windows::hide, command->user_key, m_pid, options_str, req_str);
#else
    auto process_ptr =
      std::make_shared<boost::process::child>(child.c_str(), command->user_key, m_pid, options_str, req_str);
#endif
    if (nullptr == process_ptr) {
      std::string msg =
        u8"fclib: " + GetBackendChineseName(command->backend) + u8"启动进程失败(" + command->user_key + u8")";
      m_logger.With("fun", "ProcessRegister").With("errmsg", msg).Error("start child process fail");
      SetCommandFinished(command, -1, msg);
      return;
    }
    bool running = process_ptr->running();
    if (!running) {
      auto native_exit_code = process_ptr->native_exit_code();
      if (native_exit_code != 0)
        m_logger.With("fun", "ProcessRegister")
          .With("exit_code", process_ptr->exit_code())
          .With("native_exit_code", native_exit_code)
          .Error("start child process fail");
      SetCommandFinished(command, native_exit_code);
      return;
    }
    m_child_process_map[process_ptr] = NowAsEpochNano();
  } catch (std::exception& ex) {
    auto errmsg = LocalToUtf8(ex.what());
    m_logger.With("fun", "ProcessRegister").With("errmsg", errmsg).Error("start child process fail");
    SetCommandFinished(command, -1, errmsg);
    return;
  }
  SetCommandFinished(command);
}

}  // namespace fclib

