namespace fclib {
ProcessCommandManager::ProcessCommandManager(const std::string& user_key, const future::BackEnd& backend,
  std::shared_ptr<TradeProcess> trade_process, std::shared_ptr<TqApiNodeDb> db,
  std::shared_ptr<CommandManager> command_manager, structlog::Logger& logger)
  : m_user_key(user_key)
  , m_backend(backend)
  , m_trade_process(trade_process)
  , m_db(db)
  , m_command_manager(command_manager)
  , m_logger(
      logger.With("process_command_manager", reinterpret_cast<int64_t>(this)).With("user_key", m_user_key).Clone()) {
  FCASSERT(m_trade_process);
  m_login_node = m_db->GetNode<future::LoginContent>(m_user_key);
  if (m_login_node && m_login_node->Latest()->max_order_ref >= 0) {
    m_order_ref = m_login_node->Latest()->max_order_ref;
    return;
  }
  m_login_view = m_db->CreateView<future::LoginContent>([=](std::shared_ptr<const future::LoginContent> login) {
    return login->user_key == m_user_key;
  });
  m_login_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<future::LoginNode> node, bool) {
      if (m_login_node) {
        m_login_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (node->Latest()->max_order_ref >= 0) {
        m_login_node = node;
        m_order_ref = m_login_node->Latest()->max_order_ref;
      }
    });
}

void ProcessCommandManager::SetFemas2MaxOrderId(const std::string& max_order_id) {
  if (!m_femas_order_ref_helper) {
    m_femas_max_order_ref = max_order_id;
    m_femas_order_ref_helper = std::make_shared<FemasOrderRefHelper>(max_order_id);
    m_logger.With("max_order_id", max_order_id).Info("SetFemas2MaxOrderId");
    return;
  }
  if (m_femas_max_order_ref < max_order_id) {
    m_femas_max_order_ref = max_order_id;
    m_femas_order_ref_helper = std::make_shared<FemasOrderRefHelper>(max_order_id);
    m_logger.With("max_order_id", max_order_id).Info("SetFemas2MaxOrderId");
  }
}

void ProcessCommandManager::ProcessCommand(std::shared_ptr<UserCommand> command) {
  switch (command->aid) {
    case future::InsertOrder::AID: {
      auto req = std::static_pointer_cast<future::InsertOrder>(command);
      if (req->hedge_flag == future::OrderHedgeFlag::kCovered && m_backend != future::BackEnd::kCtpSopt) {
        SetCommandFinished(req, -1, u8"只有 CtpSopt 股票期权柜台支持备兑下单");
        return;
      }
      ProcessInsertOrder(command);
      break;
    }
    case future::CancelOrder::AID: {
      ProcessCancelOrder(command);
      break;
    }
    case future::QuerySettlementInfoConfirm::AID: {
      ProcessCommandT<future::QuerySettlementInfoConfirm>(command);
      break;
    }
    case future::ConfirmSettlementInfo::AID: {
      ProcessCommandT<future::ConfirmSettlementInfo>(command);
      break;
    }
    case future::QuerySettlementInfo::AID: {
      ProcessCommandT<future::QuerySettlementInfo>(command);
      break;
    }
    case future::ChangePassword::AID: {
      ProcessCommandT<future::ChangePassword>(command);
      break;
    }
    case future::InsertExecOrder::AID: {
      ProcessInsertExecOrder(command);
      break;
    }
    case future::CancelExecOrder::AID: {
      ProcessCommandT<future::CancelExecOrder>(command);
      break;
    }
    case future::TransferMoney::AID: {
      ProcessCommandT<future::TransferMoney>(command);
      break;
    }
    case future::QueryTransferLog::AID: {
      ProcessCommandT<future::QueryTransferLog>(command);
      break;
    }
    case future::QueryMarginRate::AID: {
      ProcessCommandT<future::QueryMarginRate>(command);
      break;
    }
    case future::QueryCommissionRate::AID: {
      ProcessCommandT<future::QueryCommissionRate>(command);
      break;
    }
    case future::QueryTradingAccount::AID: {
      ProcessCommandT<future::QueryTradingAccount>(command);
      break;
    }
    case future::QueryInvestorPosition::AID: {
