      break;
    }
    case future::PositionCombInsert::AID: {
      ProcessPositionCombInsert(command);
      break;
    }
    case future::SetMarginRate::AID: {
      ProcessCommandT<future::SetMarginRate>(command);
      break;
    }
    case future::SetCommissionRate::AID: {
      ProcessCommandT<future::SetCommissionRate>(command);
      break;
    }
    case future::ResetSimUser::AID: {
      ProcessCommandT<future::ResetSimUser>(command);
      break;
