      break;
    }
    case future::QueryLockPosition::AID: {
      ProcessCommandT<future::QueryLockPosition>(command);
      break;
    }
    case future::ReqLockPosition::AID: {
      ProcessCommandT<future::ReqLockPosition>(command);
      break;
    }
    case future::ReqFlushLog::AID: {
      ProcessCommandT<future::ReqFlushLog>(command);
      SetCommandFinished(command);
      break;
    }
    case future::ReqSaveNodeDb::AID: {
      fclib::future::NodeSerializer nss;
      std::filesystem::path path = std::filesystem::u8path(m_trade_process->m_options.log_directory);
      nss.FromVar(*m_db);
      nss.ToFile(path / "node_db.json");
      SetCommandFinished(command);
      break;
    }
    default: {
      SetCommandFinished(command, 1, u8"暂不支持本指令");
      m_logger.With("aid", command->aid).Error("unsupported command");
      FCASSERT(false);
      break;
    }
  }
