template <typename T>
void ProcessCommandManager::ProcessCommandT(std::shared_ptr<UserCommand> command) {
  command->status = UserCommand::Status::kStarted;
  auto request = std::static_pointer_cast<T>(m_command_manager->Update(command));
  FCASSERT(request);
  if (nullptr == m_login_node || nullptr == m_login_node->Latest()) {
    SetCommandFinished(command, -1, u8"账户未登录");
    return;
  }
  // command_id 编号
  if (request->command_id.empty())
    request->command_id = std::to_string(++m_command_id);
  m_trade_process->ExecuteCommand(command);
  m_command_manager->SetCommandId(command, request->GetKey());
}

