void ProcessCommandManager::ProcessInsertExecOrder(std::shared_ptr<UserCommand> command) {
  command->status = UserCommand::Status::kStarted;
  auto request = std::static_pointer_cast<future::InsertExecOrder>(m_command_manager->Update(command));
  FCASSERT(request);
  if (nullptr == m_login_node || nullptr == m_login_node->Latest()) {
    SetCommandFinished(command, -1, u8"账户未登录");
    return;
  }
  // command_id 编号
  if (request->command_id.empty())
    request->command_id = std::to_string(++m_command_id);
  // exec_order_ref 和 exec_order_id 编号
  int64_t increment_id = (++m_order_ref) * 100;
  auto exec_order_ref = request->exec_order_ref != 0 ? request->exec_order_ref : increment_id;
  request->exec_order_ref = static_cast<int>(exec_order_ref);
  request->exec_order_id = std::to_string(exec_order_ref) + "|" + std::to_string(m_login_node->Latest()->session_id)
    + "|" + std::to_string(m_login_node->Latest()->front_id);
  // 飞马次席 order_id 必须字符递增且必须为数字
  if (m_backend == future::BackEnd::kFemas2) {
    request->exec_order_id = m_femas_order_ref_helper->GetNextOrderRef();
  } else if (m_backend == future::BackEnd::kUFX) {
    request->exec_order_id = std::to_string(exec_order_ref) + "|" + std::to_string(m_login_node->Latest()->session_id);
  }
  m_trade_process->ExecuteCommand(command);
  m_command_manager->SetCommandId(command, request->GetKey());
}

void ProcessCommandManager::ProcessInsertQuote(std::shared_ptr<UserCommand> command) {
  command->status = UserCommand::Status::kStarted;
  auto request = std::static_pointer_cast<future::InsertQuote>(m_command_manager->Update(command));
  FCASSERT(request);
  if (nullptr == m_login_node || nullptr == m_login_node->Latest()) {
    SetCommandFinished(command, -1, u8"账户未登录");
    return;
  }
  // command_id 编号
  if (request->command_id.empty())
    request->command_id = std::to_string(++m_command_id);
  // quote_ref / ask_ref / bid_ref 和 quote_id 编号
  int64_t increment_quote_id = (++m_order_ref) * 100 + request->unit_id;
  int64_t increment_ask_id = (++m_order_ref) * 100 + request->unit_id;
  int64_t increment_bid_id = (++m_order_ref) * 100 + request->unit_id;
  auto quote_ref = request->quote_ref != 0 ? request->quote_ref : increment_quote_id;
  request->ask_ref = request->ask_ref != 0 ? request->ask_ref : static_cast<int>(increment_ask_id);
  request->bid_ref = request->bid_ref != 0 ? request->bid_ref : static_cast<int>(increment_bid_id);
  request->quote_ref = static_cast<int>(quote_ref);
  request->quote_id = std::to_string(quote_ref) + "|" + std::to_string(m_login_node->Latest()->session_id) + "|"
    + std::to_string(m_login_node->Latest()->front_id);
  // 飞马次席 quote_id 必须字符递增且必须为数字
  if (m_backend == future::BackEnd::kFemas2) {
    request->quote_id = m_femas_order_ref_helper->GetNextOrderRef();
    request->command_id += "_ask_ref_";
    request->command_id += m_femas_order_ref_helper->GetNextOrderRef();
    request->command_id += "_bid_ref_";
    request->command_id += m_femas_order_ref_helper->GetNextOrderRef();
  }
  if (m_backend == future::BackEnd::kYiDa) {
    request->quote_id =
      std::to_string(request->quote_ref) + "|" + std::to_string(m_trade_process->m_req_login->yida.group_id);
  }
  m_trade_process->ExecuteCommand(command);
  m_command_manager->SetCommandId(command, request->GetKey());
}

