void ProcessCommandManager::GetOrderIdOrderRef(std::shared_ptr<future::InsertOrder> request) {
  // order_ref 和 order_id 编号
  int64_t increment_id = (++m_order_ref) * 100 + request->unit_id;
  auto order_ref = request->order_ref != 0 ? request->order_ref : increment_id;
  request->order_ref = static_cast<int>(order_ref);
  // 默认CTP
  request->order_id = std::to_string(request->order_ref) + "|" + std::to_string(m_login_node->Latest()->session_id)
    + "|" + std::to_string(m_login_node->Latest()->front_id);
  // 飞马次席 order_id 必须字符递增且必须为数字
  if (m_backend == future::BackEnd::kFemas2) {
    request->order_id = m_femas_order_ref_helper->GetNextOrderRef();
  } else if (m_backend == future::BackEnd::kXuntou) {
    request->order_id =
      "fclib" + std::to_string(request->order_ref) + std::to_string(m_login_node->Latest()->session_id);
  } else if (m_backend == future::BackEnd::kUFX) {
    request->order_id = std::to_string(request->order_ref) + "|" + std::to_string(m_login_node->Latest()->session_id);
  } else if (m_backend == future::BackEnd::kYiDa) {
    request->order_id =
      std::to_string(request->order_ref) + "|" + std::to_string(m_trade_process->m_req_login->yida.group_id);
  } else if (m_backend == future::BackEnd::kDstar) {
    int64_t order_ref_part = static_cast<int64_t>(request->order_ref) * 100000000;
    int64_t session_id_part = m_login_node->Latest()->session_id % 1000000;
    int64_t id = (order_ref_part + session_id_part) * 100 + 11;
    request->order_id = std::to_string(id);
  } else if (m_backend == future::BackEnd::kTap) {
    request->order_id =
      std::to_string(request->order_ref) + "_fclib_" + std::to_string(m_login_node->Latest()->session_id);
  } else if (m_backend == future::BackEnd::kX1) {
    request->order_id = std::to_string(request->order_ref) + "|" + std::to_string(m_login_node->Latest()->session_id);
  } else if (m_backend == future::BackEnd::kOtg) {
    auto unique_id = std::to_string(m_login_node->Latest()->session_id) + "." + std::to_string(++m_order_ref) + "."
      + std::to_string(request->unit_id);
    request->order_id = request->request_id > 0 ? std::to_string(request->request_id) + ".r." + unique_id : unique_id;
  }
}

