std::shared_ptr<ProcessMessageQueue> ProcessMessageQueue::Create(
  boost::asio::io_context* io_context, const std::string& name, int max_count, structlog::Logger& logger) {
  if (name.empty() || max_count < 0)
    return nullptr;
  auto p = std::make_shared<ProcessMessageQueueImpl>(io_context, name, logger);
  if (p->Create(max_count))
    return p;
  return nullptr;
}

std::shared_ptr<ProcessMessageQueue> ProcessMessageQueue::Open(
  boost::asio::io_context* io_context, const std::string& name, structlog::Logger& logger) {
  if (name.empty())
    return nullptr;
  auto p = std::make_shared<ProcessMessageQueueImpl>(io_context, name, logger);
  if (p->Open())
    return p;
  return nullptr;
}
