TradeFuture::TradeFuture(boost::asio::io_context* io_context, const std::string& user_key, const std::string& pid,
  const FutureServiceOptions& options, structlog::Logger& logger)
  : m_io_context(io_context)
  , m_strand(*m_io_context)
  , m_user_key(user_key)
  , m_pid(pid)
  , m_options(options)
  , m_logger(logger.With("trade_future", reinterpret_cast<int64_t>(this)).With("user_key", m_user_key).Clone())
  , m_recv_logger(m_logger.Clone()) {
  m_in_mq_name = m_pid + "_" + m_user_key + "_msg_in";
  m_out_mq_name = m_pid + "_" + m_user_key + "_msg_out";
  m_db = std::make_shared<TqApiNodeDb>(true, 0);
  m_command_tracker = std::make_shared<CommandTracker>();
}

bool TradeFuture::Init() {
  m_logger.Info("Init");
  m_flush_log.store(false);
  if (m_cleaned) {
    m_exit.store(true);
    m_login_fail = true;
    m_logger.With("fun", "Init").With("errmsg", "trade_ctp cleaned").Error("trade_ctp init fail");
    return false;
  }
  m_exit.store(false);
  m_login_fail = false;
  m_md_helper = std::make_shared<md::MdServiceShmHelper>(m_pid, m_logger);
  if (!m_md_helper->Init()) {
    m_logger.With("fun", "Init").With("errmsg", "md helper init").Error("md helper init fail");
    return false;
  }
  CreateFutureService();
  m_in_mq_ptr = ProcessMessageQueue::Open(m_io_context, m_in_mq_name, m_recv_logger);
  m_out_mq_ptr = ProcessMessageQueue::Open(m_io_context, m_out_mq_name, m_logger);
  if (nullptr == m_in_mq_ptr || nullptr == m_out_mq_ptr) {
    m_logger.With("fun", "Init").Error("open message queue exception");
    return false;
  }

  try {
    m_recv_flag.store(true);
    m_recv_thread = std::thread([=]() {
      this->ReceiveBuffers();
    });
  } catch (const std::exception& ex) {
    m_logger.With("fun", "Init").With("errmsg", LocalToUtf8(ex.what())).Error("trade_ctp start ReceiveMsg thread fail");
    return false;
  }

  InitViews();
  return true;
}

char TradeFuture::RunOnce() {
  if (m_exit.load()) {
    CleanUp();
    return 'E';
  }
  m_io_context->poll();
  m_io_context->restart();
  m_service->RunOnce();

#ifdef USE_FEMAS2
  for (const auto& command : std::static_pointer_cast<femas2::Femas2Service>(m_service)->SendBackCommand()) {
    m_out_mq_ptr->SendBuffer(ProcessDataSerialize::CommandToBuffer(command, m_logger));
  }
#endif

  m_db->CommitTransaction();
  m_service->ResponseCommand();
  m_command_tracker->NotifyAll();

  // 用户发起登录失败, 进程退出
  if (!m_out_mq_ptr->IsSending() && m_login_fail) {
    CleanUp();
    return 'E';
  }

  if (m_flush_log.load()) {
    m_flush_log.store(false);
    return 'F';
  }
  return '0';
}

void TradeFuture::CleanUp() {
  m_logger.Info("clean up");
  if (m_cleaned)
    return;
  m_cleaned = true;
  m_recv_flag.store(false);
  if (m_recv_thread.joinable())
    m_recv_thread.join();
  if (m_service)
    m_service->CleanUp();
}

