void TradeFuture::ReceiveBuffers() {
  std::vector<BinaryBufferType> buffers;
  while (m_recv_flag.load()) {
    std::string exception;
    bool flag = m_in_mq_ptr->TimedReceive(100, &buffers, &exception);
    if (!m_recv_flag.load())
      break;
    if (flag) {
      ProcessRecvBuffers(buffers);
      continue;
    }
    if (!exception.empty()) {
      m_recv_logger.With("fun", "ReceiveMsg").With("errmsg", exception).Error("ReceiveMsg exception!");
      break;
    }
  }
}

void TradeFuture::ProcessRecvBuffers(const std::vector<BinaryBufferType>& buffers) {
  if (buffers.empty())
    return;
  if (ProcessBinarySerializer::DeserializeTypeID(buffers.at(0)) == future::EXIT_TYPE_ID) {
    m_exit.store(true);
    return;
  }
  auto command = ProcessDataSerialize::BufferToCommand(m_user_key, buffers, m_recv_logger);
  if (nullptr == command)
    return;
  if (command->aid == ReqFlushLog::AID) {
    m_flush_log.store(true);
    m_recv_logger.Info("flush log");
    return;
  }
  // 主线程处理请求, 保证线程安全
  m_strand.post([this, command]() {
    // 跟踪请求
    m_command_tracker->TrackCommand(command, [this](std::shared_ptr<UserCommand> command) {
      if (command->status != UserCommand::Status::kFinished)
        return;
      m_logger.With("aid", command->aid).With("command_id", command->command_id).Info("TrackCommand finished");
      m_out_mq_ptr->SendBuffer(ProcessDataSerialize::CommandToBuffer(command, m_logger));
      if (command->result_code != 0
        && (command->aid == ReqLogin::AID || command->aid == ChangePasswordBeforeLogin::AID))
        m_login_fail = true;
    });
    m_service->ExecuteCommand(command);
    m_logger.With("aid", command->aid).With("command_id", command->command_id).Info("ExecuteCommand");
  });
}

