/*******************************************************************************
 * @file shm_release.cpp
 * @brief 共享内存回收
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "shm_release.h"

#include <fstream>
#include <string>

#ifdef _WIN32
#include <Windows.h>
#endif  // _WIN32

#include <boost/interprocess/sync/file_lock.hpp>
#include "fclib/utils/fcassert.h"

namespace fclib {
static constexpr int ShmReleaseHour = 24 * 3;
#ifdef _WIN32
void StringToWString(const std::string& origin_string, UINT code_page, std::wstring* target_wstring);
#endif
ShmRelease::ShmRelease(const std::string& config_path, structlog::Logger& logger)
  : m_logger(logger.With("ShmRelease", reinterpret_cast<int64_t>(this)).Clone()) {
  FCASSERT(!config_path.empty());
  m_lock_file = config_path + "/lockfile.txt";

#ifdef BOOST_INTERPROCESS_SHARED_DIR_FUNC
  m_shm_path = std::filesystem::u8path(config_path);
  m_shm_path.append("shm");
#else
  m_shm_path = std::filesystem::path("/dev/shm");
#endif  // BOOST_INTERPROCESS_SHARED_DIR_FUNC

  if (!std::filesystem::exists(m_shm_path)) {
    m_logger.With("m_shm_path", m_shm_path.string()).Error("shm path not exist");
    return;
  }

  std::ofstream outfile;
  std::filesystem::path lock_file_path = std::filesystem::u8path(m_lock_file);
  outfile.open(lock_file_path, std::ios::trunc);
  if (outfile.fail()) {
    m_logger.With("m_lock_file", m_lock_file).Error("failed to create lockfile");
    outfile.close();
    return;
  }
  outfile.close();
  Init();
}

void ShmRelease::Init() {
  try {
#ifdef _WIN32
    std::wstring utf16_lock_file;
    StringToWString(m_lock_file, CP_UTF8, &utf16_lock_file);
    boost::interprocess::file_lock filelock(utf16_lock_file.c_str());
#else
    boost::interprocess::file_lock filelock(m_lock_file.c_str());
#endif
    if (!filelock.try_lock())
      return;
    ReleaseMem();
    filelock.unlock();
  } catch (std::exception& ex) {
    m_logger.With("m_lock_file", m_lock_file).With("ex", GbkToUtf8(ex.what())).Error("failed to lock lockfile");
  }
}

void ShmRelease::ReleaseMem() {
  for (const auto& entry : std::filesystem::directory_iterator(m_shm_path)) {
    if (std::filesystem::is_regular_file(entry)) {
      const auto& filePath = entry.path();
      if (IsFileToDelete(filePath)) {
        std::filesystem::remove(filePath);
      }
    }
  }
}

bool ShmRelease::IsFileToDelete(const std::filesystem::path& path) {
  try {
    // 共享内存名: *_fclib_* / *_msg_in / *_msg_out
    std::string filename = path.filename().string();
    if (filename.find("_fclib_") == std::string::npos && filename.find("_msg_in") == std::string::npos
      && filename.find("_msg_out") == std::string::npos) {
      return false;
    }

    auto current_time = std::chrono::system_clock::now();
    std::filesystem::file_time_type access_file_time = std::filesystem::last_write_time(path);
    auto access_time = std::chrono::time_point_cast<std::chrono::system_clock::duration>(
      access_file_time - std::filesystem::file_time_type::clock::now() + std::chrono::system_clock::now());

    auto elapsed = std::chrono::duration_cast<std::chrono::hours>(current_time - access_time).count();
    return elapsed > ShmReleaseHour;
  } catch (const std::filesystem::filesystem_error& ex) {
    m_logger.With("path", path.string()).With("ex", GbkToUtf8(ex.what())).Error("failed to get file time");
    return false;
  }
}

}  // namespace fclib

