/*******************************************************************************
 * @file process_message_queue.h
 * @brief 进程间通讯 - 消息队列
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_PROCESS_MESSAGE_QUEUE_H
#define FCLIB_PROCESS_MESSAGE_QUEUE_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <memory>
#include <string>
#include <vector>

#include "structlog/structlog.h"
#include "fclib/utils/binary_serialize.h"

namespace boost {
namespace asio {
class io_context;
}  // namespace asio
}  // namespace boost

namespace fclib {
/*
 * 进程间通讯 - 消息队列(无 max_size 限制)
 */
class ProcessMessageQueue {
 public:
  /*
   * 创建消息队列
   *
   * @param io_context: 上下文指针
   * @param name: 队列名称
   * @param max_count: 队列最大容量
   * @param logger: 日志
   */
  static std::shared_ptr<ProcessMessageQueue> Create(
    boost::asio::io_context* io_context, const std::string& name, int max_count, structlog::Logger& logger);

  /*
   * 打开消息队列
   *
   * @param io_context: 上下文指针
   * @param name: 队列名称
   * @param logger: 日志
   */
  static std::shared_ptr<ProcessMessageQueue> Open(
    boost::asio::io_context* io_context, const std::string& name, structlog::Logger& logger);

  virtual ~ProcessMessageQueue() {}

  /*
   * 发送数据流.
   * 将数据流到待发送列表, 会根据队列剩余容量不断尝试发送
   *
   * @param buffers: 数据流
   */
  virtual void SendBuffer(const std::vector<BinaryBufferType>& buffers) = 0;

  /*
   * 待发送数据流是否发送完成
   *
   * @return: true: 未完成, false: 已完成
   */
  virtual bool IsSending() = 0;

  /*
   * 尝试接收数据流
   *
   * @param msg: 数据流结果
   * @param exception: 异常
   *
   * @return: 是否成功接收
   */
  virtual bool TryReceive(std::vector<BinaryBufferType>* buffer, std::string* exception = nullptr) = 0;

  /*
   * 等待接收消息
   * 以 timer(毫秒) 等待接收消息, 等待期间有消息接收到, 返回true, 否则超时返回 false.
   *
   * @param timer: 定时时间(ms)
   * @param msg: 消息结果
   * @param exception: 异常
   *
   * @return: 是否成功接收
   */
  virtual bool TimedReceive(int timer, std::vector<BinaryBufferType>* buffer, std::string* exception = nullptr) = 0;

  /*
   * 检查队列是否为空
   * @return: 队列为空返回 true
   */
  virtual bool Empty() = 0;

  /*
   * 清理
   */
  virtual void CleanUp() = 0;
};
}  // namespace fclib

#endif  // FCLIB_PROCESS_MESSAGE_QUEUE_H

