/*******************************************************************************
 * @file comb_quote_calc_impl.cpp
 * @brief 自定义组合行情计算器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "comb_quote_calc_impl.h"

#include <fclib/utils/fcassert.h>
#include <utility>
#include <string>
#include <algorithm>
#include <memory>
#include <map>

namespace fclib {
namespace extension {
CombQuoteCalcImpl::CombQuoteCalcImpl(std::shared_ptr<fclib::TqApi> api) {
  m_tq_api = api;
  m_ins_view = m_tq_api->DataDb()->CreateView<md::Instrument>([=](std::shared_ptr<const md::Instrument> ins) {
    return m_single_to_comb_map.find(ins->GetKey()) != m_single_to_comb_map.end();
  });

  m_ins_view->AfterCommit("CombQuoteCalcImpl", [this](std::shared_ptr<md::InstrumentNode> ins, bool is_last) {
    if (is_last) {
      // 一组最后一个变动 更新组合行情
      UpdateCombQuote();
      m_changed_comb.clear();
    } else {
      // 暂存变动的组合行情
      for (auto& bind_comb : m_single_to_comb_map[ins->GetKey()]) {
        m_changed_comb.insert(bind_comb);
      }
    }
  });
}

void CombQuoteCalcImpl::SubscribeCusComb(
  std::shared_ptr<md::InstrumentNode> comb_ins, std::map<std::shared_ptr<md::InstrumentNode>, int> vweight) {
  if (!comb_ins) {
    return;
  }
  // 存入下单权重
  m_comb_vweight[comb_ins] = vweight;
  // 存入单腿和组合的对应关系
  for (const auto& [leg_node, _] : comb_ins->Latest()->instrument_base->weight) {
    m_single_to_comb_map[leg_node->GetKey()].insert(comb_ins);
  }
  if (m_comb_cnt.find(comb_ins) == m_comb_cnt.end()) {
    // 首次订阅刷新一下
    m_comb_cnt[comb_ins] = 1;
    UpdateCombQuote(comb_ins);
  } else {
    m_comb_cnt[comb_ins]++;
  }
}

void CombQuoteCalcImpl::UnSubscribeCusComb(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (!ins_node || m_comb_cnt.find(ins_node) == m_comb_cnt.end()) {
    return;
  }
  // 订阅合约数为0 退订
  if (--m_comb_cnt[ins_node] == 0) {
    m_comb_to_comb_map.erase(ins_node);
    m_comb_vweight.erase(ins_node);
    // 遍历单腿合约 删除对应关系
    for (auto& [k, v] : ins_node->Latest()->instrument_base->weight) {
      auto sub_ins_key = k->GetKey();
      m_single_to_comb_map[sub_ins_key].erase(ins_node);
      // 如果单腿合约不再有任何对应关系 删除
      if (m_single_to_comb_map[sub_ins_key].empty()) {
        m_single_to_comb_map.erase(sub_ins_key);
      }
    }
    m_comb_cnt.erase(ins_node);
  }
}

void CombQuoteCalcImpl::SetCallBack(
  std::shared_ptr<md::InstrumentNode> ins_node, const std::string& instruction_key, std::function<void()> func) {
  if (!ins_node || m_comb_cnt.find(ins_node) == m_comb_cnt.end()) {
    return;
  }
  m_call_back_map[ins_node][instruction_key] = std::make_pair(func, true);
}

void CombQuoteCalcImpl::CancelCallBack(
  std::shared_ptr<md::InstrumentNode> ins_node, const std::string& instruction_key) {
  if (!ins_node) {
    return;
  }
  auto ins_node_iter = m_call_back_map.find(ins_node);
  if (ins_node_iter == m_call_back_map.end()) {
    return;
  }
  auto instruction_ptr = ins_node_iter->second.find(instruction_key);
  if (instruction_ptr == ins_node_iter->second.end()) {
    return;
  }
  // 暂时把标志位设置为False
  instruction_ptr->second.second = false;
}

void CombQuoteCalcImpl::UpdateSingleQuote(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (!ins_node) {
    return;
  }
  auto& ins = m_comb_to_comb_map[ins_node];
  // 初始化
  ins.instrument_base->product_base->exchange_id = ins_node->Latest()->ExchangeID();
  ins.instrument_base->product_base->product_class = fclib::md::ProductClass::kCusCombine;
  ins.symbol = ins_node->Latest()->symbol;
  ins.last_price = 0.0;
  ins.ask_price[0] = 0.0;
  ins.bid_price[0] = 0.0;
  ins.ask_volume[0] = INT32_MAX;
  ins.bid_volume[0] = INT32_MAX;
  ins.upper_limit = ins_node->Latest()->upper_limit;
  ins.lower_limit = ins_node->Latest()->lower_limit;
  ins.pre_settlement = ins_node->Latest()->pre_settlement;
  ins.pre_close = ins_node->Latest()->pre_close;
  ins.exchange_time = 0;
  ins.close = ins_node->Latest()->close;
  ins.instrument_base->expire_date_time = INT64_MAX;
  ins.instrument_base->product_base->price_decs = 0;
  ins.instrument_base->price_tick = ins_node->Latest()->instrument_base->price_tick;
  for (auto& [leg, leg_ratio] : ins_node->Latest()->instrument_base->weight) {
    auto leg_latest = leg->Latest();
    auto leg_weight = m_comb_vweight[ins_node][leg];
    FCASSERT(leg_weight != 0);
    ins.last_price += leg_latest->last_price * leg_ratio;
    ins.ask_price[0] += ((leg_ratio > 0) ? leg_latest->ask_price[0] : leg_latest->bid_price[0]) * leg_ratio;
    ins.bid_price[0] += ((leg_ratio > 0) ? leg_latest->bid_price[0] : leg_latest->ask_price[0]) * leg_ratio;
    ins.ask_volume[0] = std::min(ins.ask_volume[0],
      (leg_weight > 0) ? static_cast<int32_t>(leg_latest->ask_volume[0] / leg_weight)
                       : static_cast<int32_t>(leg_latest->bid_volume[0] / -leg_weight));
    ins.bid_volume[0] = std::min(ins.bid_volume[0],
      (leg_weight > 0) ? static_cast<int32_t>(leg_latest->bid_volume[0] / leg_weight)
                       : static_cast<int32_t>(leg_latest->ask_volume[0] / -leg_weight));
    ins.exchange_time = std::max(ins.exchange_time, leg_latest->exchange_time);
    ins.instrument_base->expire_date_time =
      std::min(ins.instrument_base->expire_date_time, leg_latest->instrument_base->expire_date_time);
  }
  ins.ask_price[0] += ins_node->Latest()->instrument_base->constant_term;
  ins.bid_price[0] += ins_node->Latest()->instrument_base->constant_term;
  if (isnan(ins.ask_price[0])) {
    ins.ask_volume[0] = 0;
  }
  if (isnan(ins.bid_price[0])) {
    ins.bid_volume[0] = 0;
  }
}

void CombQuoteCalcImpl::UpdateCombQuote(std::shared_ptr<md::InstrumentNode> ins_node) {
  // ins_node为空时更新所有变动的组合行情
  if (ins_node) {
    UpdateSingleQuote(ins_node);
  } else {
    for (auto& comb_node : m_changed_comb) {
      UpdateSingleQuote(comb_node);
    }
  }
  // 调用回调函数
  for (auto& comb_node : m_changed_comb) {
    auto it = m_call_back_map[comb_node].begin();
    while (it != m_call_back_map[comb_node].end()) {
      if (it->second.second) {
        it->second.first();
        ++it;
      } else {
        it = m_call_back_map[comb_node].erase(it);
      }
    }
  }
}

md::Instrument* CombQuoteCalcImpl::GetCombQuote(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (!ins_node) {
    return nullptr;
  }

  auto iter = m_comb_to_comb_map.find(ins_node);
  if (iter == m_comb_to_comb_map.end()) {
    return nullptr;
  }

  return &iter->second;
}

void CombQuoteCalcImpl::UpdateTqApi(std::shared_ptr<fclib::TqApi> api) {
  m_tq_api = api;
  m_ins_view = m_tq_api->DataDb()->CreateView<md::Instrument>([=](std::shared_ptr<const md::Instrument> ins) {
    return m_single_to_comb_map.find(ins->GetKey()) != m_single_to_comb_map.end();
  });

  m_ins_view->AfterCommit("CombQuoteCalcImpl", [this](std::shared_ptr<md::InstrumentNode> ins, bool is_last) {
    for (auto& bind_comb : m_single_to_comb_map[ins->GetKey()]) {
      m_changed_comb.insert(bind_comb);
    }
    if (is_last) {
      // 一组最后一个变动 更新组合行情
      UpdateCombQuote();
      m_changed_comb.clear();
    }
  });
}

}  // namespace extension
}  // namespace fclib

