future::Offset GetOffset(const TwoSidedQuoteAgentQuoteImpl::Present& present,
  const TwoSidedQuoteAgentQuoteImpl::Target& target, std::shared_ptr<const md::Instrument> ins,
  future::Direction direction) {
  auto offset = future::Offset::kOpen;
  if (present.position_node) {
    const future::SubPosition* subpos = (direction == future::Direction::kBuy)
      ? (&present.position_node->Latest()->subpos_short_spec)
      : (&present.position_node->Latest()->subpos_long_spec);
    if (ins->ExchangeID() == "SHFE" || ins->ExchangeID() == "INE") {
      if (subpos->volume_today - subpos->volume_today_frozen >= target.offer_volume + target.min_position)
        offset = future::Offset::kCloseToday;
      if (subpos->volume_his - subpos->volume_his_frozen >= target.offer_volume + target.min_position)
        offset = future::Offset::kCloseYesterday;
    }
    if (subpos->Volume() - subpos->VolumeFrozen() >= target.offer_volume + target.min_position)
      offset = future::Offset::kClose;
  }
  return offset;
}

void TwoSidedQuoteAgentQuoteImpl::CalcInsertQuote(ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins,
  const TwoSidedQuoteAgentQuoteImpl::Target& target, const TwoSidedQuoteAgentQuoteImpl::Present& present) {
  // 有报价指令, 或目标手数为0, 则不需要下
  if (present.quote_node || target.offer_volume <= 0)
    return;

  auto insert_quote = std::make_shared<future::InsertQuote>(target.m_user_key);
  insert_quote->exchange_id = ins->ExchangeID();
  insert_quote->instrument_id = ins->instrument_id;
  insert_quote->ask_price = TargetOrderPrice(target, ins, future::Direction::kSell);
  insert_quote->bid_price = TargetOrderPrice(target, ins, future::Direction::kBuy);
  insert_quote->ask_volume = target.offer_volume;
  insert_quote->bid_volume = target.offer_volume;
  insert_quote->ask_offset = GetOffset(present, target, ins, future::Direction::kSell);
  insert_quote->bid_offset = GetOffset(present, target, ins, future::Direction::kBuy);
  insert_quote->ask_hedge_flag = future::OrderHedgeFlag::kSpeculation;
  insert_quote->bid_hedge_flag = future::OrderHedgeFlag::kSpeculation;
  insert_quote->unit_id = target.m_unit_id;
  action_plan->insert_quote = insert_quote;
}

void TwoSidedQuoteAgentQuoteImpl::CalcCancelQuote(ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins,
  const TwoSidedQuoteAgentQuoteImpl::Target& target, TwoSidedQuoteAgentQuoteImpl::Present& present) {
  // 没有报价指令则不需要撤
  if (!present.quote_node)
    return;
  if (present.quote_node->Latest()->status == future::OrderStatus::kDead) {
    present.quote_node.reset();
    return;
  }
  // 价格/手数/开平完全正确, 不用撤
  double target_price_bid = TargetOrderPrice(target, ins, future::Direction::kBuy);
  double target_price_ask = TargetOrderPrice(target, ins, future::Direction::kSell);
  auto quote = present.quote_node->Snap();
  auto bid_order = quote->bid_order_pointer->Snap();
  auto ask_order = quote->ask_order_pointer->Snap();
  if (target.offer_volume == quote->ask_volume && target.offer_volume == quote->bid_volume
    && target_price_ask == quote->ask_price && target_price_bid == quote->bid_price)
    return;
  // 撤销报价和衍生委托单
  auto cancel_quote = std::make_shared<future::CancelQuote>(target.m_user_key);
  cancel_quote->quote_id = present.quote_node->Snap()->quote_id;
  action_plan->cancel_quote = cancel_quote;
}

double TwoSidedQuoteAgentQuoteImpl::TargetOrderPrice(
  const Target& target, std::shared_ptr<const md::Instrument> ins, future::Direction direction) {
  /*
    2、报单价格计算
    以市场中间价，即市场价（bid1 +
    ask1）/2为基准，按照指定价宽生成价格。待价格确定后，还可设置买价偏移、卖价偏移单独调整。
    （1）指定价宽＜盘口价宽时，直接取盘口买一、卖一价
            （1.1）【可选】后撤逻辑：当盘口买一量或卖一量不满足阈值时，对应买价或卖价退1tick。
    （2）指定价宽≥盘口价宽时，根据盘口量取整：指定价宽与盘口价宽奇偶性相同时不需取整；奇偶性不同时，盘面量小的一边比量大的一边多往后移1个tick。
    （2.1）【可选】后撤逻辑：当盘口买一量或卖一量不满足阈值时，对应买价或卖价退1tick。

    例如：盘口价宽是3（买价=10，卖价=13），指定价宽为4。
    若买一量＞卖一量，报买价=10，卖价=14；
    若买一量≤买一量，报买价=9，卖价=13
  */
  if (isnan(ins->bid_price[0]) || isnan(ins->ask_price[0]))
    return NAN;
  double actual_spread = ins->ask_price[0] - ins->bid_price[0];
  double target_offer_spread = target.offer_spread * ins->PriceTick();
  if (target_offer_spread < actual_spread)
    return direction == future::Direction::kBuy ? ins->bid_price[0] : ins->ask_price[0];
  double mid_price = isnan(target.mid_price) ? ((ins->ask_price[0] + ins->bid_price[0]) / 2) : target.mid_price;
  double half_offer_spread = target_offer_spread / 2.0;
  double bid_offer_price = mid_price - half_offer_spread;
  double ask_offer_price = mid_price + half_offer_spread;
  if (fabs(ask_offer_price - std::round(ask_offer_price / ins->PriceTick()) * ins->PriceTick())
    > 0.1 * ins->PriceTick()) {
    if (ins->bid_volume[0] > ins->ask_volume[0]) {
      bid_offer_price += ins->PriceTick() / 2.0;
      ask_offer_price += ins->PriceTick() / 2.0;
    } else {
      bid_offer_price -= ins->PriceTick() / 2.0;
      ask_offer_price -= ins->PriceTick() / 2.0;
    }
  }
  int price_adjust = 0;
  if (target.m_price_adjust_func)
    price_adjust = target.m_price_adjust_func(direction);
  bid_offer_price = (std::round(bid_offer_price / ins->PriceTick()) + price_adjust) * ins->PriceTick();
  ask_offer_price = (std::round(ask_offer_price / ins->PriceTick()) - price_adjust) * ins->PriceTick();
  return direction == future::Direction::kBuy ? bid_offer_price : ask_offer_price;
}

void TwoSidedQuoteAgentQuoteImpl::CalcActionPlan(
  ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins, const Target& target, Present& present) {
  // 从空的行动清单开始
  action_plan->insert_quote.reset();
  action_plan->cancel_quote.reset();
  // 如果TwoSidedQuoteAgentQuoteImpl前面发出的指令还有任何未完成的, 不做任何新指令 (todo: 应当考虑断线或超时等问题)
  if (!present.processing_commands.empty())
    return;
  // 考虑撤销报价和衍生报单
  CalcCancelQuote(action_plan, ins, target, present);
  // 如果还需要撤单, 则不发任何下单指令
  if (action_plan->cancel_quote)
    return;
  // 考虑发出报价指令
  CalcInsertQuote(action_plan, ins, target, present);
}

int TwoSidedQuoteAgentQuoteImpl::RunOnce() {
  m_last_error.clear();
  if (!m_ins_node)
    return -1;
  // 整理现状
  if (!RemoveFinishedCommand(&m_present.processing_commands, &m_last_error)) {
    m_last_error = u8"指令执行失败";
    return -1;
  }
  // 输入参数验证
  if (m_target.mid_price < 0) {
    m_last_error = u8"报价中价错误";
    return 1;
  }
  if (m_target.min_position < 0) {
    m_last_error = u8"最小持仓量错误";
    return 1;
  }
  if (m_target.offer_spread < 0) {
    m_last_error = u8"报价价差错误";
    return 1;
  }
  if (m_target.offer_volume < 0) {
    m_last_error = u8"报价手数错误";
    return 1;
  }

  if (!m_present.position_node)
    m_present.position_node = m_root_node_db->GetNode<future::Position>(m_target.m_user_key + "|0|" + m_symbol);

  // 根据现状和目标得到行动方案
  CalcActionPlan(&m_action_plan, m_ins_node->Snap(), m_target, m_present);

  // 执行行动方案
  if (m_action_plan.cancel_quote) {
    m_api->AsyncRequest(m_action_plan.cancel_quote);
    if (m_action_plan.cancel_quote->result_code != 0) {
      m_last_error = m_action_plan.cancel_quote->result_msg;
      return -1;
    }
    m_present.processing_commands.insert(m_action_plan.cancel_quote);
  }
  if (m_action_plan.insert_quote) {
    m_api->AsyncRequest(m_action_plan.insert_quote);
    if (m_action_plan.insert_quote->result_code != 0) {
      m_last_error = m_action_plan.insert_quote->result_msg;
      return -1;
    }
    m_present.quote_node = m_action_plan.insert_quote->quote_pointer;
    m_present.processing_commands.insert(m_action_plan.insert_quote);
  }
  return 0;
}

