// TradingTimeTableType转json
const std::string TradingTimeTableTypeToJson(const fclib::md::TradingTimeTable& tradingtimetable) {
  rapidjson::Document res;
  res.SetObject();
  rapidjson::Document::AllocatorType& allocator = res.GetAllocator();

  rapidjson::Value day(rapidjson::kArrayType);
  for (const auto& time : tradingtimetable.day) {
    rapidjson::Value timeArray(rapidjson::kArrayType);
    timeArray.PushBack(rapidjson::Value(time[0].c_str(), allocator).Move(), allocator);
    timeArray.PushBack(rapidjson::Value(time[1].c_str(), allocator).Move(), allocator);
    day.PushBack(timeArray, allocator);
  }
  res.AddMember("day", day, allocator);

  rapidjson::Value night(rapidjson::kArrayType);
  for (const auto& time : tradingtimetable.night) {
    rapidjson::Value timeArray(rapidjson::kArrayType);
    timeArray.PushBack(rapidjson::Value(time[0].c_str(), allocator).Move(), allocator);
    timeArray.PushBack(rapidjson::Value(time[1].c_str(), allocator).Move(), allocator);
    night.PushBack(timeArray, allocator);
  }
  res.AddMember("night", night, allocator);

  rapidjson::StringBuffer buffer;
  rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
  res.Accept(writer);

  return buffer.GetString();
}

