class GrafanaDataControllerImpl : public GrafanaDataController {
 public:
  GrafanaDataControllerImpl(std::shared_ptr<TqApi> api, std::shared_ptr<OptionCalculator> calculator,
    const std::string& path, const int reader_number, const int interval_time)
    : m_api(api)
    , m_calculator(calculator)
    , m_path(path)
    , m_time_interval(interval_time < 0 ? 1000 : interval_time)
    , m_logger((*((structlog::Logger*)(api->GetLogger())))
                 .With("grafana", "GrafanaDataController")
                 .With("instance", reinterpret_cast<int64_t>(this))
                 .Clone()) {
    FCASSERT(m_api != nullptr);
    m_reader = m_api->DataDb()->GetReader(reader_number);
    FCASSERT(m_reader);
  }

  virtual ~GrafanaDataControllerImpl() {}

  void Stop() {
    m_io_context.post([=]() {
      m_is_stop = true;

      m_account_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      m_position_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      m_login_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
    });
  }

  void Start() {
    m_io_context.post([=]() {
      if (!m_is_stop)
        return;
      m_is_stop = false;
      m_account_view->AfterCommit(
        std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<future::AccountNode> node, bool success) {
          m_snap_changed = true;
        });
      m_position_view->AfterCommit(
        std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<future::PositionNode> node, bool success) {
          m_snap_changed = true;
          if (node->Snap() && nullptr == node->Historical()) {
            if (m_instrument_set.find(node->Snap()->instrument_id) == m_instrument_set.end()) {
              m_instument_cache.insert(node->Snap()->ins_pointer);
            }
            if (m_volatility_curve_subscribes.count(node->Snap()->ins_pointer) == 0) {
              m_volatility_curve_subscribes.insert(node->Snap()->ins_pointer);
              m_calculator->SubscribeFittedVolatility(node->Snap()->ins_pointer);
            }
          }
        });
      m_login_view->AfterCommit(
        std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<future::LoginNode> node, bool success) {
          m_login_map[node->Latest()->user_key] = node;
          if (m_trading_day != node->Latest()->trading_day) {
            m_trading_day = node->Latest()->trading_day;
            InitInstrumentSet();
          }
        });
    });
  }

  void Init() {
    // 初始化变量
    m_snap_changed = false;
    try {
      m_data_base_ptr = std::make_unique<SQLite::Database>(m_path, SQLite::OPEN_READWRITE | SQLite::OPEN_CREATE);
      m_data_base_ptr->exec("PRAGMA journal_mode = WAL;");
      // 默认设定数据库超时时间为3秒
      m_data_base_ptr->setBusyTimeout(s_max_timeout);
      // 检查更新数据库版本
      VersionUpdate();
      // 判断有无对应表，没有则创建表
      CreateAccount();
      CreatePosition();
      CreateInstrument();
    } catch (const SQLite::Exception& e) {
      m_logger.With("error", e.what()).Error("InitError");
    }
    // 创建 Account / Position / Login 视图, 跟踪变动
    m_login_view = m_reader->CreateView<future::LoginContent>([](std::shared_ptr<const future::LoginContent> node) {
      return !node->trading_day.empty();
    });
    m_account_view = m_reader->CreateView<future::Account>([](std::shared_ptr<const future::Account> node) {
      return node->unit_id == 0;
    });
    m_position_view = m_reader->CreateView<future::Position>([](std::shared_ptr<const future::Position> node) {
      return node->unit_id == 0;
    });

    for (const auto& [_, node] : m_reader->GetNodeMap<future::LoginContent>()) {
      if (m_trading_day.empty()) {
        m_trading_day = node->Latest()->trading_day;
        InitInstrumentSet();
      }
    }

    m_work = std::make_unique<boost::asio::io_context::work>(m_io_context);

    m_timer = std::make_shared<boost::asio::deadline_timer>(const_cast<boost::asio::io_context&>(m_io_context));
    m_timer->expires_from_now(boost::posix_time::milliseconds(m_time_interval));
    m_timer->async_wait([this](const boost::system::error_code& ec) {
      if (!ec)
        OnTimer();
    });

    m_thread = std::thread([=]() {
      m_io_context.run();
    });
  }

  void CleanUp() {
    // 停止跟踪
    Stop();
    // 关闭定时器
    m_timer->cancel();
    m_io_context.stop();
    if (m_work)
      m_work.reset();
    if (m_thread.joinable())
      m_thread.join();
    try {
      // 检查数据库大小并做相应的删除
      {
        std::string sql = "SELECT MIN(id) AS MIN_ID , MAX(id) AS MAX_ID FROM PositionSnap;";
        SQLite::Statement query(*m_data_base_ptr, sql);
        query.executeStep();

        int64_t min_id = query.getColumn(0);
        int64_t max_id = query.getColumn(1);

        // 数据库行数大于最大行数，执行删除
        if (max_id - min_id >= m_max_rows) {
          sql = "SELECT trading_day FROM PositionSnap WHERE id = " + std::to_string(max_id - m_max_rows);
          SQLite::Statement query_date(*m_data_base_ptr, sql);
          std::string date;

          if (query_date.executeStep()) {
            date = query_date.getColumn(0).getString();
          }

          sql = "DELETE FROM AccountSnap WHERE trading_day <='" + date + "'";
          m_data_base_ptr->exec(sql);

          sql = "DELETE FROM PositionSnap WHERE trading_day <='" + date + "'";
          m_data_base_ptr->exec(sql);

          sql = "DELETE FROM InstrumentSnap WHERE trading_day <='" + date + "'";
          m_data_base_ptr->exec(sql);
        }
      }
      // 关闭数据库的连接
      m_data_base_ptr.reset();
    } catch (const SQLite::Exception& e) {
      m_logger.With("error", e.what()).Error("CleanUpError");
    }
  }

  void ChangeMaxRows(int rows) {
    m_io_context.post([=]() {
      m_max_rows = rows;
    });
  }

  void ChangeTimeInterval(int interval) {
    m_io_context.post([=]() {
      m_time_interval = interval;
    });
  }

  void SetWrite(bool is_write) {
    m_is_write = is_write;
  }

  bool GetSnapChanged() {
    return m_snap_changed;
  }

 private:
  void VersionUpdate() {
    std::string sql = "PRAGMA user_version;";
    {
      SQLite::Statement query(*m_data_base_ptr, sql);
      int version = -1;
      if (query.executeStep()) {
        version = query.getColumn(0);
      }
      FCASSERT(version != -1);
      if (database_version == version) {
        return;
      }
    }
    {
      SQLite::Transaction update_transaction(*m_data_base_ptr);

      sql =
        "DROP TABLE IF EXISTS AccountSnap;"
        "DROP TABLE IF EXISTS PositionSnap;"
        "DROP TABLE IF EXISTS InstrumentSnap;"
        "PRAGMA user_version = "
        + std::to_string(database_version) + ";";
      m_data_base_ptr->exec(sql);
      update_transaction.commit();
    }
  }

  void InitInstrumentSet() {
    if ("" == m_trading_day || !m_data_base_ptr->tableExists("InstrumentSnap")) {
      return;
    }
    std::string sql = "SELECT instrument_id FROM InstrumentSnap WHERE trading_day =" + m_trading_day + ";";
    SQLite::Statement query(*m_data_base_ptr, sql);
    while (query.executeStep()) {
      m_instrument_set.insert(query.getColumn(0));
    }
  }

