  void DealSubPosition(std::shared_ptr<const future::Position> pos, const future::SubPosition& subpos) {
    // 当昨仓、今仓、平仓盈亏均为0不写入
    if (!subpos.volume_his && !subpos.volume_today
      && ((abs(subpos.close_profit) < 1e-9) || isnan(subpos.close_profit))) {
      return;
    }

    std::string insert_sql =
      "INSERT INTO PositionSnap ("
      "trading_day, timestamp, timestamp_seconds, user_key, investor_id, exchange_id, instrument_id, product_id, "
      "volume_multiple, "
      "last_price, hedge_type, direction, volume_yesterday, volume_today, volume_his, volume_comb, "
      "volume_today_frozen, "
      "volume_his_frozen, open_price, float_profit, position_price, position_profit, close_profit, margin, "
      "commission, "
      "market_value, premium, untrade_profit,user_desc, ins_class, "
      "delta_amount,gamma_amount,vega_amount,theta_amount,rho_amount,time_value,position_delta, "
      "position_gamma,position_vega,position_theta,position_rho) "
      "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,"
      "        ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,"
      "?)";

    SQLite::Statement insert(*m_data_base_ptr, insert_sql.c_str());

    std::string date = m_trading_day;

    insert.bind(1, date);
    insert.bind(2, m_last_time);
    insert.bind(3, m_last_time / 1e9);
    insert.bind(4, pos->UserKey());
    insert.bind(5, pos->InvestorID());
    insert.bind(6, pos->ExchangeID());
    insert.bind(7, pos->InstrumentID());
    if (pos->ins_pointer && pos->ins_pointer->Latest()) {
      insert.bind(8, pos->ins_pointer->Latest()->ProductID());
      insert.bind(9, pos->ins_pointer->Latest()->VolumeMultiple());
    } else {
      insert.bind(8, "");
      insert.bind(9, "");
    }
    insert.bind(10, pos->last_price);
    insert.bind(11, HedgeTypeToString(subpos.hedge_type));
    insert.bind(12, DirectionTypeToString(subpos.direction));
    insert.bind(13, subpos.volume_yesterday);
    insert.bind(14, subpos.volume_today);
    insert.bind(15, subpos.volume_his);
    insert.bind(16, subpos.volume_comb);
    insert.bind(17, subpos.volume_today_frozen);
    insert.bind(18, subpos.volume_his_frozen);
    insert.bind(19, subpos.open_price);
    insert.bind(20, subpos.float_profit);
    insert.bind(21, subpos.position_price);
    insert.bind(22, subpos.position_profit);
    insert.bind(23, subpos.close_profit);
    insert.bind(24, subpos.margin);
    insert.bind(25, subpos.commission);
    insert.bind(26, subpos.market_value);
    insert.bind(27, subpos.premium);
    insert.bind(28, subpos.untrade_profit);
    insert.bind(29, m_login_map[pos->user_key]->Latest()->user_desc);
    insert.bind(30, ProductClassTypeToString(pos->ins_pointer->Latest()->ProductClass()));

    if (!pos->ins_pointer || !pos->ins_pointer->Latest()) {
      insert.bind(31, NAN);
      insert.bind(32, NAN);
      insert.bind(33, NAN);
      insert.bind(34, NAN);
      insert.bind(35, NAN);
      insert.bind(36, NAN);
      insert.bind(37, NAN);
      insert.bind(38, NAN);
      insert.bind(39, NAN);
      insert.bind(40, NAN);
      insert.bind(41, NAN);
    } else if (pos->ins_pointer->Latest()->ProductClass() == fclib::md::ProductClass::kOption) {
      auto node_delta = m_calculator->Delta(pos->ins_pointer);
      auto node_vega = m_calculator->Vega(pos->ins_pointer);
      auto node_gamma = m_calculator->Gamma(pos->ins_pointer);
      auto node_theta = m_calculator->Theta(pos->ins_pointer);
      auto node_rho = m_calculator->Rho(pos->ins_pointer);
      auto inner_value = m_calculator->IntrinsicValue(pos->ins_pointer);
      auto net_volume = subpos.volume_today + subpos.volume_his;
      auto volume_multiple = pos->ins_pointer->Latest()->VolumeMultiple();
      auto underlying_node = pos->ins_pointer->Latest()->instrument_base->underlying_pointer;
      insert.bind(31, node_delta * net_volume * volume_multiple * underlying_node->Latest()->last_price);
      insert.bind(32,
        node_gamma * net_volume * volume_multiple * underlying_node->Latest()->last_price
          * underlying_node->Latest()->last_price * 0.01);
      insert.bind(33, node_vega * net_volume * volume_multiple);
      insert.bind(34, node_theta * net_volume * volume_multiple);
      insert.bind(35, node_rho * net_volume * volume_multiple);
      insert.bind(36, net_volume * (volume_multiple * pos->last_price - inner_value));
      insert.bind(37, node_delta * net_volume);
      insert.bind(38, node_gamma * net_volume);
      insert.bind(39, node_vega * net_volume);
      insert.bind(40, node_theta * net_volume);
      insert.bind(41, node_rho * net_volume);
    } else {
      auto node_delta = subpos.direction == fclib::future::Direction::kBuy ? 1 : -1;
      auto net_volume = subpos.volume_today + subpos.volume_his;
      auto volume_multiple = pos->ins_pointer->Latest()->VolumeMultiple();
      auto last_price = pos->last_price;
      insert.bind(31, std::to_string(node_delta * net_volume * volume_multiple * last_price));
      insert.bind(32, NAN);
      insert.bind(33, NAN);
      insert.bind(34, NAN);
      insert.bind(35, NAN);
      insert.bind(36, NAN);
      insert.bind(37, std::to_string(node_delta * net_volume));
      insert.bind(38, NAN);
      insert.bind(39, NAN);
      insert.bind(40, NAN);
      insert.bind(41, NAN);
    }

    insert.exec();
  }

  void InsertInstrument() {
    for (const auto& node : m_instument_cache) {
      if (!node->Latest()) {
        continue;
      }
      m_instrument_set.insert(node->Latest()->instrument_id);
      std::string insert_sql =
        "INSERT INTO InstrumentSnap (trading_day,timestamp,timestamp_seconds,exchange_id,instrument_id,product_id,  "
        "category,ins_class,volume_multiple,pre_open_interest,pre_settlement,pre_close,price_tick,price_decs,"
        "underlying_symbol,strike_price,instrument_name,expire_datetime,delivery_year,delivery_month,last_exercise_"
        "datetime, exercise_year,  exercise_month,option_class,exercise_type,trading_time,category_chinese)"
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,?,?)";
      SQLite::Statement insert(*m_data_base_ptr, insert_sql.c_str());

      auto timestamp = NowAsEpochNano();
      insert.bind(1, m_trading_day);
      insert.bind(2, timestamp);
      insert.bind(3, timestamp / 1e9);
      insert.bind(4, node->Latest()->ExchangeID());
      insert.bind(5, node->Latest()->InstrumentID());
      insert.bind(6, node->Latest()->ProductID());
      insert.bind(7, ProductCategoriesToJson(node->Latest()->instrument_base->product_base->product_categories, false));
      insert.bind(8, ProductClassTypeToString(node->Latest()->ProductClass()));
      insert.bind(9, node->Latest()->VolumeMultiple());
      insert.bind(10, node->Latest()->pre_open_interest);
      insert.bind(11, node->Latest()->pre_settlement);
      insert.bind(12, node->Latest()->pre_close);
      insert.bind(13, node->Latest()->PriceTick());
      insert.bind(14, node->Latest()->PriceDecs());
      insert.bind(15, std::string(node->Latest()->instrument_base->underlying_pointer.Key()));
      insert.bind(16, node->Latest()->strike_price);
      insert.bind(17, node->Latest()->instrument_name);
      insert.bind(18, node->Latest()->instrument_base->expire_date_time);
      insert.bind(19, node->Latest()->instrument_base->delivery_year);
      insert.bind(20, node->Latest()->instrument_base->delivery_month);
      insert.bind(21, node->Latest()->instrument_base->last_exercise_day);
      if (node->Latest()->instrument_base->last_exercise_day_str.size() == 0) {
        insert.bind(22, "");
        insert.bind(23, "");
      } else {
        insert.bind(22, node->Latest()->instrument_base->last_exercise_day_str.substr(0, 4));
        insert.bind(23, node->Latest()->instrument_base->last_exercise_day_str.substr(4, 2));
      }
      if (node->Latest()->ProductClass() == fclib::md::ProductClass::kOption) {
        insert.bind(24, OptionClassTypeToString(node->Latest()->option_class));
        insert.bind(25, OptionExerciseTypeToString(node->Latest()->instrument_base->exercise_type));
      } else {
        insert.bind(24, "");
        insert.bind(25, "");
      }
      insert.bind(26, TradingTimeTableTypeToJson(node->Latest()->TradingTime()));
      insert.bind(27, ProductCategoriesToJson(node->Latest()->instrument_base->product_base->product_categories, true));
      insert.exec();
    }
    m_instument_cache.clear();
  }

  void OnTimer() {
    m_reader->UpdateData();
    if (m_snap_changed && !m_is_stop && m_is_write) {
      try {
        SQLite::Transaction transaction(*m_data_base_ptr);
        // 写入数据库 (account / position)
        InsertAccount();
        for (const auto& [_, node] : m_position_view->GetNodes()) {
          auto it = m_login_map.find(node->Latest()->user_key);
          if (it == m_login_map.end() || it->second->Latest()->position_ready == false)
            continue;
          // 处理每个SubPosition
          DealSubPosition(node->Latest(), node->Latest()->subpos_long_other);
          DealSubPosition(node->Latest(), node->Latest()->subpos_long_spec);
          DealSubPosition(node->Latest(), node->Latest()->subpos_short_other);
          DealSubPosition(node->Latest(), node->Latest()->subpos_short_spec);
        }
        InsertInstrument();
        transaction.commit();
      } catch (const SQLite::Exception& e) {
        m_logger.With("error", e.what()).Error("OnTimerError");
      }
      // 重置标志位
      m_snap_changed = false;
    }
    // 刷新定时器
    m_timer->expires_from_now(boost::posix_time::milliseconds(m_time_interval));
    m_timer->async_wait([this](const boost::system::error_code& ec) {
      if (!ec)
        OnTimer();
    });
  }

  std::shared_ptr<TqApi> m_api;
  std::shared_ptr<OptionCalculator> m_calculator;
  std::string m_path;
  int m_time_interval;
  std::atomic<bool> m_snap_changed = false;
  bool m_is_stop = true;
  std::shared_ptr<fclib::TqApiNodeDb::Reader> m_reader;

  int m_max_rows = 5000000;
  std::string m_trading_day;

  std::unique_ptr<SQLite::Database> m_data_base_ptr;

  boost::asio::io_context m_io_context;
  std::unique_ptr<boost::asio::io_context::work> m_work;
  std::shared_ptr<boost::asio::deadline_timer> m_timer;
  std::thread m_thread;

  int64_t m_last_time;

  std::map<std::string, std::shared_ptr<future::LoginNode>> m_login_map;
  std::set<std::string> m_instrument_set;
  std::set<NodePointer<fclib::md::Instrument>> m_instument_cache;
  std::shared_ptr<NodeDbView<future::Account>> m_account_view;
  std::shared_ptr<NodeDbView<future::Position>> m_position_view;
  std::shared_ptr<NodeDbView<future::LoginContent>> m_login_view;
  std::set<std::shared_ptr<md::InstrumentNode>> m_volatility_curve_subscribes;
  std::atomic_bool m_is_write = true;
  const int database_version = 5;
  structlog::Logger m_logger;
};

