bool EqualDouble(double a, double b, int sigDigs) {
  double absa = fabs(a);
  double absb = fabs(b);
  double diff = fabs(a - b);
  double epsilon = pow(0.1, sigDigs);
  // shortcut, handles infinities
  if (a == b)
    return true;
  // a or b or both are zero
  // relative error is not meaningful here
  else if (a * b == 0)
    return diff < (epsilon * epsilon);
  // use relative error
  else
    return diff / (absa + absb) < epsilon;
}

