double OptionCalculatorImpl::GetCallIntrinsicValue(double base_price, double strike_price) {
  if (isnan(base_price) || isnan(strike_price))
    return std::numeric_limits<double>::quiet_NaN();
  return std::max(0.0, base_price - strike_price);
}

double OptionCalculatorImpl::GetPutIntrinsicValue(double base_price, double strike_price) {
  if (isnan(base_price) || isnan(strike_price))
    return std::numeric_limits<double>::quiet_NaN();
  return std::max(0.0, strike_price - base_price);
}

double OptionCalculatorImpl::GetLeverageRatio(double base_price, double option_price) {
  if (isnan(base_price) || isnan(option_price))
    return std::numeric_limits<double>::quiet_NaN();
  return base_price / option_price;
}

double OptionCalculatorImpl::GetCallPremiumRate(double base_price, double option_price, double strike_price) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price))
    return std::numeric_limits<double>::quiet_NaN();
  return (strike_price + option_price) / base_price - 1;
}

double OptionCalculatorImpl::GetPutPremiumRate(double base_price, double option_price, double strike_price) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price))
    return std::numeric_limits<double>::quiet_NaN();
  return 1 - (strike_price - option_price) / base_price;
}

double OptionCalculatorImpl::NormPdf(const double x) {
  if (isnan(x))
    return std::numeric_limits<double>::quiet_NaN();
  return (1.0 / (pow(2 * M_PI, 0.5))) * exp(-0.5 * x * x);
}

double OptionCalculatorImpl::NormCdf(const double x) {
  if (isnan(x))
    return std::numeric_limits<double>::quiet_NaN();
  double k = 1.0 / (1.0 + 0.2316419 * x);
  double k_sum = k * (0.319381530 + k * (-0.356563782 + k * (1.781477937 + k * (-1.821255978 + 1.330274429 * k))));
  if (x >= 0.0)
    return (1.0 - (1.0 / (pow(2 * M_PI, 0.5))) * exp(-0.5 * x * x) * k_sum);
  return 1.0 - NormCdf(-x);
}

double OptionCalculatorImpl::CalcOptionUnderlyingPricePDF(
  double x, double last_price, double risk_free_interest, double expire_time, double volatility) {
  if (x <= 0.0)
    return 0.0;
  if (IsZero(expire_time) || IsZero(volatility))  // 到期日为0或波动率为0时，退化为单点分布
    return x == last_price ? 1.0 : 0.0;
  double mu = log(last_price) + (risk_free_interest - volatility * volatility / 2) * expire_time;  // 均值
  double sigma = volatility * pow(expire_time, 0.5);                                               // 标准差
  return exp(-pow((log(x) - mu), 2) / (2 * sigma * sigma)) / (last_price * sigma * pow(2 * M_PI, 0.5));
}

double OptionCalculatorImpl::CalcOptionUnderlyingPriceCDF(
  double x, double last_price, double risk_free_interest, double expire_time, double volatility) {
  if (x <= 0.0)
    return 0.0;
  if (IsZero(expire_time) || IsZero(volatility))  // 到期日为0或波动率为0时，退化为单点分布
    return x == last_price ? 0.5 : (x < last_price ? 0.0 : 1.0);
  double mu = log(last_price) + (risk_free_interest - volatility * volatility / 2) * expire_time;  // 均值
  double sigma = volatility * pow(expire_time, 0.5);                                               // 标准差
  return NormCdf((log(x) - mu) / sigma);
}

// This calculates d_j, for j in {1,2}. This term appears in the closed
// form solution for the European call or put price
double DJ(const int j, const double S, const double K, const double r, const double volatility, const double T) {
  if (isnan(S) || isnan(K) || isnan(r) || isnan(volatility) || isnan(T))
    return std::numeric_limits<double>::quiet_NaN();
  double d0 = (log(S / K) + (r + (pow(-1.0, j - 1)) * 0.5 * volatility * volatility) * T);
  double d1 = (volatility * (pow(T, 0.5)));
  return d0 / d1;
}

// Calculate the European vanilla call price based on
// underlying S, strike K, risk-free rate r, volatility of
// underlying volatility and time to maturity T
double OptionCalculatorImpl::GetEuropeanVanillaCallPrice(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year))
    return std::numeric_limits<double>::quiet_NaN();
  double d1 = base_price * NormCdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year));
  double d2 = strike_price * exp(-m_risk_free_interest * year)
    * NormCdf(DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
  return d1 - d2;
}

// Calculate the European vanilla put price based on
// underlying S, strike K, risk-free rate r, volatility of
// underlying volatility and time to maturity T
double OptionCalculatorImpl::GetEuropeanVanillaPutPrice(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year))
    return std::numeric_limits<double>::quiet_NaN();
  return -base_price * NormCdf(-DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year))
    + strike_price * exp(-m_risk_free_interest * year)
    * NormCdf(-DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
}

// Ref: http://www.quantstart.com/articles/Implied-Volatility-in-C-using-Template-Functions-and-Newton-Raphson
// Calculate the European vanilla call vega 'Greek' based on
// underlying S, strike K, risk-free rate r, volatility of
// underlying volatility and time to maturity T
double OptionCalculatorImpl::GetEuropeanVanillaVega(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return base_price * sqrt(year) * NormPdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year));
}

double OptionCalculatorImpl::GetEuropeanVanillaCallImpliedVolatility(
  double base_price, double option_price, double strike_price, double init_volatility, double year) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price) || isnan(init_volatility) || isnan(year)
    || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  // Set the initial option prices and volatility
  double y = GetEuropeanVanillaCallPrice(base_price, strike_price, init_volatility, year);  // Initial option prices
  double x = init_volatility;                                                               // Initial volatility
  double cp = GetEuropeanVanillaCallPrice(base_price, strike_price, 0, year);
  if (option_price < cp)
    return 0;
  // While y and y_target are not similar enough
  // Take the vega of the option and recalculate
  // a new call price based on the best linear
  // approximation at that particular vol value
  int cnt = 0;
  bool got_x = true;
  while (!EqualDouble(y, option_price, 8)) {
    double d_x = GetEuropeanVanillaVega(base_price, strike_price, x, year);
    double diff = (option_price - y) / d_x;
    if (x + diff < 0)
      x = x / 2;
    else if (diff > x / 2)
      x *= 1.5;
    else
      x += diff;
    y = GetEuropeanVanillaCallPrice(base_price, strike_price, x, year);
    if (cnt++ > 100) {
      got_x = false;
      break;
    }
  }
  return got_x ? x : std::numeric_limits<double>::quiet_NaN();
}

double OptionCalculatorImpl::GetEuropeanVanillaPutImpliedVolatility(
  double base_price, double option_price, double strike_price, double init_volatility, double year) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price) || isnan(init_volatility) || isnan(year)
    || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  // Set the initial option prices and volatility
  double y = GetEuropeanVanillaPutPrice(base_price, strike_price, init_volatility, year);  // Initial option prices
  double x = init_volatility;                                                              // Initial volatility
  if (option_price < GetEuropeanVanillaPutPrice(base_price, strike_price, 0, year))
    return 0;
  // While y and y_target are not similar enough
  // Take the vega of the option and recalculate
  // a new put price based on the best linear
  // approximation at that particular vol value
  int cnt = 0;
  bool got_x = true;
  while (!EqualDouble(y, option_price, 8)) {
    double d_x = GetEuropeanVanillaVega(base_price, strike_price, x, year);
    double diff = (option_price - y) / d_x;
    if (x + diff < 0)
      x = x / 2;
    else if (diff > x / 2)
      x *= 1.5;
    else
      x += diff;
    y = GetEuropeanVanillaPutPrice(base_price, strike_price, x, year);
    if (cnt++ > 100) {
      got_x = false;
      break;
    }
  }
  return got_x ? x : std::numeric_limits<double>::quiet_NaN();
}

// Calculate the European vanilla call Delta
// underlying S, strike K, risk-free rate r, volatility of
// underlying volatility and time to maturity T
double OptionCalculatorImpl::GetEuropeanVanillaCallDelta(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return NormCdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year));
}

double OptionCalculatorImpl::GetEuropeanVanillaPutDelta(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return NormCdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year)) - 1;
}

// Calculate the European vanilla call Gamma
double OptionCalculatorImpl::GetEuropeanVanillaGamma(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return NormPdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year))
    / (base_price * volatility * sqrt(year));
}

// Calculate the European vanilla call Theta
double OptionCalculatorImpl::GetEuropeanVanillaCallTheta(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return -(base_price * NormPdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year)) * volatility)
    / (2 * sqrt(year))
    - m_risk_free_interest * strike_price * exp(-m_risk_free_interest * year)
    * NormCdf(DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
}

double OptionCalculatorImpl::GetEuropeanVanillaPutTheta(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return -(base_price * NormPdf(DJ(1, base_price, strike_price, m_risk_free_interest, volatility, year)) * volatility)
    / (2 * sqrt(year))
    + m_risk_free_interest * strike_price * exp(-m_risk_free_interest * year)
    * NormCdf(-DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
}

// Calculate the European vanilla call Rho
double OptionCalculatorImpl::GetEuropeanVanillaCallRho(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return strike_price * year * exp(-m_risk_free_interest * year)
    * NormCdf(DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
}

double OptionCalculatorImpl::GetEuropeanVanillaPutRho(
  double base_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return -year * strike_price * exp(-m_risk_free_interest * year)
    * NormCdf(-DJ(2, base_price, strike_price, m_risk_free_interest, volatility, year));
}

double OptionCalculatorImpl::GetEuropeanVanillaCallLambda(
  double base_price, double option_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return GetLeverageRatio(base_price, option_price)
    * GetEuropeanVanillaCallDelta(base_price, strike_price, volatility, year);
}

double OptionCalculatorImpl::GetEuropeanVanillaPutLambda(
  double base_price, double option_price, double strike_price, double volatility, double year) {
  if (isnan(base_price) || isnan(option_price) || isnan(strike_price) || isnan(volatility) || isnan(year) || year <= 0)
    return std::numeric_limits<double>::quiet_NaN();
  return GetLeverageRatio(base_price, option_price)
    * GetEuropeanVanillaPutDelta(base_price, strike_price, volatility, year);
}

double OptionCalculatorImpl::GetInitialVolatility(std::shared_ptr<md::InstrumentNode> ins) {
  return 0.25;
}

double OptionCalculatorImpl::RemainLength(int64_t expire_datetime, int64_t datetime /* = -1*/) {
  return (expire_datetime - (datetime == -1 ? m_current_epoch_nano : datetime)) / (365.0 * 86400.0 * 1000000000.0);
}

