  double sigma = ImpliedVolatility(ins);
  if (isnan(sigma) && m_theory_volatility_engine)
    sigma = m_theory_volatility_engine->GetFittedVolatility(ins);
  double year = RemainLength(ins->Latest()->instrument_base->expire_date_time);
  double delta = 0;
  if (ins->Latest()->option_class == md::OptionClass::kCall)
    delta = GetEuropeanVanillaCallDelta(base_price, ins->Latest()->strike_price, sigma, year);
  else
    delta = GetEuropeanVanillaPutDelta(base_price, ins->Latest()->strike_price, sigma, year);
  return delta;
}

