double GetCalcPrice(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (!ins_node || !ins_node->Latest())
    return std::numeric_limits<double>::quiet_NaN();
  auto ins = ins_node->Latest();
  if (!isnan(ins->ask_price[0]) && !isnan(ins->bid_price[0])) {
    return (ins->ask_price[0] + ins->bid_price[0]) / 2.0;
  } else if (!isnan(ins->last_price)) {
    return ins->last_price;
  } else if (!isnan(ins->pre_settlement)) {
    return ins->pre_settlement;
  }
  return std::numeric_limits<double>::quiet_NaN();
}

std::map<int64_t, std::shared_ptr<OptionCalculatorImpl::BaseOptionInfo>> OptionCalculatorImpl::CreateOptionInfo(
  std::shared_ptr<md::InstrumentNode> underlying) {
  assert(underlying);
  auto underlying_last_price = underlying->Latest()->last_price;
  if (isnan(underlying_last_price)) {
    return {};
  }
  std::map<int64_t, std::shared_ptr<BaseOptionInfo>> option_info_map;

  for (auto& [_, ins_opt_pointer] : underlying->Snap()->instrument_base->derivate_pointer) {
    auto ins_opt = ins_opt_pointer->Snap();
    if (!ins_opt || ins_opt->ProductClass() != md::ProductClass::kOption)
      continue;
    int64_t expire_datetime = ins_opt->instrument_base->expire_date_time;
    auto it = option_info_map.find(expire_datetime);
    if (it == option_info_map.end()) {
      option_info_map[expire_datetime] = std::make_shared<BaseOptionInfo>();
      it = option_info_map.find(expire_datetime);
    }
    std::shared_ptr<BaseOptionInfo> base_option_info = it->second;
    if (isnan(base_option_info->strike_price)) {
      base_option_info->strike_price = ins_opt->strike_price;
      if (ins_opt->option_class == md::OptionClass::kCall)
        base_option_info->call_option = ins_opt_pointer;
      else
        base_option_info->put_option = ins_opt_pointer;
    } else {
      if (std::abs(ins_opt->strike_price - base_option_info->strike_price) < 1e-9) {
        if (ins_opt->option_class == md::OptionClass::kCall)
          base_option_info->call_option = ins_opt_pointer;
        else
          base_option_info->put_option = ins_opt_pointer;
      } else {
        auto now_abs = std::abs(ins_opt->strike_price - underlying_last_price);
        auto exist_abs = std::abs(base_option_info->strike_price - underlying_last_price);
        if (exist_abs > now_abs) {
          base_option_info->strike_price = ins_opt->strike_price;
          base_option_info->call_option = nullptr;
          base_option_info->put_option = nullptr;
          if (ins_opt->option_class == md::OptionClass::kCall)
            base_option_info->call_option = ins_opt_pointer;
          else
            base_option_info->put_option = ins_opt_pointer;
        }
      }
    }
  }
  if (m_tqapi) {
    auto& logger = (*((structlog::Logger*)(m_tqapi->GetLogger())));
    logger.With("underlying", underlying->Latest()->InstrumentID());
    for (auto& [time, info] : option_info_map) {
      logger.With("expire", time)
        .With("strike", info->strike_price)
        .With("call", info->call_option ? info->call_option->Latest()->InstrumentID() : "null")
        .With("put", info->put_option ? info->put_option->Latest()->InstrumentID() : "null")
        .Info("OptionCalculatorImpl Info");
    }
  }
  return option_info_map;
}

// 输入期权合约节点，返回标的价格
double OptionCalculatorImpl::GetBasePrice(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (!ins_node || !ins_node->Latest())
    return std::numeric_limits<double>::quiet_NaN();
  auto ins = ins_node->Latest();
  if (!ins->instrument_base || !ins->instrument_base->underlying_pointer
    || isnan(ins->instrument_base->underlying_pointer->Latest()->last_price))
    return std::numeric_limits<double>::quiet_NaN();
  if (ins->ExchangeID() != "CFFEX" && ins->ExchangeID() != "SSE" && ins->ExchangeID() != "SZSE")
    return ins->instrument_base->underlying_pointer->Latest()->last_price;
  // 剩下交易所的期权的基础价格需要使用期权合成
  std::shared_ptr<md::InstrumentNode> underlying = ins->instrument_base->underlying_pointer;
  auto it0 = m_base_price_cache.find(underlying);
  if (it0 == m_base_price_cache.end()) {
    m_base_price_cache[underlying] = CreateOptionInfo(underlying);
    it0 = m_base_price_cache.find(underlying);
  }
  auto& option_info_map = it0->second;
  auto it = option_info_map.find(ins->instrument_base->expire_date_time);
  if (it == option_info_map.end())
    return std::numeric_limits<double>::quiet_NaN();
  std::shared_ptr<BaseOptionInfo> base_option_info = it->second;
  return CalcBasePrice(base_option_info, ins->instrument_base->expire_date_time);
}

double OptionCalculatorImpl::CalcBasePrice(std::shared_ptr<BaseOptionInfo> info, int64_t epoch_nano) {
  double call_price = GetCalcPrice(info->call_option);
  double put_price = GetCalcPrice(info->put_option);
  if (isnan(call_price) || isnan(put_price))
    return std::numeric_limits<double>::quiet_NaN();
  double remain_day = (epoch_nano - m_current_epoch_nano) / 1000000000 / (365.0 * 24 * 60 * 60);
  return info->strike_price + (call_price - put_price) * std::exp(m_risk_free_interest * remain_day);
}

double OptionCalculatorImpl::ImpliedVolatility(std::shared_ptr<md::InstrumentNode> ins, double price /* = NAN*/) {
  if (!ins || !ins->Latest())
    return std::numeric_limits<double>::quiet_NaN();
  if (isnan(price))
    price = (ins->Latest()->ask_price[0] + ins->Latest()->bid_price[0]) / 2;
  return CalcImpliedVolatility(ins, price);
}

