void ParseHoliday(std::set<std::string>& map, const std::string& json) {
  InstrumentTradingTimeSerializer ss;
  bool ret = ss.FromString(json.c_str());
  if (!ret)
    return;
  if (!ss.m_doc->IsArray())
    return;
  const auto& vec = ss.m_doc->GetArray();
  for (const auto& v : vec) {
    if (!v.IsString())
      continue;
    std::string day = v.GetString();
    day.erase(std::remove(day.begin(), day.end(), '-'), day.end());
    map.insert(day);
  }
}

static size_t WriteToString(char* ptr, size_t size, size_t nmemb, void* resultBody) {
  (static_cast<std::string*>(resultBody))->append(std::string{ptr, size * nmemb});
  return size * nmemb;
}

int HttpDownloadToString(const char* url, std::string* result) {
  curl_global_init(CURL_GLOBAL_ALL);
  CURL* curl_handle = curl_easy_init();
  curl_easy_setopt(curl_handle, CURLOPT_TIMEOUT, 3L);
  curl_easy_setopt(curl_handle, CURLOPT_URL, url);
  curl_easy_setopt(curl_handle, CURLOPT_VERBOSE, 0L);
  curl_easy_setopt(curl_handle, CURLOPT_NOPROGRESS, 1L);
  curl_easy_setopt(curl_handle, CURLOPT_SSL_VERIFYPEER, 0L);
  curl_easy_setopt(curl_handle, CURLOPT_SSL_VERIFYHOST, 0L);
  curl_easy_setopt(curl_handle, CURLOPT_FAILONERROR, true);
  curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteToString);
  curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, result);
  curl_slist* http_headers = nullptr;
  http_headers = curl_slist_append(http_headers, "User-Agent: fclib");
  curl_easy_setopt(curl_handle, CURLOPT_HTTPHEADER, http_headers);
  auto ret = curl_easy_perform(curl_handle);
  curl_slist_free_all(http_headers);
  curl_easy_cleanup(curl_handle);
  curl_global_cleanup();
  return ret;
}

