InstrumentTradingTime::InstrumentTradingTime()
  : m_instrument_trading_time_table_map()
  , m_instrument_day_trading_time_table_map()
  , m_instrument_total_trading_time_table_map() {}
const TMarketTradingTimeTable& InstrumentTradingTime::GetTradingTimeTable(std::shared_ptr<const md::Instrument> ins) {
  static TMarketTradingTimeTable _market_trading_time_table = {
    {90000, true},
    {101500, false},
    {103000, true},
    {113000, false},
    {133000, true},
    {150000, false},
    {210000, true},
    {230000, false},
  };
  if (nullptr == ins) {
    return _market_trading_time_table;
  }
  TMarketTradingTimeTableMap::iterator it = m_instrument_trading_time_table_map.find(ins->symbol);
  if (it != m_instrument_trading_time_table_map.end()) {
    return it->second;
  }
  if (!ins->TradingTime().day.empty() || !ins->TradingTime().night.empty()) {
    std::vector<int> time_rang;
    for (const auto& tr : ins->TradingTime().day) {
      if (2 != tr.size())
        continue;
      int32_t st = TimeStrToInt(tr[0]);
      int32_t et = TimeStrToInt(tr[1]);
      if (st < 0 || et < 0) {
        continue;
      }
      time_rang.push_back(st);
      time_rang.push_back(et);
    }
    for (const auto& tr : ins->TradingTime().night) {
      if (2 != tr.size())
        continue;
      int32_t st = TimeStrToInt(tr[0]);
      int32_t et = TimeStrToInt(tr[1]);
      if (st < 0 || et < 0) {
        continue;
      }
      if (et < 240000) {
        time_rang.push_back(st);
        time_rang.push_back(et);
      } else {
        time_rang.push_back(st);
        time_rang.push_back(240000);
        time_rang.push_back(0);
        time_rang.push_back(et - 240000);
      }
    }
    TMarketTradingTimeTable market_trading_time_table;
    std::sort(time_rang.begin(), time_rang.end());
    for (std::size_t i = 0; i < time_rang.size(); i++) {
      bool flag = (0 == (i % 2));
      market_trading_time_table.insert(TMarketTradingTimeTable::value_type(time_rang[i], flag));
    }
    m_instrument_trading_time_table_map[ins->symbol] = market_trading_time_table;
    return m_instrument_trading_time_table_map[ins->symbol];
  } else {
    return _market_trading_time_table;
  }
}

std::string InstrumentTradingTime::GetPreDay(const std::string& today) {
  int year, month, day;
  year = std::stoi(today.substr(0, 4));
  month = std::stoi(today.substr(4, 2));
  day = std::stoi(today.substr(6, 2));

  std::tm date = {0};
  date.tm_year = year - 1900;
  date.tm_mon = month - 1;
  date.tm_mday = day;

  std::mktime(&date);

  if (date.tm_wday == 1) {
    date.tm_mday -= 3;
  } else if (date.tm_wday == 0) {
    date.tm_mday -= 2;
  } else {
    --date.tm_mday;
  }

  std::mktime(&date);

  std::ostringstream oss;
  oss << std::setfill('0') << std::setw(4) << (date.tm_year + 1900) << std::setw(2) << (date.tm_mon + 1) << std::setw(2)
      << date.tm_mday;

  return oss.str();
}

std::string GetStringDate(const std::tm& date) {
  std::ostringstream oss;
  oss << (date.tm_year + 1900) << std::setw(2) << std::setfill('0') << (date.tm_mon + 1) << std::setw(2)
      << std::setfill('0') << date.tm_mday;

  return oss.str();
}

std::string InstrumentTradingTime::GetTradingDay(const int64_t last_time) {
  auto date = EpochNanoToLocalDateTime(last_time, 8).date_time;
  std::mktime(&date);
  // 如果时间大于18点、或者当天是周六日返回的应该是下一个交易日
  if (date.tm_hour >= 18 || date.tm_wday == 6 || date.tm_wday == 0) {
    do {
      ++date.tm_mday;
      std::mktime(&date);
    } while (date.tm_wday == 6 || date.tm_wday == 0);
  }

  return GetStringDate(date);
}

int64_t InstrumentTradingTime::CalcDayTradingTotal(std::shared_ptr<const md::Instrument> ins) {
  int64_t res = 0;
  for (const auto& tr : ins->TradingTime().day) {
    if (2 != tr.size())
      continue;
    int32_t st = TimeStrToInt(tr[0]);
    int32_t et = TimeStrToInt(tr[1]);
    if (st < 0 || et < 0) {
      continue;
    }
    res += TimeDiff(st / 100, et / 100);
  }
  return res * 60 * 1000000000LL;
}

int64_t InstrumentTradingTime::CalcNightTradingTotal(std::shared_ptr<const md::Instrument> ins) {
  int64_t res = 0;
  for (const auto& tr : ins->TradingTime().night) {
    if (2 != tr.size())
      continue;
    int32_t st = TimeStrToInt(tr[0]);
    int32_t et = TimeStrToInt(tr[1]);
    if (st < 0 || et < 0) {
      continue;
    }
    res += TimeDiff(st / 100, et / 100);
  }
  return res * 60 * 1000000000LL;
}

const int64_t InstrumentTradingTime::GetTotalTradingTimeLength(
  std::shared_ptr<const md::Instrument> ins, bool is_use_cache) {
  if (m_holiday_days.empty() && m_is_server_online) {
    GetHolidaysFromServer();
  }
  // exchange_time == 0 的时候 直接返回全量
  if (ins->exchange_time == 0) {
    return CalcDayTradingTotal(ins) + CalcNightTradingTotal(ins);
  }
  // 每天21点清空缓存
  static bool init_cache = false;
  auto date = EpochNanoToLocalDateTime(ins->exchange_time, 8).date_time;
  std::mktime(&date);
  if (!init_cache && date.tm_hour == 21) {
    m_instrument_total_trading_time_table_map.clear();
    init_cache = true;
  }

  // 如果缓存里面有就从缓存里面取
  if (is_use_cache) {
    auto it = m_instrument_total_trading_time_table_map.find(ins->symbol);
    if (it != m_instrument_total_trading_time_table_map.end()) {
      return it->second;
    }
  }
  // 获得对应的交易日
  auto this_day = GetTradingDay(ins->exchange_time);
  // 获得前一个对应的交易日
  auto pre_day = GetPreDay(this_day);
  // 如果前一个对应的交易日是法定假期
  bool night = true;
  if (m_holiday_days.find(pre_day) != m_holiday_days.end()) {
    night = false;
  }

  if (!ins->TradingTime().day.empty() || !ins->TradingTime().night.empty()) {
    int64_t total_time_length = 0;
    total_time_length += CalcDayTradingTotal(ins);
    if (night) {
      total_time_length += CalcNightTradingTotal(ins);
    }
    m_instrument_total_trading_time_table_map[ins->symbol] = total_time_length;
    return m_instrument_total_trading_time_table_map[ins->symbol];
  } else {
    return 0;
  }
}

const int64_t InstrumentTradingTime::GetSpecificNightTradingTimeLength(
  std::shared_ptr<const md::Instrument> ins, const int64_t date_time) {
  if (!ins->NightTrading())
    return 0;
  auto& td = ins->TradingTime();
  if (td.night.size() != 1 || td.night[0].size() != 2)
    return 0;
  int32_t st = TimeStrToInt(td.night[0][0]);
  int32_t et = TimeStrToInt(td.night[0][1]);
  auto dt = EpochNanoToLocalDateTime(date_time, 8);
  // 默认18点切换交易日
  if (dt.date_time.tm_hour < 18)
    dt.date_time.tm_hour += 24;
  int32_t nt = dt.date_time.tm_hour * 10000 + dt.date_time.tm_min * 100 + dt.date_time.tm_sec;
  if (nt < st)
    return 0;
  int64_t nano_seconds = (nt < et) ? dt.nano_seconds : 0;
  return 1000000000LL * AccurateTimeDiff(st, std::min(et, nt)) + nano_seconds;
}

const int64_t InstrumentTradingTime::GetSpecificDayTradingTimeLength(
  std::shared_ptr<const md::Instrument> ins, const int64_t date_time) {
  auto day_trading_time_table = GetDayTradingTimeTable(ins);
  auto dt = EpochNanoToLocalDateTime(date_time, 8);
  // 默认18点切换交易日
  if (dt.date_time.tm_hour >= 18)
    return 0;
  auto nt = dt.date_time.tm_hour * 10000 + dt.date_time.tm_min * 100 + dt.date_time.tm_sec;
  int64_t ret = 0;
  for (auto it = day_trading_time_table.begin(); it != day_trading_time_table.end();) {
    if (nt < it->first)
      return ret;
    int32_t st = it->first;
    ++it;
    int32_t et = it->first;
    int64_t nano_seconds = (nt < et) ? dt.nano_seconds : 0;
    ret += 1000000000LL * AccurateTimeDiff(st, std::min(et, nt)) + nano_seconds;
    ++it;
  }
  return ret;
}

const int64_t InstrumentTradingTime::GetSpecificTradingTimeLength(
  std::shared_ptr<const md::Instrument> ins, const int64_t last_time) {
  auto now_date = EpochNanoToLocalDateTime(last_time, 8).date_time;
  auto now_day = GetStringDate(now_date);
  // 获得对应的交易日
  auto this_day = GetTradingDay(ins->exchange_time);
  // 获得前一个对应的工作日
  auto pre_day = GetPreDay(this_day);

  // 如果前一个交易日是节假日，则没有夜盘
  auto night = true;
  if (m_holiday_days.find(pre_day) != m_holiday_days.end()) {
    night = false;
  }
  if (!night) {
    // 考虑到节假日
    if (now_day > this_day) {
      return CalcDayTradingTotal(ins);
    }
    if (now_day < this_day) {
      return 0;
    }
    return GetSpecificDayTradingTimeLength(ins, last_time);
  } else {
    // 不考虑节假日，只有正常的周末
    if (now_day > this_day) {
      return CalcDayTradingTotal(ins) + CalcNightTradingTotal(ins);
    }
    if (now_day == this_day) {
      return GetSpecificDayTradingTimeLength(ins, last_time) + GetSpecificNightTradingTimeLength(ins, last_time);
    }

    if (now_date.tm_wday == 0 || (now_date.tm_wday == 6 && now_date.tm_hour >= 18)) {
      return CalcNightTradingTotal(ins);
    }

    return GetSpecificNightTradingTimeLength(ins, last_time);
  }
}

const TMarketTradingTimeTable& InstrumentTradingTime::GetDayTradingTimeTable(
  std::shared_ptr<const md::Instrument> ins) {
  static TMarketTradingTimeTable _day_trading_time_table = {
    {90000, true},
    {101500, false},
    {103000, true},
    {113000, false},
    {133000, true},
    {150000, false},
  };
  if (nullptr == ins) {
    return _day_trading_time_table;
  }
  TMarketTradingTimeTableMap::iterator it = m_instrument_day_trading_time_table_map.find(ins->symbol);
  if (it != m_instrument_day_trading_time_table_map.end()) {
    return it->second;
  }
  if (ins->TradingTime().day.empty()) {
    return _day_trading_time_table;
  }
  TMarketTradingTimeTable market_trading_time_table;
  for (const auto& tr : ins->TradingTime().day) {
    if (2 != tr.size())
      continue;
    int32_t st = TimeStrToInt(tr[0]);
    int32_t et = TimeStrToInt(tr[1]);
    if (st < 0 || et < 0) {
      continue;
    }
    market_trading_time_table[st] = true;
    market_trading_time_table[et] = false;
  }
  m_instrument_day_trading_time_table_map[ins->symbol] = market_trading_time_table;
  return m_instrument_day_trading_time_table_map[ins->symbol];
}

int32_t InstrumentTradingTime::TimeDiff(int32_t time_begin, int32_t time_end) {
  int nTime = 0;
  if (time_end <= time_begin) {
    return nTime;
  }
  nTime = (time_end / 100) - (time_begin / 100);
  nTime *= 60;
  nTime += time_end % 100;
  nTime -= time_begin % 100;
  return nTime;
}

int32_t InstrumentTradingTime::TimeStrToInt(std::string time_str) {
  if (time_str.size() != 8)
    return -1;
  time_str.erase(5, 1);
  time_str.erase(2, 1);
  return atoi(time_str.c_str());
}

int32_t InstrumentTradingTime::IntTimeToSec(int32_t int_time) {
  // int_time : 104537 代表 10:45:37
  int32_t seconds = 0;
  seconds += int_time / 10000 * 3600;
  int_time = int_time % 10000;
  seconds += int_time / 100 * 60 + int_time % 100;
  return seconds;
}

int32_t InstrumentTradingTime::AccurateTimeDiff(int32_t time_begin, int32_t time_end) {
  if (time_end <= time_begin)
    return 0;
  return IntTimeToSec(time_end) - IntTimeToSec(time_begin);
}

