std::shared_ptr<SettlementZipFileInfo> GetZipInfoFromPath(std::string path) {
  auto p0 = path.find(".txt");
  auto p1 = path.find_last_of("/");
  auto title = path.substr(p1 + 1, p0 - p1 - 1);
  auto p2 = std::find_if_not(title.begin(), title.end(), ::isdigit);
  auto p3 = std::find_if(p2, title.end(), ::isdigit);
  std::shared_ptr<SettlementZipFileInfo> ret = std::make_shared<SettlementZipFileInfo>();
  std::string user_key(title.begin(), p2);
  std::string key(p2, p3);
  std::string trading_day(p3, title.end());
  ret->title = key;
  ret->user_key = user_key;
  ret->trading_day = std::stoi(trading_day);
  return ret;
}

std::string GetFileData(zip* za, std::shared_ptr<SettlementZipFileInfo> info) {
  struct zip_file* zf;
  std::string Error = "E";
  zf = zip_fopen_index(za, info->index, 0);
  if (!zf) {
    return Error;
  }
  char* buf = new char[info->size];
  if (zip_fread(zf, buf, info->size) < 0) {
    return Error;
  }
  std::string data(buf, info->size);
  delete[] buf;
  zip_fclose(zf);
  return data;
}

MonitoringDataUnzipper::MonitoringDataUnzipper() {
  m_data = std::make_shared<MonitoringRawData>();
  m_error_msg = "";
}

bool MonitoringDataUnzipper::Unzip(const std::string& file_path) {
  int err = 0;
  struct zip* za;
  struct zip_stat sb;
  std::map<std::string, std::shared_ptr<SettlementZipFileInfo>> info_map;
  if ((za = zip_open(file_path.c_str(), 0, &err)) == NULL) {
    m_error_msg = u8"解压文件失败";
    return false;
  }
  m_data->trading_day = 0;
  auto count = zip_get_num_entries(za, 0);
  for (int i = 0; i < count; i++) {
    if (zip_stat_index(za, i, 0, &sb) != 0)
      continue;
    std::string file_name(sb.name);
    if (file_name.find("holddata") != std::string::npos || file_name.find("optholddata") != std::string::npos
      || file_name.find("trddata") != std::string::npos || file_name.find("opttrddata") != std::string::npos
      || file_name.find("liquiddetails") != std::string::npos || file_name.find("fundchg") != std::string::npos
      || file_name.find("otherfund") != std::string::npos || file_name.find("holddetails") != std::string::npos
      || file_name.find("cusfund") != std::string::npos || file_name.find("delivcontractdata") != std::string::npos
      || file_name.find("delivdetails") != std::string::npos) {
      auto info = GetZipInfoFromPath(file_name);
      if (m_data->trading_day == 0) {
        m_data->trading_day = info->trading_day;
        m_data->user_key = info->user_key;
      } else {
        if (m_data->trading_day != info->trading_day || m_data->user_key != info->user_key) {
          m_error_msg = u8"结算文件用户或交易日不统一";
          return false;
        }
      }
      info->size = static_cast<int>(sb.size);
      info->index = i;
      info_map[info->title] = info;
    }
  }
  if (info_map.size() < 11) {
    m_error_msg = u8"上传的结算文件有缺失";
    return false;
  }
  m_data->holddata = GetFileData(za, info_map["holddata"]);
  m_data->optholddata = GetFileData(za, info_map["optholddata"]);
  m_data->trddata = GetFileData(za, info_map["trddata"]);
  m_data->opttrddata = GetFileData(za, info_map["opttrddata"]);
  m_data->liquiddetails = GetFileData(za, info_map["liquiddetails"]);
  m_data->fundchg = GetFileData(za, info_map["fundchg"]);
  m_data->otherfund = GetFileData(za, info_map["otherfund"]);
  m_data->holddetails = GetFileData(za, info_map["holddetails"]);
  m_data->cusfund = GetFileData(za, info_map["cusfund"]);
  m_data->delivcontractdata = GetFileData(za, info_map["delivcontractdata"]);
  m_data->delivdetails = GetFileData(za, info_map["delivdetails"]);
  if (m_data->holddata == "E" || m_data->optholddata == "E" || m_data->trddata == "E" || m_data->opttrddata == "E"
    || m_data->liquiddetails == "E" || m_data->fundchg == "E" || m_data->otherfund == "E" || m_data->holddetails == "E"
    || m_data->cusfund == "E" || m_data->delivcontractdata == "E" || m_data->delivdetails == "E") {
    m_error_msg = u8"文件解析失败";
    m_data = nullptr;
    return false;
  }
  zip_close(za);
  return true;
}

const std::string& MonitoringDataUnzipper::GetErrorMsg() {
  return m_error_msg;
}

std::shared_ptr<MonitoringRawData> MonitoringDataUnzipper::GetData() {
  return m_data;
}
