static void UpdatePositionVolumeAndPrice(
  int new_volume, double new_price, md::Volume& pos_volume, double& pos_open_price) {
  if (new_volume < 1)
    return;
  pos_open_price = (pos_open_price * pos_volume + new_volume * new_price) / (pos_volume + new_volume);
  pos_volume += new_volume;
}

static void ConvertTradeToPositionVolume(std::shared_ptr<const future::Trade> trade, int& long_positive,
  int& short_positive, int& short_negative, int& long_negative) {
  if (trade->direction == future::Direction::kBuy) {
    if (trade->offset == future::Offset::kOpen)
      long_positive = trade->volume;
    else
      short_negative = trade->volume;
  } else {
    if (trade->offset == future::Offset::kOpen)
      short_positive = trade->volume;
    else
      long_negative = trade->volume;
  }
}

std::shared_ptr<DataMonitor> DataMonitor::Create(
  std::shared_ptr<TqApiNodeDb> node_db, structlog::Logger& parent_logger) {
  auto impl = std::make_shared<DataMonitorImpl>(node_db, parent_logger);
  return impl;
}

DataMonitorImpl::DataMonitorImpl(std::shared_ptr<TqApiNodeDb> node_db, structlog::Logger& parent_logger)
  : m_node_db(node_db)
  , m_logger(parent_logger.With("DataMonitorImpl", reinterpret_cast<int64_t>(this)).Clone()) {
  InitDb();
  InitViews();
}

void DataMonitorImpl::AddMonitorOrder(const std::string& order_id, const std::string& user_key) {
  m_logger.With("order_id", order_id).With("user_key", user_key).Info("AddMonitorOrder");
  std::string key = future::Order::MakeKey(user_key, order_id);
  auto f = m_monitor_order_set.insert(key);
  if (!f.second)
    return;
  auto order = m_node_db->GetNode<future::Order>(key);
  if (order && order->Snap()) {
    UpdateByOrder(order);
    for (auto& trade : order->Latest()->trade_set) {
      if (trade->Snap())
        UpdateByTrade(trade);
    }
    m_monitor_node_db->CommitTransaction();
  }
}

std::shared_ptr<MonitorNodeDb> DataMonitorImpl::GetMonitorNodeDb() {
  return m_monitor_node_db;
}

void DataMonitorImpl::UpdateByOrder(std::shared_ptr<future::OrderNode> order_node) {
  FCASSERT(order_node->Snap());
  m_monitor_node_db->ReplaceRecord<MonitorData>(MonitorData::MakeKey(), [&](std::shared_ptr<MonitorData> data) {
    auto res = data->orders.insert(order_node.get());
    if (res.second) {
      // 新委托单
      auto order = order_node->Snap();
      data->all_order_volume += order->volume_orign;
      data->cancel_volume += GetCancelVolumeDiff(order_node, true);
      data->error_volume += GetErrorVolumeDiff(order_node, true);
      data->instruments.insert(order->Symbol());
      data->last_insert_time = std::max(data->last_insert_time, order->insert_date_time);
      data->volume_left += order->status == future::OrderStatus::kDead ? 0 : order->volume_left;
      m_order_min_volume_left[order->GetKey()] = order->volume_left;
      if (order->status == future::OrderStatus::kDead) {
        m_dead_order_key_set.insert(order->GetKey());
      }
    } else {
      data->cancel_volume += GetCancelVolumeDiff(order_node, false);
      data->error_volume += GetErrorVolumeDiff(order_node, false);
      // volume_left 预期符合单调递减
      if (order_node->Snap()->volume_left < m_order_min_volume_left.at(order_node->Snap()->GetKey())) {
        m_order_min_volume_left[order_node->Snap()->GetKey()] = order_node->Snap()->volume_left;
        data->volume_left += order_node->Snap()->volume_left - order_node->Historical()->volume_left;
      }
      // 第一次死亡的单子需要将剩余手数减去
      if (order_node->Snap()->status == future::OrderStatus::kDead
        && m_dead_order_key_set.find(order_node->Snap()->GetKey()) == m_dead_order_key_set.end()) {
        data->volume_left -= order_node->Snap()->volume_left;
        m_dead_order_key_set.insert(order_node->Snap()->GetKey());
      }
      if (order_node->Snap()->volume_orign != order_node->Historical()->volume_orign) {
        FCASSERT(false);
        m_logger.With("order_id", order_node->Snap()->order_id)
          .With("new_volume_orign", order_node->Snap()->volume_orign)
          .With("old_volume_orign", order_node->Historical()->volume_orign)
          .Error("volume_orign changed");
      }
    }
  });
}

void DataMonitorImpl::UpdateByTrade(std::shared_ptr<future::TradeNode> trade_node) {
  FCASSERT(trade_node->Snap() && trade_node->Snap()->ins_pointer);
  if (!CheckTrade(trade_node))
    return;
  auto pos_data_node = UpdateMonitorDataAndPositionDataByTrade(trade_node);
  UpdateProfitByTrade(trade_node, pos_data_node);
  m_trade_ins_set.insert(trade_node->Snap()->Symbol());
}

void DataMonitorImpl::UpdateByInstrument(std::shared_ptr<md::InstrumentNode> ins_node) {
  if (ins_node->Snap()->last_price == ins_node->Historical()->last_price)
    return;
  double last_price = ins_node->Snap()->last_price;
  double volume_multiple = ins_node->Snap()->VolumeMultiple();
  std::string ins_symbol = ins_node->Snap()->symbol;
  double long_profit_diff = 0;
  double short_profit_diff = 0;
  auto& pos_map = m_monitor_node_db->GetNodeMap<PositionData>();
  for (auto it = pos_map.lower_bound(ins_symbol); it != pos_map.end(); ++it) {
    auto pos_data = it->second->Latest();
    auto& symbol = pos_data->symbol;
    if (symbol != ins_symbol)
      break;
    auto pos_profit_node =
      m_monitor_node_db->GetNode<PositionProfitData>(PositionProfitData::MakeKey(pos_data->user_key, pos_data->symbol));
    FCASSERT(pos_profit_node);
    double ori_long_profit = pos_profit_node->Latest()->long_profit;
    double ori_short_profit = pos_profit_node->Latest()->short_profit;
    UpdatePositionProfitData(pos_data, last_price, volume_multiple);
    long_profit_diff += pos_profit_node->Latest()->long_profit - ori_long_profit;
    short_profit_diff += pos_profit_node->Latest()->short_profit - ori_short_profit;
  }
  m_monitor_node_db->ReplaceRecord<SumProfitData>(SumProfitData::MakeKey(), [&](std::shared_ptr<SumProfitData> data) {
    data->sum_long_profit += long_profit_diff;
    data->sum_short_profit += short_profit_diff;
  });
}

int DataMonitorImpl::GetCancelVolumeDiff(std::shared_ptr<future::OrderNode> order_node, bool new_order) {
  if (order_node->Snap()->status == future::OrderStatus::kAlive)
    return 0;
  if (order_node->Snap()->volume_left == 0)
    return 0;
  if (order_node->Snap()->exchange_order_id.empty())
    return 0;  // 没有交易所编号是错单

  // 撤单
  if (new_order) {
    return order_node->Snap()->volume_left;
  }
  // 非本次撤单
  if (m_dead_order_key_set.find(order_node->Snap()->GetKey()) != m_dead_order_key_set.end()) {
    return 0;
  }
  // 本次撤单
  return order_node->Snap()->volume_left;
}

int DataMonitorImpl::GetErrorVolumeDiff(std::shared_ptr<future::OrderNode> order_node, bool new_order) {
  if (order_node->Snap()->status == future::OrderStatus::kAlive)
    return 0;
  if (order_node->Snap()->volume_left == 0)
    return 0;
  if (!order_node->Snap()->exchange_order_id.empty())
    return 0;  // 有交易所编号是撤单

  // 错单
  if (new_order) {
    return order_node->Snap()->volume_left;
  }
  // 不是第一次处理错单
  if (m_dead_order_key_set.find(order_node->Snap()->GetKey()) != m_dead_order_key_set.end()) {
    return 0;
  }
  // 本次处理错单
  return order_node->Snap()->volume_left;
}

std::shared_ptr<PositionProfitDataNode> DataMonitorImpl::UpdatePositionProfitData(
  std::shared_ptr<const PositionData> pos_data, double last_price, double volume_multiple) {
  auto node = m_monitor_node_db->ReplaceRecord<PositionProfitData>(
    PositionProfitData::MakeKey(pos_data->user_key, pos_data->symbol), [&](std::shared_ptr<PositionProfitData> data) {
      data->investor_id = pos_data->investor_id;
      data->symbol = pos_data->symbol;
      data->user_key = pos_data->user_key;
      double long_profit_positive =
        (last_price - pos_data->_long_open_price_positive) * volume_multiple * pos_data->_long_volume_positive;
      double long_profit_negative =
        (pos_data->_long_open_price_negative - last_price) * volume_multiple * pos_data->_long_volume_negative;
      double short_profit_positive =
        (pos_data->_short_open_price_positive - last_price) * volume_multiple * pos_data->_short_volume_positive;
      double short_profit_negative =
        (last_price - pos_data->_short_open_price_negative) * volume_multiple * pos_data->_short_volume_negative;
      data->long_profit = long_profit_positive + long_profit_negative;
      data->short_profit = short_profit_positive + short_profit_negative;
    });
  return node;
}

// 确保用户一直可以拿到 MonitorData SumProfitData.
void DataMonitorImpl::InitDb() {
  m_monitor_node_db = std::make_shared<MonitorNodeDb>(true, 0);
  m_monitor_data_node =
    m_monitor_node_db->ReplaceRecord<MonitorData>(MonitorData::MakeKey(), [](std::shared_ptr<MonitorData> data) {});
  m_sum_profit_data_node = m_monitor_node_db->ReplaceRecord<SumProfitData>(
    SumProfitData::MakeKey(), [](std::shared_ptr<SumProfitData> data) {});
  m_monitor_node_db->CommitTransaction();
}

// 监控与委托相关的数据视图
void DataMonitorImpl::InitViews() {
  m_order_view = m_node_db->CreateView<future::Order>([&](std::shared_ptr<const future::Order> o) {
    auto key = o->GetKey();
    return m_monitor_order_set.find(key) != m_monitor_order_set.end();
  });
  m_order_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
    [this](std::shared_ptr<future::OrderNode> order_node, bool is_last) {
      UpdateByOrder(order_node);
      if (is_last)
        m_monitor_node_db->CommitTransaction();
    });
  m_trade_view = m_node_db->CreateView<future::Trade>([&](std::shared_ptr<const future::Trade> t) {
    auto key = future::Order::MakeKey(t->user_key, t->order_id);
    return m_monitor_order_set.find(key) != m_monitor_order_set.end();
  });
  m_trade_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
    [this](std::shared_ptr<future::TradeNode> trade_node, bool is_last) {
      UpdateByTrade(trade_node);
      if (is_last)
        m_monitor_node_db->CommitTransaction();
    });
  m_ins_view = m_node_db->CreateView<md::Instrument>([&](std::shared_ptr<const md::Instrument> ins) {
    return m_trade_ins_set.find(ins->symbol) != m_trade_ins_set.end();
  });
  m_ins_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
    [this](std::shared_ptr<md::InstrumentNode> ins_node, bool is_last) {
      UpdateByInstrument(ins_node);
      if (is_last)
        m_monitor_node_db->CommitTransaction();
    });
}

// 检查成交是否影响截面, 并显示表达输入预期
bool DataMonitorImpl::CheckTrade(std::shared_ptr<future::TradeNode> trade_node) {
  if (m_monitor_data_node->Latest()->trades.find(trade_node.get()) != m_monitor_data_node->Latest()->trades.end()) {
    if (trade_node->Snap()->volume != trade_node->Historical()->volume
      || trade_node->Snap()->price != trade_node->Historical()->price) {
      FCASSERT(false);
      m_logger.With("order_id", trade_node->Snap()->order_id)
        .With("new_volume", trade_node->Snap()->volume)
        .With("old_volume", trade_node->Historical()->volume)
        .With("new_price", trade_node->Snap()->price)
        .With("old_price", trade_node->Historical()->price)
        .Error("trade volume changed");
    }
    return false;
  }
  return true;
}

// 更新手数和开仓均价
std::shared_ptr<PositionDataNode> DataMonitorImpl::UpdateMonitorDataAndPositionDataByTrade(
  std::shared_ptr<future::TradeNode> trade_node) {
  auto trade = trade_node->Snap();
  md::Volume long_positive = 0;
  md::Volume long_negative = 0;
  md::Volume short_positive = 0;
  md::Volume short_negative = 0;
  ConvertTradeToPositionVolume(trade, long_positive, short_positive, short_negative, long_negative);
  m_monitor_node_db->ReplaceRecord<MonitorData>(MonitorData::MakeKey(), [&](std::shared_ptr<MonitorData> data) {
    data->trades.insert(trade_node.get());
    data->all_trade_volume += trade->volume;
    data->long_pos += long_positive - long_negative;
    data->short_pos += short_positive - short_negative;
  });
  auto pos_data_node = m_monitor_node_db->ReplaceRecord<PositionData>(
    PositionData::MakeKey(trade->user_key, trade->Symbol()), [&](std::shared_ptr<PositionData> data) {
      data->investor_id = trade->investor_id;
      data->symbol = trade->Symbol();
      data->user_key = trade->user_key;
      UpdatePositionVolumeAndPrice(
        long_positive, trade->price, data->_long_volume_positive, data->_long_open_price_positive);
      UpdatePositionVolumeAndPrice(
        long_negative, trade->price, data->_long_volume_negative, data->_long_open_price_negative);
      UpdatePositionVolumeAndPrice(
        short_positive, trade->price, data->_short_volume_positive, data->_short_open_price_positive);
      UpdatePositionVolumeAndPrice(
        short_negative, trade->price, data->_short_volume_negative, data->_short_open_price_negative);
    });
  return pos_data_node;
}

void DataMonitorImpl::UpdateProfitByTrade(
  std::shared_ptr<future::TradeNode> trade_node, std::shared_ptr<PositionDataNode> pos_data_node) {
  if (!trade_node->Snap()->ins_pointer->Snap() || isnan(trade_node->Snap()->ins_pointer->Snap()->last_price))
    return;
  double ori_long_profit = 0;
  double ori_short_profit = 0;
  auto pos_profit_node = m_monitor_node_db->GetNode<PositionProfitData>(
    PositionProfitData::MakeKey(trade_node->Snap()->user_key, trade_node->Snap()->Symbol()));
  if (pos_profit_node) {
    ori_long_profit = pos_profit_node->Latest()->long_profit;
    ori_short_profit = pos_profit_node->Latest()->short_profit;
  }
  double last_price = trade_node->Snap()->ins_pointer->Snap()->last_price;
  double volume_multiple = trade_node->Snap()->ins_pointer->Snap()->VolumeMultiple();
  pos_profit_node = UpdatePositionProfitData(pos_data_node->Latest(), last_price, volume_multiple);
  double long_profit_diff = pos_profit_node->Latest()->long_profit - ori_long_profit;
  double short_profit_diff = pos_profit_node->Latest()->short_profit - ori_short_profit;
  m_monitor_node_db->ReplaceRecord<SumProfitData>(SumProfitData::MakeKey(), [&](std::shared_ptr<SumProfitData> data) {
    data->sum_long_profit += long_profit_diff;
    data->sum_short_profit += short_profit_diff;
  });
}

