std::shared_ptr<future::CancelOrder> CreateCancelOrder(const std::string& user_key, std::string order_id) {
  auto cancel_order = std::make_shared<future::CancelOrder>(user_key);
  cancel_order->order_id = order_id;
  return cancel_order;
}

std::shared_ptr<future::InsertOrder> CreateInsertOrder(const std::string& user_key,
  std::shared_ptr<const md::Instrument> ins, int volume, double price, future::Direction direction,
  future::Offset offset, int32_t unit_id) {
  auto insert_order = std::make_shared<future::InsertOrder>(user_key);
  insert_order->direction = direction;
  insert_order->exchange_id = ins->ExchangeID();
  insert_order->instrument_id = ins->instrument_id;
  insert_order->limit_price = price;
  insert_order->volume = volume;
  insert_order->offset = offset;
  insert_order->price_type = future::PriceType::kLimit;
  insert_order->time_condition = future::OrderTimeCondition::kGfd;
  insert_order->volume_condition = future::OrderVolumeCondition::kAny;
  insert_order->hedge_flag = future::OrderHedgeFlag::kSpeculation;
  insert_order->unit_id = unit_id;
  return insert_order;
}

TwoSidedQuoteAgentImpl::TwoSidedQuoteAgentImpl(
  std::shared_ptr<TqApi> tqapi, const std::string& user_key, const std::string& symbol, int32_t unit_id)
