}

TwoSidedQuoteAgentImpl::~TwoSidedQuoteAgentImpl() {}

void TwoSidedQuoteAgentImpl::CalcInsertOrder(ActionPlan* action_plan, future::Direction direction,
  std::shared_ptr<const md::Instrument> ins, const TwoSidedQuoteAgentImpl::Target& target,
  const TwoSidedQuoteAgentImpl::Present& present) {
  int order_volume = target.offer_volume - present.order_volume(direction);
  FCASSERT(order_volume >= 0);
  if (order_volume <= 0)
    return;
  double order_price = TargetOrderPrice(target, ins, direction);
  if (present.position_node) {
    const future::SubPosition* subpos = (direction == future::Direction::kBuy)
      ? (&present.position_node->Latest()->subpos_short_spec)
      : (&present.position_node->Latest()->subpos_long_spec);
    if (ins->HasCloseToday()) {
      if (subpos->volume_today - subpos->volume_today_frozen >= order_volume + target.min_position) {
        action_plan->insert_orders.push_back(CreateInsertOrder(
          target.m_user_key, ins, order_volume, order_price, direction, future::Offset::kCloseToday, target.m_unit_id));
        return;
      }
      if (subpos->volume_his - subpos->volume_his_frozen >= order_volume + target.min_position) {
        action_plan->insert_orders.push_back(CreateInsertOrder(target.m_user_key, ins, order_volume, order_price,
          direction, future::Offset::kCloseYesterday, target.m_unit_id));
        return;
      }
    }
    if (subpos->Volume() - subpos->VolumeFrozen() >= order_volume + target.min_position) {
      action_plan->insert_orders.push_back(CreateInsertOrder(
        target.m_user_key, ins, order_volume, order_price, direction, future::Offset::kClose, target.m_unit_id));
      return;
    }
  }
  action_plan->insert_orders.push_back(CreateInsertOrder(
    target.m_user_key, ins, order_volume, order_price, direction, future::Offset::kOpen, target.m_unit_id));
}

void TwoSidedQuoteAgentImpl::CalcCancelOrder(ActionPlan* action_plan, future::Direction direction,
  std::shared_ptr<const md::Instrument> ins, const TwoSidedQuoteAgentImpl::Target& target,
  const TwoSidedQuoteAgentImpl::Present& present) {
  auto order_volume = 0;
  for (auto order_node : present.order_nodes(direction)) {
    if (!order_node || !order_node->Snap())
      continue;
    auto order = order_node->Snap();
    double target_price = TargetOrderPrice(target, ins, direction);
    order_volume += order->volume_left;
    if (order_volume > target.offer_volume || fabs(order->limit_price - target_price) > 0.00001) {
      action_plan->cancel_orders.push_back(CreateCancelOrder(target.m_user_key, order_node->Snap()->order_id));
    }
  }
}

double TwoSidedQuoteAgentImpl::TargetOrderPrice(
  const Target& target, std::shared_ptr<const md::Instrument> ins, future::Direction direction) {
  /*
    2、报单价格计算
    以市场中间价，即市场价（bid1 +
    ask1）/2为基准，按照指定价宽生成价格。待价格确定后，还可设置买价偏移、卖价偏移单独调整。
    （1）指定价宽＜盘口价宽时，直接取盘口买一、卖一价
            （1.1）【可选】后撤逻辑：当盘口买一量或卖一量不满足阈值时，对应买价或卖价退1tick。
    （2）指定价宽≥盘口价宽时，根据盘口量取整：指定价宽与盘口价宽奇偶性相同时不需取整；奇偶性不同时，盘面量小的一边比量大的一边多往后移1个tick。
    （2.1）【可选】后撤逻辑：当盘口买一量或卖一量不满足阈值时，对应买价或卖价退1tick。

    例如：盘口价宽是3（买价=10，卖价=13），指定价宽为4。
    若买一量＞卖一量，报买价=10，卖价=14；
    若买一量≤买一量，报买价=9，卖价=13
  */
  if (isnan(ins->bid_price[0]) || isnan(ins->ask_price[0]))
    return NAN;
  double actual_spread = ins->ask_price[0] - ins->bid_price[0];
  double target_offer_spread = target.offer_spread * ins->PriceTick();
  double bid_offer_price = 0;
  double ask_offer_price = 0;
  if (target_offer_spread < actual_spread) {
    bid_offer_price = ins->bid_price[0];
    ask_offer_price = ins->ask_price[0];
  } else {
    double mid_price = isnan(target.mid_price) ? ((ins->ask_price[0] + ins->bid_price[0]) / 2) : target.mid_price;
    double half_offer_spread = target_offer_spread / 2.0;
    bid_offer_price = mid_price - half_offer_spread;
    ask_offer_price = mid_price + half_offer_spread;
    if (fabs(ask_offer_price - std::round(ask_offer_price / ins->PriceTick()) * ins->PriceTick())
      > 0.1 * ins->PriceTick()) {
      if (ins->bid_volume[0] > ins->ask_volume[0]) {
        bid_offer_price += ins->PriceTick() / 2.0;
        ask_offer_price += ins->PriceTick() / 2.0;
      } else {
        bid_offer_price -= ins->PriceTick() / 2.0;
        ask_offer_price -= ins->PriceTick() / 2.0;
      }
    }
  }
  int price_adjust = 0;
  if (target.m_price_adjust_func)
    price_adjust = target.m_price_adjust_func(direction);
  bid_offer_price = (std::round(bid_offer_price / ins->PriceTick()) + price_adjust) * ins->PriceTick();
  ask_offer_price = (std::round(ask_offer_price / ins->PriceTick()) - price_adjust) * ins->PriceTick();
  return direction == future::Direction::kBuy ? bid_offer_price : ask_offer_price;
}

void TwoSidedQuoteAgentImpl::CalcActionPlan(
  ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins, const Target& target, const Present& present) {
  // 从空的行动清单开始
  action_plan->cancel_orders.clear();
  action_plan->insert_orders.clear();
  // 如果TwoSidedQuoteAgentImpl前面发出的指令还有任何未完成的, 不做任何新指令 (todo: 应当考虑断线或超时等问题)
  if (!present.cancel_order_commands.empty() || !present.insert_order_commands.empty())
    return;
  /**
   * 考虑撤单. 实现规则如下:
   * * 只撤 TwoSidedQuoteAgentImpl 自己下的委托单. 其它来源的委托单一定不撤
   * * 不在目标挂单价位上的委托单应当撤销.
   * * 挂单手数超出目标手数时, 全部撤销. (todo: 这是考虑常用场景-目标手数减小通常是减到0 的简化方案)
   */
  CalcCancelOrder(action_plan, future::Direction::kBuy, ins, target, present);
  CalcCancelOrder(action_plan, future::Direction::kSell, ins, target, present);

  // 如果还需要撤单, 则不发任何下单指令
  if (!action_plan->cancel_orders.empty())
    return;

  /**
   * 考虑下单. 实现规则如下:
   * * 到这里时, 已有挂单量一定小于等于目标量. 对差额量发出挂单.
   * * 当持仓中的可平仓量足够时, 发平仓单, 否则发开仓单 (todo: 有必要再优化为多个单细分)
   */
  CalcInsertOrder(action_plan, future::Direction::kBuy, ins, target, present);
  CalcInsertOrder(action_plan, future::Direction::kSell, ins, target, present);
}

bool TwoSidedQuoteAgentImpl::ProcessInsertOrderTracker() {
  for (auto it = m_insert_order_tracker.begin(); it != m_insert_order_tracker.end();) {
    auto insert_order = *it;
    if (insert_order->status != UserCommand::Status::kFinished) {
      it++;
      continue;
    }
    if (insert_order->order_pointer) {
      if (insert_order->direction == future::Direction::kBuy)
        m_present.bid_order_nodes.insert(insert_order->order_pointer);
      else
        m_present.ask_order_nodes.insert(insert_order->order_pointer);
    }
    it = m_insert_order_tracker.erase(it);
  }
  return (m_insert_order_tracker.empty()) ? true : false;
}

bool RemoveFinishedCommand(std::set<std::shared_ptr<UserCommand>>* rset, std::string* error_msg) {
  for (auto it = rset->begin(); it != rset->end();) {
    if ((*it)->status == UserCommand::Status::kFinished) {
      if ((*it)->result_code != 0) {
        if (error_msg)
          *error_msg = (*it)->result_msg;
        it = rset->erase(it);
        return false;
      }
      it = rset->erase(it);
    } else {
      ++it;
    }
  }
  return true;
}

bool RemoveFinishedOrder(std::set<std::shared_ptr<future::OrderNode>>* order_set, std::string* error_msg) {
  for (auto it = order_set->begin(); it != order_set->end();) {
    if ((*it)->Latest() && (*it)->Latest()->status == future::OrderStatus::kDead) {
      if ((*it)->Latest()->exchange_order_id.empty()) {
        if (error_msg)
          *error_msg = (*it)->Latest()->status_msg;
        it = order_set->erase(it);
        return false;
      }
      it = order_set->erase(it);
    } else {
      ++it;
    }
  }
  return true;
}

int TwoSidedQuoteAgentImpl::RunOnce() {
  m_last_error.clear();
  if (!m_ins_node)
    return -1;

  // 整理现状
  if (!ProcessInsertOrderTracker())  // 下单指令未全部完成, 不应停止策略
    return 0;
  RemoveFinishedCommand(
    &m_present.cancel_order_commands, nullptr);  // 撤单失败可能是由于委托单已成交导致的, 不应停止策略.
  if (!RemoveFinishedCommand(&m_present.insert_order_commands, &m_last_error))
    return -1;  // 下单失败是不可原谅的.
  if (!RemoveFinishedOrder(&m_present.bid_order_nodes, &m_last_error))
    return -1;
  if (!RemoveFinishedOrder(&m_present.ask_order_nodes, &m_last_error))
    return -1;

  // 输入参数验证
  if (m_target.mid_price < 0) {
    m_last_error = u8"报价中价错误";
    return 1;
  }
  if (m_target.min_position < 0) {
    m_last_error = u8"最小持仓量错误";
    return 1;
  }
  if (m_target.offer_spread < 0) {
    m_last_error = u8"报价价差错误";
    return 1;
  }
  if (m_target.offer_volume < 0) {
    m_last_error = u8"报价手数错误";
    return 1;
  }

  if (!m_present.position_node)
    m_present.position_node = m_root_node_db->GetNode<future::Position>(m_target.m_user_key + "|0|" + m_symbol);
  // 根据现状和目标得到行动方案
  CalcActionPlan(&m_action_plan, m_ins_node->Snap(), m_target, m_present);

  // 执行行动方案
  for (auto cancel_order : m_action_plan.cancel_orders) {
    m_api->AsyncRequest(cancel_order);
    if (cancel_order->result_code != 0) {
      m_last_error = cancel_order->result_msg;
      return -1;
    }
    m_present.cancel_order_commands.insert(cancel_order);
  }
  for (auto insert_order : m_action_plan.insert_orders) {
    m_api->AsyncRequest(insert_order);
    if (insert_order->result_code != 0) {
      m_last_error = insert_order->result_msg;
      return -1;
    }
    m_present.insert_order_commands.insert(insert_order);
    m_insert_order_tracker.insert(insert_order);
  }
  return 0;
}

