  m_target.m_price_adjust_func = price_adjust_func;
}

int TwoSidedQuoteAgentImpl::Present::order_volume(future::Direction direction) const {
  const auto& order_node_set = order_nodes(direction);
  int present_order_volume = 0;
  for (auto order_node : order_node_set) {
    present_order_volume += order_node->Snap()->volume_left;
  }
  return present_order_volume;
}

