    std::shared_ptr<TqApi> api, const std::string& user_key, const std::string& symbol, int32_t unit_id = 0);
  virtual ~TwoSidedQuoteAgentQuoteImpl();

  /**
   * Target 描述 TwoSidedQuoteAgent 希望达成的目标状态.
   *
   * TwoSidedQuoteAgent可以实现的目标包括:
   * * 在场上维持两个挂单. 其中一个为买挂单, 挂在 mid_price 下方. 另一个为卖单, 挂在 mid_price 上方. 这两个挂单以
