   * 持仓量超过此数量时，挂单尽量使用平仓单, 目标是使持仓量维持在大于等于此要求的最低值;
   */
  struct Target {
    double mid_price = NAN; /**< 报价中间价, 默认为NAN, 表示使用 bidprice1和 askprice1的均价作为mid_price */
    int offer_spread = 1; /**< 报价价差, 买单和卖单的挂单价之差 */
    int offer_volume = 0; /**< 报价手数, 买单卖单都维持这个手数 */
    int min_position = 0; /**< 最低持仓量要求 */
    int32_t m_unit_id = 0;
    std::string m_user_key;
    std::function<int(future::Direction)> m_price_adjust_func;
  };

  /**
   * Present 描述用户账户现状
   *
   * 需要的现状信息包括:
   * * 持仓手数和持仓冻结手数.
   * * 当前的委托单, 包括 TwoSidedQuoteAgent 自己发出的挂单和其它来源的委托单.
   * * 已发出的撤单指令.
   */
  struct Present {
    std::shared_ptr<future::PositionNode> position_node;
    std::shared_ptr<future::QuoteNode> quote_node;
    std::set<std::shared_ptr<UserCommand>> processing_commands;
  };

  /**
   * ActionPlan 描述下一步行动方案
   *
   * * 要发出的撤单指令
   * * 要发出的下单指令
   */
  struct ActionPlan {
    std::shared_ptr<future::InsertQuote> insert_quote;
    std::shared_ptr<future::CancelQuote> cancel_quote;
  };

  /**
   * 输入目标和现状, 输出最近一步行动方案.
   *
   * @param(out) action_plan: 下一步的行动计划
   * @param(in) ins: 合约
   * @param(in) target: 目标
   * @param(in) present: 现状
   */
  static void CalcActionPlan(
    ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins, const Target& target, Present& present);
  static void CalcInsertQuote(ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins,
    const TwoSidedQuoteAgentQuoteImpl::Target& target, const TwoSidedQuoteAgentQuoteImpl::Present& present);
  static void CalcCancelQuote(ActionPlan* action_plan, std::shared_ptr<const md::Instrument> ins,
    const TwoSidedQuoteAgentQuoteImpl::Target& target, TwoSidedQuoteAgentQuoteImpl::Present& present);
  int RunOnce() override;
  void SetMidPrice(double mid_price) override;
  void SetOfferParam(int offer_spread, int offer_volume) override;
  void SetPriceAdjust(std::function<int(future::Direction)> price_adjust_func) override;
  void SetMinPosition(int min_position) override;
  std::string GetLastError() override;
  static double TargetOrderPrice(
    const Target& target, std::shared_ptr<const md::Instrument> ins, future::Direction direction);

 private:
  Target m_target;
  Present m_present;
  ActionPlan m_action_plan;

  std::shared_ptr<TqApi> m_api;
  std::string m_symbol;
  structlog::Logger m_logger;
  std::shared_ptr<TqApiNodeDb> m_root_node_db;
  std::shared_ptr<md::InstrumentNode> m_ins_node;
  std::string m_last_error;
};

