namespace fclib {
namespace extension {

std::shared_ptr<AMPDataHelper> AMPDataHelper::Create(
  std::shared_ptr<TqApiNodeDb> node_db, structlog::Logger& parent_logger) noexcept {
  auto impl = std::make_shared<AMPDataHelperImpl>(node_db, parent_logger);
  return impl;
}

AMPDataHelperImpl::AMPDataHelperImpl(std::shared_ptr<TqApiNodeDb> node_db, structlog::Logger& parent_logger)
  : m_node_db(node_db)
  , m_logger(parent_logger.With("AMPDataHelperImpl", reinterpret_cast<int64_t>(this)).Clone()) {
  m_login_view = m_node_db->CreateView<future::LoginContent>(ReuseViewKey::kLogin);
  m_login_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::LoginNode> login_node, bool is_last) {
      if (login_node->Snap()->session_id == 0)
        return;
      auto user_key = login_node->Snap()->UserKey();
      auto it = m_users.find(user_key);
      if (it == m_users.end())
        return;
      it->second->session_id = login_node->Snap()->session_id;
    });

  m_order_view = m_node_db->CreateView<future::Order>(ReuseViewKey::kOrder);
  m_order_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::OrderNode> order_node, bool is_last) {
      if (!order_node->Historical() || order_node->Historical()->exchange_order_id.empty()) {
        // 错单不统计
        auto order = order_node->Snap();
        if (order->exchange_order_id.empty())
          return;
        auto user_key = order->UserKey();
        auto it = m_users.find(user_key);
        if (it == m_users.end())
          return;
        m_product_set.insert(order->user_product_info);
        if (order->insert_date_time > it->second->start_monitor_time) {
          m_order_count++;
        }
        if (order->session_id == 0)
          return;
        if (it->second->session_id == order->session_id) {
          m_session_order_count++;
        }
      }
    });
}

void AMPDataHelperImpl::AddMonitorUser(const std::string& user_key) {
  if (m_users.find(user_key) != m_users.end()) {
    return;
  }
  auto info = std::make_shared<AccountInfo>();
  info->start_monitor_time = NowAsEpochNano();
  info->session_id = 0;
  auto login_node = m_node_db->GetNode<fclib::future::LoginContent>(user_key);
  if (login_node) {
    info->session_id = login_node->Snap()->session_id;
  }
  m_users[user_key] = info;
}

int AMPDataHelperImpl::GetOrderCount() {
  return m_order_count;
}

int AMPDataHelperImpl::GetSessionOrderCount() {
  return m_session_order_count;
}

double AMPDataHelperImpl::GetTotalBalance() {
  auto& account_map = m_node_db->GetNodeMap<fclib::future::Account>();
  double total_balance = 0.0;
  for (auto& [_, acc] : account_map) {
    auto user_key = acc->Snap()->UserKey();
    if (m_users.find(user_key) != m_users.end()) {
      total_balance += acc->Snap()->balance;
    }
  }
  return total_balance;
}

double AMPDataHelperImpl::GetTotalCommission() {
  auto& account_map = m_node_db->GetNodeMap<fclib::future::Account>();
  double total_commission = 0.0;
  for (auto& [_, acc] : account_map) {
    auto user_key = acc->Snap()->UserKey();
    if (m_users.find(user_key) != m_users.end()) {
      total_commission += acc->Snap()->commission;
    }
  }
  return total_commission;
}

int AMPDataHelperImpl::GetAccountSize() {
  return static_cast<int>(m_users.size());
}

std::string AMPDataHelperImpl::GetProductInfo() {
  std::string product_info;
  for (auto& product : m_product_set) {
    product_info += product + ";";
  }
  return product_info;
}

