}  // namespace fclib

/*******************************************************************************
 * @file settlement_parser.cpp
 * @brief 结算单解析器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/extension/settlement_parser.h"

#include <regex>
#include <memory>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

#ifndef BOOST_LOCALE_HIDE_AUTO_PTR
#define BOOST_LOCALE_HIDE_AUTO_PTR
#include <boost/locale.hpp>
#endif

namespace fclib {
namespace extension {

enum class SectionType {
  kHead = 0,
  kAccount,
  kTable,
};

struct ParseSection {
  std::string key;
  SectionType type;
  ParseContent content;
  int status = 0;  //  1 开始读表头, 2 表示开始读表内容
};

static const std::vector<std::wstring> SettleTables = {
  L"成交记录",
  L"质押明细",
  L"交割明细",
  L"平仓明细",
  L"持仓明细",
  L"持仓汇总",
  L"出入金明细",
  L"货币质押",
  L"行权明细",
};

std::string WStringToString(const std::wstring& s) {
  return boost::locale::conv::utf_to_utf<char>(s);
}
std::wstring StringToWString(const std::string& s) {
  return boost::locale::conv::utf_to_utf<wchar_t>(s);
}

/*
 * 字符串分割
 *
 * @param input: 输入原始字符串
 * @param regex: 分割正则表达式(例: 空格分隔: R"([\s]+)"
 */
std::vector<std::wstring> Split(const std::wstring& input, const std::wregex& regex) {
  std::wsregex_token_iterator it{input.begin(), input.end(), regex, -1};
  // 默认构造迭代器
  std::vector<std::wstring> ret{it, {}};
  return ret;
}

std::wstring Erase(const std::wstring& s, const wchar_t* c = L" ") {
  std::wstring ret = s;
  size_t index = 0;
  if (!ret.empty()) {
    while ((index = ret.find(c, index)) != std::wstring::npos) {
      ret.erase(index, 1);
    }
  }
  return ret;
}

// 字符串去除首尾空格
std::wstring Strip(const std::wstring& s) {
  std::wstring ret = s;
  if (s.empty())
    return ret;
  bool all_spaces = std::all_of(s.begin(), s.end(), [](wchar_t c) {
    return c == L' ';
  });
  if (all_spaces) {
    // 如果全是空格，返回一个包含单个空格的字符串
    return L" ";
  }
  ret.erase(0, ret.find_first_not_of(L" "));
  ret.erase(ret.find_last_not_of(L" ") + 1);
  return ret;
}

// 初始化表模块
std::shared_ptr<ParseSection> GetSection(const std::wstring& line) {
  auto ret = std::make_shared<ParseSection>();
  if (line.find(L"交易结算单") == 0) {
    ret->key = u8"交易结算单";
    ret->type = SectionType::kHead;
    return ret;
  }
  if (line.find(L"资金状况") == 0) {
    ret->key = u8"资金状况";
    ret->type = SectionType::kAccount;
    return ret;
  }
  for (const auto& name : SettleTables) {
    if (line.find(name) == 0) {
      ret->key = WStringToString(name);
      ret->type = SectionType::kTable;
      return ret;
    }
  }
  return nullptr;
}

// 是否是表的首行
bool IsStartLine(const std::wstring& line) {
  if (line.find(L"交易结算单") == 0)
    return true;
  if (line.find(L"资金状况") == 0) {
    std::wregex regex{LR"(资金状况\s.*)"};
    return std::regex_search(line, regex);
  }
  for (const auto& name : SettleTables) {
    if (line.find(name) == 0) {
      std::wregex regex{name + LR"(\s.*)"};
      return std::regex_search(line, regex);
    }
  }
  return false;
}

/*
 * 正则表达式迭代
 */
std::vector<std::wstring> FindAll(const std::wstring& line, const std::wregex& regex) {
  std::wsregex_token_iterator it{line.begin(), line.end(), regex};
  // 默认构造迭代器
  std::vector<std::wstring> ret{it, {}};
  return ret;
}

std::unordered_map<std::string, ParseContent> SettlementParser::Parse(const std::string& settlement_info) {
  std::shared_ptr<ParseSection> section;
  std::unordered_map<std::string, ParseContent> ret;
  // 获取每一行
  std::vector<std::wstring> lines;
  std::istringstream ss(settlement_info);
  std::string t;
  while (std::getline(ss, t, '\n')) {
    if (t.empty())
      continue;
    lines.push_back(Erase(Strip(StringToWString(t)), L"\r"));
  }
  // 逐行处理
  for (const auto& line : lines) {
    std::wsmatch match;
    if (IsStartLine(line)) {
      if (nullptr != section) {
        // table 通过 "-----" 3 次作为结束符
        // assert(section->type != SectionType::kTable);
        ret[section->key] = section->content;
        section.reset();
      }
      section = GetSection(line);
      continue;
    }
    if (nullptr == section) {
      continue;
    }
    if (section->type == SectionType::kHead) {
      if (line.find(L"客户号") == 0) {
        std::wregex regex{LR"(客户号 Client ID[:：]\s*(\d*))"};
        std::regex_search(line, match, regex);
        if (match.size() >= 2) {
          section->content.zh_columns.push_back(u8"客户号");
          section->content.en_columns.push_back(u8"client_id");
          if (section->content.rows.empty()) {
            section->content.rows.push_back({});
          }
          section->content.rows[0].push_back(WStringToString(Strip(match[1])));
        }
        // 有些场景可能缺少客户名称
        if (line.find(L"客户名称") != std::string::npos) {
          std::wregex regex_2{LR"(客户名称 Client Name[:：](.*))"};
          std::regex_search(line, match, regex_2);
          if (match.size() >= 2) {
            section->content.zh_columns.push_back(u8"客户名称");
            section->content.en_columns.push_back(u8"client_name");
            if (section->content.rows.empty()) {
              section->content.rows.push_back({});
            }
            section->content.rows[0].push_back(WStringToString(Strip(match[1])));
          }
        }
        continue;
      }
      // 有些场景客户名称为单独行
      if (line.find(L"客户名称") == 0) {
        std::wregex regex_2{LR"(客户名称 Client Name[:：](.*))"};
        std::regex_search(line, match, regex_2);
        if (match.size() >= 2) {
          section->content.zh_columns.push_back(u8"客户名称");
          section->content.en_columns.push_back(u8"client_name");
          if (section->content.rows.empty()) {
            section->content.rows.push_back({});
          }
          section->content.rows[0].push_back(WStringToString(Strip(match[1])));
        }
        continue;
      }
      if (line.find(L"日期") == 0) {
        std::wregex regex{LR"(日期 Date[:：](.*))"};
        std::regex_search(line, match, regex);
        if (match.size() >= 2) {
          section->content.zh_columns.push_back(u8"日期");
          section->content.en_columns.push_back(u8"date");
          if (section->content.rows.empty()) {
            section->content.rows.push_back({});
          }
          section->content.rows[0].push_back(WStringToString(Strip(match[1])));
        }
        continue;
      }
      continue;
    }
    if (section->type == SectionType::kAccount) {
      if (static_cast<size_t>(std::count(line.begin(), line.end(), '-')) == line.size())
        continue;
      std::wregex zh_column_regex{LR"([\u4e00-\u9fa5][\u4e00-\u9fa5\s]+[\u4e00-\u9fa5]+)"};
      std::wregex en_column_regex{LR"([A-Z][a-zA-Z\.\/\(\)\s]+)"};
      std::wregex row_regex{LR"(-?\d+\.\d\d)"};
      auto zh_columns = FindAll(line, zh_column_regex);
      auto en_columns = FindAll(line, en_column_regex);
      auto rows = FindAll(line, row_regex);
      if (zh_columns.size() != rows.size() || zh_columns.size() != en_columns.size()) {
        ret[section->key] = section->content;
        section.reset();
        continue;
      }
      if (zh_columns.size() == 0)
        continue;
      if (section->content.rows.empty()) {
        section->content.rows.push_back({});
      }
      for (size_t i = 0; i < rows.size(); ++i) {
        section->content.zh_columns.push_back(WStringToString(Erase(zh_columns[i])));
        section->content.en_columns.push_back(WStringToString(en_columns[i]));
        section->content.rows[0].push_back(WStringToString(rows[i]));
      }
      continue;
    }
    if (section->type == SectionType::kTable) {
      if (static_cast<size_t>(std::count(line.begin(), line.end(), '-')) == line.size()) {
        section->status += 1;
        continue;
      }
      if (section->status == 1) {
        auto columns =
          section->content.zh_columns.empty() ? &section->content.zh_columns : &section->content.en_columns;
        for (const auto& s : Split(line, std::wregex{LR"([|]+)"})) {
          std::string t = WStringToString(Strip(s));
          if (!t.empty())
            (*columns).push_back(t);
        }
        continue;
      }
      if (section->status == 2) {
        std::vector<std::string> row;
        for (const auto& s : Split(line, std::wregex{LR"([|]+)"})) {
          std::string t = WStringToString(Strip(s));
          if (!t.empty())
            row.push_back(t);
        }
        section->content.rows.push_back(row);
        continue;
      }
      if (section->status == 3) {
        ret[section->key] = section->content;
        section.reset();
        continue;
      }
      continue;
    }
  }
  // 保存最后一个section（主要针对只有资金状况类型的情况）
  if (nullptr != section) {
    ret[section->key] = section->content;
  }
  return ret;
}

