}  // namespace fclib

/*******************************************************************************
 * @file comb_quote_calc.cpp
 * @brief 自定义组合行情计算器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "fclib/extension/comb_quote_calc.h"

#include <string>
#include "comb_quote_calc_impl.h"
#include "fclib/utils/fcassert.h"
namespace fclib {
namespace extension {

CombQuoteCalc::CombQuoteCalc(std::shared_ptr<TqApi> api, const CombQuoteCalcParams& params)
  : m_api(api)
  , m_params(params)
  , m_id(std::to_string(++s_id)) {
  CombQuoteCalcImpl::Instance(m_api);
}

CombQuoteCalc::~CombQuoteCalc() {
  if (!m_subscribed)
    return;
  for (const auto& key : m_keys)
    CombQuoteCalcImpl::Instance(m_api).CancelCallBack(m_params.ins_node, m_id + key);
  CombQuoteCalcImpl::Instance(m_api).UnSubscribeCusComb(m_params.ins_node);
}

void CombQuoteCalc::Subscribe() {
  if (m_subscribed)
    return;
  CombQuoteCalcImpl::Instance(m_api).SubscribeCusComb(m_params.ins_node, m_params.vweight);
  m_subscribed = true;
}

void CombQuoteCalc::UnSubscribe() {
  if (!m_subscribed)
    return;
  CombQuoteCalcImpl::Instance(m_api).UnSubscribeCusComb(m_params.ins_node);
  m_subscribed = false;
}

void CombQuoteCalc::SetCallBack(const std::string& key, std::function<void()> func) {
  if (!m_subscribed)
    return;
  FCASSERT(m_keys.find(key) == m_keys.end());
  CombQuoteCalcImpl::Instance(m_api).SetCallBack(m_params.ins_node, m_id + key, func);
  m_keys.insert(key);
}

void CombQuoteCalc::CancelCallBack(const std::string& key) {
  if (!m_subscribed || m_keys.find(key) == m_keys.end())
    return;
  CombQuoteCalcImpl::Instance(m_api).CancelCallBack(m_params.ins_node, m_id + key);
  m_keys.erase(key);
}

md::Instrument* CombQuoteCalc::GetInstrument() {
  return CombQuoteCalcImpl::Instance(m_api).GetCombQuote(m_params.ins_node);
}

