InsertOrderAgentImpl::InsertOrderAgentImpl(
  std::shared_ptr<TqApi> api, const std::string& user_key, const std::string& symbol, int32_t unit_id)
  : m_api(api)
  , m_user_key(user_key)
  , m_unit_id(unit_id)
  , m_logger((*((structlog::Logger*)(api->GetLogger())))
               .With("extension", "InsertOrderAgent")
               .With("symbol", symbol)
               .With("unit_id", unit_id)
               .With("instance", reinterpret_cast<int64_t>(this))
               .Clone()) {
  m_root_node_db = m_api->DataDb();
  m_ins_node = m_root_node_db->GetNode<md::Instrument>(symbol);
}

InsertOrderAgentImpl::~InsertOrderAgentImpl() {}

void InsertOrderAgentImpl::InsertOrder(std::shared_ptr<future::InsertOrder> insert_order) {
  auto task = std::make_shared<Task>();
  task->origin_insert_order = insert_order;
  m_processing_task.push_front(task);
  m_logger.With("volume", insert_order->volume).With("price", insert_order->limit_price).Info("req insert order");
}

void InsertOrderAgentImpl::OrderOffsetCal(const InsertOrderOptions& opt,
  std::shared_ptr<future::InsertOrder> insert_order, std::shared_ptr<future::PositionNode> position_node) {
  insert_order->offset = future::Offset::kOpen;
  if (position_node) {
    auto subpos = (insert_order->direction == future::Direction::kBuy) ? (&position_node->Latest()->subpos_short_spec)
                                                                       : (&position_node->Latest()->subpos_long_spec);
    if (insert_order->exchange_id == "SHFE" || insert_order->exchange_id == "INE") {
      if (insert_order->volume + subpos->volume_today_frozen + subpos->strike_frozen + opt.min_position_volume
        <= subpos->volume_today) {
        insert_order->offset = future::Offset::kCloseToday;
      } else if (insert_order->volume + subpos->volume_his_frozen + subpos->strike_his_frozen + opt.min_position_volume
        <= subpos->volume_his) {
        insert_order->offset = future::Offset::kCloseYesterday;
      }
    } else if (insert_order->volume + subpos->VolumeFrozen() + opt.min_position_volume <= subpos->Volume()) {
      insert_order->offset = future::Offset::kClose;
    }
  }
}

void InsertOrderAgentImpl::Start() {
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine)
    return;
  const auto& subscriber = m_api->GetQuoteSubscriber();
  m_quote_handles.insert(subscriber->SubscribeQuote(m_ins_node.get()));
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kOption) {
    const auto& underlying_node = m_ins_node->Latest()->instrument_base->underlying_pointer;
    if (underlying_node)
      m_quote_handles.insert(subscriber->SubscribeQuote(underlying_node.get()));
  }
}

int InsertOrderAgentImpl::RunOnce() {
  bool f_error = false;
  m_status_msg = "";
  for (auto it = m_processing_task.begin(); it != m_processing_task.end();) {
    auto task = *it;
    if (task->insert_order) {
      if (task->insert_order->status != UserCommand::Status::kFinished) {
        ++it;
        continue;
      }
      if (task->insert_order->result_code != 0) {
        f_error = true;
        m_status_msg = task->insert_order->result_msg;
        it = m_processing_task.erase(it);
        continue;
      }
      if (!task->insert_order->order_pointer) {
        f_error = true;
        m_status_msg = u8"下单指令没有返回委托单节点";
        it = m_processing_task.erase(it);
        continue;
      }
      task->order = task->insert_order->order_pointer;
      task->insert_order.reset();
    }
    if (task->order && task->order->Latest()->volume_left == 0) {
      it = m_processing_task.erase(it);
      continue;
    }
    if (!task->next_check_timer.IsExpired()) {
      ++it;
      continue;
    }
    if ((task->origin_insert_order->direction == future::Direction::kBuy
          && m_ins_node->Snap()->last_price < task->next_check_price)
      || (task->origin_insert_order->direction == future::Direction::kSell
        && m_ins_node->Snap()->last_price > task->next_check_price)) {
      ++it;
      continue;
    }
    if (task->order && task->order->Latest()->status == future::OrderStatus::kAlive) {
      if (task->canceling_order != task->order) {
        auto cancel_order = std::make_shared<future::CancelOrder>(m_user_key);
        cancel_order->order_id = task->order->Latest()->order_id;
        m_api->AsyncRequest(cancel_order);
        // todo: 增加指令回复超时延迟检查模块,撤单失败检查模块
        task->canceling_order = task->order;
      }
    } else {
      auto insert_order = std::make_shared<future::InsertOrder>(*(task->origin_insert_order));
      insert_order->unit_id = m_unit_id;
      if (task->order) {
        insert_order->limit_price = task->order->Latest()->limit_price
          + (insert_order->direction == future::Direction::kBuy ? 1 : -1) * m_options.price_step
            * m_ins_node->Latest()->PriceTick();
        insert_order->volume = task->order->Latest()->volume_left;
      }
      if (std::isnan(insert_order->limit_price))
        insert_order->limit_price = m_ins_node->Latest()->last_price;
      if (insert_order->offset == future::Offset::kInvalid) {
        auto position_key = m_user_key + "|0|" + insert_order->exchange_id + "." + insert_order->instrument_id;
        auto position_node = m_root_node_db->GetNode<future::Position>(position_key);
        insert_order->offset = future::Offset::kOpen;
        OrderOffsetCal(m_options, insert_order, position_node);
      }
      if (fabs(insert_order->limit_price - task->origin_insert_order->limit_price)
        > m_options.price_limit * m_ins_node->Latest()->PriceTick()) {
        it = m_processing_task.erase(it);
        continue;
      }
      m_api->AsyncRequest(insert_order);
      task->next_check_timer.Reset(std::chrono::milliseconds(static_cast<int64_t>(m_options.stepping_by_time * 1000)));
      task->next_check_price = insert_order->limit_price
        + (insert_order->direction == future::Direction::kBuy ? 1 : -1) * m_options.price_step
          * m_ins_node->Latest()->PriceTick();
      task->insert_order = insert_order;
    }
    ++it;
  }
  return (!f_error) ? 0 : 1;
}

void InsertOrderAgentImpl::SetOptions(const InsertOrderOptions& options) {
  m_options = options;
  m_logger.With("price_step", options.price_step)
    .With("price_limit", options.price_limit)
    .With("stepping_by_time", options.stepping_by_time)
    .With("stepping_by_price", options.stepping_by_price)
    .With("min_position_volume", options.min_position_volume)
    .Info("set options");
}

