  : m_api(tqapi)
  , m_logger((*((structlog::Logger*)(tqapi->GetLogger())))
               .With("extension", "MarketMakerStrategy")
               .With("instance", reinterpret_cast<int64_t>(this))
               .Clone()) {
  m_running = false;
  m_resume_maker_time_point = 0;
  m_logger.Info("init");
}

MarketMakerStrategyImpl::~MarketMakerStrategyImpl() {}

void MarketMakerStrategyImpl::Start(const std::string& user_key) {
  m_user_key = user_key;
  m_root_node_db = m_api->DataDb();
  m_position_node.reset();
  if (!m_ins_node) {
    m_status_msg = u8"已停止: 做市合约不存在";
    m_running = false;
    return;
  }
  m_logger.With("symbol", m_ins_node->Latest()->symbol)
    .With("quote_spread", m_quote_spread)
    .With("quote_volume", m_quote_volume)
    .With("quote_spread", m_quote_spread_2)
    .With("quote_volume", m_quote_volume_2)
    .With("hedge.options.price_limit", m_hedge_order_max_price_adjust)
    .With("hedge.options.price_step", m_hedge_order_max_price_adjust)
    .With("hedge.options.stepping_by_price", m_hedge_order_max_price_adjust)
    .Info(u8"start");
  m_position_node = GetPositionNode(m_ins_node);
  m_quote_agent =
    extension::TwoSidedQuoteAgent::Create(m_api, m_user_key, m_ins_node->Snap()->symbol, 1, m_use_quote_command);
  m_quote_agent->SetPriceAdjust([=](future::Direction direction) -> int {
    if (!m_ins_node)
      return 0;
    if (direction == future::Direction::kBuy && m_bid_min_volume > 0
      && m_ins_node->Snap()->bid_volume[0] < m_bid_min_volume)
      return -1;
    if (direction == future::Direction::kSell && m_ask_min_volume > 0
      && m_ins_node->Snap()->ask_volume[0] < m_ask_min_volume)
      return -1;
    return 0;
  });
  if (m_quote_spread_2 > 0 && m_quote_volume_2 > 0)
    m_quote_agent_2 =
      extension::TwoSidedQuoteAgent::Create(m_api, m_user_key, m_ins_node->Snap()->symbol, 1, m_use_quote_command);
  else
    m_quote_agent_2.reset();
  auto hedge_symbol = m_ins_node->Snap()->ExchangeID() + "." + m_hedge_instrument_id;
  if (m_hedge_instrument_id.empty())
    hedge_symbol = m_ins_node->Snap()->symbol;
  m_insert_order_agent = extension::InsertOrderAgent::Create(m_api, m_user_key, hedge_symbol, 2);
  extension::InsertOrderAgent::InsertOrderOptions options;
  options.price_limit = m_hedge_order_max_price_adjust;
  options.price_step = m_hedge_order_max_price_adjust;
  options.stepping_by_price = m_hedge_order_max_price_adjust;
  options.stepping_by_time = 0;
  options.min_position_volume = m_min_position_volume;
  m_insert_order_agent->SetOptions(options);
  // 订行情
  SubscribeQuote();
  // 跟踪做市挂单成交
  m_trade_view = m_api->DataDb()->CreateView<future::Trade>(ReuseViewKey::kTrade);
  m_trade_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::TradeNode> trade_node, bool is_last) {
      if (trade_node->Historical())
        return;
      std::shared_ptr<future::OrderNode> order_node = trade_node->Snap()->order_pointer;
      if (order_node->Latest()->unit_id == 1 && order_node->Latest()->ins_pointer.Key() == m_ins_node->Latest()->symbol
        && order_node->Latest()->user_key == m_user_key) {
        OnOfferOrderTrade(trade_node);
      }
    });
  m_status_msg = u8"运行中: 做市运行中";
  m_running = true;
}

void MarketMakerStrategyImpl::Stop(const std::string& reason) {
  m_logger.With("reason", reason).Info(u8"stop");
  // todo: 这里要发出一批撤单指令, 并清空委托单记录
  // 取消超时暂停
  m_pause_timer.Reset(std::chrono::milliseconds(0));
  // 更新状态信息
  m_status_msg = u8"已停止: " + reason;
  m_running = false;
}

int MarketMakerStrategyImpl::RunOnce() {
  if (!m_quote_agent || m_user_key.empty())
    return 0;
  // 只有目前条件符合做市条件, 才执行做市挂单流程
  if (m_running && CheckMakerCondition()) {
    m_quote_agent->SetOfferParam(m_quote_spread, m_quote_volume);
    m_quote_agent->SetMinPosition(m_min_position_volume);
    if (m_quote_agent_2) {
      m_quote_agent_2->SetOfferParam(m_quote_spread_2, m_quote_volume_2);
      m_quote_agent_2->SetMinPosition(m_min_position_volume);
    }
  } else {
    m_quote_agent->SetOfferParam(0, 0);
    if (m_quote_agent_2) {
      m_quote_agent_2->SetOfferParam(0, 0);
    }
  }
  // 要求机器人执行一轮
  if (m_quote_agent->RunOnce() != 0) {
    Stop(u8"已停止: " + m_quote_agent->GetLastError());
    return 0;
  }
  if (m_quote_agent_2 && m_quote_agent_2->RunOnce() != 0) {
    Stop(u8"已停止: " + m_quote_agent_2->GetLastError());
    return 0;
  }
  if (m_insert_order_agent->RunOnce() != 0) {
    Stop(m_insert_order_agent->m_status_msg);
    return 0;
  }
  return 1;
}

void MarketMakerStrategyImpl::OnOfferOrderTrade(std::shared_ptr<future::TradeNode> trade_node) {
  auto trade = trade_node->Snap();
  m_logger.With("exchange_trade_id", trade->exchange_trade_id)
    .With("exchange_order_id", trade->exchange_order_id)
    .With("symbol", trade->Symbol())
    .With("direction", static_cast<int>(trade->direction))
    .With("offset", static_cast<int>(trade->offset))
    .With("price", trade->price)
    .With("volume", trade->volume)
    .Info(u8"offer matched");

  if (!m_running)
    return;

  // 成交时暂停所有挂单, 等一段时间后再挂
  m_quote_agent->SetOfferParam(0, 0);
  if (m_quote_agent_2)
    m_quote_agent_2->SetOfferParam(0, 0);
  m_pause_timer.Reset(std::chrono::milliseconds(static_cast<int64_t>(1000LL * m_pause_seconds_when_trade)));
  m_status_msg = u8"暂停: 挂单成交, 暂停N秒";

  // 发出对冲单
  if (m_require_run_hedge) {
    auto insert_order = std::make_shared<future::InsertOrder>(m_user_key);
    insert_order->exchange_id = trade->exchange_id;
    if (m_hedge_instrument_id.empty())
      insert_order->instrument_id = trade->instrument_id;
    else
      insert_order->instrument_id = m_hedge_instrument_id;
    insert_order->direction =
      trade->direction == future::Direction::kBuy ? future::Direction::kSell : future::Direction::kBuy;
    insert_order->offset = future::Offset::kInvalid;
    insert_order->volume = trade->volume;
    insert_order->price_type = future::PriceType::kLimit;
    if (m_hedge_instrument_id.empty())
      insert_order->limit_price = trade->price;
    else
      insert_order->limit_price = NAN;
    insert_order->time_condition = future::OrderTimeCondition::kGfd;
    insert_order->volume_condition = future::OrderVolumeCondition::kAny;
    insert_order->min_volume = 0;
    insert_order->hedge_flag = trade->hedge_flag;
    m_logger.With("exchange_trade_id", trade->exchange_trade_id)
      .With("symbol", trade->Symbol())
      .With("price", insert_order->limit_price)
      .With("volume", insert_order->volume)
      .Info(u8"start hedge task");
    m_insert_order_agent->InsertOrder(insert_order);
  }
}

bool MarketMakerStrategyImpl::CheckMultisidedMarket(std::shared_ptr<const md::Instrument> ins) {
  if (!IsValid(ins->ask_price[0])   // 卖价不存在
    || !IsValid(ins->bid_price[0])  // 买价不存在
  ) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckSpreadLimit(std::shared_ptr<const md::Instrument> ins, int spread_limit) {
  if (ins->ask_price[0] - ins->bid_price[0] > spread_limit * ins->PriceTick()) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckPriceLimit(std::shared_ptr<const md::Instrument> ins, int price_limit) {
  if ((ins->upper_limit - ins->bid_price[0] < price_limit * ins->PriceTick())   // 买价接近涨停超过阈值
    || (ins->ask_price[0] - ins->lower_limit < price_limit * ins->PriceTick())  // 卖价接近跌停超过阈值
  ) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckMakerTime(
  std::shared_ptr<const md::Instrument> ins, std::map<int, bool>& time_range) {
  auto exchange_time = EpochNanoToLocalDateTime(ins->exchange_time, 8);
  auto current_quote_time =
    exchange_time.date_time.tm_hour * 10000 + exchange_time.date_time.tm_min * 100 + exchange_time.date_time.tm_sec;
  auto it = time_range.upper_bound(current_quote_time);
  if (it == time_range.end() || it->second == true) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckPositionLimit(
  std::shared_ptr<const future::PositionNode> pos_node, int net_position_limit) {
  if (pos_node && abs(pos_node->Snap()->VolumeNet()) > net_position_limit) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckCloseProfitLimit(
  std::shared_ptr<const future::PositionNode> pos_node, double close_profit_limit) {
  if (pos_node && (0 - pos_node->Snap()->CloseProfit() >= close_profit_limit)) {
    return false;
  }
  return true;
}

bool MarketMakerStrategyImpl::CheckMakerCondition() {
  auto ins = m_ins_node->Latest();
  // （2）双边市检查：单边市不报价；
  if (!CheckMultisidedMarket(ins)) {
    m_status_msg = u8"暂停: 单边市不报价";
    return false;
  }

  // （1）盘口价宽检查：盘口价宽超过指定阈值时不报价；
  if (!CheckSpreadLimit(ins, m_spread_limit)) {
    m_status_msg = u8"暂停: 盘口价宽超过指定阈值";
    return false;
  }

  // （3）板价检查：当涨停价- 市场买一价或市场卖一价- 跌停价没有超过阈值时不报价；
  if (!CheckPriceLimit(ins, m_price_limit)) {
    m_status_msg = u8"暂停: 市场价格接近涨跌停";
    return false;
  }

  ////（4）交易时间段检查：只有在做市时间内才进行报价。
  if (!CheckMakerTime(ins, m_time_range)) {
    m_status_msg = u8"暂停: 超出做市时间范围";
    return false;
  }

  // （5）总敞口检查：组合 - 合约净持仓超过阈值时不报价；即净风险敞口
  if (!CheckPositionLimit(m_position_node, m_net_position_limit)) {
    m_status_msg = u8"暂停: 净持仓超过阈值 " + std::to_string(m_net_position_limit);
    return false;
  }

  // （6）盈亏检查：平仓盈亏超过阈值后不报价；
  if (!CheckCloseProfitLimit(m_position_node, m_close_profit_limit)) {
    m_status_msg = u8"暂停: 平仓亏损超过阈值 " + std::to_string(m_close_profit_limit);
    return false;
  }

  // 上次暂停时间还没到
  if (!m_pause_timer.IsExpired()) {
    // node: 这里不修改m_status_msg, 使它保持在暂停前的最后一个状态
    return false;
  }

  ////（7）行情变动：市场买一价或市场卖一价在一段时间内，最低价与最高价的差值其中一个不在阈值范围内暂停报价，等待一段时间重报，重报后重新记录行情。
  // if (m_ins_node->Snap()->ask_price[0] > m_highest_ask)
  //    m_highest_ask = m_ins_node->Snap()->ask_price[0];
  // if (m_ins_node->Snap()->bid_price[0] < m_lowest_bid)
  //    m_lowest_bid = m_ins_node->Snap()->bid_price[0];
  // if (m_highest_ask - m_lowest_bid > m_move_speed_limit) {
  //    m_resume_maker_time_point = ::NowAsEpochNano() + 10000000000LL;
  //    m_status_msg = u8"暂停: 行情变动过快, 暂停10秒";
  //    return false;
  //}

  m_status_msg = u8"运行中: 做市运行中";
  return true;
}

std::shared_ptr<future::PositionNode> MarketMakerStrategyImpl::GetPositionNode(
  std::shared_ptr<md::InstrumentNode> ins_node) {
  auto position_node = m_root_node_db->GetNode<future::Position>(m_user_key + "|0|" + ins_node->Latest()->symbol);
  return position_node;
}

void MarketMakerStrategyImpl::SubscribeQuote() {
  if (!m_ins_node || m_ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine)
    return;
  const auto& subscriber = m_api->GetQuoteSubscriber();
  m_quote_handles.insert(subscriber->SubscribeQuote(m_ins_node.get()));
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kOption) {
    const auto& underlying_node = m_ins_node->Latest()->instrument_base->underlying_pointer;
    if (underlying_node)
      m_quote_handles.insert(subscriber->SubscribeQuote(underlying_node.get()));
  }
}

