// 监控数据文档:https://shinnytech.atlassian.net/wiki/spaces/~839434080/pages/1278574716
namespace fclib {
namespace extension {

bool UpdatePositionMargin(
  const std::string& direction, const std::string& hedge, const double& margin, std::shared_ptr<PositionMargin> pos) {
  if (direction.empty() || hedge.empty() || isnan(margin))
    return false;
  if (direction == "B") {
    if (hedge == "S") {
      pos->long_spec = margin;
    } else {
      pos->long_other = margin;
    }
  } else {
    if (hedge == "S") {
      pos->short_spec = margin;
    } else {
      pos->short_other = margin;
    }
  }
  return true;
}

bool ParseHolddata(const std::string& holddata, std::shared_ptr<ParserResult> ret, std::string* result_msg) {
  std::istringstream ss(holddata);
  std::string line;
  double account_margin = 0.0;
  while (std::getline(ss, line, '\n')) {
    std::istringstream sss(line);
    std::string item;
    int count = 0;
    std::string symbol = "";
    std::string direction = "";
    std::string hedge = "";
    double margin = NAN;
    while (std::getline(sss, item, '@')) {
      if (count == 2)
        symbol = item;
      if (count == 3)
        direction = item;
      if (count == 4)
        hedge = item;
      if (count == 6) {
        try {
          margin = std::stod(item);
        } catch (std::exception& e) {
          *result_msg = e.what();
          return false;
        }
        account_margin += margin;
        auto pos = ret->position_map.find(symbol) == ret->position_map.end() ? std::make_shared<PositionMargin>()
                                                                             : ret->position_map.at(symbol);
        if (!UpdatePositionMargin(direction, hedge, margin, pos)) {
          *result_msg = u8"holddata 解析失败";
          return false;
        }
        ret->position_map[symbol] = pos;
        break;
      }
      ++count;
    }
  }
  ret->account->margin += account_margin;
  return true;
}

int ConvertDateFormat(const std::string& src, std::string* result_msg) {
  int year, month, day;
  if (sscanf(src.c_str(), "%d-%d-%d", &year, &month, &day) != 3) {
    *result_msg = "Date parsing error";
    return 19700101;
  }

  char dst[15];
  snprintf(dst, sizeof(dst), "%04d%02d%02d", year, month, day);

  return std::stoi(std::string(dst));
}

bool ParseTrddata(
  const std::string& trddata, std::shared_ptr<ParserResult> ret, std::string* result_msg, bool is_opt = false) {
  int index = is_opt ? 11 : 13;
  std::istringstream ss(trddata);
  std::string line;
  while (std::getline(ss, line, '\n')) {
    std::istringstream sss(line);
    std::string item;
    int count = 0;
    bool success = false;
    while (std::getline(sss, item, '@')) {
      if (count == index) {
        success = true;
        try {
          ret->account->commission += std::stod(item);
        } catch (std::exception& e) {
          *result_msg = e.what();
          return false;
        }
      }
      ++count;
    }
    if (!success) {
      *result_msg = u8"trddata文件格式有误";
      return false;
    }
  }
  return true;
}

fclib::future::Direction StringToDirection(const std::string& str) {
  if (str == "B")
    return fclib::future::Direction::kBuy;
  else if (str == "S")
    return fclib::future::Direction::kSell;
  else
    return fclib::future::Direction::kInvalid;
}

bool ParseLiquiddetails(const std::string& liquiddetails, std::shared_ptr<ParserResult> ret, std::string* result_msg) {
  std::istringstream ss(liquiddetails);
  std::string line;
