std::shared_ptr<ParserResult> MonitoringDataParser::Parse(const std::string& holddata, const std::string& trddata,
  const std::string& optholddata, const std::string& opttrddata, const std::string& liquiddetails,
  std::string* result_msg) {
  std::shared_ptr<ParserResult> ret = std::make_shared<ParserResult>();
  ret->account = std::make_shared<AccountMarginCommission>();
  if (!ParseHolddata(holddata, ret, result_msg))
    return nullptr;
  if (!ParseHolddata(optholddata, ret, result_msg))
    return nullptr;
  if (!ParseTrddata(trddata, ret, result_msg))
    return nullptr;
  if (!ParseTrddata(opttrddata, ret, result_msg, true))
    return nullptr;
  if (!ParseLiquiddetails(liquiddetails, ret, result_msg)) {
    return nullptr;
  }

  return ret;
}

std::shared_ptr<ParsedData> MonitoringDataParser::Parse(const MonitoringRawData& raw_data, std::string* result_msg) {
  std::shared_ptr<ParsedData> ret = std::make_shared<ParsedData>();
  ret->user_key = raw_data.user_key;
  ret->trading_day = raw_data.trading_day;
  if (!ParseCusFund(raw_data.cusfund, ret, result_msg))
    return nullptr;
  if (!ParseFundChg(raw_data.fundchg, ret, result_msg))
    return nullptr;
  if (!ParseTrddata(raw_data.trddata, ret, result_msg))
    return nullptr;
  if (!ParseOtherFund(raw_data.otherfund, ret, result_msg))
    return nullptr;
  if (!ParseHoldDetail(raw_data.holddetails, ret, result_msg))
    return nullptr;
  if (!ParseHoldData(raw_data.holddata, ret, result_msg))
    return nullptr;
  if (!ParseDeliveryDetail(raw_data.delivdetails, ret, result_msg))
    return nullptr;
  if (!ParseDelivContractData(raw_data.delivcontractdata, ret, result_msg))
    return nullptr;
  if (!ParseLiquiddetails(raw_data.liquiddetails, ret, result_msg))
    return nullptr;
  return ret;
}

