 * @file theory_volatility_curve.cpp
 * @brief 期权理论波动率曲线拟合引擎
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "theory_volatility_curve.h"

#include <eigen3/Eigen/Dense>
#include <vector>
#include <set>
#include <string>
#include <memory>
#include <utility>
#include <algorithm>
#include "fclib/utils/numset.h"
#include "fclib/extension/option_calc.h"

namespace fclib {
namespace extension {

/**
 * @brief: 使用最小二乘估计进行 n 阶多项式参数拟合: f(x) = a0 + a1 * x + a2 * x^2 + ... + an * x^n.
 *
 * @param X: 样本数据的 X 轴坐标向量.
 * @param Y: 样本数据的 Y 轴坐标向量.
 * @param n: 拟合阶次, 应满足 n > 0.
 * @return vector<double>: 拟合结果 a 的集合.
 */
std::vector<double> FitLeastSquareMethod(std::vector<double>& X, std::vector<double>& Y, int32_t n) {
  std::vector<double> ret;
  if (X.size() < 2 || Y.size() < 2 || X.size() != Y.size() || n < 1)
    return ret;
  // vector 转换 eigen 矩阵.
  Eigen::Map<Eigen::VectorXd> sampleX(X.data(), X.size());
  Eigen::Map<Eigen::VectorXd> sampleY(Y.data(), Y.size());
  // 范德蒙矩阵 X, 行: X 样本数据大小, 列: 阶次 + 1.
  Eigen::MatrixXd mtxVandermonde(X.size(), n + 1);
  Eigen::VectorXd colVandermonde = sampleX;
  for (int i = 0; i < n + 1; ++i) {
    if (0 == i) {
      mtxVandermonde.col(0) = Eigen::VectorXd::Constant(X.size(), 1, 1);
      continue;
    }
    if (1 == i) {
      mtxVandermonde.col(1) = colVandermonde;
      continue;
    }
    // n 阶点乘.
    colVandermonde = colVandermonde.array() * sampleX.array();
    mtxVandermonde.col(i) = colVandermonde;
  }
  // 求解线性问题 (X^T * X)^(-1) * X^T * Y.
  Eigen::VectorXd r = (mtxVandermonde.transpose() * mtxVandermonde).ldlt().solve(mtxVandermonde.transpose() * sampleY);
  ret.resize(r.size());
  Eigen::VectorXd::Map(&ret[0], r.size()) = r;
  return ret;
}

TheoryVolatilityCurve::TheoryVolatilityCurve(TheoryVolatilityCurveEngine* engine,
  const std::set<std::shared_ptr<md::InstrumentNode>>& option_nodes,
  std::function<double(std::shared_ptr<md::InstrumentNode>)> price_func /*= nullptr*/)
  : m_engine(engine)
  , m_option_ins_nodes(option_nodes)
  , m_price_func(price_func) {}

/**
 * 获取理论波动率.
 * @param strike_price : 行权价
 */

double TheoryVolatilityCurve::GetTheoryVolatility(double strike_price) const {
  return std::max(
    m_curve_params.a0 + m_curve_params.a1 * strike_price + m_curve_params.a2 * strike_price * strike_price, 0.0);
}

void TheoryVolatilityCurve::FitCurve() {
  std::vector<double> strike_price;
  std::vector<double> volatility;
  for (const auto& option_node : m_option_ins_nodes) {
    if (option_node->Latest()->ProductClass() != md::ProductClass::kOption)
      continue;
    double price = m_price_func ? m_price_func(option_node)
                                : ((option_node->Latest()->ask_price[0] + option_node->Latest()->bid_price[0]) / 2.0);
    if (isnan(option_node->Latest()->strike_price) || isnan(price) || price < 0.0)
      continue;
    double v = m_engine->m_option_calc->ImpliedVolatility(option_node, price);
    if (isnan(v) || EqualDouble(v, 0.0, 3))
      continue;
    strike_price.push_back(option_node->Latest()->strike_price);
    volatility.push_back(v);
  }
  auto ret = FitLeastSquareMethod(strike_price, volatility, 2);
  if (ret.size() == 3) {
    m_curve_params.a0 = ret[0];
    m_curve_params.a1 = ret[1];
    m_curve_params.a2 = ret[2];
  }
}

// 返回值如 CF301-C 或 000300|20221101-P.
const inline std::string GetKey(const std::shared_ptr<const md::Instrument> option_node) {
  auto underlying = option_node->instrument_base->underlying_pointer->Latest();
  // key: 标的为期货如 CF301, 为股指如 000300.
  std::string key = underlying->instrument_id;
  if (underlying->ProductClass() == md::ProductClass::kIndex)
    key += "|" + option_node->instrument_base->last_exercise_day_str;
  if (option_node->option_class == md::OptionClass::kCall)
    key += "-C";
  else
    key += "-P";
  return key;
}

TheoryVolatilityCurveEngine::TheoryVolatilityCurveEngine(
  std::shared_ptr<TqApi> tqapi, OptionCalculator* option_calculator)
  : m_tqapi(tqapi)
  , m_option_calc(option_calculator) {
  m_ins_view = m_tqapi->DataDb()->CreateView<md::Instrument>([&](std::shared_ptr<const md::Instrument> ins) -> bool {
    if (ins->ProductClass() == md::ProductClass::kOption) {
      if (ins->instrument_base->underlying_pointer) {
        return m_subscribed.count(GetKey(ins));
      }
    } else if (ins->ProductClass() == md::ProductClass::kFuture || ins->ProductClass() == md::ProductClass::kIndex) {
      auto it = m_subscribed.lower_bound(ins->instrument_id);
      if (it != m_subscribed.end() && it->first.rfind(ins->instrument_id, 0) == 0) {
        return true;
      }
    }
    return false;
  });

  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins_node, bool is_last) {
      if (ins_node->Latest()->ProductClass() == md::ProductClass::kOption) {
        if (ins_node->Latest()->instrument_base->underlying_pointer) {
          m_need_refresh.insert(GetKey(ins_node->Latest()));
        }
      } else if (ins_node->Latest()->ProductClass() == md::ProductClass::kFuture
        || ins_node->Latest()->ProductClass() == md::ProductClass::kIndex) {
        auto it = m_subscribed.lower_bound(ins_node->Latest()->instrument_id);
        while (it != m_subscribed.end() && it->first.rfind(ins_node->Latest()->instrument_id, 0) == 0) {
          m_need_refresh.insert(it->first);
          ++it;
        }
      }
      if (!m_need_refresh.empty() && m_timer.IsExpired()) {
        m_timer.Reset(std::chrono::seconds(5));
        for (const auto& key : m_need_refresh) {
          auto it = m_subscribed.find(key);
          if (it != m_subscribed.end()) {
            it->second.volatility_curve->FitCurve();
          }
        }
        m_need_refresh.clear();
      }
    });
}

TheoryVolatilityCurveEngine::~TheoryVolatilityCurveEngine() {}

void TheoryVolatilityCurveEngine::CleanUp() {
  m_quote_handles.clear();
}

void TheoryVolatilityCurveEngine::SubscribeVolatility(std::shared_ptr<md::InstrumentNode> option_node,
  std::function<double(std::shared_ptr<md::InstrumentNode>)> price_func /* = nullptr */) {
  if (option_node->Latest()->ProductClass() != md::ProductClass::kOption)
    return;

  std::string key = GetKey(option_node->Latest());
  auto it = m_subscribed.find(key);
  if (it != m_subscribed.end()) {
    // 订阅过, 增加订阅计数, 直接返回.
    ++(it->second.subscribe_cnt);
    return;
  }

  // 获取同一标的, 同一到期日, 同方向, 不同执行价的期权合约集合.
  std::set<std::shared_ptr<md::InstrumentNode>> option_node_set;
  auto underlying = option_node->Latest()->instrument_base->underlying_pointer->Latest();
  for (auto& [_, ins_pointer] : underlying->instrument_base->derivate_pointer) {
    if (!ins_pointer)
      continue;
    auto ins = ins_pointer->Latest();
    if (ins->ProductClass() == md::ProductClass::kOption && ins->option_class == option_node->Latest()->option_class
      && ins->instrument_base->last_exercise_day_str == option_node->Latest()->instrument_base->last_exercise_day_str) {
      option_node_set.insert(ins_pointer);
      m_quote_handles[key].insert(m_tqapi->GetQuoteSubscriber()->SubscribeQuote(ins_pointer.get()));
    }
  }
  it = m_subscribed.insert(std::make_pair(key, SubscribeInfo())).first;
  ++(it->second.subscribe_cnt);
  it->second.volatility_curve = std::make_shared<TheoryVolatilityCurve>(this, option_node_set, price_func);
  it->second.volatility_curve->FitCurve();
}

bool TheoryVolatilityCurveEngine::UnsubscribeVolatility(std::shared_ptr<md::InstrumentNode> ins_node) {
  auto key = GetKey(ins_node->Latest());
  auto it = m_subscribed.find(key);
  if (it == m_subscribed.end())
    return false;
  --(it->second.subscribe_cnt);
  if (it->second.subscribe_cnt == 0) {
    m_quote_handles.erase(key);
    m_subscribed.erase(it);
  }
  return true;
}

double TheoryVolatilityCurveEngine::GetFittedVolatility(std::shared_ptr<md::InstrumentNode> ins_node) {
  auto it = m_subscribed.find(GetKey(ins_node->Latest()));
  if (it == m_subscribed.end())
    return NAN;
  return it->second.volatility_curve->GetTheoryVolatility(ins_node->Latest()->strike_price);
}

