namespace fclib {
namespace extension {
class MarketSerializer : public rapid_serialize::Serializer<MarketSerializer> {
 public:
  using rapid_serialize::Serializer<MarketSerializer>::Serializer;
  void DefineStruct(MarketAvgPriceEval::MarketEvalPack& item) {
    AddItem(item.weight, "weight");
    AddItem(item.stored_amount, "stored_amount");
    AddItem(item.stored_volume, "stored_volume");
    AddItem(item.constant_term, "constant_term");
  }
};

MarketAvgPriceEval::MarketAvgPriceEval(
  std::shared_ptr<TqApi> api, std::shared_ptr<md::InstrumentNode> node, const future::Direction& direction) {
  Init(api, MarketAvgPriceEval::CalcWeight(node, direction));
  if (node)
    m_constant_term = node->Latest()->instrument_base->constant_term;
}

MarketAvgPriceEval::MarketAvgPriceEval(std::shared_ptr<TqApi> api, std::string const& params_pack) {
  FCASSERT(api);
  std::map<std::string, MarketEvalPack> pack;
  MarketSerializer ss;
  ss.FromString(params_pack.c_str());
  ss.ToVar(pack);

  std::set<std::string> symbol_set;
  std::string symbol_key;
  for (const auto& [symbol, p] : pack) {
    // 常数项
    if (symbol == "1") {
      m_constant_term = p.constant_term;
      continue;
    }
    auto node = api->DataDb()->GetNode<md::Instrument>(symbol);
    if (node == nullptr) {
      m_details.clear();
      break;
    }
    FCASSERT(node);
    auto detail = std::make_shared<MarketEvalDetail>();
    detail->weight = p.weight;
    detail->stored_amount = p.stored_amount;
    detail->stored_volume = p.stored_volume;
    detail->market_avg_price = NAN;
    m_details[node] = detail;
    symbol_set.insert(symbol);
    symbol_key += symbol;
  }

  m_ins_view = api->DataDb()->CreateView<md::Instrument>(
    symbol_key, false, [symbol_set](std::shared_ptr<const md::Instrument> ins) {
      return symbol_set.find(ins->symbol) != symbol_set.end();
    });

  // 刷新市场均价, 用于恢复存档
  UpdateEval(false);
}

void MarketAvgPriceEval::Start() {
  if (is_running) {
    return;
  }
  is_running = true;

  for (const auto& [node, detail] : m_details) {
    detail->start_amount = node->Latest()->amount;
    detail->start_volume = node->Latest()->volume;
  }
  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<md::InstrumentNode>, bool is_last) {
      if (is_last) {
        UpdateEval();
      }
    });
}

void MarketAvgPriceEval::Pause() {
  if (!is_running) {
    return;
  }
  is_running = false;

  for (const auto& [node, detail] : m_details) {
    detail->stored_amount = node->Latest()->amount - detail->start_amount;
    detail->stored_volume = node->Latest()->volume - detail->start_volume;
    detail->start_amount = 0.0;
    detail->start_volume = 0;
  }
  m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
}

double MarketAvgPriceEval::GetMarketAvgPrice() const {
  double avg_price = 0;
  if (m_details.empty()) {
    return NAN;
  }
  for (const auto& [node, detail] : m_details) {
    // 郑商所无法计算市场均价
    if (node->Latest()->ExchangeID() == "CZCE") {
      return NAN;
    }
    avg_price += detail->market_avg_price * detail->weight;
  }
  return avg_price + m_constant_term;
}

void MarketAvgPriceEval::RegisterNotify(std::function<void()> func) {
  m_func.push_back(func);
}

std::string MarketAvgPriceEval::Save() {
  Pause();
  std::map<std::string, MarketEvalPack> params_pack;
  for (const auto& [key, details] : m_details) {
    params_pack[key->Latest()->symbol].weight = details->weight;
    params_pack[key->Latest()->symbol].stored_amount = details->stored_amount;
    params_pack[key->Latest()->symbol].stored_volume = details->stored_volume;
  }
  params_pack["1"].constant_term = m_constant_term;  // 常数项单独处理
  MarketSerializer ss;
  std::string res;
  ss.FromVar(params_pack);
  ss.ToString(&res);
  return res;
}

std::shared_ptr<MarketAvgPriceEval> MarketAvgPriceEval::Load(
  std::shared_ptr<TqApi> api, std::string const& params_pack) {
  if (params_pack.empty()) {
    return nullptr;
  }
  auto ptr = std::make_shared<MarketAvgPriceEval>(api, params_pack);
  if (ptr->m_details.empty()) {
    return nullptr;
  }
  return ptr;
}

std::map<std::shared_ptr<fclib::md::InstrumentNode>, double> MarketAvgPriceEval::CalcWeight(
  std::shared_ptr<md::InstrumentNode> ins_node, const future::Direction& direction) {
  std::map<std::shared_ptr<md::InstrumentNode>, double> weight;
  if (ins_node->Latest()->instrument_base->product_base->product_class == fclib::md::ProductClass::kCusCombine) {
    for (const auto& [k, w] : ins_node->Latest()->instrument_base->weight) {
      if (k->Latest()->instrument_base->product_base->product_class == fclib::md::ProductClass::kCombine) {
        // 处理官方组合
        if (direction == future::Direction::kBuy) {
          weight[ins_node->Latest()->instrument_base->leg1_pointer] = 1;
          weight[ins_node->Latest()->instrument_base->leg2_pointer] = -1;
        } else {
          weight[ins_node->Latest()->instrument_base->leg1_pointer] = -1;
          weight[ins_node->Latest()->instrument_base->leg2_pointer] = 1;
        }
      } else {
        weight[k] = w;
      }
    }
  } else if (ins_node->Latest()->instrument_base->product_base->product_class == fclib::md::ProductClass::kCombine) {
    // 处理官方组合
    if (direction == future::Direction::kBuy) {
      weight[ins_node->Latest()->instrument_base->leg1_pointer] = 1;
      weight[ins_node->Latest()->instrument_base->leg2_pointer] = -1;
    } else {
      weight[ins_node->Latest()->instrument_base->leg1_pointer] = -1;
      weight[ins_node->Latest()->instrument_base->leg2_pointer] = 1;
    }
  } else {
    weight[ins_node] = 1;
  }

  return weight;
}

void MarketAvgPriceEval::Init(
  std::shared_ptr<TqApi> api, std::map<std::shared_ptr<md::InstrumentNode>, double> const& ins_map) {
  FCASSERT(api);
  std::set<std::string> symbol_set;
  std::string symbol_key;
  for (const auto& [node, weight] : ins_map) {
    FCASSERT(node);
    auto detail = std::make_shared<MarketEvalDetail>();
    detail->weight = weight;
    detail->stored_amount = 0;
    detail->stored_volume = 0;
    detail->market_avg_price = NAN;
    m_details[node] = detail;
    symbol_set.insert(node->Latest()->symbol);
    symbol_key += node->Latest()->symbol;
  }

  m_ins_view = api->DataDb()->CreateView<md::Instrument>(
    symbol_key, false, [symbol_set](std::shared_ptr<const md::Instrument> ins) {
      return symbol_set.find(ins->symbol) != symbol_set.end();
    });
}

void MarketAvgPriceEval::UpdateEval(bool include_ins) const {
  for (const auto& [node, detail] : m_details) {
    FCASSERT(node);
    double amount = detail->stored_amount;
    int64_t volume = detail->stored_volume;
    if (include_ins) {
      amount += node->Latest()->amount - detail->start_amount;
      volume += node->Latest()->volume - detail->start_volume;
    }
    if (volume > 0) {
      detail->market_avg_price = amount / (volume * node->Latest()->VolumeMultiple());
    }
  }

  for (const auto& func : m_func) {
    func();
  }
}

}  // namespace extension
}  // namespace fclib

