TargetPosAgentImpl::TargetPosAgentImpl(std::shared_ptr<TqApi> api, const std::string& user_key,
  const std::string& symbol, int32_t unit_id, const std::string& price, const std::string& offset_priority,
  std::function<double(const future::Direction& direction)> price_func /*= nullptr*/)
  : m_api(api)
  , m_user_key(user_key)
  , m_symbol(symbol)
  , m_unit_id(unit_id)
  , m_price(price)
  , m_offset_priority(offset_priority)
  , m_price_func(price_func)
  , m_msg_cnt(0)
  , m_running(false)
  , m_delta_volume(0)
  , m_pedding_frozen(0)
  , m_logger((*((structlog::Logger*)(api->GetLogger())))
               .With("extension", "TargetPosAgent")
               .With("symbol", symbol)
               .With("instance", reinterpret_cast<int64_t>(this))
               .Clone()) {}

TargetPosAgentImpl::~TargetPosAgentImpl() {}

void TargetPosAgentImpl::Init() {
  if (m_unit_id < 0 || m_unit_id > 100) {
    m_status_msg = u8"已停止, 交易单元信息不合法";
    m_status = TargetPosTaskStatus::kStopped;
    return;
  }
  m_ins_node = m_api->DataDb()->GetNode<md::Instrument>(m_symbol);
  if (m_ins_node->Latest()->instrument_base->min_limit_order_volume > 1
    || m_ins_node->Latest()->instrument_base->min_market_order_volume > 1) {
    m_status_msg = u8"交易所规定 " + m_ins_node->Latest()->symbol + u8" 最小市价开仓手数 "
      + std::to_string(m_ins_node->Latest()->instrument_base->min_market_order_volume) + u8" 或最小限价开仓手数 "
      + std::to_string(m_ins_node->Latest()->instrument_base->min_limit_order_volume)
      + u8"大于 1，targetpostask、twap、vwap 这些函数还未支持该规则!";
    m_status = TargetPosTaskStatus::kStopped;
    return;
  }
  m_login_node = m_api->DataDb()->GetNode<future::LoginContent>(m_user_key);
  // 订阅行情
  SubscribeQuote();
  auto position_key = m_user_key + "|" + std::to_string(m_unit_id) + "|" + m_symbol;
  if (!m_api->DataDb()->GetNode<future::Position>(position_key)) {
    auto pos = CreateUpdatePosition();
    m_api->DataDb()->ReplaceRecord<future::Position>(pos);
  }
  m_position_node = m_api->DataDb()->GetNode<future::Position>(position_key);
  m_volume = 0;
  m_status_msg = u8"运行中";
  m_status = TargetPosTaskStatus::kStarted;
  ResetOffsetQueue(m_offset_priority);
}

std::shared_ptr<future::Position> TargetPosAgentImpl::CreateUpdatePosition() {
  auto pos = std::make_shared<future::Position>();
  pos->user_key = m_user_key;
  pos->exchange_id = m_symbol.substr(0, m_symbol.find("."));
  pos->instrument_id = m_symbol.substr(m_symbol.find(".") + 1);
  pos->investor_id = m_login_node->Latest()->user_id;
  pos->ins_pointer = m_api->DataDb()->GetNode<md::Instrument>(m_symbol);
  pos->unit_id = m_unit_id;
  if (pos->ins_pointer) {
    pos->last_price = pos->ins_pointer->Latest()->last_price;
  }
  return pos;
}

void TargetPosAgentImpl::SetTargetVolume(md::Volume vol) {
  m_volume = vol;
  m_running = true;
}

void TargetPosAgentImpl::SetAddOrderIdCallBack(std::function<void(const std::string&)> add_order_id_func) {
  m_add_order_id_func = add_order_id_func;
}

bool TargetPosAgentImpl::CheckTradingTime() {
  auto time_range = InstrumentTradingTime::Instance().GetTradingTimeTable(m_ins_node->Latest());
  auto now = EpochNanoToLocalDateTime(NowAsEpochNano(), 8);
  auto now_time = now.date_time.tm_hour * 10000 + now.date_time.tm_min * 100 + now.date_time.tm_sec;
  auto it = time_range.upper_bound(now_time);
  if (it == time_range.end() || it->second == true) {
    return false;
  }
  return true;
}

int TargetPosAgentImpl::RunOnce() {
  m_msg_cnt = 0;
  if (!m_running) {
    return m_msg_cnt;
  }
  if (!m_ins_node) {
    m_status = TargetPosTaskStatus::kStopped;
    m_status_msg = u8"已停止, 合约不存在";
  }
  if (m_price != "ACTIVE" && m_price != "PASSIVE" && !m_price_func) {
    m_status = TargetPosTaskStatus::kStopped;
    m_status_msg = u8"已停止: 下单方式错误, 请选用ACTIVE或PASSIVE或自定义价格";
  }
  if (!m_login_node || !m_login_node->Latest() || m_login_node->Latest()->user_id.empty()) {
    m_status = TargetPosTaskStatus::kStopped;
    m_status_msg = u8"已停止: 未登录";
  }
  if (m_status == TargetPosTaskStatus::kStopped) {
    return -1;
  }
  if (!CheckTradingTime()) {
    return 0;
  }
  auto pos = m_position_node->Latest();
  // kStarted状态: 初始化/重置参数
  if (m_status == TargetPosTaskStatus::kStarted) {
    m_delta_volume = m_volume - pos->subpos_long_spec.Volume() + pos->subpos_short_spec.Volume();
    m_pedding_frozen = 0;
    m_processing_task.clear();
    ResetOffsetQueue(m_offset_priority);
    // 无需调整，即返回0.否则切换 kContinued状态进行下单调整
    if (m_delta_volume == 0) {
      return m_msg_cnt;
    } else {
      m_status = TargetPosTaskStatus::kContinued;
    }
  }
  // kContinued状态: 进行连续下单, 遇到","切换 kWaiting状态.
  // kWaiting状态:   进行委托单成交等待. 当委托单全部成交后:
  //                 根据offset_queue切换 kContinued 和 kStarted状态
  if (m_status == TargetPosTaskStatus::kContinued) {
    while (!m_offset_queue.empty()) {
      // offset_priority 轮询
      auto offset = m_offset_queue.front();
      // 等待标志，进入等待模式
      if (offset == ",") {
        m_offset_queue.pop();
        if (m_processing_task.empty() && m_trade_view_map.empty()) {
          if (!m_offset_queue.empty())
            continue;
          m_status = TargetPosTaskStatus::kStarted;
        }
        m_status = TargetPosTaskStatus::kWaiting;
        // 错误处理 (待修改)
        if (!ProcessTask()) {
          m_status = TargetPosTaskStatus::kStopped;
          return -1;
        }
        return m_msg_cnt;
      }
      auto orderinfo = GetOrder(m_symbol, offset, m_delta_volume, m_pedding_frozen, pos);
      // 更新pedding_frozen和delta_volume
      if (orderinfo.volume == 0) {
        m_offset_queue.pop();
        continue;
      } else if (orderinfo.offset != future::Offset::kOpen) {
        m_pedding_frozen += orderinfo.volume;
      }
      m_delta_volume -= (orderinfo.direction == future::Direction::kBuy) ? orderinfo.volume : -orderinfo.volume;
      if (!InsertOrder(orderinfo)) {
        m_status_msg = u8"已停止: 用户自定义下单价格为nan";
        m_status = TargetPosTaskStatus::kStopped;
        return -1;
      }
      m_offset_queue.pop();
    }
  } else if (m_status == TargetPosTaskStatus::kWaiting) {
    bool res = ProcessTask();
    if (!m_processing_task.empty()) {
      // 错误处理 (待修改)
      if (!res) {
        m_status = TargetPosTaskStatus::kStopped;
        return -1;
      }
      return m_msg_cnt;
    }
    if (!m_trade_view_map.empty()) {
      ProcessOrderTrade();
    } else {
      if (!m_offset_queue.empty())
        m_status = TargetPosTaskStatus::kContinued;
      else
        m_status = TargetPosTaskStatus::kStarted;
    }
  }
  return m_msg_cnt;
}

TargetPosAgentImpl::OrderInfo TargetPosAgentImpl::GetOrder(const std::string& symbol, const std::string& offset,
  const md::Volume& vol, const md::Volume& pending_frozen, std::shared_ptr<const future::Position> pos) {
  OrderInfo order = {};
  md::Volume frozen_vol = 0;
  std::string exchange = symbol.substr(0, symbol.find("."));
  order.direction = (vol > 0) ? future::Direction::kBuy : future::Direction::kSell;
  md::Volume pos_vol = (vol > 0) ? pos->subpos_short_spec.Volume() : pos->subpos_long_spec.Volume();
  if (offset == u8"昨") {
    order.offset = future::Offset::kClose;
    if (exchange == "SHFE" || exchange == "INE") {
      order.offset = future::Offset::kCloseYesterday;
      pos_vol = (vol > 0) ? pos->subpos_short_spec.volume_his : pos->subpos_long_spec.volume_his;
      frozen_vol = (vol > 0) ? pos->subpos_short_spec.volume_his_frozen : pos->subpos_long_spec.volume_his_frozen;
    } else {
      auto pos_frozen = (vol > 0) ? pos->subpos_short_spec.VolumeFrozen() : pos->subpos_long_spec.VolumeFrozen();
      frozen_vol = pending_frozen + pos_frozen;
      // 判断是否有未冻结的今仓手数: 若有则不平昨仓
      auto pos_today = (vol > 0) ? pos->subpos_short_spec.volume_today : pos->subpos_long_spec.volume_today;
      if ((pos_today - frozen_vol) > 0) {
        pos_vol = frozen_vol;
      }
    }
    order.volume = std::min(abs(vol), std::max(0, pos_vol - frozen_vol));
  } else if (offset == u8"今") {
    pos_vol = (vol > 0) ? pos->subpos_short_spec.volume_today : pos->subpos_long_spec.volume_today;
    if (exchange == "SHFE" || exchange == "INE") {
      order.offset = future::Offset::kCloseToday;
      frozen_vol = (vol > 0) ? pos->subpos_short_spec.volume_today_frozen : pos->subpos_long_spec.volume_today_frozen;
    } else {
      order.offset = future::Offset::kClose;
      auto pos_frozen = (vol > 0) ? pos->subpos_short_spec.VolumeFrozen() : pos->subpos_long_spec.VolumeFrozen();
      frozen_vol = pending_frozen + pos_frozen;
    }
    order.volume = std::min(abs(vol), std::max(0, pos_vol - frozen_vol));
  } else if (offset == u8"开") {
    order.offset = future::Offset::kOpen;
    order.volume = abs(vol);
  } else {
    order.offset = future::Offset::kInvalid;
    order.volume = 0;
  }
  return order;
}

double TargetPosAgentImpl::CalOrderPrice(const future::Direction& direction, const std::string& price,
  std::shared_ptr<md::InstrumentNode> ins_node, std::function<double(const future::Direction& direction)> price_func) {
  if (price_func)
    return price_func(direction);
  if ((price == "ACTIVE" && direction == future::Direction::kBuy)
    || (price == "PASSIVE" && direction == future::Direction::kSell)) {
    return ins_node->Latest()->ask_price[0];
  }
  if ((price == "ACTIVE" && direction == future::Direction::kSell)
    || (price == "PASSIVE" && direction == future::Direction::kBuy)) {
    return ins_node->Latest()->bid_price[0];
  }
  return 0.0;
}

void TargetPosAgentImpl::ResetOffsetQueue(std::string offset_priority) {
  std::queue<std::string> empty;
  std::swap(empty, m_offset_queue);
  // 开平仓顺序切割
  for (size_t i = 0; i < offset_priority.size();) {
    if (is_zh_ch(offset_priority.at(i))) {
      m_offset_queue.push(offset_priority.substr(i, 3));
      i += 3;
    } else {
      m_offset_queue.push(offset_priority.substr(i, 1));
      i++;
    }
  }
  // 添加终止符
  m_offset_queue.push(",");
}

bool TargetPosAgentImpl::InsertOrder(OrderInfo& orderinfo) {
  auto limit_price = CalOrderPrice(orderinfo.direction, m_price, m_ins_node, m_price_func);
  if (isnan(limit_price) && m_price_func)
    return false;
  auto target = std::make_shared<future::InsertOrder>(m_user_key);
  target->exchange_id = m_symbol.substr(0, m_symbol.find("."));
  target->instrument_id = m_symbol.substr(m_symbol.find(".") + 1);
  target->direction = orderinfo.direction;
  target->offset = orderinfo.offset;
  target->volume = orderinfo.volume;
  target->unit_id = m_unit_id;
  target->hedge_flag = future::OrderHedgeFlag::kSpeculation;
  target->price_type = future::PriceType::kLimit;
  target->time_condition = future::OrderTimeCondition::kGfd;
  target->volume_condition = future::OrderVolumeCondition::kAny;
  target->limit_price = limit_price;
  auto task = std::make_shared<Task>();
  task->origin_insert_order = target;
  m_processing_task.push_back(task);
  return true;
}

bool TargetPosAgentImpl::ProcessTask() {
  for (auto it = m_processing_task.begin(); it != m_processing_task.end();) {
    auto task = *it;
    if (task->insert_order) {
      if (task->insert_order->status != UserCommand::Status::kFinished) {
        ++it;
        continue;
      }
      if (task->insert_order->result_code != 0) {
        m_status_msg =
          u8"已停止" + (task->insert_order->result_msg.empty() ? "" : (": " + task->insert_order->result_msg));
        return false;
      }
      if (!task->insert_order->order_pointer) {
        m_status_msg = u8"已停止: 下单指令没有返回委托单节点";
        return false;
      }
      task->order = task->insert_order->order_pointer;
      task->insert_order.reset();
    }
    // 行情服务无数据, 刷新价格, 不作任何处理
    if (!m_price_func
      && (isnan(task->origin_insert_order->limit_price) || task->origin_insert_order->limit_price == 0.0)) {
      task->origin_insert_order->limit_price =
        CalOrderPrice(task->origin_insert_order->direction, m_price, m_ins_node, m_price_func);
      ++it;
      continue;
    }
    // 清除已成交完成的task
    if (task->order && task->order->Latest()->volume_left == 0) {
      it = m_processing_task.erase(it);
      TrackOrderTrade(task->order);
      continue;
    }
    // 价格未更新，跳过task
    if (task->order
      && task->order->Latest()->limit_price
        == CalOrderPrice(task->order->Latest()->direction, m_price, m_ins_node, m_price_func)) {
      ++it;
      continue;
    }
    // 撤单
    if (task->order && task->order->Latest()->status == future::OrderStatus::kAlive) {
      if (task->canceling_order != task->order) {
        m_msg_cnt++;
        auto cancel_order = std::make_shared<future::CancelOrder>(m_user_key);
        cancel_order->order_id = task->order->Latest()->order_id;
        m_api->AsyncRequest(cancel_order);
        // 撤单失败停止处理task，返回错误
        if (cancel_order->result_code != 0) {
          m_status_msg = u8"已停止: " + cancel_order->result_msg;
          return false;
        }
        task->canceling_order = task->order;
      }
    } else {
      // 下单
      m_msg_cnt++;
      auto insert_order = std::make_shared<future::InsertOrder>(*(task->origin_insert_order));
      insert_order->unit_id = m_unit_id;
      // 如已有订单，更新价格
      if (task->order) {
        if (task->order->Latest()->status_msg == u8"交易日结束，自动撤销当日有效的委托单(GFD)") {
          m_status_msg = u8"已停止: " + task->order->Latest()->status_msg;
          return false;
        }
        insert_order->limit_price = CalOrderPrice(task->order->Latest()->direction, m_price, m_ins_node, m_price_func);
        insert_order->volume = task->order->Latest()->volume_left;
      }
      if (isnan(insert_order->limit_price)) {
        m_status_msg = u8"已停止: 下单价格为nan";
        return false;
      }
      m_api->AsyncRequest(insert_order);
      if (m_add_order_id_func)
        m_add_order_id_func(insert_order->order_id);
      // 下单失败停止处理task，返回错误
      if (insert_order->result_code != 0) {
        m_status_msg = u8"已停止: " + insert_order->result_msg;
        return false;
      }
      task->insert_order = insert_order;
    }
    ++it;
  }
  return true;
}

void TargetPosAgentImpl::TrackOrderTrade(std::shared_ptr<future::OrderNode> order) {
  std::shared_ptr<NodeDbView<future::Trade>> trade_view;
  auto iter = m_trade_view_map.find(order->Snap()->order_id);
  if (iter != m_trade_view_map.end()) {
    trade_view = iter->second;
  } else {
    trade_view = m_api->DataDb()->CreateView<future::Trade>([=](std::shared_ptr<const future::Trade> trade) {
      return trade->order_id == order->Snap()->order_id;
    });
    m_trade_view_map.insert(std::make_pair(order->Snap()->order_id, trade_view));
  }
  if (CheckOrderTrade(order->Snap()->order_id, trade_view))
    m_trade_view_map.erase(order->Snap()->order_id);
}

void TargetPosAgentImpl::ProcessOrderTrade() {
  for (auto iter = m_trade_view_map.begin(); iter != m_trade_view_map.end(); iter++) {
    auto order_id = iter->first;
    auto trade_view = iter->second;
    if (CheckOrderTrade(order_id, trade_view))
      iter = m_trade_view_map.erase(iter);
  }
}

bool TargetPosAgentImpl::CheckOrderTrade(
  const std::string& order_id, std::shared_ptr<NodeDbView<future::Trade>> trade_view) {
  int trade_volume = 0;
  std::shared_ptr<future::OrderNode> order_node;
  if (trade_view->GetNodes().empty())
    return false;
  for (const auto& [_, trade_node] : trade_view->GetNodes()) {
    trade_volume += trade_node->Snap()->volume;
    if (!order_node)
      order_node = trade_node->Snap()->order_pointer;
  }
  if (!order_node)
    order_node = m_api->DataDb()->GetNode<future::Order>(m_user_key + "|" + order_id);
  if (!order_node || trade_volume >= order_node->Snap()->VolumeTrade()) {
    return true;
  }
  return false;
}

void TargetPosAgentImpl::SubscribeQuote() {
  if (!m_ins_node || m_ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine)
    return;
  std::shared_ptr<md::SubscribeQuote> cmd = std::make_shared<md::SubscribeQuote>();
  cmd->subscribe_id = std::to_string(reinterpret_cast<int64_t>(this));
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
    cmd->comb_node_set.insert(m_ins_node);
  } else {
    cmd->node_set.insert(m_ins_node);
    if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kOption) {
      std::shared_ptr<md::InstrumentNode> underlying_node = m_ins_node->Latest()->instrument_base->underlying_pointer;
      if (underlying_node)
        cmd->node_set.insert(underlying_node);
    }
  }
  m_api->AsyncRequest(cmd);
}

