  {"CFFEX", {4000, 8000, 12000}},
  {"GFEX", {4000, 8000}},
};

// 计算申报费
double CalcFee(const std::string& exchange_id, std::string product_id, int amount, double OTR) {
  double fee = 0.0;
  if (rates.count(exchange_id) == 0)
    return fee;
  int idx = 1 - (OTR <= 2.0);
  if (rates.at(exchange_id).count(product_id) == 0)
    return fee;

  auto& rate_t = rates.at(exchange_id).at(product_id);
  for (size_t i = 0; i < rate_t.size(); i++) {
    int border = level.at(exchange_id).at(i);
    double rate = rate_t.at(i).at(idx);
    double last = i == 0 ? 0 : rate_t.at(i - 1).at(idx);
    if (amount > border)
      fee += (amount - border) * (rate - last);
  }
  return fee;
}

template <class Compare>
void ReplaceOrder(
  std::list<NodePointer<future::Order>>* order_list, NodePointer<future::Order> order_pointer, Compare comp) {
  auto it = std::find(order_list->begin(), order_list->end(), order_pointer);
  if (it == order_list->end() && order_pointer->Latest()->status == future::OrderStatus::kAlive)
    order_list->push_back(order_pointer);
  if (it != order_list->end()
    && (order_pointer->Latest()->status == future::OrderStatus::kDead || order_pointer->Latest()->volume_left == 0))
    order_list->erase(it);
  order_list->sort(comp);
  if (order_list->size() > 10)
    order_list->pop_back();
}

void UpdateSHFEQuoteLength(
  std::shared_ptr<DailyTradingReportItem> report_item, int max_spread, int64_t delta_time, double offer_spread) {
  if (isnan(offer_spread) || max_spread <= 1)
    return;
  if (report_item->m_ins_pointer->Latest()->ExchangeID() != "SHFE"
    && report_item->m_ins_pointer->Latest()->ExchangeID() != "INE")
    return;
  report_item->shfe_quote_spread += (max_spread - offer_spread) / (max_spread - 1) * delta_time;
}

double GetDCESpreadGear(int max_spread, std::shared_ptr<DailyTradingReportItem> report_item) {
  double average_spread = report_item->average_quote_spread();
  if (isnan(average_spread))
    return NAN;
  if (average_spread > 0.0 && average_spread < 0.35 * max_spread)
    return 0.3;
  if (average_spread >= 0.35 * max_spread && average_spread < 0.45 * max_spread)
    return 0.25;
  if (average_spread >= 0.45 * max_spread && average_spread < 0.55 * max_spread)
    return 0.2;
  if (average_spread >= 0.55 * max_spread && average_spread < 0.65 * max_spread)
    return 0.15;
  if (average_spread >= 0.65 * max_spread && average_spread < 0.8 * max_spread)
    return 0.08;
  if (average_spread >= 0.8 * max_spread && average_spread < 1.0 * max_spread)
    return 0.02;
  return NAN;
}

void CalcDCECmulativeSpreadCoefficient(double spread_gear, std::shared_ptr<DailyTradingReportItem> report_item) {
  if (report_item->total_length > 0)
    report_item->cumulative_spread_coefficient = spread_gear * report_item->valid_quote_length / 1e9;
}

void CalcDCEQuoteSpreadCoefficient(double spread_gear, std::shared_ptr<DailyTradingReportItem> report_item) {
  auto trading_length = InstrumentTradingTime::Instance().GetSpecificTradingTimeLength(
    report_item->m_ins_pointer->Latest(), NowAsEpochNano());
  if (trading_length > 0)
    report_item->quote_spread_coefficient = spread_gear
      * (report_item->valid_quote_length / static_cast<double>(trading_length)) * report_item->total_length / 1e9;
}

void CalcSHFECmulativeSpreadCoefficient(std::shared_ptr<DailyTradingReportItem> report_item) {
  if (report_item->total_length > 0) {
    report_item->cumulative_spread_coefficient = report_item->shfe_quote_spread / report_item->total_length;
  }
}

void CalcSHFEQuoteSpreadCoefficient(std::shared_ptr<DailyTradingReportItem> report_item) {
  auto trading_length = InstrumentTradingTime::Instance().GetSpecificTradingTimeLength(
    report_item->m_ins_pointer->Latest(), NowAsEpochNano());
  if (trading_length > 0) {
    report_item->quote_spread_coefficient = report_item->shfe_quote_spread / trading_length;
  }
}

bool IsInNight(md::EpochNano datetime) {
  auto dt = EpochNanoToLocalDateTime(datetime, 8);
  return dt.date_time.tm_hour > 19 || dt.date_time.tm_hour < 5;
}

std::string GetPositionKeySymbol(std::shared_ptr<future::PositionNode> position_node) {
  if (!position_node->Snap()->ins_pointer
    || position_node->Snap()->ins_pointer->Latest()->ProductClass() != md::ProductClass::kOption)
    return "";
  auto underlying_node = position_node->Snap()->ins_pointer->Latest()->instrument_base->underlying_pointer;
  if (!underlying_node)
    return "";
  return underlying_node->Latest()->symbol;
}

bool IsCanceled(std::shared_ptr<const future::Order> order) {
  return (order && order->status == future::OrderStatus::kDead && order->volume_left > 0
    && !order->exchange_order_id.empty());
}

bool IsCanceled(std::shared_ptr<future::OrderNode> node) {
  return IsCanceled(node->Latest()) && !IsCanceled(node->Historical());
}

DailyTradingReporterImpl::DailyTradingReporterImpl(std::shared_ptr<TqApi> api, std::shared_ptr<OptionCalculator> calc)
  : m_api(api)
  , m_option_calc(calc)
  , m_logger((*((structlog::Logger*)(api->GetLogger())))
               .With("extension", "DailyTradingReport")
               .With("instance", reinterpret_cast<int64_t>(this))
               .Clone()) {}

DailyTradingReporterImpl::~DailyTradingReporterImpl() {}

void DailyTradingReporterImpl::Init() {
  FCASSERT(m_option_calc);
  m_root_node_db = m_api->DataDb();
  m_ins_view = m_root_node_db->CreateView<md::Instrument>(ReuseViewKey::kInstrument);
  auto& login_map = m_root_node_db->GetNodeMap<future::LoginContent>();
  if (!login_map.empty())
    m_trading_day = login_map.begin()->second->Latest()->trading_day;
  m_login_view = m_root_node_db->CreateView<future::LoginContent>(ReuseViewKey::kLogin);
  if (m_trading_day.empty()) {
    m_login_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
      [&](std::shared_ptr<future::LoginNode> login_node, bool is_last) {
        if (m_trading_day.empty())
          m_trading_day = login_node->Snap()->trading_day;
        if (!m_trading_day.empty())
          m_login_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      });
  }
  m_order_view = m_root_node_db->CreateView<future::Order>(ReuseViewKey::kOrder);
  m_order_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::OrderNode> order_node, bool is_last) {
      if (!m_trading_day.empty())
        UpdateReportByOrder(order_node);
    });
  m_trade_view = m_root_node_db->CreateView<future::Trade>(ReuseViewKey::kTrade);
  m_trade_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::TradeNode> trade_node, bool is_last) {
      if (!m_trading_day.empty())
        UpdateReportByTrade(trade_node);
    });
  m_position_view = m_root_node_db->CreateView<future::Position>(ReuseViewKey::kPosition);
  m_position_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<future::PositionNode> position_node, bool is_last) {
      if (!m_trading_day.empty()) {
        auto ins_node = position_node->Snap()->ins_pointer;
        FCASSERT(ins_node);

        UpdateReportByPosition(position_node);
        // 记录用户期权持仓
        auto key_symbol = GetPositionKeySymbol(position_node);
        if (key_symbol.empty())
          return;
        auto report_key = m_trading_day + "|" + position_node->Snap()->user_key + "|" + position_node->Snap()->Symbol();
        m_option_position_map[key_symbol].insert(report_key);
      }
    });
  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins_node, bool is_last) {
      if (ins_node->Historical() && ins_node->Latest()->last_price == ins_node->Historical()->last_price)
        return;
      auto symbol = ins_node->Snap()->symbol;
      auto iter = m_option_position_map.find(symbol);
      if (iter == m_option_position_map.end())
        return;
      for (const auto& report_key : iter->second) {
        m_report_node_db->ReplaceRecord<DailyTradingReportItem>(
          report_key, [&](std::shared_ptr<DailyTradingReportItem> report_item) {
            UpdateReportOptionField(report_item);
          });
      }
    });
  m_report_node_db = std::make_shared<ReportNodeDb>(true, 0);
  m_report_view = m_report_node_db->CreateView<DailyTradingReportItem>();
  m_report_node_db->CommitTransaction();
  m_logger.Info("init");
}

std::shared_ptr<ReportNodeDb> DailyTradingReporterImpl::GetReportNodeDb() {
  return m_report_node_db;
}

int DailyTradingReporterImpl::RunOnce() {
  if (m_trading_day.empty())
    return 0;
  // 每隔一段时间更新一次挂单统计信息
  if (m_update_market_maker_indicator_timer.IsExpired()) {
    for (auto& [report_key, node] : m_report_view->GetNodes()) {
      m_report_node_db->ReplaceRecord<DailyTradingReportItem>(
        report_key, [&](std::shared_ptr<DailyTradingReportItem> report_item) {
          UpdateMarketMakerIndicator(report_item);
          if (report_item->m_ins_pointer
            && report_item->m_ins_pointer->Latest()->ProductClass() == md::ProductClass::kOption)
            UpdateReportOptionField(report_item);
        });
    }
    m_update_market_maker_indicator_timer.Reset(std::chrono::milliseconds(1000));
  }
  m_report_node_db->CommitTransaction();
  return 0;
}

void DailyTradingReporterImpl::CalcSpreadCoefficient(std::shared_ptr<DailyTradingReportItem> report_item) {
  if (!report_item->m_ins_pointer)
    return;
  auto ins = report_item->m_ins_pointer->Latest();
  const auto& r = GetMarketMakerRuleParam(ins->symbol);
  if (ins->ExchangeID() == "DCE") {
    double spread_gear = GetDCESpreadGear(r.valid_max_offer_spread, report_item);
    CalcDCECmulativeSpreadCoefficient(spread_gear, report_item);
    CalcDCEQuoteSpreadCoefficient(spread_gear, report_item);
  }
  if (ins->ExchangeID() == "SHFE" || ins->ExchangeID() == "INE") {
    CalcSHFECmulativeSpreadCoefficient(report_item);
    CalcSHFEQuoteSpreadCoefficient(report_item);
  }
}

std::shared_ptr<extension::DailyTradingReportItem> DailyTradingReporterImpl::GetReportItem(
  const std::string& user_key, const std::string& investor_id, std::shared_ptr<md::InstrumentNode> ins_node) {
  FCASSERT(ins_node);
  std::string report_key = m_trading_day + "|" + user_key + "|" + ins_node->Latest()->symbol;
  auto item = m_report_node_db->CreateRecord<extension::DailyTradingReportItem>(report_key);
  item->trading_day = m_trading_day;
  if (!item->m_ins_pointer) {
    item->symbol = ins_node->Latest()->symbol;
    item->user_key = user_key;
    item->investor_id = investor_id;
    item->m_ins_pointer = ins_node;
  }
  return item;
}

void DailyTradingReporterImpl::UpdateReportByOrder(std::shared_ptr<future::OrderNode> order_node) {
  bool update_filling_fee = false;
  auto order_now = order_node->Snap();
  FCASSERT(order_now->ins_pointer);
  // 无交易所单号不进行统计
  if (order_now->exchange_order_id.empty())
    return;
  auto report_item = GetReportItem(order_now->user_key, order_now->investor_id, order_now->ins_pointer);
  // 报单次数、委托量
  if (!order_node->Historical() || order_node->Historical()->exchange_order_id.empty()) {
    // 委托单上次不存在，这次有了，说明是一个新报单, +1，并更新申报费
    report_item->insert_order_count++;
    update_filling_fee = true;
    report_item->insert_order_volume += order_now->volume_orign;
    if (IsInNight(order_now->insert_date_time))
      report_item->insert_order_count_night++;
    else
      report_item->insert_order_count_day++;
  }
  // 撤单次数
  if (IsCanceled(order_node)) {
    // 委托单是被撤销的，撤单次数 +1，并更新申报费
    report_item->cancel_order_count++;
    update_filling_fee = true;
  }
  // 成交笔数
  if (order_now->status == future::OrderStatus::kDead
    && (!order_node->Historical() || order_node->Historical()->status != future::OrderStatus::kDead)) {
    if (order_now->volume_left == 0)
      report_item->all_trade_order_count++;
    if (order_now->volume_orign > order_now->volume_left)
      // 委托单状态为结束, 剩余数量小于报单数量, 说明部分成交或全部成交，有成交的报单次数 + 1，并更新申报费
      report_item->trade_order_count++;
    update_filling_fee = true;
  }
  // 申报费
  if (update_filling_fee) {
    auto ins = report_item->m_ins_pointer->Latest();

    // 如果是上期所和能源所, 期权申报费计算当前月份所有的
    if ((ins->ExchangeID() == "SHFE" || ins->ExchangeID() == "INE")
      && ins->ProductClass() == md::ProductClass::kOption) {
      auto amount = 0;
      auto trade_order_count = 0;
      double otr = 0;
      auto const& underlying_pointer = ins->instrument_base->underlying_pointer;
      FCASSERT(underlying_pointer);
      auto const& underlying_pointer_latest = underlying_pointer->Latest();
      FCASSERT(underlying_pointer_latest);
      auto const& all_derivate_map = underlying_pointer_latest->instrument_base->derivate_pointer;

      for (auto const& [key, derivate_node] : all_derivate_map) {
        auto item =
          key == ins->symbol ? report_item : GetReportItem(order_now->user_key, order_now->investor_id, derivate_node);
        amount += item->info_amount();
        trade_order_count += item->trade_order_count;
        otr = (trade_order_count == 0) ? NAN : (amount * 1.0 / trade_order_count - 1);
      }

      for (auto const& [key, derivate_node] : all_derivate_map) {
        auto item =
          key == ins->symbol ? report_item : GetReportItem(order_now->user_key, order_now->investor_id, derivate_node);
        FCASSERT(amount != 0);
        item->filling_fee = CalcFee(ins->ExchangeID(), ins->ProductID(), amount, otr) * item->info_amount() / amount;
        // 如果是当前的期权，不立刻刷新
        if (key != ins->symbol)
          m_report_node_db->ReplaceRecord<DailyTradingReportItem>(item);
      }

    } else if (ins->ExchangeID() == "DCE" && ins->ProductClass() == md::ProductClass::kOption) {
      // 大商所全部期权统一申报费
      report_item->filling_fee =
        CalcFee(ins->ExchangeID(), "_O", report_item->info_amount(), report_item->insert_trade_ratio());
    } else {
      report_item->filling_fee =
        CalcFee(ins->ExchangeID(), ins->ProductID(), report_item->info_amount(), report_item->insert_trade_ratio());
    }
  }
  // 把委托单放进报告项
  NodePointer<future::Order> order_pointer(order_node);
  // 如果是郑商所,非做市单不记录
  if (order_now->exchange_id != "CZCE" || order_now->is_quote) {
    if (order_now->direction == future::Direction::kBuy) {
      if (order_now->exchange_id == "DCE") {
        // 大连买单, 价格高的排前, 价格相同时手数小的排前
        ReplaceOrder(&m_bid_orders_pointer[report_item->GetKey()], order_pointer,
          [](NodePointer<future::Order>& a_pointer, NodePointer<future::Order>& b_pointer) {
            if (a_pointer->Latest()->limit_price == b_pointer->Latest()->limit_price)
              return a_pointer->Latest()->volume_left < b_pointer->Latest()->volume_left;
            return a_pointer->Latest()->limit_price > b_pointer->Latest()->limit_price;
          });
      } else {
        // 其它交易所买单, 价格高的排前, 价格相同时手数大的排前
        ReplaceOrder(&m_bid_orders_pointer[report_item->GetKey()], order_pointer,
          [](NodePointer<future::Order>& a_pointer, NodePointer<future::Order>& b_pointer) {
            if (a_pointer->Latest()->limit_price == b_pointer->Latest()->limit_price)
              return a_pointer->Latest()->volume_left > b_pointer->Latest()->volume_left;
            return a_pointer->Latest()->limit_price > b_pointer->Latest()->limit_price;
          });
      }
    } else {
      if (order_now->exchange_id == "DCE") {
        // 大连卖单, 价格低的排前, 价格相同时手数小的排前
        ReplaceOrder(&m_ask_orders_pointer[report_item->GetKey()], order_pointer,
          [](NodePointer<future::Order>& a_pointer, NodePointer<future::Order>& b_pointer) {
            if (a_pointer->Latest()->limit_price == b_pointer->Latest()->limit_price)
              return a_pointer->Latest()->volume_left < b_pointer->Latest()->volume_left;
            return a_pointer->Latest()->limit_price < b_pointer->Latest()->limit_price;
          });
      } else {
        // 其它交易所卖单, 价格低的排前, 价格相同时手数大的排前
        ReplaceOrder(&m_ask_orders_pointer[report_item->GetKey()], order_pointer,
          [](NodePointer<future::Order>& a_pointer, NodePointer<future::Order>& b_pointer) {
            if (a_pointer->Latest()->limit_price == b_pointer->Latest()->limit_price)
              return a_pointer->Latest()->volume_left > b_pointer->Latest()->volume_left;
            return a_pointer->Latest()->limit_price < b_pointer->Latest()->limit_price;
          });
      }
    }
  }
  UpdateMarketMakerIndicator(report_item);
  m_report_node_db->ReplaceRecord<DailyTradingReportItem>(report_item);
}

void DailyTradingReporterImpl::UpdateMarketMakerIndicator(std::shared_ptr<DailyTradingReportItem> report_item) {
  // 计算挂单相关指标
  if (!report_item->m_ins_pointer)
    return;
  auto ins = report_item->m_ins_pointer->Latest();
  const auto& r = GetMarketMakerRuleParam(ins->symbol);
  int bid_offer_volume = 0;
  int ask_offer_volume = 0;
  double offer_spread = 0.0;
  double last_bid = NAN;
  double last_ask = NAN;
  auto& bid_order_pointer = m_bid_orders_pointer[report_item->GetKey()];
  auto& ask_order_pointer = m_ask_orders_pointer[report_item->GetKey()];
  std::vector<std::pair<double, int>> ask_limit_vol;
  std::vector<std::pair<double, int>> bid_limit_vol;
  if (!bid_order_pointer.empty() && !ask_order_pointer.empty()) {
    report_item->symbol_count = 1;
    auto bit = bid_order_pointer.begin();
    auto ait = ask_order_pointer.begin();
    // 第一档价差应为整数
    offer_spread =
      static_cast<int>(((*ait)->Latest()->limit_price - (*bit)->Latest()->limit_price) / ins->PriceTick() + 0.5);
    if (ins->ExchangeID() == "DCE") {
      int volume1 = std::min((*ait)->Latest()->volume_left, (*bit)->Latest()->volume_left);
      // 计算两档价差
      if (volume1 > 0 && volume1 < r.valid_min_offer_volume && ++ait != ask_order_pointer.end()
        && ++bit != bid_order_pointer.end()) {
        // 第二档价差应为整数
        int offer_spread2 =
          static_cast<int>(((*ait)->Latest()->limit_price - (*bit)->Latest()->limit_price) / ins->PriceTick() + 0.5);
        if (offer_spread2 <= r.valid_max_offer_spread && offer_spread2 > 0) {
          int volume2 = std::min((*ait)->Latest()->volume_left, (*bit)->Latest()->volume_left);
          int sum = ((volume1 + volume2) > r.valid_min_offer_volume) ? r.valid_min_offer_volume : (volume1 + volume2);
          volume2 = sum - volume1;
          // 两档平均价差应为 double
          offer_spread =
            (static_cast<double>(volume1) / sum) * offer_spread + (static_cast<double>(volume2) / sum) * offer_spread2;
        }
      }
      bit = bid_order_pointer.begin();
      ait = ask_order_pointer.begin();
    }
    // 上期所统计满足价差内的所有档手数
    // 大商所统计满足价差内的两档手数
    // 其他交易所统计满足价差内的一档手数
    int cnt = 0;

    while (true) {
      ++cnt;
      if (ait == ask_order_pointer.end() && bit == bid_order_pointer.end())
        break;
      if (ait != ask_order_pointer.end())
        last_ask = (*ait)->Latest()->limit_price;
      if (bit != bid_order_pointer.end())
        last_bid = (*bit)->Latest()->limit_price;
      if (ait != ask_order_pointer.end()) {
        if (static_cast<int>((last_ask - last_bid) / ins->PriceTick() + 0.5) > r.valid_max_offer_spread)
          break;
        ask_offer_volume += (*ait)->Latest()->volume_left;
        ask_limit_vol.emplace_back(
          std::pair<double, int>((*ait)->Latest()->limit_price, (*ait)->Latest()->volume_left));
        ++ait;
      }
      if (bit != bid_order_pointer.end()) {
        if (static_cast<int>((last_ask - last_bid) / ins->PriceTick() + 0.5) > r.valid_max_offer_spread)
          break;
        bid_offer_volume += (*bit)->Latest()->volume_left;
        bid_limit_vol.emplace_back(
          std::pair<double, int>((*bit)->Latest()->limit_price, (*bit)->Latest()->volume_left));
        ++bit;
      }
      if (ins->ExchangeID() != "SHFE" && ins->ExchangeID() != "CFFEX" && ins->ExchangeID() != "INE"
        && ins->ExchangeID() != "DCE")
        break;
      if (ins->ExchangeID() == "DCE" && cnt >= 2)
        break;
    }
  } else {
    report_item->symbol_count = 0;
  }
  int offer_volume = std::min(bid_offer_volume, ask_offer_volume);
  // 上期所和能源交易所计算价差
  if (ins->ExchangeID() == "SHFE" || ins->ExchangeID() == "INE") {
    offer_spread =
      CalcDeltaSpread(ask_limit_vol, bid_limit_vol, r.valid_min_offer_volume, ins->PriceTick(), offer_volume);
  }
  // 如果报告上次已经处于有效挂单状态，则可以认为上次更新到本次时间之间都是有效挂单状态
  auto market_trading_time_table = InstrumentTradingTime::Instance().GetTradingTimeTable(ins);
  report_item->total_length = InstrumentTradingTime::Instance().GetTotalTradingTimeLength(ins);
  auto now_epoch = NowAsEpochNano();
  if (report_item->update_time != 0) {
    int64_t delta_time = (now_epoch - report_item->update_time);
    auto now = EpochNanoToLocalDateTime(now_epoch, 8);
    auto current_quote_time = now.date_time.tm_hour * 10000 + now.date_time.tm_min * 100 + now.date_time.tm_sec;
    auto it = market_trading_time_table.upper_bound(current_quote_time);
    if (it != market_trading_time_table.end() && it->second == false) {
      if (report_item->offer_volume >= r.valid_min_offer_volume) {
        report_item->valid_quote_length += delta_time;
        report_item->sum_quote_spread += report_item->offer_spread * delta_time;
        UpdateSHFEQuoteLength(report_item, r.valid_max_offer_spread, delta_time, report_item->offer_spread);
      }
    }
  }
  report_item->offer_volume = offer_volume;
  report_item->offer_spread = offer_spread;
  report_item->update_time = now_epoch;
  CalcSpreadCoefficient(report_item);
}

const extension::MarketMakerRuleParam& DailyTradingReporterImpl::GetMarketMakerRuleParam(const std::string& symbol) {
  static MarketMakerRuleParam default_rule = {"-", 1, 0};
  auto it = m_rule_map.find(symbol);
  if (it == m_rule_map.end())
    return default_rule;
  return it->second;
}

void DailyTradingReporterImpl::UpdateReportByPosition(std::shared_ptr<future::PositionNode> pos_node) {
  auto position = pos_node->Latest();
  auto report_item = GetReportItem(position->user_key, position->investor_id, position->ins_pointer);
  auto ins_node = position->ins_pointer;
  report_item->float_profit = position->FloatProfit();
  report_item->position_profit = position->PositionProfit();
  report_item->close_profit = position->CloseProfit();
  report_item->margin = position->Margin();
  report_item->volume_long = position->VolumeLong();
  report_item->volume_short = position->VolumeShort();
  report_item->untrade_profit = position->UnTradeProfit();
  report_item->trade_profit = position->TradeProfit();
  report_item->commission = position->Commission();
  report_item->volume_yesterday_net = position->VolumeYesterdayNet();
  report_item->premium = position->Premium();
  report_item->position_value_long = position->LongMarketValue();
  report_item->position_value_short = position->ShortMarketValue();
  report_item->market_trade_volume = ins_node->Latest()->volume * 2;
  report_item->total_other_position = position->TotalOtherPosition();
  report_item->other_long_postion = position->subpos_long_other.Volume();
  report_item->other_short_postion = position->subpos_short_other.Volume();

  if (ins_node->Latest()->ProductClass() == md::ProductClass::kFuture) {
    report_item->delta = report_item->volume_long - report_item->volume_short;
    report_item->delta_amount =
      report_item->delta * ins_node->Latest()->VolumeMultiple() * ins_node->Latest()->last_price;
  }

  if (ins_node->Latest()->ProductClass() == md::ProductClass::kOption)
    UpdateReportOptionField(report_item);
  m_report_node_db->ReplaceRecord<DailyTradingReportItem>(report_item);
}

void DailyTradingReporterImpl::UpdateReportByTrade(std::shared_ptr<future::TradeNode> trade_node) {
  auto trade_now = trade_node->Snap();
  FCASSERT(trade_now->ins_pointer);
  if (trade_node->Historical())
    return;
  auto report_item = GetReportItem(trade_now->user_key, trade_now->investor_id, trade_now->ins_pointer);
  // 统计每个品种当天已经发生的自成交次数
  // 除郑商所之外的交易所，自成交的两笔交易，exchange_trade_id 相同，方向相反
  // 郑商所有所不同，自成交的两笔交易，卖单 exchange_trade_id 比买单 exchange_trade_id 加一
  // 且郑商所 exchange_trade_id 中没有空格，但转换为数字时数值较大，这里用 std::atoll 处理
  if (trade_now->hedge_flag == fclib::future::OrderHedgeFlag::kSpeculation && trade_now->order_pointer) {
    std::string trade_id = trade_now->exchange_trade_id;
    if (trade_now->exchange_id == "CZCE") {
      if (trade_now->direction == future::Direction::kSell)
        trade_id = std::to_string(std::atoll(trade_now->exchange_trade_id.c_str()) - 1);
      else
        trade_id = std::to_string(std::atoll(trade_now->exchange_trade_id.c_str()) + 1);
    }
    std::string trade_key = fclib::future::TradeBase::MakeKey(trade_now->user_key, trade_id, "");
    auto iter = m_trade_view->GetNodes().lower_bound(trade_key);
    for (; iter != m_trade_view->GetNodes().end(); ++iter) {
      if (iter->second->Snap()->exchange_trade_id != trade_id)
        break;
      if (iter->second->Snap()->hedge_flag == fclib::future::OrderHedgeFlag::kSpeculation
        && iter->second->Snap()->direction != trade_now->direction) {
        if (trade_now->direction == fclib::future::Direction::kBuy)
          report_item->self_trade_set.insert(trade_now->instrument_id + "." + trade_now->exchange_trade_id);
        else
          report_item->self_trade_set.insert(
            iter->second->Snap()->instrument_id + "." + iter->second->Snap()->exchange_trade_id);
        report_item->self_trade_times = static_cast<int>(report_item->self_trade_set.size());
      }
    }
  }
  report_item->trade_volume += trade_now->volume;  // 日成交量
  if (trade_now->direction == future::Direction::kBuy) {
    report_item->buy_trade_volume += trade_now->volume;  // 买成交量
    if (trade_now->offset == future::Offset::kOpen) {
      // 多头开仓
      report_item->long_open_commission += trade_now->commission;
      report_item->long_open_average_price =
        (report_item->long_open_average_price * report_item->long_open_volume + trade_now->volume * trade_now->price)
        / (report_item->long_open_volume + trade_now->volume);
      report_item->long_open_volume += trade_now->volume;
    } else {
      // 空头平仓
      report_item->short_close_commission += trade_now->commission;
      report_item->short_close_average_price = (report_item->short_close_average_price * report_item->short_close_volume
                                                 + trade_now->volume * trade_now->price)
        / (report_item->short_close_volume + trade_now->volume);
      report_item->short_close_volume += trade_now->volume;
    }
  } else {
    if (trade_now->offset == future::Offset::kOpen) {
      // 空头开仓
      report_item->short_open_commission += trade_now->commission;
      report_item->short_open_average_price =
        (report_item->short_open_average_price * report_item->short_open_volume + trade_now->volume * trade_now->price)
        / (report_item->short_open_volume + trade_now->volume);
      report_item->short_open_volume += trade_now->volume;
    } else {
      // 多头平仓
      report_item->long_close_commission += trade_now->commission;
      report_item->long_close_average_price =
        (report_item->long_close_average_price * report_item->long_close_volume + trade_now->volume * trade_now->price)
        / (report_item->long_close_volume + trade_now->volume);
      report_item->long_close_volume += trade_now->volume;
    }
    report_item->sell_trade_volume += trade_now->volume;  // 卖成交量
  }

  m_report_node_db->ReplaceRecord<DailyTradingReportItem>(report_item);
}

void DailyTradingReporterImpl::UpdateReportOptionField(std::shared_ptr<DailyTradingReportItem> report_item) {
  auto ins_node = report_item->m_ins_pointer;
  if (!ins_node)
    return;
  auto underlying_node = report_item->m_ins_pointer->Latest()->instrument_base->underlying_pointer;
  if (!underlying_node)
    return;
  if (m_volatility_curve_subscribes.count(ins_node) == 0) {
    m_volatility_curve_subscribes.insert(ins_node);
    m_option_calc->SubscribeFittedVolatility(ins_node);
  }
  report_item->ins_gamma = m_option_calc->Gamma(ins_node);
  report_item->ins_vega = m_option_calc->Vega(ins_node);
  report_item->ins_delta = m_option_calc->Delta(ins_node);
  report_item->ins_theta = m_option_calc->Theta(ins_node);
  report_item->ins_rho = m_option_calc->Rho(ins_node);
  auto inner_value = m_option_calc->IntrinsicValue(ins_node);
  auto net_volume = report_item->volume_long - report_item->volume_short;  // 净持仓
  // item->premium = pos_node->Next()->open_price_long * pos_node->Next()->VolumeLong() * ins->volume_multiple;
  // //权利金
  report_item->time_value =
    net_volume * ins_node->Latest()->VolumeMultiple() * (ins_node->Latest()->last_price - inner_value);
  report_item->delta = report_item->ins_delta * net_volume;
  report_item->delta_amount =
    report_item->ins_delta * net_volume * ins_node->Latest()->VolumeMultiple() * underlying_node->Latest()->last_price;
  report_item->gamma = report_item->ins_gamma * net_volume;
  report_item->gamma_amount = report_item->ins_gamma * net_volume * ins_node->Latest()->VolumeMultiple()
    * underlying_node->Latest()->last_price * underlying_node->Latest()->last_price * 0.01;
  report_item->theta = report_item->ins_theta * net_volume;
  report_item->theta_amount = report_item->ins_theta * net_volume * ins_node->Latest()->VolumeMultiple();
  report_item->vega = report_item->ins_vega * net_volume;
  report_item->vega_amount = report_item->ins_vega * net_volume * ins_node->Latest()->VolumeMultiple();
  report_item->rho = report_item->ins_rho * net_volume;
  report_item->rho_amount = report_item->ins_rho * net_volume * ins_node->Latest()->VolumeMultiple();
}

void DailyTradingReporterImpl::SetRules(const std::vector<MarketMakerRuleParam>& rules) {
  m_rule_map.clear();
  for (const auto& item : rules) {
    m_rule_map[item.symbol] = item;
  }
}

void DailyTradingReporterImpl::CleanUp() {
  for (const auto& ins_node : m_volatility_curve_subscribes) {
    m_option_calc->UnsubscribeFittedVolatility(ins_node);
  }
  m_volatility_curve_subscribes.clear();
}

void DailyTradingReporterImpl::LoadReport(
  const std::filesystem::path& report_file_name, const std::string& trading_day) {
  if (trading_day.empty())
    return;
  SerializerReport nss;
  if (nss.FromFile(report_file_name))
    nss.ToVar(*m_report_node_db);
  std::map<std::string_view, std::shared_ptr<ContentNode<DailyTradingReportItem>>> map =
    m_report_node_db->GetNodeMap<DailyTradingReportItem>();
  for (const auto& [key, node] : map) {
    if (node->Latest()->trading_day != trading_day)
      m_report_node_db->DeleteRecord<DailyTradingReportItem>(key);
  }
}

void DailyTradingReporterImpl::SaveReport(const std::filesystem::path& report_file_name) {
  SerializerReport nss;
  nss.FromVar(*m_report_node_db);
  nss.ToFile(report_file_name);
}

double DailyTradingReporterImpl::CalcDeltaSpread(const std::vector<std::pair<double, int>>& ask_vec,
  const std::vector<std::pair<double, int>>& bid_vec, int min_offer_vol, double tick, int offer_vol) {
  double sum = 0.0;
  if (min_offer_vol > offer_vol) {
    return sum;
  }
  int vol = min_offer_vol;

  for (const auto& [price, volume] : ask_vec) {
    if (vol < volume) {
      sum += price * vol;
      break;
    }
    sum += price * volume;
    vol -= volume;
  }

  vol = min_offer_vol;
  for (const auto& [price, volume] : bid_vec) {
    if (vol < volume) {
      sum -= price * vol;
      break;
    }
    sum -= price * volume;
    vol -= volume;
  }

  return sum / (min_offer_vol * tick);
}

