namespace rapid_serialize {
void DefineStruct(
  fclib::extension::TradeAgentSerializer* ss, fclib::extension::MarketEvalInstruction::MarketEvalPack& item) {
  ss->AddItem(item.market_eval_packs, "market_eval_packs");
  ss->AddItem(item.child, "child");
}

