MarketEvalInstruction::MarketEvalInstruction(TradeAgent* parent, const std::vector<MarketEvalParams>& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*)> child_factory)
  : m_logger((parent && parent->GetLogger()) ? parent->GetLogger()->With("market_eval", GetAgentIndex()).Clone()
                                             : structlog::Logger::Root().With("market_eval", GetAgentIndex()).Clone()) {
  m_parent = parent;

  if (child_factory)
    m_child = child_factory(this);
  for (const auto& param : params) {
    auto market_avg_price_eval =
      std::make_shared<MarketAvgPriceEval>(TradeAgent::GetTqApi(), param.ins_node, param.direction);
    market_avg_price_eval->RegisterNotify([this]() {
      if (m_callback)
        m_callback(shared_from_this());
    });
    m_evals.emplace_back(market_avg_price_eval);
  }
}

MarketEvalInstruction::MarketEvalInstruction(TradeAgent* parent, const MarketEvalPack& pack)
  : m_logger((parent && parent->GetLogger()) ? parent->GetLogger()->With("market_eval", GetAgentIndex()).Clone()
                                             : structlog::Logger::Root().With("market_eval", GetAgentIndex()).Clone()) {
  m_parent = parent;

  for (const auto& p : pack.market_eval_packs) {
    auto market_avg_price_eval = MarketAvgPriceEval::Load(TradeAgent::GetTqApi(), p);
    if (market_avg_price_eval) {
      market_avg_price_eval->RegisterNotify([this]() {
        if (m_callback)
          m_callback(shared_from_this());
      });
    }
    m_evals.emplace_back(market_avg_price_eval);
  }
}

void MarketEvalInstruction::OnChildNotify(TradeAgent* child) {
  if (!child)
    return;
  bool p = (child->GetStatus() == AgentStatus::kPaused || child->GetStatus() == AgentStatus::kStopped);
  for (const auto& eval : m_evals) {
    if (eval) {
      p ? eval->Pause() : eval->Start();
    }
  }
  if (m_parent)
    m_parent->OnChildNotify(this);
}

