std::string MarketEvalInstruction::SaveInstruction() {
  Pause();
  MarketEvalPack pack;
  for (const auto& eval : m_evals) {
    if (eval)
      pack.market_eval_packs.emplace_back(eval->Save());
  }
  pack.child = m_child ? m_child->SaveInstruction() : "";
  return SerializeToString(pack);
}

std::shared_ptr<MarketEvalInstruction> MarketEvalInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&)> load_factory) {
  auto pack = SerializeToVar<MarketEvalPack>(params);
  auto instruction = std::make_shared<MarketEvalInstruction>(parent, pack);
  if (instruction->m_evals.empty()) {
    return nullptr;
  }
  for (auto const& ptr : instruction->m_evals) {
    if (!ptr) {
      return nullptr;
    }
  }
  auto child = load_factory(instruction.get(), pack.child);
  if (!child)
    return nullptr;
  instruction->m_child = child;
  return instruction;
}

