static int s_order_request_id_begin = 0;

InsertOrderInstruction::InsertOrderInstruction(TradeAgent* parent, const InsertOrderParams& params,
  const std::vector<int>& volume_plan,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&, int, int)> child_factory)
  : m_params(params)
  , m_volume_plan(volume_plan)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("insert_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("insert_order", GetAgentIndex()).Clone()) {
  m_parent = parent;

  if (params.volume <= 0) {
    ChangeStatus(false, AgentStatus::kStopped, "fclib: 报单手数无效");
    return;
  }

  if (params.user_key_list.size() != volume_plan.size()) {
    ChangeStatus(false, AgentStatus::kStopped, "fclib: 多账户报单手数与账户组数量不符");
    return;
  }

  m_logger.With("params", SerializeToString(params))
    .With("volume_plan", SerializeToString(volume_plan))
    .Info("Constructor");

  auto request_id = GetOrderRequestID();
  if (!child_factory)
    return;
  // 如果是随机下单
  if (m_params.multi_type == InsertMultiType::kRandom)
    RandomUserList();

  for (int index = 0; index < static_cast<int>(m_volume_plan.size()); ++index) {
    const auto& volume = m_volume_plan.at(index);
    m_childs.push_back(
      volume > 0 ? child_factory(this, m_params.user_key_list.at(index), volume, request_id) : nullptr);
    m_considers.push_back(false);
  }

  // 刷新状态
  RefreshStatus(false);
}

InsertOrderInstruction::InsertOrderInstruction(TradeAgent* parent, const InsertOrderInstructionPack& pack)
  : m_params(pack.params)
  , m_volume_plan(pack.volume_plan)
  , m_index(pack.index)
  , m_status(pack.status)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("insert_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("insert_order", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_instruction_memo = pack.memo;

  m_logger.With("params", SerializeToString(pack)).Info("LoadConstructor");
}

InsertOrderInstruction::~InsertOrderInstruction() {}

void InsertOrderInstruction::SetOrderRequestIDBegin(int request_id_begin) {
  s_order_request_id_begin = request_id_begin;
}

AgentStatus InsertOrderInstruction::GetStatus() const {
  return m_status;
}

std::string InsertOrderInstruction::GetMsg() const {
  return m_msg;
}

structlog::Logger* InsertOrderInstruction::GetLogger() {
  return &m_logger;
}

void InsertOrderInstruction::SetCallBack(std::function<void(std::shared_ptr<UserTradeInstruction>)> fun) {
  m_call_back = fun;
}

int InsertOrderInstruction::GetOrderRequestID() {
  if (s_order_request_id_begin > 0)
    return s_order_request_id_begin++;
  return 0;
}

void InsertOrderInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");

  if (m_status != AgentStatus::kPaused)
    return;
  // 同时下单
  if (m_params.multi_type == InsertMultiType::kAll) {
    for (const auto& child : m_childs) {
      if (child)
        child->Start();
    }
    return;
  }

  // https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/1653866627
  for (size_t index = 0; index < m_childs.size(); ++index) {
    if (m_childs[index] && m_childs[index]->GetStatus() != AgentStatus::kStopped) {
      m_considers[index] = true;
    }
  }

  if (m_index >= static_cast<int>(m_childs.size())) {
    m_index = 0;
  }

  m_running_child = GetRunningChild();
  if (m_running_child) {
    m_considers[m_index] = false;
    m_running_child->Start();
  }
}

void InsertOrderInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");

  Run();
}

void InsertOrderInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  m_considers.assign(m_considers.size(), false);
  for (const auto& child : m_childs) {
    if (child)
      child->Pause();
  }
}

void InsertOrderInstruction::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");

  for (const auto& child : m_childs) {
    if (child)
      child->Stop();
  }
}

bool InsertOrderInstruction::VisibleInViewInstruction() const {
  return true;
}

const InsertOrderParams& InsertOrderInstruction::GetOrderParams() const {
  return m_params;
}

void InsertOrderInstruction::ChangeOrderPrice(const ChangePriceParams& params, int request_id) {
  m_logger.With("price", params.price)
    .With("type", static_cast<int>(params.type))
    .With("request_id", request_id)
    .Info("ChangeOrderPrice");

  if (m_status == AgentStatus::kStopped)
    return;
  auto r_id = GetOrderRequestID();
  for (const auto& child : m_childs) {
    if (child)
      child->ChangeOrderPrice(params, r_id);
  }
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
}

void InsertOrderInstruction::OnChildNotify(TradeAgent* child) {
  m_logger.With("child", reinterpret_cast<int64_t>(this)).Info("OnChildNotify");

  RefreshStatus(true);
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
  if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused)
    return;
  if (m_params.multi_type == InsertMultiType::kAll || m_running_child)
    return;
  m_running_child = GetRunningChild();
  if (m_running_child) {
    m_considers[m_index] = false;
    m_running_child->Start();
  }
}

int InsertOrderInstruction::VolumeTotal() {
  int vol = 0;
  for (const auto& child : m_childs) {
    if (child)
      vol += child->VolumeTotal();
  }
  return vol;
}

int InsertOrderInstruction::VolumeLeft() {
  int vol = 0;
  for (const auto& child : m_childs) {
    if (child)
      vol += child->VolumeLeft();
  }
  return vol;
}

double InsertOrderInstruction::TradeAmount() {
  double ret = 0.0;
  for (const auto& child : m_childs) {
    if (child)
      ret += child->TradeAmount();
  }
  return ret;
}

void InsertOrderInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");
  m_status = status;
  m_msg = msg;
  if (notify && m_parent)
    m_parent->OnChildNotify(this);
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

std::vector<std::shared_ptr<TradeInstruction>> InsertOrderInstruction::GetChildInstructions() {
  return m_childs;
}

std::string InsertOrderInstruction::SaveInstruction() {
  // 暂停
  Pause();
  InsertOrderInstructionPack pack;
  pack.params = m_params;
  pack.symbol = m_params.ins_node->Latest()->symbol;
  pack.status = m_status;
  pack.msg = m_msg;
  pack.index = m_index;
  pack.volume_plan = m_volume_plan;
  pack.memo = m_instruction_memo;
  for (const auto& child : m_childs) {
    pack.childs.push_back(child ? child->SaveInstruction() : "nullptr");
  }
  return SerializeToString(pack);
}

std::shared_ptr<InsertOrderInstruction> InsertOrderInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&, const std::string&, int)>
    load_factory) {
  auto pack = SerializeToVar<InsertOrderInstructionPack>(params);
  auto ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(pack.symbol);
  if (nullptr == ins_node)
    return nullptr;
  pack.params.ins_node = ins_node;
  auto instruction = std::make_shared<InsertOrderInstruction>(parent, pack);
  auto request_id = GetOrderRequestID();
  for (int index = 0; index < static_cast<int>(pack.childs.size()); ++index) {
    const auto& child_str = pack.childs.at(index);
    if (child_str == "nullptr" || !load_factory) {
      instruction->m_childs.push_back(nullptr);
    } else {
      auto child = load_factory(instruction.get(), child_str, pack.params.user_key_list.at(index), request_id);
      instruction->m_childs.push_back(child);
    }
    instruction->m_considers.push_back(false);
  }
  instruction->RefreshStatus(false);
  return instruction;
}

void InsertOrderInstruction::RefreshStatus(bool notify) {
  // 状态取决于所有账户的子指令
  ChangeStatus(notify, CalcStatusByChilds(), CalcMsgByChilds());
  if (m_params.multi_type == InsertMultiType::kAll || !m_running_child || m_status == AgentStatus::kStopped)
    return;
  // 判断是否切换至下一账户:
  // * 当前账户指令已停止
  // * 当前账户指令发生错误
  auto running_status = m_running_child->GetStatus();
  if (!m_running_child->GetMsg().empty() || running_status == AgentStatus::kStopped) {
    m_running_child.reset();
    ++m_index;
  }
}

AgentStatus InsertOrderInstruction::CalcStatusByChilds() {
  // https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/1653866627
  bool running = false;
  bool paused = false;
  for (size_t index = 0; index < m_childs.size(); ++index) {
    const auto& child = m_childs[index];
    if (!child)
      continue;
    const auto status = child->GetStatus();
    m_logger.With("child", reinterpret_cast<int64_t>(child.get()))
      .With("status", static_cast<int>(status))
      .Debug("CalcStatusByChilds");

    if (status == AgentStatus::kStarted || status == AgentStatus::kPausing
      || (status == AgentStatus::kPaused && m_considers[index])) {
      running = true;
      break;
    }
    if (status == AgentStatus::kPaused)
      paused = true;
  }
  if (running)
    return AgentStatus::kStarted;
  if (paused)
    return AgentStatus::kPaused;
  return AgentStatus::kStopped;
}

std::string InsertOrderInstruction::CalcMsgByChilds() {
  FCASSERT(m_childs.size() <= m_params.user_key_list.size());

  std::string ret;
  for (size_t index = 0; index < m_childs.size(); ++index) {
    const auto& child = m_childs[index];
    if (!child)
      continue;
    auto msg = child->GetMsg();
    // considers == true, 不考虑报错.
    if (msg.empty() || m_considers[index])
      continue;
    m_logger.With("child", reinterpret_cast<int64_t>(child.get()))
      .With("msg", child->GetMsg())
      .Debug("CalcMsgByChilds");
    if (!ret.empty())
      ret += "; ";
    ret += m_params.user_key_list[index] + ": " + msg;
  }
  return ret;
}

std::shared_ptr<TradeInstruction> InsertOrderInstruction::GetRunningChild() {
  FCASSERT(m_childs.size() == m_volume_plan.size());
  while (m_index < static_cast<int>(m_childs.size())) {
    if (m_childs[m_index] && m_childs[m_index]->GetStatus() != AgentStatus::kStopped)
      return m_childs[m_index];
    ++m_index;
  }
  return nullptr;
}

void InsertOrderInstruction::RandomUserList() {
  // 只有随机下单才可以调用
  if (m_params.multi_type != InsertMultiType::kRandom)
    return;

  // 创建索引数组
  std::vector<size_t> indices(m_params.user_key_list.size());
  std::iota(indices.begin(), indices.end(), 0);

  // 打乱索引
  auto time = NowAsEpochNano();
  std::mt19937 g(static_cast<unsigned int>(time));
  std::shuffle(indices.begin(), indices.end(), g);

  // 根据打乱后的索引重新排列user_key_list和volume_plan
  std::vector<std::string> new_user_key_list;
  std::vector<int> new_volume_plan;

  for (size_t idx : indices) {
    new_user_key_list.push_back(m_params.user_key_list[idx]);
    new_volume_plan.push_back(m_volume_plan[idx]);
  }

  // 更新原数组
  m_params.user_key_list = std::move(new_user_key_list);
  m_volume_plan = std::move(new_volume_plan);
}

std::vector<std::string> InsertOrderInstruction::GetUserList() {
  return m_params.user_key_list;
}

std::set<std::shared_ptr<future::OrderNode>> InsertOrderInstruction::GetOrderNodes() {
  std::set<std::shared_ptr<future::OrderNode>> ret;
  for (const auto& child : m_childs) {
    if (child) {
      auto nodes = child->GetOrderNodes();
      ret.merge(nodes);
    }
  }
  return ret;
}

