static md::EpochNano TimeLimit = 3 * 1000000000LL;
static std::random_device rd;
static std::mt19937 rng(rd());

bool CheckTradingTime(std::shared_ptr<md::InstrumentNode> ins_node, md::EpochNano nano_time);

// 获取n列中包含x个1的随机列表
std::vector<int> GetShuffleList(int x, int n) {
  FCASSERT(x <= n);
  std::vector<int> res;
  for (int i = 0; i < n; i++) {
    if (i < x)
      res.push_back(1);
    else
      res.push_back(0);
  }
  std::shuffle(res.begin(), res.end(), rng);
  return res;
}

/**
 * 获取生成随机列表长度, 长度应该满足：min_val * length <= sum_val <= max_val * length
  @param sum_val: 列表元素之和
  @param min_val: 列表元素最小值
  @param max_val: 列表元素最大值
  @return 长度
 */
int GetRandomListLength(int sum_val, int min_val, int max_val) {
  int length = sum_val * 2 / (min_val + max_val);
  if (sum_val > max_val * length)
    length++;
  return length;
}

/**
 * 生成随机列表, 参数应该满足：min_val * length <= sum_val <= max_val * length
  @param sum_val: 列表元素之和
  @param min_val: 列表元素最小值
  @param max_val: 列表元素最大值
  @param length:  列表长度，如果没有指定，则返回的列表长度没有指定
  @return 整型列表，满足 sum(list) = sum_val, len(list) == length, min_val < any_item(list) < max_val
 */
std::vector<int> GetRandomList(int sum_val, int min_val, int max_val, int length = 0) {
  std::vector<int> res;
  if (sum_val <= 0)
    return res;
  if (length <= 0) {
    length = sum_val * 2 / (min_val + max_val);
    FCASSERT(sum_val >= min_val * length);
    FCASSERT(sum_val <= max_val * length + min_val);
  } else {
    FCASSERT(sum_val >= min_val * length);
    FCASSERT(sum_val <= max_val * length);
  }
  for (int i = 0; i < length; i++)
    res.push_back(min_val);
  if (sum_val == min_val * length)
    return res;
  int rest_value = sum_val - min_val * length;       // 剩余可填充个数
  int rest_position = (max_val - min_val) * length;  // 剩余可填充位置
  if (sum_val > max_val * length) {
    // 如果 sum_val 超过 length 理论上限, 需再补一列, 可填充位置增加 min_val.
    res.push_back(0);
    rest_position += min_val;
  }
  auto rest_list = GetShuffleList(rest_value, rest_position);
  for (int i = 0; i < static_cast<int>(res.size()); i++) {
    auto start = (max_val - min_val) * i;
    auto end = (i < length) ? (max_val - min_val) * (i + 1) : rest_position;
    std::for_each(rest_list.begin() + start, rest_list.begin() + end, [&](int n) {
      res[i] += n;
    });
  }
  FCASSERT(static_cast<int>(res.size()) == length || static_cast<int>(res.size()) == length + 1);
  FCASSERT(std::accumulate(res.begin(), res.end(), 0) == sum_val);
  return res;
}

/**
 * 判断是否为冰山算法
  @param split_params: 大单拆分参数
 */
bool IsIceAlgo(const OrderSplitParams& split_params) {
  return split_params.split_algo == OrderSplitAlgo::kIce;
}

/**
 * 判断是否为TWAP算法
  @param split_params: 大单拆分参数
 */
bool IsTwapAlgo(const OrderSplitParams& split_params) {
  return split_params.split_algo == OrderSplitAlgo::kTwap && split_params.execute_time > 0;
}

/**
 * 判断是否为交易所拆分算法
  @param split_params: 大单拆分参数
 */
bool IsExchange(const OrderSplitParams& split_params) {
  return split_params.split_algo == OrderSplitAlgo::kExchange;
}

/**
 * 判断大单拆分算法参数是否合理
  @param split_params: 大单拆分参数
  @return 目前仅支持冰山算法和TWAP算法, 其他算法默认不支持返回错误
 */
bool IsSplitParamsValid(const OrderSplitParams& split_params) {
  return IsIceAlgo(split_params) || IsTwapAlgo(split_params) || IsExchange(split_params);
}

/**
 * 判断大单拆分算法是否需要追单
  @param order_price: 下单价格类型
  @return 仅下单价格类型是挂价的情况下才有可能需要进行追单
 */
bool IsNeedTrackOrder(const InsertOrderPriceType& order_price) {
  return order_price == InsertOrderPriceType::kHangPrice;
}

/**
 * 判断大单拆分算法是否需要撤单改价
  @param direction: 挂单方向
  @param track_price: 目前行情价格
  @param limit_price: 目前挂单价格
  @return 买入方向: 行情价格 > 挂单价格, true; 卖出方向: 行情价格 < 挂单价格, true
 */
bool IsNeedCancelOrder(const future::Direction& direction, double track_price, double limit_price) {
  if (isnan(limit_price))
    return false;
  return (direction == future::Direction::kBuy) ? (track_price - limit_price > 1e-5)
                                                : (limit_price - track_price > 1e-5);
}

/**
 * 判断行情对手量/排队量是否有效
  @param price_type: 下单价格类型 (仅支持对手/排队 -> 对应对手量/排队量)
  @param direction: 下单方向
  @param ins: 合约行情节点
 */
bool IsInsVolumeValid(const InsertOrderPriceType& price_type, const future::Direction& direction,
  std::shared_ptr<const md::Instrument> ins) {
  int ins_volume = 1;
  switch (price_type) {
    case InsertOrderPriceType::kBestPrice:
      ins_volume = (direction == future::Direction::kSell) ? ins->bid_volume[0] : ins->ask_volume[0];
      break;
    case InsertOrderPriceType::kHangPrice:
      ins_volume = (direction == future::Direction::kSell) ? ins->ask_volume[0] : ins->bid_volume[0];
      break;
    default: break;
  }
  return ins_volume > 0;
}

/**
 * 获得对手价/排队价
  @param direction: 下单方向
  @param price_type: 下单价格类型
  @param ins_node: 合约行情节点
  @return: 无对手量/排队量时, 返回nan;
 */
double GetTrackOrderPrice(const future::Direction& direction, const OrderSplitPriceType& price_type,
  std::shared_ptr<md::InstrumentNode> ins_node) {
  switch (price_type) {
    case OrderSplitPriceType::kBestPrice: {
      return (IsInsVolumeValid(InsertOrderPriceType::kBestPrice, direction, ins_node->Snap()))
        ? (direction == future::Direction::kBuy ? ins_node->Snap()->ask_price[0] : ins_node->Snap()->bid_price[0])
        : NAN;
    }
    case OrderSplitPriceType::kHangPrice: {
      return (IsInsVolumeValid(InsertOrderPriceType::kHangPrice, direction, ins_node->Snap()))
        ? (direction == future::Direction::kBuy ? ins_node->Snap()->bid_price[0] : ins_node->Snap()->ask_price[0])
        : NAN;
    }
    default: break;
  }
  return NAN;
}

const std::string GetErrorMsg(const InsertOrderPriceType& price_type) {
  switch (price_type) {
    case InsertOrderPriceType::kBestPrice: return u8"fclib: 无对价盘,算法指令停止";
    case InsertOrderPriceType::kHangPrice: return u8"fclib: 无挂价盘,算法指令停止";
    default: return "";
  }
  return "";
}

PlanSplitInstruction::PlanSplitInstruction(TradeAgent* parent, const OrderSplitParams& split_params,
  const InsertOrderPrice& order_price, const future::Direction& direction, std::shared_ptr<md::InstrumentNode> ins_node,
  int volume, std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory)
  : m_order_price(order_price)
  , m_child_factory(child_factory)
  , m_logger((parent && parent->GetLogger()) ? parent->GetLogger()->With("plan_split", GetAgentIndex()).Clone()
                                             : structlog::Logger::Root().With("plan_split", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_input_params.split_params = split_params;
  m_input_params.direction = direction;
  m_input_params.ins_node = ins_node;
  m_input_params.volume = volume;
  m_logger.With("split_params", SerializeToString(m_input_params.split_params))
    .With("order_price", SerializeToString(m_order_price))
    .With("direction", static_cast<int>(m_input_params.direction))
    .With("symbol", m_input_params.ins_node->Latest()->symbol)
    .With("volume", m_input_params.volume)
    .Info("Constructor");

  if (m_order_price.price_over < 0) {
    m_order_price.price_over = 0;
  }
  Init();
}

PlanSplitInstruction::PlanSplitInstruction(TradeAgent* parent,
  const OrderSplitInstruction::OrderSplitParamsPack& params_pack,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory)
  : m_order_price(params_pack.order_price)
  , m_child_factory(child_factory)
  , m_twap_volume_left(params_pack.twap_volume_left)
  , m_average_price(params_pack.average_price)
  , m_input_params(params_pack.split_params)
  , m_insert_datetime(params_pack.insert_datetime)
  , m_stop_datetime(params_pack.stop_datetime)
  , m_last_datetime(params_pack.last_datetime)
  , m_twap_timer(params_pack.twap_timer)
  , m_plan_index(params_pack.plan_index)
  , m_status(params_pack.status)
  , m_msg(params_pack.msg)
  , m_split_volume_plan(params_pack.split_volume_plan)
  , m_split_interval_plan(params_pack.split_interval_plan)
  , m_last_time_plan(params_pack.last_time_plan)
  , m_logger((parent && parent->GetLogger()) ? parent->GetLogger()->With("plan_split", GetAgentIndex()).Clone()
                                             : structlog::Logger::Root().With("plan_split", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_instruction_memo = params_pack.memo;
  m_input_params.split_params = params_pack.split_params.split_params;
  m_input_params.direction = params_pack.split_params.direction;
  m_input_params.ins_node = params_pack.split_params.ins_node;
  m_input_params.volume = params_pack.split_params.volume;
  m_logger.With("params_pack", SerializeToString(params_pack)).Info("LoadConstructor");

  Init(true);
}

void PlanSplitInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");
  this->Start();
}

void PlanSplitInstruction::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");
}

void PlanSplitInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");

  // 非暂停状态或补单状态不操作
  if (m_status != AgentStatus::kPaused || m_market_lame)
    return;
  // 启动定时器
  m_need_timer = true;
  ChangeStatus(true, AgentStatus::kStarted, "");
  // 行情驱动交易所拆分算法
  if (IsExchange(m_input_params.split_params)) {
    m_ins_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins, bool is_last) {
        // 状态已完成或未启动, 不再跟踪
        if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
          m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
        // 根据时间和交易状态去判断是否可以下单
        if (IsOrderInsertable())
          ExchangeSplitInsertOrder(ins);
      });
  }
  // 行情驱动冰山算法
  if (IsIceAlgo(m_input_params.split_params)) {
    m_ins_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins, bool is_last) {
        // 状态已完成或未启动, 不再跟踪
        if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
          m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
        // 根据时间和交易状态去判断是否可以下单
        if (IsOrderInsertable())
          IceSplitInsertOrder(ins);
      });
  }
  // 时间驱动 TWAP 算法
  if (IsTwapAlgo(m_input_params.split_params)) {
    m_exchange_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
        // 状态已完成或未启动, 不再跟踪
        if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
          m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
        // 根据时间和交易状态去判断是否可以下单
        if (IsOrderInsertable())
          TwapSplitInsertOrder(exchange);
      });
  }
}

void PlanSplitInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  // 非运行中状态不操作
  if (m_status != AgentStatus::kStarted)
    return;
  // 暂停定时器
  m_need_timer = false;
  // 停止 view 跟踪
  m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  ChangeStatus(true, AgentStatus::kPaused, m_msg);
  // 非交易时段不撤单
  if (!CheckTradingTime(m_input_params.ins_node, m_exchange_node->Snap()->GetDateTime())
    || !CheckTradingTime(m_input_params.ins_node, m_exchange_node->Snap()->GetDateTime() + 500000000))
    return;
  // 有下单且未撤过单的情况下撤单
  if (m_instruction && !m_track_flag) {
    // GFD 撤单 / FAK 无需撤单
    auto inserts = m_instruction->GetInsertOrder();
    if (!inserts.empty() && nullptr != inserts[0]) {
      if (inserts[0]->time_condition == future::OrderTimeCondition::kGfd) {
        m_instruction->Stop();
        m_track_flag = true;
      }
    }
  }
}

AgentStatus PlanSplitInstruction::GetStatus() const {
  // 补单状态特殊处理
  if (m_status == AgentStatus::kPaused && m_market_lame) {
    return AgentStatus::kStarted;
  }
  return m_status;
}

