int PlanSplitInstruction::VolumeTotal() {
  return m_input_params.volume;
}

int PlanSplitInstruction::VolumeLeft() {
  if (m_split_volume_plan.empty())
    return VolumeTotal();
  return std::accumulate(m_split_volume_plan.begin(), m_split_volume_plan.end(), 0) + m_twap_volume_left;
}

double PlanSplitInstruction::TradeAmount() {
  return m_average_price * (m_input_params.volume - VolumeLeft());
}

bool PlanSplitInstruction::VisibleInViewInstruction() const {
  return true;
}

void PlanSplitInstruction::OnChildNotify(TradeAgent* child) {
  m_logger.With("child", reinterpret_cast<int64_t>(child)).Info("OnChildNotify");

  auto auto_open_close_instruction = static_cast<AutoOpenCloseInstruction*>(child);
  if (auto_open_close_instruction) {
    auto order_nodes = auto_open_close_instruction->GetOrderNodes();
    m_order_nodes_set.merge(order_nodes);
  }

  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
}

void PlanSplitInstruction::ChangeOrderPrice(const ChangePriceParams& params, int request_id) {
  if (m_input_params.split_params.split_algo != OrderSplitAlgo::kIce
    || m_input_params.split_params.order_split_price_type != OrderSplitPriceType::kLimitPrice) {
    return;
  }
  if (m_instruction) {
    m_instruction->Stop();
  }
  m_order_price.limit_price = params.price;
}

