std::vector<std::shared_ptr<future::InsertOrder>> PlanSplitInstruction::GetInsertOrder() {
  std::vector<std::shared_ptr<future::InsertOrder>> ret;
  for (const auto& child : m_childs) {
    if (child) {
      auto t = child->GetInsertOrder();
      ret.insert(ret.end(), t.begin(), t.end());
    }
  }
  return ret;
}

