std::string PlanSplitInstruction::SaveInstruction() {
  // 暂停大单拆分 -> 刷新停止时间和状态.
  Pause();
  // 更新存档参数包
  OrderSplitInstruction::OrderSplitParamsPack params_pack;
  params_pack.split_params = m_input_params;
  params_pack.order_price = m_order_price;
  params_pack.symbol = m_input_params.ins_node->Snap()->symbol;
  params_pack.status = m_status;
  params_pack.msg = m_msg;
  params_pack.insert_datetime = m_insert_datetime;
  params_pack.stop_datetime = m_stop_datetime;
  params_pack.last_datetime = m_last_datetime;
  params_pack.twap_timer = m_twap_timer;
  params_pack.split_volume_plan = m_split_volume_plan;
  params_pack.split_interval_plan = m_split_interval_plan;
  params_pack.last_time_plan = m_last_time_plan;
  params_pack.plan_index = m_plan_index;
  params_pack.twap_volume_left = m_twap_volume_left;
  params_pack.average_price = m_average_price;
  params_pack.memo = m_instruction_memo;
  return SerializeToString(params_pack);
}

bool PlanSplitInstruction::CheckTwapParams(const OrderSplitParams& params, int volume, int limit_volume) {
  if (!IsSplitParamsValid(params))
    return false;
  if (IsIceAlgo(params) || IsExchange(params))
    return true;
  if (IsTwapAlgo(params)) {
    auto max_volume = (limit_volume <= 0) ? params.max_volume : std::min(limit_volume, params.max_volume);
    int interval = 0;
    if (volume < max_volume) {
      interval = params.execute_time;
    } else {
      auto length = GetRandomListLength(volume, 1, max_volume);
      interval = static_cast<int>(params.execute_time / length);
    }
    return (interval < 3) ? false : true;
  }
  return false;
}

bool PlanSplitInstruction::IsVolumeAdjustable(const OrderSplitParams& params, int volume, int limit_volume) {
  if (limit_volume <= 0)
    return false;
  OrderSplitParams split_params = params;
  split_params.max_volume = limit_volume;
  return CheckTwapParams(split_params, volume, limit_volume);
}

int PlanSplitInstruction::GetSuggestVolume(const OrderSplitParams& params, int volume, int limit_volume) {
  if (!IsSplitParamsValid(params) || IsIceAlgo(params) || IsExchange(params))
    return 0;
  if (!IsVolumeAdjustable(params, volume, limit_volume))
    return 0;
  int min_volume = 1;
  auto length = static_cast<int>(params.execute_time / 3);
  if (length <= 0)
    return 0;
  if (length == 1)
    return volume + 1;
  return static_cast<int>(ceil((volume * 2 + 1.0) / (length + 1))) - min_volume;
}

int PlanSplitInstruction::GetSuggestTime(const OrderSplitParams& params, int volume, int limit_volume) {
  if (!IsSplitParamsValid(params) || IsIceAlgo(params) || IsExchange(params))
    return 0;
  auto max_volume = (limit_volume <= 0) ? params.max_volume : std::min(limit_volume, params.max_volume);
  if (volume < max_volume) {
    return 3;
  }
  auto length = GetRandomListLength(volume, 1, max_volume);
  return length * 3;
}

void PlanSplitInstruction::Init(bool is_load /* = false*/) {
  if (m_status == AgentStatus::kStopped) {
    return;
  }
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (future::Direction::kInvalid == m_input_params.direction) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 买卖方向无效");
    return;
  }
  if (!m_input_params.ins_node || !m_input_params.ins_node->Latest()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 交易合约无效");
    return;
  }
  if (!IsSplitParamsValid(m_input_params.split_params)) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 大单拆分参数无效");
    return;
  }
  // 检查TWAP拆分后间隔是否满足 >3s
  auto limit_volume = m_input_params.ins_node->Snap()->instrument_base->max_limit_order_volume;
  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少交易所信息");
    return;
  }
  if (!CheckTwapParams(m_input_params.split_params, m_input_params.volume, limit_volume)) {
    ChangeStatus(false, AgentStatus::kStopped, "fclib: 每次下单时间间隔不能小于3s");
    return;
  }
  if (IsExchange(m_input_params.split_params)
    && m_input_params.ins_node->Latest()->instrument_base->max_limit_order_volume <= 0
    && m_input_params.ins_node->Latest()->instrument_base->max_market_order_volume <= 0) {
    ChangeStatus(false, AgentStatus::kStopped, "fclib: 合约不支持下单");
    return;
  }
  // 创建 exchange_view 方便刷新状态
  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  // 创建 ins_view 方便后续持续发单
  auto symbol = m_input_params.ins_node->Snap()->symbol;
  m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
    symbol, false, [symbol](std::shared_ptr<const md::Instrument> ins) {
      return ins->symbol == symbol;
    });

  m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status == AgentStatus::kStopped && m_ins_view) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        m_ins_view.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });
  // 构建TWAP 定时器
  CreateTwapTimer();
  // 首次创建初始化参数
  InitCreateParams(limit_volume, is_load);
  // 跟踪
  m_exchange_view->AfterCommit("PlanSplit_Init" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status == AgentStatus::kStopped) {
        m_exchange_view->DeleteCommit(
          std::to_string(reinterpret_cast<int64_t>(this)) + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (UpdateInstruction()) {
        if (m_parent)
          m_parent->OnChildNotify(this);
        if (m_call_back)
          m_call_back(shared_from_this());
      }
      if (!m_market_lame) {
        return;
      }
      if (!m_instruction && !m_lame_send) {
        // 补剩余单
        if (m_child_factory) {
          InsertOrderPrice order_price;
          order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
          order_price.order_price_type = InsertOrderPriceType::kBestPrice;
          order_price.price_over = m_market_price_over;
          m_instruction = m_child_factory(this, VolumeLeft(), order_price);
          m_last_volume_left = m_instruction->VolumeLeft();
          m_childs.push_back(m_instruction);
          m_instruction->Run();
        }
        m_lame_send = true;
      }
      // 已补单 但是场上已没有挂单 说明补单已经完成或被撤单 此时停止补单状态
      if (!m_instruction && m_lame_send) {
        m_market_lame = false;
        if (m_parent)
          m_parent->OnChildNotify(this);
        if (m_call_back)
          m_call_back(shared_from_this());
      }
    });
}

void PlanSplitInstruction::InitInsertOrderPrice() {
  if (IsExchange(m_input_params.split_params)) {
    return;
  }
  if (IsIceAlgo(m_input_params.split_params)) {
    switch (m_input_params.split_params.order_split_price_type) {
      case OrderSplitPriceType::kLimitPrice: {
        // 冰山: 指定价模式下, 采用 GFD 指定价下单, limit_price 沿用
        m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeNone;
        m_order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
        break;
      }
      case OrderSplitPriceType::kBestPrice: {
        // 冰山: 对价模式下, 采用 FAK 对价下单
        m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
        m_order_price.order_price_type = InsertOrderPriceType::kBestPrice;
        break;
      }
      case OrderSplitPriceType::kHangPrice:
      case OrderSplitPriceType::kAutoPrice: {
        // 冰山: 挂价/智能模式下, 初始均采用 GFD 挂价下单
        m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeNone;
        m_order_price.order_price_type = InsertOrderPriceType::kHangPrice;
        break;
      }
      default: break;
    }
  }
  if (IsTwapAlgo(m_input_params.split_params)) {
    // TWAP: 初始均采用 GFD 挂价下单
    m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeNone;
    m_order_price.order_price_type = InsertOrderPriceType::kHangPrice;
  }
}

void PlanSplitInstruction::InitCreateParams(int limit_volume, bool is_load) {
  if (is_load)
    return;
  InitInsertOrderPrice();

  m_insert_datetime = m_exchange_node->Snap()->GetDateTime();
  // 交易所拆分
  if (IsExchange(m_input_params.split_params)) {
    // 如果是市价交易, 否则都按限价交易
    m_split_volume_plan.clear();
    auto max = GetExchangeMaxVolume();
    int cnt = m_input_params.volume / max;
    int left = m_input_params.volume % max;
    for (auto i = 0; i < cnt; i++) {
      m_split_volume_plan.push_back(max);
    }
    if (left > 0) {
      m_split_volume_plan.push_back(left);
    }
    m_logger.With("max", max)
      .With("cnt", cnt)
      .With("left", left)
      .With("order_price_type", static_cast<int>(m_order_price.order_price_type))
      .Info("InitCreateParams");
    return;
  }

  auto max_volume = (limit_volume <= 0) ? std::min(m_input_params.split_params.max_volume,
                      m_input_params.ins_node->Latest()->instrument_base->max_limit_order_volume)
                                        : std::min({limit_volume, m_input_params.split_params.max_volume,
                                          m_input_params.ins_node->Latest()->instrument_base->max_limit_order_volume});
  // 随机拆分手数和时间间隔
  if (m_input_params.volume < max_volume) {
    m_split_volume_plan = {m_input_params.volume};
    if (IsTwapAlgo(m_input_params.split_params)) {
      m_split_interval_plan = {m_input_params.split_params.execute_time};
    }
  } else {
    m_split_volume_plan = GetRandomList(m_input_params.volume, 1, max_volume);
    if (IsTwapAlgo(m_input_params.split_params)) {
      auto interval = static_cast<int>(m_input_params.split_params.execute_time / m_split_volume_plan.size());
      m_split_interval_plan = GetRandomList(m_input_params.split_params.execute_time, std::max(3, interval - 2),
        interval * 2 - std::max(3, interval - 2) + 1, static_cast<int>(m_split_volume_plan.size()));
      FCASSERT(!m_split_interval_plan.empty());
    }
  }
  FCASSERT(!m_split_volume_plan.empty());
  for (size_t i = 0; i < m_split_volume_plan.size(); i++)
    m_last_time_plan.push_back(0);
  m_logger.With("max_volume", max_volume)
    .With("split_volume_plan_size", static_cast<int>(m_split_volume_plan.size()))
    .Info("InitCreateParams");
}

bool PlanSplitInstruction::IsTwapTimeOut(int index) {
  int interval_sum = 0;
  for (auto i = 0; i < index; i++) {
    interval_sum += m_split_interval_plan[i];
  }
  return m_twap_timer >= (md::EpochNano)interval_sum * 1000000000;
}

bool PlanSplitInstruction::IsTwapStrictTimeOut() {
  int interval_sum = 0;
  for (auto i = 0; i < m_plan_index - 1; i++) {
    interval_sum += m_split_interval_plan[i];
  }
  interval_sum += GetStrictInterval();
  return m_twap_timer >= (md::EpochNano)interval_sum * 1000000000;
}

int PlanSplitInstruction::GetStrictInterval() {
  int interval = m_split_interval_plan[m_plan_index];
  return interval - std::max(2, interval / 3);
}

int PlanSplitInstruction::GetCurrentVolume() {
  return (m_plan_index < static_cast<int>(m_split_volume_plan.size())) ? m_split_volume_plan[m_plan_index]
                                                                       : m_twap_volume_left;
}

void PlanSplitInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;

  if (m_insert_datetime <= 0) {
    m_insert_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
  }
  if (m_status == AgentStatus::kStarted)
    m_stop_datetime = 0;
  else
    m_stop_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
  if (m_msg != msg)
    m_msg = msg;
  if (notify && m_parent)
    m_parent->OnChildNotify(this);
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

void PlanSplitInstruction::CreateInstruction() {
  if (m_child_factory) {
    m_instruction = m_child_factory(this, GetCurrentVolume(), m_order_price);
    m_last_volume_left = m_instruction->VolumeLeft();
    m_last_traded_amount = 0;
    m_instruction->Run();
    m_childs.push_back(m_instruction);

    m_logger.With("price_type", static_cast<int>(m_order_price.order_price_type))
      .With("price_over", m_order_price.price_over)
      .With("advanced_limit", static_cast<int>(m_order_price.advanced_limit))
      .With("limit_price", m_order_price.limit_price)
      .With("last_volume_left", m_last_volume_left)
      .Info("CreateInstruction");
  }
}

void PlanSplitInstruction::CreateTwapTimer() {
  if (IsIceAlgo(m_input_params.split_params) || IsExchange(m_input_params.split_params))
    return;
  // TWAP 尚未启动, 不进行计时
  if (m_last_datetime <= 0)
    return;
  // TWAP 定时器, 仅 TWAP 处于非暂停且在交易时段内做时间累加.
  m_exchange_view->AfterCommit("TWAP_Timer" + std::to_string(reinterpret_cast<int64_t>(this)),
    [=](std::shared_ptr<md::ExchangeNode> exchange, bool) {
      if (m_status == AgentStatus::kStopped) {
        m_exchange_view->DeleteCommit("TWAP_Timer" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (m_need_timer)
        m_twap_timer += exchange->Snap()->GetDateTime() - m_last_datetime;
      m_need_timer = m_status != AgentStatus::kPaused
        && CheckTradingTime(m_input_params.ins_node, m_exchange_node->Snap()->GetDateTime());
      m_last_datetime = exchange->Snap()->GetDateTime();
      return;
    });
}

void PlanSplitInstruction::ExchangeSplitInsertOrder(std::shared_ptr<md::InstrumentNode> ins) {
  m_logger.With("current_volume", GetCurrentVolume())
    .With("ask_volume", ins->Snap()->ask_volume[0])
    .With("bid_volume", ins->Snap()->bid_volume[0])
    .Debug("ExchangeSplitInsertOrder");

  // 下单
  if (GetCurrentVolume() > 0) {
    // 构建下单指令
    if (!m_instruction) {
      if (!IsInsVolumeValid(m_order_price.order_price_type, m_input_params.direction, ins->Snap())) {
        ChangeStatus(true, AgentStatus::kPaused, GetErrorMsg(m_order_price.order_price_type));
        return;
      }
      CreateInstruction();
    }
    return;
  }
}

void PlanSplitInstruction::IceSplitInsertOrder(std::shared_ptr<md::InstrumentNode> ins) {
  m_logger.With("current_volume", GetCurrentVolume())
    .With("ask_volume", ins->Snap()->ask_volume[0])
    .With("bid_volume", ins->Snap()->bid_volume[0])
    .Debug("IceSplitInsertOrder");

  // 下单
  if (GetCurrentVolume() > 0) {
    // 构建下单指令
    if (!m_instruction) {
      if (!IsInsVolumeValid(m_order_price.order_price_type, m_input_params.direction, ins->Snap())) {
        ChangeStatus(true, AgentStatus::kPaused, GetErrorMsg(m_order_price.order_price_type));
        return;
      }
      CreateInstruction();
      // 随机分配每个第一次下单, 记录下单时间点
      if (m_last_time_plan[m_plan_index] == 0)
        m_last_time_plan[m_plan_index] = ins->Snap()->exchange_time;
    }
    return;
  }
}

void PlanSplitInstruction::TwapSplitInsertOrder(std::shared_ptr<md::ExchangeNode> exchange) {
  m_logger.With("current_volume", GetCurrentVolume())
    .With("time_out", IsTwapTimeOut(m_plan_index))
    .With("ask_volume", m_input_params.ins_node->Snap()->ask_volume[0])
    .With("bid_volume", m_input_params.ins_node->Snap()->bid_volume[0])
    .Debug("TwapSplitInsertOrder");

  // 下单
  if (GetCurrentVolume() > 0 && IsTwapTimeOut(m_plan_index)) {
    // 构建下单指令
    if (!m_instruction) {
      if (!IsInsVolumeValid(
            m_order_price.order_price_type, m_input_params.direction, m_input_params.ins_node->Snap())) {
        ChangeStatus(true, AgentStatus::kPaused, GetErrorMsg(m_order_price.order_price_type));
        return;
      }
      CreateInstruction();
      // 第一次启动刷新更新时间, 构建定时器
      if (m_last_datetime <= 0) {
        m_last_datetime = exchange->Snap()->GetDateTime();
        // 构建 TWAP 定时器
        CreateTwapTimer();
      }
    }
  }
}

bool PlanSplitInstruction::UpdateInstruction() {
  if (nullptr == m_instruction)
    return false;
  bool ret = false;

  // 刷新手数成交信息
  RefreshVolumeTraded(m_instruction);

  if (m_instruction->GetStatus() == AgentStatus::kStopped) {
    ret = true;
    bool is_index_added = false;
    if (!m_instruction->GetMsg().empty()) {
      // 发生错误, 暂停
      ChangeStatus(true, AgentStatus::kPaused, m_instruction->GetMsg());
    } else {
      // 尝试进行下一个 plan 项
      is_index_added = UpdatePlanIndex();
    }
    CheckTwapIndexTimeOut(is_index_added);
    if (VolumeLeft() <= 0)
      ChangeStatus(true, AgentStatus::kStopped, m_msg);
    m_track_flag = false;
    m_last_volume_left = 0;
    m_instruction.reset();
    return ret;
  }
  if (!IsNeedTrackOrder(m_order_price.order_price_type) || IsExchange(m_input_params.split_params))
    return ret;
  // 非交易时段不操作
  if (!CheckTradingTime(m_input_params.ins_node, m_exchange_node->Snap()->GetDateTime())
    || !CheckTradingTime(m_input_params.ins_node, m_exchange_node->Snap()->GetDateTime() + 500000000))
    return ret;
  // 已撤过单不再撤单
  if (m_track_flag)
    return ret;
  if (UpdateOrderPrice())
    return ret;
  // 根据价格是否变化决定是否需要撤单
  auto track_price =
    GetTrackOrderPrice(m_input_params.direction, OrderSplitPriceType::kHangPrice, m_input_params.ins_node);
  if (isnan(track_price)) {
    ret = true;
    ChangeStatus(true, AgentStatus::kPaused, GetErrorMsg(InsertOrderPriceType::kHangPrice));
    m_instruction->Stop();
    m_track_flag = true;
  } else {
    auto inserts = m_instruction->GetInsertOrder();
    if (inserts.empty() || nullptr == inserts[0])
      return ret;
    if (IsNeedCancelOrder(m_input_params.direction, track_price, inserts[0]->limit_price)
      || m_status == AgentStatus::kPaused) {
      ret = true;
      m_instruction->Stop();
      m_track_flag = true;
    }
  }
  return ret;
}

bool PlanSplitInstruction::UpdatePlanIndex() {
  if (GetCurrentVolume() > 0)
    return false;
  ++m_plan_index;
  InitInsertOrderPrice();
  return true;
}

void PlanSplitInstruction::CheckTwapIndexTimeOut(bool is_added) {
  if (!IsTwapAlgo(m_input_params.split_params))
    return;
  if (!is_added) {
    if (m_plan_index < static_cast<int>(m_split_volume_plan.size()) && IsTwapTimeOut(m_plan_index + 1)) {
      auto volume_left = m_split_volume_plan[m_plan_index];
      m_split_volume_plan[m_plan_index] = 0;
      ++m_plan_index;
      if (m_plan_index < static_cast<int>(m_split_volume_plan.size())) {
        m_split_volume_plan[m_plan_index] += volume_left;
        InitInsertOrderPrice();
      } else {
        m_twap_volume_left = volume_left;
        m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
        m_order_price.order_price_type = InsertOrderPriceType::kBestPrice;
      }
    }
  }
}

bool PlanSplitInstruction::UpdateOrderPrice() {
  if (IsExchange(m_input_params.split_params))
    return false;
  if (IsIceAlgo(m_input_params.split_params)) {
    if (m_input_params.split_params.order_split_price_type != OrderSplitPriceType::kAutoPrice)
      return false;
    if (m_last_time_plan[m_plan_index] <= 0
      || m_exchange_node->Snap()->GetDateTime() - m_last_time_plan[m_plan_index] <= TimeLimit)
      return false;
  }
  if (IsTwapAlgo(m_input_params.split_params)) {
    if (!IsTwapStrictTimeOut())
      return false;
  }
  m_order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
  m_order_price.order_price_type = InsertOrderPriceType::kBestPrice;
  // 超过3s且下单指令为GFD的智能模式需要撤单
  auto inserts = m_instruction->GetInsertOrder();
  if (!inserts.empty() && nullptr != inserts[0]) {
    if (inserts[0]->time_condition != future::OrderTimeCondition::kGfd)
      return false;
  }
  m_instruction->Stop();
  m_track_flag = true;
  return true;
}

void PlanSplitInstruction::RefreshVolumeTraded(std::shared_ptr<TradeInstruction> instruction) {
  // 计算手数和成交量的变化
  int traded_volume = m_last_volume_left - instruction->VolumeLeft();
  m_last_volume_left = instruction->VolumeLeft();
  double traded_amount = 0;
  if (traded_volume != 0) {
    traded_amount = instruction->TradeAmount() - m_last_traded_amount;
    m_last_traded_amount = instruction->TradeAmount();
  }
  FCASSERT(traded_volume <= VolumeLeft());

  m_logger.With("traded_volume", traded_volume)
    .With("last_volume_left", m_last_volume_left)
    .With("twap_volume_left", m_twap_volume_left)
    .With("prev_average_price", m_average_price)
    .With("plan_index", m_plan_index)
    .Info("RefreshVolumeTraded");

  if (0 == traded_volume) {
    return;
  }
  m_average_price = isnan(m_average_price) ? 0 : m_average_price;
  m_average_price = (TradeAmount() + traded_amount) / (m_input_params.volume - VolumeLeft() + traded_volume);

  if (m_twap_volume_left) {
    if (m_twap_volume_left < traded_volume) {
      m_twap_volume_left = 0;
      traded_volume -= m_twap_volume_left;
    } else {
      m_twap_volume_left -= traded_volume;
    }
  } else {
    while (m_plan_index < static_cast<int>(m_split_volume_plan.size())) {
      auto& plan = m_split_volume_plan[m_plan_index];
      if (plan < traded_volume) {
        traded_volume -= plan;
        plan = 0;
        ++m_plan_index;
      } else {
        plan -= traded_volume;
        break;
      }
    }
  }

  m_logger.With("average_price", m_average_price).With("plan_index", m_plan_index).Info("RefreshVolumeTraded");

  if (VolumeLeft() == 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
  }
}

bool PlanSplitInstruction::IsOrderInsertable() {
  m_logger.With("trading_allowed", m_input_params.ins_node->Latest()->IsTradingAllowed())
    .With("exchange_time", m_exchange_node->Snap()->GetDateTime())
    .Debug("IsOrderInsertable");

  // 冰山算法和交易所拆分算法的限价单在集合竞价也可以发单
  // confluence:https://shinnytech.atlassian.net/wiki/spaces/Q7PC/pages/1526562828
  if ((IsIceAlgo(m_input_params.split_params) || IsExchange(m_input_params.split_params))
    && m_order_price.order_price_type == InsertOrderPriceType::kLimitPrice
    && m_input_params.ins_node->Latest()->IsTradingAllowed()) {
    return true;
  }
  // 其他算法集合竞价不可以下单
  if (!m_input_params.ins_node->Latest()->IsTradingAllowed(true)) {
    return false;
  }
  return true;
}

void PlanSplitInstruction::MarketLame(int price_over) {
  // 已在补单 或 已完成 不允许再次点击
  if (m_market_lame || m_status == fclib::extension::AgentStatus::kStopped)
    return;
  m_market_price_over = price_over;
  Pause();
  m_market_lame = true;
  m_lame_send = false;
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
}

std::string PlanSplitInstruction::VectorToString(const std::vector<int>& vec) {
  if (vec.empty())
    return "";
  return std::accumulate(vec.begin() + 1, vec.end(), std::to_string(vec[0]), [](const std::string& a, int b) {
    return a + "," + std::to_string(b);
  });
}

void PlanSplitInstruction::ChangeParamsVolume(int volume) {
  m_logger.With("volume", volume).With("status", static_cast<int>(m_status)).Info("ChangeParamsVolume");
  if (m_split_volume_plan.empty())
    return;
  if (IsTwapAlgo(m_input_params.split_params))
    return;
  if (m_status == AgentStatus::kStopped)
    return;
  if (volume <= 0)
    return;
  Pause();
  int volume_total = VolumeTotal();
  int volume_remain = VolumeLeft();
  int volume_traded = volume_total - volume_remain;
  m_logger.With("volume_total", volume_total)
    .With("volume_remain", volume_remain)
    .With("volume_traded", volume_traded)
    .Info("ChangeParamsVolume");

  if (volume_traded >= volume)
    return;
  auto volume_left = volume - volume_traded;
  m_input_params.volume = volume;
  auto limit_vol = m_input_params.ins_node->Snap()->instrument_base->max_limit_order_volume;
  auto max_vol = (limit_vol <= 0) ? std::min(volume_left, m_input_params.split_params.max_volume)
                                  : std::min({limit_vol, volume_left, m_input_params.split_params.max_volume});
  m_logger.With("limit_vol", limit_vol).With("max_vol", max_vol).Info("ChangeParamsVolume");
  if (IsIceAlgo(m_input_params.split_params)) {
    std::vector<int> plus_vec = GetRandomList(volume_left, 1, max_vol);
    m_split_volume_plan.erase(m_split_volume_plan.begin() + m_plan_index, m_split_volume_plan.end());
    m_last_time_plan.erase(m_last_time_plan.begin() + m_plan_index, m_last_time_plan.end());
    m_split_volume_plan.insert(m_split_volume_plan.end(), plus_vec.begin(), plus_vec.end());
    m_last_time_plan.insert(m_last_time_plan.end(), plus_vec.size(), 0);
    FCASSERT(m_last_time_plan.size() == m_split_volume_plan.size());
  }

  if (IsExchange(m_input_params.split_params)) {
    std::vector<int> plus_vec;
    m_split_volume_plan.erase(m_split_volume_plan.begin() + m_plan_index, m_split_volume_plan.end());

    auto max = GetExchangeMaxVolume();
    int cnt = volume_left / max;
    int left = volume_left % max;
    for (auto i = 0; i < cnt; i++) {
      m_split_volume_plan.push_back(max);
    }
    m_split_volume_plan.push_back(left);
    m_logger.With("max", max).With("cnt", cnt).With("left", left).Info("ChangeParamsVolume");
  }
  m_logger.With("m_split_volume_plan", VectorToString(m_split_volume_plan)).Info("ChangeParamsVolume");
}

std::set<std::shared_ptr<future::OrderNode>> PlanSplitInstruction::GetOrderNodes() {
  return m_order_nodes_set;
}

int PlanSplitInstruction::GetExchangeMaxVolume() {
  if (!IsExchange(m_input_params.split_params)) {
    FCASSERT(false);
    return 0;
  }
  auto max = (m_order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    ? m_input_params.ins_node->Latest()->instrument_base->max_market_order_volume
    : m_input_params.ins_node->Latest()->instrument_base->max_limit_order_volume;
  // 如果市价最大下单手数为 0, 则使用限价最大下单手数
  if (max == 0) {
    max = m_input_params.ins_node->Latest()->instrument_base->max_limit_order_volume;
  }
  FCASSERT(max != 0);
  return max;
}

