void GetCancelOrderList(const std::shared_ptr<md::InstrumentNode> ins_node, const std::string& user_key,
  const future::Direction& direction, bool is_swap, std::function<void(std::shared_ptr<future::OrderNode>)> fun);

double GetRatioByProductId(const std::string& product_id, const std::map<std::string, double>& table) {
  FCASSERT(table.find("default") != table.end());
  auto it = table.find(product_id);
  if (it != table.end())
    return it->second;
  else
    return table.at("default");
}

double GetVolumeRatio(
  const std::string& user_key, const std::vector<std::string>& user_key_list, const std::string& product_id) {
  double ret = 0.0;
  double total = 0.0;
  for (auto& key : user_key_list) {
    auto it = VolumeSplitInstruction::GetVolumeRatioMap().find(key);
    if (it == VolumeSplitInstruction::GetVolumeRatioMap().end() || it->second.find("default") == it->second.end()) {
      auto t = VolumeSplitInstruction::GetVolumeRatioMap();
      t[key]["default"] = 1.0;
      VolumeSplitInstruction::SetVolumeRatioMap(t);
      it = VolumeSplitInstruction::GetVolumeRatioMap().find(key);
    }
    auto t = GetRatioByProductId(product_id, it->second);
    total += t;
    if (key == user_key)
      ret = t;
  }
  if (total == 0.0)
    return 0.0;
  return ret / total;
}

void GetBestAllocation(const std::vector<std::pair<std::string, double>>& src, int total,
  std::function<void(const std::string& user_key, const int vol)> fun) {
  std::map<std::string, int> ret;
  int left = total;
  for (auto& [user, va] : src) {
    if (va <= 0.000001) {
      fun(user, 0);
      continue;
    }
    int vol = static_cast<int>(floor(va * total));
    ret[user] = vol;
    left -= vol;
  }
  while (left > 0) {
    std::string min_user;
    double min_over = 1000.0;
    for (auto& [user, va] : src) {
      if (va > 0.0) {
        double over = fabs(va - (ret[user] + 1) * 1.0 / (total - left + 1));
        if (over < min_over) {
          min_user = user;
          min_over = over;
        }
      }
    }
    if (min_user.empty()) {
      break;
    } else {
      ret[min_user] += 1;
      left--;
    }
  }
  for (auto& [user, vol] : ret) {
    fun(user, vol);
  }
}

const future::SubPosition* GetNegativeSubPosition(std::shared_ptr<const md::InstrumentNode> ins_node,
  const std::string& user_key, const future::OrderHedgeFlag& hedge, const future::Direction& direction) {
  auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
    future::Position::MakeKey(user_key, 0, ins_node->Latest()->symbol));
  if (!position_node)
    return nullptr;
  if (hedge == future::OrderHedgeFlag::kSpeculation) {
    if (direction == future::Direction::kBuy)
      return &position_node->Latest()->subpos_short_spec;
    return &position_node->Latest()->subpos_long_spec;
  }
  if (direction == future::Direction::kBuy)
    return &position_node->Latest()->subpos_short_other;
  return &position_node->Latest()->subpos_long_other;
}

VolumeSplitParams RegulateParams(const VolumeSplitParams& params) {
  auto ret = params;
  if (ret.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine && ret.is_swap) {
    // 调整移仓参数
    if (ret.split_offset == SplitOffset::kOpen) {
      ret.split_offset = SplitOffset::kClose;
      ret.direction = NegativeDir(ret.direction);
      ret.ins_node = ret.ins_node->Latest()->instrument_base->leg2_pointer;
      FCASSERT(ret.ins_node);
    } else {
      ret.ins_node = ret.ins_node->Latest()->instrument_base->leg1_pointer;
      FCASSERT(ret.ins_node);
    }
  }
  return ret;
}

int GetVolumeBySubPosition(const SplitOffset& offset, const future::SubPosition* subpos) {
  FCASSERT(nullptr != subpos);
  if (offset == SplitOffset::kClose || offset == SplitOffset::kCloseBoth) {
    return subpos->Volume() - subpos->VolumeFrozen();
  } else if (offset == SplitOffset::kCloseToday) {
    return subpos->volume_today - subpos->volume_today_frozen;
  } else if (offset == SplitOffset::kCloseHis) {
    return subpos->volume_his - subpos->volume_his_frozen;
  }
  return 0;
}

void RegulateCloseVolumeByCancelOrder(int* ret, const std::string& user_key, const SplitOffset& offset,
  const future::SubPosition* subpos, const future::Direction& direction, bool is_swap,
  std::shared_ptr<md::InstrumentNode> ins_node) {
  GetCancelOrderList(ins_node, user_key, direction, is_swap, [&](std::shared_ptr<future::OrderNode> node) {
    if ((offset == SplitOffset::kClose || offset == SplitOffset::kCloseBoth)
      && node->Latest()->offset != future::Offset::kOpen) {
      *ret = std::min(subpos->Volume(), *ret + node->Latest()->volume_left);
      return;
    }
    if (offset == SplitOffset::kCloseToday && node->Latest()->offset == future::Offset::kCloseToday) {
      *ret = std::min(subpos->volume_today, *ret + node->Latest()->volume_left);
      return;
    }
    if (offset == SplitOffset::kCloseHis
      && (node->Latest()->offset == future::Offset::kCloseYesterday
        || node->Latest()->offset == future::Offset::kClose)) {
      *ret = std::min(subpos->volume_his, *ret + node->Latest()->volume_left);
      return;
    }
  });
}

void GetActualPositionVolume(
  const VolumeSplitParams& params, std::map<std::string, int>* ret, const VolumeSplitParams& cancel_params) {
  VolumeSplitParams p = params;
  if (p.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine && p.is_swap) {
    p = RegulateParams(params);
    return GetActualPositionVolume(p, ret, params);
  }
  if (p.split_offset == SplitOffset::kOpen)
    return;
  for (auto& user_key : p.user_key_list) {
    int volume = 0;
    if (p.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
      std::shared_ptr<md::InstrumentNode> ins_node0 = p.ins_node->Latest()->instrument_base->leg1_pointer;
      std::shared_ptr<md::InstrumentNode> ins_node1 = p.ins_node->Latest()->instrument_base->leg2_pointer;
      auto sub0 = GetNegativeSubPosition(ins_node0, user_key, p.hedge, p.direction);
      auto sub1 = GetNegativeSubPosition(ins_node1, user_key, p.hedge, NegativeDir(p.direction));
      if (sub0 && sub1 && sub0->Volume() > 0 && sub1->Volume() > 0) {
        int close_vol0 = sub0->Volume() - sub0->VolumeFrozen();
        int close_vol1 = sub1->Volume() - sub1->VolumeFrozen();
        if (p.cancel_order) {
          GetCancelOrderList(cancel_params.ins_node, user_key, cancel_params.direction, cancel_params.is_swap,
            [&](std::shared_ptr<future::OrderNode> node) {
              if (node->Latest()->offset == future::Offset::kClose) {
                close_vol0 = std::min(close_vol0 + node->Latest()->volume_left, sub0->Volume());
                close_vol1 = std::min(close_vol1 + node->Latest()->volume_left, sub1->Volume());
              }
            });
        }
        volume = std::min(close_vol0, close_vol1);
      }
    } else if (p.ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine) {
      auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::CusCombinePosition>(
        future::CusCombinePosition::MakeKey(user_key, 0, p.ins_node->Latest()->symbol, NegativeDir(p.direction)));
      volume = position_node ? position_node->Latest()->available_shares : 0;
      if (p.cancel_order)
        volume = position_node ? position_node->Latest()->shares : 0;
    } else {
      auto sub = GetNegativeSubPosition(p.ins_node, user_key, p.hedge, p.direction);
      if (sub && sub->Volume() > 0) {
        volume = GetVolumeBySubPosition(p.split_offset, sub);
        if (p.cancel_order)
          RegulateCloseVolumeByCancelOrder(&volume, user_key, p.split_offset, sub, cancel_params.direction,
            cancel_params.is_swap, cancel_params.ins_node);
      }
    }
    (*ret)[user_key] = volume;
  }
}

VolumeSplitInstructionImpl::VolumeSplitInstructionImpl(TradeAgent* parent, const VolumeSplitParams& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : VolumeSplitInstruction(parent, params, child_factory) {
  FCASSERT(params.ins_node);
  FCASSERT(params.split_offset != SplitOffset::kAuto);
}

VolumeSplitInstructionImpl::VolumeSplitInstructionImpl(TradeAgent* parent, const VolumeSplitParams& params,
  const std::vector<int>& plans,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : VolumeSplitInstruction(parent, params, plans, child_factory) {
  FCASSERT(params.ins_node);
  FCASSERT(params.split_offset != SplitOffset::kAuto);
}

VolumeSplitInstructionImpl::VolumeSplitInstructionImpl(TradeAgent* parent, const VolumeSplitInstructionPack& pack)
  : VolumeSplitInstruction(parent, pack) {}

VolumeSplitInstructionImpl::~VolumeSplitInstructionImpl() {}

void VolumeSplitInstructionImpl::SplitVolume(const VolumeSplitParams& params, std::vector<int>* ret) {
  if (params.user_key_list.empty())
    return;
  // 开仓移仓统一按照平仓处理
  if (params.split_offset == SplitOffset::kOpen && !params.is_swap) {
    SplitOpenVolume(params, ret);
  } else {
    SplitCloseVolume(params, ret);
  }
  // 系数调整
  for (auto&& vol : *ret)
    vol = static_cast<int>(vol * params.ratio);
  return;
}

void VolumeSplitInstructionImpl::RegulateVolume(const VolumeSplitParams& params, std::vector<int>* ret) {
  FCASSERT(params.user_key_list.size() == ret->size());
  for (int index = 0; index < static_cast<int>(ret->size()); ++index) {
    auto user_key = params.user_key_list[index];
    int* vol = &(*ret)[index];
    if (*vol == 0)
      continue;
    if (params.split_offset == SplitOffset::kOpen && !params.is_swap)
      continue;
    auto p = params;
    if (params.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine && params.is_swap)
      p = RegulateParams(p);
    if (p.split_offset == SplitOffset::kOpen)
      continue;
    if (p.ins_node->Snap()->ProductClass() == md::ProductClass::kCombine) {
      std::shared_ptr<md::InstrumentNode> ins_node0 = p.ins_node->Snap()->instrument_base->leg1_pointer;
      std::shared_ptr<md::InstrumentNode> ins_node1 = p.ins_node->Snap()->instrument_base->leg2_pointer;
      auto sub0 = GetNegativeSubPosition(ins_node0, user_key, p.hedge, p.direction);
      auto sub1 = GetNegativeSubPosition(ins_node1, user_key, p.hedge, NegativeDir(p.direction));
      if (sub0 && sub1 && sub0->Volume() > 0 && sub1->Volume() > 0) {
        int close_vol0 = sub0->Volume() - sub0->VolumeFrozen();
        int close_vol1 = sub1->Volume() - sub1->VolumeFrozen();
        if (p.cancel_order) {
          GetCancelOrderList(
            params.ins_node, user_key, params.direction, false, [&](std::shared_ptr<future::OrderNode> node) {
              if (node->Latest()->offset == future::Offset::kClose) {
                close_vol0 = std::min(close_vol0 + node->Latest()->volume_left, sub0->Volume());
                close_vol1 = std::min(close_vol1 + node->Latest()->volume_left, sub1->Volume());
              }
            });
        }
        *vol = std::min(std::min(close_vol0, close_vol1), *vol);
      }
      continue;
    }
    if (p.ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine) {
      auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::CusCombinePosition>(
        future::CusCombinePosition::MakeKey(user_key, 0, p.ins_node->Latest()->symbol, NegativeDir(p.direction)));
      if (nullptr == position_node) {
        *vol = 0;
        continue;
      }
      int calc_volume = (p.cancel_order) ? position_node->Latest()->shares : position_node->Latest()->available_shares;
      *vol = std::min(calc_volume, *vol);
      continue;
    }
    auto sub = GetNegativeSubPosition(p.ins_node, user_key, p.hedge, p.direction);
    if (nullptr == sub || sub->Volume() <= 0) {
      *vol = 0;
      continue;
    }
    int calc_volume = GetVolumeBySubPosition(p.split_offset, sub);
    if (p.cancel_order) {
      RegulateCloseVolumeByCancelOrder(
        &calc_volume, user_key, p.split_offset, sub, params.direction, params.is_swap, params.ins_node);
    }
    *vol = std::min(calc_volume, *vol);
  }
}

void VolumeSplitInstructionImpl::SplitOpenVolume(const VolumeSplitParams& params, std::vector<int>* ret) {
  if (params.split_offset != SplitOffset::kOpen || params.is_swap)
    return;
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kBaseRatioRatio: {
      for (const auto& user_key : params.user_key_list) {
        int volume = params.volume;
        auto it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
        if (it != VolumeSplitInstruction::GetVolumeRatioMap().end()) {
          if (it->second.find("default") == it->second.end()) {
            auto t = VolumeSplitInstruction::GetVolumeRatioMap();
            t[user_key]["default"] = 1.0;
            VolumeSplitInstruction::SetVolumeRatioMap(t);
            it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
          }
          auto t = GetRatioByProductId(params.ins_node->Latest()->ProductID(), it->second);
          volume = static_cast<int>(std::round(t * volume));
        }
        ret->push_back(volume);
      }
      break;
    }
    case InsertOrderStrategy::kBaseFirstFirst: {
      double first_available = 0.0;
      auto account_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(
        future::Account::MakeKey(params.user_key_list[0], 0, "CNY"));
      if (account_node)
        first_available = account_node->Latest()->available;
      for (const auto& user_key : params.user_key_list) {
        int volume = params.volume;
        if (user_key != params.user_key_list[0]) {
          double available = 0.0;
          if (auto account = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(
                future::Account::MakeKey(user_key, 0, "CNY")))
            available = account->Latest()->available;
          if (available > 0 && first_available > 0) {
            volume = static_cast<int>(std::round(params.volume * (available / first_available)));
          } else {
            volume = 0;
          }
        }
        ret->push_back(volume);
      }
      break;
    }
    case InsertOrderStrategy::kTotalRatioAvailable:
    case InsertOrderStrategy::kTotalAvailableAvailable:
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      std::map<std::string, int> allocate;
      std::vector<std::pair<std::string, double>> src;
      CalcOpenAllocateRatio(params, &src);
      GetBestAllocation(src, params.volume, [&](const std::string& user_key, const int vol) {
        allocate[user_key] = std::max(0, vol);
      });
      for (const auto& user_key : params.user_key_list) {
        auto iter = allocate.find(user_key);
        if (iter == allocate.end()) {
          ret->push_back(0);
        } else {
          ret->push_back(iter->second);
        }
      }
      break;
    }
    default: break;
  }
  return;
}

void VolumeSplitInstructionImpl::SplitCloseVolume(const VolumeSplitParams& params, std::vector<int>* ret) {
  if (params.split_offset == SplitOffset::kOpen && !params.is_swap)
    return;
  std::map<std::string, int> avail_volumes;
  GetActualPositionVolume(params, &avail_volumes, params);
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kBaseRatioRatio: {
      for (const auto& user_key : params.user_key_list) {
        FCASSERT(avail_volumes.find(user_key) != avail_volumes.end());
        int vol = params.volume;
        auto it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
        if (it != VolumeSplitInstruction::GetVolumeRatioMap().end()) {
          if (it->second.find("default") == it->second.end()) {
            auto t = VolumeSplitInstruction::GetVolumeRatioMap();
            t[user_key]["default"] = 1.0;
            VolumeSplitInstruction::SetVolumeRatioMap(t);
            it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
          }
          auto t = GetRatioByProductId(params.ins_node->Latest()->ProductID(), it->second);
          vol = static_cast<int>(std::round(vol * t));
        }
        vol = std::min(vol, avail_volumes[user_key]);
        ret->push_back(vol);
      }
      break;
    }
    case InsertOrderStrategy::kBaseFirstFirst: {
      FCASSERT(avail_volumes.find(params.user_key_list[0]) != avail_volumes.end());
      int first_volume = avail_volumes[params.user_key_list[0]];
      for (const auto& user_key : params.user_key_list) {
        FCASSERT(avail_volumes.find(user_key) != avail_volumes.end());
        int volume = avail_volumes[user_key];
        if (volume > 0) {
          int vol = params.volume;
          if (user_key != params.user_key_list[0] && first_volume > 0) {
            vol = static_cast<int>(std::round(vol * (volume * 1.0 / first_volume)));
          }
          volume = std::min(volume, vol);
        }
        ret->push_back(volume);
      }
      break;
    }
    case InsertOrderStrategy::kTotalRatioAvailable:
    case InsertOrderStrategy::kTotalAvailableAvailable:
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      int total = 0;
      for (const auto& [_, v] : avail_volumes)
        total += v;
      std::map<std::string, int> allocate;
      std::vector<std::pair<std::string, double>> src;
      for (auto& user_key : params.user_key_list) {
        FCASSERT(avail_volumes.find(user_key) != avail_volumes.end());
        double v = 0.0;
        if (total > 0)
          v = avail_volumes[user_key] * 1.0 / total;
        src.push_back(std::make_pair(user_key, v));
      }
      GetBestAllocation(src, params.volume, [&](const std::string& user_key, const int vol) {
        allocate[user_key] = std::min(std::max(0, vol), avail_volumes[user_key]);
      });
      for (const auto& user_key : params.user_key_list) {
        auto iter = allocate.find(user_key);
        if (iter == allocate.end()) {
          ret->push_back(0);
        } else {
          ret->push_back(iter->second);
        }
      }
      break;
    }
    default: break;
  }
}

void VolumeSplitInstructionImpl::CalcOpenAllocateRatio(
  const VolumeSplitParams& params, std::vector<std::pair<std::string, double>>* ret) {
  if (params.split_offset != SplitOffset::kOpen || params.is_swap)
    return;
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kTotalRatioAvailable: {
      for (const auto& user_key : params.user_key_list)
        ret->push_back(std::make_pair(
          user_key, GetVolumeRatio(user_key, params.user_key_list, params.ins_node->Latest()->ProductID())));
      break;
    }
    case InsertOrderStrategy::kTotalAvailableAvailable: {
      double total_available = 0.0;
      for (const auto& user_key : params.user_key_list) {
        double available = 0.0;
        auto account_node =
          TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(future::Account::MakeKey(user_key, 0, "CNY"));
        if (account_node)
          available = account_node->Latest()->available;
        ret->push_back(std::make_pair(user_key, available));
        total_available += available;
      }
      if (total_available > 0) {
        for (auto&& [user_key, available] : *ret) {
          available /= total_available;
        }
      }
      break;
    }
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      double total_balance = 0.0;
      for (auto& user_key : params.user_key_list) {
        double balance = 0.0;
        auto account_node =
          TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(future::Account::MakeKey(user_key, 0, "CNY"));
        if (account_node)
          balance = account_node->Latest()->balance;
        ret->push_back(std::make_pair(user_key, balance));
        total_balance += balance;
      }
      if (total_balance > 0) {
        for (auto&& [user_key, balance] : *ret) {
          balance /= total_balance;
        }
      }
      break;
    }
    default: break;
  }
  return;
}
