OrderInstruction::~OrderInstruction() {
  if (m_insert_order)
    TradeAgent::GetTqApi()->GetCommandTracker()->UntrackCommand(m_insert_order);
}

std::string GetOffsetStr(future::Offset offset) {
  if (offset == future::Offset::kOpen)
    return u8"开仓";
  else if (offset == future::Offset::kClose)
    return u8"平仓";
  else if (offset == future::Offset::kCloseToday)
    return u8"平今";
  else if (offset == future::Offset::kCloseYesterday)
    return u8"平昨";
  return u8"";
}

OrderInstruction::OrderInstruction(TradeAgent* parent, const std::string& user_key,
  std::shared_ptr<md::InstrumentNode> ins_node, future::Direction direction, future::Offset offset,
  future::OrderHedgeFlag hedge, int volume, InsertOrderPrice order_price, int request_id, bool is_swap)
  : m_ins_node(ins_node)
  , m_volume_total(volume)
  , m_order_price(order_price)
  , m_request_id(request_id)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("order_instruction", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("order_instruction", GetAgentIndex()).Clone()) {
  ConvertInsNode();
  m_parent = parent;

  m_logger.With("user_key", user_key)
    .With("symbol", ins_node->Latest()->symbol)
    .With("volume_total", m_volume_total)
    .With("order_price", SerializeToString(m_order_price))
    .With("request_id", m_request_id)
    .Info("Constructor");

  m_insert_order = std::make_shared<future::InsertOrder>(user_key);
  m_insert_order->direction = direction;
  m_insert_order->exchange_id = m_ins_node->Latest()->ExchangeID();
  m_insert_order->hedge_flag = hedge;
  m_insert_order->instrument_id = m_ins_node->Latest()->instrument_id;
  m_insert_order->min_volume = 0;
  m_insert_order->offset = offset;
  m_insert_order->volume = volume;
  m_insert_order->is_swap_order = is_swap;
  m_insert_order->volume_condition = future::OrderVolumeCondition::kAny;

  if (m_ins_node->Snap()->HasCloseToday() && offset == future::Offset::kClose)
    m_insert_order->offset = future::Offset::kCloseYesterday;
  AdjustInsertOrder(m_ins_node, m_order_price, m_insert_order);
  m_new_price = m_insert_order->limit_price;
  auto login_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::LoginContent>(user_key);
  if (!login_node) {
    m_status = AgentStatus::kStopped;
    m_result_msg = u8"fclib: 未找到登录信息";
    return;
  }
  m_trading_day = login_node->Latest()->trading_day;

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit(
    "DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode>, bool) {
      if (m_status == AgentStatus::kStopped && m_ins_view) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        m_ins_view.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });
}

OrderInstruction::OrderInstruction(TradeAgent* parent, const OrderInstructionParamsPack& params_pack,
  std::shared_ptr<md::InstrumentNode> ins_node, const std::string* trading_day)
  : m_ins_node(ins_node)
  , m_volume_total(params_pack.total_volume)
  , m_trading_day(params_pack.trading_day)
  , m_status(params_pack.status)
  , m_result_msg(params_pack.result_msg)
  , m_order_price(params_pack.order_price)
  , m_request_id(params_pack.request_id)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("order_instruction", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("order_instruction", GetAgentIndex()).Clone())
  , m_trade_amount(params_pack.trade_amount) {
  ConvertInsNode();
  m_parent = parent;
  m_instruction_memo = params_pack.memo;

  m_insert_order = std::make_shared<future::InsertOrder>(params_pack.user_key);
  m_insert_order->direction = params_pack.direction;
  m_insert_order->exchange_id = m_ins_node->Latest()->ExchangeID();
  m_insert_order->instrument_id = m_ins_node->Latest()->instrument_id;
  m_insert_order->hedge_flag = params_pack.hedge_flag;
  m_insert_order->min_volume = params_pack.min_volume;
  m_insert_order->offset = params_pack.offset;
  m_insert_order->volume = params_pack.volume;
  m_insert_order->price_type = params_pack.price_type;
  m_insert_order->limit_price = params_pack.limit_price;
  m_insert_order->volume_condition = params_pack.volume_condition;
  m_insert_order->time_condition = params_pack.time_condition;
  m_insert_order->unit_id = params_pack.unit_id;
  m_insert_order->order_id = params_pack.order_id;
  m_insert_order->is_swap_order = params_pack.is_swap;

  m_logger.With("symbol", ins_node->Latest()->symbol)
    .With("params_pack", SerializeToString(params_pack))
    .Info("LoadConstructor ");

  if (m_status == AgentStatus::kPaused || m_insert_order->order_id.empty() || m_status == AgentStatus::kStopped)
    return;
  if (nullptr != trading_day && *trading_day != m_trading_day)
    return;
  // 同一交易日
  auto order_key = future::Order::MakeKey(m_insert_order->user_key, m_insert_order->order_id);
  m_order_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Order>(order_key);
  m_order_nodes_set.insert(m_order_node);
  m_insert_order->order_pointer = m_order_node;
  m_order_view = TradeAgent::GetTqApi()->DataDb()->CreateView<future::Order>(
    [order_key](std::shared_ptr<const future::Order> order) {
      return order->GetKey() == order_key;
    });
  m_order_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<future::OrderNode> order_node, bool is_last) {
      if (!m_order_node) {
        m_order_node = order_node;
        m_order_nodes_set.insert(m_order_node);
      }
      ProcessCancelOrder(order_node);
      if (order_node->Snap()->status == future::OrderStatus::kDead && order_node->Snap()->IsTradeReady()) {
        m_order_view.reset();
        ProcessDeadOrder(order_node);
      }
      OnChildNotify(this);
    });

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit(
    "DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode>, bool) {
      if (m_status == AgentStatus::kStopped && m_ins_view) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        m_ins_view.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });
}

void OrderInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");

  if (m_status != AgentStatus::kPaused)
    return;
  if (m_order_price.order_price_type == InsertOrderPriceType::kBestPrice
    || m_order_price.order_price_type == InsertOrderPriceType::kHangPrice) {
    m_insert_order->limit_price =
      FreezeInsertOrderPrice(m_order_price, m_ins_node, m_insert_order->direction).limit_price;
  }

  m_status = AgentStatus::kStarted;

  OnChildNotify(this);
  // 报单前若调用改价, 则以最新价格报单.
  if (m_need_change) {
    m_insert_order->order_ref = 0;
    m_insert_order->order_id.clear();
    m_insert_order->order_pointer = NodePointer<future::Order>();
    m_insert_order->limit_price = m_new_price;
    AdjustInsertOrder(m_ins_node, m_order_price, m_insert_order);
    m_new_price = m_insert_order->limit_price;
    m_need_change = false;
  }
  m_need_cancel = false;
  InsertOrderAndTrack();
}

