void OrderInstruction::CancelOrder(std::shared_ptr<future::OrderNode> order_node) {
  m_logger.With("order_id", order_node ? order_node->Snap()->order_id : "nan")
    .With("is_canceling", m_is_canceling)
    .Info("CancelOrder");

  if (!order_node || m_is_canceling)
    return;
  auto cmd = std::make_shared<future::CancelOrder>(order_node->Snap()->user_key);
  cmd->order_id = order_node->Snap()->order_id;
  TradeAgent::GetTqApi()->AsyncRequest(cmd);
  m_is_canceling = true;
}

void OrderInstruction::ProcessCancelOrder(std::shared_ptr<future::OrderNode> order_node) {
  if (!order_node) {
    return;
  }
  // 委托已经死亡
  // https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/edit-v2/1553596438
  if (order_node->Latest()->status == future::OrderStatus::kDead) {
    m_is_cancel = false;
    m_need_cancel = false;
    m_is_canceling = false;
    return;
  }
  // 委托未死亡
  if (m_need_cancel && !m_is_canceling) {
    m_is_cancel = false;
    m_need_cancel = false;
    CancelOrder(order_node);
    return;
  }
  if (m_need_cancel && m_is_canceling) {
    m_need_cancel = false;
    m_is_cancel = false;
    return;
  }
  if (!m_need_cancel && m_is_canceling) {
    m_is_cancel = false;
    return;
  }
  if (!m_need_cancel && !m_is_canceling) {
    m_is_cancel = true;
    return;
  }
}

void OrderInstruction::ProcessDeadOrder(std::shared_ptr<future::OrderNode> order_node) {
  // 尝试追单
  if (IsNeedInsertOrder(order_node)) {
    m_need_change = false;
    // 调整报单参数
    m_insert_order->order_ref = 0;
    m_insert_order->order_id.clear();
    m_insert_order->order_pointer = NodePointer<future::Order>();
    m_insert_order->volume = order_node->Snap()->volume_left;
    m_insert_order->limit_price = m_new_price;
    AdjustInsertOrder(m_ins_node, m_order_price, m_insert_order);
    m_new_price = m_insert_order->limit_price;
    // 刷新成交金额
    if (order_node->Latest()->trade_total_volume > 0) {
      FCASSERT(!isnan(order_node->Latest()->trade_price));
      m_trade_amount += order_node->Latest()->trade_price * order_node->Latest()->trade_total_volume;
    }
    m_order_node.reset();
    // 报单
    InsertOrderAndTrack();
  } else {
    m_status = AgentStatus::kStopped;
    m_logger.With("status", static_cast<int>(AgentStatus::kStopped)).Info("ProcessDeadOrder");
    m_result_msg = order_node->Latest()->status_msg;
    if (!order_node->Snap()->exchange_order_id.empty()) {
      m_result_msg.clear();
      if (!m_is_self_cancel && VolumeLeft() != 0
        && m_insert_order->time_condition != future::OrderTimeCondition::kIoc) {
        m_result_msg = u8"fclib: 用户主动撤单";
      }
    }
  }
}

void OrderInstruction::ProcessChangePrice(const ChangePriceParams& params) {
  // 修改限价
  if (params.type == ChangePriceType::kLimitPrice) {
    m_change_price_type = params.type;
    m_need_change = true;
    m_new_price = params.price;
    m_order_price.limit_price = params.price;
    m_order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
    OnChildNotify(this);
    return;
  }

  // 修改市价
  if (params.type == ChangePriceType::kMarketPrice) {
    m_change_price_type = params.type;
    m_need_change = true;
    m_new_price = 0.0;
    m_order_price.limit_price = 0.0;
    m_order_price.order_price_type = InsertOrderPriceType::kMarketPrice;
    OnChildNotify(this);
    return;
  }

  // 修改对价
  if (params.type == ChangePriceType::kBestPrice) {
    m_change_price_type = params.type;

    if (IsPriceChanged()) {
      auto insert_price = (m_insert_order->direction == future::Direction::kBuy) ? m_ins_node->Latest()->GetAskPrice()
                                                                                 : m_ins_node->Latest()->GetBidPrice();
      m_need_change = true;
      m_new_price = insert_price;
      m_order_price.limit_price = insert_price;
      m_order_price.order_price_type = InsertOrderPriceType::kBestPrice;
      OnChildNotify(this);
    }

    if (m_ins_view) {
      return;
    }
    auto symbol = m_ins_node->Latest()->symbol;
    m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
      symbol, false, [symbol](std::shared_ptr<const md::Instrument> ins) {
        return ins->symbol == symbol;
      });
    m_ins_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [this](std::shared_ptr<md::InstrumentNode>, bool is_last) {
        if (m_status == AgentStatus::kStopped) {
          m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
        if (IsPriceChanged()) {
          ChangeOrderPrice(ChangePriceParams(ChangePriceType::kBestPrice), m_request_id);
        }
      });
  }
}

bool OrderInstruction::IsNeedInsertOrder(std::shared_ptr<future::OrderNode> order_node) {
  m_logger.With("status", static_cast<int>(m_status))
    .With("order_status", static_cast<int>(order_node->Snap()->status))
    .With("trade_ready", order_node->Snap()->IsTradeReady())
    .With("volume_left", order_node->Snap()->volume_left)
    .With("need_change", m_need_change)
    .Debug("IsNeedInsertOrder");

  // 已停止不追单
  if (m_status == AgentStatus::kStopped) {
    return false;
  }
  // 委托未死亡或未就绪不追单
  if (order_node->Snap()->status != future::OrderStatus::kDead || !order_node->Snap()->IsTradeReady()) {
    return false;
  }
  // 剩余手数为 0 不追单
  if (order_node->Snap()->volume_left <= 0) {
    return false;
  }
  // 不用改单不追单
  if (!m_need_change) {
    return false;
  }
  m_logger.With("need_insert", "true").Info("IsNeedInsertOrder");
  return true;
}

void OrderInstruction::InsertOrderAndTrack() {
  m_insert_order->request_id = m_request_id;

  TradeAgent::GetTqApi()->AsyncRequest(m_insert_order, [this](std::shared_ptr<future::InsertOrder> cmd) {
    if (cmd->status != UserCommand::Status::kFinished) {
      return;
    }
    m_logger.With("result_code", cmd->result_code).With("result_msg", cmd->result_msg).Info("AsyncRequest");

    if (cmd->result_code != 0) {
      m_status = AgentStatus::kStopped;
      m_result_msg = cmd->result_msg;
      if (m_result_msg.empty())
        m_result_msg = u8"fclib: 报单指令报单错误";
      OnChildNotify(this);
      return;
    }
    if (m_order_node || cmd->order_id.empty()) {
      return;
    }

    // 获取委托单
    auto order_key = future::Order::MakeKey(cmd->user_key, cmd->order_id);
    m_order_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Order>(order_key);
    m_order_nodes_set.insert(m_order_node);
    if (!m_order_node) {
      m_status = AgentStatus::kStopped;
      m_result_msg = u8"fclib: 未找到对应委托单";

      m_logger.With("status", static_cast<int>(m_status)).With("result_msg", m_result_msg).Info("InsertOrderAndTrack");

      OnChildNotify(this);
      return;
    }
    // 处理撤单相关参数
    ProcessCancelOrder(m_order_node);
    // 处理死亡委托单
    if (m_order_node->Snap()->status == future::OrderStatus::kDead && m_order_node->Snap()->IsTradeReady()) {
      ProcessDeadOrder(m_order_node);
      OnChildNotify(this);
      return;
    }

    // 跟踪委托后续变化
    m_order_view = TradeAgent::GetTqApi()->DataDb()->CreateView<future::Order>(
      [order_key](std::shared_ptr<const future::Order> order) {
        return order->GetKey() == order_key;
      });
    m_order_view->AfterCommit(std::to_string(reinterpret_cast<int64_t>(this)),
      [=](std::shared_ptr<future::OrderNode> order_node, bool is_last) {
        ProcessCancelOrder(order_node);
        if (order_node->Snap()->status == future::OrderStatus::kDead && order_node->Snap()->IsTradeReady()) {
          m_order_view.reset();
          ProcessDeadOrder(order_node);
        }
        OnChildNotify(this);
      });

    // 停止需要撤单
    if (m_is_stopping) {
      CancelOrder(m_order_node);
    }
    OnChildNotify(this);
  });

  m_logger.With("order_id", m_insert_order->order_id).With("request_id", m_request_id).Info("InsertOrderAndTrack");
}

void OrderInstruction::ConvertInsNode() {
  if (m_ins_node->Latest()->ProductClass() != md::ProductClass::kCont) {
    return;
  }
  auto main_node = m_ins_node->Latest()->instrument_base->underlying_pointer;
  FCASSERT(main_node);
  m_ins_node = main_node;
}

bool OrderInstruction::IsPriceChanged() {
  auto insert_price = (m_insert_order->direction == future::Direction::kBuy) ? m_ins_node->Latest()->GetAskPrice()
                                                                             : m_ins_node->Latest()->GetBidPrice();
  if (fabs(insert_price - m_insert_order->limit_price) > 1e-5) {
    return true;
  }
  return false;
}

void OrderInstruction::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");

  if (m_status == AgentStatus::kPaused) {
    m_status = AgentStatus::kStopped;
    OnChildNotify(this);
    return;
  }
  if (m_status != AgentStatus::kStarted) {
    return;
  }
  m_is_self_cancel = true;
  if (m_order_node) {
    CancelOrder(m_order_node);
  } else {
    m_is_stopping = true;
  }
}

void OrderInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");
  Run();
}

void OrderInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");
}

