void OrderInstruction::AdjustInsertOrder(const std::shared_ptr<md::InstrumentNode>& ins_node, InsertOrderPrice& price,
  std::shared_ptr<future::InsertOrder> insert_order) {
  // 模拟市价
  if (price.order_price_type == InsertOrderPriceType::kMarketPrice && s_sim_market_order
    && ins_node->Latest()->instrument_base->max_market_order_volume == 0) {
    if (insert_order->direction == future::Direction::kBuy)
      price = InsertOrderPrice(ins_node->Latest()->upper_limit, AdvancedLimitPrice::kVolumeFak);
    else
      price = InsertOrderPrice(ins_node->Latest()->lower_limit, AdvancedLimitPrice::kVolumeFak);
  }
  if (price.order_price_type == InsertOrderPriceType::kMarketPrice) {
    insert_order->limit_price = 0.0;
    // 中金所高级市价报单
    if (ins_node->Latest()->ExchangeID() == "CFFEX") {
      if (s_advance_market_price == AdvancedMarketPrice::kBestLimit) {
        insert_order->price_type = future::PriceType::kBest;
        insert_order->time_condition = future::OrderTimeCondition::kGfd;
      } else if (s_advance_market_price == AdvancedMarketPrice::kFive) {
        insert_order->price_type = future::PriceType::kFiveLevel;
        insert_order->time_condition = future::OrderTimeCondition::kIoc;
      } else if (s_advance_market_price == AdvancedMarketPrice::kFiveLimit) {
        insert_order->price_type = future::PriceType::kFiveLevel;
        insert_order->time_condition = future::OrderTimeCondition::kGfd;
      } else {
        insert_order->price_type = future::PriceType::kBest;
        insert_order->time_condition = future::OrderTimeCondition::kIoc;
      }
    } else {
      // 非中金所, 市价报单
      insert_order->price_type = future::PriceType::kAny;
      insert_order->time_condition = future::OrderTimeCondition::kIoc;
    }
  } else {
    // 限价报单
    insert_order->price_type = future::PriceType::kLimit;
    if (price.advanced_limit == AdvancedLimitPrice::kVolumeFak) {
      insert_order->time_condition = future::OrderTimeCondition::kIoc;
    } else if (price.advanced_limit == AdvancedLimitPrice::kVolumeFok) {
      insert_order->time_condition = future::OrderTimeCondition::kIoc;
      insert_order->volume_condition = future::OrderVolumeCondition::kAll;
    } else if (price.advanced_limit == AdvancedLimitPrice::kVolumeGis) {
      insert_order->time_condition = future::OrderTimeCondition::kGfs;
    } else {
      insert_order->time_condition = future::OrderTimeCondition::kGfd;
    }
    // 锁定价格
    insert_order->limit_price = FreezeInsertOrderPrice(price, ins_node, insert_order->direction).limit_price;
  }
}

InsertOrderPrice OrderInstruction::FreezeInsertOrderPrice(const InsertOrderPrice& order_price,
  const std::shared_ptr<md::InstrumentNode>& ins_node, const future::Direction& direction) {
  if (order_price.order_price_type == InsertOrderPriceType::kMarketPrice
    || order_price.order_price_type == InsertOrderPriceType::kLimitPrice) {
    return order_price;
  } else {
    InsertOrderPrice ret = order_price;
    ret.order_price_type = InsertOrderPriceType::kLimitPrice;
    bool buy = (direction == future::Direction::kBuy);
    double price_over = order_price.price_over * ins_node->Latest()->PriceTick() * (buy ? 1 : -1);
    if (order_price.order_price_type == InsertOrderPriceType::kLastPrice) {
      ret.limit_price = ins_node->Latest()->last_price;
      ret.limit_price += price_over;
    } else if (order_price.order_price_type == InsertOrderPriceType::kBestPrice) {
      ret.limit_price = buy ? ins_node->Latest()->GetAskPrice() : ins_node->Latest()->GetBidPrice();
      ret.limit_price += price_over;
    } else if (order_price.order_price_type == InsertOrderPriceType::kHangPrice) {
      ret.limit_price = buy ? ins_node->Latest()->GetBidPrice() : ins_node->Latest()->GetAskPrice();
      ret.limit_price += price_over;
    }
    if (ret.limit_price > ins_node->Latest()->upper_limit) {
      ret.limit_price = ins_node->Latest()->upper_limit;
    }
    if (ret.limit_price < ins_node->Latest()->lower_limit) {
      ret.limit_price = ins_node->Latest()->lower_limit;
    }
    return ret;
  }
}

void OrderInstruction::ChangeOrderPrice(const ChangePriceParams& params, int request_id) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (request_id != 0)
    m_request_id = request_id;
  m_logger.With("request_id", 0)
    .With("price", params.price)
    .With("type", static_cast<int>(params.type))
    .Info("ChangeOrderPrice");

  // 市价不可以再次改价
  if (m_change_price_type == ChangePriceType::kMarketPrice) {
    return;
  }
  // 对价只能改对价
  if (m_change_price_type == ChangePriceType::kBestPrice && params.type != ChangePriceType::kBestPrice) {
    return;
  }
  // 限价价格未发生变化, 不改价
  if (m_change_price_type == ChangePriceType::kLimitPrice && params.type == m_change_price_type
    && (fabs(params.price - m_new_price) < 1e-5)) {
    return;
  }

  // 如果是对价改价, 且价格未变化, 无任何操作
  if (!(params.type == ChangePriceType::kBestPrice && !IsPriceChanged())) {
    // 尝试撤单
    if (m_is_cancel && m_order_node) {
      CancelOrder(m_order_node);
      m_is_cancel = false;
      m_need_cancel = false;
      m_is_canceling = true;
    } else {
      m_need_cancel = true;
    }
  }

  // 修改报单价格和报单请求
  ProcessChangePrice(params);
}

