std::shared_ptr<VolumeSplitInstruction> VolumeSplitInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&)> load_factory) {
  auto pack = SerializeToVar<VolumeSplitInstructionPack>(params);
  auto ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(pack.symbol);
  if (nullptr == ins_node)
    return nullptr;
  pack.params.ins_node = ins_node;
  std::shared_ptr<VolumeSplitInstruction> instruction;
  if (pack.params.split_offset == SplitOffset::kAuto) {
    instruction = std::make_shared<AutoVolumeSplitInstructionImpl>(parent, pack);
  } else {
    instruction = std::make_shared<VolumeSplitInstructionImpl>(parent, pack);
  }
  auto child = load_factory(instruction.get(), pack.child);
  if (!child)
    return nullptr;
  instruction->m_child = child;
  return instruction;
}

