VolumeSplitInstruction::VolumeSplitInstruction(TradeAgent* parent, const VolumeSplitParams& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : m_params(params)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("volume_split", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("volume_split", GetAgentIndex()).Clone()) {
  m_parent = parent;
  FCASSERT(m_params.ins_node);

  m_logger.With("params", SerializeToString(params)).Info("Constructor");

  if (m_params.is_swap)
    FCASSERT(m_params.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine);
  if (m_params.ins_node->Latest()->HasCloseToday() && m_params.split_offset == SplitOffset::kClose)
    m_params.split_offset = SplitOffset::kCloseBoth;
  m_volume_plan.clear();
  VolumeSplitInstruction::SplitVolume(m_params, &m_volume_plan);
  if (child_factory)
    m_child = child_factory(this, m_volume_plan);
}

VolumeSplitInstruction::VolumeSplitInstruction(TradeAgent* parent, const VolumeSplitParams& params,
  const std::vector<int>& volume_plan,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : m_params(params)
  , m_volume_plan(volume_plan)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("volume_split", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("volume_split", GetAgentIndex()).Clone()) {
  m_parent = parent;
  FCASSERT(m_params.ins_node);
  FCASSERT(!m_volume_plan.empty());

  m_logger.With("volume_plan", SerializeToString(m_volume_plan))
    .With("params", SerializeToString(params))
    .Info("Constructor");

  if (m_params.is_swap)
    FCASSERT(m_params.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine);
  if (m_params.ins_node->Latest()->HasCloseToday() && m_params.split_offset == SplitOffset::kClose)
    m_params.split_offset = SplitOffset::kCloseBoth;
  // 调整手数
  if (m_params.split_offset != SplitOffset::kAuto) {
    VolumeSplitInstructionImpl::RegulateVolume(m_params, &m_volume_plan);
  }
  FCASSERT(params.user_key_list.size() == m_volume_plan.size());
  // 构造子指令
  if (child_factory)
    m_child = child_factory(this, m_volume_plan);
}

