  const std::string& user_key, const future::OrderHedgeFlag& hedge, const future::Direction& direction);

double CalcFee(double price, double amount, double volume) {
  return (isnan(price) ? 0 : price) * (isnan(amount) ? 0 : amount) + (isnan(volume) ? 0 : volume);
}
bool CloseTodayBeforeYesterDay(std::shared_ptr<md::InstrumentNode> ins_node, const std::string& user_key) {
  // 取费率
  // 取不到默认认为平今手续费低
  if (nullptr == TradeAgent::GetTqApi()) {
    return true;
  }
  auto rate_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Rate>(
    future::Rate::MakeKey(user_key, ins_node->Latest()->instrument_id));
  if (nullptr == rate_node) {
    return true;
  }
  bool today_v = isnan(rate_node->Latest()->commission_rate_close_today.volume_rate);
  bool today_a = isnan(rate_node->Latest()->commission_rate_close_today.amount_rate);
  bool yesterday_v = isnan(rate_node->Latest()->commission_rate_close.volume_rate);
  bool yesterday_a = isnan(rate_node->Latest()->commission_rate_close.amount_rate);
  bool is_last_price = isnan(ins_node->Latest()->last_price);

  // 仅按成交量计算手续费
  bool volume_only = !today_v && !yesterday_v && today_a && yesterday_a;
  // 仅按成交额计算手续费
  bool amount_only = !today_a && !yesterday_a && today_v && yesterday_v && !is_last_price;
  // 成交量和成交额都有
  bool both_have = !today_a && !today_v && !yesterday_a && !yesterday_v && !is_last_price;

  if (!volume_only && !amount_only && !both_have) {
    return true;
  }

  auto const& price = ins_node->Latest()->last_price;

  auto today = CalcFee(price, rate_node->Latest()->commission_rate_close_today.amount_rate,
    rate_node->Latest()->commission_rate_close_today.volume_rate);

  auto yesterday = CalcFee(price, rate_node->Latest()->commission_rate_close.amount_rate,
    rate_node->Latest()->commission_rate_close.volume_rate);

  // 费率相同默认平今
  if (abs(today - yesterday) < 1e-6)
    return true;
  // 平今手续费低 则返回true 否则返回false
  return today < yesterday;
}

