  const future::OrderHedgeFlag& hedge, const InsertOrderPrice& order_price, bool is_swap, int volume, int request_id)
  : m_ins_node(ins_node)
  , m_split_offset(split_offset)
  , m_direction(direction)
  , m_hedge(hedge)
  , m_order_price(order_price)
  , m_is_swap(is_swap)
  , m_user_key(user_key)
  , m_volume(volume)
  , m_request_id(request_id)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("auto_open_close", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("auto_open_close", GetAgentIndex()).Clone()) {
  m_parent = parent;
  FCASSERT(m_ins_node);

  m_logger.With("symbol", m_ins_node->Latest()->symbol)
    .With("split_offset", static_cast<int>(m_split_offset))
    .With("direction", static_cast<int>(m_direction))
    .With("hedge", static_cast<int>(m_hedge))
    .With("order_price", SerializeToString(m_order_price))
    .With("is_swap", static_cast<int>(m_is_swap))
    .With("user_key", m_user_key)
    .With("volume", m_volume)
    .With("request_id", m_request_id)
    .Info("Constructor");

  if (m_volume <= 0) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 自动开平手数不可小于0");
    return;
  }
  RebuildPlan();
}

AutoOpenCloseInstruction::AutoOpenCloseInstruction(TradeAgent* parent, const AutoOpenCloseInstructionPack& pack)
  : m_ins_node(pack.ins_node)
  , m_split_offset(pack.split_offset)
  , m_direction(pack.direction)
  , m_hedge(pack.hedge)
  , m_order_price(pack.order_price)
  , m_is_swap(pack.is_swap)
  , m_user_key(pack.user_key)
  , m_volume(pack.volume)
  , m_request_id(pack.request_id)
  , m_msg(pack.msg)
  , m_status(pack.status)
  , m_volume_open(pack.volume_open)
  , m_volume_close(pack.volume_close)
  , m_volume_close_his(pack.volume_close_his)
  , m_volume_close_today(pack.volume_close_today)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("auto_open_close", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("auto_open_close", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_instruction_memo = pack.memo;

  m_logger.With("params_pack", SerializeToString(pack)).Info("LoadConstructor");

  m_childs.clear();
  for (const auto& child : pack.childs) {
    auto c = OrderInstruction::LoadInstruction(this, child);
    if (nullptr != c)
      m_childs.push_back(c);
  }
  if (!m_childs.empty())
    FCASSERT(m_status != AgentStatus::kPaused);
  if (m_status == AgentStatus::kPaused)
    RebuildPlan();
}

AutoOpenCloseInstruction::~AutoOpenCloseInstruction() {}

void AutoOpenCloseInstruction::OnChildNotify(TradeAgent* child) {
  m_logger.With("child", reinterpret_cast<int64_t>(child)).Info("OnChildNotify");
  // 把TradeAgent转换成OrderInstruction
  auto order_instruction = dynamic_cast<OrderInstruction*>(child);
  if (!order_instruction) {
    FCASSERT(false && "AutoOpen : No order_instruction");
    return;
  }
  auto order_node = order_instruction->GetOrderNode();

  if (order_node) {
    // 第一次回包
    bool is_first_received = m_received_order_set.insert(order_instruction).second;

    m_logger.With("is_first_received", static_cast<int>(is_first_received)).Info("OnChildNotify: is_first_rec");

    if (is_first_received && m_split_offset == SplitOffset::kAuto
      && order_node->Snap()->offset != fclib::future::Offset::kOpen) {
      std::vector<std::string> ins_keys;
      std::string hedge = (m_hedge == future::OrderHedgeFlag::kSpeculation) ? "spec" : "hedge";
      if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
        auto leg1 = m_ins_node->Latest()->instrument_base->leg1_pointer;
        auto leg2 = m_ins_node->Latest()->instrument_base->leg2_pointer;
        ins_keys = {m_user_key + leg1->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge,
          m_user_key + leg2->GetKey() + (m_direction == future::Direction::kBuy ? "sell" : "buy") + hedge};
      } else {
        ins_keys = {
          m_user_key + m_ins_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge};
      }
      for (auto ins_key : ins_keys) {
        // 解冻
        // 上期所的平今回来是平今，但是平昨有可能是Close或者CloseYesterday
        if (order_node->Snap()->offset == fclib::future::Offset::kClose
          && !(order_instruction->GetInsertOrder()[0]->exchange_id == "SHFE"
            || order_instruction->GetInsertOrder()[0]->exchange_id == "INE")) {
          s_frozen_volume[ins_key] -= order_node->Latest()->volume_orign;
          if (s_frozen_volume[ins_key] < 0) {
            s_frozen_volume[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        } else if (order_node->Snap()->offset == fclib::future::Offset::kCloseToday) {
          s_frozen_volume_today[ins_key] -= order_node->Latest()->volume_orign;
          if (s_frozen_volume_today[ins_key] < 0) {
            s_frozen_volume_today[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        } else {
          s_frozen_volume_his[ins_key] -= order_node->Latest()->volume_orign;
          if (s_frozen_volume_his[ins_key] < 0) {
            s_frozen_volume_his[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        }
        m_logger.With("ins_key", ins_key)
          .With("volume", order_node->Latest()->volume_orign)
          .With("offset", static_cast<int>(order_node->Snap()->offset))
          .Info("OnChildNotify: Decrease frozen volume");
      }
    }
  } else {
    m_logger.With("status", static_cast<int>(order_instruction->GetStatus()))
      .With("msg", order_instruction->GetMsg())
      .Info("OnChildNotify: No order_node");
    // 没有order_node 状态为停止且msg不为空 说明错单
    if (order_instruction->GetStatus() == AgentStatus::kStopped && !order_instruction->GetMsg().empty()
      && order_instruction->GetInsertOrder()[0]->offset != fclib::future::Offset::kOpen
      && m_split_offset == SplitOffset::kAuto) {
      std::vector<std::string> ins_keys;
      std::string hedge = (m_hedge == future::OrderHedgeFlag::kSpeculation) ? "spec" : "hedge";
      if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
        auto leg1 = m_ins_node->Latest()->instrument_base->leg1_pointer;
        auto leg2 = m_ins_node->Latest()->instrument_base->leg2_pointer;
        ins_keys = {m_user_key + leg1->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge,
          m_user_key + leg2->GetKey() + (m_direction == future::Direction::kBuy ? "sell" : "buy") + hedge};
      } else {
        ins_keys = {
          m_user_key + m_ins_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge};
      }
      // 解冻
      for (auto ins_key : ins_keys) {
        auto offset = order_instruction->GetInsertOrder()[0]->offset;
        if (offset == fclib::future::Offset::kClose
          && !(order_instruction->GetInsertOrder()[0]->exchange_id == "SHFE"
            || order_instruction->GetInsertOrder()[0]->exchange_id == "INE")) {
          s_frozen_volume[ins_key] -= order_instruction->GetInsertOrder()[0]->volume;
          if (s_frozen_volume[ins_key] < 0) {
            s_frozen_volume[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        } else if (offset == fclib::future::Offset::kCloseToday) {
          s_frozen_volume_today[ins_key] -= order_instruction->GetInsertOrder()[0]->volume;
          if (s_frozen_volume_today[ins_key] < 0) {
            s_frozen_volume_today[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        } else {
          s_frozen_volume_his[ins_key] -= order_instruction->GetInsertOrder()[0]->volume;
          if (s_frozen_volume_his[ins_key] < 0) {
            s_frozen_volume_his[ins_key] = 0;
            FCASSERT(false && "AutoOpen: Decrease less than zero");
          }
        }
        m_logger.With("ins_key", ins_key)
          .With("volume", order_instruction->GetInsertOrder()[0]->volume)
          .With("offset", static_cast<int>(order_instruction->GetInsertOrder()[0]->offset))
          .Info("OnChildNotify: Decrease frozen volume Error");
      }
    }
  }

  UpdateStatus(false);
  if (m_parent)
    m_parent->OnChildNotify(this);
}

bool AutoOpenCloseInstruction::VisibleInViewInstruction() const {
  return false;
}

std::vector<std::shared_ptr<TradeInstruction>> AutoOpenCloseInstruction::GetChildInstructions() {
  std::vector<std::shared_ptr<TradeInstruction>> ret;
  for (const auto& child : m_childs) {
    if (child)
      ret.push_back(child);
  }
  return ret;
}

void AutoOpenCloseInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");

  if (m_status != AgentStatus::kPaused)
    return;

  RebuildPlan();
  if (!AddChild())
    return;

  for (const auto& child : m_childs) {
    if (!child)
      continue;
    auto insert_order = child->GetInsertOrder();
    // 非自动开平平仓单正常处理
    if (!(insert_order[0]->offset != fclib::future::Offset::kOpen && m_split_offset == SplitOffset::kAuto)) {
      child->Run();
      continue;
    }
    // 自动开平平仓单下单前需上锁
    std::vector<std::string> ins_keys;
    // 如果是组合则组合的两腿分别处理
    std::string hedge = (m_hedge == future::OrderHedgeFlag::kSpeculation) ? "spec" : "hedge";
    if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
      auto leg1 = m_ins_node->Latest()->instrument_base->leg1_pointer;
      auto leg2 = m_ins_node->Latest()->instrument_base->leg2_pointer;

      auto ins_key1 = m_user_key + leg1->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge;
      auto ins_key2 = m_user_key + leg2->GetKey() + (m_direction == future::Direction::kBuy ? "sell" : "buy") + hedge;
      ins_keys.push_back(ins_key1);
      ins_keys.push_back(ins_key2);
    } else {
      ins_keys.push_back(
        m_user_key + m_ins_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge);
    }
    for (auto ins_key : ins_keys) {
      // 上期所/能源所 特殊处理
      if (insert_order[0]->exchange_id == "SHFE" || insert_order[0]->exchange_id == "INE") {
        if (insert_order[0]->offset == fclib::future::Offset::kCloseToday) {
          s_frozen_volume_today[ins_key] += insert_order[0]->volume;
        } else {
          s_frozen_volume_his[ins_key] += insert_order[0]->volume;
        }
      } else {
        s_frozen_volume[ins_key] += insert_order[0]->volume;
      }
      m_logger.With("ins_key", ins_key)
        .With("volume", insert_order[0]->volume)
        .With("offset", static_cast<int>(insert_order[0]->offset))
        .Info("Run: Add frozen volume");
    }
    child->Run();
  }
  ChangeStatus(true, AgentStatus::kStarted, "");
}

void AutoOpenCloseInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");
  Run();
}

// 自动开平不支持暂停
void AutoOpenCloseInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");
}

void AutoOpenCloseInstruction::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");

  if (m_status != AgentStatus::kStarted)
    return;

  for (const auto& child : m_childs) {
    if (child)
      child->Stop();
  }
}

