std::string AutoOpenCloseInstruction::SaveInstruction() {
  AutoOpenCloseInstructionPack pack;
  pack.direction = m_direction;
  pack.hedge = m_hedge;
  pack.order_price = m_order_price;
  pack.is_swap = m_is_swap;
  pack.split_offset = m_split_offset;
  pack.symbol = m_ins_node->Latest()->symbol;
  pack.user_key = m_user_key;
  pack.volume = m_volume;
  pack.request_id = m_request_id;
  pack.volume_open = m_volume_open;
  pack.volume_close = m_volume_close;
  pack.volume_close_his = m_volume_close_his;
  pack.volume_close_today = m_volume_close_today;
  pack.status = m_status;
  pack.msg = m_msg;
  pack.memo = m_instruction_memo;
  for (const auto& child : m_childs) {
    if (child)
      pack.childs.push_back(child->SaveInstruction());
  }
  return SerializeToString(pack);
}

std::shared_ptr<AutoOpenCloseInstruction> AutoOpenCloseInstruction::LoadInstruction(
  TradeAgent* parent, const std::string& params) {
  auto pack = SerializeToVar<AutoOpenCloseInstructionPack>(params);
  auto ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(pack.symbol);
  if (nullptr == ins_node)
    return nullptr;
  pack.ins_node = ins_node;
  return std::make_shared<AutoOpenCloseInstruction>(parent, pack);
}

void AutoOpenCloseInstruction::RebuildAutoOpenClosePlan() {
  // 自动开平和官方移仓不可同时使用
  FCASSERT(!m_is_swap);
  auto subpos = GetNegativeSubPosition(m_ins_node, m_user_key, m_hedge, m_direction);
  int volume_avail = 0;
  std::string hedge = (m_hedge == future::OrderHedgeFlag::kSpeculation) ? "spec" : "hedge";
  std::string ins_key =
    m_user_key + m_ins_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge;
  // TODO(TanYan): etf 期权组合需要特殊处理
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
    std::shared_ptr<md::InstrumentNode> leg1_node = m_ins_node->Latest()->instrument_base->leg1_pointer;
    std::shared_ptr<md::InstrumentNode> leg2_node = m_ins_node->Latest()->instrument_base->leg2_pointer;
    auto subpos1 = GetNegativeSubPosition(leg1_node, m_user_key, m_hedge, m_direction);
    auto subpos2 = GetNegativeSubPosition(leg2_node, m_user_key, m_hedge, NegativeDir(m_direction));
    if (subpos1 && subpos2) {
      auto sub_key1 =
        m_user_key + leg1_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell") + hedge;
      auto sub_key2 =
        m_user_key + leg2_node->GetKey() + (m_direction == future::Direction::kBuy ? "sell" : "buy") + hedge;

      FCASSERT(s_frozen_volume[sub_key1] >= 0 && s_frozen_volume[sub_key2] >= 0);
      // 上期所不存在官方组合，无需特殊判断
      if (m_ins_node->Latest()->ExchangeID() != "CZCE") {
        volume_avail = std::min(
          subpos1->VolumeAvail() - s_frozen_volume[sub_key1], subpos2->VolumeAvail() - s_frozen_volume[sub_key2]);
      } else {
        // 郑商所特殊处理，投机和套保一起平仓
        auto sub_key1_neg = m_user_key + leg1_node->GetKey() + (m_direction == future::Direction::kBuy ? "buy" : "sell")
          + (hedge == "hedge" ? "spec" : "hedge");
        auto sub_key2_neg = m_user_key + leg2_node->GetKey() + (m_direction == future::Direction::kBuy ? "sell" : "buy")
          + (hedge == "hedge" ? "spec" : "hedge");

        FCASSERT(s_frozen_volume[sub_key1] >= 0 && s_frozen_volume[sub_key2] >= 0 && s_frozen_volume[sub_key1_neg] >= 0
          && s_frozen_volume[sub_key2_neg] >= 0);

        auto leg1_volume = GetAllNegativePostionVolume(leg1_node, m_user_key, m_direction);
        auto leg2_volume = GetAllNegativePostionVolume(leg2_node, m_user_key, NegativeDir(m_direction));

        m_logger.With("leg1_volume", leg1_volume)
          .With("leg2_volume", leg2_volume)
          .With("s_frozen_volume_leg1", s_frozen_volume[sub_key1])
          .With("s_frozen_volume_leg2", s_frozen_volume[sub_key2])
          .With("s_frozen_volume_leg1_neg", s_frozen_volume[sub_key1_neg])
          .With("s_frozen_volume_leg2_neg", s_frozen_volume[sub_key2_neg])
          .Info("RebuildAutoOpenClosePlan_CZCE_Comb");
        volume_avail = std::min(leg1_volume - s_frozen_volume[sub_key1] - s_frozen_volume[sub_key1_neg],
          leg2_volume - s_frozen_volume[sub_key2] - s_frozen_volume[sub_key2_neg]);
      }
    }
  } else {
    if (subpos) {
      if (!m_ins_node->Latest()->HasCloseToday()) {
        FCASSERT(s_frozen_volume[ins_key] >= 0);
        // 如果是郑商所，特殊处理
        if (m_ins_node->Latest()->ExchangeID() == "CZCE") {
          auto ins_key_neg = m_user_key + m_ins_node->GetKey()
            + (m_direction == future::Direction::kBuy ? "buy" : "sell") + (hedge == "hedge" ? "spec" : "hedge");
          FCASSERT(s_frozen_volume[ins_key_neg] >= 0);
          auto volume = GetAllNegativePostionVolume(m_ins_node, m_user_key, m_direction);
          m_logger.With("volume", volume)
            .With("s_frozen_volume_neg", s_frozen_volume[ins_key_neg])
            .Info("RebuildAutoOpenClosePlan_CZCE");
          volume_avail = volume - s_frozen_volume[ins_key] - s_frozen_volume[ins_key_neg];
        } else {
          volume_avail = subpos->VolumeAvail() - s_frozen_volume[ins_key];
        }
      } else {
        FCASSERT(s_frozen_volume_his[ins_key] >= 0 && s_frozen_volume_today[ins_key] >= 0);
        volume_avail = subpos->VolumeAvail() - s_frozen_volume_his[ins_key] - s_frozen_volume_today[ins_key];
      }
    }
  }
  m_logger.With("volume_avail", volume_avail)
    .With("s_frozen_volume", s_frozen_volume[ins_key])
    .With("s_frozen_volume_his", s_frozen_volume_his[ins_key])
    .With("s_frozen_volume_today", s_frozen_volume_today[ins_key])
    .Info("RebuildAutoOpenClosePlan");
  if (volume_avail <= 0) {
    m_volume_close = m_volume_close_his = m_volume_close_today = 0;
    m_volume_open = m_volume;
    return;
  }
  auto close_volume = std::min(volume_avail, m_volume);
  m_volume_close = close_volume;
  // 如果是中金所，且今天有开仓(有今仓), 且开启了股指期货禁止平今模式, 则不平仓, 只开仓
  if (m_ins_node->Latest()->ExchangeID() == "CFFEX" && subpos->volume_today > 0
    && TradeInstruction::GetDisableStockCloseToday()) {
    close_volume = 0;
    m_volume_close = 0;
  }

  m_volume_open = m_volume - close_volume;
  // 如果是上期所
  if (m_ins_node->Latest()->HasCloseToday()) {
    m_volume_close = 0;
    // 谁的手续费低先平谁
    if (CloseTodayBeforeYesterDay(m_ins_node, m_user_key)) {
      m_volume_close_today =
        std::min(subpos->volume_today - subpos->volume_today_frozen - s_frozen_volume_today[ins_key], close_volume);
      m_volume_close_his = close_volume - m_volume_close_today;
      if (m_volume_close_today < 0
        || m_volume_close_his > subpos->volume_his - subpos->volume_his_frozen - s_frozen_volume_his[ins_key]) {
        // 手数算出负数，全部反开
        m_volume_close_today = 0;
        m_volume_close_his = 0;
        m_volume_open = m_volume;
        FCASSERT(false && "AutoOpen: m_volume_close_today < 0");
      }
    } else {
      m_volume_close_his =
        std::min(subpos->volume_his - subpos->volume_his_frozen - s_frozen_volume_his[ins_key], close_volume);
      m_volume_close_today = close_volume - m_volume_close_his;
      if (m_volume_close_his < 0
        || m_volume_close_today > subpos->volume_today - subpos->volume_today_frozen - s_frozen_volume_today[ins_key]) {
        // 手数算出负数，全部反开
        m_volume_close_today = 0;
        m_volume_close_his = 0;
        m_volume_open = m_volume;
        FCASSERT(false && "AutoOpen: m_volume_close_his < 0");
      }
    }
  }
}
int AutoOpenCloseInstruction::GetAllNegativePostionVolume(
  std::shared_ptr<const md::InstrumentNode> ins_node, const std::string& user_key, const future::Direction& direction) {
  auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
    future::Position::MakeKey(user_key, 0, ins_node->Latest()->symbol));
  if (!position_node)
    return 0;
  if (direction == future::Direction::kBuy)
    return position_node->Latest()->subpos_short_spec.VolumeAvail()
      + position_node->Latest()->subpos_short_other.VolumeAvail();
  else
    return position_node->Latest()->subpos_long_spec.VolumeAvail()
      + position_node->Latest()->subpos_long_other.VolumeAvail();
}

void AutoOpenCloseInstruction::RebuildClosePlan() {
  if (m_ins_node->Latest()->HasCloseToday() && m_split_offset == SplitOffset::kClose)
    m_split_offset = SplitOffset::kCloseBoth;
  if (m_split_offset == SplitOffset::kOpen && !m_is_swap) {
    m_volume_close = m_volume_close_his = m_volume_close_today = 0;
    m_volume_open = m_volume;
    return;
  }
  auto direction = m_direction;
  auto ins_node = m_ins_node;
  auto split_offset = m_split_offset;
  bool convert = false;
  // 调整移仓参数
  if (m_ins_node->Latest()->ProductClass() == md::ProductClass::kCombine && m_is_swap) {
    if (m_split_offset == SplitOffset::kOpen) {
      convert = true;
      split_offset = SplitOffset::kClose;
      direction = NegativeDir(m_direction);
      ins_node = m_ins_node->Latest()->instrument_base->leg2_pointer;
      FCASSERT(ins_node);
    } else {
      ins_node = m_ins_node->Latest()->instrument_base->leg1_pointer;
      FCASSERT(ins_node);
    }
  }
  if (split_offset == SplitOffset::kOpen)
    return;
  // 处理组合
  if (ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
    m_volume_open = m_volume_close_his = m_volume_close_today = m_volume_close = 0;
    std::shared_ptr<md::InstrumentNode> ins_node0 = ins_node->Latest()->instrument_base->leg1_pointer;
    std::shared_ptr<md::InstrumentNode> ins_node1 = ins_node->Latest()->instrument_base->leg2_pointer;
    FCASSERT(ins_node0 && ins_node1);
    auto sub0 = GetNegativeSubPosition(ins_node0, m_user_key, m_hedge, direction);
    auto sub1 = GetNegativeSubPosition(ins_node1, m_user_key, m_hedge, NegativeDir(direction));
    if (sub0 && sub1 && sub0->Volume() > 0 && sub1->Volume() > 0) {
      int close_vol0 = sub0->Volume() - sub0->VolumeFrozen();
      int close_vol1 = sub1->Volume() - sub1->VolumeFrozen();
      m_volume_close = std::min(m_volume, std::min(close_vol0, close_vol1));
    }
    return;
  }
  // 处理非组合
  auto subpos = GetNegativeSubPosition(ins_node, m_user_key, m_hedge, direction);
  if (nullptr == subpos) {
    m_volume_close = m_volume_close_his = m_volume_close_today = 0;
    return;
  }
  if (split_offset == SplitOffset::kClose || !ins_node->Latest()->HasCloseToday()) {
    m_volume_open = m_volume_close_his = m_volume_close_today = 0;
    m_volume_close = std::min(m_volume, subpos->VolumeAvail());
    if (m_is_swap && convert)
      std::swap(m_volume_open, m_volume_close);
    return;
  }
  if (split_offset == SplitOffset::kCloseHis) {
    m_volume_open = m_volume_close = m_volume_close_today = 0;
    m_volume_close_his = std::min(m_volume, subpos->volume_his - subpos->volume_his_frozen);
    return;
  }
  if (split_offset == SplitOffset::kCloseToday) {
    m_volume_open = m_volume_close = m_volume_close_his = 0;
    m_volume_close_today = std::min(m_volume, subpos->volume_today - subpos->volume_today_frozen);
    return;
  }
  m_volume_open = m_volume_close = 0;
  auto tmp_volume = std::min(m_volume, subpos->VolumeAvail());
  if (CloseTodayBeforeYesterDay(ins_node, m_user_key)) {
    m_volume_close_today = std::min(subpos->volume_today - subpos->volume_today_frozen, tmp_volume);
    m_volume_close_his = tmp_volume - m_volume_close_today;
  } else {
    m_volume_close_his = std::min(subpos->volume_his - subpos->volume_his_frozen, tmp_volume);
    m_volume_close_today = tmp_volume - m_volume_close_his;
  }
}

bool AutoOpenCloseInstruction::AddChild() {
  m_logger.With("volume", m_volume)
    .With("volume_open", m_volume_open)
    .With("volume_close", m_volume_close)
    .With("volume_close_his", m_volume_close_his)
    .With("volume_close_today", m_volume_close_today)
    .With("status", static_cast<int>(m_status))
    .Info("AddChild");

  if (m_status == AgentStatus::kStarted || m_status == AgentStatus::kStopped)
    return false;
  m_childs.clear();
  if (m_volume_close > 0) {
    auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction, future::Offset::kClose,
      m_hedge, m_volume_close, m_order_price, m_request_id, m_is_swap);
    m_childs.push_back(child);
  }

  if (CloseTodayBeforeYesterDay(m_ins_node, m_user_key)) {
    if (m_volume_close_today > 0) {
      auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction,
        future::Offset::kCloseToday, m_hedge, m_volume_close_today, m_order_price, m_request_id, m_is_swap);
      m_childs.push_back(child);
    }
    if (m_volume_close_his > 0) {
      auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction,
        future::Offset::kCloseYesterday, m_hedge, m_volume_close_his, m_order_price, m_request_id, m_is_swap);
      m_childs.push_back(child);
    }
  } else {
    if (m_volume_close_his > 0) {
      auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction,
        future::Offset::kCloseYesterday, m_hedge, m_volume_close_his, m_order_price, m_request_id, m_is_swap);
      m_childs.push_back(child);
    }
    if (m_volume_close_today > 0) {
      auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction,
        future::Offset::kCloseToday, m_hedge, m_volume_close_today, m_order_price, m_request_id, m_is_swap);
      m_childs.push_back(child);
    }
  }
  if (m_volume_open > 0) {
    auto child = std::make_shared<OrderInstruction>(this, m_user_key, m_ins_node, m_direction, future::Offset::kOpen,
      m_hedge, m_volume_open, m_order_price, m_request_id, m_is_swap);
    m_childs.push_back(child);
  }
  if (m_childs.empty()) {
    ChangeStatus(true, AgentStatus::kStopped, "fclib: 自动开平没有发出任何报单");
    return false;
  }
  UpdateStatus(true);
  return m_status != AgentStatus::kStopped && m_msg.empty();
}

void AutoOpenCloseInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;
  m_msg = msg;
  if (notify && m_parent) {
    m_parent->OnChildNotify(this);
  }
}

void AutoOpenCloseInstruction::UpdateStatus(bool notify) {
  bool stopped = true;
  std::string msg;

  for (const auto& c : m_childs) {
    if (!c)
      continue;
    if (c->GetStatus() != AgentStatus::kStopped)
      stopped = false;
    if (!c->GetMsg().empty()) {
      if (!msg.empty())
        msg += "; ";
      msg += c->GetMsg();
      std::shared_ptr<future::InsertOrder> insert = c->GetInsertOrder()[0];
      std::string suffix = (nullptr == insert) ? "" : insert->order_id;
      if (!suffix.empty())
        msg += ": " + suffix;
    }
  }
  if (stopped)
    ChangeStatus(notify, AgentStatus::kStopped, msg);
}

