void CombOrderRule2::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");
}

void CombOrderRule2::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");
  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;

  // 手动启动, 初始认定为非追单状态
  m_track = false;
  ChangeStatus(true, AgentStatus::kStarted, "");
  InsertOrder();
  // 行情驱动后续下单
  m_calc->SetCallBack("InsertOrder", [this]() {
    if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
      m_calc->CancelCallBack("InsertOrder");
      return;
    }
    InsertOrder();
  });
}

void CombOrderRule2::Pause() {
  m_logger.With("track", m_track).With("status", static_cast<int>(m_status)).Info("Pause");

  if (m_status != AgentStatus::kStarted)
    return;

  // 规则2 追单中不可暂停, 先切为暂停中
  if (m_track) {
    ChangeStatus(true, AgentStatus::kPausing, m_msg);
    return;
  }

  ChangeStatus(true, AgentStatus::kPaused, m_msg);
  m_calc->CancelCallBack("InsertOrder");
}

void CombOrderRule2::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");
}

AgentStatus CombOrderRule2::GetStatus() const {
  return m_status;
}

int CombOrderRule2::VolumeTotal() {
  int ret = 0;
  for (const auto& params : m_comb_params.params) {
    ret += m_volume * params.volume;
  }
  return ret;
}

int CombOrderRule2::VolumeLeft() {
  int ret = 0;
  for (const auto& comb_plan : m_comb_plan) {
    for (const auto& plan : comb_plan) {
      ret += plan.params.volume;
    }
  }
  return ret;
}

double CombOrderRule2::TradeAmount() {
  return m_comb_average_price * (VolumeTotal() - VolumeLeft());
}

