void CombOrderRule2::ChangeOrderPrice(const ChangePriceParams& params, int request_id) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (m_track) {
    m_combo_price_change = params.price;
    return;
  }
  m_insert_params.order_price.limit_price = params.price;
  if (m_status == AgentStatus::kStarted)
    InsertOrder();
}

void CombOrderRule2::OnChildNotify(TradeAgent* child) {
  m_logger.With("child", reinterpret_cast<int64_t>(child)).Info("OnChildNotify");

  UpdateInstruction();

  // 处理暂停中状态
  if (!m_track && m_status == AgentStatus::kPausing) {
    ChangeStatus(true, AgentStatus::kPaused, m_msg);
    m_calc->CancelCallBack("InsertOrder");
  }

  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
  return;
}

