int const CombOrderRule2::GetLeft() {
  if (m_volume == 0) {
    return 0;
  }
  if (m_comb_params.prior_ins_index == -1) {
    return static_cast<int>(m_comb_plan.size()) - m_plan_index - (VolumeLeft() == 0);
  }
  return m_volume - (m_plan_index + (VolumeLeft() == 0)) / 2;
}

