double const CombOrderRule2::GetRealPriceDiff() const {
  if (!m_calc)
    return NAN;
  if (m_insert_params.direction == future::Direction::kBuy)
    return m_calc->GetInstrument()->ask_price[0];
  return m_calc->GetInstrument()->bid_price[0];
}

void CombOrderRule2::InsertOrder() {
  if (m_status == AgentStatus::kPausing && !m_track) {
    return;
  }
  if (m_status == AgentStatus::kPaused || m_status == AgentStatus::kStopped) {
    return;
  }
  // 有且仅有当前 plan 没有正在执行的 instruction 才下单
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    if (nullptr != plan.instruction)
      return;
  }
  if (!IsInTradingTime(m_comb_params.params))
    return;
  if (!IsPriceMet(m_track))
    return;

  // 无对手盘等待
  if (!IsVolumeValid()) {
    m_logger.With("index", m_plan_index).With("track", m_track).Info("VolumeInvalid");
    return;
  }

  if (!IsPositionVolumeValid()) {
    ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 持仓手数不足, 无法平仓");
    m_calc->CancelCallBack("InsertOrder");
    return;
  }

  InsertInstruction();
}

InsertOrderPrice CombOrderRule2::GetRuleOrderPrice(const SingleInsParams& params) const {
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return GetInsertOrderPrice(InsertOrderPriceType::kMarketPrice, AdvancedLimitPrice::kVolumeFak, 0.0);
  return GetInsertOrderPrice(
    InsertOrderPriceType::kLimitPrice, AdvancedLimitPrice::kVolumeFak, GetBestOverPrice(params));
}

void CombOrderRule2::ConvertPriceType() {
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kLimitPrice
    || m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return;
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return;
  double ask_price = ins->ask_price[0];
  double bid_price = ins->bid_price[0];
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kBestPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? ask_price : bid_price;
  } else if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kHangPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? bid_price : ask_price;
  } else {
    m_insert_params.order_price.limit_price = ins->last_price;
  }
  m_insert_params.order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
}

bool CombOrderRule2::IsVolumeValid() const {
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return false;
  bool comb_valid =
    (m_insert_params.direction == future::Direction::kBuy) ? ins->ask_volume[0] > 0 : ins->bid_volume[0] > 0;

  // 非追单, 必定检查组合对手盘.
  if (!m_track)
    return comb_valid;

  // 优先报单的优先合约, 必定检查组合对手盘.
  if (m_comb_params.prior_ins_index != -1 && m_plan_index % 2 == 0)
    return comb_valid;

  // 同时报单追单, 优先报单的非优先合约追单.
  // 有且仅需检查需要追单合约的对手盘.
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    if (plan.params.volume <= 0 || plan.instruction)
      continue;
    const auto& vol = (plan.params.direction == future::Direction::kBuy)
      ? plan.params.ins_node->Latest()->ask_volume[0]
      : plan.params.ins_node->Latest()->bid_volume[0];
    if (vol <= 0)
      return false;
  }
  return true;
}

bool CombOrderRule2::IsPriceMet(bool is_track) {
  // 追单不考虑价差, 直接追
  if (is_track || (m_plan_index % 2 != 0 && m_comb_params.prior_ins_index != -1))
    return true;
  // 检测到手动改价, 在完成一轮后改价
  if (!isnan(m_combo_price_change)) {
    m_insert_params.order_price.limit_price = m_combo_price_change;
    m_combo_price_change = NAN;
  }
  auto ins_node = m_calc->GetInstrument();
  if (!ins_node)
    return false;
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return true;
  if (m_insert_params.order_price.order_price_type != InsertOrderPriceType::kLimitPrice)
    return false;

  return (m_insert_params.direction == future::Direction::kBuy)
    ? m_insert_params.order_price.limit_price >= ins_node->ask_price[0]
    : m_insert_params.order_price.limit_price <= ins_node->bid_price[0];
}

bool CombOrderRule2::IsPositionVolumeValid() {
  // 开仓跳过检查
  if (m_insert_params.split_offset == SplitOffset::kOpen || m_insert_params.split_offset == SplitOffset::kAuto)
    return true;
  // 平仓检查持仓
  auto comb_plan = m_comb_plan[m_plan_index];
  for (const auto& plan : comb_plan) {
    auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
      m_user_key + "|0|" + plan.params.ins_node->Latest()->symbol);
    if (!position_node)
      return false;
    md::Volume volume_avail = 0;
    if (plan.params.ins_node->Latest()->ExchangeID() == "CZCE") {
      volume_avail = (plan.params.direction == future::Direction::kBuy)
        ? position_node->Latest()->VolumeShort() - position_node->Latest()->VolumeShortFrozen()
        : position_node->Latest()->VolumeLong() - position_node->Latest()->VolumeLongFrozen();
    } else {
      auto& subpos = GetSubPos(plan.params.direction, plan.params.hedge, position_node);
      volume_avail = subpos.Volume() - subpos.VolumeFrozen();
    }
    if (volume_avail < plan.params.volume)
      return false;
  }
  return true;
}

bool CombOrderRule2::IsConsiderMarketVolume() const {
  if (fabs(m_comb_params.volume_rate) < 1e-5)
    return false;
  if (m_track)
    return false;
  return m_comb_params.prior_ins_index == -1 || m_plan_index % 2 == 0;
}

void CombOrderRule2::Init(bool is_load /* = false*/) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (m_volume == 0) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 已完成");
    return;
  }
  if (m_comb_params.params.empty()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合下单参数");
    return;
  }
  if (!m_insert_params.ins_node || m_insert_params.ins_node->Snap()->ProductClass() != md::ProductClass::kCusCombine) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合合约信息");
    return;
  }
  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少交易所信息");
    return;
  }
  if (m_comb_params.prior_ins_index >= static_cast<int>(m_comb_params.params.size())) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 优先下单合约无效");
    return;
  }

  std::map<std::shared_ptr<md::InstrumentNode>, int> vweight;
  for (const auto& param : m_comb_params.params) {
    vweight[param.ins_node] = param.volume * (param.direction == future::Direction::kBuy ? 1 : -1);
  }
  m_calc = std::make_shared<CombQuoteCalc>(
    TradeAgent::GetTqApi(), CombQuoteCalc::CombQuoteCalcParams(m_insert_params.ins_node, vweight));
  m_calc->Subscribe();

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status == AgentStatus::kStopped && m_calc) {
        m_calc.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });

  // 非读档参数设置
  if (!is_load) {
    ConvertPriceType();
    BuildPlan();
    InitInsTotalVolume();
    m_insert_datetime = m_exchange_node->Latest()->GetDateTime();
    m_trigger_datetime = 0;
    m_stop_datetime = 0;
    m_comb_average_price = NAN;
  }
}

void CombOrderRule2::BuildPlan() {
  m_comb_plan.clear();
  auto cnt = m_volume;
  while (cnt--) {
    std::vector<CombPlan> plan;
    for (size_t i = 0; i < m_comb_params.params.size(); ++i) {
      const auto& params = m_comb_params.params[i];
      CombPlan t;
      if (i == static_cast<size_t>(m_comb_params.prior_ins_index)) {
        t.params = params;
        t.params.volume = params.volume;
        t.params.direction = GetInsertDirection(m_insert_params.direction, params.direction);
        m_comb_plan.emplace_back(std::vector<CombPlan>{t});
      } else {
        t.params = params;
        t.params.volume = params.volume;
        t.params.direction = GetInsertDirection(m_insert_params.direction, params.direction);
        plan.emplace_back(std::move(t));
      }
    }
    m_comb_plan.push_back(plan);
  }

  FCASSERT(!m_comb_plan.empty());
}

void CombOrderRule2::CreateInstruction(CombPlan& plan, int vol) {
  if (nullptr == m_child_factory) {
    plan.instruction = nullptr;
    return;
  }
  plan.instruction = m_child_factory(
    this, plan.params.ins_node, vol, plan.params.direction, plan.params.hedge, GetRuleOrderPrice(plan.params));
  plan.instruction->Run();
  m_childs.push_back(plan.instruction);
  m_logger.With("volume", vol)
    .With("direction", static_cast<int>(plan.params.direction))
    .With("hedge", static_cast<int>(plan.params.hedge))
    .Info("CreateInstruction");
}

void CombOrderRule2::InsertInstruction() {
  m_logger.With("m_track", m_track).With("m_plan_index", m_plan_index).Info("InsertInstruction");

  m_need_move = !m_track;

  if (m_trigger_datetime <= 0)
    m_trigger_datetime = m_exchange_node->Latest()->GetDateTime();

  if (!IsConsiderMarketVolume()) {
    m_logger.Info("IsConsiderMarketVolume_InsertInstruction");
    for (auto&& plan : m_comb_plan[m_plan_index]) {
      if (plan.params.volume > 0)
        CreateInstruction(plan, plan.params.volume);
    }
    m_track = true;
    return;
  }

  int group = INT_MAX;
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    int min_vol = plan.params.volume;
    int market_vol = GetInsertDirection(m_insert_params.direction, plan.params.direction) == future::Direction::kBuy
      ? plan.params.ins_node->Latest()->ask_volume[0]
      : plan.params.ins_node->Latest()->bid_volume[0];
    group = std::min(group, static_cast<int>(std::floor(market_vol / min_vol)));
  }
  m_logger.With("group", group).Info("InsertInstruction");
  if (group < 1)
    group = 1;

  for (auto&& plan : m_comb_plan[m_plan_index]) {
    int vol = plan.params.volume * group;
    vol = std::min(GetInsVolumeLeft(plan.params.ins_node->Latest()->symbol), vol);
    if (vol > 0)
      CreateInstruction(plan, vol);
  }
  m_track = true;
}

void CombOrderRule2::UpdateInstruction() {
  if (m_status == AgentStatus::kStopped)
    return;
  if (m_status == AgentStatus::kPaused && !m_msg.empty())
    return;

  FCASSERT(m_plan_index < static_cast<int>(m_comb_plan.size()));

  std::string error_msg;
  bool all_stopped = true;

  // 检查是否有错误.
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    const auto& instruction = plan.instruction;
    if (!instruction)
      continue;
    m_order_nodes_set.merge(instruction->GetOrderNodes());
    if (!instruction->GetMsg().empty()) {
      if (!error_msg.empty())
        error_msg += "; ";
      error_msg += plan.params.ins_node->Latest()->symbol + ": " + instruction->GetMsg();
    }
    if (instruction->GetStatus() != AgentStatus::kStopped)
      all_stopped = false;
  }

  if (!all_stopped)
    return;
  // 错误丢弃全部指令, 状态变为未启动.
  if (!error_msg.empty()) {
    // 本轮所有成交全部丢弃
    for (auto&& plan : m_comb_plan[m_plan_index]) {
      plan.instruction.reset();
    }
    m_track = false;
    ChangeStatus(true, AgentStatus::kPaused, error_msg);
    m_calc->CancelCallBack("InsertOrder");
    return;
  }

  RefreshPlanByTraded();
  CalcInsLeftVolumeByPlan();
  // 剩余手数清 0, 改变状态
  if (VolumeLeft() == 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
    return;
  }
}

void CombOrderRule2::UpdateCombAveragePrice() {
  m_comb_average_price = 0.0;
  auto& w = m_insert_params.ins_node->Snap()->instrument_base->weight;
  for (auto it = w.begin(); it != w.end(); ++it) {
    m_comb_average_price += it->second * m_average_price[it->first->Snap()->symbol];
  }
}

bool CombOrderRule2::IsPlanVolumeAllZero() {
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    if (plan.params.volume != 0)
      return false;
  }
  return true;
}

int CombOrderRule2::CalcMoveStep(const std::unordered_map<std::string, int> traded_map) {
  int move_step = 0;
  for (const auto& plan : m_comb_plan[m_plan_index]) {
    int traded_vol = 0;
    if (auto iter = traded_map.find(plan.params.ins_node->Latest()->symbol); iter != traded_map.end()) {
      traded_vol = iter->second;
    }
    move_step = std::max(move_step, static_cast<int>(std::ceil(traded_vol / plan.params.volume)));
  }
  m_logger.With("move_step", move_step).Info("CalcMoveStep");
  return move_step;
}

int CombOrderRule2::CalcIndexStep(const std::unordered_map<std::string, int> traded_map) {
  if (!m_need_move) {
    m_logger.Info("CalcIndexStep_No_Move");
    return 1;
  }
  auto step = CalcMoveStep(traded_map);
  int start_index = m_plan_index;
  if (step <= 0)
    return step;

  // 优先报单, 每次移动 2 组.
  m_plan_index += (step - 1) * (1 + static_cast<int>(m_comb_params.prior_ins_index != -1));
  m_logger.With("step", step).With("start_index", start_index).With("m_plan_index", m_plan_index).Info("CalcIndexStep");
  // 清理之前的 plan
  for (int i = start_index; i < m_plan_index; i++) {
    for (auto&& plan : m_comb_plan[i]) {
      plan.params.volume = 0;
    }
  }
  return step;
}

void CombOrderRule2::RefreshPlanByTraded() {
  std::unordered_map<std::string, int> traded_map;
  for (auto&& plan : m_comb_plan[m_plan_index]) {
    if (nullptr == plan.instruction) {
      continue;
    }
    const auto& symbol = plan.params.ins_node->Latest()->symbol;
    int trade_volume = plan.instruction->VolumeTotal() - plan.instruction->VolumeLeft();
    m_logger.With("symbol", symbol)
      .With("trade_volume", trade_volume)
      .With("volume_left", plan.instruction->VolumeLeft())
      .With("trade_amount", plan.instruction->TradeAmount())
      .Info("RefreshPlanByTraded");
    if (trade_volume > 0) {
      double amount = (trade_volume <= 0) ? 0.0 : plan.instruction->TradeAmount();
      UpdateAveragePrice(symbol, trade_volume, amount);
    }
    traded_map[plan.params.ins_node->Latest()->symbol] = trade_volume;
    plan.instruction.reset();
  }

  if (!traded_map.empty())
    UpdateCombAveragePrice();

  // 优先报单的非优先合约, 刷新手数.
  // 优先报单的非优先合约, 未全部成交必追单.
  if (m_comb_params.prior_ins_index != -1 && m_plan_index % 2 != 0) {
    m_track = false;
    for (auto&& plan : m_comb_plan[m_plan_index]) {
      const auto& symbol = plan.params.ins_node->Latest()->symbol;
      if (traded_map.find(symbol) != traded_map.end()) {
        plan.params.volume = plan.params.volume - traded_map[symbol];
        m_logger.With("symbol", symbol)
          .With("volume_left", plan.params.volume)
          .With("index", m_plan_index)
          .Info("RefreshPlanByTraded_Prior");
      }
      // 未全部成交, 需要追单
      if (plan.params.volume != 0) {
        m_track = true;
      }
    }
    // 全部成交, 移动到下一组
    if (!m_track && m_plan_index < static_cast<int>(m_comb_plan.size() - 1)) {
      ++m_plan_index;
    }
    return;
  }

  // 计算移动组数
  int step = CalcIndexStep(traded_map);

  // 刷新手数
  for (auto&& plan : m_comb_plan[m_plan_index]) {
    const auto& symbol = plan.params.ins_node->Latest()->symbol;
    if (traded_map.find(symbol) != traded_map.end()) {
      plan.params.volume = plan.params.volume * std::max(step, 1) - traded_map[symbol];
      m_logger.With("symbol", symbol)
        .With("volume_left", plan.params.volume)
        .With("index", m_plan_index)
        .Info("RefreshPlanByTraded");
    }
  }
  traded_map.clear();

  // 优先报单, 需要刷新非优先合约手数
  if (m_comb_params.prior_ins_index != -1 && m_plan_index < static_cast<int>(m_comb_plan.size() - 1) && step > 1) {
    for (auto&& plan : m_comb_plan[m_plan_index + 1]) {
      plan.params.volume = plan.params.volume * std::max(step, 1);
      m_logger.With("symbol", plan.params.ins_node->Latest()->symbol)
        .With("volume_left", plan.params.volume)
        .With("index", m_plan_index + 1)
        .Info("RefreshPlanByTraded_No_Prior");
    }
  }

  // 全部成交, 移动到下一组
  if (IsPlanVolumeAllZero() && m_plan_index < static_cast<int>(m_comb_plan.size() - 1))
    ++m_plan_index;

  // 处理追单标识:
  //
  // * 优先报单的优先合约
  // * * 切换至非优先合约, 需要追单.
  // * * 检查 plan 的 volume 是否成比例, 成比例不需要追单, 否则追单.
  //
  // * 同时报单:
  // * * 检查 plan 的 volume 是否成比例, 成比例不需要追单, 否则追单.
  if (m_comb_params.prior_ins_index != -1) {
    if (m_plan_index % 2 != 0) {
      m_track = true;
      return;
    }
    auto vol = m_comb_params.params[m_comb_params.prior_ins_index].volume;
    FCASSERT(m_comb_plan[m_plan_index].size() == 1);
    m_track = m_comb_plan[m_plan_index][0].params.volume % vol != 0;
    return;
  }

  int ratio = -1;
  for (size_t index = 0; index < m_comb_plan[m_plan_index].size(); ++index) {
    auto vol = m_comb_params.params[index].volume;
    auto plan_volume = m_comb_plan[m_plan_index][index].params.volume;
    if (plan_volume % vol != 0) {
      m_track = true;
      return;
    }
    if (ratio < 0) {
      ratio = plan_volume / vol;
    } else if (plan_volume / vol != ratio) {
      m_track = true;
      return;
    }
  }
  m_track = false;
}

void CombOrderRule2::UpdateAveragePrice(const std::string& symbol, int trade_volume, double amount) {
  auto volume_prev = m_ins_total_volume[symbol] - m_ins_volume_left[symbol];
  double price_prev = m_average_price[symbol];
  if (isnan(price_prev))
    price_prev = 0.0;
  m_average_price[symbol] = (amount + price_prev * volume_prev) / (trade_volume + volume_prev);
}

void CombOrderRule2::CalcInsLeftVolumeByPlan() {
  std::unordered_map<std::string, int> volume;
  for (const auto& comb_plan : m_comb_plan) {
    for (const auto& plan : comb_plan) {
      FCASSERT(plan.params.ins_node);
      volume[plan.params.ins_node->Latest()->symbol] += plan.params.volume;
    }
  }
  bool notify = false;
  for (const auto& [symbol, vol] : volume) {
    auto iter = m_ins_volume_left.find(symbol);
    if (iter != m_ins_volume_left.end() && m_ins_volume_left[symbol] != vol) {
      notify = true;
      m_ins_volume_left[symbol] = vol;
    }
  }
  if (notify && m_parent) {
    m_parent->OnChildNotify(this);
    m_logger.With("OnChildNotify", "parent").Info("CalcInsLeftVolumeByPlan");
  }
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

void CombOrderRule2::InitInsTotalVolume() {
  m_ins_total_volume.clear();
  m_ins_volume_left.clear();
  m_average_price.clear();
  for (const auto& param : m_comb_params.params) {
    FCASSERT(param.ins_node);
    m_ins_total_volume[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_ins_volume_left[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_average_price[param.ins_node->Latest()->symbol] = NAN;
  }
  FCASSERT(!m_ins_total_volume.empty());
}

void CombOrderRule2::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("track", m_track)
    .With("status", static_cast<int>(status))
    .With("msg", msg)
    .With("plan_index", m_plan_index)
    .Info("ChangeStatus");

  m_status = status;
  // 运行中, 停止时间归0
  if (m_status == AgentStatus::kStarted)
    m_stop_datetime = 0;
  else if (m_exchange_node)
    m_stop_datetime = m_exchange_node->Snap()->GetDateTime();
  else
    m_stop_datetime = NowAsEpochNano();
  if (m_msg != msg)
    m_msg = msg;
  if (m_parent && notify)
    m_parent->OnChildNotify(this);
  if (m_call_back && notify)
    m_call_back(shared_from_this());
}

