void CombOrderRule3::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");
}

void CombOrderRule3::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");
  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;
  // 启动组合单
  ChangeStatus(true, AgentStatus::kStarted, "");

  // 不在交易小节前下单
  if (!IsInBeforeCloseTime())
    InsertOrder();

  // 行情报单 + 改价
  m_calc->SetCallBack("InsertOrder", [this]() {
    if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
      m_calc->CancelCallBack("InsertOrder");
      return;
    }
    //  小节前不下单
    if (IsInBeforeCloseTime()) {
      return;
    }
    m_comb_plan.empty() ? InsertOrder() : TryLimitPrice();
  });
  // 超时改价
  m_exchange_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode>, bool) {
      if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
        m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      TryBestPrice();
    });
}

void CombOrderRule3::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  if (m_status != AgentStatus::kStarted)
    return;

  // 规则3 存在 plan 不可暂停, 先切为暂停中
  if (!m_comb_plan.empty()) {
    ChangeStatus(true, AgentStatus::kPausing, m_msg);
    return;
  }
  ChangeStatus(true, AgentStatus::kPaused, m_msg);
  m_calc->CancelCallBack("InsertOrder");
  m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
}

void CombOrderRule3::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");
}

AgentStatus CombOrderRule3::GetStatus() const {
  return m_status;
