int CombOrderRule3::CalcInsertVolume() {
  const auto& direction = m_insert_params.direction;
  const auto& ins = m_calc->GetInstrument();
  auto volume = direction == future::Direction::kBuy ? ins->ask_volume[0] : ins->bid_volume[0];
  auto cal_volume = static_cast<int>(std::floor(volume * m_comb_params.volume_rate));

  // std::min(std::max(盘口 * 百分比, 1), 剩余手数).
  return std::min(std::max(cal_volume, 1), m_volume);
}

void CombOrderRule3::InsertOrder() {
  if (m_status == AgentStatus::kPausing)
    return;
  if (m_status == AgentStatus::kPaused || m_status == AgentStatus::kStopped)
    return;
  // 有正在执行的 plan, 则等待完成.
  if (!m_comb_plan.empty())
    return;
  if (!IsInTradingTime(m_comb_params.params))
    return;
  if (!isnan(m_changed_price)) {
    m_insert_params.order_price.limit_price = m_changed_price;
    m_changed_price = NAN;
  }
  if (!IsPriceMet())
    return;
  auto insert_volume = CalcInsertVolume();
  m_logger.With("insert_volume", insert_volume).Info("InsertOrder");
  if (!IsPositionVolumeValid(insert_volume)) {
    ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 持仓手数不足, 无法平仓");
    m_calc->CancelCallBack("InsertOrder");
    return;
  }
  InsertInstruction(insert_volume);
}

std::vector<bool> CombOrderRule3::IsNeedChangePrice(const std::vector<CombPlan>& comb_plan,
  const CombOrderParams& comb_params, const std::vector<double>& insert_price, double limit_price,
  const fclib::future::Direction& direction) {
  auto size = comb_plan.size();
  std::vector<bool> ret(size, false);
  if (!IsInTradingTime(comb_params.params))
    return ret;
  double cur_price = 0.0;
  for (size_t index = 0; index < size; ++index) {
    if (!comb_plan[index].instruction)
      continue;
    auto ratio = comb_plan[index].params.direction == direction ? 1 : -1;
    auto amount =
      isnan(comb_plan[index].instruction->TradeAmount()) ? 0.0 : comb_plan[index].instruction->TradeAmount();
    cur_price += (insert_price[index] * comb_plan[index].instruction->VolumeLeft() + amount)
      / comb_plan[index].instruction->VolumeTotal() * comb_params.params[index].volume * ratio;
  }

  for (size_t index = 0; index < size; ++index) {
    if (!comb_plan[index].instruction)
      continue;
    auto ratio = comb_plan[index].params.direction == direction ? 1 : -1;
    auto vol_left = comb_plan[index].instruction->VolumeLeft();
    if (vol_left <= 0) {
      continue;
    }
    auto index_market_price = comb_plan[index].params.direction == fclib::future::Direction::kBuy
      ? comb_plan[index].params.ins_node->Latest()->ask_price[0]
      : comb_plan[index].params.ins_node->Latest()->bid_price[0];
    auto index_insert_price = insert_price[index];
    if (isnan(index_market_price) || fabs(index_market_price - index_insert_price) < 1e-6) {
      continue;
    }
    auto amount =
      isnan(comb_plan[index].instruction->TradeAmount()) ? 0.0 : comb_plan[index].instruction->TradeAmount();
    auto vol_total = comb_plan[index].instruction->VolumeTotal();
    auto coef = comb_params.params[index].volume;

    auto market_price = (index_market_price * vol_left + amount) / vol_total * coef * ratio;
    auto insert_price = (index_insert_price * vol_left + amount) / vol_total * coef * ratio;
    auto new_price = cur_price + market_price - insert_price;

    if ((direction == fclib::future::Direction::kBuy && new_price > limit_price + comb_params.slippage)
      || (direction == fclib::future::Direction::kSell && new_price < limit_price - comb_params.slippage)) {
      continue;
    }
    ret[index] = true;
    cur_price = new_price;
  }
  return ret;
}

void CombOrderRule3::ConvertPriceType() {
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kLimitPrice
    || m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return;
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return;
  double ask_price = ins->ask_price[0];
  double bid_price = ins->bid_price[0];
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kBestPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? ask_price : bid_price;
  } else if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kHangPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? bid_price : ask_price;
  } else {
    m_insert_params.order_price.limit_price = ins->last_price;
  }
  m_insert_params.order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
}

// 是否价格满足
bool CombOrderRule3::IsPriceMet() const {
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return false;
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return true;
  if (m_insert_params.order_price.order_price_type != InsertOrderPriceType::kLimitPrice)
    return false;
  return (m_insert_params.direction == future::Direction::kBuy)
    ? m_insert_params.order_price.limit_price >= ins->ask_price[0]
    : m_insert_params.order_price.limit_price <= ins->bid_price[0];
}

bool CombOrderRule3::IsPositionVolumeValid(int insert_volume) const {
  // 开仓跳过检查
  if (m_insert_params.split_offset == SplitOffset::kOpen || m_insert_params.split_offset == SplitOffset::kAuto)
    return true;
  // 平仓检查持仓
  for (const auto& params : m_comb_params.params) {
    auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
      m_user_key + "|0|" + params.ins_node->Latest()->symbol);
    if (!position_node)
      return false;
    auto direction = GetInsertDirection(m_insert_params.direction, params.direction);
    md::Volume volume_avail = 0;
    if (params.ins_node->Latest()->ExchangeID() == "CZCE") {
      volume_avail = (direction == future::Direction::kBuy)
        ? position_node->Latest()->VolumeShort() - position_node->Latest()->VolumeShortFrozen()
        : position_node->Latest()->VolumeLong() - position_node->Latest()->VolumeLongFrozen();
    } else {
      auto& subpos = GetSubPos(direction, params.hedge, position_node);
      volume_avail = subpos.Volume() - subpos.VolumeFrozen();
    }
    if (volume_avail < insert_volume)
      return false;
  }
  return true;
}

int StringTimeToInt(std::string str) {
  int hours = 0, minutes = 0, seconds = 0;
  FCASSERT(std::sscanf(str.c_str(), "%d:%d:%d", &hours, &minutes, &seconds) == 3);
  return hours * 3600 + minutes * 60 + seconds;
}

bool IsIndexOption(const std::string& symbol) {
  return symbol.find("IO") != std::string::npos || symbol.find("HO") != std::string::npos
    || symbol.find("MO") != std::string::npos;
}

void CombOrderRule3::InitBeforeCloseTable() {
  // 超时追单和小节前追单必须同时启用
  if (m_comb_params.time_out == -1) {
    return;
  }
  for (const auto& leg : m_comb_params.params) {
    const auto& leg_table = leg.ins_node->Latest()->TradingTime();
    std::map<int, int> leg_table_map;
    std::string symbol = leg.ins_node->Latest()->symbol;

    for (auto const& interval : leg_table.day) {
      auto end = StringTimeToInt(interval[1]);
      auto start = end - m_comb_params.time_before_close;
      //  如果是指数期权, 集合竞价特殊处理.
      if (end == 3600 * 15 && IsIndexOption(symbol)) {
        start -= 60 * 3;
      }
      leg_table_map[start] = end;
    }
    for (auto const& interval : leg_table.night) {
      auto end = StringTimeToInt(interval[1]);
      auto start = end - m_comb_params.time_before_close;
      leg_table_map[start] = end;
    }
    m_before_close_table.emplace_back(leg_table_map);
  }
}

bool CombOrderRule3::IsInBeforeCloseTime() {
  // 如果超时追单未用, 直接返回
  if (m_comb_params.time_out == -1) {
    return false;
  }
  auto now = EpochNanoToLocalDateTime(m_exchange_node->Snap()->exchange_date_time);
  // 如果是隔夜+24小时
  int seconds = now.date_time.tm_hour * 3600 + now.date_time.tm_min * 60 + now.date_time.tm_sec
    + (now.date_time.tm_hour < 8 ? 86400 : 0);
  for (const auto& leg_map : m_before_close_table) {
    auto it = leg_map.upper_bound(seconds);
    // 当前时间小于所有交易时间段的开始时间
    if (it == leg_map.begin()) {
      continue;
    }
    it--;
    // 当前时间在交易小节时间段内
    if (it->first <= seconds && seconds <= it->second) {
      return true;
    }
  }
  return false;
}

void CombOrderRule3::Init(bool is_load /* = false*/) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (m_volume == 0) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 已完成");
    return;
  }
  if (m_comb_params.params.empty()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合下单参数");
    return;
  }
  if (!m_insert_params.ins_node || m_insert_params.ins_node->Snap()->ProductClass() != md::ProductClass::kCusCombine) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合合约信息");
    return;
  }
  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少交易所信息");
    return;
  }
  InitBeforeCloseTable();
  std::map<std::shared_ptr<md::InstrumentNode>, int> vweight;
  for (const auto& param : m_comb_params.params) {
    vweight[param.ins_node] = param.volume * (param.direction == future::Direction::kBuy ? 1 : -1);
  }
  m_calc = std::make_shared<CombQuoteCalc>(
    TradeAgent::GetTqApi(), CombQuoteCalc::CombQuoteCalcParams(m_insert_params.ins_node, vweight));
  m_calc->Subscribe();

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status == AgentStatus::kStopped && m_calc) {
        m_calc.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });

  // 非读档参数设置
  if (!is_load) {
    ConvertPriceType();
    InitInsTotalVolume();
    m_insert_datetime = m_exchange_node->Latest()->GetDateTime();
    m_trigger_datetime = 0;
    m_stop_datetime = 0;
    m_comb_average_price = NAN;
  }
  m_insert_price.resize(m_comb_params.params.size());
}

double CombOrderRule3::CreateInstruction(CombPlan& plan, int vol) {
  if (nullptr == m_child_factory) {
    plan.instruction = nullptr;
    return NAN;
  }
  // 规则3 对价 GFD 报单.
  auto best_price = GetInsertOrderPrice(
    InsertOrderPriceType::kLimitPrice, AdvancedLimitPrice::kVolumeNone, GetBestOverPrice(plan.params));
  plan.instruction =
    m_child_factory(this, plan.params.ins_node, vol, plan.params.direction, plan.params.hedge, best_price);
  plan.instruction->Run();
  m_childs.push_back(plan.instruction);
  m_logger.With("volume", vol)
    .With("direction", static_cast<int>(plan.params.direction))
    .With("hedge", static_cast<int>(plan.params.hedge))
    .Info("CreateInstruction");
  return best_price.limit_price;
}

void CombOrderRule3::UpdateInstruction() {
  if (m_status == AgentStatus::kStopped)
    return;
  if (m_status == AgentStatus::kPaused && !m_msg.empty())
    return;
  if (m_comb_plan.empty())
    return;

  std::string error_msg;
  bool all_stopped = true;

  // 检查是否有错误.
  for (const auto& plan : m_comb_plan) {
    const auto& instruction = plan.instruction;
    if (!instruction)
      continue;
    m_order_nodes_set.merge(instruction->GetOrderNodes());
    if (!instruction->GetMsg().empty()) {
      if (!error_msg.empty())
        error_msg += "; ";
      error_msg += plan.params.ins_node->Latest()->symbol + ": " + instruction->GetMsg();
    }
    if (instruction->GetStatus() != AgentStatus::kStopped)
      all_stopped = false;
  }

  // 错误丢弃全部指令, 状态变为未启动.
  if (!error_msg.empty()) {
    for (auto&& plan : m_comb_plan) {
      if (!plan.instruction)
        continue;
      if (plan.instruction->GetStatus() != AgentStatus::kStopped)
        plan.instruction->Stop();
      plan.instruction.reset();
    }
    m_comb_plan.clear();
    ChangeStatus(true, AgentStatus::kPaused, error_msg);
    m_calc->CancelCallBack("InsertOrder");
    return;
  }

  if (!all_stopped)
    return;

  RefreshPlanByTraded();
  // 剩余手数清 0, 改变状态
  if (VolumeLeft() == 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
    return;
  }
}

void CombOrderRule3::InsertInstruction(int insert_volume) {
  if (m_trigger_datetime <= 0) {
    m_trigger_datetime = m_exchange_node->Latest()->GetDateTime();
  }
  if (nullptr == m_child_factory)
    return;

  for (size_t i = 0; i < m_comb_params.params.size(); i++) {
    CombPlan t;
    auto params = m_comb_params.params[i];
    t.params = params;
    t.params.volume = insert_volume * params.volume;
    t.params.direction = GetInsertDirection(m_insert_params.direction, params.direction);
    m_insert_price[i] = CreateInstruction(t, t.params.volume);
    m_comb_plan.emplace_back(std::move(t));
    m_logger.With("index", static_cast<int>(i))
      .With("symbol", params.ins_node->GetKey().data())
      .With("volume", t.params.volume)
      .With("price", m_insert_price[i])
      .With("dirction", static_cast<int>(t.params.direction))
      .Info("InsertInstruction");
  }

  // 重置超时计时器
  if (m_comb_params.time_out >= 0) {
    m_time_out = false;
    m_timer.Reset(std::chrono::seconds(m_comb_params.time_out));
  }
}

void CombOrderRule3::RefreshPlanByTraded() {
  for (size_t i = 0; i < m_comb_plan.size(); i++) {
    auto& plan = m_comb_plan[i];
    if (nullptr == plan.instruction) {
      continue;
    }

    const auto& symbol = plan.params.ins_node->Latest()->symbol;
    int trade_volume = plan.instruction->VolumeTotal() - plan.instruction->VolumeLeft();
    double amount = (trade_volume <= 0) ? 0.0 : plan.instruction->TradeAmount();

    // 刷新单合约成交均价和剩余手数
    UpdateAveragePrice(symbol, trade_volume, amount);
    m_ins_volume_left[symbol] -= trade_volume;

    m_logger.With("symbol", symbol).With("volume", trade_volume).With("amount", amount).Info("RefreshPlanByTraded");
  }

  // 刷新组合成交均价
  UpdateCombAveragePrice();
  m_logger.With("comb_average_price", m_comb_average_price).Info("RefreshPlanByTraded");

  int vol = 0;
  for (const auto& params : m_comb_params.params) {
    auto min_vol = params.volume;
    auto left_vol = m_ins_volume_left[params.ins_node->Latest()->symbol];
    vol = std::max(vol, static_cast<int>(std::ceil(left_vol / min_vol)));
  }
  m_volume = vol;
  m_logger.With("comb_vol", vol).Info("RefreshPlanByTraded");

  m_time_out = false;
  m_comb_plan.clear();
  m_insert_price.assign(m_insert_price.size(), 0.0);
}

void CombOrderRule3::UpdateAveragePrice(const std::string& symbol, int trade_volume, double amount) {
  auto volume_prev = m_ins_total_volume[symbol] - m_ins_volume_left[symbol];
  double price_prev = m_average_price[symbol];
  if (isnan(price_prev))
    price_prev = 0.0;
  m_average_price[symbol] = (amount + price_prev * volume_prev) / (trade_volume + volume_prev);
}

void CombOrderRule3::UpdateCombAveragePrice() {
  m_comb_average_price = 0.0;
  auto& w = m_insert_params.ins_node->Snap()->instrument_base->weight;
  for (auto it = w.begin(); it != w.end(); ++it) {
    m_comb_average_price += it->second * m_average_price[it->first->Snap()->symbol];
  }
}

void CombOrderRule3::InitInsTotalVolume() {
  m_logger.Info("InitInsTotalVolume");
  m_ins_total_volume.clear();
  m_ins_volume_left.clear();
  m_average_price.clear();
  for (const auto& param : m_comb_params.params) {
    FCASSERT(param.ins_node);
    m_ins_total_volume[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_ins_volume_left[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_average_price[param.ins_node->Latest()->symbol] = NAN;
  }
  FCASSERT(!m_ins_total_volume.empty());
}

void CombOrderRule3::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_status = status;
  if (m_msg != msg)
    m_msg = msg;
  TradeAgentSerializer ss;
  std::string res;
  ss.FromVar(status);
  ss.ToString(&res);
  m_logger.With("AgentStatus", res).With("msg", msg).Info("ChangeStatus");
  // 运行中, 停止时间归0
  if (m_status == AgentStatus::kStarted)
    m_stop_datetime = 0;
  else if (m_exchange_node)
    m_stop_datetime = m_exchange_node->Snap()->GetDateTime();
  else
    m_stop_datetime = NowAsEpochNano();
  if (notify && m_parent)
    m_parent->OnChildNotify(this);
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

bool CombOrderRule3::IsExpired() {
  if (m_comb_params.time_out < 0) {
    return false;
  }
  return m_timer.IsExpired();
}

void CombOrderRule3::TryLimitPrice() {
  // 定时器超时, 行情不改价, 由定时器触发对价改价.
  if (IsExpired()) {
    return;
  }
  // 根据行情, 尝试改价.
  const auto need_change = IsNeedChangePrice(
    m_comb_plan, m_comb_params, m_insert_price, m_insert_params.order_price.limit_price, m_insert_params.direction);
  FCASSERT(need_change.size() == m_comb_plan.size());
  for (size_t i = 0; i < need_change.size(); ++i) {
    if (!need_change[i]) {
      continue;
    }
    const auto& plan = m_comb_plan[i];
    if (plan.instruction) {
      plan.instruction->ChangeOrderPrice(ChangePriceParams(GetBestOverPrice(plan.params)), 0);
      m_insert_price[i] = GetBestOverPrice(plan.params);
      m_logger.With("symbol", plan.params.ins_node->Latest()->symbol)
        .With("m_insert_price", m_insert_price[i])
        .Info("ChangeOrderPrice_TryLimitPrice");
    }
  }
}

void CombOrderRule3::TryBestPrice() {
  // 场上无挂单 不追单
  if (m_comb_plan.empty())
    return;
  // 交易小节前追单 超时追单
  if (!IsInBeforeCloseTime() && (!IsExpired() || m_time_out))
    return;

  m_time_out = true;
  for (auto& plan : m_comb_plan) {
    if (plan.instruction) {
      plan.instruction->ChangeOrderPrice(ChangePriceParams(ChangePriceType::kBestPrice));
      m_logger.With("symbol", plan.params.ins_node->Latest()->symbol).Info("ChangeOrderPrice_TryBestPrice");
    }
  }
}

