InsertOrderPrice GetInsertOrderPrice(
  const InsertOrderPriceType& type, const AdvancedLimitPrice& advanced, double limit_price);

// 获取下单实际方向
future::Direction GetInsertDirection(const future::Direction& d1, const future::Direction& d2) {
  if (d1 != future::Direction::kSell)
    return d2;
  return (d2 == future::Direction::kBuy) ? future::Direction::kSell : future::Direction::kBuy;
}

// 获取子持仓
const future::SubPosition& GetSubPos(
  const future::Direction& d, const future::OrderHedgeFlag& hedge, std::shared_ptr<future::PositionNode> pos_node) {
  if (d == future::Direction::kBuy) {
    return (hedge == future::OrderHedgeFlag::kSpeculation) ? pos_node->Latest()->subpos_short_spec
                                                           : pos_node->Latest()->subpos_short_other;
  } else {
    return (hedge == future::OrderHedgeFlag::kSpeculation) ? pos_node->Latest()->subpos_long_spec
                                                           : pos_node->Latest()->subpos_long_other;
  }
}

// 是否在可交易时段.
bool IsInTradingTime(const std::vector<SingleInsParams>& params) {
  for (const auto& param : params) {
    auto ins_node = param.ins_node;
    FCASSERT(ins_node);
    if (!ins_node->Latest()->IsTradingAllowed())
      return false;
  }
  return true;
}

double GetBestOverPrice(const SingleInsParams& params) {
  bool buy = params.direction == future::Direction::kBuy;
  double over = params.price_over * params.ins_node->Latest()->PriceTick() * (buy ? 1 : -1);
  double calc_price =
    (buy ? params.ins_node->Latest()->GetAskPrice() : params.ins_node->Latest()->GetBidPrice()) + over;
  if (calc_price > params.ins_node->Snap()->upper_limit)
    calc_price = params.ins_node->Snap()->upper_limit;
  if (calc_price < params.ins_node->Snap()->lower_limit)
    calc_price = params.ins_node->Snap()->lower_limit;
  return calc_price;
}

std::shared_ptr<CombOrderInstruction> CombOrderInstruction::Create(TradeAgent* parent,
  const InsertOrderParams& insert_params, const CombOrderParams& comb_params, const std::string& user_key, int volume,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, std::shared_ptr<md::InstrumentNode>, int,
    const future::Direction&, const future::OrderHedgeFlag&, const InsertOrderPrice&)>
    child_factory) {
  if (comb_params.rule == CombRule::kRule1)
    return std::make_shared<CombOrderRule1>(parent, insert_params, comb_params, user_key, volume, child_factory);
  if (comb_params.rule == CombRule::kRule2)
    return std::make_shared<CombOrderRule2>(parent, insert_params, comb_params, user_key, volume, child_factory);
  if (comb_params.rule == CombRule::kRule3)
    return std::make_shared<CombOrderRule3>(parent, insert_params, comb_params, user_key, volume, child_factory);
  return nullptr;
}

std::shared_ptr<CombOrderInstruction> CombOrderInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, std::shared_ptr<md::InstrumentNode>, int,
    const future::Direction&, const future::OrderHedgeFlag&, const InsertOrderPrice&)>
    child_factory) {
  TradeAgentSerializer ss;
  CombOrderParamsPack params_pack;
  ss.FromString(params.c_str());
  ss.ToVar(params_pack);
  params_pack.insert_params.ins_node =
    TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(params_pack.insert_symbol);
  if (!params_pack.insert_params.ins_node)
    return nullptr;
  for (const auto& param : params_pack.comb_params.params) {
    if (!param.ins_node || param.ins_node->Latest()->expired)
      return nullptr;
  }
  if (params_pack.comb_params.rule == CombRule::kRule1) {
    return std::make_shared<CombOrderRule1>(parent, params_pack, child_factory);
  }
  if (params_pack.comb_params.rule == CombRule::kRule2) {
    return std::make_shared<CombOrderRule2>(parent, params_pack, child_factory);
  }
  if (params_pack.comb_params.rule == CombRule::kRule3) {
    return std::make_shared<CombOrderRule3>(parent, params_pack, child_factory);
  }
  return nullptr;
}

