FollowQuoteInstruction::FollowQuoteInstruction(TradeAgent* parent, const OrderSplitParams& split_params,
  const InsertOrderPrice& order_price, const future::Direction& direction, std::shared_ptr<md::InstrumentNode> ins_node,
  int volume, std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory)
  : m_split_params(split_params)
  , m_ins_node(ins_node)
  , m_quote_ratio(split_params.quote_ratio)
  , m_volume(volume)
  , m_direction(direction)
  , m_child_factory(child_factory)
  , m_order_price(order_price)
  , m_volume_total(volume)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("follow_quote", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("follow_quote", GetAgentIndex()).Clone()) {
  m_parent = parent;

  m_logger.With("symbol", (ins_node && ins_node->Snap()) ? ins_node->Snap()->symbol : "")
    .With("split_params", SerializeToString(m_split_params))
    .With("order_price", SerializeToString(m_order_price))
    .With("direction", static_cast<int>(m_direction))
    .With("volume", m_volume)
    .Info("Constructor");

  if (m_order_price.price_over < 0)
    m_order_price.price_over = 0;

  if (split_params.order_split_price_type != OrderSplitPriceType::kBestPrice
    && split_params.order_split_price_type != OrderSplitPriceType::kHangPrice) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 跟量只支持挂价和对价下单");
    return;
  }
  m_order_price.order_price_type = ConvertPriceType(split_params.order_split_price_type);

  Init();
}

