  const OrderSplitInstruction::OrderSplitParamsPack& params_pack,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory)
  : m_split_params(params_pack.split_params.split_params)
  , m_ins_node(params_pack.split_params.ins_node)
  , m_quote_ratio(params_pack.split_params.split_params.quote_ratio)
