  , m_volume_total(params_pack.volume_total)
  , m_average_price(params_pack.average_price)
  , m_input_params(params_pack.split_params)
  , m_last_volume_left(params_pack.last_volume_left)
  , m_last_traded_amount(params_pack.last_traded_amount)
  , m_insert_datetime(params_pack.insert_datetime)
  , m_msg(params_pack.msg)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("follow_quote", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("follow_quote", GetAgentIndex()).Clone()) {
