  m_instruction_memo = params_pack.memo;

  m_logger.With("params_pack", SerializeToString(params_pack)).Info("LoadConstructor");

  Init();
}

FollowQuoteInstruction::~FollowQuoteInstruction() {}

void FollowQuoteInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");

  this->Start();
}

void FollowQuoteInstruction::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");
}

void FollowQuoteInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  // 非运行中状态不操作
  if (m_status != AgentStatus::kStarted)
    return;
  // 停止 view 跟踪
  m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  ChangeStatus(true, AgentStatus::kPaused, m_msg);
  // 有下单且未撤过单的情况下撤单
  if (m_instruction) {
    m_instruction->Stop();
  }
}

int FollowQuoteInstruction::VolumeLeft() {
  return m_volume;
}

double FollowQuoteInstruction::TradeAmount() {
  return m_average_price * (m_input_params.volume - m_volume);
}

// 获取当前指令状态

AgentStatus FollowQuoteInstruction::GetStatus() const {
  if (m_status == fclib::extension::AgentStatus::kPaused && m_market_lame)
    return fclib::extension::AgentStatus::kStarted;
  return m_status;
}

std::string FollowQuoteInstruction::GetMsg() const {
  return m_msg;
}

structlog::Logger* FollowQuoteInstruction::GetLogger() {
  return &m_logger;
}

int FollowQuoteInstruction::VolumeTotal() {
  return m_volume_total;
}

bool FollowQuoteInstruction::VisibleInViewInstruction() const {
  return true;
}

void FollowQuoteInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");

  // 非暂停或补单状态状态下不操作
  if (m_status != AgentStatus::kPaused || m_market_lame)
    return;

  ChangeStatus(true, AgentStatus::kStarted, "");
  // 行情驱动跟量下单算法
  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> node, bool is_last) {
      // 状态已完成或未启动, 不再跟踪
      if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      // 判断行情时间是否在交易时间段内, 非交易时段不作任何处理
      if (IsOrderInsertable())
        InsertFollowOrder();
    });
}

std::string FollowQuoteInstruction::SaveInstruction() {
  Pause();
  OrderSplitInstruction::OrderSplitParamsPack params_pack;
  params_pack.split_params = m_input_params;
  params_pack.order_price = m_order_price;
  params_pack.symbol = m_ins_node->Snap()->symbol;
  params_pack.status = m_status;
  params_pack.msg = m_msg;
  params_pack.insert_datetime = m_insert_datetime;
  params_pack.stop_datetime = m_stop_datetime;
  params_pack.average_price = m_average_price;
  params_pack.volume = m_volume;
  params_pack.volume_total = m_volume_total;
  params_pack.last_volume_left = m_last_volume_left;
  params_pack.last_traded_amount = m_last_traded_amount;
  params_pack.memo = m_instruction_memo;
  return SerializeToString(params_pack);
}

void FollowQuoteInstruction::MarketLame(int price_over) {
  // 已在补单 或 已完成 不允许再次点击
  if (m_market_lame || m_status == fclib::extension::AgentStatus::kStopped)
    return;
  m_market_price_over = price_over;
  Pause();
  m_market_lame = true;
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
  if (!m_instruction) {
    // 发剩余的单
    m_lame_send = true;
    InsertOrderPrice order_price;
    order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
    order_price.order_price_type = InsertOrderPriceType::kBestPrice;
    order_price.price_over = m_market_price_over;
    m_last_volume_left = VolumeLeft();
    m_last_traded_amount = 0;
    m_instruction = m_child_factory(this, VolumeLeft(), order_price);
    m_childs.push_back(m_instruction);
    m_instruction->Run();
    return;
  }
  m_lame_send = false;
}

int FollowQuoteInstruction::CalcInsertVolume() {
  // 如果是跟量下单
  if (m_split_params.split_algo == OrderSplitAlgo::kFollow) {
    const auto& last_volume = m_ins_node->Latest()->volume;
    const auto his_volume = m_ins_node->Historical() ? m_ins_node->Historical()->volume : 0;

    if (!m_ins_node->Historical())
      return 0;
    int quote = static_cast<int>(last_volume - his_volume) + m_pre_quantity;
    int volume = std::min({static_cast<int>(std::floor(quote * m_quote_ratio)), m_volume, m_max_volume});
    // 检查盘口是否有挂单
    const auto& vol = (m_direction == future::Direction::kBuy)
        == (m_split_params.order_split_price_type == OrderSplitPriceType::kHangPrice)
      ? m_ins_node->Latest()->bid_volume[0]
      : m_ins_node->Latest()->ask_volume[0];

    m_logger.With("pre_quantity", m_pre_quantity)
      .With("last_volume", last_volume)
      .With("his_volume", his_volume)
      .With("quote_ratio", m_quote_ratio)
      .With("vol", vol)
      .With("volume", m_volume)
      .With("max_volume", m_max_volume)
      .Debug("CalcInsertVolume");

    if (volume <= 0 || vol <= 0) {
      m_pre_quantity = quote;
      return 0;
    } else {
      m_pre_quantity = 0;
      return volume;
    }
  } else {
    // 盘口下单
    int quote = (m_direction == future::Direction::kBuy) == (m_split_params.is_hang)
      ? m_ins_node->Latest()->bid_volume[0]
      : m_ins_node->Latest()->ask_volume[0];

    // 检查盘口是否有挂单
    const auto& vol = (m_direction == future::Direction::kBuy)
        == (m_split_params.order_split_price_type == OrderSplitPriceType::kHangPrice)
      ? m_ins_node->Latest()->bid_volume[0]
      : m_ins_node->Latest()->ask_volume[0];

    m_logger.With("bid_volume", m_ins_node->Latest()->bid_volume[0])
      .With("ask_volume", m_ins_node->Latest()->ask_volume[0])
      .With("quote_ratio", m_quote_ratio)
      .With("volume", m_volume)
      .With("vol", vol)
      .With("max_volume", m_max_volume)
      .Debug("CalcInsertVolume");

    if (quote == 0 || vol == 0) {
      return 0;
    }
    int volume = std::min({static_cast<int>(std::floor(quote * m_quote_ratio)), m_volume, m_max_volume});
    if (volume <= 0) {
      return 1;
    }
    return volume;
  }
}

double FollowQuoteInstruction::CalcNewPrice() {
  double new_price = 0.0;
  if (m_order_price.order_price_type == InsertOrderPriceType::kBestPrice) {
    new_price = (m_direction == future::Direction::kBuy) ? m_ins_node->Latest()->ask_price[0]
                                                         : m_ins_node->Latest()->bid_price[0];
  } else {
    new_price = (m_direction == future::Direction::kBuy) ? m_ins_node->Latest()->bid_price[0]
                                                         : m_ins_node->Latest()->ask_price[0];
  }
  m_logger.With("new_price", new_price).Debug("CalcNewPrice");
  return new_price;
}

void FollowQuoteInstruction::InsertFollowOrder() {
  if (m_status == AgentStatus::kPaused)
    return;
  if (m_volume <= 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
    return;
  }
  if (nullptr == m_instruction) {
    InsertInstruction();
  } else {
    // 行情变动, 需要修改价格
    auto last_order = m_instruction->GetInsertOrder();
    FCASSERT(!last_order.empty() && nullptr != last_order[0]);
    double last_price = last_order[0]->limit_price;
    double new_price = CalcNewPrice();
    if (!isnan(new_price) && fabs(last_price - new_price) > 1e-5) {
      m_logger.With("last_price", last_price).With("new_price", new_price).Info("InsertFollowOrder");
      m_instruction->ChangeOrderPrice(ChangePriceParams(new_price));
    }
  }
}

void FollowQuoteInstruction::InsertInstruction() {
  int volume = CalcInsertVolume();
  if (volume <= 0 || nullptr == m_child_factory) {
    m_logger.With("volume", volume).Info("InsertInstruction_Volume");
    return;
  }
  m_logger.With("insert_volume", volume)
    .With("order_price", SerializeToString(m_order_price))
    .Info("InsertInstruction");

  m_last_volume_left = volume;
  m_last_traded_amount = 0;
  m_instruction = m_child_factory(this, volume, m_order_price);
  FCASSERT(m_instruction);
  m_instruction->Run();
  m_childs.push_back(m_instruction);
}

void FollowQuoteInstruction::RefreshVolumeTraded(std::shared_ptr<TradeInstruction> instruction) {
  // 计算手数变化和成交量变化
  int traded_volume = m_last_volume_left - instruction->VolumeLeft();
  m_last_volume_left = instruction->VolumeLeft();
  double traded_amount = 0;
  if (traded_volume != 0) {
    traded_amount = instruction->TradeAmount() - m_last_traded_amount;
    m_last_traded_amount = instruction->TradeAmount();
  }
  FCASSERT(traded_volume <= m_volume);

  m_logger.With("traded_volume", traded_volume)
    .With("traded_amount", traded_amount)
    .With("prev_average_price", m_average_price)
    .Info("RefreshVolumeTraded");

  if (0 == traded_volume) {
    return;
  }
  m_average_price = isnan(m_average_price) ? 0 : m_average_price;
  m_average_price = (TradeAmount() + traded_amount) / (m_volume_total - m_volume + traded_volume);
  m_volume -= traded_volume;
  if (m_volume == 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
    return;
  }
}

InsertOrderPriceType FollowQuoteInstruction::ConvertPriceType(OrderSplitPriceType type) {
  switch (type) {
    case OrderSplitPriceType::kBestPrice: return InsertOrderPriceType::kBestPrice;
    case OrderSplitPriceType::kHangPrice: return InsertOrderPriceType::kHangPrice;
    default: FCASSERT(false); return InsertOrderPriceType::kLimitPrice;
  }
}

void FollowQuoteInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;

  if (m_insert_datetime <= 0) {
    m_insert_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
  }
  if (m_status == AgentStatus::kStarted)
    m_stop_datetime = 0;
  else
    m_stop_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
  if (m_msg != msg)
    m_msg = msg;
  if (notify && m_parent)
    m_parent->OnChildNotify(this);
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

void FollowQuoteInstruction::OnChildNotify(TradeAgent* child) {
  m_logger.With("child", reinterpret_cast<int64_t>(this)).Info("OnChildNotify");

  auto auto_open_close_instruction = static_cast<AutoOpenCloseInstruction*>(child);
  if (auto_open_close_instruction) {
    auto order_nodes = auto_open_close_instruction->GetOrderNodes();
    m_order_nodes_set.merge(order_nodes);
  }

  if (m_instruction) {
    RefreshVolumeTraded(m_instruction);
    if (m_instruction->GetStatus() == AgentStatus::kStopped) {
      if (!m_instruction->GetMsg().empty())
        ChangeStatus(true, AgentStatus::kPaused, m_instruction->GetMsg());
      m_instruction.reset();
    }
  }
  if (!m_instruction && !m_lame_send && m_market_lame) {
    // 下单
    InsertOrderPrice order_price;
    order_price.advanced_limit = AdvancedLimitPrice::kVolumeFak;
    order_price.order_price_type = InsertOrderPriceType::kBestPrice;
    order_price.price_over = m_market_price_over;
    m_last_volume_left = VolumeLeft();
    m_last_traded_amount = 0;
    m_instruction = m_child_factory(this, VolumeLeft(), order_price);
    m_childs.push_back(m_instruction);
    m_instruction->Run();
    m_lame_send = true;
  }
  // 已补单 但是场上已没有挂单 说明补单已经完成或被撤单 此时停止补单状态
  if (!m_instruction && m_lame_send) {
    m_market_lame = false;
  }
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
}

