void FollowQuoteInstruction::Init() {
  if (m_status == AgentStatus::kStopped) {
    return;
  }
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (future::Direction::kInvalid == m_direction) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 买卖方向无效");
    return;
  }
  if (!m_ins_node || !m_ins_node->Latest()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 交易合约无效");
    return;
  }

  m_max_volume = m_ins_node->Latest()->instrument_base->max_limit_order_volume;
  m_logger.With("max_volume", m_max_volume).Info("Init");

  // 初始化参数
  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少交易所信息");
    return;
  }

  if (m_insert_datetime <= 0) {
    m_insert_datetime = m_exchange_node->Snap()->GetDateTime();
  }
  // 初始化 m_input_params
  m_input_params.direction = m_direction;
  m_input_params.split_params = m_split_params;
  m_input_params.ins_node = m_ins_node;
  m_input_params.volume = m_volume_total;
  auto symbol = m_ins_node->Snap()->symbol;
  m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
    symbol, false, [symbol](std::shared_ptr<const md::Instrument> ins) {
      return ins->symbol == symbol;
    });
  if (m_max_volume <= 0) {
    ChangeStatus(false, AgentStatus::kStopped, "fclib: 合约最大下单手数为 0");
    return;
  }
  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit(
    "DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode>, bool) {
      if (m_status == AgentStatus::kStopped && m_ins_view) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        m_ins_view.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });
}
bool FollowQuoteInstruction::IsOrderInsertable() {
  if (!CheckTradingTime(m_ins_node, m_exchange_node->Snap()->GetDateTime())
    || !CheckTradingTime(m_ins_node, m_exchange_node->Snap()->GetDateTime() + 500000000))
    return false;
  return true;
}

void FollowQuoteInstruction::ChangeParamsVolume(int volume) {
  m_logger.With("volume", volume).With("status", static_cast<int>(m_status)).Info("ChangeParamsVolume");
  if (m_status == AgentStatus::kStopped)
    return;
  if (volume <= 0)
    return;
  Pause();
  int volume_total = VolumeTotal();
  int volume_left = VolumeLeft();
  int volume_traded = volume_total - volume_left;
  m_logger.With("volume_total", volume_total).With("volume_left", volume_left).Info("ChangeParamsVolume");
  if (volume_traded >= volume)
    return;
  m_volume = volume - volume_traded;
  m_volume_total = volume;
}

