const future::SubPosition* GetCloseSubPosition(
  const SwapOrderParams& params, std::shared_ptr<const future::PositionNode> position_node) {
  if (params.params.direction == future::Direction::kSell) {
    if (params.params.hedge_type == future::PositionHedgeType::kSpeculation)
      return &position_node->Snap()->subpos_long_spec;
    else
      return &position_node->Snap()->subpos_long_other;
  } else {
    if (params.params.hedge_type == future::PositionHedgeType::kSpeculation)
      return &position_node->Snap()->subpos_short_spec;
    else
      return &position_node->Snap()->subpos_short_other;
  }
  return nullptr;
}

bool CheckTradingTime(std::shared_ptr<md::InstrumentNode> ins_node, md::EpochNano nano_time) {
  auto time_table = InstrumentTradingTime::Instance().GetTradingTimeTable(ins_node->Snap());
  auto time_t = EpochNanoToLocalDateTime(nano_time, 8);
  auto time_index = time_t.date_time.tm_hour * 10000 + time_t.date_time.tm_min * 100 + time_t.date_time.tm_sec;
  auto it = time_table.upper_bound(time_index);
  if (it == time_table.end() || it->second == true)
    return false;
  return true;
}

future::OrderHedgeFlag ConvertHedgeFlag(const future::PositionHedgeType& hedge) {
  if (hedge == future::PositionHedgeType::kSpeculation)
    return future::OrderHedgeFlag::kSpeculation;
  else if (hedge == future::PositionHedgeType::kHedge)
    return future::OrderHedgeFlag::kHedge;
  else
    return future::OrderHedgeFlag::kArbitrage;
}

InsertOrderPrice GetInsertOrderPrice(
  const InsertOrderPriceType& type, const AdvancedLimitPrice& advanced, double limit_price) {
  InsertOrderPrice insert_order_price;
  insert_order_price.order_price_type = type;
  insert_order_price.advanced_limit = advanced;
  if (type == InsertOrderPriceType::kLimitPrice)
    insert_order_price.limit_price = limit_price;
  return insert_order_price;
}

double GetBestOverPrice(const SwapOrderParams& swap_params) {
  auto open_ins_node = swap_params.target_params.ins_node;
  bool buy = swap_params.target_params.direction == future::Direction::kBuy;
  double over = swap_params.price_over * open_ins_node->Latest()->PriceTick() * (buy ? 1 : -1);
  double calc_price = (buy ? open_ins_node->Latest()->GetAskPrice() : open_ins_node->Latest()->GetBidPrice()) + over;
  if (calc_price > open_ins_node->Snap()->upper_limit)
    calc_price = open_ins_node->Snap()->upper_limit;
  if (calc_price < open_ins_node->Snap()->lower_limit)
    calc_price = open_ins_node->Snap()->lower_limit;
  return calc_price;
}

