void SwapOrderInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");

  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;
  // 启动移仓换月, 错误信息清空
  ChangeStatus(true, AgentStatus::kStarted, "");
  // 每次启动开仓价应为对价
  m_open_price_type = InsertOrderPriceType::kBestPrice;
  InsertOrder();
  // 行情驱动后续下单
  m_ins_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins, bool is_last) {
      if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      InsertOrder();
    });
}

void SwapOrderInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  // 非运行中状态不操作
  if (m_status != AgentStatus::kStarted)
    return;
  // 停止 view 跟踪
  m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  ChangeStatus(true, AgentStatus::kPaused, m_msg);
}

