  return close_ins->Snap()->ask_price[0] - open_ins->Snap()->bid_price[0];
}

int SwapOrderInstruction::GetRealTimeVolume(std::shared_ptr<md::InstrumentNode> close_ins,
  std::shared_ptr<md::InstrumentNode> open_ins, const future::Direction& close_direction) {
  if (close_direction == future::Direction::kSell)
    return std::min(close_ins->Snap()->bid_volume[0], open_ins->Snap()->ask_volume[0]);
  return std::min(close_ins->Snap()->ask_volume[0], open_ins->Snap()->bid_volume[0]);
}

bool SwapOrderInstruction::CheckCZCEPosition(const SwapParams& params) {
  // 非郑商所 无需检查
  if (params.ins_node->Snap()->ExchangeID() != "CZCE")
    return true;
  // 投机头寸 无需检查
  if (params.hedge_type == future::PositionHedgeType::kSpeculation)
    return true;
  auto position_key = future::Position::MakeKey(params.user_key, 0, params.ins_node->Snap()->symbol);
  auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(position_key);
  if (!position_node)
    return true;
  auto spec_subpos = (params.direction == future::Direction::kSell) ? position_node->Snap()->subpos_long_spec
                                                                    : position_node->Snap()->subpos_short_spec;
  return (spec_subpos.Volume() > 0) ? false : true;
}

bool SwapOrderInstruction::IsSpreadSwapOrder(const SwapOrderParams& params) {
  return !isnan(params.price_spread);
}

std::shared_ptr<SwapOrderInstruction> SwapOrderInstruction::LoadInstruction(
  TradeAgent* parent, const std::string& params) {
  auto params_pack = SerializeToVar<SwapOrderParamsPack>(params);
  auto close_ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(params_pack.close_symbol);
  auto open_ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(params_pack.open_symbol);
  // 合约缺失, 不构建(例 合约下市 等)
  if (!close_ins_node || !open_ins_node)
    return nullptr;
  // 填充合约节点
  params_pack.swap_order_params.params.ins_node = close_ins_node;
  params_pack.swap_order_params.target_params.ins_node = open_ins_node;
  return std::make_shared<SwapOrderInstruction>(parent, params_pack);
}

void SwapOrderInstruction::Init(bool is_load /* = false*/) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (!is_load) {
    m_insert_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
    m_stop_datetime = 0;
  }
  if (!IsSwapParamsValid()) {
    m_status = AgentStatus::kStopped;
    m_stop_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
    return;
  }
  auto close_ins_node = m_swap_params.params.ins_node;
  auto open_ins_node = m_swap_params.target_params.ins_node;
  m_close_position = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
    future::Position::MakeKey(m_swap_params.params.user_key, 0, close_ins_node->Snap()->symbol));

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);

  std::string ins_key = close_ins_node->Snap()->symbol + open_ins_node->Snap()->symbol;
  m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
    ins_key, false, [close_ins_node, open_ins_node](std::shared_ptr<const md::Instrument> ins) {
      return ins->symbol == close_ins_node->Snap()->symbol || ins->symbol == open_ins_node->Snap()->symbol;
    });
  m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_ins_view && m_status == AgentStatus::kStopped) {
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        m_ins_view.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });

  m_open_price_type = InsertOrderPriceType::kBestPrice;

  // 实时处理委托单
  m_exchange_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status != AgentStatus::kStopped)
        ProcessOrder();
      else
        m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
    });
}

bool SwapOrderInstruction::IsSwapParamsValid() {
  if (!TradeAgent::GetTqApi()) {
    m_msg = u8"fclib: 缺少api信息";
    return false;
  }
  m_exchange_node =
    TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>(m_swap_params.params.ins_node->Snap()->ExchangeID());
  if (!m_exchange_node) {
    m_msg = u8"fclib: 缺少交易所信息";
    return false;
  }
  if (!m_swap_params.params.ins_node) {
    m_msg = u8"fclib: 缺少移仓合约信息";
    return false;
  }
  if (!m_swap_params.target_params.ins_node) {
    m_msg = u8"fclib: 缺少开仓合约信息";
    return false;
  }
  if (m_swap_params.params.direction == future::Direction::kInvalid) {
    m_msg = u8"fclib: 缺少移仓买卖方向信息";
    return false;
  }
  if (m_swap_params.target_params.direction == future::Direction::kInvalid) {
    m_msg = u8"fclib: 缺少开仓买卖方向信息";
    return false;
  }
  return true;
}

int SwapOrderInstruction::CalcCloseVolume() {
  // 检查持仓
  if (!m_close_position) {
    m_close_position = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
      future::Position::MakeKey(m_swap_params.params.user_key, 0, m_swap_params.params.ins_node->Snap()->symbol));
    if (!m_close_position) {
      m_msg = u8"fclib: 移仓合约持仓手数不足";
      return 0;
    }
  }
  auto subpos = GetCloseSubPosition(m_swap_params, m_close_position);
  if (subpos->VolumeAvail() <= 0) {
    m_msg = u8"fclib: 移仓合约持仓手数不足";
    return 0;
  }
  // 计算理论平仓手数
  int volume = std::min(m_close_volume_left, std::min(m_swap_params.volume_limit, subpos->Volume()));
  int ins_volume = (m_swap_params.params.direction == future::Direction::kSell)
    ? m_swap_params.params.ins_node->Snap()->bid_volume[0]
    : m_swap_params.params.ins_node->Snap()->ask_volume[0];
  if (ins_volume <= 0) {
    m_msg = u8"fclib: 移仓合约无对手盘";
    return 0;
  }
  volume = std::min(volume, ins_volume);
  // 合约限价单最大下单量限制
  if (m_swap_params.params.ins_node->Snap()->instrument_base->max_limit_order_volume > 0)
    volume = std::min(volume, m_swap_params.params.ins_node->Snap()->instrument_base->max_limit_order_volume);

  if (!m_swap_params.params.ins_node->Snap()->HasCloseToday()) {
    m_close_offset = future::Offset::kClose;
    return volume;
  }
  // 加入平今平昨判断, 使用总持仓, 非可用持仓
  if (CloseTodayBeforeYesterDay(m_swap_params.params.ins_node, m_swap_params.params.user_key)) {
    if (subpos->volume_today > 0) {
      m_close_offset = future::Offset::kCloseToday;
      return std::min(volume, subpos->volume_today);
    }
    m_close_offset = future::Offset::kClose;
    return std::min(volume, subpos->volume_his);
  } else {
    if (subpos->volume_his > 0) {
      m_close_offset = future::Offset::kClose;
      return std::min(volume, subpos->volume_his);
    }
    m_close_offset = future::Offset::kCloseToday;
    return std::min(volume, subpos->volume_today);
  }
}

bool SwapOrderInstruction::IsSpreadMet(double price) {
  if (isnan(m_swap_params.price_spread))
    return false;
  auto close_direction = m_swap_params.params.direction;
  if (close_direction == future::Direction::kInvalid)
    return false;
  double quote_spread = NAN;
  if (isnan(price)) {
    quote_spread =
      GetRealTimeSpread(m_swap_params.params.ins_node, m_swap_params.target_params.ins_node, close_direction);
  } else {
    quote_spread = (close_direction == future::Direction::kBuy)
      ? price - m_swap_params.target_params.ins_node->Snap()->bid_price[0]
      : price - m_swap_params.target_params.ins_node->Snap()->ask_price[0];
  }
  if (isnan(quote_spread))
    return false;
  // 移仓合约为卖出平仓多头时, 委托价差 <= 实时价差触发移仓指令
  // 移仓合约为买入平仓空头时, 委托价差 >= 实时价差触发移仓指令
  return (close_direction == future::Direction::kSell) ? m_swap_params.price_spread <= quote_spread
                                                       : m_swap_params.price_spread >= quote_spread;
}

void SwapOrderInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;
  // 运行中, 停止时间归0
  if (m_status == AgentStatus::kStarted) {
    m_stop_datetime = 0;
  } else {
    m_stop_datetime = m_exchange_node ? m_exchange_node->Snap()->GetDateTime() : NowAsEpochNano();
  }
  if (m_msg != msg)
    m_msg = msg;
  if (notify && m_parent)
    m_parent->OnChildNotify(this);
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

/*
 * 移仓换月下单
 * 开仓剩余手数 > 平仓剩余手数 ->开仓
 * 开仓剩余手数 = 平仓剩余手数 ->平仓
 */
void SwapOrderInstruction::InsertOrder() {
  if (m_open_volume_left > m_close_volume_left) {
    InsertOpenOrder();
  } else if (m_open_volume_left == m_close_volume_left) {
    InsertCloseOrder();
  }
}

void SwapOrderInstruction::InsertOpenOrder() {
  // 已进行下单, 等待下单指令完成
  if (m_close_instruction || m_open_instruction)
    return;
  m_logger.With("open_left", m_open_volume_left)
    .With("close_left", m_close_volume_left)
    .With("open_average", m_open_average_price)
    .With("close_averag", m_close_average_price)
    .Info("InsertOpenOrder");
  auto ins = m_swap_params.target_params.ins_node;
  FCASSERT(ins);
  // 判断行情时间是否在交易时间段内, 非交易时段不作任何处理
  if (!CheckTradingTime(ins, ins->Snap()->exchange_time)
    || !CheckTradingTime(ins, ins->Snap()->exchange_time + 500000000))
    return;
  // 开仓合约对手盘检查
  int ins_volume = (m_swap_params.target_params.direction == future::Direction::kSell) ? ins->Snap()->bid_volume[0]
                                                                                       : ins->Snap()->ask_volume[0];
  if (ins_volume <= 0) {
    ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 开仓合约无对手盘");
    return;
  }
  // 价差不满足, 市价追单
  if (IsSpreadSwapOrder(m_swap_params) && !IsSpreadMet(m_close_trade_price))
    m_open_price_type = (m_swap_params.track_type == SwapTrackType::kMarket) ? InsertOrderPriceType::kMarketPrice
                                                                             : InsertOrderPriceType::kLimitPrice;
  // 构建开仓下单指令
  auto open_volume = m_open_volume_left - m_close_volume_left;
  m_open_instruction = std::make_shared<OrderInstruction>(this, m_swap_params.target_params.user_key, ins,
    m_swap_params.target_params.direction, future::Offset::kOpen,
    ConvertHedgeFlag(m_swap_params.target_params.hedge_type), open_volume,
    GetInsertOrderPrice(m_open_price_type, AdvancedLimitPrice::kVolumeFak, GetBestOverPrice(m_swap_params)),
    m_request_id);
  m_open_instruction->Run();
  m_childs.push_back(m_open_instruction);
}

void SwapOrderInstruction::InsertCloseOrder() {
  // 移仓完成, 跳过
  if (m_close_volume_left <= 0) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
    return;
  }
  // 已进行下单, 等待下单指令完成
  if (m_close_instruction || m_open_instruction)
    return;
  m_logger.With("open_left", m_open_volume_left)
    .With("close_left", m_close_volume_left)
    .With("open_average", m_open_average_price)
    .With("close_averag", m_close_average_price)
    .Info("InsertCloseOrder");
  auto ins = m_swap_params.params.ins_node;
  FCASSERT(ins);
  // 非交易时段不作任何处理
  if (!CheckTradingTime(ins, ins->Snap()->exchange_time)
    || !CheckTradingTime(ins, ins->Snap()->exchange_time + 500000000))
    return;
  if (IsSpreadSwapOrder(m_swap_params)) {
    // 价差不满足, 跳过
    if (!IsSpreadMet())
      return;
  } else {
    // 移仓间隔不满足, 跳过
    if (ins->Snap()->exchange_time - m_last_time < static_cast<int64_t>(m_swap_params.swap_interval) * 1000000000)
      return;
  }
  // 平仓: 作持仓检查
  if (!CheckCZCEPosition(m_swap_params.params)) {
    ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 用户持有郑商所投机仓位时, 无法先对保值仓位进行移仓");
    return;
  }
  auto close_volume = CalcCloseVolume();
  // 平仓手数有误
  if (close_volume <= 0) {
    ChangeStatus(true, AgentStatus::kPaused, m_msg);
    return;
  }
  // 改价差
  if (!isnan(m_change_spread)) {
    m_swap_params.price_spread = m_change_spread;
    m_change_spread = NAN;
  }

  m_close_instruction = std::make_shared<OrderInstruction>(this, m_swap_params.params.user_key, ins,
    m_swap_params.params.direction, m_close_offset, ConvertHedgeFlag(m_swap_params.params.hedge_type), close_volume,
    GetInsertOrderPrice(InsertOrderPriceType::kBestPrice, AdvancedLimitPrice::kVolumeFak, 0.0), m_request_id);
  m_close_instruction->Run();
  m_childs.push_back(m_close_instruction);
}

void SwapOrderInstruction::ProcessOrder() {
  if (m_open_instruction && m_open_instruction->GetStatus() == AgentStatus::kStopped) {
    ProcessOpenOrder();
  } else if (m_close_instruction && m_close_instruction->GetStatus() == AgentStatus::kStopped) {
    ProcessCloseOrder();
  }
  if (m_close_volume_left <= 0 && m_open_volume_left <= 0)
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
}

void SwapOrderInstruction::ProcessOpenOrder() {
  m_logger.Info("ProcessOpenOrder");
  auto order_node = m_open_instruction->GetOrderNode();
  // 处理错单
  if (!order_node || order_node->Snap()->exchange_order_id.empty()) {
    std::string result_msg =
      (m_open_instruction->GetMsg().empty()) ? u8"fclib: 移仓换月开仓错误" : m_open_instruction->GetMsg();
    ChangeStatus(true, AgentStatus::kPaused, result_msg);
    m_open_instruction.reset();
    return;
  }
  if (order_node->Snap()->VolumeTrade() > 0) {
    if (!order_node->Snap()->IsTradeReady())
      return;
    // 更新成交均价和剩余手数
    auto volume_prev = m_swap_params.volume - m_open_volume_left;
    m_open_average_price = (isnan(m_open_average_price)) ? 0.0 : m_open_average_price;
    m_open_average_price =
      (order_node->Snap()->trade_price * order_node->Snap()->VolumeTrade() + m_open_average_price * volume_prev)
      / (volume_prev + order_node->Snap()->VolumeTrade());
    m_open_volume_left -= order_node->Snap()->VolumeTrade();
    m_logger.With("volume_trade", order_node->Snap()->VolumeTrade())
      .With("open_trade_price", order_node->Snap()->trade_price)
      .With("open_average_price", m_open_average_price)
      .Info("ProcessOpenOrder");
    if (m_parent)
      m_parent->OnChildNotify(this);
    if (m_call_back)
      m_call_back(shared_from_this());
  }
  if (IsSpreadSwapOrder(m_swap_params)) {
    if (m_open_volume_left != m_close_volume_left) {
      if (m_open_price_type == InsertOrderPriceType::kMarketPrice
        || m_open_price_type == InsertOrderPriceType::kLimitPrice) {
        ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 追单未全部成交");
      } else {
        m_open_price_type = (m_swap_params.track_type == SwapTrackType::kMarket) ? InsertOrderPriceType::kMarketPrice
                                                                                 : InsertOrderPriceType::kLimitPrice;
      }
    }
  } else if (m_open_volume_left == m_close_volume_left) {
    m_last_time = m_exchange_node->Snap()->GetDateTime();
  }
  m_open_instruction.reset();
}

void SwapOrderInstruction::ProcessCloseOrder() {
  m_logger.Info("ProcessCloseOrder");
  auto order_node = m_close_instruction->GetOrderNode();
  if (!order_node || order_node->Snap()->exchange_order_id.empty()) {
    std::string result_msg =
      (m_close_instruction->GetMsg().empty()) ? u8"fclib: 移仓换月平仓错误" : m_close_instruction->GetMsg();
    ChangeStatus(true, AgentStatus::kPaused, result_msg);
  } else if (order_node->Snap()->VolumeTrade() > 0) {
    if (!order_node->Snap()->IsTradeReady())
      return;
    // 更新成交均价和剩余手数
    auto volume_prev = m_swap_params.volume - m_close_volume_left;
    m_close_trade_price = order_node->Snap()->trade_price;
    m_close_average_price = (isnan(m_close_average_price)) ? 0.0 : m_close_average_price;
    m_close_average_price =
      (m_close_trade_price * order_node->Snap()->VolumeTrade() + m_close_average_price * volume_prev)
      / (volume_prev + order_node->Snap()->VolumeTrade());
    m_close_volume_left -= order_node->Snap()->VolumeTrade();
    m_open_price_type = InsertOrderPriceType::kBestPrice;
    m_logger.With("volume_trade", order_node->Snap()->VolumeTrade())
      .With("close_trade_price", m_close_trade_price)
      .With("close_average_price", m_close_average_price)
      .Info("ProcessCloseOrder");
    if (m_parent)
      m_parent->OnChildNotify(this);
    if (m_call_back)
      m_call_back(shared_from_this());
  }
  m_close_instruction.reset();
}

