void GetCancelOrderList(const std::shared_ptr<md::InstrumentNode> ins_node, const std::string& user_key,
  const future::Direction& direction, bool is_swap, std::function<void(std::shared_ptr<future::OrderNode>)> fun) {
  auto alive_order_view = TradeAgent::GetTqApi()->DataDb()->CreateView<future::Order>(ReuseViewKey::kAliveOrder);
  for (auto& [order_id, order] : alive_order_view->GetNodes()) {
    if (order->Latest()->ins_pointer == ins_node && order->Latest()->direction == direction
      && order->Latest()->user_key == user_key && order->Latest()->is_swap_order == is_swap)
      fun(order);
  }
}

CancelOrderInstruction::CancelOrderInstruction(TradeAgent* parent, const std::vector<CancelOrderParams>& params,
  bool cancel_order, std::function<std::shared_ptr<TradeInstruction>(TradeAgent*)> child_factory)
  : m_params(params)
  , m_cancel_order(cancel_order)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("cancel_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("cancel_order", GetAgentIndex()).Clone()) {
  m_parent = parent;

  m_logger.With("cancel", cancel_order).Info("Constructor");

  if (child_factory)
    m_child = child_factory(this);
  if (!m_cancel_order)
    return;
  m_canceled = false;
  RefreshCancelOrders();
}

CancelOrderInstruction::CancelOrderInstruction(TradeAgent* parent, const CancelOrderInstructionPack& pack)
  : m_params(pack.params)
  , m_cancel_order(pack.cancel_order)
  , m_canceled(pack.canceled)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("cancel_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("cancel_order", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_instruction_memo = pack.memo;

  m_logger.With("cancel", m_cancel_order).With("canceled", m_canceled).Info("LoadConstructor");
  if (!m_cancel_order)
    return;
  RefreshCancelOrders();
}

