void CancelOrderInstruction::Run() {
  m_logger.With("cancel_order", m_cancel_order).With("canceled", m_canceled).Info("Run");

  // 无需撤单或已撤单
  if (!m_cancel_order || m_canceled) {
    // 有且仅有无待撤委托时, 运行子指令.
    if (m_child && m_cancel_orders.empty())
      m_child->Run();
    return;
  }
  CancelOrder(true);
}

void CancelOrderInstruction::Start() {
  m_logger.With("cancel_order", m_cancel_order).With("canceled", m_canceled).Info("Start");

  // 无需撤单或已撤单
  if (!m_cancel_order || m_canceled) {
    // 有且仅有无待撤委托时, 运行子指令.
    if (m_child && m_cancel_orders.empty())
      m_child->Start();
    return;
  }
  CancelOrder(false);
}

void CancelOrderInstruction::Pause() {
  m_logger.Info("Pause");

  if (m_child)
    m_child->Pause();
}

void CancelOrderInstruction::Stop() {
  m_logger.Info("Stop");

  if (m_child)
    m_child->Stop();
}

AgentStatus CancelOrderInstruction::GetStatus() const {
  if (m_child)
    return m_child->GetStatus();
  return AgentStatus::kPaused;
}

std::string CancelOrderInstruction::GetMsg() const {
  if (m_child)
    return m_child->GetMsg();
  return "";
}

structlog::Logger* CancelOrderInstruction::GetLogger() {
  return &m_logger;
}

int CancelOrderInstruction::VolumeTotal() {
  if (m_child)
    return m_child->VolumeTotal();
  return 0;
}

int CancelOrderInstruction::VolumeLeft() {
  if (m_child)
    return m_child->VolumeLeft();
  return 0;
}

double CancelOrderInstruction::TradeAmount() {
  if (m_child)
    return m_child->TradeAmount();
  return 0.0;
}

void CancelOrderInstruction::ChangeOrderPrice(const ChangePriceParams& params, int request_id) {
  if (m_child)
    m_child->ChangeOrderPrice(params, request_id);
}

void CancelOrderInstruction::RefreshCancelOrders() {
  if (m_canceled)
    return;
  m_cancel_orders.clear();
  m_cancel_order_volumes.clear();
  for (const auto& param : m_params) {
    FCASSERT(param.ins_node);
    for (const auto& user_key : param.user_key_list) {
      GetCancelOrderList(
        param.ins_node, user_key, param.direction, param.is_swap, [=](std::shared_ptr<future::OrderNode> node) {
          m_cancel_orders.insert(node);
          m_cancel_order_volumes[param.ins_node->Latest()->symbol][user_key] += node->Latest()->volume_left;
        });
    }
  }
}

std::string CancelOrderInstruction::SaveInstruction() {
  Pause();
  CancelOrderInstructionPack pack;
  pack.params = m_params;
  pack.cancel_order = m_cancel_order;
  pack.canceled = m_canceled;
  pack.memo = m_instruction_memo;
  for (const auto& p : m_params) {
    FCASSERT(p.ins_node);
    pack.symbols.push_back(p.ins_node->Latest()->symbol);
  }
  if (m_child)
    pack.child = m_child->SaveInstruction();
  return SerializeToString(pack);
}

std::shared_ptr<CancelOrderInstruction> CancelOrderInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&)> load_factory) {
  auto pack = SerializeToVar<CancelOrderInstructionPack>(params);
  FCASSERT(pack.symbols.size() == pack.params.size());
  for (size_t i = 0; i < pack.symbols.size(); ++i) {
    auto ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(pack.symbols[i]);
    if (nullptr == ins_node)
      return nullptr;
    pack.params[i].ins_node = ins_node;
  }
  auto instruction = std::make_shared<CancelOrderInstruction>(parent, pack);
  auto child = load_factory(instruction.get(), pack.child);
  if (!child)
    return nullptr;
  instruction->m_child = child;
  return instruction;
}

void CancelOrderInstruction::CancelOrder(bool run) {
  if (!m_cancel_order || m_canceled)
    return;
  RefreshCancelOrders();
  m_canceled = true;
  auto nodes = m_cancel_orders;
  for (const auto& node : nodes) {
    if (node->Latest()->status != future::OrderStatus::kAlive) {
      m_cancel_orders.erase(node);
      continue;
    }
    const auto user_key = node->Latest()->UserKey();
    const auto& order_id = node->Latest()->order_id;

    m_logger.With("user_key", user_key).With("order_id", order_id).Info("CancelOrder");
    auto request = std::make_shared<future::CancelOrder>(user_key);
    request->order_id = order_id;

    TradeAgent::GetTqApi()->AsyncRequest(request, [this, node, run](std::shared_ptr<UserCommand> cmd) {
      auto cancel_request = std::static_pointer_cast<future::CancelOrder>(cmd);
      m_logger.With("result_code", cancel_request->result_code)
        .With("result_msg", cancel_request->result_msg)
        .With("user_key", cancel_request->user_key)
        .With("order_id", cancel_request->order_id)
        .Info("CancelOrder");

      if (cancel_request->status == UserCommand::Status::kFinished) {
        m_cancel_orders.erase(node);
        if (m_cancel_orders.empty())
          run ? Run() : Start();
      }
    });
  }
  if (m_cancel_orders.empty()) {
    run ? Run() : Start();
    return;
  }
}

