future::Direction DirNegative(future::Direction dir) {
  if (dir == future::Direction::kBuy)
    return future::Direction::kSell;
  if (dir == future::Direction::kSell)
    return future::Direction::kBuy;
  return future::Direction::kInvalid;
}

ClosePositionAgent::ClosePositionAgent(const std::vector<std::string>& user_key_list, InsertOrderPriceType price_type)
  : m_user_key_list(user_key_list)
  , m_price_type(price_type) {
  Init();
}

ClosePositionAgent::~ClosePositionAgent() {}

void ClosePositionAgent::Init() {
  struct PositionSummaryItem {
    std::shared_ptr<md::InstrumentNode> ins_node;
    future::Direction direction;
    future::PositionHedgeType hedge;
    PositionSummaryItem(
      std::shared_ptr<md::InstrumentNode> _ins_node, future::Direction _direction, future::PositionHedgeType _hedge)
      : ins_node(_ins_node)
      , direction(_direction)
      , hedge(_hedge) {}
    int64_t Key() const {
      return (reinterpret_cast<int64_t>(ins_node.get()) << 8) + (static_cast<int64_t>(direction) << 4)
        + static_cast<int64_t>(hedge);
    }
    bool operator<(const PositionSummaryItem& other) const {
      return Key() < other.Key();
    }
  };
  std::map<PositionSummaryItem, int> volume_map;
  auto position_node_map = TradeAgent::GetTqApi()->DataDb()->GetNodeMap<future::Position>();
  for (auto& [key, position_node] : position_node_map) {
    if (std::find(m_user_key_list.begin(), m_user_key_list.end(), position_node->Snap()->UserKey())
      == m_user_key_list.end())
      continue;
    for (auto p : {&fclib::future::Position::subpos_long_spec, &fclib::future::Position::subpos_short_spec,
           &fclib::future::Position::subpos_long_other, &fclib::future::Position::subpos_short_other}) {
      auto sub_pos = &((*position_node->Snap()).*p);
      if (sub_pos->Volume() > 0) {
        PositionSummaryItem item(position_node->Snap()->ins_pointer, sub_pos->direction, sub_pos->hedge_type);
        volume_map[item] += sub_pos->Volume();
      }
    }
  }

  for (auto& [item, volume] : volume_map) {
    auto direction = DirNegative(item.direction);
    auto hedge = future::OrderHedgeFlag::kSpeculation;
    if (item.hedge == future::PositionHedgeType::kHedge)
      hedge = future::OrderHedgeFlag::kHedge;
    if (item.hedge == future::PositionHedgeType::kArbitrage)
      hedge = future::OrderHedgeFlag::kArbitrage;
    InsertOrderPrice order_price;
    order_price.limit_price = 0;  // todo: 取对手价+超价
    if (m_price_type == InsertOrderPriceType::kMarketPrice) {
      order_price.order_price_type = InsertOrderPriceType::kMarketPrice;
    } else if (m_price_type == InsertOrderPriceType::kBestPrice) {
      order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
      if (direction == future::Direction::kBuy) {
        order_price.limit_price = item.ins_node->Snap()->ask_price[0] + item.ins_node->Snap()->PriceTick() * 1;
      } else {
        order_price.limit_price = item.ins_node->Snap()->bid_price[0] - item.ins_node->Snap()->PriceTick() * 1;
      }
    }
    InsertOrderParams params;
    params.user_key_list = m_user_key_list;
    params.volume_allocate_strategy = InsertOrderStrategy::kTotalAvailableAvailable;
    params.ins_node = item.ins_node;
    params.direction = direction;
    params.hedge = hedge;
    params.volume = volume;
    params.cancel_order = true;
    if (item.ins_node->Latest()->HasCloseToday())
      params.split_offset = SplitOffset::kCloseBoth;
    else
      params.split_offset = SplitOffset::kClose;
    params.order_price = order_price;
    params.is_swap = false;

    auto x = VolumeSplitInstruction::Create(this, params, [=](TradeAgent* p1, const std::vector<int>& plans) {
      return std::make_shared<InsertOrderInstruction>(
        p1, params, plans, [=](TradeAgent* p2, const std::string& user_key, int volume, int request_id) {
          return std::make_shared<AutoOpenCloseInstruction>(p2, user_key, params.ins_node, params.split_offset,
            params.direction, params.hedge, order_price, params.is_swap, volume, request_id);
        });
    });

    m_childs.push_back(x);
  }
}

void ClosePositionAgent::Run() {
  for (auto c : m_childs)
    c->Run();
}

void ClosePositionAgent::Stop() {}

void ClosePositionAgent::Start() {}

void ClosePositionAgent::Pause() {}

AgentStatus ClosePositionAgent::GetStatus() const {
  return AgentStatus::kStopped;
}

std::string ClosePositionAgent::GetMsg() const {
  return "";
}

structlog::Logger* ClosePositionAgent::GetLogger() {
  return nullptr;
}

