CombOrderRule1::CombOrderRule1(TradeAgent* parent, const InsertOrderParams& insert_params,
  const CombOrderParams& comb_params, const std::string& user_key, int volume,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, std::shared_ptr<md::InstrumentNode>, int,
    const future::Direction&, const future::OrderHedgeFlag&, const InsertOrderPrice&)>
    child_factory)
  : m_insert_params(insert_params)
  , m_comb_params(comb_params)
  , m_user_key(user_key)
  , m_volume(volume)
  , m_child_factory(child_factory)
  , m_status(AgentStatus::kPaused)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("comb_order_rule1", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("comb_order_rule1", GetAgentIndex()).Clone()) {
  m_parent = parent;

  m_logger.With("insert_params", SerializeToString(m_insert_params))
    .With("comb_params", SerializeToString(m_comb_params))
    .With("user_key", m_user_key)
    .With("volume", m_volume)
    .Info("Constructor");

  Init();
}

CombOrderRule1::CombOrderRule1(TradeAgent* parent, const CombOrderParamsPack& params_pack,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, std::shared_ptr<md::InstrumentNode>, int,
    const future::Direction&, const future::OrderHedgeFlag&, const InsertOrderPrice&)>
    child_factory)
  : m_insert_params(params_pack.insert_params)
  , m_comb_params(params_pack.comb_params)
  , m_user_key(params_pack.user_key)
  , m_volume(params_pack.volume)
  , m_child_factory(child_factory)
  , m_status(params_pack.status)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("comb_order_rule1", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("comb_order_rule1", GetAgentIndex()).Clone())
  , m_insert_datetime(params_pack.insert_datetime)
  , m_trigger_datetime(params_pack.trigger_datetime)
  , m_stop_datetime(params_pack.stop_datetime)
  , m_msg(params_pack.msg) {
  m_parent = parent;
  m_instruction_memo = params_pack.memo;

  if (!params_pack.comb_plan.empty())
    m_comb_plan = params_pack.comb_plan[0];

  m_ins_total_volume = params_pack.ins_total_volume;
  m_ins_volume_left = params_pack.ins_volume_left;
  m_average_price = params_pack.average_price;
  m_comb_average_price = params_pack.comb_average_price;
  m_is_insert = params_pack.is_insert;

  m_logger.With("params_pack", SerializeToString(params_pack)).Info("LoadConstructor");

  Init(true);
}

void CombOrderRule1::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");
}

void CombOrderRule1::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");
  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;

  // 启动组合单
  ChangeStatus(true, AgentStatus::kStarted, "");
  InsertOrder();
  // 行情驱动后续下单
  m_calc->SetCallBack("InsertOrder", [this]() {
    if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
      m_calc->CancelCallBack("InsertOrder");
      return;
    }
    InsertOrder();
  });
}

void CombOrderRule1::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");
  if (m_status == AgentStatus::kPaused || m_status == AgentStatus::kStopped)
    return;

  // 报单后不可暂停
  // 非已启动不可暂停
  if (m_is_insert || m_status != AgentStatus::kStarted)
    return;

  ChangeStatus(true, AgentStatus::kPaused, m_msg);
  // 停止 view 跟踪
  m_calc->CancelCallBack("InsertOrder");
}

void CombOrderRule1::Stop() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Stop");
}

AgentStatus CombOrderRule1::GetStatus() const {
  return m_status;
}

int CombOrderRule1::VolumeTotal() {
  int ret = 0;
  for (const auto& params : m_comb_params.params) {
    ret += m_volume * params.volume;
  }
  return ret;
}

int CombOrderRule1::VolumeLeft() {
  int ret = 0;
  for (const auto& plan : m_comb_plan) {
    ret += plan.params.volume;
  }
  return ret;
}

double CombOrderRule1::TradeAmount() {
  return m_comb_average_price * (VolumeTotal() - VolumeLeft());
}

