std::string CombOrderRule1::SaveInstruction() {
  // 暂停
  Pause();
  // 更新存档参数包
  CombOrderParamsPack params_pack;
  params_pack.insert_symbol = m_insert_params.ins_node->Snap()->symbol;
  params_pack.insert_params = m_insert_params;
  params_pack.comb_params = m_comb_params;
  params_pack.user_key = m_user_key;
  params_pack.volume = m_volume;
  params_pack.insert_datetime = m_insert_datetime;
  params_pack.trigger_datetime = m_trigger_datetime;
  params_pack.stop_datetime = m_stop_datetime;
  params_pack.status = m_status;
  params_pack.msg = m_msg;
  params_pack.comb_plan.push_back(m_comb_plan);
  params_pack.ins_total_volume = m_ins_total_volume;
  params_pack.ins_volume_left = m_ins_volume_left;
  params_pack.average_price = m_average_price;
  params_pack.comb_average_price = m_comb_average_price;
  params_pack.is_insert = m_is_insert;
  params_pack.memo = m_instruction_memo;
  // 参数包存档
  TradeAgentSerializer ss;
  std::string res;
  ss.FromVar(params_pack);
  ss.ToString(&res);
  return res;
}

void CombOrderRule1::MarketPriceLame() {
  // 运行中发生错误或者已停止, 无法市价补瘸腿
  if (!m_msg.empty() || m_status == AgentStatus::kStopped)
    return;

  // 非交易时间或者已经市价补瘸腿, 无法市价补瘸腿
  if (!IsInTradingTime(m_comb_params.params) || m_market)
    return;

  if (!IsPositionVolumeValid()) {
    ChangeStatus(true, m_status, u8"fclib: 持仓手数不足, 无法市价补瘸腿");
    return;
  }

  m_market = true;
  for (auto&& plan : m_comb_plan) {
    if (nullptr != plan.instruction)
      plan.instruction->Stop();
  }

  if (InsertMarketOrder())
    return;
  m_calc->SetCallBack("MarketPriceLame", [this]() {
    if (m_status == AgentStatus::kStopped || InsertMarketOrder()) {
      m_calc->CancelCallBack("MarketPriceLame");
      return;
    }
  });
}

double const CombOrderRule1::GetRealPriceDiff() const {
  if (!m_calc)
    return NAN;
  if (m_insert_params.direction == future::Direction::kBuy)
    return m_calc->GetInstrument()->ask_price[0];
  return m_calc->GetInstrument()->bid_price[0];
}

void CombOrderRule1::InsertOrder() {
  if (m_status == AgentStatus::kPaused || m_status == AgentStatus::kStopped) {
    return;
  }

  if (m_is_insert)
    return;
  for (const auto& plan : m_comb_plan) {
    if (nullptr != plan.instruction)
      return;
  }

  if (!IsInTradingTime(m_comb_params.params))
    return;
  if (!IsPriceMet())
    return;

  if (!IsPositionVolumeValid()) {
    ChangeStatus(true, AgentStatus::kPaused, u8"fclib: 持仓手数不足, 无法平仓");
    m_calc->CancelCallBack("InsertOrder");
    return;
  }
  InsertInstruction();
}

InsertOrderPrice CombOrderRule1::GetRuleOrderPrice(const SingleInsParams& params, bool is_market) const {
  if (is_market || m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return GetInsertOrderPrice(InsertOrderPriceType::kMarketPrice, AdvancedLimitPrice::kVolumeFak, 0.0);
  return GetInsertOrderPrice(
    InsertOrderPriceType::kLimitPrice, AdvancedLimitPrice::kVolumeNone, GetBestOverPrice(params));
}

void CombOrderRule1::ConvertPriceType() {
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kLimitPrice
    || m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return;
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return;
  double ask_price = ins->ask_price[0];
  double bid_price = ins->bid_price[0];
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kBestPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? ask_price : bid_price;
  } else if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kHangPrice) {
    m_insert_params.order_price.limit_price =
      (m_insert_params.direction == future::Direction::kBuy) ? bid_price : ask_price;
  } else {
    m_insert_params.order_price.limit_price = ins->last_price;
  }
  m_insert_params.order_price.order_price_type = InsertOrderPriceType::kLimitPrice;
}

// 是否价格满足
bool CombOrderRule1::IsPriceMet() const {
  auto ins = m_calc->GetInstrument();
  if (!ins)
    return false;
  if (m_insert_params.order_price.order_price_type == InsertOrderPriceType::kMarketPrice)
    return true;
  if (m_insert_params.order_price.order_price_type != InsertOrderPriceType::kLimitPrice)
    return false;

  return (m_insert_params.direction == future::Direction::kBuy)
    ? m_insert_params.order_price.limit_price >= ins->ask_price[0]
    : m_insert_params.order_price.limit_price <= ins->bid_price[0];
}

bool CombOrderRule1::IsPositionVolumeValid() const {
  // 开仓跳过检查
  if (m_insert_params.split_offset == SplitOffset::kOpen || m_insert_params.split_offset == SplitOffset::kAuto)
    return true;
  // 平仓检查持仓
  for (const auto& plan : m_comb_plan) {
    auto position_node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Position>(
      m_user_key + "|0|" + plan.params.ins_node->Latest()->symbol);
    if (!position_node)
      return false;
    md::Volume volume_avail = 0;
    if (plan.params.ins_node->Latest()->ExchangeID() == "CZCE") {
      volume_avail = (plan.params.direction == future::Direction::kBuy)
        ? position_node->Latest()->VolumeShort() - position_node->Latest()->VolumeShortFrozen()
        : position_node->Latest()->VolumeLong() - position_node->Latest()->VolumeLongFrozen();
    } else {
      auto& subpos = GetSubPos(plan.params.direction, plan.params.hedge, position_node);
      volume_avail = subpos.Volume() - subpos.VolumeFrozen();
    }
    if (volume_avail < plan.params.volume)
      return false;
  }
  return true;
}

void CombOrderRule1::Init(bool is_load) {
  if (m_status == AgentStatus::kStopped)
    return;
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (m_volume == 0) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 报单手数无效");
    return;
  }
  if (m_comb_params.params.empty()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合下单参数");
    return;
  }
  if (!m_insert_params.ins_node || m_insert_params.ins_node->Snap()->ProductClass() != md::ProductClass::kCusCombine) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少组合合约信息");
    return;
  }
  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少交易所信息");
    return;
  }

  std::map<std::shared_ptr<md::InstrumentNode>, int> vweight;
  for (const auto& param : m_comb_params.params) {
    vweight[param.ins_node] = param.volume * (param.direction == future::Direction::kBuy ? 1 : -1);
  }
  m_calc = std::make_shared<CombQuoteCalc>(
    TradeAgent::GetTqApi(), CombQuoteCalc::CombQuoteCalcParams(m_insert_params.ins_node, vweight));
  m_calc->Subscribe();

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
      if (m_status == AgentStatus::kStopped && m_calc) {
        m_calc.reset();
        m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
    });

  // 非读档参数设置
  if (!is_load) {
    ConvertPriceType();
    BuildPlan();
    InitInsTotalVolume();
    m_insert_datetime = m_exchange_node->Latest()->GetDateTime();
    m_trigger_datetime = 0;
    m_stop_datetime = 0;
    m_comb_average_price = NAN;
  }
}

void CombOrderRule1::BuildPlan() {
  m_comb_plan.clear();
  for (const auto& params : m_comb_params.params) {
    CombPlan t;
    t.params = params;
    t.params.volume = m_volume * params.volume;
    t.params.direction = GetInsertDirection(m_insert_params.direction, params.direction);
    m_comb_plan.emplace_back(std::move(t));
  }
  FCASSERT(!m_comb_plan.empty());
}

void CombOrderRule1::CreateInstruction(CombPlan& plan, bool is_market, int vol) {
  if (nullptr == m_child_factory) {
    plan.instruction = nullptr;
    return;
  }
  plan.instruction = m_child_factory(this, plan.params.ins_node, vol, plan.params.direction, plan.params.hedge,
    GetRuleOrderPrice(plan.params, is_market));
  plan.instruction->Run();
  m_childs.push_back(plan.instruction);
  m_logger.With("volume", vol)
    .With("direction", static_cast<int>(plan.params.direction))
    .With("hedge", static_cast<int>(plan.params.hedge))
    .Info("CreateInstruction");
}

void CombOrderRule1::UpdateInstruction() {
  if (m_status == AgentStatus::kStopped)
    return;

  std::string error_msg;
  bool all_stopped = true;

  // 检查是否有错误.
  for (const auto& plan : m_comb_plan) {
    const auto& instruction = plan.instruction;
    if (!instruction)
      continue;
    m_order_nodes_set.merge(instruction->GetOrderNodes());
    if (!instruction->GetMsg().empty()) {
      if (!error_msg.empty())
        error_msg += "; ";
      error_msg += plan.params.ins_node->Latest()->symbol + ": " + instruction->GetMsg();
    }
    if (instruction->GetStatus() != AgentStatus::kStopped)
      all_stopped = false;
  }

  // 错误丢弃全部指令, 状态变为已停止.
  if (!error_msg.empty()) {
    for (auto&& plan : m_comb_plan) {
      if (!plan.instruction)
        continue;
      if (plan.instruction->GetStatus() != AgentStatus::kStopped)
        plan.instruction->Stop();
      plan.instruction.reset();
    }
    ChangeStatus(true, AgentStatus::kStopped, error_msg);
    return;
  }

  if (!all_stopped)
    return;

  // 此时, 一定是全部停止且未发生错误.
  // 计算成交均价, 更新剩余手数.
  int volume = 0;
  for (auto&& plan : m_comb_plan) {
    if (nullptr == plan.instruction) {
      volume += plan.params.volume;
      continue;
    }
    const auto& instruction = plan.instruction;

    // 刷新剩余手数.
    plan.params.volume = instruction->VolumeLeft();
    volume += plan.params.volume;

    const auto& plan_ins_symbol = plan.params.ins_node->Latest()->symbol;
    int trade_volume = instruction->VolumeTotal() - instruction->VolumeLeft();
    if (trade_volume > 0) {
      double amount = (trade_volume <= 0) ? 0.0 : instruction->TradeAmount();
      auto volume_prev = m_ins_total_volume[plan_ins_symbol] - m_ins_volume_left[plan_ins_symbol];
      double price_prev = (isnan(m_average_price[plan_ins_symbol])) ? 0.0 : m_average_price[plan_ins_symbol];
      m_average_price[plan_ins_symbol] = (amount + price_prev * volume_prev) / (trade_volume + volume_prev);
    }
    plan.instruction.reset();
  }

  CalcInsLeftVolumeByPlan();

  if (volume == 0) {
    // 刷新组合成交均价
    m_comb_average_price = 0.0;
    const auto& w = m_insert_params.ins_node->Snap()->instrument_base->weight;
    for (auto it = w.begin(); it != w.end(); ++it) {
      m_comb_average_price += it->second * m_average_price[it->first->Snap()->symbol];
    }
    ChangeStatus(true, AgentStatus::kStopped, "");
  }
}

void CombOrderRule1::InsertInstruction(bool is_market) {
  m_logger.With("status", static_cast<int>(m_status)).With("market", is_market).Info("InsertInstruction");

  if (m_trigger_datetime <= 0) {
    m_trigger_datetime = m_exchange_node->Latest()->GetDateTime();
  }
  m_is_insert = true;
  for (auto&& plan : m_comb_plan) {
    if (plan.params.volume > 0)
      CreateInstruction(plan, is_market, plan.params.volume);
  }
}

bool CombOrderRule1::InsertMarketOrder() {
  if (m_status == AgentStatus::kStopped || !m_msg.empty())
    return true;
  if (!IsInTradingTime(m_comb_params.params))
    return false;
  for (const auto& plan : m_comb_plan) {
    if (nullptr != plan.instruction)
      return false;
  }
  if (!IsPositionVolumeValid()) {
    ChangeStatus(true, m_status, u8"fclib: 持仓手数不足, 无法市价补瘸腿");
    return true;
  }
  const auto& volume = m_insert_params.direction == future::Direction::kBuy ? m_calc->GetInstrument()->ask_volume[0]
                                                                            : m_calc->GetInstrument()->bid_volume[0];
  if (volume <= 0) {
    ChangeStatus(true, m_status, u8"fclib: 市价补瘸腿缺少对手盘");
    return true;
  }
  InsertInstruction(true);
  return true;
}

void CombOrderRule1::CalcInsLeftVolumeByPlan() {
  bool notify = false;
  for (const auto& plan : m_comb_plan) {
    FCASSERT(plan.params.ins_node);
    const auto& symbol = plan.params.ins_node->Latest()->symbol;
    auto iter = m_ins_volume_left.find(symbol);
    if (iter != m_ins_volume_left.end() && iter->second != plan.params.volume) {
      notify = true;
      iter->second = plan.params.volume;
    }
  }
  if (notify && m_parent) {
    m_parent->OnChildNotify(this);
    m_logger.With("OnChildNotify", "parent").Info("CalcInsLeftVolumeByPlan");
  }
  if (notify && m_call_back)
    m_call_back(shared_from_this());
}

void CombOrderRule1::InitInsTotalVolume() {
  m_ins_total_volume.clear();
  m_ins_volume_left.clear();
  m_average_price.clear();
  for (const auto& param : m_comb_params.params) {
    FCASSERT(param.ins_node);
    m_ins_total_volume[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_ins_volume_left[param.ins_node->Latest()->symbol] += param.volume * m_volume;
    m_average_price[param.ins_node->Latest()->symbol] = NAN;
  }
  FCASSERT(!m_ins_total_volume.empty());
}

void CombOrderRule1::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;
  // 运行中, 停止时间归0
  if (m_status == AgentStatus::kStarted)
    m_stop_datetime = 0;
  else if (m_exchange_node)
    m_stop_datetime = m_exchange_node->Snap()->GetDateTime();
  else
    m_stop_datetime = NowAsEpochNano();
  if (m_msg != msg)
    m_msg = msg;
  if (m_parent && notify)
    m_parent->OnChildNotify(this);
  if (m_call_back && notify)
    m_call_back(shared_from_this());
}

