static const md::EpochNano AutoUpdateInterval = 500000000;

bool IsTimeConditionOrder(const ConditionParams& params) {
  return params.time > 0;
}

bool IsNextTradingConditionOrder(const ConditionParams& params) {
  return params.next_trading;
}

bool IsManualConfirmConditionOrder(const ConditionParams& params) {
  return params.manual_confirm;
}

bool IsPriceConditionOrder(const ConditionParams& params) {
  return !isnan(params.price);
}

double GetInsPrice(const ConditionParams& condition_params) {
  switch (condition_params.price_type) {
    case TriggerPriceType::kLastPrice: return condition_params.ins_node->Latest()->last_price;
    case TriggerPriceType::kAskPrice: return condition_params.ins_node->Latest()->ask_price[0];
    case TriggerPriceType::kBidPrice: return condition_params.ins_node->Latest()->bid_price[0];
    default: break;
  }
  return NAN;
}

// 判断价格条件单价格是否满足条件
bool IsPriceOrderMet(const ConditionOrderOperator& opt, double ins_price, double price) {
  if (isnan(ins_price) || isnan(price) || opt == ConditionOrderOperator::kInvalid)
    return false;
  return ((opt == ConditionOrderOperator::kLe && ins_price - price <= 0.000000001)
    || (opt == ConditionOrderOperator::kGe && price - ins_price <= 0.000000001));
}

void ChangeConditionOperator(ConditionOrderOperator& opt) {
  if (opt == ConditionOrderOperator::kInvalid)
    return;
  opt = (opt == ConditionOrderOperator::kGe) ? ConditionOrderOperator::kLe : ConditionOrderOperator::kGe;
}

ConditionOrderInstruction::ConditionOrderInstruction(TradeAgent* parent, const ConditionParams& condition_params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*)> child_factory)
  : m_condition_params(condition_params)
  , m_child_factory(child_factory)
  , m_status(AgentStatus::kPaused)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("condition_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("condition_order", GetAgentIndex()).Clone()) {
  m_parent = parent;
  if (!TradeAgent::GetTqApi() || !m_condition_params.ins_node) {
    ChangeStatus(AgentStatus::kStopped);
    return;
  }

  m_logger.With("condition_params", SerializeToString(m_condition_params)).Info("Constructor");

  if (m_child_factory)
    m_child = m_child_factory(this);

  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(AgentStatus::kStopped);
    return;
  }

  m_insert_datetime = m_exchange_node->Latest()->GetDateTime();

  // 创建 exchange_view 方便后续时间条件单跟踪及多账户拆分自动更新
  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  if (IsManualConfirmConditionOrder(m_condition_params))
    return;

  // 创建 instrument_view 方便后续跟踪变动
  if (!IsTimeConditionOrder(m_condition_params)) {
    std::string ins_key = m_condition_params.ins_node->Snap()->symbol;
    if (IsNextTradingConditionOrder(m_condition_params)
      && m_condition_params.ins_node->Snap()->ProductClass() == md::ProductClass::kCombine) {
      ins_key = m_condition_params.ins_node->Snap()->instrument_base->leg1_pointer.Key();
      m_condition_params.include_gfa = false;
    }
    m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
      ins_key, false, [ins_key](std::shared_ptr<const md::Instrument> ins) {
        return ins->symbol == ins_key;
      });

    m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
      [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
        if (m_status == AgentStatus::kStopped && m_ins_view) {
          m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          m_ins_view.reset();
          m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
      });
  }
}

ConditionOrderInstruction::ConditionOrderInstruction(TradeAgent* parent, const ConditionOrderInstructionPack& pack,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&)> load_factory,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*)> child_factory)
  : m_condition_params(pack.condition_params)
  , m_child_factory(child_factory)
  , m_status(pack.status)
  , m_insert_datetime(pack.insert_datetime)
  , m_trigger_datetime(pack.trigger_datetime)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("condition_order", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("condition_order", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_instruction_memo = pack.memo;

  m_logger.With("condition_params", SerializeToString(m_condition_params))
    .With("status", static_cast<int>(m_status))
    .Info("LoadConstructor");

  if (load_factory)
    m_child = load_factory(this, pack.child);

  if (m_status == AgentStatus::kStopped) {
    return;
  }

  m_exchange_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>("SHFE");
  if (!m_exchange_node) {
    ChangeStatus(AgentStatus::kStopped);
    return;
  }

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);
  if (IsManualConfirmConditionOrder(m_condition_params))
    return;

  if (!IsTimeConditionOrder(m_condition_params)) {
    std::string ins_key = m_condition_params.ins_node->Snap()->symbol;
    if (IsNextTradingConditionOrder(m_condition_params)
      && m_condition_params.ins_node->Snap()->ProductClass() == md::ProductClass::kCombine) {
      ins_key = m_condition_params.ins_node->Snap()->instrument_base->leg1_pointer.Key();
      m_condition_params.include_gfa = false;
    }
    m_ins_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Instrument>(
      ins_key, false, [ins_key](std::shared_ptr<const md::Instrument> ins) {
        return ins->symbol == ins_key;
      });

    m_exchange_view->AfterCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)),
      [&](std::shared_ptr<md::ExchangeNode> exchange, bool is_last) {
        if (m_status == AgentStatus::kStopped && m_ins_view) {
          m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          m_ins_view.reset();
          m_exchange_view->DeleteCommit("DeleteInsView" + std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
      });
  }
}

ConditionOrderInstruction::~ConditionOrderInstruction() = default;

void ConditionOrderInstruction::Run() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Run");

  // 条件单指令已触发, 调用 Run() 不起作用
  if (m_status == AgentStatus::kStopped)
    return;
  // 多账户拆分刷新
  if (m_condition_params.auto_update) {
    if (m_child_factory)
      m_child = m_child_factory(this);
    if (m_call_back)
      m_call_back(shared_from_this());
  }
  m_trigger_datetime = m_exchange_node->Latest()->GetDateTime();
  if (m_child)
    m_child->Start();
  ChangeStatus(AgentStatus::kStopped);
}

void ConditionOrderInstruction::Start() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Start");

  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;
  // 启动条件单
  ChangeStatus(AgentStatus::kStarted);
  // 拆分刷新
  if (m_condition_params.auto_update) {
    if (m_child_factory)
      m_child = m_child_factory(this);
    if (m_call_back)
      m_call_back(shared_from_this());
  }

  m_trade_view = TradeAgent::GetTqApi()->DataDb()->CreateView<future::Trade>(ReuseViewKey::kTrade);
  // Trade回调自动刷新状态
  m_trade_view->AfterCommit("ConditionOrderAutoUpdate" + std::to_string(reinterpret_cast<int64_t>(this)),
    [&](std::shared_ptr<fclib::future::TradeNode> trade, bool is_last) {
      if (!is_last)
        return;
      // 状态不再是已启动状态, 不再自动刷新
      if (m_status != AgentStatus::kStarted) {
        m_trade_view->DeleteCommit("ConditionOrderAutoUpdate" + std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (!m_condition_params.auto_update)
        return;
      if (m_child_factory)
        m_child = m_child_factory(this);
      if (m_call_back)
        m_call_back(shared_from_this());
    });

  // 处理时间条件单
  if (IsTimeConditionOrder(m_condition_params)) {
    m_exchange_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode> exchange, bool) {
        if (m_status != AgentStatus::kStarted) {
          m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
          return;
        }
        if (exchange->Snap()->GetDateTime() >= m_condition_params.time) {
          Run();
          m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        }
      });
    return;
  }
  // 处理进入连续交易时间段条件单
  if (IsNextTradingConditionOrder(m_condition_params)) {
    m_ins_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins_node, bool) {
        // 有且仅有状态切换, 且切换至可交易时段才进行报单
        if (!ins_node->Snap()->IsTradingAllowed()
          || md::Instrument::GetTradeStatus(ins_node, true) == md::Instrument::GetTradeStatus(ins_node))
          return;

        bool include_gfa = ins_node->Snap()->TradeStatus() == md::TradeStatus::kAuctionOrdering;
        if (include_gfa && !m_condition_params.include_gfa)
          return;
        // 郑商所第二次集合竞价不能发单
        if (include_gfa && ins_node->Snap()->ExchangeID() == "CZCE" && ins_node->Snap()->volume > 0)
          return;
        m_logger.With("trade_status", static_cast<int>(md::Instrument::GetTradeStatus(ins_node)))
          .With("trade_status_prev", static_cast<int>(md::Instrument::GetTradeStatus(ins_node, true)))
          .With("name", ins_node->Snap()->GetKey())
          .With("trading_allowed", ins_node->Snap()->IsTradingAllowed())
          .With("volume", ins_node->Snap()->volume)
          .Info("NextTradingConditionOrder");

        Run();
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      });
    return;
  }
  // 处理价格条件单
  if (IsPriceConditionOrder(m_condition_params)) {
    m_ins_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::InstrumentNode> ins_node, bool) {
        m_logger.With("operator", static_cast<int>(m_condition_params.opt))
          .With("ins_price", GetInsPrice(m_condition_params))
          .With("condition_price", m_condition_params.price)
          .With("trading_allowed", ins_node->Snap()->IsTradingAllowed())
          .Debug("PriceConditionOrder");

        // 价格条件单需要同时满足下单条件和处于可交易时段内, 才进行下单
        if (!IsPriceOrderMet(m_condition_params.opt, GetInsPrice(m_condition_params), m_condition_params.price))
          return;
        if (!ins_node->Snap()->IsTradingAllowed())
          return;
        Run();
        m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      });
    return;
  }
}

void ConditionOrderInstruction::Pause() {
  m_logger.With("status", static_cast<int>(m_status)).Info("Pause");

  // 非运行中且未报单状态不操作
  if (m_status != AgentStatus::kStarted)
    return;
  ChangeStatus(AgentStatus::kPaused);
  // 停止 view 跟踪
  m_exchange_view->DeleteCommit("ConditionOrderAutoUpdate" + std::to_string(reinterpret_cast<int64_t>(this)));
  if (IsManualConfirmConditionOrder(m_condition_params))
    return;
  if (IsTimeConditionOrder(m_condition_params))
    m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
  else
    m_ins_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
}

