bool ConditionOrderInstruction::SetConditionPrice(double price) {
  m_logger.With("price", price).Info("SetConditionPrice");

  // 条件单已触发, 不支持修改参数
  if (m_status == AgentStatus::kStopped)
    return false;

  // 非价格条件单不支持修改价格
  if (!IsPriceConditionOrder(m_condition_params))
    return false;
  if (isnan(price) || fabs(price - 0.0) <= 1e-5)
    return false;
  m_condition_params.price = price;
  if (IsPriceOrderMet(m_condition_params.opt, GetInsPrice(m_condition_params), m_condition_params.price)) {
    ChangeConditionOperator(m_condition_params.opt);
  }
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back)
    m_call_back(shared_from_this());
  return true;
}

void ConditionOrderInstruction::SetAutoUpdate(bool auto_update) {
  m_logger.With("auto_update", auto_update).Info("SetAutoUpdate");

  m_condition_params.auto_update = auto_update;
  if (auto_update && m_child_factory) {
    m_child = m_child_factory(this);
  }
  if (m_call_back)
    m_call_back(shared_from_this());
}

bool ConditionOrderInstruction::SetChildInstruction(std::shared_ptr<TradeInstruction> child) {
  // 自动刷新不可修改 child
  if (m_condition_params.auto_update)
    return false;
  // 条件单指令已触发不可修改 child
  if (m_status == AgentStatus::kStopped)
    return false;
  m_child = child;
  if (m_call_back)
    m_call_back(shared_from_this());
  return true;
}

