  Pause();
  ConditionOrderInstructionPack pack;
  pack.condition_params = m_condition_params;
  pack.status = m_status;
  pack.insert_datetime = m_insert_datetime;
  pack.trigger_datetime = m_trigger_datetime;
  pack.memo = m_instruction_memo;
  if (m_child)
    pack.child = m_child->SaveInstruction();
  return SerializeToString(pack);
}

std::shared_ptr<ConditionOrderInstruction> ConditionOrderInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::string&)> load_factory,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*)> child_factory) {
  auto pack = SerializeToVar<ConditionOrderInstructionPack>(params);
  if (!pack.condition_params.ins_node)
    return nullptr;
  return std::make_shared<ConditionOrderInstruction>(parent, pack, load_factory, child_factory);
}

bool ConditionOrderInstruction::IsConditionMet(const ConditionParams& condition_params) {
  if (IsTimeConditionOrder(condition_params)) {  // 时间条件单
    auto exchange_node =
      TradeAgent::GetTqApi()->DataDb()->GetNode<md::Exchange>(condition_params.ins_node->Snap()->ExchangeID());
    return exchange_node->Snap()->GetDateTime() >= condition_params.time;
  } else if (IsPriceConditionOrder(condition_params)) {  // 价格条件单
    return IsPriceOrderMet(condition_params.opt, GetInsPrice(condition_params), condition_params.price)
      && condition_params.ins_node->Snap()->IsTradingAllowed();
  }
  return false;
}

std::vector<std::shared_ptr<TradeInstruction>> ConditionOrderInstruction::GetChildInstructions() {
  std::vector<std::shared_ptr<TradeInstruction>> ret;
  if (m_child)
    ret.push_back(m_child);
  return ret;
