OrderSplitInstruction::~OrderSplitInstruction() {}

std::shared_ptr<OrderSplitInstruction> OrderSplitInstruction::Create(TradeAgent* parent,
  const OrderSplitParams& split_params, const InsertOrderPrice& order_price, const future::Direction& direction,
  std::shared_ptr<md::InstrumentNode> ins_node, int volume,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory) {
  if (split_params.split_algo == OrderSplitAlgo::kFollow || split_params.split_algo == OrderSplitAlgo::kDepth)
    return std::make_shared<FollowQuoteInstruction>(
      parent, split_params, order_price, direction, ins_node, volume, child_factory);
  return std::make_shared<PlanSplitInstruction>(
    parent, split_params, order_price, direction, ins_node, volume, child_factory);
