bool OrderSplitInstruction::CheckTwapParams(const OrderSplitParams& params, int volume, int limit_volume) {
  if (params.split_algo == OrderSplitAlgo::kFollow || params.split_algo == OrderSplitAlgo::kDepth) {
    return true;
  }
  return PlanSplitInstruction::CheckTwapParams(params, volume, limit_volume);
}

bool OrderSplitInstruction::IsVolumeAdjustable(const OrderSplitParams& params, int volume, int limit_volume) {
  if (params.split_algo == OrderSplitAlgo::kFollow || params.split_algo == OrderSplitAlgo::kDepth) {
    return true;
  }
  return PlanSplitInstruction::IsVolumeAdjustable(params, volume, limit_volume);
}

int OrderSplitInstruction::GetSuggestVolume(const OrderSplitParams& params, int volume, int limit_volume) {
  if (params.split_algo == OrderSplitAlgo::kFollow || params.split_algo == OrderSplitAlgo::kDepth) {
    return 0;
  }
  return PlanSplitInstruction::GetSuggestVolume(params, volume, limit_volume);
}

int OrderSplitInstruction::GetSuggestTime(const OrderSplitParams& params, int volume, int limit_volume) {
  if (params.split_algo == OrderSplitAlgo::kFollow || params.split_algo == OrderSplitAlgo::kDepth) {
    return 0;
  }
  return PlanSplitInstruction::GetSuggestTime(params, volume, limit_volume);
}

std::shared_ptr<OrderSplitInstruction> OrderSplitInstruction::LoadInstruction(TradeAgent* parent,
  const std::string& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const InsertOrderPrice&)> child_factory) {
  auto params_pack = SerializeToVar<OrderSplitParamsPack>(params);
  params_pack.split_params.ins_node = TradeAgent::GetTqApi()->DataDb()->GetNode<md::Instrument>(params_pack.symbol);
  if (!params_pack.split_params.ins_node) {
    return nullptr;
  }
  if (params_pack.split_params.split_params.split_algo != OrderSplitAlgo::kFollow
    && params_pack.split_params.split_params.split_algo != OrderSplitAlgo::kDepth) {
    return std::make_shared<PlanSplitInstruction>(parent, params_pack, child_factory);
  }
  return std::make_shared<FollowQuoteInstruction>(parent, params_pack, child_factory);
}

