GridInstruction::GridInstruction(TradeAgent* parent, const std::string& user_key,
  const InsertOrderParams& insert_params, const GridParams& grid_params, int32_t volume,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, int, const future::Direction&, const InsertOrderPrice&)>
    child_factory)
  : m_user_key(user_key)
  , m_insert_params(insert_params)
  , m_grid_params(grid_params)
  , m_volume(volume)
  , m_child_factory(child_factory)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("grid_instruction", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("grid_instruction", GetAgentIndex()).Clone()) {
  m_parent = parent;
  m_tick_equal = m_grid_params.buy_opposite_tick == m_grid_params.sell_opposite_tick;

  std::string ss_insert_params;
  std::string ss_grid_params;
  {
    TradeAgentSerializer ss;
    ss.FromVar(m_insert_params);
    ss.ToString(&ss_insert_params);
  }
  {
    TradeAgentSerializer ss;
    ss.FromVar(m_grid_params);
    ss.ToString(&ss_grid_params);
  }
  m_logger.With("m_insert_params", ss_insert_params)
    .With("m_grid_params", ss_grid_params)
    .With("m_user_key", m_user_key)
    .With("m_volume", m_volume)
    .Info("GridInstruction");

  Init(false);
}

GridInstruction::GridInstruction(TradeAgent* parent, const GridParamsPack& params_pack)
  : m_user_key(params_pack.user_key)
  , m_insert_params(params_pack.insert_params)
  , m_grid_params(params_pack.grid_params)
  , m_volume(params_pack.volume)
  , m_status(params_pack.status)
  , m_trading_day(params_pack.trading_day)
  , m_order_ids(params_pack.order_ids)
  , m_trade_volume(params_pack.trade_volume)
  , m_msg(params_pack.msg)
  , m_logger((parent && parent->GetLogger())
        ? parent->GetLogger()->With("grid_instruction", GetAgentIndex()).Clone()
        : structlog::Logger::Root().With("grid_instruction", GetAgentIndex()).Clone()) {
  auto login_node =
    TradeAgent::GetTqApi()->DataDb()->GetNode<future::LoginContent>(future::LoginContent::MakeKey(m_user_key));

  if (!login_node || m_trading_day != login_node->Latest()->trading_day) {
    m_status = AgentStatus::kStopped;
    return;
  }

  std::string ss_insert_params;
  std::string ss_grid_params;
  {
    TradeAgentSerializer ss;
    ss.FromVar(m_insert_params);
    ss.ToString(&ss_insert_params);
  }
  {
    TradeAgentSerializer ss;
    ss.FromVar(m_grid_params);
    ss.ToString(&ss_grid_params);
  }
  m_logger.With("m_insert_params", ss_insert_params)
    .With("m_grid_params", ss_grid_params)
    .With("m_user_key", m_user_key)
    .With("m_volume", m_volume)
    .Info("GridInstruction_Load");

  for (auto const& id : m_order_ids) {
    auto order = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Order>(future::Order::MakeKey(m_user_key, id));
    if (order)
      m_order_nodes.insert(order);
  }

  m_parent = parent;
  m_tick_equal = m_grid_params.buy_opposite_tick == m_grid_params.sell_opposite_tick;
  // 读档后状态必定为停止
  ChangeStatus(true, AgentStatus::kStopped, m_msg);
  Init(true);
}

