int GridInstruction::VolumeLeft() {
  if (m_grid_params.cycle_times == 0) {
    return VolumeTotal() - m_trade_volume;
  }
  return std::max(VolumeTotal() - m_trade_volume, 0);
}

double GridInstruction::TradeAmount() {
  double ret = 0.0;
  for (const auto& order : m_order_nodes) {
    if (order && order->Latest()->IsTradeReady()) {
      ret += order->Latest()->VolumeTrade() * order->Latest()->trade_price;
    }
  }
  return ret;
}
