void GridInstruction::OnChildNotify(TradeAgent* child) {
  // 部分柜台错单, 不会生成对应委托
  for (auto iter = m_alive_childs.begin(); iter != m_alive_childs.end();) {
    if (iter->second->GetStatus() == AgentStatus::kStopped
      && nullptr
        == TradeAgent::GetTqApi()->DataDb()->GetNode<future::Order>(future::Order::MakeKey(m_user_key, iter->first))) {
      iter = m_alive_childs.erase(iter);
    } else {
      ++iter;
    }
  }
  m_msg = child ? child->GetMsg() : "";
  if (m_alive_childs.empty() && m_order_caches.empty()) {
    ChangeStatus(true, AgentStatus::kStopped, m_msg);
  }
  if (m_parent)
    m_parent->OnChildNotify(this);
  if (m_call_back) {
    m_call_back(shared_from_this());
  }
}
void GridInstruction::CreateExchangeViewAfter() {
  m_exchange_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<md::ExchangeNode> node, bool) {
      if (m_status == AgentStatus::kStopped || m_status == AgentStatus::kPaused) {
        m_exchange_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (node->Latest()->GetDateTime() - m_last_time < static_cast<int64_t>(5e8))
        return;
      m_last_time = node->Latest()->GetDateTime();
      // 如果停止
      if (m_stop)
        m_order_caches.clear();
      if (m_alive_childs.empty() && m_order_caches.empty()) {
        ChangeStatus(true, AgentStatus::kStopped, m_msg);
      }
      if (!m_insert_params.ins_node->Latest()->IsTradingAllowed())
        return;
      for (const auto& order : m_order_caches) {
        // 获得方向、价格、手数
        auto direction = order.first;
        auto price = order.second.first;
        auto volume = order.second.second;
        auto insert_direction =
          direction == future::Direction::kBuy ? future::Direction::kSell : future::Direction::kBuy;
        double insert_price = direction == future::Direction::kBuy
          ? price + m_grid_params.buy_opposite_tick * m_insert_params.ins_node->Latest()->PriceTick()
          : price - m_grid_params.sell_opposite_tick * m_insert_params.ins_node->Latest()->PriceTick();
        m_logger.With("direction", static_cast<int>(direction))
          .With("insert_direction", static_cast<int>(insert_direction))
          .With("price", price)
          .With("insert_price", insert_price)
          .With("volume", volume)
          .Info("grid_insert");
        auto child = m_child_factory(this, volume, insert_direction, InsertOrderPrice(insert_price));
        child->Start();
        m_childs.push_back(child);
        for (const auto& insert : child->GetInsertOrder()) {
          FCASSERT(!insert->order_id.empty());
          m_order_ids.insert(insert->order_id);
          m_alive_childs[insert->order_id] = child;
        }
        if (m_parent)
          m_parent->OnChildNotify(this);
      }
      m_order_caches.clear();
    });
}

void GridInstruction::Run() {
  Start();
}

void GridInstruction::Start() {
  // 非暂停状态不操作
  if (m_status != AgentStatus::kPaused)
    return;
  ChangeStatus(true, AgentStatus::kStarted, m_msg);
  // 清空缓存
  m_order_caches.clear();

  m_exchange_view = TradeAgent::GetTqApi()->DataDb()->CreateView<md::Exchange>(ReuseViewKey::kSingleExchange);

  m_last_time = m_exchange_view->GetNodes().begin()->second->Latest()->GetDateTime();

  // 做一个Caches打入
  auto direction =
    m_insert_params.direction == future::Direction::kBuy ? future::Direction::kSell : future::Direction::kBuy;
  auto price = m_insert_params.direction == future::Direction::kBuy ? m_insert_params.order_price.limit_price
      + m_grid_params.sell_opposite_tick * m_insert_params.ins_node->Latest()->PriceTick()
                                                                    : m_insert_params.order_price.limit_price
      - m_grid_params.buy_opposite_tick * m_insert_params.ins_node->Latest()->PriceTick();
  auto volume = m_volume;
  m_order_caches[direction] = std::pair(price, volume);
  CreateExchangeViewAfter();
}

void GridInstruction::Pause() {
  if (m_status != AgentStatus::kStarted)
    return;
  // 直接停止
  for (const auto& [_, child] : m_alive_childs) {
    child->Stop();
  }
  ChangeStatus(true, AgentStatus::kStopped, m_msg);
  m_stop = true;
}

void GridInstruction::Stop() {
  if (m_status == AgentStatus::kStopped)
    return;
  for (const auto& [_, child] : m_alive_childs) {
    child->Stop();
  }
  ChangeStatus(true, AgentStatus::kStopped, m_msg);
  m_stop = true;
}

void GridInstruction::Init(bool is_load) {
  auto login_node =
    TradeAgent::GetTqApi()->DataDb()->GetNode<future::LoginContent>(future::LoginContent::MakeKey(m_user_key));
  if (!login_node || !login_node->Latest()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 用户未登录");
    return;
  }
  if (!TradeAgent::GetTqApi()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 缺少api信息");
    return;
  }
  if (!m_insert_params.ins_node || !m_insert_params.ins_node->Latest()) {
    ChangeStatus(false, AgentStatus::kStopped, u8"fclib: 交易合约无效");
    return;
  }

  m_trading_day = login_node->Latest()->trading_day;

  std::string symbol = m_insert_params.ins_node->Snap()->symbol;

  m_order_view = TradeAgent::GetTqApi()->DataDb()->CreateView<future::Order>(
    "grid_ins_" + symbol, false, [symbol](std::shared_ptr<const future::Order> order) {
      return order->Symbol() == symbol;
    });
  if (is_load) {
    // 读档的order_view仅用于获取历史订单
    m_order_view->AfterCommit(
      std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::OrderNode> node, bool) {
        if (node->Latest()->UserKey() != m_user_key)
          return;
        if (m_order_ids.find(node->Latest()->order_id) == m_order_ids.end())
          return;
        if (node->Latest()->exchange_order_id.empty())
          return;
        m_order_nodes.insert(node);

        if (m_order_nodes.size() == m_order_ids.size())
          m_order_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
      });
    return;
  }
  m_order_view->AfterCommit(
    std::to_string(reinterpret_cast<int64_t>(this)), [&](std::shared_ptr<future::OrderNode> node, bool) {
      if (m_status == AgentStatus::kStopped) {
        m_order_view->DeleteCommit(std::to_string(reinterpret_cast<int64_t>(this)));
        return;
      }
      if (node->Latest()->UserKey() != m_user_key)
        return;
      if (m_order_ids.find(node->Latest()->order_id) == m_order_ids.end())
        return;
      m_order_nodes.insert(node);
      if (node->Latest()->status == future::OrderStatus::kDead && node->Latest()->IsTradeReady()) {
        m_alive_childs.erase(node->Latest()->order_id);
      }

      if (node->Latest()->exchange_order_id.empty())
        return;

      int trade_volume = 0;
      // 首次回来赋值
      if (m_order_pre.find(node->Latest()->exchange_order_id) == m_order_pre.end()) {
        trade_volume = node->Latest()->VolumeTrade();
        m_order_pre[node->Latest()->exchange_order_id] = trade_volume;
      } else {
        trade_volume = node->Latest()->VolumeTrade() - m_order_pre[node->Latest()->exchange_order_id];
        m_order_pre[node->Latest()->exchange_order_id] = node->Latest()->VolumeTrade();
      }

      m_trade_volume += trade_volume;
      m_logger.With("trade_volume", trade_volume).With("m_trade_volume", m_trade_volume).Info("OnOrder");
      if (trade_volume > 0) {
        CacheTradeByOrder(node, trade_volume);
      }
      if (m_alive_childs.empty() && m_order_caches.empty()) {
        ChangeStatus(true, AgentStatus::kStopped, m_msg);
      }
      if (m_parent) {
        m_parent->OnChildNotify(this);
      }
      if (m_call_back) {
        m_call_back(shared_from_this());
      }
      // 无限次下单
      if (0 == m_grid_params.cycle_times) {
        return;
      }
      // 成交进度完成, 撤单并停止
      if (m_trade_volume >= m_volume * 2 * m_grid_params.cycle_times) {
        m_stop = true;
        m_order_caches.clear();
        for (const auto& [_, child] : m_alive_childs) {
          child->Stop();
        }
      }
    });
}

void GridInstruction::CacheTradeByOrder(std::shared_ptr<future::OrderNode> node, int trade_volume) {
  if (m_tick_equal) {
    if (!m_stop) {
      m_logger.With("direction", static_cast<int>(node->Latest()->direction))
        .With("limit_price", node->Latest()->limit_price)
        .With("volume", trade_volume)
        .Info("CacheTradeByOrder");
      if (m_order_caches.find(node->Latest()->direction) == m_order_caches.end()) {
        m_order_caches[node->Latest()->direction] = std::pair(node->Latest()->limit_price, trade_volume);
      } else {
        m_order_caches[node->Latest()->direction].second += trade_volume;
        FCASSERT(abs(m_order_caches[node->Latest()->direction].first - node->Latest()->limit_price) < 10e-5);
      }
    }
    return;
  }
  if (!IsOrderAllTrade(node->Latest()) || m_stop)
    return;
  m_logger.With("direction", static_cast<int>(node->Latest()->direction))
    .With("limit_price", node->Latest()->limit_price)
    .With("volume", trade_volume)
    .Info("CacheTradeByOrder");

  m_order_caches[node->Latest()->direction] = std::pair(node->Latest()->limit_price, node->Latest()->volume_orign);
}

bool GridInstruction::IsOrderAllTrade(std::shared_ptr<const future::Order> order) const {
  return order->volume_left == 0 && order->status == future::OrderStatus::kDead && order->IsTradeReady();
}

void GridInstruction::ChangeStatus(bool notify, const AgentStatus& status, const std::string& msg) {
  m_logger.With("status", static_cast<int>(status)).With("msg", msg).Info("ChangeStatus");

  m_status = status;

  if (notify && m_parent) {
    m_parent->OnChildNotify(this);
  }
  if (m_call_back)
    m_call_back(shared_from_this());
}

