void GetCancelOrderList(const std::shared_ptr<md::InstrumentNode> ins_node, const std::string& user_key,
  const future::Direction& direction, bool is_swap, std::function<void(std::shared_ptr<future::OrderNode>)> fun);

bool CloseTodayBeforeYesterDay(std::shared_ptr<md::InstrumentNode> ins_node, const std::string& user_key);

double GetRatioByProductId(const std::string& product_id, const std::map<std::string, double>& table);

double GetVolumeRatio(
  const std::string& user_key, const std::vector<std::string>& user_key_list, const std::string& product_id);

void GetBestAllocation(const std::vector<std::pair<std::string, double>>& src, int total,
  std::function<void(const std::string& user_key, const int vol)> fun);

const future::SubPosition* GetNegativeSubPosition(std::shared_ptr<const md::InstrumentNode> ins_node,
  const std::string& user_key, const future::OrderHedgeFlag& hedge, const future::Direction& direction);

VolumeSplitParams RegulateParams(const VolumeSplitParams& params);

struct ActualVolume {
  int TotalVolume() {
    return volume + volume_his + volume_today;
  }
  int volume = 0;
  int volume_his = 0;
  int volume_today = 0;
};

ActualVolume GetVolumeBySubPosition(
  std::shared_ptr<const md::InstrumentNode> ins_node, const future::SubPosition* subpos) {
  FCASSERT(nullptr != subpos);
  ActualVolume ret;
  ret.volume = subpos->Volume() - subpos->VolumeFrozen();
  if (ins_node->Latest()->HasCloseToday()) {
    ret.volume = 0;
    ret.volume_his = subpos->volume_his - subpos->volume_his_frozen;
    ret.volume_today = subpos->volume_today - subpos->volume_today_frozen;
  }
  return ret;
}

void RegulateCloseVolumeByCancelOrder(ActualVolume* ret, const std::string& user_key, const future::SubPosition* subpos,
  const future::Direction& direction, bool is_swap, std::shared_ptr<md::InstrumentNode> ins_node) {
  GetCancelOrderList(ins_node, user_key, direction, is_swap, [&](std::shared_ptr<future::OrderNode> node) {
    if (!ins_node->Latest()->HasCloseToday()) {
      ret->volume = std::min(subpos->Volume(), ret->volume + node->Latest()->volume_left);
      return;
    }
    if (node->Latest()->offset == future::Offset::kCloseToday) {
      ret->volume_today = std::min(subpos->volume_today, ret->volume_today + node->Latest()->volume_left);
    }
    if (node->Latest()->offset == future::Offset::kCloseYesterday || node->Latest()->offset == future::Offset::kClose) {
      ret->volume_his = std::min(subpos->volume_his, ret->volume_his + node->Latest()->volume_left);
    }
  });
}

void GetActualPositionVolume(const VolumeSplitParams& params, std::map<std::string, ActualVolume>* ret,
  const VolumeSplitParams& cancel_params, const bool& disable_stock_close) {
  if (params.is_swap)
    return;
  for (const auto& user_key : params.user_key_list) {
    ActualVolume volume;
    if (params.ins_node->Latest()->ProductClass() == md::ProductClass::kCombine) {
      std::shared_ptr<md::InstrumentNode> ins_node0 = params.ins_node->Latest()->instrument_base->leg1_pointer;
      std::shared_ptr<md::InstrumentNode> ins_node1 = params.ins_node->Latest()->instrument_base->leg2_pointer;
      auto sub0 = GetNegativeSubPosition(ins_node0, user_key, params.hedge, params.direction);
      auto sub1 = GetNegativeSubPosition(ins_node1, user_key, params.hedge, NegativeDir(params.direction));
      if (sub0 && sub1 && sub0->Volume() > 0 && sub1->Volume() > 0) {
        int close_vol0 = sub0->Volume() - sub0->VolumeFrozen();
        int close_vol1 = sub1->Volume() - sub1->VolumeFrozen();
        if (params.cancel_order) {
          GetCancelOrderList(cancel_params.ins_node, user_key, cancel_params.direction, cancel_params.is_swap,
            [&](std::shared_ptr<future::OrderNode> node) {
              if (node->Latest()->offset == future::Offset::kClose) {
                close_vol0 = std::min(close_vol0 + node->Latest()->volume_left, sub0->Volume());
                close_vol1 = std::min(close_vol1 + node->Latest()->volume_left, sub1->Volume());
              }
            });
        }
        volume.volume = std::min(close_vol0, close_vol1);
      }
    } else if (params.ins_node->Latest()->ProductClass() == md::ProductClass::kCusCombine) {
      auto position_node =
        TradeAgent::GetTqApi()->DataDb()->GetNode<future::CusCombinePosition>(future::CusCombinePosition::MakeKey(
          user_key, 0, params.ins_node->Latest()->symbol, NegativeDir(params.direction)));
      volume.volume = position_node ? position_node->Latest()->available_shares : 0;
      if (params.cancel_order)
        volume.volume = position_node ? position_node->Latest()->shares : 0;
    } else {
      auto sub = GetNegativeSubPosition(params.ins_node, user_key, params.hedge, params.direction);
      if (params.ins_node->Latest()->ExchangeID() != "CZCE") {
        if (sub && sub->Volume() > 0) {
          volume = GetVolumeBySubPosition(params.ins_node, sub);
          if (params.cancel_order)
            RegulateCloseVolumeByCancelOrder(
              &volume, user_key, sub, cancel_params.direction, cancel_params.is_swap, cancel_params.ins_node);
        }
      } else {
        auto sub2 = GetNegativeSubPosition(params.ins_node, user_key,
          params.hedge == future::OrderHedgeFlag::kSpeculation ? future::OrderHedgeFlag::kArbitrage
                                                               : future::OrderHedgeFlag::kSpeculation,
          params.direction);

        bool flag1 = sub && sub->Volume() > 0;
        bool flag2 = sub2 && sub2->Volume() > 0;

        // CZCE特殊处理 投机套保加一起
        if (flag1 || flag2) {
          volume.volume = (flag1 ? GetVolumeBySubPosition(params.ins_node, sub).volume : 0)
            + (flag2 ? GetVolumeBySubPosition(params.ins_node, sub2).volume : 0);
          if (params.cancel_order)
            RegulateCloseVolumeByCancelOrder(
              &volume, user_key, sub, cancel_params.direction, cancel_params.is_swap, cancel_params.ins_node);
        }
      }
      if (params.ins_node->Latest()->ExchangeID() == "CFFEX" && disable_stock_close) {
        // 中金所开启股指期权, 存在今仓, 不平仓
        if (sub && sub->volume_today > 0)
          volume.volume = 0;
      }
    }
    (*ret)[user_key] = volume;
  }
}

AutoVolumeSplitInstructionImpl::AutoVolumeSplitInstructionImpl(TradeAgent* parent, const VolumeSplitParams& params,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : VolumeSplitInstruction(parent, params, child_factory) {
  FCASSERT(params.split_offset == SplitOffset::kAuto);
}

AutoVolumeSplitInstructionImpl::AutoVolumeSplitInstructionImpl(TradeAgent* parent, const VolumeSplitParams& params,
  const std::vector<int>& plans,
  std::function<std::shared_ptr<TradeInstruction>(TradeAgent*, const std::vector<int>&)> child_factory)
  : VolumeSplitInstruction(parent, params, plans, child_factory) {
  FCASSERT(params.split_offset == SplitOffset::kAuto);
}

AutoVolumeSplitInstructionImpl::AutoVolumeSplitInstructionImpl(
  TradeAgent* parent, const VolumeSplitInstructionPack& pack)
  : VolumeSplitInstruction(parent, pack) {}

AutoVolumeSplitInstructionImpl::~AutoVolumeSplitInstructionImpl() {}

void AutoVolumeSplitInstructionImpl::SplitVolume(const VolumeSplitParams& params, std::vector<int>* ret) {
  auto p = params;
  if (p.user_key_list.empty() || nullptr == p.ins_node)
    return;
  std::vector<int> close_ret;
  std::vector<int> open_ret;
  // 先计算平仓后计算开仓
  SplitCloseVolume(p, &close_ret, ret);
  SplitOpenVolume(p, &open_ret, close_ret, ret);
  FCASSERT(ret->size() == open_ret.size());
  FCASSERT(ret->size() == close_ret.size());
  FCASSERT(params.user_key_list.size() == ret->size());
  // 系数调整
  for (auto&& vol : *ret)
    vol = static_cast<int>(vol * params.ratio);
  return;
}

void AutoVolumeSplitInstructionImpl::SplitOpenVolume(const VolumeSplitParams& params, std::vector<int>* open_ret,
  const std::vector<int>& close_ret, std::vector<int>* max_ret) {
  FCASSERT(close_ret.size() == params.user_key_list.size());
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kBaseRatioRatio:
    case InsertOrderStrategy::kBaseFirstFirst: {
      for (int index = 0; index < static_cast<int>(close_ret.size()); ++index) {
        int close_vol = close_ret.at(index);
        int max_vol = max_ret->at(index);
        open_ret->push_back(std::max(0, max_vol - close_vol));
      }
      break;
    }
    case InsertOrderStrategy::kTotalRatioAvailable:
    case InsertOrderStrategy::kTotalAvailableAvailable:
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      int close_volume = 0;
      for (const auto& v : close_ret) {
        close_volume += v;
      }
      max_ret->clear();
      // 计算剩余手数
      auto volume_left = params.volume - close_volume;
      if (volume_left <= 0) {
        std::vector<int> t(close_ret.size(), 0);
        open_ret->insert(open_ret->end(), t.begin(), t.end());
        max_ret->insert(max_ret->end(), close_ret.begin(), close_ret.end());
        break;
      }
      std::map<std::string, int> allocate;
      std::vector<std::pair<std::string, double>> src;
      CalcOpenAllocateRatio(params, &src);
      GetBestAllocation(src, volume_left, [&](const std::string& user_key, const int vol) {
        allocate[user_key] = std::max(0, vol);
      });
      for (int index = 0; index < static_cast<int>(params.user_key_list.size()); ++index) {
        const auto& user_key = params.user_key_list[index];
        int open_volume = 0;
        auto iter = allocate.find(user_key);
        if (iter != allocate.end()) {
          open_volume = iter->second;
        }
        open_ret->push_back(open_volume);
        max_ret->push_back(open_volume + close_ret.at(index));
      }
      break;
    }
    default: break;
  }
  return;
}

void CalcAllocateRate(int* total, std::vector<std::pair<std::string, double>>* ret, int ActualVolume::*p,
  const std::map<std::string, ActualVolume>& volume, const VolumeSplitParams& params) {
  for (const auto& [_, v] : volume)
    *total += v.*p;
  for (const auto& user_key : params.user_key_list) {
    double v = 0.0;
    if ((*total) > 0)
      v = volume.at(user_key).*p * 1.0 / *total;
    ret->push_back(std::make_pair(user_key, v));
  }
}

void AutoVolumeSplitInstructionImpl::SplitCloseVolume(
  const VolumeSplitParams& params, std::vector<int>* close_ret, std::vector<int>* max_ret) {
  std::map<std::string, ActualVolume> avail_volumes;
  GetActualPositionVolume(params, &avail_volumes, params, TradeInstruction::GetDisableStockCloseToday());
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kBaseRatioRatio: {
      for (const auto& user_key : params.user_key_list) {
        int vol = params.volume;
        auto it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
        if (it != VolumeSplitInstruction::GetVolumeRatioMap().end()) {
          if (it->second.find("default") == it->second.end()) {
            auto t = VolumeSplitInstruction::GetVolumeRatioMap();
            t[user_key]["default"] = 1.0;
            VolumeSplitInstruction::SetVolumeRatioMap(t);
            it = VolumeSplitInstruction::GetVolumeRatioMap().find(user_key);
          }
          auto t = GetRatioByProductId(params.ins_node->Latest()->ProductID(), it->second);
          vol = static_cast<int>(std::round(vol * t));
        }
        max_ret->push_back(vol);
        close_ret->push_back(std::min(avail_volumes[user_key].TotalVolume(), vol));
      }
      break;
    }
    case InsertOrderStrategy::kBaseFirstFirst: {
      double first_available = 0.0;
      if (auto node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(
            future::Account::MakeKey(params.user_key_list[0], 0, "CNY")))
        first_available = node->Latest()->available;
      for (const auto& user_key : params.user_key_list) {
        int vol = params.volume;
        if (user_key != params.user_key_list[0]) {
          double available = 0.0;
          if (auto node = TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(
                future::Account::MakeKey(user_key, 0, "CNY")))
            available = node->Latest()->available;
          if (available > 0 && first_available > 0) {
            vol = static_cast<int>(std::round(vol * (available / first_available)));
          } else {
            vol = 0;
          }
        }
        max_ret->push_back(vol);
        close_ret->push_back(std::min(avail_volumes[user_key].TotalVolume(), vol));
      }
      break;
    }

    case InsertOrderStrategy::kTotalRatioAvailable:
    case InsertOrderStrategy::kTotalAvailableAvailable:
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      std::map<std::string, int> allocate;
      // 支持平今/平昨
      if (params.ins_node->Latest()->HasCloseToday()) {
        int total_his = 0;
        int total_today = 0;
        std::vector<std::pair<std::string, double>> src_his;
        std::vector<std::pair<std::string, double>> src_today;
        CalcAllocateRate(&total_his, &src_his, &ActualVolume::volume_his, avail_volumes, params);
        CalcAllocateRate(&total_today, &src_today, &ActualVolume::volume_today, avail_volumes, params);
        // 根据费率拆分先后平仓手数
        std::pair<int, const std::vector<std::pair<std::string, double>>*> close_before = {0, &src_his};
        std::pair<int, const std::vector<std::pair<std::string, double>>*> close_after = {0, &src_today};
        if (!CloseTodayBeforeYesterDay(params.ins_node, params.user_key_list[0])) {
          close_before.first = std::min(params.volume, total_his);
          close_after.first = std::min((params.volume - close_before.first), total_today);
        } else {
          close_before.first = std::min(params.volume, total_today);
          close_before.second = &src_today;
          close_after.first = std::min((params.volume - close_before.first), total_his);
          close_after.second = &src_his;
        }
        // 分配手数
        GetBestAllocation(*(close_before.second), close_before.first, [&](const std::string& user_key, const int vol) {
          allocate[user_key] += std::max(0, vol);
        });
        if (close_after.first > 0) {
          GetBestAllocation(*(close_after.second), close_after.first, [&](const std::string& user_key, const int vol) {
            allocate[user_key] += std::max(0, vol);
          });
        }
      } else {
        int total = 0;
        std::vector<std::pair<std::string, double>> src;
        CalcAllocateRate(&total, &src, &ActualVolume::volume, avail_volumes, params);
        GetBestAllocation(src, std::min(params.volume, total), [&](const std::string& user_key, const int vol) {
          allocate[user_key] = std::max(0, vol);
        });
      }
      for (const auto& user_key : params.user_key_list) {
        auto iter = allocate.find(user_key);
        if (iter == allocate.end()) {
          close_ret->push_back(0);
        } else {
          close_ret->push_back(iter->second);
        }
      }
      break;
    }
    default: break;
  }
}

void AutoVolumeSplitInstructionImpl::CalcOpenAllocateRatio(
  const VolumeSplitParams& params, std::vector<std::pair<std::string, double>>* ret) {
  switch (params.volume_allocate_strategy) {
    case InsertOrderStrategy::kTotalRatioAvailable: {
      for (const auto& user_key : params.user_key_list)
        ret->push_back(std::make_pair(
          user_key, GetVolumeRatio(user_key, params.user_key_list, params.ins_node->Latest()->ProductID())));
      break;
    }
    case InsertOrderStrategy::kTotalAvailableAvailable: {
      double total_available = 0.0;
      for (const auto& user_key : params.user_key_list) {
        double available = 0.0;
        auto account_node =
          TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(future::Account::MakeKey(user_key, 0, "CNY"));
        if (account_node)
          available = account_node->Latest()->available;
        ret->push_back(std::make_pair(user_key, available));
        total_available += available;
      }
      if (total_available > 0) {
        for (auto&& [user_key, available] : *ret) {
          available /= total_available;
        }
      }
      break;
    }
    case InsertOrderStrategy::kTotalBalanceAvailable: {
      double total_balance = 0.0;
      for (auto& user_key : params.user_key_list) {
        double balance = 0.0;
        auto account_node =
          TradeAgent::GetTqApi()->DataDb()->GetNode<future::Account>(future::Account::MakeKey(user_key, 0, "CNY"));
        if (account_node)
          balance = account_node->Latest()->balance;
        ret->push_back(std::make_pair(user_key, balance));
        total_balance += balance;
      }
      if (total_balance > 0) {
        for (auto&& [user_key, balance] : *ret) {
          balance /= total_balance;
        }
      }
      break;
    }
    default: break;
  }
  return;
}

