template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, const T* plain_src = nullptr,
  CThostFtdcRspInfoField* rsp_info = nullptr, int req_id = 0, bool is_last = true) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  if (rsp_info) {
    memcpy(&msg->RspInfo, rsp_info, sizeof(CThostFtdcRspInfoField));
  }
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

class CtpRegSpiHandler : public CThostFtdcTraderSpi {
 public:
  explicit CtpRegSpiHandler(boost::asio::io_context* ioc, structlog::Logger& parent_logger, CtpRegService* service)
    : m_logger(parent_logger.Clone())
    , m_service(service)
    , m_strand(*ioc) {}

  virtual ~CtpRegSpiHandler() {}

  virtual void OnFrontConnected();

  virtual void OnFrontDisconnected(int nReason);

  virtual void OnRspError(CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast);

  virtual void OnRspAuthenticate(CThostFtdcRspAuthenticateField* pRspAuthenticateField,
    CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast);

  virtual void OnRspUserLogin(
    CThostFtdcRspUserLoginField* pRspUserLogin, CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast);

 private:
  structlog::Logger m_logger;
  CtpRegService* m_service = nullptr;

  void PushSpiMessage(std::shared_ptr<SpiMessage> msg);
  std::thread m_test_thread;
  boost::asio::io_context::strand m_strand;
};

