void CtpRegSpiHandler::OnFrontConnected() {
  m_logger.Info("OnFrontConnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontConnected;
  PushSpiMessage(msg);
}

void CtpRegSpiHandler::OnFrontDisconnected(int nReason) {
  m_logger.With("nReason", nReason).Info("OnFrontDisconnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontDisconnected;
  msg->RspInfo.ErrorID = nReason;
  PushSpiMessage(msg);
}

void CtpRegSpiHandler::OnRspError(CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  m_logger.With("request_id", nRequestID).With("is_last", bIsLast);
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnRspError;
  msg->nRequestID = nRequestID;
  msg->bIsLast = bIsLast;
  if (pRspInfo) {
    m_logger.With("ErrorID", pRspInfo->ErrorID).With("ErrorMsg", GbkToUtf8(pRspInfo->ErrorMsg));
    memcpy(&msg->RspInfo, pRspInfo, sizeof(CThostFtdcRspInfoField));
  }
  m_logger.Info("OnRspError");
  PushSpiMessage(msg);
}

void CtpRegSpiHandler::OnRspAuthenticate(CThostFtdcRspAuthenticateField* pRspAuthenticateField,
  CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  m_logger.With("request_id", nRequestID).With("is_last", bIsLast);
  if (pRspAuthenticateField) {
    m_logger.With("BrokerID", pRspAuthenticateField->BrokerID)
      .With("UserID", pRspAuthenticateField->UserID)
      .With("UserProductInfo", pRspAuthenticateField->UserProductInfo)
      .With("AppID", pRspAuthenticateField->AppID)
      .With("AppType", pRspAuthenticateField->AppType);
  }
  if (pRspInfo) {
    m_logger.With("ErrorID", pRspInfo->ErrorID).With("ErrorMsg", GbkToUtf8(pRspInfo->ErrorMsg));
  }
  m_logger.Info("OnRspAuthenticate");
  PushSpiMessage(MakeSpiMsg<CThostFtdcRspAuthenticateField>(
    SpiMessage::Tag::OnRspAuthenticate, pRspAuthenticateField, pRspInfo, nRequestID, bIsLast));
}

void CtpRegSpiHandler::OnRspUserLogin(
  CThostFtdcRspUserLoginField* pRspUserLogin, CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  m_logger.With("request_id", nRequestID).With("is_last", bIsLast);
  if (pRspUserLogin) {
    m_logger.With("TradingDay", pRspUserLogin->TradingDay)
      .With("LoginTime", pRspUserLogin->LoginTime)
      .With("BrokerID", pRspUserLogin->BrokerID)
      .With("UserID", pRspUserLogin->UserID)
      .With("SystemName", GbkToUtf8(pRspUserLogin->SystemName))
      .With("FrontID", pRspUserLogin->FrontID)
      .With("SessionID", pRspUserLogin->SessionID)
      .With("MaxOrderRef", pRspUserLogin->MaxOrderRef)
      .With("SHFETime", pRspUserLogin->SHFETime)
      .With("DCETime", pRspUserLogin->DCETime)
      .With("CZCETime", pRspUserLogin->CZCETime)
      .With("FFEXTime", pRspUserLogin->FFEXTime)
      .With("INETime", pRspUserLogin->INETime);
  }
  if (pRspInfo) {
    m_logger.With("ErrorID", pRspInfo->ErrorID).With("ErrorMsg", GbkToUtf8(pRspInfo->ErrorMsg));
  }
  m_logger.Info("OnRspUserLogin");
  PushSpiMessage(MakeSpiMsg<CThostFtdcRspUserLoginField>(
    SpiMessage::Tag::OnRspUserLogin, pRspUserLogin, pRspInfo, nRequestID, bIsLast));
}

void CtpRegSpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_service)
    return;
  auto queue = &m_service->m_recv_queue;
  m_strand.post([=]() {
    queue->push(msg);
  });
}

