CtpRegService::CtpRegService(boost::asio::io_context* ioc, structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("ctp_service", reinterpret_cast<int64_t>(this)).Clone())
  , m_ioc(ioc) {
  m_func_units.push_back(std::make_shared<CtpRegUnitLogin>(this, m_logger));
}

CtpRegService::~CtpRegService() {}

void CtpRegService::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: CTP柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
  assert(false);
}

void CtpRegService::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int CtpRegService::RunOnce() {
  std::shared_ptr<SpiMessage> msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    ProcessSpiMsg(msg);
    msg_count++;
  }
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  return msg_count;
}

int CtpRegService::BuildApi(bool subscribe_topic) {
  if (!m_req_login)
    return 0;
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_ctp_reg_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = CtpRegService::ThostApiCreator(m_flow_dir.c_str());
  m_spi = new CtpRegSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(THOST_TERT_NONE);
    m_api->SubscribePublicTopic(THOST_TERT_NONE);
  }
  m_api->Init();
  return 0;
}

std::function<CThostFtdcTraderApi*(const char*)> CtpRegService::ThostApiCreator =
  [](const char* pszFlowPath) -> CThostFtdcTraderApi* {
  return CThostFtdcTraderApi::CreateFtdcTraderApi(pszFlowPath);
};

