/*******************************************************************************
 * @file main.cpp
 * @brief 信息上报子进程主程序
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include <iostream>
#include <memory>
#include <cstdio>
#include <string>
#include <fstream>
#include <boost/asio.hpp>

#include "ctp_service_reg.h"
#include "structlog/structlog.h"
#include "fclib/utils/datetime.h"
#include "fclib/utils/base64.h"
#include "process/process_data_serialize.h"

std::ofstream g_log_file;

int main(int argc, char* argv[]) {
  if (argc != 5)
    return 1;
  // 获取进程启动时间,作为日志名称
  auto now = fclib::EpochNanoToLocalDateTime(fclib::NowAsEpochNano());
  char buf[20];
  snprintf(buf, sizeof(buf), "%04d%02d%02d_%02d%02d%02d", (now.date_time.tm_year + 1900) % 10000u,
    (now.date_time.tm_mon + 1) % 100u, now.date_time.tm_mday, now.date_time.tm_hour, now.date_time.tm_min,
    now.date_time.tm_sec);
  // 获取 user_key
  std::string user_key = argv[1];
  std::string pid = argv[2];
  // 获取 options
  fclib::future::FutureServiceOptions options;
  fclib::ProcessJsonSerializer ss;
  try {
    ss.FromString(fclib::base64url_decode(argv[3]).data());
    ss.ToVar(options);
  } catch (...) {
    return 2;
  }
  // 获取登录指令
  std::shared_ptr<fclib::future::ReqLogin> req_login = std::make_shared<fclib::future::ReqLogin>("register");
  fclib::CommandSerializer cmd_ss;
  std::string req_str = fclib::base64url_decode(argv[4]);
  try {
    cmd_ss.FromString(req_str.data());
    cmd_ss.ToVar(*req_login);
  } catch (...) {
    return 3;
  }
  // 设置输出日志
  if (!options.log_directory.empty()) {
    options.log_directory += "/";
    std::string log_path = options.log_directory + std::string(buf) + "_ctp_reg_" + user_key + "_" + pid + ".log";
    std::replace(log_path.begin(), log_path.end(), '|', '_');
    std::filesystem::path p = std::filesystem::u8path(log_path);
    g_log_file = std::ofstream(p, std::ios_base::out | std::ios::binary);
    g_log_file.rdbuf()->pubsetbuf(nullptr, 0);
    structlog::SetOutput(&g_log_file);
  } else {
    structlog::SetOutput(nullptr);
  }
  structlog::SetLevel(structlog::LogLevel::Info);
  auto logger = structlog::Logger::Root().With("main", "ctp_reg_" + pid).Clone();
  logger.With("req_str", req_str).Info("start ctp register process");
  // 创建 CtpRegService
  boost::asio::io_context io_context;
  auto service = std::make_shared<fclib::future::ctp_reg::CtpRegService>(&io_context, logger);
  service->ExecuteCommand(req_login);
  int count = 0;
  while (service->m_exit == false && count < 120) {
    count++;
    io_context.poll();
    io_context.restart();
    service->RunOnce();
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }
  logger.With("count", count).With("exit", service->m_exit).Info("ctp register process finished");
  g_log_file.close();
  return 0;
}

