  , m_logger(parent_logger.With("exec_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterCommandProcessor(InsertExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertExecOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspInsertExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertExecOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnErrRtnExecOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertExecOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnExecOrder(msg);
  });
  m_service->RegisterCommandProcessor(CancelExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelExecOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspExecOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspExecOrderAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnErrRtnExecOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnErrRtnExecOrderAction(msg);
  });
  m_service->RegisterCommandProcessor(InsertOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertOptionSelfClose(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOptionSelfClose, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOptionSelfClose(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOptionSelfCloseInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOptionSelfClose(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnInsertOptionSelfClose, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspOptionSelfClose(msg);
    });
  m_service->RegisterCommandProcessor(CancelOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelOptionSelfClose(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOptionSelfCloseAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOptionSelfCloseAction(msg);
