bool CtpUnitExecOrder::FillDCEOffsetSettingField(
  CThostFtdcInputOffsetSettingField* field, const std::shared_ptr<InsertOptionSelfClose>& req, std::string& err_msg) {
  if (!field || !req) {
    err_msg = "fclib: 指令不存在";
    return false;
  }
  if (!req->product_id.empty()) {
    std::transform(req->product_id.begin(), req->product_id.end(), req->product_id.begin(), [](unsigned char c) {
      return static_cast<char>(std::tolower(c));
    });
  }
  if (req->close_flag == SelfCloseType::kOptionPosition) {
    if (req->instrument_id.empty() && req->underlying_instrument_id.empty() && req->product_id.empty()) {
      err_msg = "fclib: 期权自对冲指令缺少合约代码、标的合约代码或产品代码, 任意填写一个即可";
      return false;
    }
    field->OffsetType = THOST_FTDC_OT_OPT_OFFSET;
    strcpy_x(field->InstrumentID, req->instrument_id);
    strcpy_x(field->UnderlyingInstrID, req->underlying_instrument_id);
    strcpy_x(field->ProductID, req->product_id);
  } else if (req->close_flag == SelfCloseType::kFuturePosition) {
    field->OffsetType = THOST_FTDC_OT_FUT_OFFSET;
    strcpy_x(field->InstrumentID, req->instrument_id);
    strcpy_x(field->ProductID, req->product_id);
  } else if (req->close_flag == SelfCloseType::kSelfFuturePosition) {
    field->OffsetType = THOST_FTDC_OT_PERFORM_OFFSET;
    strcpy_x(field->UnderlyingInstrID, req->underlying_instrument_id);
    strcpy_x(field->ProductID, req->product_id);
  } else if (req->close_flag == SelfCloseType::kSelfFuturePositionBuy) {
    field->OffsetType = THOST_FTDC_OT_EXEC_OFFSET;
    strcpy_x(field->UnderlyingInstrID, req->underlying_instrument_id);
    strcpy_x(field->ProductID, req->product_id);
  } else {
    err_msg = "fclib: 大商所期权自对冲指令类型错误";
    return false;
  }
  strcpy_x(field->InvestorID, m_last_session->UserID);
  strcpy_x(field->ExchangeID, req->exchange_id);
  strcpy_x(field->UserID, m_last_session->UserID);
  strcpy_x(field->BrokerID, m_last_session->BrokerID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field->IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field->MacAddress, m_service->m_req_login->client_mac_address);
  field->Volume = req->volume;
  field->RequestID = m_service->GenerateRequestID();
  field->IsOffset = req->is_offset ? 1 : 0;
  return true;
}

void CtpUnitExecOrder::ReqInsertOptionSelfClose(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOptionSelfClose>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
