      return;
    }
    int ret = m_service->m_api->ReqOffsetSetting(&field, field.RequestID);
    LogCtpReq(m_logger, "ReqOffsetSetting", &field, field.RequestID, ret);
    std::string key = "ReqOffsetSetting" + std::to_string(field.RequestID);
    m_service->SetReqResponse(command, key, ret);
    return;
  }
  CThostFtdcInputOptionSelfCloseField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.OptionSelfCloseRef, std::to_string(req->self_close_ref));
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_last_session->UserID);
  strcpy_x(field.BrokerID, m_last_session->BrokerID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  field.Volume = req->volume;
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  ConvertToSfitSelfCloseAction(req->close_flag, field.OptSelfCloseFlag);
  int ret = m_service->m_api->ReqOptionSelfCloseInsert(&field, field.RequestID);
  LogCtpReq(m_logger, "ReqInsertOptionSelfClose", &field, field.RequestID, ret);
  std::string key = "OptionSelfClose" + req->instrument_id;
  m_service->SetReqResponse(command, key, ret);
