void CtpUnitExecOrder::OnRtnOffsetSetting(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pOptionSelfClose = std::static_pointer_cast<CThostFtdcOffsetSettingField>(msg->pMainField);
  auto target_option_self_close = std::make_shared<OptionSelfClose>();
  target_option_self_close->exchange_id = pOptionSelfClose->ExchangeID;
  target_option_self_close->broker_id = pOptionSelfClose->BrokerID;
  target_option_self_close->investor_id = pOptionSelfClose->InvestorID;
  target_option_self_close->volume = pOptionSelfClose->Volume;
  target_option_self_close->insert_date_time =
    StringToEpochNano(pOptionSelfClose->InsertDate, pOptionSelfClose->InsertTime);
  if (pOptionSelfClose->CancelTime[0] != '\0') {
    target_option_self_close->cancel_time =
      StringToEpochNano(pOptionSelfClose->InsertDate, pOptionSelfClose->CancelTime);
  }
  target_option_self_close->exec_result = ConvertFromSfitExecOrderResultType(pOptionSelfClose->ExecResult);
  target_option_self_close->status_msg = GbkToUtf8(pOptionSelfClose->StatusMsg);
  target_option_self_close->front_id = pOptionSelfClose->FrontID;
  target_option_self_close->session_id = pOptionSelfClose->SessionID;
  target_option_self_close->user_key = m_service->m_user_key;

  if (pOptionSelfClose->InstrumentID[0] != '\0')
    target_option_self_close->instrument_id = pOptionSelfClose->InstrumentID;
  else if (pOptionSelfClose->UnderlyingInstrID[0] != '\0')
    target_option_self_close->instrument_id = pOptionSelfClose->UnderlyingInstrID;
  else if (pOptionSelfClose->ProductID[0] != '\0')
    target_option_self_close->instrument_id = pOptionSelfClose->ProductID;
  else
    target_option_self_close->instrument_id = "DCE";
  target_option_self_close->close_type_flag =
    ConvertFromSfitOffsetType(pOptionSelfClose->OffsetType, pOptionSelfClose->IsOffset == 0 ? false : true);
  target_option_self_close->self_close_id =
    std::string(target_option_self_close->instrument_id.data()) + "_" + std::to_string(pOptionSelfClose->OffsetType);
  m_service->m_node_db->ReplaceRecord<OptionSelfClose>(target_option_self_close);
  if (pOptionSelfClose->OrderSubmitStatus == THOST_FTDC_OSS_Accepted) {
    auto req = std::make_shared<QueryInvestorPosition>(m_service->m_user_key);
    m_service->ExecuteCommand(req);
  }
  auto selfclose_key = target_option_self_close->self_close_id;
  if (target_option_self_close->exec_result == ExecOrderResultType::kNoExec
    || target_option_self_close->exec_result == ExecOrderResultType::kUnKnown) {
    m_alive_selfclose_orders_dce[selfclose_key] = pOptionSelfClose;
  } else {
    m_alive_selfclose_orders_dce.erase(selfclose_key);
  }
  auto insert_cmd =
    m_service->m_command_manager->Update("ReqOffsetSetting" + std::to_string(pOptionSelfClose->RequestID));
  if (insert_cmd && insert_cmd->status != UserCommand::Status::kFinished)
    SetCommandFinished(insert_cmd);
  if (target_option_self_close->exec_result != ExecOrderResultType::kCanceled)
    return;
  auto it = m_selfclose_cancel_req_id.find(selfclose_key);
  if (it == m_selfclose_cancel_req_id.end())
    return;
  auto req_id = it->second;
  auto cancel_cmd = m_service->m_command_manager->Update("ReqCancelOffsetSetting" + std::to_string(req_id));
  SetCommandFinished(cancel_cmd);
  m_selfclose_cancel_req_id.erase(it);
}

void CtpUnitExecOrder::ReqCancelOptionSelfClose(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOptionSelfClose>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }

  auto dce_iter = m_alive_selfclose_orders_dce.find(req->self_close_id);
  if (dce_iter != m_alive_selfclose_orders_dce.end()) {
    // DCE 撤单
    auto origin = dce_iter->second;
    CThostFtdcInputOffsetSettingField field = {0};
    strcpy_x(field.BrokerID, origin->BrokerID);
    strcpy_x(field.InvestorID, origin->InvestorID);
    strcpy_x(field.ExchangeID, origin->ExchangeID);
    strcpy_x(field.InstrumentID, origin->InstrumentID);
    strcpy_x(field.UnderlyingInstrID, origin->UnderlyingInstrID);
    strcpy_x(field.ProductID, origin->ProductID);
    field.OffsetType = origin->OffsetType;
    field.RequestID = m_service->GenerateRequestID();
    int ret = m_service->m_api->ReqCancelOffsetSetting(&field, field.RequestID);
    LogCtpReq(m_logger, "ReqCancelOffsetSetting", &field, field.RequestID, ret);
    std::string key = "ReqCancelOffsetSetting" + std::to_string(field.RequestID);
    m_service->SetReqResponse(command, key, ret);
    m_selfclose_cancel_req_id[req->self_close_id] = field.RequestID;
    return;
  }
  auto iter = m_alive_selfclose_orders.find(req->self_close_id);
  if (iter == m_alive_selfclose_orders.end()) {
    SetCommandFinished(req, 1, u8"fclib: 自对冲报单委托不存在");
    return;
  }
  auto origin = iter->second;
  CThostFtdcInputOptionSelfCloseActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, origin->BrokerID);
  strcpy_x(field.InvestorID, origin->InvestorID);
  strcpy_x(field.ExchangeID, origin->ExchangeID);
  strcpy_x(field.InstrumentID, origin->InstrumentID);
  strcpy_x(field.OptionSelfCloseRef, origin->OptionSelfCloseRef);
  field.FrontID = origin->FrontID;
  field.SessionID = origin->SessionID;

  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  field.FrontID = origin->FrontID;
  field.SessionID = origin->SessionID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqOptionSelfCloseAction(&field, field.RequestID);
  LogCtpReq(m_logger, "ReqOptionSelfCloseAction", &field, field.RequestID, ret);
  std::string key = "OptionSelfCloseAction" + std::string(origin->OptionSelfCloseSysID);
  m_service->SetReqResponse(command, key, ret);
}

void CtpUnitExecOrder::OnRspOptionSelfCloseAction(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pOptionSelfCloseAction = std::static_pointer_cast<CThostFtdcInputOptionSelfCloseActionField>(msg->pMainField);
    auto key = "OptionSelfCloseAction" + std::string(pOptionSelfCloseAction->OptionSelfCloseSysID);
    auto req = m_service->m_command_manager->Update(key);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  } else {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpUnitExecOrder::OnErrRtnOptionSelfCloseAction(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pOptionSelfCloseAction = std::static_pointer_cast<CThostFtdcOptionSelfCloseActionField>(msg->pMainField);
    auto key = "OptionSelfCloseAction" + std::string(pOptionSelfCloseAction->OptionSelfCloseSysID);
    auto req = m_service->m_command_manager->Update(key);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpUnitExecOrder::OnRspCancelOffsetSetting(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto self_close = std::static_pointer_cast<CThostFtdcInputOffsetSettingField>(msg->pMainField);
    auto key = "ReqCancelOffsetSetting" + std::to_string(self_close->RequestID);
    auto req = m_service->m_command_manager->Update(key);
    if (msg->bIsLast) {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  }
}

