CtpUnitItems::CtpUnitItems(CtpServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("item_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterCommandProcessor(QueryCFMMCToken::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryCFMMCToken(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQueryCFMMCTradingAccountToken, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQueryCFMMCTradingAccountToken(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRtnCFMMCTradingAccountToken, [this](std::shared_ptr<SpiMessage> msg) {
      OnRtnCFMMCTradingAccountToken(msg);
    });
  m_service->RegisterCommandProcessor(QueryMaxVolume::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryQueryMaxVolume(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryMaxOrderVolume, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryMaxOrderVolume(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePassword(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserPasswordUpdate, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserPasswordUpdate(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspTradingAccountPasswordUpdate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspTradingAccountPasswordUpdate(msg);
    });
  m_service->RegisterCommandProcessor(SubmitUserSystemInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    SubmitUserSystemInfo(command);
  });
}

void CtpUnitItems::ReqQryCFMMCToken(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 请登录后查询");
    return;
  }
  CThostFtdcQueryCFMMCTradingAccountTokenField field;
  memset(&field, 0, sizeof(CThostFtdcQueryCFMMCTradingAccountTokenField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryCFMMCToken");
  auto ret = m_service->m_api->ReqQueryCFMMCTradingAccountToken(&field, request_id);
  LogCtpReq(m_logger, "ReqQueryCFMMCTradingAccountToken", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败");
  }
}

void CtpUnitItems::OnRspQueryCFMMCTradingAccountToken(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("ReqQryCFMMCToken"));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
}

void CtpUnitItems::OnRtnCFMMCTradingAccountToken(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("ReqQryCFMMCToken"));
    if (!req)
      return;
    auto field = std::static_pointer_cast<CThostFtdcCFMMCTradingAccountTokenField>(msg->pMainField);
    SetCommandFinished(
      req, 0, std::string(field->ParticipantID) + ";" + std::to_string(field->KeyID) + ";" + std::string(field->Token));
  }
}

void CtpUnitItems::ReqQryQueryMaxVolume(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(m_service->m_command_manager->Update(command));
  std::string error_msg;
  if (!req->Check(&error_msg)) {
    SetCommandFinished(req, -1, error_msg);
    return;
  }
  CThostFtdcQryMaxOrderVolumeField field;
  memset(&field, 0, sizeof(CThostFtdcQryMaxOrderVolumeField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.InstrumentID, req->instrument_id);
  ConvertToSfitDirection(req->direction, &(field.Direction));
  ConvertToSfitOffsetFlag(req->offset, &(field.OffsetFlag));
  ConvertToSfitHedgeFlag(req->hedge_flag, &(field.HedgeFlag));
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryQueryMaxVolume" + std::to_string(request_id));
  int ret = m_service->m_api->ReqQryMaxOrderVolume(&field, request_id);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败,请重试");
  }
  m_logger.With("req", req->ToJson()).With("request_id", request_id).With("ret", ret).Info("ReqQryQueryMaxVolume");
}

void CtpUnitItems::OnRspQryMaxOrderVolume(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(
    m_service->m_command_manager->Update("ReqQryQueryMaxVolume" + std::to_string(msg->nRequestID)));
  if (msg->RspInfo.ErrorID != 0 || !req) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  if (!msg->pMainField) {
    return;
  }
  auto field = std::static_pointer_cast<CThostFtdcQryMaxOrderVolumeField>(msg->pMainField);
  req->volume = field->MaxVolume;
  SetCommandFinished(req);
}

void CtpUnitItems::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (s_first == reinterpret_cast<int64_t>(this))
    s_first = 0;
}

void CtpUnitItems::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_service->m_command_manager->Update(command));
  if (!m_service->m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录前修改密码接口");
    return;
  }
  int request_id;
  if (req->query_request_id > 0) {
    request_id = req->query_request_id;
  } else {
    request_id = m_service->GenerateRequestID();
  }
  if (req->password_type == PasswordType::kTrade) {
    CThostFtdcUserPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
    strcpy_x(field.UserID, m_service->m_req_login->user_id);
    int ret = m_service->m_api->ReqUserPasswordUpdate(&field, request_id);
    LogCtpReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
    m_service->SetReqResponse(command, request_id, ret);
  } else {
    CThostFtdcTradingAccountPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
    strcpy_x(field.AccountID, m_service->m_req_login->user_id);
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.CurrencyID, "CNY");
    int ret = m_service->m_api->ReqTradingAccountPasswordUpdate(&field, request_id);
    LogCtpReq(m_logger, "ReqTradingAccountPasswordUpdate", &field, 0, ret);
    m_service->SetReqResponse(command, request_id, ret);
  }
}

void CtpUnitItems::OnRspUserPasswordUpdate(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  } else {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpUnitItems::OnRspTradingAccountPasswordUpdate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpUnitItems::SubmitUserSystemInfo(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录接口");
    return;
  }
  auto submit_command =
    std::static_pointer_cast<future::SubmitUserSystemInfo>(m_service->m_command_manager->Update(command));
  CThostFtdcUserSystemInfoField field{};
  strcpy_x(field.BrokerID, submit_command->broker_id);
  strcpy_x(field.UserID, submit_command->user_id);
  strcpy_x(field.ClientSystemInfo, submit_command->client_system_info);
  strcpy_x(field.ClientPublicIP, submit_command->client_ip);
  strcpy_x(field.ClientAppID, submit_command->client_app_id);
  strcpy_x(field.ClientLoginRemark, submit_command->login_remark);
  field.ClientIPPort = submit_command->client_port;
  field.ClientSystemInfoLen = static_cast<int>(submit_command->client_system_info.length());
  auto now = EpochNanoToLocalDateTime(NowAsEpochNano());
  snprintf(
    field.ClientLoginTime, 9, "%02d:%02d:%02d", now.date_time.tm_hour, now.date_time.tm_min, now.date_time.tm_sec);
  int ret = m_service->m_api->SubmitUserSystemInfo(&field);
  LogCtpReq(m_logger, "SubmitUserSystemInfo", &field, 1, ret);
  if (ret == -1) {
    SetCommandFinished(command, -1, u8"字段长度不对");
    return;
  }
  if (ret == -2) {
    SetCommandFinished(command, -1, u8"非CTP采集的终端信息");
    return;
  }
  if (ret == -4) {
    SetCommandFinished(command, -1, u8"当前用户非一对多操作员");
    return;
  }
  if (ret == -5) {
    SetCommandFinished(command, -1, u8"字段中存在非法字符或者长度超限");
    return;
  }
  if (ret == -6) {
    SetCommandFinished(command, -1, u8"采集结果字段错误");
    return;
  }
  if (ret == -7) {
    SetCommandFinished(command, -1, u8"采集库的版本类型和生产库的不一致");
    return;
  }
  SetCommandFinished(command, ret);
}

