// 根据平仓成交更新明细手数
void UpdateDetailsByVolume(std::list<std::shared_ptr<PositionDetail>>* details, int* volume) {
  while (*volume > 0 && !details->empty()) {
    auto vol = (std::min)(*volume, details->front()->volume);
    *volume -= vol;
    details->front()->volume -= vol;
    if (details->front()->volume <= 0)
      details->pop_front();
  }
}

//  对比两个PositionDetail全字段是否相等
bool CompareDetail(const std::shared_ptr<fclib::future::PositionDetail> snap_detail,
  const std::shared_ptr<fclib::future::PositionDetail> prev_detail) {
  if (snap_detail == nullptr && prev_detail == nullptr)
    return true;
  if (!snap_detail || !prev_detail)
    return false;
  if (snap_detail->open_date_time != prev_detail->open_date_time)
    return false;
  if (std::fabs(snap_detail->open_price - prev_detail->open_price) > 1e-5)
    return false;
  if (snap_detail->open_trading_day != prev_detail->open_trading_day)
    return false;
  if (snap_detail->volume != prev_detail->volume)
    return false;
  if (snap_detail->open_exchange_order_id != prev_detail->open_exchange_order_id)
    return false;
  if (snap_detail->open_exchange_trade_id != prev_detail->open_exchange_trade_id)
    return false;
  return true;
}

// 对比两个Position全字段是否相等
bool CompareEqual(
  std::shared_ptr<const fclib::future::Position> snap, std::shared_ptr<const fclib::future::Position> prev) {
  if (snap == nullptr && prev == nullptr)
    return true;
  if (snap == nullptr || prev == nullptr)
    return false;

  if (std::abs(snap->last_price - prev->last_price) > 1e-5)
    return false;
  if (snap->risk_position != prev->risk_position)
    return false;
  for (auto p : {
         &Position::subpos_long_spec,
         &Position::subpos_short_spec,
         &Position::subpos_long_other,
         &Position::subpos_short_other,
       }) {
    auto sub_snap = &(*snap.*p);
    auto sub_prev = &(*prev.*p);
    if (std::fabs(sub_snap->margin - sub_prev->margin) > 1e-5)
      return false;
    if (std::fabs(sub_snap->commission - sub_prev->commission) > 1e-5)
      return false;
    if (std::fabs(sub_snap->premium - sub_prev->premium) > 1e-5)
      return false;
    if (std::fabs(sub_snap->close_profit - sub_prev->close_profit) > 1e-5)
      return false;
    if (std::fabs(sub_snap->close_profit_by_open - sub_prev->close_profit_by_open) > 1e-5)
      return false;
    if (std::fabs(sub_snap->float_profit - sub_prev->float_profit) > 1e-5)
      return false;
    if (std::fabs(sub_snap->market_value - sub_prev->market_value) > 1e-5)
      return false;
    if (std::fabs(sub_snap->market_value_yesterday - sub_prev->market_value_yesterday) > 1e-5)
      return false;
    if (std::fabs(sub_snap->open_price - sub_prev->open_price) > 1e-5)
      return false;
    if (std::fabs(sub_snap->position_price - sub_prev->position_price) > 1e-5)
      return false;
    if (std::fabs(sub_snap->position_profit - sub_prev->position_profit) > 1e-5)
      return false;
    if (sub_snap->strike_frozen != sub_prev->strike_frozen)
      return false;
    if (sub_snap->strike_his_frozen != sub_prev->strike_his_frozen)
      return false;
    if (std::fabs(sub_snap->untrade_profit - sub_prev->untrade_profit) > 1e-5)
      return false;
    if (sub_snap->volume_comb != sub_prev->volume_comb)
      return false;
    if (sub_snap->volume_his != sub_prev->volume_his)
      return false;
    if (sub_snap->volume_his_frozen != sub_prev->volume_his_frozen)
      return false;
    if (sub_snap->volume_today != sub_prev->volume_today)
      return false;
    if (sub_snap->volume_today_frozen != sub_prev->volume_today_frozen)
      return false;
    if (sub_snap->volume_yesterday != sub_prev->volume_yesterday)
      return false;
    if (sub_snap->his_position_details.size() != sub_prev->his_position_details.size())
      return false;
    if (sub_snap->today_position_details.size() != sub_prev->today_position_details.size())
      return false;

    auto const sub_snap_his_front =
      sub_snap->his_position_details.empty() ? nullptr : sub_snap->his_position_details.front();
    auto const sub_prev_his_front =
      sub_prev->his_position_details.empty() ? nullptr : sub_prev->his_position_details.front();
    if (!CompareDetail(sub_snap_his_front, sub_prev_his_front))
      return false;

    auto const sub_snap_his_back =
      sub_snap->his_position_details.empty() ? nullptr : sub_snap->his_position_details.back();
    auto const sub_prev_his_back =
      sub_prev->his_position_details.empty() ? nullptr : sub_prev->his_position_details.back();

    if (!CompareDetail(sub_snap_his_back, sub_prev_his_back))
      return false;

    auto const sub_snap_today_front =
      sub_snap->today_position_details.empty() ? nullptr : sub_snap->today_position_details.front();
    auto const sub_prev_today_front =
      sub_prev->today_position_details.empty() ? nullptr : sub_prev->today_position_details.front();

    if (!CompareDetail(sub_snap_today_front, sub_prev_today_front))
      return false;

    auto const sub_snap_today_back =
      sub_snap->today_position_details.empty() ? nullptr : sub_snap->today_position_details.back();
    auto const sub_prev_today_back =
      sub_prev->today_position_details.empty() ? nullptr : sub_prev->today_position_details.back();

    if (!CompareDetail(sub_snap_today_back, sub_prev_today_back))
      return false;
  }
  return true;
}

// 根据平仓成交更新明细
void UpdateDetailsByCloseTrade(SubPosition* subpos, std::shared_ptr<CThostFtdcTradeField> trade, int volume) {
  if (volume <= 0)
    return;
  if (std::string(trade->ExchangeID) == "SHFE" || std::string(trade->ExchangeID) == "INE") {
    bool flag = trade->OffsetFlag != THOST_FTDC_OF_CloseToday;
    auto details = flag ? &subpos->his_position_details : &subpos->today_position_details;
    UpdateDetailsByVolume(details, &volume);
  } else {
    UpdateDetailsByVolume(&subpos->his_position_details, &volume);
    UpdateDetailsByVolume(&subpos->today_position_details, &volume);
  }
}

