      target_account->investor_id = ctp_account->AccountID;
      target_account->available = ctp_account->Available;
      target_account->client_equity = ctp_account->Balance;
      target_account->close_profit = ctp_account->CloseProfit;
      target_account->commission = ctp_account->Commission;
      target_account->deposit = ctp_account->Deposit;
      target_account->frozen_commission = ctp_account->FrozenCommission;
      target_account->frozen_margin = ctp_account->FrozenMargin;
      target_account->margin = ctp_account->CurrMargin;
      target_account->position_profit = ctp_account->PositionProfit;
      target_account->pre_balance = ctp_account->PreBalance;
