}

void CtpUnitPositionAccountView::OnRtnCombAction(std::shared_ptr<SpiMessage> msg) {
  auto comb_action = std::static_pointer_cast<CThostFtdcCombActionField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action->CombActionRef));
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Rejected) {
    SetCommandFinished(req, -1, GbkToUtf8(comb_action->StatusMsg));
    return;
  }
  // 只有当被接受才指令完成
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Accepted) {
    RequireQryPosition(false);
    RequireQryAccount(false);
    SetCommandFinished(req);
  }
}

