void CtpUnitBank::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<TransferMoney>(m_service->m_command_manager->Update(command));
  int ret = 0;
  CThostFtdcReqTransferField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.BankID, req->bank_id.c_str());
  strcpy_x(field.BankBranchID, "0000");
  field.SecuPwdFlag = THOST_FTDC_BPWDF_BlankCheck;  // 核对密码
  field.BankPwdFlag = THOST_FTDC_BPWDF_NoCheck;     // 核对密码
  field.VerifyCertNoFlag = THOST_FTDC_YNI_No;
  strcpy_x(field.AccountID, m_service->m_req_login->user_id);
  strcpy_x(field.Password, req->future_password.c_str());
  strcpy_x(field.BankPassWord, req->bank_password.c_str());
  strcpy_x(field.CurrencyID, req->currency.c_str());
  field.TradeAmount = req->amount;
  auto request_id = m_service->GenerateRequestID();
  field.RequestID = request_id;
  if (req->is_deposit) {
    // 入金
    strcpy_x(field.TradeCode, "202001");
    ret = m_service->m_api->ReqFromBankToFutureByFuture(&field, field.RequestID);
  } else {
    // 出金
    strcpy_x(field.TradeCode, "202002");
    ret = m_service->m_api->ReqFromFutureToBankByFuture(&field, field.RequestID);
  }
  memset(field.Password, 0, sizeof(field.Password));
  memset(field.BankPassWord, 0, sizeof(field.BankPassWord));
  LogCtpReq(m_logger, "ReqTransferMoney", &field, field.RequestID, ret);
  m_service->SetReqResponse(command, request_id, ret);
}

