// public
void CtpCert::ExecuteCertEnroll(std::shared_ptr<UserCommand> command) {
  if (!CreateCertApi(command)) {
    SetCommandFinished(command, -1, u8"初始化失败");
    CertFree();
    return;
  }
  auto ret_code = m_SMCertSDK_Enroll(m_cert_api);
  if (ret_code != SMCERTSDK_ERR_NONE) {
    SetCommandFinished(command, ret_code, GetCertErrorMsg(ret_code));
    CertFree();
    return;
  }
  SetCommandFinished(command, 0, u8"申请用户证书成功");
  CertFree();
}

void CtpCert::ExecuteCertDelay(std::shared_ptr<UserCommand> command) {
  if (!CreateCertApi(command)) {
    SetCommandFinished(command, -1, u8"初始化失败");
    CertFree();
    return;
  }
  auto ret_code = m_SMCertSDK_Delay(m_cert_api);
  if (ret_code != SMCERTSDK_ERR_NONE) {
    SetCommandFinished(command, ret_code, GetCertErrorMsg(ret_code));
    CertFree();
    return;
  }
  SetCommandFinished(command, 0, u8"延期本设备用户证书成功");
  CertFree();
}

void CtpCert::ExecuteCertRevoke(std::shared_ptr<UserCommand> command) {
  if (!CreateCertApi(command)) {
    SetCommandFinished(command, -1, u8"初始化失败");
    CertFree();
    return;
  }
  auto req = std::static_pointer_cast<ReqCertRevoke>(command);
  auto ret_code = m_SMCertSDK_Revoke(m_cert_api, req->cert_id.c_str());
  if (ret_code != SMCERTSDK_ERR_NONE) {
    SetCommandFinished(command, ret_code, GetCertErrorMsg(ret_code));
    CertFree();
    return;
  }
  SetCommandFinished(command, 0, u8"废弃用户证书成功");
  CertFree();
}

void CtpCert::ExecuteCertResetPin(std::shared_ptr<UserCommand> command) {
  if (!CreateCertApi(command)) {
    SetCommandFinished(command, -1, u8"初始化失败");
    CertFree();
    return;
  }
  auto req = std::static_pointer_cast<ReqCertResetPin>(command);
  auto ret_code = m_SMCertSDK_ResetPin(m_cert_api, req->pin.c_str());
  if (ret_code != SMCERTSDK_ERR_NONE) {
    SetCommandFinished(command, ret_code, GetCertErrorMsg(ret_code));
    CertFree();
    return;
  }
  SetCommandFinished(command, 0, u8"重置PIN成功");
  CertFree();
}

void CtpCert::ExecuteCertQuery(std::shared_ptr<UserCommand> command) {
  if (!CreateCertApi(command)) {
    SetCommandFinished(command, -1, u8"初始化失败");
    CertFree();
    return;
  }
  const SMCert_t* cert_ptr;
  int total;
  auto ret_code = m_SMCertSDK_CertQuery(m_cert_api, &cert_ptr, &total);
  if (ret_code != SMCERTSDK_ERR_NONE) {
    SetCommandFinished(command, ret_code, GetCertErrorMsg(ret_code));
    CertFree();
    return;
  }
  auto req = std::static_pointer_cast<ReqCertQuery>(command);
  for (int i = 0; i < total; i++) {
    auto crt = std::make_shared<Cert>();
    crt->cert_id = cert_ptr->CertID;
    crt->cert_info = cert_ptr->CertInfo;
    crt->device_id = cert_ptr->DeviceID;
    crt->is_current = cert_ptr->IsCurrent;
    crt->user_id = cert_ptr->UserID;
    req->cert_ret.push_back(crt);
    ++cert_ptr;
  }
  SetCommandFinished(command, 0, u8"查询成功");
  CertFree();
}

// private
void CtpCert::CertFree() {
  m_SMCertSDK_Free(m_cert_api);
  m_cert_api = nullptr;
  m_cert_front.clear();
  m_SMCertSDK_Clean();
}

bool CtpCert::CreateCertApi(std::shared_ptr<UserCommand> command) {
  if (m_cert_api)
    return true;
  if (m_cert_front.empty()) {
    if (!InitCertApi()) {
      return false;
    }
  }
  auto base_command = std::static_pointer_cast<ReqCertDelay>(command);
  m_cert_config.BrokerID = base_command->broker_id.c_str();
  m_cert_config.UserID = base_command->user_id.c_str();
  m_cert_config.Password = base_command->password.c_str();
  m_cert_config.Pin = base_command->pin.c_str();
  m_cert_config.BrokerName = base_command->broker_name.c_str();
  auto ret_code = m_SMCertSDK_New(&m_cert_config, &m_cert_api);
  if (ret_code != SMCERTSDK_ERR_NONE) {
    m_cert_api = nullptr;
    return false;
  }
  return true;
}

bool CtpCert::InitCertApi() {
  std::string cert_front = m_service->m_api->GetSMCertAddr();
  if (cert_front.empty())
    return false;
  size_t pos0 = cert_front.find("//");
  if (pos0 == std::string::npos)
    return false;
  size_t pos1 = cert_front.find(':', pos0 + 1);
  if (pos1 == std::string::npos)
    return false;
  std::string prev = cert_front.substr(0, pos0 - 1);
#ifdef _WIN32
  std::filesystem::path certdll_path = std::filesystem::u8path(GetRelativePath(prev + "_certsdk.dll"));
  HMODULE handle = LoadLibraryW(certdll_path.wstring().c_str());
#else
  std::string certdll = (prev + "_certsdk.so");
  void* handle = dlopen(certdll.c_str(), RTLD_LAZY);
#endif
  if (!handle)
    return false;
  m_SMCertSDK_GetVersion = (CtpSMCertSDK_GetVersion)fclib_GetProcAddress(handle, "SMCertSDK_GetVersion");
  m_SMCertSDK_Init = (CtpSMCertSDK_Init)fclib_GetProcAddress(handle, "SMCertSDK_Init");
  m_SMCertSDK_Clean = (CtpSMCertSDK_Clean)fclib_GetProcAddress(handle, "SMCertSDK_Clean");
  m_SMCertSDK_New = (CtpSMCertSDK_New)fclib_GetProcAddress(handle, "SMCertSDK_New");
  m_SMCertSDK_Free = (CtpSMCertSDK_Free)fclib_GetProcAddress(handle, "SMCertSDK_Free");
  m_SMCertSDK_CertQuery = (CtpSMCertSDK_CertQuery)fclib_GetProcAddress(handle, "SMCertSDK_CertQuery");
  m_SMCertSDK_Enroll = (CtpSMCertSDK_CertEnroll)fclib_GetProcAddress(handle, "SMCertSDK_CertEnroll");
  m_SMCertSDK_Delay = (CtpSMCertSDK_CertDelay)fclib_GetProcAddress(handle, "SMCertSDK_CertDelay");
  m_SMCertSDK_Revoke = (CtpSMCertSDK_CertRevoke)fclib_GetProcAddress(handle, "SMCertSDK_CertRevoke");
  m_SMCertSDK_ResetPin = (CtpSMCertSDK_ResetPin)fclib_GetProcAddress(handle, "SMCertSDK_ResetPin");
  m_host = cert_front.substr(pos0 + 2, pos1 - pos0 - 2);
  m_cert_config.CertHost = m_host.c_str();
  std::string port_str = cert_front.substr(pos1 + 1);
  m_cert_config.CertPort = atoi(port_str.c_str());
  m_cert_config.CertSocket = -1;
  m_cert_config.TimeoutMs = 10000;
  if (m_SMCertSDK_Init("") != SMCERTSDK_ERR_NONE)
    return false;
  m_cert_front = cert_front;
  return true;
}

