    case SMCERTSDK_ERR_INTERNAL_DIGEST: return u8"摘要失败";
    case SMCERTSDK_ERR_INTERNAL_BASE64: return u8"base64编码失败";
    case SMCERTSDK_ERR_INTERNAL_RANDOM: return u8"产生随机数失败";
    case SMCERTSDK_ERR_INTERNAL_XTSIGN: return u8"协同签名失败";
    case SMCERTSDK_ERR_PARAM_NULL: return u8"空参数";
    case SMCERTSDK_ERR_PARAM_INVALID: return u8"参数非法";
    case SMCERTSDK_ERR_PARAM_BUFFER_SMALL: return u8"缓冲区太小";
    case SMCERTSDK_ERR_NETWORK_CONNECT: return u8"连接出错";
    case SMCERTSDK_ERR_NETWORK_REQUEST: return u8"请求错误";
    case SMCERTSDK_ERR_NETWORK_RESPONSE: return u8"响应错误";
    case SMCERTSDK_ERR_STORE_UNKNOWN: return u8"存储未知错误";
    case SMCERTSDK_ERR_PIN_INCORRECT: return u8"PIN 不正确";
    case SMCERTSDK_ERR_PIN_LOCKED: return u8"PIN 已锁定";
    case SMCERTSDK_ERR_CERT_NOT_EXISTS: return u8"证书不存在";
    case SMCERTSDK_ERR_CERT_EXPIRED: return u8"证书过期";
    case SMCERTSDK_ERR_CERT_OVERLIMIT: return u8"证书个数超限";
    case SMCERTSDK_ERR_CERT_INVALID: return u8"证书无效";
    case SMCERTSDK_ERR_USER_PASS: return u8"错误的用户名或密码";
    case SMCERTSDK_ERR_PIN_WRONGFORMAT: return u8"PIN码格式不正确";
    case SMSSLCERT_ERROR_SSL: return u8"SSL错误";
    case SMSSLCERT_ERROR_WANT_READ: return u8"读阻塞";
    case SMSSLCERT_ERROR_WANT_WRITE: return u8"写阻塞";
