CtpUnitQuote::CtpUnitQuote(CtpServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("quote_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterCommandProcessor(InsertQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertQuote(command);
  });
  m_service->RegisterCommandProcessor(CancelQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelQuote(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQuoteInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQuoteAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnQuote, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnQuote(msg);
  });

  m_service->RegisterCommandProcessor(InsertForQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqForQuoteInsert(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspForQuoteInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspForQuoteInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnErrRtnForQuoteInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnErrRtnForQuoteInsert(msg);
  });
}

void CtpUnitQuote::ReqInsertQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto field = std::make_shared<CThostFtdcInputQuoteField>();
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->ExchangeID, req->exchange_id);
  strcpy_x(field->InstrumentID, req->instrument_id);
  strcpy_x(field->QuoteRef, std::to_string(req->quote_ref));
  strcpy_x(field->AskOrderRef, std::to_string(req->ask_ref));
  strcpy_x(field->BidOrderRef, std::to_string(req->bid_ref));
  strcpy_x(field->ForQuoteSysID, req->response_quote_id);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field->IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field->MacAddress, m_service->m_req_login->client_mac_address);

  field->AskPrice = req->ask_price;
  field->BidPrice = req->bid_price;
  field->AskVolume = req->ask_volume;
  field->BidVolume = req->bid_volume;
  field->RequestID = m_service->GenerateRequestID();
  ConvertToSfitOffsetFlag(req->ask_offset, &field->AskOffsetFlag);
  ConvertToSfitOffsetFlag(req->bid_offset, &field->BidOffsetFlag);
  ConvertToSfitHedgeFlag(req->ask_hedge_flag, &field->AskHedgeFlag);
  ConvertToSfitHedgeFlag(req->bid_hedge_flag, &field->BidHedgeFlag);
  int ret = m_service->m_api->ReqQuoteInsert(field.get(), field->RequestID);
  LogCtpReq(m_logger, "ReqQuoteInsert", field.get(), field->RequestID, ret);
  auto quote_id = ToFclibOrderId(field->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertQuote" + req->quote_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpUnitQuote::ReqCancelQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelQuote>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto quote_node = m_service->m_node_db->GetNode<future::Quote>(req->user_key + "|" + req->quote_id);
  if (!quote_node) {
    SetCommandFinished(req, 1, u8"报价指令不存在");
    return;
  }
  auto quote = quote_node->Latest();
  CThostFtdcInputQuoteActionField quote_action_field;
  memset(&quote_action_field, 0, sizeof(quote_action_field));
  strcpy_x(quote_action_field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(quote_action_field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(quote_action_field.UserID, m_service->m_req_login->user_id);
  strcpy_x(quote_action_field.ExchangeID, quote->exchange_id);
  strcpy_x(quote_action_field.InstrumentID, quote->instrument_id);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(quote_action_field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(quote_action_field.MacAddress, m_service->m_req_login->client_mac_address);

  quote_action_field.ActionFlag = THOST_FTDC_AF_Delete;
  auto index0 = quote->quote_id.find("|");
  auto index1 = quote->quote_id.find_last_of("|");
  strcpy_x(quote_action_field.QuoteRef, quote->quote_id.substr(0, index0));
  quote_action_field.SessionID = atoi(quote->quote_id.substr(index0 + 1, index1 - index0 - 1).c_str());
  quote_action_field.FrontID = atoi(quote->quote_id.substr(index1 + 1).c_str());
  strcpy_x(quote_action_field.QuoteSysID, quote->exchange_quote_id);
  quote_action_field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqQuoteAction(&quote_action_field, quote_action_field.RequestID);
  LogCtpReq(m_logger, "ReqQuoteAction", &quote_action_field, quote_action_field.RequestID, ret);
  // 撤销报价时需要撤销衍生报单
  if (quote->ask_order_pointer && quote->bid_order_pointer) {
    CThostFtdcInputOrderActionField order_action_field;
    memset(&order_action_field, 0, sizeof(order_action_field));
    strcpy_x(order_action_field.BrokerID, quote_action_field.BrokerID);
    strcpy_x(order_action_field.UserID, quote_action_field.UserID);
    strcpy_x(order_action_field.InvestorID, quote_action_field.InvestorID);
    strcpy_x(order_action_field.ExchangeID, quote_action_field.ExchangeID);
    strcpy_x(order_action_field.InstrumentID, quote_action_field.InstrumentID);
    if (!m_service->m_req_login->client_ip.empty())
      strcpy_x(order_action_field.IPAddress, m_service->m_req_login->client_ip);
    if (!m_service->m_req_login->client_mac_address.empty())
      strcpy_x(order_action_field.MacAddress, m_service->m_req_login->client_mac_address);

    order_action_field.SessionID = quote_action_field.SessionID;
    order_action_field.FrontID = quote_action_field.FrontID;
    order_action_field.ActionFlag = THOST_FTDC_AF_Delete;
    order_action_field.LimitPrice = 0;
    order_action_field.VolumeChange = 0;

    auto ask_order = quote->ask_order_pointer->Latest();
    auto bid_order = quote->bid_order_pointer->Latest();
    strcpy_x(order_action_field.OrderRef, ask_order->order_ref);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
    strcpy_x(order_action_field.OrderRef, bid_order->order_ref);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
  }
  m_service->m_command_manager->SetCommandId(command, "ReqCancelQuote" + req->quote_id);

  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpUnitQuote::OnRspQuoteInsert(std::shared_ptr<SpiMessage> msg) {
  auto input_quote = std::static_pointer_cast<CThostFtdcInputQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(input_quote->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  if (msg->RspInfo.ErrorID != 0) {
    auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpUnitQuote::OnRspQuoteAction(std::shared_ptr<SpiMessage> msg) {
  auto cancel_quote = std::static_pointer_cast<CThostFtdcInputQuoteActionField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(cancel_quote->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  auto req = m_service->m_command_manager->Update("ReqCancelQuote" + quote_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpUnitQuote::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->OrderRef, origin->SessionID, origin->FrontID);
  if (origin->OrderSysID[0] != '\0') {
    m_order_sysids[origin->InstrumentID][origin->OrderSysID] = order_id;
  }
}

void CtpUnitQuote::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  auto quote = std::static_pointer_cast<CThostFtdcQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(quote->QuoteRef, quote->SessionID, quote->FrontID);
  auto investor_id = std::string(quote->InvestorID);
  auto user_id = std::string(quote->UserID);
  if (user_id.empty())
    user_id = investor_id;
  std::string bid_order_id, ask_order_id;
  if (quote->BidOrderRef[0] == '\0') {
    if (quote->BidOrderSysID[0] != '\0') {
      bid_order_id = m_order_sysids[quote->InstrumentID][quote->BidOrderSysID];
      ask_order_id = m_order_sysids[quote->InstrumentID][quote->AskOrderSysID];
    }
  } else {
    bid_order_id = ToFclibOrderId(quote->BidOrderRef, quote->SessionID, quote->FrontID);
    ask_order_id = ToFclibOrderId(quote->AskOrderRef, quote->SessionID, quote->FrontID);
  }
  auto quote_key = m_service->m_user_key + "|" + quote_id;
  auto quote_node = m_service->m_node_db->ReplaceRecord<Quote>(quote_key, [=](std::shared_ptr<Quote> target_quote) {
    target_quote->user_key = m_service->m_user_key;
    target_quote->investor_id = investor_id;
    target_quote->user_id = user_id;
    target_quote->instrument_id = quote->InstrumentID;
    target_quote->exchange_id = quote->ExchangeID;
    target_quote->response_quote_id = quote->ForQuoteSysID;
    target_quote->ask_price = quote->AskPrice;
    target_quote->bid_price = quote->BidPrice;
    target_quote->ask_volume = quote->AskVolume;
    target_quote->bid_volume = quote->BidVolume;
    target_quote->ask_order_id = ask_order_id;
    target_quote->bid_order_id = bid_order_id;
    target_quote->ask_offset = ConvertFromSfitOffset(quote->AskOffsetFlag);
    target_quote->bid_offset = ConvertFromSfitOffset(quote->BidOffsetFlag);
    target_quote->ask_hedge_flag = ConvertFromSfitHedgeFlag(&quote->AskHedgeFlag);
    target_quote->bid_hedge_flag = ConvertFromSfitHedgeFlag(&quote->BidHedgeFlag);
    target_quote->status = ConvertFromSfitOrderStatus(&quote->QuoteStatus);
    target_quote->exchange_quote_id = quote->QuoteSysID;
    if (target_quote->quote_id.empty())
      target_quote->quote_id = quote_id;
  });
  if (quote->SessionID == m_service->m_session_id && m_service->m_command_manager) {
    if (quote->QuoteStatus == THOST_FTDC_OST_Canceled) {
      auto req = m_service->m_command_manager->Update("ReqCancelQuote" + quote_id);
      SetCommandFinished(req, 0, u8"成功");
    } else if (quote->QuoteStatus != THOST_FTDC_OST_Unknown) {
      auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
      if (req) {
        auto insert = std::static_pointer_cast<InsertQuote>(req);
        insert->quote_id = quote_id;
        insert->quote_pointer = quote_node;
      }
      SetCommandFinished(req, 0, u8"成功");
    }
  }
}

void CtpUnitQuote::ReqForQuoteInsert(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertForQuote>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }

  CThostFtdcInputForQuoteField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  int request_id = m_service->GenerateRequestID();
  strcpy_x(field.ForQuoteRef, std::to_string(request_id));
  int ret = m_service->m_api->ReqForQuoteInsert(&field, request_id);
  LogCtpReq(m_logger, "ReqForQuoteInsert", &field, request_id, ret);
  m_service->SetReqResponse(command, request_id, ret);
}

