void CtpSpiHandler::StartStressTesting() {
  if (m_test_thread.joinable())
    return;
  m_test_thread = std::thread([&] {
    for (int i = 0; i < 100; i++) {
      for (int j = 0; j < 10000; j++) {
        CThostFtdcOrderField f;
        memset(&f, 0, sizeof(f));
        strcpy_x(f.ExchangeID, "SHFE");
        strcpy_x(f.InstrumentID, "cu2101");
        strcpy_x(f.InvestorID, "155862");
        strcpy_x(f.UserID, "155862");
        f.Direction = THOST_FTDC_D_Buy;
        strcpy_x(f.OrderSysID, std::to_string(i * 100000 + j).c_str());
        f.LimitPrice = 30000.0;
        f.CombOffsetFlag[0] = THOST_FTDC_OF_Open;
        f.CombHedgeFlag[0] = THOST_FTDC_HF_Speculation;
        f.OrderPriceType = THOST_FTDC_OPT_LimitPrice;
        if (j > 8000) {
          f.OrderStatus = THOST_FTDC_OST_AllTraded;
        } else if (j > 6000) {
          f.OrderStatus = THOST_FTDC_OST_PartTradedQueueing;
        } else if (j > 4000) {
          f.OrderStatus = THOST_FTDC_OST_NoTradeQueueing;
        } else {
          f.OrderStatus = THOST_FTDC_OST_Canceled;
        }
        f.TimeCondition = THOST_FTDC_TC_GFD;
        f.VolumeCondition = THOST_FTDC_VC_AV;
        f.VolumeTotal = 5;
        f.VolumeTotalOriginal = 7;
        f.SessionID = 12345678;
        f.FrontID = 1;
        f.ContingentCondition = THOST_FTDC_CC_Immediately;
        strcpy_x(f.OrderRef, std::to_string((i + 1) * 100000 + j).c_str());
        strcpy_x(f.OrderLocalID, std::to_string((i + 2) * 100000 + j).c_str());
        strcpy_x(f.TraderID, "87654");
        strcpy_x(f.InsertDate, "20200101");
        strcpy_x(f.InsertTime, "10:40:30");
        OnRtnOrder(&f);
        if (j % 100 == 0)
          boost::this_thread::sleep_for(boost::chrono::milliseconds(10));
      }
    }
  });
}

void CtpSpiHandler::PushBack(std::shared_ptr<SpiMessage> msg) {
  if (m_service)
    m_service->m_recv_queue.push(msg);
}

void CtpSpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_service)
    return;
  auto queue = &m_service->m_recv_queue;
  m_strand.post([=]() {
    queue->push(msg);
  });
}

