void LogReplayer::OpenLogFile(const std::string& log_file_name, CtpSpiHandler* spi) {
  m_spi = spi;
  m_log_input_stream.push(boost::iostreams::lzma_decompressor());
  m_log_input_stream.push(boost::iostreams::file_source(log_file_name, BOOST_IOS::in | BOOST_IOS::binary));
}

bool LogReplayer::ProcessUntil(int64_t dt_step) {
  int msg_count = 0;
  if (m_stop_dt != 0) {
    m_stop_dt += dt_step;
  }
  while (true) {
    while (!m_next_spi_msg) {
      std::string line;
      if (!std::getline(m_log_input_stream, line))
        return false;
      m_next_spi_msg = LogLineToSpiMessage(line, &m_next_spi_msg_dt);
    }
    if (m_stop_dt == 0)
      m_stop_dt = m_next_spi_msg_dt;
    if (m_next_spi_msg_dt > m_stop_dt)
      break;
    m_spi->PushBack(m_next_spi_msg);
    msg_count++;
    m_next_spi_msg = nullptr;
  }
  MockDateTime(m_stop_dt);
  return true;
}

std::shared_ptr<fclib::future::ctp::SpiMessage> LogReplayer::LogLineToSpiMessage(
  const std::string& log_line, int64_t* msg_date_time) {
  SerializerCtpLog ss;
  ss.FromString(log_line.c_str());
  std::string msg = (*ss.m_doc)["msg"].GetString();
  std::string dts = (*ss.m_doc)["time"].GetString();
  SpiMessage::Tag t;
  if (!StringToTag(&t, msg))
    return nullptr;
  int64_t dt = DateTimeStringToEpochNano(dts.c_str());
  if (dt == -1)
    return nullptr;
  *msg_date_time = dt;
  switch (t) {
    case SpiMessage::Tag::OnRtnOrder: {
      auto p = CThostFtdcOrderField();
      ss.ToVar(p);
      Utf8ToGbk(p.StatusMsg, sizeof(p.StatusMsg));
      return MakeSpiMsg<CThostFtdcOrderField>(SpiMessage::Tag::OnRtnOrder, &p);
    }
    case SpiMessage::Tag::OnRtnTrade: {
      auto p = CThostFtdcTradeField();
      ss.ToVar(p);
