CtpServiceImpl::CtpServiceImpl(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("ctp_service", reinterpret_cast<int64_t>(this)).Clone())
  , m_options(options)
  , m_node_db(node_db)
  , m_md_helper(helper)
  , m_user_key(user_key)
  , m_ioc(ioc)
  , m_query_planner(parent_logger) {
  SetNodeRelease();

  m_position_view = m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_user_key && pos->unit_id == 0;
  });
  m_dce_position_comb = std::make_shared<DcePositionAutoComb>(m_position_view, m_md_helper, m_logger);

  m_func_units.push_back(std::make_shared<CtpUnitSettlementInfo>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitOrderTradeView>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitPositionAccountView>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitInsertCancelOrder>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitExecOrder>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpCert>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitNotice>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitNoticeView>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitLogin>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitRate>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitBank>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitQuote>(this, m_logger));
  m_func_units.push_back(std::make_shared<CtpUnitItems>(this, m_logger));
}

CtpServiceImpl::~CtpServiceImpl() {}

ServiceInterface::ServiceType CtpServiceImpl::GetServiceType() {
  return ServiceType::kFuture;
}

void CtpServiceImpl::Start() {}

void CtpServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  command->status = UserCommand::Status::kStarted;
  m_command_manager->Store(command);
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: CTP柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
  assert(false);
}

void CtpServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  if (m_req_change_password_before_login && spi_msg->tag != SpiMessage::Tag::OnFrontConnected
    && spi_msg->tag != SpiMessage::Tag::OnFrontDisconnected && spi_msg->tag != SpiMessage::Tag::OnRspAuthenticate
    && spi_msg->tag != SpiMessage::Tag::OnRspUserLogin && spi_msg->tag != SpiMessage::Tag::OnRspUserPasswordUpdate
    && spi_msg->tag != SpiMessage::Tag::OnRspError) {
    return;
  }
  m_query_planner.ProcessSpiMsg(spi_msg);
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int CtpServiceImpl::RunOnce() {
  m_query_planner.RunOnce();
  std::shared_ptr<SpiMessage> msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    ProcessSpiMsg(msg);
    msg_count++;
  }
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  if (msg_count == 0) {  // 当截面稳定,检查是否需要发送组合请求
    if (m_options.position_comb_auto) {
      m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
        ExecuteCommand(comb_insert);
      });
    }
  }
  m_node_release->ReleaseNode();
  // 行情变化和交易变化都会影响
  return msg_count;
}

int CtpServiceImpl::BuildApi(bool subscribe_topic) {
  if (!m_req_login)
    return 0;
  DeleteApi();
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_ctp_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = CtpServiceImpl::ThostApiCreator(m_flow_dir.c_str());
  m_spi = new CtpSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(THOST_TERT_RESUME);
    m_api->SubscribePublicTopic(THOST_TERT_RESUME);
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    // TODO(TanYan): 增加延时
    m_api->Init();
  }
  return 0;
}

int CtpServiceImpl::MockApi() {
  if (!m_req_login)
    return 0;
  DeleteApi();
  auto api = new CtpMockApi(m_md_helper);
  api->ReqLogin(m_req_login);
  m_api = api;
  m_spi = new CtpSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  m_api->Init();
  return 0;
}

std::function<CThostFtdcTraderApi*(const char*)> CtpServiceImpl::ThostApiCreator =
  [](const char* pszFlowPath) -> CThostFtdcTraderApi* {
  return CThostFtdcTraderApi::CreateFtdcTraderApi(pszFlowPath);
};

void CtpServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api->Release();
  m_api = nullptr;
}

void CtpServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_cmd_processor[tag] = processor;
}

void CtpServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

int CtpServiceImpl::GenerateRequestID() {
  static int request_id = 0;
  return request_id++;
}

int64_t CtpServiceImpl::GenerateOrderRef() {
  return ++m_order_ref;
}

void CtpServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, int request_id, int result_code) {
  SetReqResponse(c, std::to_string(request_id), result_code);
}

void CtpServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, const std::string request_key, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, request_key);
}

void CtpServiceImpl::SetNodeRelease() {
  NodeRelease::NodeReleaseFunc release_funcs;
  release_funcs.order_release = [](const future::Order* order) {
    return order->status == future::OrderStatus::kDead;
  };
  release_funcs.trade_release = [this](const future::Trade* trade) {
    if (isnan(trade->commission)) {
      return false;
    }
    if (!m_options.enable_position_details) {
      return true;
    }
    int v = 0;
    for (const auto& log : trade->close_logs) {
      v += log->volume;
    }
    return v == trade->volume;
  };
  release_funcs.quote_release = [](const future::Quote* quote) {
    return quote->status == future::OrderStatus::kDead && !quote->ask_order_id.empty() && !quote->bid_order_id.empty();
  };
  m_node_release = std::make_shared<NodeRelease>(m_node_db, release_funcs, m_logger);
}

void CtpServiceImpl::CleanUp() {}

std::shared_ptr<CtpService> CtpService::Create(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger) {
  auto p = std::make_shared<CtpServiceImpl>(ioc, user_key, options, node_db, helper, parent_logger);
  p->Start();
  return p;
}

