CtpMockApi::CtpMockApi(std::shared_ptr<md::MdServiceShmHelper> helper) : m_helper(helper), m_strand(m_io_context) {
  m_work = std::make_unique<boost::asio::io_context::work>(m_io_context);
  m_thread = std::thread([this]() {
    m_io_context.run();
  });
  // rsp_info
  m_rsp_info = std::make_shared<CThostFtdcRspInfoField>();
  memset(m_rsp_info.get(), 0, sizeof(CThostFtdcRspInfoField));
  m_rsp_info->ErrorID = 0;
  strcpy_x(m_rsp_info->ErrorMsg, Utf8ToGbk(u8"正确"));
  // init account
  InitAccount();
}

void CtpMockApi::ReqLogin(std::shared_ptr<UserCommand> command) {
  if (command->aid != future::ReqLogin::AID)
    return;
  auto req = std::dynamic_pointer_cast<future::ReqLogin>(command);
  if (nullptr == req)
    return;
  m_mock_options = req->mock_api;
  assert(m_mock_options.enable);
}

void CtpMockApi::RegisterSpi(CThostFtdcTraderSpi* pSpi) {
  m_spi = pSpi;
}

void CtpMockApi::Init() {
  assert(m_spi);
  m_strand.post([this]() {
    m_spi->OnFrontConnected();
  });
}

int CtpMockApi::ReqUserLoginSM(CThostFtdcReqUserLoginSMField* pReqUserLoginSM, int nRequestID) {
  auto field = std::make_shared<CThostFtdcRspUserLoginField>();
  memset(field.get(), 0, sizeof(CThostFtdcRspUserLoginField));
  strcpy_x(field->TradingDay, m_trading_day);
  strcpy_x(field->LoginTime, m_login_time);
  strcpy_x(field->BrokerID, pReqUserLoginSM->BrokerID);
  strcpy_x(field->UserID, pReqUserLoginSM->UserID);
  strcpy_x(field->SystemName, "MockTradingHosting");
  strcpy_x(field->MaxOrderRef, "1");
  field->FrontID = m_front_id;
  field->SessionID = m_session_id;
  m_strand.post([=]() {
    m_spi->OnRspUserLogin(field.get(), m_rsp_info.get(), nRequestID, true);
  });

  strcpy_x(m_rsp_account->BrokerID, pReqUserLoginSM->BrokerID);
  strcpy_x(m_rsp_account->AccountID, pReqUserLoginSM->UserID);

  if (m_mock_options.pre_stored_quantity.empty() || m_mock_options.pre_stored_quantity.at(0) <= 0)
    return 0;

  m_strand.post([=]() {
    const auto& order_quantity = m_mock_options.pre_stored_quantity.at(0);
    int32_t trade_quantity = 0;
    if (m_mock_options.pre_stored_quantity.size() >= 2)
      trade_quantity = (std::min)(order_quantity, m_mock_options.pre_stored_quantity.at(1));
    // init orders and trades
    InitOrders(order_quantity, trade_quantity);
  });
  return 0;
}

