int CtpMockApi::ReqQryInvestorPosition(CThostFtdcQryInvestorPositionField* pQryInvestorPosition, int nRequestID) {
  if (m_mock_positions.empty() && m_mock_options.pre_stored_quantity.size() >= 3
    && m_mock_options.pre_stored_quantity.at(2) > 0 && !m_position_init) {
    // init positions
    InitPositions(m_mock_options.pre_stored_quantity.at(2));
  }
  m_position_init = true;
  if (m_mock_positions.empty()) {
    m_strand.post([=]() {
      m_spi->OnRspQryInvestorPosition(nullptr, m_rsp_info.get(), nRequestID, true);
    });
    return 0;
  }
  while (!m_mock_positions.empty()) {
    auto field = m_mock_positions.front();
    m_mock_positions.pop();
    m_strand.post([=]() {
      m_spi->OnRspQryInvestorPosition(field.get(), m_rsp_info.get(), nRequestID, m_mock_positions.empty());
    });
  }
  return 0;
}

int CtpMockApi::ReqOrderInsert(CThostFtdcInputOrderField* pInputOrder, int nRequestID) {
  auto field = std::make_shared<CThostFtdcOrderField>();
  GenerateOrder(pInputOrder, nRequestID, field.get());
  // the following field will be changed
  strcpy_x(field->OrderSysID, "");
  field->OrderStatus = THOST_FTDC_OST_Unknown;
  field->VolumeTotal = pInputOrder->VolumeTotalOriginal;
  field->VolumeTraded = 0;
  strcpy_x(field->StatusMsg, Utf8ToGbk(u8"报单已提交"));

  // change to next status
  auto field2 = std::make_shared<CThostFtdcOrderField>(*field);
  strcpy_x(field2->OrderSysID, std::to_string(m_order_id));
  field2->OrderStatus = THOST_FTDC_OST_NoTradeQueueing;

  m_strand.post([=]() {
    m_spi->OnRtnOrder(field.get());
    m_spi->OnRtnOrder(field2.get());
  });
  return 0;
}

