  strcpy_x(trade_field->TradingDay, m_trading_day);
  trade_field->SettlementID = 1;
  strcpy_x(trade_field->InstrumentID, order_field->InstrumentID);
  strcpy_x(trade_field->ExchangeInstID, order_field->ExchangeInstID);
}

