/**
委托/成交列表 功能单元. 它所要完成的任务包括:

* 维护账户的委托单/成交记录列表, 尽力保持它们更新.

它不处理任何用户指令.
 */
class FemasUnitOrderTradeView : public FuncUnit {
 public:
  FemasUnitOrderTradeView(FemasServiceImpl* service, structlog::Logger& parent_logger);

  /**
   * 收到登录回应.
   *
   * 当登录回应表示登录成功时, 记录 session 信息到 m_session.
   */
  void OnRspUserLogin(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到下单回报. 用回报信息更新委托单列表.
   */
  void OnRspOrderInsert(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到预埋单查询回报. 用回报信息更新预埋单列表.
   */
  void OnRspQryParkedOrder(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到回单信息. 用回单信息更新委托单列表.
   */
  void OnRtnOrder(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到成交通知.
   *
   * 如果收到成交通知时, 尚未收到对应的委托单信息, 则将成交记录存放(AddTradeToCache), 暂不处理.
   * 否则会立即处理(ProcessTrade)
   */
  void OnRtnTrade(std::shared_ptr<SpiMessage> msg);

 private:
  /**
   * 处理成交通知. 将成交记录放入成交列表, 并建立成交记录和对应委托单之间的双向指针关联.
   */
  void ProcessTrade(std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> origin, std::shared_ptr<future::OrderNode>);

  std::shared_ptr<future::OrderNode> GetMatchOrder(std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> origin);

  /**
   * 将还不能处理的成交记录放入暂存区.
   */
  void AddTradeToCache(std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> origin);

  /**
   * 处理暂存区中与 order_node 相关的成交记录.
   */
  void ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node);

  /**
   * 在处理quote信息时，有可能单腿行情尚未找到获取到，此时需要本地创建一条这样的委托单
   */
  std::shared_ptr<future::OrderNode> GenerateDerivateOrderNode(const std::string& order_id,
    const std::string& exchange_id, const std::string& instrument_id, Direction direction, Offset offset,
    OrderHedgeFlag hedge_flag, double price, int volume, OrderStatus status, const std::string& user_id,
    const std::string& investor_id);

  /**
   * 这个表用于查找一个Trade对应的Order节点.
   * KEY定义为 OrderSysID + "|" + ExchangeID, 这两个字段可以唯一确定一个委托单, 且Trade中携带有这两个字段.
   */
  std::map<std::string, std::shared_ptr<future::OrderNode>> m_trade_order_map;

  /**
   * 这个表用于缓存收到的Trade数据包.
   * 在CTP私有流中, 存在Order/Trade乱序问题, 即一个委托单可能在收到第一个RtnOrder前先收到RtnTrade,
   * 因为我们需要在 Trade 中提供指向 Order 节点的指针, 必须将 Trade 信息暂缓处理, 直到 RtnOrder 到位.
   *
   * KEY定义为 OrderSysID + "|" + ExchangeID, 这两个字段可以唯一确定一个委托单, 且Trade中携带有这两个字段.
   * 每个KEY下存放所有暂时无法处理的 Trade 记录.
   */
  std::map<std::string, std::set<std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField>>> m_trade_cache;

  int RunOnce() override {
    return 0;
  }

  FemasServiceImpl* m_service = nullptr;
  std::shared_ptr<TqApiNodeDb> m_node_db;
  std::string m_user_key;

  structlog::Logger m_logger;

  std::shared_ptr<NodeDbView<Trade>> m_trade_view;
  std::shared_ptr<NodeDbView<Rate>> m_rate_view;

  std::map<std::string, md::Volume> m_long_position;
  std::map<std::string, md::Volume> m_short_position;

  int m_index;
  std::string m_trading_day;
  int m_session_id;
  int m_front_id;
};

}  // namespace femas
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_FEMAS_ORDER_TRADE_VIEW_H

