FemasUnitRate::FemasUnitRate(FemasServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("unit_rate", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryMargin(command);
  });
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryCommission(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentMarginRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentMarginRate(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentCommissionRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentCommissionRate(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryOptionTradeCost, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryOptionTradeCost(msg);
  });
}

void FemasUnitRate::ReqQryCommission(std::shared_ptr<UserCommand> command) {
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  if (!m_service->m_command_manager->Update(command))
    m_service->m_command_manager->Store(command);
  auto qry = std::static_pointer_cast<QueryCommissionRate>(command);
  auto key = "ReqQryCommission" + qry->instrument_id;
  if (m_service->m_query_planner.AlreadyInQueue(key)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcQryInvestorFeeField>();
  memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcQryInvestorFeeField));
  strcpy_x(field->BrokerID, m_service->m_broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  field->HedgeFlag = USTP_FTDC_CHF_Speculation;
  femas::ConvertToFemasExchangeID(qry->exchange_id, &field->ExchangeID);
  int request_id = m_service->GenerateRequestID();
  m_service->m_query_planner.AddTask(key, FemasQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInvestorFee(field.get(), request_id);
    if (ret >= 0) {
      LogFemasReq(m_logger, "ReqQryInvestorFee", field.get(), request_id, ret);
      m_service->SetReqResponse(command, request_id, ret);
    }
    return ret;
  });
}

void FemasUnitRate::OnRspQryInstrumentCommissionRate(std::shared_ptr<SpiMessage> msg) {
  std::shared_ptr<cffex_femas_fip::CUstpFtdcInvestorFeeField> commission = nullptr;
  if (msg->pMainField) {
    commission = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInvestorFeeField>(msg->pMainField);
    auto rate_key = m_service->m_user_key + "|" + std::string(commission->InstrumentID);
    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->commission_rate_open = (UnitRate(commission->OpenFeeRate, commission->OpenFeeAmt));
      rate_node->commission_rate_close = (UnitRate(commission->OffsetFeeRate, commission->OffsetFeeAmt));
      rate_node->commission_rate_close_today = (UnitRate(commission->OTFeeRate, commission->OTFeeAmt));
      auto product_class = m_service->m_md_helper->GetShmInstrumentField(
        std::string(commission->ExchangeID) + "." + std::string(commission->InstrumentID),
        &shm::ShmInstrument::product_class, true);

      if (product_class == md::ProductClass::kOption) {
        rate_node->commission_rate_exec = (UnitRate(commission->ExecFeeRate, commission->ExecFeeAmt));
      } else {
        rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
      }
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = std::string(commission->InstrumentID);
      rate_node->exchange_id = ConvertFromFemasExchangeID(&commission->ExchangeID);
      if (rate_node->exchange_id.empty()) {
        auto exchange_id =
          m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
        if (exchange_id.has_value()) {
          rate_node->exchange_id = exchange_id->data();
        }
      }
    });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    if (commission && req) {
      auto qry = std::static_pointer_cast<QueryCommissionRate>(req);
      if (!qry->instrument_id.empty() && qry->instrument_id != std::string(commission->InstrumentID)) {
        auto new_commission_field = std::make_shared<cffex_femas_fip::CUstpFtdcInvestorFeeField>(*commission);
        strcpy_x(new_commission_field->InstrumentID, qry->instrument_id);
        auto rate_key = m_service->m_user_key + "|" + std::string(new_commission_field->InstrumentID);
        m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
          rate_node->commission_rate_open =
            (UnitRate(new_commission_field->OpenFeeRate, new_commission_field->OpenFeeAmt));
          rate_node->commission_rate_close =
            (UnitRate(new_commission_field->OffsetFeeRate, new_commission_field->OffsetFeeAmt));
          rate_node->commission_rate_close_today =
            (UnitRate(new_commission_field->OTFeeRate, new_commission_field->OTFeeAmt));
          auto product_class = m_service->m_md_helper->GetShmInstrumentField(
            std::string(qry->exchange_id) + "." + std::string(qry->instrument_id), &shm::ShmInstrument::product_class,
            true);
          if (product_class == md::ProductClass::kOption) {
            rate_node->commission_rate_exec = (UnitRate(commission->ExecFeeRate, commission->ExecFeeAmt));
          } else {
            rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
          }
          rate_node->user_key = m_service->m_user_key;
          rate_node->instrument_id = std::string(new_commission_field->InstrumentID);
          rate_node->exchange_id = ConvertFromFemasExchangeID(&new_commission_field->ExchangeID);
          if (rate_node->exchange_id.empty()) {
            auto exchange_id =
              m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
            if (exchange_id.has_value()) {
              rate_node->exchange_id = exchange_id->data();
            }
          }
        });
      }
    }
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void FemasUnitRate::ReqQryMargin(std::shared_ptr<UserCommand> command) {
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  if (!m_service->m_command_manager->Update(command))
    m_service->m_command_manager->Store(command);
  auto qry = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  auto key = "ReqQryMargin" + qry->instrument_id;
  if (m_service->m_query_planner.AlreadyInQueue(key)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  // 如果是期权 查询的合约ID不能为空
  if (!qry->instrument_id.empty()) {
    auto product_class = m_service->m_md_helper->GetShmInstrumentField(
      qry->exchange_id + "." + qry->instrument_id, &shm::ShmInstrument::product_class, true);
    if (product_class == md::ProductClass::kOption) {
      auto field = std::make_shared<cffex_femas_fip::CUstpFtdcQryOptionTradeCostField>();
      memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcQryOptionTradeCostField));
      strcpy_x(field->BrokerID, m_service->m_broker_id);
      strcpy_x(field->InvestorID, m_service->m_investor_id);
      strcpy_x(field->UserID, m_service->m_req_login->user_id);
      strcpy_x(field->InstrumentID, qry->instrument_id);
      femas::ConvertToFemasExchangeID(qry->exchange_id, &field->ExchangeID);
      femas::ConvertToFemasHedgeFlag(qry->hedge_flag, &field->HedgeFlag);
      int request_id = m_service->GenerateRequestID();
      m_service->m_query_planner.AddTask(key, FemasQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
        auto ret = m_service->m_api->ReqQryOptionTradeCost(field.get(), request_id);
        if (ret >= 0) {
          LogFemasReq(m_logger, "ReqQryOptionTradeCost", field.get(), request_id, ret);
          m_service->SetReqResponse(command, request_id, ret);
        }
        return ret;
      });
      return;
    }
  }

  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcQryInvestorMarginField>();
  memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcQryInvestorMarginField));
  strcpy_x(field->BrokerID, m_service->m_broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  femas::ConvertToFemasExchangeID(qry->exchange_id, &field->ExchangeID);
  int request_id = m_service->GenerateRequestID();
  m_service->m_query_planner.AddTask(key, FemasQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInvestorMargin(field.get(), request_id);
    if (ret >= 0) {
      LogFemasReq(m_logger, "ReqQryInvestorMargin", field.get(), request_id, ret);
      m_service->SetReqResponse(command, request_id, ret);
    }
    return ret;
  });
}

void FemasUnitRate::OnRspQryInstrumentMarginRate(std::shared_ptr<SpiMessage> msg) {
  std::shared_ptr<cffex_femas_fip::CUstpFtdcInvestorMarginField> margin_rate = nullptr;
  if (msg->pMainField != nullptr) {
    margin_rate = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInvestorMarginField>(msg->pMainField);
    auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);
    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = std::string(margin_rate->InstrumentID);
      rate_node->exchange_id = ConvertFromFemasExchangeID(&margin_rate->ExchangeID);
      if (rate_node->exchange_id.empty()) {
        auto exchange_id =
          m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
        if (exchange_id.has_value()) {
          rate_node->exchange_id = exchange_id->data();
        }
      }
      if (margin_rate->HedgeFlag == USTP_FTDC_CHF_Speculation || margin_rate->HedgeFlag == '\0') {
        rate_node->margin_rate_long_spec = UnitRate(margin_rate->LongMarginRate, margin_rate->LongMarginAmt);
        rate_node->margin_rate_short_spec = UnitRate(margin_rate->ShortMarginRate, margin_rate->ShortMarginAmt);
        if (std::isnan(rate_node->margin_rate_long_other.amount_rate))
          rate_node->margin_rate_long_other.amount_rate = margin_rate->LongMarginRate;
        if (std::isnan(rate_node->margin_rate_long_other.volume_rate))
          rate_node->margin_rate_long_other.volume_rate = margin_rate->LongMarginAmt;
        if (std::isnan(rate_node->margin_rate_short_other.amount_rate))
          rate_node->margin_rate_short_other.amount_rate = margin_rate->ShortMarginRate;
        if (std::isnan(rate_node->margin_rate_short_other.volume_rate))
          rate_node->margin_rate_short_other.volume_rate = margin_rate->ShortMarginAmt;
      } else {
        rate_node->margin_rate_long_other = UnitRate(margin_rate->LongMarginRate, margin_rate->LongMarginAmt);
        rate_node->margin_rate_short_other = UnitRate(margin_rate->ShortMarginRate, margin_rate->ShortMarginAmt);
      }
    });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    if (req && margin_rate) {
      auto qry = std::static_pointer_cast<QueryMarginRate>(req);
      if (!qry->instrument_id.empty() && qry->instrument_id != std::string(margin_rate->InstrumentID)) {
        auto new_margin_field = std::make_shared<cffex_femas_fip::CUstpFtdcInvestorMarginField>(*margin_rate);
        strcpy_x(new_margin_field->InstrumentID, qry->instrument_id);
        auto rate_key = m_service->m_user_key + "|" + std::string(new_margin_field->InstrumentID);
        m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
          rate_node->user_key = m_service->m_user_key;
          rate_node->instrument_id = std::string(new_margin_field->InstrumentID);
          rate_node->exchange_id = ConvertFromFemasExchangeID(&new_margin_field->ExchangeID);
          if (rate_node->exchange_id.empty()) {
            auto exchange_id =
              m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
            if (exchange_id.has_value()) {
              rate_node->exchange_id = exchange_id->data();
            }
          }
          if (new_margin_field->HedgeFlag == USTP_FTDC_CHF_Speculation || new_margin_field->HedgeFlag == '\0') {
            rate_node->margin_rate_long_spec =
              UnitRate(new_margin_field->LongMarginRate, new_margin_field->LongMarginAmt);
            rate_node->margin_rate_short_spec =
              UnitRate(new_margin_field->ShortMarginRate, new_margin_field->ShortMarginAmt);
            if (std::isnan(rate_node->margin_rate_long_other.amount_rate))
              rate_node->margin_rate_long_other.amount_rate = margin_rate->LongMarginRate;
            if (std::isnan(rate_node->margin_rate_long_other.volume_rate))
              rate_node->margin_rate_long_other.volume_rate = margin_rate->LongMarginAmt;
            if (std::isnan(rate_node->margin_rate_short_other.amount_rate))
              rate_node->margin_rate_short_other.amount_rate = margin_rate->ShortMarginRate;
            if (std::isnan(rate_node->margin_rate_short_other.volume_rate))
              rate_node->margin_rate_short_other.volume_rate = margin_rate->ShortMarginAmt;
          } else {
            rate_node->margin_rate_long_other =
              UnitRate(new_margin_field->LongMarginRate, new_margin_field->LongMarginAmt);
            rate_node->margin_rate_short_other =
              UnitRate(new_margin_field->ShortMarginRate, new_margin_field->ShortMarginAmt);
          }
        });
      }
    }
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void FemasUnitRate::OnRspQryOptionTradeCost(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto margin_rate = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcOptionTradeCostField>(msg->pMainField);
    auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);

    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = std::string(margin_rate->InstrumentID);
      rate_node->exchange_id = ConvertFromFemasExchangeID(&margin_rate->ExchangeID);
      double rate = (std::max)((margin_rate->FixedMargin + margin_rate->Premium), margin_rate->MiniMargin);
      if (margin_rate->HedgeFlag == '\0') {
        rate_node->margin_rate_short_spec.volume_rate = rate;
        rate_node->margin_rate_short_other.volume_rate = rate;
      } else if (margin_rate->HedgeFlag == USTP_FTDC_CHF_Speculation) {
        rate_node->margin_rate_short_spec.volume_rate = rate;
      } else {
        rate_node->margin_rate_short_other.volume_rate = rate;
      }
    });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    if (req) {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  }
}

