    SpiMessage::Tag::OnRspTradingAccountPasswordUpdate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspTradingAccountPasswordUpdate(msg);
    });
}

void FemasUnitItems::ReqChangePasswordBeforeLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePasswordBeforeLogin>(m_service->m_command_manager->Update(command));
  if (m_service->IsLogined()) {
    SetCommandFinished(req, -1, u8"fclib: 账户已登录,请调用登录后修改密码接口");
    return;
  }
  if (!req->req_login->replay_flow_file_name.empty() || req->req_login->user_id == "STRESS-TESTING-100") {
    SetCommandFinished(req, -1, u8"fclib: 当前模式无法修改密码");
    return;
  }
  m_service->m_req_change_password_before_login = req;
  m_service->m_req_change_password_before_login->req_login->password = req->old_password;
  m_service->m_req_login = m_service->m_req_change_password_before_login->req_login;
  m_service->BuildApi(false);
  m_logger.Info("ReqChangePasswordBeforeLogin");
  m_service->m_command_manager->SetCommandId(command, "change_password_before_login");
}

void FemasUnitItems::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_service->m_command_manager->Update(command));
  if (!m_service->IsApiReady()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  int request_id;
  if (req->query_request_id > 0) {
    request_id = req->query_request_id;
  } else {
    request_id = m_service->GenerateRequestID();
  }
  if (req->password_type == PasswordType::kTrade) {
    cffex_femas_fip::CUstpFtdcUserPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.BrokerID, m_service->m_broker_id);
    strcpy_x(field.UserID, m_service->m_req_login->user_id);
    int ret = m_service->m_api->ReqUserPasswordUpdate(&field, request_id);
    LogFemasReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
    if (ret == 0) {
      m_service->SetReqResponse(command, request_id, ret);
    } else {
      SetCommandFinished(command, ret, u8"飞马主席: " + std::to_string(ret) + u8", 修改交易密码指令发送失败");
    }
  } else {
    cffex_femas_fip::CUstpFtdcTradingAccountPasswordUpdateReqField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.BrokerID, m_service->m_broker_id);
    strcpy_x(field.InvestorID, m_service->m_investor_id);
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    int ret = m_service->m_api->ReqTradingAccountPasswordUpdate(&field, request_id);
    LogFemasReq(m_logger, "ReqTradingAccountPasswordUpdate", &field, 0, ret);
    if (ret == 0) {
      m_service->SetReqResponse(command, request_id, ret);
    } else {
      SetCommandFinished(command, ret, u8"飞马主席: " + std::to_string(ret) + u8", 修改资金密码指令发送失败");
    }
  }
}

