  if (m_service->m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  } else {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

