}

void FemasUnitItems::RequireQryCFMMCToken(std::shared_ptr<UserCommand> command) {
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  if (m_service->m_query_planner.AlreadyInQueue("RequireQryCFMMCToken")) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcCFMMCTradingAccountKeyReqField>();
  memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcCFMMCTradingAccountKeyReqField));
  strcpy_x(field->BrokerID, m_service->m_broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "RequireQryCFMMCToken");
  m_service->m_query_planner.AddTask(
    "RequireQryCFMMCToken", FemasQueryPlanner::Priority::kHigh, request_id, [=](int request_id) {
      auto ret = m_service->m_api->ReqCFMMCTradingAccountKey(field.get(), request_id);
      if (ret >= 0)
        LogFemasReq(m_logger, "ReqQueryCFMMCTradingAccountToken", field.get(), request_id, ret);
      return ret;
    });
}

void FemasUnitItems::OnRspCFMMCTradingAccountKey(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("RequireQryCFMMCToken"));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  if (msg->pMainField != nullptr) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("RequireQryCFMMCToken"));
    if (!req)
      return;
    auto field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcCFMMCTradingAccountKeyRspField>(msg->pMainField);
    SetCommandFinished(req, 0,
      std::string(field->ParticipantID) + ";" + std::to_string(field->KeyID) + ";" + std::string(field->CurrentKey));
  }
}

void FemasUnitItems::SubmitUserSystemInfo(std::shared_ptr<UserCommand> command) {
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  auto submit_command =
    std::static_pointer_cast<future::SubmitUserSystemInfo>(m_service->m_command_manager->Update(command));
  cffex_femas_fip::CUstpFtdcDSProxySubmitDataField field;
  strcpy_x(field.TerminalPubNetIP, submit_command->client_ip);
  strcpy_x(field.TerminalPubNetPort, std::to_string(submit_command->client_port));
  strcpy_x(field.AppID, submit_command->client_app_id);
  auto now = EpochNanoToLocalDateTime(NowAsEpochNano());
  snprintf(
    field.TerminalLoginTime, 9, "%02d:%02d:%02d", now.date_time.tm_hour, now.date_time.tm_min, now.date_time.tm_sec);
  int req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqDSProxySubmitInfo(&field, req_id);
  LogFemasReq(m_logger, "SubmitUserSystemInfo", &field, req_id, ret);
  SetCommandFinished(command, ret);
}

