#include "femas_convert.h"
#include <memory>
#include <string>
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace femas {

void ConvertToFemasDirection(future::Direction d, cffex_femas_fip::TUstpFtdcDirectionType* t) {
  if (d == Direction::kBuy) {
    *t = USTP_FTDC_D_Buy;
  } else if (d == Direction::kSell) {
    *t = USTP_FTDC_D_Sell;
  } else {
    FCASSERT(false);
  }
}

future::Direction ConvertFromFemasDirection(const cffex_femas_fip::TUstpFtdcDirectionType* t) {
  if (*t == USTP_FTDC_D_Buy)
    return future::Direction::kBuy;
  else if (*t == USTP_FTDC_D_Sell)
    return future::Direction::kSell;
  return future::Direction::kInvalid;
}

void ConvertToFemasExchangeID(std::string d, cffex_femas_fip::TUstpFtdcExchangeIDType* t) {
  if (d == "CZCE")
    strcpy_x(*t, "ZCE");
  else
    strcpy_x(*t, d);
}

std::string ConvertFromFemasExchangeID(const cffex_femas_fip::TUstpFtdcExchangeIDType* t) {
  if (std::string(*t) == "ZCE")
    return "CZCE";
  return std::string(*t);
}

future::OrderStatus ConvertFromFemasParkStatus(const cffex_femas_fip::TUstpFtdcParkedOrderStatusType* t) {
  // 已触发待报、已接受、未知状态都认为是有效的预埋单
  if (*t == USTP_FTDC_POS_TriggeredSubmitting || *t == USTP_FTDC_POS_FemasAccepted || *t == USTP_FTDC_POS_Unknown) {
    return OrderStatus::kAlive;
  } else {
    return OrderStatus::kDead;
  }
}

future::ExecOrderResultType ConvertFromExecOrderResultType(const cffex_femas_fip::TUstpFtdcExecResultType& t) {
  switch (t) {
    case USTP_FTDC_EXRST_NoExec: return future::ExecOrderResultType::kNoExec;
    case USTP_FTDC_EXRST_Canceled: return future::ExecOrderResultType::kCanceled;
    case USTP_FTDC_EXRST_OK: return future::ExecOrderResultType::kSuccess;
    case USTP_FTDC_EXRST_NoPosition: return future::ExecOrderResultType::kNoPosition;
    case USTP_FTDC_EXRST_NoDeposit: return future::ExecOrderResultType::kNoDeposit;
    case USTP_FTDC_EXRST_NoParticipant: return future::ExecOrderResultType::kNoParticipant;
    case USTP_FTDC_EXRST_NoClient: return future::ExecOrderResultType::kNoClient;
    case USTP_FTDC_EXRST_NoInstrument: return future::ExecOrderResultType::kNoInstrument;
    case USTP_FTDC_EXRST_NoRight: return future::ExecOrderResultType::kNoRight;
    case USTP_FTDC_EXRST_InvalidVolume: return future::ExecOrderResultType::kInvalidVolume;
    case USTP_FTDC_EXRST_NoEnoughHistoryTrade: return future::ExecOrderResultType::kNoEnoughHistoryTrade;
    default: return future::ExecOrderResultType::kUnKnown;
  }
}

void ConvertToFemasExecAction(future::ExecActionType d, cffex_femas_fip::TUstpFtdcOrderTypeType& t) {
  if (d == future::ExecActionType::kExec) {
    t = USTP_FTDC_OT_OptExec;
  } else if (d == future::ExecActionType::kAbandon) {
    t = USTP_FTDC_OT_OptAbandon;
  }
}

future::ExecActionType ConvertFromFemasExecAction(const cffex_femas_fip::TUstpFtdcOrderTypeType& t) {
  if (t == USTP_FTDC_OT_OptExec)
    return future::ExecActionType::kExec;
  else if (t == USTP_FTDC_OT_OptAbandon)
    return future::ExecActionType::kAbandon;
  FCASSERT(false);
  return future::ExecActionType::kClose;
}

future::Offset ConvertFromFemasOffset(const cffex_femas_fip::TUstpFtdcOffsetFlagType* t) {
  if (*t == USTP_FTDC_OF_Open) {
    return future::Offset::kOpen;
  } else if (*t == USTP_FTDC_OF_CloseToday) {
    return future::Offset::kCloseToday;
  } else if (*t == USTP_FTDC_OF_CloseYesterday) {
    return future::Offset::kCloseYesterday;
  } else if (*t == USTP_FTDC_OF_ALL) {
    return future::Offset::kInvalid;
  } else {
    return future::Offset::kClose;
  }
}

void ConvertToFemasHedgeFlag(future::OrderHedgeFlag h, cffex_femas_fip::TUstpFtdcHedgeFlagType* t) {
  if (h == future::OrderHedgeFlag::kArbitrage)
    *t = USTP_FTDC_CHF_Arbitrage;
  else if (h == future::OrderHedgeFlag::kHedge)
    *t = USTP_FTDC_CHF_Hedge;
  else if (h == future::OrderHedgeFlag::kMarketMaker)
    *t = USTP_FTDC_CHF_MarketMaker;
  else if (h == future::OrderHedgeFlag::kSpecAndHedge)
    *t = USTP_FTDC_CHF_SpecHedge;
  else if (h == future::OrderHedgeFlag::kHedgeAndSpec)
    *t = USTP_FTDC_CHF_HedgeSpec;
  else
    *t = USTP_FTDC_CHF_Speculation;
}

future::OrderHedgeFlag ConvertFromFemasHedgeFlag(const cffex_femas_fip::TUstpFtdcHedgeFlagType* t) {
  if (*t == USTP_FTDC_CHF_Speculation) {
    return future::OrderHedgeFlag::kSpeculation;
  } else if (*t == USTP_FTDC_CHF_MarketMaker) {
    return future::OrderHedgeFlag::kMarketMaker;
  } else if (*t == USTP_FTDC_CHF_Hedge) {
    return future::OrderHedgeFlag::kHedge;
  } else if (*t == USTP_FTDC_CHF_Arbitrage) {
    return future::OrderHedgeFlag::kArbitrage;
  }
  FCASSERT(false);
  return future::OrderHedgeFlag::kSpeculation;
}

future::PriceType ConvertFromFemasOrderPriceType(const cffex_femas_fip::TUstpFtdcOrderPriceTypeType* t) {
  if (*t == USTP_FTDC_OPT_LimitPrice) {
    return future::PriceType::kLimit;
  } else if (*t == USTP_FTDC_OPT_AnyPrice) {
    return future::PriceType::kAny;
  } else if (*t == USTP_FTDC_OPT_BestPrice) {
    return future::PriceType::kBest;
  } else if (*t == USTP_FTDC_OPT_FiveLevelPrice) {
    return future::PriceType::kFiveLevel;
  }
  FCASSERT(false);
  return future::PriceType::kLimit;
}

future::OrderStatus ConvertFromFemasOrderStatus(const cffex_femas_fip::TUstpFtdcOrderStatusType* t) {
  if (*t == USTP_FTDC_OS_AllTraded || *t == USTP_FTDC_OS_Canceled || *t == USTP_FTDC_OS_TimeOut) {
    return future::OrderStatus::kDead;
  }
  return future::OrderStatus::kAlive;
}

future::OrderStatus ConvertFromFemasQuoteStatus(const cffex_femas_fip::TUstpFtdcQuoteStatusType* t) {
  if (*t == USTP_FTDC_QS_Canceled_All || *t == USTP_FTDC_QS_Traded_All) {
    return future::OrderStatus::kDead;
  }
  return future::OrderStatus::kAlive;
}

future::OrderTimeCondition ConvertFromFemasTimeCondition(const cffex_femas_fip::TUstpFtdcTimeConditionType* t) {
  if (*t == USTP_FTDC_TC_IOC) {
    return future::OrderTimeCondition::kIoc;
  } else if (*t == USTP_FTDC_TC_GFD) {
    return future::OrderTimeCondition::kGfd;
  } else if (*t == USTP_FTDC_TC_GFS) {
    return future::OrderTimeCondition::kGfs;
  } else if (*t == USTP_FTDC_TC_GTD) {
    return future::OrderTimeCondition::kGtd;
  } else if (*t == USTP_FTDC_TC_GTC) {
    return future::OrderTimeCondition::kGtc;
  } else if (*t == USTP_FTDC_TC_GFA) {
    return future::OrderTimeCondition::kGfa;
  }
  FCASSERT(false);
  return future::OrderTimeCondition::kInvalid;
}

future::OrderVolumeCondition ConvertFromFemasVolumeCondition(const cffex_femas_fip::TUstpFtdcVolumeConditionType* t) {
  if (*t == USTP_FTDC_VC_AV) {
    return future::OrderVolumeCondition::kAny;
  } else if (*t == USTP_FTDC_VC_MV) {
    return future::OrderVolumeCondition::kMin;
  } else if (*t == USTP_FTDC_VC_CV) {
    return future::OrderVolumeCondition::kAll;
  }
  FCASSERT(false);
  return future::OrderVolumeCondition::kInvalid;
}

future::ForceCloseReason ConvertFromFemasForceCloseReason(const cffex_femas_fip::TUstpFtdcForceCloseReasonType* t) {
  if (*t == USTP_FTDC_FCR_NotForceClose) {
    return future::ForceCloseReason::kNotForceClose;
  } else if (*t == USTP_FTDC_FCR_LackDeposit) {
    return future::ForceCloseReason::kLackDeposit;
  } else if (*t == USTP_FTDC_FCR_ClientOverPositionLimit) {
    return future::ForceCloseReason::kClientOverPositionLimit;
  } else if (*t == USTP_FTDC_FCR_MemberOverPositionLimit) {
    return future::ForceCloseReason::kMemberOverPositionLimit;
  } else if (*t == USTP_FTDC_FCR_NotMultiple) {
    return future::ForceCloseReason::kNotMultiple;
  } else if (*t == USTP_FTDC_FCR_Violation) {
    return future::ForceCloseReason::kViolation;
  } else if (*t == USTP_FTDC_FCR_Other) {
    return future::ForceCloseReason::kOther;
  } else if (*t == USTP_FTDC_FCR_PersonDeliv) {
    return future::ForceCloseReason::kPersonDeliv;
  } else if (*t == USTP_FTDC_FCR_HedgeOverPositionLimit) {
    return future::ForceCloseReason::kHedgeOverPositionLimit;
  }
  FCASSERT(false);
  return future::ForceCloseReason::kNotForceClose;
}

void ConvertToFemasTimeCondition(future::OrderTimeCondition d, cffex_femas_fip::TUstpFtdcTimeConditionType* t) {
  if (d == OrderTimeCondition::kIoc) {
    *t = USTP_FTDC_TC_IOC;
  } else if (d == OrderTimeCondition::kGfd) {
    *t = USTP_FTDC_TC_GFD;
  } else if (d == OrderTimeCondition::kGfs) {
    *t = USTP_FTDC_TC_GFS;
  } else if (d == OrderTimeCondition::kGfa) {
    *t = USTP_FTDC_TC_GFA;
  } else if (d == OrderTimeCondition::kGtc) {
    *t = USTP_FTDC_TC_GTC;
  } else if (d == OrderTimeCondition::kGtd) {
    *t = USTP_FTDC_TC_GTD;
  } else {
    FCASSERT(false);
  }
}

void ConvertToFemasOrderPriceType(future::PriceType d, cffex_femas_fip::TUstpFtdcOrderPriceTypeType* t) {
  if (d == PriceType::kAny) {
    *t = USTP_FTDC_OPT_AnyPrice;
  } else if (d == PriceType::kBest) {
    *t = USTP_FTDC_OPT_BestPrice;
  } else if (d == PriceType::kFiveLevel) {
    *t = USTP_FTDC_OPT_FiveLevelPrice;
  } else if (d == PriceType::kLimit) {
    *t = USTP_FTDC_OPT_LimitPrice;
  } else {
    FCASSERT(false);
  }
}

void ConvertToFemasVolumeCondition(future::OrderVolumeCondition d, cffex_femas_fip::TUstpFtdcVolumeConditionType* t) {
  if (d == OrderVolumeCondition::kAll) {
    *t = USTP_FTDC_VC_CV;
  } else if (d == OrderVolumeCondition::kAny) {
    *t = USTP_FTDC_VC_AV;
  } else if (d == OrderVolumeCondition::kMin) {
    *t = USTP_FTDC_VC_MV;
  } else {
    FCASSERT(false);
  }
}

void ConvertToFemasOffsetFlag(future::Offset d, cffex_femas_fip::TUstpFtdcOffsetFlagType* t) {
  if (d == Offset::kOpen) {
    *t = USTP_FTDC_OF_Open;
  } else if (d == Offset::kClose) {
    *t = USTP_FTDC_OF_Close;
  } else if (d == Offset::kCloseToday) {
    *t = USTP_FTDC_OF_CloseToday;
  } else if (d == Offset::kCloseYesterday) {
    *t = USTP_FTDC_OF_CloseYesterday;
  } else {
    FCASSERT(false);
  }
}

md::TradeStatus ConvertFromFemasInstrumentStatusType(const cffex_femas_fip::TUstpFtdcInstrumentStatusType* t) {
  if (*t == USTP_FTDC_IS_BeforeTrading) {
    return md::TradeStatus::kBeforeTrading;
  } else if (*t == USTP_FTDC_IS_NoTrading) {
    return md::TradeStatus::kNoTrading;
  } else if (*t == USTP_FTDC_IS_Continous) {
    return md::TradeStatus::kContinous;
  } else if (*t == USTP_FTDC_IS_AuctionOrdering) {
    return md::TradeStatus::kAuctionOrdering;
  } else if (*t == USTP_FTDC_IS_AuctionBalance) {
    return md::TradeStatus::kAuctionBalance;
  } else if (*t == USTP_FTDC_IS_AuctionMatch) {
    return md::TradeStatus::kAuctionMatch;
  } else if (*t == USTP_FTDC_IS_Closed) {
    return md::TradeStatus::kClosed;
  }
  FCASSERT(false);
  return md::TradeStatus::kUnknown;
}

void ConvertToFemasOrderField(
  const std::shared_ptr<future::InsertOrder> d, std::shared_ptr<cffex_femas_fip::CUstpFtdcInputOrderField> field) {
  strcpy_x(field->InstrumentID, d->instrument_id);
  ConvertToFemasExchangeID(d->exchange_id, &field->ExchangeID);
  ConvertToFemasDirection(d->direction, &field->Direction);
  ConvertToFemasOffsetFlag(d->offset, &field->OffsetFlag);
  ConvertToFemasHedgeFlag(d->hedge_flag, &field->HedgeFlag);
  field->Volume = d->volume;
  field->LimitPrice = d->limit_price;
  if (isnan(d->limit_price))
    field->LimitPrice = 0.0;
  ConvertToFemasOrderPriceType(d->price_type, &field->OrderPriceType);
  ConvertToFemasTimeCondition(d->time_condition, &field->TimeCondition);
  ConvertToFemasVolumeCondition(d->volume_condition, &field->VolumeCondition);
  field->ForceCloseReason = USTP_FTDC_FCR_NotForceClose;
  std::string head = d->instrument_id.substr(0, 3);
  if (head == "SP " || head == "SPD") {
    field->ArbiType = USTP_FTDC_AT_SP;
  } else if (head == "SPC" || head == "IPS") {
    field->ArbiType = USTP_FTDC_AT_SPC;
  } else {
    field->ArbiType = USTP_FTDC_AT_Basic;
  }
  if (d->is_swap_order) {
    field->ArbiType = USTP_FTDC_AT_Swap;
  }
}

std::string ToFclibOrderId(const cffex_femas_fip::TUstpFtdcUserOrderLocalIDType& user_order_id,
  const std::string& local_order_id, const cffex_femas_fip::TUstpFtdcSessionIDType& session_id,
  const cffex_femas_fip::TUstpFtdcFrontIDType& front_id) {
  auto order_ref = std::string(user_order_id);
  if (order_ref.empty())
    order_ref = local_order_id;
  return order_ref + "|" + std::to_string(session_id) + "|" + std::to_string(front_id);
}

