FemasUnitBank::FemasUnitBank(FemasServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("unit_bank", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(TransferMoney::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqTransferMoney(command);
  });
  m_service->RegisterCommandProcessor(QueryAccountregister::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryAccountregister(command);
  });
  m_service->RegisterCommandProcessor(QueryContractBank::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryContractBank(command);
  });
  m_service->RegisterCommandProcessor(QueryTransferLog::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryTransferSerial(command);
  });
  m_service->RegisterCommandProcessor(QueryBankBalance::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryBankBalance(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspFromBankToFutureByFuture, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspTransferMoney(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspFromFutureToBankByFuture, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspTransferMoney(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryAccountregister, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryAccountregister(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryContractBank, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryContractBank(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTransferSerial, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTransferSerial(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryBankBalance, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryBankBalance(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnBankBalance, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnBankBalance(msg);
  });
  m_bank_view = m_service->m_node_db->CreateView<Bank>([&](std::shared_ptr<const Bank> bank) {
    return bank->user_key == m_service->m_user_key;
  });
}

void FemasUnitBank::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<TransferMoney>(m_service->m_command_manager->Update(command));
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  std::string bank_account;
  for (const auto& [_, node] : m_bank_view->GetNodes()) {
    if (node->Latest()->bank_id == req->bank_id) {
      bank_account = node->Latest()->bank_account;
      break;
    }
  }
  if (bank_account.empty()) {
    SetCommandFinished(command, -1, u8"fclib: 银行编号无效");
    return;
  }
  int ret = 0;
  cffex_femas_fip::CUstpFtdcTransferFieldReqField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_broker_id);
  strcpy_x(field.BankID, req->bank_id);
  strcpy_x(field.BankAccount, bank_account);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.AccountID, req->account_id);
  strcpy_x(field.AccountPwd1, req->future_password);
  strcpy_x(field.BankAccountPwd1, req->bank_password);
  strcpy_x(field.CurrencyID, req->currency);
  field.TradeAmount = req->amount;
  auto request_id = m_service->GenerateRequestID();
  if (req->is_deposit) {
    // 入金
    ret = m_service->m_api->ReqFromBankToFutureByFuture(&field, request_id);
  } else {
    // 出金
    ret = m_service->m_api->ReqFromFutureToBankByFuture(&field, request_id);
  }
  memset(field.AccountPwd1, 0, sizeof(field.AccountPwd1));
  memset(field.BankAccountPwd1, 0, sizeof(field.BankAccountPwd1));
  LogFemasReq(m_logger, "ReqTransferMoney", &field, request_id, ret);
  m_service->SetReqResponse(command, request_id, ret);
}

void FemasUnitBank::OnRspTransferMoney(std::shared_ptr<SpiMessage> msg) {
  auto qry = std::make_shared<QueryTradingAccount>(m_service->m_user_key);
  m_service->ExecuteCommand(qry);

  if (msg->pMainField) {
    auto transfer_field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcTransferFieldReqField>(msg->pMainField);

    auto command = std::make_shared<QueryTransferLog>(m_service->m_user_key);
    command->account_id = transfer_field->AccountID;
    command->bank_id = transfer_field->BankID;
    m_service->ExecuteCommand(command);
  }

  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

