void FemasUnitBank::OnRspQryContractBank(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pBank = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcQryContractBankRspField>(msg->pMainField);
    bool insert = true;
    for (const auto& [key, bank_node] : m_bank_view->GetNodes()) {
      if (bank_node->Latest()->bank_id == GbkToUtf8(pBank->BankID)) {
        insert = false;
        m_service->m_node_db->ReplaceRecord<Bank>(key, [&](std::shared_ptr<future::Bank> bank) {
          if (bank->bank_name.empty()) {
            bank->bank_name = GbkToUtf8(pBank->BankName);
          }
        });
      }
    }
    if (insert)
      m_bank_id_name[pBank->BankID] = pBank->BankName;
  }
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

