void FemasUnitBank::OnRspQryTransferSerial(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pTransferSerial =
      std::static_pointer_cast<cffex_femas_fip::CUstpFtdcTransferSerialFieldRspField>(msg->pMainField);
    auto target_transferserial = std::make_shared<TransferLog>();
    target_transferserial->user_key = m_service->m_user_key;
    target_transferserial->amount = pTransferSerial->TradeAmount;
    target_transferserial->currency = pTransferSerial->CurrencyID;
    if (target_transferserial->currency.empty())
      target_transferserial->currency = "CNY";
    std::string rtn_code = pTransferSerial->RtnCode;
    if (!rtn_code.empty() && std::all_of(rtn_code.begin(), rtn_code.end(), ::isdigit))
      target_transferserial->error_id = std::stoi(rtn_code);
    target_transferserial->error_msg = GbkToUtf8(pTransferSerial->RtnMsg);
    target_transferserial->bank_account = GbkToUtf8(pTransferSerial->BankAccount);
    std::string tradecode = pTransferSerial->TradeCode;
    if (tradecode == "11") {
      target_transferserial->trade_type = u8"查询银行余额";
    } else if (tradecode == "15") {
      target_transferserial->trade_type = u8"入金";
    } else if (tradecode == "16") {
      target_transferserial->trade_type = u8"出金";
    }
    target_transferserial->bank_serial = pTransferSerial->BankSerial;
    std::string future_serial = pTransferSerial->FutureSerial;
    if (!future_serial.empty() && std::all_of(future_serial.begin(), future_serial.end(), ::isdigit))
      target_transferserial->future_serial = std::stoi(future_serial);
    target_transferserial->bank_id = pTransferSerial->BankID;
    target_transferserial->bank_branch_id = pTransferSerial->BankBrchID;
    if (pTransferSerial->TradingDay[0] != '\0' && pTransferSerial->TradeTime[0] != '\0')
      target_transferserial->date_time = StringToEpochNano(pTransferSerial->TradingDay, pTransferSerial->TradeTime);
    m_service->m_node_db->ReplaceRecord<TransferLog>(target_transferserial);
  }
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

