template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, const T* plain_src = nullptr,
  cffex_femas_fip::CUstpFtdcRspInfoField* rsp_info = nullptr, int req_id = 0, bool is_last = true) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  if (rsp_info)
    memcpy(&msg->RspInfo, rsp_info, sizeof(cffex_femas_fip::CUstpFtdcRspInfoField));
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

