void FemasUnitExecOrder::ReqInsertExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsApiReady() || !m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  cffex_femas_fip::CUstpFtdcInputExecOrderField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.InstrumentID, req->instrument_id);
  ConvertToFemasExchangeID(req->exchange_id, &field.ExchangeID);

  if (req->exec_action_type == ExecActionType::kAbandon) {
    field.OrderType = USTP_FTDC_OT_OptAbandon;
    field.DeliveryFlag = USTP_FTDC_DF_ExecOpen;
  } else {
    field.OrderType = USTP_FTDC_OT_OptExec;
    field.DeliveryFlag =
      req->close_flag == ExecOrderCloseFlag::kAutoClose ? USTP_FTDC_DF_Delivery : USTP_FTDC_DF_ExecOpen;
  }
  field.Volume = req->volume;
  ConvertToFemasOffsetFlag(req->offset, &field.OffsetFlag);
  ConvertToFemasHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  strcpy_x(field.UserOrderLocalID, std::to_string(req->exec_order_ref));

  auto exec_order_id =
    ToFclibOrderId(field.UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
  FCASSERT(exec_order_id == req->exec_order_id);
  auto req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderInsert(&field, req_id);
  LogFemasReq(m_logger, "ReqExecOrderInsert", &field, 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqExecOrderInsert" + exec_order_id);
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 行权指令发送失败");
}

void FemasUnitExecOrder::OnRspExecOrderInsert(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInputExecOrderField>(msg->pMainField);
  auto exec_order_id =
    ToFclibOrderId(field->UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
  auto req = m_service->m_command_manager->Update("ReqExecOrderInsert" + exec_order_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void FemasUnitExecOrder::OnRtnExecOrder(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcExecOrderField>(msg->pMainField);
  auto exec_order_id = ToFclibOrderId(field->UserOrderLocalID, "", field->SessionID, field->FrontID);

  auto target_execorder = std::make_shared<ExecOrder>();
  target_execorder->instrument_id = field->InstrumentID;
  target_execorder->exchange_id = ConvertFromFemasExchangeID(&field->ExchangeID);
  target_execorder->investor_id = field->InvestorID;
  target_execorder->volume = field->Volume;
  target_execorder->offsetflag = femas::ConvertFromFemasOffset(&field->OffsetFlag);
  target_execorder->hedge_flag = femas::ConvertFromFemasHedgeFlag(&field->HedgeFlag);
  target_execorder->exchange_exec_order_sysid = field->OrderSysID;
  target_execorder->exec_close_flag =
    field->DeliveryFlag == USTP_FTDC_DF_Delivery ? ExecOrderCloseFlag::kAutoClose : ExecOrderCloseFlag::kNotToClose;
  target_execorder->exec_action_type =
    field->OrderType == USTP_FTDC_OT_OptAbandon ? ExecActionType::kAbandon : ExecActionType::kExec;
  target_execorder->exec_result =
    field->OrderStatus == USTP_FTDC_OS_Canceled ? ExecOrderResultType::kCanceled : ExecOrderResultType::kNoExec;
  target_execorder->exec_order_ref = field->UserOrderLocalID;
  target_execorder->front_id = field->FrontID;
  target_execorder->session_id = field->SessionID;
  target_execorder->insert_date_time = StringToEpochNano(field->TradingDay, field->InsertTime);
  target_execorder->user_key = m_service->m_user_key;
  if (field->CancelTime[0] != '\0') {
    target_execorder->cancel_time = StringToEpochNano(field->TradingDay, field->CancelTime);
  }
  target_execorder->exec_order_id = exec_order_id;
  m_service->m_node_db->ReplaceRecord<ExecOrder>(target_execorder);
  if (field->OrderStatus == USTP_FTDC_OS_Canceled) {
    m_alive_exec_orders.erase(exec_order_id);
  } else {
    m_alive_exec_orders[exec_order_id] = field;
  }
}

void FemasUnitExecOrder::ReqCancelExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsApiReady() || !m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  auto it = m_alive_exec_orders.find(req->exec_order_id);
  if (it == m_alive_exec_orders.end()) {
    SetCommandFinished(req, -1, u8"fclib: 撤消行权失败, 找不到此行权单");
    return;
  }
  auto& exec_field = it->second;
  cffex_femas_fip::CUstpFtdcInputExecOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, exec_field->BrokerID);
  strcpy_x(field.UserID, exec_field->UserID);
  strcpy_x(field.InvestorID, exec_field->InvestorID);
  strcpy_x(field.InstrumentID, exec_field->InstrumentID);
  strcpy_x(field.ExchangeID, exec_field->ExchangeID);
  strcpy_x(field.OrderSysID, exec_field->OrderSysID);
  field.ActionFlag = USTP_FTDC_AF_Delete;
  strcpy_x(field.UserOrderLocalID, exec_field->UserOrderLocalID);

  auto req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderAction(&field, req_id);
  LogFemasReq(m_logger, "ReqExecOrderAction", &field, 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqExecOrderAction" + std::string(field.OrderSysID));
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 撤销行权指令发送失败");
}

