void FemasUnitExecOrder::ReqInsertSelfCloseOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOptionSelfClose>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsApiReady() || !m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  cffex_femas_fip::CUstpFtdcInputExecSelfCloseField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  field.Volume = req->volume;

  std::string ins_id;
  if (!req->instrument_id.empty()) {
    ins_id = req->instrument_id;
  } else if (!req->underlying_instrument_id.empty()) {
    ins_id = req->underlying_instrument_id;
  } else if (!req->product_id.empty()) {
    size_t pos = req->product_id.find('_');
    if (pos != std::string::npos)
      ins_id = req->product_id.substr(0, pos);
    else
      ins_id = req->product_id;
  } else {
    ins_id = "ALL";
  }
  strcpy_x(field.InstrumentID, ins_id);
  ConvertToFemasExchangeID(req->exchange_id, &field.ExchangeID);
  ConvertToFemasHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  if (req->close_flag == SelfCloseType::kOptionPosition) {
    field.SelfCloseFlag = USTP_FTDC_DF_OptDelivery;
  } else if (req->close_flag == SelfCloseType::kReserveOptionPosition) {
    field.SelfCloseFlag = USTP_FTDC_DF_OptHold;
  } else if (req->close_flag == SelfCloseType::kFuturePosition) {
    field.SelfCloseFlag = USTP_FTDC_DF_FutDelivery;
  } else if (req->close_flag == SelfCloseType::kSelfFuturePositionBuy) {
    field.SelfCloseFlag = USTP_FTDC_DF_Delivery;
  } else if (req->close_flag == SelfCloseType::kSelfFuturePosition) {
    field.SelfCloseFlag = USTP_FTDC_DF_SellDelivery;
  } else {
    field.SelfCloseFlag = USTP_FTDC_DF_SellNoDelivery;
  }
  strcpy_x(field.UserSelfCloseLocalID, std::to_string(req->self_close_ref));
  field.IsOffset = req->is_offset ? 1 : 0;
  auto req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecSelfCloseInsert(&field, req_id);
  LogFemasReq(m_logger, "ReqExecSelfCloseInsert", &field, 0, ret);
  m_service->m_command_manager->SetCommandId(
    command, "ReqExecSelfCloseInsert" + std::string(field.UserSelfCloseLocalID));
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 自对冲指令发送失败");
}

