  auto field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcExecSelfCloseField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqExecSelfCloseInsert" + std::string(field->UserSelfCloseLocalID));
