void FemasUnitExecOrder::OnRtnExecSelfClose(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcExecSelfCloseField>(msg->pMainField);
  auto target_option_self_close = std::make_shared<OptionSelfClose>();
  target_option_self_close->instrument_id = field->InstrumentID;
  target_option_self_close->exchange_id = ConvertFromFemasExchangeID(&field->ExchangeID);
  target_option_self_close->broker_id = field->BrokerID;
  target_option_self_close->investor_id = field->InvestorID;
  target_option_self_close->exchange_self_close_sysid = field->SelfCloseSysID;
  target_option_self_close->volume = field->Volume;
  if (field->SelfCloseFlag == USTP_FTDC_DF_OptDelivery) {
    target_option_self_close->close_type_flag =
      field->IsOffset == 1 ? SelfCloseType::kOptionPosition : SelfCloseType::kNotOptionPosition;
  } else if (field->SelfCloseFlag == USTP_FTDC_DF_OptHold) {
    target_option_self_close->close_type_flag = SelfCloseType::kReserveOptionPosition;
  } else if (field->SelfCloseFlag == USTP_FTDC_DF_SellNoDelivery) {
    target_option_self_close->close_type_flag = SelfCloseType::kReserveFuturePosition;
  } else if (field->SelfCloseFlag == USTP_FTDC_DF_Delivery) {
    target_option_self_close->close_type_flag =
      field->IsOffset == 1 ? SelfCloseType::kSelfFuturePositionBuy : SelfCloseType::kNotSelfFuturePositionBuy;
  } else if (field->SelfCloseFlag == USTP_FTDC_DF_SellDelivery) {
    target_option_self_close->close_type_flag =
      field->IsOffset == 1 ? SelfCloseType::kSelfFuturePosition : SelfCloseType::kNotSelfFuturePosition;
  } else {
    target_option_self_close->close_type_flag =
      field->IsOffset == 1 ? SelfCloseType::kFuturePosition : SelfCloseType::kNotFuturePosition;
  }
  target_option_self_close->hedge_flag = femas::ConvertFromFemasHedgeFlag(&field->HedgeFlag);
  target_option_self_close->exec_result = ConvertFromExecOrderResultType(field->ExecResult);
  target_option_self_close->insert_date_time = StringToEpochNano(field->InsertDate, field->InsertTime);
  if (field->CancelTime[0] != '\0') {
    target_option_self_close->cancel_time = StringToEpochNano(field->InsertDate, field->CancelTime);
  }
  target_option_self_close->option_self_close_ref = field->UserSelfCloseLocalID;
  target_option_self_close->front_id = field->FrontID;
  target_option_self_close->session_id = field->SessionID;
  target_option_self_close->self_close_id =
    ToFclibOrderId(field->UserSelfCloseLocalID, "", field->SessionID, field->FrontID);
  target_option_self_close->user_key = m_service->m_user_key;
  m_service->m_node_db->ReplaceRecord<OptionSelfClose>(target_option_self_close);
  if (field->ExecResult == USTP_FTDC_EXRST_NoExec || field->ExecResult == USTP_FTDC_EXRST_Unknown) {
    m_alive_self_close_orders[target_option_self_close->self_close_id] = field;
  } else {
    m_alive_self_close_orders.erase(target_option_self_close->self_close_id);
  }
}

