  SerializerFemasLog ss;
  ss.FromString(log_line.c_str());
  std::string msg = (*ss.m_doc)["msg"].GetString();
  std::string dts = (*ss.m_doc)["time"].GetString();
  SpiMessage::Tag t;
  if (!StringToTag(&t, msg))
    return nullptr;
  int64_t dt = DateTimeStringToEpochNano(dts.c_str());
