FemasUnitInsertCancelOrder::FemasUnitInsertCancelOrder(FemasServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderAction(msg);
  });
  // 预埋Rsp 设置req状态
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspParkedOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspParkedOrderInsert(msg);
  });
  // 查询预埋回包 设置req状态
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryParkedOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryParkedOrder(msg);
  });
  // 撤预埋Rsp 设置Req状态
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspParkedOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspParkedOrderAction(msg);
  });
}

void FemasUnitInsertCancelOrder::OnRspQryParkedOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto order = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcParkedOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(order->UserOrderLocalID, "", order->SessionID, order->FrontID);

  if (order->ParkedOrderStatus != USTP_FTDC_POS_TriggeredSubmitting
    && order->ParkedOrderStatus != USTP_FTDC_POS_FemasAccepted && order->ParkedOrderStatus != USTP_FTDC_POS_Unknown)
    m_parked_orders.erase(order_id);
  else
    m_parked_orders[order_id] = *order;
  // 如果是撤单
  if (order->ParkedOrderStatus == USTP_FTDC_POS_Canceled) {
    auto it = m_order_cancel.find(order_id);
    // 是主动发起的撤单
    if (it != m_order_cancel.end()) {
      auto req = m_service->m_command_manager->Update("ReqCancelOrder" + it->second);
      m_order_cancel.erase(it);
      SetCommandFinished(req);
    }
  }
}

// 撤单回包设置req状态
void FemasUnitInsertCancelOrder::OnRspParkedOrderAction(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pInputCancel = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcParkedOrderActionField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pInputCancel->UserOrderLocalID, "", pInputCancel->SessionID, pInputCancel->FrontID);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + order_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void FemasUnitInsertCancelOrder::InsertParkOrder(std::shared_ptr<InsertOrder> req) {
  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcParkedOrderInsertField>();
  strcpy_x(field->BrokerID, m_last_session.value().BrokerID);
  ConvertToFemasExchangeID(req->exchange_id, &field->ExchangeID);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_last_session.value().UserID);

  strcpy_x(field->InstrumentID, req->instrument_id);
  strcpy_x(field->UserOrderLocalID, std::to_string(req->order_ref));
  ConvertToFemasOrderPriceType(req->price_type, &field->OrderPriceType);
  ConvertToFemasDirection(req->direction, &field->Direction);
  ConvertToFemasOffsetFlag(req->offset, &field->OffsetFlag);
  ConvertToFemasHedgeFlag(req->hedge_flag, &field->HedgeFlag);
  field->LimitPrice = req->limit_price;
  field->Volume = req->volume;
  ConvertToFemasTimeCondition(req->time_condition, &field->TimeCondition);
  ConvertToFemasVolumeCondition(req->volume_condition, &field->VolumeCondition);
  field->ForceCloseReason = USTP_FTDC_FCR_NotForceClose;
  field->ArbiType = USTP_FTDC_AT_Basic;

  std::string custom = std::to_string(req->request_id) + "_fclib_" + std::to_string(req->order_ref);
  strcpy_x(field->UserCustom, custom);

  auto order_id =
    ToFclibOrderId(field->UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
  FCASSERT(order_id == req->order_id);

  int ret = m_service->m_api->ReqParkedOrderInsert(field.get(), 0);
  LogFemasReq(m_logger, "ReqParkedOrderInsert", field.get(), 0, ret);
  m_service->m_command_manager->SetCommandId(req, "ReqParkedOrderInsert" + order_id);
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 预埋单指令发送失败");
}

void FemasUnitInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsApiReady() || !m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  // 如果是预埋单
  if (req->condition_type == fclib::future::ConditionType::kParked) {
    InsertParkOrder(req);
    return;
  }

  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcInputOrderField>();
  strcpy_x(field->BrokerID, m_last_session.value().BrokerID);
  strcpy_x(field->UserID, m_last_session.value().UserID);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  ConvertToFemasOrderField(req, field);

  std::string custom = std::to_string(req->request_id) + "_fclib_" + std::to_string(req->order_ref);
  strcpy_x(field->UserCustom, custom);
  strcpy_x(field->UserOrderLocalID, std::to_string(req->order_ref));

  // 下单
  auto order_id =
    ToFclibOrderId(field->UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
  FCASSERT(order_id == req->order_id);

  int ret = m_service->m_api->ReqOrderInsert(field.get(), 0);
  LogFemasReq(m_logger, "ReqOrderInsert", field.get(), 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOrder" + order_id);
  m_service->m_send_time[order_id] = NowAsEpochNano();
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 下单指令发送失败");
}

void FemasUnitInsertCancelOrder::CancelParkOrder(std::shared_ptr<CancelOrder> req) {
  auto it = m_parked_orders.find(req->order_id);
  if (it == m_parked_orders.end()) {
    SetCommandFinished(req, -1, u8"fclib: 报单编号不存在");
    return;
  }
  cffex_femas_fip::CUstpFtdcParkedOrderField& order = it->second;
  cffex_femas_fip::CUstpFtdcParkedOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.ExchangeID, order.ExchangeID);
  strcpy_x(field.BrokerID, m_last_session.value().BrokerID);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.UserID, m_last_session.value().UserID);
  std::snprintf(field.UserOrderActionLocalID, sizeof(field.UserOrderActionLocalID), "%20" PRId64,
    m_service->GenerateOrderRef() * 100);
  strcpy_x(field.UserOrderLocalID, order.UserOrderLocalID);
  strcpy_x(field.InstrumentID, order.InstrumentID);
  field.SessionID = order.SessionID;
  field.FrontID = order.FrontID;
  int ret = m_service->m_api->ReqParkedOrderAction(&field, 0);
  LogFemasReq(m_logger, "ReqParkedOrderAction", &field, 0, ret);
  // 共用一个cancel
  m_order_cancel[req->order_id] = field.UserOrderActionLocalID;
  m_service->m_command_manager->SetCommandId(req, "ReqCancelOrder" + std::string(field.UserOrderActionLocalID));
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 撤单指令发送失败");
}

void FemasUnitInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (!m_service->IsApiReady() || !m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  req->status = UserCommand::Status::kStarted;
  // 撤预埋单
  if (req->condition_type == ConditionType::kParked) {
    CancelParkOrder(req);
    return;
  }

  auto it = m_alive_orders.find(req->order_id);
  if (it == m_alive_orders.end()) {
    SetCommandFinished(req, -1, u8"fclib: 报单编号不存在");
    return;
  }
  cffex_femas_fip::CUstpFtdcOrderField& order = it->second;
  cffex_femas_fip::CUstpFtdcOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_last_session.value().BrokerID);
  strcpy_x(field.UserID, m_last_session.value().UserID);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.UserOrderLocalID, order.UserOrderLocalID);
  strcpy_x(field.ExchangeID, order.ExchangeID);
  strcpy_x(field.InstrumentID, order.InstrumentID);
  strcpy_x(field.OrderSysID, order.OrderSysID);
  std::snprintf(field.UserOrderActionLocalID, sizeof(field.UserOrderActionLocalID), "%20" PRId64,
    m_service->GenerateOrderRef() * 100);
  field.ActionFlag = USTP_FTDC_AF_Delete;
  int ret = m_service->m_api->ReqOrderAction(&field, 0);
  LogFemasReq(m_logger, "ReqOrderAction", &field, 0, ret);
  m_order_cancel[req->order_id] = field.UserOrderActionLocalID;
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::string(field.UserOrderActionLocalID));
  if (ret != 0)
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 撤单指令发送失败");
}

void FemasUnitInsertCancelOrder::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  m_last_session.reset();
}

void FemasUnitInsertCancelOrder::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspUserLoginField>(msg->pMainField);
    m_last_session = *rsp;
  }
}

void FemasUnitInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  if (m_service->GetUserKey().find("STRESS-TESTING-100") != std::string::npos)
    return;
  LOG_ASSERT(m_last_session.has_value());
  LOG_ASSERT(m_service->IsApiReady());
  auto order = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(order->UserOrderLocalID, order->OrderLocalID, order->SessionID, order->FrontID);
  // alive 委托单都放入 m_alive_orders, 以备撤单时使用.
  if (order->OrderStatus == USTP_FTDC_OS_Canceled || order->OrderStatus == USTP_FTDC_OS_AllTraded
    || order->OrderStatus == USTP_FTDC_OS_TimeOut)
    m_alive_orders.erase(order_id);
  else
    m_alive_orders[order_id] = *order;

  if (order->OrderStatus == USTP_FTDC_OS_Canceled) {
    auto it = m_order_cancel.find(order_id);
    // 是主动发起的撤单
    if (it != m_order_cancel.end()) {
      auto req = m_service->m_command_manager->Update("ReqCancelOrder" + it->second);
      m_order_cancel.erase(it);
      SetCommandFinished(req, 0, u8"fclib: 撤单成功");
    }
  }
  if (order->SessionID == m_last_session.value().SessionID) {
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    if (req) {
      auto order_node = m_service->GetNodeDb()->GetNode<Order>(m_service->m_user_key + "|" + order_id);
      std::static_pointer_cast<InsertOrder>(req)->order_id = order_id;
      std::static_pointer_cast<InsertOrder>(req)->order_pointer = order_node;
      if (order->OrderStatus == USTP_FTDC_OS_Canceled && order->OrderSysID[0] == '\0') {
        SetCommandFinished(req, -1, u8"fclib: 报单失败");
      } else if (order->OrderStatus != USTP_FTDC_OS_TimeOut) {
        SetCommandFinished(req, 0, u8"fclib: 报单成功");
      }
    }
  }
}

void FemasUnitInsertCancelOrder::OnRspParkedOrderInsert(std::shared_ptr<SpiMessage> msg) {
  // 收到预埋单回包直接将指令置为Finish
  auto pInputOrder = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcParkedOrderInsertField>(msg->pMainField);
  auto order_id =
    ToFclibOrderId(pInputOrder->UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
  auto req = m_service->m_command_manager->Update("ReqParkedOrderInsert" + order_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void FemasUnitInsertCancelOrder::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  LOG_ASSERT(m_last_session.has_value());
  if (msg->RspInfo.ErrorID != 0) {
    auto pInputOrder = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInputOrderField>(msg->pMainField);
    auto order_id = ToFclibOrderId(
      pInputOrder->UserOrderLocalID, "", m_last_session.value().SessionID, m_last_session.value().FrontID);
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void FemasUnitInsertCancelOrder::OnRspOrderAction(std::shared_ptr<SpiMessage> msg) {
  auto pInputCancel = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcOrderActionField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::string(pInputCancel->UserOrderActionLocalID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

