// 根据平仓成交更新明细手数
void UpdateDetailsByVolume(std::list<std::shared_ptr<PositionDetail>>* details, int* volume) {
  while (*volume > 0 && !details->empty()) {
    auto vol = std::min(*volume, details->front()->volume);
    *volume -= vol;
    details->front()->volume -= vol;
    if (details->front()->volume <= 0)
      details->pop_front();
  }
}

// 根据平仓成交更新明细
void UpdateDetailsByCloseTrade(
  SubPosition* subpos, std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade, int volume) {
  if (volume <= 0)
    return;
  if (ConvertFromFemasExchangeID(&trade->ExchangeID) == "SHFE"
    || ConvertFromFemasExchangeID(&trade->ExchangeID) == "INE") {
    bool flag = trade->OffsetFlag != USTP_FTDC_OF_CloseToday;
    auto details = flag ? &subpos->his_position_details : &subpos->today_position_details;
    UpdateDetailsByVolume(details, &volume);
  } else {
    UpdateDetailsByVolume(&subpos->his_position_details, &volume);
    UpdateDetailsByVolume(&subpos->today_position_details, &volume);
  }
}

// 计算持仓成本
void CalcPositionCost(SubPosition* subpos, int close_volume, double volume_multiple) {
  for (auto it = subpos->_open_list.begin(); it != subpos->_open_list.end();) {
    int close_vol = std::min(close_volume, it->second);
    close_volume -= close_vol;
    it->second -= close_vol;
    if (it->second == 0) {
      it = subpos->_open_list.erase(it);
      if (close_volume > 0)
        continue;
    }
    break;
  }
  subpos->_position_cost = 0;
  for (auto open : subpos->_open_list) {
    subpos->_position_cost += open.first * open.second * volume_multiple;
  }
}

// 插入持仓明细
void InsertDetails(std::list<std::shared_ptr<PositionDetail>>* details, std::shared_ptr<PositionDetail> detail) {
  details->push_back(detail);
  details->sort([](std::shared_ptr<PositionDetail> detail_1, std::shared_ptr<PositionDetail> detail_2) {
    if (detail_1->open_trading_day == detail_2->open_trading_day)
      return detail_1->open_exchange_trade_id < detail_2->open_exchange_trade_id;
    return detail_1->open_trading_day < detail_2->open_trading_day;
  });
}

FemasUnitPositionAccountView::FemasUnitPositionAccountView(FemasServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_node_db(service->m_node_db)
  , m_user_key(service->m_user_key)
  , m_options(&service->m_options)
  , m_logger(parent_logger.With("position_account_view", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    m_service->m_command_manager->SetCommandId(command, "RequireQryAccount");
    if (!m_service->IsApiReady()) {
      SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
      return;
    }
    RequireAccount(true);
  });
  m_service->RegisterCommandProcessor(PositionCombInsert::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqDcePositionCombInsert(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
    if (m_service->IsApiReady()) {
      RequirePosition(true);
      RequireAccount(true);
      RequirePackedOrder(true);
    }
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQueryUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    if (m_service->IsApiReady()) {
      RequirePosition(true);
      RequireAccount(true);
      RequirePackedOrder(true);
    }
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryUserInvestor, [this](std::shared_ptr<SpiMessage> msg) {
    if (m_service->IsApiReady()) {
      RequirePosition(true);
      RequireAccount(true);
      RequirePackedOrder(true);
    }
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryInvestorPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryInvestorPosition(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInvestorCombPosition, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInvestorCombPosition(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInvestorPositionDetail, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInvestorPositionDetail(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingAccount(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspMarginCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspMarginCombAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMarginCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMarginCombAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspParkedOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    // 收到预埋单Rsp后立刻去查询
    RequirePackedOrder(true);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnParkedOrder, [this](std::shared_ptr<SpiMessage> msg) {
    // 收到预埋单Rtn后立刻去查询
    RequirePackedOrder(true);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspParkedOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    // 收到预埋单撤单指令后立刻去查询
    RequirePackedOrder(true);
  });

  m_position_view = m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_user_key && pos->unit_id == 0;
  });
}

int FemasUnitPositionAccountView::RunOnce() {
  int ret = 0;
  // 处理平仓记录
  for (auto iter = m_close_log_cache.begin(); iter != m_close_log_cache.end();) {
    auto key = iter->first;
    if (ProcessCloseLogCache(key)) {
      iter = m_close_log_cache.erase(iter);
      ++ret;
    } else {
      ++iter;
    }
  }
  for (const auto& [_, pos_node] : m_position_view->GetNodes()) {
    auto position = pos_node->Latest();
    auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
    if (ins.has_value() && !std::isnan(ins->last_price) && ins->last_price != position->last_price
      && ins->product_class != md::ProductClass::kCombine && ins->CheckQuote(m_trading_day)) {
      ++ret;
      m_service->m_node_db->ReplaceRecord<Position>(
        position->GetKey(), [this](std::shared_ptr<Position> calc_position) {
          UpdatePositionProfit(calc_position);
        });
    }
  }
  if (ret > 0)
    UpdateAccountProfit();
  return ret;
}

bool FemasUnitPositionAccountView::IsPositionInit() {
  return m_position_inited && m_comb_position_inited;
}

void FemasUnitPositionAccountView::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto pRspUserLogin = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspUserLoginField>(msg->pMainField);
    if (m_trading_day != std::string(pRspUserLogin->TradingDay)) {
      // 新的交易日
      m_trading_day = pRspUserLogin->TradingDay;
      FCASSERT(!m_trading_day.empty());
      FCASSERT(std::all_of(m_trading_day.begin(), m_trading_day.end(), ::isdigit));
      // 挂载持仓明细
      SplicePostitionDetail();
    }
  }
}

void FemasUnitPositionAccountView::OnRspQryInvestorPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto position = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspInvestorPositionField>(msg->pMainField);
    m_qry_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryPositionResults(!m_position_inited);
    m_qry_position_results.clear();
    if (!m_position_inited) {
      m_position_inited = true;
      if (!IsPositionInit())
        return;
      if (m_options->enable_position_details && !m_position_view->GetNodes().empty()) {
        RequirePositionDetail();
      } else {
        ProcessCachedTrade();
        ProcessCachedOrder();
        m_position_ready = true;
        m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_user_key;
          p->position_ready = true;
          p->backend = BackEnd::kFemas;
        });
      }
      UpdateAccountProfit(true);
    }
  }
}

void FemasUnitPositionAccountView::OnRspQryInvestorCombPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto position = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspInvestorCombPositionField>(msg->pMainField);
    m_qry_comb_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryCombPositionResults();
    m_qry_comb_position_results.clear();
    if (!m_comb_position_inited) {
      m_comb_position_inited = true;
      if (!IsPositionInit())
        return;
      if (m_options->enable_position_details && !m_position_view->GetNodes().empty()) {
        RequirePositionDetail();
      } else {
        ProcessCachedTrade();
        ProcessCachedOrder();
        m_position_ready = true;
        m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_user_key;
          p->position_ready = true;
          p->backend = BackEnd::kFemas;
        });
      }
      UpdateAccountProfit(true);
    }
  }
}

void FemasUnitPositionAccountView::OnRspQryInvestorPositionDetail(std::shared_ptr<SpiMessage> msg) {
  if (m_trading_day.empty() || m_position_ready)
    return;
  if (msg->pMainField) {
    auto position_detail =
      std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspQryInvestorPositionDetailField>(msg->pMainField);
    std::string symbol =
      ConvertFromFemasExchangeID(&position_detail->ExchangeID) + "." + std::string(position_detail->InstrumentID);
    FCASSERT(!symbol.empty());
    m_qry_position_detail_results[symbol].push_back(position_detail);
  }
  if (msg->bIsLast) {
    UpdatePositionDetail();
    m_qry_position_detail_results.clear();
    ProcessCachedTrade();
    ProcessCachedOrder();
    m_position_ready = true;
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
      p->user_key = m_user_key;
      p->position_ready = true;
      p->backend = BackEnd::kFemas;
    });
    UpdateAccountProfit();
  }
}

void FemasUnitPositionAccountView::OnRspQryTradingAccount(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto account = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspInvestorAccountField>(msg->pMainField);
    m_qry_account_results.push_back(account);
  }
  if (msg->bIsLast) {
    ProcessQryAccountResults();
    m_qry_account_results.clear();
    if (!m_account_inited) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_user_key;
        p->account_ready = true;
        p->backend = BackEnd::kFemas;
      });
      m_account_inited = true;
    }
    if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
      SetCommandFinished(req);
  }
}

void FemasUnitPositionAccountView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  auto trade = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcTradeField>(msg->pMainField);
  if (!m_position_ready) {
    m_trade_cache.push_back(trade);
    return;
  }
  RequirePosition(false);
  RequireAccount(false);
  std::string symbol = ConvertFromFemasExchangeID(&trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  std::string key = m_user_key + "|0|" + symbol;
  m_node_db->ReplaceRecord<Position>(key, [=](std::shared_ptr<Position> position) {
    int spec_close_volume = 0;
    UpdatePositionVolumeByTrade(trade, &spec_close_volume, position);
    if (m_options->enable_position_details)
      UpdatePositionDetailsByTrade(trade, spec_close_volume, position);
  });
}

void FemasUnitPositionAccountView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto order = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcOrderField>(msg->pMainField);
  if (order->OffsetFlag != USTP_FTDC_OF_Open || order->ArbiType == USTP_FTDC_AT_Swap) {
    if (!m_position_ready) {
      m_order_cache.push_back(order);
    } else {
      UpdatePositionFrozenVolumeByOrder(order);
      RequirePosition(false);
    }
  }
  if (m_account_inited)
    RequireAccount(false);
}

void FemasUnitPositionAccountView::ProcessQryPositionResults(bool is_first) {
  for (const auto& origin_position : m_qry_position_results) {
    std::string position_symbol =
      ConvertFromFemasExchangeID(&origin_position->ExchangeID) + "." + std::string(origin_position->InstrumentID);
    auto position_key = m_user_key + "|0|" + position_symbol;
    auto position_node =
      m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target_position) {
        target_position->user_key = m_user_key;
        target_position->investor_id = origin_position->InvestorID;
        target_position->exchange_id = ConvertFromFemasExchangeID(&origin_position->ExchangeID);
        target_position->instrument_id = origin_position->InstrumentID;
        auto ins = m_service->m_md_helper->GetShmInstrument(target_position->Symbol(), true);
        double pre_settlement = origin_position->PreSettlementPrice;
        if (!IsValid(pre_settlement) || IsZero(pre_settlement))
          pre_settlement = ins->pre_settlement;
        future::SubPosition* subpos =
          GetSubPosition(target_position, origin_position->Direction, origin_position->HedgeFlag);
        if (origin_position->HedgeFlag == USTP_FTDC_CHF_Arbitrage)
          subpos->hedge_type = PositionHedgeType::kArbitrage;
        subpos->_margin = origin_position->UsedMargin;
        subpos->_position_profit = origin_position->PositionProfitBySettl;
        subpos->_close_profit = origin_position->CloseProfitBySettl;
        subpos->_qry_volume_today = origin_position->TodayPositionRemain;
        subpos->volume_yesterday = origin_position->PrePosition;
        subpos->_open_cost = origin_position->PositionCostByDeal;
        subpos->strike_frozen = origin_position->TodayFrozenExecPosition;
        if (ins->HasCloseToday()) {
          subpos->_qry_volume_his = origin_position->YdPositionRemain;
          subpos->strike_his_frozen = origin_position->YdFrozenExecPosition;
          if (is_first) {
            subpos->volume_his = origin_position->PrePosition;
            subpos->_position_cost_his = origin_position->PrePosition * pre_settlement * ins->volume_multiple;
          }
        } else {
          subpos->_qry_volume_his = origin_position->Position - origin_position->TodayPositionRemain;
          subpos->volume_comb = origin_position->CombPosition;
          if (is_first) {
            subpos->volume_his = origin_position->PrePosition;
            subpos->_position_cost_his = origin_position->PrePosition * pre_settlement * ins->volume_multiple;
          }
        }
        if (is_first && ins->product_class == md::ProductClass::kOption) {
          subpos->market_value_yesterday = pre_settlement * subpos->volume_yesterday * ins->volume_multiple;
          if (subpos->direction == Direction::kSell)
            subpos->market_value_yesterday *= -1;
        }
        subpos->margin = subpos->_margin + subpos->_margin_his;
        subpos->premium = subpos->_premium + subpos->_premium_his;
        subpos->commission = subpos->_commission + subpos->_commission_his;
        subpos->close_profit = subpos->_close_profit + subpos->_close_profit_his;
        if (subpos->_qry_volume_today + subpos->_qry_volume_his > 0 && fabs(ins->volume_multiple) > 1e-8) {
          subpos->open_price = (subpos->_open_cost + subpos->_open_cost_his)
            / (subpos->_qry_volume_today + subpos->_qry_volume_his) / ins->volume_multiple;
          if (is_first) {
            subpos->position_price =
              (subpos->_position_cost + subpos->_position_cost_his) / subpos->volume_yesterday / ins->volume_multiple;
          }
        } else {
          subpos->open_price = 0;
          subpos->position_price = 0;
        }
        UpdatePositionProfit(target_position);
      });
  }
}

void FemasUnitPositionAccountView::ProcessQryCombPositionResults() {
  for (const auto& origin_position : m_qry_comb_position_results) {
    std::string position_symbol =
      ConvertFromFemasExchangeID(&origin_position->ExchangeID) + "." + std::string(origin_position->CombInstrumentID);
    auto position_key = m_user_key + "|0|" + position_symbol;
    m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_user_key;
      target_position->investor_id = origin_position->InvestorID;
      target_position->exchange_id = ConvertFromFemasExchangeID(&origin_position->ExchangeID);
      target_position->instrument_id = origin_position->CombInstrumentID;
      future::SubPosition* subpos =
        GetSubPosition(target_position, origin_position->Direction, origin_position->HedgeFlag);
      if (origin_position->HedgeFlag == USTP_FTDC_CHF_Arbitrage)
        subpos->hedge_type = PositionHedgeType::kArbitrage;

      subpos->volume_today = origin_position->CombPosition;
      subpos->volume_today_frozen = origin_position->CombFrozenPosition;
      subpos->position_profit = NAN;
      subpos->float_profit = NAN;
      subpos->open_price = 0;
      subpos->position_price = 0;
    });
  }
}

void FemasUnitPositionAccountView::ProcessQryAccountResults() {
  for (auto femas_account : m_qry_account_results) {
    auto account_key = Account::MakeKey(m_user_key, 0, femas_account->Currency);
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> target_account) {
      target_account->user_key = m_user_key;
      target_account->currency = femas_account->Currency;
      target_account->investor_id = femas_account->AccountID;
      target_account->available = femas_account->Available;
      target_account->client_equity = femas_account->Balance;
      target_account->close_profit = femas_account->CloseProfit;
      target_account->commission = femas_account->Fee;
      target_account->deposit = femas_account->Deposit;
      target_account->frozen_commission = femas_account->FrozenFee;
      target_account->frozen_margin = femas_account->FrozenMargin;
      target_account->margin = femas_account->Margin;
      target_account->position_profit = femas_account->PositionProfit;
      target_account->pre_balance = femas_account->PreBalance;
      target_account->withdraw = femas_account->Withdraw;
      target_account->premium = femas_account->Premium;
      target_account->frozen_premium = femas_account->TotalFrozen;
      target_account->balance = target_account->client_equity + target_account->option_market_value;
      if (target_account->client_equity > 0)
        target_account->risk_ratio = target_account->margin / target_account->client_equity;
      if (target_account->balance > 0)
        target_account->ref_risk_ratio = target_account->margin / target_account->balance;
      target_account->withdraw_quota = femas_account->WithdrawAllowed;
      target_account->pre_mortgage = femas_account->PreCurrencyPledge;
      target_account->delivery_margin = femas_account->DeliveryMargin;
      target_account->mortgage = femas_account->Mortgage;
      target_account->fund_mortgagein = femas_account->CurrencyPledgeIn;
      target_account->fund_mortgageout = femas_account->CurrencyPledgeOut;
    });
  }
}

void FemasUnitPositionAccountView::ProcessCachedOrder() {
  for (auto order : m_order_cache)
    UpdatePositionFrozenVolumeByOrder(order);
  m_order_cache.clear();
}

void FemasUnitPositionAccountView::UpdatePositionFrozenVolumeByOrder(
  std::shared_ptr<cffex_femas_fip::CUstpFtdcOrderField> order) {
  // 计算冻结手数差额
  auto order_id = ToFclibOrderId(order->UserOrderLocalID, order->OrderLocalID, order->SessionID, order->FrontID);
  int delta_order_volume =
    (ConvertFromFemasOrderStatus(&order->OrderStatus) == OrderStatus::kAlive) ? order->VolumeRemain : 0;
  auto it = m_alive_orders.find(order_id);
  if (it != m_alive_orders.end()) {
    auto prev_order = it->second;
    int prev_order_volume =
      (ConvertFromFemasOrderStatus(&prev_order->OrderStatus) == OrderStatus::kAlive) ? prev_order->VolumeRemain : 0;
    delta_order_volume -= prev_order_volume;
  }
  if (delta_order_volume == 0)
    return;
  // 更新持仓
  auto ins = m_service->m_md_helper->GetShmInstrument(
    ConvertFromFemasExchangeID(&order->ExchangeID) + "." + std::string(order->InstrumentID), true);
  if (ins->product_class == md::ProductClass::kCombine) {
    auto offset_flag = order->OffsetFlag;
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2_ins = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    FCASSERT(leg1_ins);
    FCASSERT(leg2_ins);
    if (offset_flag != USTP_FTDC_OF_Open)
      UpdateFrozenVolume(order, leg1_ins, order->Direction, order->OffsetFlag, delta_order_volume);
    auto direction = (order->Direction == USTP_FTDC_D_Buy ? USTP_FTDC_D_Sell : USTP_FTDC_D_Buy);
    if (order->ArbiType == USTP_FTDC_AT_Swap)
      offset_flag = (offset_flag == USTP_FTDC_OF_Open ? USTP_FTDC_OF_Close : USTP_FTDC_OF_Open);
    if (offset_flag != USTP_FTDC_OF_Open)
      UpdateFrozenVolume(order, leg2_ins, direction, offset_flag, delta_order_volume);
  } else {
    UpdateFrozenVolume(order, ins, order->Direction, order->OffsetFlag, delta_order_volume);
  }

  auto status = ConvertFromFemasOrderStatus(&order->OrderStatus);
  if (status == OrderStatus::kDead) {
    m_alive_orders.erase(order_id);
  } else {
    m_alive_orders[order_id] = order;
  }
}

void FemasUnitPositionAccountView::UpdateFrozenVolume(std::shared_ptr<cffex_femas_fip::CUstpFtdcOrderField> order,
  const std::optional<shm::ShmInstrument>& ins, cffex_femas_fip::TUstpFtdcDirectionType direction,
  cffex_femas_fip::TUstpFtdcOffsetFlagType offset_flag, int delta_order_volume) {
  std::string position_key = m_user_key + "|0|" + ins->symbol.data();
  auto position_node = m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
    position->user_key = m_user_key;
    position->investor_id = order->InvestorID;
    position->exchange_id = ConvertFromFemasExchangeID(&order->ExchangeID);
    position->instrument_id = ins->instrument_id.data();

    SubPosition* calc_subpos = GetSubPosition(position, order->HedgeFlag, direction, offset_flag);
    if (offset_flag == USTP_FTDC_OF_CloseToday && !ins->HasCloseToday()) {
      offset_flag = USTP_FTDC_OF_Close;
    }
    if (offset_flag == USTP_FTDC_OF_CloseToday) {
      calc_subpos->volume_today_frozen += delta_order_volume;
    } else if (ins->HasCloseToday()) {
      calc_subpos->volume_his_frozen += delta_order_volume;
    } else {
      if (std::string_view(ins->exchange_id.data()) == "CZCE") {
        SubPosition* calc_subpos0 = GetSubPosition(position, USTP_FTDC_CHF_Speculation, direction, offset_flag);
        SubPosition* calc_subpos1 = GetSubPosition(position, USTP_FTDC_CHF_Hedge, direction, offset_flag);
        if (delta_order_volume > 0) { /** 冻结时，先投机后保值 */
          auto frozen0 = std::min(delta_order_volume, calc_subpos0->Volume() - calc_subpos0->VolumeFrozen());
          if (frozen0 > 0)
            calc_subpos0->volume_his_frozen += frozen0;
          if (delta_order_volume > frozen0) {
            calc_subpos1->volume_his_frozen += delta_order_volume - frozen0;
          }
        } else {
          // 解冻时，先保值后投机
          auto frozen1 = std::min(-delta_order_volume, calc_subpos1->OrderFrozen());
          if (frozen1 > 0)
            calc_subpos1->volume_his_frozen -= frozen1;
          if (-delta_order_volume > frozen1) {
            calc_subpos0->volume_his_frozen -= -delta_order_volume - frozen1;
          }
        }
        UpdatePositionVolumeFrozen(calc_subpos0);
        UpdatePositionVolumeFrozen(calc_subpos1);
      } else {
        calc_subpos->volume_his_frozen += delta_order_volume;
        UpdatePositionVolumeFrozen(calc_subpos);
      }
    }
    UpdatePositionProfit(position);
  });
}

void FemasUnitPositionAccountView::UpdatePositionVolumeFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->OrderFrozen();
  calc_subpos->volume_his_frozen = std::min(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

void FemasUnitPositionAccountView::ProcessCachedTrade() {
  std::unordered_map<std::string, std::shared_ptr<Position>> caches;
  for (const auto& trade : m_trade_cache) {
    std::string symbol = ConvertFromFemasExchangeID(&trade->ExchangeID) + "." + std::string(trade->InstrumentID);
    std::string key = m_user_key + "|0|" + symbol;
    // 获取修改节点
    std::shared_ptr<Position> position;
    if (caches.find(key) != caches.end()) {
      position = caches[key];
    } else {
      position = m_node_db->CreateRecord<Position>(key);
      caches[key] = position;
    }
    int spec_close_volume = 0;
    UpdatePositionVolumeByTrade(trade, &spec_close_volume, position);
    if (m_options->enable_position_details)
      UpdatePositionDetailsByTrade(trade, spec_close_volume, position);
  }
  for (const auto& [_, position] : caches) {
    m_node_db->ReplaceRecord<Position>(position);
  }
  m_trade_cache.clear();
}

void FemasUnitPositionAccountView::UpdatePositionVolumeByTrade(
  std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade, int* spec_close_volume,
  std::shared_ptr<future::Position> position) {
  *spec_close_volume = 0;
  std::string symbol = ConvertFromFemasExchangeID(&trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  position->user_key = m_user_key;
  position->investor_id = trade->InvestorID;
  position->exchange_id = ConvertFromFemasExchangeID(&trade->ExchangeID);
  position->instrument_id = trade->InstrumentID;
  auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
  std::string investor_id = std::string(trade->InvestorID);
  auto offset_flag = trade->OffsetFlag;
  if (offset_flag == USTP_FTDC_OF_CloseToday && !ins->HasCloseToday()) {
    offset_flag = USTP_FTDC_OF_Close;
  }
  SubPosition* calc_subpos = GetSubPosition(position, trade->HedgeFlag, trade->Direction, trade->OffsetFlag);
  if (offset_flag == USTP_FTDC_OF_Open) {
    calc_subpos->volume_today += trade->TradeVolume;
    auto cost = trade->TradeVolume * trade->TradePrice * ins->volume_multiple;
    calc_subpos->_position_cost += cost;
    calc_subpos->_open_list.push_back({trade->TradePrice, trade->TradeVolume});
    if (m_options->enable_position_details) {
      // 加入持仓明细
      auto position_detail = std::make_shared<PositionDetail>();
      FCASSERT(!m_trading_day.empty());
      position_detail->open_trading_day = std::stoi(m_trading_day);
      position_detail->open_date_time = NowAsEpochNano();
      position_detail->open_price = trade->TradePrice;
      position_detail->open_exchange_order_id = trade->OrderSysID;
      position_detail->open_exchange_trade_id = trade->TradeID;
      position_detail->volume = trade->TradeVolume;
      calc_subpos->today_position_details.push_back(position_detail);
    }
  } else if (offset_flag == USTP_FTDC_OF_CloseToday) {
    calc_subpos->volume_today -= trade->TradeVolume;
    CalcPositionCost(calc_subpos, trade->TradeVolume, ins->volume_multiple);
    *spec_close_volume = (trade->HedgeFlag == USTP_FTDC_CHF_Speculation) ? trade->TradeVolume : 0;
  } else {
    /** 郑商所优先平投机，后平保值 */
    if (std::string_view(ins->exchange_id.data()) == "CZCE") {
      SubPosition* calc_subpos0 =
        GetSubPosition(position, USTP_FTDC_CHF_Speculation, trade->Direction, trade->OffsetFlag);
      SubPosition* calc_subpos1 = GetSubPosition(position, USTP_FTDC_CHF_Hedge, trade->Direction, trade->OffsetFlag);
      auto spec_vol = std::min(calc_subpos0->Volume(), trade->TradeVolume);
      *spec_close_volume = spec_vol;
      if (spec_vol > 0) {
        auto spec_vol_his = std::min(calc_subpos0->volume_his, spec_vol);
        if (spec_vol_his > 0) {
          // 老仓按比率缩小持仓成本
          calc_subpos0->_position_cost_his *=
            (calc_subpos0->volume_his - spec_vol_his) * 1.0 / calc_subpos0->volume_his;
          calc_subpos0->volume_his -= spec_vol_his;
        }
        if (spec_vol > spec_vol_his) {
          // 今仓按先开先平计算持仓成本
          calc_subpos0->volume_today -= (spec_vol - spec_vol_his);
          CalcPositionCost(calc_subpos0, spec_vol - spec_vol_his, ins->volume_multiple);
        }
        if (calc_subpos0->Volume() == 0) {
          calc_subpos0->position_price = 0;
        } else {
          calc_subpos0->position_price = calc_subpos0->_position_cost / calc_subpos0->Volume() / ins->volume_multiple;
        }
        UpdatePositionVolumeFrozen(calc_subpos0);
      }
      auto hedge_vol = trade->TradeVolume - spec_vol;
      if (hedge_vol > 0) {
        auto hedge_vol_his = std::min(calc_subpos1->volume_his, hedge_vol);
        if (hedge_vol_his > 0) {
          double percentage = (calc_subpos1->volume_his - hedge_vol_his) * 1.0 / calc_subpos1->volume_his;
          calc_subpos1->_position_cost_his *= percentage;
          calc_subpos1->volume_his -= hedge_vol_his;
        }
        if (hedge_vol > hedge_vol_his) {
          calc_subpos1->volume_today -= (hedge_vol - hedge_vol_his);
          CalcPositionCost(calc_subpos1, hedge_vol - hedge_vol_his, ins->volume_multiple);
        }
        if (calc_subpos1->Volume() == 0) {
          calc_subpos1->position_price = 0;
        } else {
          calc_subpos1->position_price = calc_subpos1->_position_cost / calc_subpos1->Volume() / ins->volume_multiple;
        }
        UpdatePositionVolumeFrozen(calc_subpos1);
      }
    } else {
      *spec_close_volume = (trade->HedgeFlag == USTP_FTDC_CHF_Speculation) ? trade->TradeVolume : 0;
      if (ins->HasCloseToday()) {
        double percentage = (calc_subpos->volume_his - trade->TradeVolume) * 1.0 / calc_subpos->volume_his;
        calc_subpos->_position_cost_his *= percentage;
        calc_subpos->volume_his -= trade->TradeVolume;
        FCASSERT(calc_subpos->volume_his >= 0);
      } else {
        auto vol_his = std::min(calc_subpos->volume_his, trade->TradeVolume);
        if (vol_his > 0) {
          double percentage = (calc_subpos->volume_his - vol_his) * 1.0 / calc_subpos->volume_his;
          calc_subpos->_position_cost_his *= percentage;
          calc_subpos->volume_his -= vol_his;
        }
        if (trade->TradeVolume > vol_his) {
          calc_subpos->volume_today -= (trade->TradeVolume - vol_his);
          CalcPositionCost(calc_subpos, trade->TradeVolume - vol_his, ins->volume_multiple);
        }
      }
    }
  }
  if (calc_subpos->Volume() == 0) {
    calc_subpos->position_price = 0;
  } else {
    calc_subpos->position_price =
      (calc_subpos->_position_cost + calc_subpos->_position_cost_his) / calc_subpos->Volume() / ins->volume_multiple;
  }
  if (!ins->HasCloseToday()) {
    UpdatePositionVolumeFrozen(calc_subpos);
  }
  UpdatePositionProfit(position);
}

void FemasUnitPositionAccountView::UpdatePositionProfit(std::shared_ptr<Position> position) {
  auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
  if (ins->CheckQuote(m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  // 无法获得最新价, 取查询返回值
  if (std::isnan(position->last_price) || IsZero(position->last_price)) {
    for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
           &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
      auto subpos = &((*(position)).*p);
      auto profit = subpos->_position_profit + subpos->_position_profit_his;
      subpos->position_profit = profit;
      subpos->float_profit = 0.0;
      subpos->market_value = 0.0;
      if (subpos->Volume() < 1)
        continue;
      if (subpos->direction == Direction::kBuy) {
        subpos->market_value =
          subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      } else {
        subpos->market_value =
          -subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
        subpos->float_profit = -subpos->market_value + subpos->open_price * ins->volume_multiple * subpos->Volume();
        if (ins->product_class == md::ProductClass::kOption)
          subpos->market_value *= -1;
      }
    }
    return;
  }

  // 可以计算
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption)
        subpos->position_profit = subpos->market_value - subpos->_position_cost - subpos->_position_cost_his;
      if (!IsZero(subpos->open_price))
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
      if (subpos->volume_yesterday > 0 && position->last_price != ins->pre_settlement) {
        subpos->untrade_profit = (position->last_price - ins->pre_settlement) * subpos->volume_yesterday
          * ins->volume_multiple * (subpos->direction == Direction::kBuy ? 1 : -1);
      } else {
        subpos->untrade_profit = 0.0;
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

void FemasUnitPositionAccountView::UpdateAccountProfit(bool is_first) {
  auto account_node = m_node_db->GetNode<Account>(m_user_key + "|0|CNY");
  if (!account_node)
    return;
  double position_profit = 0.0;
  double float_profit = 0.0;
  double option_buy_market_value = 0.0;
  double option_sell_market_value = 0.0;
  double option_buy_market_value_yesterday = 0.0;
  double option_sell_market_value_yesterday = 0.0;
  double future_market_value = 0.0;
  auto& position_node_map = m_position_view->GetNodes();
  for (auto& [key, position_node] : position_node_map) {
    if (!position_node->Latest())
      continue;
    auto ins = m_service->m_md_helper->GetShmInstrument(position_node->Latest()->Symbol(), true);
    FCASSERT(ins.has_value());
    if (ins->product_class != md::ProductClass::kCombine) {
      if (!isnan(position_node->Latest()->PositionProfit()) && ins->product_class != md::ProductClass::kOption)
        position_profit += position_node->Latest()->PositionProfit();
      if (!isnan(position_node->Latest()->FloatProfit()))
        float_profit += position_node->Latest()->FloatProfit();
      if (ins->product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
        if (is_first) {
          option_buy_market_value_yesterday += position_node->Latest()->LongMarketValueYesterday();
          option_sell_market_value_yesterday += position_node->Latest()->ShortMarketValueYesterday();
        }
      }
      if (ins->product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->ShortMarketValue() + position_node->Latest()->LongMarketValue();
    }
  }
  m_node_db->ReplaceRecord<Account>(m_user_key + "|0|CNY", [=](std::shared_ptr<future::Account> account) {
    account->user_key = m_user_key;
    account->option_buy_market_value = option_buy_market_value;
    account->option_sell_market_value = option_sell_market_value;
    if (is_first) {
      account->option_buy_market_value_yesterday = option_buy_market_value_yesterday;
      account->option_sell_market_value_yesterday = option_sell_market_value_yesterday;
    }
    double old_option_market_value = account->option_market_value;
    account->option_market_value = option_buy_market_value + option_sell_market_value;
    account->balance += account->option_market_value - old_option_market_value;
    account->float_profit = float_profit;
    account->future_market_value = future_market_value;
    if (fabs(position_profit - account->position_profit) > 0.01) {
      double old_position_profit = account->position_profit;
      account->position_profit = position_profit;
      account->balance += account->position_profit - old_position_profit;
      account->client_equity += account->position_profit - old_position_profit;
      account->available += account->position_profit - old_position_profit;
      if (account->client_equity > 0) {
        account->risk_ratio = account->margin / account->client_equity;
      }
    }
  });
}

SubPosition* FemasUnitPositionAccountView::GetSubPosition(std::shared_ptr<future::Position> position,
  cffex_femas_fip::TUstpFtdcDirectionType posi_dir, cffex_femas_fip::TUstpFtdcHedgeFlagType hedge) {
  if (posi_dir == USTP_FTDC_D_Buy) {
    if (hedge == USTP_FTDC_CHF_Speculation)
      return &position->subpos_long_spec;
    else
      return &position->subpos_long_other;
  } else if (posi_dir == USTP_FTDC_D_Sell) {
    if (hedge == USTP_FTDC_CHF_Speculation)
      return &position->subpos_short_spec;
    else
      return &position->subpos_short_other;
  }
  FCASSERT(false);
  return nullptr;
}

SubPosition* FemasUnitPositionAccountView::GetSubPosition(std::shared_ptr<Position> position,
  cffex_femas_fip::TUstpFtdcHedgeFlagType hedge_flag, cffex_femas_fip::TUstpFtdcDirectionType trade_direction,
  cffex_femas_fip::TUstpFtdcOffsetFlagType offset) {
  SubPosition* subpos = nullptr;
  if (hedge_flag == USTP_FTDC_CHF_Speculation) {
    if ((trade_direction == USTP_FTDC_D_Buy && offset == USTP_FTDC_OF_Open)
      || (trade_direction == USTP_FTDC_D_Sell && offset != USTP_FTDC_OF_Open))
      subpos = &position->subpos_long_spec;
    else
      subpos = &position->subpos_short_spec;
  } else {
    if ((trade_direction == USTP_FTDC_D_Buy && offset == USTP_FTDC_OF_Open)
      || (trade_direction == USTP_FTDC_D_Sell && offset != USTP_FTDC_OF_Open))
      subpos = &position->subpos_long_other;
    else
      subpos = &position->subpos_short_other;
  }
  return subpos;
}

void FemasUnitPositionAccountView::UpdatePositionDetail() {
  for (const auto& item : m_qry_position_detail_results) {
    auto& symbol = item.first;
    auto& details = item.second;
    if (symbol.empty() || details.empty())
      continue;
    std::string position_key = m_user_key + "|0|" + symbol;
    auto position_node = m_node_db->GetNode<Position>(position_key);
    if (!position_node)
      continue;
    m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
      for (const auto& detail : details) {
        std::string open_day = detail->OpenDate;
        // 当日的持仓明细由成交自行计算
        if (open_day == m_trading_day)
          continue;
        if (detail->Position + detail->ClosePosition <= 0)
          continue;
        auto subpos = GetSubPosition(position, detail->HedgeFlag, detail->Direction, USTP_FTDC_OF_Open);
        FCASSERT(subpos != nullptr);
        auto his_detail = std::make_shared<PositionDetail>();
        if (!open_day.empty()) {
          FCASSERT(std::all_of(open_day.begin(), open_day.end(), ::isdigit));
          his_detail->open_trading_day = std::stoi(open_day);
        }
        his_detail->open_price = detail->DealPrice;
        his_detail->open_exchange_trade_id = detail->TradeID;
        // 盘前手数 = 当前手数 + 今平手数
        his_detail->volume = detail->Position + detail->ClosePosition;
        InsertDetails(&subpos->his_position_details, his_detail);
      }
    });
  }
}

void FemasUnitPositionAccountView::SplicePostitionDetail() {
  for (const auto& [key, _] : m_position_view->GetNodes()) {
    m_node_db->ReplaceRecord<Position>(key, [](std::shared_ptr<Position> position) {
      for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
             &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
        auto subpos = &((*position).*p);
        subpos->his_position_details.splice(subpos->his_position_details.end(), subpos->today_position_details);
      }
    });
  }
}

void FemasUnitPositionAccountView::UpdatePositionDetailsByTrade(
  std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade, int spec_close_volume,
  std::shared_ptr<Position> position) {
  if (trade->OffsetFlag == USTP_FTDC_OF_Open)
    return;
  UpdateTradeCloseLog(trade, spec_close_volume, position);
  // 更新成交记录
  auto trade_key = m_user_key + "|" + trade->TradeID + "|" + trade->OrderSysID;
  if (ProcessCloseLogCache(trade_key))
    m_close_log_cache.erase(trade_key);
}

void FemasUnitPositionAccountView::UpdateTradeCloseLog(
  std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade, int spec_volume, std::shared_ptr<Position> position) {
  if (trade->OffsetFlag == USTP_FTDC_OF_Open)
    return;
  std::string symbol = ConvertFromFemasExchangeID(&trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  std::string position_key = m_user_key + "|0|" + symbol;
  auto cache = std::make_shared<CloseLogCache>();
  cache->spec_volume = spec_volume;
  cache->other_volume = trade->TradeVolume - spec_volume;
  FCASSERT(cache->other_volume >= 0 && cache->spec_volume >= 0);
  if (cache->spec_volume > 0) {
    auto subpos = GetSubPosition(position, USTP_FTDC_CHF_Speculation, trade->Direction, trade->OffsetFlag);
    std::list<std::shared_ptr<CloseLog>> logs;
    CalcCloseLogs(subpos, cache->spec_volume, trade, &logs);
    for (auto&& log : logs) {
      cache->logs.push_back(log);
      cache->spec_close_profit += log->close_profit;
      cache->spec_close_profit_by_open += log->close_profit_by_open;
    }
  }
  if (cache->other_volume > 0) {
    auto subpos = GetSubPosition(position, USTP_FTDC_CHF_Hedge, trade->Direction, trade->OffsetFlag);
    std::list<std::shared_ptr<CloseLog>> logs;
    CalcCloseLogs(subpos, cache->other_volume, trade, &logs);
    for (auto&& log : logs) {
      cache->logs.push_back(log);
      cache->other_close_profit += log->close_profit;
      cache->other_close_profit_by_open += log->close_profit_by_open;
    }
  }
  auto trade_key = m_user_key + "|" + trade->TradeID + "|" + trade->OrderSysID;
  m_close_log_cache[trade_key] = cache;
}

bool FemasUnitPositionAccountView::ProcessCloseLogCache(const std::string& key) {
  if (nullptr == m_node_db->GetNode<Trade>(key))
    return false;
  if (m_close_log_cache.count(key) == 0)
    return false;
  auto cache = m_close_log_cache[key];
  m_node_db->ReplaceRecord<Trade>(key, [=](std::shared_ptr<Trade> trade) {
    trade->_volume_spec = cache->spec_volume;
    trade->_volume_other = cache->other_volume;
    trade->_spec_close_profit = cache->spec_close_profit;
    trade->_spec_close_profit_by_open = cache->spec_close_profit_by_open;
    trade->_other_close_profit = cache->other_close_profit;
    trade->_other_close_profit_by_open = cache->other_close_profit_by_open;
    trade->close_logs = cache->logs;
  });
  return true;
}

void FemasUnitPositionAccountView::CalcCloseLogs(SubPosition* subpos, int volume,
  std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade, std::list<std::shared_ptr<CloseLog>>* ret) {
  if (volume <= 0)
    return;
  std::string symbol = ConvertFromFemasExchangeID(&trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
  if (ins->HasCloseToday()) {
    bool flag = trade->OffsetFlag != USTP_FTDC_OF_CloseToday;
    auto details = flag ? &subpos->his_position_details : &subpos->today_position_details;
    CalcCloseLogsByDetails(details, &volume, trade, ins, subpos->hedge_type, flag, ret);
  } else {
    CalcCloseLogsByDetails(&subpos->his_position_details, &volume, trade, ins, subpos->hedge_type, true, ret);
    CalcCloseLogsByDetails(&subpos->today_position_details, &volume, trade, ins, subpos->hedge_type, false, ret);
  }
}

void FemasUnitPositionAccountView::CalcCloseLogsByDetails(std::list<std::shared_ptr<PositionDetail>>* details,
  int* volume, std::shared_ptr<cffex_femas_fip::CUstpFtdcTradeField> trade,
  const std::optional<shm::ShmInstrument>& ins, const PositionHedgeType& hedge_type, bool use_pre_settlement,
  std::list<std::shared_ptr<CloseLog>>* ret) {
  auto trade_price = trade->TradePrice;
  int multiple = (trade->Direction == USTP_FTDC_D_Buy) ? -1 : 1;
  while (*volume > 0 && !details->empty()) {
    auto t_detail = details->front();
    auto vol = std::min(*volume, t_detail->volume);
    FCASSERT(vol > 0);
    FCASSERT(!isnan(t_detail->open_price));
    // 逐笔盈亏
    auto close_profit_by_open = (trade_price - t_detail->open_price) * ins->volume_multiple * vol * multiple;
    // 盯市盈亏
    auto close_profit = close_profit_by_open;
    if (use_pre_settlement) {
      FCASSERT(!isnan(ins->pre_settlement));
      close_profit = (trade_price - ins->pre_settlement) * ins->volume_multiple * vol * multiple;
    }
    // 构建平仓记录
    auto log = std::make_shared<CloseLog>();
    log->open_trading_day = t_detail->open_trading_day;
    log->open_date_time = t_detail->open_date_time;
    log->open_price = t_detail->open_price;
    log->open_exchange_order_id = t_detail->open_exchange_order_id;
    log->open_exchange_trade_id = t_detail->open_exchange_trade_id;
    log->volume = vol;
    log->hedge_flag = hedge_type;
    log->close_profit_by_open = close_profit_by_open;
    log->close_profit = close_profit;
    ret->push_back(log);
    // 检查循环
    *volume -= vol;
    t_detail->volume -= vol;
    if (t_detail->volume <= 0)
      details->pop_front();
  }
}

void FemasUnitPositionAccountView::RequireAccount(bool is_critical) {
  if (!m_service->IsApiReady())
    return;
  if (m_service->m_query_planner.AlreadyInQueue("RequireQryAccount"))
    return;
  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcQryInvestorAccountField>();
  memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcQryInvestorAccountField));
  strcpy_x(field->BrokerID, m_service->m_broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  m_service->m_query_planner.AddTask(
    "RequireQryAccount", FemasQueryPlanner::Priority::kHigh, m_service->GenerateRequestID(),
    [=](int request_id) {
      auto ret = m_service->m_api->ReqQryInvestorAccount(field.get(), request_id);
      if (ret >= 0)
        LogFemasReq(m_logger, "ReqQryTradingAccount", field.get(), request_id, ret);
      return ret;
    },
    50, is_critical);
}
void FemasUnitPositionAccountView::RequirePackedOrder(bool is_critical) {
  if (!m_service->IsApiReady())
    return;
  if (m_service->m_query_planner.AlreadyInQueue("RequireQryPackedOrder"))
    return;

  auto field = std::make_shared<cffex_femas_fip::CUstpFtdcQryParkedOrderField>();
  memset(field.get(), 0, sizeof(cffex_femas_fip::CUstpFtdcQryParkedOrderField));
  strcpy_x(field->BrokerID, m_service->m_broker_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  m_service->m_query_planner.AddTask(
    "RequireQryPackedOrder", FemasQueryPlanner::Priority::kHigh, m_service->GenerateRequestID(),
    [=](int request_id) {
      auto ret = m_service->m_api->ReqQryParkedOrder(field.get(), request_id);
      if (ret >= 0)
        LogFemasReq(m_logger, "RequireQryPackedOrder", field.get(), request_id, ret);
      return ret;
    },
    50, is_critical);
}

