void FemasUnitPositionAccountView::ReqDcePositionCombInsert(std::shared_ptr<UserCommand> command) {
  auto comb_command = std::static_pointer_cast<PositionCombInsert>(m_service->m_command_manager->Update(command));
  if (!m_service->IsApiReady()) {
    SetCommandFinished(command, -1, u8"fclib: 当前交易服务未就绪");
    return;
  }
  cffex_femas_fip::CUstpFtdcInputMarginCombActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.CombInstrumentID, comb_command->instrument_id);
  std::snprintf(
    field.UserActionLocalID, sizeof(field.UserActionLocalID), "%20" PRId64, m_service->GenerateOrderRef() * 100);
  femas::ConvertToFemasExchangeID(comb_command->exchange_id, &field.ExchangeID);
  ConvertToFemasDirection(comb_command->direction, &field.Direction);
  field.CombVolume = comb_command->volume;
  if (comb_command->comb_direction == CombDirection::kComb)
    field.CombDirection = USTP_FTDC_CA_Combine;
  else
    field.CombDirection = USTP_FTDC_CA_UnCombine;
  ConvertToFemasHedgeFlag(comb_command->hedge_flag, &field.HedgeFlag);
  int req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqMarginCombAction(&field, req_id);
  LogFemasReq(m_logger, "ReqMarginCombAction", &field, req_id, ret);
  m_service->m_command_manager->SetCommandId(
    command, "ReqDcePositionCombInsert" + std::string(field.UserActionLocalID));
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"飞马主席: " + std::to_string(ret) + u8", 大商所盘中组合指令发送失败");
  }
}

void FemasUnitPositionAccountView::OnRspMarginCombAction(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto comb_action_field =
      std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInputMarginCombActionField>(msg->pMainField);
    auto req = m_service->m_command_manager->Update(
      "ReqDcePositionCombInsert" + std::string(comb_action_field->UserActionLocalID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void FemasUnitPositionAccountView::OnRtnMarginCombAction(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto comb_action = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcInputMarginCombActionField>(msg->pMainField);
    auto req =
      m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action->UserActionLocalID));
    if (comb_action->CombActionStatus == USTP_FTDC_CAS_Rejected) {
      SetCommandFinished(req, -1, u8"组合申请被拒绝");
      return;
    }
    if (comb_action->CombActionStatus == USTP_FTDC_CAS_Accepted
      || comb_action->CombActionStatus == USTP_FTDC_CAS_Canceled) {
      RequirePosition(false);
      RequireAccount(false);
      SetCommandFinished(req);
    }
  }
}


