  int64_t m_order_ref = 0;
  std::string m_flow_dir;
  std::unordered_map<SpiMessage::Tag, std::queue<std::shared_ptr<SpiMessage>>> m_data_cache;
  bool m_trade_avail = false;
  bool m_query_avail = false;
  std::string m_investor_id;
  std::shared_ptr<future::ChangePasswordBeforeLogin> m_req_change_password_before_login;
  std::shared_ptr<future::ReqLogin> m_req_login;
  std::string m_broker_id;
  std::string m_trading_day;  // 登录成功后有值,格式 20210528

  std::queue<std::shared_ptr<SpiMessage>> m_recv_queue;
  std::map<std::string, int64_t> m_send_time;
  FemasSpiHandler* m_spi = nullptr;
  cffex_femas_fip::CUstpFtdcTraderApi* m_api = nullptr;
  bool m_new_day = false;
};
