// 断线次数上限
static const int DisconnectMax = 10;
// 是否可以重新尝试登录
bool IsErrorReLogin(int error_id) {
  static const std::unordered_set<int> non_relogin_errors = {
    0,   // 正确
    3,   // Femas: 找不到该用户
    4,   // Femas: 找不到投资者
    62,  // Femas: 用户不活跃
    65,  // Femas: 不合法的登录IP地址
  };
  return non_relogin_errors.find(error_id) == non_relogin_errors.end();
}
FemasUnitLogin::FemasUnitLogin(FemasServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("unit_login", reinterpret_cast<int64_t>(this)).Clone())
  , m_login_logger(m_logger.Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontConnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontConnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnQryFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnQryFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspAuthenticate, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspAuthenticate(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQueryUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQueryUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryUserInvestor, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryUserInvestor(msg);
  });
}

void FemasUnitLogin::InitAndLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ReqLogin>(m_service->m_command_manager->Update(command));
  m_service->m_req_login = req;
  m_service->m_req_change_password_before_login = nullptr;
  m_relogin = false;
  m_first_logined = false;
  m_service->m_trade_avail = false;
  m_service->m_query_avail = false;
  m_service->BuildApi();
  if (m_service->m_req_login->user_id == "STRESS-TESTING-100") {
    m_service->m_spi->StartStressTesting();
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        target_login->user_key = m_service->m_user_key;
        target_login->session_status = SessionStatus::kLogined;
        target_login->trading_day = "000000";
        target_login->backend = BackEnd::kFemas;
      });
    SetCommandFinished(req);
    return;
  }
  // 日志回放
  if (!req->replay_flow_file_name.empty()) {
    if (m_log_replayer) {
      m_log_replayer->m_pause = !m_log_replayer->m_pause;
    } else {
      m_log_replayer = std::make_shared<LogReplayer>();
      m_log_replayer->OpenLogFile(req->replay_flow_file_name, m_service->m_spi);
    }
  }
  m_logger.Info("init");
  m_service->m_command_manager->SetCommandId(req, "login");
}

void FemasUnitLogin::OnFrontConnected(std::shared_ptr<SpiMessage> msg) {
  m_disconnect_cnt = 0;
  FCASSERT(m_service->m_req_login);
  if (m_service->m_req_login->broker.auth_code.empty()) {
    ReqUserLoginEx();
  } else {
    ReqAuthenticate();
  }
}

void FemasUnitLogin::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (m_service->IsLogined()) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        target_login->backend = BackEnd::kFemas;
        target_login->session_status = SessionStatus::kDisconnected;
        target_login->status_msg = GetDisConnectReason(msg->RspInfo.ErrorID);
        if (target_login->user_key.empty())
          target_login->user_key = m_service->m_user_key;
      });
  }
  m_service->m_trade_avail = false;
  m_relogin = false;
  ++m_disconnect_cnt;
}

void FemasUnitLogin::OnQryFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  // 飞马柜台查询前置断连, 该回调触发, 当查询前置可用时, 自动重连登录
  if (m_service->IsLogined()) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        target_login->backend = BackEnd::kFemas;
        target_login->session_status = SessionStatus::kDisconnected;
        target_login->status_msg = GetDisConnectReason(msg->RspInfo.ErrorID);
        if (target_login->user_key.empty())
          target_login->user_key = m_service->m_user_key;
      });
  }
  m_service->m_query_avail = false;
  m_relogin = false;
  ++m_disconnect_cnt;
}

void FemasUnitLogin::ReqAuthenticate() {
  cffex_femas_fip::CUstpFtdcDSUserInfoField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.AppID, m_service->m_req_login->broker.app_id);
  strcpy_x(field.AuthCode, m_service->m_req_login->broker.auth_code);
  field.EncryptType = '1';
  int nRequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqDSUserCertification(&field, nRequestID);
  if (IsNeedReLogin(ret)) {
    m_relogin = true;
  } else if (ret != 0) {
    std::string rsp_key = m_service->m_req_change_password_before_login ? "change_password_before_login" : "login";
    SetCommandFinished(m_service->m_command_manager->Update(rsp_key), ret,
      u8"飞马主席: " + std::to_string(ret) + u8", 认证指令发送失败");
  }
  LogFemasReq(m_logger, "ReqDSUserCertification", &field, nRequestID, ret);
}

void FemasUnitLogin::OnRspAuthenticate(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID) {
    if (m_first_logined) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
          target_login->backend = BackEnd::kFemas;
          target_login->session_status = SessionStatus::kDisconnected;
          target_login->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
          if (target_login->user_key.empty())
            target_login->user_key = m_service->m_user_key;
        });
    }
    if (IsNeedReLogin(msg->RspInfo.ErrorID))
      m_relogin = true;
    std::string rsp_key = m_service->m_req_change_password_before_login ? "change_password_before_login" : "login";
    SetCommandFinished(
      m_service->m_command_manager->Update(rsp_key), msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  ReqUserLoginEx();
}

void FemasUnitLogin::ReqUserLoginEx() {
  if (m_service->m_req_login->async_login) {
    m_login_thread = std::thread([=]() {
      ReqUserLogin(m_login_logger);
    });
    if (m_login_thread.joinable()) {
      m_login_thread.detach();
      return;
    }
    return;
  }
  ReqUserLogin(m_logger);
}

void FemasUnitLogin::ReqUserLogin(structlog::Logger& logger) {
  cffex_femas_fip::CUstpFtdcReqUserLoginField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.Password, m_service->m_req_login->password);
  strcpy_x(field.UserProductInfo, m_service->m_req_login->broker.product_info);
  strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  int ret = m_service->m_api->ReqUserLogin(&field, 1);
  if (m_service->m_req_login->replay_flow_file_name.empty()) {
    if (IsNeedReLogin(ret)) {
      m_relogin = true;
    } else if (ret != 0) {
      std::string rsp_key = m_service->m_req_change_password_before_login ? "change_password_before_login" : "login";
      SetCommandFinished(m_service->m_command_manager->Update(rsp_key), ret,
        u8"飞马主席: " + std::to_string(ret) + u8", 登录指令发送失败");
    }
    LogFemasReq(logger, "ReqUserLogin", &field, 1, ret);
  }
}

void FemasUnitLogin::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    if (((0 == msg->RspInfo.ErrorID) || (131 == msg->RspInfo.ErrorID) || (140 == msg->RspInfo.ErrorID)
          || (141 == msg->RspInfo.ErrorID))
      && msg->pMainField) {
      auto pRspUserLogin = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspUserLoginField>(msg->pMainField);
      m_service->m_broker_id = pRspUserLogin->BrokerID;
      cffex_femas_fip::CUstpFtdcUserPasswordUpdateField field;
      memset(&field, 0, sizeof(field));
      strcpy_x(field.OldPassword, m_service->m_req_change_password_before_login->req_login->password);
      strcpy_x(field.NewPassword, m_service->m_req_change_password_before_login->new_password);
      strcpy_x(field.BrokerID, m_service->m_broker_id);
      strcpy_x(field.UserID, m_service->m_req_change_password_before_login->req_login->user_id);
      int ret = m_service->m_api->ReqUserPasswordUpdate(&field, 0);
      LogFemasReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
      if (0 != ret)
        SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 修改密码指令发送失败");
    } else {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  } else {
    auto req = m_service->m_command_manager->Update("login");
    auto pRspUserLogin = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspUserLoginField>(msg->pMainField);
    if (pRspUserLogin->FemasLifeCycle == -1) {
      m_service->m_trade_avail = false;
      SetCommandFinished(req, -1, u8"首次登录需要修改密码");
      return;
    }
    if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
          target_login->user_key = m_service->m_user_key;
          target_login->user_id = pRspUserLogin->UserID;
          target_login->investor_id = pRspUserLogin->UserID;
          if (!target_login->trading_day.empty() && target_login->trading_day != pRspUserLogin->TradingDay) {
            m_service->m_new_day = true;
            target_login->session_status = SessionStatus::kDisconnected;
          } else {
            target_login->session_status = SessionStatus::kLogined;
          }
          target_login->trading_day = pRspUserLogin->TradingDay;
          target_login->login_time = pRspUserLogin->LoginTime;
          target_login->broker_id = pRspUserLogin->BrokerID;
          target_login->system_name = GbkToUtf8(pRspUserLogin->TradingSystemName);
          target_login->front_id = pRspUserLogin->FrontID;
          target_login->session_id = pRspUserLogin->SessionID;
          target_login->backend = BackEnd::kFemas;
          if (target_login->user_desc == "") {
            target_login->user_desc = m_service->m_req_login->user_desc;
          }
        });
      m_service->m_trading_day = pRspUserLogin->TradingDay;
      m_service->m_broker_id = pRspUserLogin->BrokerID;
      m_service->m_order_ref = std::atoll(pRspUserLogin->MaxOrderLocalID) / 100LL;
      m_service->m_trade_avail = true;
      m_first_logined = true;
      if (!m_service->IsLogined())
        return;
      if (m_service->m_investor_id.empty()) {
        ReqQryUserInvestor();
      }
    } else {
      m_service->m_trade_avail = false;
      if (!m_service->m_trading_day.empty()) {
        m_service->m_node_db->ReplaceRecord<LoginContent>(
          m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
            target_login->backend = BackEnd::kFemas;
            target_login->trading_day = m_service->m_trading_day;
            target_login->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
            if (target_login->user_key.empty())
              target_login->user_key = m_service->m_user_key;
          });
      }
      if (IsNeedReLogin(msg->RspInfo.ErrorID))
        m_relogin = true;
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  }
}

void FemasUnitLogin::OnRspQueryUserLogin(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("login");
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    m_service->m_query_avail = true;
    if (!m_service->IsLogined())
      return;
    if (m_service->m_investor_id.empty()) {
      ReqQryUserInvestor();
    }
  } else {
    m_service->m_query_avail = false;
    if (!m_service->m_trading_day.empty()) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
          target_login->backend = BackEnd::kFemas;
          target_login->trading_day = m_service->m_trading_day;
          target_login->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
          if (target_login->user_key.empty())
            target_login->user_key = m_service->m_user_key;
        });
    }
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void FemasUnitLogin::ReqQryUserInvestor() {
  cffex_femas_fip::CUstpFtdcQryUserInvestorField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  int request_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqQryUserInvestor(&field, request_id);
  LogFemasReq(m_logger, "ReqQryUserInvestor", &field, request_id, ret);

  if (ret != 0) {
    auto req = m_service->m_command_manager->Update("login");
    SetCommandFinished(req, ret, u8"飞马主席: " + std::to_string(ret) + u8", 查询账户信息指令发送失败");
  }
}

void FemasUnitLogin::OnRspQryUserInvestor(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto pRspUserInvestor = std::static_pointer_cast<cffex_femas_fip::CUstpFtdcRspUserInvestorField>(msg->pMainField);
    m_service->m_investor_id = pRspUserInvestor->InvestorID;
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        target_login->user_key = m_service->m_user_key;
        target_login->backend = BackEnd::kFemas;
        target_login->investor_name = GbkToUtf8(pRspUserInvestor->InvestorName);
      });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("login");
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

int FemasUnitLogin::RunOnce() {
  if (!m_service->m_api || !m_service->m_spi)
    return 0;

  if (m_log_replayer && !m_log_replayer->m_pause) {
    bool running =
      m_log_replayer->ProcessUntil((300LL + std::rand() % 200) * 1000000LL);  // 回放日志时, 每次推进300 - 500毫秒
    if (!running) {
      m_log_replayer->m_pause = true;
    }
  }

  if (m_log_replayer && m_log_replayer->m_pause && m_service->m_recv_queue.empty()) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
        login->user_key = m_service->m_user_key;
        login->status_msg = "log replay finished";
      });
  }

  if (m_disconnect_cnt > DisconnectMax) {
    m_service->BuildApi();
    m_disconnect_cnt = 0;
    return 0;
  }
  // 间隔 10s 进行一次重新登录尝试
  if (m_relogin && m_relogin_timer.IsExpired()) {
    m_relogin = false;
    FCASSERT(m_service->m_req_login);
    if (m_service->m_req_login->broker.auth_code.empty()) {
      ReqUserLoginEx();
    } else {
      ReqAuthenticate();
    }
    m_relogin_timer.Reset(std::chrono::seconds(10));
  }
  return 0;
}

bool FemasUnitLogin::IsNeedReLogin(int error_id) {
  // 首次登录后且本次错误可以重新登陆
  return m_first_logined && IsErrorReLogin(error_id);
}

