void FemasServiceImpl::Start() {}

void FemasServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    it->second(command);
    return;
  }
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case PositionCombAuto::AID: {
      auto req = std::static_pointer_cast<PositionCombAuto>(command);
      m_options.position_comb_auto = req->auto_combi;
      SetCommandFinished(command);
      break;
    }
    default: {
      SetCommandFinished(command, 1, u8"fclib: 飞马主席暂不支持本指令");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

int FemasServiceImpl::RunOnce() {
  int msg_count = 0;
  // api运转一次
  if (m_api && m_spi) {
    m_query_planner.RunOnce();
    // 处理spi接收到的数据包
    std::shared_ptr<SpiMessage> msg;
    while (!m_recv_queue.empty()) {
      msg = m_recv_queue.front();
      m_recv_queue.pop();
      auto& cache = m_data_cache[msg->tag];
      cache.push(msg);
      if (!msg->bIsLast)
        continue;
      while (!cache.empty()) {
        ProcessSpiMsg(cache.front());
        msg_count++;
        cache.pop();
      }
    }
  }
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  if (msg_count == 0) {
    if (m_options.position_comb_auto) {
      m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
        m_command_manager->Store(comb_insert);
        ExecuteCommand(comb_insert);
      });
    }
  }
  // 行情变化和交易变化都会影响
  return msg_count;
}

