void FemasServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  m_query_planner.ProcessSpiMsg(spi_msg);
  // 调用其他模块注册的回调函数, 通知他们收到相应回报了
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end())
    for (auto& f : it->second)
      f(spi_msg);
}

void FemasServiceImpl::SetReqResponse(
  std::shared_ptr<UserCommand> c, int request_id, int result_code, const std::string& error_msg) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"fclib: 指令发送失败";
  }
  if (!error_msg.empty()) {
    command->result_msg = error_msg;
  }
  m_command_manager->SetCommandId(command, std::to_string(request_id));
}

void FemasServiceImpl::BuildApi(bool subscribe_topic /*= true*/) {
  if (!m_req_login)
    return;
  DeleteApi();
  if (m_flow_dir.empty()) {
    auto now = std::chrono::steady_clock::now();
    static int index = 0;
    std::string sztime = "fclib"
      + std::to_string(std::chrono::time_point_cast<std::chrono::milliseconds>(now).time_since_epoch().count())
      + std::to_string(index++);
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = UstpApiCreator(m_flow_dir.c_str());
  m_spi = new FemasSpiHandler(m_ioc, m_logger, m_recv_queue);
  m_api->RegisterSpi(m_spi);
  for (const auto& front : m_req_login->broker.trading_fronts) {
    auto pos = front.find(';');
    if (pos == std::string::npos) {
      m_api->RegisterFront(const_cast<char*>(front.c_str()));
    } else {
      auto front1 = front.substr(0, pos);
      auto front2 = front.substr(pos + 1);
      m_api->RegisterFront(const_cast<char*>(front1.c_str()));
      m_api->RegisterQryFront(const_cast<char*>(front2.c_str()));
    }
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(cffex_femas_fip::USTP_TERT_RESUME);
    m_api->SubscribePublicTopic(cffex_femas_fip::USTP_TERT_RESUME);
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    m_api->Init();
  }
}

void FemasServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
    m_trading_day = "";
  }
  m_api->Release();
  m_api = nullptr;
}

void FemasServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
