X1UnitInsertCancelOrder::X1UnitInsertCancelOrder(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspInsertOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspCancelOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCancelOrder(msg);
  });
}

void X1UnitInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto order_ref = req->order_ref;
  // 下单
  auto ins = m_service->m_md_helper->GetShmInstrument(req->exchange_id + '.' + req->instrument_id, true);
  auto field = std::make_shared<CX1FtdcInsertOrderField>();
  strcpy_x(field->AccountID, m_last_session.value().AccountID);
  field->LocalOrderID = order_ref;
  field->RequestID = req->request_id;
  if (ins->product_class == md::ProductClass::kCombine) {
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    if (leg1_ins.has_value()) {
      if (leg1_ins->product_class == md::ProductClass::kFuture)
        field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_COMM;
      else
        field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_OPT;
    } else {
      field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_COMM;
      FCASSERT(false);
    }
  } else if (ins->product_class == md::ProductClass::kFuture) {
    field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_COMM;
  } else {
    field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_OPT;
  }
  if (req->price_type == PriceType::kLimit) {
    field->OrderType = X1_FTDC_LIMITORDER;
    if (req->time_condition == OrderTimeCondition::kIoc) {
      if (req->volume_condition == OrderVolumeCondition::kAll) {
        field->OrderProperty = X1_FTDC_SP_FOK;
      } else if (req->volume_condition == OrderVolumeCondition::kAny) {
        field->OrderProperty = X1_FTDC_SP_FAK;
      }
    } else if (req->time_condition == OrderTimeCondition::kGfs) {
      field->OrderProperty = X1_FTDC_SP_GIS;
    } else {
      field->OrderProperty = X1_FTDC_SP_NON;
    }
  } else if (req->price_type == PriceType::kAny) {
    field->OrderType = X1_FTDC_MKORDER;
    if (req->exchange_id == "CZCE")  // X1 郑商所市价的OrderProperty要填 FAK
      field->OrderProperty = X1_FTDC_SP_FAK;
    else
      field->OrderProperty = X1_FTDC_SP_NON;
  } else if (req->price_type == PriceType::kBest) {
    field->OrderType = X1_FTDC_MKORDER;
    field->OrderProperty = X1_FTDC_SP_NON;
  } else if (req->price_type == PriceType::kFiveLevel) {
    field->OrderType = X1_FTDC_MKORDER;
    field->OrderProperty = X1_FTDC_SP_NON;
  }

  if (ins->product_class == md::ProductClass::kCombine)
    field->OrderType = (!req->is_swap_order) ? X1_FTDC_ARBITRAGE : X1_FTDC_EXTENSION;

  ConvertToSfitOrderField(req, field);
  auto order_id = ToFclibOrderId(field->LocalOrderID, m_last_session.value().SessionID);
  FCASSERT(req->order_id == order_id);
  int ret = m_service->m_api->ReqInsertOrder(field.get());
  LogReq(m_logger, "ReqOrderInsert", field.get(), 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOrder" + order_id);
  if (ret != 0) {
    std::string error_msg = u8"指令发送失败";
    if (ret == 13)
      error_msg = u8"客户号无效";
    else if (ret == 64)
      error_msg = u8"未找到合约代码";
    else if (ret == 65)
      error_msg = u8"未找到交易所代码";
    SetCommandFinished(req, ret, error_msg);
  }
}

void X1UnitInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  req->status = UserCommand::Status::kStarted;
  auto key = req->user_key + "|" + req->order_id;
  auto order_node = m_service->m_node_db->GetNode<future::Order>(key);
  if (!order_node) {
    SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
    return;
  }
  if (order_node->Latest()->status != future::OrderStatus::kAlive) {
    SetCommandFinished(req, 1, u8"fclib: 报单状态无法撤销");
    return;
  }

  m_service->m_send_time[req->order_id] = NowAsEpochNano();

  CX1FtdcCancelOrderField field;
  memset(&field, 0, sizeof(field));
  field.LocalOrderID = atoi(order_node->Latest()->order_ref.c_str());
  strcpy_x(field.AccountID, m_last_session.value().AccountID);
  strcpy_x(field.InstrumentID, order_node->Latest()->instrument_id);
  strcpy_x(field.OrderSysID, order_node->Latest()->exchange_order_id);
  field.X1OrderID = atoi(order_node->Latest()->order_local_id.c_str());
  int ret = m_service->m_api->ReqCancelOrder(&field);
  LogReq(m_logger, "ReqCancelOrder", &field, 0, ret);
  auto order_id = ToFclibOrderId(field.LocalOrderID, m_last_session.value().SessionID);
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + order_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void X1UnitInsertCancelOrder::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto rsp = std::static_pointer_cast<CX1FtdcRspUserLoginField>(msg->pMainField);
    m_last_session = *rsp;
  }
}

void X1UnitInsertCancelOrder::OnRspInsertOrder(std::shared_ptr<SpiMessage> msg) {
  LOG_ASSERT(m_last_session.has_value());
  if (msg->pMainField) {
    auto pInputOrder = std::static_pointer_cast<CX1FtdcRspOperOrderField>(msg->pMainField);
    auto order_id = ToFclibOrderId(pInputOrder->LocalOrderID, m_last_session.value().SessionID);
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  }
}

void X1UnitInsertCancelOrder::OnRspCancelOrder(std::shared_ptr<SpiMessage> msg) {
