template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(
  SpiMessage::Tag tag, const T* plain_src, ::CX1FtdcRspErrorField* rsp_info, int req_id, bool is_last) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  if (rsp_info) {
    memcpy(&msg->RspInfo, rsp_info, sizeof(CX1FtdcRspErrorField));
  }
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

