void X1SpiHandler::StartStressTesting() {
  m_test_thread = std::thread([&] {
    using namespace std::chrono_literals;
    for (int i = 0; i < 100; i++) {
      for (int j = 0; j < 10000; j++) {
        CX1FtdcRspPriOrderField f;
        memset(&f, 0, sizeof(f));
        strcpy_x(f.ExchangeID, "SHFE");
        strcpy_x(f.InstrumentID, "cu2101");
        strcpy_x(f.AccountID, "155862");
        f.BuySellType = X1_FTDC_SPD_BUY;
        strcpy_x(f.OrderSysID, std::to_string(i * 100000 + j).c_str());
        f.InsertPrice = 30000.0;
        f.OpenCloseType = X1_FTDC_SPD_OPEN;
        f.Speculator = X1_FTDC_SPD_SPECULATOR;
        f.OrderType = X1_FTDC_LIMITORDER;
        if (j > 8000) {
          f.OrderStatus = X1_FTDC_SPD_FILLED;
        } else if (j > 6000) {
          f.OrderStatus = X1_FTDC_SPD_IN_QUEUE;
        } else if (j > 4000) {
          f.OrderStatus = X1_FTDC_SPD_PARTIAL;
        } else {
          f.OrderStatus = X1_FTDC_SPD_CANCELED;
        }
        f.OrderProperty = X1_FTDC_SP_FAK;
        f.OrderAmount = 5;
        f.SessionID = 12345678;
        f.X1OrderID = (i + 1) * 100000 + j;
        f.LocalOrderID = (i + 2) * 100000 + j;
        strcpy_x(f.CommTime, "10:40:30");
        OnRtnOrder(&f);
        if (j % 100 == 0)
          boost::this_thread::sleep_for(boost::chrono::milliseconds(10));
      }
    }
  });
}

void X1SpiHandler::PushBack(std::shared_ptr<SpiMessage> msg) {
  if (m_service)
    m_service->m_recv_queue.push(msg);
}

void X1SpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_service)
    return;
  auto queue = &m_service->m_recv_queue;
  m_strand.post([=]() {
    queue->push(msg);
  });
}
