/**
 * 持仓/资金表服务. 数据来源方式:
 *
 * 持仓表普通持仓项:
 * * 持仓手数随 RtnTrade 更新.
 * * 持仓冻结手数随 RtnOrder 更新.
 * * 持仓盈亏由 持仓均价, 持仓手数和最新价计算. 当无法得到最新价时, 持仓盈亏取 RspQryPosition 的结果
 * * 浮动盈亏由 开仓均价, 持仓手数和最新价计算.
 * * 其它字段(包括平仓盈亏、保证金等) 取 RspQryPosition 的结果
 * * 为SubPosition新增 _x1_volume_today 和 _x1_volume_his 字段, 这两个值来自 RspQryPosition 的结果,
 * 保证与开仓均价、保证金等字段同步.
 *
 * 持仓表组合持仓项:
 * * 组合持仓项的全部字段都来自 RspQryPosition 的结果
 *
 * 这个算法已知有这些问题:
 *
 * * 持仓手数随RtnTrade更新，冻结手数随RtnOrder更新, 可能产生不同步, 并可能使可平手数出现负数.
 * * 平仓盈亏/保证金/开仓均价 与手数更新不同步. 如果需要保证同步, 需使用 _ctp_volume_today 和 _ctp_volume_his 字段.
 * * 组合持仓手数与普通持仓手数更新不同步, 如果需要保证同步, 需使用 _ctp_volume_today 和 _ctp_volume_his 字段.
 * * 软件初始化时, 持仓手数/冻结手数会不断跳动, 且没有稳定标志. 可以考虑登录改为QUICK模式收流,
 * 并查询历史报单/成交记录来解决
 */
class X1UnitPositionAccountView : public FuncUnit {
 public:
  X1UnitPositionAccountView(X1ServiceImpl* service, structlog::Logger& parent_logger);

  /**
   * 收到查询持仓返回包. 包中携带的信息应当被更新到持仓表中.
   */
  void OnRspQryPosition(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到查询组合持仓返回包. 包中携带的信息应当被更新到持仓表中.
   */
  void OnRspQryCombPosition(std::shared_ptr<SpiMessage> msg);

  void OnRspCustomerCapital(std::shared_ptr<SpiMessage> msg);
  /**
   * 收到成交记录. 此时应该:
   *
   * * 发起持仓查询和账户查询
   * * 尝试重算持仓手数
   *
   * 注意: 计算持仓手数时, 持仓记录中的开盘持仓手数必须已经到位
   */
  void OnRtnMatchedInfo(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到报单回报. 此时应该:
   *
   * * 发起持仓查询和账户查询
   * * 尝试重算持仓冻结手数
   *
   * 注意: 计算持仓冻结手数时, 持仓记录中的持仓手数必须已经到位, 否则可用手数可能会算成负数
   */
  void OnRtnOrder(std::shared_ptr<SpiMessage> msg);

  int RunOnce() override;

 private:
  /**
   * 处理持仓查询结果. 将查询结果中的字段填入 position 表中.
   * @param is_first: 是否是第一次收到持仓信息，如果是的话，需要给盘前持仓赋值
   */
  void ProcessQryPositionResults(bool is_first = false);
  void ProcessQryCombPositionResults();

  /**
   * 处理账户查询结果. 将查询结果中的字段填入 account 表中.
   */
  void ProcessQryAccountResults();

  /**
   * 用成交记录更新持仓中的持仓手数字段, 并相应更新其它依赖持仓手数的字段
   * * 成交记录只有单腿的，没有组合的，更新的持仓手数也只更新单腿的，组合持仓只靠查询
   * * 郑商所中，平仓是优先投机
   */
  void UpdatePositionVolumeByTrade(std::shared_ptr<CX1FtdcRspPriMatchInfoField> trade);

  /**
   * 用委托单信息更新持仓中的冻结手数字段.
   * * 组合委托单需要冻结两腿持仓的冻结量
   * * 郑商所中，平仓是优先投机
   */
  void UpdatePositionFrozenVolumeByOrder(std::shared_ptr<CX1FtdcRspPriOrderField> order);

  /**
   * 执行这个函数时，ins_node 已经没有组合合约了
   */
  void UpdateFrozenVolume(std::shared_ptr<CX1FtdcRspPriOrderField> order, const std::optional<shm::ShmInstrument>& ins,
    TX1FtdcBuySellTypeType direction,
    TX1FtdcOpenCloseTypeType offset_flag, int delta_order_volume);

  /**
   * 根据行情最新价, 更新持仓项的持仓盈亏, 不交易盈亏, 市值等字段.
   */
  void UpdatePositionProfit(std::shared_ptr<Position> calc_position);

  void OnRspUserLogin(std::shared_ptr<SpiMessage> msg);
  // void OnRspQryBrokerTradingParams(std::shared_ptr<SpiMessage> msg);

  void UpdateAccountProfit(bool is_first = false);
  void ReqQryPositionFuture(bool is_critical);
  void ReqQryPositionOption(bool is_critical);
  void ReqQryPositionComb(bool is_critical);
  void ReqQryCustomerCapital(bool is_critical);
  void UpdatePositionVolumeFrozen(SubPosition* calc_subpos);
  SubPosition* GetSubPosition(
    std::shared_ptr<future::Position> position, TX1FtdcBuySellTypeType posi_dir, TX1FtdcSpeculatorType hedge);
  SubPosition* GetSubPosition(std::shared_ptr<Position> position, TX1FtdcSpeculatorType hedge_flag,
    TX1FtdcBuySellTypeType trade_direction, TX1FtdcOpenCloseTypeType offset);

  /**
   * 最新一轮持仓查询结果.
   */
  std::vector<std::shared_ptr<CX1FtdcRspPositionField>> m_qry_position_results;
  std::vector<std::shared_ptr<CX1FtdcRspCombPositionField>> m_qry_comb_position_results;

  /**
   * 仅包含 m_user_key 的持仓视图.
   */
  std::shared_ptr<NodeDbView<Position>> m_target_position_view;

  std::shared_ptr<CX1FtdcRspCapitalField> m_last_query_account = nullptr;  // 查询到的最新资金字段
  bool m_position_inited = false;                                          // 组合之外持仓
  bool m_position_initialized = false;                                     // 所有持仓

  X1ServiceImpl* m_service = nullptr;
  std::shared_ptr<TqApiNodeDb> m_node_db;
  std::string m_user_key;
  structlog::Logger m_logger;
};

}  // namespace x1
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_X1_POSITION_ACCOUNT_VIEW_H

