X1UnitLogIn::X1UnitLogIn(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterCommandProcessor(ChangePasswordBeforeLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePasswordBeforeLogin(command);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePassword(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontConnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontConnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspTradingDay, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspTradingDay(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspResetPassword, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspResetPassword(msg);
  });
}

void X1UnitLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ReqLogin>(m_service->m_command_manager->Update(command));
  m_service->m_req_login = req;
  m_req_change_password_before_login = nullptr;
  m_service->BuildApi();
  m_service->m_command_manager->SetCommandId(req, "login");
}

void X1UnitLogIn::OnFrontConnected(std::shared_ptr<SpiMessage> msg) {
  m_api_wait_seconds = 0;
  auto req = m_service->m_command_manager->Update("login");
  if (m_service->m_req_login->user_id == "STRESS-TESTING-100") {
    if (msg->SessionType == X1_FTDC_TRADE) {
      m_service->m_spi->StartStressTesting();
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
          target_login->user_key = m_service->m_user_key;
          target_login->backend = BackEnd::kX1;
          target_login->user_id = "000000";
        });
      SetCommandFinished(req);
    }
    return;
  }
  if (msg->SessionType == X1_FTDC_TRADE) {
    m_service->m_trade_connected = true;
  } else {
    m_service->m_query_connected = true;
  }
  // 有且双前置全部连接成功再发起登录
  // 先登录交易, 再登录查询
  if (m_service->m_trade_connected && m_service->m_query_connected && !m_service->IsLogined())
    ReqUserLogin(X1_FTDC_TRADE);
}

void X1UnitLogIn::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (msg->SessionType == X1_FTDC_TRADE) {
    m_service->m_trade_connected = false;
    m_service->m_trade_logined = false;
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        if (target_login->session_status != SessionStatus::kBeforeConnect) {
          target_login->session_status = SessionStatus::kDisconnected;
        }
        target_login->status_msg = u8"前置机断连";
        target_login->trading_day = m_service->m_trading_day;
        target_login->backend = BackEnd::kX1;
        if (target_login->user_key.empty())
          target_login->user_key = m_service->m_user_key;
      });
    // 重新整理思路, 无需考虑不同场景下引起的断线是否应该重连问题.
    // 而是考虑无论任何原因引起了断线, 在 api_wait_seconds 时间内, 用户没能成功登录交易, 均应该尝试重连.
    // 故仅保留RunOnce()中的等待重连逻辑即可.
    m_last_need_connect_time = NowAsEpochNano();
    m_api_wait_seconds = 5;
  } else {
    m_service->m_query_connected = false;
    m_service->m_query_logined = false;
  }
}

void X1UnitLogIn::ReqUserLogin(int session_type) {
  CX1FtdcReqUserLoginField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.AccountID, m_service->m_req_login->user_id);
  strcpy_x(field.Password, m_service->m_req_login->password);
  strcpy_x(field.AppID, m_service->m_req_login->broker.app_id);
  strcpy_x(field.AuthCode, m_service->m_req_login->broker.auth_code);
  field.SessionType = session_type;
  int ret = m_service->m_api->ReqUserLogin(&field);
  LogReq(m_logger, "ReqUserLogin", &field, 1, ret);
  if (ret != 0) {
    auto req = m_service->m_command_manager->Update("login");
    if (session_type == 1) {
      SetCommandFinished(req, ret, u8"执行交易登录请求返回错误，ret=" + std::to_string(ret));
    } else {
      SetCommandFinished(req, ret, u8"执行查询登录请求返回错误，ret=" + std::to_string(ret));
    }
  }
}

void X1UnitLogIn::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  //  11136,        // 初次登录，请修改初始密码，否则下次不能登录 （强制修改密码）
  //  11141,        // 登录密码已过期，请联系系统管理员重置密码！ （强制修改密码）
  if (m_req_change_password_before_login) {
    if (msg->SessionType == X1_FTDC_TRADE) {
      m_service->m_trade_logined = true;
      auto req = m_service->m_command_manager->Update("change_password_before_login");
      static std::set<int> s_change_password = {0, 11136, 11141};
      if (s_change_password.find(msg->RspInfo.ErrorID) != s_change_password.end()) {
        CX1FtdcReqResetPasswordField field;
        memset(&field, 0, sizeof(field));
        strcpy_x(field.OldPassword, m_req_change_password_before_login->req_login->password);
        strcpy_x(field.NewPassword, m_req_change_password_before_login->new_password);
        strcpy_x(field.AccountID, m_req_change_password_before_login->req_login->user_id);
        int ret = m_service->m_api->ReqResetPassword(&field);
        LogReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
        if (0 != ret) {
          SetCommandFinished(req, ret, u8"修改密码指令发送失败");
        }
      } else {
        SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
      }
    }
  } else {
    if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
      if (msg->SessionType == X1_FTDC_TRADE) {
        m_service->m_trade_logined = true;
        auto pRspUserLogin = std::static_pointer_cast<CX1FtdcRspUserLoginField>(msg->pMainField);
        m_service->m_node_db->ReplaceRecord<LoginContent>(
          m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
            target_login->user_key = m_service->m_user_key;
            target_login->backend = BackEnd::kX1;
            target_login->user_id = pRspUserLogin->AccountID;
            target_login->investor_id = pRspUserLogin->AccountID;
            target_login->session_status = SessionStatus::kLogined;
            target_login->login_time = pRspUserLogin->DCEtime;
            target_login->session_id = pRspUserLogin->SessionID;
            target_login->confirm_status = ConfirmStatus::kConfirmed;
            if (target_login->user_desc == "") {
              target_login->user_desc = m_service->m_req_login->user_desc;
            }
          });
        // 此时仍然可能发生查询前置断线, 故必须保证 m_query_connected = true
        if (m_service->m_query_connected && !m_service->m_query_logined)
          ReqUserLogin(X1_FTDC_QUERY);
      } else {
        m_service->m_query_logined = true;
      }
      if (m_service->IsLogined()) {
        std::filesystem::current_path(m_service->m_path);
        ReqTradingDay();
      }
    } else {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
          if (target_login->session_status != SessionStatus::kBeforeConnect) {
            target_login->session_status = SessionStatus::kDisconnected;
          }
          target_login->status_msg = ErrorCodeToString(msg->RspInfo.ErrorID);
          target_login->trading_day = m_service->m_trading_day;
          target_login->backend = BackEnd::kX1;
          if (target_login->user_key.empty())
            target_login->user_key = m_service->m_user_key;
          if (target_login->user_desc == "") {
            target_login->user_desc = m_service->m_req_login->user_desc;
          }
        });
      auto req = m_service->m_command_manager->Update("login");
      SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
    }
  }
}

void X1UnitLogIn::ReqTradingDay() {
  CX1FtdcTradingDayField field;
  memset(&field, 0, sizeof(field));
  int request_id = m_service->GenerateRequestID();
  field.RequestID = request_id;
  auto ret = m_service->m_api->ReqTradingDay(&field);
  if (ret != 0) {
    auto req = m_service->m_command_manager->Update("login");
    SetCommandFinished(req, ret, u8"查询交易日失败");
  }
}

void X1UnitLogIn::OnRspTradingDay(std::shared_ptr<SpiMessage> msg) {
  auto pRsp = std::static_pointer_cast<CX1FtdcTradingDayRtnField>(msg->pMainField);
  m_service->m_trading_day = pRsp->date;
  m_service->m_node_db->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
      if (!target_login->trading_day.empty() && target_login->trading_day != m_service->m_trading_day) {
        m_service->m_new_day = true;
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = m_service->m_trading_day;
      if (target_login->user_key.empty())
        target_login->user_key = m_service->m_user_key;
    });
  auto req = m_service->m_command_manager->Update("login");
  SetCommandFinished(req, 0);
}

void X1UnitLogIn::ReqChangePasswordBeforeLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePasswordBeforeLogin>(m_service->m_command_manager->Update(command));
  if (!m_service->m_trading_day.empty()) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户已登录,请调用登录后修改密码接口");
    return;
  }
  if (!req->req_login->replay_flow_file_name.empty() || req->req_login->user_id == "STRESS-TESTING-100") {
    SetCommandFinished(req, -1, u8"fclib: 当前模式无法修改密码");
    return;
  }
  m_req_change_password_before_login = req;
  m_req_change_password_before_login->req_login->password = req->old_password;
  m_service->m_req_login = m_req_change_password_before_login->req_login;
  m_service->BuildApi(false);
  m_logger.Info("ReqChangePasswordBeforeLogin");
  m_service->m_command_manager->SetCommandId(command, "change_password_before_login");
}

void X1UnitLogIn::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_service->m_command_manager->Update(command));
  if (!m_service->IsLogined()) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录前修改密码接口");
    return;
  }
  int request_id;
  if (req->query_request_id > 0) {
    request_id = req->query_request_id;
  } else {
    request_id = m_service->GenerateRequestID();
  }
  CX1FtdcReqResetPasswordField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.OldPassword, req->old_password);
  strcpy_x(field.NewPassword, req->new_password);
  field.RequestID = request_id;
  strcpy_x(field.AccountID, m_service->m_req_login->user_id);
  int ret = m_service->m_api->ReqResetPassword(&field);
  m_service->SetReqResponse(command, request_id, ret);
  LogReq(m_logger, "ReqResetPassword", &field, 0, ret);
}

void X1UnitLogIn::OnRspResetPassword(std::shared_ptr<SpiMessage> msg) {
  if (m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  } else {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  }
}

int X1UnitLogIn::RunOnce() {
  // 检查
  if (!m_service->m_api || !m_service->m_spi)
    return 0;
  // 考虑重连的条件, 必须下述所有条件均满足才进行断线重连:
  // 1. 用户当前未登录交易
  // 2. 用户曾经登录成功过
  // 3. api 断线且需要重连
  if (m_api_wait_seconds > 0 && !m_service->IsLogined() && !m_service->m_trading_day.empty()) {
    // 等待连接超时, 进行重连
    if (NowAsEpochNano() - m_last_need_connect_time > m_api_wait_seconds * 1000 * 1000 * 1000) {
      m_service->BuildApi();
      m_api_wait_seconds = std::min(30, m_api_wait_seconds * 2);
      // 刷新上次重连时间, 默认认为本次连接未成功.
      // 1. 若本次连接成功, OnFrontConnected 会重置 m_api_wait_seconds = 0.
      // 2. 若本次连接失败, 则以当前时间作为上次需要重连的时间戳.
      m_last_need_connect_time = NowAsEpochNano();
    }
  }
  return 0;
}

