/*******************************************************************************
 * @file x1_position_account_view.cpp
 * @brief X1持仓列表服务
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "x1_position_account_view.h"

#include <algorithm>
#include <memory>
#include <string>
#include "fclib/model/model_future.h"
#include "fclib/utils/numset.h"
#include "x1_convert.h"
#include "x1_logger.h"
#include "x1_service_impl.h"
#include "md/md_service_shm_helper.h"
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace x1 {
template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(
  SpiMessage::Tag tag, const T* plain_src, ::CX1FtdcRspErrorField* rsp_info, int req_id, bool is_last);

X1UnitPositionAccountView::X1UnitPositionAccountView(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_node_db(service->m_node_db)
  , m_user_key(service->m_user_key)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    m_service->m_command_manager->SetCommandId(command, "RequireQryAccount");
    ReqQryCustomerCapital(false);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryCombPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryCombPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspCustomerCapital, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCustomerCapital(msg);
  });
  /** trade和order可能重复，这个没有考虑 */
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCancelOrder, [this](std::shared_ptr<SpiMessage> msg) {
    auto pCancelOrderData = std::static_pointer_cast<CX1FtdcRspPriCancelOrderField>(msg->pMainField);
    CX1FtdcRspPriOrderField pRtnOrderData = {0};
    ConvertCancelOrderToOrder(pCancelOrderData.get(), &pRtnOrderData);
    auto new_msg = MakeSpiMsg<CX1FtdcRspPriOrderField>(SpiMessage::Tag::OnRtnOrder, &pRtnOrderData);
    OnRtnOrder(new_msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMatchedInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMatchedInfo(msg);
  });
  m_target_position_view = m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_user_key && pos->unit_id == 0;
  });
}

void X1UnitPositionAccountView::OnRspQryPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto position = std::static_pointer_cast<CX1FtdcRspPositionField>(msg->pMainField);
    m_qry_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryPositionResults(!m_position_inited);
    UpdateAccountProfit(!m_position_inited);
    m_position_inited = true;
  }
}

void X1UnitPositionAccountView::OnRspQryCombPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto position = std::static_pointer_cast<CX1FtdcRspCombPositionField>(msg->pMainField);
    m_qry_comb_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryCombPositionResults();
    if (!m_position_initialized) {  // 组合持仓是最后一个查询的持仓，在这个请求到位后，可以判定持仓到位了
      m_position_initialized = true;
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_user_key;
        p->backend = BackEnd::kX1;
        p->position_ready = true;
      });
    }
    UpdateAccountProfit();
  }
}

void X1UnitPositionAccountView::OnRspCustomerCapital(std::shared_ptr<SpiMessage> msg) {
  bool is_first = (m_last_query_account == nullptr);
  if (msg->pMainField) {
    auto rsp = std::static_pointer_cast<CX1FtdcRspCapitalField>(msg->pMainField);
    if (strcmp(rsp->CurrencyID, "CNY") == 0)
      m_last_query_account = rsp;
  }
  if (msg->bIsLast) {
    ProcessQryAccountResults();
    if (is_first) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_user_key;
        p->backend = BackEnd::kX1;
        p->account_ready = true;
      });
    }
    if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
      SetCommandFinished(req);
  }
}

void X1UnitPositionAccountView::ProcessQryAccountResults() {
  if (!m_last_query_account)
    return;
  auto account_key = Account::MakeKey(m_user_key, 0, m_last_query_account->CurrencyID);
  m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> target_account) {
    target_account->user_key = m_user_key;
    target_account->currency = m_last_query_account->CurrencyID;
    target_account->pre_balance = m_last_query_account->PreEquity;
    target_account->balance = m_last_query_account->TodayEquity;
    target_account->investor_id = m_last_query_account->AccountID;
    target_account->close_profit = m_last_query_account->CloseProfitLoss;
    target_account->position_profit = m_last_query_account->PositionProfitLoss;
    target_account->frozen_margin = m_last_query_account->FrozenMargin;
    target_account->margin = m_last_query_account->Margin;
    target_account->commission = m_last_query_account->Fee;
    target_account->available = m_last_query_account->Available;
    target_account->withdraw_quota = m_last_query_account->Withdraw;
    target_account->risk_ratio = m_last_query_account->RiskDegree;
    target_account->premium = m_last_query_account->TodayPremiumIncome - m_last_query_account->TodayPremiumPay;
    target_account->option_market_value = m_last_query_account->OptMarketValue;
    target_account->float_profit = m_last_query_account->ProfitLoss;
    target_account->deposit = m_last_query_account->TotalFundIn;
    target_account->withdraw = m_last_query_account->TotalFundOut;
    target_account->mortgage = m_last_query_account->Mortgage;
    target_account->fund_mortgagein = m_last_query_account->FundMortgageIn;
    target_account->fund_mortgageout = m_last_query_account->FundMortgageOut;
    target_account->fund_mortgageavailable = m_last_query_account->FundMortgageAvailable;
    target_account->client_equity = m_last_query_account->TodayEquity + m_last_query_account->OptMarketValue;
  });
}

void X1UnitPositionAccountView::ProcessQryPositionResults(bool is_first) {
  for (auto origin_position : m_qry_position_results) {
    std::string position_symbol =
      std::string(origin_position->ExchangeID) + "." + std::string(origin_position->InstrumentID);
    auto position_key = m_user_key + "|0|" + position_symbol;
    m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_user_key;
      target_position->investor_id = origin_position->AccountID;
      target_position->exchange_id = origin_position->ExchangeID;
      target_position->instrument_id = origin_position->InstrumentID;
      auto ins = m_service->m_md_helper->GetShmInstrument(target_position->Symbol(), true);
      double pre_settlement = origin_position->PreSettlementPrice;
      if (!IsValid(pre_settlement) || IsZero(pre_settlement))
        pre_settlement = ins->pre_settlement;
      future::SubPosition* subpos =
        GetSubPosition(target_position, origin_position->BuySellType, origin_position->Speculator);
      if (origin_position->Speculator == X1_FTDC_SPD_ARBITRAGE) {
        subpos->hedge_type = PositionHedgeType::kArbitrage;
      }
      subpos->volume_today = origin_position->TodayAmount;
      subpos->volume_his = origin_position->LastAmount;
      subpos->volume_today_frozen = origin_position->TradingAmount;
      subpos->volume_his_frozen = origin_position->YesterdayTradingAmount;
      subpos->margin = origin_position->Margin;
      subpos->premium = origin_position->Premium;
      subpos->close_profit = origin_position->DateCloseProfitLoss;
      subpos->open_price = origin_position->OpenAvgPrice;
      subpos->position_price = origin_position->PositionAvgPrice;
      subpos->_qry_volume_today = origin_position->TodayAmount;
      subpos->_premium = origin_position->Premium;
      subpos->_open_cost = origin_position->OpenAvgPrice * origin_position->PositionAmount;
      subpos->volume_yesterday = origin_position->LastAmount;
      subpos->_qry_volume_his = origin_position->LastAmount;
      if (is_first) {  // 首次收到持仓
        subpos->_position_cost_his = origin_position->LastAmount * pre_settlement * ins->volume_multiple;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value_yesterday = pre_settlement * subpos->volume_yesterday * ins->volume_multiple;
          if (subpos->direction == Direction::kSell)
            subpos->market_value_yesterday *= -1;
        }
      }
      UpdatePositionProfit(target_position);
    });
  }
  m_qry_position_results.clear();
}

// x1接口返回的组合合约代码是 a2305,-a2306这样的，需要转成标准组合
std::string GetCombInsID(std::string insid, TX1FtdcBuySellTypeType& direction) {
  auto pos0 = insid.find(",");
  auto insid0 = insid.substr(0, pos0);
  auto insid1 = insid.substr(pos0 + 1);
  if (insid0[0] == '-') {
    insid0 = insid0.substr(1);
    direction = X1_FTDC_SPD_BUY;
    if (insid0.size() == insid1.size() && insid0[0] == insid1[0])
      return "SP " + insid0 + "&" + insid1;
    else
      return "SPC " + insid0 + "&" + insid1;
  } else {
    direction = X1_FTDC_SPD_SELL;
    insid1 = insid1.substr(1);
    if (insid0.size() == insid1.size() && insid0[0] == insid1[0])
      return "SP " + insid0 + "&" + insid1;
    else
      return "SPC " + insid0 + "&" + insid1;
  }
}

