    UpdatePositionVolumeByTrade(trade);
}

void CalcPositionCost(SubPosition* subpos, int close_volume, double volume_multiple) {
  for (auto it = subpos->_open_list.begin(); it != subpos->_open_list.end();) {
    int close_vol = std::min(close_volume, it->second);
    close_volume -= close_vol;
    it->second -= close_vol;
    if (it->second == 0) {
      it = subpos->_open_list.erase(it);
      if (close_volume > 0)
        continue;
    }
    break;
  }
  subpos->_position_cost = 0;
  for (auto open : subpos->_open_list) {
    subpos->_position_cost += open.first * open.second * volume_multiple;
  }
}

void X1UnitPositionAccountView::UpdatePositionVolumeByTrade(std::shared_ptr<CX1FtdcRspPriMatchInfoField> trade) {
  std::string symbol = std::string(trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  std::string position_key = m_user_key + "|0|" + symbol;
  auto position_node = m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
    position->user_key = m_user_key;
    position->investor_id = trade->AccountID;
    position->exchange_id = trade->ExchangeID;
    position->instrument_id = trade->InstrumentID;
    auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
    std::string investor_id = std::string(trade->AccountID);
    auto offset_flag = trade->OpenCloseType;
    if (offset_flag == X1_FTDC_SPD_CLOSETODAY && !ins->HasCloseToday()) {
      offset_flag = X1_FTDC_SPD_CLOSE;
    }
    SubPosition* calc_subpos = GetSubPosition(position, trade->Speculator, trade->BuySellType, trade->OpenCloseType);
    if (offset_flag == X1_FTDC_SPD_OPEN) {
      calc_subpos->volume_today += trade->MatchedAmount;
      auto cost = trade->MatchedAmount * trade->MatchedPrice * ins->volume_multiple;
      calc_subpos->_position_cost += cost;
      calc_subpos->_open_list.push_back({trade->MatchedPrice, trade->MatchedAmount});
    } else if (offset_flag == X1_FTDC_SPD_CLOSETODAY) {
      calc_subpos->volume_today -= trade->MatchedAmount;
      CalcPositionCost(calc_subpos, trade->MatchedAmount, ins->volume_multiple);
    } else {
      /** 郑商所优先平投机，后平保值 */
      if (position->exchange_id == "CZCE") {
        SubPosition* calc_subpos0 =
          GetSubPosition(position, X1_FTDC_SPD_SPECULATOR, trade->BuySellType, trade->OpenCloseType);
        auto spec_vol = std::min(calc_subpos0->Volume(), static_cast<int>(trade->MatchedAmount));
        if (spec_vol > 0) {
          auto spec_vol_his = std::min(calc_subpos0->volume_his, spec_vol);
          if (spec_vol_his > 0) {  // 老仓按比率缩小持仓成本
            calc_subpos0->_position_cost_his *=
              (calc_subpos0->volume_his - spec_vol_his) * 1.0 / calc_subpos0->volume_his;
            calc_subpos0->volume_his -= spec_vol_his;
          }
          if (spec_vol > spec_vol_his) {  // 今仓按先开先平计算持仓成本
            calc_subpos0->volume_today -= (spec_vol - spec_vol_his);
            CalcPositionCost(calc_subpos0, spec_vol - spec_vol_his, ins->volume_multiple);
          }
          // if (calc_subpos0->Volume() == 0) {
          //   calc_subpos0->position_price = 0;
          // } else {
          //   calc_subpos0->position_price =
          //     calc_subpos0->_position_cost / calc_subpos0->Volume() / ins->volume_multiple;
          // }
          UpdatePositionVolumeFrozen(calc_subpos0);
        }
        auto hedge_vol = static_cast<int>(trade->MatchedAmount) - spec_vol;
        if (hedge_vol > 0) {
          SubPosition* calc_subpos1 =
            GetSubPosition(position, X1_FTDC_SPD_HEDGE, trade->BuySellType, trade->OpenCloseType);
          auto hedge_vol_his = std::min(calc_subpos1->volume_his, hedge_vol);
          if (hedge_vol_his > 0) {
            double percentage = (calc_subpos1->volume_his - hedge_vol_his) * 1.0 / calc_subpos1->volume_his;
            calc_subpos1->_position_cost_his *= percentage;
            calc_subpos1->volume_his -= hedge_vol_his;
          }
          if (hedge_vol > hedge_vol_his) {
            calc_subpos1->volume_today -= (hedge_vol - hedge_vol_his);
            CalcPositionCost(calc_subpos1, hedge_vol - hedge_vol_his, ins->volume_multiple);
          }
          // if (calc_subpos1->Volume() == 0) {
          //   calc_subpos1->position_price = 0;
          // } else {
          //   calc_subpos1->position_price =
          //     calc_subpos1->_position_cost / calc_subpos1->Volume() / ins->volume_multiple;
          // }
          UpdatePositionVolumeFrozen(calc_subpos1);
        }
      } else {
        if (ins->HasCloseToday()) {
          double percentage = (calc_subpos->volume_his - trade->MatchedAmount) * 1.0 / calc_subpos->volume_his;
          calc_subpos->_position_cost_his *= percentage;
          calc_subpos->volume_his -= trade->MatchedAmount;
          FCASSERT(calc_subpos->volume_his >= 0);
        } else {
          auto vol_his = std::min(calc_subpos->volume_his, static_cast<int>(trade->MatchedAmount));
          if (vol_his > 0) {
            double percentage = (calc_subpos->volume_his - vol_his) * 1.0 / calc_subpos->volume_his;
            calc_subpos->_position_cost_his *= percentage;
            calc_subpos->volume_his -= vol_his;
          }
          if (trade->MatchedAmount > vol_his) {
            calc_subpos->volume_today -= (trade->MatchedAmount - vol_his);
            CalcPositionCost(calc_subpos, trade->MatchedAmount - vol_his, ins->volume_multiple);
          }
        }
      }
    }
    // if (calc_subpos->Volume() == 0) {
    //   calc_subpos->position_price = 0;
    // } else {
    //   calc_subpos->position_price = (calc_subpos->_position_cost + calc_subpos->_position_cost_his)
    //     / calc_subpos->Volume() / ins->volume_multiple;
    // }
    if (!ins->HasCloseToday()) {
      UpdatePositionVolumeFrozen(calc_subpos);
    }
    UpdatePositionProfit(position);
  });
}

void X1UnitPositionAccountView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto order = std::static_pointer_cast<CX1FtdcRspPriOrderField>(msg->pMainField);
  if (order->OpenCloseType != X1_FTDC_SPD_OPEN && order->OrderStatus != X1_FTDC_SPD_FILLED) {
    if (order->InstrumentType == X1FTDC_INSTRUMENT_TYPE_OPT)
      ReqQryPositionOption(false);
    else
      ReqQryPositionFuture(false);
    if (m_position_initialized)
      UpdatePositionFrozenVolumeByOrder(order);
  }
  ReqQryCustomerCapital(false);
  ReqQryPositionComb(false);
}

void X1UnitPositionAccountView::UpdatePositionFrozenVolumeByOrder(std::shared_ptr<CX1FtdcRspPriOrderField> order) {
  // 计算冻结手数差额
  auto order_id = ToFclibOrderId(order->LocalOrderID, order->SessionID);
  int delta_order_volume =
    (ConvertFromSfitOrderStatus(&order->OrderStatus) == OrderStatus::kAlive) ? order->OrderAmount : 0;
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->GetNode<Order>(order_key);
  if (order_node->Historical()) {
    int prev_order_volume =
      (order_node->Historical()->status == OrderStatus::kAlive) ? order_node->Historical()->volume_left : 0;
    delta_order_volume -= prev_order_volume;
  }
  if (delta_order_volume == 0)
    return;
  // 更新持仓
  auto ins = m_service->m_md_helper->GetShmInstrument(
    std::string(order->ExchangeID) + "." + std::string(order->InstrumentID), true);
  if (ins->product_class == md::ProductClass::kCombine) {
    auto offset_flag = order->OpenCloseType;
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2_ins = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    FCASSERT(leg1_ins);
    FCASSERT(leg2_ins);
    auto direction = (order->BuySellType == X1_FTDC_SPD_BUY ? X1_FTDC_SPD_SELL : X1_FTDC_SPD_BUY);
    if (offset_flag != X1_FTDC_SPD_OPEN) {
      UpdateFrozenVolume(order, leg1_ins, order->BuySellType, order->OpenCloseType, delta_order_volume);
      UpdateFrozenVolume(order, leg2_ins, direction, offset_flag, delta_order_volume);
    }
  } else {
    UpdateFrozenVolume(order, ins, order->BuySellType, order->OpenCloseType, delta_order_volume);
  }
}

void X1UnitPositionAccountView::UpdateFrozenVolume(std::shared_ptr<CX1FtdcRspPriOrderField> order,
  const std::optional<shm::ShmInstrument>& ins, TX1FtdcBuySellTypeType direction, TX1FtdcOpenCloseTypeType offset_flag,
  int delta_order_volume) {
  std::string position_key = m_user_key + "|0|" + ins->symbol.data();
  auto position_node = m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
    position->user_key = m_user_key;
    position->investor_id = order->AccountID;
    position->exchange_id = order->ExchangeID;
    position->instrument_id = ins->instrument_id.data();

    SubPosition* calc_subpos = GetSubPosition(position, order->Speculator, direction, offset_flag);
    if (offset_flag == X1_FTDC_SPD_CLOSETODAY && !ins->HasCloseToday()) {
      offset_flag = X1_FTDC_SPD_CLOSE;
    }
    if (offset_flag == X1_FTDC_SPD_CLOSETODAY) {
      calc_subpos->volume_today_frozen += delta_order_volume;
    } else if (ins->HasCloseToday()) {
      calc_subpos->volume_his_frozen += delta_order_volume;
    } else {
      if (position->exchange_id == "CZCE") {
        SubPosition* calc_subpos0 = GetSubPosition(position, X1_FTDC_SPD_SPECULATOR, direction, offset_flag);
        SubPosition* calc_subpos1 = GetSubPosition(position, X1_FTDC_SPD_HEDGE, direction, offset_flag);
        if (delta_order_volume > 0) { /** 冻结时，先投机后保值 */
          auto frozen0 = std::min(delta_order_volume, calc_subpos0->Volume() - calc_subpos0->VolumeFrozen());
          if (frozen0 > 0)
            calc_subpos0->volume_his_frozen += frozen0;
          if (delta_order_volume > frozen0) {
            calc_subpos1->volume_his_frozen += delta_order_volume - frozen0;
          }
        } else { /** 解冻时，先保值后投机 */
          auto frozen1 = std::min(-delta_order_volume, calc_subpos1->VolumeFrozen());
          if (frozen1 > 0)
            calc_subpos1->volume_his_frozen -= frozen1;
          if (-delta_order_volume > frozen1) {
            calc_subpos0->volume_his_frozen -= -delta_order_volume - frozen1;
          }
        }
        UpdatePositionVolumeFrozen(calc_subpos0);
        UpdatePositionVolumeFrozen(calc_subpos1);
      } else {
        calc_subpos->volume_his_frozen += delta_order_volume;
        UpdatePositionVolumeFrozen(calc_subpos);
      }
    }
    UpdatePositionProfit(position);
  });
}

void X1UnitPositionAccountView::UpdatePositionVolumeFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->VolumeFrozen();
  calc_subpos->volume_his_frozen = std::min(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

future::SubPosition* X1UnitPositionAccountView::GetSubPosition(
  std::shared_ptr<future::Position> position, TX1FtdcBuySellTypeType posi_dir, TX1FtdcSpeculatorType hedge) {
  if (posi_dir == X1_FTDC_SPD_BUY) {
    if (hedge == X1_FTDC_SPD_SPECULATOR)
      return &position->subpos_long_spec;
    else
      return &position->subpos_long_other;
  } else if (posi_dir == X1_FTDC_SPD_SELL) {
    if (hedge == X1_FTDC_SPD_SPECULATOR)
      return &position->subpos_short_spec;
    else
      return &position->subpos_short_other;
  }
  FCASSERT(false);
  return nullptr;
}

SubPosition* X1UnitPositionAccountView::GetSubPosition(std::shared_ptr<Position> position,
  TX1FtdcSpeculatorType hedge_flag, TX1FtdcBuySellTypeType trade_direction, TX1FtdcOpenCloseTypeType offset) {
  SubPosition* subpos = nullptr;
  if (hedge_flag == X1_FTDC_SPD_SPECULATOR) {
    if ((trade_direction == X1_FTDC_SPD_BUY && offset == X1_FTDC_SPD_OPEN)
      || (trade_direction == X1_FTDC_SPD_SELL && offset != X1_FTDC_SPD_OPEN))
      subpos = &position->subpos_long_spec;
    else
      subpos = &position->subpos_short_spec;
  } else {
    if ((trade_direction == X1_FTDC_SPD_BUY && offset == X1_FTDC_SPD_OPEN)
      || (trade_direction == X1_FTDC_SPD_SELL && offset != X1_FTDC_SPD_OPEN))
      subpos = &position->subpos_long_other;
    else
      subpos = &position->subpos_short_other;
  }
  return subpos;
}

void X1UnitPositionAccountView::UpdatePositionProfit(std::shared_ptr<Position> position) {
  auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
  if (ins->CheckQuote(m_service->m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  // 无法获得最新价, 取查询返回值
  if (std::isnan(position->last_price) || IsZero(position->last_price)) {
    for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
           &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
      auto subpos = &((*(position)).*p);
      auto profit = subpos->_position_profit + subpos->_position_profit_his;
      subpos->position_profit = profit;
      subpos->float_profit = 0;
    }
    return;
  }

  // 可以计算
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture)
        subpos->position_profit =
          subpos->market_value - subpos->position_price * ins->volume_multiple * subpos->Volume();
      else if (ins->product_class == md::ProductClass::kOption)
        subpos->position_profit = 0;
      if (!IsZero(subpos->open_price))
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
      if (subpos->volume_yesterday > 0 && position->last_price != ins->pre_settlement) {
        subpos->untrade_profit = (position->last_price - ins->pre_settlement) * subpos->volume_yesterday
          * ins->volume_multiple * (subpos->direction == Direction::kBuy ? 1 : -1);
      } else {
        subpos->untrade_profit = 0.0;
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

