    "ReqQryPositionFuture", X1QueryPlanner::Priority::kHigh, m_service->GenerateRequestID(),
    [=](int request_id) {
      auto field = std::make_shared<CX1FtdcQryPositionField>();
      memset(field.get(), 0, sizeof(*field));
      strcpy_x(field->AccountID, m_service->m_req_login->user_id);
      field->InstrumentType = X1FTDC_INSTRUMENT_TYPE_COMM;  // 期货
      field->RequestID = request_id;
      auto ret = m_service->m_api->ReqQryPosition(field.get());
      LogReq(m_logger, "ReqQryPosition", field.get(), request_id, ret);
      return ret;
