template <>
void LogReq(structlog::Logger& logger, const char* msg, CX1FtdcTimeOutField* p, int request_id, int ret_code) {
  logger.With("request_id", request_id).With("ret_code", ret_code).With("RequestID", p->RequestID).Info(msg);
}

template <>
void LogRtn(structlog::Logger& logger, const char* msg, CX1FtdcTimeOutField* p, CX1FtdcRspErrorField* pRspInfo,
  int request_id, bool is_last) {
  logger.With("request_id", request_id).With("is_last", is_last);
  if (p) {
    logger.With("RequestID", p->RequestID);
  }
  if (pRspInfo) {
    logger.With("ErrorID", pRspInfo->ErrorID).With("ErrorMsg", pRspInfo->ErrorMsg);
  }
  logger.Info(msg);
}

