static void UpdateTradeVolumeByTrade(std::shared_ptr<const TradeBase> trade,
  const std::optional<shm::ShmInstrument>& ins, std::shared_ptr<OrderBase> order) {
  if (nullptr == trade || !ins.has_value())
    return;
  // 更新成交均价和成交手数
  bool is_combine =
    (ins->product_class == md::ProductClass::kCombine || ins->product_class == md::ProductClass::kCusCombine);
  if (!is_combine) {
    if (trade->Symbol() != std::string(ins->symbol.data()) || order->trade_total_volume + trade->volume <= 0)
      return;
    order->trade_total_volume += trade->volume;
    return;
  }
  auto leg1_symbol = ins->leg1_symbol;
  auto leg2_symbol = ins->leg2_symbol;
  if (trade->Symbol() != std::string(leg1_symbol.data()) && trade->Symbol() != std::string(leg2_symbol.data()))
    return;
  if (trade->Symbol() == std::string(leg1_symbol.data())) {
    order->_leg1_trade_total_volume += trade->volume;
  } else {
    order->_leg2_trade_total_volume += trade->volume;
  }
  order->trade_total_volume = (std::min)(order->_leg1_trade_total_volume, order->_leg2_trade_total_volume);
}

X1UnitOrderTradeView::X1UnitOrderTradeView(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_node_db(service->m_node_db)
  , m_user_key(service->m_user_key)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspInsertOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspTradingDay, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspTradingDay(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCancelOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnCancelOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMatchedInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMatchedInfo(msg);
  });
}

void X1UnitOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CX1FtdcRspPriOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->LocalOrderID, origin->SessionID);
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (order->order_id.empty()) {
      order->volume_left = origin->OrderAmount;
      auto iter = m_service->m_send_time.find(order_id);
      if (iter != m_service->m_send_time.end()) {
        order->send_date_time = iter->second;
        m_service->m_send_time.erase(iter);
      }
      order->receive_date_time = NowAsEpochNano();
    }
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->AccountID;
    order->user_id = origin->AccountID;
    order->direction = x1::ConvertFromSfitDirection(&origin->BuySellType);
    order->exchange_order_id = origin->OrderSysID;
    order->status_msg = origin->StatusMsg;
    order->limit_price = origin->InsertPrice;
    order->offset = x1::ConvertFromSfitOffset(origin->OpenCloseType);
    order->hedge_flag = x1::ConvertFromSfitHedgeFlag(&origin->Speculator);
    x1::ConvertOrder(&origin->OrderType, &origin->OrderProperty, order);
    order->status = x1::ConvertFromSfitOrderStatus(&origin->OrderStatus);
    order->volume_orign = origin->OrderAmount;
    order->order_ref = std::to_string(origin->LocalOrderID);
    order->session_id = origin->SessionID;
    order->order_local_id = std::to_string(origin->X1OrderID);
    order->min_volume = static_cast<int32_t>(origin->MinMatchAmount);
    if (origin->CommTime[0] != '\0') {
      order->insert_date_time = GetRealTradeTime(m_trading_day.c_str(), origin->CommTime);
    }
    order->force_close_reason = ForceCloseReason::kNotForceClose;
    order->order_id = ToFclibOrderId(origin->LocalOrderID, origin->SessionID);
    order->unit_id = origin->LocalOrderID % 100;
    order->user_key = m_user_key;
  });
  auto map_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  m_order_map[map_key] = order_node;
  if (!m_trade_cache.empty())
    ProcessCachedTrade(order_node);
}

