  auto origin = std::static_pointer_cast<CX1FtdcRspPriCancelOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->LocalOrderID, origin->SessionID);
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->AccountID;
    order->user_id = origin->AccountID;
    order->direction = x1::ConvertFromSfitDirection(&origin->BuySellType);
    order->exchange_order_id = origin->OrderSysID;
    order->status_msg = origin->StatusMsg;
    order->limit_price = origin->InsertPrice;
    order->offset = x1::ConvertFromSfitOffset(origin->OpenCloseType);
    order->hedge_flag = x1::ConvertFromSfitHedgeFlag(&origin->Speculator);
    order->status = x1::ConvertFromSfitOrderStatus(&origin->OrderStatus);
    order->volume_orign = origin->OrderAmount;
    order->order_ref = std::to_string(origin->LocalOrderID);
    order->session_id = origin->SessionID;
    order->order_local_id = std::to_string(origin->X1OrderID);
    order->min_volume = static_cast<int32_t>(origin->MinMatchAmount);
    if (origin->CanceledTime[0] != '\0') {
      order->dead_date_time = GetRealTradeTime(m_trading_day.c_str(), origin->CanceledTime);
    }
    order->force_close_reason = ForceCloseReason::kNotForceClose;
    order->order_id = ToFclibOrderId(origin->LocalOrderID, origin->SessionID);
    order->unit_id = origin->LocalOrderID % 100;
    order->user_key = m_user_key;
  });
}

void X1UnitOrderTradeView::OnRspInsertOrder(std::shared_ptr<SpiMessage> msg) {
  if (!m_session.has_value())
    return;
  auto origin = std::static_pointer_cast<CX1FtdcRspOperOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->LocalOrderID, m_session.value().SessionID);
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    order->request_id = std::to_string(origin->RequestID);
    if (!order->order_id.empty())
      return;
    order->order_id = order_id;
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->AccountID;
    order->user_id = origin->AccountID;
    order->direction = x1::ConvertFromSfitDirection(&origin->BuySellType);
    order->limit_price = origin->InsertPrice;
    order->offset = x1::ConvertFromSfitOffset(origin->OpenCloseType);
    order->hedge_flag = x1::ConvertFromSfitHedgeFlag(&origin->Speculator);
    x1::ConvertOrder(&origin->OrderType, &origin->OrderProperty, order);
    order->volume_left = origin->OrderAmount;
    order->volume_orign = origin->OrderAmount;
    order->order_ref = std::to_string(origin->LocalOrderID);
    order->session_id = m_session.value().SessionID;
    order->order_local_id = std::to_string(origin->X1OrderID);
    order->min_volume = origin->MinMatchAmount;
    order->force_close_reason = ForceCloseReason::kNotForceClose;
    order->unit_id = origin->LocalOrderID % 100;
    order->user_key = m_user_key;
    order->status = OrderStatus::kAlive;
    if (msg->RspInfo.ErrorID != 0) {
      order->status = OrderStatus::kDead;
      order->status_msg = ErrorCodeToString(msg->RspInfo.ErrorID);
    }
  });
}

void X1UnitOrderTradeView::ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node) {
  const std::string& cache_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  auto it = m_trade_cache.find(cache_key);
  if (it == m_trade_cache.end())
    return;
  auto& trades = it->second;
  for (auto trade : trades) {
    ProcessTrade(trade, order_node);
  }
  m_trade_cache.erase(it);
}

void X1UnitOrderTradeView::ProcessTrade(
  std::shared_ptr<CX1FtdcRspPriMatchInfoField> origin, std::shared_ptr<future::OrderNode> order_node) {
  auto trade_key = m_user_key + "|" + origin->MatchID + "|" + origin->OrderSysID;
  auto trade_node = m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->investor_id = origin->AccountID;
    trade->user_id = origin->AccountID;
    if (origin->MatchedTime[0] != '\0') {
      trade->trade_date_time = GetRealTradeTime(m_trading_day.c_str(), origin->MatchedTime);
    }
    trade->direction = x1::ConvertFromSfitDirection(&origin->BuySellType);
    trade->exchange_id = origin->ExchangeID;
    trade->instrument_id = origin->InstrumentID;
    trade->exchange_trade_id = origin->MatchID;
    trade->offset = x1::ConvertFromSfitOffset(origin->OpenCloseType);
    trade->hedge_flag = x1::ConvertFromSfitHedgeFlag(&origin->Speculator);
    trade->exchange_order_id = origin->OrderSysID;
    trade->order_local_id = std::to_string(origin->LocalOrderID);
    trade->price = origin->MatchedPrice;
    trade->volume = origin->MatchedAmount;
    auto ins = m_service->m_md_helper->GetShmInstrument(trade->Symbol(), true);
    if (trade->offset == Offset::kOpen) {
      if (!ins->HasCloseToday()) {
        if (trade->direction == Direction::kBuy)
          m_long_position[trade->Symbol()] += trade->volume;
        else
          m_short_position[trade->Symbol()] += trade->volume;
      }
    } else {
      if (ins->HasCloseToday()) {
        if (trade->offset == Offset::kCloseToday)
          trade->volume_close_today = trade->volume;
        else
          trade->volume_close_yesterday = trade->volume;
      } else {
        if (trade->direction == Direction::kBuy) {
          trade->volume_close_today = std::min(m_short_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_short_position[trade->Symbol()] -= trade->volume_close_today;
        } else {
          trade->volume_close_today = std::min(m_long_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_long_position[trade->Symbol()] -= trade->volume_close_today;
        }
      }
    }
    trade->trader_id = origin->MatchID;
    trade->user_key = m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_node->Latest()->order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->commission = origin->Fee;
  });
  m_node_db->ReplaceRecord<Order>(order_node->Latest()->GetKey(), [=](std::shared_ptr<Order> order) {
    auto pre_trade_total_volume = order->trade_total_volume;
    auto ins = m_service->m_md_helper->GetShmInstrument(order_node->Latest()->Symbol(), true);
    FCASSERT(ins);
    if (order->volume_left == 0)
      return;
    if (!(order->trade_set.insert(trade_node)).second) {
      return;
    }
    UpdateTradeVolumeByTrade(
      std::static_pointer_cast<const TradeBase>(trade_node->Latest()), ins, std::static_pointer_cast<OrderBase>(order));
    auto delta = order->trade_total_volume - pre_trade_total_volume;
    FCASSERT(delta >= 0);
    order->volume_left -= delta;
    if (order->volume_left == 0) {
      order->status = OrderStatus::kDead;
      m_order_map.erase(order->exchange_order_id + "|" + order->exchange_id);
    }
  });
}

void X1UnitOrderTradeView::OnRtnMatchedInfo(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CX1FtdcRspPriMatchInfoField>(msg->pMainField);
  auto order_node = GetMatchOrder(origin->OrderSysID, origin->ExchangeID);
  if (!order_node) {
    AddTradeToCache(origin);
    return;
  }
  ProcessTrade(origin, order_node);
}

int X1UnitOrderTradeView::RunOnce() {
  return 0;
}

std::shared_ptr<future::OrderNode> X1UnitOrderTradeView::GetMatchOrder(std::string OrderSysID, std::string ExchangeID) {
  auto map_key = OrderSysID + "|" + ExchangeID;
  auto it = m_order_map.find(map_key);
  if (it == m_order_map.end())
    return nullptr;
  return it->second;
}

void X1UnitOrderTradeView::AddTradeToCache(std::shared_ptr<CX1FtdcRspPriMatchInfoField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  m_trade_cache[map_key].insert(origin);
}

void X1UnitOrderTradeView::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField
    && (msg->RspInfo.ErrorID == 0 || msg->RspInfo.ErrorID == 2087 || msg->RspInfo.ErrorID == 3034
      || msg->RspInfo.ErrorID == 3033 || msg->RspInfo.ErrorID == 3035 || msg->RspInfo.ErrorID == 3036)) {
    auto rsp = std::static_pointer_cast<CX1FtdcRspUserLoginField>(msg->pMainField);
    m_session = *rsp;
  }
}

void X1UnitOrderTradeView::OnRspTradingDay(std::shared_ptr<SpiMessage> msg) {
  auto pRsp = std::static_pointer_cast<CX1FtdcTradingDayRtnField>(msg->pMainField);
  m_trading_day = pRsp->date;
}

