X1UnitRate::X1UnitRate(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQrySpecifyInstrument(command);
  });
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQrySpecifyInstrument(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQrySpecifyInstrument, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQrySpecifyInstrument(msg);
  });
}

void X1UnitRate::ReqQrySpecifyInstrument(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  if (qry->instrument_id.empty()) {
    SetCommandFinished(qry);
    return;
  }
  auto rate_key = m_service->m_req_login->user_key + "|" + qry->instrument_id;
  if (m_service->m_node_db->GetNode<Rate>(rate_key)) {
    SetCommandFinished(qry);
    return;
  }
  auto key = "ReqQrySpecifyInstrument" + qry->instrument_id;
  auto field = std::make_shared<CX1FtdcQrySpecificInstrumentField>();
  memset(field.get(), 0, sizeof(CX1FtdcQrySpecificInstrumentField));
  strcpy_x(field->AccountID, m_service->m_req_login->user_id);
  field->InstrumentType = 0;
  strcpy_x(field->InstrumentID, qry->instrument_id);
  if (command->query_request_id > 0)
    field->RequestID = command->query_request_id;
  else
    field->RequestID = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, std::to_string(field->RequestID));
  auto ret = m_service->m_api->ReqQrySpecifyInstrument(field.get());
  if (ret >= 0)
    LogReq(m_logger, "ReqQrySpecifyInstrument", field.get(), field->RequestID, ret);
}

void X1UnitRate::OnRspQrySpecifyInstrument(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->RspInfo.ErrorID == 0) {
    std::shared_ptr<CX1FtdcRspSpecificInstrumentField> rate =
      std::static_pointer_cast<CX1FtdcRspSpecificInstrumentField>(msg->pMainField);
    auto rate_key = m_service->m_req_login->user_key + "|" + rate->InstrumentID;
    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_req_login->user_key;
      rate_node->instrument_id = rate->InstrumentID;
      rate_node->margin_rate_long_spec = (UnitRate(rate->LongMarginRatio, rate->LongMarginRatioByVolume));
      rate_node->margin_rate_short_spec = (UnitRate(rate->ShortMarginRatio, rate->ShortMarginRatioByVolume));
      rate_node->margin_rate_long_other = (UnitRate(rate->LongMarginRatio, rate->LongMarginRatioByVolume));
      rate_node->margin_rate_short_spec = (UnitRate(rate->ShortMarginRatio, rate->ShortMarginRatioByVolume));
      rate_node->commission_rate_open = (UnitRate(rate->OpenFeeAmtRatio, rate->OpenFeeVolRatio));
      rate_node->commission_rate_close = (UnitRate(rate->CloseFeeAmtRatio, rate->CloseFeeVolRatio));
      rate_node->commission_rate_close_today = (UnitRate(rate->CloseTodayFeeAmtRatio, rate->CloseTodayFeeVolRatio));
      auto product_class = m_service->m_md_helper->GetShmInstrumentField(
        std::string(rate_node->ExchangeID()) + "." + std::string(rate_node->InstrumentID()),
        &shm::ShmInstrument::product_class, true);
      if (product_class == md::ProductClass::kOption) {
        rate_node->commission_rate_exec = (UnitRate(rate->OptExecRatio, rate->OptExecRatioPerVol));
      } else {
        rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
      }
    });
  }
  SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
}

int X1UnitRate::RunOnce() {
  return 0;
}

