 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "x1_convert.h"
#include <cassert>
#include <memory>
#include <string>
namespace fclib {
namespace future {
namespace x1 {
void ConvertToSfitDirection(Direction d, TX1FtdcBuySellTypeType* t) {
  if (d == Direction::kBuy) {
    *t = X1_FTDC_SPD_BUY;
  } else if (d == Direction::kSell) {
    *t = X1_FTDC_SPD_SELL;
  }
}

void ConvertToSfitOffsetFlag(Offset d, TX1FtdcOpenCloseTypeType* t) {
  if (d == Offset::kClose) {
    *t = X1_FTDC_SPD_CLOSE;
  } else if (d == Offset::kCloseToday) {
    *t = X1_FTDC_SPD_CLOSETODAY;
  } else if (d == Offset::kOpen) {
    *t = X1_FTDC_SPD_OPEN;
  }
}

void ConvertToSfitHedgeFlag(future::OrderHedgeFlag h, TX1FtdcSpeculatorType* t) {
  if (h == OrderHedgeFlag::kArbitrage)
    *t = X1_FTDC_SPD_ARBITRAGE;
  else if (h == OrderHedgeFlag::kHedge)
    *t = X1_FTDC_SPD_HEDGE;
  else if (h == OrderHedgeFlag::kSpeculation)
    *t = X1_FTDC_SPD_SPECULATOR;
}

void ConvertToSfitOrderField(const std::shared_ptr<InsertOrder> d, std::shared_ptr<CX1FtdcInsertOrderField> field) {
  strcpy_x(field->InstrumentID, d->instrument_id);
  field->InsertType = X1_FTDC_BASIC_ORDER;
  ConvertToSfitDirection(d->direction, &field->BuySellType);
  ConvertToSfitOffsetFlag(d->offset, &field->OpenCloseType);
  if (field->OrderType == X1_FTDC_LIMITORDER) {
    field->InsertPrice = d->limit_price;
  } else {
    field->InsertPrice = 0;
  }
  ConvertToSfitHedgeFlag(d->hedge_flag, &field->Speculator);
  field->OrderAmount = d->volume;
}

void ConvertToPriMatch(
  const std::shared_ptr<CX1FtdcRspMatchField> d, std::shared_ptr<CX1FtdcRspPriMatchInfoField> field) {
  strcpy_x(field->MatchID, d->MatchedID);
  strcpy_x(field->OrderSysID, d->OrderSysID);
  strcpy_x(field->AccountID, d->AccountID);
  strcpy_x(field->MatchedTime, d->MatchedTime);
  field->BuySellType = d->BuySellType;
  strcpy_x(field->ExchangeID, d->ExchangeID);
  strcpy_x(field->InstrumentID, d->InstrumentID);
  field->OpenCloseType = d->OpenClose;
  field->LocalOrderID = d->LocalOrderID;
  field->MatchedPrice = d->MatchedPrice;
  field->MatchedAmount = d->MatchedAmount;
  field->Fee = d->Fee;
}

std::string ToFclibOrderId(const TX1FtdcLocalOrderIDType order_ref, const TX1FtdcSessionIDType session_id) {
  return std::to_string(order_ref) + "|" + std::to_string(session_id);
}

Direction ConvertFromSfitDirection(const TX1FtdcBuySellTypeType* t) {
  if (*t == X1_FTDC_SPD_BUY)
    return Direction::kBuy;
  if (*t == X1_FTDC_SPD_SELL)
    return Direction::kSell;
  return Direction::kInvalid;
}

Offset ConvertFromSfitOffset(const TX1FtdcOpenCloseTypeType t) {
  if (t == X1_FTDC_SPD_OPEN)
    return Offset::kOpen;
  if (t == X1_FTDC_SPD_CLOSETODAY)
    return Offset::kCloseToday;
  return Offset::kClose;
}

OrderHedgeFlag ConvertFromSfitHedgeFlag(const TX1FtdcSpeculatorType* t) {
  if (*t == X1_FTDC_SPD_SPECULATOR)
    return OrderHedgeFlag::kSpeculation;
  if (*t == X1_FTDC_SPD_ARBITRAGE)
    return OrderHedgeFlag::kArbitrage;
  if (*t == X1_FTDC_SPD_HEDGE)
    return OrderHedgeFlag::kHedge;
  return OrderHedgeFlag::kSpeculation;
}

void ConvertOrder(const TX1FtdcOrderTypeType* t, const TX1FtdcOrderPropertyType* p, std::shared_ptr<Order> order) {
  if (*t == X1_FTDC_LIMITORDER) {
    order->price_type = PriceType::kLimit;
    if (*p == X1_FTDC_SP_FAK) {
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kIoc;
    } else if (*p == X1_FTDC_SP_FOK) {
      order->volume_condition = OrderVolumeCondition::kAll;
      order->time_condition = OrderTimeCondition::kIoc;
    } else if (*p == X1_FTDC_SP_NON) {  // 无订单属性
      order->volume_condition = future::OrderVolumeCondition::kAny;
      order->time_condition = future::OrderTimeCondition::kGfd;
    } else if (*p == X1_FTDC_SP_GIS) {
      order->volume_condition = future::OrderVolumeCondition::kAny;
      order->time_condition = future::OrderTimeCondition::kGfs;
    }
  } else if (*t == X1_FTDC_MKORDER) {
    if (*p == X1_FTDC_SP_ANYPRICE) {
      order->price_type = PriceType::kAny;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kIoc;
    } else if (*p == X1_FTDC_SP_FIVELEVELPRICE) {
      order->price_type = PriceType::kFiveLevel;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kIoc;
    } else if (*p == X1_FTDC_SP_BESTPRICE) {
      order->price_type = PriceType::kBest;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kIoc;
    } else if (*p == X1_FTDC_SP_NON) {
      order->price_type = PriceType::kAny;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kGfd;
    } else if (*p == X1_FTDC_SP_FAK) {  // X1 里, 郑商所的市价是 FAK
      order->price_type = PriceType::kAny;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->time_condition = OrderTimeCondition::kIoc;
    }
  } else if (*t == X1_FTDC_ARBITRAGE) {
    order->price_type = PriceType::kLimit;
    order->volume_condition = OrderVolumeCondition::kAny;
    order->time_condition = OrderTimeCondition::kGfd;
  } else if (*t == X1_FTDC_EXTENSION) {
    order->is_swap_order = true;
    order->price_type = PriceType::kLimit;
    order->volume_condition = OrderVolumeCondition::kAny;
    order->time_condition = OrderTimeCondition::kGfd;
  } else if (*t == 0) {  // 错单
    order->price_type = PriceType::kLimit;
    order->volume_condition = OrderVolumeCondition::kAny;
    order->time_condition = OrderTimeCondition::kGfd;
  }
}

OrderStatus ConvertFromSfitOrderStatus(const TX1FtdcOrderAnswerStatusType* t) {
  if (*t == X1_FTDC_SPD_IN_QUEUE || *t == X1_FTDC_SPD_PARTIAL || *t == X1_FTDC_SPD_IN_CANCELING
    || *t == X1_FTDC_SPD_PLACED || *t == X1_FTDC_SPD_TRIGGERED) {
    return OrderStatus::kAlive;
  }
  return OrderStatus::kDead;
}

void ConvertToSfitExecAction(future::ExecActionType d, TX1FtdcOptExecAbandType& t) {
  if (d == future::ExecActionType::kExec) {
    t = X1_FTDC_SPD_EXECUTE;
  } else if (d == future::ExecActionType::kAbandon) {
    t = X1_FTDC_SPD_ABAND;
  }
}

Offset ConvertFromSfitOffset(const char t) {
  if (t == X1_FTDC_SPD_OPEN)
    return Offset::kOpen;
  if (t == X1_FTDC_SPD_CLOSETODAY)
    return Offset::kCloseToday;
  return Offset::kClose;
}

future::ExecActionType ConvertFromSfitExecAction(const TX1FtdcOptExecAbandType& t) {
  if (t == X1_FTDC_SPD_EXECUTE) {
    return future::ExecActionType::kExec;
  } else {
    return future::ExecActionType::kAbandon;
  }
}

void ConvertCancelOrderToOrder(CX1FtdcRspPriCancelOrderField* cancel_order, CX1FtdcRspPriOrderField* order) {
  order->LocalOrderID = cancel_order->LocalOrderID;
  strcpy_x(order->OrderSysID, cancel_order->OrderSysID);
  strcpy_x(order->InstrumentID, cancel_order->InstrumentID);
  order->InsertPrice = cancel_order->InsertPrice;
  order->BuySellType = cancel_order->BuySellType;
  order->OpenCloseType = cancel_order->OpenCloseType;
  order->CancelAmount = cancel_order->CancelAmount;
  order->X1OrderID = cancel_order->X1OrderID;
  order->Speculator = cancel_order->Speculator;
  strcpy_x(order->ExchangeID, cancel_order->ExchangeID);
  strcpy_x(order->SuspendTime, cancel_order->CanceledTime);  // 暂时先用这个时间表示撤单时间
  order->SessionID = cancel_order->SessionID;
  order->OrderStatus = cancel_order->OrderStatus;
  order->InstrumentType = cancel_order->InstrumentType;
  strcpy_x(order->AccountID, cancel_order->AccountID);
  order->OrderAmount = cancel_order->OrderAmount;
  strcpy_x(order->CustomCategory, cancel_order->CustomCategory);
  order->ProfitLossPrice = cancel_order->ProfitLossPrice;
  order->MinMatchAmount = cancel_order->MinMatchAmount;
  order->InsertType = cancel_order->InsertType;
  strcpy_x(order->ClientID, cancel_order->ClientID);
  order->ErrorID = cancel_order->ErrorID;
  strcpy_x(order->StatusMsg, cancel_order->StatusMsg);
  order->OrderProperty = cancel_order->OrderProperty;
  order->PriFlowNo = cancel_order->PriFlowNo;
}

