X1UnitExecOrder::X1UnitExecOrder(X1ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("exec_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqOptExecOrAband(command);
  });
  m_service->RegisterCommandProcessor(CancelExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelOptExecOrAband(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOptExecAband, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOptExecAband(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOptExecAband, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOptExecAband(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspCancelOptExecAband, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCancelOptExecAband(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCancelOptExecAband, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnCancelOptExecAband(msg);
  });
}

void X1UnitExecOrder::ReqOptExecOrAband(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_service->m_command_manager->Update(command));
  CX1FtdcOptExecOrAbandField field;
  memset(&field, 0, sizeof(field));
  field.LocalOrderID = req->exec_order_ref > 0 ? req->exec_order_ref : (m_service->GenerateOrderRef()) * 100;
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.AccountID, m_service->m_req_login->user_id);
  ConvertToSfitOffsetFlag(req->offset, &field.OpenCloseType);
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.Speculator);
  ConvertToSfitExecAction(req->exec_action_type, field.OptExecAbandType);
  field.RequestID = m_service->GenerateRequestID();
  field.OrderAmount = req->volume;
  int ret = m_service->m_api->ReqOptExecOrAband(&field);
  LogReq(m_logger, "ReqInsertExecOrder", &field, field.RequestID, ret);
  m_service->SetReqResponse(command, field.RequestID, ret);
}

void X1UnitExecOrder::OnRspOptExecAband(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  }
}

void X1UnitExecOrder::OnRtnOptExecAband(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto pExecOrder = std::static_pointer_cast<CX1FtdcRtnOptExecOrAbandField>(msg->pMainField);
    auto target_execorder = std::make_shared<ExecOrder>();
    target_execorder->instrument_id = pExecOrder->InstrumentID;
    target_execorder->exchange_id = pExecOrder->ExchangeID;
    target_execorder->investor_id = pExecOrder->AccountID;
    target_execorder->volume = pExecOrder->OrderAmount;
    target_execorder->direction = PosiDirection::kLong;
    target_execorder->offsetflag = ConvertFromSfitOffset(pExecOrder->OpenCloseType);
    target_execorder->hedge_flag = ConvertFromSfitHedgeFlag(&pExecOrder->Speculator);
    target_execorder->exchange_exec_order_sysid = GbkToUtf8(pExecOrder->OrderSysID);
    target_execorder->exec_action_type = ConvertFromSfitExecAction(pExecOrder->OptExecAbandType);
    target_execorder->exec_close_flag = ExecOrderCloseFlag::kNotToClose;
    target_execorder->status_msg = GbkToUtf8(pExecOrder->StatusMsg);
    target_execorder->exec_order_ref = std::to_string(pExecOrder->LocalOrderID);
    target_execorder->session_id = pExecOrder->SessionID;
    target_execorder->insert_date_time = StringToEpochNano(m_service->m_trading_day.c_str(), pExecOrder->CommTime);
    target_execorder->user_key = m_service->m_req_login->user_key;
    target_execorder->exec_result = ConvertFromSfitOrderStatus(&pExecOrder->OrderStatus) == OrderStatus::kAlive
      ? ExecOrderResultType::kNoExec
      : ExecOrderResultType::kCanceled;
    target_execorder->exec_order_id = ToFclibOrderId(pExecOrder->LocalOrderID, pExecOrder->SessionID);
    m_service->m_node_db->ReplaceRecord<ExecOrder>(target_execorder);
  }
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req);
}

void X1UnitExecOrder::ReqCancelOptExecOrAband(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_service->m_command_manager->Update(command));
  auto origin = m_service->m_node_db->GetNode<ExecOrder>(m_service->m_req_login->user_key + "|" + req->exec_order_id);
  if (origin == nullptr) {
    SetCommandFinished(req, 1, u8"fclib: 行权报单委托不存在");
    return;
  }
  CX1FtdcCancelOptExecAbandField field;
  memset(&field, 0, sizeof(field));
  field.RequestID = m_service->GenerateRequestID();
  strcpy_x(field.AccountID, origin->Latest()->investor_id);
  strcpy_x(field.InstrumentID, origin->Latest()->instrument_id);
  strcpy_x(field.OrderSysID, Utf8ToGbk(origin->Latest()->exchange_exec_order_sysid));
  int ret = m_service->m_api->ReqCancelOptExecOrAband(&field);
  LogReq(m_logger, "ReqCancelExecOrder", &field, field.RequestID, ret);
  m_service->SetReqResponse(command, field.RequestID, ret);
}

void X1UnitExecOrder::OnRspCancelOptExecAband(std::shared_ptr<SpiMessage> msg) {
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  }
}

void X1UnitExecOrder::OnRtnCancelOptExecAband(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto pExecOrder = std::static_pointer_cast<CX1FtdcRtnCancelOptExecAbandField>(msg->pMainField);
    auto target_execorder = std::make_shared<ExecOrder>();
    target_execorder->instrument_id = pExecOrder->InstrumentID;
    target_execorder->exchange_id = pExecOrder->ExchangeID;
    target_execorder->investor_id = pExecOrder->AccountID;
    target_execorder->volume = pExecOrder->OrderAmount;
    target_execorder->direction = PosiDirection::kLong;
    target_execorder->offsetflag = ConvertFromSfitOffset(pExecOrder->OpenCloseType);
    target_execorder->hedge_flag = ConvertFromSfitHedgeFlag(&pExecOrder->Speculator);
    target_execorder->exchange_exec_order_sysid = GbkToUtf8(pExecOrder->OrderSysID);
    target_execorder->exec_action_type = ConvertFromSfitExecAction(pExecOrder->OptExecAbandType);
    target_execorder->exec_close_flag = ExecOrderCloseFlag::kNotToClose;
    target_execorder->status_msg = GbkToUtf8(pExecOrder->StatusMsg);
    target_execorder->exec_order_ref = std::to_string(pExecOrder->LocalOrderID);
    target_execorder->session_id = pExecOrder->SessionID;
    target_execorder->insert_date_time = StringToEpochNano(m_service->m_trading_day.c_str(), pExecOrder->CanceledTime);
    target_execorder->user_key = m_service->m_req_login->user_key;
    target_execorder->exec_result = ExecOrderResultType::kCanceled;
    target_execorder->exec_order_id = ToFclibOrderId(pExecOrder->LocalOrderID, pExecOrder->SessionID);
    m_service->m_node_db->ReplaceRecord<ExecOrder>(target_execorder);
  }
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, ErrorCodeToString(msg->RspInfo.ErrorID));
  }
}

