// 断线重连后获取私有流编号
unsigned int GetX1PrivateFLowNo(const std::filesystem::path& path, const std::string& user_id) {
  unsigned int ret = 0;
  if (path.empty())
    return ret;
  std::string dat_file = path.generic_string() + "\\private_flow_" + user_id + ".dat";
  std::ifstream file(dat_file);
  if (!file)
    return ret;
  std::string line;
  while (getline(file, line)) {
    if (std::all_of(line.begin(), line.end(), ::isdigit)) {
      ret = std::stoul(line);
      break;
    }
  }
  return ret;
}

