int X1ServiceImpl::BuildApi(bool subscribe_topic /*= true*/) {
  if (!m_req_login) {
    m_logger.With("ret", -1).Info("init");
    return -1;
  }
  if (m_api) {
    m_api->Release();
    m_api = nullptr;
    if (m_spi) {
      delete m_spi;
      m_spi = nullptr;
    }
  }
  int ret = -1;
  if (m_flow_dir.empty()) {
    std::error_code ec;
    auto now = std::chrono::steady_clock::now();
    static int index = 0;
    std::string sztime = "fclib_x1_" + m_req_login->user_id + "_"
      + std::to_string(std::chrono::time_point_cast<std::chrono::milliseconds>(now).time_since_epoch().count())
      + std::to_string(++index);
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime);
    std::filesystem::create_directories(m_flow_dir, ec);
  }
  m_path = std::filesystem::current_path();
  if (!m_options.run_directory.empty())
    m_path = std::filesystem::u8path(m_options.run_directory);
  std::filesystem::current_path(m_flow_dir);
  m_api = ThostApiCreator();
  if (m_options.xone_api_test_mode)
    m_api->SetRsaPubKey(1);
  m_spi = new X1SpiHandler(m_ioc, m_logger, this);
  for (const auto& f : m_req_login->broker.trading_fronts) {
    auto pos = f.find(';');
    if (pos != std::string::npos) {
      ret = m_api->Init(f.substr(0, pos).c_str(), f.substr(pos + 1).c_str(), m_spi);
    } else {
      ret = m_api->Init(f.c_str(), f.c_str(), m_spi);
    }
  }
  m_api->SetLogLevel(3, 3);
  if (subscribe_topic) {
    if (m_trading_day.empty()) {
      // 第一次登录选1
      m_logger.With("priflow_req_flag", 1).Info("SubscribePrivateTopic");
      m_api->SubscribePrivateTopic(1, 0);
    } else {
      auto pri_no = GetX1PrivateFLowNo(m_flow_dir, m_req_login->user_id);
      if (pri_no <= 0) {
        //  断线重连无序号选2
        m_logger.With("priflow_req_flag", 2).Info("SubscribePrivateTopic");
        m_api->SubscribePrivateTopic(2, 0);
      } else {
        // 断线重连有序号选3
        m_logger.With("priflow_req_flag", 3)
          .With("priflow_no", static_cast<int64_t>(pri_no))
          .Info("SubscribePrivateTopic");
        m_api->SubscribePrivateTopic(3, pri_no);
      }
    }
  }
  m_logger.With("ret", ret).Info("init");
  return ret;
}

int X1ServiceImpl::GenerateRequestID() {
  static int request_id = 0;
  return request_id++;
}

void X1ServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  m_query_planner.ProcessSpiMsg(spi_msg);
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

void X1ServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, int request_id, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, std::to_string(request_id));
}

