int LocalSimCalculator::CalcRequestID() {
  static int request_id = 0;
  return ++request_id;
}

bool LocalSimCalculator::IsMarketOrder(std::shared_ptr<const Order> order) {
  return order->price_type == PriceType::kAny;
}

md::EpochNano LocalSimCalculator::CalcTradingDayEnd(const md::EpochNano& timestamp) {
  auto begin_mark = 631123200000000000;
  auto days = (timestamp - begin_mark) / 86400000000000;
  if ((timestamp - begin_mark) % 86400000000000 >= 64800000000000) {
    days++;
  }
  if (auto week_day = days % 7; week_day >= 5) {
    days = days + 7 - week_day;
  }
  return begin_mark + days * 86400000000000 + 64799999999999;
}

void LocalSimCalculator::UpdateAccountField(std::shared_ptr<Account> account) {
  account->balance = account->pre_balance + account->deposit - account->withdraw + account->close_profit
    + account->position_profit - account->commission + account->premium + account->option_market_value;
  account->client_equity = account->balance - account->option_market_value;
  account->available = account->client_equity - account->margin - account->frozen_margin - account->frozen_commission
    - account->frozen_premium;
}

void LocalSimCalculator::UpdatePositionField(std::shared_ptr<Position> position, std::shared_ptr<const Order> order) {
  position->user_key = order->user_key;
  position->exchange_id = order->exchange_id;
  position->instrument_id = order->instrument_id;
  position->investor_id = order->user_id;
  position->ins_pointer = order->ins_pointer;
}

void LocalSimCalculator::AccountSettle(std::shared_ptr<Account> account) {
  account->pre_balance = account->balance - account->option_market_value;
  account->frozen_margin = 0.0;
  account->frozen_commission = 0.0;
  account->commission = 0.0;
  account->frozen_premium = 0.0;
  account->premium = 0.0;
  account->withdraw = 0.0;
  account->deposit = 0.0;
  account->close_profit = 0.0;
  account->position_profit = 0.0;
  account->client_equity = account->pre_balance;
  account->risk_ratio = account->margin / account->balance;
  account->available = account->client_equity - account->margin;
  account->balance = account->pre_balance + account->deposit - account->withdraw + account->close_profit
    + account->position_profit - account->commission + account->premium + account->option_market_value;
}

void LocalSimCalculator::SubPositionSettle(SubPosition* subpos, double last_price) {
  subpos->volume_today_frozen = 0;
  subpos->volume_his_frozen = 0;
  subpos->volume_yesterday = subpos->volume_today;
  subpos->volume_his = subpos->Volume();
  subpos->volume_today = 0;
  subpos->position_price = isnan(last_price) ? 0.0 : last_price;
  subpos->position_profit = 0.0;
  subpos->commission = 0.0;
  subpos->premium = 0.0;
  subpos->his_position_details.splice(subpos->his_position_details.end(), subpos->today_position_details);
}

double LocalSimCalculator::CalcFutureMarginRate(
