double LocalSimCalculator::CalcOptionMarginRate(
  const std::optional<shm::ShmInstrument>& ins, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!ins.has_value())
    return NAN;
  if (ins->product_class != md::ProductClass::kOption)
    return NAN;
  if (isnan(ins->strike_price) || isnan(ins->last_price))
    return NAN;
  auto underlying_ins = helper->GetShmInstrument(ins->underlying_symbol.data());
  if (!underlying_ins.has_value() || isnan(underlying_ins->last_price))
    return NAN;
  // 期权保证金计算公式参考深交所文档
  // http://docs.static.szse.cn/www/disclosure/notice/general/W020191207433397366259.pdf
  if (ins->option_class == md::OptionClass::kCall) {
    // 认购期权义务仓开仓保证金＝[合约最新价 + Max（12% × 合约标的最新价 - 认购期权虚值， 7% × 合约标的最新价）] ×
    // 合约单位
    // 认购期权虚值＝Max（行权价 - 合约标的最新价，0）
    auto out_value = std::max(ins->strike_price - underlying_ins->last_price, 0.0);
    return (ins->last_price
             + std::max(0.12 * underlying_ins->last_price - out_value, 0.07 * underlying_ins->last_price))
      * ins->volume_multiple;
  } else {
    // 认沽期权义务仓开仓保证金＝Min[合约最新价+ Max（12% × 合约标的最新价 - 认沽期权虚值，7% × 行权价），行权价] ×
    // 合约单位
    // 认沽期权虚值＝Max（合约标的最新价 - 行权价，0）
    auto out_value = std::max(underlying_ins->last_price - ins->strike_price, 0.0);
    return std::min(ins->last_price + std::max(0.12 * underlying_ins->last_price - out_value, 0.07 * ins->strike_price),
             ins->strike_price)
      * ins->volume_multiple;
  }
}

double LocalSimCalculator::CalcOptionMarginRate(
  std::shared_ptr<md::InstrumentNode> node, std::shared_ptr<TqApiNodeDb> node_db) {
  if (!node)
    return NAN;
  if (node->Latest()->ProductClass() != md::ProductClass::kOption)
    return NAN;

  const auto& last_price = node->Latest()->last_price;
  const auto& strike_price = node->Latest()->strike_price;
  const auto volume_multiple = node->Latest()->VolumeMultiple();
  if (isnan(strike_price) || isnan(last_price))
    return NAN;

  const auto underlying_key = node->Latest()->instrument_base->underlying_pointer.Key();
  std::shared_ptr<md::InstrumentNode> underlying_node = node->Latest()->instrument_base->underlying_pointer;
  if (!underlying_node && !underlying_key.empty())
    underlying_node = node_db->GetNode<md::Instrument>(underlying_key);
  if (!underlying_node || isnan(underlying_node->Latest()->last_price))
    return NAN;

  const auto& underlying_last_price = underlying_node->Latest()->last_price;
  if (node->Latest()->option_class == md::OptionClass::kCall) {
    auto out_value = std::max(strike_price - underlying_last_price, 0.0);
    return (last_price + std::max(0.12 * underlying_last_price - out_value, 0.07 * underlying_last_price))
      * volume_multiple;
  } else {
    auto out_value = std::max(underlying_last_price - strike_price, 0.0);
    return std::min(last_price + std::max(0.12 * underlying_last_price - out_value, 0.07 * strike_price), strike_price)
      * volume_multiple;
  }
}

double LocalSimCalculator::CalcCommissionRate(const std::string& user_key, const std::optional<shm::ShmInstrument>& ins,
  const future::Offset& offset, std::shared_ptr<TqApiNodeDb> node_db) {
  if (!ins.has_value())
    return NAN;
  auto instrument_id = ins->instrument_id.data();
  auto rate_node = node_db->GetNode<Rate>(user_key + "|" + instrument_id);
  double rate = NAN;
  if (rate_node) {
    if (offset == future::Offset::kOpen) {
      rate = rate_node->Latest()->commission_rate_open.volume_rate;
    } else if (offset == future::Offset::kCloseToday) {
      rate = rate_node->Latest()->commission_rate_close_today.volume_rate;
    } else {
      rate = rate_node->Latest()->commission_rate_close.volume_rate;
    }
  }
  if (!isnan(rate))
    return rate;
  // 期权 quote 没有 commission 字段, 设为固定 10元 / 手
  if (ins->product_class == md::ProductClass::kOption)
    return 10.0;
  return ins->commission;
}

double LocalSimCalculator::CalcCommissionRate(const std::string& user_key, std::shared_ptr<md::InstrumentNode> node,
  const future::Offset& offset, std::shared_ptr<TqApiNodeDb> node_db) {
  if (!node)
    return NAN;
  auto instrument_id = node->Latest()->instrument_id.data();
  auto rate_node = node_db->GetNode<Rate>(user_key + "|" + instrument_id);
  double rate = NAN;
  if (rate_node) {
    if (offset == future::Offset::kOpen) {
      rate = rate_node->Latest()->commission_rate_open.volume_rate;
    } else if (offset == future::Offset::kCloseToday) {
      rate = rate_node->Latest()->commission_rate_close_today.volume_rate;
    } else {
      rate = rate_node->Latest()->commission_rate_close.volume_rate;
    }
  }
  if (!isnan(rate))
    return rate;
  if (node->Latest()->ProductClass() == md::ProductClass::kOption)
    return 10.0;
  return node->Latest()->instrument_base->commission;
}

double LocalSimCalculator::CalcPremium(
  std::shared_ptr<future::Trade> trade, double volume_multiple, const md::ProductClass& product_class) {
  if (product_class == md::ProductClass::kOption) {
    auto premium = trade->price * trade->volume * volume_multiple;
    return (trade->direction == Direction::kSell) ? premium : -premium;
  }
  return 0.0;
}

SubPosition* LocalSimCalculator::GetSubPos(std::shared_ptr<const Order> order, std::shared_ptr<Position> pos) {
  if ((order->direction == Direction::kBuy) == (order->offset == Offset::kOpen)) {
    if (order->hedge_flag == OrderHedgeFlag::kSpeculation)
      return &pos->subpos_long_spec;
    return &pos->subpos_long_other;
  }
  if (order->hedge_flag == OrderHedgeFlag::kSpeculation)
    return &pos->subpos_short_spec;
  return &pos->subpos_short_other;
}

const SubPosition* LocalSimCalculator::GetSubPos(
  std::shared_ptr<const Order> order, std::shared_ptr<const Position> pos) {
  return GetSubPos(order, std::const_pointer_cast<Position>(pos));
}

int32_t LocalSimCalculator::CalcAvailCloseVolume(
  std::shared_ptr<future::Order> order, std::shared_ptr<future::PositionNode> position_node) {
  auto subpos = GetSubPos(order, position_node->Latest());
  if (order->exchange_id == "SHFE" || order->exchange_id == "INE") {
    if (order->offset == Offset::kCloseToday)
      return subpos->volume_today - subpos->volume_today_frozen;
    if (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday)
      return subpos->volume_his - subpos->volume_his_frozen;
  }
  if (order->exchange_id == "CZCE") {
    auto position = position_node->Latest();
    return (order->direction == future::Direction::kBuy) ? (position->VolumeShort() - position->VolumeShortFrozen())
                                                         : (position->VolumeLong() - position->VolumeLongFrozen());
  }
  return subpos->Volume() - subpos->VolumeFrozen();
}

double LocalSimCalculator::CalcTradePrice(const std::string& symbol, const future::Direction& direction,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (helper) {
    auto ins = helper->GetShmInstrument(symbol);
    if (!ins.has_value())
      return NAN;
    return direction == Direction::kBuy ? ins->ask_price1 : ins->bid_price1;
  }
  auto ins = node_db->GetNode<md::Instrument>(symbol);
  if (nullptr == ins)
    return NAN;
  return direction == Direction::kBuy ? ins->Latest()->GetAskPrice() : ins->Latest()->GetBidPrice();
}

bool LocalSimCalculator::IsOrderTraded(double trade_price, std::shared_ptr<future::OrderNode> order_node) {
  // 无行情, 不撮合
  if (isnan(trade_price))
    return false;
  if (order_node->Latest()->direction == Direction::kInvalid)
    return false;
  if (IsMarketOrder(order_node->Latest()))
    return true;
  if (order_node->Latest()->direction == Direction::kBuy && trade_price > order_node->Latest()->limit_price)
    return false;
  if (order_node->Latest()->direction == Direction::kSell && trade_price < order_node->Latest()->limit_price)
    return false;
  return true;
}

std::shared_ptr<future::Order> LocalSimCalculator::CreateOrder(
  const std::string& user_id, std::shared_ptr<future::InsertOrder> req, std::shared_ptr<TqApiNodeDb> node_db) {
  // 这是一个特殊的测试机制，用于模拟某些特殊情况，例如需要模拟FAK部分成交的情况，则可以事先ReplaceReocrd进Db一个Order，
  // CreateOrder时发现这个单已存在，同时unit_id = -1(测试中用作特殊单标志位)，则直接返回这个单
  auto node = node_db->GetNode<Order>(req->user_key + "|" + req->order_id);
  if (node && node->Latest()->unit_id == -1)
    return std::const_pointer_cast<Order>(node->Latest());

  auto target = std::make_shared<future::Order>();
  target->user_key = req->user_key;
  target->user_id = user_id;
  target->investor_id = user_id;
  target->order_id = req->order_id;
  target->exchange_id = req->exchange_id;
  target->exchange_order_id = "";
  target->instrument_id = req->instrument_id;
  target->direction = req->direction;
  target->price_type = req->price_type;
  target->limit_price = req->limit_price;
  target->offset = req->offset;
  target->hedge_flag = req->hedge_flag;
  target->time_condition = req->time_condition;
  target->volume_condition = req->volume_condition;
  target->min_volume = req->min_volume;
  target->volume_orign = req->volume;
  target->volume_left = req->volume;
  target->request_id = req->user_key;
  target->force_close_reason = future::ForceCloseReason::kNotForceClose;
  target->insert_date_time = NowAsEpochNano();
  target->ins_pointer = node_db->GetNode<md::Instrument>(target->Symbol());
  target->unit_id = req->unit_id;
  target->status = future::OrderStatus::kAlive;
  target->status_msg = u8"下单成功";
  target->_frozen_margin = 0.0;
  target->_frozen_premium = 0.0;
  target->_frozen_commission = 0.0;
  target->send_date_time = NowAsEpochNano();
  target->receive_date_time = NowAsEpochNano();
  return target;
}

std::shared_ptr<Trade> LocalSimCalculator::CreateTrade(int64_t& last_trade_id, std::shared_ptr<const Order> order,
  double trade_price, std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::MdServiceShmHelper> helper) {
  std::string exchange_trade_id = std::to_string(last_trade_id++);
  std::string trade_key = exchange_trade_id + "|" + order->exchange_order_id;
  auto trade = std::make_shared<Trade>();
  trade->user_key = order->user_key;
  trade->direction = order->direction;
  trade->exchange_id = order->exchange_id;
  trade->exchange_order_id = order->exchange_order_id;
  trade->exchange_trade_id = trade_key;
  trade->hedge_flag = order->hedge_flag;
  trade->instrument_id = order->instrument_id;
  trade->investor_id = order->investor_id;
  trade->offset = order->offset;
  trade->order_id = order->order_id;
  trade->user_id = order->user_id;
  trade->price = trade_price;
  trade->volume = order->volume_left;
  trade->unit_id = order->unit_id;
  trade->order_pointer = node_db->GetNode<Order>(order->GetKey());
  trade->trade_date_time = NowAsEpochNano();
  trade->ins_pointer = node_db->GetNode<md::Instrument>(trade->Symbol());
  trade->order_pointer = node_db->GetNode<Order>(order->GetKey());
  if (helper) {
    auto trade_ins = helper->GetShmInstrument(trade->Symbol());
    trade->commission = CalcCommissionRate(trade->user_key, trade_ins, trade->offset, node_db) * order->volume_left;
  } else {
    static int seq_no = 0;
    trade->seq_no = ++seq_no;
    trade->commission =
      CalcCommissionRate(trade->user_key, trade->ins_pointer, trade->offset, node_db) * order->volume_left;
  }
  return trade;
}

void LocalSimCalculator::UpdateOrderByTrade(
  std::shared_ptr<TradeNode> trade_node, const std::optional<shm::ShmInstrument>& ins, std::shared_ptr<Order> o) {
  NodePointer<Trade> trade_pointer(trade_node);
  o->trade_set.insert(trade_pointer);
  auto trade = std::static_pointer_cast<const TradeBase>(trade_node->Latest());
  auto order = std::static_pointer_cast<OrderBase>(o);
  if (nullptr == trade || !ins.has_value())
    return;
  // 更新委托最后成交时间
  if (trade->trade_date_time > order->last_trade_date_time)
    order->last_trade_date_time = trade->trade_date_time;
  // 更新成交均价和成交手数
  bool is_combine =
    (ins->product_class == md::ProductClass::kCombine || ins->product_class == md::ProductClass::kCusCombine);
  if (!is_combine) {
    if (trade->Symbol() != std::string(ins->symbol.data()) || order->trade_total_volume + trade->volume <= 0)
      return;
    if (isnan(order->trade_price))
      order->trade_price = 0.0;
    order->trade_price = (order->trade_price * order->trade_total_volume + trade->price * trade->volume)
      / (order->trade_total_volume + trade->volume);
    order->trade_total_volume += trade->volume;
    return;
  }
  auto leg1_symbol = ins->leg1_symbol;
  auto leg2_symbol = ins->leg2_symbol;
  if (trade->Symbol() != std::string(leg1_symbol.data()) && trade->Symbol() != std::string(leg2_symbol.data()))
    return;
  if (trade->Symbol() == std::string(leg1_symbol.data())) {
    if (isnan(order->_leg1_trade_price))
      order->_leg1_trade_price = 0.0;
    order->_leg1_trade_price =
      (order->_leg1_trade_price * order->_leg1_trade_total_volume + trade->price * trade->volume)
      / (order->_leg1_trade_total_volume + trade->volume);
    order->_leg1_trade_total_volume += trade->volume;
  } else {
    if (isnan(order->_leg2_trade_price))
      order->_leg2_trade_price = 0.0;
    order->_leg2_trade_price =
      (order->_leg2_trade_price * order->_leg2_trade_total_volume + trade->price * trade->volume)
      / (order->_leg2_trade_total_volume + trade->volume);
    order->_leg2_trade_total_volume += trade->volume;
  }
  order->trade_price = order->_leg1_trade_price - order->_leg2_trade_price;
  order->trade_total_volume = (std::min)(order->_leg1_trade_total_volume, order->_leg2_trade_total_volume);
}

