void LocalSimCalculator::UpdatePositionByOrder(std::shared_ptr<Position> position, std::shared_ptr<Order> order) {
  UpdatePositionField(position, order);
  SubPosition* subpos = GetSubPos(order, position);
  if (order->exchange_id == "SHFE" || order->exchange_id == "INE") {
    auto& volume = (order->offset == Offset::kCloseToday) ? subpos->volume_today_frozen : subpos->volume_his_frozen;
    volume += order->volume_orign;
    return;
  }
  if (position->exchange_id == "CZCE") {
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_spec : &position->subpos_short_spec;
    if (subpos->VolumeAvail() > order->volume_orign) {
      FrozenVolumeByOrder(subpos, order->volume_orign);
      return;
    }
    auto delta_vol = order->volume_orign - subpos->VolumeAvail();
    FrozenVolumeByOrder(subpos, subpos->VolumeAvail());
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_other : &position->subpos_short_other;
    FrozenVolumeByOrder(subpos, delta_vol);
    return;
  }
  FrozenVolumeByOrder(subpos, order->volume_orign);
}

void LocalSimCalculator::UpdatePositionByCancelOrder(
  std::shared_ptr<Position> position, std::shared_ptr<const Order> order) {
  UpdatePositionField(position, order);
  SubPosition* subpos = GetSubPos(order, position);
  if (order->exchange_id == "SHFE" || order->exchange_id == "INE") {
    auto& volume = (order->offset == Offset::kCloseToday) ? subpos->volume_today_frozen : subpos->volume_his_frozen;
    volume -= order->volume_orign;
    return;
  }
  if (order->exchange_id == "CZCE") {
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_other : &position->subpos_short_other;
    if (subpos->VolumeFrozen() > order->volume_orign) {
      UnFrozenVolumeByCancel(subpos, order->volume_orign);
      return;
    }
    auto delta_vol = order->volume_orign - subpos->VolumeFrozen();
    UnFrozenVolumeByCancel(subpos, subpos->VolumeFrozen());
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_spec : &position->subpos_short_spec;
    UnFrozenVolumeByCancel(subpos, delta_vol);
    return;
  }
  UnFrozenVolumeByCancel(subpos, order->volume_orign);
}

void LocalSimCalculator::UpdatePositionDetailByCloseTrade(std::list<std::shared_ptr<PositionDetail>>* details, int* vol,
  double volume_multiple, double pre_settlement, SubPosition* subpos, std::shared_ptr<Trade> trade,
  std::shared_ptr<const Order> order, bool is_his) {
  auto make_log = [=]() {
    auto close_log = std::make_shared<CloseLog>();
    close_log->hedge_flag = subpos->hedge_type;
    auto open_price = details->front()->open_price;
    auto close_price = trade->price;

    close_log->open_trading_day = details->front()->open_trading_day;
    close_log->open_date_time = details->front()->open_date_time;
    close_log->open_exchange_trade_id = details->front()->open_exchange_trade_id;
    close_log->open_exchange_order_id = details->front()->open_exchange_order_id;
    close_log->open_price = open_price;
    close_log->close_profit_by_open =
      (order->direction == Direction::kBuy ? -1 : 1) * volume_multiple * (close_price - open_price);
    open_price = is_his ? pre_settlement : details->front()->open_price;
    close_log->close_profit =
      (order->direction == Direction::kBuy ? -1 : 1) * volume_multiple * (close_price - open_price);
    return close_log;
  };
  while (!details->empty() && *vol > 0) {
    if (details->front()->volume > *vol) {
      auto log = make_log();
      log->close_profit *= *vol;
      log->close_profit_by_open *= *vol;
      log->volume = *vol;
      trade->close_logs.emplace_back(log);
      // 复制一个新的指针，而不是在原来的基础上修改
      std::shared_ptr<PositionDetail> new_front = std::make_shared<PositionDetail>(*details->front());
      new_front->volume -= *vol;
      details->front() = new_front;
      // details->front()->volume -= *vol;
      *vol = 0;
    } else {
      auto log = make_log();
      log->close_profit *= details->front()->volume;
      log->close_profit_by_open *= details->front()->volume;
      log->volume = details->front()->volume;
      trade->close_logs.emplace_back(log);
      *vol -= details->front()->volume;
      details->pop_front();
    }
  }
}

void LocalSimCalculator::UpdatePositionByTrade(std::shared_ptr<Position> position, std::shared_ptr<Trade> trade,
  double volume_multiple, double pre_settlement, const md::ProductClass& product_class) {
  auto order = trade->order_pointer->Latest();
  auto volume = trade->volume;
  UpdatePositionField(position, order);
  auto subpos = GetSubPos(order, position);
  // 郑商所平仓涉及跨越投机保值,所以单独处理
  if (order->exchange_id != "CZCE" || order->offset == Offset::kOpen) {
    subpos->commission += trade->commission;
    subpos->premium += CalcPremium(trade, volume_multiple, product_class);
  }

  // 开仓解冻并更新占用保证金、开仓均价、持仓均价、持仓数
  if (order->offset == Offset::kOpen) {
    subpos->open_price = (subpos->open_price * subpos->Volume() + trade->price * volume) / (subpos->Volume() + volume);
    subpos->position_price =
      (subpos->position_price * subpos->Volume() + trade->price * volume) / (subpos->Volume() + volume);
    subpos->volume_today += volume;
    auto pos_details = std::make_shared<PositionDetail>();
    auto time_s = EpochNanoToLocalDateTime(trade->trade_date_time, 8);
    pos_details->open_trading_day =
      (time_s.date_time.tm_year + 1900) * 10000 + (time_s.date_time.tm_mon) * 100 + time_s.date_time.tm_mday;
    pos_details->open_date_time = trade->trade_date_time;
    pos_details->open_price = trade->price;
    pos_details->open_exchange_trade_id = trade->exchange_trade_id;
    pos_details->open_exchange_order_id = trade->exchange_order_id;
    pos_details->volume = trade->volume;
    subpos->today_position_details.emplace_back(pos_details);
    return;
  }
  if (order->exchange_id == "SHFE" || order->exchange_id == "INE") {
    if (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday) {
      subpos->volume_his_frozen -= volume;
      subpos->volume_his -= volume;
      // 明细平昨;
      UpdatePositionDetailByCloseTrade(
        &subpos->his_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 1);
      return;
    }
    if (order->offset == Offset::kCloseToday) {
      subpos->volume_today_frozen -= volume;
      subpos->volume_today -= volume;
      // 明细平今
      UpdatePositionDetailByCloseTrade(
        &subpos->today_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 0);
      return;
    }
    return;
  }
  if (order->exchange_id == "CZCE") {
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_spec : &position->subpos_short_spec;
    if (subpos->VolumeFrozen() > volume) {
      subpos->commission += trade->commission;
      subpos->premium += CalcPremium(trade, volume_multiple, product_class);
      UnFrozenVolumeByTrade(subpos, volume);
      // 平仓成交调整持仓明细
      UpdatePositionDetailByCloseTrade(
        &subpos->his_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 1);
      UpdatePositionDetailByCloseTrade(
        &subpos->today_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 0);
      return;
    }
    auto delta_vol = volume - subpos->VolumeFrozen();
    subpos->commission += trade->commission / volume * subpos->VolumeFrozen();
    subpos->premium += CalcPremium(trade, volume_multiple, product_class) / volume * subpos->VolumeFrozen();
    UnFrozenVolumeByTrade(subpos, subpos->VolumeFrozen());
    // 先投机
    UpdatePositionDetailByCloseTrade(
      &subpos->his_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 1);
    UpdatePositionDetailByCloseTrade(
      &subpos->today_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 0);
    // 再保值
    subpos = (order->direction == Direction::kSell) ? &position->subpos_long_other : &position->subpos_short_other;
    subpos->commission += trade->commission / volume * delta_vol;
    subpos->premium += CalcPremium(trade, volume_multiple, product_class) / volume * delta_vol;
    UnFrozenVolumeByTrade(subpos, delta_vol);
    UpdatePositionDetailByCloseTrade(
      &subpos->his_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 1);
    UpdatePositionDetailByCloseTrade(
      &subpos->today_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 0);
    return;
  }
  UnFrozenVolumeByTrade(subpos, volume);
  // 先平昨再平今
  UpdatePositionDetailByCloseTrade(
    &subpos->his_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 1);
  UpdatePositionDetailByCloseTrade(
    &subpos->today_position_details, &volume, volume_multiple, pre_settlement, subpos, trade, order, 0);
}

void LocalSimCalculator::UpdateAccountByCancelOrder(
  std::shared_ptr<Account> account, std::shared_ptr<const Order> order) {
  // 撤开仓单解冻保证金
  if (order->offset == Offset::kOpen) {
    account->frozen_margin -= order->_frozen_margin;
    account->frozen_premium -= order->_frozen_premium;
  }
  // 解冻手续费
  account->frozen_commission -= order->_frozen_commission;
  UpdateAccountField(account);
}

void LocalSimCalculator::UpdateAccountByTrade(std::shared_ptr<Account> account, std::shared_ptr<Trade> trade,
  const SubPosition& subpos, double volume_multiple, const md::ProductClass& product_class) {
  auto order = trade->order_pointer->Latest();
  auto volume = trade->volume;
  // 开仓解冻并更新占用保证金
  if (order->offset == Offset::kOpen) {
    account->frozen_margin -= order->_frozen_margin;
    account->frozen_premium -= order->_frozen_premium;
  } else if (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday
    || order->offset == Offset::kCloseToday) {
    // 期权没有平仓盈亏
    if (product_class != md::ProductClass::kOption) {
      double close_profit_c = (order->direction == Direction::kBuy)
        ? (subpos.position_price - trade->price) * volume_multiple * volume
        : (trade->price - subpos.position_price) * volume_multiple * volume;
      account->close_profit += close_profit_c;
    }
  }
  // 成交划转手续费
  account->commission += trade->commission;
  account->frozen_commission -= order->_frozen_commission;
  // 期权更新权利金
  if (product_class == md::ProductClass::kOption)
    account->premium += CalcPremium(trade, volume_multiple, product_class);
  UpdateAccountField(account);
}

std::shared_ptr<const future::Position> LocalSimCalculator::ProcessPosition(
  std::shared_ptr<future::PositionNode> pos_node, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (helper) {
    auto ins = helper->GetShmInstrument(pos_node->Latest()->Symbol());
    if (!ins.has_value() || !IsPositionNeedUpdate(pos_node->Latest(), node_db, ins, helper))
      return nullptr;
    auto position = std::make_shared<Position>(*(pos_node->Latest()));
    RefreshPosition(position, node_db, ins, helper);
    FCASSERT(!IsPositionNeedUpdate(position, node_db, ins, helper));
    return position;
  }
  auto node = node_db->GetNode<md::Instrument>(pos_node->Latest()->Symbol());
  if (!node || !IsPositionNeedUpdate(pos_node->Latest(), node_db, node))
    return nullptr;
  auto position = std::make_shared<Position>(*(pos_node->Latest()));
  RefreshPosition(position, node_db, node);
  FCASSERT(!IsPositionNeedUpdate(position, node_db, node));
  return position;
}

void LocalSimCalculator::FrozenVolumeByOrder(SubPosition* subpos, int32_t volume) {
  auto avail_his_volume = subpos->volume_his - subpos->volume_his_frozen;
  if (volume <= avail_his_volume) {
    subpos->volume_his_frozen += volume;
    return;
  }
  subpos->volume_his_frozen += avail_his_volume;
  subpos->volume_today_frozen += volume - avail_his_volume;
}

void LocalSimCalculator::UnFrozenVolumeByCancel(SubPosition* subpos, int32_t volume) {
  if (subpos->volume_today_frozen >= volume) {
    subpos->volume_today_frozen -= volume;
    return;
  }
  subpos->volume_his_frozen -= volume - subpos->volume_today_frozen;
  subpos->volume_today_frozen = 0;
}

void LocalSimCalculator::UnFrozenVolumeByTrade(SubPosition* subpos, int32_t volume) {
  auto frozen_his_volume = subpos->volume_his_frozen;
  if (volume <= frozen_his_volume) {
    subpos->volume_his_frozen -= volume;
    subpos->volume_his -= volume;
    return;
  }
  auto delta_volume = volume - frozen_his_volume;
  subpos->volume_today_frozen -= delta_volume;
  subpos->volume_today -= delta_volume;
  subpos->volume_his_frozen = 0;
  subpos->volume_his -= frozen_his_volume;
}

bool LocalSimCalculator::IsPositionProfitUpdate(std::shared_ptr<const future::Position> position, double last_price) {
  if (isnan(last_price))
    return false;
  if (isnan(position->last_price))
    return true;
  return std::fabs(last_price - position->last_price) > 1e-5;
}

void LocalSimCalculator::UpdateProfit(double last_price, double volume_multiple, SubPosition& subpos) {
  if (isnan(last_price))
    return;
  subpos.position_profit = (last_price - subpos.position_price) * subpos.Volume() * volume_multiple;
  subpos.float_profit = (last_price - subpos.open_price) * subpos.Volume() * volume_multiple;
  if (subpos.direction == future::Direction::kSell) {
    subpos.position_profit *= -1;
    subpos.float_profit *= -1;
  }
}

bool LocalSimCalculator::IsPositionMarginUpdate(std::shared_ptr<const future::Position> position,
  std::shared_ptr<TqApiNodeDb> node_db, const std::optional<shm::ShmInstrument>& ins,
  std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!ins.has_value())
    return false;
  if (ins->product_class == md::ProductClass::kFuture) {
    auto margin_rate = CalcFutureMarginRate(position->user_key, ins, node_db);
    if (isnan(margin_rate))
      return false;
    if (std::fabs(margin_rate * position->VolumeTotal() - position->Margin()) < 1e-5)
      return false;
    return true;
  } else {
    auto margin_rate = CalcOptionMarginRate(ins, helper);
    if (isnan(margin_rate))
      return false;
    if (std::fabs(margin_rate * position->VolumeShort() - position->Margin()) < 1e-5)
      return false;
    return true;
  }
}

bool LocalSimCalculator::IsPositionMarginUpdate(std::shared_ptr<const future::Position> position,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::InstrumentNode> node) {
  if (!node)
    return false;
  if (node->Latest()->ProductClass() == md::ProductClass::kFuture) {
    auto margin_rate = CalcFutureMarginRate(position->user_key, node, node_db);
    if (isnan(margin_rate))
      return false;
    if (std::fabs(margin_rate * position->VolumeTotal() - position->Margin()) < 1e-5)
      return false;
    return true;
  } else {
    auto margin_rate = CalcOptionMarginRate(node, node_db);
    if (isnan(margin_rate))
      return false;
    if (std::fabs(margin_rate * position->VolumeShort() - position->Margin()) < 1e-5)
      return false;
    return true;
  }
}

bool LocalSimCalculator::IsPositionNeedUpdate(std::shared_ptr<const future::Position> position,
  std::shared_ptr<TqApiNodeDb> node_db, const std::optional<shm::ShmInstrument>& ins,
  std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!ins)
    return false;
  return IsPositionProfitUpdate(position, ins->last_price) || IsPositionMarginUpdate(position, node_db, ins, helper);
}

bool LocalSimCalculator::IsPositionNeedUpdate(std::shared_ptr<const future::Position> position,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::InstrumentNode> node) {
  if (!node)
    return false;
  return IsPositionProfitUpdate(position, node->Latest()->last_price)
    || IsPositionMarginUpdate(position, node_db, node);
}

void LocalSimCalculator::UpdateMargin(const std::string& user_key, const std::optional<shm::ShmInstrument>& ins,
  SubPosition& subpos, std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (ins->product_class == md::ProductClass::kFuture) {
    auto margin_rate = CalcFutureMarginRate(user_key, ins, node_db);
    if (isnan(margin_rate))
      return;
    subpos.margin = margin_rate * subpos.Volume();
    return;
  } else if (ins->product_class == md::ProductClass::kOption) {
    // 期权只有义务方才有占用保证金
    if (subpos.direction == future::Direction::kBuy)
      return;
    auto margin_rate = CalcOptionMarginRate(ins, helper);
    if (isnan(margin_rate))
      return;
    subpos.margin = margin_rate * subpos.Volume();
  }
}

void LocalSimCalculator::UpdateMargin(const std::string& user_key, std::shared_ptr<md::InstrumentNode> node,
  SubPosition& subpos, std::shared_ptr<TqApiNodeDb> node_db) {
  if (node->Latest()->ProductClass() == md::ProductClass::kFuture) {
    auto margin_rate = CalcFutureMarginRate(user_key, node, node_db);
    if (isnan(margin_rate))
      return;
    subpos.margin = margin_rate * subpos.Volume();
  } else if (node->Latest()->ProductClass() == md::ProductClass::kOption) {
    if (subpos.direction == future::Direction::kBuy)
      return;
    auto margin_rate = CalcOptionMarginRate(node, node_db);
    if (isnan(margin_rate))
      return;
    subpos.margin = margin_rate * subpos.Volume();
  }
}

void LocalSimCalculator::UpdateMarketValue(const std::optional<shm::ShmInstrument>& ins, SubPosition& subpos) {
  auto last_price = ins->last_price;
  if (isnan(last_price))
    return;
  subpos.market_value = last_price * ins->volume_multiple * subpos.Volume();
  if (ins->product_class == md::ProductClass::kOption && subpos.direction == future::Direction::kSell)
    subpos.market_value *= -1;
}

void LocalSimCalculator::UpdateMarketValue(std::shared_ptr<md::InstrumentNode> node, SubPosition& subpos) {
  auto last_price = node->Latest()->last_price;
  if (isnan(last_price))
    return;
  subpos.market_value = last_price * node->Latest()->VolumeMultiple() * subpos.Volume();
  if (node->Latest()->ProductClass() == md::ProductClass::kOption && subpos.direction == future::Direction::kSell)
    subpos.market_value *= -1;
}

void LocalSimCalculator::RefreshPosition(std::shared_ptr<Position> position, std::shared_ptr<TqApiNodeDb> node_db,
  const std::optional<shm::ShmInstrument>& ins, std::shared_ptr<md::MdServiceShmHelper> helper) {
  FCASSERT(ins.has_value());
  position->last_price = ins->last_price;
  if (isnan(ins->last_price))
    return;
  // 更新持仓盈亏
  UpdateProfit(ins->last_price, ins->volume_multiple, position->subpos_long_spec);
  UpdateProfit(ins->last_price, ins->volume_multiple, position->subpos_long_other);
  UpdateProfit(ins->last_price, ins->volume_multiple, position->subpos_short_spec);
  UpdateProfit(ins->last_price, ins->volume_multiple, position->subpos_short_other);
  // 更新持仓占用保证金
  UpdateMargin(position->user_key, ins, position->subpos_long_spec, node_db, helper);
  UpdateMargin(position->user_key, ins, position->subpos_long_other, node_db, helper);
  UpdateMargin(position->user_key, ins, position->subpos_short_spec, node_db, helper);
  UpdateMargin(position->user_key, ins, position->subpos_short_other, node_db, helper);
  // 更新持仓市值
  UpdateMarketValue(ins, position->subpos_long_spec);
  UpdateMarketValue(ins, position->subpos_long_other);
  UpdateMarketValue(ins, position->subpos_short_spec);
  UpdateMarketValue(ins, position->subpos_short_other);
}

void LocalSimCalculator::RefreshPosition(
  std::shared_ptr<Position> position, std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::InstrumentNode> node) {
  FCASSERT(node);
  const auto& ins = node->Latest();
  position->last_price = ins->last_price;
  if (isnan(ins->last_price))
    return;
  // 更新持仓盈亏
  UpdateProfit(ins->last_price, ins->VolumeMultiple(), position->subpos_long_spec);
  UpdateProfit(ins->last_price, ins->VolumeMultiple(), position->subpos_long_other);
  UpdateProfit(ins->last_price, ins->VolumeMultiple(), position->subpos_short_spec);
  UpdateProfit(ins->last_price, ins->VolumeMultiple(), position->subpos_short_other);
  // 更新持仓占用保证金
  UpdateMargin(position->user_key, node, position->subpos_long_spec, node_db);
  UpdateMargin(position->user_key, node, position->subpos_long_other, node_db);
  UpdateMargin(position->user_key, node, position->subpos_short_spec, node_db);
  UpdateMargin(position->user_key, node, position->subpos_short_other, node_db);
  // 更新持仓市值
  UpdateMarketValue(node, position->subpos_long_spec);
  UpdateMarketValue(node, position->subpos_long_other);
  UpdateMarketValue(node, position->subpos_short_spec);
  UpdateMarketValue(node, position->subpos_short_other);
}

