LocalSimServiceImpl::LocalSimServiceImpl(boost::asio::io_context* ioc, const std::string& user_key,
  std::shared_ptr<TqApiNodeDb> node_db, std::shared_ptr<md::MdServiceShmHelper> helper,
  structlog::Logger& parent_logger)
  : m_user_key(user_key)
  , m_node_db(node_db)
  , m_md_helper(helper)
  , m_logger(parent_logger.With("c2", "future").With("c3", "local_sim").Clone())
  , m_strand(*ioc) {
  m_alive_order_view = m_node_db->CreateView<Order>([&](std::shared_ptr<const Order> order) {
    return order->user_key == m_user_key && order->status == OrderStatus::kAlive;
  });
  m_position_view = m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_user_key;
  });
  m_current_datetime = NowAsEpochNano();
  m_trading_day_end = NowAsEpochNano();
}

// 处理各个命令，调用Req**，将各种命令压入队列
void LocalSimServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  SetCommandStarted(command);
  switch (command->aid) {
    case future::ReqLogin::AID: {
      ReqLogin(std::static_pointer_cast<future::ReqLogin>(command));
      break;
    }
    case InsertOrder::AID: {
      ReqInsertOrder(std::static_pointer_cast<InsertOrder>(command));
      break;
    }
    case CancelOrder::AID: {
      ReqCancelOrder(std::static_pointer_cast<CancelOrder>(command));
      break;
    }
    case TransferMoney::AID: {
      ReqTransferMoney(std::static_pointer_cast<TransferMoney>(command));
      break;
    }
    case SetMarginRate::AID: {
      ReqSetMarginRate(std::static_pointer_cast<SetMarginRate>(command));
      break;
    }
    case SetCommissionRate::AID: {
      ReqSetCommissionRate(std::static_pointer_cast<SetCommissionRate>(command));
      break;
    }
    case QueryMarginRate::AID: {
      ReqQueryMarginRate(std::static_pointer_cast<QueryMarginRate>(command));
      break;
    }
    case QueryCommissionRate::AID: {
      ReqQueryCommissionRate(std::static_pointer_cast<QueryCommissionRate>(command));
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"fclib: 本地模拟交易暂不支持该接口");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}
// 每次RunOnce，检测登陆状态，调用ProcessCommand处理队列
int LocalSimServiceImpl::RunOnce() {
  m_runonce_cnt = 0;
  // 网络断连, 不执行任何代码
  if (!m_network_connect)
    return m_runonce_cnt;
  m_current_datetime = NowAsEpochNano();
  if (m_login_status == LocalSimLoginStatus::kBeforeInit) {
    RspLogin();
    m_runonce_cnt++;
  }
  // 非登录状态, 不执行任何指令
  if (m_login_status != LocalSimLoginStatus::kLogined)
    return 0;
  // 跨日结算
  if (TradingDayChanged()) {
    Settle();
    m_runonce_cnt++;
  }
  // 处理所有的请求队列
  while (!m_command_queue.empty()) {
    ProcessCommand(m_command_queue.front());
    m_command_queue.pop();
    m_runonce_cnt++;
  }
  // 处理未成交的委托单
  //!! 不能使用 const &, set会由于for引起变动
  auto alive_order_map = m_alive_order_view->GetNodes();
  for (auto& [key, alive_order] : alive_order_map) {
    ProcessAliveOrder(alive_order);
  }
  // 调整持仓和账户截面, 维持数据截面自洽
  AdjustPositionAccount();
  return m_runonce_cnt;
}
// 调用Rsp**，处理队列中的任务
void LocalSimServiceImpl::ProcessCommand(std::shared_ptr<UserCommand> command) {
  switch (command->aid) {
    case InsertOrder::AID: {
      RspInsertOrder(std::static_pointer_cast<InsertOrder>(command));
      break;
    }
    case CancelOrder::AID: {
      RspCancelOrder(std::static_pointer_cast<CancelOrder>(command));
      break;
    }
    case TransferMoney::AID: {
      RspTransferMoney(std::static_pointer_cast<TransferMoney>(command));
      break;
    }
    case SetMarginRate::AID: {
      RspSetMarginRate(std::static_pointer_cast<SetMarginRate>(command));
      break;
    }
    case SetCommissionRate::AID: {
      RspSetCommissionRate(std::static_pointer_cast<SetCommissionRate>(command));
      break;
    }
    case QueryMarginRate::AID: {
      RspQueryMarginRate(std::static_pointer_cast<QueryMarginRate>(command));
      break;
    }
    case QueryCommissionRate::AID: {
      RspQueryCommissionRate(std::static_pointer_cast<QueryCommissionRate>(command));
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"fclib: 本地模拟交易暂不支持该接口");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

void LocalSimServiceImpl::ReqLogin(std::shared_ptr<future::ReqLogin> req) {
  m_local_sim_user_id = req->user_id;
  m_command_manager->SetCommandId(req, "login");
  m_session_id = reinterpret_cast<int64_t>(this);
  m_strand.post([=]() {
    m_login_status = LocalSimLoginStatus::kBeforeInit;
  });
}

void LocalSimServiceImpl::RspLogin() {
  if (m_login_status != LocalSimLoginStatus::kBeforeInit)
    return;
  auto req = m_command_manager->Update("login");
  auto req_login = std::static_pointer_cast<future::ReqLogin>(req);
  SetCommandFinished(req, 0, u8"登录成功");
  m_login_status = LocalSimLoginStatus::kLogined;
  m_node_db->ReplaceRecord<LoginContent>(m_user_key, [=](std::shared_ptr<LoginContent> login) {
    login->user_key = m_user_key;
    login->currency = "CNY";
    char trading_day[9];
    char login_time[9];
    login->broker_id = "8800";
    login->system_name = "TradingHosting";
    login->backend = BackEnd::kLocalSim;
    login->user_id = m_local_sim_user_id;
    login->investor_id = m_local_sim_user_id;
    login->account_ready = true;
    login->position_ready = true;
    login->session_status = SessionStatus::kLogined;
    login->session_id = m_session_id;
    if (login->user_desc == "") {
      login->user_desc = req_login->user_desc;
    }
    auto time_s = EpochNanoToLocalDateTime(m_current_datetime, 8);
    if (snprintf(trading_day, sizeof(trading_day), "%04d%02d%02d", (time_s.date_time.tm_year + 1900),
          (time_s.date_time.tm_mon + 1), time_s.date_time.tm_mday)
      > 0) {
      login->trading_day = trading_day;
    }
    if (snprintf(login_time, sizeof(login_time), "%02d:%02d:%02d", time_s.date_time.tm_hour, time_s.date_time.tm_min,
          time_s.date_time.tm_sec)
      > 0) {
      login->login_time = login_time;
    }
  });
  // 初始化账户资金
  m_node_db->ReplaceRecord<Account>(m_user_key + "|0|CNY", [=](std::shared_ptr<Account> account) {
    account->user_key = m_user_key;
    account->investor_id = m_local_sim_user_id;
    account->currency = "CNY";
    account->pre_balance = 10000000.0;
    LocalSimCalculator::UpdateAccountField(account);
  });
}

void LocalSimServiceImpl::ReqInsertOrder(std::shared_ptr<InsertOrder> req) {
  std::string check_msg;
  bool ret = CheckInsertOrderValidity(req, &check_msg);
  if (!check_msg.empty() || !ret) {
    SetCommandFinished(req, -1, check_msg);
    return;
  }
  if (req->order_id.empty())
    req->order_id = std::to_string(++m_order_id);
  m_command_manager->SetCommandId(req, "InsertOrder" + req->order_id);
  PushCommand(req);
}

void LocalSimServiceImpl::RspInsertOrder(std::shared_ptr<InsertOrder> req) {
  auto order = LocalSimCalculator::CreateOrder(m_local_sim_user_id, req, m_node_db);
  order->session_id = m_session_id;
  // 委托单有效性检查
  if (!CheckOrderValidity(order)) {
    order->_frozen_margin = 0.0;
    order->_frozen_premium = 0.0;
    order->_frozen_commission = 0.0;
    order->status = OrderStatus::kDead;
    order->dead_date_time = NowAsEpochNano();
  } else {
    order->exchange_order_id = order->order_id;
  }
  // 存储委托单
  auto order_node = m_node_db->ReplaceRecord<Order>(order);
  req->order_pointer = order_node;
  // 下单指令反馈
  if (order->status == OrderStatus::kDead) {
    SetCommandFinished(req, -1, order->status_msg);
    return;
  }
  SetCommandFinished(req, 0, order->status_msg);
  // 更新账户和持仓
  auto account_key = m_user_key + "|0|CNY";
  if (order->offset == Offset::kOpen) {
    m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> account) {
      account->frozen_margin += order->_frozen_margin;
      account->frozen_premium += order->_frozen_premium;
      account->frozen_commission += order->_frozen_commission;
      LocalSimCalculator::LocalSimCalculator::UpdateAccountField(account);
    });
  } else {
    m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> account) {
      account->frozen_commission += order->_frozen_commission;
      LocalSimCalculator::LocalSimCalculator::UpdateAccountField(account);
    });
    auto position_key = m_user_key + "|0|" + order->Symbol();
    m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      LocalSimCalculator::UpdatePositionByOrder(position, order);
    });
  }
}

void LocalSimServiceImpl::ReqCancelOrder(std::shared_ptr<CancelOrder> req) {
  auto check_msg = CheckCancelOrderValidity(req);
  if (!check_msg.empty()) {
    SetCommandFinished(req, -1, check_msg);
    return;
  }
  m_command_manager->SetCommandId(req, "CancelOrder" + req->order_id);
  PushCommand(req);
}

void LocalSimServiceImpl::RspCancelOrder(std::shared_ptr<CancelOrder> req) {
  // 更新委托单
  auto order_key = m_user_key + "|" + req->order_id;
  auto order_node = m_node_db->GetNode<Order>(order_key);
  if (order_node->Latest()->status == OrderStatus::kDead) {
    SetCommandFinished(req, 0, u8"对应id的委托单已成交或已撤销, 无法撤单");
    return;
  }
  // 更新账户
  auto account_key = m_user_key + "|0|CNY";
  m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> account) {
    LocalSimCalculator::UpdateAccountByCancelOrder(account, order_node->Latest());
  });
  // 更新持仓
  if (order_node->Latest()->offset != Offset::kOpen) {
    auto position_key = m_user_key + "|0|" + order_node->Latest()->Symbol();
    m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      LocalSimCalculator::UpdatePositionByCancelOrder(position, order_node->Latest());
    });
  }
  m_node_db->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<Order> o) {
    o->status = OrderStatus::kDead;
    o->status_msg = u8"撤单成功";
    o->dead_date_time = NowAsEpochNano();
    o->_frozen_margin = 0.0;
    o->_frozen_premium = 0.0;
    o->_frozen_commission = 0.0;
  });
  SetCommandFinished(req, 0, u8"撤单成功");
}

void LocalSimServiceImpl::ReqTransferMoney(std::shared_ptr<TransferMoney> req) {
  if (!m_network_connect) {
    SetCommandFinished(req, -1, u8"当前网络断连, 无法银期转账");
    return;
  }
  if (isnan(req->amount)) {
    SetCommandFinished(req, -1, u8"未输入转账金额, 无法银期转账");
    return;
  }
  auto request_id = LocalSimCalculator::CalcRequestID();
  m_command_manager->SetCommandId(req, std::to_string(request_id));
  PushCommand(req);
}

void LocalSimServiceImpl::RspTransferMoney(std::shared_ptr<TransferMoney> req) {
  auto account_key = req->user_key + "|0|CNY";
  if (req->is_deposit) {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->deposit += req->amount;
      LocalSimCalculator::UpdateAccountField(account);
    });
  } else {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->withdraw += req->amount;
      LocalSimCalculator::UpdateAccountField(account);
    });
  }
  SetCommandFinished(req, 0, u8"转账成功");
}

void LocalSimServiceImpl::ReqSetMarginRate(std::shared_ptr<SetMarginRate> req) {
  if (!m_network_connect) {
    SetCommandFinished(req, -1, u8"当前网络断连, 无法设置保证金率");
    return;
  }
  if (req->symbol.empty()) {
    SetCommandFinished(req, -1, u8"未指定标的, 无法设置保证金率");
    return;
  }
  if (m_md_helper && !m_md_helper->GetShmInstrument(req->symbol).has_value()) {
    SetCommandFinished(req, -1, u8"指定的合约不存在, 无法设置保证金率");
    return;
  }
  if (!m_md_helper && nullptr == m_node_db->GetNode<md::Instrument>(req->symbol)) {
    SetCommandFinished(req, -1, u8"指定的合约不存在, 无法设置保证金率");
    return;
  }
  if (isnan(req->volume_margin)) {
    SetCommandFinished(req, -1, u8"本地模拟交易, 未设置每手保证金率");
    return;
  }
  m_command_manager->SetCommandId(req, std::to_string(LocalSimCalculator::CalcRequestID()));
  PushCommand(req);
}

void LocalSimServiceImpl::RspSetMarginRate(std::shared_ptr<SetMarginRate> req) {
  std::string instrument_id;
  if (m_md_helper) {
    auto ins_id = m_md_helper->GetShmInstrumentField(req->symbol, &shm::ShmInstrument::instrument_id);
    if (!ins_id.has_value())
      return;
    instrument_id = ins_id->data();
  } else {
    auto ins = m_node_db->GetNode<md::Instrument>(req->symbol);
    if (nullptr == ins)
      return;
    instrument_id = ins->Latest()->InstrumentID();
  }
  auto rate_key = req->user_key + "|" + instrument_id;
  m_node_db->ReplaceRecord<Rate>(rate_key, [=](std::shared_ptr<Rate> rate) {
    rate->user_key = req->user_key;
    rate->instrument_id = instrument_id;
    if (!isnan(req->volume_margin)) {
      UnitRate unit_rate;
      unit_rate.volume_rate = req->volume_margin;
      rate->margin_rate_long_other = unit_rate;
      rate->margin_rate_short_other = unit_rate;
      rate->margin_rate_long_spec = unit_rate;
      rate->margin_rate_short_spec = unit_rate;
    }
  });
  SetCommandFinished(req, 0, u8"设置保证金率成功");
}

