void LocalSimServiceImpl::RspSetCommissionRate(std::shared_ptr<SetCommissionRate> req) {
  double commission;
  std::string instrument_id;
  if (m_md_helper) {
    auto ins = m_md_helper->GetShmInstrument(req->symbol);
    if (!ins.has_value())
      return;
    commission = ins->commission;
    instrument_id = ins->instrument_id.data();
  } else {
    auto ins = m_node_db->GetNode<md::Instrument>(req->symbol);
    if (nullptr == ins)
      return;
    commission = ins->Latest()->instrument_base->commission;
    instrument_id = ins->Latest()->InstrumentID();
  }
  auto rate_key = req->user_key + "|" + instrument_id;
  m_node_db->ReplaceRecord<Rate>(rate_key, [=](std::shared_ptr<Rate> rate) {
    rate->user_key = req->user_key;
    rate->instrument_id = instrument_id;
    for (int i = 0; i < 3; i++) {
      UnitRate unit_rate;
      // 获取手续费率默认值
      unit_rate.volume_rate = commission;
      if (isnan(unit_rate.volume_rate) || unit_rate.volume_rate <= 0.0)
        unit_rate.volume_rate = 10.0;
      if (!isnan(req->volume_commission[i]))
        unit_rate.volume_rate = req->volume_commission[i];
      if (i == 0) {
        rate->commission_rate_open = unit_rate;
      } else if (i == 1) {
        rate->commission_rate_close = unit_rate;
      } else if (i == 2) {
        rate->commission_rate_close_today = unit_rate;
      }
    }
  });
  SetCommandFinished(req, 0, u8"设置手续费率成功");
}

void LocalSimServiceImpl::RspQueryMarginRate(std::shared_ptr<QueryMarginRate> req) {
  double rate_volume;
  std::string instrument_id;
  if (m_md_helper) {
    auto ins = m_md_helper->GetShmInstrument(req->exchange_id + "." + req->instrument_id);
    if (!ins.has_value()) {
      SetCommandFinished(req, -1, u8"找不到合约");
      return;
    }
    rate_volume = LocalSimCalculator::CalcFutureMarginRate(m_user_key, ins, m_node_db);
    instrument_id = ins->instrument_id.data();
  } else {
    auto ins = m_node_db->GetNode<md::Instrument>(req->exchange_id + "." + req->instrument_id);
    if (nullptr == ins) {
      SetCommandFinished(req, -1, u8"找不到合约");
      return;
    }
    rate_volume = LocalSimCalculator::CalcFutureMarginRate(m_user_key, ins, m_node_db);
    instrument_id = ins->Latest()->InstrumentID();
  }

  auto rate_key = req->user_key + "|" + instrument_id;
  m_node_db->ReplaceRecord<Rate>(rate_key, [=](std::shared_ptr<Rate> rate) {
    rate->user_key = req->user_key;
    rate->instrument_id = instrument_id;
    rate->margin_rate_long_other = (UnitRate(0.0, rate_volume));
    rate->margin_rate_long_spec = (UnitRate(0.0, rate_volume));
    rate->margin_rate_short_other = (UnitRate(0.0, rate_volume));
    rate->margin_rate_short_spec = (UnitRate(0.0, rate_volume));
  });
  SetCommandFinished(req);
  return;
}

void LocalSimServiceImpl::RspQueryCommissionRate(std::shared_ptr<QueryCommissionRate> req) {
  std::string instrument_id;
  std::vector<double> rates(3);
  if (m_md_helper) {
    auto ins = m_md_helper->GetShmInstrument(req->exchange_id + "." + req->instrument_id);
    if (!ins.has_value()) {
      SetCommandFinished(req, -1, u8"找不到合约");
      return;
    }
    instrument_id = ins->instrument_id.data();
    rates[0] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kOpen, m_node_db);
    rates[1] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kCloseYesterday, m_node_db);
    rates[2] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kCloseToday, m_node_db);
  } else {
    auto ins = m_node_db->GetNode<md::Instrument>(req->exchange_id + "." + req->instrument_id);
    if (nullptr == ins) {
      SetCommandFinished(req, -1, u8"找不到合约");
      return;
    }
    instrument_id = ins->Latest()->InstrumentID();
    rates[0] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kOpen, m_node_db);
    rates[1] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kCloseYesterday, m_node_db);
    rates[2] = LocalSimCalculator::CalcCommissionRate(m_user_key, ins, Offset::kCloseToday, m_node_db);
  }

  auto rate_key = req->user_key + "|" + instrument_id;
  m_node_db->ReplaceRecord<Rate>(rate_key, [=](std::shared_ptr<Rate> rate) {
    rate->user_key = req->user_key;
    rate->instrument_id = instrument_id;
    rate->commission_rate_open = (UnitRate(0.0, rates[0]));
    rate->commission_rate_close = (UnitRate(0.0, rates[1]));
    rate->commission_rate_close_today = (UnitRate(0.0, rates[2]));
    rate->commission_rate_exec = (UnitRate(NAN, NAN));
  });
  SetCommandFinished(req);
}

bool LocalSimServiceImpl::TradingDayChanged() {
  auto current_quote_datetime = NowAsEpochNano();
  if (current_quote_datetime <= 0) {
    return false;
  }
  m_current_datetime = current_quote_datetime;
  if (m_current_datetime >= m_trading_day_end) {
    return true;
  }
  return false;
}

void LocalSimServiceImpl::Settle() {
  // 撤销所有未成交的委托单
  auto alive_order_map = m_alive_order_view->GetNodes();
  for (auto& alive_order_it : alive_order_map) {
    auto key = alive_order_it.first;
    auto order_node = m_node_db->ReplaceRecord<Order>(key, [&](std::shared_ptr<Order> o) {
      o->_frozen_margin = 0.0;
      o->_frozen_premium = 0.0;
      o->_frozen_commission = 0.0;
      o->status = OrderStatus::kDead;
      o->status_msg = u8"交易日结束, 自动撤销当日有效的委托单(GFD)";
      o->dead_date_time = m_trading_day_end;
    });
  }
  // account 资金字段更新
  auto account_key = m_user_key + "|" + m_unit_id + "|CNY";
  m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> account) {
    LocalSimCalculator::AccountSettle(account);
  });
  // position 持仓字段更新
  for (auto&& [position_key, _] : m_position_view->GetNodes()) {
    m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      LocalSimCalculator::SubPositionSettle(&position->subpos_long_spec, position->last_price);
      LocalSimCalculator::SubPositionSettle(&position->subpos_long_other, position->last_price);
      LocalSimCalculator::SubPositionSettle(&position->subpos_short_spec, position->last_price);
      LocalSimCalculator::SubPositionSettle(&position->subpos_short_other, position->last_price);
    });
  }
  m_trading_day_end = LocalSimCalculator::CalcTradingDayEnd(m_current_datetime);
}

void LocalSimServiceImpl::ProcessAliveOrder(std::shared_ptr<future::OrderNode> order_node) {
  if (!CheckAliveOrderValidity(order_node))
    return;
  double trade_price = LocalSimCalculator::CalcTradePrice(
    order_node->Latest()->Symbol(), order_node->Latest()->direction, m_node_db, m_md_helper);
  if (isnan(trade_price))
    return;
  const auto& order_id = order_node->Latest()->order_id;

  // 检验委托单是否可以成交
  bool can_trade = LocalSimCalculator::IsOrderTraded(trade_price, order_node);

  // FAK订单特殊处理：如果不能立即成交，直接撤销
  if (!can_trade && order_node->Latest()->time_condition == OrderTimeCondition::kIoc) {
    m_runonce_cnt++;

    // 获取订单信息用于后续释放资源
    auto order = order_node->Latest();
    auto frozen_margin = order->_frozen_margin;
    auto frozen_premium = order->_frozen_premium;
    auto frozen_commission = order->_frozen_commission;

    // 检查撤销原因：是否因为资金不足
    std::string cancel_reason = u8"";
    if (order->offset == Offset::kOpen) {
      auto account = m_node_db->GetNode<Account>(m_user_key + "|0|CNY")->Latest();
      if (account->available < (frozen_margin + frozen_premium + frozen_commission)) {
        cancel_reason = u8"账户可用余额不足，IOC订单自动撤销";
      }
    }

    // 撤销FAK订单
    m_node_db->ReplaceRecord<Order>(m_user_key + "|" + order_id, [&](std::shared_ptr<Order> o) {
      o->status = OrderStatus::kDead;
      o->status_msg = cancel_reason;
      o->dead_date_time = NowAsEpochNano();
      o->_frozen_margin = 0.0;
      o->_frozen_premium = 0.0;
      o->_frozen_commission = 0.0;
    });
    return;
  }

  // 普通订单如果不能成交，继续等待
  if (!can_trade)
    return;

  m_runonce_cnt++;
  // 成交记录更新
  auto trade =
    LocalSimCalculator::CreateTrade(m_last_trade_id, order_node->Latest(), trade_price, m_node_db, m_md_helper);
  std::optional<shm::ShmInstrument> shm_ins = std::nullopt;
  std::shared_ptr<md::InstrumentNode> ins_node = nullptr;
  if (m_md_helper) {
    shm_ins = m_md_helper->GetShmInstrument(trade->Symbol());
    FCASSERT(shm_ins.has_value());
  } else {
    ins_node = m_node_db->GetNode<md::Instrument>(trade->Symbol());
    FCASSERT(ins_node);
  }
  const auto volume_multiple = m_md_helper ? shm_ins->volume_multiple : ins_node->Latest()->VolumeMultiple();
  const auto& pre_settlement = m_md_helper ? shm_ins->pre_settlement : ins_node->Latest()->pre_settlement;
  const auto product_class = m_md_helper ? shm_ins->product_class : ins_node->Latest()->ProductClass();

  // 持仓记录更新
  auto position_key = m_user_key + "|0|" + order_node->Latest()->Symbol();
  auto pos_node = m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
    LocalSimCalculator::UpdatePositionByTrade(position, trade, volume_multiple, pre_settlement, product_class);
    // last_price 设置为nan, 触发后续刷新机制
    position->last_price = NAN;
  });
  // 账户记录更新
  auto account_key = m_user_key + "|0|CNY";
  m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
    auto subpos = LocalSimCalculator::GetSubPos(order_node->Latest(), pos_node->Latest());
    LocalSimCalculator::UpdateAccountByTrade(account, trade, *subpos, volume_multiple, product_class);
  });
  m_node_db->ReplaceRecord<Trade>(trade);
  // 委托单更新为全部成交
  m_node_db->ReplaceRecord<Order>(m_user_key + "|" + order_id, [&](std::shared_ptr<Order> o) {
    o->volume_left = 0;
    o->_frozen_margin = 0.0;
    o->_frozen_premium = 0.0;
    o->_frozen_commission = 0.0;
    o->status = OrderStatus::kDead;
    o->dead_date_time = NowAsEpochNano();
    m_md_helper
      ? LocalSimCalculator::UpdateOrderByTrade(m_node_db->GetNode<future::Trade>(trade->GetKey()), shm_ins, o)
      : LocalSimCalculator::UpdateOrderByTrade(m_node_db->GetNode<future::Trade>(trade->GetKey()), ins_node, o);
  });
}

void LocalSimServiceImpl::AdjustPositionAccount() {
  double account_position_profit = 0.0;
  double account_float_profit = 0.0;
  double account_margin = 0.0;
  double account_buy_market_value = 0.0;
  double account_sell_market_value = 0.0;
  double future_market_value = 0.0;
  for (auto& [_, pos_node] : m_position_view->GetNodes()) {
    auto position = LocalSimCalculator::ProcessPosition(pos_node, m_node_db, m_md_helper);
    if (position) {
      m_node_db->ReplaceRecord<Position>(position);
      m_runonce_cnt++;
    } else {
      position = pos_node->Latest();
    }
    account_float_profit += position->FloatProfit();
    account_margin += position->Margin();
    md::ProductClass product_class;
    if (m_md_helper) {
      auto pc = m_md_helper->GetShmInstrumentField(position->Symbol(), &shm::ShmInstrument::product_class);
      if (!pc.has_value())
        continue;
      product_class = pc.value();
    } else {
      auto ins = m_node_db->GetNode<md::Instrument>(position->Symbol());
      if (nullptr == ins)
        continue;
      product_class = ins->Latest()->ProductClass();
    }
    if (product_class == md::ProductClass::kFuture)
      future_market_value += position->LongMarketValue() + position->ShortMarketValue();
    if (product_class != md::ProductClass::kOption)
      account_position_profit += position->PositionProfit();
    if (product_class == md::ProductClass::kOption) {
      account_buy_market_value += position->LongMarketValue();
      account_sell_market_value += position->ShortMarketValue();
    }
  }
  // 账户盈亏更新
  auto account_key = m_user_key + "|" + m_unit_id + "|CNY";
  auto account_node = m_node_db->GetNode<Account>(account_key);
  if (!EqualDouble(account_node->Latest()->position_profit, account_position_profit, 5)
    || !EqualDouble(account_node->Latest()->float_profit, account_float_profit, 5)
    || !EqualDouble(account_node->Latest()->margin, account_margin, 5)
    || !EqualDouble(account_node->Latest()->option_buy_market_value, account_buy_market_value, 5)
    || !EqualDouble(account_node->Latest()->option_sell_market_value, account_sell_market_value, 5)) {
    m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> account) {
      account->position_profit = account_position_profit;
      account->float_profit = account_float_profit;
      account->margin = account_margin;
      account->option_buy_market_value = account_buy_market_value;
      account->option_sell_market_value = account_sell_market_value;
      account->option_market_value = account_buy_market_value + account_sell_market_value;
      account->future_market_value = future_market_value;
      LocalSimCalculator::UpdateAccountField(account);
    });
    m_runonce_cnt++;
  }
}

bool LocalSimServiceImpl::CheckInsertOrderValidity(std::shared_ptr<future::InsertOrder> req, std::string* msg) {
  if (!m_network_connect) {
    *msg = u8"当前网络断连, 无法下单";
    return false;
  }
  if (m_login_status != LocalSimLoginStatus::kLogined) {
    *msg = u8"当前未登录到交易服务器, 无法下单";
    return false;
  }
  if (m_user_key.empty()) {
    *msg = u8"账户信息不存在, 无法下单";
    return false;
  }
  if (m_local_sim_user_id.empty()) {
    *msg = u8"用户ID信息不存在, 无法下单";
    return false;
  }
  if (req->exchange_id.empty()) {
    *msg = u8"委托单交易所信息不存在, 无法下单";
    return false;
  }
  if (req->instrument_id.empty()) {
    *msg = u8"委托单交易合约信息不存在, 无法下单";
    return false;
  }
  if (req->direction == future::Direction::kInvalid) {
    *msg = u8"委托单交易方向无效, 无法下单";
    return false;
  }
  if (req->offset == future::Offset::kInvalid) {
    *msg = u8"委托单开平方向无效, 无法下单";
    return false;
  }
  if (req->offset == future::Offset::kOpenAndClose || req->offset == future::Offset::kCloseAndOpen) {
    *msg = u8"模拟交易暂不支持组合下单, 无法下单";
    return false;
  }
  if (req->hedge_flag == future::OrderHedgeFlag::kInvalid) {
    *msg = u8"委托单投保标志无效, 无法下单";
    return false;
  }
  if (req->price_type == future::PriceType::kInvalid) {
    *msg = u8"委托单价格类型无效, 无法下单";
    return false;
  }
  if (req->volume_condition == future::OrderVolumeCondition::kInvalid) {
    *msg = u8"委托单成交量类型无效, 无法下单";
    return false;
  }
  if (req->time_condition == future::OrderTimeCondition::kInvalid) {
    *msg = u8"委托单有效期类型无效, 无法下单";
    return false;
  }
  auto symbol = req->exchange_id + "." + req->instrument_id;
  if (m_md_helper) {
    auto ins = m_md_helper->GetShmInstrument(symbol);
    if (!ins.has_value()) {
      *msg = u8"下单合约不存在, 无法下单";
      return false;
    }
    if ((isnan(ins->margin) || isnan(ins->commission)) && ins->product_class != md::ProductClass::kOption) {
      *msg = u8"不支持的合约类型, 模拟交易目前不支持组合, 股票, etf期权模拟交易";
      return false;
    }
    return true;
  }
  auto node = m_node_db->GetNode<md::Instrument>(symbol);
  if (nullptr == node) {
    *msg = u8"下单合约不存在, 无法下单";
    return false;
  }
  if ((isnan(node->Latest()->instrument_base->margin) || isnan(node->Latest()->instrument_base->commission))
    && node->Latest()->ProductClass() != md::ProductClass::kOption) {
    *msg = u8"不支持的合约类型, 模拟交易目前不支持组合, 股票, etf期权模拟交易";
    return false;
  }
  return true;
}

const std::string LocalSimServiceImpl::CheckCancelOrderValidity(std::shared_ptr<future::CancelOrder> req) {
  if (!m_network_connect)
    return u8"当前网络断连, 无法撤单";
  if (m_login_status != LocalSimLoginStatus::kLogined)
    return u8"当前未登录到交易服务器, 无法撤单";
  auto order_node = m_node_db->GetNode<Order>(m_user_key + "|" + req->order_id);
  if (!order_node)
    return u8"没有对应id的委托单, 无法撤单";
  if (order_node->Latest()->status != OrderStatus::kAlive)
    return u8"对应id的委托单已成交或已撤销, 无法撤单";
  return std::string();
}

bool LocalSimServiceImpl::CheckOrderValidity(std::shared_ptr<future::Order> order) {
  std::optional<shm::ShmInstrument> shm_ins = std::nullopt;
  std::shared_ptr<md::InstrumentNode> ins_node = nullptr;
  if (m_md_helper) {
    shm_ins = m_md_helper->GetShmInstrument(order->Symbol());
    if (!shm_ins.has_value()) {
      order->status_msg = u8"下单合约不存在, 无法下单";
      return false;
    }
  } else {
    ins_node = m_node_db->GetNode<md::Instrument>(order->Symbol());
    if (nullptr == ins_node) {
      order->status_msg = u8"下单合约不存在, 无法下单";
      return false;
    }
  }
  const auto& last_price = m_md_helper ? shm_ins->last_price : ins_node->Latest()->last_price;
  const auto& upper_limit = m_md_helper ? shm_ins->upper_limit : ins_node->Latest()->upper_limit;
  const auto& lower_limit = m_md_helper ? shm_ins->lower_limit : ins_node->Latest()->lower_limit;
  const auto product_class = m_md_helper ? shm_ins->product_class : ins_node->Latest()->ProductClass();
  const auto volume_multiple = m_md_helper ? shm_ins->volume_multiple : ins_node->Latest()->VolumeMultiple();

  if (!LocalSimCalculator::IsMarketOrder(order)) {
    if (order->limit_price <= 0 || isnan(order->limit_price)) {
      order->status_msg = u8"委托单价格小于等于0, 无法下单";
      return false;
    }
    if (order->limit_price > upper_limit || order->limit_price < lower_limit) {
      order->status_msg = u8"下单价格超出当日涨跌停范围, 无法下单";
      return false;
    }
  }
  if (order->volume_orign <= 0) {
    order->status_msg = u8"委托单手数小于等于0, 无法下单";
    return false;
  }
  order->_frozen_commission = m_md_helper
    ? LocalSimCalculator::CalcCommissionRate(m_user_key, shm_ins, order->offset, m_node_db) * order->volume_orign
    : LocalSimCalculator::CalcCommissionRate(m_user_key, ins_node, order->offset, m_node_db) * order->volume_orign;
  if (order->offset == Offset::kOpen) {
    if (product_class == md::ProductClass::kOption) {
      // 期权义务方开仓(卖开),冻结保证金
      // 期权权利方开仓(买开),冻结权利金
      if (order->direction == future::Direction::kSell) {
        auto frozen_margin_rate = m_md_helper ? LocalSimCalculator::CalcOptionMarginRate(shm_ins, m_md_helper)
                                              : LocalSimCalculator::CalcOptionMarginRate(ins_node, m_node_db);
        if (isnan(frozen_margin_rate)) {
          order->status_msg = u8"下单合约缺少有效保证金率, 无法下单";
          return false;
        }
        order->_frozen_margin = frozen_margin_rate * order->volume_orign;
      } else {
        auto price = (order->price_type == future::PriceType::kAny) ? last_price : order->limit_price;
        if (isnan(price)) {
          order->status_msg = u8"下单合约无最新价, 无法下单";
          return false;
        }
        order->_frozen_premium = order->volume_orign * volume_multiple * price;
      }
    } else {
      auto frozen_margin_rate = m_md_helper ? LocalSimCalculator::CalcFutureMarginRate(m_user_key, shm_ins, m_node_db)
                                            : LocalSimCalculator::CalcFutureMarginRate(m_user_key, ins_node, m_node_db);
      if (isnan(frozen_margin_rate)) {
        order->status_msg = u8"下单合约缺少有效保证金率, 无法下单";
        return false;
      }
      order->_frozen_margin = frozen_margin_rate * order->volume_orign;
    }
    auto account = m_node_db->GetNode<Account>(m_user_key + "|0|CNY")->Latest();
    if (account->available < (order->_frozen_margin + order->_frozen_premium + order->_frozen_commission)) {
      order->status_msg = u8"账户可用余额不足, 无法开仓";
      return false;
    }
  } else if (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday
    || order->offset == Offset::kCloseToday) {
    // 期权义务方平仓(买平),应冻结权利金, 但由于会返回付出的保证金, 且保证金 > 权利金, 故无需冻结,
    // 期权权利方平仓(卖平),无需冻结.
    auto pos_node = m_node_db->GetNode<Position>(m_user_key + "|" + m_unit_id + "|" + order->Symbol());
    if (!pos_node) {
      order->status_msg = u8"账户没有当前合约的持仓, 无法平仓";
      return false;
    }
    auto avail_volume = LocalSimCalculator::CalcAvailCloseVolume(order, pos_node);
    if (avail_volume < order->volume_orign) {
      order->status_msg = u8"账户持仓量不足, 无法平仓";
      return false;
    }
  }
  return true;
}

bool LocalSimServiceImpl::CheckAliveOrderValidity(std::shared_ptr<future::OrderNode> order_node) {
  // 排除状态为kDead的委托单
  if (order_node->Latest()->status == OrderStatus::kDead)
    return false;
  // 委托单方向无效
  if (order_node->Latest()->direction == Direction::kInvalid)
    return false;
  return true;
}

std::shared_ptr<PositionNode> LocalSimServiceImpl::GetPositionNode(const std::string& instrument_id) {
  for (const auto& [_, raw_position] : m_position_view->GetNodes()) {
    if (raw_position->Latest()->instrument_id == instrument_id)
      return raw_position;
  }
  return nullptr;
}

void LocalSimServiceImpl::PushCommand(std::shared_ptr<UserCommand> command) {
  m_strand.post([=]() {
    m_command_queue.push(command);
  });
}

