int JeesUnitPositionAccountView::RunOnce() {
  int ret = 0;
  // 处理平仓记录
  for (auto iter = m_close_log_cache.begin(); iter != m_close_log_cache.end();) {
    auto key = iter->first;
    if (ProcessCloseLogCache(key)) {
      iter = m_close_log_cache.erase(iter);
      ++ret;
    } else {
      ++iter;
    }
  }
  for (const auto& [_, pos_node] : m_position_view->GetNodes()) {
    auto position = pos_node->Latest();
    auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
    if (ins.has_value() && !std::isnan(ins->last_price) && ins->last_price != position->last_price
      && ins->product_class != md::ProductClass::kCombine && ins->CheckQuote(m_trading_day)) {
      ++ret;
      m_service->m_node_db->ReplaceRecord<Position>(
        position->GetKey(), [this](std::shared_ptr<Position> calc_position) {
          UpdatePositionProfit(calc_position);
        });
    }
  }
  if (ret > 0)
    UpdateAccountProfit();
  return ret;
}

