void JeesSpiHandler::OnRtnOrder(CThostFtdcOrderField* pOrder) {
  LogCtpRtn(m_logger, "OnRtnOrder", pOrder);
  if (pOrder && pOrder->ContingentCondition != THOST_FTDC_CC_Immediately)
    return;
  // todo: 这里push时如果遇到缓冲区满，应反复重试直至填入成功
  PushSpiMessage(MakeSpiMsg<CThostFtdcOrderField>(SpiMessage::Tag::OnRtnOrder, pOrder));
}

