class JeesUnitLogin : public FuncUnit {
 public:
  JeesUnitLogin(JeesServiceImpl* service, structlog::Logger& parent_logger);

  void InitAndLogin(std::shared_ptr<UserCommand> command);

  void OnFrontConnected(std::shared_ptr<SpiMessage> msg);

