 * @file jees_settlement_info.h
 * @brief Jees 结算单服务
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_JEES_SETTLEMENT_INFO_H
#define FCLIB_JEES_SETTLEMENT_INFO_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <memory>
#include <string>
#include <map>
#include <optional>
#include "structlog/structlog.h"
#include "fclib/command.h"
#include "jees_func_unit.h"
#include "model_jees.h"

namespace fclib {
class CommandManager;
namespace future {
namespace jees {
class JeesServiceImpl;
class JeesQueryPlanner;

/**
 * JeesUnitSettlementInfo 是历史结算单查询服务组件. 它负责执行 QuerySettlementInfo 指令.
 *
 * * 查询成功时, 将完整的结算单字符串放入 QuerySettlementInfo 指令的 result_msg 字段.
 * * 查询失败时, 将错误码放入 QuerySettlementInfo 的 result_code 字段, result_msg 字段给出错误原因.
 */
class JeesUnitSettlementInfo : public FuncUnit {
 public:
  JeesUnitSettlementInfo(JeesServiceImpl* service, structlog::Logger& parent_logger);

  void ReqQrySettlementInfo(std::shared_ptr<UserCommand> command);

  void OnRspQrySettlementInfo(std::shared_ptr<SpiMessage> msg);

  void RequireQrySettlementInfoConfirm();

  void OnRspQrySettlementInfoConfirm(std::shared_ptr<SpiMessage> msg);

  void ReqSettlementInfoConfirm(std::shared_ptr<UserCommand> command);

  void OnRspSettlementInfoConfirm(std::shared_ptr<SpiMessage> msg);

  void OnRspUserLogin(std::shared_ptr<SpiMessage> msg);

  int RunOnce() override;

  std::optional<CThostFtdcRspUserLoginField> m_session;

  /**
   * 结算单信息汇集合并. 结算单以多个数据包分段返回, 需要拼装成完整串.
   *
   * KEY: RequestID, VALUE: 结算单原始文本(gb2312)
   */
  std::map<int, std::string> m_rsp_settlement_info;

  JeesServiceImpl* m_service = nullptr;
  structlog::Logger m_logger;
  JeesQueryPlanner* m_query_planner = nullptr;
};

}  // namespace jees
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_JEES_SETTLEMENT_INFO_H

