bool StringToTag(SpiMessage::Tag* tag, const std::string& str) {
  static std::map<std::string, SpiMessage::Tag> tag_map = {// 基础连接相关
    {"OnFrontConnected", SpiMessage::Tag::OnFrontConnected},
    {"OnFrontDisconnected", SpiMessage::Tag::OnFrontDisconnected}, {"OnRspError", SpiMessage::Tag::OnRspError},

    // 认证与登录相关
    {"OnRspAuthenticate", SpiMessage::Tag::OnRspAuthenticate}, {"OnRspUserLogin", SpiMessage::Tag::OnRspUserLogin},

    // 查询相关
    {"OnRspQryInvestor", SpiMessage::Tag::OnRspQryInvestor},

    // 密码修改相关
    {"OnRspUserPasswordUpdate", SpiMessage::Tag::OnRspUserPasswordUpdate},
    {"OnRspTradingAccountPasswordUpdate", SpiMessage::Tag::OnRspTradingAccountPasswordUpdate},

    // 结算单相关
    {"OnRspQrySettlementInfoConfirm", SpiMessage::Tag::OnRspQrySettlementInfoConfirm},
    {"OnRspSettlementInfoConfirm", SpiMessage::Tag::OnRspSettlementInfoConfirm},
    {"OnRspQrySettlementInfo", SpiMessage::Tag::OnRspQrySettlementInfo},

    // 报单相关
    {"OnRtnOrder", SpiMessage::Tag::OnRtnOrder}, {"OnRspQryOrder", SpiMessage::Tag::OnRspQryOrder},
    {"OnRtnTrade", SpiMessage::Tag::OnRtnTrade}, {"OnRspQryTrade", SpiMessage::Tag::OnRspQryTrade},

    // 持仓与资金相关
    {"OnRspQryInvestorPosition", SpiMessage::Tag::OnRspQryInvestorPosition},
    {"OnRspQryTradingAccount", SpiMessage::Tag::OnRspQryTradingAccount},

    // 银期转账相关
