    {"OnErrRtnBankToFutureByFuture", SpiMessage::Tag::OnErrRtnBankToFutureByFuture},
    {"OnErrRtnFutureToBankByFuture", SpiMessage::Tag::OnErrRtnFutureToBankByFuture},
    {"OnRspFromBankToFutureByFuture", SpiMessage::Tag::OnRspFromBankToFutureByFuture},
    {"OnRspFromFutureToBankByFuture", SpiMessage::Tag::OnRspFromFutureToBankByFuture},
    {"OnRspQueryBankAccountMoneyByFuture", SpiMessage::Tag::OnRspQryBankBalance},
