JeesUnitRate::JeesUnitRate(JeesServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("unit_login", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryCommission(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentCommissionRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentCommissionRate(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryOptionInstrCommRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryOptionInstrCommRate(msg);
    });
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryMargin(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentMarginRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentMarginRate(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryOptionInstrTradeCost, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryOptionInstrTradeCost(msg);
    });
}

void JeesUnitRate::ReqQryCommission(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_command_manager->Update(command))
    m_service->m_command_manager->Store(command);
  auto qry = std::static_pointer_cast<QueryCommissionRate>(command);
  auto key = "ReqQryCommission" + qry->instrument_id;
  if (m_service->m_query_planner.AlreadyInQueue(key)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  if (!qry->instrument_id.empty()) {
    auto ins = m_service->m_md_helper->GetShmInstrument(qry->exchange_id + "." + qry->instrument_id, true);
    if (ins->product_class == md::ProductClass::kOption) {
      auto field = std::make_shared<CThostFtdcQryOptionInstrCommRateField>();
      memset(field.get(), 0, sizeof(CThostFtdcQryOptionInstrCommRateField));
      strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
      strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
      strcpy_x(field->InstrumentID, qry->instrument_id);
      strcpy_x(field->ExchangeID, qry->exchange_id);
      int request_id = m_service->GenerateRequestID();
      m_service->m_command_manager->SetCommandId(command, std::to_string(request_id));
      m_service->m_query_planner.AddTask(key, JeesQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
        auto ret = m_service->m_api->ReqQryOptionInstrCommRate(field.get(), request_id);
        if (ret >= 0)
          LogCtpReq(m_logger, "ReqQryOptionInstrCommRate", field.get(), request_id, ret);
        return ret;
      });
      return;
    }
  }
  auto field = std::make_shared<CThostFtdcQryInstrumentCommissionRateField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryInstrumentCommissionRateField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  strcpy_x(field->ExchangeID, qry->exchange_id);
  int request_id = m_service->GenerateRequestID();
  m_service->m_query_planner.AddTask(key, JeesQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInstrumentCommissionRate(field.get(), request_id);
    if (ret >= 0) {
      LogCtpReq(m_logger, "ReqQryInstrumentCommissionRate", field.get(), request_id, ret);
      m_service->SetReqResponse(command, request_id, ret);
    }
    return ret;
  });
}

void JeesUnitRate::OnRspQryInstrumentCommissionRate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast)
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  if (!msg->pMainField)
    return;
  auto rate_field = std::static_pointer_cast<CThostFtdcInstrumentCommissionRateField>(msg->pMainField);
  UpdateCommission(rate_field);
  if (!req)
    return;
  /** 查询费率返回的数据,可能是按合约设的,也可能是按品种.如果查询是合约,返回是品种,则本地创建一条合约的费率*/
  auto qry = std::static_pointer_cast<QueryCommissionRate>(req);
  if (!qry->instrument_id.empty() && qry->instrument_id != std::string(rate_field->InstrumentID)) {
    auto new_filed = std::make_shared<CThostFtdcInstrumentCommissionRateField>(*rate_field);
    strcpy_x(new_filed->InstrumentID, qry->instrument_id);
    UpdateCommission(new_filed);
  }
}

void JeesUnitRate::UpdateCommission(std::shared_ptr<CThostFtdcInstrumentCommissionRateField> commission) {
  auto rate_key = m_service->m_user_key + "|" + std::string(commission->InstrumentID);
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->commission_rate_open = (UnitRate(commission->OpenRatioByMoney, commission->OpenRatioByVolume));
    rate_node->commission_rate_close = (UnitRate(commission->CloseRatioByMoney, commission->CloseRatioByVolume));
    rate_node->commission_rate_close_today =
      (UnitRate(commission->CloseTodayRatioByMoney, commission->CloseTodayRatioByVolume));
    rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = std::string(commission->InstrumentID);
    rate_node->exchange_id = std::string(commission->ExchangeID);
    auto exchange_id =
      m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
    if (exchange_id.has_value()) {
      rate_node->exchange_id = exchange_id->data();
    }
  });
}

void JeesUnitRate::OnRspQryOptionInstrCommRate(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    auto qry = std::static_pointer_cast<QueryCommissionRate>(req);
    auto commission = std::static_pointer_cast<CThostFtdcOptionInstrCommRateField>(msg->pMainField);
    if (!qry->instrument_id.empty() && qry->instrument_id != std::string(commission->InstrumentID)) {
      auto rate_key = m_service->m_user_key + "|" + qry->instrument_id;
      m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
        rate_node->commission_rate_open = (UnitRate(commission->OpenRatioByMoney, commission->OpenRatioByVolume));
        rate_node->commission_rate_close = (UnitRate(commission->CloseRatioByMoney, commission->CloseRatioByVolume));
        rate_node->commission_rate_close_today =
          (UnitRate(commission->CloseTodayRatioByMoney, commission->CloseTodayRatioByVolume));
        rate_node->commission_rate_exec = (UnitRate(commission->StrikeRatioByMoney, commission->StrikeRatioByVolume));
        rate_node->user_key = m_service->m_user_key;
        rate_node->instrument_id = qry->instrument_id;
        rate_node->exchange_id = std::string(commission->ExchangeID);
      });
    }
    auto rate_key = m_service->m_user_key + "|" + std::string(commission->InstrumentID);
    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->commission_rate_open = (UnitRate(commission->OpenRatioByMoney, commission->OpenRatioByVolume));
      rate_node->commission_rate_close = (UnitRate(commission->CloseRatioByMoney, commission->CloseRatioByVolume));
      rate_node->commission_rate_close_today =
        (UnitRate(commission->CloseTodayRatioByMoney, commission->CloseTodayRatioByVolume));
      rate_node->commission_rate_exec = (UnitRate(commission->StrikeRatioByMoney, commission->StrikeRatioByVolume));
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = std::string(commission->InstrumentID);
      rate_node->exchange_id = std::string(commission->ExchangeID);
    });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    if (req) {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  }
}

void JeesUnitRate::ReqQryMargin(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  auto key = "ReqQryMargin" + qry->instrument_id + (qry->hedge_flag == OrderHedgeFlag::kSpeculation ? "S" : "H");
  if (m_service->m_query_planner.AlreadyInQueue(key))
    return;
  if (!qry->instrument_id.empty()) {
    auto product_class = m_service->m_md_helper->GetShmInstrumentField(
      qry->exchange_id + "." + qry->instrument_id, &shm::ShmInstrument::product_class, true);
    if (product_class == md::ProductClass::kOption) {
      auto field = std::make_shared<CThostFtdcQryOptionInstrTradeCostField>();
      memset(field.get(), 0, sizeof(CThostFtdcQryOptionInstrTradeCostField));
      strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
      strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
      strcpy_x(field->InstrumentID, qry->instrument_id);
      strcpy_x(field->ExchangeID, qry->exchange_id);
      ConvertToSfitHedgeFlag(qry->hedge_flag, &field->HedgeFlag);
      int request_id = m_service->GenerateRequestID();
      m_service->m_command_manager->SetCommandId(command, std::to_string(request_id));
      m_service->m_query_planner.AddTask(key, JeesQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
        auto ret = m_service->m_api->ReqQryOptionInstrTradeCost(field.get(), request_id);
        if (ret >= 0)
          LogCtpReq(m_logger, "ReqQryOptionInstrTradeCost", field.get(), request_id, ret);
        return ret;
      });
      return;
    }
  }
  auto field = std::make_shared<CThostFtdcQryInstrumentMarginRateField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryInstrumentMarginRateField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  strcpy_x(field->ExchangeID, qry->exchange_id);
  ConvertToSfitHedgeFlag(qry->hedge_flag, &field->HedgeFlag);
  int request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, std::to_string(request_id));
  m_service->m_query_planner.AddTask(key, JeesQueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInstrumentMarginRate(field.get(), request_id);
    if (ret >= 0)
      LogCtpReq(m_logger, "ReqQryInstrumentMarginRate", field.get(), request_id, ret);
    return ret;
  });
}

void JeesUnitRate::OnRspQryInstrumentMarginRate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
  if (!msg->pMainField)
    return;
  auto margin_rate = std::static_pointer_cast<CThostFtdcInstrumentMarginRateField>(msg->pMainField);
  UpdateMargin(margin_rate);
  if (!req)
    return;
  auto qry = std::static_pointer_cast<QueryMarginRate>(req);
  if (!qry->instrument_id.empty() && qry->instrument_id != std::string(margin_rate->InstrumentID)) {
    auto new_field = std::make_shared<CThostFtdcInstrumentMarginRateField>(*margin_rate);
    strcpy_x(new_field->InstrumentID, qry->instrument_id);
    UpdateMargin(new_field);
  }
}

void JeesUnitRate::UpdateMargin(std::shared_ptr<CThostFtdcInstrumentMarginRateField> margin_rate) {
  auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = std::string(margin_rate->InstrumentID);
    rate_node->exchange_id = std::string(margin_rate->ExchangeID);
    if (rate_node->exchange_id.empty()) {
      auto exchange_id =
        m_service->m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
      if (exchange_id.has_value()) {
        rate_node->exchange_id = exchange_id->data();
      }
    }
    if (margin_rate->HedgeFlag == THOST_FTDC_HF_Speculation || margin_rate->HedgeFlag == '\0') {
      rate_node->margin_rate_long_spec =
        UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume);
      rate_node->margin_rate_short_spec =
        UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume);
    } else {
      rate_node->margin_rate_long_other =
        UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume);
      rate_node->margin_rate_short_other =
        UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume);
    }
  });
}

void JeesUnitRate::OnRspQryOptionInstrTradeCost(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto margin_rate = std::static_pointer_cast<CThostFtdcOptionInstrTradeCostField>(msg->pMainField);
    auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);
    m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = std::string(margin_rate->InstrumentID);
      rate_node->exchange_id = std::string(margin_rate->ExchangeID);
      double rate = (std::max)((margin_rate->FixedMargin + margin_rate->Royalty), margin_rate->MiniMargin);
      if (margin_rate->HedgeFlag == '\0') {
        rate_node->margin_rate_short_other.volume_rate = rate;
        rate_node->margin_rate_short_spec.volume_rate = rate;
      } else if (margin_rate->HedgeFlag == THOST_FTDC_HF_Speculation) {
        rate_node->margin_rate_short_spec.volume_rate = rate;
      } else {
        rate_node->margin_rate_short_other.volume_rate = rate;
      }
    });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    if (req) {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  }
}

