void JeesServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: 杰宜斯柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

int JeesServiceImpl::RunOnce() {
  // api运转一次
  m_query_planner.RunOnce();
  int msg_count = 0;
  for (auto f : m_func_units)
    msg_count += f->RunOnce();

  std::shared_ptr<SpiMessage> msg;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    if (!msg->bIsLast) {
      m_data_cache[msg->tag].push(msg);
      continue;
    }
    auto& cache = m_data_cache[msg->tag];
    while (!cache.empty()) {
      ProcessSpiMsg(cache.front());
      msg_count++;
      cache.pop();
    }
    ProcessSpiMsg(msg);
    msg_count++;
  }
  return msg_count;
}

void JeesServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_cmd_processor[tag] = processor;
}

void JeesServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

void JeesServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  m_query_planner.ProcessSpiMsg(spi_msg);
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int64_t JeesServiceImpl::GenerateOrderRef() {
  return ++m_order_ref;
}

int JeesServiceImpl::GenerateRequestID() {
  static int request_id = 0;
  return request_id++;
}

void JeesServiceImpl::BuildApi(bool subscribe_topic /* = true*/) {
  if (!m_req_login)
    return;
  DeleteApi();
  m_api = JeesServiceImpl::ThostApiCreator(m_options.log_directory.c_str());
  m_spi = new JeesSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(THOST_TERT_QUICK);
    m_api->SubscribePublicTopic(THOST_TERT_QUICK);
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    // TODO(TanYan): 增加延时
    m_api->Init();
  }
}

void JeesServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api->Release();
  m_api = nullptr;
}

void JeesServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, int request_id, int result_code) {
  SetReqResponse(c, std::to_string(request_id), result_code);
}

void JeesServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, const std::string request_key, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, request_key);
}

