EtfPositionAutoComb::EtfPositionAutoComb(std::shared_ptr<NodeDbView<Position>> position_view,
  std::shared_ptr<md::MdServiceShmHelper> md_helper, structlog::Logger& parent_logger)
  : m_position_view(position_view)
  , m_md_helper(md_helper)
  , m_logger(parent_logger.With("etf_comb", reinterpret_cast<int64_t>(this)).Clone()) {}

void EtfPositionAutoComb::CalcCombInsert(std::function<void(std::shared_ptr<future::PositionCombInsert>)> func) {
  for (auto& [key, cmd] : m_last_comb_insert) { /** 尚有指令未完成,此时应该等待完成 */
    if (cmd->result_code == 0 && cmd->status != UserCommand::Status::kFinished)
      return;
  }
  std::vector<std::shared_ptr<future::Position>> positions;
  for (auto& [key, position_node] : m_position_view->GetNodes()) {
    if (!position_node->Snap())
      continue;
    auto position = position_node->Latest();
    if (position->VolumeTotal() == 0 || position->VolumeTotal() == position->VolumeComb())
      continue;
    auto ins = m_md_helper->GetShmInstrument(position->Symbol(), true);
    auto trade_status = m_md_helper->GetShmTradeStatus(position->Symbol());
    if (trade_status != md::TradeStatus::kContinous || ins->product_class != md::ProductClass::kOption
      || (position->exchange_id != "SSE" && position->exchange_id != "SZSE"))
      continue;
    positions.push_back(std::make_shared<future::Position>(*position));
  }

  for (int i = static_cast<int>(EtfCombType::kCNSJC); i <= static_cast<int>(EtfCombType::kKKS); i++) {
    for (auto it_first = positions.begin(); it_first != positions.end(); ++it_first) {
      auto p0 = *it_first;
      if (p0->VolumeTotal() == 0 || p0->VolumeTotal() == p0->VolumeComb())
        continue;
      auto ins0 = m_md_helper->GetShmInstrument(p0->Symbol(), true);
      for (auto it_second = positions.begin(); it_second != positions.end(); ++it_second) {
        if (it_second == it_first)
          continue;
        auto p1 = *it_second;
        auto ins1 = m_md_helper->GetShmInstrument(p1->Symbol(), true);
        if (std::string_view(ins0->underlying_symbol.data()) != std::string_view(ins1->underlying_symbol.data())
          || p1->VolumeTotal() == 0 || p1->VolumeTotal() == p1->VolumeComb())
          continue;
        if (i == static_cast<int>(EtfCombType::kCNSJC)) {
          if (ins0->strike_price < ins1->strike_price && ins0->option_class == md::OptionClass::kCall
            && ins1->option_class == md::OptionClass::kCall) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kCNSJC, p0, p1))
              func(comb_insert);
            continue;
          }
        } else if (i == static_cast<int>(EtfCombType::kPXSJC)) {
          if (ins0->strike_price > ins1->strike_price && ins0->option_class == md::OptionClass::kPut
            && ins1->option_class == md::OptionClass::kPut) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kPXSJC, p0, p1))
              func(comb_insert);
            continue;
          }
        } else if (i == static_cast<int>(EtfCombType::kPNSJC)) {
          if (ins0->strike_price > ins1->strike_price && ins0->option_class == md::OptionClass::kPut
            && ins1->option_class == md::OptionClass::kPut) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kPNSJC, p0, p1))
              func(comb_insert);
            continue;
          }
        } else if (i == static_cast<int>(EtfCombType::kCXSJC)) {
          if (ins0->strike_price < ins1->strike_price && ins0->option_class == md::OptionClass::kCall
            && ins1->option_class == md::OptionClass::kCall) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kCXSJC, p0, p1))
              func(comb_insert);
            continue;
          }
        } else if (i == static_cast<int>(EtfCombType::kKS)) {
          if (fabs(ins0->strike_price - ins1->strike_price) < 0.00001 && ins0->option_class == md::OptionClass::kCall
            && ins1->option_class == md::OptionClass::kPut) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kKS, p0, p1))
              func(comb_insert);
            continue;
          }
        } else if (i == static_cast<int>(EtfCombType::kKKS)) {
          if (ins0->strike_price > ins1->strike_price && ins0->option_class == md::OptionClass::kCall
            && ins1->option_class == md::OptionClass::kPut) {
            if (auto comb_insert = GetCombInsert(EtfCombType::kKKS, p0, p1))
              func(comb_insert);
            continue;
          }
        }
      }
    }
  }
}

std::shared_ptr<future::PositionCombInsert> EtfPositionAutoComb::GetCombInsert(
  EtfCombType comb_type, std::shared_ptr<future::Position> p0, std::shared_ptr<future::Position> p1) {
  auto comb_insert = std::make_shared<PositionCombInsert>(p0->user_key);
  comb_insert->comb_direction = CombDirection::kComb;
  comb_insert->exchange_id = p0->exchange_id;
  comb_insert->instrument_id = p0->instrument_id + "&" + p1->instrument_id;
  md::Volume long_spec0 = p0->subpos_long_spec.VolumeCombLeft();
  md::Volume short_spec0 = p0->subpos_short_spec.VolumeCombLeft();
  md::Volume long_spec1 = p1->subpos_long_spec.VolumeCombLeft();
  md::Volume short_spec1 = p1->subpos_short_spec.VolumeCombLeft();
  if (comb_type == EtfCombType::kCNSJC || comb_type == EtfCombType::kPXSJC) {
    md::Volume vol = std::min(long_spec0, short_spec1);
    if (vol > 0) {
      comb_insert->volume = vol;
      comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
      comb_insert->direction = Direction::kBuy;
      p0->subpos_long_spec.volume_comb += comb_insert->volume;
      p1->subpos_short_spec.volume_comb += comb_insert->volume;
      goto end;
    }
  } else if (comb_type == EtfCombType::kPNSJC || comb_type == EtfCombType::kCXSJC) {
    md::Volume vol = std::min(short_spec0, long_spec1);
    if (vol > 0) {
      comb_insert->volume = vol;
      comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
      comb_insert->direction = Direction::kSell;
      p0->subpos_short_spec.volume_comb += comb_insert->volume;
      p1->subpos_long_spec.volume_comb += comb_insert->volume;
      goto end;
    }
  } else if (comb_type == EtfCombType::kKS || comb_type == EtfCombType::kKKS) {
    md::Volume vol = std::min(short_spec0, short_spec1);
    if (vol > 0) {
      comb_insert->volume = vol;
      comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
      comb_insert->direction = Direction::kSell;
      p0->subpos_short_spec.volume_comb += comb_insert->volume;
      p1->subpos_short_spec.volume_comb += comb_insert->volume;
      goto end;
    }
  }
  return nullptr;
end:
  auto it = m_last_comb_insert.find(comb_insert->instrument_id);
  if (it != m_last_comb_insert.end()) {
    if (it->second->result_code != 0 && it->second->result_msg.find(u8"找不到合约") != std::string::npos) {
      return nullptr;
    }
  }
  m_last_comb_insert[comb_insert->instrument_id] = comb_insert;
  return comb_insert;
}

