/*******************************************************************************
 * @file ctp_sopt_convert.cpp
 * @brief CTP_SOPT数据类型转换
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "ctp_sopt_convert.h"
#include <string>
#include <memory>
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace ctp_sopt {
void ConvertToSfitDirection(Direction d, TThostFtdcDirectionType* t) {
  if (d == Direction::kBuy) {
    *t = THOST_FTDC_D_Buy;
  } else if (d == Direction::kSell) {
    *t = THOST_FTDC_D_Sell;
  }
}

void ConvertToSfitPosiDirection(future::PosiDirection d, TThostFtdcPosiDirectionType& t) {
  if (d == PosiDirection::kNet) {
    t = THOST_FTDC_PD_Net;
  } else if (d == PosiDirection::kLong) {
    t = THOST_FTDC_PD_Long;
  } else if (d == PosiDirection::kShort) {
    t = THOST_FTDC_PD_Short;
  }
}

future::PosiDirection ConvertFromSfitPosiDirection(const TThostFtdcPosiDirectionType& t) {
  if (t == THOST_FTDC_PD_Net) {
    return future::PosiDirection::kNet;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kLong;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kShort;
  }
  return future::PosiDirection::kInvalid;
}

void ConvertToSfitExecAction(future::ExecActionType d, TThostFtdcActionTypeType& t) {
  if (d == future::ExecActionType::kExec) {
    t = THOST_FTDC_ACTP_Exec;
  } else if (d == future::ExecActionType::kAbandon) {
    t = THOST_FTDC_ACTP_Abandon;
  }
}

future::ExecActionType ConvertFromSfitExecAction(const TThostFtdcActionTypeType& t) {
  if (t == THOST_FTDC_ACTP_Exec) {
    return future::ExecActionType::kExec;
  } else {
    return future::ExecActionType::kAbandon;
  }
}

void ConvertToSfitSelfCloseAction(future::SelfCloseType d, TThostFtdcOptSelfCloseFlagType& t) {
  if (d == future::SelfCloseType::kOptionPosition) {
    t = THOST_FTDC_OSCF_CloseSelfOptionPosition;
  } else if (d == future::SelfCloseType::kReserveOptionPosition) {
    t = THOST_FTDC_OSCF_ReserveOptionPosition;
  } else {
    t = THOST_FTDC_OSCF_SellCloseSelfFuturePosition;
  }
}

future::SelfCloseType ConvertFromSfitSelfCloseAction(const TThostFtdcOptSelfCloseFlagType& t) {
  if (t == THOST_FTDC_OSCF_CloseSelfOptionPosition) {
    return future::SelfCloseType::kOptionPosition;
  } else if (t == THOST_FTDC_OSCF_ReserveOptionPosition) {
    return future::SelfCloseType::kReserveOptionPosition;
  } else if (t == THOST_FTDC_OSCF_SellCloseSelfFuturePosition) {
    return future::SelfCloseType::kSelfFuturePosition;
  } else {
    return future::SelfCloseType::kReserveFuturePosition;
  }
}

void ConvertToSfitExecOrderCloseFlag(future::ExecOrderCloseFlag d, TThostFtdcExecOrderCloseFlagType& t) {
  if (d == future::ExecOrderCloseFlag::kAutoClose) {
    t = THOST_FTDC_EOCF_AutoClose;
  } else {
    t = THOST_FTDC_EOCF_NotToClose;
  }
}

future::ExecOrderCloseFlag ConvertFromSfitExecOrderCloseFlag(const TThostFtdcExecOrderCloseFlagType& t) {
  if (t == THOST_FTDC_EOCF_AutoClose) {
    return future::ExecOrderCloseFlag::kAutoClose;
  } else {
    return future::ExecOrderCloseFlag::kNotToClose;
  }
}

future::ExecOrderResultType ConvertFromSfitExecOrderResultType(const TThostFtdcExecResultType& t) {
  switch (t) {
    case THOST_FTDC_OER_NoExec: return future::ExecOrderResultType::kNoExec;
    case THOST_FTDC_OER_Canceled: return future::ExecOrderResultType::kCanceled;
    case THOST_FTDC_OER_OK: return future::ExecOrderResultType::kSuccess;
    case THOST_FTDC_OER_NoPosition: return future::ExecOrderResultType::kNoPosition;
    case THOST_FTDC_OER_NoDeposit: return future::ExecOrderResultType::kNoDeposit;
    case THOST_FTDC_OER_NoParticipant: return future::ExecOrderResultType::kNoParticipant;
    case THOST_FTDC_OER_NoClient: return future::ExecOrderResultType::kNoClient;
    case THOST_FTDC_OER_NoInstrument: return future::ExecOrderResultType::kNoInstrument;
    case THOST_FTDC_OER_NoRight: return future::ExecOrderResultType::kNoRight;
    case THOST_FTDC_OER_InvalidVolume: return future::ExecOrderResultType::kInvalidVolume;
    case THOST_FTDC_OER_NoEnoughHistoryTrade: return future::ExecOrderResultType::kNoEnoughHistoryTrade;
    default: return future::ExecOrderResultType::kUnKnown;
  }
}

Direction ConvertFromSfitDirection(const TThostFtdcDirectionType* t) {
  if (*t == THOST_FTDC_D_Buy)
    return Direction::kBuy;
  if (*t == THOST_FTDC_D_Sell)
    return Direction::kSell;
  return Direction::kInvalid;
}

void ConvertToSfitCombDirection(future::CombDirection d, TThostFtdcCombDirectionType* t) {
  if (d == CombDirection::kComb) {
    *t = THOST_FTDC_CMDR_Comb;
  } else if (d == CombDirection::kUnComb) {
    *t = THOST_FTDC_CMDR_UnComb;
  } else {
    FCASSERT(false);
  }
}

future::CombDirection ConvertFromSfitCombDirection(const TThostFtdcCombDirectionType* t) {
  if (*t == THOST_FTDC_CMDR_Comb)
    return CombDirection::kComb;
  if (*t == THOST_FTDC_CMDR_UnComb)
    return CombDirection::kUnComb;
  return CombDirection::kDelComb;
}

Offset ConvertFromSfitOffset(const char t) {
  if (t == THOST_FTDC_OF_Open)
    return Offset::kOpen;
  if (t == THOST_FTDC_OF_CloseToday)
    return Offset::kCloseToday;
  if (t == THOST_FTDC_OF_CloseYesterday)
    return Offset::kCloseYesterday;
  return Offset::kClose;
}

void ConvertToSfitHedgeFlag(future::OrderHedgeFlag h, TThostFtdcHedgeFlagType* t) {
  if (h == OrderHedgeFlag::kArbitrage)
    t[0] = THOST_FTDC_HF_Arbitrage;
  else if (h == OrderHedgeFlag::kHedge)
    t[0] = THOST_FTDC_HF_Hedge;
  else if (h == OrderHedgeFlag::kSpeculation)
    t[0] = THOST_FTDC_HF_Speculation;
  else if (h == OrderHedgeFlag::kMarketMaker)
    t[0] = THOST_FTDC_HF_MarketMaker;
  else if (h == OrderHedgeFlag::kCovered)
    t[0] = THOST_FTDC_HF_Covered;
  else
    t[0] = THOST_FTDC_HF_Speculation;
}

OrderHedgeFlag ConvertFromSfitHedgeFlag(const TThostFtdcCombHedgeFlagType* t) {
  if (*t[0] == THOST_FTDC_HF_Speculation)
    return OrderHedgeFlag::kSpeculation;
  if (*t[0] == THOST_FTDC_HF_Arbitrage)
    return OrderHedgeFlag::kArbitrage;
  if (*t[0] == THOST_FTDC_HF_Hedge)
    return OrderHedgeFlag::kHedge;
  if (*t[0] == THOST_FTDC_HF_MarketMaker)
    return OrderHedgeFlag::kMarketMaker;
  if (*t[0] == THOST_FTDC_HF_Covered)
    return OrderHedgeFlag::kCovered;
  return OrderHedgeFlag::kSpeculation;
}

OrderHedgeFlag ConvertFromSfitHedgeFlag(const TThostFtdcHedgeFlagType* t) {
  if (*t == THOST_FTDC_HF_Speculation)
    return OrderHedgeFlag::kSpeculation;
  if (*t == THOST_FTDC_HF_Arbitrage)
    return OrderHedgeFlag::kArbitrage;
  if (*t == THOST_FTDC_HF_Hedge)
    return OrderHedgeFlag::kHedge;
  if (*t == THOST_FTDC_HF_MarketMaker)
    return OrderHedgeFlag::kMarketMaker;
  if (*t == THOST_FTDC_HF_Covered)
    return OrderHedgeFlag::kCovered;
  return OrderHedgeFlag::kSpeculation;
}

PriceType ConvertFromSfitOrderPriceType(const TThostFtdcOrderPriceTypeType* t) {
  if (*t == THOST_FTDC_OPT_AnyPrice)
    return PriceType::kAny;
  else if (*t == THOST_FTDC_OPT_LimitPrice)
    return PriceType::kLimit;
  else if (*t == THOST_FTDC_OPT_BestPrice)
    return PriceType::kBest;
  else if (*t == THOST_FTDC_OPT_FiveLevelPrice)
    return PriceType::kFiveLevel;
  return PriceType::kLimit;
}

OrderStatus ConvertFromSfitOrderStatus(const TThostFtdcOrderStatusType* t) {
  if (*t == THOST_FTDC_OST_Unknown || *t == THOST_FTDC_OST_PartTradedQueueing
    || *t == THOST_FTDC_OST_PartTradedNotQueueing || *t == THOST_FTDC_OST_NoTradeQueueing
    || *t == THOST_FTDC_OST_NoTradeNotQueueing) {
    return OrderStatus::kAlive;
  }
  return OrderStatus::kDead;
}

OrderTimeCondition ConvertFromSfitTimeCondition(const TThostFtdcTimeConditionType* t) {
  if (*t == THOST_FTDC_TC_IOC)
    return OrderTimeCondition::kIoc;
  if (*t == THOST_FTDC_TC_GFS)
    return OrderTimeCondition::kGfs;
  if (*t == THOST_FTDC_TC_GFD)
    return OrderTimeCondition::kGfd;
  if (*t == THOST_FTDC_TC_GTD)
    return OrderTimeCondition::kGtd;
  if (*t == THOST_FTDC_TC_GTC)
    return OrderTimeCondition::kGtc;
  if (*t == THOST_FTDC_TC_GFA)
    return OrderTimeCondition::kGfa;
  return OrderTimeCondition::kGfd;
}

OrderVolumeCondition ConvertFromSfitVolumeCondition(const TThostFtdcVolumeConditionType* t) {
  if (*t == THOST_FTDC_VC_AV)
    return OrderVolumeCondition::kAny;
  if (*t == THOST_FTDC_VC_CV)
    return OrderVolumeCondition::kAll;
  if (*t == THOST_FTDC_VC_MV)
    return OrderVolumeCondition::kMin;
  return OrderVolumeCondition::kAny;
}

fclib::future::ForceCloseReason ConvertFromSfitForceClose(const TThostFtdcForceCloseReasonType* t) {
  if (*t == THOST_FTDC_FCC_NotForceClose)
    return future::ForceCloseReason::kNotForceClose;
  else if (*t == THOST_FTDC_FCC_LackDeposit)
    return future::ForceCloseReason::kLackDeposit;
  else if (*t == THOST_FTDC_FCC_ClientOverPositionLimit)
    return future::ForceCloseReason::kClientOverPositionLimit;
  else if (*t == THOST_FTDC_FCC_MemberOverPositionLimit)
    return future::ForceCloseReason::kMemberOverPositionLimit;
  else if (*t == THOST_FTDC_FCC_NotMultiple)
    return future::ForceCloseReason::kNotMultiple;
  else if (*t == THOST_FTDC_FCC_Violation)
    return future::ForceCloseReason::kViolation;
  else if (*t == THOST_FTDC_FCC_Other)
    return future::ForceCloseReason::kOther;
  else if (*t == THOST_FTDC_FCC_PersonDeliv)
    return future::ForceCloseReason::kPersonDeliv;
  return future::ForceCloseReason::kNotForceClose;
}

void ConvertToSfitTimeCondition(OrderTimeCondition d, TThostFtdcTimeConditionType* t) {
  if (d == OrderTimeCondition::kGfa) {
    *t = THOST_FTDC_TC_GFA;
  } else if (d == OrderTimeCondition::kGfd) {
    *t = THOST_FTDC_TC_GFD;
  } else if (d == OrderTimeCondition::kGfs) {
    *t = THOST_FTDC_TC_GFS;
  } else if (d == OrderTimeCondition::kGtc) {
    *t = THOST_FTDC_TC_GTC;
  } else if (d == OrderTimeCondition::kGtd) {
    *t = THOST_FTDC_TC_GTD;
  } else if (d == OrderTimeCondition::kIoc) {
    *t = THOST_FTDC_TC_IOC;
  }
}

void ConvertToSfitOrderPriceType(PriceType d, TThostFtdcOrderPriceTypeType* t) {
  if (d == PriceType::kAny) {
    *t = THOST_FTDC_OPT_AnyPrice;
  } else if (d == PriceType::kBest) {
    *t = THOST_FTDC_OPT_BestPrice;
  } else if (d == PriceType::kFiveLevel) {
    *t = THOST_FTDC_OPT_FiveLevelPrice;
  } else if (d == PriceType::kLimit) {
    *t = THOST_FTDC_OPT_LimitPrice;
  }
}

void ConvertToSfitVolumeCondition(OrderVolumeCondition d, TThostFtdcVolumeConditionType* t) {
  if (d == OrderVolumeCondition::kAll) {
    *t = THOST_FTDC_VC_CV;
  } else if (d == OrderVolumeCondition::kAny) {
    *t = THOST_FTDC_VC_AV;
  } else if (d == OrderVolumeCondition::kMin) {
    *t = THOST_FTDC_VC_MV;
  }
}

void ConvertToSfitOffsetFlag(Offset d, TThostFtdcOffsetFlagType* t) {
  if (d == Offset::kClose) {
    *t = THOST_FTDC_OF_Close;
  } else if (d == Offset::kCloseToday) {
    *t = THOST_FTDC_OF_CloseToday;
  } else if (d == Offset::kCloseYesterday) {
    *t = THOST_FTDC_OF_CloseYesterday;
  } else if (d == Offset::kOpen) {
    *t = THOST_FTDC_OF_Open;
  }
}

std::shared_ptr<CThostFtdcQuoteField> FtdcInputQuoteFieldToQuoteField(std::shared_ptr<CThostFtdcInputQuoteField> origin,
  TThostFtdcSessionIDType session_id, TThostFtdcFrontIDType front_id) {
  auto target = std::make_shared<CThostFtdcQuoteField>();
  strcpy_x(target->BrokerID, origin->BrokerID);
  strcpy_x(target->UserID, origin->UserID);
  strcpy_x(target->InvestorID, origin->InvestorID);
  strcpy_x(target->ExchangeID, origin->ExchangeID);
  strcpy_x(target->InstrumentID, origin->InstrumentID);
  strcpy_x(target->QuoteRef, origin->QuoteRef);
  strcpy_x(target->AskOrderRef, origin->AskOrderRef);
  strcpy_x(target->BidOrderRef, origin->BidOrderRef);
  target->AskPrice = origin->AskPrice;
  target->BidPrice = origin->BidPrice;
  target->AskVolume = origin->AskVolume;
  target->BidVolume = origin->BidVolume;
  target->RequestID = origin->RequestID;
  target->AskOffsetFlag = origin->AskOffsetFlag;
  target->BidOffsetFlag = origin->BidOffsetFlag;
  target->AskHedgeFlag = origin->AskHedgeFlag;
  target->BidHedgeFlag = origin->BidHedgeFlag;
  target->SessionID = session_id;
  target->FrontID = front_id;
  target->QuoteStatus = THOST_FTDC_OST_Unknown;
  return target;
}

void ConvertToSfitOrderField(const std::shared_ptr<InsertOrder> d, std::shared_ptr<CThostFtdcInputOrderField> field) {
  strcpy_x(field->InstrumentID, d->instrument_id);
  strcpy_x(field->ExchangeID, d->exchange_id);
  strcpy_x(field->OrderRef, std::to_string(d->order_ref).c_str());
  ConvertToSfitDirection(d->direction, &field->Direction);
  ConvertToSfitTimeCondition(d->time_condition, &field->TimeCondition);
  ConvertToSfitOrderPriceType(d->price_type, &field->OrderPriceType);
  ConvertToSfitVolumeCondition(d->volume_condition, &field->VolumeCondition);
  ConvertToSfitOffsetFlag(d->offset, &field->CombOffsetFlag[0]);
  if (field->OrderPriceType == THOST_FTDC_OPT_LimitPrice) {
    field->LimitPrice = d->limit_price;
  } else {
    field->LimitPrice = 0;
  }
  ConvertToSfitHedgeFlag(d->hedge_flag, &field->CombHedgeFlag[0]);
  field->MinVolume = d->min_volume;
  field->IsSwapOrder = d->is_swap_order;
  field->VolumeTotalOriginal = d->volume;
  field->ForceCloseReason = THOST_FTDC_FCC_NotForceClose;
  field->ContingentCondition = THOST_FTDC_CC_Immediately;
}

md::TradeStatus ConvertFromSfitInstrumentStatusType(const TThostFtdcInstrumentStatusType* t) {
  if (*t == THOST_FTDC_IS_BeforeTrading) {
    return md::TradeStatus::kBeforeTrading;
  } else if (*t == THOST_FTDC_IS_NoTrading) {
    return md::TradeStatus::kNoTrading;
  } else if (*t == THOST_FTDC_IS_Continous) {
    return md::TradeStatus::kContinous;
  } else if (*t == THOST_FTDC_IS_AuctionOrdering) {
    return md::TradeStatus::kAuctionOrdering;
  } else if (*t == THOST_FTDC_IS_AuctionBalance) {
    return md::TradeStatus::kAuctionBalance;
  } else if (*t == THOST_FTDC_IS_AuctionMatch) {
    return md::TradeStatus::kAuctionMatch;
  } else if (*t == THOST_FTDC_IS_Closed) {
    return md::TradeStatus::kClosed;
  }
  return md::TradeStatus::kUnknown;
}

std::string ToFclibOrderId(const TThostFtdcOrderRefType order_ref, const TThostFtdcSessionIDType session_id,
  const TThostFtdcFrontIDType front_id) {
  return std::string(order_ref) + "|" + std::to_string(session_id) + "|" + std::to_string(front_id);
}

std::string GetDisConnectReason(int id) {
  if (id == 4097)
    return u8"网络读失败";
  if (id == 4098)
    return u8"网络写失败";
  if (id == 8193)
    return u8"接收心跳超时";
  if (id == 8194)
    return u8"发送心跳超时";
  if (id == 8195)
    return u8"收到错误报文";
  return u8"前置机断连";
}

