void CtpSoptUnitBank::OnRspQryTransferSerial(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto transferserial = std::static_pointer_cast<CThostFtdcTransferSerialField>(msg->pMainField);
    auto target_transferserial = std::make_shared<TransferLog>();
    target_transferserial->user_key = m_service->m_user_key;
    target_transferserial->amount = transferserial->TradeAmount;
    target_transferserial->currency = transferserial->CurrencyID;
    if (target_transferserial->currency.empty())
      target_transferserial->currency = "CNY";
    target_transferserial->error_id = transferserial->ErrorID;
    target_transferserial->error_msg = GbkToUtf8(transferserial->ErrorMsg);
    target_transferserial->bank_account = GbkToUtf8(transferserial->BankAccount);
    std::string tradecode = transferserial->TradeCode;
    if (tradecode == "204002") {
      target_transferserial->trade_type = u8"查询银行余额";
    } else if (tradecode == "204999") {
      target_transferserial->trade_type = u8"查询转账明细";
    } else if (tradecode == "202001" || tradecode == "102001") {
      target_transferserial->trade_type = u8"入金";
    } else if (tradecode == "202002" || tradecode == "102002") {
      target_transferserial->trade_type = u8"出金";
    }
    target_transferserial->bank_serial = transferserial->BankSerial;
    target_transferserial->future_serial = transferserial->FutureSerial;
    target_transferserial->bank_id = transferserial->BankID;
    target_transferserial->bank_branch_id = transferserial->BankBranchID;
    if (transferserial->TradeDate[0] != '\0' && transferserial->TradeTime[0] != '\0') {
      target_transferserial->date_time = StringToEpochNano(transferserial->TradeDate, transferserial->TradeTime);
    }
    m_service->m_node_db->ReplaceRecord<TransferLog>(target_transferserial);
  }
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitBank::ReqQryBankBalance(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryBankBalance>(m_service->m_command_manager->Update(command));
  int request_id = qry->query_request_id > 0 ? qry->query_request_id : m_service->GenerateRequestID();
  CThostFtdcReqQueryAccountField field;
  memset(&field, 0, sizeof(CThostFtdcReqQueryAccountField));
  strcpy_x(field.TradeCode, "204002");
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.BankID, qry->bank_id);
  strcpy_x(field.BankBranchID, "0000");
  field.SecuPwdFlag = THOST_FTDC_BPWDF_BlankCheck;  // 核对密码
  field.BankPwdFlag = THOST_FTDC_BPWDF_NoCheck;     // 核对密码
  field.VerifyCertNoFlag = THOST_FTDC_YNI_No;
  strcpy_x(field.AccountID, m_service->m_req_login->user_id);
  strcpy_x(field.Password, qry->future_password);
  strcpy_x(field.BankPassWord, qry->bank_password);
  strcpy_x(field.CurrencyID, qry->currency);
  field.RequestID = request_id;
  auto ret = m_service->m_api->ReqQueryBankAccountMoneyByFuture(&field, request_id);
  LogCtpSoptReq(m_logger, "ReqQueryBankAccountMoneyByFuture", &field, request_id, ret);
  if (ret == 0) {
    m_service->SetReqResponse(command, request_id, ret);
  } else {
    SetCommandFinished(command, ret, u8"指令发送失败");
  }
}

void CtpSoptUnitBank::OnRspQryBankBalance(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitBank::OnRtnBankBalance(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto bankbalance = std::static_pointer_cast<CThostFtdcNotifyQueryAccountField>(msg->pMainField);
    if (bankbalance->ErrorID == 0) {
      auto target_bankbalance = std::make_shared<BankBalance>();
      target_bankbalance->user_key = m_service->m_user_key;
      target_bankbalance->bank_account = bankbalance->BankAccount;
      target_bankbalance->bank_fetch_amount = bankbalance->BankFetchAmount;
      target_bankbalance->bank_use_amount = bankbalance->BankUseAmount;
      target_bankbalance->currency = bankbalance->CurrencyID;
      target_bankbalance->bank_id = bankbalance->BankID;
      target_bankbalance->bank_branch_id = bankbalance->BankBranchID;
      m_service->m_node_db->ReplaceRecord<BankBalance>(target_bankbalance);
    }
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, bankbalance->ErrorID, GbkToUtf8(bankbalance->ErrorMsg));
  }
}

int CtpSoptUnitBank::RunOnce() {
  if (m_bank_name_map.empty())
    return 0;
  auto& bank_node_map = m_bank_view->GetNodes();
  for (auto& [key, bank_node] : bank_node_map) {
    if (!bank_node->Snap())
      continue;
    if (!bank_node->Snap()->bank_name.empty() || bank_node->Snap()->bank_id.empty())
      continue;
    auto contract_bank = m_bank_name_map[bank_node->Snap()->bank_id];
    if (!contract_bank)
      continue;
    m_service->m_node_db->ReplaceRecord<Bank>(key, [&](std::shared_ptr<future::Bank> bank) {
      bank->bank_name = GbkToUtf8(contract_bank->BankName);
      m_bank_name_map.erase(bank->bank_id);
    });
  }
  return 1;
}

