CtpSoptUnitSettlementInfo::CtpSoptUnitSettlementInfo(CtpSoptServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("settlement_info_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterCommandProcessor(QuerySettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQrySettlementInfo(command);
  });
  m_service->RegisterCommandProcessor(ConfirmSettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqSettlementInfoConfirm(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQrySettlementInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQrySettlementInfo(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQrySettlementInfoConfirm, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQrySettlementInfoConfirm(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspSettlementInfoConfirm, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspSettlementInfoConfirm(msg);
  });
}

void CtpSoptUnitSettlementInfo::ReqQrySettlementInfo(std::shared_ptr<UserCommand> command) {
  int request_id = command ? m_service->GenerateRequestID() : -1;
  auto key = "QuerySettlementInfo" + std::to_string(request_id);
  auto field = std::make_shared<CThostFtdcQrySettlementInfoField>();
  memset(field.get(), 0, sizeof(CThostFtdcQrySettlementInfoField));
  strcpy_x(field->BrokerID, m_session.value().BrokerID);
  strcpy_x(field->AccountID, m_session.value().UserID);
  strcpy_x(field->InvestorID, m_session.value().UserID);
  if (command) {
    m_service->m_command_manager->Update(command);
    auto qry = std::static_pointer_cast<QuerySettlementInfo>(command);
    strcpy_x(field->TradingDay, qry->trading_day);
    m_service->m_command_manager->SetCommandId(command, key);
  }
  m_query_planner->AddTask(key, QueryPriority::kImmediately, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQrySettlementInfo(field.get(), request_id);
    if (ret >= 0)
      LogCtpSoptReq(m_logger, "ReqQrySettlementInfo", field.get(), request_id, ret);
    return ret;
  });
}

void CtpSoptUnitSettlementInfo::OnRspQrySettlementInfo(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pSettlementInfo = std::static_pointer_cast<CThostFtdcSettlementInfoField>(msg->pMainField);
    m_rsp_settlement_info[msg->nRequestID].append(pSettlementInfo->Content);
  }
  if (msg->bIsLast) {
    std::string rsp_info;
    if (msg->RspInfo.ErrorID == 0) {
      rsp_info = GbkToUtf8(m_rsp_settlement_info[msg->nRequestID]);
      m_rsp_settlement_info.erase(msg->nRequestID);
    } else {
      rsp_info = GbkToUtf8(msg->RspInfo.ErrorMsg);
    }
    if (msg->nRequestID == -1) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_info) {
          target_info->content = rsp_info;
          target_info->user_key = m_service->m_user_key;
          target_info->backend = BackEnd::kCtpSopt;
          target_info->confirm_status = ConfirmStatus::kWaitingConfirm;
        });
    } else {
      auto req = m_service->m_command_manager->Update("QuerySettlementInfo" + std::to_string(msg->nRequestID));
      SetCommandFinished(req, msg->RspInfo.ErrorID, rsp_info);
    }
  }
}

void CtpSoptUnitSettlementInfo::RequireQrySettlementInfoConfirm() {
  auto field = std::make_shared<CThostFtdcQrySettlementInfoConfirmField>();
  memset(field.get(), 0, sizeof(CThostFtdcQrySettlementInfoConfirmField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id.c_str());
  strcpy_x(field->AccountID, m_service->m_req_login->user_id.c_str());
  strcpy(field->CurrencyID, "CNY");  // NOLINT
  m_query_planner->AddTask(
    "RequireQrySettlementInfoConfirm", QueryPriority::kNormal, m_service->GenerateRequestID(), [=](int request_id) {
      auto ret = m_service->m_api->ReqQrySettlementInfoConfirm(field.get(), request_id);
      if (ret >= 0)
        LogCtpSoptReq(m_logger, "ReqQrySettlementInfoConfirm", field.get(), request_id, ret);
      return ret;
    });
}

void CtpSoptUnitSettlementInfo::OnRspQrySettlementInfoConfirm(std::shared_ptr<SpiMessage> msg) {
  auto origin_confirm = std::static_pointer_cast<CThostFtdcSettlementInfoConfirmField>(msg->pMainField);
  if (origin_confirm && origin_confirm->ConfirmDate >= m_service->m_trading_day) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_confirm) {
        target_confirm->confirm_date = origin_confirm->ConfirmDate;
        target_confirm->confirm_time = origin_confirm->ConfirmTime;
        target_confirm->confirm_status = ConfirmStatus::kConfirmed;
        target_confirm->currency = origin_confirm->CurrencyID;
        target_confirm->user_key = m_service->m_user_key;
        target_confirm->backend = BackEnd::kCtpSopt;
      });
  } else {
    if (m_service->m_options.auto_settlement_confirm) {
      auto confirm = std::make_shared<future::ConfirmSettlementInfo>(m_service->m_user_key);
      m_service->m_command_manager->Store(confirm);
      ReqSettlementInfoConfirm(confirm);
    } else {
      ReqQrySettlementInfo(nullptr);
    }
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitSettlementInfo::ReqSettlementInfoConfirm(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<ConfirmSettlementInfo>(m_service->m_command_manager->Update(command));
  CThostFtdcSettlementInfoConfirmField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  int request_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqSettlementInfoConfirm(&field, request_id);
  LogCtpSoptReq(m_logger, "ReqSettlementInfoConfirm", &field, request_id, ret);
  m_service->SetReqResponse(command, request_id, ret);
  m_service->m_command_manager->SetCommandId(qry, "ReqSettlementInfoConfirm");
}

void CtpSoptUnitSettlementInfo::OnRspSettlementInfoConfirm(std::shared_ptr<SpiMessage> msg) {
  auto origin_confirm = std::static_pointer_cast<CThostFtdcSettlementInfoConfirmField>(msg->pMainField);
  if (origin_confirm) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> target_confirm) {
        target_confirm->confirm_date = origin_confirm->ConfirmDate;
        target_confirm->confirm_time = origin_confirm->ConfirmTime;
        target_confirm->confirm_status = ConfirmStatus::kConfirmed;
        target_confirm->currency = origin_confirm->CurrencyID;
        target_confirm->user_key = m_service->m_user_key;
        target_confirm->backend = BackEnd::kCtpSopt;
      });
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("ReqSettlementInfoConfirm");
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitSettlementInfo::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
    m_session = *rsp;
    if (!m_service->m_req_change_password_before_login)
      RequireQrySettlementInfoConfirm();
  }
}

