void CtpSoptServiceImpl::SetReqResponse(
  std::shared_ptr<UserCommand> c, const std::string request_key, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, request_key);
}

