void CtpSoptSpiHandler::OnRspError(CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  m_logger.With("request_id", nRequestID).With("is_last", bIsLast);
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnRspError;
  msg->nRequestID = nRequestID;
  msg->bIsLast = bIsLast;
  if (pRspInfo) {
    m_logger.With("ErrorID", pRspInfo->ErrorID).With("ErrorMsg", GbkToUtf8(pRspInfo->ErrorMsg));
