CtpSoptUnitInsertCancelOrder::CtpSoptUnitInsertCancelOrder(
  CtpSoptServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_alive_order_view = m_service->m_node_db->CreateView<future::Order>(
    ReuseViewKey::kAliveOrder, true, [](std::shared_ptr<const future::Order> order) -> bool {
      return order->status == future::OrderStatus::kAlive;
    });
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderAction(msg);
  });
}

void CtpSoptUnitInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  // 下单
  auto field = std::make_shared<CThostFtdcInputOrderField>();
  strcpy_x(field->BrokerID, m_last_session.value().BrokerID);
  strcpy_x(field->UserID, m_last_session.value().UserID);
  strcpy_x(field->InvestorID, m_last_session.value().UserID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field->IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field->MacAddress, m_service->m_req_login->client_mac_address);

  if (req->request_id != 0)
    field->RequestID = req->request_id;
  ConvertToSfitOrderField(req, field);
  m_service->m_send_time[req->order_id] = NowAsEpochNano();
  // 报单
  int ret = m_service->m_api->ReqOrderInsert(field.get(), 0);
  LogCtpSoptReq(m_logger, "ReqOrderInsert", field.get(), 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOrder" + req->order_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpSoptUnitInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  req->status = UserCommand::Status::kStarted;
  auto it = m_alive_orders.find(req->order_id);
  if (it == m_alive_orders.end()) {
    SetCommandFinished(req, -1, u8"fclib: 报单编号不存在");
    return;
  }
  CThostFtdcOrderField& order = it->second;
  CThostFtdcInputOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_last_session.value().BrokerID);
  strcpy_x(field.UserID, m_last_session.value().UserID);
  strcpy_x(field.InvestorID, m_last_session.value().UserID);
  strcpy_x(field.OrderRef, order.OrderRef);
  strcpy_x(field.ExchangeID, order.ExchangeID);
  strcpy_x(field.InstrumentID, order.InstrumentID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  field.OrderActionRef = ++m_order_action_ref;
  field.SessionID = order.SessionID;
  field.FrontID = order.FrontID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  field.LimitPrice = 0;
  field.VolumeChange = 0;
  int ret = m_service->m_api->ReqOrderAction(&field, 0);
  LogCtpSoptReq(m_logger, "ReqOrderAction", &field, 0, ret);
  m_order_cancel[req->order_id] = field.OrderActionRef;
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::to_string(field.OrderActionRef));
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpSoptUnitInsertCancelOrder::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
    m_last_session = *rsp;
  }
}

void CtpSoptUnitInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_user_key.find("STRESS-TESTING-100") != std::string::npos)
    return;
  LOG_ASSERT(m_last_session.has_value());
  auto order = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(order->OrderRef, order->SessionID, order->FrontID);
  if (order->OrderRef[0] == '\0')
    order_id = order->OrderSysID;
  if (order_id.empty())
    return;
  // alive 委托单都放入 m_alive_orders, 以备撤单时使用.
  if (order->OrderStatus == THOST_FTDC_OST_Canceled || order->OrderStatus == THOST_FTDC_OST_AllTraded) {
    m_alive_orders.erase(order_id);
  } else {
    m_alive_orders[order_id] = *order;
  }
  // 反馈指令执行结果
  if (order->OrderStatus == THOST_FTDC_OST_Canceled) {
    auto it = m_order_cancel.find(order_id);
    if (it != m_order_cancel.end()) {
      auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(it->second));
      m_order_cancel.erase(it);
      if (req) {
        SetCommandFinished(req, 0, u8"成功");
        return;
      }
    }
  }
  if (order->SessionID == m_last_session.value().SessionID) {
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    if (req) {
      FCASSERT(order->OrderRef[0] != '\0');
      auto order_node = m_service->m_node_db->GetNode<Order>(m_service->m_user_key + "|" + order_id);
      std::static_pointer_cast<InsertOrder>(req)->order_id = order_id;
      std::static_pointer_cast<InsertOrder>(req)->order_pointer = order_node;
      if (order->OrderStatus == THOST_FTDC_OST_Canceled && order->OrderSysID[0] == '\0') {
        SetCommandFinished(req, 1, GbkToUtf8(order->StatusMsg));
      } else if (order->OrderStatus != THOST_FTDC_OST_Unknown) {
        SetCommandFinished(req, 0, u8"成功");
      }
    }
  }
}

void CtpSoptUnitInsertCancelOrder::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  LOG_ASSERT(m_last_session.has_value());
  if (msg->RspInfo.ErrorID != 0) {
    auto pInputOrder = std::static_pointer_cast<CThostFtdcInputOrderField>(msg->pMainField);
    auto order_id =
      ToFclibOrderId(pInputOrder->OrderRef, m_last_session.value().SessionID, m_last_session.value().FrontID);
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitInsertCancelOrder::OnRspOrderAction(std::shared_ptr<SpiMessage> msg) {
  auto pInputCancel = std::static_pointer_cast<CThostFtdcInputOrderActionField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(pInputCancel->OrderActionRef));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpSoptUnitInsertCancelOrder::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  m_last_session.reset();
}

int CtpSoptUnitInsertCancelOrder::RunOnce() {
  return 0;
}

