CtpSoptUnitLockPosition::CtpSoptUnitLockPosition(CtpSoptServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("lock_position_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryLockPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryLockPosition(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryLockPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryLockPosition(msg);
  });
  m_service->RegisterCommandProcessor(ReqLockPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqLockInsert(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnLock, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnLock(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnErrRtnLockInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspLockInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspLockInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspLockInsert(msg);
  });
}

void CtpSoptUnitLockPosition::ReqQryLockPosition(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 请登录后查询");
    return;
  }
  CThostFtdcQryLockPositionField field;
  memset(&field, 0, sizeof(CThostFtdcQryLockPositionField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryLockPosition" + std::to_string(request_id));
  auto ret = m_service->m_api->ReqQryLockPosition(&field, request_id);
  LogCtpSoptReq(m_logger, "ReqQryLockPosition", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败");
  }
}

void CtpSoptUnitLockPosition::OnRspQryLockPosition(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<QueryLockPosition>(
    m_service->m_command_manager->Update("ReqQryLockPosition" + std::to_string(msg->nRequestID)));
  if (msg->RspInfo.ErrorID == 0 && msg->pMainField) {
    auto field = std::static_pointer_cast<CThostFtdcLockPositionField>(msg->pMainField);
    req->symbols.push_back(std::string(field->ExchangeID) + "." + field->InstrumentID);
    req->lock_volume.push_back(field->Volume);
    req->frozen_volume.push_back(field->FrozenVolume);
  }
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitLockPosition::ReqLockInsert(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 请登录后查询");
    return;
  }
  auto req = std::static_pointer_cast<ReqLockPosition>(command);
  auto ref = m_service->GenerateOrderRef();
  CThostFtdcInputLockField field;
  memset(&field, 0, sizeof(CThostFtdcInputLockField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.LockRef, std::to_string(ref));
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  field.Volume = req->volume;
  field.LockType = req->lock_type == PositionLockType::kLock ? THOST_FTDC_LCKT_Lock : THOST_FTDC_LCKT_Unlock;
  auto request_id = m_service->GenerateRequestID();
  auto ret = m_service->m_api->ReqLockInsert(&field, request_id);
  LogCtpSoptReq(m_logger, "ReqLockInsert", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败");
  }
  auto lock_id = std::string(field.LockRef) + "|" + std::to_string(m_service->m_session_id);
  m_service->m_command_manager->SetCommandId(command, "ReqLockInsert" + lock_id);
}

void CtpSoptUnitLockPosition::OnRtnLock(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<CThostFtdcLockField>(msg->pMainField);
  auto lock_id = std::string(field->LockRef) + "|" + std::to_string(field->SessionID);
  auto req =
    std::static_pointer_cast<QueryLockPosition>(m_service->m_command_manager->Update("ReqLockInsert" + lock_id));
  if (field->LockStatus == THOST_FTDC_OAS_Accepted)
    SetCommandFinished(req);
  if (field->LockStatus == THOST_FTDC_OAS_Rejected)
    SetCommandFinished(req, -1, GbkToUtf8(field->StatusMsg));
}

void CtpSoptUnitLockPosition::OnRspLockInsert(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<CThostFtdcInputLockField>(msg->pMainField);
  auto lock_id = std::string(field->LockRef) + "|" + std::to_string(m_service->m_session_id);
  auto req =
    std::static_pointer_cast<QueryLockPosition>(m_service->m_command_manager->Update("ReqLockInsert" + lock_id));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

int CtpSoptUnitLockPosition::RunOnce() {
  return 0;
}

