      target_account->client_equity = ctp_sopt_account->Balance;
      target_account->close_profit = ctp_sopt_account->CloseProfit;
      target_account->commission = ctp_sopt_account->Commission;
      target_account->deposit = ctp_sopt_account->Deposit;
      target_account->frozen_commission = ctp_sopt_account->FrozenCommission;
      target_account->frozen_margin = ctp_sopt_account->FrozenMargin;
      target_account->margin = ctp_sopt_account->CurrMargin;
      target_account->position_profit = ctp_sopt_account->PositionProfit;
      target_account->pre_balance = ctp_sopt_account->PreBalance;
      target_account->withdraw = ctp_sopt_account->Withdraw;
