  : m_service(service)
  , m_logger(parent_logger.With("item_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterCommandProcessor(QueryCFMMCToken::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryCFMMCToken(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQueryCFMMCTradingAccountToken, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQueryCFMMCTradingAccountToken(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRtnCFMMCTradingAccountToken, [this](std::shared_ptr<SpiMessage> msg) {
      OnRtnCFMMCTradingAccountToken(msg);
    });
  m_service->RegisterCommandProcessor(QueryMaxVolume::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryQueryMaxVolume(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryMaxOrderVolume, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryMaxOrderVolume(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePassword(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserPasswordUpdate, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserPasswordUpdate(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspTradingAccountPasswordUpdate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspTradingAccountPasswordUpdate(msg);
    });
  m_service->RegisterCommandProcessor(SubmitUserSystemInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    SubmitUserSystemInfo(command);
  });
}

void CtpSoptUnitItems::ReqQryCFMMCToken(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 请登录后查询");
    return;
  }
  CThostFtdcQueryCFMMCTradingAccountTokenField field;
  memset(&field, 0, sizeof(CThostFtdcQueryCFMMCTradingAccountTokenField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryCFMMCToken");
  auto ret = m_service->m_api->ReqQueryCFMMCTradingAccountToken(&field, request_id);
  LogCtpSoptReq(m_logger, "ReqQueryCFMMCTradingAccountToken", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败");
  }
}

void CtpSoptUnitItems::OnRspQueryCFMMCTradingAccountToken(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("ReqQryCFMMCToken"));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
}

void CtpSoptUnitItems::OnRtnCFMMCTradingAccountToken(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("ReqQryCFMMCToken"));
    if (!req)
      return;
    auto field = std::static_pointer_cast<CThostFtdcCFMMCTradingAccountTokenField>(msg->pMainField);
    SetCommandFinished(
      req, 0, std::string(field->ParticipantID) + ";" + std::to_string(field->KeyID) + ";" + std::string(field->Token));
  }
}

void CtpSoptUnitItems::ReqQryQueryMaxVolume(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(m_service->m_command_manager->Update(command));
  std::string error_msg;
  if (!req->Check(&error_msg)) {
    SetCommandFinished(req, -1, error_msg);
    return;
  }
  CThostFtdcQueryMaxOrderVolumeField field;
  memset(&field, 0, sizeof(CThostFtdcQueryMaxOrderVolumeField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.InstrumentID, req->instrument_id);
  ConvertToSfitDirection(req->direction, &(field.Direction));
  ConvertToSfitOffsetFlag(req->offset, &(field.OffsetFlag));
  ConvertToSfitHedgeFlag(req->hedge_flag, &(field.HedgeFlag));
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryQueryMaxVolume" + std::to_string(request_id));
  int ret = m_service->m_api->ReqQueryMaxOrderVolume(&field, request_id);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败,请重试");
  }
  m_logger.With("req", req->ToJson()).With("request_id", request_id).With("ret", ret).Info("ReqQryQueryMaxVolume");
}

void CtpSoptUnitItems::OnRspQryMaxOrderVolume(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(
    m_service->m_command_manager->Update("ReqQryQueryMaxVolume" + std::to_string(msg->nRequestID)));
  if (msg->RspInfo.ErrorID != 0 || !req) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  if (!msg->pMainField) {
    return;
  }
  auto field = std::static_pointer_cast<CThostFtdcQueryMaxOrderVolumeField>(msg->pMainField);
  req->volume = field->MaxVolume;
  SetCommandFinished(req);
}

