void CtpSoptUnitItems::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_service->m_command_manager->Update(command));
  if (!m_service->m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录前修改密码接口");
    return;
  }
  int request_id;
  if (req->query_request_id > 0) {
    request_id = req->query_request_id;
  } else {
    request_id = m_service->GenerateRequestID();
  }
  if (req->password_type == PasswordType::kTrade) {
    CThostFtdcUserPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
    strcpy_x(field.UserID, m_service->m_req_login->user_id);
    int ret = m_service->m_api->ReqUserPasswordUpdate(&field, request_id);
    LogCtpSoptReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
    m_service->SetReqResponse(command, request_id, ret);
  } else {
    CThostFtdcTradingAccountPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
    strcpy_x(field.AccountID, m_service->m_req_login->user_id);
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.CurrencyID, "CNY");
    int ret = m_service->m_api->ReqTradingAccountPasswordUpdate(&field, request_id);
    LogCtpSoptReq(m_logger, "ReqTradingAccountPasswordUpdate", &field, 0, ret);
    m_service->SetReqResponse(command, request_id, ret);
  }
}

void CtpSoptUnitItems::OnRspUserPasswordUpdate(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  } else {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpSoptUnitItems::OnRspTradingAccountPasswordUpdate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpSoptUnitItems::SubmitUserSystemInfo(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录接口");
    return;
  }
  auto submit_command =
    std::static_pointer_cast<future::SubmitUserSystemInfo>(m_service->m_command_manager->Update(command));
  CThostFtdcUserSystemInfoField field;
  strcpy_x(field.BrokerID, submit_command->broker_id);
  strcpy_x(field.UserID, submit_command->user_id);
  strcpy_x(field.ClientSystemInfo, submit_command->client_system_info);
  strcpy_x(field.ClientPublicIP, submit_command->client_ip);
  strcpy_x(field.ClientAppID, submit_command->client_app_id);
  field.ClientIPPort = submit_command->client_port;
  field.ClientSystemInfoLen = static_cast<int>(submit_command->client_system_info.length());
  auto now = EpochNanoToLocalDateTime(NowAsEpochNano());
  snprintf(
    field.ClientLoginTime, 9, "%02d:%02d:%02d", now.date_time.tm_hour, now.date_time.tm_min, now.date_time.tm_sec);
  int ret = m_service->m_api->SubmitUserSystemInfo(&field);
  LogCtpSoptReq(m_logger, "SubmitUserSystemInfo", &field, 1, ret);
  if (ret == -1) {
    SetCommandFinished(command, -1, u8"字段长度不对");
    return;
  }
  if (ret == -2) {
    SetCommandFinished(command, -1, u8"非CTP_SOPT采集的终端信息");
    return;
  }
  if (ret == -4) {
    SetCommandFinished(command, -1, u8"当前用户非一对多操作员");
    return;
  }
  if (ret == -5) {
    SetCommandFinished(command, -1, u8"字段中存在非法字符或者长度超限");
    return;
  }
  if (ret == -6) {
    SetCommandFinished(command, -1, u8"采集结果字段错误");
    return;
  }
  SetCommandFinished(command, ret);
}

int CtpSoptUnitItems::RunOnce() {
  return 0;
}

