/*******************************************************************************
 * @file ctp_sopt_query_controller.h
 * @brief CTP_SOPT 查询流控
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_CTP_SOPT_QUERY_CONTROLLER_H
#define FCLIB_CTP_SOPT_QUERY_CONTROLLER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <list>
#include <memory>
#include <string>
#include <map>
#include <vector>
#include <functional>
#include "structlog/structlog.h"
#include "fclib/utils/timer.h"
#include "../model_ctp_sopt.h"

namespace fclib {
namespace future {
namespace ctp_sopt {
// Query Controller 是一个查询流控发送模块, 其负责将加入的 task 按照优先级, 依次发送给柜台.
// 该模块的主要功能是:
// 1. 将加入的 task 按照优先级排序, 每次发送所有待发送 task 中优先级最高的.
// 2. 保证在途查询有且只有一条.
// 3. 触发流控时, 尝试重新查询.
// 4. task 完结时, 触发回调通知, 完结条件如下:
//    a). 收到柜台回复.
//    b). 不重要的 task 查询计时器超时.
//    c). 带有 command 的 task, command 超时.
//
// CTP_SOPT 查询流控规则如下:
// * https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/1411547239
// 目前认定: OnRspError 均表征流控触发.
//
// 约束条件: 添加的任务 key 必须唯一, 否则丢弃.
//
class CtpSoptQueryController {
 public:
  explicit CtpSoptQueryController(structlog::Logger& parent_logger);

  // 添加任务
  // @param task: 任务
  // @param run: 是否立即执行
  void AddTask(std::shared_ptr<QueryTask> task, bool run);

  // 注册查询任务完结回调
  // @param func: 回调函数( param: 完结的任务指针)
  void RegisterQueryTaskCallBack(std::function<void(std::shared_ptr<QueryTask>)> func);

  // 运行一轮, 主要负责:
  // 1. 判断当前任务是否超时.
  // 2. 移除超时的剩余任务
  // 3. 选取下一个运行的任务.
  void RunOnce();

  // 处理柜台数据包, 主要负责:
  // 1. 处理触发流控场景.
  // 2. 处理任务完成场景.
  void ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg);

  // 获取当前正在运行的任务
  // @return: 当前正在运行的任务指针
  std::shared_ptr<QueryTask> GetRunningTask() const;

  // 查询超时时长
  static inline std::chrono::milliseconds QUERY_TIMEOUT = std::chrono::milliseconds(5000);

 private:
  void RemoveTask(bool remove, std::shared_ptr<QueryTask> task);
  void TriggerCallBack(std::shared_ptr<QueryTask> task);

  bool IsTaskTimeOut(std::shared_ptr<QueryTask> task);

  structlog::Logger m_logger;

  std::map<std::string, std::shared_ptr<QueryTask>> m_task_map;
  std::list<std::shared_ptr<QueryTask>> m_task_queue;
  std::vector<std::function<void(std::shared_ptr<QueryTask>)>> m_call_backs;

  std::shared_ptr<QueryTask> m_running_task;
  Timer m_query_timeout_timer;
};

}  // namespace ctp_sopt
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_CTP_SOPT_QUERY_CONTROLLER_H

/*******************************************************************************
 * @file ctp_sopt_query_waiting.cpp
 * @brief CTP_SOPT 查询等待
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "ctp_sopt_query_waiting.h"

#include "ctp_sopt_query_controller.h"
#include "ctp_sopt_query_duplicate.h"
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace ctp_sopt {

CtpSoptQueryWaiting::CtpSoptQueryWaiting(
  CtpSoptQueryController* controller, CtpSoptQueryDuplicate* duplicate, structlog::Logger& parent_logger)
  : m_controller(controller)
  , m_duplicate(duplicate)
  , m_logger(parent_logger.With("query_waiting", reinterpret_cast<int64_t>(this)).Clone()) {
  m_controller->RegisterQueryTaskCallBack([this](std::shared_ptr<QueryTask> task) {
    if (task != m_running_task)
      return;
    m_running_task.reset();
    if (m_task_cache.empty())
      return;
    FCASSERT(task->key == m_task_cache.front()->key);
    for (const auto& t : m_task_cache) {
      m_duplicate->AddTask(t, false);
    }
    m_task_cache.clear();
  });
}

void CtpSoptQueryWaiting::AddTask(std::shared_ptr<QueryTask> task) {
  if (!m_running_task)
    m_running_task = m_controller->GetRunningTask();
  FCASSERT(m_running_task == m_controller->GetRunningTask());
  if (!m_running_task || m_running_task->key != task->key) {
    m_duplicate->AddTask(task, true);
    return;
  }
  m_task_cache.push_back(task);
}
}  // namespace ctp_sopt
}  // namespace future
}  // namespace fclib

