class SerializerOtgLog : public rapid_serialize::Serializer<SerializerOtgLog> {
 public:
  using rapid_serialize::Serializer<SerializerOtgLog>::Serializer;
};

void LogReplayer::OpenLogFile(const std::string& log_file_name, OtgServiceImpl* service) {
  m_service = service;
  m_log_input_stream.push(boost::iostreams::lzma_decompressor());
  m_log_input_stream.push(boost::iostreams::file_source(log_file_name, BOOST_IOS::in | BOOST_IOS::binary));
}

void LogReplayer::ProcessUntil(int64_t dt_step) {
  int msg_count = 0;
  if (m_stop_dt != 0) {
    m_stop_dt += dt_step;
  }
  while (true) {
    while (m_next_spi_msg.empty()) {
      std::string line;
      if (!std::getline(m_log_input_stream, line))
        return;
      m_next_spi_msg = LogLineToSpiMessage(line, &m_next_spi_msg_dt);
    }
    if (m_stop_dt == 0)
      m_stop_dt = m_next_spi_msg_dt;
    if (m_next_spi_msg_dt > m_stop_dt)
      break;
    m_service->ProcessMsg(m_next_spi_msg);
    msg_count++;
    m_next_spi_msg = "";
  }
  MockDateTime(m_stop_dt);
}

std::string LogReplayer::LogLineToSpiMessage(const std::string& log_line, int64_t* msg_date_time) {
  SerializerOtgLog ss;
  ss.FromString(log_line.c_str());
  std::string msg = (*ss.m_doc)["msg"].GetString();
  if (msg != "received message")
    return "";
  std::string dts = (*ss.m_doc)["time"].GetString();
  assert(ss.m_doc->HasMember("content"));
  rapidjson::Value& content = (*ss.m_doc)["content"];
  rapidjson::StringBuffer buffer;
  rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
  content.Accept(writer);
  std::string content_str = buffer.GetString();
  int64_t dt = DateTimeStringToEpochNano(dts.c_str());
  if (dt == -1)
    return "";
  *msg_date_time = dt;
  return content_str;
}

