int CreateOtgSessionID() {
  static int session_id = static_cast<int>(
    std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count());
  return session_id++;
}

OtgServiceImpl::OtgServiceImpl(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger)
  : m_md_helper(helper)
  , m_node_db(node_db)
  , m_logger(parent_logger.With("c2", "future").With("c3", "otg").Clone())
  , m_main_logger(parent_logger.With("c2", "future").With("c3", "otg_main").Clone())
  , m_ssl_context(boost::asio::ssl::context::sslv23_client)
  , m_user_key(user_key)
  , m_options(options)
  , m_option_market_yesterday_inited(false)
  , m_login_ready(false)
  , m_strand(*ioc) {
  m_websocket_connected = false;
  m_ec.store(false);
  m_access_token = options.access_token;
  if (!options.agent.empty())
    m_agent = options.agent;
  // 获取期权持仓视图
  m_order_view = m_node_db->CreateView<future::Order>([=](std::shared_ptr<const future::Order> o) {
    return o->user_key == m_user_key;
  });
  m_position_view = m_node_db->CreateView<future::Position>([=](std::shared_ptr<const future::Position> position) {
    return position->user_key == m_user_key && position->unit_id == 0;
  });
}

OtgServiceImpl::~OtgServiceImpl() {
  if (m_reconnect_timer)
    m_reconnect_timer->cancel();
  if (m_log_replayer)
    return;
  m_ioc.stop();
  if (m_thread.joinable()) {
    m_thread.join();
  }
}

ServiceInterface::ServiceType OtgServiceImpl::GetServiceType() {
  return ServiceInterface::ServiceType::kFuture;
}

void OtgServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  switch (command->aid) {
    case ReqLogin::AID: {
      ReqLogin(command);
      break;
    }
    case InsertOrder::AID: {
      ReqInsertOrder(command);
      break;
    }
    case CancelOrder::AID: {
      ReqCancelOrder(command);
      break;
    }
    case TransferMoney::AID: {
      ReqTransferMoney(command);
      break;
    }
    case ConfirmSettlementInfo::AID: {
      ReqSettlementInfoConfirm(command);
      break;
    }
    case ResetSimUser::AID: {
      ReqResetSimUser(command);
      break;
    }
    case ChangePassword::AID: {
      ReqChangePassword(command);
      break;
    }
    case InsertExecOrder::AID: {
      ReqInsertExecOrder(command);
      break;
    }
    case CancelExecOrder::AID: {
      ReqCancelExecOrder(command);
      break;
    }
    case ReqSetMemo::AID: {
      ReqSetMemo(command);
      break;
    }
    case QuerySettlementInfo::AID: {
      ReqQuerySettlementInfo(command);
      break;
    }
    case QueryCommissionRate::AID: {
      ReqQueryRate(command, false);
      break;
    }
    case QueryMarginRate::AID: {
      ReqQueryRate(command, true);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"fclib: OTG暂不支持该接口");
      m_main_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

int OtgServiceImpl::RunOnce() {
  if (m_log_replayer && !m_log_replayer->m_pause)
    m_log_replayer->ProcessUntil((300LL + std::rand() % 200) * 1000000LL);  // 回放日志时, 每次推进300 - 500毫秒
  if ((m_is_ssl_on && !m_wss_socket) || (!m_is_ssl_on && !m_ws_socket))
    return 0;
  // 处理接收到的数据包
  std::string msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    ProcessMsg(msg);
    ++msg_count;
  }
  if (m_login_node) {
    // 就绪
    if (m_login_ready && !m_login_node->Latest()->account_ready && !m_login_node->Latest()->position_ready) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<LoginContent> session) {
        session->account_ready = true;
        session->position_ready = true;
      });
      ++msg_count;
    }
    // 断线
    if (m_ec.load() && m_login_node->Latest()->session_status == SessionStatus::kLogined) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<LoginContent> session) {
        session->session_status = SessionStatus::kDisconnected;
      });
      ++msg_count;
    }
    // 重连
    if (!m_ec.load() && m_login_node->Latest()->session_status == SessionStatus::kDisconnected) {
      m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<LoginContent> session) {
        session->session_status = SessionStatus::kLogined;
      });
      ++msg_count;
    }
  }
  // 更新账户的多头和空头市值
  if (msg_count > 0 && !m_position_view->GetNodes().empty()) {
    double option_buy_market_value = 0.0;
    double option_sell_market_value = 0.0;
    double option_buy_market_value_yesterday = 0.0;
    double option_sell_market_value_yesterday = 0.0;
    double future_market_value = 0.0;
    for (const auto& [_, position_node] : m_position_view->GetNodes()) {
      auto ins = m_md_helper->GetShmInstrument(position_node->Latest()->Symbol(), true);
      if (ins->product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
        if (!m_option_market_yesterday_inited) {
          option_buy_market_value_yesterday += position_node->Latest()->LongMarketValueYesterday();
          option_sell_market_value_yesterday += position_node->Latest()->ShortMarketValueYesterday();
        }
      }
      if (ins->product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->LongMarketValue() + position_node->Latest()->ShortMarketValue();
    }
    m_node_db->ReplaceRecord<Account>(m_user_key + "|0|CNY", [&](std::shared_ptr<future::Account> account) {
      account->user_key = m_user_key;
      account->currency = "CNY";
      account->investor_id = m_req_login->otg.user_name;
      account->option_buy_market_value = option_buy_market_value;
      account->option_sell_market_value = option_sell_market_value;
      if (!m_option_market_yesterday_inited) {
        account->option_buy_market_value_yesterday = option_buy_market_value_yesterday;
        account->option_sell_market_value_yesterday = option_sell_market_value_yesterday;
        m_option_market_yesterday_inited = true;
      }
      account->future_market_value = future_market_value;
    });
  }
  return msg_count;
}

std::vector<std::shared_ptr<UserCommand>> OtgServiceImpl::ProcessMsg(const std::string& json_str) {
  std::vector<std::shared_ptr<UserCommand>> command_response_list;
  if (m_new_day)
    return command_response_list;
  OtgParser ss;
  ss.FromString(json_str.c_str());
  if (ss.m_doc->HasMember("aid") && ss.m_doc->HasMember("trading_day") && ss.m_doc->HasMember("settlement_info")) {
    auto& trading_day_value = (*ss.m_doc)["trading_day"];
    auto& settlement_info_value = (*ss.m_doc)["settlement_info"];
    if (trading_day_value.IsInt() && settlement_info_value.IsString()) {
      int trading_day = trading_day_value.GetInt();
      std::string trading_day_str = std::to_string(trading_day);
      auto settlement_info = settlement_info_value.GetString();
      auto req = m_command_manager->Update("ReqQuerySettlementInfo" + trading_day_str);
      SetCommandFinished(req, 0, settlement_info);
    }
  }
  if (!ss.m_doc->HasMember("data"))
    return command_response_list;

  rapidjson::Value& datas = (*ss.m_doc)["data"];
  if (!datas.IsArray())
    return command_response_list;
  for (auto& data : datas.GetArray()) {
    if (data.HasMember("notify")) {
      rapidjson::Value& notice = data["notify"];
      for (auto& n : notice.GetObject()) {
        auto notice_id = n.name.GetString();
        auto notice_key = m_user_key + "|" + notice_id;
        m_node_db->ReplaceRecord<Notice>(notice_key, [&](std::shared_ptr<Notice> target) {
          ss.ToVar(target, &n.value);
          target->notice_id = notice_id;
          target->user_key = m_user_key;
          target->content_type = NoticeType::kText;
          target->notice_time = NowAsEpochNano();
          target->source_type = SourceType::kOtg;
        });

        if (auto notice_node = m_node_db->GetNode<Notice>(m_user_key + "|" + notice_id)) {
          auto code = notice_node->Latest()->otg_error_code;
          if (code == 401 || code == 324
            || code == 323) {  // 登录成功通知, 登录成功应以收到登录确认包为准, 所以跳过该通知.
            continue;
          } else if (code == 326 || code == 1020 || code == 1030) {  // 修改密码成功
            SetCommandFinished(m_command_manager->Update("ReqChangePassword"), 0, notice_node->Latest()->content);
          } else if (         // 修改密码失败
            (code == 10)      // CTP:修改别人的口令
            || (code == 14)   // CTP:原口令不匹配
            || (code == 142)  // CTP:修改密码失败。新密码不允许与旧密码相同
            || (code == 1021) || (code == 1031)) {
            SetCommandFinished(m_command_manager->Update("ReqChangePassword"), code, notice_node->Latest()->content);
          } else if (code == 421 || code == 422 || code == 1050 || code == 1051) {  // 出入金回包 421成功，422失败.
            // 转账请求以 Notify 设置是否完成, 指令完成时内存内 TransferLog 可能未就绪.
            SetCommandFinished(m_command_manager->Update("ReqTransferMoney"), (code == 421 || code == 1050) ? 0 : 1,
              notice_node->Latest()->content);
          } else {
            static const std::set<int32_t> login_error_codes = {
              /* --- CTP 交易服务器原生错误码, OTG 直接转发 --- */
              1,    // CTP:不在已同步状态
              2,    // CTP:会话信息不一致
              3,    // CTP:不合法的登录
              4,    // CTP:用户不活跃
              5,    // CTP:重复的登录
              6,    // CTP:还没有登录
              7,    // CTP:还没有初始化
              8,    // CTP:前置不活跃
              9,    // CTP:无此权限
              48,   // CTP:无效的投资者或者密码
              49,   // CTP:不合法的登录IP地址
              60,   // CTP:用户在线会话超出上限
              63,   // CTP:客户端认证失败
              64,   // CTP:客户端未认证
              75,   // CTP:连续登录失败次数超限，登录被禁止
              131,  // CTP:您当前密码为弱密码，请修改成强密码后重新登录
              140,  // CTP:首次登录必须修改密码，请修改密码后重新登录
              141,  // CTP:您当前密码已过期，请修改后登录
              143,  // CTP:您登录失败次数过多，IP被禁止登入CTP
              /* --- CTP 交易服务器 OTG 错误码 --- */
              338,  // 重复发送登录请求!
              339,  // 账户和密码不匹配!
              340,
              341,
              342,
              343,
              344,
              345,
              346,  // 用户登录失败!
              347,  // 用户登录超时!
              /* --- 快期模拟交易服务器 --- */
              400,  // 重复发送登录请求!
              402,  // 账户和密码不匹配!
              403,  // 用户登录失败!
              1011,
              1012,
              1013,
            };
            if (login_error_codes.find(code) != login_error_codes.end()) {  // 登录失败.
              SetCommandFinished(m_command_manager->Update("ReqLogin"), code, notice_node->Latest()->content);
            }
          }
        }
      }
    }
    if (!data.HasMember("trade"))
      continue;
    rapidjson::Value& trade = data["trade"];
    if (!m_req_login)
      continue;
    if (m_log_replayer) {
      assert(trade.IsObject());
      auto obj = trade.GetObject();
      assert(obj.begin()->name.IsString());
      m_req_login->user_id = obj.begin()->name.GetString();
    }
    if (!trade.HasMember(m_req_login->user_id))
      continue;
    rapidjson::Value& d = trade[m_req_login->user_id];
    /*
     * OTG 登录确认包格式
     * {"aid": "rtn_data","data" : [{"trade":{"a04f89c6-695b-4f1c-ba50-231e01e61cff":{"session":{"user_id" :
     * "a04f89c6-695b-4f1c-ba50-231e01e61cff","trading_day" : "20210301"}}}}]}
     */
    if (d.HasMember("session") && d["session"].HasMember("user_id") && d["session"].HasMember("trading_day")) {
      m_login_node = m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<LoginContent> session) {
        session->user_key = m_user_key;
        session->user_id = m_req_login->user_id;
        session->investor_id = m_req_login->otg.user_name;
        auto trading_day = d["session"]["trading_day"].GetString();
        if (!session->trading_day.empty() && session->trading_day != trading_day) {
          m_new_day = true;
          session->session_status = SessionStatus::kDisconnected;
        } else {
          session->session_status = SessionStatus::kLogined;
        }

        session->trading_day = trading_day;
        session->backend = BackEnd::kOtg;
        session->session_id = m_session_id;
        if (session->user_desc == "") {
          session->user_desc = m_req_login->user_desc;
        }
      });
      auto req = m_command_manager->Update("ReqLogin");
      SetCommandFinished(req);
      if (m_options.auto_settlement_confirm) {
        auto confirm = std::make_shared<future::ConfirmSettlementInfo>(m_user_key);
        ExecuteCommand(confirm);
      }
      continue;
    }
    // OTG 使用trademoredata 作为标志位确认业务信息截面完整
    if (d.HasMember("trade_more_data") && !d["trade_more_data"].GetBool())
      m_login_ready = true;

    if (d.HasMember("accounts")) {
      for (auto& c : d["accounts"].GetObject()) {
        future::Account a;
        ss.ToVar(a, &c.value);
        auto account_key = m_user_key + "|0|" + a.currency;
        m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<future::Account> account) {
          *account = a;
          account->user_key = m_user_key;
          account->investor_id = m_req_login->otg.user_name;
          // OTG返回的客户权益加上了期权市值 需要减掉
          account->client_equity = account->balance - account->option_market_value;
          if (account->balance > 0) {
            account->ref_risk_ratio = account->margin / account->balance;
          }
        });
      }
      auto req = std::static_pointer_cast<future::TransferMoney>(m_command_manager->Update("ReqResetSimUser"));
      SetCommandFinished(req);
    }
    if (d.HasMember("orders")) {
      std::multimap<int, future::Order> orders;
      for (auto& c : d["orders"].GetObject()) {
        future::Order order;
        ss.ToVar(order, &c.value);
        orders.insert(std::make_pair(order.seq_no, order));
      }
      for (auto&& item : orders) {
        auto& o = item.second;
        auto order_key = Order::MakeKey(m_user_key, o.order_id);
        m_node_db->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> order) {
          int seq_no = order->seq_no;
          o.trade_set = order->trade_set;
          o.trade_price = order->trade_price;
          o.trade_total_volume = order->trade_total_volume;
          o._leg1_trade_price = order->_leg1_trade_price;
          o._leg2_trade_price = order->_leg2_trade_price;
          o._leg1_trade_total_volume = order->_leg1_trade_total_volume;
          o._leg2_trade_total_volume = order->_leg2_trade_total_volume;
          o.send_date_time = order->send_date_time;
          o.receive_date_time = order->receive_date_time;
          if (order->order_id.empty()) {
            // 委托单第一次出现, 编序号
            seq_no = static_cast<int>(m_node_db->GetNodeCount<Order>()) + 1;
            auto it = m_send_time.find(o.order_id);
            if (it != m_send_time.end()) {
              o.send_date_time = it->second;
              m_send_time.erase(it);
            }
            o.receive_date_time = NowAsEpochNano();
          }
          *order = o;
          order->seq_no = seq_no;
          order->user_key = m_user_key;
          order->force_close_reason = ForceCloseReason::kNotForceClose;
          if (order->investor_id.empty()) {
            auto n_pos = order->order_id.find_last_of(".");
            if (n_pos != order->order_id.npos) {
              auto unit_id = order->order_id.substr(order->order_id.find_last_of(".") + 1);
              order->unit_id = std::atoi(unit_id.c_str());
            } else {
              order->unit_id = -1;
            }

            auto r_pos = order->order_id.find(".r.");
            if (r_pos != order->order_id.npos) {
              auto request_id = order->order_id.substr(0, r_pos);
              order->request_id = request_id;
            } else {
              order->request_id = order->order_id;
            }
            order->investor_id = m_req_login->otg.user_name;
          }
          auto req = std::static_pointer_cast<future::InsertOrder>(
            m_command_manager->Update("ReqInsertOrder" + order->order_id));
          if (req) {
            order->min_volume = req->min_volume;
          }
          // 错单不刷新 exchange_order_id
          if (order->exchange_order_id.empty() && order->status == OrderStatus::kDead
            && order->volume_orign == order->volume_left)
            return;
          // 使用 order_id 替换 exchange_order_id, 为了和成交对应
          order->exchange_order_id = order->order_id;
          auto iter = m_order_ref_map.find(order->order_id);
          if (iter != m_order_ref_map.end()) {
            order->order_ref = iter->second;
            order->session_id = m_session_id;
          }
        });
      }
    }
    if (d.HasMember("trades")) {
      std::multimap<int, future::Trade> trades;
      for (auto& c : d["trades"].GetObject()) {
        future::Trade trade;
        ss.ToVar(trade, &c.value);
        trade.user_key = m_user_key;
        trades.insert(std::make_pair(trade.seq_no, trade));
      }
      for (const auto& item : trades) {
        auto& t = item.second;
        auto trade_key = t.GetKey();
        auto trade_node = m_node_db->ReplaceRecord<Trade>(trade_key, [&](std::shared_ptr<future::Trade> trade) {
          *trade = t;
          trade->seq_no = static_cast<int>(m_node_db->GetNodeCount<Trade>());
          trade->user_key = m_user_key;
          if (trade->investor_id.empty()) {
            auto trade_order_node = m_node_db->GetNode<Order>(m_user_key + "|" + trade->order_id);
            if (trade_order_node) {
              trade->order_pointer = trade_order_node;
              trade->unit_id = trade_order_node->Latest()->unit_id;
            }
            trade->investor_id = m_req_login->otg.user_name;
          }
        });
      }
    }
    if (d.HasMember("positions")) {
      for (auto& c : d["positions"].GetObject()) {
        future::Position p;
        ss.ToVar(p, &c.value);
        p.user_key = m_user_key;
        auto position_key = p.GetKey();
        m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<future::Position> position) {
          ss.ToVar(position, &c.value);
          FCASSERT(!position->Symbol().empty());
          position->user_key = m_user_key;
          position->investor_id = m_req_login->otg.user_name;

          auto ins = m_md_helper->GetShmInstrument(position->Symbol(), true);
          if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption) {
            double price = (isnan(ins->last_price) ? ins->pre_settlement : ins->last_price) * ins->volume_multiple;
            for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_long_other,
                   &future::Position::subpos_short_spec, &future::Position::subpos_short_other}) {
              ((*(position)).*p).market_value = price * ((*(position)).*p).Volume();
              if (ins->product_class == md::ProductClass::kOption) {
                ((*(position)).*p).market_value_yesterday =
                  ins->pre_settlement * ((*(position)).*p).volume_yesterday * ins->volume_multiple;
                if (((*(position)).*p).direction == Direction::kSell) {
                  ((*(position)).*p).market_value *= -1;
                  ((*(position)).*p).market_value_yesterday *= -1;
                }
              }
            }
          }
          // otg 下无法计算操作盈亏和非操作盈亏
          if (!isnan(position->UnTradeProfit())) {
            for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
                   &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
              ((*(position)).*p).untrade_profit = NAN;
            }
          }
        });
      }
    }
    if (d.HasMember("banks")) {
      for (auto& c : d["banks"].GetObject()) {
        auto key = c.name.GetString();
        auto bank_key = m_user_key + "|" + key;
        m_node_db->ReplaceRecord<Bank>(bank_key, [&](std::shared_ptr<future::Bank> bank) {
          ss.ToVar(bank, &c.value);
          bank->bank_account = key;
          bank->user_key = m_user_key;
        });
      }
    }
    if (d.HasMember("transfers")) {
      for (auto& c : d["transfers"].GetObject()) {
        int32_t key = std::atoi(c.name.GetString());
        m_node_db->ReplaceRecord<TransferLog>(
          TransferLog::MakeKey(m_user_key, key, ""), [&](std::shared_ptr<future::TransferLog> transferlog) {
            ss.ToVar(transferlog, &c.value);
            transferlog->user_key = m_user_key;
            transferlog->future_serial = key;
            transferlog->bank_serial = "";
            // TODO(hongyan): otg 服务器转账记录没有提供银行信息, 等后续补充.
            transferlog->bank_account = "SIM";
            transferlog->trade_type = (transferlog->amount > 0) ? u8"入金" : u8"出金";
            transferlog->amount = std::fabs(transferlog->amount);
          });
      }
    }
    if (d.HasMember("rates")) {
      rapidjson::Value& rate_node = d["rates"];
      if (rate_node.IsObject()) {
        for (auto& c : rate_node.GetObject()) {
          auto r = std::make_shared<future::Rate>();
          ss.ToVar(r, &c.value);
          r->user_key = m_user_key;
          auto req_margin = m_command_manager->Update("QueryMarginRate" + r->InstrumentID());
          auto req_commission = m_command_manager->Update("QueryCommissionRate" + r->InstrumentID());
          SetCommandFinished(req_margin);
          SetCommandFinished(req_commission);
          m_node_db->ReplaceRecord<Rate>(r);
        }
      } else {
        FCASSERT(false && "otg rate invalid");
      }
    }

    if (d.HasMember("exec_orders")) {
      for (auto& c : d["exec_orders"].GetObject()) {
        std::string exec_order_id = c.name.GetString();
        m_node_db->ReplaceRecord<future::ExecOrder>(
          future::ExecOrder::MakeKey(m_user_key, exec_order_id), [&](std::shared_ptr<future::ExecOrder> exec_order) {
            ss.ToVar(exec_order, &c.value);
            exec_order->user_key = m_user_key;
            exec_order->exec_order_id = exec_order_id;

            auto iter = m_exec_order_ref_map.find(exec_order_id);
            if (iter != m_exec_order_ref_map.end()) {
              exec_order->exec_order_ref = iter->second;
              exec_order->session_id = m_session_id;
            }

            int result_code = (exec_order->exec_result == future::ExecOrderResultType::kUnKnown
                                && exec_order->exchange_exec_order_sysid == exec_order_id)
              ? -1
              : 0;
            auto req = std::static_pointer_cast<future::InsertExecOrder>(
              m_command_manager->Update("ReqInsertExecOrder" + exec_order_id));
            SetCommandFinished(req, result_code, exec_order->status_msg);

            if (exec_order->exec_result == future::ExecOrderResultType::kCanceled) {
              auto request = m_command_manager->Update("ReqCancelExecOrder" + exec_order->exec_order_id);
              SetCommandFinished(request);
            }
          });
      }
    }
    int64_t max_memo_id = 0;
    for (const auto& order_node : m_order_view->GetChangedNodes()) {
      auto order = order_node->Latest();
      // 下单请求
      auto req =
        std::static_pointer_cast<future::InsertOrder>(m_command_manager->Update("ReqInsertOrder" + order->order_id));
      if (req) {
        req->order_pointer = order_node;
      }
      if (order->status == OrderStatus::kDead && order->volume_orign == order->volume_left
        && order->exchange_order_id.empty())
        // 下单失败
        SetCommandFinished(req, 1, order->status_msg);
      else
        SetCommandFinished(req);
      // 撤单请求
      if (order->status == OrderStatus::kDead && !order->exchange_order_id.empty()) {
        auto request = m_command_manager->Update("ReqCancelOrder" + order->order_id);
        SetCommandFinished(request);
      }
      // 找寻最大的备注id
      if (order->memo._memo_id > max_memo_id)
        max_memo_id = order->memo._memo_id;
    }
    // 备注请求
    if (max_memo_id > 0) {
      for (auto iter = m_memo_id.begin(); iter != m_memo_id.end();) {
        auto id = *iter;
        if (id > max_memo_id) {
          ++iter;
          continue;
        }
        iter = m_memo_id.erase(iter);
        auto req_setmemo =
          std::static_pointer_cast<future::ReqSetMemo>(m_command_manager->Update("ReqSetMemo" + std::to_string(id)));
        SetCommandFinished(req_setmemo);
      }
    }
  }
  return command_response_list;
}

void OtgServiceImpl::ReqLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<future::ReqLogin>(m_command_manager->Update(command));
  // 日志回放
  if (!req->replay_flow_file_name.empty()) {
    m_req_login = req;
    m_req_login->otg.user_name = "replayer";
    if (m_log_replayer) {
      m_log_replayer->m_pause = !m_log_replayer->m_pause;
    } else {
      m_log_replayer = std::make_shared<LogReplayer>();
      m_log_replayer->OpenLogFile(req->replay_flow_file_name, this);
    }
    return;
  }
  if (!req->otg.access_token.empty())
    m_access_token = req->otg.access_token;
  std::regex regex("(wss|ws)://([^/ :]+):?([^/ ]*)(/?[^ #?]*)");
  std::smatch match;
  if (req->otg.front_url.empty() || !std::regex_search(req->otg.front_url, match, regex)) {
    SetCommandFinished(req, -1, u8"fclib: 服务器地址错误");
    return;
  }
  m_otg_protocol = std::string(match[1]);
  m_otg_host = std::string(match[2]);
  m_otg_port = std::string(match[3]).empty() ? (m_otg_protocol == "ws" ? "80" : "443") : std::string(match[3]);
  m_otg_path = std::string(match[4]);
  m_is_ssl_on = m_otg_protocol == "wss" ? true : false;
  m_req_login = req;
  if (m_req_login->otg.user_name.empty())
    m_req_login->otg.user_name = m_req_login->user_id;
  m_req_peek_message = "{\"aid\":\"peek_message\"}";

  // 穿管采集信息获取 https://documentation.help/CTP-API-cn/CTP-GETSYSTEMINFO.html
  if (m_req_login->client_system_info.empty()) {
    static std::string system_info;
    static bool called_once = false;
    if (!called_once) {
      called_once = true;
      char buf[344];
      int len = 0;
      int ret_code = CTP_GetSystemInfo(buf, len);
      if (0 == ret_code) {
        system_info = Base64_Encode((unsigned char*)buf, len);
      }
    }
    if (!system_info.empty()) {
      m_req_login->client_system_info = system_info;
    }
  }
  m_command_manager->SetCommandId(command, "ReqLogin");

  // Look up the domain name
  DoResolve();

  // start thread
  if (!m_thread.joinable()) {
    m_thread = std::thread([&] {
      m_ioc.run();
    });
  }
}

void OtgServiceImpl::ReqInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_command_manager->Update(command));
  m_command_manager->SetCommandId(command, "ReqInsertOrder" + req->order_id);
  m_send_time[req->order_id] = NowAsEpochNano();
  if (req->order_ref > 0)
    m_order_ref_map[req->order_id] = std::to_string(req->order_ref);
  if (req->offset == Offset::kCloseYesterday) {
    req->offset = Offset::kClose;
  }

  // 发单
  OtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "insert_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("order_id", req->order_id, ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
}

void OtgServiceImpl::ReqCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_command_manager->Update(command));
  std::string command_id = "ReqCancelOrder" + req->order_id;
  auto node = m_node_db->GetNode<Order>(Order::MakeKey(m_user_key, req->order_id));
  if (!node) {
    SetCommandFinished(command, -1, u8"fclib: 委托单不存在, 撤单失败");
    return;
  }
  if (node->Latest()->status == OrderStatus::kDead) {
    SetCommandFinished(command, -1, u8"fclib: 委托单不可撤单, 撤单失败");
    return;
  }
  // 发单
  OtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "cancel_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
  m_command_manager->SetCommandId(command, command_id);
}

