void OtgServiceImpl::Reconnect() {
  m_reconnect_timer = std::make_shared<boost::asio::deadline_timer>(m_ioc, boost::posix_time::seconds(10));
  m_reconnect_timer->async_wait([this](const boost::system::error_code& ec) {
    if (!ec)
      DoResolve();
  });
}
