void OtgServiceImpl::ReqQueryRate(std::shared_ptr<UserCommand> command, bool margin) {
  OtgParser ss;
  if (margin) {
    auto req = std::static_pointer_cast<future::QueryMarginRate>(m_command_manager->Update(command));
    if (req->instrument_id.empty() || req->exchange_id.empty()) {
      SetCommandFinished(command, -1, u8"查询保证金率失败, instrument_id or exchange_id 为空");
      return;
    }
    m_command_manager->SetCommandId(command, "QueryMarginRate" + req->instrument_id);
    ss.FromVar(*req);
  } else {
    auto req = std::static_pointer_cast<future::QueryCommissionRate>(m_command_manager->Update(command));
    if (req->instrument_id.empty() || req->exchange_id.empty()) {
      SetCommandFinished(command, -1, u8"查询手续费率失败, instrument_id or exchange_id 为空");
      return;
    }
    m_command_manager->SetCommandId(command, "QueryCommissionRate" + req->instrument_id);
    ss.FromVar(*req);
  }
  ss.m_doc->AddMember("aid", "qry_rate", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
}

