void OtgServiceImpl::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_command_manager->Update(command));
  std::string command_id = "ReqChangePassword";
  // 发单
  OtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "change_password", ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
  m_command_manager->SetCommandId(command, command_id);
}

void OtgServiceImpl::ReqInsertExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_command_manager->Update(command));
  m_command_manager->SetCommandId(command, "ReqInsertExecOrder" + req->exec_order_id);
  if (req->exec_order_ref != 0)
    m_exec_order_ref_map[req->exec_order_id] = std::to_string(req->exec_order_ref);

  // 发单
  OtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "insert_exec_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("exec_order_id", req->exec_order_id, ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
}

void OtgServiceImpl::ReqCancelExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_command_manager->Update(command));
  std::string command_id = "ReqCancelExecOrder" + req->exec_order_id;
  auto node = m_node_db->GetNode<ExecOrder>(ExecOrder::MakeKey(m_user_key, req->exec_order_id));
  if (!node) {
    SetCommandFinished(command, -1, u8"行权单不存在, 撤单失败");
    return;
  }
  // 发单
  OtgParser ss;
  ss.FromVar(*req);
  ss.m_doc->AddMember("aid", "cancel_exec_order", ss.m_doc->GetAllocator());
  ss.m_doc->AddMember("user_id", m_req_login->user_id, ss.m_doc->GetAllocator());
  std::string json_req;
  ss.ToString(&json_req);
  m_ioc.post([=] {
    SendTextMsg(json_req);
  });
  m_command_manager->SetCommandId(command, command_id);
}

void OtgServiceImpl::DoResolve() {
  m_websocket_connected = false;
  // 连接关闭后, stream 不可复用, 需要重新构建 https://github.com/boostorg/beast/issues/1071
  websocket::stream_base::timeout opt{};
  opt.handshake_timeout = std::chrono::seconds(30);
  opt.keep_alive_pings = true;
  opt.idle_timeout = std::chrono::seconds(5);

  if (m_is_ssl_on) {
    m_wss_socket =
      std::make_shared<websocket::stream<beast::ssl_stream<boost::asio::ip::tcp::socket>>>(m_ioc, m_ssl_context);
    m_wss_socket->set_option(opt);
    m_wss_socket->read_message_max(64ull << 20);
  } else {
    m_ws_socket = std::make_shared<websocket::stream<boost::asio::ip::tcp::socket>>(m_ioc);
    m_ws_socket->set_option(opt);
    m_ws_socket->read_message_max(64ull << 20);
  }
  m_resolver = std::make_shared<boost::asio::ip::tcp::resolver>(m_ioc);
  m_resolver->async_resolve(m_otg_host, m_otg_port,
    std::bind(&OtgServiceImpl::OnResolve, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
}

void OtgServiceImpl::OnResolve(boost::system::error_code ec, boost::asio::ip::tcp::resolver::results_type results) {
  if (ec) {
    m_ec.store(true);
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("resolve fail");
    Reconnect();
    return;
  }
  if (m_is_ssl_on) {
    boost::asio::async_connect(m_wss_socket->next_layer().next_layer(), results.begin(), results.end(),
      std::bind(&OtgServiceImpl::OnConnect, shared_from_this(), std::placeholders::_1));
  } else {
    boost::asio::async_connect(m_ws_socket->next_layer(), results.begin(), results.end(),
      std::bind(&OtgServiceImpl::OnConnect, shared_from_this(), std::placeholders::_1));
  }
}

void OtgServiceImpl::OnConnect(boost::system::error_code ec) {
  if (ec) {
    m_ec.store(true);
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("connect fail");
    Reconnect();
    return;
  }
  m_ec.store(false);
  if (m_is_ssl_on) {
    m_wss_socket->next_layer().async_handshake(
      boost::asio::ssl::stream_base::client, beast::bind_front_handler(&OtgServiceImpl::OnSslHandshake, this));
  } else {
    m_ws_socket->set_option(
      boost::beast::websocket::stream_base::decorator([=](boost::beast::websocket::request_type& m) {
        m.insert(http::field::accept, "application/v1+json");
        m.insert(http::field::user_agent, m_agent);
        m.insert(http::field::authorization, "Bearer " + m_access_token);
      }));
    m_ws_socket->async_handshake(
      m_otg_host, m_otg_path, std::bind(&OtgServiceImpl::OnHandshake, shared_from_this(), std::placeholders::_1));
  }
}

void OtgServiceImpl::OnSslHandshake(beast::error_code ec) {
  if (ec) {
    m_ec.store(true);
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("ssl handshake fail");
    Reconnect();
    return;
  }
  m_ec.store(false);
  m_wss_socket->set_option(websocket::stream_base::decorator([=](websocket::request_type& m) {
    m.insert(http::field::accept, "application/v1+json");
    m.insert(http::field::user_agent, m_agent);
    m.insert(http::field::authorization, "Bearer " + m_access_token);
    m.insert(http::field::user_agent, std::string(BOOST_BEAST_VERSION_STRING) + " websocket-client-coro");
  }));
  m_wss_socket->async_handshake(
    m_otg_host, m_otg_path, std::bind(&OtgServiceImpl::OnHandshake, shared_from_this(), std::placeholders::_1));
}

void OtgServiceImpl::OnHandshake(boost::system::error_code ec) {
  if (ec) {
    m_ec.store(true);
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("handshake fail");
    Reconnect();
    return;
  }
  m_ec.store(false);
  m_logger.With("ec", LocalToUtf8(ec.message())).Info("got connection");
  m_websocket_connected = true;
  m_output_buffer_list.clear();
  m_session_id = CreateOtgSessionID();
  std::string login_message;
  OtgParser ss;
  ss.FromVar(*m_req_login);
  ss.m_doc->AddMember("aid", "req_login", ss.m_doc->GetAllocator());
  ss.ToString(&login_message);
  SendTextMsg(login_message);
  SendTextMsg(m_req_peek_message);
  DoRead();
}

void OtgServiceImpl::DoRead() {
  if (m_is_ssl_on) {
    m_wss_socket->async_read(m_input_buffer,
      std::bind(&OtgServiceImpl::OnRead, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
  } else {
    m_ws_socket->async_read(m_input_buffer,
      std::bind(&OtgServiceImpl::OnRead, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
  }
}

void OtgServiceImpl::OnRead(boost::system::error_code ec, std::size_t bytes_transferred) {
  boost::ignore_unused(bytes_transferred);
  if (ec) {
    m_ec.store(true);
    m_logger.With("err_code", ec.value()).With("err_msg", LocalToUtf8(ec.message())).Info("read error");
    if (m_is_ssl_on) {
      m_wss_socket->next_layer().next_layer().shutdown(boost::asio::ip::tcp::socket::shutdown_both, ec);
      m_wss_socket->next_layer().next_layer().close(ec);
    } else {
      m_ws_socket->next_layer().shutdown(boost::asio::ip::tcp::socket::shutdown_both, ec);
      m_ws_socket->next_layer().close(ec);
    }
    Reconnect();
    return;
  }
  OnMessage(beast::buffers_to_string(m_input_buffer.data()));
  m_input_buffer.consume(m_input_buffer.size());
  DoRead();
}

void OtgServiceImpl::OnMessage(const std::string& json_str) {
  m_logger.With("len", static_cast<int>(json_str.size()))
    .With("content", structlog::make_json(json_str))
    .Info("received message");
  SendTextMsg(m_req_peek_message);
  m_strand.post([=]() {
    m_recv_queue.push(json_str);
  });
}

void OtgServiceImpl::SendTextMsg(const std::string& json_str) {
  if (!m_websocket_connected)
    return;
  m_output_buffer_list.push_back(json_str);
  if (m_output_buffer_list.size() == 1)
    DoWrite();
}

void OtgServiceImpl::DoWrite() {
  auto& json_str = m_output_buffer_list.front();
  m_logger.With("len", static_cast<int>(json_str.size()))
    .With("content", structlog::make_json(json_str))
    .Info("send message");
  auto buf = boost::asio::buffer(json_str);
  if (m_is_ssl_on) {
    m_wss_socket->text(true);
    m_wss_socket->async_write(
      buf, std::bind(&OtgServiceImpl::OnWrite, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
  } else {
    m_ws_socket->text(true);
    m_ws_socket->async_write(
      buf, std::bind(&OtgServiceImpl::OnWrite, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
  }
}

void OtgServiceImpl::OnWrite(boost::system::error_code ec, std::size_t bytes_transferred) {
  if (ec) {
    m_ec.store(true);
    m_logger.With("ec", LocalToUtf8(ec.message())).Warning("send message fail");
    Reconnect();
    return;
  }
  if (!m_output_buffer_list.empty())
    m_output_buffer_list.pop_front();
  if (!m_output_buffer_list.empty())
    DoWrite();
}

