template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, const T* plain_src) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  return msg;
}

DstarSpiHandler::DstarSpiHandler(boost::asio::io_context* ioc, structlog::Logger& parent_logger, DstarServiceImpl* impl)
  : m_logger(parent_logger.Clone())
  , m_impl(impl)
  , m_strand(*ioc) {
  m_serial_id = {
    {"RtnOrder", 0},
    {"RtnMatch", 0},
    {"RtnCashInOut", 0},
    {"RtnPosiProfit", 0},
    {"RtnOffer", 0},
