DstarInsertCancelOrder::DstarInsertCancelOrder(DstarServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(InsertQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertQuote(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelQuote(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderDelete, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderDelete(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOfferInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOfferInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOffer, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOffer(msg);
  });
}

int DstarInsertCancelOrder::RunOnce() {
  return 0;
}

void DstarInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (m_service->m_serial_id == 0) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  if (req->instrument_id.find("&") != std::string::npos) {
    ExecuteInsertCombOrder(req);
    return;
  }
  std::string ins_id = PushInsId(req->instrument_id);
  auto order_ref = req->order_ref;
  int64_t order_id = ToFclibOrderId(order_ref, m_service->m_auth_code);
  FCASSERT(std::to_string(order_id) == req->order_id);
  DstarApiReqOrderInsertField field;
  memset(&field, 0, sizeof(field));
  field.Direct = PushDir(req->direction);
  field.Offset = PushOffset(req->offset);
  field.Hedge = PushHedge(req->hedge_flag);
  field.OrderType = PushOrderType(req->price_type);
  field.ValidType = PushValidType(req->time_condition, req->volume_condition);
  strcpy_x(field.ContractNo, ins_id.c_str());
  field.OrderQty = req->volume;
  field.MinQty = req->min_volume;
  field.OrderPrice = req->limit_price;
  field.Reference = order_id;
  field.UdpAuthCode = m_service->m_auth_code;
  field.AccountIndex = static_cast<DstarApiAccountIndexType>(m_service->m_account_index);
  field.SeatIndex = '0';
  field.ContractIndex = m_service->m_contract_index[ins_id].first;
  if (field.ContractIndex == 0) {
    auto order_id = std::to_string(field.Reference);
    auto order_key = m_service->m_user_key + "|" + order_id;
    m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
      o->user_key = m_service->m_user_key;
      o->user_id = m_service->m_req_login->user_id;
      o->order_id = order_id;
      o->investor_id = m_service->m_req_login->user_id;
      o->exchange_id = req->exchange_id;
      o->instrument_id = req->instrument_id;
      o->direction = req->direction;
      o->offset = req->offset;
      o->time_condition = req->time_condition;
      o->volume_condition = req->volume_condition;
      o->price_type = req->price_type;
      o->volume_orign = req->volume;
      o->volume_left = req->volume;
      o->limit_price = req->limit_price;
      o->hedge_flag = req->hedge_flag;
      o->is_swap_order = req->is_swap_order;
      o->force_close_reason = ForceCloseReason::kNotForceClose;
      o->status = OrderStatus::kDead;
      o->status_msg = u8"不支持此合约";
    });
    SetCommandFinished(req, -1, u8"不支持此合约");
    return;
  }
  int ret = m_service->m_api->ReqOrderInsert(&field);
  m_logger.With("ret", ret)
    .With("ContractNo", field.ContractNo)
    .With("OrderQty", std::to_string(field.OrderQty))
    .With("Reference", std::to_string(field.Reference))
    .With("Direct", field.Direct)
    .With("Offset", field.Offset)
    .Info("ReqOrderInsert");
  m_service->m_send_time[std::to_string(order_id)] = NowAsEpochNano();
  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + std::to_string(order_id));
  if (ret < 0) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
  }
}

void DstarInsertCancelOrder::ExecuteInsertCombOrder(std::shared_ptr<InsertOrder> req) {
  auto ins = m_service->m_md_helper->GetShmInstrument(req->exchange_id + "." + req->instrument_id, true);
  FCASSERT(ins->product_class == md::ProductClass::kCombine);
  auto ins1 = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
  auto ins2 = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
  std::string ins_id1 = PushInsId(ins1->instrument_id.data());
  std::string ins_id2 = PushInsId(ins2->instrument_id.data());
  auto contract_cache = m_service->m_comb_contract_index[ins_id1 + ins_id2];
  if (!contract_cache) {
    SetCommandFinished(req, -1, u8"fclib: 不支持此合约");
    return;
  }
  DstarApiReqCmbOrderInsertField field;
  memset(&field, 0, sizeof(DstarApiReqCmbOrderInsertField));
  auto order_ref = req->order_ref ? req->order_ref : (GenerateOrderRef() * 100 + req->unit_id);
  int64_t order_id = ToFclibOrderId(order_ref, m_service->m_auth_code);
  field.Direct = PushDir(req->direction);
  field.Offset = PushOffset(req->offset);
  field.Hedge = PushHedge(req->hedge_flag);
  field.OrderType = PushOrderType(req->price_type);
  field.ValidType = PushValidType(req->time_condition, req->volume_condition);
  strcpy_x(field.ContractNo1, ins_id1.c_str());
  strcpy_x(field.ContractNo2, ins_id2.c_str());
  field.OrderQty = req->volume;
  field.MinQty = req->min_volume;
  field.OrderPrice = req->limit_price;
  field.Reference = order_id;
  field.UdpAuthCode = m_service->m_auth_code;
  field.AccountIndex = static_cast<DstarApiAccountIndexType>(m_service->m_account_index);
  field.SeatIndex = '0';
  field.ContractIndex1 = contract_cache->ContractIndex1;
  field.ContractIndex2 = contract_cache->ContractIndex2;
  int ret = m_service->m_api->ReqCmbOrderInsert(&field);
  m_logger.With("ret", ret)
    .With("ContractNo1", field.ContractNo1)
    .With("ContractNo2", field.ContractNo2)
    .With("OrderQty", std::to_string(field.OrderQty))
    .With("Reference", std::to_string(field.Reference))
    .With("Direct", field.Direct)
    .With("Offset", field.Offset)
    .Info("ReqCmbOrderInsert");
  req->order_id = std::to_string(order_id);
  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + std::to_string(order_id));
  if (ret < 0) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
  }
}

void DstarInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (m_service->m_serial_id == 0) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  m_logger.With("req->order_id", req->order_id).Info("ExecuteCancelOrder");
  req->status = UserCommand::Status::kStarted;
  auto pos = std::find_if_not(req->order_id.begin(), req->order_id.end(), ::isdigit);
  if (pos != req->order_id.end()) {
    // 撤做市单
    auto quote_id = std::string(req->order_id.begin(), pos);
    auto it = m_offer_alive.find(quote_id);
    if (it == m_offer_alive.end()) {
      SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
      return;
    }
    // 重复撤单指令储存
    auto order = m_offer_alive[quote_id];
    if (!m_cancel_quote_req[std::to_string(order->Reference)].empty()) {
      m_cancel_quote_req[std::to_string(order->Reference)].push_back(command);
      return;
    }
    DstarApiReqOrderDeleteField field;
    memset(&field, 0, sizeof(field));
    field.AccountIndex = static_cast<DstarApiAccountIndexType>(m_service->m_account_index);
    field.OrderId = order->OrderId;
    field.Reference = order->Reference;
    field.SeatIndex = order->SeatIndex;
    strcpy_x(field.SystemNo, order->SystemNo);
    field.UdpAuthCode = m_service->m_auth_code;
    int ret = m_service->m_api->ReqOrderDelete(&field);
    m_logger.With("field.OrderId", std::to_string(field.OrderId))
      .With("field.Reference", std::to_string(field.Reference))
      .With("ret", ret)
      .Info("ReqCancelQuote");
    if (ret < 0) {
      SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
      return;
    }
    m_service->m_command_manager->SetCommandId(command, "ReqCancelQuote" + std::to_string(field.Reference));
    m_cancel_quote_req[std::to_string(field.Reference)].push_back(command);
    return;
  }
  // 撤委托单
  auto it = m_order_alive.find(req->order_id);
  if (it == m_order_alive.end()) {
    SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
    return;
  }
  DstarApiReqOrderDeleteField field;
  memset(&field, 0, sizeof(field));
  auto order = m_order_alive[req->order_id];
  field.AccountIndex = static_cast<DstarApiAccountIndexType>(m_service->m_account_index);
  field.OrderId = order->OrderId;
  field.Reference = order->Reference;
  field.SeatIndex = order->SeatIndex;
  strcpy_x(field.SystemNo, order->SystemNo);
  field.UdpAuthCode = m_service->m_auth_code;
  int ret = m_service->m_api->ReqOrderDelete(&field);
  m_logger.With("field.OrderId", std::to_string(field.OrderId))
    .With("field.Reference", std::to_string(field.Reference))
    .With("ret", ret)
    .Info("ReqCancelOrder");
  if (ret < 0) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::to_string(field.Reference));
}

