void DstarInsertCancelOrder::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiRspOrderInsertField>(msg->pMainField);
  auto req = std::static_pointer_cast<InsertOrder>(
    m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(field->Reference)));
  auto order_id = std::to_string(field->Reference);
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(order_key);
  req->order_pointer = order_node;
  SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
}

void DstarInsertCancelOrder::OnRspOrderDelete(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiRspOrderInsertField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(field->Reference));
  SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
  if (!m_cancel_quote_req[std::to_string(field->Reference)].empty()) {
    for (const auto& req_offer : m_cancel_quote_req[std::to_string(field->Reference)]) {
      SetCommandFinished(req_offer, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    }
    m_cancel_quote_req.erase(std::to_string(field->Reference));
  }
}

void DstarInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOrderField>(msg->pMainField);
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  if (PullOrderStatus(field->OrderState) == OrderStatus::kAlive) {
    m_order_alive[order_id] = field;
  } else {
    m_order_alive.erase(order_id);
  }
}

void DstarInsertCancelOrder::OnRtnOffer(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOfferField>(msg->pMainField);
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  if (PullOrderStatus(field->OrderState) == OrderStatus::kAlive) {
    m_offer_alive[order_id] = field;
  } else {
    m_offer_alive.erase(order_id);
  }
}

void DstarInsertCancelOrder::ExecuteInsertQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update(command));
  if (m_service->m_serial_id == 0) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  std::string ins_id = PushInsId(req->instrument_id);
  auto quote_ref = req->quote_ref ? req->quote_ref : (GenerateOrderRef() * 100 + req->unit_id);
  int64_t quote_id = ToFclibOrderId(quote_ref, m_service->m_auth_code);
  DstarApiReqOfferInsertField field;
  memset(&field, 0, sizeof(field));
  field.AccountIndex = static_cast<DstarApiAccountIndexType>(m_service->m_account_index);
  field.UdpAuthCode = m_service->m_auth_code;
  field.SeatIndex = '0';
  field.Reference = quote_id;
  strcpy_x(field.ContractNo, ins_id.c_str());
  field.BuyOffset = PushOffset(req->bid_offset);
  field.SellOffset = PushOffset(req->ask_offset);
  field.ContractIndex = m_service->m_contract_index[ins_id].first;
  if (field.ContractIndex == 0) {
    auto order_id = std::to_string(field.Reference);
    auto order_key = m_service->m_user_key + "|" + order_id;
    m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
      o->user_key = m_service->m_user_key;
      o->user_id = m_service->m_req_login->user_id;
      o->order_id = order_id;
      o->investor_id = m_service->m_req_login->user_id;
      o->exchange_id = req->exchange_id;
      o->instrument_id = req->instrument_id;
      o->direction = Direction::kBuy;
      o->offset = req->ask_offset;
      o->time_condition = OrderTimeCondition::kGfd;
      o->volume_condition = OrderVolumeCondition::kAny;
      o->price_type = PriceType::kLimit;
      o->volume_orign = req->ask_volume;
      o->volume_left = req->ask_volume;
      o->limit_price = req->ask_price;
      o->hedge_flag = req->ask_hedge_flag;
      o->force_close_reason = ForceCloseReason::kNotForceClose;
      o->status = OrderStatus::kDead;
      o->status_msg = u8"不支持此合约做市";
    });
    SetCommandFinished(req, -1, u8"不支持此合约");
    return;
  }
  field.BuyPrice = req->bid_price;
  field.SellPrice = req->ask_price;
  field.OrderQty = req->bid_volume;
  int ret = m_service->m_api->ReqOfferInsert(&field);
  m_logger.With("ret", ret)
    .With("Reference", std::to_string(field.Reference))
    .With("OrderQty", std::to_string(field.OrderQty))
    .With("BuyPrice", field.BuyPrice)
    .With("SellPrice", field.SellPrice)
    .With("ContractNo", field.ContractNo)
    .With("BuyOffset", field.BuyOffset)
    .With("SellOffset", field.SellOffset)
    .Info("ReqOfferInsert");
  req->quote_id = std::to_string(quote_id);
  m_service->m_command_manager->SetCommandId(req, "ReqOfferInsert" + std::to_string(quote_id));
  if (ret < 0) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
  }
}

