 * @brief Dstar数据类型转换
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "dstar_convert.h"
#include <string>
#include <algorithm>
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace dstar {
int64_t ToFclibOrderId(int64_t ref, int64_t authcode) {
  return (ref * 100000000 + (authcode % 1000000)) * 100 + 11;
}

bool IsRefValid(const int64_t& ref) {
  if (ref % 100 != 11)
    return false;
  if (ref < 100000000)
    return false;
  return ((ref / 100000000) % 100 == 0);
}

char PushDir(Direction& d) {
  if (d == Direction::kBuy)
    return 'B';
  return 'S';
}

Direction PullDir(char& d) {
  if (d == 'B')
    return Direction::kBuy;
  return Direction::kSell;
}

char PushOffset(Offset& o) {
  if (o == Offset::kOpen)
