std::string PushInsId(std::string ins_id) {
  auto pos = std::find_if(ins_id.begin(), ins_id.end(), ::isdigit);
  transform(ins_id.begin(), pos, ins_id.begin(), ::toupper);
  ins_id.erase(std::remove(ins_id.begin(), ins_id.end(), '-'), ins_id.end());
  return ins_id;
}

std::string PullInsId(std::string ins_id, char& ex_id) {
  // 郑商所和中金所品种是大写
  if (ex_id != 'Z' && ex_id != 'C') {
    auto pos = std::find_if(ins_id.begin(), ins_id.end(), ::isdigit);
    transform(ins_id.begin(), pos, ins_id.begin(), ::tolower);
  }
  auto pos_p = ins_id.find('P', 4);
  auto pos_c = ins_id.find('C', 4);
  if (pos_p == std::string::npos && pos_c == std::string::npos)
    return ins_id;
  // option
  // 郑商所和上期所没有"-"
  if (ex_id == 'Z' || ex_id == 'S')
    return ins_id;
  auto pos = pos_p == std::string::npos ? pos_c : pos_p;
  std::string p_c = pos_p == std::string::npos ? "C" : "P";
  std::string pre = ins_id.substr(0, pos);
  std::string last = ins_id.substr(pos + 1);
  return pre + "-" + p_c + "-" + last;
}

std::string PullExchangeId(char& ex_id) {
  if (ex_id == 'Z')
    return "CZCE";
  if (ex_id == 'S')
    return "SHFE";
  if (ex_id == 'I')
    return "INE";
  if (ex_id == 'C')
    return "CFFEX";
  if (ex_id == 'D')
    return "DCE";
  if (ex_id == 'F')
    return "GFEX";
  if (ex_id == 'G')
    return "SGE";  // 上海黄金交易所
  FCASSERT(false);
  return "ERROR";
}

std::string GetProductId(std::string ins) {
  auto pos = std::find_if(ins.begin(), ins.end(), ::isdigit);
  return std::string(ins.begin(), pos);
}

// 获取带前缀组合合约
std::string GetCombId(char ex_id, const std::string& leg1_ins_id, const std::string& leg2_ins_id) {
  if (ex_id == 'D' || ex_id == 'G') {  // 易盛不支持广期所
    if (GetProductId(leg1_ins_id) == GetProductId(leg2_ins_id)) {
      return "SP " + leg1_ins_id + "&" + leg2_ins_id;
    } else {
      return "SPC " + leg1_ins_id + "&" + leg2_ins_id;
    }
  } else if (ex_id == 'Z') {
    if (GetProductId(leg1_ins_id) == GetProductId(leg2_ins_id)) {
      return "SPD " + leg1_ins_id + "&" + leg2_ins_id;
    } else {
      return "IPS " + leg1_ins_id + "&" + leg2_ins_id;
    }
  }
  FCASSERT(false);
  return "Error " + leg1_ins_id + "&" + leg2_ins_id;
}

