void DstarServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: Dstar柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

void DstarServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  if (spi_msg->tag == SpiMessage::Tag::OnRspContract) {
    if (!spi_msg->pMainField)
      return;
    auto field = std::static_pointer_cast<DstarApiContractField>(spi_msg->pMainField);
    m_contract_index[field->ContractNo].first = field->ContractIndex;
    m_contract_index[field->ContractNo].second = field->ExchangeId;
    return;
  }
  if (spi_msg->tag == SpiMessage::Tag::OnRspCmbContract) {
    if (!spi_msg->pMainField)
      return;
    auto field = std::static_pointer_cast<DstarApiCmbContractField>(spi_msg->pMainField);
    m_comb_contract_index[field->ContractNo1 + std::string(field->ContractNo2)] = field;
    return;
  }
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

