int DstarServiceImpl::BuildApi(std::shared_ptr<UserCommand> command) {
  m_req_login = std::static_pointer_cast<ReqLogin>(m_command_manager->Update(command));
  DeleteApi();
  m_api = ThostApiCreator();
  m_spi = new DstarSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    auto index = front.find("//");
    if (index == std::string::npos)
      return -1;
    auto ip_port = front.substr(index + 2);
    auto pos = ip_port.find(":");
    if (pos == std::string::npos)
      return -1;
    auto port_str = ip_port.substr(pos + 1);
    auto ip = ip_port.substr(0, pos);
    unsigned short port = (unsigned short)strtoul(port_str.c_str(), NULL, 0);
    m_api->RegisterFrontAddress(const_cast<char*>(ip.c_str()), port);
  }
  return 0;
}

void DstarServiceImpl::DeleteApi() {
  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  FreeDstarTradeApi(m_api);
  m_api = nullptr;
}

