DstarLogIn::DstarLogIn(DstarServiceImpl *service, structlog::Logger &parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspError, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspError(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnApiReady, [this](std::shared_ptr<SpiMessage> msg) {
    OnApiReady(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspSubmitInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspSubmitInfo(msg);
  });
}

void DstarLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  int ret = m_service->BuildApi(command);
  if (ret != 0)
    SetCommandFinished(command, -1, u8"fclib: 连接失败,请检查交易前置");
  m_service->m_api->SetApiLogPath(const_cast<char *>(m_service->m_options.log_directory.c_str()));
  DstarApiReqLoginField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.AccountNo, m_service->m_req_login->user_id);
  strcpy_x(field.AppId, m_service->m_req_login->broker.app_id);
  strcpy_x(field.LicenseNo, m_service->m_req_login->broker.auth_code);
  strcpy_x(field.Password, m_service->m_req_login->password);
  m_service->m_api->SetLoginInfo(&field);
  m_service->m_api->SetCpuId(-1, 1);
  m_service->m_api->SetSubscribeStartId(0);
  char pSystemInfo[501];
  memset(pSystemInfo, 0, sizeof(pSystemInfo));
  int nLen;
  unsigned int nAuthKeyVersion;
  ret = m_service->m_api->GetSystemInfo(pSystemInfo, &nLen, &nAuthKeyVersion);
  if (ret == 0) {
    DstarApiSubmitInfoField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.AccountNo, m_service->m_req_login->user_id);
    field.AuthType = '1';
    strcpy_x(field.SystemInfo, pSystemInfo);
    strcpy_x(field.ClientAppId, m_service->m_req_login->broker.app_id);
    strcpy_x(field.LicenseNo, m_service->m_req_login->broker.auth_code);
    field.AuthKeyVersion = nAuthKeyVersion;
    m_service->m_api->SetSubmitInfo(&field);
    m_logger.With("systeminfo_upload", std::string(pSystemInfo)).Info("SetSubmitInfo");
  } else {
    m_logger.With("systeminfo_upload", "fail").Info("systeminfo_upload");
  }
  DstarApiInitQryInfoField qry_field;
  qry_field.ContractInitQryFlag = DSTAR_API_YES;          // 合约初始化查询标识
  qry_field.CmbContractInitQryFlag = DSTAR_API_YES;       // 组合合约初始化查询标识
  qry_field.SeatInitQryFlag = DSTAR_API_YES;              // 席位信息初始化查询标识
  qry_field.TrdFeeInitQryFlag = DSTAR_API_YES;            // 手续费参数初始化查询标识
  qry_field.TrdMarInitQryFlag = DSTAR_API_YES;            // 保证金参数初始化查询标识
  qry_field.TrdRightInitQryFlag = DSTAR_API_NO;           // 交易权限初始化查询标识
  qry_field.AccountCommListInitQryFlag = DSTAR_API_NO;    // 客户白名单初始化查询标识
  qry_field.TrdExchangeStateInitQryFlag = DSTAR_API_YES;  // 市场状态初始化查询标识
  qry_field.PrePositionInitQryFlag = DSTAR_API_YES;       // 昨持仓快照初始化查询标识
  qry_field.OrderInitQryFlag = DSTAR_API_NO;              // 委托信息初始化查询标识
  qry_field.OfferInitQryFlag = DSTAR_API_NO;              // 报价信息初始化查询标识
  qry_field.MatchInitQryFlag = DSTAR_API_NO;              // 成交信息初始化查询标识
  qry_field.CashInOutInitQryFlag = DSTAR_API_YES;         // 出入金初始化查询标识
  m_service->m_api->SetInitQryInfo(&qry_field);
  ret = m_service->m_api->Init();
  m_logger.With("ret", ret).Info("Init");
  if (ret == -4 || ret == -5) {
    SetCommandFinished(command, -1, u8"服务器连接失败");
  } else if (ret != 0) {
    SetCommandFinished(command, -1, u8"采集信息失败");
  }
  m_service->m_command_manager->SetCommandId(command, "login");
}

void DstarLogIn::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("login");
  if (msg->nErrorCode != 0 || !msg->pMainField) {
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    return;
  }
  auto pRspUserLogin = std::static_pointer_cast<DstarApiRspLoginField>(msg->pMainField);
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = pRspUserLogin->AccountNo;
      target_login->investor_id = pRspUserLogin->AccountNo;
      if (!target_login->trading_day.empty() && target_login->trading_day != pRspUserLogin->TradeDate) {
        m_service->m_new_day = true;
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = pRspUserLogin->TradeDate;
      target_login->confirm_status = ConfirmStatus::kConfirmed;
      target_login->system_name = "dstar";
      target_login->backend = BackEnd::kDstar;
      target_login->session_id = static_cast<int64_t>(pRspUserLogin->UdpAuthCode);
      if (target_login->user_desc == "") {
        target_login->user_desc = m_service->m_req_login->user_desc;
      }
    });
  m_service->m_trading_day = pRspUserLogin->TradeDate;
  m_service->m_auth_code = pRspUserLogin->UdpAuthCode;
  m_service->m_account_index = pRspUserLogin->AccountIndex;
  SetCommandFinished(req);
  m_disconnect_count = 0;
  m_last_connect_time = 0;
  m_connecting = false;
  m_logined = true;
  m_service->m_timer_manager.AddTimerTask(3000, [this]() {
    if (m_disconnect_count == 0 || m_connecting)
      return;
    int64_t now = NowAsEpochNano();
    int64_t diff = now - m_last_connect_time;
    if (diff > (m_disconnect_count - 1) * 3000000000 || diff > 60000000000) {
      m_service->m_api->Init();
      m_connecting = true;
      m_last_connect_time = now;
    }
  });
}

void DstarLogIn::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (m_logined) {
    m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
        target_login->user_key = m_service->m_user_key;
        target_login->session_status = SessionStatus::kDisconnected;
        target_login->system_name = "dstar";
        target_login->backend = BackEnd::kDstar;
        target_login->status_msg = u8"前置机断连";
      });
    m_logined = false;
  }
  ++m_disconnect_count;
  m_connecting = false;
}

void DstarLogIn::OnRspError(std::shared_ptr<SpiMessage> msg) {}

void DstarLogIn::OnApiReady(std::shared_ptr<SpiMessage> msg) {
  m_service->m_serial_id = msg->SerialId;
  m_service->m_node_db->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
      p->user_key = m_service->m_user_key;
      p->backend = BackEnd::kDstar;
      p->position_ready = true;
      p->account_ready = true;
    });
}

