  auto req = m_service->m_command_manager->Update("login");
  if (!req)
    return;
  if (msg->nErrorCode != 0 || !msg->pMainField)
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
}

