SubPosition* GetSubPosition(std::shared_ptr<Position> position, Direction trade_direction, Offset offset) {
  SubPosition* subpos = nullptr;
  if ((trade_direction == Direction::kBuy && offset == Offset::kOpen)
    || (trade_direction == Direction::kSell && offset != Offset::kOpen))
    subpos = &position->subpos_long_spec;
  else
    subpos = &position->subpos_short_spec;
  return subpos;
}

SubPosition* GetSubPosition(std::shared_ptr<future::Position> position, Direction posi_dir) {
  if (posi_dir == Direction::kBuy) {
    return &position->subpos_long_spec;
  } else if (posi_dir == Direction::kSell) {
    return &position->subpos_short_spec;
  }
  FCASSERT(false);
  return nullptr;
}

void CalcPositionCost(SubPosition* subpos, int close_volume, double volume_multiple, double trade_price, Direction d) {
  double close_profit = 0;
  for (auto it = subpos->_open_list.begin(); it != subpos->_open_list.end();) {
    int close_vol = std::min(close_volume, it->second);
    close_volume -= close_vol;
    it->second -= close_vol;
    double close_profit_tmp = (trade_price - it->first) * close_vol * volume_multiple;
    if (d == Direction::kBuy)
      close_profit_tmp *= -1;
    close_profit += close_profit_tmp;
    if (it->second == 0) {
      it = subpos->_open_list.erase(it);
      if (close_volume > 0)
        continue;
    }
    break;
  }
  subpos->close_profit += close_profit;
  subpos->_position_cost = 0;
  for (auto open : subpos->_open_list) {
    subpos->_position_cost += open.first * open.second * volume_multiple;
  }
}

void RegulateAccount(std::shared_ptr<Account> account) {
  account->balance = account->pre_balance + account->deposit - account->withdraw + account->close_profit
    + account->position_profit - account->commission + account->premium + account->option_market_value;
  account->client_equity = account->balance - account->option_market_value;
  account->available = account->client_equity - account->margin - account->frozen_margin - account->frozen_commission
    - account->frozen_premium;
  account->risk_ratio = std::fabs(account->client_equity) < 1e-5 ? 0.0 : account->margin / account->client_equity;
  account->ref_risk_ratio = std::fabs(account->client_equity) < 1e-5 ? 0.0 : account->margin / account->balance;
}

DstarPositionAccount::DstarPositionAccount(DstarServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspPrePosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspPrePosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspFund, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspFund(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMatch, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMatch(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCashInOut, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnCashInOut(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnPosiProfit, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnPosiProfit(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOffer, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOffer(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnApiReady, [this](std::shared_ptr<SpiMessage> msg) {
    UpdateAccountProfit(true);
    m_service->m_timer_manager.AddTimerTask(500, [this]() {
      bool update = false;
      auto& target_position_node_map = m_position_view->GetNodes();
      for (auto& [pos_key, position_node] : target_position_node_map) {
        auto position = position_node->Latest();
        auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
        if (!ins.has_value() || ins->product_class == md::ProductClass::kCombine
          || ins->last_price == position->last_price || std::isnan(ins->last_price) || !std::isnan(ins->settlement)
          || position->VolumeTotal() == 0 || !ins->CheckQuote(m_service->m_trading_day))
          continue;
        m_service->GetNodeDb()->ReplaceRecord<Position>(pos_key, [this](std::shared_ptr<Position> calc_position) {
          UpdatePositionProfit(calc_position);
        });
        update = true;
      }
      if (update)
        UpdateAccountProfit();
    });
  });
  m_position_view = m_service->GetNodeDb()->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_service->m_user_key && pos->unit_id == 0;
  });
}

void DstarPositionAccount::OnRspPrePosition(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiPrePositionField>(msg->pMainField);
  std::string ins_id = PullInsId(field->ContractNo, m_service->m_contract_index.at(field->ContractNo).second);
  auto ins = m_service->m_md_helper->GetShmInstrument(
    PullExchangeId(m_service->m_contract_index.at(field->ContractNo).second) + "." + ins_id, true);
  FCASSERT(ins && ins->instrument_id.data() == ins_id);
  auto position_key = Position::MakeKey(m_service->m_user_key, 0, ins->symbol.data());
  m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
    target_position->user_key = m_service->m_user_key;
    target_position->investor_id = field->AccountNo;
    target_position->exchange_id = ins->exchange_id.data();
    target_position->instrument_id = ins_id;
    target_position->subpos_long_spec.volume_yesterday = field->PreBuyQty;
    target_position->subpos_long_spec.volume_his = field->PreBuyQty;
    target_position->subpos_long_spec.position_price = field->PreBuyAvgPrice;
    target_position->subpos_long_spec._position_cost_his =
      field->PreBuyAvgPrice * field->PreBuyQty * ins->volume_multiple;
    target_position->subpos_short_spec.volume_yesterday = field->PreSellQty;
    target_position->subpos_short_spec.volume_his = field->PreSellQty;
    target_position->subpos_short_spec.position_price = field->PreSellAvgPrice;
    target_position->subpos_short_spec._position_cost_his =
      field->PreSellAvgPrice * field->PreSellQty * ins->volume_multiple;
    if (ins->product_class == md::ProductClass::kOption) {
      target_position->subpos_long_spec.market_value_yesterday =
        ins->pre_settlement * target_position->subpos_long_spec.volume_yesterday * ins->volume_multiple;
      target_position->subpos_short_spec.market_value_yesterday =
        ins->pre_settlement * target_position->subpos_short_spec.volume_yesterday * ins->volume_multiple * (-1);
    }
    UpdatePositionProfit(target_position);
  });
}

void DstarPositionAccount::OnRspFund(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiFundField>(msg->pMainField);
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
    target_account->user_key = m_service->m_user_key;
    target_account->currency = "CNY";
    target_account->investor_id = field->AccountNo;
    target_account->available = field->Avail;
    target_account->client_equity = field->Equity;
    target_account->commission = field->Fee;
    target_account->margin = field->Margin;
    target_account->frozen_margin = field->FrozenMargin;
    target_account->premium = field->Premium;
    target_account->close_profit = field->CloseProfit;
    target_account->float_profit = field->PositionProfit;
    target_account->deposit = field->CashIn;
    target_account->withdraw = field->CashOut;
    target_account->balance = field->Equity;
    target_account->pre_balance = field->PreEquity;
    if (target_account->client_equity > 0) {
      target_account->risk_ratio = target_account->margin / target_account->client_equity;
    }
    if (target_account->balance > 0) {
      target_account->ref_risk_ratio = target_account->margin / target_account->balance;
    }
  });
}

void UpdatePositionVolumeFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->VolumeFrozen();
  calc_subpos->volume_his_frozen = std::min(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

void DstarPositionAccount::UpdateFrozenVolume(std::shared_ptr<const Order> order,
  const std::optional<shm::ShmInstrument>& ins, Direction direction, Offset offset_flag, int delta_order_volume) {
  std::string position_key = order->user_key + "|0|" + ins->symbol.data();
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      position->user_key = order->user_key;
      position->investor_id = order->investor_id;
      position->exchange_id = order->exchange_id;
      position->instrument_id = ins->instrument_id.data();

      SubPosition* calc_subpos = GetSubPosition(position, direction, offset_flag);
      auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
      if (offset_flag == Offset::kCloseToday && !ins->HasCloseToday()) {
        offset_flag = Offset::kClose;
      }
      if (offset_flag == Offset::kCloseToday) {
        calc_subpos->volume_today_frozen += delta_order_volume;
      } else if (ins->HasCloseToday()) {
        calc_subpos->volume_his_frozen += delta_order_volume;
      } else {
        calc_subpos->volume_his_frozen += delta_order_volume;
        UpdatePositionVolumeFrozen(calc_subpos);
      }
      UpdatePositionProfit(position);
    });
}

void DstarPositionAccount::UpdateAccountProfit(bool is_first) {
  auto account_node = m_service->GetNodeDb()->GetNode<Account>(m_service->m_user_key + "|0|CNY");
  if (!account_node)
    return;
  double position_profit = 0.0;
  double option_buy_market_value = 0.0;
  double option_sell_market_value = 0.0;
  double option_buy_market_value_yesterday = 0.0;
  double option_sell_market_value_yesterday = 0.0;
  double future_market_value = 0.0;
  auto& position_node_map = m_position_view->GetNodes();
  for (auto& [key, position_node] : position_node_map) {
    auto ins = m_service->m_md_helper->GetShmInstrument(position_node->Latest()->Symbol(), true);
    FCASSERT(ins);
    if (ins->product_class != md::ProductClass::kCombine) {
      if (!isnan(position_node->Latest()->PositionProfit()) && ins->product_class != md::ProductClass::kOption)
        position_profit += position_node->Latest()->PositionProfit();
      if (ins->product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
        if (is_first) {
          option_buy_market_value_yesterday += position_node->Latest()->LongMarketValueYesterday();
          option_sell_market_value_yesterday += position_node->Latest()->ShortMarketValueYesterday();
        }
      }
      if (ins->product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->ShortMarketValue() + position_node->Latest()->LongMarketValue();
    }
  }
  m_service->GetNodeDb()->ReplaceRecord<Account>(
    m_service->m_user_key + "|0|CNY", [=](std::shared_ptr<future::Account> account) {
      account->user_key = m_service->m_user_key;
      account->option_buy_market_value = option_buy_market_value;
      account->option_sell_market_value = option_sell_market_value;
      if (is_first) {
        account->option_buy_market_value_yesterday = option_buy_market_value_yesterday;
        account->option_sell_market_value_yesterday = option_sell_market_value_yesterday;
      }
      account->option_market_value = option_buy_market_value + option_sell_market_value;
      account->future_market_value = future_market_value;
      account->position_profit = position_profit;
      RegulateAccount(account);
    });
}

void DstarPositionAccount::UpdatePositionFrozenVolumeByOrder(std::shared_ptr<const Order> order) {
  // 计算冻结手数差额
  int delta_order_volume = (order->status == OrderStatus::kAlive) ? order->volume_left : 0;
  auto it = m_alive_orders.find(order->order_id);
  if (it != m_alive_orders.end()) {
    auto prev_order = it->second;
    int prev_order_volume = (prev_order->status == OrderStatus::kAlive) ? prev_order->volume_left : 0;
    delta_order_volume -= prev_order_volume;
  }
  if (delta_order_volume == 0)
    return;
  // 更新持仓
  auto ins = m_service->m_md_helper->GetShmInstrument(
    std::string(order->exchange_id) + "." + std::string(order->instrument_id), true);
  if (ins->product_class == md::ProductClass::kCombine) {
    auto offset_flag = order->offset;
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2_ins = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    if (offset_flag != Offset::kOpen)
      UpdateFrozenVolume(order, leg1_ins, order->direction, order->offset, delta_order_volume);
    auto direction = (order->direction == Direction::kBuy ? Direction::kSell : Direction::kBuy);
    if (order->is_swap_order)
      offset_flag = (offset_flag == Offset::kOpen ? Offset::kClose : Offset::kOpen);
    if (offset_flag != Offset::kOpen)
      UpdateFrozenVolume(order, leg2_ins, direction, offset_flag, delta_order_volume);
  } else {
    UpdateFrozenVolume(order, ins, order->direction, order->offset, delta_order_volume);
  }

  // alive 委托单都放入 m_alive_orders, 以备下次计算差额.
  if (order->status == OrderStatus::kDead) {
    m_alive_orders.erase(order->order_id);
  } else {
    m_alive_orders[order->order_id] = order;
  }
}

void DstarPositionAccount::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOrderField>(msg->pMainField);
  // 更新冻结
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  auto order_node = m_service->m_node_db->GetNode<Order>(Order::MakeKey(m_service->m_user_key, order_id));
  FCASSERT(order_node);
  if (order_node->Latest()->offset != Offset::kOpen || order_node->Latest()->is_swap_order) {
    UpdatePositionFrozenVolumeByOrder(order_node->Latest());
  }
  // 更新账户
  if (static_cast<int64_t>(field->SerialId) > m_service->m_serial_id)
    UpdateFeeMarginProfit(field->Margin, field->Fee, field->FrozenMargin, false, 0, 0);
}

void DstarPositionAccount::OnRtnOffer(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOfferField>(msg->pMainField);
  // 更新冻结
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  std::string buy_order_id = order_id + "B";
  std::string sell_order_id = order_id + "S";
  auto order_node_buy = m_service->m_node_db->GetNode<Order>(Order::MakeKey(m_service->m_user_key, buy_order_id));
  auto order_node_sell = m_service->m_node_db->GetNode<Order>(Order::MakeKey(m_service->m_user_key, sell_order_id));
  FCASSERT(order_node_buy && order_node_sell);
  if (order_node_buy->Latest()->offset != Offset::kOpen || order_node_buy->Latest()->is_swap_order) {
    UpdatePositionFrozenVolumeByOrder(order_node_buy->Latest());
  }
  if (order_node_sell->Latest()->offset != Offset::kOpen || order_node_sell->Latest()->is_swap_order) {
    UpdatePositionFrozenVolumeByOrder(order_node_sell->Latest());
  }
  // 更新账户
  if (static_cast<int64_t>(field->SerialId) > m_service->m_serial_id)
    UpdateFeeMarginProfit(field->Margin, -1, field->FrozenMargin, false, 0, 0);
}

void DstarPositionAccount::UpdatePositionVolumeByTrade(std::shared_ptr<const Trade> trade) {
  std::string symbol = trade->Symbol();
  std::string position_key = trade->user_key + "|0|" + symbol;
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
      position->user_key = trade->user_key;
      position->investor_id = trade->investor_id;
      position->exchange_id = trade->exchange_id;
      position->instrument_id = trade->instrument_id;
      auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
      auto offset_flag = trade->offset;
      if (offset_flag == Offset::kCloseToday && !ins->HasCloseToday()) {
        offset_flag = Offset::kClose;
      }
      SubPosition* calc_subpos = GetSubPosition(position, trade->direction, trade->offset);
      auto rate_node =
        m_service->GetNodeDb()->GetNode<Rate>(Rate::MakeKey(m_service->m_user_key, position->instrument_id));
      auto multi = ins->volume_multiple;
      if (offset_flag == Offset::kOpen) {
        calc_subpos->volume_today += trade->volume;
        auto cost = trade->volume * trade->price * ins->volume_multiple;
        calc_subpos->_position_cost += cost;
        calc_subpos->_open_list.push_back({trade->price, trade->volume});
        if (rate_node && rate_node->Latest()->commission_rate_open.Valid()) {
          calc_subpos->commission += (rate_node->Latest()->commission_rate_open.amount_rate * multi * trade->price
                                       + rate_node->Latest()->commission_rate_open.volume_rate)
            * trade->volume;
        }
      } else if (offset_flag == Offset::kCloseToday) {
        calc_subpos->volume_today -= trade->volume;
        CalcPositionCost(calc_subpos, trade->volume, ins->volume_multiple, trade->price, trade->direction);
        if (rate_node && rate_node->Latest()->commission_rate_close_today.Valid()) {
          calc_subpos->commission +=
            (rate_node->Latest()->commission_rate_close_today.amount_rate * multi * trade->price
              + rate_node->Latest()->commission_rate_close_today.volume_rate)
            * trade->volume;
        }
      } else {
        if (ins->HasCloseToday()) {
          double percentage = (calc_subpos->volume_his - trade->volume) * 1.0 / calc_subpos->volume_his;
          calc_subpos->_position_cost_his *= percentage;
          calc_subpos->volume_his -= trade->volume;
          FCASSERT(calc_subpos->volume_his >= 0);
          double close_profit = (trade->price - ins->pre_settlement) * trade->volume * ins->volume_multiple;
          if (trade->direction == Direction::kBuy)
            close_profit *= -1;
          calc_subpos->close_profit += close_profit;
        } else {
          auto vol_his = std::min(calc_subpos->volume_his, trade->volume);
          if (vol_his > 0) {
            double percentage = (calc_subpos->volume_his - vol_his) * 1.0 / calc_subpos->volume_his;
            calc_subpos->_position_cost_his *= percentage;
            calc_subpos->volume_his -= vol_his;
            double close_profit = (trade->price - ins->pre_settlement) * vol_his * ins->volume_multiple;
            if (trade->direction == Direction::kBuy)
              close_profit *= -1;
            calc_subpos->close_profit += close_profit;
          }
          if (trade->volume > vol_his) {
            calc_subpos->volume_today -= (trade->volume - vol_his);
            CalcPositionCost(
              calc_subpos, trade->volume - vol_his, ins->volume_multiple, trade->price, trade->direction);
          }
        }
        if (rate_node && rate_node->Latest()->commission_rate_close.Valid()) {
          calc_subpos->commission += (rate_node->Latest()->commission_rate_close.amount_rate * multi * trade->price
                                       + rate_node->Latest()->commission_rate_close.volume_rate)
            * trade->volume;
        }
      }
      if (calc_subpos->Volume() == 0) {
        calc_subpos->position_price = 0;
      } else {
        calc_subpos->position_price = (calc_subpos->_position_cost + calc_subpos->_position_cost_his)
          / calc_subpos->Volume() / ins->volume_multiple;
      }
      if (!ins->HasCloseToday()) {
        UpdatePositionVolumeFrozen(calc_subpos);
      }
      UpdatePositionProfit(position);
    });
}

void DstarPositionAccount::OnRtnMatch(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiMatchField>(msg->pMainField);
  // 更新持仓相关数据
  auto trade_key =
    Trade::MakeKey(m_service->m_user_key, std::to_string(field->MatchId), std::to_string(field->OrderId));
  auto trade_node = m_service->m_node_db->GetNode<Trade>(trade_key);
  UpdatePositionVolumeByTrade(trade_node->Latest());
  auto ins = m_service->m_md_helper->GetShmInstrument(trade_node->Latest()->Symbol(), true);
  FCASSERT(ins);
  double premium = 0;
  double close_profit = 0;
  if (ins->product_class == md::ProductClass::kOption) {
    premium = field->Premium;
  } else {
    close_profit = field->CloseProfit;
  }
  // 更新账户
  if (static_cast<int64_t>(field->SerialId) > m_service->m_serial_id)
    UpdateFeeMarginProfit(field->Margin, field->Fee, field->FrozenMargin, true, premium, close_profit);
}

void DstarPositionAccount::OnRtnCashInOut(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiCashInOutField>(msg->pMainField);
  if (static_cast<int64_t>(field->SerialId) < m_service->m_serial_id)
    return;
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
    if (field->CashInOutType == 'I') {
      target_account->deposit += field->CashInOutValue;
    } else {
      target_account->withdraw = field->CashInOutValue;
    }
  });
}

void DstarPositionAccount::OnRtnPosiProfit(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiPosiProfitField>(msg->pMainField);
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
    target_account->user_key = m_service->m_user_key;
    target_account->currency = "CNY";
    target_account->investor_id = field->AccountNo;
    target_account->float_profit = field->PosiProfit;
  });
}

void DstarPositionAccount::UpdateFeeMarginProfit(
  double margin, double fee, double frozen_margin, bool trade, double premium, double close_profit) {
  auto account_node = m_service->GetNodeDb()->GetNode<Account>(m_service->m_user_key + "|0|CNY");
  FCASSERT(account_node);
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
    if (fee >= 0)
      target_account->commission = fee;
    target_account->margin = margin;
    target_account->frozen_margin = frozen_margin;
    if (trade) {
      target_account->premium = premium;
      target_account->close_profit = close_profit;
    }
  });
}

void DstarPositionAccount::UpdatePositionProfit(std::shared_ptr<Position> position) {
  auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
  if (ins->CheckQuote(m_service->m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  if (position->last_price == 0.0 || isnan(position->last_price)) {
    for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
           &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
      auto subpos = &((*(position)).*p);
      subpos->position_profit = 0.0;
      subpos->float_profit = 0.0;
      subpos->market_value = 0.0;
      if (std::isnan(position->last_price) && !std::isnan(ins->pre_settlement) && subpos->Volume() > 0) {
        subpos->market_value = ins->pre_settlement * ins->volume_multiple * subpos->Volume();
      }
      if (subpos->direction == Direction::kSell) {
        if (ins->product_class == md::ProductClass::kOption)
          subpos->market_value *= -1;
      }
    }
    return;
  }
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption)
        subpos->position_profit =
          (position->last_price - subpos->position_price) * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
  auto rate_node = m_service->GetNodeDb()->GetNode<Rate>(Rate::MakeKey(m_service->m_user_key, position->instrument_id));
  if (!rate_node)
    return;
  auto rate = rate_node->Latest();
  auto multi = ins->volume_multiple;
  if (rate->margin_rate_long_other.Valid())
    position->subpos_long_other.margin = rate->margin_rate_long_other.volume_rate * multi
      * position->subpos_long_other.position_price * position->subpos_long_other.Volume();
  if (rate->margin_rate_long_spec.Valid())
    position->subpos_long_spec.margin = rate->margin_rate_long_spec.volume_rate * multi
      * position->subpos_long_spec.position_price * position->subpos_long_spec.Volume();
  if (rate->margin_rate_short_other.Valid())
    position->subpos_short_other.margin = rate->margin_rate_short_other.volume_rate * multi
      * position->subpos_short_other.position_price * position->subpos_short_other.Volume();
  if (rate->margin_rate_short_spec.Valid())
    position->subpos_short_spec.margin = rate->margin_rate_short_spec.volume_rate * multi
      * position->subpos_short_spec.position_price * position->subpos_short_spec.Volume();
}

