template <int T>
void ConvertTime(const char* origin_time, char (&fmt)[T]) {
  snprintf(fmt, sizeof(fmt), "%c%c%c%c%c%c%c%c%c%c%c%c%c%c", origin_time[0], origin_time[1], origin_time[2],
    origin_time[3], origin_time[5], origin_time[6], origin_time[8], origin_time[9], origin_time[11], origin_time[12],
    origin_time[14], origin_time[15], origin_time[17], origin_time[18]);
}

DstarOrderTradeView::DstarOrderTradeView(DstarServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspMatch, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMatch(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMatch, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMatch(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOffer, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOffer(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOffer, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOffer(msg);
  });
}

