void ConvertOrderType(DstarApiOrderTypeType order_type, PriceType& price_type) {
  if (order_type == '1') {  // 市价
    price_type = PriceType::kAny;
  } else {
    price_type = PriceType::kLimit;
  }
}

void ConvertValidType(
  DstarApiValidTypeType valid_type, OrderVolumeCondition& volume_condition, OrderTimeCondition& time_condition) {
  if (valid_type == '1') {  // 即时全部
    volume_condition = OrderVolumeCondition::kAll;
    time_condition = OrderTimeCondition::kIoc;
  } else if (valid_type == '2') {  // 即时部分
    volume_condition = OrderVolumeCondition::kAny;
    time_condition = OrderTimeCondition::kIoc;
  } else {                                          // 当日有效
    volume_condition = OrderVolumeCondition::kAny;  // 当日有效默认为任意数量
    time_condition = OrderTimeCondition::kGfd;
  }
}

void DstarOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOrderField>(msg->pMainField);
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  // 赋值字段
  auto order_key = m_service->m_user_key + "|" + order_id;
  std::string ins_id = PullInsId(field->ContractNo1, m_service->m_contract_index.at(field->ContractNo1).second);
  // 组合
  if (field->CmbId != 0) {
    std::string ins_id2 = PullInsId(field->ContractNo2, m_service->m_contract_index.at(field->ContractNo2).second);
    ins_id = GetCombId(m_service->m_contract_index.at(field->ContractNo2).second, ins_id, ins_id2);
  }
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    if (o->order_id.empty()) {
      auto iter = m_service->m_send_time.find(order_id);
      if (iter != m_service->m_send_time.end()) {
        o->send_date_time = iter->second;
        m_service->m_send_time.erase(iter);
      }
      o->receive_date_time = NowAsEpochNano();
    }
    o->exchange_order_id = std::to_string(field->OrderId);
    o->user_key = m_service->m_user_key;
    o->user_id = m_service->m_req_login->user_id;
    o->order_id = order_id;
    o->investor_id = m_service->m_req_login->user_id;
    o->exchange_id = PullExchangeId(m_service->m_contract_index.at(field->ContractNo1).second);
    o->instrument_id = ins_id;
    o->status = PullOrderStatus(field->OrderState);
    if (msg->nErrorCode != 0) {
      o->status = OrderStatus::kDead;
      o->status_msg = GetErrorMsg(msg->nErrorCode);
    }
    o->direction = PullDir(field->Direct);
    o->offset = PullOffset(field->Offset, m_service->m_contract_index.at(field->ContractNo1).second);

    ConvertOrderType(field->OrderType, o->price_type);
    ConvertValidType(field->ValidType, o->volume_condition, o->time_condition);

    o->force_close_reason = ForceCloseReason::kNotForceClose;
    o->volume_orign = field->OrderQty;
    o->volume_left = field->OrderQty - field->MatchQty;
    o->limit_price = field->OrderPrice;
    o->hedge_flag = PullHedge(field->Hedge);
    o->is_swap_order = false;
    char time[20];
    ConvertTime(field->ExchInsertTime, time);
    o->insert_date_time = GetRealTradeTime(time, time + 8);
    if (o->status == OrderStatus::kDead && o->volume_left > 0) {
      ConvertTime(field->UpdateTime, time);
      o->dead_date_time = GetRealTradeTime(time, time + 8);
    }
  });
}

void DstarOrderTradeView::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiRspOrderInsertField>(msg->pMainField);
  auto req = std::static_pointer_cast<InsertOrder>(
    m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(field->Reference)));
  FCASSERT(req);
  auto order_id = std::to_string(field->Reference);
  auto order_key = m_service->m_user_key + "|" + order_id;
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    o->request_id = std::to_string(req->request_id);
    if (o->session_id == 0) {
      o->session_id = static_cast<int64_t>(m_service->m_auth_code);
    }
    if (o->order_id.empty()) {
      o->user_key = m_service->m_user_key;
      o->user_id = m_service->m_req_login->user_id;
      o->order_id = order_id;
      o->investor_id = m_service->m_req_login->user_id;
      o->exchange_id = req->exchange_id;
      o->instrument_id = req->instrument_id;
      o->status = OrderStatus::kAlive;
      if (msg->nErrorCode != 0) {
        o->status = OrderStatus::kDead;
        o->status_msg = GetErrorMsg(msg->nErrorCode);
      }
      o->direction = req->direction;
      o->offset = req->offset;
      o->time_condition = req->time_condition;
      o->volume_condition = req->volume_condition;
      o->price_type = req->price_type;
      o->force_close_reason = ForceCloseReason::kNotForceClose;
      o->volume_orign = req->volume;
      o->volume_left = req->volume;
      o->limit_price = req->limit_price;
      o->hedge_flag = req->hedge_flag;
      o->is_swap_order = req->is_swap_order;
    }
  });
}

void DstarOrderTradeView::OnRtnMatch(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiMatchField>(msg->pMainField);
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  int64_t ctp_order_id = static_cast<int64_t>(field->OrderId);
  if (IsOffer(ctp_order_id)) {
    order_id += field->Direct == 'B' ? "B" : "S";
  }
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(Order::MakeKey(m_service->m_user_key, order_id));
  std::string ins_id = PullInsId(field->ContractNo, m_service->m_contract_index.at(field->ContractNo).second);

  auto trade_key =
    Trade::MakeKey(m_service->m_user_key, std::to_string(field->MatchId), std::to_string(field->OrderId));
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->investor_id = field->AccountNo;
    trade->user_id = field->AccountNo;
    trade->trade_date_time = GetRealTradeTime(field->MatchTime, field->MatchTime + 8);
    trade->direction = PullDir(field->Direct);
    trade->exchange_id = PullExchangeId(m_service->m_contract_index.at(field->ContractNo).second);
    trade->instrument_id = ins_id;
    trade->exchange_trade_id = std::to_string(field->MatchId);
    trade->offset = PullOffset(field->Offset, m_service->m_contract_index.at(field->ContractNo).second);
    trade->exchange_order_id = std::to_string(field->OrderId);
    trade->hedge_flag = PullHedge(field->Hedge);
    trade->order_local_id = std::to_string(field->Reference);
    trade->price = field->MatchPrice;
    trade->volume = field->MatchQty;
    trade->user_key = m_service->m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->commission = field->Fee;
  });
}

void DstarOrderTradeView::OnRtnOffer(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<DstarApiOfferField>(msg->pMainField);
  m_order_id_set.insert(field->OrderId);
  std::string ins_id = PullInsId(field->ContractNo, m_service->m_contract_index.at(field->ContractNo).second);
  std::string order_id =
    IsRefValid(field->Reference) ? std::to_string(field->Reference) : std::to_string(field->OrderId);
  std::string buy_order_id = order_id + "B";
  std::string sell_order_id = order_id + "S";
  auto buy_order_key = Order::MakeKey(m_service->m_user_key, buy_order_id);
  auto sell_order_key = Order::MakeKey(m_service->m_user_key, sell_order_id);
  m_service->m_node_db->ReplaceRecord<Order>(buy_order_key, [=](std::shared_ptr<Order> order) {
    order->investor_id = m_service->m_req_login->user_id;
    order->user_id = m_service->m_req_login->user_id;
    order->direction = Direction::kBuy;
    order->exchange_id = PullExchangeId(m_service->m_contract_index.at(field->ContractNo).second);
    order->instrument_id = ins_id;
    order->exchange_order_id = std::to_string(field->OrderId);
    order->offset = PullOffset(field->BuyOffset, m_service->m_contract_index.at(field->ContractNo).second);
    order->hedge_flag = OrderHedgeFlag::kSpeculation;
    order->limit_price = field->BuyPrice;
    order->volume_orign = field->OrderQty;
    order->volume_left = field->OrderQty - field->BuyMatchQty;
    order->user_key = m_service->m_user_key;
    order->order_id = buy_order_id;
    order->status = PullOrderStatus(field->OrderState);
    if (msg->nErrorCode != 0 || order->volume_left == 0) {
      order->status = OrderStatus::kDead;
      order->status_msg = GetErrorMsg(msg->nErrorCode);
    }
    order->is_swap_order = false;
    order->time_condition = OrderTimeCondition::kIoc;
    order->volume_condition = OrderVolumeCondition::kAny;
    order->price_type = PriceType::kLimit;
    order->force_close_reason = ForceCloseReason::kNotForceClose;
    char time[20];
    ConvertTime(field->ExchInsertTime, time);
    order->insert_date_time = GetRealTradeTime(time, time + 8);
    if (order->status == OrderStatus::kDead && order->volume_left > 0) {
      ConvertTime(field->UpdateTime, time);
      order->dead_date_time = GetRealTradeTime(time, time + 8);
    }
  });
  m_service->m_node_db->ReplaceRecord<Order>(sell_order_key, [=](std::shared_ptr<Order> order) {
    order->investor_id = m_service->m_req_login->user_id;
    order->user_id = m_service->m_req_login->user_id;
    order->direction = Direction::kSell;
    order->exchange_id = PullExchangeId(m_service->m_contract_index.at(field->ContractNo).second);
    order->instrument_id = ins_id;
    order->exchange_order_id = std::to_string(field->OrderId);
    order->offset = PullOffset(field->SellOffset, m_service->m_contract_index.at(field->ContractNo).second);
    order->hedge_flag = OrderHedgeFlag::kSpeculation;
    order->limit_price = field->SellPrice;
    order->volume_orign = field->OrderQty;
    order->volume_left = field->OrderQty - field->SellMatchQty;
    order->user_key = m_service->m_user_key;
    order->order_id = sell_order_id;
    order->status = PullOrderStatus(field->OrderState);
    if (msg->nErrorCode != 0 || order->volume_left == 0) {
      order->status = OrderStatus::kDead;
      order->status_msg = GetErrorMsg(msg->nErrorCode);
    }
    order->is_swap_order = false;
    order->time_condition = OrderTimeCondition::kIoc;
    order->volume_condition = OrderVolumeCondition::kAny;
    order->price_type = PriceType::kLimit;
    order->force_close_reason = ForceCloseReason::kNotForceClose;
    char time[20];
    ConvertTime(field->ExchInsertTime, time);
    order->insert_date_time = GetRealTradeTime(time, time + 8);
    if (order->status == OrderStatus::kDead && order->volume_left > 0) {
      ConvertTime(field->UpdateTime, time);
      order->dead_date_time = GetRealTradeTime(time, time + 8);
    }
  });
}

