std::string GetProductId(std::string ins) {
  auto pos = std::find_if(ins.begin(), ins.end(), ::isdigit);
  return std::string(ins.begin(), pos);
}

// 获取带前缀组合合约
std::string GetCombId(std::string ex_id, std::string comb_ins_id) {
  if (comb_ins_id.find(" ") != std::string::npos)
    return comb_ins_id;
  auto pos = comb_ins_id.find("&");
  if (pos == std::string::npos)
    return comb_ins_id;
  std::string leg1_ins_id = comb_ins_id.substr(0, pos);
  std::string leg2_ins_id = comb_ins_id.substr(pos + 1);
  if (ex_id == "DCE" || ex_id == "GFEX") {
    if (GetProductId(leg1_ins_id) == GetProductId(leg2_ins_id)) {
      return "SP " + comb_ins_id;
    } else {
      return "SPC " + comb_ins_id;
    }
  } else if (ex_id == "CZCE") {
    if (GetProductId(leg1_ins_id) == GetProductId(leg2_ins_id)) {
      return "SPD " + comb_ins_id;
    } else {
      return "IPS " + comb_ins_id;
    }
  }
  return comb_ins_id;
}

std::string GetPacket(IF2UnPacker *lpUnPacker) {
  std::string ret;
  int i = 0, j = 0, k = 0;
  ret += "[";
  for (i = 0; i < lpUnPacker->GetDatasetCount(); ++i) {
    lpUnPacker->SetCurrentDatasetByIndex(i);
    for (j = 0; j < static_cast<int>(lpUnPacker->GetRowCount()); ++j) {
      ret += "{";
      for (k = 0; k < lpUnPacker->GetColCount(); ++k) {
        ret += (std::string(lpUnPacker->GetColName(k)) + ":" + GbkToUtf8(lpUnPacker->GetStrByIndex(k))) + ",";
      }
      ret += "},";
      lpUnPacker->Next();
    }
  }
  ret += "]";
  return ret;
}

char *hs_strncpy(char *dest, const char *src, size_t size) {
  if (dest == NULL)
    return 0;
  if (src == NULL) {
    dest[0] = 0;
    return 0;
  }
  char *ret = strncpy(dest, src, size - 1);
  dest[size - 1] = 0;
  return ret;
}

void DealErrorInfo(int nReturnCode, int nErrorNo, const char *pszErrorInfo, IF2UnPacker *lpUnPacker,
  std::shared_ptr<CHSRspInfoField> pRspInfo) {
  // ReturnCode（7域）为0，说明请求处理正常（包括通讯和业务）
  if (nReturnCode == 0) {
    // 不对Packer处理
    pRspInfo->ErrorID = 0;
    hs_strncpy(pRspInfo->ErrorMsg, "No Error", sizeof(pRspInfo->ErrorMsg));
  } else {
    // 判断如果Packer不为空，则取业务包中的错误信息
    if (lpUnPacker != NULL) {
      pRspInfo->ErrorID = lpUnPacker->GetInt("error_no");
      hs_strncpy(pRspInfo->ErrorMsg, lpUnPacker->GetStr("error_info"), sizeof(pRspInfo->ErrorMsg));
    } else {
      // 否则直接取ESB的ErrorNo（19域）和ErrorInfo（20域）
      pRspInfo->ErrorID = nErrorNo;
      hs_strncpy(pRspInfo->ErrorMsg, pszErrorInfo, sizeof(pRspInfo->ErrorMsg));
    }
  }
}

std::vector<std::string> split_string(const std::string &str, char splitter) {
  std::vector<std::string> strings;
  std::istringstream f(str);
  std::string s;
  while (std::getline(f, s, splitter)) {
    strings.push_back(s);
  }
  return strings;
}

