void UFXServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: 恒生柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

void UFXServiceImpl::ProcessMsg(std::pair<IBizMessage*, int> msg) {
  if (m_new_day)
    return;
  // 获取信息包
  int iLen = 0;
  void* pBuffer = const_cast<void*>(msg.first->GetContent(iLen));
  IF2UnPacker* pUnPacker = NewUnPacker(pBuffer, iLen);
  if (pUnPacker == nullptr)
    return;
  pUnPacker->AddRef();
  auto fun_id = msg.first->GetFunction();
  auto log_str = GetPacket(pUnPacker);

  // 构建回复信息
  auto RspInfo = std::make_shared<CHSRspInfoField>();
  DealErrorInfo(msg.first->GetReturnCode(), msg.first->GetErrorNo(), msg.first->GetErrorInfo(), pUnPacker, RspInfo);
  RspInfo->hSend = msg.second;
  m_query_planner.ProcessSpiMsg(RspInfo);
  if (fun_id == MSGCENTER_FUNC_SENDED) {
    m_logger.With(std::to_string(msg.first->GetIssueType()), log_str).Info("ufx_packer");
    if (RspInfo->ErrorID == 514657) {
      m_node_db->ReplaceRecord<Notice>(
        m_api_adapter->m_login_info->user_key + "|" + "error_password", [&](std::shared_ptr<Notice> n) {
          n->user_key = m_api_adapter->m_login_info->user_key;
          n->content = GbkToUtf8(RspInfo->ErrorMsg) + u8", 请重新登录";
          n->level = NoticeLevel::kError;
          n->content_type = NoticeType::kText;
          n->notice_time = NowAsEpochNano();
          n->source_type = SourceType::kFclib;
          n->notice_id = "error_password";
        });
      return;
    }
    // 如果是主推包, 查询消息编号
    auto it = m_msg_processor.find(msg.first->GetIssueType());
    if (it != m_msg_processor.end()) {
      for (auto& f : it->second) {
        f(pUnPacker, RspInfo);
      }
    }
  } else {
    // 非主推包查询功能号
    m_logger.With(std::to_string(fun_id), log_str).Info("ufx_packer");
    if (RspInfo->ErrorID == 514657) {
      m_node_db->ReplaceRecord<Notice>(
        m_api_adapter->m_login_info->user_key + "|" + "error_password", [&](std::shared_ptr<Notice> n) {
          n->user_key = m_api_adapter->m_login_info->user_key;
          n->content = GbkToUtf8(RspInfo->ErrorMsg) + u8", 请重新登录";
          n->level = NoticeLevel::kError;
          n->content_type = NoticeType::kText;
          n->notice_time = NowAsEpochNano();
          n->source_type = SourceType::kFclib;
          n->notice_id = "error_password";
        });
      return;
    }
    auto it = m_msg_processor.find(fun_id);
    if (it != m_msg_processor.end()) {
      for (auto& f : it->second) {
        f(pUnPacker, RspInfo);
      }
    }
  }

  // 释放
  if (pUnPacker != NULL)
    pUnPacker->Release();
}

int UFXServiceImpl::RunOnce() {
  // api运转一次
  int msg_count = 0;
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  m_query_planner.RunOnce();
  while (!m_recv_queue.empty()) {
    auto msg = m_recv_queue.front();
    ProcessMsg(msg);
    m_recv_queue.pop();
    msg.first->Release();
    msg_count++;
  }
  // 返回处理数据包数量
  return msg_count;
}

