UFXNotice::UFXNotice(
  UFXServiceImpl* service, UFXApiAdapter* api_adapter, structlog::Logger& parent_logger, UFXQueryPlanner& planner)
  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("rate_unit", reinterpret_cast<int64_t>(this)).Clone())
  , m_query_planner(planner) {
  m_service->RegisterCommandProcessor(QueryNotice::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqNotice338422(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingNotice::AID, [](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
  });
  m_service->RegisterMsgProcessor(338422, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspNotice338422(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(331100, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    if (RspInfo->ErrorID == 0) {
      SubNotice33113();
    }
  });
  m_service->RegisterMsgProcessor(33113, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRtnNotice33113(pUnPacker, RspInfo);
  });
}

void UFXNotice::ReqNotice338422(std::shared_ptr<UserCommand> command) {
  auto key = "QueryNotice";
  if (m_query_planner.AlreadyInQueue(key)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  m_query_planner.AddTask(key, UFXQueryPlanner::Priority::kLow, [=]() {
    // 创建业务包体
    IF2Packer* pPacker = NewPacker(2);
    pPacker->AddRef();
    pPacker->BeginPack();

    /// 加入字段名
    pPacker->AddField("op_branch_no", 'I', 5);
    pPacker->AddField("op_entrust_way", 'C', 1);
    pPacker->AddField("op_station", 'S', 255);
    pPacker->AddField("branch_no", 'I', 5);
    pPacker->AddField("client_id", 'S', 18);
    pPacker->AddField("fund_account", 'S', 18);
    pPacker->AddField("password", 'S', 13);
    pPacker->AddField("request_num", 'I', 10);
    pPacker->AddField("position_str", 'S', 100);
    // 加入对应的字段值
    pPacker->AddInt(m_api_adapter->m_op_branch_no);
    pPacker->AddChar(m_api_adapter->m_entrust_way);
    pPacker->AddStr(m_api_adapter->m_op_station.c_str());
    pPacker->AddInt(m_api_adapter->m_branch_no);
    pPacker->AddStr(m_api_adapter->m_client_id.c_str());
    pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
    pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
    pPacker->AddInt(1000);
    pPacker->AddStr("");

    /// 结束打包
    pPacker->EndPack();

    IBizMessage* pBizMessage = NewBizMessage();
    pBizMessage->AddRef();
    // 设置包头
    pBizMessage->SetFunction(338422);
    pBizMessage->SetPacketType(REQUEST_PACKET);
    // 设置包的内容
    pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
    // 异步发送
    int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);
    // 释放资源
    pPacker->FreeMem(pPacker->GetPackBuf());
    pPacker->Release();
    pBizMessage->Release();
    m_service->m_command_manager->SetCommandId(command, std::to_string(nRet));
    return nRet;
  });
}

void UFXNotice::OnRspNotice338422(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  auto req = m_service->m_command_manager->Update(std::to_string(RspInfo->hSend));
  SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
  if (RspInfo->ErrorID != 0)
    return;
  while (!pUnPacker->IsEOF()) {
    auto message_title = pUnPacker->GetStr("message_title");
    auto content = pUnPacker->GetStr("content");
    if (!message_title && !content) {
      pUnPacker->Next();
      continue;
    }
    std::string id = std::to_string(m_notice_id++);
    auto notice_key = m_api_adapter->m_login_info->user_key + "|" + id;
    m_service->GetNodeDb()->ReplaceRecord<Notice>(notice_key, [&](std::shared_ptr<future::Notice> n) {
      n->user_key = m_api_adapter->m_login_info->user_key;
      n->notice_id = id;
      n->content_type = NoticeType::kText;
      auto content = FormatNoticeTextContent(GbkToUtf8(GetPackStr(pUnPacker->GetStr("content"))));
      auto message_title = FormatNoticeTextContent(GbkToUtf8(GetPackStr(pUnPacker->GetStr("message_title"))));
#ifdef __linux__
      std::string enter = ": \n";
#else
      std::string enter = ": \r\n";
#endif
      n->content = message_title + enter + content;
      auto message_type = GetPackStr(pUnPacker->GetStr("message_type"));
      n->level = message_type == "1" ? NoticeLevel::kWarning : NoticeLevel::kOrdinary;
      n->source_type = SourceType::kBroker;
      auto notice_date = pUnPacker->GetStr("init_date");
      auto notice_time = pUnPacker->GetStr("update_time");
      if (notice_time && notice_date)
        n->notice_time = StringToEpochNano(notice_date, notice_time);
    });
    pUnPacker->Next();
  }
}

// 620001_33101 期货订阅委托成交回报
int UFXNotice::SubNotice33113() {
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  // 加入字段名
  pPacker->AddField("op_branch_no", 'I', 5);
  pPacker->AddField("op_entrust_way", 'C', 1);
  pPacker->AddField("op_station", 'S', 255);
  pPacker->AddField("branch_no", 'I', 5);
  pPacker->AddField("client_id", 'S', 18);
  pPacker->AddField("password", 'S', 13);
  pPacker->AddField("user_token", 'S', 512);
  pPacker->AddField("issue_type", 'I', 8);
  pPacker->AddField("fund_account", 'S', 18);

  // 加入对应的字段值
  pPacker->AddInt(m_api_adapter->m_op_branch_no);
  pPacker->AddChar(m_api_adapter->m_entrust_way);
  pPacker->AddStr(m_api_adapter->m_op_station.c_str());
  pPacker->AddInt(m_api_adapter->m_branch_no);
  pPacker->AddStr(m_api_adapter->m_client_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddInt(33101);
  pPacker->AddStr(m_api_adapter->m_fund_account.c_str());
  /// 结束打包
  pPacker->EndPack();

  IBizMessage* pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(MSGCENTER_FUNC_REG);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  pBizMessage->SetIssueType(33113);
  // 设置内容
  pBizMessage->SetKeyInfo(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();

  return nRet;
}

void UFXNotice::OnRtnNotice33113(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (vect.size() < 5) {
      FCASSERT(false);
      pUnPacker->Next();
      continue;
    }
    std::string id = std::to_string(m_notice_id++);
    auto notice_key = m_api_adapter->m_login_info->user_key + "|" + id;
    m_service->GetNodeDb()->ReplaceRecord<Notice>(notice_key, [&](std::shared_ptr<future::Notice> n) {
      n->user_key = m_api_adapter->m_login_info->user_key;
      n->notice_id = id;
      n->content_type = NoticeType::kText;
      auto content = FormatNoticeTextContent(GbkToUtf8(vect.at(Notice_content)));
      auto message_title = FormatNoticeTextContent(GbkToUtf8(vect.at(Notice_message_title)));
#ifdef __linux__
      std::string enter = ": \n";
#else
      std::string enter = ": \r\n";
#endif
      n->content = message_title + enter + content;
      auto message_type = vect.at(Notice_message_type);
      n->level = message_type == "1" ? NoticeLevel::kWarning : NoticeLevel::kOrdinary;
      n->source_type = SourceType::kBroker;
      n->notice_time = StringToEpochNano(vect.at(Notice_init_date).c_str(), vect.at(Notice_update_time).c_str());
    });
    pUnPacker->Next();
  }
}

