void UFXPositionAccount::OnRspPosition338303(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    std::string position_symbol =
      PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type"))) + "." + GetPackStr(pUnPacker->GetStr("futu_code"));
    bool is_combine = position_symbol.find('&') != std::string::npos;
    auto position_key = m_api_adapter->m_login_info->user_key + "|0|" + position_symbol;
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_api_adapter->m_login_info->user_key;
      target_position->investor_id = m_api_adapter->m_fund_account;
      target_position->risk_position = false;
      target_position->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
      target_position->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
      target_position->last_price = pUnPacker->GetDouble("futu_last_price");
      auto ins = m_service->m_md_helper->GetShmInstrument(target_position->Symbol(), true);
      future::SubPosition* subpos =
        GetSubPosition(target_position, PullDirection(GetPackStr(pUnPacker->GetStr("entrust_bs"))),
          PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type"))));
      if (GetPackStr(pUnPacker->GetStr("hedge_type")) == "2") {
        subpos->hedge_type = PositionHedgeType::kArbitrage;
      }
      if (pUnPacker->GetDouble("hold_margin") != 0) {
        subpos->margin = pUnPacker->GetDouble("hold_margin");
      }
      subpos->volume_today = pUnPacker->GetInt("real_current_amount");
      subpos->volume_today_frozen = subpos->volume_today - pUnPacker->GetInt("real_enable_amount");
      subpos->volume_his = pUnPacker->GetInt("old_current_amount");
      subpos->volume_his_frozen =
        subpos->volume_his - pUnPacker->GetInt("enable_amount") + pUnPacker->GetInt("real_enable_amount");
      subpos->volume_yesterday = pUnPacker->GetInt("begin_amount");
      subpos->float_profit = pUnPacker->GetDouble("hold_income_float");
      subpos->open_price = pUnPacker->GetDouble("average_price");
      subpos->position_price = pUnPacker->GetDouble("average_hold_price");
      subpos->position_profit = pUnPacker->GetDouble("hold_income");
      if (!is_combine)
        UpdatePositionProfit(target_position);
      if (!m_position_inited) {
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value_yesterday = ins->pre_settlement * subpos->volume_yesterday * ins->volume_multiple;
          if (subpos->direction == Direction::kSell)
            subpos->market_value_yesterday *= -1;
        }
      }
    });
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000) {
    UpdateAccountProfit(!m_position_inited);
    if (!m_position_inited) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_api_adapter->m_login_info->user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_api_adapter->m_login_info->user_key;
          p->backend = BackEnd::kUFX;
          p->position_ready = true;
        });
      m_position_inited = true;
    }
    if (auto req = m_service->m_command_manager->Update("RequireQryPosition"))
      SetCommandFinished(req);
  } else {
    pUnPacker->Last();
    std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
    ReqPosition338303(pos_str);
  }
}

void UFXPositionAccount::OnRspCombPosition338323(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  // 恒生持仓手数为0 就不会发回报
  auto& comb_pos_map = m_comb_position_view->GetNodes();
  for (auto& [key, _] : comb_pos_map) {
    m_service->GetNodeDb()->ReplaceRecord<Position>(key, [&](std::shared_ptr<Position> pos) {
      for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
             &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
        auto subpos = &((*(pos)).*p);
        subpos->volume_his = 0;
        subpos->volume_his_frozen = 0;
        subpos->volume_today = 0;
        subpos->volume_today_frozen = 0;
      }
    });
  }
  while (!pUnPacker->IsEOF()) {
    auto ins_id =
      GetCombId(PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type"))), GetPackStr(pUnPacker->GetStr("arbit_code")));
    std::string position_symbol = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type"))) + "." + ins_id;
    auto position_key = m_api_adapter->m_login_info->user_key + "|0|" + position_symbol;
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_api_adapter->m_login_info->user_key;
      target_position->investor_id = m_api_adapter->m_fund_account;
      target_position->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
      target_position->instrument_id = ins_id;
      future::SubPosition* subpos =
        GetSubPosition(target_position, PullDirection(GetPackStr(pUnPacker->GetStr("entrust_bs"))),
          PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type"))));
      if (GetPackStr(pUnPacker->GetStr("hedge_type")) == "2") {
        subpos->hedge_type = PositionHedgeType::kArbitrage;
      }
      if (pUnPacker->GetDouble("hold_margin") != 0) {
        subpos->margin = pUnPacker->GetDouble("hold_margin");
      }
      subpos->volume_today = pUnPacker->GetInt("current_amount");
      subpos->volume_yesterday = pUnPacker->GetInt("begin_amount");
    });
    pUnPacker->Next();
  }
  auto& comb_order_node_map = m_comb_order_view->GetNodes();
  for (const auto& [_, order_node] : comb_order_node_map) {
    auto order = order_node->Latest();
    auto key = Position::MakeKey(order->user_key, 0, order->Symbol());
    auto pos_node = m_service->m_node_db->GetNode<Position>(key);
    if (pos_node) {
      m_service->GetNodeDb()->ReplaceRecord<Position>(key, [&](std::shared_ptr<Position> pos) {
        auto subpos = GetSubPosition(pos, order->hedge_flag, order->direction, order->offset);
        subpos->volume_today_frozen += order->volume_left;
      });
    }
  }
}

void UFXPositionAccount::UpdatePositionVolumeByTrade(std::shared_ptr<const Trade> trade) {
  std::string symbol = trade->Symbol();
  std::string position_key = trade->user_key + "|0|" + symbol;
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
      position->user_key = trade->user_key;
      position->investor_id = trade->investor_id;
      position->exchange_id = trade->exchange_id;
      position->instrument_id = trade->instrument_id;
      auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
      auto offset_flag = trade->offset;
      if (offset_flag == Offset::kCloseToday && !ins->HasCloseToday()) {
        offset_flag = Offset::kClose;
      }
      SubPosition* calc_subpos = GetSubPosition(position, trade->hedge_flag, trade->direction, trade->offset);
      if (offset_flag == Offset::kOpen) {
        calc_subpos->volume_today += trade->volume;
      } else if (offset_flag == Offset::kCloseToday) {
        calc_subpos->volume_today -= trade->volume;
        calc_subpos->close_profit += trade->_other_close_profit + trade->_spec_close_profit;
      } else {
        /** 郑商所优先平投机，后平保值 */
        if (std::string(ins->exchange_id.data()) == "CZCE") {
          SubPosition* calc_subpos0 =
            GetSubPosition(position, OrderHedgeFlag::kSpeculation, trade->direction, trade->offset);
          calc_subpos0->close_profit += trade->_spec_close_profit;
          SubPosition* calc_subpos1 = GetSubPosition(position, OrderHedgeFlag::kHedge, trade->direction, trade->offset);
          calc_subpos1->close_profit += trade->_other_close_profit;
          auto spec_vol = std::min(calc_subpos0->Volume(), trade->volume);
          if (spec_vol > 0) {
            auto spec_vol_his = std::min(calc_subpos0->volume_his, spec_vol);
            if (spec_vol_his > 0) {
              calc_subpos0->volume_his -= spec_vol_his;
            }
            if (spec_vol > spec_vol_his) {
              calc_subpos0->volume_today -= (spec_vol - spec_vol_his);
            }
            if (calc_subpos0->Volume() == 0) {
              calc_subpos0->position_price = 0;
            }
            UpdatePositionVolumeFrozen(calc_subpos0);
          }
          auto hedge_vol = trade->volume - spec_vol;
          if (hedge_vol > 0) {
            auto hedge_vol_his = std::min(calc_subpos1->volume_his, hedge_vol);
            if (hedge_vol_his > 0) {
              calc_subpos1->volume_his -= hedge_vol_his;
            }
            if (hedge_vol > hedge_vol_his) {
              calc_subpos1->volume_today -= (hedge_vol - hedge_vol_his);
            }
            if (calc_subpos1->Volume() == 0) {
              calc_subpos1->position_price = 0;
            }
            UpdatePositionVolumeFrozen(calc_subpos1);
          }
        } else {
          calc_subpos->close_profit += trade->_other_close_profit + trade->_spec_close_profit;
          if (ins->HasCloseToday()) {
            calc_subpos->volume_his -= trade->volume;
            FCASSERT(calc_subpos->volume_his >= 0);
          } else {
            auto vol_his = std::min(calc_subpos->volume_his, trade->volume);
            if (vol_his > 0) {
              calc_subpos->volume_his -= vol_his;
            }
            if (trade->volume > vol_his) {
              calc_subpos->volume_today -= (trade->volume - vol_his);
            }
          }
        }
      }
      if (calc_subpos->Volume() == 0) {
        calc_subpos->position_price = 0;
      }
      if (!ins->HasCloseToday()) {
        UpdatePositionVolumeFrozen(calc_subpos);
      }
      UpdatePositionProfit(position);
    });
}

void UFXPositionAccount::UpdatePositionFrozenVolumeByOrder(std::shared_ptr<const Order> order) {
  // 计算冻结手数差额
  int delta_order_volume = (order->status == OrderStatus::kAlive) ? order->volume_left : 0;
  auto it = m_alive_orders.find(order->order_id);
  if (it != m_alive_orders.end()) {
    auto prev_order = it->second;
    int prev_order_volume = (prev_order->status == OrderStatus::kAlive) ? prev_order->volume_left : 0;
    delta_order_volume -= prev_order_volume;
  }
  if (delta_order_volume == 0)
    return;
  // 更新持仓
  auto ins = m_service->m_md_helper->GetShmInstrument(
    std::string(order->exchange_id) + "." + std::string(order->instrument_id), true);
  if (ins->product_class == md::ProductClass::kCombine) {
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2_ins = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    auto offset_flag = order->offset;
    if (offset_flag != Offset::kOpen)
      UpdateFrozenVolume(order, leg1_ins, order->direction, order->offset, delta_order_volume);
    auto direction = (order->direction == Direction::kBuy ? Direction::kSell : Direction::kBuy);
    if (order->is_swap_order)
      offset_flag = (offset_flag == Offset::kOpen ? Offset::kClose : Offset::kOpen);
    if (offset_flag != Offset::kOpen)
      UpdateFrozenVolume(order, leg2_ins, direction, offset_flag, delta_order_volume);
  } else {
    UpdateFrozenVolume(order, ins, order->direction, order->offset, delta_order_volume);
  }

  // alive 委托单都放入 m_alive_orders, 以备下次计算差额.
  if (order->status == OrderStatus::kDead) {
    m_alive_orders.erase(order->order_id);
  } else {
    m_alive_orders[order->order_id] = order;
  }
}

void UFXPositionAccount::UpdateFrozenVolume(std::shared_ptr<const Order> order,
  const std::optional<shm::ShmInstrument>& ins, Direction direction, Offset offset_flag, int delta_order_volume) {
  std::string position_key = order->user_key + "|0|" + ins->symbol.data();
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      position->user_key = order->user_key;
      position->investor_id = order->investor_id;
      position->exchange_id = order->exchange_id;
      position->instrument_id = ins->instrument_id.data();

      SubPosition* calc_subpos = GetSubPosition(position, order->hedge_flag, direction, offset_flag);
      auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
      if (offset_flag == Offset::kCloseToday && !ins->HasCloseToday()) {
        offset_flag = Offset::kClose;
      }
      if (offset_flag == Offset::kCloseToday) {
        calc_subpos->volume_today_frozen += delta_order_volume;
      } else if (ins->HasCloseToday()) {
        calc_subpos->volume_his_frozen += delta_order_volume;
      } else {
        if (std::string(ins->exchange_id.data()) == "CZCE") {
          SubPosition* calc_subpos0 = GetSubPosition(position, OrderHedgeFlag::kSpeculation, direction, offset_flag);
          SubPosition* calc_subpos1 = GetSubPosition(position, OrderHedgeFlag::kHedge, direction, offset_flag);
          if (delta_order_volume > 0) { /** 冻结时，先投机后保值 */
            auto frozen0 = std::min(delta_order_volume, calc_subpos0->Volume() - calc_subpos0->VolumeFrozen());
            if (frozen0 > 0)
              calc_subpos0->volume_his_frozen += frozen0;
            if (delta_order_volume > frozen0) {
              calc_subpos1->volume_his_frozen += delta_order_volume - frozen0;
            }
          } else { /** 解冻时，先保值后投机 */
            auto frozen1 = std::min(-delta_order_volume, calc_subpos1->VolumeFrozen());
            if (frozen1 > 0)
              calc_subpos1->volume_his_frozen -= frozen1;
            if (-delta_order_volume > frozen1) {
              calc_subpos0->volume_his_frozen -= -delta_order_volume - frozen1;
            }
          }
          UpdatePositionVolumeFrozen(calc_subpos0);
          UpdatePositionVolumeFrozen(calc_subpos1);
        } else {
          calc_subpos->volume_his_frozen += delta_order_volume;
          UpdatePositionVolumeFrozen(calc_subpos);
        }
      }
      UpdatePositionProfit(position);
    });
}

void UFXPositionAccount::OnRspAccount338300(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto account_key =
      Account::MakeKey(m_api_adapter->m_login_info->user_key, 0, PullCurr(GetPackStr(pUnPacker->GetStr("money_type"))));
    m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
      target_account->user_key = m_api_adapter->m_login_info->user_key;
      target_account->currency = PullCurr(GetPackStr(pUnPacker->GetStr("money_type")));
      target_account->investor_id = GetPackStr(pUnPacker->GetStr("fund_account"));
      target_account->available = pUnPacker->GetDouble("enable_balance");
      target_account->client_equity = pUnPacker->GetDouble("equity_balance");
      target_account->close_profit = pUnPacker->GetDouble("drop_income");
      target_account->commission = pUnPacker->GetDouble("business_fare");
      target_account->deposit = pUnPacker->GetDouble("in_balance");
      target_account->frozen_commission = pUnPacker->GetDouble("entrust_fare");
      target_account->frozen_margin = pUnPacker->GetDouble("pre_entrust_balance")
        - pUnPacker->GetDouble("entrust_premium") - pUnPacker->GetDouble("entrust_fare");
      target_account->margin = pUnPacker->GetDouble("hold_margin");
      target_account->position_profit = pUnPacker->GetDouble("hold_income");
      target_account->float_profit = pUnPacker->GetDouble("hold_income_float");
      double in_impawn_balance = pUnPacker->GetDouble("in_impawn_balance");
      target_account->pre_balance = pUnPacker->GetDouble("begin_equity_balance") + in_impawn_balance;
      target_account->withdraw = pUnPacker->GetDouble("out_balance");
      target_account->premium = pUnPacker->GetDouble("in_premium") - pUnPacker->GetDouble("out_premium");
      target_account->frozen_premium = pUnPacker->GetDouble("entrust_premium");
      target_account->balance = target_account->client_equity + target_account->option_market_value;
      if (target_account->client_equity > 0) {
        target_account->risk_ratio = target_account->margin / target_account->client_equity;
      }
      if (target_account->balance > 0) {
        target_account->ref_risk_ratio = target_account->margin / target_account->balance;
      }
      target_account->withdraw_quota = pUnPacker->GetDouble("fetch_balance");
      target_account->pre_mortgage = pUnPacker->GetDouble("begin_futu_impawn_balance");
      target_account->mortgage = pUnPacker->GetDouble("futu_impawn_balance");
    });
    pUnPacker->Next();
  }
  if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
    SetCommandFinished(req);
  m_service->m_node_db->ReplaceRecord<LoginContent>(
    m_api_adapter->m_login_info->user_key, [&](std::shared_ptr<future::LoginContent> p) {
      p->user_key = m_api_adapter->m_login_info->user_key;
      p->backend = BackEnd::kUFX;
      p->account_ready = true;
    });
}

void UFXPositionAccount::RequireQryPosition(bool is_critical) {
  if (!m_query_planner.AlreadyInQueue("RequireQryPosition")) {
    m_query_planner.AddTask(
      "RequireQryPosition", UFXQueryPlanner::Priority::kHigh,
      [=]() {
        auto ret = ReqPosition338303();
        return ret;
      },
      50, is_critical);
  }
  if (!m_query_planner.AlreadyInQueue("RequireQryCombPosition")) {
    m_query_planner.AddTask(
      "RequireQryCombPosition", UFXQueryPlanner::Priority::kHigh,
      [=]() {
        auto ret = ReqCombPosition338323();
        return ret;
      },
      50, is_critical);
  }
}

int UFXPositionAccount::ReqPosition338303(const std::string& pos_str) {
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();

  /// 加入字段名
  pPacker->AddField("op_branch_no", 'I', 5);
  pPacker->AddField("op_entrust_way", 'C', 1);
  pPacker->AddField("op_station", 'S', 255);
  pPacker->AddField("branch_no", 'I', 5);
  pPacker->AddField("client_id", 'S', 18);
  pPacker->AddField("fund_account", 'S', 18);
  pPacker->AddField("password", 'S', 13);
  pPacker->AddField("user_token", 'S', 512);
  pPacker->AddField("hedge_flag", 'C', 1);
  pPacker->AddField("request_num", 'I', 10);
  pPacker->AddField("position_str", 'S', 100);
