void UFXPositionAccount::OnRtnOrderTrade33101(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0) {
    return;
  }
  pUnPacker->First();
  RequireQryPosition(false);
  RequireQryAccount(false);
  while (!pUnPacker->IsEOF()) {
    // 解包到vector中
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (pUnPacker->GetChar("LY") == 'B') {
      // 成交回报
      auto trade_key = m_service->m_user_key + "|" + vect.at(Business_Id) + "|" + vect.at(Entrust_No);
      auto trade_node = m_service->m_node_db->GetNode<Trade>(trade_key);
      UpdatePositionVolumeByTrade(trade_node->Latest());
      UpdatePositionFrozenVolumeByOrder(trade_node->Latest()->order_pointer->Latest());
    } else {
      // 委托回报
      auto order_id = vect.at(Entrust_reference) + "|" + vect.at(Session_no);
      // 赋值字段
      auto order_key = m_api_adapter->m_login_info->user_key + "|" + order_id;
      auto order_node = m_service->m_node_db->GetNode<Order>(order_key);
      // 更新持仓
      if (order_node->Latest()->offset != Offset::kOpen || order_node->Latest()->is_swap_order) {
        UpdatePositionFrozenVolumeByOrder(order_node->Latest());
      }
    }
    pUnPacker->Next();
  }
}

void UFXPositionAccount::OnRspQueryTodayTrade338302(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0)
    return;
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto trade_key = m_api_adapter->m_login_info->user_key + "|" + GetPackStr(pUnPacker->GetStr("business_id")) + "|"
      + GetPackStr(pUnPacker->GetStr("entrust_no"));
    auto trade_node = m_service->m_node_db->GetNode<Trade>(trade_key);
    if (!trade_node) {
      pUnPacker->Next();
      continue;
    }
    auto trade = trade_node->Latest();
    std::string symbol = trade->Symbol();
    std::string position_key = trade->user_key + "|0|" + symbol;
    auto position_node =
      m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
        position->user_key = trade->user_key;
        position->investor_id = trade->investor_id;
        position->exchange_id = trade->exchange_id;
        position->instrument_id = trade->instrument_id;
        auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
        auto offset_flag = trade->offset;
        if (offset_flag == Offset::kCloseToday && !ins->HasCloseToday()) {
          offset_flag = Offset::kClose;
        }
        SubPosition* calc_subpos = GetSubPosition(position, trade->hedge_flag, trade->direction, trade->offset);
        if (offset_flag == Offset::kOpen) {
          return;
        } else if (offset_flag == Offset::kCloseToday) {
          calc_subpos->close_profit += trade->_other_close_profit + trade->_spec_close_profit;
        } else {
          /** 郑商所优先平投机，后平保值 */
          if (std::string(ins->exchange_id.data()) == "CZCE") {
            SubPosition* calc_subpos0 =
              GetSubPosition(position, OrderHedgeFlag::kSpeculation, trade->direction, trade->offset);
            calc_subpos0->close_profit += trade->_spec_close_profit;
            SubPosition* calc_subpos1 =
              GetSubPosition(position, OrderHedgeFlag::kHedge, trade->direction, trade->offset);
            calc_subpos1->close_profit += trade->_other_close_profit;
          } else {
            calc_subpos->close_profit += trade->_other_close_profit + trade->_spec_close_profit;
          }
        }
      });
    pUnPacker->Next();
  }
}

