void UFXPositionAccount::OnRspTransferLog332250(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0)
    return;
  pUnPacker->First();
  auto req = m_service->m_command_manager->Update(std::to_string(RspInfo->hSend));
  SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
  while (!pUnPacker->IsEOF()) {
    auto transfer_log = std::make_shared<TransferLog>();
    transfer_log->user_key = m_service->m_user_key;
    transfer_log->bank_id = GetPackStr(pUnPacker->GetStr("bank_no"));
    transfer_log->amount = pUnPacker->GetDouble("occur_balance");
    transfer_log->currency = PullCurr(GetPackStr(pUnPacker->GetStr("money_type")));
    transfer_log->error_id = pUnPacker->GetInt("error_no_t");

    // 检查是否为最终状态
    auto bktrans_status = pUnPacker->GetChar("bktrans_status");
    if (bktrans_status == '2' || bktrans_status == '3' || bktrans_status == '5' || bktrans_status == '8'
      || bktrans_status == 'Q') {
      transfer_log->error_msg = GbkToUtf8(GetPackStr(pUnPacker->GetStr("bank_error_info")));
    } else {
      // 不是最终状态，需要再次查询
      transfer_log->error_msg = "待确认 " + GbkToUtf8(GetPackStr(pUnPacker->GetStr("bank_error_info")));
      m_need_qry_transfer_log = true;
      m_qry_transfer_log_timer.Reset(std::chrono::milliseconds(3000));
    }

    transfer_log->bank_serial = GetPackStr(pUnPacker->GetStr("entrust_no"));
    transfer_log->future_serial = pUnPacker->GetInt("entrust_no");
    transfer_log->trade_type = GbkToUtf8(GetPackStr(pUnPacker->GetStr("trans_name")));
    std::string date = m_api_adapter->m_trading_day;
    auto time = pUnPacker->GetStr("entrust_time");
    transfer_log->date_time = GetRealTradeTime(date.c_str(), time);
    if (m_bank_cache[transfer_log->bank_id].size() == 1)
      transfer_log->bank_account = *(m_bank_cache.at(transfer_log->bank_id).begin());
    m_service->m_node_db->ReplaceRecord<TransferLog>(transfer_log);
    pUnPacker->Next();
  }
}

void UFXPositionAccount::UpdateAccountProfit(bool is_first) {
  auto account_node = m_service->GetNodeDb()->GetNode<Account>(m_api_adapter->m_login_info->user_key + "|0|CNY");
  if (!account_node)
    return;
  double position_profit = 0.0;
  double float_profit = 0.0;
  double option_buy_market_value = 0.0;
  double option_sell_market_value = 0.0;
  double option_buy_market_value_yesterday = 0.0;
  double option_sell_market_value_yesterday = 0.0;
  double future_market_value = 0.0;
  auto& position_node_map = m_position_view->GetNodes();
  for (auto& [key, position_node] : position_node_map) {
    if (!position_node->Snap())
      continue;
    auto ins = m_service->m_md_helper->GetShmInstrument(position_node->Snap()->Symbol(), true);
    if (ins->product_class != md::ProductClass::kCombine) {
      if (!isnan(position_node->Latest()->PositionProfit()) && ins->product_class != md::ProductClass::kOption)
        position_profit += position_node->Latest()->PositionProfit();
      if (!isnan(position_node->Latest()->FloatProfit()))
        float_profit += position_node->Latest()->FloatProfit();
      if (ins->product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
        if (is_first) {
          option_buy_market_value_yesterday += position_node->Latest()->LongMarketValueYesterday();
          option_sell_market_value_yesterday += position_node->Latest()->ShortMarketValueYesterday();
        }
      }
      if (ins->product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->ShortMarketValue() + position_node->Latest()->LongMarketValue();
    }
  }
  m_service->GetNodeDb()->ReplaceRecord<Account>(
    m_api_adapter->m_login_info->user_key + "|0|CNY", [=](std::shared_ptr<future::Account> account) {
      account->user_key = m_api_adapter->m_login_info->user_key;
      account->option_buy_market_value = option_buy_market_value;
      account->option_sell_market_value = option_sell_market_value;
      if (is_first) {
        account->option_buy_market_value_yesterday = option_buy_market_value_yesterday;
        account->option_sell_market_value_yesterday = option_sell_market_value_yesterday;
      }
      double old_option_market_value = account->option_market_value;
      account->option_market_value = option_buy_market_value + option_sell_market_value;
      account->balance += account->option_market_value - old_option_market_value;
      account->float_profit = float_profit;
      account->future_market_value = future_market_value;
      if (fabs(position_profit - account->position_profit) > 0.01) {
        double old_position_profit = account->position_profit;
        account->position_profit = position_profit;
        account->balance += account->position_profit - old_position_profit;
        account->client_equity += account->position_profit - old_position_profit;
        if (account->client_equity > 0) {
          account->risk_ratio = account->margin / account->client_equity;
        }
        char algorithm = '0';  // 0:所有浮动盈亏都记入可用资金;1:亏损都记入，赢利都不记;2:都不记;
        if (m_api_adapter->m_algorithm != '0') {
          algorithm = m_api_adapter->m_algorithm;
        }
        if (algorithm == '0') {
          account->available += account->position_profit - old_position_profit;
        } else if (algorithm == '1') {
          account->available -= std::min(old_position_profit, 0.0);
          account->available += std::min(position_profit, 0.0);
        }
      }
    });
}

void UFXPositionAccount::UpdatePositionProfit(std::shared_ptr<Position> position) {
  auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol(), true);
  if (ins->CheckQuote(m_api_adapter->m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  // 无法获得最新价, 取查询返回值
  if (std::isnan(position->last_price) || IsZero(position->last_price)) {
    for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
           &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
      auto subpos = &((*(position)).*p);
      if (subpos->direction == Direction::kBuy) {
        subpos->market_value =
          subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
      } else {
        subpos->market_value =
          -subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
        if (ins->product_class == md::ProductClass::kOption)
          subpos->market_value *= -1;
      }
    }
    return;
  }

  // 可以计算
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption)
        subpos->position_profit =
          (position->last_price - subpos->position_price) * subpos->Volume() * ins->volume_multiple;
      subpos->float_profit = (position->last_price - subpos->open_price) * subpos->Volume() * ins->volume_multiple;
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

int UFXPositionAccount::RunOnce() {
  int ret = 0;
  auto& target_position_node_map = m_position_view->GetNodes();
  for (auto& [pos_key, position_node] : target_position_node_map) {
    auto position = position_node->Latest();
    auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
    if (!ins.has_value() || ins->product_class == md::ProductClass::kCombine || ins->last_price == position->last_price
      || std::isnan(ins->last_price) || !ins->CheckQuote(m_api_adapter->m_trading_day))
      continue;
    m_service->GetNodeDb()->ReplaceRecord<Position>(pos_key, [this](std::shared_ptr<Position> calc_position) {
      UpdatePositionProfit(calc_position);
    });
    ret++;
  }
  if (ret > 0)
    UpdateAccountProfit();
  if (m_need_qry_transfer_log && m_qry_transfer_log_timer.IsExpired()) {
    int ret = ReqQryTransferLog332250();
    if (ret > 0) {
      m_need_qry_transfer_log = false;
    }
  }
  return ret;
}
