void UFXInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (m_api_adapter->m_session_no == 0) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto order_ref = req->order_ref;
  bool is_comb = req->instrument_id.find('&') != std::string::npos;
  if (is_comb && req->exchange_id == "CZCE") {
    auto pos = req->instrument_id.find(" ");
    req->instrument_id = req->instrument_id.substr(pos + 1);
  }
  auto price_type = is_comb ? PushPriceType(req->price_type, req->exchange_id) : PushPriceType(req->price_type);
  int ret = InsertOrder338204(PushExType(req->exchange_id), req->instrument_id.c_str(), PushDirection(req->direction),
    PushOffset(req->offset), req->volume, req->limit_price, std::to_string(order_ref), PushHedge(req->hedge_flag),
    PushTimeCondition(req->time_condition), PushVolumeCondition(req->volume_condition), price_type, is_comb,
    req->is_swap_order);
  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + std::to_string(ret));
  m_service->m_send_time[req->order_id] = NowAsEpochNano();
  if (ret <= 0) {
    SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
  }
}

int UFXInsertCancelOrder::InsertOrder338204(const char* pszExchangeType, const char* pszFutuCode, char cEntrustBs,
  char cFuturesDirection, int nEntrustAmount, double dFutuEntrustPrice, std::string order_ref, char hedge,
  char time_condition, char volume_condition, const char* entrust_prop, bool is_comb, bool is_swap) {
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  /// 加入字段名
  pPacker->AddField("user_token", 'S', 512);    // user_token
  pPacker->AddField("op_branch_no", 'I', 5);    // 操作分支机构
  pPacker->AddField("op_entrust_way", 'C', 1);  // 委托方式
  pPacker->AddField("op_station", 'S', 255);    // 站点地址
  pPacker->AddField("branch_no", 'I', 5);       // 分支机构
  pPacker->AddField("client_id", 'S', 18);      // 客户编号
  pPacker->AddField("fund_account", 'S', 18);   // 资产账户
  pPacker->AddField("password", 'S', 13);       // 密码
  // pPacker->AddField("futures_account", 'S', 12);        // 交易编码
  pPacker->AddField("futu_exch_type", 'S', 4);          // 交易类别
  pPacker->AddField("entrust_bs", 'C', 1);              // 买卖方向
  pPacker->AddField("futures_direction", 'C', 1);       // 开平仓方向
  pPacker->AddField("hedge_type", 'C', 1);              // 投机/套保类型
  pPacker->AddField("futu_entrust_price", 'D', 12, 6);  // 委托价格
  pPacker->AddField("entrust_amount", 'I');             // 委托数量
  pPacker->AddField("time_condition", 'S', 3);          // 有效期
  pPacker->AddField("volume_condition", 'S', 32);       // 成交量类型
  if (is_comb) {
    pPacker->AddField("arbit_code", 'S', 128);  // 组合合约代码
    if (is_swap) {
      pPacker->AddField("futu_code", 'S', 30);    // 合约代码 第一腿
      pPacker->AddField("second_code", 'S', 30);  // 合约代码 第二腿
      pPacker->AddField("weave_type", 'C');       // 组合类型
    }
  } else {
    pPacker->AddField("futu_code", 'S', 30);  // 合约代码
  }
  pPacker->AddField("entrust_prop", 'S', 3);        // 委托属性
  pPacker->AddField("entrust_reference", 'S', 32);  // 委托引用
  // 加入对应的字段值
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddInt(m_api_adapter->m_op_branch_no);
  pPacker->AddChar(m_api_adapter->m_entrust_way);
  pPacker->AddStr(m_api_adapter->m_op_station.c_str());
  pPacker->AddInt(m_api_adapter->m_branch_no);
  pPacker->AddStr(m_api_adapter->m_client_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  pPacker->AddStr(pszExchangeType);
  pPacker->AddChar(cEntrustBs);
  pPacker->AddChar(cFuturesDirection);
  pPacker->AddChar(hedge);
  pPacker->AddDouble(dFutuEntrustPrice);
  pPacker->AddInt(nEntrustAmount);
  pPacker->AddChar(time_condition);
  pPacker->AddChar(volume_condition);
  if (is_comb) {
    pPacker->AddStr(pszFutuCode);  // 组合合约代码
    if (is_swap) {
      std::string ins_id = pszFutuCode;
      auto pos = ins_id.find('&');
      pPacker->AddStr(ins_id.substr(0, pos).c_str());
      pPacker->AddStr(ins_id.substr(pos + 1).c_str());
      pPacker->AddChar('6');
    }
  } else {
    pPacker->AddStr(pszFutuCode);  // 合约代码
  }
  pPacker->AddStr(entrust_prop);

  pPacker->AddStr(order_ref.c_str());

  /// 结束打包
  pPacker->EndPack();

  IBizMessage* pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(338204);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  // 设置包内容
  pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();

  return nRet;
}

void UFXInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (m_api_adapter->m_session_no == 0) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  req->status = UserCommand::Status::kStarted;
  auto it = m_order_alive.find(req->order_id);
  if (it == m_order_alive.end()) {
    SetCommandFinished(req, -1, u8"fclib: 报单编号不存在");
    return;
  }
  auto ret = ReqCancelOrder338217(it->second);
  if (ret <= 0) {
    SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
    return;
  }
  m_order_cancel[req->order_id] = ret;
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::to_string(ret));
}

