void UFXInsertCancelOrder::OnRspInsertOrder338204(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(RspInfo->hSend));
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    pUnPacker->Next();
  }
}

void UFXInsertCancelOrder::OnRspCancelOrder338217(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    if (RspInfo->ErrorID != 0) {
      auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(RspInfo->hSend));
      SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    }
    pUnPacker->Next();
  }
}

void UFXInsertCancelOrder::OnRtnOrderTrade33101(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    // 解包到vector中
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (pUnPacker->GetChar("LY") != 'B') {
      // 委托回报
      auto order_id = vect.at(Entrust_reference) + "|" + vect.at(Session_no);
      // alive 委托单都放入 m_alive_orders, 以备撤单时使用.
      if (PullStatus(vect.at(Entrust_status)) == OrderStatus::kDead) {
        m_order_alive.erase(order_id);
      } else {
        m_order_alive[order_id] = std::make_tuple(
          std::atoi(vect.at(Entrust_no).c_str()), std::atoi(vect.at(Session_no).c_str()), vect.at(Entrust_reference));
      }
      // 撤单反馈
      if (vect.at(Entrust_status) == "6") {
        auto it = m_order_cancel.find(order_id);
        if (it != m_order_cancel.end()) {
          auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(it->second));
          m_order_cancel.erase(it);
          if (req) {
            SetCommandFinished(req, 0, u8"成功");
            return;
          }
        }
      }
    }
    pUnPacker->Next();
  }
}

void UFXInsertCancelOrder::OnRspQueryTodayOrder338301(
  IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto order_id =
      GetPackStr(pUnPacker->GetStr("entrust_reference")) + "|" + GetPackStr(pUnPacker->GetStr("session_no"));
    // alive 委托单都放入 m_alive_orders, 以备撤单时使用.
    if (PullStatus(GetPackStr(pUnPacker->GetStr("entrust_status"))) == OrderStatus::kDead) {
      m_order_alive.erase(order_id);
    } else {
      m_order_alive[order_id] = std::make_tuple(pUnPacker->GetInt("entrust_no"), pUnPacker->GetInt("session_no"),
        GetPackStr(pUnPacker->GetStr("entrust_reference")));
    }
    pUnPacker->Next();
  }
}

