  m_logger.With("req", req->ToJson()).With("request_id", nRet).Info("ReqQryQueryMaxVolume");
}

void UFXInsertCancelOrder::OnRspQryMaxOrderVolume338201(
  IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(
    m_service->m_command_manager->Update("ReqQryQueryMaxVolume" + std::to_string(RspInfo->hSend)));
  if (RspInfo->ErrorID != 0 || !req) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    req->volume = pUnPacker->GetInt("max_entrust_amount");
    SetCommandFinished(req);
    pUnPacker->Next();
  }
}

