/*******************************************************************************
 * @file ufx_query_planner.h
 * @brief UFX接口查询管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_UFX_QUERY_PLANNER_H
#define FCLIB_UFX_QUERY_PLANNER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <list>
#include <memory>
#include <string>
#include <map>
#include <functional>
#include "structlog/structlog.h"
#include "fclib/utils/timer.h"
#include "model_ufx.h"

namespace fclib {
namespace future {
namespace ufx {

/*
UFXQueryPlanner 是CTP接口查询任务管理器.

CTP 接口对查询任务有流量限制. 按照CTP开发文档, 限制规则如下:

* 查询流控是指用户当前Session在做查询的时候每秒内允许的最大请求笔数。
* 查询流控配置在交易前置组件上，配置项为【QryFreq】。其中API内置了在途查询流控1笔。
* 自从穿透式监管版本以后，API在连接交易前置时，会去查询到前置的查询流控设置（该设置配置在front_se组件）。假设前置配置了2笔/秒，那么连接该前置的API每秒只能发起2笔查询请求。
* 但是要注意，不管怎么配置，API都内置了在途流控，在途查询流控为1笔。即，当前这笔查询请求发出后，在未收完所有的查询响应前，不能发起下一笔查询请求。
* 如果超过API内置的在途流控，则查询请求的返回值为-2，表示未处理请求超过许可数。
* 如果超过交易前置配置的查询流控，则会触发OnRspError，并提示：“CTP：查询未就绪，请稍后重试”
* 所有ReqQuery开头查询函数不受流控限制，原因是此类函数都是通过交易核心处理的，不通过查询核心。

未在接口文档中写明, 但曾经遇到过的异常情况包括:

* 查询无任何返回. 调用查询函数时, 返回值为0, 此后未收到任何回调通知. 这又可以细分为两种情况:
    * 偶发性的查询无返回, 重试可能成功.
    * 由于后台配置原因, 导致某个查询反复重试始终无返回.
* 回包的RequestID与请求时填写的RequestID不一致.


我们希望实现的目标是:

* 能最大效率的使用CTP接口查询能力.
* 需求方希望只提出一次任务需求, 当查询可用时任务会被执行, 而不需要任务发起方反复检查.
* 各查询任务具有优先级差异, 某些任务希望获得更优先的执行权.
* 鉴于后台提供的查询服务不能保证可靠回应, 需要使用某种超时机制避免系统锁死.
* 为最大限度提高系统可用性, 需求方可以指定某些查询是"关键"的.
*   * 对于标注为"关键"的查询, 必须成功后才会从任务队列中移除
*   * 对于未标注为"关键"的查询, 即使查询失败或查询超时, 也会从任务队列中移除, 以便后续的查询任务可以正确执行.
* 某些场景下, 需要为查询指定一个"发出冷静期", 避免过度发出查询. 例如, 我们希望每当收到成交记录时重新查询持仓情况,
但在登录过程中, 可能会连续收到几万条成交记录, 这可能导致发出数百次持仓查询, 增加了登录耗时.

 */
class UFXQueryPlanner {
 public:
  explicit UFXQueryPlanner(structlog::Logger& parent_logger);

  /**
   * 查询超时时间常量. 当一个查询发出后, 连续经过 query_timeout 时间没有收到任何回应, 判定此查询超时.
   */
  static inline std::chrono::milliseconds QUERY_TIMEOUT = std::chrono::milliseconds(5000);

  /**
   * 查询任务优先级. 当有多个查询需求时, 优先执行优先级高的查询任务. 若同一优先级有多个任务, 按先进先出原则执行.
   */
  enum class Priority : int {
    /**
     * 最高优先级. 通常用于优先处理用户的工作焦点, 用户正在等待这个查询的结果, 要求这个查询任务立即执行
     *
     * 例如, 用户已经点击了"查询银行账户余额", 明确期待拿到结果, 这个查询就应该给与 kPriorityImmediately 优先级.
     *
     * 登录过程中的必要查询也是这一级, 因为用户一定是在盯着等登录过程尽快完成.
     */
    kImmediately = 0,

    /**
     * 高优先级. 通常情况下, 这个查询的结果都是用户关心的重点. 目前用于:
     *
     * * 成交后更新持仓信息等.
     */
    kHigh = 1,

    /**
     * 普通优先级. 放置其它查询任务.
     */
    kNormal = 2,

    /**
     * 低优先级. 用于安排那些用户现在还用不到, 但可能以后会需要的信息, 这类信息可以利用API空闲时间来做查询.
     *
     * 例如: 某合约用户并无持仓, 但在自选报价表里, 用户可能会交易它. 可以安排提前查询保证金率, 以备下单时使用.
     */
    kLow = 3,
  };

  /**
   * 每个 TaskItem 表示一项待执行的查询任务.
   */
  struct QueryTask {
    /**
     * 每个任务都具有一个KEY. 相同KEY的任务被认为是等价的. 如果任务队列中已经存在某个KEY的查询任务,
     * 再发起一个具有相同KEY的任务, 则仅保留原有的任务, 新的任务被抛弃.
     */
    std::string key;

    /**
     * 优先级. 任务执行顺序按优先级排列. 相同优先级的按照先进先出原则操作.
     */
    Priority priority;

    /**
     * 需要执行的查询函数. 这个函数应当接受一个 int 类型的 request_id, 并返回一个查询请求函数调用返回值.
     */
    std::function<int(void)> query_func;

    /**
     * 关键查询标志.
     * * 若 critical == true, 查询必须成功后才会从任务队列中移除
     * * 若 critical == false, 即使查询失败或查询超时, 也会从任务队列中移除, 以便后续的查询任务可以正确执行.
     */
    bool critical = false;

    /**
     * 查询冷静期.
     * * 当 cooling_off_ms == 0 时, 表示要求查询尽快发出.
     * * 当 cooling_off_ms > 0 时, 表示从提交任务时开始, 至少等待 cooling_off_ms 毫秒才发出查询.
     * 如果在发出查询前又有同KEY的查询任务提出, 则计时器重置, 还需要再等待 cooling_off_ms 毫秒才发出查询.
     */
    int cooling_off = 0;

    /**
     * 查询冷静期结束时点.
     */
    std::chrono::milliseconds cooling_end_time;

    int hSend = 0;
  };

  /**
   * 任务表. 用于查找特定KEY的任务是否已经存在.
   */
  std::map<std::string, std::shared_ptr<QueryTask>> m_task_map;

  /**
   * 正在执行的查询任务. 如果没有则为 nullptr.
   */
  std::shared_ptr<QueryTask> m_running_task;

  /**
   * 等待执行的查询任务队列. 按照预定的执行顺序排序.
   */
  std::list<std::shared_ptr<QueryTask>> m_task_queue;

  /**
   * 还在冷静期等待的查询任务. 按照冷静期结束的时间远近排序.
   */
  std::list<std::shared_ptr<QueryTask>> m_cooling_queue;

  /**
   * 检查一个任务是否已经在任务队列中.
   */
  bool AlreadyInQueue(const std::string& key);

  /**
   * 提起一个任务.
   */
  void AddTask(const std::string& key, Priority priority, std::function<int(void)> query_func, int cooling_off = 0,
    bool critical = false);

  /**
   * 处理查询返回.
   */
  void ProcessSpiMsg(std::shared_ptr<CHSRspInfoField> RspInfo);

  /**
   * 将m_running_task指向的任务从队列中移除.
   */
  void RemoveRunningTask();

  /**
   * 尝试执行一个任务.
   *
   * 每次RunOnce时, 从查询队列中拿出一项交给API执行, 若API返回"超时", 则此任务留到下一次执行. 否则,
   * 将此任务从队列中移除.
   */
  void RunOnce();

  // 仅用于测试
  void ClearTask();

  // 仅用于测试
  std::map<std::string, std::shared_ptr<QueryTask>>& GetTaskMap();

  Timer m_query_timeout_timer;
  Timer m_cooling_off_timer;
  structlog::Logger m_logger;
};

}  // namespace ufx
}  // namespace future
}  // namespace fclib

#endif // FCLIB_UFX_QUERY_PLANNER_H

/*******************************************************************************
 * @file ufx_query_planner.cpp
 * @brief UFX接口查询管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "ufx_query_planner.h"

#include <algorithm>
#include <memory>
#include <string>
#include <map>

namespace fclib {
namespace future {
namespace ufx {

UFXQueryPlanner::UFXQueryPlanner(structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("query_planner", reinterpret_cast<int64_t>(this)).Clone()) {}

bool UFXQueryPlanner::AlreadyInQueue(const std::string& key) {
  auto it = m_task_map.find(key);
  if (it == m_task_map.end())
    return false;
  return true;
}

void UFXQueryPlanner::AddTask(
  const std::string& key, Priority priority, std::function<int(void)> query_func, int cooling_off, bool critical) {
  auto it = m_task_map.find(key);
  if (it != m_task_map.end()) {
    // 任务已在队列中, 更新冷静值.
    auto task = it->second;
    if (task->cooling_off > 0)
      task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    return;
  }
  std::shared_ptr<QueryTask> task = std::make_shared<QueryTask>(QueryTask({
    key,
    priority,
    query_func,
    critical,
    cooling_off,
  }));
  m_task_map[task->key] = task;
  if (task->cooling_off == 0) {
    m_task_queue.push_back(task);
    m_task_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->priority < b->priority;
    });
    RunOnce();
  } else {
    task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    m_cooling_queue.push_back(task);
    m_cooling_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->cooling_end_time < b->cooling_end_time;
    });
  }
}

void UFXQueryPlanner::ProcessSpiMsg(std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (!m_running_task)
    return;
  if (RspInfo->hSend == m_running_task->hSend) {
    // 收到查询回包, 有且只有下述两种情况需要重发, 否则移除.
    // * ErrorID = 61: 触发流控, 需要再次发送
    // * ErrorID != 0 且 critical: 关键请求发生错误, 再次发送
    if (RspInfo->ErrorID == 61 || (RspInfo->ErrorID != 0 && m_running_task->critical)) {
      m_running_task.reset();
    } else {
      RemoveRunningTask();
    }
  }
}

void UFXQueryPlanner::RemoveRunningTask() {
  if (!m_running_task)
    return;
  m_task_map.erase(m_running_task->key);
  for (auto it = m_task_queue.begin(); it != m_task_queue.end(); ++it) {
    auto& t = *it;
    if (t == m_running_task) {
      m_task_queue.erase(it);
      break;
    }
  }
  m_running_task.reset();
}

void UFXQueryPlanner::RunOnce() {
  if (m_query_timeout_timer.IsExpired() && m_running_task) {
    if (m_running_task->critical) {
      m_running_task.reset();
    } else {
      RemoveRunningTask();
    }
  }
  if (m_running_task)
    return;
  bool need_resort = false;
  while (!m_cooling_queue.empty()) {
    auto now = m_cooling_off_timer.GetTime();
    auto t = m_cooling_queue.front();
    if (t->cooling_end_time > now)
      break;
    m_task_queue.push_back(t);
    m_cooling_queue.pop_front();
    need_resort = true;
  }
  if (m_task_queue.empty())
    return;
  if (need_resort) {
    m_task_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->priority < b->priority;
    });
  }
  auto& t = m_task_queue.front();
  auto ret = t->query_func();
  t->hSend = ret;
  if (ret >= 0) {
    m_running_task = t;
    m_query_timeout_timer.Reset(QUERY_TIMEOUT);
  }
}

void UFXQueryPlanner::ClearTask() {
  m_task_map.clear();
}

std::map<std::string, std::shared_ptr<UFXQueryPlanner::QueryTask>>& UFXQueryPlanner::GetTaskMap() {
  return m_task_map;
}

