UFXOrderTradeView::UFXOrderTradeView(
  UFXServiceImpl* service, UFXApiAdapter* api_adapter, structlog::Logger& parent_logger)
  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone())
  , m_index(0) {
  m_service->RegisterMsgProcessor(338204, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspOrder338204(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(33101, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRtnOrderTrade33101(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(331100, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspLogIn_331100(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(338301, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspQueryTodayOrder338301(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(338302, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspQueryTodayTrade338302(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(338217, [this](IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspCancelOrder338217(pUnPacker, RspInfo);
  });
}

void UFXOrderTradeView::OnRspCancelOrder338217(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  if (RspInfo->ErrorID != 0)
    return;
  while (!pUnPacker->IsEOF()) {
    auto order_id = ToFclibOrderId(
      std::atoi(GetPackStr(pUnPacker->GetStr("entrust_reference")).c_str()), pUnPacker->GetInt("session_no"));
    // 赋值字段
    auto order_key = m_service->m_user_key + "|" + order_id;
    auto node = m_service->GetNodeDb()->GetNode<Order>(order_key);
    if (!node) {
      pUnPacker->Next();
      continue;
    }
    m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
      o->dead_date_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pUnPacker->GetStr("entrust_time"));
    });
    pUnPacker->Next();
  }
}

std::shared_ptr<future::OrderNode> UFXOrderTradeView::GetMatchOrder(std::vector<std::string>& vect) {
  auto map_key = vect.at(Entrust_no) + "|" + PullExId(vect.at(Futu_exch_type));
  auto it = m_trade_order_map.find(map_key);
  if (it == m_trade_order_map.end())
    return nullptr;
  return it->second;
}

void UFXOrderTradeView::AddTradeToCache(std::vector<std::string>& vect) {
  auto map_key = vect.at(Entrust_no) + "|" + PullExId(vect.at(Futu_exch_type));
  m_trade_cache[map_key].insert(vect);
}

std::shared_ptr<future::TradeNode> UFXOrderTradeView::ProcessTrade(
  std::vector<std::string>& vect, std::shared_ptr<future::OrderNode> order_node, std::string user_key) {
  auto trade_key = user_key + "|" + vect.at(Business_Id) + "|" + vect.at(Entrust_No);
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->index = ++m_index;
    trade->investor_id = vect.at(Fund_Account);
    trade->user_id = vect.at(Fund_Account);
    trade->trade_date_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), vect.at(Business_Time).c_str());
    trade->direction = PullDirection(vect.at(Entrust_Bs));
    trade->exchange_id = PullExId(vect.at(Futu_Exch_Type));
    trade->instrument_id = vect.at(Futu_Code);
    trade->exchange_trade_id = vect.at(Business_Id);
    trade->offset = PullOffset(vect.at(Futures_Direction));
    trade->exchange_order_id = vect.at(Entrust_No);
    trade->hedge_flag = PullHedge(vect.at(Hedge_Type));
    trade->order_local_id = vect.at(Entrust_Reference);
    trade->price = stod(vect.at(Futu_Business_price));
    trade->volume = atoi(vect.at(Business_Amount).c_str());
    trade->trader_id = vect.at(Business_Id);
    trade->user_key = user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_node->Latest()->order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->commission = stod(vect.at(Delta_Business_fare));
    if (trade->hedge_flag == OrderHedgeFlag::kSpeculation) {
      trade->_spec_close_profit = stod(vect.at(Delta_Drop_income));
      trade->_spec_close_profit_by_open = stod(vect.at(Delta_Drop_income_float));
    } else {
      trade->_other_close_profit = stod(vect.at(Delta_Drop_income));
      trade->_other_close_profit_by_open = stod(vect.at(Delta_Drop_income_float));
    }
  });
  m_service->m_node_db->ReplaceRecord<Order>(order_node->Latest()->GetKey(), [=](std::shared_ptr<Order> order) {
    int volume_left = atoi(vect.at(Entrust_Amount).c_str()) - atoi(vect.at(Total_Business_amount).c_str());
    if (order->volume_left > volume_left)
      order->volume_left = volume_left;
    if (order->status != OrderStatus::kDead) {
      order->status = PullStatus(vect.at(Entrust_Status));
    }
  });
  return trade_node;
}

void UFXOrderTradeView::ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node) {
  const std::string& cache_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  auto it = m_trade_cache.find(cache_key);
  if (it == m_trade_cache.end())
    return;
  auto& trades = it->second;
  for (auto trade : trades) {
    ProcessTrade(trade, order_node, order_node->Latest()->user_key);
  }
  m_trade_cache.erase(it);
}

void UFXOrderTradeView::OnRspOrder338204(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto order_id = ToFclibOrderId(
      std::atoi(GetPackStr(pUnPacker->GetStr("entrust_reference")).c_str()), m_api_adapter->m_session_no);
    // 赋值字段
    auto order_key = m_service->m_user_key + "|" + order_id;
    m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
      auto req = std::static_pointer_cast<InsertOrder>(
        m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(RspInfo->hSend)));
      FCASSERT(req);
      o->request_id = std::to_string(req->request_id);
      if (o->order_id.empty()) {
        o->order_ref = GetPackStr(pUnPacker->GetStr("entrust_reference"));
        o->session_id = m_api_adapter->m_session_no;
        o->user_key = m_service->m_user_key;
        o->user_id = m_api_adapter->m_login_info->user_id;
        o->order_id = order_id;
        auto iter = m_service->m_send_time.find(o->order_id);
        if (iter != m_service->m_send_time.end()) {
          o->send_date_time = iter->second;
          m_service->m_send_time.erase(iter);
        }
        o->receive_date_time = NowAsEpochNano();
        o->investor_id = m_api_adapter->m_login_info->user_id;
        o->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
        o->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
        o->force_close_reason = ForceCloseReason::kNotForceClose;
        std::string comb_id = GetPackStr(pUnPacker->GetStr("arbit_code"));
        if (!comb_id.empty())
          o->instrument_id = GetCombId(o->exchange_id, GetPackStr(pUnPacker->GetStr("arbit_code")));
        auto status = pUnPacker->GetStr("entrust_status");
        if (status) {
          o->status = PullStatus(pUnPacker->GetStr("entrust_status"));
        } else if (RspInfo->ErrorID != 0) {
          o->status = OrderStatus::kDead;
          o->status_msg = GbkToUtf8(RspInfo->ErrorMsg);
        }
        o->direction = PullDirection(GetPackStr(pUnPacker->GetStr("entrust_bs")));
        o->offset = PullOffset(GetPackStr(pUnPacker->GetStr("futures_direction")));
        if (RspInfo->ErrorID == 0) {
          o->time_condition = PullTimeCondition(GetPackStr(pUnPacker->GetStr("time_condition")));
          o->volume_condition = PullVolumeCondition(GetPackStr(pUnPacker->GetStr("volume_condition")));
        } else {
          o->time_condition = req->time_condition;
          o->volume_condition = req->volume_condition;
        }
        o->volume_orign = pUnPacker->GetInt("entrust_amount");
        o->volume_left = o->volume_orign;
        o->limit_price = pUnPacker->GetDouble("futu_entrust_price");
        o->price_type = PullPriceType(GetPackStr(pUnPacker->GetStr("entrust_prop")));
        o->hedge_flag = PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type")));
        if (pUnPacker->GetChar("weave_type") == '6')
          o->is_swap_order = true;
      }
    });
    pUnPacker->Next();
  }
  return;
}

void UFXOrderTradeView::OnRtnOrderTrade33101(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    // 解包到vector中
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (pUnPacker->GetChar("LY") == 'B') {
      if (vect.size() < 44) {
        pUnPacker->Next();
        continue;
      }
      // 成交回报
      auto order_node = GetMatchOrder(vect);
      if (!order_node) {
        FCASSERT(false);
        AddTradeToCache(vect);
        pUnPacker->Next();
        continue;
      }
      ProcessTrade(vect, order_node, m_api_adapter->m_login_info->user_key);
    } else {
      if (vect.size() < 45) {
        FCASSERT(false);
        pUnPacker->Next();
        continue;
      }
      // 委托回报
      auto order_id = vect.at(Entrust_reference) + "|" + vect.at(Session_no);
      // 赋值字段
      auto order_key = m_api_adapter->m_login_info->user_key + "|" + order_id;
      auto order_node = m_service->m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<future::Order> o) {
        if (o->order_id.empty()) {
          o->volume_left = atoi(vect.at(Entrust_amount).c_str());
        }
        o->order_ref = vect.at(Entrust_reference);
        o->index = ++m_index;
        o->exchange_id = PullExId(vect.at(Futu_exch_type));
        if (vect.at(Arbit_code).empty())
          o->instrument_id = vect.at(Futu_code);
        else
          o->instrument_id = GetCombId(o->exchange_id, vect.at(Arbit_code));
        o->investor_id = vect.at(Fund_account);
        o->user_id = m_api_adapter->m_client_id;
        o->direction = PullDirection(vect.at(Entrust_bs));
        o->is_quote = vect.at(Entrust_prop) == "FF";
        o->exchange_order_id = vect.at(Entrust_no);
        o->status_msg = GbkToUtf8(vect.at(Error_message));
        o->limit_price = std::stod(vect.at(Futu_entrust_price));
        o->offset = PullOffset(vect.at(Futures_direction));
        o->hedge_flag = PullHedge(vect.at(Hedge_type));
        o->price_type = PullPriceType(vect.at(Entrust_prop));
        if (o->status != OrderStatus::kDead)
          o->status = PullStatus(vect.at(Entrust_status));
        o->time_condition = PullTimeCondition(vect.at(Time_condition));
        o->volume_condition = PullVolumeCondition(vect.at(Volume_condition));
        o->force_close_reason = ForceCloseReason::kNotForceClose;
        o->volume_orign = atoi(vect.at(Entrust_amount).c_str());
        o->session_id = atoi(vect.at(Session_no).c_str());
        o->min_volume = atoi(vect.at(Fex_min_volume).c_str());
        if (vect.at(Entrust_time) != "") {
          o->insert_date_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), vect.at(Entrust_time).c_str());
        }
        o->order_id = order_id;
        o->unit_id = std::atoll(vect.at(Entrust_reference).c_str()) != 0
          ? std::atoll(vect.at(Entrust_reference).c_str()) % 100
          : -1;
        o->user_key = m_api_adapter->m_login_info->user_key;
        if (vect.at(Weave_type) == "6")
          o->is_swap_order = true;
      });
      auto map_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
      m_trade_order_map[map_key] = order_node;
    }
    pUnPacker->Next();
  }
}

