std::shared_ptr<future::TradeNode> UFXOrderTradeView::ProcessTradeQuery(
  IF2UnPacker* pUnPacker, std::shared_ptr<future::OrderNode> order_node, std::string user_key) {
  auto trade_key =
    user_key + "|" + GetPackStr(pUnPacker->GetStr("business_id")) + "|" + GetPackStr(pUnPacker->GetStr("entrust_no"));
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->index = ++m_index;
    auto fund_account = pUnPacker->GetStr("fund_account");
    if (fund_account) {
      trade->investor_id = pUnPacker->GetStr("fund_account");
      trade->user_id = pUnPacker->GetStr("fund_account");
    } else {
      trade->investor_id = m_api_adapter->m_login_info->user_id;
      trade->user_id = m_api_adapter->m_login_info->user_id;
    }
    trade->trade_date_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pUnPacker->GetStr("business_time"));
    trade->direction = PullDirection(GetPackStr(pUnPacker->GetStr("entrust_bs")));
    trade->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
    std::string comb_id = GetPackStr(pUnPacker->GetStr("arbit_code"));
    trade->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
    trade->exchange_trade_id = GetPackStr(pUnPacker->GetStr("business_id"));
    trade->offset = PullOffset(GetPackStr(pUnPacker->GetStr("futures_direction")));
    trade->exchange_order_id = GetPackStr(pUnPacker->GetStr("entrust_no"));
    trade->order_local_id = GetPackStr(pUnPacker->GetStr("entrust_reference"));
    trade->price = pUnPacker->GetDouble("futu_business_price");
    trade->volume = pUnPacker->GetInt("business_amount");
    trade->trader_id = GetPackStr(pUnPacker->GetStr("business_id"));
    trade->user_key = user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_node->Latest()->order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->hedge_flag = PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type")));
    trade->commission = pUnPacker->GetDouble("business_fare");
    if (trade->hedge_flag == OrderHedgeFlag::kSpeculation) {
      trade->_spec_close_profit = pUnPacker->GetDouble("drop_income");
      trade->_spec_close_profit_by_open = pUnPacker->GetDouble("drop_income_float");
    } else {
      trade->_other_close_profit = pUnPacker->GetDouble("drop_income");
      trade->_other_close_profit_by_open = pUnPacker->GetDouble("drop_income_float");
    }
  });
  return trade_node;
}

void UFXOrderTradeView::OnRspQueryTodayTrade338302(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0)
    return;
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto map_key =
      GetPackStr(pUnPacker->GetStr("entrust_no")) + "|" + PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
    auto it = m_trade_order_map.find(map_key);
    if (it == m_trade_order_map.end()) {
      // 只有成交没有委托不处理
      pUnPacker->Next();
      continue;
    } else {
      ProcessTradeQuery(pUnPacker, it->second, m_api_adapter->m_login_info->user_key);
    }
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000)
    return;
  pUnPacker->Last();
  std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
  ReqQueryTodayTrade338302(pos_str);
}

