}

void UFXRate::ReqMarginRate338305(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  auto key = "ReqQryMargin" + qry->instrument_id;
  if (m_query_planner.AlreadyInQueue(key)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同的请求");
    return;
  }
  m_query_planner.AddTask(key, UFXQueryPlanner::Priority::kLow, [=]() {
    return SendMarginRate338305(qry);
