void UFXRate::OnRspMarginRate338305(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  if (RspInfo->ErrorID != 0) {
    return;
  }
  auto req =
    std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(std::to_string(RspInfo->hSend)));
  while (!pUnPacker->IsEOF()) {
    auto futu_exch_type = GetPackStr(pUnPacker->GetStr("futu_exch_type"));
    if (futu_exch_type.empty()) {
      pUnPacker->Next();
      continue;
    }
    std::string ex_id = PullExId(futu_exch_type);
    auto rate_key = m_api_adapter->m_login_info->user_key + "|" + GetPackStr(pUnPacker->GetStr("futu_code"));
    m_service->GetNodeDb()->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_api_adapter->m_login_info->user_key;
      rate_node->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
      rate_node->exchange_id = ex_id;
      if (pUnPacker->GetChar("hedge_type") == '0') {
        // 投机
        if (pUnPacker->GetChar("entrust_bs") == '1') {
          // 买入
          rate_node->margin_rate_long_spec =
            UnitRate(pUnPacker->GetDouble("open_ratio"), pUnPacker->GetDouble("open_margin"));
        } else {
          rate_node->margin_rate_short_spec =
            UnitRate(pUnPacker->GetDouble("open_ratio"), pUnPacker->GetDouble("open_margin"));
        }
      } else {
        // 非投机
        if (pUnPacker->GetChar("entrust_bs") == '1') {
          // 买入
          rate_node->margin_rate_long_other =
            UnitRate(pUnPacker->GetDouble("open_ratio"), pUnPacker->GetDouble("open_margin"));
        } else {
          rate_node->margin_rate_short_other =
            UnitRate(pUnPacker->GetDouble("open_ratio"), pUnPacker->GetDouble("open_margin"));
        }
      }
    });
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
  } else {
    pUnPacker->Last();
    std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
    SendMarginRate338305(req, pos_str);
  }
}

