  while (!pUnPacker->IsEOF()) {
    auto rate_key = m_api_adapter->m_login_info->user_key + "|" + GetPackStr(pUnPacker->GetStr("futu_code"));
    auto hedge_flag_str = GetPackStr(pUnPacker->GetStr("hedge_type"));
    if (hedge_flag_str.empty()) {
      pUnPacker->Next();
      continue;
    }
    auto hedge_flag = PullHedge(hedge_flag_str);
    if (hedge_flag != OrderHedgeFlag::kSpeculation) {
      pUnPacker->Next();
      continue;
    }
    m_service->GetNodeDb()->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_api_adapter->m_login_info->user_key;
      rate_node->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
      rate_node->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
      // 1: 开仓 2: 平仓 3: 交割 4: 行权
      auto type = GetPackStr(pUnPacker->GetStr("futufare_type"));
      if (type == "1") {
        rate_node->commission_rate_open =
          UnitRate(pUnPacker->GetDouble("open_drop_ratio"), pUnPacker->GetDouble("open_drop_fare"));
        rate_node->commission_rate_close_today =
          UnitRate(pUnPacker->GetDouble("drop_today_ratio"), pUnPacker->GetDouble("drop_today_fare"));
      } else if (type == "2") {
        rate_node->commission_rate_close =
          UnitRate(pUnPacker->GetDouble("open_drop_ratio"), pUnPacker->GetDouble("open_drop_fare"));
      } else if (type == "4") {
        rate_node->commission_rate_exec =
          UnitRate(pUnPacker->GetDouble("open_drop_ratio"), pUnPacker->GetDouble("open_drop_fare"));
      }
    });
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
  } else {
    pUnPacker->Last();
    std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
    SendCommissionRate338304(req, pos_str);
  }
}

int UFXRate::RunOnce() {
  return 0;
}

