// 构造函数
CFensServer::CFensServer(char entrust_way) {
  lpFensConnection = NULL;
  lpFensConfig = NULL;
  pBestTradeArStationInfo = NULL;
  pBestMCArStationInfo = NULL;
  m_entrust_way = entrust_way;
}

// 析构函数
CFensServer::~CFensServer() {
  for (std::vector<ArStationInfoFild*>::iterator it1 = m_vFensConfigsTrade.begin(); it1 != m_vFensConfigsTrade.end();
       ++it1) {
    delete *it1;
  }

  for (std::vector<ArStationInfoFild*>::iterator it2 = m_vFensConfigsMC.begin(); it2 != m_vFensConfigsMC.end(); ++it2) {
    delete *it2;
  }
  m_vFensConfigsTrade.clear();
  m_vFensConfigsMC.clear();

  if (lpFensConnection) {
    lpFensConnection->Close();
    lpFensConnection->Release();
  }

  if (lpFensConfig) {
    lpFensConfig->Release();
  }
}

int CFensServer::InitFensConn(
  const char* FundAccount, const char* Password, const char* LicenseFile, const char* FensServerAddr) {
  int iRet = 0;

  if (NULL == lpFensConfig) {
    lpFensConfig = NewConfig();
    if (NULL != lpFensConfig) {
      lpFensConfig->AddRef();
    } else {
      return ERR_FALSE;
    }
    // 配置连接对象
    lpFensConfig->SetString("t2sdk", "servers", FensServerAddr);
    lpFensConfig->SetString("t2sdk", "license_file", LicenseFile);
    lpFensConfig->SetString("safe", "safe_level", "none");
  }

  if (NULL == lpFensConnection) {
    lpFensConnection = NewConnection(lpFensConfig);
    if (NULL == lpFensConnection) {
      lpFensConfig->Release();
      return ERR_FALSE;
    } else {
      lpFensConnection->AddRef();
      lpFensConnection->Create2BizMsg(NULL);
      int count = 0;
      while (ERR_OK != (iRet = lpFensConnection->Connect(FENS_TIMEOUT))) {
        count++;
        if (count > 2)
          return iRet;
      }
    }
  }

  /// 连接成功后保存资金账号和密码
  szFundAccount = FundAccount;
  szPassword = Password;

  return iRet;
}

// 登录Fens服务器获取信息
int CFensServer::SendGetFensSvrReq(char cArType) {
  IBizMessage* lpSendBizMessage = NewBizMessage();
  lpSendBizMessage->AddRef();

  lpSendBizMessage->SetFunction(FENS_GETSTATIONINFO_FUNC);
  lpSendBizMessage->SetPacketType(REQUEST_PACKET);

  IF2Packer* lpF2Packer = NewPacker(2);
  lpF2Packer->AddRef();
  lpF2Packer->BeginPack();
  lpF2Packer->AddField("op_entrust_way", 'C');  // 委托方式
  lpF2Packer->AddField("op_station", 'S');      // 站点
  lpF2Packer->AddField("fund_account", 'S');    // 资金账号
  lpF2Packer->AddField("ar_type", 'C');         // ar类型

  lpF2Packer->AddChar(m_entrust_way);
  lpF2Packer->AddStr("");
  lpF2Packer->AddStr(szFundAccount.c_str());
  lpF2Packer->AddChar(cArType);
  lpF2Packer->EndPack();

  lpSendBizMessage->SetContent(lpF2Packer->GetPackBuf(), lpF2Packer->GetPackLen());
  int iSendId = lpFensConnection->SendBizMsg(lpSendBizMessage, 0);

  lpF2Packer->FreeMem(lpF2Packer->GetPackBuf());
  lpF2Packer->Release();
  lpSendBizMessage->Release();

  return iSendId;
}

// 从fens获取负载最小站点信息，cArType = '0'获取交易站点信息，cArType = '1'获取行情站点信息
int CFensServer::GetFensArConnfig(char cArType) {
  int iSendId = SendGetFensSvrReq(cArType);
  if (0 >= iSendId) {
    return iSendId;
  }

  IBizMessage* lpRecvFensBizMessage;
  int iRet = 0;
  iRet = lpFensConnection->RecvBizMsg(iSendId, &lpRecvFensBizMessage, FENS_TIMEOUT, 0);
  // 同步接收数据
  if (0 != iRet) {
    return iRet;
  } else {
    iRet = DealGetFensOpstationAnsMsg(lpRecvFensBizMessage);
  }

  return iRet;
}

// Fens服务器获取信息
int CFensServer::GetBestConnArInfo() {
  int iErrNo = 0;

  iErrNo = GetFensArConnfig(AR_TYPE_TRADE);
  if (0 == iErrNo) {
    iErrNo = GetFensArConnfig(AR_TYPE_MC);
    if (0 == iErrNo) {
      GetFastArConnfig(AR_TYPE_TRADE);
      GetFastArConnfig(AR_TYPE_MC);
    }
  }
  return iErrNo;
}

// 处理获取负载最小地址应答
int CFensServer::DealGetFensOpstationAnsMsg(IBizMessage* lpFensAnsBizMessage) {
  int iLen = 0;
  int iErrNo = 0;
  const void* lpBuffer = lpFensAnsBizMessage->GetContent(iLen);
  IF2UnPacker* lpUnPacker = NewUnPacker((void*)lpBuffer, iLen);  // NOLINT
  if (NULL != lpUnPacker) {
    lpUnPacker->AddRef();
    iErrNo = lpUnPacker->GetInt("error_no");
    if (0 != iErrNo) {
      const char* ErrorInfo = lpUnPacker->GetStr("error_info");
      std::cout << " error_info:" << ErrorInfo << std::endl;
      return iErrNo;
    } else {
      while (!lpUnPacker->IsEOF()) {
        ArStationInfoFild* pArStationInfoFild = new (std::nothrow) ArStationInfoFild;
        if (NULL != pArStationInfoFild) {
          pArStationInfoFild->cArType = lpUnPacker->GetChar("ar_type");

          const char* pTmpStr = lpUnPacker->GetStr("safe_level");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szSafeLevel, pTmpStr, sizeof(pArStationInfoFild->szSafeLevel));
          }
          pTmpStr = lpUnPacker->GetStr("commpwd");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szCommPwd, pTmpStr, sizeof(pArStationInfoFild->szCommPwd));
          }
          pTmpStr = lpUnPacker->GetStr("cert_pwd");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szCertPwd, pTmpStr, sizeof(pArStationInfoFild->szCertPwd));
          }
          pTmpStr = lpUnPacker->GetStr("cert_file");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szCerFile, pTmpStr, sizeof(pArStationInfoFild->szCerFile));
          }
          pTmpStr = lpUnPacker->GetStr("ar_name");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szArName, pTmpStr, sizeof(pArStationInfoFild->szArName));
          }
          pTmpStr = lpUnPacker->GetStr("ar_server");
          if (NULL != pTmpStr) {
            hs_strncpy(pArStationInfoFild->szArServer, pTmpStr, sizeof(pArStationInfoFild->szArServer));
          }
          if (AR_TYPE_TRADE == pArStationInfoFild->cArType) {
            m_vFensConfigsTrade.push_back(pArStationInfoFild);
          } else {
            m_vFensConfigsMC.push_back(pArStationInfoFild);
          }
        } else {
          iErrNo = ERR_FALSE;
          break;
        }

        lpUnPacker->Next();
      }
    }
    lpUnPacker->Release();
  }

  return iErrNo;
}

// 获取速度最快的站点地址
int CFensServer::GetFastArConnfig(char cArType) {
  IF2Packer* lpF2ReqPacker = NewPacker(2);
  if (NULL != lpF2ReqPacker) {
    lpF2ReqPacker->AddRef();
  } else {
    return ERR_FALSE;
  }

  lpF2ReqPacker->AddRef();
  IF2Packer* lpF2AnsPacker = NewPacker(2);
  if (NULL == lpF2AnsPacker) {
    lpF2ReqPacker->Release();
    return ERR_FALSE;
  } else {
    lpF2AnsPacker->AddRef();
  }

  char szBuf[128] = {0};
  lpF2ReqPacker->BeginPack();
  lpF2ReqPacker->AddField("address");    // 委托方式
  lpF2ReqPacker->AddField("port", 'I');  // 站点

  if (AR_TYPE_TRADE == cArType) {
    for (std::vector<ArStationInfoFild*>::iterator it1 = m_vFensConfigsTrade.begin(); it1 != m_vFensConfigsTrade.end();
         it1++) {
      szBuf[0] = '\0';
      memcpy(szBuf, (*it1)->szArServer, sizeof((*it1)->szArServer));
      char* pos = strchr(szBuf, ':');
      if (NULL != pos) {
        *pos = '\0';
        lpF2ReqPacker->AddStr(szBuf);
        lpF2ReqPacker->AddInt(atoi(pos + 1));
      }
    }
  } else {
    for (std::vector<ArStationInfoFild*>::iterator it1 = m_vFensConfigsMC.begin(); it1 != m_vFensConfigsMC.end();
         it1++) {
      szBuf[0] = '\0';
      memcpy(szBuf, (*it1)->szArServer, sizeof((*it1)->szArServer));
      char* pos = strchr(szBuf, ':');
      if (NULL != pos) {
        *pos = '\0';
        lpF2ReqPacker->AddStr(szBuf);
        lpF2ReqPacker->AddInt(atoi(pos + 1));
      }
    }
  }

  lpF2ReqPacker->EndPack();

  // 开始测速
  lpF2AnsPacker->BeginPack();
  GetMultiNetWorkSpeed(lpF2ReqPacker->UnPack(), lpF2AnsPacker, 3000);
  lpF2AnsPacker->EndPack();

  int iCurPos = 0;
  int iBestArPos = 0;  // 最优AR在std::vector中的位置
  double NetSpeed = 0;
  double NetMaxSpeedTmp = 0;  // 最大测速速度
  IF2UnPacker* lpF2AnsUnPacker = lpF2AnsPacker->UnPack();
  while (!lpF2AnsUnPacker->IsEOF()) {
    // 结果集字段：
    ////net_delay表示从发送测试包到接收到测试包的应答的时间差
    /// net_speed是包长度除以时间差   转换成的速度
    /// conn_count服务端的链接个

    NetSpeed = lpF2AnsUnPacker->GetDouble("net_speed");

    if (NetSpeed > NetMaxSpeedTmp) {
      iBestArPos = iCurPos;
      NetMaxSpeedTmp = NetSpeed;
    }

    iCurPos++;

    lpF2AnsUnPacker->Next();
  }

  if (AR_TYPE_TRADE == cArType) {
    if (m_vFensConfigsTrade.size() > 0) {
      pBestTradeArStationInfo = m_vFensConfigsTrade[iBestArPos];
    } else {
      // LOG_ERROR("没有从Fens服务器取得交易前置机地址");
    }
  } else {
    if (m_vFensConfigsMC.size() > 0) {
      pBestMCArStationInfo = m_vFensConfigsMC[iBestArPos];
    } else {
      // LOG_ERROR("没有从Fens服务器取得行情前置机地址");
    }
  }

  lpF2ReqPacker->Release();
  lpF2AnsPacker->Release();

  return 0;
}

// 获取负载最小，速度最快地址交易站点信息
ArStationInfoFild* CFensServer::GetBestTradeConnfig() {
  return pBestTradeArStationInfo;
}

// 获取负载最小，速度最快地址行情站点信息
ArStationInfoFild* CFensServer::GetBestMCConfig() {
  return pBestMCArStationInfo;
}
