void UFXRiskPosition::OnRspLogIn331100(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0 || m_api_adapter->m_change_password_before_login)
    return;
  m_risk_position = false;
  QryRiskPosition338427();
}

void UFXRiskPosition::QryRiskPosition338427(const std::string& pos_str) {
  auto key = "QryRiskPosition";
  if (m_query_planner.AlreadyInQueue(key)) {
    return;
  }
  m_query_planner.AddTask(
    key, UFXQueryPlanner::Priority::kHigh,
    [=]() {
      // 创建业务包体
      IF2Packer* pPacker = NewPacker(2);
      pPacker->AddRef();
      pPacker->BeginPack();

      /// 加入字段名
      pPacker->AddField("op_branch_no", 'I', 5);
      pPacker->AddField("op_entrust_way", 'C', 1);
      pPacker->AddField("op_station", 'S', 255);
      pPacker->AddField("branch_no", 'I', 5);
      pPacker->AddField("client_id", 'S', 18);
      pPacker->AddField("fund_account", 'S', 18);
      pPacker->AddField("password", 'S', 13);
      pPacker->AddField("password_type", 'C');
      pPacker->AddField("user_token", 'S', 512);
      pPacker->AddField("request_num", 'I', 10);
      pPacker->AddField("position_str", 'S', 100);
      // 加入对应的字段值
      pPacker->AddInt(m_api_adapter->m_op_branch_no);
      pPacker->AddChar(m_api_adapter->m_entrust_way);
      pPacker->AddStr(m_api_adapter->m_op_station.c_str());
      pPacker->AddInt(m_api_adapter->m_branch_no);
      pPacker->AddStr(m_api_adapter->m_client_id.c_str());
      pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
      pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
      pPacker->AddChar('2');
      pPacker->AddStr(m_api_adapter->m_user_token.c_str());
      pPacker->AddInt(1000);
      pPacker->AddStr(pos_str.c_str());

      /// 结束打包
      pPacker->EndPack();

      IBizMessage* pBizMessage = NewBizMessage();
      pBizMessage->AddRef();
      // 设置包头
      pBizMessage->SetFunction(338427);
      pBizMessage->SetPacketType(REQUEST_PACKET);
      // 设置包的内容
      pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
      // 异步发送
      int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);
      // 释放资源
      pPacker->FreeMem(pPacker->GetPackBuf());
      pPacker->Release();
