      return nRet;
    },
    0, false);
}

void UFXRiskPosition::OnRspRiskPosition338427(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID != 0)
    return;
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    std::string position_symbol =
      PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type"))) + "." + GetPackStr(pUnPacker->GetStr("futu_code"));
    m_risk_position = true;
    auto position_key = m_api_adapter->m_login_info->user_key + "|0|" + position_symbol;
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_api_adapter->m_login_info->user_key;
      target_position->investor_id = m_api_adapter->m_fund_account;
      target_position->risk_position = true;
      target_position->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
      target_position->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
      target_position->last_price = pUnPacker->GetDouble("futu_last_price");
      future::SubPosition* subpos =
        GetSubPosition(target_position, PullDirection(GetPackStr(pUnPacker->GetStr("entrust_bs"))),
          PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type"))));
      if (GetPackStr(pUnPacker->GetStr("hedge_type")) == "2") {
        subpos->hedge_type = PositionHedgeType::kArbitrage;
      }
      if (pUnPacker->GetDouble("hold_margin") != 0) {
        subpos->margin = pUnPacker->GetDouble("hold_margin");
      }
      subpos->volume_today = pUnPacker->GetInt("real_current_amount");
      subpos->volume_today_frozen = subpos->volume_today - pUnPacker->GetInt("real_enable_amount");
      subpos->volume_his = pUnPacker->GetInt("begin_amount");
      subpos->volume_his_frozen =
        subpos->volume_his - pUnPacker->GetInt("enable_amount") + pUnPacker->GetInt("real_enable_amount");
      subpos->volume_yesterday = pUnPacker->GetInt("begin_amount");
      subpos->float_profit = pUnPacker->GetDouble("hold_income_float");
      subpos->open_price = pUnPacker->GetDouble("average_price");
      subpos->position_price = pUnPacker->GetDouble("average_hold_price");
      subpos->position_profit = pUnPacker->GetDouble("hold_income");
    });
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() >= 1000) {
    pUnPacker->Last();
    std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
    QryRiskPosition338427(pos_str);
  }
}

