UFXLogIn::UFXLogIn(UFXServiceImpl *service, UFXApiAdapter *api_adapter, structlog::Logger &parent_logger)
  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterCommandProcessor(SubmitUserSystemInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    SubmitSystemInfo(command);
  });
  m_service->RegisterCommandProcessor(ConfirmSettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqSettleConfirm331851(command);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePassword331101(command);
  });
  m_service->RegisterCommandProcessor(ChangePasswordBeforeLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    ChangePasswordBeforeLogin(command);
  });
  m_service->RegisterCommandProcessor(QueryCFMMCToken::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQueryCFMMCToken(command);
  });
  m_service->RegisterCommandProcessor(QuerySettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    auto qry = std::static_pointer_cast<QuerySettlementInfo>(m_service->m_command_manager->Update(command));
    int ret = ReqQuerySettleInfo339851(qry->trading_day);
    m_service->m_command_manager->SetCommandId(qry, "QuerySettlementInfo");
    if (ret < 0)
      SetCommandFinished(qry, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
  });
  m_service->RegisterMsgProcessor(331480, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspSessionId331480(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(331481, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspAuth331481(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(331100, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspLogIn_331100(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(339851, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspQuerySettleInfo339851(pUnPacker, RspInfo);
