  m_service->RegisterMsgProcessor(331851, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspSettleConfirm331851(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(338332, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspOrderParams338332(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(331101, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspChangePassword331101(pUnPacker, RspInfo);
  });
  m_service->RegisterMsgProcessor(330855, [this](IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
    OnRspQueryCFMMCToken(pUnPacker, RspInfo);
  });
  m_kill_thread.store(false);
}

UFXLogIn::~UFXLogIn() {
  m_kill_thread.store(true);
  if (m_reconnect_thread.joinable())
    m_reconnect_thread.join();
}

int UFXLogIn::ConnectFens(char entrust_way) {
  CFensServer *lp_FensServer = new (std::nothrow) CFensServer(entrust_way);
  if (NULL == lp_FensServer) {
    return -1;
  }
  std::string tradeserver, mdserver;
  /// 和Fens建立连接
  std::string licansefilepath = m_api_adapter->m_login_info->license_file_addr;
  int iRet = lp_FensServer->InitFensConn(m_api_adapter->m_login_info->user_id.c_str(),
    m_api_adapter->m_login_info->password.c_str(), licansefilepath.c_str(), (*m_fens_addr.begin()).c_str());
  if (ERR_OK == iRet) {
    /// 获取最优地址
    iRet = lp_FensServer->GetBestConnArInfo();
    if (ERR_OK == iRet && lp_FensServer->GetBestTradeConnfig()) {
      tradeserver = lp_FensServer->GetBestTradeConnfig()->szArServer;
      mdserver = lp_FensServer->GetBestMCConfig()->szArServer;
    } else {
      // 获取失败柜台地址失败
      delete lp_FensServer;
      return iRet;
    }
  } else {
    delete lp_FensServer;
    return iRet;
  }
  delete lp_FensServer;
  m_api_adapter->m_login_info->broker.trading_fronts.clear();
  m_api_adapter->m_login_info->broker.trading_fronts.push_back(tradeserver);
  return 0;
}

void UFXLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  if (command) {
    m_api_adapter->m_login_info = std::static_pointer_cast<ReqLogin>(m_service->m_command_manager->Update(command));
  } else {
    m_api_adapter->m_login_info = m_api_adapter->m_change_password_before_login->req_login;
    command = m_api_adapter->m_change_password_before_login;
  }
  int ret = 0;
  if (m_api_adapter->m_login_info->broker.is_fens) {
    m_fens_addr = m_api_adapter->m_login_info->broker.trading_fronts;
    ret = ConnectFens(m_api_adapter->m_login_info->entrust_way);
  }
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"连接失败,请检查交易前置或证书");
    return;
  }
  ret = m_api_adapter->InitConnect();
  if (ret != 0) {
    SetCommandFinished(
      command, ret, ret == -1 ? u8"连接失败" : GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
    return;
  }
  m_service->m_command_manager->SetCommandId(command, "login");
}

int UFXLogIn::ReqSessionId331480(const char *pszFundAccount, const char *pszPassword) {
  // 创建业务包体
  IF2Packer *pPacker = NewPacker(2);
