  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();
  return nRet;
}

void UFXLogIn::OnRspSessionId331480(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  auto req = m_service->m_command_manager->Update("login");
  if (RspInfo->ErrorID != 0) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  // 储存session_id
  m_app_session_id = GetPackStr(pUnPacker->GetStr("session_id"));
  // 请求客户端认证
  if (m_api_adapter->m_login_info->broker.auth_code.empty()) {
    int ret = ReqLogIn331100(m_api_adapter->m_login_info->entrust_way);
    if (ret <= 0) {
      SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
    }
  } else {
    int ret = ReqAuth331481(m_api_adapter->m_login_info->user_id.c_str(),
      m_api_adapter->m_login_info->broker.app_id.c_str(), m_api_adapter->m_login_info->broker.auth_code.c_str());
    if (ret <= 0) {
      SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
    }
  }
}

int UFXLogIn::ReqAuth331481(const char *pszFundAccount, const char *pszAppId, const char *pszAuthCode) {
  int iOutLen = 0;
  char szAuthCode[64];
  char encrypted_session_id[256] = {0};
  hs_strncpy(szAuthCode, pszAuthCode, sizeof(szAuthCode));
  int inLen = static_cast<int>(strlen(m_app_session_id.c_str()));
  int nRet =
    hundsun_encrypt(const_cast<char *>(m_app_session_id.c_str()), inLen, encrypted_session_id, &iOutLen, szAuthCode);
  if (nRet != 0) {
    auto req = m_service->m_command_manager->Update("login");
    SetCommandFinished(req, nRet, "Session Encrypt Failed");
    return nRet;
  }
  // 创建业务包体
  IF2Packer *pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  // 加入字段名
  pPacker->AddField("fund_account", 'S', 18);          // 资产账户
  pPacker->AddField("app_id", 'S', 255);               // 客户端id名称
  pPacker->AddField("session_id", 'S', 64);            // 会话号
  pPacker->AddField("encrypted_session_id", 'S', 64);  // 加密后的会话id
  // 加入对应的字段值
  pPacker->AddStr(pszFundAccount);
  pPacker->AddStr(pszAppId);
  pPacker->AddStr(m_app_session_id.c_str());
  pPacker->AddStr(encrypted_session_id);
  // 结束打包
  pPacker->EndPack();
  // 构建消息
  IBizMessage *pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(331481);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  // 设置包内容
  pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  nRet = m_api_adapter->SendMsg(pBizMessage);
  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();

  return nRet;
}

void UFXLogIn::OnRspAuth331481(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  auto req = m_service->m_command_manager->Update("login");
  if (RspInfo->ErrorID != 0) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  // 请求信息上报
  int ret =
    ReqSysInfo(m_api_adapter->m_login_info->user_id.c_str(), m_api_adapter->m_login_info->broker.app_id.c_str());
  if (ret <= 0) {
    m_logger.With("upload system info", "failed").Info("systeminfo_upload");
  }
  // 请求登录
  ret = ReqLogIn331100(m_api_adapter->m_login_info->entrust_way);
  if (ret <= 0) {
    SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
  }
}

int UFXLogIn::ReqSysInfo(const char *pszFundAccount, const char *pszAppId) {
  /*采集系统信息
   *@param pszSysInfo:  加密后的采集信息, 缓冲区长度至少492字节
   *@param iSysInfoLen:  加密后的采集信息的长度
   *@param pszSysInfoIntegrity:   采集信息完整度，缓冲区长度至少300字节
   *@param iSysInfoIntegrityLen:   采集信息完整度的长度
   *@return 0：正常1：终端信息采集为空2：终端采集数据加密密钥版本异常3：终端信息数据异常
   */
  int nSysInfoLen = 0;
  int nSysInfoIntegrityLen = 0;
  char szszSysInfo[512] = {0};
  char szSysInfoIntegrity[512] = {0};

  int nRet = 0;
  if (!m_api_adapter->m_test_mode) {
    nRet = hundsun_getsysteminfo(szszSysInfo, &nSysInfoLen, szSysInfoIntegrity, &nSysInfoIntegrityLen);
  } else {
    nRet = 1;
  }
  if (nRet != 0) {
    char pszDetailInfo[512] = {0};
    int iDetailInfoLen = 0;
    hundsun_getdetailerror(szSysInfoIntegrity, pszDetailInfo, &iDetailInfoLen);
    m_logger.With("pszDetailInfo", std::string(pszDetailInfo)).Info("systeminfo_upload");
    return nRet;
  }
  return ReqSysInfo331482(pszFundAccount, pszAppId, szszSysInfo, szSysInfoIntegrity, nRet, "", "");
}

void UFXLogIn::SubmitSystemInfo(std::shared_ptr<UserCommand> command) {
  auto cmd = std::static_pointer_cast<SubmitUserSystemInfo>(m_service->m_command_manager->Update(command));
  std::string app_public_addr = cmd->client_ip + ":" + std::to_string(cmd->client_port);
  int ret = ReqSysInfo331482(m_api_adapter->m_login_info->user_id.c_str(), cmd->client_app_id.c_str(),
    cmd->client_system_info.c_str(), cmd->ufx_info.app_sys_info_integrity.c_str(), cmd->ufx_info.app_abnormal_type,
    cmd->ufx_info.app_login_time.c_str(), app_public_addr.c_str());
  m_logger.With("client_app_id", cmd->client_app_id)
    .With("client_ip", cmd->client_ip)
    .With("client_port", cmd->client_port)
    .With("client_system_info", cmd->client_system_info)
    .With("app_abnormal_type", cmd->ufx_info.app_abnormal_type)
    .With("app_login_time", cmd->ufx_info.app_login_time)
    .With("app_sys_info_integrity", cmd->ufx_info.app_sys_info_integrity)
    .With("ret", ret)
    .Info("SubmitSystemInfo");
  if (ret <= 0) {
    SetCommandFinished(cmd, -1, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
  } else {
    SetCommandFinished(cmd);
  }
