void UFXLogIn::OnRspLogIn_331100(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  if (RspInfo->ErrorID == 0) {
    if (pUnPacker->GetStr("client_id") != NULL)
      m_api_adapter->m_client_id = pUnPacker->GetStr("client_id");
    if (pUnPacker->GetStr("user_token") != NULL)
      m_api_adapter->m_user_token = pUnPacker->GetStr("user_token");
    if (pUnPacker->GetStr("fund_account") != NULL)
      m_api_adapter->m_fund_account = pUnPacker->GetStr("fund_account");
    m_api_adapter->m_session_no = pUnPacker->GetInt("session_no");
    m_api_adapter->m_branch_no = pUnPacker->GetInt("branch_no");
    m_api_adapter->m_op_branch_no = pUnPacker->GetInt("op_branch_no");
    m_api_adapter->m_last_date = pUnPacker->GetInt("last_date");
    m_api_adapter->m_trading_day = std::to_string(pUnPacker->GetInt("init_date"));
  }
  if (m_api_adapter->m_change_password_before_login) {
    if (RspInfo->ErrorID == 0) {
      int ret = ReqChangePassword331101(nullptr);
      if (ret <= 0) {
        SetCommandFinished(m_api_adapter->m_change_password_before_login, ret,
          GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
      }
    } else {
      SetCommandFinished(m_api_adapter->m_change_password_before_login, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    }
    return;
  }
  auto req = m_service->m_command_manager->Update("login");
  auto req_login = std::static_pointer_cast<future::ReqLogin>(req);
  if (RspInfo->ErrorID != 0) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_api_adapter->m_login_info->user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_api_adapter->m_login_info->user_key;
      target_login->user_id = GetPackStr(pUnPacker->GetStr("client_id"));
      target_login->investor_id = GetPackStr(pUnPacker->GetStr("fund_account"));
      auto trading_day = std::to_string(pUnPacker->GetInt("init_date"));
      if (!target_login->trading_day.empty() && target_login->trading_day != trading_day) {
        m_service->m_new_day = true;
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = trading_day;
      target_login->broker_id = std::to_string(pUnPacker->GetInt("company_no"));
      target_login->session_id = pUnPacker->GetInt("session_no");
      target_login->system_name = "ufx";
      target_login->investor_name = GbkToUtf8(GetPackStr(pUnPacker->GetStr("client_name")));
      target_login->backend = BackEnd::kUFX;
      target_login->confirm_status =
        pUnPacker->GetChar("tabconfirm_flag") == '1' ? ConfirmStatus::kUnconfirm : ConfirmStatus::kConfirmed;
      if (target_login->user_desc == "") {
        target_login->user_desc = req_login->user_desc;
      }
    });
  SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));

  if (pUnPacker->GetChar("tabconfirm_flag") == '1') {
    if (m_service->m_options.auto_settlement_confirm) {
      auto comfirm_req = std::make_shared<ConfirmSettlementInfo>(m_api_adapter->m_login_info->user_key);
      ReqSettleConfirm331851(comfirm_req);
    } else {
      // 如果未确认结算单,则查询结算单
      ReqQuerySettleInfo339851();
    }
  }

  // 订阅主推接口
  SubOrderTrade33101();
  SubInsStatus33118();
  // 查询参数
  ReqOrderParams338332();
  Log338401();
}

