  pPacker->AddField("client_id", 'S', 18);
  pPacker->AddField("fund_account", 'S', 18);
  pPacker->AddField("password", 'S', 13);
  pPacker->AddField("begin_date", 'I', 8);
  pPacker->AddField("end_date", 'I', 8);
  pPacker->AddField("money_type", 'S', 3);
  pPacker->AddField("total_type", 'C', 1);

  // 加入对应的字段值
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddInt(m_api_adapter->m_op_branch_no);
  pPacker->AddChar(m_api_adapter->m_entrust_way);
