  pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  if (day.empty()) {
    pPacker->AddInt(m_api_adapter->m_last_date);
    pPacker->AddInt(m_api_adapter->m_last_date);
