  // 异步发送
  int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();

  return nRet;
}

void UFXLogIn::OnRspQuerySettleInfo339851(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  auto req = m_service->m_command_manager->Update("QuerySettlementInfo");
  if (RspInfo->ErrorID != 0) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  pUnPacker->First();
  std::string settle_data;
  while (!pUnPacker->IsEOF()) {
    auto data = pUnPacker->GetStr("check_tab_data");
    if (data)
      settle_data.append(data);
    pUnPacker->Next();
    settle_data.append("\r\n");
  }
  if (!req) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_api_adapter->m_login_info->user_key, [&](std::shared_ptr<future::LoginContent> target_info) {
        target_info->content.append(GbkToUtf8(settle_data));
        target_info->user_key = m_api_adapter->m_login_info->user_key;
        target_info->backend = BackEnd::kUFX;
        target_info->confirm_status = ConfirmStatus::kWaitingConfirm;
      });
  }
  SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(settle_data));
}

