void UFXLogIn::OnRspChangePassword331101(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    if (m_api_adapter->m_change_password_before_login) {
      if (pUnPacker->GetInt("error_no") != 0) {
        SetCommandFinished(m_api_adapter->m_change_password_before_login, pUnPacker->GetInt("error_no"),
          GbkToUtf8(GetPackStr(pUnPacker->GetStr("error_info"))));
      } else {
        m_api_adapter->m_login_info->password = m_api_adapter->m_change_password_before_login->new_password;
        SetCommandFinished(
          m_api_adapter->m_change_password_before_login, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
      }
      m_api_adapter->m_change_password_before_login = nullptr;
    } else {
      auto req = std::static_pointer_cast<ChangePassword>(m_service->m_command_manager->Update("ChangePassword"));
      if (pUnPacker->GetInt("error_no") != 0) {
        SetCommandFinished(req, pUnPacker->GetInt("error_no"), GbkToUtf8(GetPackStr(pUnPacker->GetStr("error_info"))));
      } else {
        if (req && req->password_type == PasswordType::kTrade)
          m_api_adapter->m_login_info->password = req->new_password;
        SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
      }
    }
    pUnPacker->Next();
  }
}

