void UFXLogIn::OnRspQueryCFMMCToken(IF2UnPacker *pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  auto req = std::static_pointer_cast<QueryCFMMCToken>(m_service->m_command_manager->Update("QueryCFMMCToken"));
  if (RspInfo->ErrorID != 0) {
    SetCommandFinished(req, RspInfo->ErrorID, GbkToUtf8(RspInfo->ErrorMsg));
    return;
  }
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto cfmmc_key = pUnPacker->GetStr("cfmmc_key");
    auto cfmmc_key_no = pUnPacker->GetInt("cfmmc_key_no");
    auto company_id = pUnPacker->GetStr("company_id");
    if (cfmmc_key && company_id) {
      SetCommandFinished(
        req, 0, std::string(company_id) + ";" + std::to_string(cfmmc_key_no) + ";" + std::string(cfmmc_key));
    }
    pUnPacker->Next();
  }
}

int UFXLogIn::RunOnce() {
  if (m_api_adapter->m_OnRegister) {
    m_logger.Info("m_OnRegister");
    int ret =
      ReqSessionId331480(m_api_adapter->m_login_info->user_id.c_str(), m_api_adapter->m_login_info->password.c_str());
    if (ret <= 0) {
      auto req = m_service->m_command_manager->Update("login");
      SetCommandFinished(req, ret, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(ret)));
    }
    m_api_adapter->m_OnRegister = false;
  }
  if (m_api_adapter->m_OnClose) {
    m_logger.Warning("m_OnClose");
    m_app_session_id = "";
    m_api_adapter->m_OnClose = false;
    auto node = m_service->GetNodeDb()->GetNode<LoginContent>(m_api_adapter->m_login_info->user_key);
    if (!node)
      return 0;
    m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
      m_api_adapter->m_login_info->user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
        target_login->status_msg = u8"前置机断连";
        target_login->user_key = m_api_adapter->m_login_info->user_key;
        target_login->backend = BackEnd::kUFX;
        target_login->session_status = SessionStatus::kDisconnected;
      });
    if (m_reconnect_thread.joinable())
      m_reconnect_thread.join();
    m_reconnect_thread = std::thread([&]() {
      auto logger = m_logger.Clone();
      while (!m_kill_thread.load()) {
        logger.Warning("Reconnecting");
        if (m_api_adapter->m_login_info->broker.is_fens) {
          if (ConnectFens(m_api_adapter->m_login_info->entrust_way) != 0)
            continue;
        }
        if (0 == m_api_adapter->InitConnect()) {
          logger.Info("Reconnect Success");
          break;
        }
      }
    });
  }
  return 0;
}

