void UFXExecOrder::OnQryExecOrder338328(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    auto ref = pUnPacker->GetStr("exercise_reference");
    std::string order_ref;
    if (ref)
      order_ref = ref;
    else
      order_ref = std::to_string(pUnPacker->GetInt("exercise_no"));
    int session_no = pUnPacker->GetInt("session_no");
    auto exec_order_id = ToFclibOrderId(stoi(order_ref), session_no);
    auto node = m_service->GetNodeDb()->ReplaceRecord<ExecOrder>(
      m_service->m_user_key + "|" + exec_order_id, [=](std::shared_ptr<ExecOrder> o) {
        o->exec_order_id = exec_order_id;
        o->user_key = m_service->m_user_key;
        o->investor_id = GetPackStr(pUnPacker->GetStr("fund_account"));
        o->instrument_id = GetPackStr(pUnPacker->GetStr("futu_code"));
        o->hedge_flag = PullHedge(GetPackStr(pUnPacker->GetStr("hedge_type")));
        o->direction = PosiDirection::kLong;
        o->exec_action_type =
          GetPackStr(pUnPacker->GetStr("auto_drop_flag")) == "1" ? ExecActionType::kClose : ExecActionType::kExec;
        o->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
        o->exchange_exec_order_sysid = std::to_string(pUnPacker->GetInt("exercise_no"));
        o->offsetflag = PullOffset(GetPackStr(pUnPacker->GetStr("futures_direction")));
        o->exec_result = PullStatus(GetPackStr(pUnPacker->GetStr("entrust_status"))) == OrderStatus::kAlive
          ? ExecOrderResultType::kNoExec
          : ExecOrderResultType::kCanceled;
        o->volume = pUnPacker->GetInt("apply_amount");
        o->session_id = pUnPacker->GetInt("session_no");
        o->exec_order_ref = order_ref;
        o->exec_close_flag = GetPackStr(pUnPacker->GetStr("auto_drop_flag")) == "1" ? ExecOrderCloseFlag::kAutoClose
                                                                                    : ExecOrderCloseFlag::kNotToClose;
        o->insert_date_time =
          GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pUnPacker->GetStr("exercise_time"));
        if (o->exec_result == ExecOrderResultType::kCanceled) {
          o->cancel_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pUnPacker->GetStr("exercise_time"));
        }
      });
    if (node->Latest()->exec_result == ExecOrderResultType::kNoExec) {
      m_alive_order[exec_order_id] = pUnPacker->GetInt("exercise_no");
    } else {
      m_alive_order.erase(exec_order_id);
    }
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000)
    return;
  pUnPacker->Last();
  std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
  QryExecOrder338328(pos_str);
}

