void UFXExecOrder::OnRtnExecOrder33110(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    // 解包到vector中
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (vect.size() < 35) {
      FCASSERT(false);
      pUnPacker->Next();
      continue;
    }
    std::string ref = vect.at(Exec_exercise_reference);
    std::string order_ref;
    if (!ref.empty())
      order_ref = ref;
    else
      order_ref = vect.at(Exec_exercise_no);
    std::string session_no = vect.at(Exec_session_no);
    auto exec_order_id = ToFclibOrderId(stoi(order_ref), stoi(session_no));
    auto node = m_service->GetNodeDb()->ReplaceRecord<ExecOrder>(
      m_service->m_user_key + "|" + exec_order_id, [=](std::shared_ptr<ExecOrder> o) {
        o->session_id = stoi(vect.at(Exec_session_no));
        o->exec_order_ref = ref;
        o->exec_order_id = exec_order_id;
        o->user_key = m_service->m_user_key;
        o->investor_id = vect.at(Exec_fund_account);
        o->instrument_id = vect.at(Exec_futu_code);
        o->exchange_id = PullExId(vect.at(Exec_futu_exch_type));
        o->exchange_exec_order_sysid = vect.at(Exec_exercise_no);
        o->direction = PosiDirection::kLong;
        o->exec_action_type = vect.at(Exec_apply_flag) == "1" ? ExecActionType::kExec : ExecActionType::kAbandon;
        o->offsetflag = PullOffset(vect.at(Exec_futures_direction));
        o->hedge_flag = PullHedge(vect.at(Exec_hedge_type));
        o->status_msg = GbkToUtf8(vect.at(Exec_error_message));
        o->exec_result = PullStatus(vect.at(Exec_entrust_status)) == OrderStatus::kAlive
          ? ExecOrderResultType::kNoExec
          : ExecOrderResultType::kCanceled;
        o->volume = stoi(vect.at(Exec_apply_amount));
        o->exec_close_flag =
          (vect.at(Exec_auto_drop_flag) == "1") ? ExecOrderCloseFlag::kAutoClose : ExecOrderCloseFlag::kNotToClose;
        o->insert_date_time =
          GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), vect.at(Exec_exercise_time).c_str());
        if (o->exec_result == ExecOrderResultType::kCanceled) {
          o->cancel_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), vect.at(Exec_exercise_time).c_str());
        }
      });
    if (node->Latest()->exec_result == ExecOrderResultType::kNoExec) {
      m_alive_order[exec_order_id] = stoi(vect.at(Exec_exercise_no));
    } else {
      m_alive_order.erase(exec_order_id);
    }
    pUnPacker->Next();
  }
  auto req = std::make_shared<QueryInvestorPosition>(m_api_adapter->m_login_info->user_key);
  m_service->ExecuteCommand(req);
}

std::string CovertProductID(const std::string& id) {
  std::string base = id;
  bool is_option = false;
  // Step 1: 检查是否是期权（结尾为 "_O"）
  if (id.size() >= 2 && (id.substr(id.size() - 2) == "_o" || id.substr(id.size() - 2) == "_O")) {
    is_option = true;
    base = id.substr(0, id.size() - 2);
  }
  // Step 2: 如果长度为 1，补 '0'
  if (base.size() == 1) {
    base = '0' + base;
  }
  // Step 3: 如果是期权，加 'O' 结尾
  if (is_option) {
    base += 'O';
  }
  return base;
}

// 自对冲
void UFXExecOrder::ReqInsertOptionSelfClose338225(const std::shared_ptr<UserCommand>& command) {
  auto req = std::static_pointer_cast<InsertOptionSelfClose>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (m_api_adapter->m_session_no == 0) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  char close_flag = '0';
  std::string futu_code, futucode_type, fopt_expiry;
  std::string err_msg;
  if (req->close_flag == SelfCloseType::kOptionPosition) {
    close_flag = '0';
    if (!req->instrument_id.empty()) {
      futu_code = req->instrument_id;
    } else if (!req->underlying_instrument_id.empty()) {
      futu_code = "!";
      fopt_expiry = req->underlying_instrument_id;
    } else if (!req->product_id.empty()) {
      futu_code = "!";
      fopt_expiry = "!";
      futucode_type = CovertProductID(req->product_id);
    } else {
      err_msg = u8"fclib: 期权自对冲需要指定合约代码或标的代码或品种代码";
    }
  } else if (req->close_flag == SelfCloseType::kReserveOptionPosition) {
    close_flag = '2';
    futu_code = req->instrument_id;
  } else {
    if (!req->instrument_id.empty()) {
      futu_code = req->instrument_id;  // 非大商所
    } else if (!req->underlying_instrument_id.empty()) {
      futu_code = req->underlying_instrument_id;  // 大商所针对标的合约自对冲填写在 futu_code
    } else if (!req->product_id.empty()) {
      futu_code = "!";
      futucode_type = CovertProductID(req->product_id);
    } else {
      futu_code = "!";
      futucode_type = "!";
    }
    if (req->close_flag == SelfCloseType::kSelfFuturePosition) {
      close_flag = '1';
    } else if (req->close_flag == SelfCloseType::kSelfFuturePositionBuy) {
      close_flag = '6';
    } else if (req->close_flag == SelfCloseType::kFuturePosition) {
      close_flag = '7';
    } else {
      err_msg = u8"fclib: 不支持此类型自对冲";
    }
  }
  if (!err_msg.empty()) {
    SetCommandFinished(req, -1, err_msg);
    return;
  }
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  /// 加入字段名
  pPacker->AddField("op_entrust_way", 'C', 1);  // 委托方式
  pPacker->AddField("op_station", 'S', 255);    // 站点地址
  pPacker->AddField("branch_no", 'I', 5);       // 分支机构
