  pPacker->AddField("fund_account", 'S', 18);   // 资产账户
  pPacker->AddField("password", 'S', 13);       // 密码
  pPacker->AddField("user_token", 'S', 512);    // user_token
  // pPacker->AddField("futures_account", 'S', 12);        // 交易编码
  pPacker->AddField("futu_exch_type", 'S', 4);  // 交易类别
  pPacker->AddField("futu_code", 'S', 30);      // 合约代码
  pPacker->AddField("futucode_type", 'S', 30);  // 品种
  pPacker->AddField("fopt_expiry", 'S', 30);    // 标的
  pPacker->AddField("entrust_amount", 'I');     // 委托数量
  pPacker->AddField("offset_type", 'C', 1);     // 申请标志
  pPacker->AddField("if_offset", 'C', 1);       // 是否执行
  // 加入对应的字段值
  pPacker->AddChar(m_api_adapter->m_entrust_way);
  pPacker->AddStr(m_api_adapter->m_op_station.c_str());
  pPacker->AddInt(m_api_adapter->m_branch_no);
  pPacker->AddStr(m_api_adapter->m_client_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddStr(PushExType(req->exchange_id));
  pPacker->AddStr(futu_code.c_str());
  pPacker->AddStr(futucode_type.c_str());
  pPacker->AddStr(fopt_expiry.c_str());
  pPacker->AddInt(req->volume);
  pPacker->AddChar(close_flag);
  pPacker->AddChar(req->is_offset ? '1' : '0');
  /// 结束打包
  pPacker->EndPack();

  IBizMessage* pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(338225);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  // 设置包内容
  pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();
  m_service->m_command_manager->SetCommandId(req, "InsertOptionSelfClose" + std::to_string(nRet));
  if (nRet <= 0) {
