void UFXExecOrder::OnRtnOptionSelfClose33117(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    // 解包到vector中
    auto vect = split_string(GetPackStr(pUnPacker->GetStr("QH")), '\001');
    if (vect.size() < 11) {
      FCASSERT(false);
      pUnPacker->Next();
      continue;
    }
    bool support_dce = true;
    if (vect.size() < 14) {
      support_dce = false;
    }
    std::string exec_order_id = vect.at(Self_entrust_no);
    std::string instrument_id = vect.at(Self_futu_code);
    bool is_offset = true;
    std::string futucode_type, fopt_expiry;
    std::string offset_type = vect.at(Self_offset_type);
    std::string futu_code = vect.at(Self_futu_code);
    if (support_dce) {
      futucode_type = vect.at(Self_futucode_type);
      fopt_expiry = vect.at(Self_fopt_expiry);
      futu_code = vect.at(Self_futu_code);
      if (!futu_code.empty() && futu_code != "!") {
        instrument_id = futu_code;
      } else if (!fopt_expiry.empty() && fopt_expiry != " " && fopt_expiry != "!") {
        instrument_id = fopt_expiry;
      } else if (!futucode_type.empty() && futucode_type != "!") {
        instrument_id = futucode_type;
      } else {
        instrument_id = PullExId(vect.at(Self_futu_exch_type));
      }
      is_offset = vect.at(Self_if_offset) == "1";
    }

    for (const auto& [id, o] : m_alive_option_self_close) {
      if (o.futu_code == futu_code && o.futucode_type == futucode_type && o.fopt_expiry == fopt_expiry
        && o.offset_type == offset_type) {
        exec_order_id = id;
        break;
      }
    }
    auto node = m_service->GetNodeDb()->ReplaceRecord<OptionSelfClose>(
      m_service->m_user_key + "|" + exec_order_id, [=](std::shared_ptr<OptionSelfClose> o) {
        o->user_key = m_service->m_user_key;
        o->investor_id = vect.at(Self_fund_account);
        o->instrument_id = instrument_id;
        o->exchange_id = PullExId(vect.at(Self_futu_exch_type));
        o->exchange_self_close_sysid = exec_order_id;
        o->self_close_id = exec_order_id;
        o->hedge_flag = future::OrderHedgeFlag::kSpeculation;
        if (offset_type == "0") {
          o->close_type_flag = is_offset ? SelfCloseType::kOptionPosition : SelfCloseType::kNotOptionPosition;
        } else if (offset_type == "2") {
          o->close_type_flag = SelfCloseType::kReserveOptionPosition;
        } else if (offset_type == "1") {
          o->close_type_flag = is_offset ? SelfCloseType::kSelfFuturePosition : SelfCloseType::kNotSelfFuturePosition;
        } else if (offset_type == "6") {
          o->close_type_flag =
            is_offset ? SelfCloseType::kSelfFuturePositionBuy : SelfCloseType::kNotSelfFuturePositionBuy;
        } else if (offset_type == "7") {
          o->close_type_flag = is_offset ? SelfCloseType::kFuturePosition : SelfCloseType::kNotFuturePosition;
        } else {
          o->close_type_flag = SelfCloseType::kSelfFuturePosition;
        }
        o->exec_result = PullExecOrderResultType(vect.at(Self_entrust_status), vect.at(Self_offset_action_type));
        o->status_msg = GbkToUtf8(vect.at(Self_error_message));
        o->volume = stoi(vect.at(Self_entrust_amount));
      });
    if (node->Latest()->exec_result == ExecOrderResultType::kCanceled) {
      m_alive_option_self_close.erase(exec_order_id);
    } else {
      m_alive_option_self_close[exec_order_id] = {futu_code, futucode_type, fopt_expiry, offset_type};
    }
    pUnPacker->Next();
  }
}

void UFXExecOrder::OnQrySelfClose338339(IF2UnPacker* pUnPacker, std::shared_ptr<CHSRspInfoField> RspInfo) {
  pUnPacker->First();
  while (!pUnPacker->IsEOF()) {
    // 将自对冲委托与撤销自对冲委托融合成一个委托单
    // 全部选取自对冲委托 id 作为自对冲 id,丢弃取消自对冲 id
    bool is_first = false;
    auto set_key = GetPackStr(pUnPacker->GetStr("futu_code")) + "|" + GetPackStr(pUnPacker->GetStr("futucode_type"))
      + "|" + GetPackStr(pUnPacker->GetStr("fopt_expiry")) + "|" + GetPackStr(pUnPacker->GetStr("offset_type"));
    if (m_ins_set.find(set_key) != m_ins_set.end()) {
      if (PullExecOrderResultType(
            GetPackStr(pUnPacker->GetStr("entrust_status")), GetPackStr(pUnPacker->GetStr("offset_action_type")))
        == ExecOrderResultType::kCanceled) {
        pUnPacker->Next();
        continue;
      }
    } else {
      is_first = true;
      m_ins_set.insert(set_key);
      if (PullExecOrderResultType(
            GetPackStr(pUnPacker->GetStr("entrust_status")), GetPackStr(pUnPacker->GetStr("offset_action_type")))
        == ExecOrderResultType::kCanceled) {
        pUnPacker->Next();
        continue;
      }
    }

    auto futucode_type = GetPackStr(pUnPacker->GetStr("futucode_type"));
    auto fopt_expiry = GetPackStr(pUnPacker->GetStr("fopt_expiry"));
    auto futu_code = GetPackStr(pUnPacker->GetStr("futu_code"));
    auto offset_type = GetPackStr(pUnPacker->GetStr("offset_type"));
    std::string ins_id;
    if (!futu_code.empty() && futu_code != "!") {
      ins_id = futu_code;
    } else if (!fopt_expiry.empty() && fopt_expiry != " " && fopt_expiry != "!") {
      ins_id = fopt_expiry;
    } else if (!futucode_type.empty() && futucode_type != "!") {
      ins_id = futucode_type;
    } else {
      ins_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
    }
    auto exec_order_id = GetPackStr(pUnPacker->GetStr("entrust_no"));
    auto node = m_service->GetNodeDb()->ReplaceRecord<OptionSelfClose>(
      m_service->m_user_key + "|" + exec_order_id, [=](std::shared_ptr<OptionSelfClose> o) {
        o->self_close_id = exec_order_id;
        o->investor_id = GetPackStr(pUnPacker->GetStr("fund_account"));
        o->user_key = m_service->m_user_key;
        o->instrument_id = ins_id;
        o->hedge_flag = future::OrderHedgeFlag::kSpeculation;
        o->self_close_id = std::to_string(pUnPacker->GetInt("entrust_no"));
        o->exchange_id = PullExId(GetPackStr(pUnPacker->GetStr("futu_exch_type")));
        o->exchange_self_close_sysid = std::to_string(pUnPacker->GetInt("entrust_no"));
        auto if_offset = pUnPacker->GetChar("if_offset");
        if (offset_type == "0") {
          o->close_type_flag = if_offset == '1' ? SelfCloseType::kOptionPosition : SelfCloseType::kNotOptionPosition;
        } else if (offset_type == "2") {
          o->close_type_flag = SelfCloseType::kReserveOptionPosition;
        } else if (offset_type == "1") {
          o->close_type_flag =
            if_offset == '1' ? SelfCloseType::kSelfFuturePosition : SelfCloseType::kNotSelfFuturePosition;
        } else if (offset_type == "6") {
          o->close_type_flag =
            if_offset == '1' ? SelfCloseType::kSelfFuturePositionBuy : SelfCloseType::kNotSelfFuturePositionBuy;
        } else if (offset_type == "7") {
          o->close_type_flag = if_offset == '1' ? SelfCloseType::kFuturePosition : SelfCloseType::kNotFuturePosition;
        } else {
          o->close_type_flag = SelfCloseType::kSelfFuturePosition;
        }
        o->exec_result = is_first ? PullExecOrderResultType(GetPackStr(pUnPacker->GetStr("entrust_status")),
                           GetPackStr(pUnPacker->GetStr("offset_action_type")))
                                  : ExecOrderResultType::kCanceled;
        o->volume = pUnPacker->GetInt("entrust_amount");
        o->insert_date_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pUnPacker->GetStr("entrust_time"));
        o->status_msg = GbkToUtf8(GetPackStr(pUnPacker->GetStr("error_message")));
      });
    if (node->Latest()->exec_result == ExecOrderResultType::kCanceled) {
      m_alive_option_self_close.erase(exec_order_id);
    } else {
      m_alive_option_self_close[exec_order_id] = {futu_code, futucode_type, fopt_expiry, offset_type};
    }
    pUnPacker->Next();
  }
  if (pUnPacker->GetRowCount() < 1000)
    return;
  pUnPacker->Last();
  std::string pos_str = GetPackStr(pUnPacker->GetStr("position_str"));
  QrySelfClose338339(pos_str);
}

void UFXExecOrder::QrySelfClose338339(const std::string& pos_str) {
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  /// 加入字段名
  pPacker->AddField("op_entrust_way", 'C', 1);  // 委托方式
  pPacker->AddField("op_station", 'S', 255);    // 站点地址
  pPacker->AddField("branch_no", 'I', 5);       // 分支机构
  pPacker->AddField("client_id", 'S', 18);      // 客户编号
  pPacker->AddField("fund_account", 'S', 18);   // 资产账户
  pPacker->AddField("password", 'S', 13);       // 密码
  pPacker->AddField("user_token", 'S', 512);    // user_token
  pPacker->AddField("request_num", 'I', 10);
  pPacker->AddField("position_str", 'S', 100);

  // 加入对应的字段值
  pPacker->AddChar(m_api_adapter->m_entrust_way);
  pPacker->AddStr(m_api_adapter->m_op_station.c_str());
  pPacker->AddInt(m_api_adapter->m_branch_no);
  pPacker->AddStr(m_api_adapter->m_client_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddInt(1000);
  pPacker->AddStr(pos_str.c_str());

  /// 结束打包
  pPacker->EndPack();

  IBizMessage* pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(338339);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  // 设置包内容
  pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();
}

void UFXExecOrder::ReqCancelOptionSelfClose338226(const std::shared_ptr<UserCommand>& command) {
  auto req = std::static_pointer_cast<CancelOptionSelfClose>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (m_api_adapter->m_session_no == 0) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto it = m_alive_option_self_close.find(req->self_close_id);
  if (it == m_alive_option_self_close.end()) {
    SetCommandFinished(req, -1, u8"fclib: 未找到可撤销的自对冲");
    return;
  }
  auto node = m_service->GetNodeDb()->GetNode<OptionSelfClose>(m_service->m_user_key + "|" + req->self_close_id);
  FCASSERT(node);
  auto& order = it->second;
  // 创建业务包体
  IF2Packer* pPacker = NewPacker(2);
  pPacker->AddRef();
  pPacker->BeginPack();
  /// 加入字段名
  pPacker->AddField("op_entrust_way", 'C', 1);  // 委托方式
  pPacker->AddField("op_station", 'S', 255);    // 站点地址
  pPacker->AddField("branch_no", 'I', 5);       // 分支机构
  pPacker->AddField("client_id", 'S', 18);      // 客户编号
  pPacker->AddField("fund_account", 'S', 18);   // 资产账户
  pPacker->AddField("password", 'S', 13);       // 密码
  pPacker->AddField("user_token", 'S', 512);    // user_token
  pPacker->AddField("futu_exch_type", 'S', 4);  // 交易类别
  pPacker->AddField("futu_code", 'S', 30);      // 合约代码
  pPacker->AddField("offset_type", 'C', 1);     // 申请标志
  pPacker->AddField("futucode_type", 'S', 30);
  pPacker->AddField("fopt_expiry", 'S', 30);
  // 加入对应的字段值
  pPacker->AddChar(m_api_adapter->m_entrust_way);
  pPacker->AddStr(m_api_adapter->m_op_station.c_str());
  pPacker->AddInt(m_api_adapter->m_branch_no);
  pPacker->AddStr(m_api_adapter->m_client_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->user_id.c_str());
  pPacker->AddStr(m_api_adapter->m_login_info->password.c_str());
  pPacker->AddStr(m_api_adapter->m_user_token.c_str());
  pPacker->AddStr(PushExType(node->Latest()->exchange_id));
  pPacker->AddStr(order.futu_code.c_str());
  pPacker->AddChar(order.offset_type[0]);
  pPacker->AddStr(order.futucode_type.c_str());
  pPacker->AddStr(order.fopt_expiry.c_str());

  /// 结束打包
  pPacker->EndPack();

  IBizMessage* pBizMessage = NewBizMessage();
  pBizMessage->AddRef();
  // 设置包头
  pBizMessage->SetFunction(338226);
  pBizMessage->SetPacketType(REQUEST_PACKET);
  // 设置包内容
  pBizMessage->SetContent(pPacker->GetPackBuf(), pPacker->GetPackLen());
  // 异步发送
  int nRet = m_api_adapter->m_pConnection->SendBizMsg(pBizMessage, 1);

  // 释放资源
  pPacker->FreeMem(pPacker->GetPackBuf());
  pPacker->Release();
  pBizMessage->Release();
  m_service->m_command_manager->SetCommandId(req, "CancelOptionSelfClose" + std::to_string(nRet));
  if (nRet <= 0) {
    SetCommandFinished(req, nRet, GbkToUtf8(m_api_adapter->m_pConnection->GetErrorMsg(nRet)));
  }
}

