void UFXApiAdapter::OnReceivedBizMsg(CConnectionInterface *m_pConnection, int hSend, IBizMessage *lpMsg) {
  if (lpMsg == NULL)
    return;
  if (lpMsg->GetFunction() == MSGCENTER_FUNC_HEART) {
    OnHeartbeat(lpMsg);
    return;
  }
  IBizMessage *msg = NewBizMessage();
  msg->AddRef();
  int nBuffLen = 0;
  void *lpBuff = lpMsg->GetBuff(nBuffLen);
  msg->SetBuff(lpBuff, nBuffLen);
  // 增加引用,压入队列
  m_strand.post([=]() {
    m_recv_queue.push(std::make_pair(msg, hSend));
  });
}

