int UFXApiAdapter::InitConnect(
  const char *pszLicFile, const char *pszSafeLevel, const char *pszPwd, const char *pszSslFile, const char *pszSslPwd) {
  // 配置连接对象
  std::string front_addr = "";
  FCASSERT(m_login_info);
  for (const auto &front : m_login_info->broker.trading_fronts) {
    front_addr += (front + ";");
  }
  m_pConfig->SetString("t2sdk", "servers", front_addr.c_str());
  m_pConfig->SetString("t2sdk", "license_file", m_login_info->license_file_addr.c_str());
  m_pConfig->SetInt("t2sdk", "init_recv_buf_size", 512);
  m_pConfig->SetInt("t2sdk", "init_send_buf_size", 512);
  m_pConfig->SetInt("t2sdk", "send_queue_size", 10000);
  m_pConfig->SetInt("t2sdk", "heartbeat_time", 30);

  // 通讯加密设置，必须在NewConnection之前
  // 如果接入前置t2通道设置了safe_level = pwd
  if (std::string(pszSafeLevel) == "pwd") {
    m_pConfig->SetString("safe", "safe_level", "pwd");
    // 通信密码
    m_pConfig->SetString("safe", "comm_pwd", pszPwd);
  }

  // 如果接入前置t2通道设置了safe_level = ssl
  if (strcmp(pszSslFile, "") != 0) {
    m_pConfig->SetString("safe", "safe_level", "ssl");
    m_pConfig->SetString("safe", "cert_file", pszSslFile);  // Cert文件
    m_pConfig->SetString("safe", "cert_pwd", pszSslPwd);    // Cert密码
  }
  if (!m_test_mode) {
    if (m_pConnection != NULL) {
      m_pConnection->Release();
      m_pConnection = NULL;
    }
    m_pConnection = NewConnection(m_pConfig);
    m_pConnection->AddRef();
  }
  int nRet = 0;
  if (0 != (nRet = m_pConnection->Create2BizMsg(this))) {
    return nRet;
  }
  if (0 != (nRet = m_pConnection->Connect(2000))) {
    return nRet;
  }
  return nRet;
}

void UFXApiAdapter::TestMode(CConnectionInterface *c) {
  m_pConnection = c;
  m_test_mode = true;
}

