// 维护心跳
void UFXApiAdapter::OnHeartbeat(IBizMessage *pMsg) {
  // 订阅心跳维护
  if (pMsg->GetPacketType() == REQUEST_PACKET) {
    pMsg->ChangeReq2AnsMessage();
    if (NULL != m_pConnection)
      m_pConnection->SendBizMsg(pMsg, 1);
  }
}

