void XuntouServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, 1, u8"fclib: 暂不支持本指令");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

void XuntouServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int XuntouServiceImpl::RunOnce() {
  // api运转一次
  int msg_count = 0;
  int has_account = 0;
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  while (!m_recv_queue.empty()) {
    auto msg = m_recv_queue.front();
    if (msg->tag == SpiMessage::Tag::onRtnAccountDetail) {
      m_account_snap = msg;
      has_account = 1;
      m_recv_queue.pop();
      continue;
    }
    ProcessSpiMsg(msg);
    m_recv_queue.pop();
    msg_count++;
  }
  if (has_account == 1)
    ProcessSpiMsg(m_account_snap);
  // 返回处理数据包数量
  return msg_count + has_account;
}

void XuntouServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_processor[tag] = processor;
}

void XuntouServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

int XuntouServiceImpl::BuildApi(std::shared_ptr<UserCommand> command) {
  m_req_login = std::static_pointer_cast<ReqLogin>(m_command_manager->Update(command));
  DeleteApi();
  if (m_req_login->broker.trading_fronts.size() < 1)
    return -1;
  m_api = ApiCreator(m_req_login->broker.trading_fronts[0].c_str());
  m_spi = new XuntouSpiHandler(m_ioc, m_logger, this);
  m_api->setCallback(m_spi);
  if (!m_api->init())
    return -1;
  return 0;
}

void XuntouServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->setCallback(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api->destroy();
  m_api = nullptr;
}

