template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(
  SpiMessage::Tag tag, const T *plain_src = nullptr, int req_id = 0, bool is_last = true) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>(*plain_src);
    msg->pMainField = target;
  }
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

