future::SubPosition* GetSubPosition(
  std::shared_ptr<future::Position> position, const Direction& posi_dir, const OrderHedgeFlag& hedge) {
  if (posi_dir == Direction::kBuy) {
    if (hedge == OrderHedgeFlag::kSpeculation)
      return &position->subpos_long_spec;
    else
      return &position->subpos_long_other;
  } else if (posi_dir == Direction::kSell) {
    if (hedge == OrderHedgeFlag::kSpeculation)
      return &position->subpos_short_spec;
    else
      return &position->subpos_short_other;
  }
  FCASSERT(false);
  return nullptr;
}

XuntouPositionAccount::XuntouPositionAccount(
  XuntouServiceImpl* service, std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger)
  : m_service(service)
  , m_helper(helper)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnOrderDetail, [this](std::shared_ptr<SpiMessage> msg) {
    m_service->m_api->reqPositionStatics(
      m_service->m_account_id.c_str(), m_service->GetReqId(), m_service->m_account_key.c_str());
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onReqPositionStatics, [this](std::shared_ptr<SpiMessage> msg) {
    onReqPositionStatics(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onReqAccountDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnAccountDetail(msg);
    UpdateAccountProfit();
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnAccountDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnAccountDetail(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnDealDetail, [this](std::shared_ptr<SpiMessage> msg) {
    m_service->m_api->reqPositionStatics(
      m_service->m_account_id.c_str(), m_service->GetReqId(), m_service->m_account_key.c_str());
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    m_service->m_api->reqAccountDetail(
      m_service->m_account_id.c_str(), m_service->GetReqId(), m_service->m_account_key.c_str());
    m_service->m_api->reqPositionStatics(
      m_service->m_account_id.c_str(), m_service->GetReqId(), m_service->m_account_key.c_str());
  });
  m_position_view = m_service->GetNodeDb()->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_service->m_user_key && pos->unit_id == 0;
  });
}

void XuntouPositionAccount::onReqPositionStatics(std::shared_ptr<SpiMessage> msg) {
  if (msg->bIsLast && !m_init_position) {
    m_init_position = true;
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_service->m_user_key;
        p->position_ready = true;
        p->account_ready = true;
      });
  }
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::CPositionStatics>(msg->pMainField);
  auto position_key = Position::MakeKey(
    m_service->m_user_key, 0, std::string(field->m_strExchangeID) + "." + std::string(field->m_strInstrumentID));
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target_position) {
      target_position->user_key = m_service->m_user_key;
      target_position->investor_id = m_service->m_account_id;
      target_position->exchange_id = field->m_strExchangeID;
      target_position->instrument_id = field->m_strInstrumentID;
      future::SubPosition* subpos =
        GetSubPosition(target_position, PullDir(field->m_nDirection), PullHedge(field->m_nHedgeFlag));
      if (field->m_nHedgeFlag == xti::EHedgeFlagType::HEDGE_FLAG_ARBITRAGE) {
        subpos->hedge_type = PositionHedgeType::kArbitrage;
      }
      if (field->m_bIsToday) {
        subpos->volume_today = field->m_nPosition;
        subpos->volume_today_frozen = field->m_nPosition - field->m_nCanCloseVolume;
        subpos->_position_cost = field->m_dAveragePrice * field->m_nPosition;
        subpos->_open_cost = field->m_dOpenPrice * field->m_nPosition;
        subpos->_margin = field->m_dUsedMargin;
        subpos->_commission = field->m_dUsedCommission;
      } else {
        subpos->volume_his = field->m_nPosition;
        subpos->volume_his_frozen = field->m_nPosition - field->m_nCanCloseVolume;
        subpos->_position_cost_his = field->m_dAveragePrice * field->m_nPosition;
        subpos->_open_cost_his = field->m_dOpenPrice * field->m_nPosition;
        subpos->_margin_his = field->m_dUsedMargin;
        subpos->_commission_his = field->m_dUsedCommission;
      }
      subpos->margin = subpos->_margin + subpos->_margin_his;
      subpos->commission = subpos->_commission + subpos->_commission_his;
      subpos->position_price =
        subpos->Volume() == 0 ? 0.0 : (subpos->_position_cost_his + subpos->_position_cost) / subpos->Volume();
      subpos->open_price =
        subpos->Volume() == 0 ? 0.0 : (subpos->_open_cost_his + subpos->_open_cost) / subpos->Volume();
      UpdatePositionProfit(target_position);
    });
}

void XuntouPositionAccount::onRtnAccountDetail(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::CAccountDetail>(msg->pMainField);
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> target_account) {
    target_account->user_key = m_service->m_user_key;
    target_account->currency = "CNY";
    target_account->investor_id = field->m_strAccountID;
    target_account->available = field->m_dAvailable;
    target_account->client_equity = field->m_dBalance;
    target_account->commission = field->m_dCommission;
    target_account->frozen_commission = field->m_dFrozenCommission;
    target_account->margin = field->m_dCurrMargin;
    target_account->frozen_margin = field->m_dFrozenMargin;
    target_account->premium = field->m_dPremiumNetExpense;
    target_account->close_profit = field->m_dCloseProfit;
    target_account->position_profit = field->m_dPositionProfit;
    target_account->deposit = field->m_dDeposit;
    target_account->withdraw = field->m_dWithdraw;
    target_account->balance = field->m_dBalance;
    target_account->pre_balance = field->m_dPreBalance;
    target_account->risk_ratio = field->m_dRisk;
    if (target_account->balance > 0) {
      target_account->ref_risk_ratio = target_account->margin / target_account->balance;
    }
  });
}

void XuntouPositionAccount::UpdatePositionProfit(std::shared_ptr<Position> position) {
  auto ins = m_helper->GetShmInstrument(position->Symbol(), true);
  if (ins->last_price == 0.0 || isnan(ins->last_price))
    return;
  position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption) {
        subpos->position_profit =
          (position->last_price - subpos->position_price) * ins->volume_multiple * subpos->Volume();
        subpos->float_profit = (position->last_price - subpos->open_price) * ins->volume_multiple * subpos->Volume();
      }
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

void XuntouPositionAccount::UpdateAccountProfit() {
  auto account_node = m_service->m_node_db->GetNode<Account>(m_service->m_user_key + "|0|CNY");
  if (!account_node)
    return;
  double float_profit = 0.0;
  double option_buy_market_value = 0.0;
  double option_sell_market_value = 0.0;
  double future_market_value = 0.0;
  auto& position_node_map = m_position_view->GetNodes();
  for (auto& [key, position_node] : position_node_map) {
    if (!position_node->Snap())
      continue;
    auto product_class =
      m_helper->GetShmInstrumentField(position_node->Snap()->Symbol(), &shm::ShmInstrument::product_class);
    if (product_class != md::ProductClass::kCombine) {
      if (!isnan(position_node->Latest()->FloatProfit()))
        float_profit += position_node->Latest()->FloatProfit();
      if (product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
      }
      if (product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->ShortMarketValue() + position_node->Latest()->LongMarketValue();
    }
  }
  m_service->m_node_db->ReplaceRecord<Account>(
    m_service->m_user_key + "|0|CNY", [=](std::shared_ptr<future::Account> account) {
      account->user_key = m_service->m_user_key;
      account->option_buy_market_value = option_buy_market_value;
      account->option_sell_market_value = option_sell_market_value;
      account->option_market_value = option_buy_market_value + option_sell_market_value;
      account->float_profit = float_profit;
      account->future_market_value = future_market_value;
    });
}

int XuntouPositionAccount::RunOnce() {
  int ret = 0;
  auto& target_position_node_map = m_position_view->GetNodes();
  for (auto& [pos_key, position_node] : target_position_node_map) {
    auto position = position_node->Snap();
    auto ins = m_helper->GetShmInstrument(position->Symbol(), true);
    if (!position || ins->product_class == md::ProductClass::kCombine || ins->last_price == position->last_price
      || std::isnan(ins->last_price))
      continue;
    m_service->GetNodeDb()->ReplaceRecord<Position>(pos_key, [this](std::shared_ptr<Position> calc_position) {
      UpdatePositionProfit(calc_position);
    });
    ret++;
  }
  if (ret > 0)
    UpdateAccountProfit();
  return ret;
}
