void XuntouInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (m_service->m_api_ready == false) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    auto order_key = Order::MakeKey(m_service->m_user_key, req->order_id);
    m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
      o->user_key = m_service->m_user_key;
      o->user_id = m_service->m_req_login->user_id;
      o->order_id = req->order_id;
      o->investor_id = m_service->m_req_login->user_id;
      o->exchange_id = req->exchange_id;
      o->instrument_id = req->instrument_id;
      o->status = OrderStatus::kDead;
      o->status_msg = u8"fclib: 交易API未就绪,请稍后重试";
      o->direction = req->direction;
      o->offset = req->offset;
      o->time_condition = req->time_condition;
      o->volume_condition = req->volume_condition;
      o->price_type = req->price_type;
      o->volume_orign = req->volume;
      o->volume_left = req->volume;
      o->limit_price = req->limit_price;
      o->hedge_flag = req->hedge_flag;
      o->force_close_reason = ForceCloseReason::kNotForceClose;
    });
    return;
  }
  auto order_id = req->order_id;
  m_service->m_send_time[req->order_id] = NowAsEpochNano();
  xti::COrdinaryOrder field;
  strcpy_x(field.m_strAccountID, m_service->m_account_id);
  field.m_dPrice = req->limit_price;
  field.m_nVolume = req->volume;
  strcpy_x(field.m_strInstrument, req->instrument_id);
  field.m_ePriceType = PushOrderType(req->price_type);
  if (field.m_ePriceType == xti::EPriceType::PRTP_INVALID) {
    SetCommandFinished(req, -1, u8"fclib: 不支持此报价方式");
    return;
  }
  field.m_eOperationType = PushOperationType(req->direction, req->offset);
  if (field.m_eOperationType == xti::EOperationType::OPT_INVALID) {
    SetCommandFinished(req, -1, u8"fclib: 买卖/开平方向无效");
    return;
  }
  field.m_eHedgeFlag = PushHedge(req->hedge_flag);
  field.m_eTimeCondition = PushTimeCondition(req->time_condition);
  field.m_eVolumeCondition = PushVolumeCondition(req->volume_condition);
  strcpy_x(field.m_strRemark, order_id);
  strcpy_x(field.m_strMarket, req->exchange_id);
  int req_id = m_service->GetReqId();
  m_service->m_api->order(&field, req_id, m_service->m_account_key.c_str());
  m_logger.With("m_strInstrument", field.m_strInstrument)
    .With("OrderQty", field.m_nVolume)
    .With("Reference", field.m_strRemark)
    .With("m_dPrice", field.m_dPrice)
    .With("m_ePriceType", std::to_string(field.m_ePriceType))
    .With("m_eOperationType", std::to_string(field.m_eOperationType))
    .With("m_eTimeCondition", std::to_string(field.m_eTimeCondition))
    .With("m_eVolumeCondition", std::to_string(field.m_eVolumeCondition))
    .With("m_eHedgeFlag", std::to_string(field.m_eHedgeFlag))
    .Info("ReqOrderInsert");
  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + std::to_string(req_id));
}

void XuntouInsertCancelOrder::onOrder(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<InsertOrder>(
    m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(msg->nRequestID)));
  auto field = std::static_pointer_cast<onOrderField>(msg->pMainField);
  std::string order_id = field->m_strRemark;
  auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
  SetCommandFinished(req, msg->nErrorCode, msg->error_msg);
}

void XuntouInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  if (m_service->m_api_ready == false) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  req->status = UserCommand::Status::kStarted;
  auto it = m_order_alive.find(req->order_id);
  if (it == m_order_alive.end()) {
    SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
    return;
  }
  int req_id = m_service->GetReqId();
  m_service->m_api->cancel(it->second, req_id);
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::to_string(req_id));
}

void XuntouInsertCancelOrder::onCancelWithRemark(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<onCancelWithRemarkField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(msg->nRequestID));
  SetCommandFinished(req, msg->nErrorCode, GbkToUtf8(msg->error_msg));
}

void XuntouInsertCancelOrder::onRtnOrderDetail(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::COrderDetail>(msg->pMainField);
  if (field->m_nAccountType != m_service->m_req_login->xuntou.sub_user_type)
    return;
  std::string order_id = IsRefValid(field->m_strRemark) ? field->m_strRemark : std::to_string(field->m_nOrderID);
  if (PullOrderStatus(field->m_eOrderStatus) == OrderStatus::kAlive) {
    m_order_alive[order_id] = field->m_nOrderID;
  } else {
    m_order_alive.erase(order_id);
  }
}

