}

void XuntouSpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_impl)
    return;
  auto queue = m_impl->GetSpiQueue();
  m_strand.post([=]() {
    queue->push(msg);
  });
}

