  m_service->RegisterMsgProcessor(SpiMessage::Tag::onReqDealDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnDealDetail(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onOrder, [this](std::shared_ptr<SpiMessage> msg) {
    onOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onReqOrderDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnOrderDetail(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnDealDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnDealDetail(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    m_service->m_api->reqOrderDetail(
      m_service->m_account_id.c_str(), m_service->GetReqId(), m_service->m_account_key.c_str());
