  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::COrderDetail>(msg->pMainField);
  if (field->m_nAccountType != m_service->m_req_login->xuntou.sub_user_type)
    return;
  std::string order_id = IsRefValid(field->m_strRemark) ? field->m_strRemark : std::to_string(field->m_nOrderID);
  // 赋值字段
  auto order_key = m_service->m_user_key + "|" + order_id;
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    o->exchange_order_id = field->m_strOrderSysID;
    o->user_key = m_service->m_user_key;
    o->user_id = m_service->m_req_login->user_id;
    o->order_id = order_id;
    o->investor_id = m_service->m_req_login->user_id;
    o->exchange_id = field->m_strExchangeID;
    o->instrument_id = field->m_strInstrumentID;
    o->status = PullOrderStatus(field->m_eOrderStatus);
    o->status_msg = field->m_strErrorMsg;
    o->direction = PullDir(field->m_nDirection);
    o->offset = PullOffset(field->m_eOffsetFlag);
    o->force_close_reason = ForceCloseReason::kNotForceClose;
    if (field->m_nOrderPriceType == xti::EBrokerPriceType::BROKER_PRICE_LIMIT) {
      o->time_condition = OrderTimeCondition::kGfd;
      o->volume_condition = OrderVolumeCondition::kAny;
      o->price_type = PriceType::kLimit;
    } else {
      o->time_condition = OrderTimeCondition::kIoc;
      o->volume_condition = OrderVolumeCondition::kAny;
      o->price_type = PriceType::kAny;
    }
    o->volume_orign = field->m_nTotalVolume;
    o->volume_left = field->m_nTotalVolume - field->m_nTradedVolume;
    o->limit_price = field->m_dLimitPrice;
    o->hedge_flag = PullHedge(field->m_eHedgeFlag);
    o->insert_date_time = StringToEpochNano(field->m_strInsertDate, field->m_strInsertTime);
  });
}

void XuntouOrderTradeView::onRtnDealDetail(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::CDealDetail>(msg->pMainField);
  if (field->m_nAccountType != m_service->m_req_login->xuntou.sub_user_type)
    return;
  std::string order_id = IsRefValid(field->m_strRemark) ? field->m_strRemark : std::to_string(field->m_nOrderID);
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(Order::MakeKey(m_service->m_user_key, order_id));
  auto trade_key = Trade::MakeKey(m_service->m_user_key, field->m_strTradeID, field->m_strOrderSysID);
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->investor_id = m_service->m_req_login->user_id;
    trade->user_id = m_service->m_req_login->user_id;
    trade->direction = PullDir(field->m_nDirection);
    trade->exchange_id = field->m_strExchangeID;
    trade->instrument_id = field->m_strInstrumentID;
    trade->exchange_trade_id = field->m_strTradeID;
    trade->offset = PullOffset(field->m_nOffsetFlag);
    trade->exchange_order_id = field->m_strOrderSysID;
    trade->hedge_flag = PullHedge(field->m_nHedgeFlag);
    trade->price = field->m_dAveragePrice;
    trade->volume = field->m_nVolume;
    trade->user_key = m_service->m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->commission = field->m_dComssion;
    trade->trade_date_time = StringToEpochNano(field->m_strTradeDate, field->m_strTradeTime);
  });
}

void XuntouOrderTradeView::onOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<onOrderField>(msg->pMainField);
  auto req = std::static_pointer_cast<InsertOrder>(
    m_service->m_command_manager->Update("ReqInsertOrder" + std::to_string(msg->nRequestID)));
  FCASSERT(req);
  std::string order_id = field->m_strRemark;
  // 赋值字段
  auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    if (o->session_id == 0) {
      o->session_id = m_service->m_session_id;
    }
    o->user_key = m_service->m_user_key;
    o->user_id = m_service->m_req_login->user_id;
    o->order_id = order_id;
    o->investor_id = m_service->m_req_login->user_id;
    o->exchange_id = req->exchange_id;
    o->instrument_id = req->instrument_id;
    o->status = OrderStatus::kAlive;
    o->status_msg = u8"已发出";
    if (msg->nErrorCode != 0) {
      o->status = OrderStatus::kDead;
      o->status_msg = IsGBK(msg->error_msg) ? GbkToUtf8(msg->error_msg) : msg->error_msg;
    }
    o->direction = req->direction;
    o->offset = req->offset;
    o->time_condition = req->time_condition;
    o->volume_condition = req->volume_condition;
    o->price_type = req->price_type;
    o->volume_orign = req->volume;
    o->volume_left = req->volume;
    o->limit_price = req->limit_price;
    o->hedge_flag = req->hedge_flag;
    o->force_close_reason = ForceCloseReason::kNotForceClose;
  });
}

void XuntouOrderTradeView::onRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::COrderInfo>(msg->pMainField);
  if (field->m_eBrokerType != m_service->m_req_login->xuntou.sub_user_type)
    return;
  std::string order_id = IsRefValid(field->m_strRemark) ? field->m_strRemark : std::to_string(field->m_nOrderID);
  // 赋值字段
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto node = m_service->GetNodeDb()->GetNode<Order>(order_key);
  if (!node)
    return;
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    o->user_key = m_service->m_user_key;
    o->user_id = m_service->m_req_login->user_id;
    o->order_id = order_id;
    o->investor_id = m_service->m_req_login->user_id;
    o->force_close_reason = ForceCloseReason::kNotForceClose;
    o->status = (field->m_eStatus == 0 || field->m_eStatus == 2 || field->m_eStatus == -1) ? OrderStatus::kAlive
                                                                                           : OrderStatus::kDead;
    o->status_msg = field->m_strMsg;
    o->volume_left = o->volume_orign - static_cast<int>(field->m_dTradedVolume);
    o->insert_date_time = field->m_startTime;
    o->insert_date_time *= 1000000000;
    o->dead_date_time = field->m_endTime > 2147083647 ? 0 : field->m_endTime;
    o->dead_date_time *= 1000000000;
    auto iter = m_service->m_send_time.find(o->order_id);
    if (iter != m_service->m_send_time.end()) {
      o->send_date_time = iter->second;
      m_service->m_send_time.erase(iter);
    }
    if (o->receive_date_time == 0) {
      o->receive_date_time = NowAsEpochNano();
    }
  });
}

