XuntouLogIn::XuntouLogIn(XuntouServiceImpl *service, structlog::Logger &parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onConnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnConnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onRtnLoginStatusWithActKey, [this](std::shared_ptr<SpiMessage> msg) {
    onRtnLoginStatusWithActKey(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::onReqAccountDetail, [this](std::shared_ptr<SpiMessage> msg) {
    onReqAccountDetail(msg);
  });
}

void XuntouLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  int ret = m_service->BuildApi(command);
  if (ret != 0)
    SetCommandFinished(command, -1, u8"fclib: API创建失败,请检查交易前置");
  m_service->m_command_manager->SetCommandId(command, "login");
}

void XuntouLogIn::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("login");
  if (msg->nErrorCode != 0) {
    SetCommandFinished(req, msg->nErrorCode, GbkToUtf8(msg->error_msg));
    return;
  }
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->investor_id = m_service->m_req_login->user_id;
      target_login->session_status = SessionStatus::kLogined;
      target_login->system_name = "xuntou";
      target_login->backend = BackEnd::kXuntou;
      target_login->session_id = reinterpret_cast<int64_t>(msg.get());
      target_login->confirm_status = ConfirmStatus::kConfirmed;
      if (target_login->user_desc == "") {
        target_login->user_desc = m_service->m_req_login->user_desc;
      }
    });
  SetCommandFinished(req, 0, u8"登录成功");
  m_service->m_session_id = reinterpret_cast<int64_t>(msg.get());
}

void XuntouLogIn::OnConnected(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode == 0) {
    m_service->m_api->userLogin(m_service->m_req_login->user_id.c_str(), m_service->m_req_login->password.c_str(),
      m_service->GetReqId(), m_service->m_req_login->broker.product_info.c_str(),
      m_service->m_req_login->broker.app_id.c_str(), m_service->m_req_login->broker.auth_code.c_str());
    return;
  }
  auto req = m_service->m_command_manager->Update("login");
  SetCommandFinished(req, msg->nErrorCode, GbkToUtf8(msg->error_msg));
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->investor_id = m_service->m_req_login->user_id;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->session_status = SessionStatus::kDisconnected;
      target_login->system_name = u8"xuntou";
      target_login->backend = BackEnd::kXuntou;
      target_login->status_msg = GbkToUtf8(msg->error_msg);
    });
}

void XuntouLogIn::onRtnLoginStatusWithActKey(std::shared_ptr<SpiMessage> msg) {
  auto pRspUserLogin = std::static_pointer_cast<LoginStatus>(msg->pMainField);
  if (pRspUserLogin->broker_type != m_service->m_req_login->xuntou.sub_user_type)
    return;
  if (pRspUserLogin->status == xti::BROKER_LOGIN_STATUS_OK) {
    m_service->m_api_ready = true;
  } else {
    m_service->m_api_ready = false;
  }
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->investor_id = pRspUserLogin->account_id;
      target_login->session_status = SessionStatus::kLogined;
      target_login->system_name = "xuntou";
      target_login->backend = BackEnd::kXuntou;
    });
  m_service->m_account_id = std::string(pRspUserLogin->account_id);
  m_service->m_account_key = pRspUserLogin->account_key;
  m_logger.With("broker_type", pRspUserLogin->broker_type)
    .With("account_id", pRspUserLogin->account_id)
    .With("account_key", pRspUserLogin->account_key)
    .Info("broker_type");
}

void XuntouLogIn::onReqAccountDetail(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<xti::CAccountDetail>(msg->pMainField);
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      if (!target_login->trading_day.empty() && target_login->trading_day != field->m_strTradingDate) {
        m_service->m_new_day = true;
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = field->m_strTradingDate;
      target_login->system_name = "xuntou";
      target_login->backend = BackEnd::kXuntou;
    });
}

int XuntouLogIn::RunOnce() {
  return 0;
}

