/*******************************************************************************
 * @file xuntou_convert.cpp
 * @brief Dstar数据类型转换
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "xuntou_convert.h"

#include <algorithm>
#include <string>

namespace fclib {
namespace future {
namespace xuntou {
bool IsGBK(const std::string& str) {
  unsigned char c1, c2;
  size_t i = 0;
  while (i < str.size()) {
    if (!(str[i] & 0x80)) {
      i++;
      continue;
    } else {
      c1 = str[i++];
      c2 = str[i++];
      if (c1 >= 0x81 && c1 <= 0xFE && c2 >= 0x40 && c2 <= 0xFE)
        continue;
      else
        return false;
    }
  }
  return true;
}

bool IsRefValid(const std::string& ref) {
  if (ref.find("fclib") != std::string::npos)
    return true;
  return false;
}

Direction PullDir(const xti::EEntrustBS& d) {
  if (d == xti::EEntrustBS::ENTRUST_BUY)
    return Direction::kBuy;
  if (d == xti::EEntrustBS::ENTRUST_SELL)
    return Direction::kSell;
  return Direction::kInvalid;
}

Offset PullOffset(const xti::EOffsetFlagType& o) {
  if (o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_Open)
    return Offset::kOpen;
  if (o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_Close || o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_ForceClose
    || o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_LocalForceClose)
    return Offset::kClose;
  if (o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_CloseToday)
    return Offset::kCloseToday;
  if (o == xti::EOffsetFlagType::EOFF_THOST_FTDC_OF_CloseYesterday)
    return Offset::kCloseYesterday;
  return Offset::kInvalid;
}

OrderHedgeFlag PullHedge(const xti::EHedgeFlagType& h) {
  if (h == xti::EHedgeFlagType::HEDGE_FLAG_SPECULATION)
    return OrderHedgeFlag::kSpeculation;
  return OrderHedgeFlag::kHedge;
}

xti::EPriceType PushOrderType(PriceType& o) {
  if (o == PriceType::kLimit)
    return xti::EPriceType::PRTP_FIX;
  if (o == PriceType::kAny)
    return xti::EPriceType::PRTP_MARKET;
  if (o == PriceType::kBest)
    return xti::EPriceType::PRTP_MARKET_BEST;
  return xti::EPriceType::PRTP_INVALID;
}

OrderStatus PullOrderStatus(const xti::EEntrustStatus& s) {
  if (s == xti::EEntrustStatus::ENTRUST_STATUS_PART_CANCEL || s == xti::EEntrustStatus::ENTRUST_STATUS_CANCELED
    || s == xti::EEntrustStatus::ENTRUST_STATUS_SUCCEEDED || s == xti::EEntrustStatus::ENTRUST_STATUS_JUNK)
    return OrderStatus::kDead;
  return OrderStatus::kAlive;
}

xti::EOperationType PushOperationType(const Direction& d, const Offset& o) {
  if (d == Direction::kBuy) {
    if (o == Offset::kOpen)
      return xti::EOperationType::OPT_OPEN_LONG;
    if (o == Offset::kClose)
      return xti::EOperationType::OPT_CLOSE_SHORT_HISTORY_FIRST;
    if (o == Offset::kCloseToday)
      return xti::EOperationType::OPT_CLOSE_SHORT_TODAY;
    if (o == Offset::kCloseYesterday)
      return xti::EOperationType::OPT_CLOSE_SHORT_HISTORY;
  } else {
    if (o == Offset::kOpen)
      return xti::EOperationType::OPT_OPEN_SHORT;
    if (o == Offset::kClose)
      return xti::EOperationType::OPT_CLOSE_LONG_HISTORY_FIRST;
    if (o == Offset::kCloseToday)
      return xti::EOperationType::OPT_CLOSE_LONG_TODAY;
    if (o == Offset::kCloseYesterday)
      return xti::EOperationType::OPT_CLOSE_LONG_HISTORY;
  }
  return xti::EOperationType::OPT_INVALID;
}

xti::EHedgeFlagType PushHedge(const OrderHedgeFlag& h) {
  if (h == OrderHedgeFlag::kArbitrage)
    return xti::EHedgeFlagType::HEDGE_FLAG_ARBITRAGE;
  if (h == OrderHedgeFlag::kHedge)
    return xti::EHedgeFlagType::HEDGE_FLAG_HEDGE;
  return xti::EHedgeFlagType::HEDGE_FLAG_SPECULATION;
}

xti::ETimeCondition PushTimeCondition(const OrderTimeCondition& t) {
  if (t == OrderTimeCondition::kGfa)
    return xti::ETimeCondition::TIME_CONDITION_GFA;
  if (t == OrderTimeCondition::kGfd)
    return xti::ETimeCondition::TIME_CONDITION_GFD;
  if (t == OrderTimeCondition::kGfs)
    return xti::ETimeCondition::TIME_CONDITION_GFS;
  if (t == OrderTimeCondition::kGtc)
    return xti::ETimeCondition::TIME_CONDITION_GTC;
  if (t == OrderTimeCondition::kGtd)
    return xti::ETimeCondition::TIME_CONDITION_GTD;
  return xti::ETimeCondition::TIME_CONDITION_IOC;
}

xti::EVolumeCondition PushVolumeCondition(const OrderVolumeCondition& t) {
  if (t == OrderVolumeCondition::kAll)
    return xti::EVolumeCondition::VOLUME_CONDITION_TOTAL;
  if (t == OrderVolumeCondition::kMin)
    return xti::EVolumeCondition::VOLUME_CONDITION_MIN;
  return xti::EVolumeCondition::VOLUME_CONDITION_ANY;
}

