void Femas2UnitQuote::ExecuteInsertQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update(command));
  auto field = std::make_shared<CUstpFtdcInputQuoteField>();
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  femas2::ConvertToFemas2ExchangeID(req->exchange_id, &field->ExchangeID);
  strcpy_x(field->InstrumentID, req->instrument_id);

  // 从command_id中解析出ask_ref和bid_ref
  std::string tmp = req->command_id;
  auto pos1 = tmp.find("_ask_ref_");
  auto pos2 = tmp.find("_bid_ref_");
  FCASSERT(pos1 != std::string::npos);
  FCASSERT(pos2 != std::string::npos);
  std::string ask_ref = tmp.substr(pos1 + 9, pos2 - pos1 - 9);
  std::string bid_ref = tmp.substr(pos2 + 9);

  strcpy_x(field->UserQuoteLocalID, req->quote_id);
  strcpy_x(field->AskUserOrderLocalID, ask_ref);
  strcpy_x(field->BidUserOrderLocalID, bid_ref);
  strcpy_x(field->ReqForQuoteID, req->response_quote_id);
  field->AskPrice = req->ask_price;
  field->BidPrice = req->bid_price;
  field->AskVolume = req->ask_volume;
  field->BidVolume = req->bid_volume;
  ConvertToFemas2OffsetFlag(req->ask_offset, &field->AskOffsetFlag);
  ConvertToFemas2OffsetFlag(req->bid_offset, &field->BidOffsetFlag);
  ConvertToFemas2HedgeFlag(req->ask_hedge_flag, &field->AskHedgeFlag);
  ConvertToFemas2HedgeFlag(req->bid_hedge_flag, &field->BidHedgeFlag);
  int request_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqQuoteInsert(field.get(), request_id);
  LogReq(m_logger, "ReqQuoteInsert", field.get(), request_id, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertQuote" + req->quote_id);
  req->result_code = ret;
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void Femas2UnitQuote::ReqCancelQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelQuote>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto quote_node = m_service->m_node_db->GetNode<future::Quote>(req->user_key + "|" + req->quote_id);
  if (!quote_node) {
    SetCommandFinished(req, 1, u8"报价指令不存在");
    return;
  }
  auto quote = quote_node->Latest();
  CUstpFtdcQuoteActionField quote_action_field;
  memset(&quote_action_field, 0, sizeof(quote_action_field));
  strcpy_x(quote_action_field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(quote_action_field.InvestorID, m_service->m_investor_id);
  strcpy_x(quote_action_field.UserID, m_service->m_req_login->user_id);
  strcpy_x(quote_action_field.ExchangeID, quote->ExchangeID());
  quote_action_field.ActionFlag = USTP_FTDC_AF_Delete;
  strcpy_x(quote_action_field.UserQuoteLocalID, quote->quote_id);
  strcpy_x(quote_action_field.UserQuoteActionLocalID, req->cancel_id);
  strcpy_x(quote_action_field.QuoteSysID, m_quote_sysids[quote->GetKey()]);
  int request_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqQuoteAction(&quote_action_field, request_id);
  LogReq(m_logger, "ReqQuoteAction", &quote_action_field, request_id, ret);
  // 撤销报价时需要撤销衍生报单
  {
    CUstpFtdcOrderActionField order_action_field;
    memset(&order_action_field, 0, sizeof(order_action_field));
    strcpy_x(order_action_field.BrokerID, quote_action_field.BrokerID);
    strcpy_x(order_action_field.UserID, quote_action_field.UserID);
    strcpy_x(order_action_field.InvestorID, m_service->m_investor_id);
    strcpy_x(order_action_field.ExchangeID, quote_action_field.ExchangeID);
    order_action_field.ActionFlag = USTP_FTDC_AF_Delete;
    order_action_field.LimitPrice = 0;
    order_action_field.VolumeChange = 0;
    strcpy_x(order_action_field.UserOrderLocalID, quote->ask_order_id);
    strcpy_x(order_action_field.OrderSysID, m_order_sysids[quote->GetKey()].first);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
    strcpy_x(order_action_field.UserOrderLocalID, quote->bid_order_id);
    strcpy_x(order_action_field.OrderSysID, m_order_sysids[quote->GetKey()].second);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
  }
  m_service->m_command_manager->SetCommandId(command, "ReqCancelQuote" + req->quote_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void Femas2UnitQuote::OnRspQuoteInsert(std::shared_ptr<SpiMessage> msg) {
  auto input_quote = std::static_pointer_cast<CUstpFtdcInputQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(input_quote->UserQuoteLocalID, input_quote->QuoteLocalID);
  if (quote_id.empty()) {
    FCASSERT(false);
    return;
  }
  if (msg->RspInfo.ErrorID != 0) {
    auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void Femas2UnitQuote::OnRspQuoteAction(std::shared_ptr<SpiMessage> msg) {
  auto cancel_quote = std::static_pointer_cast<CUstpFtdcQuoteActionField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(cancel_quote->UserQuoteLocalID, "");
  if (quote_id.empty()) {
    FCASSERT(false);
    return;
  }
  auto req = m_service->m_command_manager->Update("ReqCancelQuote" + quote_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void Femas2UnitQuote::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  auto quote = std::static_pointer_cast<CUstpFtdcRtnQuoteField>(msg->pMainField);
  if (!quote)
    return;
  auto quote_id = ToFclibOrderId(quote->UserQuoteLocalID, quote->QuoteLocalID);
  if (quote_id.empty()) {
    FCASSERT(false);
    return;
  }
  auto investor_id = std::string(quote->InvestorID);
  auto user_id = std::string(quote->UserID);
  if (user_id.empty())
    user_id = investor_id;
  auto quote_key = m_service->m_user_key + "|" + quote_id;
  auto quote_node = m_service->m_node_db->ReplaceRecord<Quote>(quote_key, [=](std::shared_ptr<Quote> target_quote) {
    target_quote->user_key = m_service->m_user_key;
    target_quote->investor_id = investor_id;
    target_quote->user_id = user_id;
    target_quote->instrument_id = quote->InstrumentID;
    target_quote->exchange_id = ConvertFromFemas2ExchangeID(&quote->ExchangeID);
    target_quote->response_quote_id = quote->ReqForQuoteID;
    target_quote->ask_price = quote->AskPrice;
    target_quote->bid_price = quote->BidPrice;
    target_quote->ask_volume = quote->AskVolume;
    target_quote->bid_volume = quote->BidVolume;
    target_quote->ask_offset = ConvertFromFemas2Offset(&quote->AskOffsetFlag);
    target_quote->bid_offset = ConvertFromFemas2Offset(&quote->BidOffsetFlag);
    target_quote->ask_hedge_flag = ConvertFromFemas2HedgeFlag(&quote->AskHedgeFlag);
    target_quote->bid_hedge_flag = ConvertFromFemas2HedgeFlag(&quote->BidHedgeFlag);
    target_quote->status = ConvertFromFemas2QuoteStatus(&quote->QuoteStatus);
    target_quote->exchange_quote_id = quote->QuoteSysID;
    target_quote->ask_order_id = ToFclibOrderId(quote->AskUserOrderLocalID, quote->AskOrderLocalID);
    target_quote->bid_order_id = ToFclibOrderId(quote->BidUserOrderLocalID, quote->BidOrderLocalID);
    if (target_quote->quote_id.empty())
      target_quote->quote_id = quote_id;
  });
  m_quote_sysids[quote_key] = quote->QuoteSysID;
  m_order_sysids[quote_key].first = quote->AskOrderSysID;
  m_order_sysids[quote_key].second = quote->BidOrderSysID;
  auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
  if (req) {
    std::static_pointer_cast<InsertQuote>(req)->quote_id = quote_id;
    std::static_pointer_cast<InsertQuote>(req)->quote_pointer = quote_node;
    if (!quote_node->Latest()->exchange_quote_id.empty()) {
      SetCommandFinished(req, 0, u8"成功");
    }
  }
}

void Femas2UnitQuote::ReqForQuoteInsert(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertForQuote>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  CUstpFtdcReqForQuoteField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.InstrumentID, req->instrument_id);
  femas2::ConvertToFemas2ExchangeID(req->exchange_id, &field.ExchangeID);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  int request_id = m_service->GenerateRequestID();
  strcpy_x(field.ReqForQuoteID, std::to_string(request_id));
  int ret = m_service->m_api->ReqForQuote(&field, request_id);
  LogReq(m_logger, "ReqForQuote", &field, request_id, ret);
  m_service->SetReqResponse(command, request_id, ret);
}

void Femas2UnitQuote::OnRspForQuoteInsert(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
