void Femas2ServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  m_command_manager->Store(command);
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: Femas2柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
  // assert(false);
  return;
}

const std::vector<std::shared_ptr<UserCommand>>& Femas2ServiceImpl::SendBackCommand() const {
  return m_send_back_commands;
}

int Femas2ServiceImpl::RunOnce() {
  m_femas2_query_planner.RunOnce();
  std::shared_ptr<SpiMessage> msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    ProcessSpiMsg(msg);
    msg_count++;
  }
  for (auto& f : m_func_units)
    msg_count += f->RunOnce();
  if (msg_count == 0) {  // 当截面稳定,检查是否需要发送组合请求
    if (m_options.position_comb_auto) {
      m_send_back_commands.clear();
      m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
        comb_insert->status = UserCommand::Status::kStarted;
        comb_insert->insert_id.clear();
        m_send_back_commands.push_back(comb_insert);
      });
    }
  }
  if (m_req_login && !m_req_login->replay_flow_file_name.empty() && m_recv_queue.empty()) {
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
      login->user_key = m_user_key;
      login->status_msg = "log replay finished";
    });
  }

  return msg_count;
}

