};

int Femas2ServiceImpl::BuildApi(bool subscribe_topic) {
  if (!m_req_login)
    return 0;
  DeleteApi();
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_femas2_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = Femas2ServiceImpl::UstpApiCreator(m_flow_dir.c_str());
  m_spi = new Femas2SpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(USTP_TERT_RESUME);
    m_api->SubscribePublicTopic(USTP_TERT_RESUME);
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    m_api->Init();
  }

  return 0;
}

void Femas2ServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
    m_trading_day = "";
  }
  m_api->Release();
  m_api = nullptr;
}

void Femas2ServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;

  m_femas2_query_planner.ProcessSpiMsg(spi_msg);
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

void Femas2ServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_cmd_processor[tag] = processor;
}

void Femas2ServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

int Femas2ServiceImpl::GenerateRequestID() {
  return request_id++;
}

void Femas2ServiceImpl::SetReqResponse(
  std::shared_ptr<UserCommand> c, int request_id, int result_code, const std::string& error_msg) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  if (!error_msg.empty()) {
    command->result_msg = error_msg;
  }
  m_command_manager->SetCommandId(command, std::to_string(request_id));
}

