//  对比两个PositionDetail全字段是否相等
bool CompareDetail(const std::shared_ptr<fclib::future::PositionDetail> snap_detail,
  const std::shared_ptr<fclib::future::PositionDetail> prev_detail) {
  if (snap_detail == nullptr && prev_detail == nullptr)
    return true;
  if (!snap_detail || !prev_detail) {
    return false;
  }
  if (snap_detail->open_date_time != prev_detail->open_date_time)
    return false;
  if (std::fabs(snap_detail->open_price - prev_detail->open_price) > 1e-5)
    return false;
  if (snap_detail->open_trading_day != prev_detail->open_trading_day)
    return false;
  if (snap_detail->volume != prev_detail->volume)
    return false;
  if (snap_detail->open_exchange_order_id != prev_detail->open_exchange_order_id)
    return false;
  if (snap_detail->open_exchange_trade_id != prev_detail->open_exchange_trade_id)
    return false;
  return true;
}

// 对比两个Position全字段是否相等
bool CompareEqual(
  std::shared_ptr<const fclib::future::Position> snap, std::shared_ptr<const fclib::future::Position> prev) {
  if (snap == nullptr && prev == nullptr)
    return true;
  if (snap == nullptr || prev == nullptr)
    return false;

  if (std::abs(snap->last_price - prev->last_price) > 1e-5)
    return false;
  if (snap->risk_position != prev->risk_position)
    return false;
  for (auto p : {
         &Position::subpos_long_spec,
         &Position::subpos_short_spec,
         &Position::subpos_long_other,
         &Position::subpos_short_other,
       }) {
    auto sub_snap = &(*snap.*p);
    auto sub_prev = &(*prev.*p);
    if (std::fabs(sub_snap->margin - sub_prev->margin) > 1e-5)
      return false;
    if (std::fabs(sub_snap->commission - sub_prev->commission) > 1e-5)
      return false;
    if (std::fabs(sub_snap->premium - sub_prev->premium) > 1e-5)
      return false;
    if (std::fabs(sub_snap->close_profit - sub_prev->close_profit) > 1e-5)
      return false;
    if (std::fabs(sub_snap->close_profit_by_open - sub_prev->close_profit_by_open) > 1e-5)
      return false;
    if (std::fabs(sub_snap->float_profit - sub_prev->float_profit) > 1e-5)
      return false;
    if (std::fabs(sub_snap->market_value - sub_prev->market_value) > 1e-5)
      return false;
    if (std::fabs(sub_snap->market_value_yesterday - sub_prev->market_value_yesterday) > 1e-5)
      return false;
    if (std::fabs(sub_snap->open_price - sub_prev->open_price) > 1e-5)
      return false;
    if (std::fabs(sub_snap->position_price - sub_prev->position_price) > 1e-5)
      return false;
    if (std::fabs(sub_snap->position_profit - sub_prev->position_profit) > 1e-5)
      return false;
    if (sub_snap->strike_frozen != sub_prev->strike_frozen)
      return false;
    if (sub_snap->strike_his_frozen != sub_prev->strike_his_frozen)
      return false;
    if (std::fabs(sub_snap->untrade_profit - sub_prev->untrade_profit) > 1e-5)
      return false;
    if (sub_snap->volume_comb != sub_prev->volume_comb)
      return false;
    if (sub_snap->volume_his != sub_prev->volume_his)
      return false;
    if (sub_snap->volume_his_frozen != sub_prev->volume_his_frozen)
      return false;
    if (sub_snap->volume_today != sub_prev->volume_today)
      return false;
    if (sub_snap->volume_today_frozen != sub_prev->volume_today_frozen)
      return false;
    if (sub_snap->volume_yesterday != sub_prev->volume_yesterday)
      return false;
    if (sub_snap->his_position_details.size() != sub_prev->his_position_details.size())
      return false;
    if (sub_snap->today_position_details.size() != sub_prev->today_position_details.size())
      return false;

    auto const sub_snap_his_front =
      sub_snap->his_position_details.empty() ? nullptr : sub_snap->his_position_details.front();
    auto const sub_prev_his_front =
      sub_prev->his_position_details.empty() ? nullptr : sub_prev->his_position_details.front();
    if (!CompareDetail(sub_snap_his_front, sub_prev_his_front))
      return false;

    auto const sub_snap_his_back =
      sub_snap->his_position_details.empty() ? nullptr : sub_snap->his_position_details.back();
    auto const sub_prev_his_back =
      sub_prev->his_position_details.empty() ? nullptr : sub_prev->his_position_details.back();

    if (!CompareDetail(sub_snap_his_back, sub_prev_his_back))
      return false;

    auto const sub_snap_today_front =
      sub_snap->today_position_details.empty() ? nullptr : sub_snap->today_position_details.front();
    auto const sub_prev_today_front =
      sub_prev->today_position_details.empty() ? nullptr : sub_prev->today_position_details.front();

    if (!CompareDetail(sub_snap_today_front, sub_prev_today_front))
      return false;

    auto const sub_snap_today_back =
      sub_snap->today_position_details.empty() ? nullptr : sub_snap->today_position_details.back();
    auto const sub_prev_today_back =
      sub_prev->today_position_details.empty() ? nullptr : sub_prev->today_position_details.back();

    if (!CompareDetail(sub_snap_today_back, sub_prev_today_back))
      return false;
  }
  return true;
}

Femas2UnitPositionAccountView::Femas2UnitPositionAccountView(
  Femas2ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_femas2_query_planner;
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryInvestorPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryInvestorPosition(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInvestorCombPosition, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInvestorCombPosition(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingAccount(msg);
  });
  //  /** trade和order可能重复，这个没有考虑 */
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnMarginCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnMarginCombAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspMarginCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspMarginCombAction(msg);
  });
  m_service->RegisterCommandProcessor(PositionCombAuto::AID, [this](std::shared_ptr<UserCommand> command) {
    auto req = std::static_pointer_cast<PositionCombAuto>(command);
    m_service->m_options.position_comb_auto = req->auto_combi;
    SetCommandFinished(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
    ReqQryTradingAccount(false);
  });

  m_service->RegisterCommandProcessor(QueryInvestorPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
    RequireQryPosition(false);
  });

  m_service->RegisterCommandProcessor(QueryInvestorCombPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
    ReqQryInvestorCombPosition(false);
  });

  m_service->RegisterCommandProcessor(PositionCombInsert::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqMarginCombAction(command);
  });

  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryUserInvestor, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryUserInvestor(msg);
  });
  // 转账后查询更新账户信息
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRtnFromFutureToBankByFuture, [this](std::shared_ptr<SpiMessage> msg) {
      ReqQryTradingAccount(true);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRtnFromBankToFutureByFuture, [this](std::shared_ptr<SpiMessage> msg) {
      ReqQryTradingAccount(true);
    });

  m_position_view = m_service->m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_service->m_user_key && pos->unit_id == 0;
  });

  m_timer = std::make_shared<boost::asio::deadline_timer>(*m_service->m_ioc);
  m_timer->expires_from_now(boost::posix_time::seconds(2));
  m_timer->async_wait([this](const boost::system::error_code& error) {
    if (!error) {
      RefreshPositionProfit();
    } else {
      auto lg = structlog::Logger::Root();
      lg.With("error", error.message()).Error("timer error");
#ifndef TQ_TEST
      watchdog::WatchDog::SendMsg(
        "position_account_view: time error " + error.message(), watchdog::MessageLevel::kError);
#endif
    }
  });
}

void Femas2UnitPositionAccountView::OnRspQryInvestorPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto position = std::static_pointer_cast<CUstpFtdcRspInvestorPositionField>(msg->pMainField);
    m_qry_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryPositionResults();
    m_qry_position_results.clear();
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_service->m_user_key;
        p->backend = BackEnd::kFemas2;
        p->position_ready = true;
      });
  }
}

void Femas2UnitPositionAccountView::OnRspQryTradingAccount(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto account = std::static_pointer_cast<CUstpFtdcRspInvestorAccountField>(msg->pMainField);
    m_qry_account_results.push_back(account);
  }
  if (msg->bIsLast) {
    ProcessQryAccountResults();
    m_qry_account_results.clear();
    if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
      SetCommandFinished(req);
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_service->m_user_key;
        p->backend = BackEnd::kFemas2;
        p->account_ready = true;
      });
  }
}

void Femas2UnitPositionAccountView::UpdatePositionProfit(
  std::shared_ptr<Position> position, const std::optional<shm::ShmInstrument>& ins) {
  FCASSERT(ins.has_value());
  if (ins->CheckQuote(m_service->m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  // 无法获得最新价, 取查询返回值
  if (std::isnan(position->last_price) || IsZero(position->last_price)) {
    return;
  }
  // 可以计算
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption)
        subpos->position_profit = subpos->market_value - subpos->_position_cost - subpos->_position_cost_his;
      if (!IsZero(subpos->open_price))
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
      if (subpos->volume_yesterday > 0 && position->last_price != ins->pre_settlement) {
        subpos->untrade_profit = (position->last_price - ins->pre_settlement) * subpos->volume_yesterday
          * ins->volume_multiple * (subpos->direction == Direction::kBuy ? 1 : -1);
      } else {
        subpos->untrade_profit = 0.0;
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

void Femas2UnitPositionAccountView::ProcessQryAccountResults() {
  for (auto account : m_qry_account_results) {
    auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
    m_service->m_node_db->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> target_account) {
      target_account->user_key = m_service->m_user_key;
      target_account->investor_id = account->InvestorID;
      target_account->available = account->Available;
      target_account->close_profit = account->CloseProfit;
      target_account->commission = account->Fee;
      target_account->currency = "CNY";
      target_account->deposit = account->Deposit;
      target_account->frozen_commission = account->FrozenFee;
      target_account->frozen_margin = account->FrozenMargin;
      target_account->margin = account->Margin;
      target_account->position_profit = account->PositionProfit;
      target_account->pre_balance = account->PreBalance;
      target_account->withdraw = account->Withdraw;

      target_account->premium = account->Premium;
      target_account->frozen_premium = account->FrozenPremium;

      target_account->client_equity = account->PreBalance + account->Deposit - account->Withdraw + account->CloseProfit
        + account->PositionProfit - account->Fee + account->Premium;

      target_account->balance = target_account->client_equity + target_account->option_market_value;

      if (target_account->client_equity > 0) {
        target_account->risk_ratio = target_account->margin / target_account->client_equity;
      } else {
        target_account->risk_ratio = target_account->margin > 0 ? 1.0 : 0.0;
      }
      if (target_account->balance > 0) {
        target_account->ref_risk_ratio = target_account->margin / target_account->balance;
      } else {
        target_account->ref_risk_ratio = target_account->margin > 0 ? 1.0 : 0.0;
      }
    });
  }
}

void Femas2UnitPositionAccountView::ProcessQryPositionResults() {
  for (auto origin_position : m_qry_position_results) {
    if (origin_position->InstrumentID[0] == '\0') {
      continue;
    }

    std::string position_symbol = femas2::ConvertFromFemas2ExchangeID(&origin_position->ExchangeID) + "."
      + std::string(origin_position->InstrumentID);
    bool is_combine = position_symbol.find('&') != std::string::npos;
    auto ins = m_service->m_md_helper->GetShmInstrument(position_symbol, true);
    FCASSERT(ins.has_value());
    auto position_key = m_service->m_user_key + "|0|" + position_symbol;
    // 暂存变动前的node
    auto node = m_service->m_node_db->GetNode<Position>(position_key);
    auto prev = node ? node->Latest() : nullptr;

    auto target_position = m_service->m_node_db->CreateRecord<Position>(position_key);
    target_position->user_key = m_service->m_user_key;
    target_position->investor_id = origin_position->InvestorID;
    target_position->exchange_id = femas2::ConvertFromFemas2ExchangeID(&origin_position->ExchangeID);
    target_position->instrument_id = origin_position->InstrumentID;

    future::SubPosition* subpos =
      GetSubPosition(target_position, origin_position->Direction, origin_position->HedgeFlag);
    if (origin_position->HedgeFlag == USTP_FTDC_CHF_Arbitrage) {
      subpos->hedge_type = PositionHedgeType::kArbitrage;
    }
    // 暂时考虑只用Position刷新
    subpos->volume_his = origin_position->YdPosition;
    subpos->volume_his_frozen = origin_position->YdFrozenClosing;
    subpos->volume_today = origin_position->Position - origin_position->YdPosition;
    subpos->volume_today_frozen = origin_position->FrozenClosing;
    subpos->_position_cost = origin_position->PositionCost - origin_position->YdPositionCost;
    subpos->_open_cost = origin_position->PositionCost;
    subpos->_margin = origin_position->UsedMargin;
    subpos->_position_cost_his = origin_position->YdPositionCost;
    subpos->_margin_his = 0.0;
    subpos->margin = subpos->_margin + subpos->_margin_his;
    subpos->volume_comb = origin_position->ArbitragePosition + origin_position->HedgePosition;
    double price = ins->last_price;
    if (std::isnan(price)) {
      price = ins->pre_settlement;
    }
    if (!isnan(price)) {
      subpos->market_value = price * ins->volume_multiple * subpos->Volume();
    }
    if (subpos->direction == Direction::kSell && ins->product_class == md::ProductClass::kOption) {
      subpos->market_value *= -1;
    }
    if (subpos->Volume() > 0 && ins.has_value() && (ins->volume_multiple - 0.0) > 1e-5) {
      subpos->open_price = (subpos->_open_cost + subpos->_open_cost_his) / subpos->Volume() / ins->volume_multiple;
      subpos->position_price =
        (subpos->_position_cost + subpos->_position_cost_his) / subpos->Volume() / ins->volume_multiple;
    } else {
      subpos->open_price = 0;
      subpos->position_price = 0;
    }
    UpdatePositionProfit(target_position, ins);
    // 变动前后不一样才进行ReplaceRecord
    if (!CompareEqual(target_position, prev)) {
      m_service->m_node_db->ReplaceRecord<Position>(target_position);
    }
  }
}

