void Femas2UnitPositionAccountView::OnRspQryInvestorCombPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto position = std::static_pointer_cast<CUstpFtdcRspInvestorCombPositionField>(msg->pMainField);
    m_qry_comb_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryCombPositionResults();
    m_qry_comb_position_results.clear();
