void Femas2UnitPositionAccountView::ProcessQryCombPositionResults() {
  for (auto origin_comb_position : m_qry_comb_position_results) {
    std::string position_symbol = femas2::ConvertFromFemas2ExchangeID(&origin_comb_position->ExchangeID) + "."
      + std::string(origin_comb_position->CombInstrumentID);
    auto position_key = m_service->m_user_key + "|0|" + position_symbol;
    // 暂存变动前的node
    auto node = m_service->m_node_db->GetNode<Position>(position_key);
    auto prev = node ? node->Latest() : nullptr;

    auto target_position = m_service->m_node_db->CreateRecord<Position>(position_key);
    target_position->user_key = m_service->m_user_key;
    target_position->investor_id = origin_comb_position->InvestorID;
    target_position->exchange_id = femas2::ConvertFromFemas2ExchangeID(&origin_comb_position->ExchangeID);
    target_position->instrument_id = origin_comb_position->CombInstrumentID;

    auto last_price =
      m_service->m_md_helper->GetShmInstrumentField(target_position->Symbol(), &shm::ShmInstrument::last_price, true);
    if (last_price.has_value())
      target_position->last_price = last_price.value();

    future::SubPosition* subpos =
      GetSubPosition(target_position, origin_comb_position->Direction, origin_comb_position->HedgeFlag);
    if (origin_comb_position->HedgeFlag == USTP_FTDC_CHF_Arbitrage) {
      subpos->hedge_type = PositionHedgeType::kArbitrage;
    }
    subpos->volume_today = origin_comb_position->CombPosition;
    subpos->volume_today_frozen = origin_comb_position->CombFrozenPosition;
    subpos->position_profit = NAN;
    subpos->float_profit = NAN;
    subpos->open_price = 0;
    subpos->position_price = 0;

    // 变动前后不一样才进行ReplaceRecord
    if (!CompareEqual(target_position, prev)) {
      m_service->m_node_db->ReplaceRecord<Position>(target_position);
    }
  }
}

void Femas2UnitPositionAccountView::ReqQryTradingAccount(bool is_critical) {
  if (m_query_planner->AlreadyInQueue("ReqQryInvestorAccount"))
    return;
  auto field = std::make_shared<CUstpFtdcQryInvestorAccountField>();
  memset(field.get(), 0, sizeof(CUstpFtdcQryInvestorAccountField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);

  int request_id = m_service->GenerateRequestID();

  m_query_planner->AddTask(
