void Femas2UnitPositionAccountView::ReqMarginCombAction(std::shared_ptr<UserCommand> command) {
  auto comb_command = std::static_pointer_cast<PositionCombInsert>(m_service->m_command_manager->Update(command));
  CUstpFtdcInputMarginCombActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.CombInstrumentID, comb_command->instrument_id);
  strcpy_x(field.UserActionLocalID, comb_command->insert_id);
  femas2::ConvertToFemas2ExchangeID(comb_command->exchange_id, &field.ExchangeID);
  ConvertToFemas2Direction(comb_command->direction, &field.Direction);
  field.CombVolume = comb_command->volume;
  if (comb_command->comb_direction == CombDirection::kComb)
    field.CombDirection = USTP_FTDC_CA_Combine;
  else
    field.CombDirection = USTP_FTDC_CA_UnCombine;
  ConvertToFemas2HedgeFlag(comb_command->hedge_flag, &field.HedgeFlag);
  int req_id = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqMarginCombAction(&field, req_id);
  LogReq(m_logger, "ReqMarginCombAction", &field, req_id, ret);
  m_service->m_command_manager->SetCommandId(
    command, "ReqDcePositionCombInsert" + std::string(field.UserActionLocalID));
  if (ret != 0) {
    SetCommandFinished(comb_command, ret, u8"指令发送失败");
  }
}

void Femas2UnitPositionAccountView::OnRtnMarginCombAction(std::shared_ptr<SpiMessage> msg) {
  auto comb_action = std::static_pointer_cast<CUstpFtdcInputMarginCombActionField>(msg->pMainField);
  auto req =
    m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action->UserActionLocalID));

  if (comb_action->CombActionStatus == USTP_FTDC_CAS_Rejected) {
    SetCommandFinished(req, -1, u8"组合申请被拒绝");
    return;
  }
  if (comb_action->CombActionStatus == USTP_FTDC_CAS_Accepted) {
    SetCommandFinished(req);
  }
}

void Femas2UnitPositionAccountView::OnRspMarginCombAction(std::shared_ptr<SpiMessage> msg) {
  auto comb_action_field = std::static_pointer_cast<CUstpFtdcInputMarginCombActionField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update(
    "ReqDcePositionCombInsert" + std::string(comb_action_field->UserActionLocalID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

