#ifndef FCLIB_FEMAS2_QUERY_PLANNER_H
#define FCLIB_FEMAS2_QUERY_PLANNER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

