Femas2UnitOrderTradeView::Femas2UnitOrderTradeView(Femas2ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_trade_view_unit", reinterpret_cast<int64_t>(this)).Clone())
  , m_index(0) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
}

void Femas2UnitOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CUstpFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->UserOrderLocalID, origin->OrderLocalID);
  if (order_id.empty()) {
    FCASSERT(false);
    return;
  }

  auto order_key = m_service->m_user_key + "|" + order_id;
  auto order_node = m_service->m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (m_order_set.find(order_id) == m_order_set.end()) {
      if (m_service->m_session_id == order->session_id) {
        auto iter = m_service->m_send_time.find(order_id);
        if (iter != m_service->m_send_time.end()) {
          order->send_date_time = iter->second;
          m_service->m_send_time.erase(iter);
        }
        order->receive_date_time = NowAsEpochNano();
      }
      m_order_set.insert(order_id);
    }
    order->index = ++m_index;
    order->exchange_id = femas2::ConvertFromFemas2ExchangeID(&origin->ExchangeID);
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->InvestorID;
    order->user_id = origin->UserID;
    order->direction = femas2::ConvertFromFemas2Direction(&origin->Direction);
    order->exchange_order_id = origin->OrderSysID;
    order->limit_price = origin->LimitPrice;
    order->offset = femas2::ConvertFromFemas2Offset(&origin->OffsetFlag);
    order->hedge_flag = femas2::ConvertFromFemas2HedgeFlag(&origin->HedgeFlag);
    order->price_type = femas2::ConvertFromFemas2OrderPriceType(&origin->OrderPriceType);

    order->status = femas2::ConvertFromFemas2OrderStatus(&origin->OrderStatus);
    order->time_condition = femas2::ConvertFromFemas2TimeCondition(&origin->TimeCondition);
    order->volume_condition = femas2::ConvertFromFemas2VolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = femas2::ConvertFromFemas2ForceCloseReason(&origin->ForceCloseReason);
    order->volume_left = origin->VolumeRemain;
    order->volume_orign = origin->Volume;
    std::string custom = origin->UserCustom;
    auto pos = custom.find("_fclib_");
    if (pos != std::string::npos) {
      order->request_id = custom.substr(0, pos);
      order->order_ref = custom.substr(pos + 7);
    }
    if (origin->InsertTime[0] != '\0') {
      order->insert_date_time = GetRealTradeTime(m_service->m_trading_day.c_str(), origin->InsertTime);
    }
    if (origin->CancelTime[0] != '\0') {
      order->dead_date_time = GetRealTradeTime(m_service->m_trading_day.c_str(), origin->CancelTime);
    }
    order->order_id = order_id;
    order->unit_id = std::atoll(origin->UserOrderLocalID) % 100;
    order->user_key = m_service->m_user_key;
    if (origin->BusinessLocalID != -1) {
      order->index = origin->BusinessLocalID;
    }
    order->session_id = m_service->m_session_id;
    order->min_volume = origin->MinVolume;
  });
  auto map_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  m_trade_order_map[map_key] = order_id;
  if (origin->VolumeTraded > 0) {
    ProcessCachedTrade(order_node);
  }
}

void Femas2UnitOrderTradeView::ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node) {
  const std::string& cache_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  auto it = m_trade_cache.find(cache_key);
  if (it == m_trade_cache.end())
    return;
  auto& trades = it->second;
  for (auto& trade : trades) {
    ProcessTrade(trade, order_node->Latest()->order_id);
  }
  m_trade_cache.erase(it);
}

int Femas2UnitOrderTradeView::RunOnce() {
  return 0;
}

void Femas2UnitOrderTradeView::ProcessTrade(std::shared_ptr<CUstpFtdcTradeField> origin, const std::string& order_id) {
  auto trade_key = future::TradeBase::MakeKey(m_service->m_user_key, origin->TradeID, origin->OrderSysID);
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->index = ++m_index;
    trade->investor_id = origin->InvestorID;
    trade->user_id = origin->UserID;
    if (origin->TradingDay[0] != '\0' && origin->TradeTime[0] != '\0') {
      trade->trade_date_time = GetRealTradeTime(origin->TradingDay, origin->TradeTime);
    }
    trade->direction = femas2::ConvertFromFemas2Direction(&origin->Direction);

    trade->exchange_id = femas2::ConvertFromFemas2ExchangeID(&origin->ExchangeID);
    trade->instrument_id = origin->InstrumentID;
    trade->exchange_trade_id = origin->TradeID;
    trade->offset = femas2::ConvertFromFemas2Offset(&origin->OffsetFlag);
    trade->exchange_order_id = origin->OrderSysID;
    //  trade->order_local_id = origin->UserOrderLocalID;
    trade->price = origin->TradePrice;
    trade->volume = origin->TradeVolume;
    trade->commission = origin->UsedFee;
    trade->hedge_flag = ConvertFromFemas2HedgeFlag(&origin->HedgeFlag);
    trade->user_key = m_service->m_user_key;

    auto ins = m_service->m_md_helper->GetShmInstrument(trade->Symbol(), true);
    FCASSERT(ins.has_value());
    trade->order_id = order_id;
  });
}

void Femas2UnitOrderTradeView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CUstpFtdcTradeField>(msg->pMainField);
  auto order_id = GetMatchOrder(origin);
  if (order_id.empty()) {
    AddTradeToCache(origin);
    return;
  }
  ProcessTrade(origin, order_id);
}

std::string Femas2UnitOrderTradeView::GetMatchOrder(std::shared_ptr<CUstpFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  auto it = m_trade_order_map.find(map_key);
  if (it == m_trade_order_map.end())
    return "";
  return it->second;
}

void Femas2UnitOrderTradeView::AddTradeToCache(std::shared_ptr<CUstpFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + femas2::ConvertFromFemas2ExchangeID(&origin->ExchangeID);
  m_trade_cache[map_key].insert(origin);
}

