template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, const T* plain_src = nullptr,
  CUstpFtdcRspInfoField* rsp_info = nullptr, int req_id = 0, bool is_last = true) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  if (rsp_info) {
    memcpy(&msg->RspInfo, rsp_info, sizeof(CUstpFtdcRspInfoField));
  }
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

Femas2SpiHandler::Femas2SpiHandler(
  boost::asio::io_context* ioc, structlog::Logger& parent_logger, Femas2ServiceImpl* service)
  : m_logger(parent_logger.Clone())
  , m_service(service)
  , m_strand(*ioc) {}

Femas2SpiHandler::~Femas2SpiHandler() {}

void Femas2SpiHandler::OnFrontConnected() {
  m_logger.Info("OnFrontConnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontConnected;
  PushSpiMessage(msg);
}

void Femas2SpiHandler::OnFrontDisconnected(int nReason) {
  m_logger.With("nReason", nReason).Info("OnFrontDisconnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontDisconnected;
  msg->RspInfo.ErrorID = nReason;
  PushSpiMessage(msg);
}

void Femas2SpiHandler::OnRspDSUserCertification(
  CUstpFtdcDSUserCertRspDataField* pDSUserCertRspData, CUstpFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  LogRtn(m_logger, "OnRspDSUserCertification", pDSUserCertRspData, pRspInfo, nRequestID, bIsLast);
  PushSpiMessage(MakeSpiMsg<CUstpFtdcDSUserCertRspDataField>(
    SpiMessage::Tag::OnRspAuthenticate, pDSUserCertRspData, pRspInfo, nRequestID, bIsLast));
}

void Femas2SpiHandler::OnRspError(CUstpFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  if (pRspInfo) {
    m_logger.With("request_id", nRequestID)
      .With("is_last", bIsLast)
      .With("ErrorID", pRspInfo->ErrorID)
      .With("ErrorMsg", GbkToUtf8(pRspInfo->ErrorMsg))
      .Warning("OnRspError");
  }
}

