void Femas2SpiHandler::OnRtnOrder(CUstpFtdcOrderField* pOrder) {
  LogRtn(m_logger, "OnRtnOrder", pOrder);
  // todo: 这里push时如果遇到缓冲区满，应反复重试直至填入成功
  PushSpiMessage(MakeSpiMsg<CUstpFtdcOrderField>(SpiMessage::Tag::OnRtnOrder, pOrder));
}

void Femas2SpiHandler::OnRtnTrade(CUstpFtdcTradeField* pTrade) {
  LogRtn(m_logger, "OnRtnTrade", pTrade);
  auto trade = MakeSpiMsg<CUstpFtdcTradeField>(SpiMessage::Tag::OnRtnTrade, pTrade);
  if (!m_rsp_position) {
    m_trades_cache.push(trade);
  } else {
    PushSpiMessage(trade);
  }
}

void Femas2SpiHandler::OnRspQryInvestorPosition(CUstpFtdcRspInvestorPositionField* pRspInvestorPosition,
  CUstpFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  LogRtn(m_logger, "OnRspQryInvestorPosition", pRspInvestorPosition, pRspInfo, nRequestID, bIsLast);
  auto spi_msg = MakeSpiMsg<CUstpFtdcRspInvestorPositionField>(
    SpiMessage::Tag::OnRspQryInvestorPosition, pRspInvestorPosition, pRspInfo, nRequestID, bIsLast);
  PushSpiMessage(spi_msg);
  if (!m_rsp_position && bIsLast) {
    m_rsp_position = true;
    while (!m_trades_cache.empty()) {
      PushSpiMessage(m_trades_cache.front());
      m_trades_cache.pop();
    }
  }
}

