void Femas2SpiHandler::StartStressTesting() {
  if (m_test_thread.joinable())
    return;
  m_test_thread = std::thread([&] {
    using namespace std::chrono_literals;
    for (int i = 0; i < 100; i++) {
      for (int j = 0; j < 10000; j++) {
        CUstpFtdcOrderField f;
        memset(&f, 0, sizeof(f));
        strcpy_x(f.ExchangeID, "SHFE");
        strcpy_x(f.InstrumentID, "cu2101");
        strcpy_x(f.InvestorID, "155862");
        strcpy_x(f.UserID, "155862");
        f.Direction = USTP_FTDC_D_Buy;
        strcpy_x(f.OrderSysID, std::to_string(i * 100000 + j).c_str());
        f.LimitPrice = 30000.0;
        f.OffsetFlag = USTP_FTDC_OF_Open;
        f.HedgeFlag = USTP_FTDC_CHF_Speculation;
        f.OrderPriceType = USTP_FTDC_OPT_LimitPrice;
        if (j > 8000) {
          f.OrderStatus = USTP_FTDC_OS_AllTraded;
        } else if (j > 6000) {
          f.OrderStatus = USTP_FTDC_OS_PartTradedQueueing;
        } else if (j > 4000) {
          f.OrderStatus = USTP_FTDC_OS_Canceled;
        } else {
          f.OrderStatus = USTP_FTDC_OS_NoTradeQueueing;
        }
        f.TimeCondition = USTP_FTDC_TC_GFD;
        f.VolumeCondition = USTP_FTDC_VC_AV;
        f.Volume = 5;
        f.VolumeRemain = 3;
        strcpy_x(f.UserOrderLocalID, std::to_string((i + 1) * 100000 + j).c_str());
        strcpy_x(f.OrderLocalID, std::to_string((i + 2) * 100000 + j).c_str());
        strcpy_x(f.ActionDay, "20200101");
        strcpy_x(f.InsertTime, "10:20:30");
        OnRtnOrder(&f);
      }
    }
  });
}

void Femas2SpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_service)
    return;
  auto queue = &m_service->m_recv_queue;
  m_strand.post([=]() {
    queue->push(msg);
  });
}

