Femas2UnitRate::Femas2UnitRate(Femas2ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_femas2_query_planner;
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryMargin(command);
  });
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryCommission(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentMarginRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentMarginRate(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentCommissionRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentCommissionRate(msg);
    });
}

void Femas2UnitRate::ReqQryMargin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  auto field = std::make_shared<CUstpFtdcQryInvestorMarginField>();
  memset(field.get(), 0, sizeof(CUstpFtdcQryInvestorMarginField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, req->instrument_id);
  femas2::ConvertToFemas2ExchangeID(req->exchange_id, &field->ExchangeID);

  auto qry = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  auto key = "ReqQryMargin" + qry->instrument_id + (qry->hedge_flag == OrderHedgeFlag::kSpeculation ? "S" : "H");
  int request_id = req->query_request_id > 0 ? req->query_request_id : m_service->GenerateRequestID();

  m_query_planner->AddTask(key, Femas2QueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInvestorMargin(field.get(), request_id);
    if (ret >= 0)
      LogReq(m_logger, "ReqQryMargin", field.get(), request_id, ret);
    m_service->SetReqResponse(command, request_id, ret);
    return ret;
  });
}

void Femas2UnitRate::OnRspQryInstrumentMarginRate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
  if (!msg->pMainField)
    return;

  auto margin_rate = std::static_pointer_cast<CUstpFtdcInvestorMarginField>(msg->pMainField);
  UpdateMargin(margin_rate);
}

void Femas2UnitRate::UpdateMargin(std::shared_ptr<CUstpFtdcInvestorMarginField> margin_rate) {
  auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = std::string(margin_rate->InstrumentID);
    rate_node->exchange_id = ConvertFromFemas2ExchangeID(&margin_rate->ExchangeID);
    if (margin_rate->HedgeFlag == USTP_FTDC_CHF_Speculation) {
      rate_node->margin_rate_long_spec = (UnitRate(margin_rate->LongMarginRate, margin_rate->LongMarginAmt));
      rate_node->margin_rate_short_spec = (UnitRate(margin_rate->ShortMarginRate, margin_rate->ShortMarginAmt));
      rate_node->margin_rate_long_other = (UnitRate(margin_rate->LongMarginRate, margin_rate->LongMarginAmt));
      rate_node->margin_rate_short_other = (UnitRate(margin_rate->ShortMarginRate, margin_rate->ShortMarginAmt));
    } else {
      rate_node->margin_rate_long_other = UnitRate(margin_rate->LongMarginRate, margin_rate->LongMarginAmt);
      rate_node->margin_rate_short_other = UnitRate(margin_rate->ShortMarginRate, margin_rate->ShortMarginAmt);
    }
  });
}

void Femas2UnitRate::ReqQryCommission(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryCommissionRate>(m_service->m_command_manager->Update(command));
  auto key = "ReqQryCommission" + qry->instrument_id;
  auto field = std::make_shared<CUstpFtdcQryInvestorFeeField>();
  memset(field.get(), 0, sizeof(CUstpFtdcQryInvestorFeeField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  femas2::ConvertToFemas2ExchangeID(qry->exchange_id, &field->ExchangeID);

  int request_id = qry->query_request_id > 0 ? qry->query_request_id : m_service->GenerateRequestID();

  m_query_planner->AddTask(key, Femas2QueryPlanner::Priority::kLow, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInvestorFee(field.get(), request_id);
    if (ret >= 0) {
      LogReq(m_logger, "ReqQryCommission", field.get(), request_id, ret);
      m_service->SetReqResponse(command, request_id, ret);
    }
    return ret;
  });
}

void Femas2UnitRate::OnRspQryInstrumentCommissionRate(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast)
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  if (!msg->pMainField)
    return;
  auto rate_field = std::static_pointer_cast<CUstpFtdcInvestorFeeField>(msg->pMainField);
  UpdateCommission(rate_field);
}

void Femas2UnitRate::UpdateCommission(std::shared_ptr<CUstpFtdcInvestorFeeField> commission) {
  auto rate_key = m_service->m_user_key + "|" + std::string(commission->InstrumentID);
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->commission_rate_open = (UnitRate(commission->OpenFeeRate, commission->OpenFeeAmt));
    rate_node->commission_rate_close = (UnitRate(commission->OffsetFeeRate, commission->OffsetFeeAmt));
    rate_node->commission_rate_close_today = (UnitRate(commission->OTFeeRate, commission->OTFeeAmt));

    auto product_class = m_service->m_md_helper->GetShmInstrumentField(
      std::string(commission->ExchangeID) + "." + std::string(commission->InstrumentID),
      &shm::ShmInstrument::product_class, true);
    if (product_class == md::ProductClass::kOption) {
      rate_node->commission_rate_exec = (UnitRate(commission->ExecFeeRate, commission->ExecFeeAmt));
    } else {
      rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
    }

    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = std::string(commission->InstrumentID);
  });
}

int Femas2UnitRate::RunOnce() {
  return 0;
}

