Femas2UnitInsertCancelOrder::Femas2UnitInsertCancelOrder(Femas2ServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderAction(msg);
  });
}

void Femas2UnitInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  if (!m_service->m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  // 下单
  auto field = std::make_shared<CUstpFtdcInputOrderField>();
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InvestorID, m_service->m_investor_id);
  ConvertToFemas2OrderField(req, field);
  std::string custom = std::to_string(req->request_id) + "_fclib_" + std::to_string(req->order_ref);
  strcpy_x(field->UserCustom, custom);
  strcpy_x(field->UserOrderLocalID, req->order_id);
  // 报单
  int ret = m_service->m_api->ReqOrderInsert(field.get(), 0);
  m_service->m_send_time[req->order_id] = NowAsEpochNano();
  LogReq(m_logger, "ReqOrderInsert", field.get(), m_service->GenerateRequestID(), ret);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOrder" + req->order_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void Femas2UnitInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  auto it = m_alive_orders.find(req->order_id);
  if (it == m_alive_orders.end()) {
    SetCommandFinished(req, -1, u8"报单编号不存在");
    return;
  }
  CUstpFtdcOrderField& order = it->second;
  CUstpFtdcOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id.c_str());
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.UserOrderLocalID, order.UserOrderLocalID);
  strcpy_x(field.ExchangeID, order.ExchangeID);
  strcpy_x(field.UserOrderActionLocalID, req->cancel_id);
  strcpy_x(field.OrderSysID, order.OrderSysID);
  field.ActionFlag = USTP_FTDC_AF_Delete;
  field.LimitPrice = 0;
  field.VolumeChange = 0;
  int ret = m_service->m_api->ReqOrderAction(&field, 0);
  LogReq(m_logger, "ReqOrderAction", &field, 0, ret);
  m_order_cancel[req->order_id] = req->cancel_id;
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + req->cancel_id);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void Femas2UnitInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto order = std::static_pointer_cast<CUstpFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(order->UserOrderLocalID, order->OrderLocalID);
  if (order_id.empty()) {
    FCASSERT(false);
    return;
  }
  // alive 委托单都放入 m_alive_orders, 以备撤单时使用.
  if (order->OrderStatus == USTP_FTDC_OS_Canceled || order->OrderStatus == USTP_FTDC_OS_AllTraded) {
    m_alive_orders.erase(order_id);
  } else {
    m_alive_orders[order_id] = *order;
  }

  // 反馈指令执行结果
  if (order->OrderStatus == USTP_FTDC_OS_Canceled) {
    auto it = m_order_cancel.find(order_id);
    if (it != m_order_cancel.end()) {
      auto req = m_service->m_command_manager->Update("ReqCancelOrder" + it->second);
      m_order_cancel.erase(it);
      if (req) {
        SetCommandFinished(req, 0, u8"成功");
        return;
      }
    }
  }
  if (order->OrderStatus != USTP_FTDC_OS_AcceptedNoReply) {
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    SetCommandFinished(req);
  }
}

void Femas2UnitInsertCancelOrder::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  auto pInputOrder = std::static_pointer_cast<CUstpFtdcInputOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pInputOrder->UserOrderLocalID, "");
  if (order_id.empty()) {
    FCASSERT(false);
    return;
  }
  auto origin = FtdcInputOrderFieldToOrderField(pInputOrder);
  auto order_key = m_service->m_user_key + "|" + order_id;

  if (msg->RspInfo.ErrorID != 0) {
    origin->OrderStatus = USTP_FTDC_OS_Canceled;
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);

    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }

  m_service->m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    order->user_key = m_service->m_user_key;
    order->order_id = order_id;
    order->user_id = origin->UserID;
    order->investor_id = origin->InvestorID;
    order->exchange_id = ConvertFromFemas2ExchangeID(&origin->ExchangeID);
    order->instrument_id = origin->InstrumentID;
    order->direction = femas2::ConvertFromFemas2Direction(&origin->Direction);
    order->offset = femas2::ConvertFromFemas2Offset(&origin->OffsetFlag);
    order->hedge_flag = femas2::ConvertFromFemas2HedgeFlag(&origin->HedgeFlag);
    order->price_type = femas2::ConvertFromFemas2OrderPriceType(&origin->OrderPriceType);
    order->status = femas2::ConvertFromFemas2OrderStatus(&origin->OrderStatus);
    order->time_condition = femas2::ConvertFromFemas2TimeCondition(&origin->TimeCondition);
    order->volume_condition = femas2::ConvertFromFemas2VolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = femas2::ConvertFromFemas2ForceCloseReason(&origin->ForceCloseReason);
    order->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
    order->session_id = m_service->m_session_id;
    order->limit_price = origin->LimitPrice;
    order->volume_orign = origin->Volume;
    order->volume_left = origin->VolumeRemain;
  });
}

void Femas2UnitInsertCancelOrder::OnRspOrderAction(std::shared_ptr<SpiMessage> msg) {
  auto pInputCancel = std::static_pointer_cast<CUstpFtdcOrderActionField>(msg->pMainField);
  auto cancel_id = ToFclibOrderId(pInputCancel->UserOrderActionLocalID, "");
  if (cancel_id.empty()) {
    FCASSERT(false);
    return;
  }
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + cancel_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

