bool Femas2QueryPlanner::AlreadyInQueue(const std::string& key) {
  auto it = m_task_map.find(key);
  if (it == m_task_map.end())
    return false;
  return true;
}

void Femas2QueryPlanner::AddTask(const std::string& key, Priority priority, int request_id,
  std::function<int(int)> query_func, int cooling_off, bool critical) {
  auto it = m_task_map.find(key);
  if (it != m_task_map.end()) {
    // 任务已在队列中, 更新冷静值.
    auto task = it->second;
    if (task->cooling_off > 0)
      task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    return;
  }
  std::shared_ptr<QueryTask> task = std::make_shared<QueryTask>(QueryTask({
    key,
    priority,
    query_func,
    request_id,
    critical,
    cooling_off,
  }));
  m_task_map[task->key] = task;
  if (task->cooling_off == 0) {
    m_task_queue.push_back(task);
    m_task_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->priority < b->priority;
    });
    RunOnce();
  } else {
    task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    m_cooling_queue.push_back(task);
    m_cooling_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->cooling_end_time < b->cooling_end_time;
    });
  }
}

void Femas2QueryPlanner::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (!m_running_task)
    return;
  if (spi_msg->nRequestID == m_running_task->request_id) {
    // 收到查询回包.
    if (spi_msg->bIsLast) {
      if (spi_msg->RspInfo.ErrorID == 0 || !m_running_task->critical)
        RemoveRunningTask();
      else
        m_running_task.reset();
    } else {
      m_query_timeout_timer.Reset(QUERY_TIMEOUT);
    }
  }
}

void Femas2QueryPlanner::RemoveRunningTask() {
  if (!m_running_task)
    return;
  m_task_map.erase(m_running_task->key);
  for (auto it = m_task_queue.begin(); it != m_task_queue.end(); ++it) {
    auto& t = *it;
    if (t == m_running_task) {
      m_task_queue.erase(it);
      break;
    }
  }
  m_running_task.reset();
}

void Femas2QueryPlanner::RunOnce() {
  if (!m_fail_wait_timer.IsExpired()) {
    return;
  }
  if (m_query_timeout_timer.IsExpired() && m_running_task) {
    if (m_running_task->critical) {
      m_running_task.reset();
    } else {
      RemoveRunningTask();
    }
  }
  if (m_running_task)
    return;
  bool need_resort = false;
  while (!m_cooling_queue.empty()) {
    auto now = m_cooling_off_timer.GetTime();
    auto t = m_cooling_queue.front();
    if (t->cooling_end_time > now)
      break;
    m_task_queue.push_back(t);
    m_cooling_queue.pop_front();
    need_resort = true;
  }
  if (m_task_queue.empty())
    return;
  if (need_resort) {
    m_task_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
      return a->priority < b->priority;
    });
  }
  auto& t = m_task_queue.front();
  auto ret = t->query_func(t->request_id);
  if (ret >= 0) {
    m_running_task = t;
    m_query_timeout_timer.Reset(QUERY_TIMEOUT);
  } else {
    m_fail_wait_timer.Reset(std::chrono::milliseconds(500));
  }
}

