void ConvertToFemas2Direction(future::Direction d, TUstpFtdcDirectionType* t) {
  if (d == Direction::kBuy) {
    *t = USTP_FTDC_D_Buy;
  } else if (d == Direction::kSell) {
    *t = USTP_FTDC_D_Sell;
  } else {
    FCASSERT(false);
  }
}

future::Direction ConvertFromFemas2Direction(const TUstpFtdcDirectionType* t) {
  if (*t == USTP_FTDC_D_Buy)
    return future::Direction::kBuy;
  else if (*t == USTP_FTDC_D_Sell)
    return future::Direction::kSell;
  return future::Direction::kInvalid;
}

void ConvertToFemas2ExchangeID(std::string d, TUstpFtdcExchangeIDType* t) {
  if (d == "CZCE")
    strcpy_x(*t, "ZCE");
  else
    strcpy_x(*t, d);
}

std::string ConvertFromFemas2ExchangeID(const TUstpFtdcExchangeIDType* t) {
  if (std::string(*t) == "ZCE") {
    return "CZCE";
  }
  return std::string(*t);
}

void ConvertToFemas2ExecAction(future::ExecActionType d, TUstpFtdcOrderTypeType& t) {
  if (d == future::ExecActionType::kExec) {
    t = USTP_FTDC_OT_OptExec;
  } else if (d == future::ExecActionType::kAbandon) {
    t = USTP_FTDC_OT_OptAbandon;
  }
}

future::ExecActionType ConvertFromFemas2ExecAction(const TUstpFtdcOrderTypeType& t) {
  if (t == USTP_FTDC_OT_OptExec) {
    return future::ExecActionType::kExec;
  } else if (t == USTP_FTDC_OT_OptAbandon) {
    return future::ExecActionType::kAbandon;
  }
  FCASSERT(false);
  return future::ExecActionType::kClose;
}

future::Offset ConvertFromFemas2Offset(const TUstpFtdcOffsetFlagType* t) {
  if (*t == USTP_FTDC_OF_Open) {
    return future::Offset::kOpen;
  } else if (*t == USTP_FTDC_OF_CloseToday) {
    return future::Offset::kCloseToday;
  } else if (*t == USTP_FTDC_OF_CloseYesterday) {
    return future::Offset::kCloseYesterday;
  } else if (*t == USTP_FTDC_OF_ALL) {
    return future::Offset::kInvalid;
  } else {
    return future::Offset::kClose;
  }
}

void ConvertToFemas2HedgeFlag(future::OrderHedgeFlag h, TUstpFtdcHedgeFlagType* t) {
  if (h == future::OrderHedgeFlag::kArbitrage)
    *t = USTP_FTDC_CHF_Arbitrage;
  else if (h == future::OrderHedgeFlag::kHedge)
    *t = USTP_FTDC_CHF_Hedge;
  else if (h == future::OrderHedgeFlag::kMarketMaker)
    *t = USTP_FTDC_CHF_MarketMaker;
  else if (h == future::OrderHedgeFlag::kSpecAndHedge)
    *t = USTP_FTDC_CHF_SpecHedge;
  else if (h == future::OrderHedgeFlag::kHedgeAndSpec)
    *t = USTP_FTDC_CHF_HedgeSpec;
  else
    *t = USTP_FTDC_CHF_Speculation;
}

future::OrderHedgeFlag ConvertFromFemas2HedgeFlag(const TUstpFtdcHedgeFlagType* t) {
  if (*t == USTP_FTDC_CHF_Speculation) {
    return future::OrderHedgeFlag::kSpeculation;
  } else if (*t == USTP_FTDC_CHF_MarketMaker) {
    return future::OrderHedgeFlag::kMarketMaker;
  } else if (*t == USTP_FTDC_CHF_Hedge) {
    return future::OrderHedgeFlag::kHedge;
  } else if (*t == USTP_FTDC_CHF_Arbitrage) {
    return future::OrderHedgeFlag::kArbitrage;
  }
  FCASSERT(false);
  return future::OrderHedgeFlag::kSpeculation;
}

future::PriceType ConvertFromFemas2OrderPriceType(const TUstpFtdcOrderPriceTypeType* t) {
  if (*t == USTP_FTDC_OPT_LimitPrice) {
    return future::PriceType::kLimit;
  } else if (*t == USTP_FTDC_OPT_AnyPrice) {
    return future::PriceType::kAny;
  } else if (*t == USTP_FTDC_OPT_BestPrice) {
    return future::PriceType::kBest;
  } else if (*t == USTP_FTDC_OPT_FiveLevelPrice) {
    return future::PriceType::kFiveLevel;
  }
  FCASSERT(false);
  return future::PriceType::kLimit;
}

future::OrderStatus ConvertFromFemas2OrderStatus(const TUstpFtdcOrderStatusType* t) {
  if (*t == USTP_FTDC_OS_AllTraded || *t == USTP_FTDC_OS_Canceled) {
    return future::OrderStatus::kDead;
  }
  return future::OrderStatus::kAlive;
}

future::OrderStatus ConvertFromFemas2QuoteStatus(const TUstpFtdcQuoteStatusType* t) {
  if (*t == USTP_FTDC_QS_Canceled_All || *t == USTP_FTDC_QS_Traded_All) {
    return future::OrderStatus::kDead;
  }
  return future::OrderStatus::kAlive;
}

future::OrderTimeCondition ConvertFromFemas2TimeCondition(const TUstpFtdcTimeConditionType* t) {
  if (*t == USTP_FTDC_TC_IOC) {
    return future::OrderTimeCondition::kIoc;
  } else if (*t == USTP_FTDC_TC_GFD) {
    return future::OrderTimeCondition::kGfd;
  } else if (*t == USTP_FTDC_TC_GFS) {
    return future::OrderTimeCondition::kGfs;
  } else if (*t == USTP_FTDC_TC_GTD) {
    return future::OrderTimeCondition::kGtd;
  } else if (*t == USTP_FTDC_TC_GTC) {
    return future::OrderTimeCondition::kGtc;
  } else if (*t == USTP_FTDC_TC_GFA) {
    return future::OrderTimeCondition::kGfa;
  }
  FCASSERT(false);
  return future::OrderTimeCondition::kInvalid;
}

future::OrderVolumeCondition ConvertFromFemas2VolumeCondition(const TUstpFtdcVolumeConditionType* t) {
  if (*t == USTP_FTDC_VC_AV) {
    return future::OrderVolumeCondition::kAny;
  } else if (*t == USTP_FTDC_VC_MV) {
    return future::OrderVolumeCondition::kMin;
  } else if (*t == USTP_FTDC_VC_CV) {
    return future::OrderVolumeCondition::kAll;
  }
  FCASSERT(false);
  return future::OrderVolumeCondition::kInvalid;
}

future::ForceCloseReason ConvertFromFemas2ForceCloseReason(const TUstpFtdcForceCloseReasonType* t) {
  if (*t == USTP_FTDC_FCR_NotForceClose) {
    return future::ForceCloseReason::kNotForceClose;
  } else if (*t == USTP_FTDC_FCR_LackDeposit) {
    return future::ForceCloseReason::kLackDeposit;
  } else if (*t == USTP_FTDC_FCR_ClientOverPositionLimit) {
    return future::ForceCloseReason::kClientOverPositionLimit;
  } else if (*t == USTP_FTDC_FCR_MemberOverPositionLimit) {
    return future::ForceCloseReason::kMemberOverPositionLimit;
  } else if (*t == USTP_FTDC_FCR_NotMultiple) {
    return future::ForceCloseReason::kNotMultiple;
  } else if (*t == USTP_FTDC_FCR_Violation) {
    return future::ForceCloseReason::kViolation;
  } else if (*t == USTP_FTDC_FCR_Other) {
    return future::ForceCloseReason::kOther;
  } else if (*t == USTP_FTDC_FCR_PersonDeliv) {
    return future::ForceCloseReason::kPersonDeliv;
  } else if (*t == USTP_FTDC_FCR_HedgeOverPositionLimit) {
    return future::ForceCloseReason::kHedgeOverPositionLimit;
  }
  FCASSERT(false);
  return future::ForceCloseReason::kNotForceClose;
}

void ConvertToFemas2TimeCondition(future::OrderTimeCondition d, TUstpFtdcTimeConditionType* t) {
  if (d == OrderTimeCondition::kIoc) {
    *t = USTP_FTDC_TC_IOC;
  } else if (d == OrderTimeCondition::kGfd) {
    *t = USTP_FTDC_TC_GFD;
