md::TradeStatus ConvertFromFemas2InstrumentStatusType(const TUstpFtdcInstrumentStatusType* t) {
  if (*t == USTP_FTDC_IS_BeforeTrading) {
    return md::TradeStatus::kBeforeTrading;
  } else if (*t == USTP_FTDC_IS_NoTrading) {
    return md::TradeStatus::kNoTrading;
  } else if (*t == USTP_FTDC_IS_Continous) {
    return md::TradeStatus::kContinous;
  } else if (*t == USTP_FTDC_IS_AuctionOrdering) {
    return md::TradeStatus::kAuctionOrdering;
  } else if (*t == USTP_FTDC_IS_AuctionBalance) {
    return md::TradeStatus::kAuctionBalance;
  } else if (*t == USTP_FTDC_IS_AuctionMatch) {
    return md::TradeStatus::kAuctionMatch;
  } else if (*t == USTP_FTDC_IS_Closed) {
    return md::TradeStatus::kClosed;
  }
  FCASSERT(false);
  return md::TradeStatus::kUnknown;
}

void ConvertToFemas2OrderField(
  const std::shared_ptr<future::InsertOrder> d, std::shared_ptr<CUstpFtdcInputOrderField> field) {
  strcpy_x(field->InstrumentID, d->instrument_id);
  ConvertToFemas2ExchangeID(d->exchange_id, &field->ExchangeID);
  ConvertToFemas2Direction(d->direction, &field->Direction);
  ConvertToFemas2OffsetFlag(d->offset, &field->OffsetFlag);
  ConvertToFemas2HedgeFlag(d->hedge_flag, &field->HedgeFlag);
  field->Volume = d->volume;
  field->LimitPrice = d->limit_price;
  ConvertToFemas2OrderPriceType(d->price_type, &field->OrderPriceType);
  ConvertToFemas2TimeCondition(d->time_condition, &field->TimeCondition);
  ConvertToFemas2VolumeCondition(d->volume_condition, &field->VolumeCondition);
  field->ForceCloseReason = USTP_FTDC_FCR_NotForceClose;
  std::string head = d->instrument_id.substr(0, 3);
  if (head == "SP " || head == "SPD") {  // 分别对应大连跨期和郑州跨期
    field->ArbiType = USTP_FTDC_AT_SP;
  } else if (head == "SPC" || head == "IPS") {  // 分别对应大连跨品种和郑州跨品种
    field->ArbiType = USTP_FTDC_AT_SPC;
  } else {
    field->ArbiType = USTP_FTDC_AT_Basic;
  }
}

std::shared_ptr<CUstpFtdcOrderField> FtdcInputOrderFieldToOrderField(std::shared_ptr<CUstpFtdcInputOrderField> origin) {
  auto target = std::make_shared<CUstpFtdcOrderField>();
  strcpy_x(target->ActionDay, origin->ActionDay);
  strcpy_x(target->InstrumentID, origin->InstrumentID);
  strcpy_x(target->InvestorID, origin->InvestorID);
  strcpy_x(target->UserID, origin->UserID);
  strcpy_x(target->ExchangeID, origin->ExchangeID);
  target->Direction = origin->Direction;
  target->OffsetFlag = origin->OffsetFlag;
  target->HedgeFlag = origin->HedgeFlag;
  target->TimeCondition = origin->TimeCondition;
  target->OrderPriceType = origin->OrderPriceType;
  target->VolumeCondition = origin->VolumeCondition;
  target->LimitPrice = origin->LimitPrice;
  target->MinVolume = origin->MinVolume;
  target->Volume = origin->Volume;
  target->VolumeRemain = origin->Volume;
  strcpy_x(target->UserCustom, origin->UserCustom);
  strcpy_x(target->OrderSysID, origin->OrderSysID);
  strcpy_x(target->UserOrderLocalID, origin->UserOrderLocalID);
  target->OrderStatus = USTP_FTDC_OS_AcceptedNoReply;
  target->ForceCloseReason = origin->ForceCloseReason;
  target->BusinessLocalID = -1;
  return target;
}

std::string ToFclibOrderId(
  const TUstpFtdcUserOrderLocalIDType order_local_id, const TUstpFtdcOrderLocalIDType order_id) {
  auto str = std::string(order_local_id);
  if (str.empty()) {
    return std::string(order_id);
  }
  return str;
}

