void Femas2UnitBank::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<TransferMoney>(m_service->m_command_manager->Update(command));
  int ret = 0;
  CUstpFtdcstpUserDepositField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_investor_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  field.Amount = req->amount;
  field.AmountDirection = req->is_deposit ? USTP_FTDC_AD_In : USTP_FTDC_AD_Out;
  auto request_id = m_service->GenerateRequestID();
  ret = m_service->m_api->ReqUserDeposit(&field, request_id);
  LogReq(m_logger, "ReqTransferMoney", &field, request_id, ret);
  m_service->SetReqResponse(command, request_id, ret);
}

void Femas2UnitBank::OnErrRtnTransferMoney(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void Femas2UnitBank::OnRspTransferMoney(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

int Femas2UnitBank::RunOnce() {
  return 1;
}

