bool StringToTag(SpiMessage::Tag* tag, const std::string& str) {
  // Tag里无OnRspDSUserCertification OnRspError
  static std::map<std::string, SpiMessage::Tag> tag_map = {
    {"OnRtnOrder", SpiMessage::Tag::OnRtnOrder},
    {"OnRtnTrade", SpiMessage::Tag::OnRtnTrade},
    {"OnRtnQuote", SpiMessage::Tag::OnRtnQuote},
    {"OnRspUserLogin", SpiMessage::Tag::OnRspUserLogin},

    {"OnFrontConnected", SpiMessage::Tag::OnFrontConnected},
    {"OnFrontDisconnected", SpiMessage::Tag::OnFrontDisconnected},
    {"OnRspUserPasswordUpdate", SpiMessage::Tag::OnRspUserPasswordUpdate},
    {"OnRspQryInvestorPosition", SpiMessage::Tag::OnRspQryInvestorPosition},
    {"OnRspQryInvestorCombPosition", SpiMessage::Tag::OnRspQryInvestorCombPosition},
    {"OnRspOrderInsert", SpiMessage::Tag::OnRspOrderInsert},
    {"OnErrRtnOrderInsert", SpiMessage::Tag::OnErrRtnOrderInsert},
    {"OnRspOrderAction", SpiMessage::Tag::OnRspOrderAction},
    {"OnErrRtnOrderAction", SpiMessage::Tag::OnErrRtnOrderAction},
    {"OnRtnExecOrder", SpiMessage::Tag::OnRtnExecOrder},
    {"OnErrRtnExecOrderInsert", SpiMessage::Tag::OnErrRtnExecOrderInsert},
    {"OnRspExecOrderAction", SpiMessage::Tag::OnRspExecOrderAction},
    {"OnErrRtnExecOrderAction", SpiMessage::Tag::OnErrRtnExecOrderAction},
    {"OnRspQuoteInsert", SpiMessage::Tag::OnRspQuoteInsert},
    {"OnErrRtnQuoteInsert", SpiMessage::Tag::OnErrRtnQuoteInsert},
    {"OnRspQuoteAction", SpiMessage::Tag::OnRspQuoteAction},
    {"OnRspQryUserInvestor", SpiMessage::Tag::OnRspQryUserInvestor},
    {"OnErrRtnQuoteAction", SpiMessage::Tag::OnErrRtnQuoteAction},
    {"OnRspQryInvestorAccount", SpiMessage::Tag::OnRspQryTradingAccount},
    {"OnRspExecOrderInsert", SpiMessage::Tag::OnRspInsertExecOrder},
    {"OnRspQryInvestorMargin", SpiMessage::Tag::OnRspQryInstrumentMarginRate},
    {"OnRspQryInvestorFee", SpiMessage::Tag::OnRspQryInstrumentCommissionRate},
  };
  auto it = tag_map.find(str);
  if (it == tag_map.end())
    return false;
  *tag = it->second;
  return true;
}

template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, std::shared_ptr<void> field = nullptr,
  CUstpFtdcRspInfoField* rsp_info = nullptr, int req_id = 0, bool is_last = true) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (field) {
    msg->pMainField = field;
  }
  if (rsp_info) {
    memcpy(&msg->RspInfo, rsp_info, sizeof(CUstpFtdcRspInfoField));
  }
  msg->nRequestID = req_id;
  msg->bIsLast = is_last;
  return msg;
}

std::shared_ptr<SpiMessage> LogReplayer::LogLineToSpiMessage(const std::string& log_line) {
  SerializerFemasLog ss;
  ss.FromString(log_line.c_str());
  auto msg = (*ss.m_doc)["msg"].GetString();
  SpiMessage::Tag t;
  if (!StringToTag(&t, msg))
    return nullptr;
  switch (t) {
    case SpiMessage::Tag::OnRtnOrder: {
      auto p = std::make_shared<CUstpFtdcOrderField>();
      ss.ToVar(*p);
      return MakeSpiMsg<CUstpFtdcOrderField>(SpiMessage::Tag::OnRtnOrder, p);
    }
    case SpiMessage::Tag::OnRtnTrade: {
      auto p = std::make_shared<CUstpFtdcTradeField>();
      ss.ToVar(*p);
      return MakeSpiMsg<CUstpFtdcTradeField>(SpiMessage::Tag::OnRtnTrade, p);
    }
    case SpiMessage::Tag::OnRtnQuote: {
      auto p = std::make_shared<CUstpFtdcRtnQuoteField>();
      ss.ToVar(*p);
      return MakeSpiMsg<CUstpFtdcRtnQuoteField>(SpiMessage::Tag::OnRtnQuote, p);
    }
    case SpiMessage::Tag::OnRspUserLogin: {
      auto p = std::make_shared<CUstpFtdcRspUserLoginField>();
      ss.ToVar(*p);
      RspPack rsp;
      ss.ToVar(rsp);
      return MakeSpiMsg<CUstpFtdcRspUserLoginField>(
        SpiMessage::Tag::OnRspUserLogin, p, &rsp.rsp_info, rsp.request_id, rsp.is_last);
    }
    case SpiMessage::Tag::OnFrontConnected: {
      auto msg = std::make_shared<SpiMessage>();
      msg->tag = SpiMessage::Tag::OnFrontConnected;
      return msg;
    }
    case SpiMessage::Tag::OnFrontDisconnected: {
      auto msg = std::make_shared<SpiMessage>();
      msg->tag = SpiMessage::Tag::OnFrontDisconnected;
      msg->RspInfo.ErrorID = -1;
      return msg;
    }
    case SpiMessage::Tag::OnRspUserPasswordUpdate: {
      auto p = std::make_shared<CUstpFtdcUserPasswordUpdateField>();
      ss.ToVar(*p);
      RspPack rsp;
      ss.ToVar(rsp);
