void LogReplayer::LoadLogFile(const std::string& log_file_name, Femas2ServiceImpl* adapter) {
  boost::iostreams::filtering_istream in;
  in.push(boost::iostreams::lzma_decompressor());
  in.push(boost::iostreams::file_source(log_file_name, BOOST_IOS::in | BOOST_IOS::binary));

  int line_no = 0;
  std::string line;
  while (std::getline(in, line)) {
    if (line_no % 10000 == 0)
      printf("Processing line %d\n", line_no + 1);
    line_no += 1;
    auto r = LogLineToSpiMessage(line);
    if (r)
      adapter->m_recv_queue.push(r);
  }
}

