DtpUnitNotice::DtpUnitNotice(DtpServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("notice_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_session.reset();
  m_service->RegisterCommandProcessor(QueryNotice::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryNotice(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingNotice::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryTradingNotice(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryNotice(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingNotice(msg);
  });
}

void DtpUnitNotice::ReqQryNotice(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryNotice>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto field = std::make_shared<CThostFtdcQryNoticeField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryNoticeField));
  strcpy_x(field->BrokerID, m_session.value().BrokerID);
  int request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryNotice" + std::to_string(request_id));
  m_query_planner->AddTask("ReqQryNotice", QueryPriority::kImmediately, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryNotice(field.get(), request_id);
    if (ret >= 0) {
      LogDtpReq(m_logger, "ReqQryNotice", field.get(), request_id, ret);
    }
    return ret;
  });
}

void DtpUnitNotice::ReqQryTradingNotice(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryTradingNotice>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  auto field = std::make_shared<CThostFtdcQryTradingNoticeField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryTradingNoticeField));
  strcpy_x(field->BrokerID, m_session.value().BrokerID);
  strcpy_x(field->InvestorID, m_session.value().UserID);
  int request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryTradingNotice" + std::to_string(request_id));
  m_query_planner->AddTask("ReqQryTradingNotice", QueryPriority::kImmediately, request_id, [=](int request_id) {
    auto ret = m_service->m_api->ReqQryTradingNotice(field.get(), request_id);
    if (ret >= 0) {
      LogDtpReq(m_logger, "ReqQryTradingNotice", field.get(), request_id, ret);
    }
    return ret;
  });
}

