void ConvertToSfitDirection(Direction d, TThostFtdcDirectionType* t) {
  if (d == Direction::kBuy) {
    *t = THOST_FTDC_D_Buy;
  } else if (d == Direction::kSell) {
    *t = THOST_FTDC_D_Sell;
  }
}

void ConvertToSfitPosiDirection(future::PosiDirection d, TThostFtdcPosiDirectionType& t) {
  if (d == PosiDirection::kNet) {
    t = THOST_FTDC_PD_Net;
  } else if (d == PosiDirection::kLong) {
    t = THOST_FTDC_PD_Long;
  } else if (d == PosiDirection::kShort) {
    t = THOST_FTDC_PD_Short;
  }
}

future::PosiDirection ConvertFromSfitPosiDirection(const TThostFtdcPosiDirectionType& t) {
  if (t == THOST_FTDC_PD_Net) {
    return future::PosiDirection::kNet;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kLong;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kShort;
  }
  return future::PosiDirection::kInvalid;
}

void ConvertToSfitExecAction(future::ExecActionType d, TThostFtdcActionTypeType& t) {
