std::shared_ptr<CThostFtdcQuoteField> FtdcInputQuoteFieldToQuoteField(std::shared_ptr<CThostFtdcInputQuoteField> origin,
  TThostFtdcSessionIDType session_id, TThostFtdcFrontIDType front_id) {
  auto target = std::make_shared<CThostFtdcQuoteField>();
  strcpy_x(target->BrokerID, origin->BrokerID);
  strcpy_x(target->UserID, origin->UserID);
  strcpy_x(target->InvestorID, origin->InvestorID);
  strcpy_x(target->ExchangeID, origin->ExchangeID);
  strcpy_x(target->InstrumentID, origin->InstrumentID);
  strcpy_x(target->QuoteRef, origin->QuoteRef);
  strcpy_x(target->AskOrderRef, origin->AskOrderRef);
  strcpy_x(target->BidOrderRef, origin->BidOrderRef);
  target->AskPrice = origin->AskPrice;
  target->BidPrice = origin->BidPrice;
  target->AskVolume = origin->AskVolume;
  target->BidVolume = origin->BidVolume;
  target->RequestID = origin->RequestID;
  target->AskOffsetFlag = origin->AskOffsetFlag;
  target->BidOffsetFlag = origin->BidOffsetFlag;
  target->AskHedgeFlag = origin->AskHedgeFlag;
  target->BidHedgeFlag = origin->BidHedgeFlag;
  target->SessionID = session_id;
  target->FrontID = front_id;
  target->QuoteStatus = THOST_FTDC_OST_Unknown;
  return target;
}

void ConvertToSfitOrderField(const std::shared_ptr<InsertOrder> d, std::shared_ptr<CThostFtdcInputOrderField> field) {
  strcpy_x(field->InstrumentID, d->instrument_id);
  strcpy_x(field->ExchangeID, d->exchange_id);
  strcpy_x(field->OrderRef, std::to_string(d->order_ref).c_str());
  ConvertToSfitDirection(d->direction, &field->Direction);
  ConvertToSfitTimeCondition(d->time_condition, &field->TimeCondition);
  ConvertToSfitOrderPriceType(d->price_type, &field->OrderPriceType);
  ConvertToSfitVolumeCondition(d->volume_condition, &field->VolumeCondition);
  ConvertToSfitOffsetFlag(d->offset, &field->CombOffsetFlag[0]);
  if (field->OrderPriceType == THOST_FTDC_OPT_LimitPrice) {
    field->LimitPrice = d->limit_price;
  } else {
    field->LimitPrice = 0;
  }
  ConvertToSfitHedgeFlag(d->hedge_flag, &field->CombHedgeFlag[0]);
  field->MinVolume = d->min_volume;
  field->IsSwapOrder = d->is_swap_order;
  field->VolumeTotalOriginal = d->volume;
  field->ForceCloseReason = THOST_FTDC_FCC_NotForceClose;
  field->ContingentCondition = THOST_FTDC_CC_Immediately;
}

md::TradeStatus ConvertFromSfitInstrumentStatusType(const TThostFtdcInstrumentStatusType* t) {
  if (*t == THOST_FTDC_IS_BeforeTrading) {
    return md::TradeStatus::kBeforeTrading;
  } else if (*t == THOST_FTDC_IS_NoTrading) {
    return md::TradeStatus::kNoTrading;
  } else if (*t == THOST_FTDC_IS_Continous) {
    return md::TradeStatus::kContinous;
  } else if (*t == THOST_FTDC_IS_AuctionOrdering) {
    return md::TradeStatus::kAuctionOrdering;
  } else if (*t == THOST_FTDC_IS_AuctionBalance) {
    return md::TradeStatus::kAuctionBalance;
  } else if (*t == THOST_FTDC_IS_AuctionMatch) {
    return md::TradeStatus::kAuctionMatch;
  } else if (*t == THOST_FTDC_IS_Closed) {
    return md::TradeStatus::kClosed;
  }
  return md::TradeStatus::kUnknown;
}

std::string ToFclibOrderId(const TThostFtdcOrderRefType order_ref, const TThostFtdcSessionIDType session_id,
  const TThostFtdcFrontIDType front_id) {
  return std::string(order_ref) + "|" + std::to_string(session_id) + "|" + std::to_string(front_id);
}

std::string GetDisConnectReason(int id) {
  if (id == 4097)
    return u8"网络读失败";
  if (id == 4098)
    return u8"网络写失败";
  if (id == 8193)
    return u8"接收心跳超时";
  if (id == 8194)
    return u8"发送心跳超时";
  if (id == 8195)
    return u8"收到错误报文";
  return u8"前置机断连";
}

