DtpUnitNoticeView::DtpUnitNoticeView(DtpServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("notice_view_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryNotice(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingNotice(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTradingNotice(msg);
  });
}

void DtpUnitNoticeView::OnRspQryNotice(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pNotice = std::static_pointer_cast<CThostFtdcNoticeField>(msg->pMainField);
  m_rsp_field.push_back(pNotice);
  if (!msg->bIsLast)
    return;
  auto notice = std::make_shared<future::Notice>();
  notice->user_key = m_service->m_user_key;
  notice->notice_id = "notice_";
  for (const auto& n : m_rsp_field) {
    notice->notice_id += std::string(n->SequenceLabel) + "_";
    notice->content.append(n->Content);
  }
  notice->content = GbkToUtf8(notice->content);
  notice->content_type = NoticeType::kHtml;
  notice->level = NoticeLevel::kOrdinary;
  notice->notice_time = NowAsEpochNano();
  notice->source_type = SourceType::kBroker;
  m_service->m_node_db->ReplaceRecord<Notice>(notice);
  m_rsp_field.clear();
}

void DtpUnitNoticeView::OnRspQryTradingNotice(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pNotice = std::static_pointer_cast<CThostFtdcTradingNoticeField>(msg->pMainField);
    m_rsp_notice[pNotice->SequenceNo].push_back(pNotice);
  }
  if (!msg->bIsLast)
    return;
  for (const auto& [seq, notice_vector] : m_rsp_notice) {
    auto notice = std::make_shared<future::Notice>();
    notice->user_key = m_service->m_user_key;
    notice->notice_id = "trading_notice_" + std::to_string(seq);
    notice->content_type = NoticeType::kText;
    notice->level = NoticeLevel::kWarning;
    notice->source_type = SourceType::kBroker;
    notice->notice_time = GetRealTradeTime(m_service->m_trading_day.c_str(), (*notice_vector.begin())->SendTime);
    std::string temp;
    for (const auto& n : notice_vector) {
      temp += n->FieldContent;
    }
    notice->content = FormatNoticeTextContent(GbkToUtf8(temp));
    m_service->m_node_db->ReplaceRecord<Notice>(notice);
  }
  m_rsp_notice.clear();
}

void DtpUnitNoticeView::OnRtnTradingNotice(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pNotice = std::static_pointer_cast<CThostFtdcTradingNoticeInfoField>(msg->pMainField);
  m_rtn_notice[pNotice->SequenceNo].push_back(pNotice);
  if (strlen(pNotice->FieldContent) != 0)
    return;
  for (const auto& [seq, notice_vector] : m_rtn_notice) {
    auto notice = std::make_shared<future::Notice>();
    notice->user_key = m_service->m_user_key;
    notice->notice_id = "trading_notice_" + std::to_string(seq);
    notice->content_type = NoticeType::kText;
    notice->level = NoticeLevel::kWarning;
    notice->source_type = SourceType::kBroker;
    notice->notice_time = GetRealTradeTime(m_service->m_trading_day.c_str(), (*notice_vector.begin())->SendTime);
    std::string temp;
    for (const auto& n : notice_vector) {
      temp += n->FieldContent;
    }
    notice->content = FormatNoticeTextContent(GbkToUtf8(temp));
    m_service->m_node_db->ReplaceRecord<Notice>(notice);
  }
  m_rtn_notice.clear();
}

int DtpUnitNoticeView::RunOnce() {
  return 0;
}

