  m_service->RegisterCommandProcessor(InsertQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertQuote(command);
  });
  m_service->RegisterCommandProcessor(CancelQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelQuote(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQuoteInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteAction, [this](std::shared_ptr<SpiMessage> msg) {
