void DtpUnitExecOrder::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  m_last_session.reset();
}

void DtpUnitExecOrder::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
    m_last_session = *rsp;
  }
}

void DtpUnitExecOrder::ReqInsertExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  CThostFtdcInputExecOrderField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.ExecOrderRef, std::to_string(req->exec_order_ref));
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_last_session->UserID);
  strcpy_x(field.UserID, m_last_session->UserID);
  strcpy_x(field.BrokerID, m_last_session->BrokerID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  ConvertToSfitOffsetFlag(req->offset, &field.OffsetFlag);
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  ConvertToSfitPosiDirection(req->direction, field.PosiDirection);
  ConvertToSfitExecAction(req->exec_action_type, field.ActionType);
  ConvertToSfitExecOrderCloseFlag(req->close_flag, field.CloseFlag);
  // 大商所放弃行权操作为：行权，行权量为0
  if (req->exchange_id == "DCE" && req->exec_action_type == future::ExecActionType::kAbandon) {
    field.ActionType = THOST_FTDC_ACTP_Exec;
    field.Volume = 0;
  } else {
    field.Volume = req->volume;
  }
  field.ReservePositionFlag = THOST_FTDC_EOPF_Reserve;
  field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderInsert(&field, field.RequestID);
  LogDtpReq(m_logger, "ReqInsertExecOrder", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  } else {
    m_service->m_command_manager->SetCommandId(command, "ReqInsertExecOrder" + req->exec_order_id);
  }
}

void DtpUnitExecOrder::OnRspInsertExecOrder(std::shared_ptr<SpiMessage> msg) {
  auto pExecOrder = std::static_pointer_cast<CThostFtdcInputExecOrderField>(msg->pMainField);
  auto exec_order_id =
    ToFclibOrderId(pExecOrder->ExecOrderRef, m_last_session.value().SessionID, m_last_session.value().FrontID);
  auto req = m_service->m_command_manager->Update("ReqInsertExecOrder" + exec_order_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void DtpUnitExecOrder::OnRtnExecOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pExecOrder = std::static_pointer_cast<CThostFtdcExecOrderField>(msg->pMainField);
  if (pExecOrder->OrderSubmitStatus == THOST_FTDC_OSS_Accepted) {
    auto req = std::make_shared<QueryInvestorPosition>(m_service->m_user_key);
    m_service->ExecuteCommand(req);
  }
  auto target_execorder = std::make_shared<ExecOrder>();
  target_execorder->instrument_id = pExecOrder->InstrumentID;
  target_execorder->exchange_id = pExecOrder->ExchangeID;
  target_execorder->investor_id = pExecOrder->InvestorID;
  target_execorder->volume = pExecOrder->Volume;
  target_execorder->direction = ConvertFromSfitPosiDirection(pExecOrder->PosiDirection);
  target_execorder->offsetflag = dtp::ConvertFromSfitOffset(pExecOrder->OffsetFlag);
  target_execorder->hedge_flag = ConvertFromSfitHedgeFlag(&pExecOrder->HedgeFlag);
  target_execorder->exchange_exec_order_sysid = GbkToUtf8(pExecOrder->ExecOrderSysID);
  target_execorder->exec_action_type = ConvertFromSfitExecAction(pExecOrder->ActionType);
  target_execorder->exec_close_flag = ConvertFromSfitExecOrderCloseFlag(pExecOrder->CloseFlag);
  target_execorder->exec_result = ConvertFromSfitExecOrderResultType(pExecOrder->ExecResult);
  target_execorder->status_msg = GbkToUtf8(pExecOrder->StatusMsg);
  target_execorder->exec_order_ref = GbkToUtf8(pExecOrder->ExecOrderRef);
  target_execorder->front_id = pExecOrder->FrontID;
  target_execorder->session_id = pExecOrder->SessionID;
  target_execorder->insert_date_time = StringToEpochNano(pExecOrder->InsertDate, pExecOrder->InsertTime);
  target_execorder->user_key = m_service->m_user_key;
  if (pExecOrder->CancelTime[0] != '\0') {
    target_execorder->cancel_time = StringToEpochNano(pExecOrder->InsertDate, pExecOrder->CancelTime);
  }
  target_execorder->exec_order_id =
    ToFclibOrderId(pExecOrder->ExecOrderRef, pExecOrder->SessionID, pExecOrder->FrontID);
  m_service->m_node_db->ReplaceRecord<ExecOrder>(target_execorder);

  auto exec_order_id = ToFclibOrderId(pExecOrder->ExecOrderRef, pExecOrder->SessionID, pExecOrder->FrontID);
  m_alive_exec_orders[exec_order_id] = pExecOrder;
  // 行权请求
  auto req_insert = m_service->m_command_manager->Update("ReqInsertExecOrder" + exec_order_id);
  if (req_insert && req_insert->status != UserCommand::Status::kFinished) {
    SetCommandFinished(req_insert, 0, u8"成功");
  }
  // 撤销行权请求
  auto req_cancel = m_service->m_command_manager->Update("ReqCancelExecOrder" + std::string(pExecOrder->ExecOrderRef));
  if (req_cancel && pExecOrder->ExecResult == THOST_FTDC_OER_Canceled
    && req_cancel->status != UserCommand::Status::kFinished) {
    SetCommandFinished(req_cancel, 0, u8"成功");
  }
}

void DtpUnitExecOrder::ReqCancelExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_service->m_command_manager->Update(command));
  if (!m_last_session.has_value() || !m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  if (!m_alive_exec_orders.count(req->exec_order_id)) {
    SetCommandFinished(req, -1, u8"fclib: 行权报单委托不存在");
    return;
  }
  auto origin = m_alive_exec_orders[req->exec_order_id];
  CThostFtdcInputExecOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.InstrumentID, origin->InstrumentID);
  strcpy_x(field.ExchangeID, origin->ExchangeID);
  strcpy_x(field.BrokerID, origin->BrokerID);
  strcpy_x(field.InvestorID, origin->InvestorID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  auto ref = m_service->GenerateOrderRef();
  field.ExecOrderActionRef = static_cast<int>(ref * 100);
  strcpy_x(field.ExecOrderRef, origin->ExecOrderRef);
  field.FrontID = origin->FrontID;
  field.SessionID = origin->SessionID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  if (origin->ExecOrderSysID[0] != '\0') {
    strcpy_x(field.ExecOrderSysID, origin->ExecOrderSysID);
  }
  field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderAction(&field, field.RequestID);
  LogDtpReq(m_logger, "ReqCancelExecOrder", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  } else {
    m_service->m_command_manager->SetCommandId(command, "ReqCancelExecOrder" + std::string(field.ExecOrderRef));
  }
}

