  target_option_self_close->hedge_flag = ConvertFromSfitHedgeFlag(&pOptionSelfClose->HedgeFlag);
  target_option_self_close->exec_result = ConvertFromSfitExecOrderResultType(pOptionSelfClose->ExecResult);
  target_option_self_close->insert_date_time =
