// 根据平仓成交更新明细手数
void UpdateDetailsByVolume(std::list<std::shared_ptr<PositionDetail>>* details, int* volume) {
  while (*volume > 0 && !details->empty()) {
    auto vol = (std::min)(*volume, details->front()->volume);
    *volume -= vol;
    details->front()->volume -= vol;
    if (details->front()->volume <= 0)
      details->pop_front();
  }
}

// 根据平仓成交更新明细
void UpdateDetailsByCloseTrade(SubPosition* subpos, std::shared_ptr<CThostFtdcTradeField> trade, int volume) {
  if (volume <= 0)
    return;
  if (std::string(trade->ExchangeID) == "SHFE" || std::string(trade->ExchangeID) == "INE") {
    bool flag = trade->OffsetFlag != THOST_FTDC_OF_CloseToday;
    auto details = flag ? &subpos->his_position_details : &subpos->today_position_details;
    UpdateDetailsByVolume(details, &volume);
  } else {
    UpdateDetailsByVolume(&subpos->his_position_details, &volume);
    UpdateDetailsByVolume(&subpos->today_position_details, &volume);
  }
}

DtpUnitPositionAccountView::DtpUnitPositionAccountView(DtpServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryBrokerTradingParams, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryBrokerTradingParams(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryInvestorPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryInvestorPosition(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInvestorPositionDetail, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInvestorPositionDetail(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingAccount(msg);
  });
  /** trade和order可能重复，这个没有考虑 */
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspCombActionInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCombActionInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnCombAction(msg);
  });
  m_service->RegisterCommandProcessor(PositionCombAuto::AID, [this](std::shared_ptr<UserCommand> command) {
    auto req = std::static_pointer_cast<PositionCombAuto>(command);
    m_service->m_options.position_comb_auto = req->auto_combi;
    SetCommandFinished(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    m_service->m_command_manager->SetCommandId(command, "RequireQryAccount");
    RequireQryAccount(true);
  });
  m_service->RegisterCommandProcessor(QueryInvestorPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
    RequireQryPosition(false);
  });
  m_service->RegisterCommandProcessor(PositionCombInsert::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqDcePositionCombInsert(command);
  });
  m_position_view = m_service->m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_service->m_user_key && pos->unit_id == 0;
  });
  m_timer = std::make_shared<boost::asio::deadline_timer>(*m_service->m_ioc);
  m_timer->expires_from_now(boost::posix_time::seconds(2));
  m_timer->async_wait([this](const boost::system::error_code& error) {
    if (!error) {
      RefreshPositionProfit();
    }
  });
}

void DtpUnitPositionAccountView::OnRspQryInvestorPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto position = std::static_pointer_cast<CThostFtdcInvestorPositionField>(msg->pMainField);
    m_qry_position_results.push_back(position);
  }
  if (msg->bIsLast) {
    ProcessQryPositionResults(!m_position_inited);
    m_qry_position_results.clear();
    if (!m_position_inited) {
      m_position_inited = true;
      if (m_service->m_options.enable_position_details && !m_position_view->GetNodes().empty()) {
        RequireQryPositionDetail();
      } else {
        ProcessCachedTrade();
        ProcessCachedOrder();
        m_trade_order_cache_cleared = true;
        if (m_position_trade_volume == 0 || m_position_trade_volume <= m_trade_volume) {
          m_position_ready = true;
          m_service->m_node_db->ReplaceRecord<LoginContent>(
            m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
              p->user_key = m_service->m_user_key;
              p->backend = BackEnd::kDtp;
              p->position_ready = true;
            });
        }
      }
      UpdateAccountProfit(true);
    }
  }
}

void DtpUnitPositionAccountView::OnRspQryInvestorPositionDetail(std::shared_ptr<SpiMessage> msg) {
  if (m_trading_day.empty() || m_trade_order_cache_cleared)
    return;
  if (msg->pMainField != nullptr) {
    auto position_detail = std::static_pointer_cast<CThostFtdcInvestorPositionDetailField>(msg->pMainField);
    std::string symbol = std::string(position_detail->ExchangeID) + "." + std::string(position_detail->InstrumentID);
    FCASSERT(!symbol.empty());
    m_qry_position_detail_results[symbol].push_back(position_detail);
  }
  if (msg->bIsLast) {
    UpdatePositionDetail();
    m_qry_position_detail_results.clear();
    ProcessCachedTrade();
    ProcessCachedOrder();
    m_trade_order_cache_cleared = true;
    if (m_position_trade_volume == 0 || m_position_trade_volume <= m_trade_volume) {
      m_position_ready = true;
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_service->m_user_key;
          p->backend = BackEnd::kDtp;
          p->position_ready = true;
        });
    }
    UpdateAccountProfit();
  }
}

void DtpUnitPositionAccountView::OnRspQryTradingAccount(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto account = std::static_pointer_cast<CThostFtdcTradingAccountField>(msg->pMainField);
    m_qry_account_results.push_back(account);
  }
  if (msg->bIsLast) {
    ProcessQryAccountResults();
    m_qry_account_results.clear();
    UpdateAccountProfit();
    if (!m_account_inited) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_service->m_user_key;
          p->backend = BackEnd::kDtp;
          p->account_ready = true;
        });
      m_account_inited = true;
    }
    if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
      SetCommandFinished(req);
  }
}

