      target_account->user_key = m_service->m_user_key;
      target_account->currency = dtp_account->CurrencyID;
      target_account->investor_id = dtp_account->AccountID;
      target_account->available = dtp_account->Available;
      target_account->client_equity = dtp_account->Balance;
      target_account->close_profit = dtp_account->CloseProfit;
      target_account->commission = dtp_account->Commission;
      target_account->deposit = dtp_account->Deposit;
      target_account->frozen_commission = dtp_account->FrozenCommission;
      target_account->frozen_margin = dtp_account->FrozenMargin;
      target_account->margin = dtp_account->CurrMargin;
      target_account->position_profit = dtp_account->PositionProfit;
      target_account->pre_balance = dtp_account->PreBalance;
      target_account->withdraw = dtp_account->Withdraw;
      target_account->premium = dtp_account->CashIn;
      target_account->frozen_premium = dtp_account->FrozenCash;
      target_account->balance = target_account->client_equity + target_account->option_market_value;
      if (target_account->client_equity > 0) {
        target_account->risk_ratio = target_account->margin / target_account->client_equity;
      }
      if (target_account->balance > 0) {
        target_account->ref_risk_ratio = target_account->margin / target_account->balance;
      }
      target_account->withdraw_quota = dtp_account->WithdrawQuota;
      target_account->reserve = dtp_account->Reserve;
      target_account->pre_mortgage = dtp_account->PreMortgage;
      target_account->pre_credit = dtp_account->PreCredit;
      target_account->credit = dtp_account->Credit;
      target_account->delivery_margin = dtp_account->DeliveryMargin;
      target_account->mortgage = dtp_account->Mortgage;
      target_account->pre_fund_mortgagein = dtp_account->PreFundMortgageIn;
      target_account->pre_fund_mortgageout = dtp_account->PreFundMortgageOut;
