namespace dtp {
DtpQueryPlanner::DtpQueryPlanner(structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("query_planner", reinterpret_cast<int64_t>(this)).Clone()) {
  m_controller = std::make_shared<DtpQueryController>(m_logger);
  m_duplicate = std::make_shared<DtpQueryDuplicate>(m_controller.get(), m_logger);
  m_waiting = std::make_shared<DtpQueryWaiting>(m_controller.get(), m_duplicate.get(), m_logger);
  m_cooling = std::make_shared<DtpQueryCooling>(m_waiting.get(), m_logger);
}

void DtpQueryPlanner::AddTask(const std::string& key, QueryPriority priority, int request_id,
  std::function<int(int)> query_func, int cooling_off, bool critical, std::shared_ptr<UserCommand> command) {
  auto task = std::make_shared<QueryTask>();
  task->key = key;
  task->priority = priority;
  task->query_func = query_func;
  task->request_id = request_id;
  task->cooling_off = cooling_off;
  task->critical = critical;
  task->command = command;
  m_cooling->AddTask(task);
}

void DtpQueryPlanner::RunOnce() {
  m_controller->RunOnce();
  m_duplicate->RunOnce();
  m_cooling->RunOnce();
}

void DtpQueryPlanner::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  m_controller->ProcessSpiMsg(spi_msg);
}

