/*******************************************************************************
 * @file dtp_query_duplicate.cpp
 * @brief DTP 查询去重
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "dtp_query_duplicate.h"
#include <list>
#include <memory>
#include "dtp_query_controller.h"
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace dtp {

DtpQueryDuplicate::DtpQueryDuplicate(DtpQueryController* controller, structlog::Logger& parent_logger)
  : m_controller(controller)
  , m_logger(parent_logger.With("query_duplicate", reinterpret_cast<int64_t>(this)).Clone()) {
  m_controller->RegisterQueryTaskCallBack([this](std::shared_ptr<QueryTask> task) {
    ProcessFinishTask(task);
  });
}

void DtpQueryDuplicate::AddTask(std::shared_ptr<QueryTask> task, bool run) {
  if (m_task_set.insert(task->key).second)
    m_controller->AddTask(task, run);
  if (task->command)
    m_task_commands[task->key].push_back(task->command);
}

void DtpQueryDuplicate::RunOnce() {
  for (auto it = m_waiting_commands.begin(); it != m_waiting_commands.end();) {
    if (SetCommandsFinished(it->first, it->second)) {
      it = m_waiting_commands.erase(it);
    } else {
      ++it;
    }
  }
}

void DtpQueryDuplicate::ProcessFinishTask(std::shared_ptr<QueryTask> task) {
  m_task_set.erase(task->key);
  auto it_command = m_task_commands.find(task->key);
  if (it_command != m_task_commands.end()) {
    FCASSERT(task->command);
    if (!SetCommandsFinished(task->command, it_command->second)) {
      auto& commands = m_waiting_commands[task->command];
      commands.splice(commands.end(), it_command->second);
    }
    m_task_commands.erase(it_command);
  }
}

bool DtpQueryDuplicate::SetCommandsFinished(
  std::shared_ptr<UserCommand> command, std::list<std::shared_ptr<UserCommand>>& commands) {
  if (nullptr == command || command->status != UserCommand::Status::kFinished)
    return false;
  for (auto it = commands.begin(); it != commands.end();) {
    if (nullptr == (*it) || (*it)->status == UserCommand::Status::kFinished) {
      it = commands.erase(it);
      continue;
    } else {
      SetCommandFinished(*it, command->result_code, command->result_msg);
      ++it;
    }
  }
  return true;
}

}  // namespace dtp
}  // namespace future
}  // namespace fclib

/*******************************************************************************
 * @file dtp_query_waiting.cpp
 * @brief DTP 查询等待
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "dtp_query_waiting.h"

#include "dtp_query_controller.h"
#include "dtp_query_duplicate.h"
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {
namespace dtp {

DtpQueryWaiting::DtpQueryWaiting(
  DtpQueryController* controller, DtpQueryDuplicate* duplicate, structlog::Logger& parent_logger)
  : m_controller(controller)
  , m_duplicate(duplicate)
  , m_logger(parent_logger.With("query_waiting", reinterpret_cast<int64_t>(this)).Clone()) {
  m_controller->RegisterQueryTaskCallBack([this](std::shared_ptr<QueryTask> task) {
    if (task != m_running_task)
      return;
    m_running_task.reset();
    if (m_task_cache.empty())
      return;
    FCASSERT(task->key == m_task_cache.front()->key);
    for (const auto& t : m_task_cache) {
      m_duplicate->AddTask(t, false);
    }
    m_task_cache.clear();
  });
}

void DtpQueryWaiting::AddTask(std::shared_ptr<QueryTask> task) {
  if (!m_running_task)
    m_running_task = m_controller->GetRunningTask();
  FCASSERT(m_running_task == m_controller->GetRunningTask());
  if (!m_running_task || m_running_task->key != task->key) {
    m_duplicate->AddTask(task, true);
    return;
  }
  m_task_cache.push_back(task);
}
}  // namespace dtp
}  // namespace future
}  // namespace fclib

/*******************************************************************************
 * @file dtp_query_cooling.cpp
 * @brief DTP 查询冷静
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "dtp_query_cooling.h"
#include <memory>
#include "dtp_query_waiting.h"

namespace fclib {
namespace future {
namespace dtp {

DtpQueryCooling::DtpQueryCooling(DtpQueryWaiting* waiting, structlog::Logger& parent_logger)
  : m_waiting(waiting)
  , m_logger(parent_logger.With("query_cooling", reinterpret_cast<int64_t>(this)).Clone())
  , m_unique_key(0) {}

void DtpQueryCooling::AddTask(std::shared_ptr<QueryTask> task) {
  if (task->cooling_off <= 0) {
    m_waiting->AddTask(task);
    return;
  }
  auto it = m_task_map.find(task->key);
  if (it != m_task_map.end()) {
    it->second->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
  } else {
    m_task_map[task->key] = task;
    task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    m_cooling_queue.push_back(task);
  }
  m_cooling_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
    return a->cooling_end_time < b->cooling_end_time;
  });
}

void DtpQueryCooling::RunOnce() {
  while (!m_cooling_queue.empty()) {
    auto now = m_cooling_off_timer.GetTime();
    auto t = m_cooling_queue.front();
    if (t->cooling_end_time > now)
      break;
    // 移除
    m_cooling_queue.pop_front();
    m_task_map.erase(t->key);
    // 发送
    t->key += std::to_string(++m_unique_key);
    m_waiting->AddTask(t);
  }
}

}  // namespace dtp
}  // namespace future
}  // namespace fclib

