void DtpMockApi::InitPositions(int quantity) {
  m_helper->VisitShmInstrument([=, &quantity](const shm::ShmInstrument* ins) {
    if (quantity--) {
      const auto exchange_id = std::string(ins->exchange_id.data());
      m_mock_positions.push(GeneratePosition(ins));
      if (quantity % 7 == 0) {
        auto short_field = GeneratePosition(ins);
        short_field->PosiDirection = THOST_FTDC_PD_Short;
        m_mock_positions.push(short_field);
      }
      if (quantity % 13 == 0 && (exchange_id == "SHFE" || exchange_id == "INE")) {
        auto yesterday_field = GeneratePosition(ins);
        yesterday_field->PositionDate = THOST_FTDC_PSD_History;
        m_mock_positions.push(yesterday_field);
      }
      if (quantity % 181 == 0) {
        auto other_field = GeneratePosition(ins);
        other_field->HedgeFlag = (exchange_id == "CFFEX") ? THOST_FTDC_HF_Arbitrage : THOST_FTDC_HF_Hedge;
        m_mock_positions.push(other_field);
      }
      return true;
    }
    return false;
  });
}

void DtpMockApi::InitOrders(int order_quantity, int trade_quantity) {
  while (order_quantity--) {
    // each order will appear twice
    CThostFtdcOrderField order_field;
    GenerateOrder(&order_field);
    strcpy_x(order_field.OrderSysID, "");
    order_field.OrderStatus = THOST_FTDC_OST_Unknown;
    order_field.VolumeTotal = order_field.VolumeTotalOriginal;
    order_field.VolumeTraded = 0;
    strcpy_x(order_field.StatusMsg, Utf8ToGbk(u8"报单已提交"));
    // first status is unknown;
    m_spi->OnRtnOrder(&order_field);
    // change to next status
    strcpy_x(order_field.OrderSysID, std::to_string(m_order_id));
    order_field.OrderStatus = THOST_FTDC_OST_NoTradeQueueing;
    m_spi->OnRtnOrder(&order_field);
    // init trade
    if (trade_quantity--) {
      // order before
      order_field.OrderStatus = THOST_FTDC_OST_AllTraded;
      order_field.VolumeTotal = 0;
      order_field.VolumeTraded = order_field.VolumeTotalOriginal;
      strcpy_x(order_field.StatusMsg, Utf8ToGbk(u8"全部成交报单已提交"));
      m_spi->OnRtnOrder(&order_field);
      // trade after
      CThostFtdcTradeField trade_field;
      GenerateTrade(&order_field, &trade_field);
      m_spi->OnRtnTrade(&trade_field);
    }
  }
}

