  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
}

int TapInsertCancelOrder::RunOnce() {
  return 0;
}

void TapInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsAPIReady()) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  auto ins = m_service->m_md_helper->GetShmInstrument(req->exchange_id + "." + req->instrument_id, true);
  if (!ins.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 报单合约不存在");
    return;
  }
  const auto& product_class = ins->product_class;
  auto underlying = m_service->m_md_helper->GetShmInstrument(ins->underlying_symbol.data());
  auto leg1_node = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data());
  auto leg2_node = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data());
  if (product_class != md::ProductClass::kFuture && product_class != md::ProductClass::kOption
    && product_class != md::ProductClass::kCombine) {
    SetCommandFinished(req, -1, u8"fclib: 柜台仅支持期货/期权/组合交易");
    return;
  }

  if (product_class == md::ProductClass::kOption) {
    if (!underlying.has_value()) {
      SetCommandFinished(req, -1, u8"fclib: 期权合约缺少标的信息");
      return;
    }
  } else if (product_class == md::ProductClass::kCombine) {
    if (isnan(req->limit_price)) {
      SetCommandFinished(req, -1, u8"fclib: 组合合约报单价格无效");
      return;
    }
    if (!leg1_node.has_value() || !leg2_node.has_value()) {
      SetCommandFinished(req, -1, u8"fclib: 组合合约缺少单腿信息");
      return;
    }
    if (leg1_node->product_class != md::ProductClass::kFuture
      || leg2_node->product_class != md::ProductClass::kFuture) {
      SetCommandFinished(req, -1, u8"fclib: 组合合约报单仅支持期货组合");
      return;
    }
  }

  auto order_ref = req->order_ref;
  auto order_id = ToFclibOrderId(order_ref, m_service->m_login_node->Latest()->session_id);
  FCASSERT(order_id == req->order_id);
  m_service->m_send_time[order_id] = NowAsEpochNano();
  TapAPINewOrder field;
  memset(&field, 0, sizeof(field));

  // 设置默认值
  field.CallOrPutFlag = TAPI_CALLPUT_FLAG_NONE;
  field.CallOrPutFlag2 = TAPI_CALLPUT_FLAG_NONE;
  field.PositionEffect2 = TAPI_PositionEffect_NONE;
  field.IsRiskOrder = APIYNFLAG_NO;
  field.OrderSource = TAPI_ORDER_SOURCE_ESUNNY_API;
  field.TacticsType = TAPI_TACTICS_TYPE_NONE;
  field.TriggerCondition = TAPI_TRIGGER_CONDITION_NONE;
  field.TriggerPriceType = TAPI_TRIGGER_PRICE_NONE;
  field.AddOneIsValid = APIYNFLAG_NO;
  field.HedgeFlag2 = TAPI_HEDGEFLAG_NONE;
  field.MarketLevel = TAPI_MARKET_LEVEL_0;
  field.FutureAutoCloseFlag = APIYNFLAG_NO;

  strcpy_x(field.AccountNo, m_service->m_login_node->Latest()->investor_id);

  ConvertToTapExchangeID(req->exchange_id, &field.ExchangeNo);
  ConvertToTapTimeInForce(req->volume_condition, req->time_condition, &field.TimeInForce);
  ConvertToTapSide(req->direction, &field.OrderSide);
  ConvertToTapPositionEffect(req->offset, &field.PositionEffect);
  ConvertToTapHedgeFlag(req->hedge_flag, &field.HedgeFlag);

  field.OrderQty = req->volume;
  if (req->volume_condition == OrderVolumeCondition::kMin)
    field.OrderMinQty = req->min_volume;

  if (product_class == md::ProductClass::kCombine) {
    {
      // 跨期套利, 品种填写 A
      // 跨品种套利, 品种填写 A&B
      std::string leg1_commodity_no, leg2_commodity_no;
      ConvertToTapProductID(leg1_node, &leg1_commodity_no);
      ConvertToTapProductID(leg2_node, &leg2_commodity_no);
      FCASSERT(!leg1_commodity_no.empty() && !leg2_commodity_no.empty());
      if (leg1_commodity_no == leg2_commodity_no) {
        strcpy_x(field.CommodityNo, leg1_commodity_no);
        field.CommodityType = TAPI_COMMODITY_TYPE_SPREAD_MONTH;
      } else {
        strcpy_x(field.CommodityNo, leg1_commodity_no + "&" + leg2_commodity_no);
        field.CommodityType = TAPI_COMMODITY_TYPE_SPREAD_COMMODITY;
      }
    }
    // 两腿到期日
    ConvertToTapContractNo(leg1_node, &field.ContractNo);
    ConvertToTapContractNo(leg2_node, &field.ContractNo2);
    // 互换单
    if (req->is_swap_order) {
      field.OrderType = TAPI_ORDER_TYPE_SWAP;
      field.OrderPrice = req->limit_price;
      field.PositionEffect2 = (req->offset == Offset::kOpen) ? TAPI_PositionEffect_COVER : TAPI_PositionEffect_OPEN;
    } else {
      field.OrderPrice = req->limit_price;
      field.OrderType = TAPI_ORDER_TYPE_LIMIT;
    }
  } else {
    ConvertToTapCommodityType(product_class, &field.CommodityType);
    ConvertToTapProductID(ins, &field.CommodityNo);
    ConvertToTapContractNo(ins, &field.ContractNo);

    if (req->price_type == PriceType::kLimit) {
      field.OrderPrice = req->limit_price;
      field.OrderType = TAPI_ORDER_TYPE_LIMIT;
    } else {
      field.OrderType = TAPI_ORDER_TYPE_MARKET;
    }

    if (product_class == md::ProductClass::kOption) {
      field.CallOrPutFlag =
        ins->option_class == md::OptionClass::kCall ? TAPI_CALLPUT_FLAG_CALL : TAPI_CALLPUT_FLAG_PUT;
      int strike_price = static_cast<int>(ins->strike_price + 0.1);
      strcpy_x(field.StrikePrice, std::to_string(strike_price));
    }
  }

  field.RefInt = static_cast<int>(order_ref);
  strcpy_x(field.RefString, order_id);

  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + order_id);

  TAPIUINT32 sessionID = 0;
  int ret = m_service->m_api->InsertOrder(&sessionID, &field);
  if (ret < 0) {
    SetCommandFinished(req, ret, GetErrorMsg(ret));
  }
}

void TapInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_service->IsAPIReady()) {
    SetCommandFinished(req, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(Order::MakeKey(m_service->m_user_key, req->order_id));
  if (order_node == nullptr || order_node->Latest() == nullptr) {
    SetCommandFinished(req, -1, u8"fclib: 撤单委托不存在");
    return;
  }
  if (order_node->Latest()->status != OrderStatus::kAlive) {
    SetCommandFinished(req, -1, u8"fclib: 撤单委托已撤或已完全成交");
    return;
  }
  if (order_node->GetExtra() == nullptr) {
    SetCommandFinished(req, -1, u8"fclib: 撤单委托缺少撤单信息");
    return;
  }
  auto extra_info = std::static_pointer_cast<std::pair<std::string, char>>(order_node->GetExtra());

  TapAPIOrderCancelReq field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.OrderNo, extra_info->first);
  field.ServerFlag = extra_info->second;

  m_service->m_command_manager->SetCommandId(req, "ReqCancelOrder" + req->order_id);

  TAPIUINT32 sessionID = 0;
  int ret = m_service->m_api->CancelOrder(&sessionID, &field);
  if (ret < 0) {
    SetCommandFinished(req, ret, GetErrorMsg(ret));
  }
}

void TapInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
  if (field->OrderType == TAPI_ORDER_TYPE_COMB || field->OrderType == TAPI_ORDER_TYPE_UNCOMB)
    return;
  std::string order_id = IsRefValid(field->RefString) ? std::string(field->RefString) : std::string(field->OrderNo);
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(order_key);
  {
    auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update("ReqInsertOrder" + order_id));
    if (req) {
      req->order_pointer = order_node;
    }
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
  }
  {
    if (order_node && order_node->Latest() && order_node->Latest()->status == OrderStatus::kDead) {
      auto req =
        std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update("ReqCancelOrder" + order_id));
      SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    }
  }
}

