TapSettlement::TapSettlement(TapServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("settlement_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QuerySettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryBill(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryBill, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryBill(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnConnect, [this](std::shared_ptr<SpiMessage> msg) {
    OnConnect();
  });
}

int TapSettlement::RunOnce() {
  return 0;
}

void TapSettlement::OnRspQryBill(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto bill_info = std::static_pointer_cast<std::string>(msg->pMainField);
    if (!bill_info->empty())
      m_rsp_settlement_info[msg->SessionID].append(*bill_info);
  }
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("QuerySettlementInfo" + std::to_string(msg->SessionID));
    std::string rsp_info;
    if (msg->nErrorCode == 0) {
      rsp_info = GbkToUtf8(m_rsp_settlement_info[msg->SessionID]);
      m_rsp_settlement_info.erase(msg->SessionID);
    } else {
      rsp_info = GetErrorMsg(msg->nErrorCode);
    }
    SetCommandFinished(req, msg->nErrorCode, rsp_info);
  }
}

void TapSettlement::OnConnect() {
  m_rsp_settlement_info.clear();
}

void TapSettlement::ReqQryBill(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<QuerySettlementInfo>(command);
  if (!m_service->IsAPIReady()) {
    SetCommandFinished(command, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  if (request->trading_day.empty()) {
    SetCommandFinished(command, -1, u8"fclib: 查询结算单未指定交易日");
    return;
  }
  if (request->trading_day.size() < 6) {
    SetCommandFinished(command, -1, u8"fclib: 查询结算单交易日格式错误");
    return;
  }

  TapAPIBillQryReq field;
  memset(&field, 0, sizeof(TapAPIBillQryReq));
  strcpy_x(field.UserNo, m_service->m_login_node->Latest()->user_id);
  field.BillFileType = TAPI_BILL_FILE_TXT;
  std::string date = request->trading_day.substr(0, 4) + "-" + request->trading_day.substr(4, 2) + "-";
  if (request->trading_day.size() >= 8) {
    field.BillType = TAPI_BILL_DATE;
    date += request->trading_day.substr(6, 2);
  } else {
    field.BillType = TAPI_BILL_MONTH;
    date += "01";
  }
  strcpy_x(field.BillDate, date);

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryBill(&sessionID, &field);

  if (ret != 0) {
    SetCommandFinished(command, ret, GetErrorMsg(ret));
  }

  m_service->m_command_manager->SetCommandId(command, "QuerySettlementInfo" + std::to_string(sessionID));
}

