TapServiceImpl::TapServiceImpl(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger)
  : m_ioc(ioc)
  , m_user_key(user_key)
  , m_options(options)
  , m_node_db(node_db)
  , m_md_helper(helper)
  , m_logger(parent_logger.With("tap_service", reinterpret_cast<int64_t>(this)).Clone()) {
  m_func_units.push_back(std::make_shared<TapLogIn>(this, m_logger));
  m_func_units.push_back(std::make_shared<TapOrderTradeView>(this, m_logger));
  m_func_units.push_back(std::make_shared<TapInsertCancelOrder>(this, m_logger));
  m_func_units.push_back(std::make_shared<TapPositionAccount>(this, m_logger));
  m_func_units.push_back(std::make_shared<TapSettlement>(this, m_logger));
  m_func_units.push_back(std::make_shared<TapRate>(this, m_logger));
  std::shared_ptr<NodeDbView<Position>> position_view =
    m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
      return pos->user_key == m_user_key && pos->unit_id == 0;
    });
  m_dce_position_comb = std::make_shared<DcePositionAutoComb>(position_view, m_md_helper, m_logger);
}

TapServiceImpl::~TapServiceImpl() {}

void TapServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  command->status = UserCommand::Status::kStarted;
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: Tap柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

ServiceInterface::ServiceType TapServiceImpl::GetServiceType() {
  return ServiceInterface::ServiceType::kFuture;
}

void TapServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int TapServiceImpl::RunOnce() {
  // api运转一次
  int msg_count = 0;
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  while (!m_recv_queue.empty()) {
    auto msg = m_recv_queue.front();
    ProcessSpiMsg(msg);
    m_recv_queue.pop();
    ++msg_count;
  }
  if (msg_count == 0 && m_options.position_comb_auto) {
    m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
      ExecuteCommand(comb_insert);
    });
  }
  // 返回处理数据包数量
  return msg_count;
}

void TapServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_processor[tag] = processor;
}

void TapServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

int TapServiceImpl::BuildApi(std::shared_ptr<UserCommand> command) {
  SetLoginRequest(command);
  if (nullptr == m_req_login)
    return -1;

  DeleteApi();
  // 创建API实例
  TAPIINT32 result = TAPIERROR_SUCCEED;
  TapAPIApplicationInfo field;
  memset(&field, 0, sizeof(field));
  // strcpy_x(field.AuthCode, DEFAULT_AUTHCODE);
  // strcpy_x(field.KeyOperationLogPath, "");
  m_api = TapServiceImpl::TapApiCreator(&field, result);
  FCASSERT(nullptr != m_api);
  m_spi = new TapSpiHandler(m_ioc, m_logger, this);
  m_api->SetAPINotify(m_spi);

  // 设置交易前置
  for (const auto& front : m_req_login->broker.trading_fronts) {
    auto index = front.find("//");
    if (index == std::string::npos)
      return -1;
    auto ip_port = front.substr(index + 2);
    auto pos = ip_port.find(":");
    if (pos == std::string::npos)
      return -1;
    auto port_str = ip_port.substr(pos + 1);
    auto ip = ip_port.substr(0, pos);
    unsigned short port = (unsigned short)strtoul(port_str.c_str(), NULL, 0);
    if (TAPIERROR_SUCCEED != m_api->SetHostAddress(const_cast<char*>(ip.c_str()), port))
      return -1;
  }
  return 0;
}

void TapServiceImpl::DeleteApi() {
  if (nullptr == m_api)
    return;
  m_api->SetAPINotify(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  FreeTapTradeAPI(m_api);
  m_api = nullptr;
}

bool TapServiceImpl::IsAPIReady() {
  if (nullptr == m_login_node)
    m_login_node = m_node_db->GetNode<LoginContent>(m_user_key);
  if (nullptr == m_login_node)
    return false;
  if (nullptr == m_login_node->Latest() || m_login_node->Latest()->session_status != SessionStatus::kLogined)
    return false;
  return m_login_node->Latest()->account_ready && m_login_node->Latest()->position_ready;
}

int TapServiceImpl::SetLoginRequest(std::shared_ptr<UserCommand> command) {
  if (nullptr == command)
    return 0;
  auto cd = m_command_manager->Update(command);
  if (command->aid == ReqLogin::AID) {
    m_req_login = std::static_pointer_cast<ReqLogin>(cd);
    m_change_passwd_before_login = false;
  } else if (command->aid == ChangePasswordBeforeLogin::AID) {
    m_req_login = std::static_pointer_cast<ChangePasswordBeforeLogin>(cd)->req_login;
    m_change_passwd_before_login = true;
  } else {
    return -1;
  }
  return 0;
}

void TapServiceImpl::CleanUp() {}

std::function<ITapTradeAPI*(const TapAPIApplicationInfo*, TAPIINT32&)> TapServiceImpl::TapApiCreator =
  [](const TapAPIApplicationInfo* appInfo, TAPIINT32& iResult) -> ITapTradeAPI* {
  return CreateTapTradeAPI(appInfo, iResult);
};

