struct SpiMessage {
  SpiMessage() {
    SessionID = 0;
    nErrorCode = 0;
    bIsLast = true;
  }
  enum class Tag {
    OnConnect = 1,
    OnRspLogin,
    OnApiReady,
    OnDisconnect,
    OnRspChangePassword,
    OnRspQryAccount,
