bool IsRefValid(const std::string& ref) {
  auto pos = ref.find("_fclib_");
  return pos != std::string::npos;
}

std::string GetSessionID(const std::string& ref) {
  std::string ret;
  auto pos = ref.find("_fclib_");
  if (pos == std::string::npos)
    return ret;
  return ref.substr(pos + 7);
}

TapOrderTradeView::TapOrderTradeView(TapServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryFill, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryFill(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnFill, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnFill(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnConnect, [this](std::shared_ptr<SpiMessage> msg) {
    OnConnect();
  });
}

int TapOrderTradeView::RunOnce() {
  return 0;
}

void TapOrderTradeView::OnRspQryPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->bIsLast) {
    RequireQryOrder();
    RequireQryFill();
  }
}

void TapOrderTradeView::OnRspQryOrder(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != 0)
    m_logger.With("OnRspQryOrder", GetErrorMsg(msg->nErrorCode)).Error("on rsp order error");

  if (msg->pMainField != nullptr) {
    auto order = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
    m_rsp_order_results.push_back(std::pair(order, msg->nErrorCode));
  }
  if (msg->bIsLast) {
    ProcessQryOrderResults();
    ProcessQryTradeResults();
    ProcessRtnTradeResults();
    if (!m_order_inited) {
      m_order_inited = true;
    }
  }
}

void TapOrderTradeView::OnRspQryFill(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != 0)
    m_logger.With("OnRspQryFill", GetErrorMsg(msg->nErrorCode)).Error("on rsp fill error");

  if (msg->pMainField != nullptr) {
    auto fill = std::static_pointer_cast<TapAPIFillInfo>(msg->pMainField);
    m_rsp_trade_results.push_back(fill);
  }
  if (msg->bIsLast) {
    // 委托单处理完再处理成交
    if (m_order_inited) {
      ProcessQryTradeResults();
      if (!m_trade_inited) {
        m_trade_inited = true;
      }
    }
  }
}

void TapOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField || !m_order_inited)
    return;
  auto field = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
  if (field->OrderType == TAPI_ORDER_TYPE_COMB || field->OrderType == TAPI_ORDER_TYPE_UNCOMB)
    return;
  ProcessOrderResult(field, msg->nErrorCode);
  ProcessRtnTradeResults();
}

void TapOrderTradeView::OnRtnFill(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField || !m_trade_inited)
    return;
  auto field = std::static_pointer_cast<TapAPIFillInfo>(msg->pMainField);
  if (!ProcessTradeResult(field))
    m_rtn_trade_results.push_back(field);
}

void TapOrderTradeView::OnConnect() {
  m_order_inited = false;
  m_trade_inited = false;

  m_rsp_order_results.clear();
  m_order_mapping.clear();

  m_rsp_trade_results.clear();
  m_rtn_trade_results.clear();
}

void TapOrderTradeView::RequireQryOrder() {
  if (m_service->m_change_passwd_before_login)
    return;

  TapAPIOrderQryReq field;
  memset(&field, 0, sizeof(TapAPIOrderQryReq));
  field.OrderQryType = TAPI_ORDER_QRY_TYPE_ALL;

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryOrder(&sessionID, &field);
  if (ret != 0) {
    m_logger.With("RequireQryOrder", GetErrorMsg(ret)).Error("query order error");
  }
}

void TapOrderTradeView::RequireQryFill() {
  if (m_service->m_change_passwd_before_login)
    return;

  TapAPIFillQryReq field;
  memset(&field, 0, sizeof(TapAPIFillQryReq));

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryFill(&sessionID, &field);
  if (ret != 0) {
    m_logger.With("RequireQryFill", GetErrorMsg(ret)).Error("query fill error");
  }
}

void TapOrderTradeView::ProcessQryOrderResults() {
  for (const auto& [field, code] : m_rsp_order_results) {
    ProcessOrderResult(field, code);
  }
  m_rsp_order_results.clear();
}

void TapOrderTradeView::ProcessOrderResult(std::shared_ptr<TapAPIOrderInfo> field, TAPIINT32 error_code) {
  std::string order_id = IsRefValid(field->RefString) ? std::string(field->RefString) : std::string(field->OrderNo);
  std::string session_id = GetSessionID(field->RefString);
  if (order_id.empty())
    return;
  if (field->OrderNo[0] != '\0')
    m_order_mapping[field->OrderNo] = order_id;
  // 赋值字段
  auto order_key = m_service->m_user_key + "|" + order_id;

  std::string exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  std::string instrument_id;

  if (exchange_id.empty() || field->CommodityNo[0] == '\0') {
    auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update("ReqInsertOrder" + order_id));
    if (nullptr == req)
      return;
    exchange_id = req->exchange_id;
    instrument_id = req->instrument_id;
  } else {
    exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
    instrument_id = ConvertToFclibInstrumentID(field.get());
  }

  if (exchange_id.empty() || instrument_id.empty())
    return;
  auto ins = m_service->m_md_helper->GetShmInstrument(exchange_id + "." + instrument_id, true);
  FCASSERT(ins.has_value() && ins->instrument_id.data() == instrument_id);

  auto order_node = m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> order) {
    if (order->order_id.empty()) {
      order->user_key = m_service->m_user_key;
      order->user_id = m_service->m_req_login->user_id;
      order->order_id = order_id;
      auto iter = m_service->m_send_time.find(order->order_id);
      if (iter != m_service->m_send_time.end()) {
        order->send_date_time = iter->second;
        m_service->m_send_time.erase(iter);
      }
      order->receive_date_time = NowAsEpochNano();
      order->order_local_id = field->OrderLocalNo;
      order->session_id = 0;
      if (!session_id.empty() && std::all_of(session_id.begin(), session_id.end(), ::isdigit))
        order->session_id = std::stoll(session_id);
      order->order_ref = std::to_string(field->RefInt);
      if (order->order_ref.empty())
        order->order_ref = field->OrderNo;
      order->trader_id = field->OrderCommandUserNo;
      order->investor_id = field->AccountNo;

      order->exchange_id = ins->exchange_id.data();
      order->instrument_id = ins->instrument_id.data();

      order->direction = ConvertFromTapSide(&field->OrderSide);
      order->offset = ConvertFromTapPositionEffect(&field->PositionEffect, ins->HasCloseToday());
      order->hedge_flag = ConvertFromTapHedgeFlag(&field->HedgeFlag);
      order->force_close_reason = ForceCloseReason::kNotForceClose;

      order->volume_orign = field->OrderQty;

      if (field->OrderType == TAPI_ORDER_TYPE_LIMIT) {
        order->limit_price = field->OrderPrice;
      }
    }

    order->exchange_order_id = field->OrderSystemNo;
    order->volume_left = field->OrderQty - field->OrderMatchQty;
    order->status = ConvertFromTapOrderStatus(&field->OrderState);
    order->is_swap_order = field->OrderType == TAPI_ORDER_TYPE_SWAP;

    if (field->OrderType == TAPI_ORDER_TYPE_MARKET) {
      order->time_condition = OrderTimeCondition::kIoc;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->price_type = PriceType::kAny;
    } else {
      order->time_condition = OrderTimeCondition::kGfd;
      order->volume_condition = OrderVolumeCondition::kAny;
      order->price_type = PriceType::kLimit;
    }

    if (field->TimeInForce == TAPI_ORDER_TIMEINFORCE_GFD) {
      order->time_condition = OrderTimeCondition::kGfd;
    } else if (field->TimeInForce == TAPI_ORDER_TIMEINFORCE_GTC) {
      order->time_condition = OrderTimeCondition::kGtc;
    } else if (field->TimeInForce == TAPI_ORDER_TIMEINFORCE_GTD) {
      order->time_condition = OrderTimeCondition::kGtd;
    } else if (field->TimeInForce == TAPI_ORDER_TIMEINFORCE_FAK) {
      order->time_condition = OrderTimeCondition::kIoc;
      order->volume_condition = OrderVolumeCondition::kAny;
    } else if (field->TimeInForce == TAPI_ORDER_TIMEINFORCE_FOK) {
      order->time_condition = OrderTimeCondition::kIoc;
      order->volume_condition = OrderVolumeCondition::kAll;
    }

    if (field->OrderMinQty > 0) {
      order->min_volume = field->OrderMinQty;
      order->volume_condition = OrderVolumeCondition::kMin;
    }

    if (field->ErrorCode != 0) {
      order->status_msg = (field->ErrorText[0] == '\0') ? GetErrorMsg(field->ErrorCode)
                                                        : u8"易盛启明星v9: " + GbkToUtf8(field->ErrorText);
    } else if (error_code != 0) {
      order->status_msg = GetErrorMsg(error_code);
    }

    if (order->insert_date_time <= 0 && field->OrderInsertTime[0] != '\0') {
      // field->OrderInsertTime 格式: 230607134529.954860
      std::string time = "20";
      time += field->OrderInsertTime;
      order->insert_date_time = GetRealTradeTime(time.substr(0, 8).c_str(), time.substr(8, 6).c_str());
    }
    if (order->status == OrderStatus::kDead && order->volume_left > 0 && order->dead_date_time <= 0
      && (field->OrderUpdateTime[0] != '\0' || field->OrderInsertTime[0] != '\0')) {
      std::string time = "20";
      time += field->OrderUpdateTime[0] != '\0' ? field->OrderUpdateTime : field->OrderInsertTime;
      order->dead_date_time = GetRealTradeTime(time.substr(0, 8).c_str(), time.substr(8, 6).c_str());
    }
    auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Get("ReqInsertOrder" + order_id));
    if (req) {
      order->request_id = std::to_string(req->request_id);
    }
  });
  auto extra_info = std::make_shared<std::pair<std::string, char>>();
  extra_info->first = field->OrderNo;
  extra_info->second = field->ServerFlag;
  if (order_node->GetExtra() == nullptr) {
    order_node->SetExtra(extra_info);
  }
}

void TapOrderTradeView::ProcessQryTradeResults() {
  for (auto it = m_rsp_trade_results.begin(); it != m_rsp_trade_results.end();) {
    if (ProcessTradeResult(*it)) {
      it = m_rsp_trade_results.erase(it);
    } else {
      ++it;
    }
  }
}

void TapOrderTradeView::ProcessRtnTradeResults() {
  for (auto it = m_rtn_trade_results.begin(); it != m_rtn_trade_results.end();) {
    if (ProcessTradeResult(*it)) {
      it = m_rtn_trade_results.erase(it);
    } else {
      ++it;
    }
  }
}

bool TapOrderTradeView::ProcessTradeResult(std::shared_ptr<TapAPIFillInfo> field) {
  auto it = m_order_mapping.find(field->OrderNo);
  if (it == m_order_mapping.end())
    return false;
  auto order_id = it->second;
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(order_key);
  const auto exchange_order_id = order_node->Latest()->exchange_order_id;
  if (nullptr == order_node || exchange_order_id.empty())
    return false;

  auto exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  auto instrument_id = ConvertToFclibInstrumentID(field.get());
  auto ins = m_service->m_md_helper->GetShmInstrument(exchange_id + "." + instrument_id, true);

  FCASSERT(field->ExchangeMatchNo[0] != '\0');
  auto trade_key = Trade::MakeKey(m_service->m_user_key, field->ExchangeMatchNo, exchange_order_id);

  auto trade_node = m_service->GetNodeDb()->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    if (trade->user_key.empty()) {
      trade->user_key = m_service->m_user_key;
      trade->user_id = m_service->m_req_login->user_id;
      trade->investor_id = field->AccountNo;

      trade->exchange_id = exchange_id;
      trade->instrument_id = instrument_id;
      trade->exchange_trade_id = field->ExchangeMatchNo;
      trade->exchange_order_id = exchange_order_id;

      trade->trader_id = order_node->Latest()->trader_id;
      trade->order_local_id = field->OrderLocalNo;

      trade->direction = ConvertFromTapSide(&field->MatchSide);
      trade->offset = ConvertFromTapPositionEffect(&field->PositionEffect, ins->HasCloseToday());
      trade->hedge_flag = ConvertFromTapHedgeFlag(&field->HedgeFlag);

      trade->order_id = order_node->Latest()->order_id;
      trade->unit_id = order_node->Latest()->unit_id;
      trade->order_pointer = order_node;
    }

    trade->price = field->MatchPrice;
    trade->volume = field->MatchQty;
    trade->commission = field->FeeValue;
    // 成交时间 2023-06-13 10:37:19
    trade->trade_date_time = GetRealTradeTime(field->MatchDateTime, field->MatchDateTime + 11);
  });
  return true;
}

