TapRate::TapRate(TapServiceImpl *service, structlog::Logger &parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    QryAccountRent(command);
  });
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    QryAccountRent(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspAccountRentInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspAccountRentInfo(msg);
  });
}

void TapRate::QryAccountRent(std::shared_ptr<UserCommand> command) {
  if (m_rate_ready) {
    SetCommandFinished(command);
    return;
  }

  TapAPIAccountRentQryReq field;
  memset(&field, 0, sizeof(TapAPIAccountRentQryReq));
  strcpy_x(field.AccountNo, m_service->m_login_node->Latest()->investor_id);

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryAccountRent(&sessionID, &field);

  if (ret != 0) {
    SetCommandFinished(command, ret, GetErrorMsg(ret));
    m_logger.With("RequireAccountRent", GetErrorMsg(ret)).Error("query rent error");
  }
}

std::string CalcInstrumentID(const TapAPIAccountRentInfo *field) {
  auto exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  auto instrument_id = std::string(field->CommodityNo);
  if (exchange_id != "CFFEX" && exchange_id != "CZCE")
    transform(instrument_id.begin(), instrument_id.end(), instrument_id.begin(), ::tolower);
  instrument_id += field->ContractNo;
  FCASSERT(!exchange_id.empty() && !instrument_id.empty());
  return instrument_id;
}

void TapRate::UpdateRate(const std::string &key, const TapAPIAccountRentInfo *field) {
  m_service->GetNodeDb()->ReplaceRecord<Rate>(
    m_service->m_user_key + "|" + key, [&](std::shared_ptr<future::Rate> rate) {
      rate->user_key = m_service->m_user_key;
      rate->instrument_id = key;
      rate->commission_rate_close = UnitRate(field->ClosedTurnover, field->ClosedVolume);
      rate->commission_rate_close_today = UnitRate(field->CloseNewTurnover, field->CloseNewVolume);
      rate->commission_rate_exec = UnitRate(0.0, 0.0);
      rate->commission_rate_open = UnitRate(field->OpenTurnover, field->OpenVolume);
      rate->margin_rate_long_other = UnitRate(field->BuyBInitMargin, field->BuyBMaintMargin);
      rate->margin_rate_long_spec = UnitRate(field->BuyTInitMargin, field->BuyTMaintMargin);
      rate->margin_rate_short_other = UnitRate(field->SellBInitMargin, field->SellBMaintMargin);
      rate->margin_rate_short_spec = UnitRate(field->SellTInitMargin, field->SellTMaintMargin);
    });
}

void TapRate::OnRspAccountRentInfo(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField) {
    return;
  }
  if (0 == msg->nErrorCode) {
    m_rate_ready = true;
  }
  auto field = std::static_pointer_cast<TapAPIAccountRentInfo>(msg->pMainField);
  std::string instrument_id = CalcInstrumentID(field.get());
  // 如果是期权费率
  if (field->CommodityType == 'O') {
    std::string ins_key = std::string(field->ExchangeNo) + "." + instrument_id;
    auto derivet_sets = m_service->m_md_helper->GetDerivativeInstruments(ins_key);

    for (auto const &key : derivet_sets) {
      UpdateRate(key, field.get());
    }
  } else {
    UpdateRate(instrument_id, field.get());
  }

  auto req = m_service->m_command_manager->Update(instrument_id);
  if (req) {
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
  }
}

int TapRate::RunOnce() {
  return 0;
}

