static const std::set<std::string> ProductCombi = {"A&M", "Y&P", "L&V", "J&JM", "L&PP", "V&PP", "I&JM", "I&J", "C&CS",
  "B&M", "EB&EG", "EB&L", "A&B", "EB&PP", "EB&V", "EG&L", "EG&PP", "EG&V", "PG&L", "PG&PP", "PG&V", "PG&EB", "PG&EG",
  "CF&CY", "FG&SA", "SF&SM", "TA&PF"};

TapPositionAccount::TapPositionAccount(TapServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    QueryAccount(command);
  });
  m_service->RegisterCommandProcessor(PositionCombAuto::AID, [this](std::shared_ptr<UserCommand> command) {
    auto req = std::static_pointer_cast<PositionCombAuto>(m_service->m_command_manager->Update(command));
    m_service->m_options.position_comb_auto = req->auto_combi;
    m_logger.With("position_comb_auto", m_service->m_options.position_comb_auto).Info("PositionCombAuto");
    SetCommandFinished(command);
  });
  m_service->RegisterCommandProcessor(PositionCombInsert::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqDcePositionCombInsert(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryAccount(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryFund, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryFund(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnFund, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnFund(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnPositionProfit, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnPositionProfit(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCombInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnConnect, [this](std::shared_ptr<SpiMessage> msg) {
    OnConnect();
  });
}

void TapPositionAccount::QueryAccount(std::shared_ptr<UserCommand> command) {
  // Tap 柜台资金主动推送, 资金截面永远保持最新
  if (!m_service->IsAPIReady()) {
    SetCommandFinished(command, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  SetCommandFinished(command);
}

void TapPositionAccount::ReqDcePositionCombInsert(std::shared_ptr<UserCommand> command) {
  auto comb_command = std::static_pointer_cast<PositionCombInsert>(m_service->m_command_manager->Update(command));
  auto ins =
    m_service->m_md_helper->GetShmInstrument(comb_command->exchange_id + "." + comb_command->instrument_id, true);
  auto leg1 = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
  auto leg2 = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
  TapAPINewOrder field;
  memset(&field, 0, sizeof(field));
  field.CallOrPutFlag = TAPI_CALLPUT_FLAG_NONE;
  field.CallOrPutFlag2 = TAPI_CALLPUT_FLAG_NONE;
  field.IsRiskOrder = APIYNFLAG_NO;
  field.OrderSource = TAPI_ORDER_SOURCE_ESUNNY_API;
  field.TacticsType = TAPI_TACTICS_TYPE_NONE;
  field.TriggerCondition = TAPI_TRIGGER_CONDITION_NONE;
  field.TriggerPriceType = TAPI_TRIGGER_PRICE_NONE;
  field.AddOneIsValid = APIYNFLAG_NO;
  field.MarketLevel = TAPI_MARKET_LEVEL_0;
  field.FutureAutoCloseFlag = APIYNFLAG_NO;
  field.TimeInForce = TAPI_ORDER_TIMEINFORCE_GFD;
  field.PositionEffect = TAPI_PositionEffect_NONE;
  field.PositionEffect2 = TAPI_PositionEffect_NONE;

  field.OrderQty = comb_command->volume;
  field.OrderQty2 = comb_command->volume;
  strcpy_x(field.AccountNo, m_service->m_login_node->Latest()->investor_id);
  ConvertToTapExchangeID(comb_command->exchange_id, &field.ExchangeNo);
  ConvertToTapHedgeFlag(comb_command->hedge_flag, &field.HedgeFlag);
  ConvertToTapHedgeFlag(comb_command->hedge_flag, &field.HedgeFlag2);
  ConvertToTapSide(comb_command->direction, &field.OrderSide);
  field.OrderType =
    comb_command->comb_direction == CombDirection::kComb ? TAPI_ORDER_TYPE_COMB : TAPI_ORDER_TYPE_UNCOMB;

  std::string leg1_commodity_no, leg2_commodity_no;
  ConvertToTapProductID(leg1, &leg1_commodity_no);
  ConvertToTapProductID(leg2, &leg2_commodity_no);
  FCASSERT(!leg1_commodity_no.empty() && !leg2_commodity_no.empty());
  if (leg1_commodity_no == leg2_commodity_no) {
    strcpy_x(field.CommodityNo, leg1_commodity_no);
  } else {
    strcpy_x(field.CommodityNo, leg1_commodity_no + "&" + leg2_commodity_no);
  }
  field.CommodityType = ConvertToCommodityType(comb_command->instrument_id);
  // 两腿到期日
  ConvertToTapContractNo(leg1, &field.ContractNo);
  ConvertToTapContractNo(leg2, &field.ContractNo2);

  TAPIUINT32 sessionID = 0;
  int ret = m_service->m_api->InsertOrder(&sessionID, &field);
  m_service->m_command_manager->SetCommandId(comb_command, "ReqDcePositionCombInsert" + std::to_string(sessionID));
  m_logger.With("req", comb_command->ToJson())
    .With("ret", ret)
    .With("err", GetErrorMsg(ret))
    .With("sessionID", sessionID)
    .Info("ReqDcePositionCombInsert");
  if (ret < 0) {
    SetCommandFinished(comb_command, ret, GetErrorMsg(ret));
  }
}

void TapPositionAccount::OnRspCombInsert(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<PositionCombInsert>(
    m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::to_string(msg->SessionID)));
  if (!req)
    return;
  if (msg->nErrorCode != 0) {
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    return;
  }
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
  if (field->OrderType != TAPI_ORDER_TYPE_COMB && field->OrderType != TAPI_ORDER_TYPE_UNCOMB)
    return;
  if (field->OrderState == TAPI_ORDER_STATE_FAIL)
    SetCommandFinished(req, -1, u8"指令失败");
  else
    SetCommandFinished(req);
}

void TapPositionAccount::OnRspQryAccount(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode == 0 && msg->pMainField) {
    auto pAccountInfo = std::static_pointer_cast<TapAPIAccountInfo>(msg->pMainField);
    m_account_no = pAccountInfo->AccountNo;
    RequireQryFund();
    RequireQryPosition();
  }
}

void TapPositionAccount::OnRspQryFund(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != 0)
    m_logger.With("OnRspQryFund", GetErrorMsg(msg->nErrorCode)).Error("on rsp fund error");

  if (msg->pMainField != nullptr) {
    auto account = std::static_pointer_cast<TapAPIFundData>(msg->pMainField);
    m_qry_fund_results.push_back(account);
  }
  if (msg->bIsLast) {
    ProcessQryFundResults();
    m_qry_fund_results.clear();
    if (!m_account_inited) {
      m_account_inited = true;
    }
    if (nullptr == m_service->m_login_node || !m_service->m_login_node->Latest()->account_ready) {
      m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_service->m_user_key;
          p->backend = BackEnd::kTap;
          p->account_ready = true;
        });
    }
    if (auto req = m_service->m_command_manager->Update("RequireQryAccount"))
      SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
  }
}

void TapPositionAccount::OnRtnFund(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField || !m_account_inited)
    return;
  auto account = std::static_pointer_cast<TapAPIFundData>(msg->pMainField);
  ProcessFundResult(account);
}

void TapPositionAccount::OnRspQryPosition(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != 0)
    m_logger.With("OnRspQryPosition", GetErrorMsg(msg->nErrorCode)).Error("on rsp position error");

  if (msg->pMainField != nullptr) {
    auto position = std::static_pointer_cast<TapAPIPositionInfo>(msg->pMainField);
    m_qry_position_results[position->PositionNo] = position;
    ProcessCombPositionCaches(position);
  }
  if (msg->bIsLast) {
    m_qry_comb_position_caches.clear();
    ProcessQryPositionResults();
    ProcessQryCombPositionResults();
    ProcessRtnPositionProfitResults();
    if (!m_position_inited) {
      m_position_inited = true;
    }
    if (nullptr == m_service->m_login_node || !m_service->m_login_node->Latest()->position_ready) {
      m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
          p->user_key = m_service->m_user_key;
          p->backend = BackEnd::kTap;
          p->position_ready = true;
        });
    }
  }
}

void TapPositionAccount::OnRtnPosition(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField || !m_position_inited)
    return;
  auto position = std::static_pointer_cast<TapAPIPositionInfo>(msg->pMainField);
  auto it = m_qry_position_results.find(position->PositionNo);
  std::shared_ptr<TapAPIPositionInfo> prev_position = nullptr;
  if (it != m_qry_position_results.end())
    prev_position = it->second;
  ProcessPositionResult(false, position, prev_position);
  // 处理组合持仓
  std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>> prev_comb_position = {
    nullptr, nullptr};
  auto ret = ProcessCombPositionCaches(position, &prev_comb_position);
  if (nullptr != ret)
    ProcessCombPositionResult(false, GetCombInsNode(*ret), *ret, prev_comb_position);
  // 处理持仓盈亏
  ProcessRtnPositionProfitResults();
  m_qry_position_results[position->PositionNo] = position;
}

void TapPositionAccount::OnRtnPositionProfit(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto position_profit = std::static_pointer_cast<TapAPIPositionProfit>(msg->pMainField);
    m_rtn_position_profit_caches[position_profit->PositionNo] = position_profit;
    m_position_profit_last = false;
  }
  if (msg->bIsLast) {
    m_position_profit_last = true;
    if (m_position_inited)
      ProcessRtnPositionProfitResults();
  }
}

void TapPositionAccount::OnRspQryOrder(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto field = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
    if ((field->PositionEffect != TAPI_PositionEffect_OPEN && field->PositionEffect != TAPI_PositionEffect_NONE)
      || field->OrderType == TAPI_ORDER_TYPE_SWAP)
      m_rsp_order_results.push_back(std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField));
  }
  if (msg->bIsLast) {
    ProcessRspOrderResults();
  }
}

void TapPositionAccount::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField != nullptr) {
    auto field = std::static_pointer_cast<TapAPIOrderInfo>(msg->pMainField);
    if (field->OrderType == TAPI_ORDER_TYPE_COMB || field->OrderType == TAPI_ORDER_TYPE_UNCOMB)
      return;
    if ((field->PositionEffect != TAPI_PositionEffect_OPEN && field->PositionEffect != TAPI_PositionEffect_NONE)
      || field->OrderType == TAPI_ORDER_TYPE_SWAP)
      ProcessOrderResult(field);
  }
}

void TapPositionAccount::OnConnect() {
  m_account_no.clear();

  m_account_inited = false;
  m_position_inited = false;
  m_position_profit_last = false;

  m_qry_fund_results.clear();
  m_qry_position_results.clear();

  m_qry_comb_position_results.clear();
  m_qry_comb_position_caches.clear();

  m_rtn_position_profit_results.clear();
  m_rtn_position_profit_caches.clear();

  m_rsp_order_results.clear();
  m_alive_order_results.clear();
}

void TapPositionAccount::RequireQryFund() {
  if (m_service->m_change_passwd_before_login)
    return;
  if (m_account_no.empty())
    return;

  TapAPIFundReq field;
  memset(&field, 0, sizeof(TapAPIFundReq));
  strcpy_x(field.AccountNo, m_account_no);
  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryFund(&sessionID, &field);

  if (ret != 0) {
    m_logger.With("RequireQryFund", GetErrorMsg(ret)).Error("query fund error");
  }
}

void TapPositionAccount::RequireQryPosition() {
  if (m_service->m_change_passwd_before_login)
    return;

  TapAPIPositionQryReq field;
  memset(&field, 0, sizeof(TapAPIPositionQryReq));
  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryPosition(&sessionID, &field);
  if (ret != 0) {
    m_logger.With("RequireQryPosition", GetErrorMsg(ret)).Error("query position error");
  }
}

void TapPositionAccount::ProcessQryFundResults() {
  for (const auto& result : m_qry_fund_results) {
    ProcessFundResult(result);
  }
}

void TapPositionAccount::ProcessFundResult(std::shared_ptr<TapAPIFundData> result) {
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, result->CurrencyNo);
  m_service->GetNodeDb()->ReplaceRecord<Account>(account_key, [=](std::shared_ptr<Account> target_account) {
    target_account->user_key = m_service->m_user_key;
    target_account->currency = result->CurrencyNo;
    target_account->investor_id = result->AccountNo;
    target_account->available = result->Available;
    target_account->client_equity = result->Equity;
    target_account->pre_balance = result->PreBalance;
    target_account->balance = result->Balance;
    target_account->position_profit = result->PositionProfit;
    target_account->close_profit = result->CloseProfit;
    target_account->float_profit = result->FloatingPL;

    target_account->commission = result->AccountFee;
    target_account->frozen_commission = result->FrozenFee;
    target_account->margin = result->AccountIntialMargin;
    target_account->frozen_margin = result->FrozenDeposit;
    target_account->premium = result->PremiumIncome - result->PremiumPay;
    target_account->frozen_premium = 0.0;

    target_account->withdraw = result->CashOutValue;
    target_account->deposit = result->CashInValue;

    target_account->option_market_value = result->OptionMarketValue;
    target_account->withdraw_quota = result->CanDraw;

    if (target_account->client_equity > 0) {
      target_account->risk_ratio = target_account->margin / target_account->client_equity;
    }
    if (target_account->balance > 0) {
      target_account->ref_risk_ratio = target_account->margin / target_account->balance;
    }

    target_account->mortgage = result->CashPledged;
    target_account->mortgageablefund = result->CashPledged;

    target_account->fund_mortgagein = result->PledgeIn;
    target_account->fund_mortgageout = result->PledgeOut;
    target_account->fund_mortgageavailable = result->PledgeValue;

    target_account->spec_product_margin = result->SpecialAccountMargin;
    target_account->spec_product_frozenmargin = result->SpecialAccountFrozenMargin;
    target_account->spec_product_commission = result->SpecialAccountFee;
    target_account->spec_product_frozen_commission = result->SpecialAccountFrozenFee;
    target_account->spec_product_position_profit = result->SpecialFloatProfit;
    target_account->spec_product_close_profit = result->SpecialCloseProfit;
  });
}

void TapPositionAccount::ProcessQryPositionResults() {
  std::set<std::string> cache;
  for (const auto& [_, origin_position] : m_qry_position_results) {
    auto ins = GetInsNode(origin_position);
    FCASSERT(ins.has_value());
    bool init = false;
    if (cache.find(ins->symbol.data()) == cache.end()) {
      cache.insert(ins->symbol.data());
      init = true;
    }
    ProcessPositionResult(init, origin_position);
  }
}

void TapPositionAccount::ProcessPositionResult(
  bool init, std::shared_ptr<TapAPIPositionInfo> origin_position, std::shared_ptr<TapAPIPositionInfo> prev_position) {
  auto ins = GetInsNode(origin_position);
  auto position_key = Position::MakeKey(m_service->m_user_key, 0, ins->symbol.data());
  m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
    if (target_position->user_key.empty()) {
      target_position->user_key = m_service->m_user_key;
      target_position->investor_id = origin_position->AccountNo;
      target_position->exchange_id = ins->exchange_id.data();
      target_position->instrument_id = ins->instrument_id.data();
    }
    if (init) {
      for (auto p : {&Position::subpos_long_spec, &Position::subpos_short_spec, &Position::subpos_long_other,
             &Position::subpos_short_other}) {
        auto sub_pos = &(target_position.get()->*p);
        sub_pos->volume_his = 0;
        sub_pos->volume_today = 0;
        sub_pos->volume_comb = 0;
        sub_pos->volume_today_frozen = 0;
        sub_pos->volume_his_frozen = 0;
        sub_pos->margin = 0;
        sub_pos->open_price = 0.0;
        sub_pos->position_price = 0.0;
        sub_pos->float_profit = 0.0;
        sub_pos->position_profit = 0.0;
        sub_pos->market_value = 0.0;
        sub_pos->his_position_details.clear();
        sub_pos->today_position_details.clear();
      }
    }

    future::SubPosition* subpos =
      GetSubPosition(target_position, origin_position->MatchSide, origin_position->HedgeFlag);
    if (nullptr == subpos)
      return;
    if (origin_position->HedgeFlag == TAPI_HEDGEFLAG_L)
      subpos->hedge_type = PositionHedgeType::kArbitrage;

    auto is_history = origin_position->IsHistory == APIYNFLAG_YES;
    auto pre_settlement = origin_position->PreSettlePrice;
    if (isnan(pre_settlement) || fabs(pre_settlement) < 1e-3)
      pre_settlement = ins->pre_settlement;
    FCASSERT(!isnan(pre_settlement));

    auto calc_price = origin_position->SettlePrice;
    if ((isnan(calc_price) || fabs(calc_price) < 1e-3) && (!isnan(ins->last_price)))
      calc_price = ins->last_price;
    if (isnan(calc_price))
      calc_price = ins->pre_settlement;
    FCASSERT(!isnan(calc_price));
    target_position->last_price = calc_price;

    auto delta_volume = origin_position->PositionQty;
    auto delta_margin = origin_position->AccountInitialMargin;
    auto delta_open_cost = origin_position->PositionQty * origin_position->PositionPrice;
    auto delta_position_cost =
      origin_position->PositionQty * ((is_history) ? pre_settlement : origin_position->PositionPrice);

    auto delta_position_profit = origin_position->PositionProfit;
    auto delta_float_profit = origin_position->FloatingPL;

    if (prev_position) {
      delta_volume -= prev_position->PositionQty;
      delta_margin -= prev_position->AccountInitialMargin;
      delta_open_cost -= prev_position->PositionQty * prev_position->PositionPrice;
      delta_position_cost -=
        prev_position->PositionQty * ((is_history) ? pre_settlement : prev_position->PositionPrice);
      delta_position_profit -= prev_position->PositionProfit;
      delta_float_profit -= prev_position->FloatingPL;
    }

    // 开仓均价和持仓均价
    if ((subpos->Volume() + delta_volume) <= 0) {
      subpos->open_price = 0.0;
      subpos->position_price = 0.0;
    } else {
      subpos->open_price =
        (subpos->open_price * subpos->Volume() + delta_open_cost) / (subpos->Volume() + delta_volume);
      subpos->position_price =
        (subpos->position_price * subpos->Volume() + delta_position_cost) / (subpos->Volume() + delta_volume);
    }

    auto volume = (is_history) ? &subpos->volume_his : &subpos->volume_today;
    *volume += delta_volume;
    if (origin_position->MatchCmbNo[0] != '\0')
      subpos->volume_comb += delta_volume;
    subpos->margin += delta_margin;
    FCASSERT(*volume >= 0);
    FCASSERT(subpos->volume_comb >= 0);

    subpos->position_profit += delta_position_profit;
    subpos->float_profit += delta_float_profit;

    if (subpos->Volume() > 0) {
      // 持仓市值
      subpos->market_value = target_position->last_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell && ins->product_class == md::ProductClass::kOption)
        subpos->market_value *= -1;
      // 期权盈亏需自行计算
      if (ins->product_class == md::ProductClass::kOption) {
        subpos->float_profit =
          (target_position->last_price - subpos->open_price) * ins->volume_multiple * subpos->Volume();
        subpos->position_profit =
          (target_position->last_price - subpos->position_price) * ins->volume_multiple * subpos->Volume();
        if (subpos->direction == Direction::kSell) {
          subpos->float_profit *= -1;
          subpos->position_profit *= -1;
        }
      }
    } else {
      subpos->market_value = 0.0;
      subpos->position_profit = 0.0;
      subpos->float_profit = 0.0;
    }
    if (!ins->HasCloseToday())
      RegulatePositionFrozen(subpos);
  });
}

std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>*
TapPositionAccount::ProcessCombPositionCaches(std::shared_ptr<TapAPIPositionInfo> position,
  std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>* prev_position) {
  if (position->MatchCmbNo[0] == '\0' || position->CommodityNo[0] == '\0')
    return nullptr;
  auto it = m_qry_comb_position_caches.find(position->MatchCmbNo);
  if (it == m_qry_comb_position_caches.end()) {
    m_qry_comb_position_caches[position->MatchCmbNo] = position;
    return nullptr;
  }
  std::string pd = position->CommodityNo;
  std::string cache_pd = it->second->CommodityNo;
  std::string no_s = position->ContractNo;
  std::string cache_no_s = it->second->ContractNo;
  if (!std::all_of(no_s.begin(), no_s.end(), ::isdigit)
    || !std::all_of(cache_no_s.begin(), cache_no_s.end(), ::isdigit)) {
    m_qry_comb_position_caches.erase(position->MatchCmbNo);
    return nullptr;
  }
  auto no = std::stoi(no_s);
  auto cache_no = std::stoi(cache_no_s);

  bool positive = cache_no < no;
  if (cache_no == no) {
    positive = position->MatchSide == TAPI_SIDE_SELL;
  }
  if (pd != cache_pd) {
    std::string combine_pd1 = cache_pd + "&" + pd;
    std::string combine_pd2 = pd + "&" + cache_pd;
    auto iter1 = ProductCombi.find(combine_pd1);
    auto iter2 = ProductCombi.find(combine_pd2);
    if (iter1 == ProductCombi.end() && iter2 == ProductCombi.end()) {
      m_qry_comb_position_caches.erase(position->MatchCmbNo);
      return nullptr;
    }
    positive = iter1 != ProductCombi.end();
  }
  if (prev_position) {
    auto iter = m_qry_comb_position_results.find(position->MatchCmbNo);
    if (iter != m_qry_comb_position_results.end()) {
      *prev_position = iter->second;
    } else {
      prev_position->first = nullptr;
      prev_position->second = nullptr;
    }
  }
  return InsertCombPositionResults(positive, it->second, position);
}

std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>*
TapPositionAccount::InsertCombPositionResults(
  bool positive, std::shared_ptr<TapAPIPositionInfo> first, std::shared_ptr<TapAPIPositionInfo> second) {
  auto result = &m_qry_comb_position_results[first->MatchCmbNo];
  if (positive) {
    result->first = first;
    result->second = second;
  } else {
    result->first = second;
    result->second = first;
  }
  return result;
}

void TapPositionAccount::ProcessQryCombPositionResults() {
  std::set<std::string> cache;
  for (const auto& [_, p] : m_qry_comb_position_results) {
    auto ins = GetCombInsNode(p);
    bool init = false;
    if (cache.find(ins->symbol.data()) == cache.end()) {
      cache.insert(ins->symbol.data());
      init = true;
    }
    ProcessCombPositionResult(init, ins, p);
  }
}

void TapPositionAccount::ProcessCombPositionResult(bool init, const std::optional<shm::ShmInstrument>& ins,
  const std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>& origin_position,
  const std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>& prev_position) {
  if (!ins.has_value())
    return;
  auto position_key =
    Position::MakeKey(m_service->m_user_key, 0, std::string(ins->exchange_id.data()) + "." + ins->instrument_id.data());
  m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
    if (target_position->user_key.empty()) {
      target_position->user_key = m_service->m_user_key;
      target_position->investor_id = origin_position.first->AccountNo;
      target_position->exchange_id = ins->exchange_id.data();
      target_position->instrument_id = ins->instrument_id.data();
    }
    if (init) {
      for (auto p : {&Position::subpos_long_spec, &Position::subpos_short_spec, &Position::subpos_long_other,
             &Position::subpos_short_other}) {
        auto sub_pos = &(target_position.get()->*p);
        sub_pos->volume_his = 0;
        sub_pos->volume_today = 0;
        sub_pos->margin = 0;
      }
    }
    future::SubPosition* subpos =
      GetSubPosition(target_position, origin_position.first->MatchSide, origin_position.first->HedgeFlag);
    if (nullptr == subpos)
      return;
    if (origin_position.first->HedgeFlag == TAPI_HEDGEFLAG_L)
      subpos->hedge_type = PositionHedgeType::kArbitrage;

    auto is_history = origin_position.first->IsHistory == APIYNFLAG_YES;
    auto delta_volume = std::min(origin_position.first->PositionQty, origin_position.second->PositionQty);
    auto delta_margin =
      std::max(origin_position.first->AccountInitialMargin, origin_position.second->AccountInitialMargin);

    if (nullptr != prev_position.first && nullptr != prev_position.second) {
      delta_volume -= std::min(prev_position.first->PositionQty, prev_position.second->PositionQty);
      delta_margin -= std::max(prev_position.first->AccountInitialMargin, prev_position.second->AccountInitialMargin);
    }

    auto volume = (is_history) ? &subpos->volume_his : &subpos->volume_today;
    *volume += delta_volume;
    subpos->margin += delta_margin;
    FCASSERT(*volume >= 0);
  });
}

void TapPositionAccount::ProcessRtnPositionProfitResults() {
  if (!m_position_profit_last)
    return;
  for (auto iter = m_rtn_position_profit_caches.begin(); iter != m_rtn_position_profit_caches.end();) {
    auto position_it = m_qry_position_results.find(iter->first);
    if (position_it == m_qry_position_results.end()) {
      ++iter;
      continue;
    }
    std::shared_ptr<TapAPIPositionProfit> prev_position_profit = nullptr;
    auto position_profit_it = m_rtn_position_profit_results.find(iter->first);
    if (position_profit_it != m_rtn_position_profit_results.end()) {
      prev_position_profit = position_profit_it->second;
    }
    ProcessPositionProfitResult(position_it->second, iter->second, prev_position_profit);
    m_rtn_position_profit_results[iter->first] = iter->second;
    iter = m_rtn_position_profit_caches.erase(iter);
  }
}

void TapPositionAccount::ProcessPositionProfitResult(std::shared_ptr<TapAPIPositionInfo> info,
  std::shared_ptr<TapAPIPositionProfit> origin_position, std::shared_ptr<TapAPIPositionProfit> prev_position) {
  auto ins = GetInsNode(info);
  auto position_key = Position::MakeKey(m_service->m_user_key, 0, ins->symbol.data());
  m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
    if (target_position->user_key.empty()) {
      target_position->user_key = m_service->m_user_key;
      target_position->investor_id = info->AccountNo;
      target_position->exchange_id = ins->exchange_id.data();
      target_position->instrument_id = ins->instrument_id.data();
    }

    future::SubPosition* subpos = GetSubPosition(target_position, info->MatchSide, info->HedgeFlag);
    if (nullptr == subpos)
      return;

    auto price = origin_position->CalculatePrice;
    if (!isnan(price) && fabs(price) > 1e-3)
      target_position->last_price = price;
    if (isnan(target_position->last_price) && !isnan(ins->last_price))
      target_position->last_price = ins->last_price;
    if (isnan(target_position->last_price))
      target_position->last_price = ins->pre_settlement;

    auto delta_position_profit = origin_position->PositionProfit;
    auto delta_float_profit = origin_position->FloatingPL;

    if (prev_position) {
      delta_position_profit -= prev_position->PositionProfit;
      delta_float_profit -= prev_position->FloatingPL;
    }
    subpos->position_profit += delta_position_profit;
    subpos->float_profit += delta_float_profit;

    if (subpos->Volume() > 0) {
      // 持仓市值
      subpos->market_value = target_position->last_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell && ins->product_class == md::ProductClass::kOption)
        subpos->market_value *= -1;
      // 期权盈亏需自行计算
      if (ins->product_class == md::ProductClass::kOption) {
        subpos->float_profit =
          (target_position->last_price - subpos->open_price) * ins->volume_multiple * subpos->Volume();
        subpos->position_profit =
          (target_position->last_price - subpos->position_price) * ins->volume_multiple * subpos->Volume();
        if (subpos->direction == Direction::kSell) {
          subpos->float_profit *= -1;
          subpos->position_profit *= -1;
        }
      }
    } else {
      subpos->market_value = 0.0;
      subpos->position_profit = 0.0;
      subpos->float_profit = 0.0;
    }
  });
}

void TapPositionAccount::ProcessRspOrderResults() {
  for (const auto& order : m_rsp_order_results)
    ProcessOrderResult(order);
  m_rsp_order_results.clear();
}

void TapPositionAccount::ProcessOrderResult(std::shared_ptr<TapAPIOrderInfo> field) {
  if (field->OrderNo[0] == '\0')
    return;
  auto exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  auto instrument_id = ConvertToFclibInstrumentID(field.get());
  if (exchange_id.empty() || instrument_id.empty())
    return;
  auto ins = m_service->m_md_helper->GetShmInstrument(exchange_id + "." + instrument_id, true);
  FCASSERT(ins.has_value());

  // 调整持仓冻结手数
  int delta_volume = (ConvertFromTapOrderStatus(&field->OrderState) == OrderStatus::kAlive)
    ? (field->OrderQty - field->OrderMatchQty)
    : 0;
  auto it = m_alive_order_results.find(field->OrderNo);
  if (it != m_alive_order_results.end()) {
    const auto& prev_order = it->second;
    int prev_order_volume = (ConvertFromTapOrderStatus(&prev_order->OrderState) == OrderStatus::kAlive)
      ? (prev_order->OrderQty - prev_order->OrderMatchQty)
      : 0;
    delta_volume -= prev_order_volume;
  }
  if (delta_volume == 0)
    return;

  if (ins->product_class == md::ProductClass::kCombine) {
    auto offset_flag = field->PositionEffect;
    auto leg1 = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2 = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    FCASSERT(leg1.has_value() && leg2.has_value());
    if (offset_flag != TAPI_PositionEffect_OPEN)
      ProcessFrozenVolume(field, leg1, field->OrderSide, offset_flag, delta_volume);
    auto direction = (field->OrderSide == TAPI_SIDE_BUY ? TAPI_SIDE_SELL : TAPI_SIDE_BUY);
    if (field->OrderType == TAPI_ORDER_TYPE_SWAP)
      offset_flag = (offset_flag == TAPI_PositionEffect_OPEN ? TAPI_PositionEffect_COVER : TAPI_PositionEffect_OPEN);
    if (offset_flag != TAPI_PositionEffect_OPEN)
      ProcessFrozenVolume(field, leg2, direction, offset_flag, delta_volume);
  } else {
    ProcessFrozenVolume(field, ins, field->OrderSide, field->PositionEffect, delta_volume);
  }

  if (ConvertFromTapOrderStatus(&field->OrderState) != OrderStatus::kAlive) {
    m_alive_order_results.erase(field->OrderNo);
  } else {
    m_alive_order_results[field->OrderNo] = field;
  }
}

void TapPositionAccount::ProcessFrozenVolume(std::shared_ptr<TapAPIOrderInfo> order,
  const std::optional<shm::ShmInstrument>& ins, const TAPISideType& direction, const TAPIPositionEffectType& offset,
  int delta_volume) {
  std::string position_key = m_service->m_user_key + "|0|" + ins->symbol.data();
  auto position_node =
    m_service->GetNodeDb()->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      if (position->user_key.empty()) {
        position->user_key = m_service->m_user_key;
        position->investor_id = m_account_no;
        position->exchange_id = ins->exchange_id.data();
        position->instrument_id = ins->instrument_id.data();
      }

      auto calc_subpos = GetSubPosition(position, direction, order->HedgeFlag, offset);
      if (nullptr == calc_subpos)
        return;

      auto offset_flag = offset;
      if (offset_flag == TAPI_PositionEffect_COVER_TODAY && !ins->HasCloseToday()) {
        offset_flag = TAPI_PositionEffect_COVER;
      }
      if (offset_flag == TAPI_PositionEffect_COVER_TODAY) {
        calc_subpos->volume_today_frozen += delta_volume;
      } else if (ins->HasCloseToday()) {
        calc_subpos->volume_his_frozen += delta_volume;
      } else {
        if (std::string(ins->exchange_id.data()) == "CZCE") {
          SubPosition* calc_subpos0 = GetSubPosition(position, direction, TAPI_HEDGEFLAG_T, offset_flag);
          SubPosition* calc_subpos1 = GetSubPosition(position, direction, TAPI_HEDGEFLAG_B, offset_flag);
          if (delta_volume > 0) {
            // 冻结时，先投机后保值
            auto frozen0 = std::min(delta_volume, calc_subpos0->Volume() - calc_subpos0->VolumeFrozen());
            if (frozen0 > 0)
              calc_subpos0->volume_his_frozen += frozen0;
            if (delta_volume > frozen0) {
              calc_subpos1->volume_his_frozen += delta_volume - frozen0;
            }
          } else {
            // 解冻时，先保值后投机
            auto frozen1 = std::min(-delta_volume, calc_subpos1->OrderFrozen());
            if (frozen1 > 0)
              calc_subpos1->volume_his_frozen -= frozen1;
            if (-delta_volume > frozen1) {
              calc_subpos0->volume_his_frozen -= -delta_volume - frozen1;
            }
          }
          RegulatePositionFrozen(calc_subpos0);
          RegulatePositionFrozen(calc_subpos1);
        } else {
          calc_subpos->volume_his_frozen += delta_volume;
          RegulatePositionFrozen(calc_subpos);
        }
      }
    });
}

void TapPositionAccount::RegulatePositionFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->OrderFrozen();
  calc_subpos->volume_his_frozen = std::min(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

std::optional<shm::ShmInstrument> TapPositionAccount::GetInsNode(std::shared_ptr<TapAPIPositionInfo> origin_position) {
  FCASSERT(origin_position);
  auto exchange_id = ConvertFromTapExchangeID(&origin_position->ExchangeNo);
  auto instrument_id = ConvertToFclibInstrumentID(origin_position.get());
  auto ins = m_service->m_md_helper->GetShmInstrument(exchange_id + "." + instrument_id, true);
  FCASSERT(ins.has_value());
  FCASSERT(ins->instrument_id.data() == instrument_id);
  FCASSERT(ins->exchange_id.data() == exchange_id);
  return ins;
}

std::optional<shm::ShmInstrument> TapPositionAccount::GetCombInsNode(
  const std::pair<std::shared_ptr<TapAPIPositionInfo>, std::shared_ptr<TapAPIPositionInfo>>& p) {
  auto leg1 = GetInsNode(p.first);
  auto leg2 = GetInsNode(p.second);
  FCASSERT(leg1.has_value() && leg2.has_value());

  std::string prefix;
  bool is_same = std::string_view(leg1->instrument_id.data()) == std::string_view(leg2->instrument_id.data());
  if (std::string_view(leg1->exchange_id.data()) == "DCE" || std::string_view(leg1->exchange_id.data()) == "GFEX") {
    prefix = is_same ? "SP" : "SPC";
  } else if (std::string_view(leg1->exchange_id.data()) == "CZCE") {
    prefix = is_same ? "SPD" : "IPS";
  } else {
    FCASSERT(false);
  }
  auto instrument_id = prefix + " " + leg1->instrument_id.data() + "&" + leg2->instrument_id.data();
  auto ins =
    m_service->m_md_helper->GetShmInstrument(std::string(leg1->exchange_id.data()) + "." + instrument_id, true);
  FCASSERT(ins.has_value());
  return ins;
}

SubPosition* TapPositionAccount::GetSubPosition(std::shared_ptr<future::Position> position,
  const TAPISideType& direction, const TAPIHedgeFlagType& hedge, const TAPIPositionEffectType& offset) {
  if (hedge == TAPI_HEDGEFLAG_T) {
    if ((direction == TAPI_SIDE_BUY && offset == TAPI_PositionEffect_OPEN)
      || (direction == TAPI_SIDE_SELL && offset != TAPI_PositionEffect_OPEN))
      return &position->subpos_long_spec;
    else
      return &position->subpos_short_spec;
  } else {
    if ((direction == TAPI_SIDE_BUY && offset == TAPI_PositionEffect_OPEN)
      || (direction == TAPI_SIDE_SELL && offset != TAPI_PositionEffect_OPEN))
      return &position->subpos_long_other;
    else
      return &position->subpos_short_other;
  }
  return nullptr;
}

