template <typename T>
std::string ConvertToFclibInstrumentID(const T* field) {
  auto exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  auto instrument_id = std::string(field->CommodityNo);
  if (exchange_id != "CFFEX" && exchange_id != "CZCE")
    transform(instrument_id.begin(), instrument_id.end(), instrument_id.begin(), ::tolower);
  instrument_id += field->ContractNo;
  if (field->CommodityType == TAPI_COMMODITY_TYPE_OPTION) {
    if (exchange_id == "DCE" || exchange_id == "CFFEX") {
      instrument_id.push_back('-');
      instrument_id.push_back(field->CallOrPutFlag);
      instrument_id.push_back('-');
    } else {
      instrument_id.push_back(field->CallOrPutFlag);
    }
    instrument_id += field->StrikePrice;
  }
  FCASSERT(!exchange_id.empty() && !instrument_id.empty());
  return instrument_id;
}

