template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(
  SpiMessage::Tag tag, const T *plain_src, TAPIINT32 errorCode, TAPIUINT32 sessionID, TAPIYNFLAG isLast) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  msg->nErrorCode = errorCode;
  msg->SessionID = sessionID;
  msg->bIsLast = isLast == APIYNFLAG_YES;
  return msg;
}

template <>
std::shared_ptr<SpiMessage> MakeSpiMsg(
  SpiMessage::Tag tag, const std::string *plain_src, TAPIINT32 errorCode, TAPIUINT32 sessionID, TAPIYNFLAG isLast) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<std::string> target = std::make_shared<std::string>();
    *target = *plain_src;
    msg->pMainField = target;
  }
  msg->nErrorCode = errorCode;
  msg->SessionID = sessionID;
  msg->bIsLast = isLast == APIYNFLAG_YES;
  return msg;
}

