void TapSpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_impl)
    return;
  auto queue = &(m_impl->m_recv_queue);
  m_strand.post([=]() {
    queue->push(msg);
  });
}

