static const std::set<int> TapReconnectedError = {
  TAPIERROR_ConnectFail,
  TAPIERROR_NotReadyTestNetwork,
  TAPIERROR_CurTestNotOver,
  TAPIERROR_LastReqNotFinish,
  TAPIERROR_API_NotReady,
  TAPIERROR_Frequently,
};

TapLogIn::TapLogIn(TapServiceImpl *service, structlog::Logger &parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterCommandProcessor(ChangePasswordBeforeLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndChangePassword(command);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ChangePassword(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspChangePassword, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspChangePassword(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnConnect, [this](std::shared_ptr<SpiMessage> msg) {
    OnConnect();
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnDisconnect, [this](std::shared_ptr<SpiMessage> msg) {
    OnDisconnect(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnApiReady, [this](std::shared_ptr<SpiMessage> msg) {
    OnApiReady();
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryAccount(msg);
  });
}

void TapLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  int ret = m_service->BuildApi(command);
  if (ret != 0) {
    m_need_reconnected = false;
    SetCommandFinished(command, -1, u8"fclib: API创建失败");
    return;
  }
  Login(command);
}

void TapLogIn::InitAndChangePassword(std::shared_ptr<UserCommand> command) {
  if (m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 账户已登录, 请调用修改密码接口");
    return;
  }
  int ret = m_service->BuildApi(command);
  if (ret != 0) {
    SetCommandFinished(command, -1, u8"fclib: API创建失败,请检查交易前置");
    return;
  }
  auto request = std::static_pointer_cast<ChangePasswordBeforeLogin>(command);
  if (request->new_password.empty() || request->old_password.empty()) {
    SetCommandFinished(command, -1, u8"fclib: 交易密码不可为空");
    return;
  }
  if (request->new_password == request->old_password) {
    SetCommandFinished(command, -1, u8"fclib: 修改前后密码相同");
    return;
  }
  // 登录服务器
  TapAPITradeLoginAuth field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.UserNo, m_service->m_req_login->user_id);
  strcpy_x(field.AuthCode, m_service->m_req_login->broker.auth_code);
  strcpy_x(field.AppID, m_service->m_req_login->broker.app_id);
  strcpy_x(field.Password, request->old_password);
  strcpy_x(field.NewPassword, request->new_password);
  field.ISModifyPassword = APIYNFLAG_YES;
  field.ISDDA = APIYNFLAG_NO;
  field.NoticeIgnoreFlag = TAPI_NOTICE_IGNORE_ALL;

  ret = m_service->m_api->Login(&field);
  m_service->m_command_manager->SetCommandId(command, "change_password_before_login");
  if (ret != 0) {
    SetCommandFinished(command, ret, GetErrorMsg(ret));
    return;
  }
}

void TapLogIn::ChangePassword(std::shared_ptr<UserCommand> command) {
  if (!m_ready) {
    SetCommandFinished(command, -1, u8"fclib: 交易API未就绪,请稍后重试");
    return;
  }
  auto request = std::static_pointer_cast<future::ChangePassword>(command);
  if (request->password_type != PasswordType::kTrade) {
    SetCommandFinished(command, -1, u8"fclib: 交易API仅支持修改交易密码");
    return;
  }
  if (request->new_password.empty() || request->old_password.empty()) {
    SetCommandFinished(command, -1, u8"fclib: 交易密码不可为空");
    return;
  }
  if (request->new_password == request->old_password) {
    SetCommandFinished(command, -1, u8"fclib: 修改前后密码相同");
    return;
  }
  // 修改密码
  TapAPIChangePasswordReq field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.OldPassword, request->old_password);
  strcpy_x(field.NewPassword, request->new_password);

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->ChangePassword(&sessionID, &field);
  m_service->m_command_manager->SetCommandId(command, "change_password");
  if (ret != 0) {
    SetCommandFinished(request, ret, GetErrorMsg(ret));
    return;
  }
}

void TapLogIn::OnRspLogin(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_change_passwd_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    return;
  } else {
    auto req = m_service->m_command_manager->Update("login");
    if (msg->nErrorCode != 0 || !msg->pMainField) {
      SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
      m_need_reconnected = IsNeedReconnected(msg->nErrorCode);
      return;
    }
    m_logined = true;
    m_need_reconnected = true;
    auto pRspUserLogin = std::static_pointer_cast<TapAPITradeLoginRspInfo>(msg->pMainField);
    m_service->m_login_node = m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
        target_login->user_key = m_service->m_user_key;
        target_login->user_id = pRspUserLogin->UserNo;
        target_login->investor_name = GbkToUtf8(pRspUserLogin->UserName);
        if (nullptr != m_service->m_req_login)
          target_login->broker_id = m_service->m_req_login->broker.broker_id;
        if (!target_login->trading_day.empty() && target_login->trading_day != pRspUserLogin->TradeDate) {
          m_service->m_new_day = true;
          target_login->session_status = SessionStatus::kDisconnected;
        } else {
          target_login->session_status = SessionStatus::kLogined;
        }
        target_login->confirm_status = ConfirmStatus::kConfirmed;
        target_login->trading_day = pRspUserLogin->TradeDate;
        target_login->system_name = "tap";
        target_login->backend = BackEnd::kTap;
        target_login->session_id = reinterpret_cast<int64_t>(pRspUserLogin.get());
        if (target_login->user_desc == "") {
          target_login->user_desc = m_service->m_req_login->user_desc;
        }
      });
  }
}

void TapLogIn::OnRspChangePassword(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("change_password");
  SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
}

void TapLogIn::OnConnect() {
  m_api_wait_seconds = 1;
  m_need_reconnected = false;
  m_last_disconnected_time = 0;
  if (nullptr != m_service->m_login_node) {
    m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
        target_login->session_status = SessionStatus::kBeforeConnect;
        target_login->position_ready = false;
        target_login->account_ready = false;
      });
  }
}

void TapLogIn::OnDisconnect(std::shared_ptr<SpiMessage> msg) {
  m_ready = false;
  m_need_reconnected = IsNeedReconnected(TAPIERROR_ConnectFail);
  // 刷新登录节点
  m_service->m_login_node = m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->session_status =
        m_service->m_login_node == nullptr ? SessionStatus::kBeforeConnect : SessionStatus::kDisconnected;
      target_login->confirm_status = ConfirmStatus::kConfirmed;
      target_login->system_name = "tap";
      target_login->backend = BackEnd::kTap;
      target_login->status_msg = GetErrorMsg(msg->nErrorCode);
    });
}

void TapLogIn::OnApiReady() {
  m_ready = true;
  if (m_service->m_change_passwd_before_login)
    return;
  auto req = m_service->m_command_manager->Update("login");
  TapAPIAccQryReq field;
  memset(&field, 0, sizeof(TapAPIAccQryReq));

  TAPIUINT32 sessionID = 0;
  auto ret = m_service->m_api->QryAccount(&sessionID, &field);
  if (ret != 0) {
    m_need_reconnected = IsNeedReconnected(ret);
    SetCommandFinished(req, ret, GetErrorMsg(ret));
  }
}

void TapLogIn::OnRspQryAccount(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != 0)
    m_logger.With("OnRspQryAccount", GetErrorMsg(msg->nErrorCode)).Error("on rsp account error");

  if (msg->nErrorCode == 0 && msg->pMainField) {
    auto pAccountInfo = std::static_pointer_cast<TapAPIAccountInfo>(msg->pMainField);
    m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
        target_login->user_key = m_service->m_user_key;
        target_login->backend = BackEnd::kTap;
        target_login->investor_id = pAccountInfo->AccountNo;
      });
  }
  auto req = m_service->m_command_manager->Update("login");
  SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
}

int TapLogIn::RunOnce() {
  if (m_need_reconnected && m_last_disconnected_time > 0
    && NowAsEpochNano() - m_last_disconnected_time > m_api_wait_seconds * 1000 * 1000 * 1000LL) {
    m_last_disconnected_time = 0;
    Login();
    return 0;
  }
  return 0;
}

void TapLogIn::Login(std::shared_ptr<UserCommand> command) {
  FCASSERT(m_service->m_req_login != nullptr);
  // 登录服务器
  TapAPITradeLoginAuth field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.UserNo, m_service->m_req_login->user_id);
  strcpy_x(field.Password, m_service->m_req_login->password);
  strcpy_x(field.AuthCode, m_service->m_req_login->broker.auth_code);
  strcpy_x(field.AppID, m_service->m_req_login->broker.app_id);
  field.ISModifyPassword = APIYNFLAG_NO;
  field.ISDDA = APIYNFLAG_NO;
  auto ret = m_service->m_api->Login(&field);
  if (nullptr != command)
    m_service->m_command_manager->SetCommandId(command, "login");
  if (ret != 0) {
    m_need_reconnected = IsNeedReconnected(ret);
    SetCommandFinished(command, ret, GetErrorMsg(ret));
  }
}

bool TapLogIn::IsNeedReconnected(int code) {
  bool need = !m_service->m_change_passwd_before_login && m_logined
    && TapReconnectedError.find(code) != TapReconnectedError.end();
  if (need) {
    m_api_wait_seconds = std::min(30, 2 * m_api_wait_seconds);
    m_last_disconnected_time = NowAsEpochNano();
  }
  return need;
}

