std::string GetErrorMsg(int error_code) {
  if (error_code == TAPIERROR_SUCCEED)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 成功";
  if (error_code == TAPIERROR_ConnectFail)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 连接服务失败";
  if (error_code == TAPIERROR_LinkAuthFail)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 链路认证失败";
  if (error_code == TAPIERROR_HostUnavailable)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 主机地址不可用";
  if (error_code == TAPIERROR_SendDataError)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 发送数据错误";
  if (error_code == TAPIERROR_TestIDError)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 测试编号不合法";
  if (error_code == TAPIERROR_NotReadyTestNetwork)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 没准备好测试网络";
  if (error_code == TAPIERROR_CurTestNotOver)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 当前网络测试还没结束";
  if (error_code == TAPIERROR_NOFrontAvailable)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 没用可用的接入前置";
  if (error_code == TAPIERROR_DataPathAvaiable)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 数据路径不可用";
  if (error_code == TAPIERROR_RepeatLogin)
    return u8"易盛启明星v9: " + std::to_string(error_code) + u8", 重复登录";
  if (error_code == TAPIERROR_InnerError)
