void ConvertToTapExchangeID(const std::string& exchange_id, TAPISTR_10* t) {
  if (exchange_id == "CZCE")
    strcpy_x(*t, "ZCE");
  else
    strcpy_x(*t, exchange_id);
}

std::string ConvertFromTapExchangeID(const TAPISTR_10* t) {
  if (std::string(*t) == "ZCE") {
    return "CZCE";
  }
  return std::string(*t);
}

void ConvertToTapCommodityType(const md::ProductClass& p_class, TAPICommodityType* t) {
  if (p_class == md::ProductClass::kFuture) {
    *t = TAPI_COMMODITY_TYPE_FUTURES;
    return;
  }
  if (p_class == md::ProductClass::kOption) {
    *t = TAPI_COMMODITY_TYPE_OPTION;
    return;
  }
  *t = TAPI_COMMODITY_TYPE_NONE;
  return;
}

void ConvertToTapProductID(const std::optional<shm::ShmInstrument>& ins, TAPISTR_10* t) {
  FCASSERT(ins.has_value());
  if (ins->product_class == md::ProductClass::kFuture) {
    auto p_id = std::string(ins->product_id.data());
    transform(p_id.begin(), p_id.end(), p_id.begin(), ::toupper);
    strcpy_x(*t, p_id);
    return;
  }
  if (ins->product_class == md::ProductClass::kOption) {
    auto p_id = std::string(ins->instrument_id.data());
    transform(p_id.begin(), p_id.end(), p_id.begin(), ::toupper);
    auto pos = p_id.find_first_not_of("0123456789", 4);
    FCASSERT(pos != std::string::npos);
    p_id = p_id.substr(0, pos);
    pos = p_id.find_first_of("0123456789");
    FCASSERT(pos != std::string::npos);
    strcpy_x(*t, p_id.substr(0, pos));
    return;
  }
}

void ConvertToTapProductID(const std::optional<shm::ShmInstrument>& ins, std::string* t) {
  FCASSERT(ins.has_value());
  if (ins->product_class == md::ProductClass::kFuture) {
    auto p_id = std::string(ins->product_id.data());
    transform(p_id.begin(), p_id.end(), p_id.begin(), ::toupper);
    *t = p_id;
    return;
  }
  if (ins->product_class == md::ProductClass::kOption) {
    auto p_id = std::string(ins->instrument_id.data());
    transform(p_id.begin(), p_id.end(), p_id.begin(), ::toupper);
    auto pos = p_id.find_first_not_of("0123456789", 4);
    FCASSERT(pos != std::string::npos);
    p_id = p_id.substr(0, pos);
    pos = p_id.find_first_of("0123456789");
    FCASSERT(pos != std::string::npos);
    *t = p_id.substr(0, pos);
    return;
  }
}

void ConvertToTapContractNo(const std::optional<shm::ShmInstrument>& ins, TAPISTR_10* t) {
  FCASSERT(ins.has_value());
  auto t_instrument_id = std::string(ins->instrument_id.data());
  if (ins->product_class == md::ProductClass::kOption) {
    auto pos = t_instrument_id.find_first_not_of("0123456789", 4);
    FCASSERT(pos != std::string::npos);
    t_instrument_id = t_instrument_id.substr(0, pos);
  }

  auto p = std::find_if(t_instrument_id.begin(), t_instrument_id.end(), ::isdigit);
  std::string contrack_no;
  if (p != t_instrument_id.end())
    contrack_no = std::string(p, t_instrument_id.end());
  FCASSERT(!contrack_no.empty());
  strcpy_x(*t, contrack_no);
}

void ConvertToTapTimeInForce(
  const OrderVolumeCondition& volume_condition, const OrderTimeCondition& time_condition, TAPITimeInForceType* t) {
  switch (time_condition) {
    case OrderTimeCondition::kIoc: {
      if (volume_condition == OrderVolumeCondition::kAll) {
        *t = TAPI_ORDER_TIMEINFORCE_FOK;
      } else {
        *t = TAPI_ORDER_TIMEINFORCE_FAK;
      }
      break;
    }
    case OrderTimeCondition::kGtd: {
      *t = TAPI_ORDER_TIMEINFORCE_GTD;
      break;
    }
    case OrderTimeCondition::kGtc: {
      *t = TAPI_ORDER_TIMEINFORCE_GTC;
      break;
    }
    default: {
      *t = TAPI_ORDER_TIMEINFORCE_GFD;
      break;
    }
  }
  return;
}

OrderTimeCondition ConvertFromTapTimeInForce(const TAPITimeInForceType* t, const TAPIOrderTypeType* order_type) {
  OrderTimeCondition ret = OrderTimeCondition::kInvalid;
  if (*order_type == TAPI_ORDER_TYPE_MARKET)
    ret = OrderTimeCondition::kIoc;
  else
    ret = OrderTimeCondition::kGfd;

  if (*t == TAPI_ORDER_TIMEINFORCE_GFD) {
    ret = OrderTimeCondition::kGfd;
  } else if (*t == TAPI_ORDER_TIMEINFORCE_GTC) {
    ret = OrderTimeCondition::kGtc;
  } else if (*t == TAPI_ORDER_TIMEINFORCE_GTD) {
    ret = OrderTimeCondition::kGtd;
  } else if (*t == TAPI_ORDER_TIMEINFORCE_FAK) {
    ret = OrderTimeCondition::kIoc;
  } else if (*t == TAPI_ORDER_TIMEINFORCE_FOK) {
    ret = OrderTimeCondition::kIoc;
  }
  FCASSERT(ret != OrderTimeCondition::kInvalid);
  return ret;
}

void ConvertToTapSide(const Direction& direction, TAPISideType* t) {
  switch (direction) {
    case Direction::kBuy: {
      *t = TAPI_SIDE_BUY;
      break;
    }
    case Direction::kSell: {
      *t = TAPI_SIDE_SELL;
      break;
    }
    default: {
      *t = TAPI_SIDE_NONE;
      break;
    }
  }
  return;
}

Direction ConvertFromTapSide(const TAPISideType* t) {
  if (*t == TAPI_SIDE_SELL)
    return Direction::kSell;
  return Direction::kBuy;
}

void ConvertToTapPositionEffect(const Offset& offset, TAPIPositionEffectType* t) {
  switch (offset) {
    case Offset::kOpen: {
      *t = TAPI_PositionEffect_OPEN;
      break;
    }
    case Offset::kClose:
    case Offset::kCloseYesterday: {
      *t = TAPI_PositionEffect_COVER;
      break;
    }
    case Offset::kCloseToday: {
      *t = TAPI_PositionEffect_COVER_TODAY;
      break;
    }
    default: {
      *t = TAPI_PositionEffect_NONE;
      break;
    }
  }
  return;
}

Offset ConvertFromTapPositionEffect(const TAPIPositionEffectType* t, bool has_close_today) {
  if (*t == TAPI_PositionEffect_OPEN)
    return Offset::kOpen;
  if (*t == TAPI_PositionEffect_COVER_TODAY)
    return Offset::kCloseToday;
  if (*t == TAPI_PositionEffect_COVER) {
    if (has_close_today) {
      return Offset::kCloseYesterday;
    }
    return Offset::kClose;
  }
  return Offset::kOpen;
}

void ConvertToTapHedgeFlag(const OrderHedgeFlag& hedge_flag, TAPIHedgeFlagType* t) {
  switch (hedge_flag) {
    case OrderHedgeFlag::kSpeculation: {
      *t = TAPI_HEDGEFLAG_T;
      break;
    }
    case OrderHedgeFlag::kArbitrage: {
      *t = TAPI_HEDGEFLAG_L;
      break;
    }
    case OrderHedgeFlag::kHedge: {
      *t = TAPI_HEDGEFLAG_B;
      break;
    }
    default: {
      *t = TAPI_HEDGEFLAG_NONE;
      break;
    }
  }
  return;
}

OrderHedgeFlag ConvertFromTapHedgeFlag(const TAPIHedgeFlagType* t) {
  if (*t == TAPI_HEDGEFLAG_B)
    return OrderHedgeFlag::kHedge;
  if (*t == TAPI_HEDGEFLAG_L)
    return OrderHedgeFlag::kArbitrage;
  return OrderHedgeFlag::kSpeculation;
}

OrderStatus ConvertFromTapOrderStatus(const TAPIOrderStateType* t) {
  if (*t == TAPI_ORDER_STATE_SUBMIT || *t == TAPI_ORDER_STATE_ACCEPT || *t == TAPI_ORDER_STATE_TRIGGERING
    || *t == TAPI_ORDER_STATE_EXCTRIGGERING || *t == TAPI_ORDER_STATE_QUEUED || *t == TAPI_ORDER_STATE_PARTFINISHED
    || *t == TAPI_ORDER_STATE_CANCELING || *t == TAPI_ORDER_STATE_MODIFYING || *t == TAPI_ORDER_STATE_SUPPENDED
    || *t == TAPI_ORDER_STATE_CHECKING) {
    return OrderStatus::kAlive;
  }
  return OrderStatus::kDead;
}

template <>
std::string ConvertToFclibInstrumentID(const TapAPIOrderInfo* field) {
  auto exchange_id = ConvertFromTapExchangeID(&field->ExchangeNo);
  auto instrument_id = std::string(field->CommodityNo);
  if (exchange_id != "CFFEX" && exchange_id != "CZCE")
    transform(instrument_id.begin(), instrument_id.end(), instrument_id.begin(), ::tolower);
  if (field->CommodityType == TAPI_COMMODITY_TYPE_SPREAD_MONTH
    || field->CommodityType == TAPI_COMMODITY_TYPE_SPREAD_COMMODITY) {
    std::string leg1_instrument_id, leg2_instrument_id;
    auto pos = instrument_id.find("&");
    if (pos == std::string::npos) {
      leg1_instrument_id = leg2_instrument_id = instrument_id;
    } else {
      leg1_instrument_id = instrument_id.substr(0, pos);
      leg2_instrument_id = instrument_id.substr(pos + 1, instrument_id.size());
    }
    FCASSERT(!leg1_instrument_id.empty() && !leg2_instrument_id.empty());
    std::string prefix;
    if (exchange_id == "DCE" || exchange_id == "GFEX") {
      prefix = (leg1_instrument_id == leg2_instrument_id) ? "SP" : "SPC";
    } else if (exchange_id == "CZCE") {
      prefix = (leg1_instrument_id == leg2_instrument_id) ? "SPD" : "IPS";
    } else {
      FCASSERT(false);
    }
    leg1_instrument_id += field->ContractNo;
    leg2_instrument_id += (field->ContractNo2[0] == '\0') ? field->ContractNo : field->ContractNo2;
    instrument_id = prefix + " " + leg1_instrument_id + "&" + leg2_instrument_id;
  } else {
    instrument_id += field->ContractNo;
    if (field->CommodityType == TAPI_COMMODITY_TYPE_OPTION) {
      if (exchange_id == "DCE" || exchange_id == "CFFEX") {
        instrument_id.push_back('-');
        instrument_id.push_back(field->CallOrPutFlag);
        instrument_id.push_back('-');
      } else {
        instrument_id.push_back(field->CallOrPutFlag);
      }
      instrument_id += field->StrikePrice;
    }
  }
  FCASSERT(!exchange_id.empty() && !instrument_id.empty());
  return instrument_id;
}

TAPICommodityType ConvertToCommodityType(const std::string& ins_id) {
  size_t spacePos = ins_id.find(" ");
  if (spacePos != std::string::npos) {
    std::string result = ins_id.substr(0, spacePos);
    if (result == "SP")
      return TAPI_COMMODITY_TYPE_FUTURE_LOCK;
    if (result == "SPD")
      return TAPI_COMMODITY_TYPE_SPREAD_MONTH;
    if (result == "SPC")
      return TAPI_COMMODITY_TYPE_SPREAD_COMMODITY;
    if (result == "PRT")
      return TAPI_COMMODITY_TYPE_PRT;
    if (result == "STD")
      return TAPI_COMMODITY_TYPE_STD;
    if (result == "STG")
      return TAPI_COMMODITY_TYPE_STG;
    if (result == "OPL")
      return TAPI_COMMODITY_TYPE_FUTURE_LOCK;
    if (result == "BER")
      return TAPI_COMMODITY_TYPE_BER;
    if (result == "BUL")
      return TAPI_COMMODITY_TYPE_BUL;
    if (result == "BFO")
      return TAPI_COMMODITY_TYPE_PRT;
  }
  return TAPI_COMMODITY_TYPE_NONE;
}

