CtpMiniInsertCancelOrder::CtpMiniInsertCancelOrder(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("insert_cancel_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelOrder(command);
  });
  m_service->RegisterCommandProcessor(InsertQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteInsertQuote(command);
  });
  m_service->RegisterCommandProcessor(CancelQuote::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCancelQuote(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnErrRtnOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnErrRtnOrderAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnQuote, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnQuote(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQuoteInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQuoteAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQuoteAction(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    m_login = false;
  });
}

int CtpMiniInsertCancelOrder::RunOnce() {
  return 0;
}

void CtpMiniInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  if (!m_login || !m_service->m_req_login) {
    SetCommandFinished(command, -1, u8"fclib: 账户未登录");
    return;
  }
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  auto field = std::make_shared<CThostFtdcInputOrderField>();
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  ConvertToSfitOrderField(req, field);
  auto order_ref = req->order_ref;
  strcpy_x(field->OrderRef, std::to_string(order_ref).c_str());
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field->IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field->MacAddress, m_service->m_req_login->client_mac_address);

  if (req->request_id > 0)
    field->RequestID = req->request_id;
  auto order_id = ToFclibOrderId(field->OrderRef, m_service->m_session_id, m_service->m_front_id);
  FCASSERT(order_id == req->order_id);
  int ret = m_service->m_api->ReqOrderInsert(field.get(), 0);
  LogCtpReq(m_logger, "ReqOrderInsert", field.get(), m_service->GenerateRequestID(), ret);
  // 返回指令回报
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOrder" + order_id);
  req->status = UserCommand::Status::kStarted;
  m_service->m_send_time[order_id] = NowAsEpochNano();
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpMiniInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  if (!m_login || !m_service->m_req_login) {
    SetCommandFinished(command, -1, u8"fclib: 账户未登录");
    return;
  }
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  auto it = m_alive_order.find(req->order_id);
  if (it == m_alive_order.end()) {
    SetCommandFinished(req, 1, u8"报单编号不存在");
    return;
  }
  auto order = it->second;
  CThostFtdcInputOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id.c_str());
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id.c_str());
  strcpy_x(field.OrderRef, order->OrderRef);
  strcpy_x(field.ExchangeID, order->ExchangeID);
  strcpy_x(field.InstrumentID, order->InstrumentID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  field.SessionID = order->SessionID;
  field.FrontID = order->FrontID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  field.LimitPrice = 0;
  field.VolumeChange = 0;
  int ret = m_service->m_api->ReqOrderAction(&field, 0);
  LogCtpReq(m_logger, "ReqOrderAction", &field, 0, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + req->order_id);
  req->status = UserCommand::Status::kStarted;
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpMiniInsertCancelOrder::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto pOrder = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pOrder->OrderRef, pOrder->SessionID, pOrder->FrontID);
  auto status = ctp_mini::ConvertFromSfitOrderStatus(&pOrder->OrderStatus);
  if (status == OrderStatus::kAlive) {
    m_alive_order[order_id] = pOrder;
  } else {
    m_alive_order.erase(order_id);
  }
  if (pOrder->OrderStatus == THOST_FTDC_OST_Canceled) {
    auto req = m_service->m_command_manager->Update("ReqCancelOrder" + order_id);
    SetCommandFinished(req, 0, u8"成功");
  }
  auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
  if (req) {
    auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
    auto order_req = std::static_pointer_cast<InsertOrder>(req);
    order_req->order_id = order_id;
    SetCommandFinished(req, 0, u8"成功");
  }
}

void CtpMiniInsertCancelOrder::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  auto pInputOrder = std::static_pointer_cast<CThostFtdcInputOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pInputOrder->OrderRef, m_service->m_session_id, m_service->m_front_id);
  if (msg->RspInfo.ErrorID != 0) {
    auto req = m_service->m_command_manager->Update("ReqInsertOrder" + order_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpMiniInsertCancelOrder::OnErrRtnOrderAction(std::shared_ptr<SpiMessage> msg) {
  auto pOrderAction = std::static_pointer_cast<CThostFtdcOrderActionField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pOrderAction->OrderRef, pOrderAction->SessionID, pOrderAction->FrontID);
  if (pOrderAction->OrderActionStatus == THOST_FTDC_OAS_Rejected) {
    auto req = m_service->m_command_manager->Update("ReqCancelOrder" + order_id);
    SetCommandFinished(req, 1, GbkToUtf8(pOrderAction->StatusMsg));
  }
}

void CtpMiniInsertCancelOrder::OnRspOrderAction(std::shared_ptr<SpiMessage> msg) {
  auto pInputCancel = std::static_pointer_cast<CThostFtdcInputOrderActionField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pInputCancel->OrderRef, m_service->m_session_id, m_service->m_front_id);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + order_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpMiniInsertCancelOrder::ExecuteInsertQuote(std::shared_ptr<UserCommand> command) {
  if (!m_login || !m_service->m_req_login) {
    SetCommandFinished(command, -1, u8"fclib: 账户未登录");
    return;
  }
  auto req = std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update(command));
  auto field = std::make_shared<CThostFtdcInputQuoteField>();
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->UserID, m_service->m_req_login->user_id);
  strcpy_x(field->ExchangeID, req->exchange_id);
  strcpy_x(field->InstrumentID, req->instrument_id);
  strcpy_x(field->QuoteRef, std::to_string(req->quote_ref));
  strcpy_x(field->AskOrderRef, std::to_string(req->ask_ref));
  strcpy_x(field->BidOrderRef, std::to_string(req->bid_ref));
  strcpy_x(field->ForQuoteSysID, req->response_quote_id);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field->IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field->MacAddress, m_service->m_req_login->client_mac_address);

  field->AskPrice = req->ask_price;
  field->BidPrice = req->bid_price;
  field->AskVolume = req->ask_volume;
  field->BidVolume = req->bid_volume;
  field->RequestID = m_service->GenerateRequestID();
  ConvertToSfitOffsetFlag(req->ask_offset, &field->AskOffsetFlag);
  ConvertToSfitOffsetFlag(req->bid_offset, &field->BidOffsetFlag);
  ConvertToSfitHedgeFlag(req->ask_hedge_flag, &field->AskHedgeFlag);
  ConvertToSfitHedgeFlag(req->bid_hedge_flag, &field->BidHedgeFlag);
  int ret = m_service->m_api->ReqQuoteInsert(field.get(), field->RequestID);
  LogCtpReq(m_logger, "ReqQuoteInsert", field.get(), field->RequestID, ret);
  // 返回指令回报
  auto quote_id = ToFclibOrderId(field->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  FCASSERT(quote_id == req->quote_id);
  m_service->m_command_manager->SetCommandId(command, "ReqInsertQuote" + quote_id);
  req->status = UserCommand::Status::kStarted;
  req->quote_id = quote_id;
  req->result_code = ret;
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

void CtpMiniInsertCancelOrder::ExecuteCancelQuote(std::shared_ptr<UserCommand> command) {
  if (!m_login || !m_service->m_req_login) {
    SetCommandFinished(command, -1, u8"fclib: 账户未登录");
    return;
  }
  auto req = std::static_pointer_cast<CancelQuote>(m_service->m_command_manager->Update(command));
  auto it = m_alive_quote.find(req->quote_id);
  if (it == m_alive_quote.end()) {
    SetCommandFinished(req, 1, u8"报单编号不存在");
    return;
  }
  auto quote = it->second;
  CThostFtdcInputQuoteActionField quote_action_field;
  memset(&quote_action_field, 0, sizeof(quote_action_field));
  strcpy_x(quote_action_field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(quote_action_field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(quote_action_field.UserID, m_service->m_req_login->user_id);
  strcpy_x(quote_action_field.ExchangeID, quote->ExchangeID);
  strcpy_x(quote_action_field.InstrumentID, quote->InstrumentID);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(quote_action_field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(quote_action_field.MacAddress, m_service->m_req_login->client_mac_address);

  quote_action_field.ActionFlag = THOST_FTDC_AF_Delete;
  if (quote->QuoteSysID[0] == '\0') {
    strcpy_x(quote_action_field.QuoteRef, quote->QuoteRef);
    quote_action_field.FrontID = quote->FrontID;
    quote_action_field.SessionID = quote->SessionID;
  } else {
    strcpy_x(quote_action_field.QuoteSysID, quote->QuoteSysID);
  }
  quote_action_field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqQuoteAction(&quote_action_field, quote_action_field.RequestID);
  LogCtpReq(m_logger, "ReqQuoteAction", &quote_action_field, quote_action_field.RequestID, ret);
  // 撤销报价时需要撤销衍生报单
  {
    CThostFtdcInputOrderActionField order_action_field;
    memset(&order_action_field, 0, sizeof(order_action_field));
    strcpy_x(order_action_field.BrokerID, quote_action_field.BrokerID);
    strcpy_x(order_action_field.UserID, quote_action_field.UserID);
    strcpy_x(order_action_field.InvestorID, quote_action_field.InvestorID);
    strcpy_x(order_action_field.ExchangeID, quote_action_field.ExchangeID);
    strcpy_x(order_action_field.InstrumentID, quote_action_field.InstrumentID);
    if (!m_service->m_req_login->client_ip.empty())
      strcpy_x(order_action_field.IPAddress, m_service->m_req_login->client_ip);
    if (!m_service->m_req_login->client_mac_address.empty())
      strcpy_x(order_action_field.MacAddress, m_service->m_req_login->client_mac_address);

    order_action_field.SessionID = quote_action_field.SessionID;
    order_action_field.FrontID = quote_action_field.FrontID;
    order_action_field.ActionFlag = THOST_FTDC_AF_Delete;
    order_action_field.LimitPrice = 0;
    order_action_field.VolumeChange = 0;
    strcpy_x(order_action_field.OrderRef, quote->AskOrderRef);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
    strcpy_x(order_action_field.OrderRef, quote->BidOrderRef);
    m_service->m_api->ReqOrderAction(&order_action_field, 0);
  }
  m_service->m_command_manager->SetCommandId(command, "ReqCancelQuote" + req->quote_id);
  req->status = UserCommand::Status::kStarted;
  req->result_code = ret;
  if (ret != 0) {
    req->status = UserCommand::Status::kFinished;
    req->result_msg = u8"指令发送失败";
  }
}

void CtpMiniInsertCancelOrder::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  auto pQuote = std::static_pointer_cast<CThostFtdcQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(pQuote->QuoteRef, pQuote->SessionID, pQuote->FrontID);
  auto status = ctp_mini::ConvertFromSfitOrderStatus(&pQuote->QuoteStatus);
  if (status == OrderStatus::kAlive) {
    m_alive_quote[quote_id] = pQuote;
  } else {
    m_alive_quote.erase(quote_id);
  }
  if (pQuote->QuoteStatus == THOST_FTDC_OST_Canceled) {
    auto req = m_service->m_command_manager->Update("ReqCancelQuote" + quote_id);
    SetCommandFinished(req, 0, u8"成功");
  }
  auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
  if (req) {
    auto quote_key = m_service->m_user_key + "|" + quote_id;
    auto quote_req = std::static_pointer_cast<InsertQuote>(req);
    quote_req->quote_id = quote_id;
    SetCommandFinished(req);
  }
}

void CtpMiniInsertCancelOrder::OnRspQuoteInsert(std::shared_ptr<SpiMessage> msg) {
  auto input_quote = std::static_pointer_cast<CThostFtdcInputQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(input_quote->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  if (msg->RspInfo.ErrorID != 0) {
    auto req = m_service->m_command_manager->Update("ReqInsertQuote" + quote_id);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpMiniInsertCancelOrder::OnRspQuoteAction(std::shared_ptr<SpiMessage> msg) {
  auto cancel_quote = std::static_pointer_cast<CThostFtdcInputQuoteActionField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(cancel_quote->QuoteRef, m_service->m_session_id, m_service->m_front_id);
  auto req = m_service->m_command_manager->Update("ReqCancelQuote" + quote_id);
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpMiniInsertCancelOrder::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID == 0)
    m_login = true;
}

