CtpMiniRate::CtpMiniRate(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("ctp_mini_rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqMarginRate(command);
  });
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCommissionRate(command);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentMarginRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentMarginRate(msg);
    });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInstrumentCommissionRate, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInstrumentCommissionRate(msg);
    });
}

void CtpMiniRate::ReqMarginRate(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryMarginRate>(m_service->m_command_manager->Update(command));
  if (m_service->m_query_planner.AlreadyInQueue("ReqQryMargin" + req->instrument_id)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同查询");
    return;
  }
  auto field = std::make_shared<CThostFtdcQryInstrumentMarginRateField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryInstrumentMarginRateField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, req->instrument_id);
  int req_id = req->query_request_id > 0 ? req->query_request_id : m_service->GenerateRequestID();
  m_service->m_ioc->post([=]() {
    m_service->m_query_planner.AddTask(
      "ReqQryMargin" + req->instrument_id, CtpMiniQueryPlanner::Priority::kHigh, req_id, [=](int request_id) {
        int ret = m_service->m_api->ReqQryInstrumentMarginRate(field.get(), request_id);
        LogCtpReq(m_logger, "ReqQryMargin", field.get(), request_id, ret);
        m_service->SetReqResponse(command, request_id, ret);
        return ret;
      });
  });
}

void CtpMiniRate::OnRspQryInstrumentMarginRate(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto margin_rate = std::static_pointer_cast<CThostFtdcInstrumentMarginRateField>(msg->pMainField);
  auto rate_key = m_service->m_user_key + "|" + std::string(margin_rate->InstrumentID);
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = margin_rate->InstrumentID;
    if (margin_rate->HedgeFlag == THOST_FTDC_HF_Speculation) {
      rate_node->margin_rate_long_spec =
        UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume);
      rate_node->margin_rate_short_spec =
        UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume);
    } else {
      rate_node->margin_rate_long_other =
        UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume);
      rate_node->margin_rate_short_other =
        UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume);
    }
  });
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpMiniRate::ReqCommissionRate(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QueryCommissionRate>(m_service->m_command_manager->Update(command));
  if (m_service->m_query_planner.AlreadyInQueue("ReqQryCommission" + qry->instrument_id)) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同查询");
    return;
  }
  auto field = std::make_shared<CThostFtdcQryInstrumentCommissionRateField>();
  memset(field.get(), 0, sizeof(field));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field->InstrumentID, qry->instrument_id);
  int req_id = qry->query_request_id > 0 ? qry->query_request_id : m_service->GenerateRequestID();
  m_service->m_ioc->post([=]() {
    m_service->m_query_planner.AddTask(
      "ReqQryCommission" + qry->instrument_id, CtpMiniQueryPlanner::Priority::kHigh, req_id, [=](int request_id) {
        int ret = m_service->m_api->ReqQryInstrumentCommissionRate(field.get(), request_id);
        LogCtpReq(m_logger, "ReqQryCommission", field.get(), request_id, ret);
        m_service->SetReqResponse(command, request_id, ret);
        return ret;
      });
  });
}

void CtpMiniRate::OnRspQryInstrumentCommissionRate(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto commission = std::static_pointer_cast<CThostFtdcInstrumentCommissionRateField>(msg->pMainField);
  auto rate_key = m_service->m_user_key + "|" + commission->InstrumentID;
  m_service->m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
    rate_node->commission_rate_open = (UnitRate(commission->OpenRatioByMoney, commission->OpenRatioByVolume));
    rate_node->commission_rate_close = (UnitRate(commission->CloseRatioByMoney, commission->CloseRatioByVolume));
    rate_node->commission_rate_close_today =
      (UnitRate(commission->CloseTodayRatioByMoney, commission->CloseTodayRatioByVolume));
    rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
    rate_node->user_key = m_service->m_user_key;
    rate_node->instrument_id = commission->InstrumentID;
  });

  // 确认本指令完成
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

int CtpMiniRate::RunOnce() {
  return 0;
}

