void ConvertToSfitDirection(Direction d, TThostFtdcDirectionType* t) {
  if (d == Direction::kBuy) {
    *t = THOST_FTDC_D_Buy;
  } else if (d == Direction::kSell) {
    *t = THOST_FTDC_D_Sell;
  }
}

void ConvertToSfitPosiDirection(future::PosiDirection d, TThostFtdcPosiDirectionType& t) {
  if (d == PosiDirection::kNet) {
    t = THOST_FTDC_PD_Net;
  } else if (d == PosiDirection::kLong) {
    t = THOST_FTDC_PD_Long;
  } else if (d == PosiDirection::kShort) {
    t = THOST_FTDC_PD_Short;
  }
}

future::PosiDirection ConvertFromSfitPosiDirection(const TThostFtdcPosiDirectionType& t) {
  if (t == THOST_FTDC_PD_Net) {
    return future::PosiDirection::kNet;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kLong;
  } else if (t == THOST_FTDC_PD_Long) {
    return future::PosiDirection::kShort;
  }
  return future::PosiDirection::kInvalid;
}

void ConvertToSfitExecAction(future::ExecActionType d, TThostFtdcActionTypeType& t) {
  if (d == future::ExecActionType::kExec) {
    t = THOST_FTDC_ACTP_Exec;
  } else if (d == future::ExecActionType::kAbandon) {
    t = THOST_FTDC_ACTP_Abandon;
  }
}

future::ExecActionType ConvertFromSfitExecAction(const TThostFtdcActionTypeType& t) {
  if (t == THOST_FTDC_ACTP_Exec) {
    return future::ExecActionType::kExec;
  } else {
    return future::ExecActionType::kAbandon;
  }
}

void ConvertToSfitExecOrderCloseFlag(future::ExecOrderCloseFlag d, TThostFtdcExecOrderCloseFlagType& t) {
  if (d == future::ExecOrderCloseFlag::kAutoClose) {
    t = THOST_FTDC_EOCF_AutoClose;
  } else {
    t = THOST_FTDC_EOCF_NotToClose;
  }
}

future::ExecOrderCloseFlag ConvertFromSfitExecOrderCloseFlag(const TThostFtdcExecOrderCloseFlagType& t) {
  if (t == THOST_FTDC_EOCF_AutoClose) {
    return future::ExecOrderCloseFlag::kAutoClose;
  } else {
    return future::ExecOrderCloseFlag::kNotToClose;
  }
}

future::ExecOrderResultType ConvertFromSfitExecOrderResultType(const TThostFtdcExecResultType& t) {
  switch (t) {
    case THOST_FTDC_OER_NoExec: return future::ExecOrderResultType::kNoExec;
    case THOST_FTDC_OER_Canceled: return future::ExecOrderResultType::kCanceled;
    case THOST_FTDC_OER_OK: return future::ExecOrderResultType::kSuccess;
    case THOST_FTDC_OER_NoPosition: return future::ExecOrderResultType::kNoPosition;
    case THOST_FTDC_OER_NoDeposit: return future::ExecOrderResultType::kNoDeposit;
    case THOST_FTDC_OER_NoParticipant: return future::ExecOrderResultType::kNoParticipant;
    case THOST_FTDC_OER_NoClient: return future::ExecOrderResultType::kNoClient;
    case THOST_FTDC_OER_NoInstrument: return future::ExecOrderResultType::kNoInstrument;
    case THOST_FTDC_OER_NoRight: return future::ExecOrderResultType::kNoRight;
    case THOST_FTDC_OER_InvalidVolume: return future::ExecOrderResultType::kInvalidVolume;
    case THOST_FTDC_OER_NoEnoughHistoryTrade: return future::ExecOrderResultType::kNoEnoughHistoryTrade;
    default: return future::ExecOrderResultType::kUnKnown;
  }
}

Direction ConvertFromSfitDirection(const TThostFtdcDirectionType* t) {
  if (*t == THOST_FTDC_D_Buy)
    return Direction::kBuy;
  if (*t == THOST_FTDC_D_Sell)
    return Direction::kSell;
  return Direction::kInvalid;
}

Offset ConvertFromSfitOffset(const TThostFtdcOffsetFlagType& t) {
  if (t == THOST_FTDC_OF_Open)
    return Offset::kOpen;
  if (t == THOST_FTDC_OF_CloseToday)
    return Offset::kCloseToday;
  if (t == THOST_FTDC_OF_CloseYesterday)
    return Offset::kCloseYesterday;
  return Offset::kClose;
}

void ConvertToSfitHedgeFlag(future::OrderHedgeFlag h, TThostFtdcHedgeFlagType* t) {
  if (h == OrderHedgeFlag::kArbitrage)
    t[0] = THOST_FTDC_HF_Arbitrage;
  else if (h == OrderHedgeFlag::kHedge)
    t[0] = THOST_FTDC_HF_Hedge;
  else if (h == OrderHedgeFlag::kSpeculation)
    t[0] = THOST_FTDC_HF_Speculation;
  else if (h == OrderHedgeFlag::kMarketMaker)
    t[0] = THOST_FTDC_HF_MarketMaker;
}

OrderHedgeFlag ConvertFromSfitHedgeFlag(const TThostFtdcCombHedgeFlagType* t) {
  if (*t[0] == THOST_FTDC_HF_Speculation)
    return OrderHedgeFlag::kSpeculation;
  if (*t[0] == THOST_FTDC_HF_Arbitrage)
    return OrderHedgeFlag::kArbitrage;
  if (*t[0] == THOST_FTDC_HF_Hedge)
    return OrderHedgeFlag::kHedge;
  if (*t[0] == THOST_FTDC_HF_MarketMaker)
    return OrderHedgeFlag::kMarketMaker;
  return OrderHedgeFlag::kSpeculation;
}

void ConvertToSfitSelfCloseAction(future::SelfCloseType d, TThostFtdcOptSelfCloseFlagType& t) {
  if (d == future::SelfCloseType::kOptionPosition) {
    t = THOST_FTDC_OSCF_CloseSelfOptionPosition;
  } else if (d == future::SelfCloseType::kReserveOptionPosition) {
    t = THOST_FTDC_OSCF_ReserveOptionPosition;
  } else if (d == future::SelfCloseType::kSelfFuturePosition) {
    t = THOST_FTDC_OSCF_SellCloseSelfFuturePosition;
  } else {
    t = THOST_FTDC_OSCF_ReserveFuturePosition;
  }
}

future::SelfCloseType ConvertFromSfitSelfCloseAction(const TThostFtdcOptSelfCloseFlagType& t) {
  if (t == THOST_FTDC_OSCF_CloseSelfOptionPosition) {
    return future::SelfCloseType::kOptionPosition;
  } else if (t == THOST_FTDC_OSCF_ReserveOptionPosition) {
    return future::SelfCloseType::kReserveOptionPosition;
  } else if (t == THOST_FTDC_OSCF_SellCloseSelfFuturePosition) {
    return future::SelfCloseType::kSelfFuturePosition;
  } else {
    return future::SelfCloseType::kReserveFuturePosition;
  }
}

OrderHedgeFlag ConvertFromSfitHedgeFlag(const TThostFtdcHedgeFlagType* t) {
  if (*t == THOST_FTDC_HF_Speculation)
    return OrderHedgeFlag::kSpeculation;
  if (*t == THOST_FTDC_HF_Arbitrage)
    return OrderHedgeFlag::kArbitrage;
  if (*t == THOST_FTDC_HF_Hedge)
    return OrderHedgeFlag::kHedge;
  if (*t == THOST_FTDC_HF_MarketMaker)
    return OrderHedgeFlag::kMarketMaker;
  return OrderHedgeFlag::kSpeculation;
}

PriceType ConvertFromSfitOrderPriceType(const TThostFtdcOrderPriceTypeType* t) {
  if (*t == THOST_FTDC_OPT_AnyPrice)
    return PriceType::kAny;
  else if (*t == THOST_FTDC_OPT_LimitPrice)
    return PriceType::kLimit;
  else if (*t == THOST_FTDC_OPT_BestPrice)
    return PriceType::kBest;
  else if (*t == THOST_FTDC_OPT_FiveLevelPrice)
    return PriceType::kFiveLevel;
  return PriceType::kLimit;
}

OrderStatus ConvertFromSfitOrderStatus(const TThostFtdcOrderStatusType* t) {
  if (*t == THOST_FTDC_OST_Unknown || *t == THOST_FTDC_OST_PartTradedQueueing
    || *t == THOST_FTDC_OST_PartTradedNotQueueing || *t == THOST_FTDC_OST_NoTradeQueueing
    || *t == THOST_FTDC_OST_NoTradeNotQueueing) {
    return OrderStatus::kAlive;
  }
  return OrderStatus::kDead;
}

OrderTimeCondition ConvertFromSfitTimeCondition(const TThostFtdcTimeConditionType* t) {
  if (*t == THOST_FTDC_TC_IOC)
    return OrderTimeCondition::kIoc;
  if (*t == THOST_FTDC_TC_GFS)
