  if (*t == THOST_FTDC_TC_GFD)
    return OrderTimeCondition::kGfd;
  if (*t == THOST_FTDC_TC_GTD)
    return OrderTimeCondition::kGtd;
  if (*t == THOST_FTDC_TC_GTC)
    return OrderTimeCondition::kGtc;
  if (*t == THOST_FTDC_TC_GFA)
    return OrderTimeCondition::kGfa;
  return OrderTimeCondition::kGfd;
}

OrderVolumeCondition ConvertFromSfitVolumeCondition(const TThostFtdcVolumeConditionType* t) {
  if (*t == THOST_FTDC_VC_AV)
    return OrderVolumeCondition::kAny;
  if (*t == THOST_FTDC_VC_CV)
    return OrderVolumeCondition::kAll;
  if (*t == THOST_FTDC_VC_MV)
    return OrderVolumeCondition::kMin;
