    return future::ForceCloseReason::kLackDeposit;
  else if (*t == THOST_FTDC_FCC_ClientOverPositionLimit)
    return future::ForceCloseReason::kClientOverPositionLimit;
  else if (*t == THOST_FTDC_FCC_MemberOverPositionLimit)
