  else if (*t == THOST_FTDC_FCC_NotMultiple)
    return future::ForceCloseReason::kNotMultiple;
  else if (*t == THOST_FTDC_FCC_Violation)
    return future::ForceCloseReason::kViolation;
  else if (*t == THOST_FTDC_FCC_Other)
    return future::ForceCloseReason::kOther;
  else if (*t == THOST_FTDC_FCC_PersonDeliv)
