CtpMiniExecOrder::CtpMiniExecOrder(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("ctp_mini_rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(InsertExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertExecOrder(command);
  });
  m_service->RegisterCommandProcessor(CancelExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelExecOrder(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspInsertExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertExecOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnExecOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspExecOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspExecOrderAction(msg);
  });
  m_service->RegisterCommandProcessor(InsertOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqSelfClose(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOptionSelfCloseInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspSelfClose(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnOptionSelfCloseInsert, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspSelfClose(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOptionSelfClose, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnSelfClose(msg);
  });
  m_service->RegisterCommandProcessor(CancelOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelSelfClose(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOptionSelfCloseAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCancelSelfClose(msg);
  });
}

void CtpMiniExecOrder::ReqInsertExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 账户未登录");
    return;
  }
  CThostFtdcInputExecOrderField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.ExecOrderRef, std::to_string(req->exec_order_ref));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  ConvertToSfitOffsetFlag(req->offset, &field.OffsetFlag);
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  ConvertToSfitPosiDirection(req->direction, field.PosiDirection);
  ConvertToSfitExecAction(req->exec_action_type, field.ActionType);
  ConvertToSfitExecOrderCloseFlag(req->close_flag, field.CloseFlag);
  // 大商所放弃行权操作为：行权，行权量为0
  if (req->exchange_id == "DCE" && req->exec_action_type == future::ExecActionType::kAbandon) {
    field.ActionType = THOST_FTDC_ACTP_Exec;
    field.Volume = 0;
  } else {
    field.Volume = req->volume;
  }
  field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderInsert(&field, field.RequestID);
  LogCtpReq(m_logger, "ReqInsertExecOrder", &field, field.RequestID, ret);
  m_service->SetReqResponse(command, field.RequestID, ret);
}

void CtpMiniExecOrder::OnRspInsertExecOrder(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void CtpMiniExecOrder::OnRtnExecOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto execorder = std::static_pointer_cast<CThostFtdcExecOrderField>(msg->pMainField);
  auto target_execorder = std::make_shared<ExecOrder>();
  target_execorder->instrument_id = execorder->InstrumentID;
  target_execorder->exchange_id = execorder->ExchangeID;
  if (target_execorder->exchange_id.empty()) {
    auto ins = m_service->m_md_helper->GetShmInstrumentByInsID(target_execorder->instrument_id);
    if (ins.has_value()) {
      target_execorder->exchange_id = ins->exchange_id.data();
    }
  }
  target_execorder->investor_id = execorder->InvestorID;
  target_execorder->volume = execorder->Volume;
  target_execorder->direction = ConvertFromSfitPosiDirection(execorder->PosiDirection);
  target_execorder->offsetflag = ctp_mini::ConvertFromSfitOffset(execorder->OffsetFlag);
  target_execorder->hedge_flag = ConvertFromSfitHedgeFlag(&execorder->HedgeFlag);
  target_execorder->exchange_exec_order_sysid = GbkToUtf8(execorder->ExecOrderSysID);
  target_execorder->exec_order_id = ToFclibOrderId(execorder->ExecOrderRef, execorder->SessionID, execorder->FrontID);
  target_execorder->exec_action_type = ConvertFromSfitExecAction(execorder->ActionType);
  target_execorder->exec_close_flag = ConvertFromSfitExecOrderCloseFlag(execorder->CloseFlag);
  target_execorder->exec_result = ConvertFromSfitExecOrderResultType(execorder->ExecResult);
  target_execorder->status_msg = GbkToUtf8(execorder->StatusMsg);
  target_execorder->exec_order_ref = GbkToUtf8(execorder->ExecOrderRef);
  target_execorder->front_id = execorder->FrontID;
  target_execorder->session_id = execorder->SessionID;
  target_execorder->insert_date_time = StringToEpochNano(execorder->InsertDate, execorder->InsertTime);
  target_execorder->user_key = m_service->m_user_key;
  if (execorder->CancelTime[0] != '\0') {
    target_execorder->cancel_time = StringToEpochNano(execorder->InsertDate, execorder->CancelTime);
  }
  m_service->m_node_db->ReplaceRecord<ExecOrder>(target_execorder);
  auto req = m_service->m_command_manager->Update(std::to_string(msg->nRequestID));
  SetCommandFinished(req);
  if (target_execorder->exec_result == ExecOrderResultType::kNoExec) {
    m_alive_exec_order[target_execorder->exec_order_id] = execorder;
  } else {
    m_alive_exec_order.erase(target_execorder->exec_order_id);
    auto cancel_req = m_service->m_command_manager->Update("ReqCancelExecOrder" + target_execorder->exec_order_id);
    SetCommandFinished(cancel_req);
  }
  auto qry = std::make_shared<QueryInvestorPosition>(m_service->m_user_key);
  m_service->ExecuteCommand(qry);
}

void CtpMiniExecOrder::ReqCancelExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_service->m_command_manager->Update(command));
  if (!m_service->m_req_login) {
    SetCommandFinished(req, -1, u8"fclib: 账户未登录");
    return;
  }
  auto it = m_alive_exec_order.find(req->exec_order_id);
  if (it == m_alive_exec_order.end()) {
    SetCommandFinished(req, 1, u8"报单编号不存在");
    return;
  }
  auto origin = it->second;
  CThostFtdcInputExecOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.InstrumentID, origin->InstrumentID);
  strcpy_x(field.ExchangeID, origin->ExchangeID);
  strcpy_x(field.InvestorID, origin->InvestorID);
  strcpy_x(field.ExecOrderRef, origin->ExecOrderRef);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.IPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);

  field.ActionFlag = THOST_FTDC_AF_Delete;
  if (origin->ExecOrderSysID[0] == '\0') {
    field.ExecOrderActionRef = m_order_ref++;
    field.FrontID = origin->FrontID;
    field.SessionID = origin->SessionID;
  } else {
    strcpy_x(field.ExecOrderSysID, origin->ExecOrderSysID);
  }
  field.RequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqExecOrderAction(&field, field.RequestID);
  LogCtpReq(m_logger, "ReqCancelExecOrder", &field, field.RequestID, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqCancelExecOrder" + req->exec_order_id);
  req->status = UserCommand::Status::kStarted;
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
  }
}

