void CtpMiniServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: CtpMini柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

void CtpMiniServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  m_last_process = true;
  if (m_new_day)
    return;
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int CtpMiniServiceImpl::RunOnce() {
  if (m_log_replayer && m_log_replayer->m_pause && !m_last_process) {
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
      login->user_key = m_user_key;
      login->status_msg = "log replay finished";
    });
  }
  m_node_release->ReleaseNode();
  m_last_process = false;
  return 0;
}

