int CtpMiniServiceImpl::BuildApi(std::shared_ptr<UserCommand> command) {
  m_req_login = std::static_pointer_cast<ReqLogin>(m_command_manager->Update(command));
  DeleteApi();
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_ctp_mini_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = ThostApiCreator(m_flow_dir.c_str());
  m_spi = new CtpMiniSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  m_api->SubscribePrivateTopic(THOST_TERT_RESUME);
  m_api->SubscribePublicTopic(THOST_TERT_RESUME);
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    m_api->Init();
  }
  if (!m_req_login->replay_flow_file_name.empty()) {
    m_log_replayer = std::make_shared<CtpMiniLogReplayer>();
    m_log_replayer->OpenLogFile(m_req_login->replay_flow_file_name, m_spi);
    return 0;
  }
  if (m_req_login->user_id == "STRESS-TESTING-100") {
    m_spi->StartStressTesting();
    SetCommandFinished(m_req_login);
  }
  return 0;
}

void CtpMiniServiceImpl::DeleteApi() {
  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
    m_trading_day = "";
  }
  m_api->Release();
  m_api = nullptr;
}

void CtpMiniServiceImpl::CleanUp() {}

int CtpMiniServiceImpl::GenerateRequestID() {
  return m_req_id++;
}

void CtpMiniServiceImpl::SetReqResponse(std::shared_ptr<UserCommand> c, int request_id, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, std::to_string(request_id));
}

void CtpMiniServiceImpl::SetNodeRelease() {
  NodeRelease::NodeReleaseFunc release_funcs;
  release_funcs.order_release = [](const future::Order* order) {
    return order->status == future::OrderStatus::kDead;
  };
  release_funcs.trade_release = [](const future::Trade* trade) {
    return !isnan(trade->commission);
  };
  release_funcs.quote_release = [](const future::Quote* quote) {
    return quote->status == future::OrderStatus::kDead && !quote->ask_order_id.empty() && !quote->bid_order_id.empty();
  };
  m_node_release = std::make_shared<NodeRelease>(m_node_db, release_funcs, m_logger);
}

