// 计算成交手续费
double CalcTradeCommission(
  std::shared_ptr<RateNode> rate_node, std::shared_ptr<Trade> trade, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!rate_node)
    return NAN;
  auto volume_multiple = helper->GetShmInstrumentField(trade->Symbol(), &shm::ShmInstrument::volume_multiple, true);
  if (!volume_multiple.has_value())
    return NAN;
  if (trade->offset == Offset::kOpen) {
    auto commission = rate_node->Latest()->commission_rate_open;
    return (commission.volume_rate + commission.amount_rate * trade->price * volume_multiple.value()) * trade->volume;
  }
  auto commission_close = rate_node->Latest()->commission_rate_close;
  auto commission_close_today = rate_node->Latest()->commission_rate_close_today;
  return (commission_close.volume_rate + commission_close.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_yesterday
    + (commission_close_today.volume_rate + commission_close_today.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_today;
}

CtpMiniOrderTradeView::CtpMiniOrderTradeView(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnQuote, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnQuote(msg);
  });

  m_trade_view = m_service->m_node_db->CreateView<Trade>([=](std::shared_ptr<const Trade> trade) {
    return trade->user_key == m_service->m_user_key;
  });
  m_rate_view = m_service->m_node_db->CreateView<Rate>([=](std::shared_ptr<const Rate> rate) {
    return rate->user_key == m_service->m_user_key;
  });
  m_rate_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<RateNode> rate_node) {
    auto instrument_id = rate_node->Latest()->instrument_id;
    for (const auto& [key, trade_node] : m_trade_view->GetNodes()) {
      if (trade_node->Latest()->instrument_id != instrument_id)
        continue;
      m_service->m_node_db->ReplaceRecord<Trade>(key, [=](std::shared_ptr<Trade> trade) {
        trade->commission = CalcTradeCommission(rate_node, trade, m_service->m_md_helper);
      });
    }
  });
}

void CtpMiniOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto pOrder = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pOrder->OrderRef, pOrder->SessionID, pOrder->FrontID);
  auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
  auto order_node = m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    if (o->order_id.empty()) {
      auto iter = m_service->m_send_time.find(order_id);
      if (iter != m_service->m_send_time.end()) {
        o->send_date_time = iter->second;
        m_service->m_send_time.erase(iter);
      }
      o->receive_date_time = NowAsEpochNano();
    }
    o->exchange_id = pOrder->ExchangeID;
    o->instrument_id = pOrder->InstrumentID;
    o->investor_id = pOrder->InvestorID;
    if (pOrder->UserID[0] == '\0')
      o->user_id = pOrder->InvestorID;
    else
      o->user_id = pOrder->UserID;
    o->direction = ctp_mini::ConvertFromSfitDirection(&pOrder->Direction);
    o->exchange_order_id = pOrder->OrderSysID;
    o->status_msg = GbkToUtf8(pOrder->StatusMsg);
    o->limit_price = pOrder->LimitPrice;
    o->offset = ctp_mini::ConvertFromSfitOffset(pOrder->CombOffsetFlag[0]);
    o->hedge_flag = ctp_mini::ConvertFromSfitHedgeFlag(&pOrder->CombHedgeFlag);
    o->price_type = ctp_mini::ConvertFromSfitOrderPriceType(&pOrder->OrderPriceType);
    o->status = ctp_mini::ConvertFromSfitOrderStatus(&pOrder->OrderStatus);
    o->time_condition = ctp_mini::ConvertFromSfitTimeCondition(&pOrder->TimeCondition);
    o->volume_condition = ctp_mini::ConvertFromSfitVolumeCondition(&pOrder->VolumeCondition);
    o->force_close_reason = ctp_mini::ConvertFromSfitForceClose(&pOrder->ForceCloseReason);
    o->volume_left = pOrder->VolumeTotal;
    o->volume_orign = pOrder->VolumeTotalOriginal;
    o->order_ref = pOrder->OrderRef;
    o->session_id = pOrder->SessionID;
    o->front_id = pOrder->FrontID;
    o->order_local_id = pOrder->OrderLocalID;
    o->trader_id = pOrder->TraderID;
    o->min_volume = pOrder->MinVolume;
    o->is_swap_order = pOrder->IsSwapOrder;
    o->request_id = std::to_string(pOrder->RequestID);
    // ctp_mini 委托单缺少 TradingDay
    if ((pOrder->TradingDay[0] != '\0' || !m_service->m_trading_day.empty())) {
      std::string date = (pOrder->TradingDay[0] != '\0') ? pOrder->TradingDay : m_service->m_trading_day;
      if (pOrder->InsertTime[0] != '\0') {
        o->insert_date_time = GetRealTradeTime(date.c_str(), pOrder->InsertTime);
      }
      if (pOrder->CancelTime[0] != '\0') {
        o->dead_date_time = GetRealTradeTime(date.c_str(), pOrder->CancelTime);
      }
    }
    // 做市产生的订单没有下单时间,赋值标志 "E"
    if (pOrder->InsertTime[0] == '\0' && m_service->m_session_id == pOrder->SessionID) {
      o->insert_date_time = NowAsEpochNano();
    }
    std::string user_product_info = pOrder->UserProductInfo;
    o->user_product_info = user_product_info;
    o->order_id = order_id;
    if (user_product_info.find("SHINNY") != 0 && user_product_info.find("shinny") != 0)
      o->unit_id = -1;
    else
      o->unit_id = std::atoll(pOrder->OrderRef) % 100;
    o->is_quote = pOrder->OrderType == '1';
    if (o->exchange_id.empty()) {
      auto ins = m_service->m_md_helper->GetShmInstrumentByInsID(o->instrument_id);
      if (ins.has_value()) {
        o->exchange_id = ins->exchange_id.data();
      }
    }
    o->user_key = m_service->m_user_key;
  });
  m_order_map[pOrder->OrderSysID] = order_id;
}

void CtpMiniOrderTradeView::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  auto pOrder = std::static_pointer_cast<CThostFtdcInputOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(pOrder->OrderRef, m_service->m_session_id, m_service->m_front_id);
  auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    o->exchange_id = pOrder->ExchangeID;
    o->instrument_id = pOrder->InstrumentID;
    o->investor_id = pOrder->InvestorID;
    if (pOrder->UserID[0] == '\0')
      o->user_id = pOrder->InvestorID;
    else
      o->user_id = pOrder->UserID;
    o->direction = ctp_mini::ConvertFromSfitDirection(&pOrder->Direction);
    o->status = OrderStatus::kAlive;
    if (msg->RspInfo.ErrorID != 0) {
      o->status = OrderStatus::kDead;
      o->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
    }
    o->limit_price = pOrder->LimitPrice;
    o->offset = ctp_mini::ConvertFromSfitOffset(pOrder->CombOffsetFlag[0]);
    o->hedge_flag = ctp_mini::ConvertFromSfitHedgeFlag(&pOrder->CombHedgeFlag);
    o->price_type = ctp_mini::ConvertFromSfitOrderPriceType(&pOrder->OrderPriceType);
    o->time_condition = ctp_mini::ConvertFromSfitTimeCondition(&pOrder->TimeCondition);
    o->volume_condition = ctp_mini::ConvertFromSfitVolumeCondition(&pOrder->VolumeCondition);
    o->force_close_reason = ctp_mini::ConvertFromSfitForceClose(&pOrder->ForceCloseReason);
    o->volume_left = pOrder->VolumeTotalOriginal;
    o->volume_orign = pOrder->VolumeTotalOriginal;
    o->order_ref = pOrder->OrderRef;
    o->session_id = m_service->m_session_id;
    o->front_id = m_service->m_front_id;
    o->min_volume = pOrder->MinVolume;
    o->is_swap_order = pOrder->IsSwapOrder;
    o->request_id = std::to_string(pOrder->RequestID);
    o->insert_date_time = NowAsEpochNano();
    o->dead_date_time = NowAsEpochNano();
    o->order_id = order_id;
    if (o->exchange_id.empty()) {
      auto ins = m_service->m_md_helper->GetShmInstrumentByInsID(o->instrument_id);
      if (ins.has_value()) {
        o->exchange_id = ins->exchange_id.data();
      }
    }
    o->user_key = m_service->m_user_key;
  });
}

void CtpMiniOrderTradeView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  auto field = std::static_pointer_cast<CThostFtdcTradeField>(msg->pMainField);
  auto trade_key = Trade::MakeKey(m_service->m_user_key, field->TradeID, field->OrderSysID);
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> t) {
    t->investor_id = field->InvestorID;
    if (field->UserID[0] == '\0')
      t->user_id = field->InvestorID;
    else
      t->user_id = field->UserID;
    if (field->TradeTime[0] != '\0') {
      if (field->TradeDate[0] != '\0')
        t->trade_date_time = StringToEpochNano(field->TradeDate, field->TradeTime);
      else if (field->TradingDay[0] != '\0')
        t->trade_date_time = GetRealTradeTime(field->TradingDay, field->TradeTime);
    }
    t->exchange_id = field->ExchangeID;
    t->instrument_id = field->InstrumentID;
    t->exchange_trade_id = field->TradeID;
    t->exchange_order_id = field->OrderSysID;
    t->order_local_id = field->OrderLocalID;
    t->price = field->Price;
    t->volume = field->Volume;
    t->trader_id = field->TraderID;
    t->direction = ctp_mini::ConvertFromSfitDirection(&field->Direction);
    t->offset = ctp_mini::ConvertFromSfitOffset(field->OffsetFlag);
    t->hedge_flag = ConvertFromSfitHedgeFlag(&field->HedgeFlag);
    if (t->exchange_id.empty()) {
      auto ins = m_service->m_md_helper->GetShmInstrumentByInsID(t->instrument_id);
      if (ins.has_value()) {
        t->exchange_id = ins->exchange_id.data();
      }
    }
    t->user_key = m_service->m_user_key;
    t->order_id = m_order_map.at(field->OrderSysID);
    auto rate_node = m_service->m_node_db->GetNode<Rate>(m_service->m_user_key + "|" + t->instrument_id);
    auto commission = CalcTradeCommission(rate_node, t, m_service->m_md_helper);
    // 无法计算, 进行手续费率查询
    if (isnan(commission)) {
      auto req = std::make_shared<fclib::future::QueryCommissionRate>(m_service->m_user_key);
      req->exchange_id = t->exchange_id;
      req->instrument_id = t->instrument_id;
      m_service->ExecuteCommand(req);
    } else {
      t->commission = commission;
    }
  });
}

void CtpMiniOrderTradeView::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto quote = std::static_pointer_cast<CThostFtdcQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(quote->QuoteRef, quote->SessionID, quote->FrontID);
  auto user_id = std::string(quote->UserID);
  auto investor_id = std::string(quote->InvestorID);
  auto quote_key = m_service->m_user_key + "|" + quote_id;
  auto quote_node_db = m_service->m_node_db->ReplaceRecord<Quote>(quote_key, [=](std::shared_ptr<Quote> target_quote) {
    target_quote->user_key = m_service->m_user_key;
    target_quote->investor_id = investor_id;
    if (user_id.empty())
      target_quote->user_id = investor_id;
    else
      target_quote->user_id = user_id;
    target_quote->instrument_id = quote->InstrumentID;
    target_quote->exchange_id = quote->ExchangeID;
    if (target_quote->exchange_id.empty()) {
      auto ins = m_service->m_md_helper->GetShmInstrumentByInsID(target_quote->instrument_id);
      if (ins.has_value()) {
        target_quote->exchange_id = ins->exchange_id.data();
      }
    }
    target_quote->response_quote_id = quote->ForQuoteSysID;
    target_quote->ask_price = quote->AskPrice;
    target_quote->bid_price = quote->BidPrice;
    target_quote->ask_volume = quote->AskVolume;
    target_quote->bid_volume = quote->BidVolume;
    target_quote->ask_offset = ConvertFromSfitOffset(quote->AskOffsetFlag);
    target_quote->bid_offset = ConvertFromSfitOffset(quote->BidOffsetFlag);
    target_quote->ask_hedge_flag = ConvertFromSfitHedgeFlag(&quote->AskHedgeFlag);
    target_quote->bid_hedge_flag = ConvertFromSfitHedgeFlag(&quote->BidHedgeFlag);
    target_quote->status = ConvertFromSfitOrderStatus(&quote->QuoteStatus);
    if (target_quote->quote_id.empty())
      target_quote->quote_id = quote_id;
  });
}

