SubPosition* GetSubPosition(
  std::shared_ptr<Position> position, const Direction& trade_direction, const Offset& offset) {
  SubPosition* subpos = nullptr;
  if ((trade_direction == Direction::kBuy && offset == Offset::kOpen)
    || (trade_direction == Direction::kSell && offset != Offset::kOpen))
    subpos = &position->subpos_long_spec;
  else
    subpos = &position->subpos_short_spec;
  return subpos;
}

future::SubPosition* GetSubPosition(
  std::shared_ptr<future::Position> position, TThostFtdcPosiDirectionType posi_dir, TThostFtdcHedgeFlagType hedge) {
  if (posi_dir == THOST_FTDC_PD_Long) {
    if (hedge == THOST_FTDC_HF_Speculation)
      return &position->subpos_long_spec;
    else
      return &position->subpos_long_other;
  } else if (posi_dir == THOST_FTDC_PD_Short) {
    if (hedge == THOST_FTDC_HF_Speculation)
      return &position->subpos_short_spec;
    else
      return &position->subpos_short_other;
  }
  FCASSERT(false);
  return nullptr;
}

void CalcPositionCost(SubPosition* subpos, int close_volume, double volume_multiple, double trade_price) {
  for (auto it = subpos->_open_list.begin(); it != subpos->_open_list.end();) {
    int close_vol = std::min(close_volume, it->second);
    close_volume -= close_vol;
    it->second -= close_vol;
    if (it->second == 0) {
      it = subpos->_open_list.erase(it);
      if (close_volume > 0)
        continue;
    }
    break;
  }
  subpos->_position_cost = 0;
  for (auto open : subpos->_open_list) {
    subpos->_position_cost += open.first * open.second * volume_multiple;
  }
}

void RegulateAccount(std::shared_ptr<Account> account) {
  account->balance = account->pre_balance + account->deposit - account->withdraw + account->close_profit
    + account->position_profit - account->commission + account->premium + account->option_market_value;
  account->client_equity = account->balance - account->option_market_value;
  account->available = account->client_equity - account->margin - account->frozen_margin - account->frozen_commission
    - account->frozen_premium;
  account->risk_ratio = std::fabs(account->client_equity) < 1e-5 ? 0.0 : account->margin / account->client_equity;
  account->ref_risk_ratio = std::fabs(account->client_equity) < 1e-5 ? 0.0 : account->margin / account->balance;
}

void UpdatePositionVolumeFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->OrderFrozen();
  calc_subpos->volume_his_frozen = std::min(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

CtpMiniPositionAccount::CtpMiniPositionAccount(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryInvestorPosition::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryInvestorPosition(command);
  });
  m_service->RegisterCommandProcessor(PositionCombAuto::AID, [this](std::shared_ptr<UserCommand> command) {
    auto req = std::static_pointer_cast<PositionCombAuto>(m_service->m_command_manager->Update(command));
    m_service->m_options.position_comb_auto = req->auto_combi;
    m_logger.With("position_comb_auto", m_service->m_options.position_comb_auto).Info("PositionCombAuto");
    SetCommandFinished(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQryTradingAccount(command);
  });
  m_service->RegisterCommandProcessor(PositionCombInsert::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqDcePositionCombInsert(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingAccount, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingAccount(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryInvestorPosition, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryInvestorPosition(msg);
  });
  m_service->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspQryInvestorPositionForComb, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspQryInvestorPositionForComb(msg);
    });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspCombActionInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspCombActionInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnCombAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnCombAction(msg);
  });
  m_position_view = m_service->m_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_service->m_user_key && pos->unit_id == 0;
  });
  m_dce_position_comb = std::make_shared<DcePositionAutoComb>(m_position_view, m_service->m_md_helper, m_logger);
}

void CtpMiniPositionAccount::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0)
    return;
  ReqQryInvestorPosition(nullptr);
  ReqQryTradingAccount(nullptr);
}

void CtpMiniPositionAccount::ReqQryTradingAccount(std::shared_ptr<UserCommand> command) {
  if (m_service->m_query_planner.AlreadyInQueue("ReqQryTradingAccount")) {
    SetCommandFinished(command, -1, u8"fclib: 已存在相同查询");
    return;
  }
  auto qry = std::static_pointer_cast<QueryTradingAccount>(m_service->m_command_manager->Update(command));
  auto field = std::make_shared<CThostFtdcQryTradingAccountField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryTradingAccountField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  if (qry != nullptr)
    strcpy_x(field->CurrencyID, qry->currency);
  int req_id;
  if (qry && qry->query_request_id > 0) {
    req_id = qry->query_request_id;
  } else {
    req_id = m_service->GenerateRequestID();
  }
  m_service->m_ioc->post([=]() {
    m_service->m_query_planner.AddTask(
      "ReqQryTradingAccount", CtpMiniQueryPlanner::Priority::kHigh, req_id,
      [=](int request_id) {
        int ret = m_service->m_api->ReqQryTradingAccount(field.get(), request_id);
        LogCtpReq(m_logger, "ReqQryTradingAccount", field.get(), request_id, ret);
        m_service->SetReqResponse(command, request_id, ret);
        return ret;
      },
      50);
  });
}

void CtpMiniPositionAccount::OnRspQryTradingAccount(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<CThostFtdcTradingAccountField>(msg->pMainField);
  std::string account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> a) {
    a->user_key = m_service->m_user_key;
    a->investor_id = field->AccountID;
    a->available = field->Available;
    a->close_profit = field->CloseProfit;
    a->commission = field->Commission;
    a->currency = field->CurrencyID;
    a->deposit = field->Deposit;
    a->frozen_commission = field->FrozenCommission;
    a->frozen_margin = field->FrozenMargin;
    a->margin = field->CurrMargin;
    a->position_profit = field->PositionProfit;
    a->pre_balance = field->PreBalance;
    a->withdraw = field->Withdraw;
    a->premium = field->CashIn;
    a->frozen_premium = field->FrozenCash;
    a->withdraw_quota = field->WithdrawQuota;
    a->reserve = field->Reserve;
    a->pre_mortgage = field->PreMortgage;
    a->pre_credit = field->PreCredit;
    a->credit = field->Credit;
    a->delivery_margin = field->DeliveryMargin;
    a->mortgage = field->Mortgage;
    a->pre_fund_mortgagein = field->PreFundMortgageIn;
    a->pre_fund_mortgageout = field->PreFundMortgageOut;
    a->fund_mortgagein = field->FundMortgageIn;
    a->fund_mortgageout = field->FundMortgageOut;
    a->fund_mortgageavailable = field->FundMortgageAvailable;
    a->mortgageablefund = field->MortgageableFund;
    a->spec_product_margin = field->SpecProductMargin;
    a->spec_product_frozenmargin = field->SpecProductFrozenMargin;
    a->spec_product_commission = field->SpecProductCommission;
    a->spec_product_frozen_commission = field->SpecProductFrozenCommission;
    a->spec_product_position_profit = field->SpecProductPositionProfit;
    a->spec_product_close_profit = field->SpecProductCloseProfit;
    // CTP mini 没有 Balacnce数据
    a->client_equity = a->pre_balance + a->deposit - a->withdraw + a->close_profit - a->commission + a->premium
      + a->position_profit + a->fund_mortgagein - a->pre_fund_mortgagein - a->pre_credit + a->mortgage
      - a->pre_mortgage;
    a->balance = a->client_equity + a->option_market_value;
    if (a->client_equity > 0) {
      a->risk_ratio = a->margin / a->client_equity;
    }
    if (a->balance > 0) {
      a->ref_risk_ratio = a->margin / a->balance;
    }
  });
  if (!m_acoount_inited) {
    m_acoount_inited = true;
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
        target_login->account_ready = true;
      });
    UpdateAccountProfit();
  }
}

