}

void CtpMiniPositionAccount::ReqQryInvestorPositionForComb() {
  auto field = std::make_shared<CThostFtdcQryInvestorPositionForCombField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryInvestorPositionForCombField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  int req_id = m_service->GenerateRequestID();
  m_service->m_ioc->post([=]() {
    m_service->m_query_planner.AddTask(
      "ReqQryInvestorPositionForComb", CtpMiniQueryPlanner::Priority::kHigh, req_id,
      [=](int request_id) {
        int ret = m_service->m_api->ReqQryInvestorPositionForComb(field.get(), request_id);
        m_logger.With("request_id", request_id).With("ret", ret).Info("ReqQryInvestorPositionForComb");
        return ret;
      },
      50);
  });
}

void CtpMiniPositionAccount::OnRspQryInvestorPositionForComb(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto detail = std::static_pointer_cast<CThostFtdcInvestorPositionForCombField>(msg->pMainField);
  if (detail->LegID == 0) {
    std::string position_symbol = std::string(detail->ExchangeID) + "." + std::string(detail->CombInstrumentID);
    auto position_key = m_service->m_user_key + "|0|" + position_symbol;
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target) {
      target->last_price = NAN;
      target->investor_id = detail->InvestorID;
      target->exchange_id = detail->ExchangeID;
      target->instrument_id = detail->CombInstrumentID;
      future::SubPosition* subpos = nullptr;
      if (detail->LegDirection == THOST_FTDC_D_Buy) {
        if (detail->LegHedgeFlag == THOST_FTDC_HF_Speculation)
          subpos = &target->subpos_long_spec;
        else
          subpos = &target->subpos_long_other;
      } else {
        if (detail->LegHedgeFlag == THOST_FTDC_HF_Speculation)
          subpos = &target->subpos_short_spec;
        else
          subpos = &target->subpos_short_other;
      }
      subpos->volume_his = detail->TotalAmt;
      target->user_key = m_service->m_user_key;
    });
  }
}

void CtpMiniPositionAccount::ReqDcePositionCombInsert(std::shared_ptr<UserCommand> command) {
  auto comb_command = std::static_pointer_cast<PositionCombInsert>(m_service->m_command_manager->Update(command));
  CThostFtdcInputCombActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.InstrumentID, comb_command->instrument_id);
  int request_id = m_service->GenerateRequestID();
  strcpy_x(field.CombActionRef, std::to_string(request_id));
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.ExchangeID, comb_command->exchange_id);
  ConvertToSfitDirection(comb_command->direction, &field.Direction);
  field.Volume = comb_command->volume;
  if (comb_command->comb_direction == CombDirection::kComb)
    field.CombDirection = THOST_FTDC_CMDR_Comb;
  else
    field.CombDirection = THOST_FTDC_CMDR_UnComb;
  ConvertToSfitHedgeFlag(comb_command->hedge_flag, &field.HedgeFlag);
  int ret = m_service->m_api->ReqCombActionInsert(&field, request_id);
  LogCtpReq(m_logger, "ReqCombActionInsert", &field, request_id, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqDcePositionCombInsert" + std::string(field.CombActionRef));
  if (ret != 0) {
    SetCommandFinished(comb_command, ret, u8"指令发送失败");
  }
}

void CtpMiniPositionAccount::OnRspCombActionInsert(std::shared_ptr<SpiMessage> msg) {
  auto comb_action_field = std::static_pointer_cast<CThostFtdcInputCombActionField>(msg->pMainField);
  auto req =
    m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action_field->CombActionRef));
  SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
}

void CtpMiniPositionAccount::OnRtnCombAction(std::shared_ptr<SpiMessage> msg) {
  auto comb_action = std::static_pointer_cast<CThostFtdcCombActionField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action->CombActionRef));
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Rejected) {
    SetCommandFinished(req, -1, GbkToUtf8(comb_action->StatusMsg));
    return;
  }
  // 只有当被接受才指令完成
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Accepted) {
    ReqQryTradingAccount(nullptr);
    ReqQryInvestorPositionForComb();
    SetCommandFinished(req);
  }
}

void CtpMiniPositionAccount::RefreshPositionAccount() {
  bool update = m_position_inited && !m_market_value_yesterday_inited;
  auto& target_position_node_map = m_position_view->GetNodes();
  for (auto& [pos_key, position_node] : target_position_node_map) {
    auto position = position_node->Latest();
    auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
    if (!ins.has_value() || ins->product_class == md::ProductClass::kCombine || ins->last_price == position->last_price
      || std::isnan(ins->last_price) || !std::isnan(ins->settlement) || !ins->CheckQuote(m_service->m_trading_day))
      continue;
    m_service->GetNodeDb()->ReplaceRecord<Position>(pos_key, [this](std::shared_ptr<Position> calc_position) {
      UpdatePositionProfit(calc_position);
    });
    update = true;
  }
  if (update)
    UpdateAccountProfit();
}

