CtpMiniOrderQuoteConnection::CtpMiniOrderQuoteConnection(CtpMiniServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_quote_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnQuote, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnQuote(msg);
  });
}

void CtpMiniOrderQuoteConnection::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  // 使用 OrderSysID 作为 key
  auto pOrder = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  if (pOrder->OrderType != THOST_FTDC_ORDT_DeriveFromQuote)
    return;
  if (pOrder->OrderSysID[0] == '\0') {
    m_logger.Error("Empty OrderSysID");
    return;
  }
  auto order_id = ToFclibOrderId(pOrder->OrderRef, pOrder->SessionID, pOrder->FrontID);
  auto it = m_quote_map.find(pOrder->OrderSysID);
  if (it == m_quote_map.end()) {
    m_order_map[pOrder->OrderSysID] = order_id;
    return;
  }
  auto quote_key = m_service->m_user_key + "|" + it->second;
  if (nullptr == m_service->GetNodeDb()->GetNode<Quote>(quote_key)) {
    m_quote_map.erase(it);
    m_order_map.erase(pOrder->OrderSysID);
    return;
  }
  m_service->GetNodeDb()->ReplaceRecord<Quote>(quote_key, [&](std::shared_ptr<future::Quote> q) {
    if (pOrder->Direction == THOST_FTDC_D_Buy) {
      q->bid_order_id = order_id;
    } else {
      q->ask_order_id = order_id;
    }
  });
  m_quote_map.erase(it);
}

void CtpMiniOrderQuoteConnection::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pQuote = std::static_pointer_cast<CThostFtdcQuoteField>(msg->pMainField);
  if (pQuote->QuoteSysID[0] == '\0')
    return;
  auto quote_id = ToFclibOrderId(pQuote->QuoteRef, pQuote->SessionID, pQuote->FrontID);
  auto quote_key = m_service->m_user_key + "|" + quote_id;
  auto quote_node = m_service->GetNodeDb()->GetNode<Quote>(quote_key);
  if (!quote_node)
    return;
  if (quote_node->Latest()->bid_order_id.empty()) {
    UpdateConnectionByQuote(pQuote->BidOrderSysID, Direction::kBuy, quote_node);
  }
  if (quote_node->Latest()->ask_order_id.empty()) {
    UpdateConnectionByQuote(pQuote->AskOrderSysID, Direction::kSell, quote_node);
  }
}

void CtpMiniOrderQuoteConnection::UpdateConnectionByQuote(
  const std::string& order_sys_id, const Direction& d, std::shared_ptr<QuoteNode> quote_node) {
  auto it = m_order_map.find(order_sys_id);
  if (it == m_order_map.end()) {
    m_quote_map[order_sys_id] = quote_node->Latest()->quote_id;
    return;
  }
  const auto& order_id = it->second;
  auto order_key = Order::MakeKey(m_service->m_user_key, order_id);
  m_service->GetNodeDb()->ReplaceRecord<Quote>(quote_node->Latest()->GetKey(), [&](std::shared_ptr<future::Quote> q) {
    if (d == Direction::kBuy) {
      q->bid_order_id = order_id;
    } else {
      q->ask_order_id = order_id;
    }
  });
  m_order_map.erase(it);
}

int CtpMiniOrderQuoteConnection::RunOnce() {
  return 0;
}

