#include <string>
#include <vector>
#include <list>
#include "fclib/utils/fcassert.h"

namespace fclib {
namespace future {

// 获取某个持仓明细的唯一key
std::string GetPositionDetailKey(std::shared_ptr<PositionDetail> detail) {
  return detail->open_exchange_order_id + detail->open_exchange_trade_id + std::to_string(detail->open_trading_day);
}

// 根据单项持仓明细计算变动
bool CalcChangeByDetails(const std::list<std::shared_ptr<PositionDetail>>& snap_details,
  const std::list<std::shared_ptr<PositionDetail>>& history_details, std::shared_ptr<PositionDetailChangeBase> ret) {
  if (snap_details.empty() && history_details.empty()) {
    return false;
  }
  if (snap_details.empty() && !history_details.empty()) {
    ret->delete_cnt = static_cast<int>(history_details.size());
    return true;
  }
  if (!snap_details.empty() && history_details.empty()) {
    for (const auto& detail : snap_details) {
      ret->add_details.push_back(detail);
    }
    return true;
  }
  bool res = false;
  ret->delete_cnt = 0;
  std::string snap_first_key = GetPositionDetailKey(snap_details.front());
  std::string history_last_key = GetPositionDetailKey(history_details.back());

  // 计算删除明细数量和手数差异
  for (const auto& detail : history_details) {
    if (GetPositionDetailKey(detail) == snap_first_key) {
      ret->modify_volume = detail->volume - snap_details.front()->volume;
      if (ret->modify_volume > 0)
        res = true;
      break;
    }
    ++(ret->delete_cnt);
    res = true;
  }
  // 计算增加的明细
  for (auto it = snap_details.rbegin(); it != snap_details.rend(); ++it) {
    auto detail = *it;
    if (GetPositionDetailKey(detail) == history_last_key) {
      break;
    } else {
      ret->add_details.push_front(detail);
      res = true;
    }
  }
  return res;
}

bool CalcSubPositionDetailChange(
  const SubPosition* snap_sub, const SubPosition* history_sub, std::shared_ptr<PositionDetailChange> ret) {
  bool res = false;
  std::list<std::shared_ptr<PositionDetail>> empty;
  {
    // 计算昨仓明细变动
    if (nullptr == ret->his_change)
      ret->his_change = std::make_shared<PositionDetailChangeBase>();
    const auto& history_position_details = (nullptr == history_sub) ? empty : history_sub->his_position_details;
    const auto& snap_position_details = (nullptr == snap_sub) ? empty : snap_sub->his_position_details;
    res |= CalcChangeByDetails(snap_position_details, history_position_details, ret->his_change);
  }
  {
    // 计算今仓明细变动
    if (nullptr == ret->today_change)
      ret->today_change = std::make_shared<PositionDetailChangeBase>();
    const auto& history_position_details = (nullptr == history_sub) ? empty : history_sub->today_position_details;
    const auto& snap_position_details = (nullptr == snap_sub) ? empty : snap_sub->today_position_details;
    res |= CalcChangeByDetails(snap_position_details, history_position_details, ret->today_change);
  }
  return res;
}

void CalcSubPositionDetailByChange(
  const std::shared_ptr<PositionDetailChangeBase> detail_change, std::list<std::shared_ptr<PositionDetail>>* details) {
  // 移除头部
  while (detail_change->delete_cnt--) {
    details->pop_front();
  }
  // 更新头部
  if (detail_change->modify_volume != 0 && !details->empty()) {
    auto new_front = std::make_shared<PositionDetail>(*details->front());
    new_front->volume -= detail_change->modify_volume;
    FCASSERT(new_front->volume > 0);
    details->pop_front();
    details->emplace_front(new_front);
  }
  // 增加尾部
  for (const auto& detail : detail_change->add_details) {
    details->emplace_back(detail);
  }
}

void PositionDetailCalculator::CalcPositionDetailChange(
  const std::shared_ptr<PositionNode> node, std::vector<std::shared_ptr<PositionDetailChange>>* ret) {
  FCASSERT(nullptr != ret);
  FCASSERT(nullptr != node);
  ret->clear();
  if (nullptr == node->Snap() && nullptr == node->Historical())
    return;
  bool update = false;
  // 分别计算子持仓明细变动
  for (auto p : {&Position::subpos_long_spec, &Position::subpos_short_spec, &Position::subpos_long_other,
         &Position::subpos_short_other}) {
    const SubPosition* snap_sub = (nullptr != node->Snap()) ? &(node->Snap().get()->*p) : nullptr;
    const SubPosition* his_sub = (nullptr != node->Historical()) ? &(node->Historical().get()->*p) : nullptr;

    auto r = std::make_shared<PositionDetailChange>();
    update |= CalcSubPositionDetailChange(snap_sub, his_sub, r);
    ret->push_back(r);
  }
  if (!update) {
    ret->clear();
  }
}

void PositionDetailCalculator::CalcPositionDetailByChange(
  std::shared_ptr<Position> position, const std::vector<std::shared_ptr<PositionDetailChange>>& change) {
  if (change.size() != 4)
    return;
  int index = 0;
  for (auto p : {&Position::subpos_long_spec, &Position::subpos_short_spec, &Position::subpos_long_other,
         &Position::subpos_short_other}) {
    auto subpos = &(position.get()->*p);
    auto detail_change = change[index];
    ++index;
    CalcSubPositionDetailByChange(detail_change->his_change, &subpos->his_position_details);
    CalcSubPositionDetailByChange(detail_change->today_change, &subpos->today_position_details);
  }
}

