XOneUnitExecOrder::XOneUnitExecOrder(
  XOneServiceImpl* service, XOneApiAdapter* api_adapter, structlog::Logger& parent_logger)
  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("exec_order_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  // 行权
  m_service->RegisterCommandProcessor(InsertExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertExecOrder(command);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspInsertExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspInsertExecOrder(msg);
  });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnExecOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspInsertExecOrder(msg);
    });
  // 取消行权
  m_service->RegisterCommandProcessor(CancelExecOrder::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelExecOrder(command);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspExecOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspExecOrderAction(msg);
  });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnExecOrderAction, [this](std::shared_ptr<SpiMessage> msg) {
      OnErrRtnExecOrderAction(msg);
    });
  // 行权或取消行权
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnExecOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnExecOrder(msg);
  });
  // 自对冲
  m_service->RegisterCommandProcessor(InsertOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqInsertOptionSelfClose(command);
  });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspOptionSelfCloseInsert, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspOptionSelfClose(msg);
    });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnInsertOptionSelfClose, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspOptionSelfClose(msg);
    });
  // 取消自对冲
  m_service->RegisterCommandProcessor(CancelOptionSelfClose::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCancelOptionSelfClose(command);
  });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnRspOptionSelfCloseAction, [this](std::shared_ptr<SpiMessage> msg) {
      OnRspOptionSelfCloseAction(msg);
    });
  m_api_adapter->RegisterMsgProcessor(
    SpiMessage::Tag::OnErrRtnOptionSelfCloseAction, [this](std::shared_ptr<SpiMessage> msg) {
      OnErrRtnOptionSelfCloseAction(msg);
    });
  // 自对冲或者取消自对冲
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOptionSelfClose, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOptionSelfClose(msg);
  });
}

void XOneUnitExecOrder::ReqInsertExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertExecOrder>(m_service->m_command_manager->Update(command));
  XOneTradePlatform::CThostFtdcInputExecOrderField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.ExecOrderRef, std::to_string(req->exec_order_ref));
  strcpy_x(field.InstrumentID, req->instrument_id);
  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_api_adapter->m_req_login->user_id);
  strcpy_x(field.BrokerID, m_api_adapter->m_req_login->broker.broker_id);
  ConvertToSfitOffsetFlag(req->offset, &field.OffsetFlag);
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  ConvertToSfitPosiDirection(req->direction, field.PosiDirection);
  ConvertToSfitExecAction(req->exec_action_type, field.ActionType);
  ConvertToSfitExecOrderCloseFlag(req->close_flag, field.CloseFlag);
  field.Volume = req->volume;
  field.RequestID = m_api_adapter->GenerateRequestID();
  int ret = m_api_adapter->m_api->ReqExecOrderInsert(&field, field.RequestID);
  LogXOneReq(m_logger, "ReqInsertExecOrder", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(command, "ReqInsertExecOrder" + std::to_string(req->exec_order_ref));
}

void XOneUnitExecOrder::OnRspInsertExecOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<XOneTradePlatform::CThostFtdcInputExecOrderField>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqInsertExecOrder" + std::string(field->ExecOrderRef));
  SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
}

