void XOneUnitExecOrder::ReqCancelExecOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelExecOrder>(m_service->m_command_manager->Update(command));
  auto origin =
    m_api_adapter->m_origin_node_db->GetNode<XOneTradePlatform::CThostFtdcExecOrderField>(req->exec_order_id);
  if (origin == nullptr || origin->Latest()->ExecResult != THOST_FTDC_OER_NoExec) {
    SetCommandFinished(req, 1, u8"fclib: 不存在可撤销的行权报单委托");
    return;
  }
  XOneTradePlatform::CThostFtdcInputExecOrderActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.InstrumentID, origin->Latest()->InstrumentID);
  strcpy_x(field.ExchangeID, origin->Latest()->ExchangeID);
  strcpy_x(field.BrokerID, origin->Latest()->BrokerID);
  strcpy_x(field.InvestorID, origin->Latest()->InvestorID);
  field.ExecOrderActionRef = static_cast<int>(++m_api_adapter->m_order_ref);
  strcpy_x(field.ExecOrderRef, origin->Latest()->ExecOrderRef);
  field.FrontID = origin->Latest()->FrontID;
  field.SessionID = origin->Latest()->SessionID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  if (origin->Latest()->ExecOrderSysID[0] != '\0') {
    strcpy_x(field.ExecOrderSysID, origin->Latest()->ExecOrderSysID);
  }
  field.RequestID = m_api_adapter->GenerateRequestID();
  int ret = m_api_adapter->m_api->ReqExecOrderAction(&field, field.RequestID);
  LogXOneReq(m_logger, "ReqCancelExecOrder", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(
    command, "ReqCancelExecOrder" + std::string(origin->Latest()->ExecOrderRef));
}

