void XOneUnitExecOrder::ReqInsertOptionSelfClose(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOptionSelfClose>(m_service->m_command_manager->Update(command));
  XOneTradePlatform::CThostFtdcInputOptionSelfCloseField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.OptionSelfCloseRef, std::to_string(req->self_close_ref));

  if (req->close_flag == SelfCloseType::kOptionPosition) {
    strcpy_x(field.InstrumentID, req->instrument_id);
    strcpy_x(field.SeriesID, req->underlying_instrument_id);
    if (!req->underlying_instrument_id.empty()) {
      size_t pos = req->underlying_instrument_id.find_first_of("0123456789");
      std::string product_id =
        (pos != std::string::npos) ? req->underlying_instrument_id.substr(0, pos) : req->underlying_instrument_id;
      strcpy_x(field.ProductID, product_id);
    } else {
      size_t pos = req->product_id.find('_');
      std::string product_id = (pos != std::string::npos) ? req->product_id.substr(0, pos) : req->product_id;
      strcpy_x(field.ProductID, product_id);
    }
  } else {
    strcpy_x(field.InstrumentID, req->instrument_id);
    if (!req->underlying_instrument_id.empty()) {
      strcpy_x(field.InstrumentID, req->underlying_instrument_id);
    }
    size_t pos = req->product_id.find('_');
    std::string product_id = (pos != std::string::npos) ? req->product_id.substr(0, pos) : req->product_id;
    strcpy_x(field.ProductID, product_id);
  }

  strcpy_x(field.ExchangeID, req->exchange_id);
  strcpy_x(field.InvestorID, m_api_adapter->m_req_login->user_id);
  strcpy_x(field.BrokerID, m_api_adapter->m_req_login->broker.broker_id);
  field.Volume = req->volume;
  ConvertToSfitHedgeFlag(req->hedge_flag, &field.HedgeFlag);
  ConvertToSfitSelfCloseAction(req->close_flag, field.OptSelfCloseFlag, req->is_offset);
  field.RequestID = m_api_adapter->GenerateRequestID();
  int ret = m_api_adapter->m_api->ReqOptionSelfCloseInsert(&field, field.RequestID);
  LogXOneReq(m_logger, "ReqInsertOptionSelfClose", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(command, "ReqInsertOptionSelfClose" + std::to_string(req->self_close_ref));
}

