  auto origin =
    m_api_adapter->m_origin_node_db->GetNode<XOneTradePlatform::CThostFtdcOptionSelfCloseField>(req->self_close_id);
  if (origin == nullptr || origin->Latest()->ExecResult != THOST_FTDC_OER_NoExec) {
    SetCommandFinished(req, 1, u8"fclib: 可撤销的自对冲报单委托不存在");
    return;
  }
  XOneTradePlatform::CThostFtdcInputOptionSelfCloseActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, origin->Latest()->BrokerID);
  strcpy_x(field.InvestorID, origin->Latest()->InvestorID);
  strcpy_x(field.ExchangeID, origin->Latest()->ExchangeID);
  strcpy_x(field.InstrumentID, origin->Latest()->InstrumentID);
  if (origin->Latest()->OptionSelfCloseSysID[0] == '\0') {
    strcpy_x(field.OptionSelfCloseRef, origin->Latest()->OptionSelfCloseRef);
    field.FrontID = origin->Latest()->FrontID;
    field.SessionID = origin->Latest()->SessionID;
  } else {
    strcpy_x(field.OptionSelfCloseSysID, origin->Latest()->OptionSelfCloseSysID);
  }
  field.FrontID = origin->Latest()->FrontID;
  field.SessionID = origin->Latest()->SessionID;
  field.ActionFlag = THOST_FTDC_AF_Delete;
  field.RequestID = m_api_adapter->GenerateRequestID();
  int ret = m_api_adapter->m_api->ReqOptionSelfCloseAction(&field, field.RequestID);
  LogXOneReq(m_logger, "ReqOptionSelfCloseAction", &field, field.RequestID, ret);
  if (ret != 0) {
    SetCommandFinished(req, ret, u8"指令发送失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(
    command, "ReqCancelOptionSelfClose" + std::string(origin->Latest()->OptionSelfCloseRef));
}

