XOneApiAdapter::~XOneApiAdapter() {}

/** 在一次 RunOnce 中,查询类返回数据总是完整的 */
int XOneApiAdapter::RunOnce() {
  // 检查
  if (!m_api || !m_spi)
    return 0;
  if (m_last_front_connect_error_time > 0
    && NowAsEpochNano() - m_last_front_connect_error_time > m_api_wait_seconds * 1000 * 1000 * 1000) {
    m_last_front_connect_error_time = 0;
    BuildApi();
    return 0;
  }
  if (m_log_replayer && !m_log_replayer->m_pause)
    m_log_replayer->ProcessUntil((300LL + std::rand() % 200) * 1000000LL);  // 回放日志时, 每次推进300 - 500毫秒
  // 处理spi接收到的数据包
  std::shared_ptr<SpiMessage> msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    if (!msg->bIsLast) {
      m_data_cache[msg->tag].push(msg);
      continue;
    }
    auto& cache = m_data_cache[msg->tag];
    while (!cache.empty()) {
      ProcessSpiMsg(cache.front());
      msg_count++;
      cache.pop();
    }
    ProcessSpiMsg(msg);
    msg_count++;
  }
  // 返回处理数据包数量
  return msg_count;
}

void XOneApiAdapter::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  auto it = m_processor.find(spi_msg->tag);
  if (it != m_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
  switch (spi_msg->tag) {
    case SpiMessage::Tag::OnFrontConnected: {
      OnFrontConnected(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnFrontDisconnected: {
      OnFrontDisconnected(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnFrontConnectError: {
      OnFrontConnectError(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspAuthenticate: {
      OnRspAuthenticate(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspUserLogin: {
      OnRspUserLogin(spi_msg);
      break;
    }
