      OnRspSettlementInfoConfirm(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryInstrumentMarginRate: {
      OnRspQryInstrumentMarginRate(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryInstrumentCommissionRate: {
      OnRspQryInstrumentCommissionRate(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnErrRtnFutureToBankByFuture:
    case SpiMessage::Tag::OnErrRtnBankToFutureByFuture: {
      OnErrRtnTransferMoney(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRtnFromBankToFutureByFuture:
    case SpiMessage::Tag::OnRtnFromFutureToBankByFuture:
    case SpiMessage::Tag::OnRspFromBankToFutureByFuture:
    case SpiMessage::Tag::OnRspFromFutureToBankByFuture: {
      OnRspTransferMoney(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryAccountregister: {
      OnRspQryAccountregister(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryContractBank: {
      OnRspQryContractBank(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryTransferSerial: {
      OnRspQryTransferSerial(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRspQryBankBalance: {
      OnRspQryBankBalance(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRtnBankBalance: {
      OnRtnBankBalance(spi_msg);
      break;
    }
    case SpiMessage::Tag::OnRtnExecOrder: {
      OnRtnExecOrder(spi_msg);
      break;
