int XOneApiAdapter::GenerateRequestID() {
  static int request_id = 0;
  return request_id++;
}

void XOneApiAdapter::InitAndLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ReqLogin>(m_command_manager->Update(command));
  m_req_login = req;
  m_req_change_password_before_login = nullptr;
  m_logined = false;
  // 构建 Api
  auto ret = BuildApi();
  if (ret != 0) {
    SetCommandFinished(command, ret, m_api->GetErrorMsg(ret));
    return;
  }
  if (m_req_login->user_id == "STRESS-TESTING-100") {
    m_spi->StartStressTesting();
    m_origin_node_db->ReplaceRecord<XOneTradePlatform::CThostFtdcRspUserLoginField>(
      "000000", [](std::shared_ptr<XOneTradePlatform::CThostFtdcRspUserLoginField> login_node) {
        strcpy_x(login_node->TradingDay, "000000");
      });
    SetCommandFinished(req);
    return;
  }
  // 日志回放
  if (!m_req_login->replay_flow_file_name.empty()) {
    if (m_log_replayer) {
      m_log_replayer->m_pause = !m_log_replayer->m_pause;
    } else {
      m_log_replayer = std::make_shared<LogReplayer>();
      m_log_replayer->OpenLogFile(req->replay_flow_file_name, m_spi);
    }
  }
  m_logger.Info("init");
  m_command_manager->SetCommandId(req, "login");
}

void XOneApiAdapter::ReqChangePasswordBeforeLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePasswordBeforeLogin>(m_command_manager->Update(command));
  if (m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户已登录,请调用登录后修改密码接口");
    return;
  }
  if (!req->req_login->replay_flow_file_name.empty() || req->req_login->user_id == "STRESS-TESTING-100") {
    SetCommandFinished(req, -1, u8"fclib: 当前模式无法修改密码");
    return;
  }
  m_req_change_password_before_login = req;
  m_req_change_password_before_login->req_login->password = req->old_password;
  m_req_login = m_req_change_password_before_login->req_login;
  BuildApi(false);
  m_logger.Info("ReqChangePasswordBeforeLogin");
  m_command_manager->SetCommandId(command, "change_password_before_login");
}

void XOneApiAdapter::OnFrontConnected(std::shared_ptr<SpiMessage> msg) {
  m_api_wait_seconds = 1;
  m_origin_node_db->ReplaceRecord<RspConnect>(m_trading_day, [&](std::shared_ptr<RspConnect> rsp_connect) {
    rsp_connect->connect_status = true;
    rsp_connect->trading_day = m_trading_day;
  });
  auto broker = m_req_login->broker;
  if (m_req_change_password_before_login) {
    broker = m_req_change_password_before_login->req_login->broker;
  }
  if (broker.auth_code.empty()) {
    ReqUserLogin();
  } else {
    ReqAuthenticate();
  }
}

void XOneApiAdapter::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (s_first_adapter == reinterpret_cast<int64_t>(this))
    s_first_adapter = 0;
  m_logined = false;
  m_origin_node_db->ReplaceRecord<RspConnect>(m_trading_day, [&](std::shared_ptr<RspConnect> rsp_connect) {
    rsp_connect->connect_status = false;
    rsp_connect->trading_day = m_trading_day;
    rsp_connect->msg = u8"前置机断连";
  });
  BuildApi();  // XONE接口不会自动重连
}

int XOneApiAdapter::ProcessSMErrorCode(int error_code) {
  if (error_code == 101012 || error_code == 101020) {
    return ProcessSMUserLoginError<ReqCertEnroll>();
  } else if (error_code == 101011 || error_code == 101015 || error_code == 101014) {
    return ProcessSMUserLoginError<ReqCertResetPin>();
  } else if (error_code == 101013) {
    return ProcessSMUserLoginError<ReqCertDelay>();
  }
  return 0;
}

void XOneApiAdapter::OnFrontConnectError(std::shared_ptr<SpiMessage> msg) {
  if (m_req_login->broker.is_sm) {
    ProcessSMErrorCode(msg->RspInfo.ErrorID);
    return;
  }
  if (!m_trading_day.empty()) {  // 断线重连失败
    m_api_wait_seconds *= 2;
    if (m_api_wait_seconds > 30)
      m_api_wait_seconds = 30;
    m_last_front_connect_error_time = NowAsEpochNano();
  } else {
    if (auto cmd = m_command_manager->Update("login"))
      SetCommandFinished(cmd, -1, u8"连接前置失败");
    else if (auto cmd = m_command_manager->Update("change_password_before_login"))
      SetCommandFinished(cmd, -1, u8"连接前置失败");
  }
}

void XOneApiAdapter::ReqAuthenticate() {
  XOneTradePlatform::CThostFtdcReqAuthenticateField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.UserID, m_req_login->user_id);
  strcpy_x(field.UserProductInfo, m_req_login->broker.product_info);
  strcpy_x(field.AppID, m_req_login->broker.app_id);
  strcpy_x(field.AuthCode, m_req_login->broker.auth_code);
  int nRequestID = GenerateRequestID();
  int ret = m_api->ReqAuthenticate(&field, nRequestID);
  LogXOneReq(m_logger, "ReqAuthenticate", &field, nRequestID, ret);
}

void XOneApiAdapter::OnRspAuthenticate(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0) {
    std::string rsp_key = m_req_change_password_before_login ? "change_password_before_login" : "login";
    m_origin_node_db->ReplaceRecord<RspConnect>(m_trading_day, [&](std::shared_ptr<RspConnect> rsp_connect) {
      rsp_connect->connect_status = false;
      rsp_connect->trading_day = m_trading_day;
      rsp_connect->msg = msg->RspInfo.ErrorMsg;
    });
    auto req = m_command_manager->Update(rsp_key);
    SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
    return;
  }
  ReqUserLogin();
}

void XOneApiAdapter::ReqUserLogin() {
  XOneTradePlatform::CThostFtdcReqUserLoginField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.UserID, m_req_login->user_id);
  strcpy_x(field.Password, m_req_login->password);
  strcpy_x(field.UserProductInfo, m_req_login->broker.product_info);
  int ret = m_api->ReqUserLogin(&field, 1);
  LogXOneReq(m_logger, "ReqUserLogin", &field, 1, ret);
}

void XOneApiAdapter::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  //  TS_RET_NOT_RESET_PWD = 25,        // 首次登陆必须重置密码 （强制修改密码）
  //  TS_RET_PWD_OUTDATE = 2080,      // 密码已过期,请重新修改后再登录 （强制修改密码）
  //  TS_RET_PWD_WILL_EXPIRE = 2087,  // 密码将要到期,建议尽快修改（提示，认为登录成功）
  //  TS_RET_USER_ACCOUNT_NOT_MATCH_WITH_PASSWORD = 2119,  // 提示账号和密码不匹配 (登录错误)
  //  TS_RET_PWD_RESET_NOT_MODFIY = 3032,         // 密码已重置,首次登录请重新修改 (强制修改密码)
  //  TS_RET_PWD_RESET_NOT_MODFIY_NOTICE = 3033,  // 密码已重置,建议尽快修改 (提示，认为登录成功)
  //  TS_RET_PWD_OUTDATE_NOTICE = 3034,           // 密码已过期,建议尽快修改 (提示，认为登录成功)
  //  TS_RET_PWD_RESET_AND_OUTDATE_NOTICE = 3035,  // 密码已重置,且已过期,建议尽快修改(提示，认为登录成功)
  //  TS_RET_PWD_RESET_AND_WILL_OUTDATE_NOTICE = 3036, // 密码已重置,且将要到期,建议尽快修改(提示，认为登录成功)
  static std::set<int> s_change_password = {0, 25, 2080, 2087, 3032, 3033, 3034, 3035, 3036};
  static std::set<int> s_login_sucess = {0, 2087, 3033, 3034, 3035, 3036};
  if (m_req_change_password_before_login) {
    auto req = m_command_manager->Update("change_password_before_login");
    if (s_change_password.find(msg->RspInfo.ErrorID) != s_change_password.end()) {
      XOneTradePlatform::CThostFtdcUserPasswordUpdateField field;
      memset(&field, 0, sizeof(field));
      strcpy_x(field.OldPassword, m_req_change_password_before_login->req_login->password);
      strcpy_x(field.NewPassword, m_req_change_password_before_login->new_password);
      strcpy_x(field.BrokerID, m_req_change_password_before_login->req_login->broker.broker_id);
      strcpy_x(field.UserID, m_req_change_password_before_login->req_login->user_id);
      int ret = m_api->ReqUserPasswordUpdate(&field, 0);
      LogXOneReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
      if (0 != ret) {
        SetCommandFinished(req, ret, u8"修改密码指令发送失败");
      }
    } else {
      SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
    }
  } else {
    if (s_login_sucess.find(msg->RspInfo.ErrorID) != s_login_sucess.end()) {
      auto req = m_command_manager->Update("login");
      m_rsp_login = std::static_pointer_cast<XOneTradePlatform::CThostFtdcRspUserLoginField>(msg->pMainField);
      if (!m_trading_day.empty() && m_trading_day != m_rsp_login->TradingDay) {
        m_new_day = true;
      }
      m_trading_day = m_rsp_login->TradingDay;
      m_front_id = m_rsp_login->FrontID;
      m_session_id = m_rsp_login->SessionID;
      m_order_ref = std::atoll(m_rsp_login->MaxOrderRef) / 100LL + 1;
      m_logined = true;
      if (ReqQryInvestor() != 0) {
        m_origin_node_db->ReplaceRecord<XOneTradePlatform::CThostFtdcRspUserLoginField>(m_rsp_login);
        SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
      } else if (msg->RspInfo.ErrorID != 0 && req) {
        req->result_msg = msg->RspInfo.ErrorMsg;
      }
      if (m_confirm == future::ConfirmStatus::kUnknown) {
        ReqQrySettlementInfoConfirm();
      }
    } else {
      auto req = m_command_manager->Update("login");
      SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
      m_origin_node_db->ReplaceRecord<RspConnect>(m_trading_day, [&](std::shared_ptr<RspConnect> rsp_connect) {
        rsp_connect->connect_status = false;
        rsp_connect->trading_day = m_trading_day;
        rsp_connect->msg = msg->RspInfo.ErrorMsg;
      });
    }
  }
}

int XOneApiAdapter::ReqQryInvestor() {
  auto field = std::make_shared<XOneTradePlatform::CThostFtdcQryInvestorField>();
  memset(field.get(), 0, sizeof(XOneTradePlatform::CThostFtdcQryInvestorField));
  strcpy_x(field->BrokerID, m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_req_login->user_id);
  int request_id = GenerateRequestID();
  auto ret = m_api->ReqQryInvestor(field.get(), request_id);
  LogXOneReq(m_logger, "ReqQryInvestor", field.get(), request_id, ret);
  return ret;
}

void XOneApiAdapter::OnRspQryInvestor(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pInvestor = std::static_pointer_cast<XOneTradePlatform::CThostFtdcInvestorField>(msg->pMainField);
    m_origin_node_db->ReplaceRecord<XOneTradePlatform::CThostFtdcInvestorField>(pInvestor);
  }
  auto req = m_command_manager->Update(std::to_string(msg->nRequestID));
  if (msg->bIsLast) {
    if (m_rsp_login)
      m_origin_node_db->ReplaceRecord<XOneTradePlatform::CThostFtdcRspUserLoginField>(m_rsp_login);
    auto req = m_command_manager->Update("login");
    if (msg->RspInfo.ErrorID != 0)
      SetCommandFinished(req, msg->RspInfo.ErrorID, msg->RspInfo.ErrorMsg);
    else
      SetCommandFinished(req, 0, req->result_msg);
  }
}

