void XOneApiAdapter::SetReqResponse(std::shared_ptr<UserCommand> c, int request_id, int result_code) {
  auto command = m_command_manager->Update(c);
  if (!command)
    return;
  command->result_code = result_code;
  if (result_code == 0) {
    command->status = UserCommand::Status::kStarted;
  } else {
    command->status = UserCommand::Status::kFinished;
    command->result_msg = u8"指令发送失败";
  }
  m_command_manager->SetCommandId(command, std::to_string(request_id));
}

int XOneApiAdapter::BuildApi(bool subscribe_topic /*= true*/) {
  if (!m_req_login)
    return 0;
  DeleteApi();
  int ret = -1;
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_xone_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  auto c = std::filesystem::current_path();
  if (!m_options->run_directory.empty())
    c = std::filesystem::u8path(m_options->run_directory);
  std::filesystem::current_path(std::filesystem::temp_directory_path());
  // XOneTradePlatform::CThostFtdcTraderApi::InitLog(1);
  // std::string version = XOneTradePlatform::CThostFtdcTraderApi::GetApiVersion();
  // m_logger.With("version", version).Info("xone api version");
  m_api = XOneApiAdapter::ThostApiCreator(m_flow_dir.c_str());
  std::filesystem::current_path(c);
  if (m_options->xone_api_test_mode)
    m_api->SetRsaPubKey(1);
  m_spi = new XOneSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  if (m_req_login->broker.is_fens
    || (m_req_login->broker.trading_fronts.size() >= 2
      && m_req_login->broker.trading_fronts[0] == m_req_login->broker.trading_fronts[1])) {
    ret = m_api->RegisterNameServer(m_req_login->broker.trading_fronts[0].c_str());
    FCASSERT(ret == 0);
  } else {
    for (const auto& front : m_req_login->broker.trading_fronts) {
      auto pos = front.find(';');
      if (pos != std::string::npos)
        m_api->RegisterFront(front.substr(0, pos).c_str(), front.substr(pos + 1).c_str());
      else
        m_api->RegisterFront(front.c_str(), front.c_str());
    }
  }
  if (subscribe_topic) {
    ret = m_api->SubscribePrivateTopic(XOneTradePlatform::THOST_TERT_RESUME);
    if (ret != 0) {
      m_logger.With("ret", ret).Warning("SubscribePrivateTopic");
      return ret;
    }
    ret = m_api->SubscribePublicTopic(XOneTradePlatform::THOST_TERT_RESUME);
    if (ret != 0) {
      m_logger.With("ret", ret).Warning("SubscribePublicTopic");
      return ret;
    }
  }
  // 国密登录(等待厂商更新)
  if (m_req_login->broker.is_sm) {
    XOneTradePlatform::CThostFtdcEncryptInfoField enc_info = {0};
    enc_info.EncryptType = m_req_login->broker.sm_info.sm_type;
    strcpy_x(enc_info.CertServerHost, m_req_login->broker.sm_info.cert_host);
    enc_info.CertServerPort = m_req_login->broker.sm_info.cert_port;
    strcpy_x(enc_info.SMAppID, m_req_login->broker.sm_info.sm_app_id);
    strcpy_x(enc_info.SMServiceID, m_req_login->broker.sm_info.sm_service_id);
    strcpy_x(enc_info.SMSecretKey, m_req_login->broker.sm_info.sm_secret_key);
    enc_info.SMTimeoutMs = 30000;
    enc_info.SMLogSwitch = 1;
    ret = m_api->RegisterEncryptInfo(&enc_info);
    if (ret != 0) {
      m_logger.With("ret", ret).Warning("RegisterEncryptInfo");
      return ret;
    }
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    ret = m_api->Init();
    if (ret != 0) {
      m_logger.With("ret", ret).Warning("Init");
      return ret;
    }
  }
  if (m_req_login->broker.is_sm) {
    XOneTradePlatform::CThostFtdcConnectSMField req = {0};
    memset(&req, 0, sizeof(req));
    strcpy_x(req.UserID, m_req_login->user_id);
    strcpy_x(req.Pin, m_req_login->pin);
    strcpy_x(req.Password, m_req_login->password);
    ret = m_api->ConnectSM(&req);
    if (ret != 0) {
      m_logger.With("ret", ret).Warning("ConnectSM");
      ret = ProcessSMErrorCode(ret);
    }
  }
  return ret;
}

void XOneApiAdapter::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api->Release();
  m_api = nullptr;
}

void XOneApiAdapter::ReqQrySettlementInfoConfirm() {
  XOneTradePlatform::CThostFtdcQrySettlementInfoConfirmField field;
  memset(&field, 0, sizeof(XOneTradePlatform::CThostFtdcQrySettlementInfoConfirmField));
  strcpy_x(field.BrokerID, m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_req_login->user_id.c_str());
  strcpy_x(field.AccountID, m_req_login->user_id.c_str());
  strcpy(field.CurrencyID, "CNY");  // NOLINT

  auto request_id = GenerateRequestID();
