void XOneApiAdapter::OnRspQrySettlementInfoConfirm(std::shared_ptr<SpiMessage> msg) {
  auto pSettlementInfoConfirm =
    std::static_pointer_cast<XOneTradePlatform::CThostFtdcSettlementInfoConfirmField>(msg->pMainField);
  if (pSettlementInfoConfirm && pSettlementInfoConfirm->ConfirmDate[0] != '\0') {
