void XOneApiAdapter::OnRspQrySettlementInfo(std::shared_ptr<SpiMessage> msg) {
  /** 注意，查询日期如果不存在结算单，则返回的 msg->pMainField 为nullptr*/
  if (msg->nRequestID != -1)
    return;
  if (msg->pMainField) {
    auto pSettlementInfo = std::static_pointer_cast<XOneTradePlatform::CThostFtdcSettlementInfoField>(msg->pMainField);
    m_rsp_settlement_info.append(pSettlementInfo->Content);
  }
  // 确认本指令完成
  if (msg->bIsLast) {
    if (m_confirm == ConfirmStatus::kUnconfirm) {
      m_confirm = ConfirmStatus::kWaitingConfirm;
    }
    m_node_db->ReplaceRecord<LoginContent>(
      m_req_login->user_key, [&](std::shared_ptr<future::LoginContent> target_info) {
        target_info->content = m_rsp_settlement_info;
        target_info->user_key = m_req_login->user_key;
        target_info->backend = BackEnd::kXOne;
        target_info->confirm_status = ConfirmStatus::kWaitingConfirm;
        if (target_info->user_desc == "") {
          target_info->user_desc = m_req_login->user_desc;
        }
      });
    m_rsp_settlement_info.clear();
  }
}

