void XOneApiAdapter::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePassword>(m_command_manager->Update(command));
  if (!m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录前修改密码接口");
    return;
  }
  int request_id;
  if (req->query_request_id > 0) {
    request_id = req->query_request_id;
  } else {
    request_id = GenerateRequestID();
  }
  if (req->password_type == PasswordType::kTrade) {
    XOneTradePlatform::CThostFtdcUserPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.BrokerID, m_req_login->broker.broker_id);
    strcpy_x(field.UserID, m_req_login->user_id);
    int ret = m_api->ReqUserPasswordUpdate(&field, request_id);
    LogXOneReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
    SetReqResponse(command, request_id, ret);
  } else {
    XOneTradePlatform::CThostFtdcTradingAccountPasswordUpdateField field;
    memset(&field, 0, sizeof(field));
    strcpy_x(field.BrokerID, m_req_login->broker.broker_id);
    strcpy_x(field.AccountID, m_req_login->user_id);
    strcpy_x(field.OldPassword, req->old_password);
    strcpy_x(field.NewPassword, req->new_password);
    strcpy_x(field.CurrencyID, "CNY");
    int ret = m_api->ReqTradingAccountPasswordUpdate(&field, request_id);
    LogXOneReq(m_logger, "ReqTradingAccountPasswordUpdate", &field, 0, ret);
    SetReqResponse(command, request_id, ret);
  }
}

