void XOneApiAdapter::ReqTransferMoney(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<TransferMoney>(m_command_manager->Update(command));
  int ret = 0;
  XOneTradePlatform::CThostFtdcReqTransferField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_req_login->broker.broker_id);
  strcpy_x(field.BankID, req->bank_id.c_str());
  strcpy_x(field.BankBranchID, "0000");
  field.SecuPwdFlag = THOST_FTDC_BPWDF_BlankCheck;  // 核对密码
  field.BankPwdFlag = THOST_FTDC_BPWDF_NoCheck;     // 核对密码
  field.VerifyCertNoFlag = THOST_FTDC_YNI_No;
  strcpy_x(field.AccountID, m_req_login->user_id);
  strcpy_x(field.Password, req->future_password.c_str());
  strcpy_x(field.BankPassWord, req->bank_password.c_str());
  strcpy_x(field.CurrencyID, req->currency.c_str());
  auto node = m_origin_node_db->GetNode<XOneTradePlatform::CThostFtdcAccountregisterField>(req->bank_id);
  if (node)
    strcpy_x(field.BankAccount, node->Snap()->BankAccount);

  field.TradeAmount = req->amount;
  auto request_id = GenerateRequestID();
  field.RequestID = request_id;
  if (req->is_deposit) {
    // 入金
    strcpy_x(field.TradeCode, "202001");
    ret = m_api->ReqFromBankToFutureByFuture(&field, field.RequestID);
  } else {
    // 出金
    strcpy_x(field.TradeCode, "202002");
    ret = m_api->ReqFromFutureToBankByFuture(&field, field.RequestID);
  }
  memset(field.Password, 0, sizeof(field.Password));
  memset(field.BankPassWord, 0, sizeof(field.BankPassWord));
  LogXOneReq(m_logger, "ReqTransferMoney", &field, field.RequestID, ret);
  SetReqResponse(command, request_id, ret);
}

