  strcpy_x(field.BankBranchID, "0000");
  field.SecuPwdFlag = THOST_FTDC_BPWDF_BlankCheck;
  field.BankPwdFlag = THOST_FTDC_BPWDF_NoCheck;
  field.VerifyCertNoFlag = THOST_FTDC_YNI_No;
  field.RequestID = request_id;
  strcpy_x(field.AccountID, m_req_login->user_id);
  strcpy_x(field.Password, qry->future_password);
  strcpy_x(field.BankPassWord, qry->bank_password);
  strcpy_x(field.CurrencyID, qry->currency);

  auto node = m_origin_node_db->GetNode<XOneTradePlatform::CThostFtdcAccountregisterField>(qry->bank_id);
  if (node)
    strcpy_x(field.BankAccount, node->Snap()->BankAccount);

  m_command_manager->SetCommandId(command, std::to_string(request_id));

  auto ret = m_api->ReqQueryBankAccountMoneyByFuture(&field, request_id);
  LogXOneReq(m_logger, "ReqQueryBankAccountMoneyByFuture", &field, request_id, ret);

  if (ret != 0) {
    SetCommandFinished(command, ret, u8"查询银行余额失败");
  }
}

