void XOneApiAdapter::OnRtnCombAction(std::shared_ptr<SpiMessage> msg) {
  auto comb_action = std::static_pointer_cast<XOneTradePlatform::CThostFtdcCombActionField>(msg->pMainField);
  m_origin_node_db->ReplaceRecord<XOneTradePlatform::CThostFtdcCombActionField>(comb_action);
  auto req = m_command_manager->Update("ReqDcePositionCombInsert" + std::string(comb_action->CombActionRef));
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Rejected) {
    SetCommandFinished(req, -1, GbkToUtf8(comb_action->StatusMsg));
    return;
  }
  // 只有当被接受才指令完成
  if (comb_action->ActionStatus == THOST_FTDC_OAS_Accepted) {
    ReqQryPosition(false);
    ReqQryAccount(false);
    SetCommandFinished(req);
  }
}

void XOneApiAdapter::ExecuteQueryCommand(std::shared_ptr<UserCommand> c) {
  auto command = m_command_manager->Update(c);
  SetCommandStarted(command);
  switch (command->aid) {
    case QueryMarginRate::AID: {
      ReqQryMargin(command);
      break;
    }
    case QueryCommissionRate::AID: {
      ReqQryCommission(command);
      break;
    }
    case QueryAccountregister::AID: {
      ReqQryAccountregister(command);
      break;
    }
    case QueryContractBank::AID: {
      ReqQryContractBank(command);
      break;
    }
    case QueryTransferLog::AID: {
      ReqQryTransferSerial(command);
      break;
    }
    case QueryBankBalance::AID: {
      ReqQryBankBalance(command);
      break;
    }
    case QueryTradingAccount::AID: {
      ReqQryAccount(command);
      break;
    }
    case QueryCFMMCToken::AID: {
      ReqQryCFMMCToken(command);
      break;
    }
    default: {
      SetCommandFinished(command, -1, u8"fclib: Xone主席柜台暂不支持该接口");
      m_logger.With("aid", command->aid).Error("unsupported command");
      break;
    }
  }
}

