template <class T>
int XOneApiAdapter::ProcessSMUserLoginError() {
  int ret = 0;
  auto req = std::make_shared<T>(m_req_login->user_key);
  req->broker_id = m_req_login->broker.broker_id;
  req->broker_name = m_req_login->broker.broker_name;
  req->password = m_req_login->password;
  req->pin = m_req_login->pin;
  req->user_id = m_req_login->user_id;
  req->user_key = m_req_login->user_key;
  m_service->ExecuteCommand(req);
  if (req->result_code == 0) {
    XOneTradePlatform::CThostFtdcConnectSMField req = {0};
    memset(&req, 0, sizeof(req));
    strcpy_x(req.UserID, m_req_login->user_id);
    strcpy_x(req.Pin, m_req_login->pin);
    strcpy_x(req.Password, m_req_login->password);
    ret = m_api->ConnectSM(&req);
  } else {
    if (m_req_change_password_before_login) {
      auto command = m_command_manager->Update("change_password_before_login");
      SetCommandFinished(command, req->result_code, u8"国密错误: " + req->result_msg);
    } else {
      auto command = m_command_manager->Update("login");
      SetCommandFinished(command, req->result_code, u8"国密错误: " + req->result_msg);
    }
  }
  return ret;
}

