void XOneMerger::MergeUser() {
  for (const auto& origin_confirm_node : m_settle_info_confirm_view->GetChangedNodes()) {
    auto origin_confirm = origin_confirm_node->Latest();
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> target_confirm) {
      target_confirm->confirm_date = origin_confirm->ConfirmDate;
      target_confirm->confirm_time = origin_confirm->ConfirmTime;
      target_confirm->confirm_status = ConfirmStatus::kConfirmed;
      target_confirm->currency = origin_confirm->CurrencyID;
      target_confirm->backend = BackEnd::kXOne;
      target_confirm->user_key = m_user_key;
    });
  }

  for (const auto& origin_login_node : m_rsp_connect_view->GetChangedNodes()) {
    auto origin_login = origin_login_node->Latest();
    auto bConnected = origin_login->connect_status;
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
      if (target_login->session_status != SessionStatus::kBeforeConnect && !bConnected)
        target_login->session_status = SessionStatus::kDisconnected;
      target_login->status_msg = origin_login->msg;
      target_login->backend = BackEnd::kXOne;
      if (target_login->user_key.empty())
        target_login->user_key = m_user_key;
      if (target_login->user_desc == "") {
        target_login->user_desc = m_adapter->m_req_login->user_desc;
      }
    });
  }

  for (const auto& origin_login_node : m_rsp_login_view->GetChangedNodes()) {
    auto origin_login = origin_login_node->Latest();
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_user_key;
      target_login->backend = BackEnd::kXOne;
      target_login->user_id = origin_login->UserID;
      target_login->investor_id = origin_login->UserID;
      if (m_adapter->m_new_day) {
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = origin_login->TradingDay;
      target_login->login_time = origin_login->LoginTime;
      target_login->broker_id = origin_login->BrokerID;
      target_login->system_name = origin_login->SystemName;
      target_login->session_id = origin_login->SessionID;
      target_login->front_id = origin_login->FrontID;
      if (target_login->user_desc == "") {
        target_login->user_desc = m_adapter->m_req_login->user_desc;
      }
    });
  }

  for (const auto& origin_rsp_investor_node : m_investor_view->GetChangedNodes()) {
    auto origin = origin_rsp_investor_node->Latest();
    m_node_db->ReplaceRecord<LoginContent>(m_user_key, [&](std::shared_ptr<future::LoginContent> target_login) {
      target_login->investor_name = std::string(origin->InvestorName);
      target_login->backend = BackEnd::kXOne;
      if (target_login->user_desc == "") {
        target_login->user_desc = m_adapter->m_req_login->user_desc;
      }
    });
  }
}

void XOneMerger::MergeAccountregister() {
  for (const auto& account_node : m_account_register_view->GetChangedNodes()) {
    auto bank_node = std::make_shared<Bank>();
    bank_node->user_key = m_user_key;
    bank_node->bank_id = account_node->Latest()->BankID;
    bank_node->bank_account = account_node->Latest()->BankAccount;
    bank_node->bank_brch_id = account_node->Latest()->BankBranchID;
    m_node_db->ReplaceRecord<Bank>(bank_node);
  }
}

void XOneMerger::MergeContractBank() {
  for (const auto& [key, bank_node] : m_bank_view->GetNodes()) {
    if (!bank_node->Snap())
      continue;
    m_node_db->ReplaceRecord<Bank>(key, [&](std::shared_ptr<future::Bank> bank) {
      if (bank->bank_name.empty() && !bank->bank_id.empty()) {
        auto contract_bank = m_origin_node_db->GetNode<XOneTradePlatform::CThostFtdcContractBankField>(bank->bank_id);
        if (contract_bank)
          bank->bank_name = contract_bank->Latest()->BankName;
      }
    });
  }
}

void XOneMerger::MergeTransferSerial() {
  for (const auto& transferserial_node : m_transfer_log_view->GetChangedNodes()) {
    auto transferserial = transferserial_node->Latest();
    auto target_transferserial = std::make_shared<TransferLog>();
    target_transferserial->user_key = m_user_key;
    target_transferserial->amount = transferserial->TradeAmount;
    target_transferserial->currency = target_transferserial->currency;
    target_transferserial->error_id = transferserial->ErrorID;
    target_transferserial->error_msg = transferserial->ErrorMsg;
    target_transferserial->bank_account = transferserial->BankAccount;
    std::string tradecode = transferserial->TradeCode;
    if (tradecode == "100009" || tradecode == "200007") {
      target_transferserial->trade_type = u8"查询银行余额";
    } else if (tradecode == "100003" || tradecode == "200001") {
      target_transferserial->trade_type = u8"入金";
    } else if (tradecode == "100004" || tradecode == "200002") {
      target_transferserial->trade_type = u8"出金";
    } else if (tradecode == "100005" || tradecode == "200003") {
      target_transferserial->trade_type = u8"冲正";
    }
    target_transferserial->bank_serial = transferserial->BankSerial;
    target_transferserial->future_serial = transferserial->FutureSerial;
    target_transferserial->bank_id = transferserial->BankID;
    target_transferserial->bank_branch_id = transferserial->BankBranchID;
    if (transferserial->TradeDate[0] != '\0' && transferserial->TradeTime[0] != '\0') {
      target_transferserial->date_time = StringToEpochNano(transferserial->TradeDate, transferserial->TradeTime);
    }
    m_node_db->ReplaceRecord<TransferLog>(target_transferserial);
  }
}

void XOneMerger::MergeBankBalance() {
