void XOneMerger::MergeExecOrder() {
  for (const auto& execorder_node : m_execorder_view->GetChangedNodes()) {
    auto execorder = execorder_node->Latest();
    if (execorder == nullptr)
      continue;
    auto target_execorder = std::make_shared<ExecOrder>();
    target_execorder->instrument_id = execorder->InstrumentID;
    target_execorder->exchange_id = execorder->ExchangeID;
    target_execorder->investor_id = execorder->InvestorID;
    target_execorder->volume = execorder->Volume;
    target_execorder->direction = ConvertFromSfitPosiDirection(execorder->PosiDirection);
    target_execorder->offsetflag = xone::ConvertFromSfitOffset(execorder->OffsetFlag);
    target_execorder->hedge_flag = ConvertFromSfitHedgeFlag(&execorder->HedgeFlag);
    target_execorder->exchange_exec_order_sysid = execorder->ExecOrderSysID;
    target_execorder->exec_action_type = ConvertFromSfitExecAction(execorder->ActionType);
    target_execorder->exec_close_flag = ConvertFromSfitExecOrderCloseFlag(execorder->CloseFlag);
    target_execorder->exec_result = ConvertFromSfitExecOrderResultType(execorder->ExecResult);
    target_execorder->status_msg = execorder->StatusMsg;
    target_execorder->exec_order_ref = execorder->ExecOrderRef;
    target_execorder->front_id = execorder->FrontID;
    target_execorder->session_id = execorder->SessionID;
    target_execorder->insert_date_time = StringToEpochNano(execorder->InsertDate, execorder->InsertTime);
    target_execorder->user_key = m_user_key;
    if (execorder->CancelTime[0] != '\0') {
      target_execorder->cancel_time = StringToEpochNano(execorder->InsertDate, execorder->CancelTime);
    }
    target_execorder->exec_order_id = ToFclibOrderId(execorder->ExecOrderRef, execorder->SessionID, execorder->FrontID);
    m_node_db->ReplaceRecord<ExecOrder>(target_execorder);
  }
}

void XOneMerger::MergeOptionSelfClose() {
  for (const auto& option_self_close_node : m_option_self_close_view->GetChangedNodes()) {
    auto option_self_close = option_self_close_node->Latest();
    if (option_self_close == nullptr)
      continue;
    auto target_option_self_close = std::make_shared<OptionSelfClose>();
    if (option_self_close->InstrumentID[0] != '\0')
      target_option_self_close->instrument_id = option_self_close->InstrumentID;
    else if (option_self_close->SeriesID[0] != '\0')
      target_option_self_close->instrument_id = option_self_close->SeriesID;
    else if (option_self_close->ProductID[0] != '\0')
      target_option_self_close->instrument_id = option_self_close->ProductID;
    else
      target_option_self_close->instrument_id = option_self_close->ExchangeID;
    target_option_self_close->exchange_id = option_self_close->ExchangeID;
    target_option_self_close->broker_id = option_self_close->BrokerID;
    target_option_self_close->investor_id = option_self_close->InvestorID;
    target_option_self_close->exchange_self_close_sysid = option_self_close->OptionSelfCloseSysID;
    target_option_self_close->volume = option_self_close->Volume;
    target_option_self_close->close_type_flag = ConvertFromSfitSelfCloseAction(option_self_close->OptSelfCloseFlag);
    target_option_self_close->hedge_flag = ConvertFromSfitHedgeFlag(&option_self_close->HedgeFlag);
    target_option_self_close->exec_result = ConvertFromSfitExecOrderResultType(option_self_close->ExecResult);
    target_option_self_close->insert_date_time =
      StringToEpochNano(option_self_close->InsertDate, option_self_close->InsertTime);
    if (option_self_close->CancelTime[0] != '\0') {
      target_option_self_close->cancel_time =
        StringToEpochNano(option_self_close->InsertDate, option_self_close->CancelTime);
    }
    target_option_self_close->status_msg = option_self_close->StatusMsg;
    target_option_self_close->option_self_close_ref = option_self_close->OptionSelfCloseRef;
    target_option_self_close->front_id = option_self_close->FrontID;
    target_option_self_close->session_id = option_self_close->SessionID;
    target_option_self_close->self_close_id =
      ToFclibOrderId(option_self_close->OptionSelfCloseRef, option_self_close->SessionID, option_self_close->FrontID);
    target_option_self_close->user_key = m_user_key;
    m_node_db->ReplaceRecord<OptionSelfClose>(target_option_self_close);
  }
}

void XOneMerger::MergeCommission() {
  for (const auto& commission_node : m_commission_view->GetChangedNodes()) {
    auto commission = commission_node->Latest();
    auto rate_key = m_user_key + "|" + std::string(commission->InstrumentID);
    m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->commission_rate_open = (UnitRate(commission->OpenRatioByMoney, commission->OpenRatioByVolume));
      rate_node->commission_rate_close = (UnitRate(commission->CloseRatioByMoney, commission->CloseRatioByVolume));
      rate_node->commission_rate_close_today =
        (UnitRate(commission->CloseTodayRatioByMoney, commission->CloseTodayRatioByVolume));
      rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
      rate_node->user_key = m_user_key;
      rate_node->instrument_id = std::string(commission->InstrumentID);
      rate_node->exchange_id = std::string(commission->ExchangeID);
      if (rate_node->exchange_id.empty()) {
        auto exchange_id = m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
        if (exchange_id.has_value()) {
          rate_node->exchange_id = exchange_id->data();
        }
      }
    });
  }
}

void XOneMerger::MergeMargin() {
  for (const auto& margin_node : m_margin_view->GetChangedNodes()) {
    auto margin_rate = margin_node->Latest();
    auto rate_key = m_user_key + "|" + std::string(margin_rate->InstrumentID);
    m_node_db->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_user_key;
      rate_node->instrument_id = std::string(margin_rate->InstrumentID);
      rate_node->exchange_id = std::string(margin_rate->ExchangeID);
      if (rate_node->exchange_id.empty()) {
        auto exchange_id = m_md_helper->GetShmProductField(rate_node->instrument_id, &shm::ShmProduct::exchange_id);
        if (exchange_id.has_value()) {
          rate_node->exchange_id = exchange_id->data();
        }
      }
      if (margin_rate->HedgeFlag == THOST_FTDC_HF_Speculation || margin_rate->HedgeFlag == '\0') {
        rate_node->margin_rate_long_spec =
          (UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume));
        rate_node->margin_rate_short_spec =
          (UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume));
        rate_node->margin_rate_long_other =
          (UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume));
        rate_node->margin_rate_short_other =
          (UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume));
      } else {
        rate_node->margin_rate_long_other =
          UnitRate(margin_rate->LongMarginRatioByMoney, margin_rate->LongMarginRatioByVolume);
        rate_node->margin_rate_short_other =
          UnitRate(margin_rate->ShortMarginRatioByMoney, margin_rate->ShortMarginRatioByVolume);
      }
    });
  }
}

