  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingNotice(msg);
  });
}

void XOneUnitNotice::ReqQryNotice(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryNotice>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  XOneTradePlatform::CThostFtdcQryNoticeField field;
  memset(&field, 0, sizeof(XOneTradePlatform::CThostFtdcQryNoticeField));
  strcpy_x(field.BrokerID, m_session.value().BrokerID);

  int request_id = m_api_adapter->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryNotice" + std::to_string(request_id));

  auto ret = m_api_adapter->GetApi()->ReqQryNotice(&field, request_id);
  LogXOneReq(m_logger, "ReqQryNotice", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"查询通知失败");
  }
}

void XOneUnitNotice::ReqQryTradingNotice(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryTradingNotice>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  if (!m_session.has_value()) {
    SetCommandFinished(req, -1, u8"fclib: 当前未登录到交易服务器");
    return;
  }
  XOneTradePlatform::CThostFtdcQryTradingNoticeField field;
  memset(&field, 0, sizeof(XOneTradePlatform::CThostFtdcQryTradingNoticeField));
  strcpy_x(field.BrokerID, m_session.value().BrokerID);
  strcpy_x(field.InvestorID, m_session.value().UserID);

  int request_id = m_api_adapter->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryTradingNotice" + std::to_string(request_id));

  auto ret = m_api_adapter->GetApi()->ReqQryTradingNotice(&field, request_id);
  LogXOneReq(m_logger, "ReqQryTradingNotice", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"查询交易通知失败");
  }
}

void XOneUnitNotice::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  m_session.reset();
}

void XOneUnitNotice::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<XOneTradePlatform::CThostFtdcRspUserLoginField>(msg->pMainField);
    m_session = *rsp;
  }
}

void XOneUnitNotice::OnRspQryNotice(std::shared_ptr<SpiMessage> msg) {
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("ReqQryNotice" + std::to_string(msg->nRequestID));
    std::string rsp_info = (msg->RspInfo.ErrorID != 0) ? msg->RspInfo.ErrorMsg : u8"正确";
    SetCommandFinished(req, msg->RspInfo.ErrorID, rsp_info);
  }
}
void XOneUnitNotice::OnRspQryTradingNotice(std::shared_ptr<SpiMessage> msg) {
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("ReqQryTradingNotice" + std::to_string(msg->nRequestID));
    std::string rsp_info = (msg->RspInfo.ErrorID != 0) ? msg->RspInfo.ErrorMsg : u8"正确";
    SetCommandFinished(req, msg->RspInfo.ErrorID, rsp_info);
  }
}

