bool StringToTag(SpiMessage::Tag* tag, const std::string& str) {
  static std::map<std::string, SpiMessage::Tag> tag_map = {
    {"OnRtnOrder", SpiMessage::Tag::OnRtnOrder},
    {"OnRtnTrade", SpiMessage::Tag::OnRtnTrade},
    {"OnRtnQuote", SpiMessage::Tag::OnRtnQuote},
    {"OnRspUserLogin", SpiMessage::Tag::OnRspUserLogin},
    {"OnRspQryInvestorPosition", SpiMessage::Tag::OnRspQryInvestorPosition},
    {"OnRspQrySettlementInfo", SpiMessage::Tag::OnRspQrySettlementInfo},
    {"OnErrRtnOrderAction", SpiMessage::Tag::OnErrRtnOrderAction},
    {"OnRspQryTradingAccount", SpiMessage::Tag::OnRspQryTradingAccount},
  };
  auto it = tag_map.find(str);
  if (it == tag_map.end())
    return false;
  *tag = it->second;
  return true;
}

void LogReplayer::OpenLogFile(const std::string& log_file_name, XOneSpiHandler* spi) {
  m_spi = spi;
  m_log_input_stream.push(boost::iostreams::lzma_decompressor());
  m_log_input_stream.push(boost::iostreams::file_source(log_file_name, BOOST_IOS::in | BOOST_IOS::binary));
}

void LogReplayer::ProcessUntil(int64_t dt_step) {
  int msg_count = 0;
  if (m_stop_dt != 0) {
    m_stop_dt += dt_step;
  }
  while (true) {
    while (!m_next_spi_msg) {
      std::string line;
      if (!std::getline(m_log_input_stream, line))
        return;
      m_next_spi_msg = LogLineToSpiMessage(line, &m_next_spi_msg_dt);
    }
    if (m_stop_dt == 0)
      m_stop_dt = m_next_spi_msg_dt;
    if (m_next_spi_msg_dt > m_stop_dt)
      break;
    m_spi->PushBack(m_next_spi_msg);
    msg_count++;
    m_next_spi_msg = nullptr;
  }
  MockDateTime(m_stop_dt);
}

std::shared_ptr<fclib::future::xone::SpiMessage> LogReplayer::LogLineToSpiMessage(
  const std::string& log_line, int64_t* msg_date_time) {
  SerializerXOneLog ss;
  ss.FromString(log_line.c_str());
  std::string msg = (*ss.m_doc)["msg"].GetString();
  std::string dts = (*ss.m_doc)["time"].GetString();
  SpiMessage::Tag t;
  if (!StringToTag(&t, msg))
    return nullptr;
  int64_t dt = DateTimeStringToEpochNano(dts.c_str());
  if (dt == -1)
    return nullptr;
  *msg_date_time = dt;
  switch (t) {
    case SpiMessage::Tag::OnRtnOrder: {
      auto p = XOneTradePlatform::CThostFtdcOrderField();
      ss.ToVar(p);
      Utf8ToGbk(p.StatusMsg, sizeof(p.StatusMsg));
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcOrderField>(SpiMessage::Tag::OnRtnOrder, &p);
    }
    case SpiMessage::Tag::OnRtnTrade: {
      auto p = XOneTradePlatform::CThostFtdcTradeField();
      ss.ToVar(p);
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcTradeField>(SpiMessage::Tag::OnRtnTrade, &p);
    }
    case SpiMessage::Tag::OnRtnQuote: {
      auto p = XOneTradePlatform::CThostFtdcQuoteField();
      ss.ToVar(p);
      Utf8ToGbk(p.StatusMsg, sizeof(p.StatusMsg));
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcQuoteField>(SpiMessage::Tag::OnRtnQuote, &p);
    }
    case SpiMessage::Tag::OnErrRtnOrderAction: {
      auto p = XOneTradePlatform::CThostFtdcOrderActionField();
      ss.ToVar(p);
      RspPack rsp;
      ss.ToVar(rsp);
      Utf8ToGbk(rsp.rsp_info.ErrorMsg, sizeof(rsp.rsp_info.ErrorMsg));
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcOrderActionField>(
        SpiMessage::Tag::OnErrRtnOrderAction, &p, &rsp.rsp_info);
    }
    case SpiMessage::Tag::OnRspUserLogin: {
      auto p = XOneTradePlatform::CThostFtdcRspUserLoginField();
      ss.ToVar(p);
      RspPack rsp;
      ss.ToVar(rsp);
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcRspUserLoginField>(
        SpiMessage::Tag::OnRspUserLogin, &p, &rsp.rsp_info, rsp.request_id, rsp.is_last);
    }
    case SpiMessage::Tag::OnRspQryTradingAccount: {
      auto p = XOneTradePlatform::CThostFtdcTradingAccountField();
      ss.ToVar(p);
      RspPack rsp;
      ss.ToVar(rsp);
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcTradingAccountField>(
        SpiMessage::Tag::OnRspQryTradingAccount, &p, &rsp.rsp_info, rsp.request_id, rsp.is_last);
    }
    case SpiMessage::Tag::OnRspQryInvestorPosition: {
      auto p = XOneTradePlatform::CThostFtdcInvestorPositionField();
      ss.ToVar(p);
      RspPack rsp;
      ss.ToVar(rsp);
      if (p.InstrumentID[0] == '\0')
        return MakeSpiMsg<XOneTradePlatform::CThostFtdcInvestorPositionField>(
          SpiMessage::Tag::OnRspQryInvestorPosition, nullptr, &rsp.rsp_info, rsp.request_id, rsp.is_last);
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcInvestorPositionField>(
        SpiMessage::Tag::OnRspQryInvestorPosition, &p, &rsp.rsp_info, rsp.request_id, rsp.is_last);
    }
    case SpiMessage::Tag::OnRspQrySettlementInfo: {
      auto p = XOneTradePlatform::CThostFtdcSettlementInfoField();
      ss.ToVar(p);
      Utf8ToGbk(p.Content, sizeof(p.Content));
      RspPack rsp;
      ss.ToVar(rsp);
      return MakeSpiMsg<XOneTradePlatform::CThostFtdcSettlementInfoField>(
        SpiMessage::Tag::OnRspQrySettlementInfo, &p, &rsp.rsp_info, rsp.request_id, rsp.is_last);
    }
    default: break;
  }
  return nullptr;
}

