/**
 * 持仓/资金表服务. 数据来源方式:
 *
 * 持仓表普通持仓项:
 * * 持仓手数随 RtnTrade 更新.
 * * 持仓冻结手数随 RtnOrder 更新.
 * * 持仓盈亏由 持仓均价, 持仓手数和最新价计算. 当无法得到最新价时, 持仓盈亏取 RspQryPosition 的结果
 * * 浮动盈亏由 开仓均价, 持仓手数和最新价计算.
 * * 其它字段(包括平仓盈亏、保证金等) 取 RspQryPosition 的结果
 * * 为SubPosition新增 _xone_volume_today 和 _xone_volume_his 字段, 这两个值来自 RspQryPosition 的结果,
 * 保证与开仓均价、保证金等字段同步.
 *
 * 持仓表组合持仓项:
 * * 组合持仓项的全部字段都来自 RspQryPosition 的结果
 *
 * 这个算法已知有这些问题:
 *
 * * 持仓手数随RtnTrade更新，冻结手数随RtnOrder更新, 可能产生不同步, 并可能使可平手数出现负数.
 * * 平仓盈亏/保证金/开仓均价 与手数更新不同步. 如果需要保证同步, 需使用 _ctp_volume_today 和 _ctp_volume_his 字段.
 * * 组合持仓手数与普通持仓手数更新不同步, 如果需要保证同步, 需使用 _ctp_volume_today 和 _ctp_volume_his 字段.
 * * 软件初始化时, 持仓手数/冻结手数会不断跳动, 且没有稳定标志. 可以考虑登录改为QUICK模式收流,
 * 并查询历史报单/成交记录来解决
 */
class XOneUnitPositionAccountView : public FuncUnit {
 public:
  XOneUnitPositionAccountView(XOneApiAdapterInterface* api_adapter, std::shared_ptr<TqApiNodeDb> node_db,
    const std::string& user_key, std::shared_ptr<md::MdServiceShmHelper> md_helper, FutureServiceOptions* options,
    structlog::Logger& parent_logger);

  /**
   * 收到查询持仓返回包. 包中携带的信息应当被更新到持仓表中.
   */
  void OnRspQryInvestorPosition(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到查询持仓明细返回包. 包中携带的信息应当被更新到持仓中.
   */
  void OnRspQryInvestorPositionDetail(std::shared_ptr<SpiMessage> msg);

  void OnRspQryTradingAccount(std::shared_ptr<SpiMessage> msg);
  /**
   * 收到成交记录. 此时应该:
   *
   * * 发起持仓查询和账户查询
   * * 尝试重算持仓手数
   *
   * 注意: 计算持仓手数时, 持仓记录中的开盘持仓手数必须已经到位
   */
  void OnRtnTrade(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到报单回报. 此时应该:
   *
   * * 发起持仓查询和账户查询
   * * 尝试重算持仓冻结手数
   *
   * 注意: 计算持仓冻结手数时, 持仓记录中的持仓手数必须已经到位, 否则可用手数可能会算成负数
   */
  void OnRtnOrder(std::shared_ptr<SpiMessage> msg);

  int RunOnce() override;

 private:
  /**
   * 处理持仓查询结果. 将查询结果中的字段填入 position 表中.
   * @param is_first: 是否是第一次收到持仓信息，如果是的话，需要给盘前持仓赋值
   */
  void ProcessQryPositionResults(bool is_first = false);

  /**
   * 处理账户查询结果. 将查询结果中的字段填入 account 表中.
   */
  void ProcessQryAccountResults();

  /**
   * 用成交记录更新持仓中的持仓手数字段, 并相应更新其它依赖持仓手数的字段
   * * 成交记录只有单腿的，没有组合的，更新的持仓手数也只更新单腿的，组合持仓只靠查询
   * * 郑商所中，平仓是优先投机
   */
  void UpdatePositionVolumeByTrade(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> trade,
    int* spec_close_volume, std::shared_ptr<future::Position> position);

  /**
   * 成交缓存. 因为计算持仓手数需要在确定开盘持仓手数的基础上逐个处理成交记录, 因此在没有获得初始持仓信息前,
   * 成交记录先存放待处理
   */
  std::vector<std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField>> m_trade_cache;

  /**
   * 处理暂存区中的成交记录.
   */
  void ProcessCachedTrade();

  /**
   * 用委托单信息更新持仓中的冻结手数字段.
   * * 组合委托单需要冻结两腿持仓的冻结量
   * * 郑商所中，平仓是优先投机
   */
  void UpdatePositionFrozenVolumeByOrder(std::shared_ptr<XOneTradePlatform::CThostFtdcOrderField> order);

  /**
   * 执行这个函数时，ins_node 已经没有组合合约了
   */
  void UpdateFrozenVolume(std::shared_ptr<XOneTradePlatform::CThostFtdcOrderField> order,
    const std::optional<shm::ShmInstrument>& ins, XOneTradePlatform::TThostFtdcDirectionType direction,
    XOneTradePlatform::TThostFtdcOffsetFlagType offset_flag, int delta_order_volume);

  /**
   * 委托单缓存. 因为计算持仓冻结手数需要在确定持仓手数的基础上处理, 因此在没有获得持仓手数前,
   * 委托单记录先存放待处理
   */
  std::vector<std::shared_ptr<XOneTradePlatform::CThostFtdcOrderField>> m_order_cache;

  /**
   * 处理暂存区中的委托记录.
   */
  void ProcessCachedOrder();

  /**
   * 存放已经处理过的所有alive委托单, 用于在收到报单信息时得到冻结手数的差额.
   *
   * order_id->OrderField
   */
  std::map<std::string, std::shared_ptr<XOneTradePlatform::CThostFtdcOrderField>> m_alive_orders;

  /**
   * 根据行情最新价, 更新持仓项的持仓盈亏, 不交易盈亏, 市值等字段.
   */
  void UpdatePositionProfit(std::shared_ptr<Position> calc_position);

  void OnRspUserLogin(std::shared_ptr<SpiMessage> msg);
  void OnRspQryBrokerTradingParams(std::shared_ptr<SpiMessage> msg);

  void UpdateAccountProfit(bool is_first = false);
  void UpdatePositionVolumeFrozen(SubPosition* calc_subpos);
  SubPosition* GetSubPosition(std::shared_ptr<future::Position> position,
    XOneTradePlatform::TThostFtdcPosiDirectionType posi_dir, XOneTradePlatform::TThostFtdcHedgeFlagType hedge);
  SubPosition* GetSubPosition(std::shared_ptr<Position> position, XOneTradePlatform::TThostFtdcHedgeFlagType hedge_flag,
    XOneTradePlatform::TThostFtdcDirectionType trade_direction, XOneTradePlatform::TThostFtdcOffsetFlagType offset);

  void UpdatePositionDetail();

  void SplicePostitionDetail();

  void UpdateTradeCloseLog(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> trade, int spec_volume,
    std::shared_ptr<Position> position);

  void UpdatePositionDetailsByTrade(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> trade,
    int spec_close_volume, std::shared_ptr<future::Position> position);

  bool ProcessCloseLogCache(const std::string& key);

  void CalcCloseLogs(SubPosition* subpos, int volume, std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> trade,
    std::list<std::shared_ptr<CloseLog>>* ret);

  void CalcCloseLogsByDetails(std::list<std::shared_ptr<PositionDetail>>* details, int* volume,
    std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> trade, const std::optional<shm::ShmInstrument>& ins,
    const PositionHedgeType& hedge_type, bool use_pre_settlement, std::list<std::shared_ptr<CloseLog>>* ret);

  /**
   * 最新一轮持仓查询结果.
   */
  std::vector<std::shared_ptr<XOneTradePlatform::CThostFtdcInvestorPositionField>> m_qry_position_results;
  std::map<std::string, std::vector<std::shared_ptr<XOneTradePlatform::CThostFtdcInvestorPositionDetailField>>>
    m_qry_position_detail_results;
  std::vector<std::shared_ptr<XOneTradePlatform::CThostFtdcTradingAccountField>> m_qry_account_results;

  struct CloseLogCache {
    int spec_volume = 0;
    int other_volume = 0;
    double spec_close_profit = 0.0;
    double spec_close_profit_by_open = 0.0;
    double other_close_profit = 0.0;
    double other_close_profit_by_open = 0.0;
    std::list<std::shared_ptr<CloseLog>> logs;
  };

  std::map<std::string, std::shared_ptr<CloseLogCache>> m_close_log_cache;

  /**
   * 仅包含 m_user_key 的持仓视图.
   */
  std::shared_ptr<NodeDbView<Position>> m_position_view;
  std::shared_ptr<NodeDbView<Position>> m_comb_position_view;

  /**
   * 第一次持仓查询结果是否已处理完.
   */
  bool m_position_inited = false;
  bool m_account_inited = false;

  bool m_position_ready = false;
  bool m_trade_order_cache_cleared = false;

  int m_position_trade_volume = 0;  // 初始持仓今开今平
  int m_trade_volume = 0;           // 成交手数

  std::shared_ptr<XOneTradePlatform::CThostFtdcBrokerTradingParamsField> m_trading_params =
    nullptr; /** 记录从查询接口返回的交易参数 */

  std::string m_trading_day;

  XOneApiAdapterInterface* m_api_adapter = nullptr;
  std::shared_ptr<TqApiNodeDb> m_node_db;
  std::string m_user_key;
  std::shared_ptr<md::MdServiceShmHelper> m_md_helper;
  FutureServiceOptions* m_options;
  structlog::Logger m_logger;
