  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("unit_cert", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqCertEnroll::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCertEnroll(command);
  });
  m_service->RegisterCommandProcessor(ReqCertDelay::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCertDelay(command);
  });
  m_service->RegisterCommandProcessor(ReqCertRevoke::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCertRevoke(command);
  });
  m_service->RegisterCommandProcessor(ReqCertResetPin::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCertResetPin(command);
  });
  m_service->RegisterCommandProcessor(ReqCertQuery::AID, [this](std::shared_ptr<UserCommand> command) {
    ExecuteCertQuery(command);
  });
}

void XOneUnitCert::ExecuteCertEnroll(std::shared_ptr<UserCommand> command) {
  auto cmd = std::static_pointer_cast<ReqCertEnroll>(command);
  XOneTradePlatform::CThostFtdcSMCertDownloadField req = {0};
  memset(&req, 0, sizeof(req));
  strcpy_x(req.UserID, cmd->user_id);
  strcpy_x(req.Pin, cmd->pin);
  strcpy_x(req.Password, cmd->password);
  int ret = m_api_adapter->m_api->ReqSMCertDownload(&req);
  m_logger.With("UserID", req.UserID).With("ret", ret).Info("ReqSMCertDownload");
  SetCommandFinished(command, ret, m_api_adapter->m_api->GetErrorMsg(ret));
}

