void XOneUnitCert::ExecuteCertResetPin(std::shared_ptr<UserCommand> command) {
  auto cmd = std::static_pointer_cast<ReqCertResetPin>(command);
  XOneTradePlatform::CThostFtdcSMPinResetField req = {0};
  memset(&req, 0, sizeof(req));
  strcpy_x(req.UserID, cmd->user_id);
  strcpy_x(req.Password, cmd->password);
  strcpy_x(req.NewPin, cmd->pin);
  int ret = m_api_adapter->m_api->ReqSMPinReset(&req);
  m_logger.With("UserID", req.UserID).With("ret", ret).Info("ReqSMPinReset");
  SetCommandFinished(command, ret, m_api_adapter->m_api->GetErrorMsg(ret));
}

void XOneUnitCert::ExecuteCertQuery(std::shared_ptr<UserCommand> command) {
  auto cmd = std::static_pointer_cast<ReqCertQuery>(command);
  XOneTradePlatform::CThostFtdcSMCertQueryField req = {0};
  memset(&req, 0, sizeof(req));
  strcpy_x(req.UserID, cmd->user_id);
  strcpy_x(req.Pin, cmd->pin);
  strcpy_x(req.Password, cmd->password);
  std::vector<XOneTradePlatform::CThostFtdcSMCertInfoField> cert_vec;
  int ret = m_api_adapter->m_api->ReqSMCertQuery(&req, cert_vec);
  m_logger.With("UserID", req.UserID).With("ret", ret).Info("ReqSMCertQuery");
  for (auto& c : cert_vec) {
    auto crt = std::make_shared<Cert>();
    crt->cert_id = c.CertID;
    crt->cert_info = c.CertInfo;
    crt->device_id = c.DeviceID;
    crt->is_current = c.IsCurrent;
    crt->user_id = c.UserID;
    cmd->cert_ret.push_back(crt);
    m_logger.With("cert_id", c.CertID)
      .With("cert_info", c.CertInfo)
      .With("device_id", c.DeviceID)
      .Info("ReqSMCertQuery");
  }
  SetCommandFinished(command, ret, m_api_adapter->m_api->GetErrorMsg(ret));
}

