XOneServiceImpl::XOneServiceImpl(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("xone_service", reinterpret_cast<int64_t>(this)).Clone())
  , m_options(options)
  , m_target_node_db(node_db)
  , m_md_helper(helper)
  , m_user_key(user_key)
  , m_ioc(ioc) {
  m_origin_node_db = std::make_shared<OriginNodeDb>(true, 0);
  m_calc_node_db = std::make_shared<TqApiNodeDb>(true, 0);

  // 创建View
  m_target_bank_view = m_target_node_db->CreateView<Bank>([&](std::shared_ptr<const Bank> bank) {
    return bank->user_key == m_user_key;
  });
  m_target_position_view = m_target_node_db->CreateView<Position>([&](std::shared_ptr<const Position> pos) {
    return pos->user_key == m_user_key && pos->unit_id == 0;
  });

  m_api_adapter = std::make_shared<XOneApiAdapter>(
    this, m_ioc, m_origin_node_db, m_target_node_db, &m_options, m_logger, m_command_manager);
  m_merger = std::make_shared<XOneMerger>(user_key, m_md_helper, m_logger, m_target_node_db, m_origin_node_db,
    m_target_bank_view, m_target_position_view, m_command_manager, m_api_adapter);
  m_dce_position_comb = std::make_shared<DcePositionAutoComb>(m_target_position_view, m_md_helper, m_logger);

  m_func_units.push_back(std::make_shared<XOneUnitSettlementInfo>(this, m_api_adapter.get(), m_logger));
  m_func_units.push_back(std::make_shared<XOneUnitCert>(this, m_api_adapter.get(), m_logger));
  m_func_units.push_back(
    std::make_shared<XOneUnitOrderTradeView>(m_api_adapter.get(), m_target_node_db, m_user_key, m_md_helper, m_logger));
  m_func_units.push_back(std::make_shared<XOneUnitPositionAccountView>(
    m_api_adapter.get(), m_target_node_db, m_user_key, m_md_helper, &m_options, m_logger));
  m_func_units.push_back(std::make_shared<XOneUnitInsertCancelOrder>(this, m_api_adapter.get(), m_logger));

  m_func_units.push_back(std::make_shared<XOneUnitNotice>(this, m_api_adapter.get(), m_logger));
  m_func_units.push_back(
    std::make_shared<XOneUnitNoticeView>(this, m_api_adapter.get(), m_target_node_db, m_user_key, m_logger));
  m_func_units.push_back(std::make_shared<XOneUnitExecOrder>(this, m_api_adapter.get(), m_logger));
}

void XOneServiceImpl::Start() {}

void XOneServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_api_adapter->m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    it->second(command);
    return;
  }
  if (command->query_request_id != 0) {
    m_api_adapter->ExecuteQueryCommand(command);
  } else {
    command->status = UserCommand::Status::kStarted;
    switch (command->aid) {
      case ReqLogin::AID: {
        m_api_adapter->InitAndLogin(command);
        break;
      }
      case ChangePassword::AID: {
        m_api_adapter->ReqChangePassword(command);
        break;
      }
      case ChangePasswordBeforeLogin::AID: {
        m_api_adapter->ReqChangePasswordBeforeLogin(command);
        break;
      }
      case InsertForQuote::AID: {
        m_api_adapter->ReqForQuoteInsert(command);
        break;
      }
      case ConfirmSettlementInfo::AID: {
        m_api_adapter->ReqSettlementInfoConfirm(command);
        break;
      }
      case TransferMoney::AID: {
        m_api_adapter->ReqTransferMoney(command);
        break;
      }
      case InsertQuote::AID: {
        ExecuteInsertQuote(command);
        break;
      }
      case CancelQuote::AID: {
        m_api_adapter->ReqCancelQuote(command);
        break;
      }
      case PositionCombInsert::AID: {
        m_api_adapter->ReqDcePositionCombInsert(command);
        break;
      }
      case QueryMarginRate::AID: {
        m_api_adapter->ReqQryMargin(command);
        break;
      }
      case QueryCommissionRate::AID: {
        m_api_adapter->ReqQryCommission(command);
        break;
      }
      case PositionCombAuto::AID: {
        auto req = std::static_pointer_cast<PositionCombAuto>(command);
        m_options.position_comb_auto = req->auto_combi;
        SetCommandFinished(command);
        break;
      }
      default: {
        SetCommandFinished(command, 1, u8"fclib:Xone主席柜台暂不支持该接口");
        m_logger.With("aid", command->aid).Error("unsupported command");
        assert(false);
        break;
      }
    }
  }
}

void XOneServiceImpl::ExecuteInsertQuote(std::shared_ptr<UserCommand> command) {
  auto insert_quote = std::static_pointer_cast<InsertQuote>(m_command_manager->Update(command));
  m_api_adapter->ReqInsertQuote(command);
}

int XOneServiceImpl::RunOnce() {
  // api运转一次
  int msg_count = m_api_adapter->RunOnce();
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  if (msg_count > 0) {
    m_merger->Merge();
  } else {
    if (m_options.position_comb_auto) {
      m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
        m_command_manager->Store(comb_insert);
        comb_insert->status = UserCommand::Status::kStarted;
        m_api_adapter->ReqDcePositionCombInsert(comb_insert);
      });
    }
  }
  // 行情变化和交易变化都会影响
  m_calc_node_db->CommitTransaction();
  m_origin_node_db->CommitTransaction();
  return msg_count;
}

void XOneServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_processor[tag] = processor;
}

void XOneServiceImpl::CleanUp() {
  // todo
}

std::shared_ptr<XOneService> XOneService::Create(boost::asio::io_context* ioc, const std::string& user_key,
  const FutureServiceOptions& options, std::shared_ptr<TqApiNodeDb> node_db,
  std::shared_ptr<md::MdServiceShmHelper> helper, structlog::Logger& parent_logger) {
  auto p = std::make_shared<XOneServiceImpl>(ioc, user_key, options, node_db, helper, parent_logger);
  p->Start();
  return p;
}

