XOneUnitSettlementInfo::XOneUnitSettlementInfo(
  ServiceInterface* service, XOneApiAdapter* api_adapter, structlog::Logger& parent_logger)
  : m_service(service)
  , m_api_adapter(api_adapter)
  , m_logger(parent_logger.With("unit_settlement_info", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QuerySettlementInfo::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqQrySettlementInfo(command);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspQrySettlementInfo, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQrySettlementInfo(msg);
  });
}

void XOneUnitSettlementInfo::ReqQrySettlementInfo(std::shared_ptr<UserCommand> command) {
  auto qry = std::static_pointer_cast<QuerySettlementInfo>(m_service->m_command_manager->Update(command));
  int request_id = m_api_adapter->GenerateRequestID();
  auto key = "QuerySettlementInfo" + std::to_string(request_id);

  XOneTradePlatform::CThostFtdcQrySettlementInfoField field;
  memset(&field, 0, sizeof(XOneTradePlatform::CThostFtdcQrySettlementInfoField));
  strcpy_x(field.BrokerID, m_session.value().BrokerID);
  strcpy_x(field.AccountID, m_session.value().UserID);
  strcpy_x(field.InvestorID, m_session.value().UserID);
  strcpy_x(field.TradingDay, qry->trading_day);

  m_service->m_command_manager->SetCommandId(command, key);

  auto ret = m_api_adapter->GetApi()->ReqQrySettlementInfo(&field, request_id);
  LogXOneReq(m_logger, "ReqQrySettlementInfo", &field, request_id, ret);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"查询结算单失败");
  }
}

void XOneUnitSettlementInfo::OnRspQrySettlementInfo(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    auto pSettlementInfo = std::static_pointer_cast<XOneTradePlatform::CThostFtdcSettlementInfoField>(msg->pMainField);
    m_rsp_settlement_info[msg->nRequestID].append(pSettlementInfo->Content);
  }
  if (msg->bIsLast) {
    auto req = m_service->m_command_manager->Update("QuerySettlementInfo" + std::to_string(msg->nRequestID));
    std::string rsp_info;
    if (msg->RspInfo.ErrorID == 0) {
      rsp_info = m_rsp_settlement_info[msg->nRequestID];
      m_rsp_settlement_info.erase(msg->nRequestID);
    } else {
      rsp_info = msg->RspInfo.ErrorMsg;
    }
    SetCommandFinished(req, msg->RspInfo.ErrorID, rsp_info);
  }
}

void XOneUnitSettlementInfo::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField
    && (msg->RspInfo.ErrorID == 0 || msg->RspInfo.ErrorID == 2087 || msg->RspInfo.ErrorID == 3034
      || msg->RspInfo.ErrorID == 3033 || msg->RspInfo.ErrorID == 3035 || msg->RspInfo.ErrorID == 3036)) {
    auto rsp = std::static_pointer_cast<XOneTradePlatform::CThostFtdcRspUserLoginField>(msg->pMainField);
    m_session = *rsp;
  }
}

int XOneUnitSettlementInfo::GenerateRequestID() {
  static int request_id = 0;
  return request_id++;
}

