XOneUnitNoticeView::XOneUnitNoticeView(ServiceInterface* service, XOneApiAdapter* api_adapter,
  std::shared_ptr<TqApiNodeDb> node_db, const std::string& user_key, structlog::Logger& parent_logger)
  : m_api_adapter(api_adapter)
  , m_node_db(node_db)
  , m_user_key(user_key)
  , m_logger(parent_logger.With("unit_notice_view", reinterpret_cast<int64_t>(this)).Clone()) {
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryNotice(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryTradingNotice(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTradingNotice, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTradingNotice(msg);
  });
}

void XOneUnitNoticeView::OnRspQryNotice(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pNotice = std::static_pointer_cast<XOneTradePlatform::CThostFtdcNoticeField>(msg->pMainField);
  auto notice = std::make_shared<future::Notice>();
  notice->user_key = m_user_key;
  notice->notice_id = "notice_" + std::to_string(pNotice->SequenceLabel);
  notice->content_type = NoticeType::kText;
  notice->content = FormatNoticeTextContent(pNotice->Content);
  notice->level = NoticeLevel::kOrdinary;
  notice->notice_time = NowAsEpochNano();
  notice->source_type = SourceType::kBroker;
  m_node_db->ReplaceRecord<Notice>(notice);
}

void XOneUnitNoticeView::OnRspQryTradingNotice(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pNotice = std::static_pointer_cast<XOneTradePlatform::CThostFtdcTradingNoticeField>(msg->pMainField);
  auto seq = std::to_string(pNotice->SequenceSeries) + "_" + std::to_string(pNotice->SequenceNo);
  auto notice = std::make_shared<future::Notice>();
  notice->user_key = m_user_key;
  notice->notice_id = "trading_notice_" + seq;
  notice->content_type = NoticeType::kText;
  notice->content = FormatNoticeTextContent(pNotice->FieldContent);
  notice->level = NoticeLevel::kWarning;
  notice->notice_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pNotice->SendTime);
  notice->source_type = SourceType::kBroker;
  m_node_db->ReplaceRecord<Notice>(notice);
}

void XOneUnitNoticeView::OnRtnTradingNotice(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pNotice = std::static_pointer_cast<XOneTradePlatform::CThostFtdcTradingNoticeInfoField>(msg->pMainField);
  auto seq = std::to_string(pNotice->SequenceSeries) + "_" + std::to_string(pNotice->SequenceNo);
  auto notice = std::make_shared<future::Notice>();
  notice->user_key = m_user_key;
  notice->notice_id = "trading_notice_" + seq;
  notice->content_type = NoticeType::kText;
  notice->content = FormatNoticeTextContent(pNotice->FieldContent);
  if (pNotice->NewsUrgency == 'c')
    notice->level = NoticeLevel::kOrdinary;
  else if (pNotice->NewsUrgency == 'w')
    notice->level = NoticeLevel::kWarning;
  else
    notice->level = NoticeLevel::kError;
  notice->notice_time = GetRealTradeTime(m_api_adapter->m_trading_day.c_str(), pNotice->SendTime);
  notice->source_type = SourceType::kBroker;
  m_node_db->ReplaceRecord<Notice>(notice);
}

