// 计算成交手续费
double CalcTradeCommission(
  std::shared_ptr<RateNode> rate_node, std::shared_ptr<Trade> trade, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!rate_node)
    return NAN;
  auto volume_multiple = helper->GetShmInstrumentField(trade->Symbol(), &shm::ShmInstrument::volume_multiple, true);
  if (!volume_multiple.has_value())
    return NAN;
  if (trade->offset == Offset::kOpen) {
    auto commission = rate_node->Latest()->commission_rate_open;
    return (commission.volume_rate + commission.amount_rate * trade->price * volume_multiple.value()) * trade->volume;
  }
  auto commission_close = rate_node->Latest()->commission_rate_close;
  auto commission_close_today = rate_node->Latest()->commission_rate_close_today;
  return (commission_close.volume_rate + commission_close.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_yesterday
    + (commission_close_today.volume_rate + commission_close_today.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_today;
}
namespace xone {
XOneUnitOrderTradeView::XOneUnitOrderTradeView(XOneApiAdapter* api_adapter, std::shared_ptr<TqApiNodeDb> node_db,
  std::string user_key, std::shared_ptr<md::MdServiceShmHelper> md_helper, structlog::Logger& parent_logger)
  : m_api_adapter(api_adapter)
  , m_node_db(node_db)
  , m_user_key(user_key)
  , m_md_helper(md_helper)
  , m_logger(parent_logger.With("unit_order_trade_view", reinterpret_cast<int64_t>(this)).Clone())
  , m_index(0) {
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });
  m_api_adapter->RegisterMsgProcessor(SpiMessage::Tag::OnRtnQuote, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnQuote(msg);
  });
  m_login_view = m_node_db->CreateView<LoginContent>();
  m_login_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<LoginNode> login_node) {
    if (!login_node->Latest()->account_ready || !login_node->Latest()->position_ready)
      return;
    m_ready = true;
    for (const auto& [_, command] : m_query_commands)
      m_api_adapter->ReqQryCommission(command);
    m_query_commands.clear();
    m_login_view->DeleteUpdate(std::to_string(reinterpret_cast<int64_t>(this)));
  });
  m_trade_view = m_node_db->CreateView<Trade>([=](std::shared_ptr<const Trade> trade) {
    return trade->user_key == m_user_key;
  });
  m_rate_view = m_node_db->CreateView<Rate>([=](std::shared_ptr<const Rate> rate) {
    return rate->user_key == m_user_key;
  });
  m_rate_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<RateNode> rate_node) {
    auto instrument_id = rate_node->Latest()->instrument_id;
    for (const auto& [key, trade_node] : m_trade_view->GetNodes()) {
      if (trade_node->Latest()->instrument_id != instrument_id)
        continue;
      m_node_db->ReplaceRecord<Trade>(key, [=](std::shared_ptr<Trade> trade) {
        trade->commission = CalcTradeCommission(rate_node, trade, m_md_helper);
      });
    }
  });
}

void XOneUnitOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<XOneTradePlatform::CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->OrderRef, origin->SessionID, origin->FrontID);
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (order->order_id.empty()) {
      auto iter = m_api_adapter->m_send_time.find(order->order_id);
      if (iter != m_api_adapter->m_send_time.end()) {
        order->send_date_time = iter->second;
        m_api_adapter->m_send_time.erase(iter);
      }
      order->receive_date_time = NowAsEpochNano();
    }
    order->index = ++m_index;
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->InvestorID;
    if (origin->UserID[0] != '\0')
      order->user_id = origin->UserID;
    else
      order->user_id = origin->InvestorID;
    order->direction = xone::ConvertFromSfitDirection(&origin->Direction);
    order->exchange_order_id = origin->OrderSysID;
    order->status_msg = origin->StatusMsg;
    order->limit_price = origin->LimitPrice;
    order->offset = xone::ConvertFromSfitOffset(origin->CombOffsetFlag[0]);
    order->hedge_flag = xone::ConvertFromSfitHedgeFlag(&origin->CombHedgeFlag);
    order->price_type = xone::ConvertFromSfitOrderPriceType(&origin->OrderPriceType);
    order->status = xone::ConvertFromSfitOrderStatus(&origin->OrderStatus);
    order->time_condition = xone::ConvertFromSfitTimeCondition(&origin->TimeCondition);
    order->volume_condition = xone::ConvertFromSfitVolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = xone::ConvertFromSfitForceClose(&origin->ForceCloseReason);
    order->volume_left = origin->VolumeTotalOriginal - origin->VolumeTraded;
    order->volume_orign = origin->VolumeTotalOriginal;
    order->order_ref = origin->OrderRef;
    order->session_id = origin->SessionID;
    order->front_id = origin->FrontID;
    order->order_local_id = origin->OrderLocalID;
    order->trader_id = origin->TraderID;
    order->is_quote = origin->OrderType == '1';
    order->min_volume = origin->MinVolume;
    order->request_id = std::to_string(origin->RequestID);
    order->is_swap_order = origin->IsSwapOrder;
    if (origin->TradingDay[0] != '\0') {
      if (origin->InsertTime[0] != '\0') {
        order->insert_date_time = GetRealTradeTime(origin->TradingDay, origin->InsertTime);
      }
      if (origin->CancelTime[0] != '\0') {
        order->dead_date_time = GetRealTradeTime(origin->TradingDay, origin->CancelTime);
      }
    }
    order->user_product_info = origin->UserProductInfo;
    order->order_id = ToFclibOrderId(origin->OrderRef, origin->SessionID, origin->FrontID);
    std::string user_product_info = origin->UserProductInfo;
    if (user_product_info.find("SHINNY") != 0 && user_product_info.find("shinny") != 0)
      order->unit_id = -1;
    else
      order->unit_id = std::atoll(origin->OrderRef) % 100;
    order->user_key = m_user_key;
    if (!order->exchange_order_id.empty()) {
      m_order_sysids[order->instrument_id][order->exchange_order_id] = order->order_id;
    }
  });
  auto map_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  m_trade_order_map[map_key] = order_node;
  if (origin->VolumeTraded > 0) {
    ProcessCachedTrade(order_node);
  }
}

void XOneUnitOrderTradeView::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  if (!m_session.has_value())
    return;
  auto origin = std::static_pointer_cast<XOneTradePlatform::CThostFtdcInputOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->OrderRef, m_session.value().SessionID, m_session.value().FrontID);
  auto order_key = m_user_key + "|" + order_id;
  auto order_node = m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (!order->order_id.empty())
      return;
    order->order_id = order_id;
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->InvestorID;
    if (origin->UserID[0] != '\0')
      order->user_id = origin->UserID;
    else
      order->user_id = origin->InvestorID;
    order->direction = xone::ConvertFromSfitDirection(&origin->Direction);
    order->limit_price = origin->LimitPrice;
    order->offset = xone::ConvertFromSfitOffset(origin->CombOffsetFlag[0]);
    order->hedge_flag = xone::ConvertFromSfitHedgeFlag(&origin->CombHedgeFlag);
    order->price_type = xone::ConvertFromSfitOrderPriceType(&origin->OrderPriceType);
    order->time_condition = xone::ConvertFromSfitTimeCondition(&origin->TimeCondition);
    order->volume_condition = xone::ConvertFromSfitVolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = xone::ConvertFromSfitForceClose(&origin->ForceCloseReason);
    order->volume_left = origin->VolumeTotalOriginal;
    order->volume_orign = origin->VolumeTotalOriginal;
    order->order_ref = origin->OrderRef;
    order->session_id = m_session.value().SessionID;
    order->front_id = m_session.value().FrontID;
    order->min_volume = origin->MinVolume;
    order->unit_id = std::atoll(origin->OrderRef) % 100;
    order->user_key = m_user_key;
    order->status = OrderStatus::kAlive;
    if (msg->RspInfo.ErrorID != 0) {
      order->status = OrderStatus::kDead;
      order->status_msg = msg->RspInfo.ErrorMsg;
    }
  });
}

void XOneUnitOrderTradeView::ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node) {
  const std::string& cache_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  auto it = m_trade_cache.find(cache_key);
  if (it == m_trade_cache.end())
    return;
  auto& trades = it->second;
  for (auto trade : trades) {
    ProcessTrade(trade, order_node);
  }
  m_trade_cache.erase(it);
}

void XOneUnitOrderTradeView::ProcessTrade(
  std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin, std::shared_ptr<future::OrderNode> order_node) {
  auto trade_key = future::TradeBase::MakeKey(m_user_key, origin->TradeID, origin->OrderSysID);
  auto trade_node = m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->index = ++m_index;
    trade->investor_id = origin->InvestorID;
    if (origin->UserID[0] != '\0')
      trade->user_id = origin->UserID;
    else
      trade->user_id = origin->InvestorID;
    if (origin->TradingDay[0] != '\0' && origin->TradeTime[0] != '\0') {
      trade->trade_date_time = GetRealTradeTime(origin->TradingDay, origin->TradeTime);
    }
    trade->exchange_id = origin->ExchangeID;
    trade->instrument_id = origin->InstrumentID;
    trade->exchange_trade_id = origin->TradeID;
    trade->exchange_order_id = origin->OrderSysID;
    trade->order_local_id = origin->OrderLocalID;
    trade->price = origin->Price;
    trade->volume = origin->Volume;
    trade->direction = xone::ConvertFromSfitDirection(&origin->Direction);
    trade->offset = xone::ConvertFromSfitOffset(origin->OffsetFlag);
    trade->hedge_flag = ConvertFromSfitHedgeFlag(&origin->HedgeFlag);
    auto ins = m_md_helper->GetShmInstrument(trade->Symbol(), true);
    if (trade->offset == Offset::kOpen) {
      if (!ins->HasCloseToday()) {
        if (trade->direction == Direction::kBuy)
          m_long_position[trade->Symbol()] += trade->volume;
        else
          m_short_position[trade->Symbol()] += trade->volume;
      }
    } else {
      if (ins->HasCloseToday()) {
        if (trade->offset == Offset::kCloseToday)
          trade->volume_close_today = trade->volume;
        else
          trade->volume_close_yesterday = trade->volume;
      } else {
        if (trade->direction == Direction::kBuy) {
          trade->volume_close_today = std::min(m_short_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_short_position[trade->Symbol()] -= trade->volume_close_today;
        } else {
          trade->volume_close_today = std::min(m_long_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_long_position[trade->Symbol()] -= trade->volume_close_today;
        }
      }
    }
    trade->trader_id = origin->TraderID;
    trade->user_key = m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_node->Latest()->order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    auto rate_node = m_node_db->GetNode<Rate>(m_user_key + "|" + trade->instrument_id);
    auto commission = CalcTradeCommission(rate_node, trade, m_md_helper);
    // 无法计算, 进行手续费率查询
    if (isnan(commission)) {
      auto req = std::make_shared<fclib::future::QueryCommissionRate>(m_user_key);
      req->exchange_id = trade->exchange_id;
      req->instrument_id = trade->instrument_id;
      if (m_ready) {
        m_api_adapter->ReqQryCommission(req);
      } else {
        std::string symbol = trade->Symbol();
        if (m_query_commands.find(symbol) == m_query_commands.end())
          m_query_commands[symbol] = req;
      }
    } else {
      trade->commission = commission;
    }
  });
}

void XOneUnitOrderTradeView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<XOneTradePlatform::CThostFtdcTradeField>(msg->pMainField);
  auto order_node = GetMatchOrder(origin);
  if (!order_node) {
    AddTradeToCache(origin);
    return;
  }
  ProcessTrade(origin, order_node);
}

void XOneUnitOrderTradeView::OnRtnQuote(std::shared_ptr<SpiMessage> msg) {
  auto quote = std::static_pointer_cast<XOneTradePlatform::CThostFtdcQuoteField>(msg->pMainField);
  auto quote_id = ToFclibOrderId(quote->QuoteRef, quote->SessionID, quote->FrontID);
  auto investor_id = std::string(quote->InvestorID);
  auto user_id = std::string(quote->UserID);
  if (user_id.empty())
    user_id = investor_id;
  std::string bid_order_id, ask_order_id;
  if (quote->BidOrderRef[0] == '\0') {
    if (quote->BidOrderSysID[0] != '\0') {
      bid_order_id = m_order_sysids[quote->InstrumentID][quote->BidOrderSysID];
      ask_order_id = m_order_sysids[quote->InstrumentID][quote->AskOrderSysID];
    }
  } else {
    bid_order_id = ToFclibOrderId(quote->BidOrderRef, quote->SessionID, quote->FrontID);
    ask_order_id = ToFclibOrderId(quote->AskOrderRef, quote->SessionID, quote->FrontID);
  }
  auto quote_key = m_user_key + "|" + quote_id;
  auto quote_node = m_node_db->ReplaceRecord<Quote>(quote_key, [=](std::shared_ptr<Quote> target_quote) {
    target_quote->user_key = m_user_key;
    target_quote->investor_id = investor_id;
    target_quote->user_id = user_id;
    target_quote->instrument_id = quote->InstrumentID;
    target_quote->exchange_id = quote->ExchangeID;
    target_quote->response_quote_id = quote->ForQuoteSysID;
    target_quote->ask_price = quote->AskPrice;
    target_quote->bid_price = quote->BidPrice;
    target_quote->ask_volume = quote->AskVolume;
    target_quote->bid_volume = quote->BidVolume;
    target_quote->ask_order_id = ask_order_id;
    target_quote->bid_order_id = bid_order_id;
    target_quote->ask_offset = ConvertFromSfitOffset(quote->AskOffsetFlag);
    target_quote->bid_offset = ConvertFromSfitOffset(quote->BidOffsetFlag);
    target_quote->ask_hedge_flag = ConvertFromSfitHedgeFlag(&quote->AskHedgeFlag);
    target_quote->bid_hedge_flag = ConvertFromSfitHedgeFlag(&quote->BidHedgeFlag);
    target_quote->status = ConvertFromSfitOrderStatus(&quote->QuoteStatus);
    target_quote->exchange_quote_id = quote->QuoteSysID;
    if (target_quote->quote_id.empty())
      target_quote->quote_id = quote_id;
  });
  if (quote->SessionID == m_api_adapter->GetSession() && m_api_adapter->GetCommandManager()) {
    if (quote->QuoteStatus == THOST_FTDC_OST_Canceled) {
      auto req = m_api_adapter->GetCommandManager()->Update("ReqCancelQuote" + quote_id);
      SetCommandFinished(req, 0, u8"成功");
    } else if (quote->QuoteStatus != THOST_FTDC_OST_Unknown) {
      auto req = m_api_adapter->GetCommandManager()->Update("ReqInsertQuote" + quote_id);
      if (req) {
        std::static_pointer_cast<InsertQuote>(req)->quote_id = quote_id;
        std::static_pointer_cast<InsertQuote>(req)->quote_pointer = quote_node;
      }
      SetCommandFinished(req, 0, u8"成功");
    }
  }
}

std::shared_ptr<future::OrderNode> XOneUnitOrderTradeView::GetMatchOrder(
  std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  auto it = m_trade_order_map.find(map_key);
  if (it == m_trade_order_map.end())
    return nullptr;
  return it->second;
}

void XOneUnitOrderTradeView::AddTradeToCache(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  m_trade_cache[map_key].insert(origin);
}

void XOneUnitOrderTradeView::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField
    && (msg->RspInfo.ErrorID == 0 || msg->RspInfo.ErrorID == 2087 || msg->RspInfo.ErrorID == 3034
      || msg->RspInfo.ErrorID == 3033 || msg->RspInfo.ErrorID == 3035 || msg->RspInfo.ErrorID == 3036)) {
    auto rsp = std::static_pointer_cast<XOneTradePlatform::CThostFtdcRspUserLoginField>(msg->pMainField);
    if (m_trading_day != std::string(rsp->TradingDay)) {
      m_index = 0;
    }
    m_trading_day = rsp->TradingDay;
    m_session = *rsp;
  }
}

