  return OrderVolumeCondition::kAny;
}

fclib::future::ForceCloseReason ConvertFromSfitForceClose(const XOneTradePlatform::TThostFtdcForceCloseReasonType* t) {
  if (*t == THOST_FTDC_FCC_NotForceClose)
