/**
委托/成交列表 功能单元. 它所要完成的任务包括:

* 维护账户的委托单/成交记录列表, 尽力保持它们更新.

它不处理任何用户指令.
 */
class XOneUnitOrderTradeView : public FuncUnit {
 public:
  XOneUnitOrderTradeView(XOneApiAdapter* api_adapter, std::shared_ptr<TqApiNodeDb> node_db, std::string user_key,
    std::shared_ptr<md::MdServiceShmHelper> md_helper, structlog::Logger& parent_logger);

  /**
   * 收到登录回应.
   *
   * 当登录回应表示登录成功时, 记录 session 信息到 m_session.
   */
  void OnRspUserLogin(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到下单回报. 用回报信息更新委托单列表.
   */
  void OnRspOrderInsert(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到回单信息. 用回单信息更新委托单列表.
   */
  void OnRtnOrder(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到成交通知.
   *
   * 如果收到成交通知时, 尚未收到对应的委托单信息, 则将成交记录存放(AddTradeToCache), 暂不处理.
   * 否则会立即处理(ProcessTrade)
   */
  void OnRtnTrade(std::shared_ptr<SpiMessage> msg);

  /**
   * 收到quote回单信息， 更新quote列表
   *
   * 如果收到quote信息时，尚未收到order信息，则quote信息将会被缓存
   * 否则会立即处理
   */
  void OnRtnQuote(std::shared_ptr<SpiMessage> msg);

 private:
  /**
   * 处理成交通知. 将成交记录放入成交列表, 并建立成交记录和对应委托单之间的双向指针关联.
   */
  void ProcessTrade(
    std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin, std::shared_ptr<future::OrderNode>);

  std::shared_ptr<future::OrderNode> GetMatchOrder(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin);

  /**
   * 将还不能处理的成交记录放入暂存区.
   */
  void AddTradeToCache(std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField> origin);

  /**
   * 处理暂存区中与 order_node 相关的成交记录.
   */
  void ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node);

  /**
   * 这个表用于查找一个Trade对应的Order节点.
   * KEY定义为 OrderSysID + "|" + ExchangeID, 这两个字段可以唯一确定一个委托单, 且Trade中携带有这两个字段.
   */
  std::map<std::string, std::shared_ptr<future::OrderNode>> m_trade_order_map;

  /**
   * 这个表用于缓存收到的Trade数据包.
   * 在XOne私有流中, 存在Order/Trade乱序问题, 即一个委托单可能在收到第一个RtnOrder前先收到RtnTrade,
   * 因为我们需要在 Trade 中提供指向 Order 节点的指针, 必须将 Trade 信息暂缓处理, 直到 RtnOrder 到位.
   *
   * KEY定义为 OrderSysID + "|" + ExchangeID, 这两个字段可以唯一确定一个委托单, 且Trade中携带有这两个字段.
   * 每个KEY下存放所有暂时无法处理的 Trade 记录.
   */
  std::map<std::string, std::set<std::shared_ptr<XOneTradePlatform::CThostFtdcTradeField>>> m_trade_cache;

  /**
   * 当前登录 session 信息. 如果当前处于未登录或已断线状态, 则为空.
   */
  std::optional<XOneTradePlatform::CThostFtdcRspUserLoginField> m_session;

  int RunOnce() override {
    return 0;
  }

  XOneApiAdapter* m_api_adapter = nullptr;
  std::shared_ptr<TqApiNodeDb> m_node_db;
  std::string m_user_key;
  std::shared_ptr<md::MdServiceShmHelper> m_md_helper;

  structlog::Logger m_logger;

  std::map<std::string, std::map<std::string, std::string>> m_order_sysids;
  std::shared_ptr<NodeDbView<LoginContent>> m_login_view;
  std::shared_ptr<NodeDbView<Trade>> m_trade_view;
  std::shared_ptr<NodeDbView<Rate>> m_rate_view;

  bool m_ready = false;

  /** 以下两个map记录无平今指令的交易所下合约当前剩余开仓手数 */
  std::map<std::string, md::Volume> m_long_position;
  std::map<std::string, md::Volume> m_short_position;
  /**
   * m_index 记录 OnRtnOrder/Trade 次序.
   * 两个回包会导致 oder/trade 变动,众期将这些变动写入数据库.
   * 一旦断线重连,则会收到当日流水,导致数据库有重复数据.
   * 因此添加m_index来标志短线前流水位置,重连后从断线后开始写入日志.
   * m_index 切换交易日后应当清零.
   */
  int m_index;
  std::string m_trading_day;
  std::map<std::string, std::shared_ptr<UserCommand>> m_query_commands;
};

