void XOneSpiHandler::OnFrontConnected() {
  m_logger.Info("OnFrontConnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontConnected;
  PushSpiMessage(msg);
}

void XOneSpiHandler::OnFrontDisconnected(int nReason) {
  m_logger.With("nReason", nReason).Info("OnFrontDisconnected");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontDisconnected;
  msg->RspInfo.ErrorID = nReason;
  PushSpiMessage(msg);
}

void XOneSpiHandler::OnFrontConnectError(int nErrCode) {
  m_logger.With("nErrCode", nErrCode).Info("OnFrontConnectError");
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnFrontConnectError;
  msg->RspInfo.ErrorID = nErrCode;
  PushSpiMessage(msg);
}

void XOneSpiHandler::OnRspError(XOneTradePlatform::CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  m_logger.With("request_id", nRequestID).With("is_last", bIsLast);
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::OnRspError;
  msg->nRequestID = nRequestID;
  msg->bIsLast = bIsLast;
  if (pRspInfo) {
    memcpy(&msg->RspInfo, pRspInfo, sizeof(XOneTradePlatform::CThostFtdcRspInfoField));
  }
  m_logger.Info("OnRspError");
  PushSpiMessage(msg);
}

