  XOneTradePlatform::CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
  LogXOneRtn(m_logger, "OnRspAuthenticate", pRspAuthenticateField, pRspInfo, nRequestID, bIsLast);
  PushSpiMessage(MakeSpiMsg<XOneTradePlatform::CThostFtdcRspAuthenticateField>(
    SpiMessage::Tag::OnRspAuthenticate, pRspAuthenticateField, pRspInfo, nRequestID, bIsLast));
}

void XOneSpiHandler::OnRspUserLogin(XOneTradePlatform::CThostFtdcRspUserLoginField* pRspUserLogin,
  XOneTradePlatform::CThostFtdcRspInfoField* pRspInfo, int nRequestID, bool bIsLast) {
