  : m_service(service)
  , m_logger(parent_logger.With("order_trade_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyExtendedOrder, [this](std::shared_ptr<SpiMessage> msg) {
    notifyExtendedOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyExtendedTrade, [this](std::shared_ptr<SpiMessage> msg) {
    notifyExtendedTrade(msg);
  });
}

int YiDaOrderTradeView::RunOnce() {
  return 0;
}

void YiDaOrderTradeView::notifyExtendedOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<YDExtendedOrder>(msg->pMainField);
  std::string order_id;
  if (field->YDOrderFlag == YD_YOF_Normal) {
    order_id = ToFclibOrderId(field->OrderRef, field->OrderGroupID);
    if (field->OrderGroupID == 0) {
      order_id = std::to_string(field->OrderSysID);
    }
  } else if (field->YDOrderFlag == YD_YOF_QuoteDerived) {
    order_id = std::to_string(field->OrderSysID);
  } else {
    return;
  }
  int64_t session_id = 0;
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update("ReqInsertOrder" + order_id));
  if (req) {
    session_id = m_service->m_session_id;
  }
  // 赋值字段
  auto order_key = m_service->m_user_key + "|" + order_id;
  m_service->GetNodeDb()->ReplaceRecord<Order>(order_key, [&](std::shared_ptr<future::Order> o) {
    if (o->order_id.empty()) {
      auto iter = m_service->m_send_time.find(o->order_id);
      if (iter != m_service->m_send_time.end()) {
        o->send_date_time = iter->second;
        m_service->m_send_time.erase(iter);
      }
      o->receive_date_time = NowAsEpochNano();
    }
    o->session_id = session_id;
    o->exchange_order_id = field->ErrorNo == YD_ERROR_InvalidGroupOrderRef ? "" : std::to_string(field->OrderSysID);
    o->user_key = m_service->m_user_key;
    o->user_id = field->m_pAccount->AccountID;
    o->order_id = order_id;

    o->investor_id = field->m_pAccount->AccountID;
    o->exchange_id = field->m_pInstrument->m_pExchange->ExchangeID;
    o->instrument_id = field->m_pInstrument->InstrumentID;
    o->status = PullOrderStatus(field->OrderStatus);
    if (field->ErrorNo != 0) {
      o->status = OrderStatus::kDead;
      o->status_msg = GetErrorMsg(field->ErrorNo);
    }
    o->direction = PullDir(field->Direction);
    o->offset = PullOffset(field->OffsetFlag);
    if (field->OrderType == 0) {
      o->time_condition = OrderTimeCondition::kGfd;
      o->volume_condition = OrderVolumeCondition::kAny;
      o->price_type = PriceType::kLimit;
    } else if (field->OrderType == 3) {
      o->time_condition = OrderTimeCondition::kIoc;
      o->volume_condition = OrderVolumeCondition::kAll;
      o->price_type = PriceType::kAny;
    } else {
      o->time_condition = OrderTimeCondition::kIoc;
      o->volume_condition = OrderVolumeCondition::kAny;
      o->price_type = PriceType::kAny;
    }
    o->force_close_reason = ForceCloseReason::kNotForceClose;
    o->volume_orign = field->OrderVolume;
    o->volume_left = field->OrderVolume - field->TradeVolume;
    o->limit_price = field->Price;
    o->hedge_flag = PullHedge(field->HedgeFlag);
    o->is_swap_order = false;
    char time[20];
    timeStamp2String(field->InsertTimeStamp, time);
    o->insert_date_time = GetRealTradeTime(m_service->m_trading_day.c_str(), time);
    if (req) {
      o->request_id = std::to_string(req->request_id);
    }
    if (o->status == OrderStatus::kDead && o->volume_left > 0) {
      o->dead_date_time = GetRealTradeTime(m_service->m_trading_day.c_str(), time);
    }
  });
}

void YiDaOrderTradeView::notifyExtendedTrade(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<YDExtendedTrade>(msg->pMainField);
  std::string order_id = ToFclibOrderId(field->OrderRef, field->OrderGroupID);
  if (field->OrderGroupID == 0) {
    order_id = std::to_string(field->OrderSysID);
  }
  auto order_node = m_service->GetNodeDb()->GetNode<Order>(Order::MakeKey(m_service->m_user_key, order_id));
  auto trade_key =
    Trade::MakeKey(m_service->m_user_key, std::to_string(field->TradeID), std::to_string(field->OrderSysID));
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->investor_id = field->m_pAccount->AccountID;
    trade->user_id = field->m_pAccount->AccountID;
    char time[20];
    timeStamp2String(field->TradeTimeStamp, time);
    trade->trade_date_time = GetRealTradeTime(m_service->m_trading_day.c_str(), time);
    trade->direction = PullDir(field->Direction);
    trade->exchange_id = order_node->Latest()->exchange_id;
    trade->instrument_id = order_node->Latest()->instrument_id;
    trade->exchange_trade_id = std::to_string(field->TradeID);
    trade->offset = PullOffset(field->OffsetFlag);
    trade->exchange_order_id = std::to_string(field->OrderSysID);
    trade->hedge_flag = PullHedge(field->HedgeFlag);
    trade->order_local_id = std::to_string(field->OrderLocalID);
    trade->price = field->Price;
    trade->volume = field->Volume;
    trade->user_key = m_service->m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    trade->commission = field->Commission;
  });
}

