void YiDaServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  auto it = m_processor.find(command->aid);
  if (it != m_processor.end()) {
    command->status = UserCommand::Status::kStarted;
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: YiDa柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
}

void YiDaServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int YiDaServiceImpl::RunOnce() {
  // api运转一次
  int msg_count = 0;
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  while (!m_recv_queue.empty()) {
    auto msg = m_recv_queue.front();
    ProcessSpiMsg(msg);
    m_recv_queue.pop();
    msg_count++;
  }
  // 返回处理数据包数量
  return msg_count;
}

void YiDaServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_processor[tag] = processor;
}

void YiDaServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

