int YiDaServiceImpl::BuildApi(std::shared_ptr<UserCommand> command) {
  DeleteApi();
  if (m_config_file.empty()) {
    // get ip and port
    std::vector<std::string> ips;
    std::vector<std::string> ports;
    for (auto& front : m_req_login->broker.trading_fronts) {
      auto index = front.find("//");
      if (index == std::string::npos)
        return -1;
      auto ip_port = front.substr(index + 2);
      auto pos = ip_port.find(":");
      if (pos == std::string::npos)
        return -1;
      ports.push_back(ip_port.substr(pos + 1));
      ips.push_back(ip_port.substr(0, pos));
    }
    // create config file
    std::string file_name = m_req_login->user_id + "_" + std::to_string(GetCurrentPID()) + "_yd.ini";
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_config_file = temp_dir_path.append(file_name).generic_string();
    std::ofstream outputFile(m_config_file, std::ofstream::out);
    if (outputFile.is_open()) {
      if (m_req_login->broker.trading_fronts.size() > 1) {
        outputFile << "RecoverySiteCount=2" << std::endl;
        outputFile << "TradingServerIP=" << ips[0] << std::endl;
        outputFile << "TradingServerPort=" << ports[0] << std::endl;
        outputFile << "TradingServerIP2=" << ips[1] << std::endl;
        outputFile << "TradingServerPort2=" << ports[1] << std::endl;
      } else {
        outputFile << "RecoverySiteCount=1" << std::endl;
        outputFile << "TradingServerIP=" << ips[0] << std::endl;
        outputFile << "TradingServerPort=" << ports[0] << std::endl;
      }
      outputFile << "TradingProtocol=TCP" << std::endl;
      outputFile << "TCPTradingCPUID=-1" << std::endl;
      outputFile << "XTCPTradingCPUID=-1" << std::endl;
      outputFile << "TradingServerTimeout=10" << std::endl;
      outputFile << "RecalcMode=auto" << std::endl;
      outputFile << "RecalcMarginPositionProfitGap=1000" << std::endl;
      outputFile << "RecalcFreeGap=100" << std::endl;
      outputFile << "TimerCPUID=-1" << std::endl;
      outputFile << "ConnectTCPMarketData=yes" << std::endl;
      outputFile << "TCPMarketDataTimeout=10" << std::endl;
      outputFile << "TCPMarketDataCPUID=-1" << std::endl;
      outputFile << "ReceiveUDPMarketData=no" << std::endl;
      outputFile.close();
    } else {
      return -1;
    }
  }
  m_api = makeYDExtendedApi(m_config_file.c_str());
  if (!m_api) {
    return -1;
  }
  m_spi = new YiDaSpiHandler(m_ioc, m_logger, this);
  if (!m_api->startExtended(m_spi, m_spi)) {
    return -1;
  }
  return 0;
}

void YiDaServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);
  if (nullptr == m_api)
    return;
  m_api->startDestroy();
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api = nullptr;
}

std::queue<std::shared_ptr<SpiMessage>>* YiDaServiceImpl::GetSpiQueue() {
  return &m_recv_queue;
}

