template <class T>
std::shared_ptr<SpiMessage> MakeSpiMsg(SpiMessage::Tag tag, const T* plain_src) {
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = tag;
  if (plain_src) {
    std::shared_ptr<T> target = std::make_shared<T>();
    memcpy(target.get(), plain_src, sizeof(T));
    msg->pMainField = target;
  }
  return msg;
}

YiDaSpiHandler::YiDaSpiHandler(boost::asio::io_context* ioc, structlog::Logger& parent_logger, YiDaServiceImpl* impl)
  : m_logger(parent_logger.Clone())
  , m_impl(impl)
  , m_strand(*ioc) {}

YiDaSpiHandler::~YiDaSpiHandler() {}

void YiDaSpiHandler::notifyReadyForLogin(bool hasLoginFailed) {
  m_logger.With("hasLoginFailed", hasLoginFailed).Info("notifyReadyForLogin");
  if (hasLoginFailed)
    return;
  auto msg = std::make_shared<SpiMessage>();
  msg->tag = SpiMessage::Tag::notifyReadyForLogin;
  PushSpiMessage(msg);
}

void YiDaSpiHandler::notifyEvent(int apiEvent) {
  m_logger.With("apiEvent", apiEvent).Info("notifyEvent");
  auto msg = std::make_shared<SpiMessage>();
  msg->nErrorCode = apiEvent;
  msg->tag = SpiMessage::Tag::notifyEvent;
  PushSpiMessage(msg);
}

void YiDaSpiHandler::notifyLogin(int errorNo, int maxOrderRef, bool isMonitor) {
  m_logger.With("errorNo", errorNo).With("maxOrderRef", maxOrderRef).With("isMonitor", isMonitor).Info("notifyLogin");
  auto msg = std::make_shared<SpiMessage>();
  msg->nErrorCode = errorNo;
  msg->tag = SpiMessage::Tag::notifyLogin;
  PushSpiMessage(msg);
}

