void YiDaSpiHandler::PushBack(std::shared_ptr<SpiMessage> msg) {
  if (m_impl)
    m_impl->GetSpiQueue()->push(msg);
}

void YiDaSpiHandler::PushSpiMessage(std::shared_ptr<SpiMessage> msg) {
  if (nullptr == m_impl)
    return;
  auto queue = m_impl->GetSpiQueue();
  m_strand.post([=]() {
    queue->push(msg);
  });
}
