    notifyExtendedQuote(msg);
  });
}

int YiDaInsertCancelOrder::RunOnce() {
  return 0;
}

void YiDaInsertCancelOrder::ExecuteInsertOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  auto order_ref = req->order_ref;
  auto order_id = ToFclibOrderId(order_ref, m_service->m_req_login->yida.group_id);
  FCASSERT(order_id == req->order_id);
  YDInputOrder field;
  memset(&field, 0, sizeof(field));
  field.Direction = PushDir(req->direction);
  field.OffsetFlag = PushOffset(req->offset);
  field.HedgeFlag = PushHedge(req->hedge_flag);
  field.Price = req->limit_price;
  field.OrderVolume = req->volume;
  field.OrderRef = order_ref;
  field.OrderGroupID = m_service->m_req_login->yida.group_id;
  field.GroupOrderRefControl = YD_GORF_Increase;
  field.OrderType = PushOrderType(req->price_type, req->time_condition, req->volume_condition);
  auto ins = m_service->m_api->getInstrumentByID(req->instrument_id.c_str());
  if (!ins) {
    SetCommandFinished(command, -1, u8"未找到此合约");
    return;
  }
  bool ret = m_service->m_api->insertOrder(&field, ins);
  m_logger.With("ret", ret)
    .With("InstrumentID", ins->InstrumentID)
    .With("OrderRef", field.OrderRef)
    .With("OrderType", field.OrderType)
    .With("Price", field.Price)
    .With("OrderVolume", field.OrderVolume)
    .With("HedgeFlag", field.HedgeFlag)
    .With("Direct", field.Direction)
    .With("Offset", field.OffsetFlag)
    .With("GroupId", field.OrderGroupID)
    .Info("ReqOrderInsert");
  m_service->m_command_manager->SetCommandId(req, "ReqInsertOrder" + order_id);
  m_service->m_send_time[order_id] = NowAsEpochNano();
  if (!ret) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
  }
}

void YiDaInsertCancelOrder::notifyExtendedOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<YDExtendedOrder>(msg->pMainField);
  std::string order_id;
  if (field->YDOrderFlag == YD_YOF_Normal) {
    order_id = ToFclibOrderId(field->OrderRef, field->OrderGroupID);
    if (field->OrderGroupID == 0) {
      order_id = std::to_string(field->OrderSysID);
    }
  } else if (field->YDOrderFlag == YD_YOF_QuoteDerived) {
    order_id = std::to_string(field->OrderSysID);
  } else {
    return;
  }
  if (PullOrderStatus(field->OrderStatus) == OrderStatus::kAlive) {
    m_order_alive[order_id] = field;
  } else {
    m_order_alive.erase(order_id);
  }
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update("ReqInsertOrder" + order_id));
  auto cancel_req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(field->OrderSysID));
  if (req && req->status != UserCommand::Status::kFinished) {
    auto order_key = m_service->m_user_key + "|" + order_id;
    auto order_node = m_service->GetNodeDb()->GetNode<Order>(order_key);
    SetCommandFinished(req, field->ErrorNo, GetErrorMsg(field->ErrorNo));
  }
  if (cancel_req && cancel_req->status != UserCommand::Status::kFinished) {
    if (PullOrderStatus(field->OrderStatus) == OrderStatus::kDead)
      SetCommandFinished(cancel_req);
  }
}

void YiDaInsertCancelOrder::ExecuteCancelOrder(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<CancelOrder>(m_service->m_command_manager->Update(command));
  m_logger.With("req->order_id", req->order_id).Info("ExecuteCancelOrder");
  req->status = UserCommand::Status::kStarted;
  // 撤委托单
  auto it = m_order_alive.find(req->order_id);
  if (it == m_order_alive.end()) {
    SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
    return;
  }
  auto order = it->second;
  if (order->YDOrderFlag == YD_YOF_QuoteDerived) {
    ExecuteCancelQuote(req, order->m_pInstrument->m_pExchange);
    return;
  }
  YDCancelOrder field;
  memset(&field, 0, sizeof(field));
  field.OrderSysID = order->OrderSysID;
  bool ret = m_service->m_api->cancelOrder(&field, order->m_pInstrument->m_pExchange);
  m_logger.With("field.OrderSysID", std::to_string(field.OrderSysID)).With("ret", ret).Info("ReqCancelOrder");
  if (!ret) {
    SetCommandFinished(req, ret, u8"因网络原因导致撤单失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(command, "ReqCancelOrder" + std::to_string(field.OrderSysID));
}

void YiDaInsertCancelOrder::notifyFailedCancelOrder(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<YDFailedCancelOrder>(msg->pMainField);
  auto req = m_service->m_command_manager->Update("ReqCancelOrder" + std::to_string(field->OrderSysID));
  SetCommandFinished(req, field->ErrorNo, GetErrorMsg(field->ErrorNo));
}

void YiDaInsertCancelOrder::ExecuteInsertQuote(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update(command));
  req->status = UserCommand::Status::kStarted;
  auto quote_ref = req->quote_ref ? req->quote_ref : (GenerateOrderRef() * 100 + req->unit_id);
  auto quote_id = ToFclibOrderId(quote_ref, m_service->m_req_login->yida.group_id);
  FCASSERT(quote_id == req->quote_id);
  YDInputQuote field;
  memset(&field, 0, sizeof(field));
  field.OrderRef = quote_ref;
  field.AskHedgeFlag = PushHedge(req->ask_hedge_flag);
  field.AskOffsetFlag = PushOffset(req->ask_offset);
  field.AskPrice = req->ask_price;
  field.AskVolume = req->ask_volume;
  field.BidHedgeFlag = PushHedge(req->bid_hedge_flag);
  field.BidOffsetFlag = PushOffset(req->bid_offset);
  field.BidPrice = req->bid_price;
  field.BidVolume = req->bid_volume;
  field.OrderGroupID = m_service->m_req_login->yida.group_id;
  field.GroupOrderRefControl = YD_GORF_Increase;
  auto ins = m_service->m_api->getInstrumentByID(req->instrument_id.c_str());
  if (!ins) {
    SetCommandFinished(command, -1, u8"未找到此合约");
    return;
  }
  bool ret = m_service->m_api->insertQuote(&field, ins);
  m_logger.With("ret", ret)
    .With("Reference", field.OrderRef)
    .With("AskPrice", field.AskPrice)
    .With("AskVolume", field.AskVolume)
    .With("BidPrice", field.BidPrice)
    .With("BidVolume", field.BidVolume)
    .With("InstrumentID", ins->InstrumentID)
    .With("AskOffsetFlag", field.AskOffsetFlag)
    .With("BidOffsetFlag", field.BidOffsetFlag)
    .With("AskHedgeFlag", field.AskHedgeFlag)
    .With("BidHedgeFlag", field.BidHedgeFlag)
    .Info("ExecuteInsertQuote");
  m_service->m_command_manager->SetCommandId(req, "ExecuteInsertQuote" + quote_id);
  if (!ret) {
    SetCommandFinished(req, ret, u8"因网络原因导致下单失败");
  }
}

void YiDaInsertCancelOrder::notifyExtendedQuote(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto field = std::static_pointer_cast<YDExtendedQuote>(msg->pMainField);
  if (!field->AskOrderFinished) {
    m_quote_alive[std::to_string(field->AskOrderSysID)] = field->QuoteSysID;
  } else {
    m_quote_alive.erase(std::to_string(field->AskOrderSysID));
  }
  if (!field->BidOrderFinished) {
    m_quote_alive[std::to_string(field->BidOrderSysID)] = field->QuoteSysID;
  } else {
    m_quote_alive.erase(std::to_string(field->BidOrderSysID));
  }
  std::string quote_id = ToFclibOrderId(field->OrderRef, field->OrderGroupID);
  auto req =
    std::static_pointer_cast<InsertQuote>(m_service->m_command_manager->Update("ExecuteInsertQuote" + quote_id));
  if (req && req->status != UserCommand::Status::kFinished) {
    SetCommandFinished(req, field->ErrorNo, GetErrorMsg(field->ErrorNo));
  }
  auto cancel_req = m_service->m_command_manager->Update("ReqCancelQuote" + std::to_string(field->QuoteSysID));
  if (cancel_req && cancel_req->status != UserCommand::Status::kFinished) {
    if (field->AskOrderFinished && field->BidOrderFinished)
      SetCommandFinished(cancel_req);
  }
}

void YiDaInsertCancelOrder::ExecuteCancelQuote(std::shared_ptr<CancelOrder> req, const YDExchange* yd_exchange) {
  req->status = UserCommand::Status::kStarted;
  YDCancelQuote field;
  memset(&field, 0, sizeof(field));
  auto it = m_quote_alive.find(req->order_id);
  if (it == m_quote_alive.end()) {
    SetCommandFinished(req, 1, u8"fclib: 报单编号不存在");
    return;
  }
  field.QuoteSysID = it->second;
  bool ret = m_service->m_api->cancelQuote(&field, yd_exchange);
  m_logger.With("QuoteSysID", std::to_string(field.QuoteSysID)).With("ret", ret).Info("ReqCancelQuote");
  if (!ret) {
    SetCommandFinished(req, ret, u8"因网络原因导致撤单失败");
    return;
  }
  m_service->m_command_manager->SetCommandId(req, "ReqCancelQuote" + std::to_string(field.QuoteSysID));
}

int YiDaInsertCancelOrder::GenerateOrderRef() {
  return m_order_ref++;
}

