YiDaLogIn::YiDaLogIn(YiDaServiceImpl *service, structlog::Logger &parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterCommandProcessor(ChangePassword::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePassword(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyReadyForLogin, [this](std::shared_ptr<SpiMessage> msg) {
    notifyReadyForLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyEvent, [this](std::shared_ptr<SpiMessage> msg) {
    notifyEvent(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyLogin, [this](std::shared_ptr<SpiMessage> msg) {
    notifyLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyCaughtUp, [this](std::shared_ptr<SpiMessage> msg) {
    notifyCaughtUp(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyChangePassword, [this](std::shared_ptr<SpiMessage> msg) {
    notifyChangePassword(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyGroupMaxOrderRef, [this](std::shared_ptr<SpiMessage> msg) {
    notifyGroupMaxOrderRef(msg);
  });
}

void YiDaLogIn::InitAndLogin(std::shared_ptr<UserCommand> command) {
  m_service->m_command_manager->SetCommandId(command, "login");
  m_service->m_req_login = std::static_pointer_cast<ReqLogin>(m_service->m_command_manager->Update(command));
  if (!m_api_created) {
    int ret = m_service->BuildApi(command);
    if (ret != 0)
      SetCommandFinished(command, -1, u8"fclib: API创建失败,请检查交易前置");
    m_api_created = true;
    return;
  }
  if (m_service->m_api->login(m_service->m_req_login->user_id.c_str(), m_service->m_req_login->password.c_str(),
        m_service->m_req_login->broker.app_id.c_str(), m_service->m_req_login->broker.auth_code.c_str()))
    return;
  auto req = m_service->m_command_manager->Update("login");
  SetCommandFinished(req, -1, u8"fclib: 登录请求频繁, 请 3s 后重试");
}

void YiDaLogIn::notifyEvent(std::shared_ptr<SpiMessage> msg) {
  if (msg->nErrorCode != YD_AE_TCPTradeDisconnected)
    return;
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->investor_id = m_service->m_req_login->user_id;
      target_login->session_status = SessionStatus::kDisconnected;
      target_login->max_order_ref = -1;
      target_login->system_name = "yida";
      target_login->backend = BackEnd::kYiDa;
    });
}

void YiDaLogIn::notifyReadyForLogin(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_api->login(m_service->m_req_login->user_id.c_str(), m_service->m_req_login->password.c_str(),
        m_service->m_req_login->broker.app_id.c_str(), m_service->m_req_login->broker.auth_code.c_str()))
    return;
  auto req = m_service->m_command_manager->Update("login");
  SetCommandFinished(req, -1, u8"fclib: 登录请求频繁, 请 3s 后重试");
}

void YiDaLogIn::notifyLogin(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("login");
  if (msg->nErrorCode != 0) {
    SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
    return;
  }
  m_service->m_trading_day = std::to_string(m_service->m_api->getTradingDay());
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->investor_id = m_service->m_req_login->user_id;
      if (!target_login->trading_day.empty()
        && target_login->trading_day != std::to_string(m_service->m_api->getTradingDay())) {
        m_service->m_new_day = true;
        target_login->session_status = SessionStatus::kDisconnected;
      } else {
        target_login->session_status = SessionStatus::kLogined;
      }
      target_login->trading_day = std::to_string(m_service->m_api->getTradingDay());
      target_login->confirm_status = ConfirmStatus::kConfirmed;
      target_login->system_name = "yida";
      target_login->backend = BackEnd::kYiDa;
      target_login->max_order_ref = -1;
      target_login->session_id = reinterpret_cast<int64_t>(msg.get());
      if (target_login->user_desc == "") {
        target_login->user_desc = m_service->m_req_login->user_desc;
      }
    });
  SetCommandFinished(req);
  m_service->m_session_id = reinterpret_cast<int64_t>(msg.get());
}

void YiDaLogIn::notifyCaughtUp(std::shared_ptr<SpiMessage> msg) {
  m_service->GetNodeDb()->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [=](std::shared_ptr<future::LoginContent> target_login) {
      target_login->user_key = m_service->m_user_key;
      target_login->user_id = m_service->m_req_login->user_id;
      target_login->investor_id = m_service->m_req_login->user_id;
      target_login->position_ready = true;
      target_login->account_ready = true;
    });
}

void YiDaLogIn::ReqChangePassword(std::shared_ptr<UserCommand> command) {
  auto request = std::static_pointer_cast<future::ChangePassword>(command);
  if (request->password_type == PasswordType::kTransfer) {
    SetCommandFinished(request, -1, u8"fclib: 只支持修改交易密码");
    return;
  }
  m_service->m_api->changePassword(
    m_service->m_req_login->user_id.c_str(), request->old_password.c_str(), request->new_password.c_str());
  m_service->m_command_manager->SetCommandId(command, "change_password");
}

void YiDaLogIn::notifyChangePassword(std::shared_ptr<SpiMessage> msg) {
  auto req = m_service->m_command_manager->Update("change_password");
  SetCommandFinished(req, msg->nErrorCode, GetErrorMsg(msg->nErrorCode));
