#include "yida_rate.h"

#include <memory>

namespace fclib {
namespace future {
namespace yida {
YiDaRate::YiDaRate(YiDaServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("yida_rate_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterCommandProcessor(QueryMarginRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqMarginRate(command);
  });
  m_service->RegisterCommandProcessor(QueryCommissionRate::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqCommissionRate(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyFinishInit, [this](std::shared_ptr<SpiMessage> msg) {
    notifyFinishInit(msg);
  });
}

void YiDaRate::ReqMarginRate(std::shared_ptr<UserCommand> command) {
  if (!m_inited) {
    SetCommandFinished(command, -1, u8"fclib: 数据未就绪, 稍后重试");
    return;
  }
  auto qry = std::static_pointer_cast<QueryMarginRate>(command);
  auto ins = m_service->m_api->getInstrumentByID(qry->instrument_id.c_str());
  if (!ins) {
    SetCommandFinished(command, -1, u8"未找到此合约");
    return;
  }
  const YDMarginRate* field_spec = m_service->m_api->getInstrumentMarginRate(ins, YD_HF_Speculation);
  const YDMarginRate* field_other = m_service->m_api->getInstrumentMarginRate(ins, YD_HF_Hedge);
  if (!field_spec || !field_other) {
    SetCommandFinished(command, -1, u8"无保证金信息");
    return;
  }
  m_func_list.push_back([this, ins, field_spec, field_other, command]() {
    auto rate_key = m_service->m_user_key + "|" + ins->InstrumentID;
    m_service->GetNodeDb()->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = ins->InstrumentID;
      rate_node->exchange_id = ins->m_pExchange->ExchangeID;
      rate_node->margin_rate_long_spec =
        UnitRate(field_spec->LongMarginRatioByMoney, field_spec->LongMarginRatioByVolume);
      rate_node->margin_rate_short_spec =
        UnitRate(field_spec->ShortMarginRatioByMoney, field_spec->ShortMarginRatioByVolume);
      rate_node->margin_rate_long_other =
        UnitRate(field_other->LongMarginRatioByMoney, field_other->LongMarginRatioByVolume);
      rate_node->margin_rate_short_other =
        UnitRate(field_other->ShortMarginRatioByMoney, field_other->ShortMarginRatioByVolume);
    });
    SetCommandFinished(command);
  });
}

void YiDaRate::ReqCommissionRate(std::shared_ptr<UserCommand> command) {
  if (!m_inited) {
    SetCommandFinished(command, -1, u8"fclib: 数据未就绪, 稍后重试");
    return;
  }
  auto qry = std::static_pointer_cast<QueryCommissionRate>(command);
  auto ins = m_service->m_api->getInstrumentByID(qry->instrument_id.c_str());
  if (!ins) {
    SetCommandFinished(command, -1, u8"未找到此合约");
    return;
  }
  const YDCommissionRate* field = m_service->m_api->getInstrumentCommissionRate(ins, YD_HF_Speculation);
  if (!field) {
    SetCommandFinished(command, -1, u8"无手续费信息");
    return;
  }
  m_func_list.push_back([this, ins, field, command]() {
    auto rate_key = m_service->m_user_key + "|" + ins->InstrumentID;
    m_service->GetNodeDb()->ReplaceRecord<Rate>(rate_key, [&](std::shared_ptr<future::Rate> rate_node) {
      rate_node->user_key = m_service->m_user_key;
      rate_node->instrument_id = ins->InstrumentID;
      rate_node->exchange_id = ins->m_pExchange->ExchangeID;
      rate_node->commission_rate_open = UnitRate(field->OpenRatioByMoney, field->OpenRatioByVolume);
      rate_node->commission_rate_close = UnitRate(field->CloseRatioByMoney, field->CloseRatioByVolume);
      rate_node->commission_rate_close_today = UnitRate(field->CloseTodayRatioByMoney, field->CloseTodayRatioByVolume);
      rate_node->commission_rate_exec = (UnitRate(NAN, NAN));
    });
    SetCommandFinished(command);
  });
}

void YiDaRate::notifyFinishInit(std::shared_ptr<SpiMessage> msg) {
  m_inited = true;
}

int YiDaRate::RunOnce() {
  for (const auto& f : m_func_list) {
    f();
  }
  m_func_list.clear();
  return 0;
}

