  return std::to_string(ref) + "|" + std::to_string(group_id);
}

char PushDir(Direction& d) {
  if (d == Direction::kBuy)
    return YD_D_Buy;
  return YD_D_Sell;
}

Direction PullDir(const int& d) {
  if (d == 0)
    return Direction::kBuy;
  return Direction::kSell;
}

char PushOffset(Offset& o) {
  if (o == Offset::kOpen)
    return YD_OF_Open;
  if (o == Offset::kCloseToday)
    return YD_OF_CloseToday;
  if (o == Offset::kCloseYesterday)
    return YD_OF_CloseYesterday;
  if (o == Offset::kOpenAndClose)
    return YD_OF_Open1Close2;
  if (o == Offset::kCloseAndOpen)
    return YD_OF_Close1Open2;
  return YD_OF_Close;
}

Offset PullOffset(const int& o) {
  if (o == YD_OF_Open)
    return Offset::kOpen;
  if (o == YD_OF_CloseToday)
    return Offset::kCloseToday;
  if (o == YD_OF_CloseYesterday)
    return Offset::kCloseYesterday;
  if (o == YD_OF_Open1Close2)
    return Offset::kOpenAndClose;
  if (o == YD_OF_Close1Open2)
    return Offset::kCloseAndOpen;
  return Offset::kClose;
}

char PushHedge(OrderHedgeFlag& h) {
  if (h == OrderHedgeFlag::kSpeculation)
    return YD_HF_Speculation;
  if (h == OrderHedgeFlag::kArbitrage)
    return YD_HF_Arbitrage;
  return YD_HF_Hedge;
}

OrderHedgeFlag PullHedge(const int& h) {
  if (h == YD_HF_Speculation)
    return OrderHedgeFlag::kSpeculation;
  if (h == YD_HF_Arbitrage)
    return OrderHedgeFlag::kArbitrage;
  return OrderHedgeFlag::kHedge;
}

char PushOrderType(PriceType& o, OrderTimeCondition& t, OrderVolumeCondition& v) {
  if (o == PriceType::kLimit)
    return YD_ODT_Limit;
  if (o == PriceType::kAny)
    return YD_ODT_Market;
  if (t == OrderTimeCondition::kIoc && v == OrderVolumeCondition::kAny)
    return YD_ODT_FAK;
  if (t == OrderTimeCondition::kIoc && v == OrderVolumeCondition::kAll)
    return YD_ODT_FOK;
  FCASSERT(false);
  return YD_ODT_Limit;
}

OrderStatus PullOrderStatus(const int& s) {
  if (s == 0 || s == 1)
    return OrderStatus::kAlive;
  return OrderStatus::kDead;
}

