SubPosition* GetSubPosition(std::shared_ptr<Position> position, const int& direction, const int& hedgeflag) {
  SubPosition* subpos = nullptr;
  if (hedgeflag == YD_HF_Speculation) {
    if (direction == YD_PD_Long) {
      subpos = &position->subpos_long_spec;
    } else {
      subpos = &position->subpos_short_spec;
    }
  } else {
    if (direction == YD_PD_Long) {
      subpos = &position->subpos_long_other;
    } else {
      subpos = &position->subpos_short_other;
    }
  }
  return subpos;
}

double GetPositionPrice(YDExtendedPosition::CPositionDetail* PositionDetailList, double settle_price) {
  YDExtendedPosition::CPositionDetail* p = PositionDetailList;
  double sum_v = 0;
  double sum_p = 0;
  while (p) {
    double price = p->Price;
    if (p->TradeID < 0)
      price = settle_price;
    sum_v += p->Volume;
    sum_p += p->Volume * price;
    p = p->m_pNext;
  }
  if (sum_v > 0)
    return sum_p / sum_v;
  return 0;
}

YiDaPositionAccount::YiDaPositionAccount(YiDaServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("position_account_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyExtendedPosition, [this](std::shared_ptr<SpiMessage> msg) {
    notifyExtendedPosition(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::notifyExtendedAccount, [this](std::shared_ptr<SpiMessage> msg) {
    notifyExtendedAccount(msg);
  });
  m_service->RegisterCommandProcessor(QueryInvestorPosition::AID, [](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
  });
  m_service->RegisterCommandProcessor(QueryTradingAccount::AID, [](std::shared_ptr<UserCommand> command) {
    SetCommandFinished(command);
  });
}

void YiDaPositionAccount::notifyExtendedPosition(std::shared_ptr<SpiMessage> msg) {
  if (!msg->pMainField)
    return;
  auto pos_spi_key = std::static_pointer_cast<PositionSpi>(msg->pMainField);
  auto field = m_service->m_api->getExtendedPosition(pos_spi_key->positionDate, pos_spi_key->positionDirection,
    pos_spi_key->hedgeFlag, pos_spi_key->pInstrument, pos_spi_key->pAccount);
  if (!field)
    return;
  std::string ins_id = pos_spi_key->pInstrument->InstrumentID;
  std::string position_symbol = std::string(pos_spi_key->pInstrument->m_pExchange->ExchangeID) + "."
    + std::string(pos_spi_key->pInstrument->InstrumentID);
  auto ins = m_service->m_md_helper->GetShmInstrument(position_symbol, true);
  auto position_key = Position::MakeKey(m_service->m_user_key, 0, ins->symbol.data());
  m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> target_position) {
    target_position->user_key = m_service->m_user_key;
    target_position->investor_id = pos_spi_key->pAccount->AccountID;
    target_position->exchange_id = ins->exchange_id.data();
    target_position->instrument_id = ins->instrument_id.data();
    target_position->last_price = pos_spi_key->pInstrument->m_pMarketData->LastPrice;
    auto subpos = GetSubPosition(target_position, field->PositionDirection, field->HedgeFlag);
    if (pos_spi_key->pInstrument->m_pExchange->UseTodayPosition) {
      if (field->PositionDate == YD_PSD_Today) {
        subpos->volume_today = field->Position;
        subpos->volume_today_frozen = field->CloseFrozen;
        subpos->_margin = field->Margin;
        subpos->_close_profit = field->CloseProfit;
        subpos->_position_profit = field->PositionProfit;
        subpos->_open_cost = field->getOpenPrice() * subpos->volume_today * pos_spi_key->pInstrument->Multiple;
        subpos->_position_cost =
          GetPositionPrice(field->PositionDetailList, pos_spi_key->pInstrument->m_pMarketData->PreSettlementPrice)
          * subpos->volume_today * pos_spi_key->pInstrument->Multiple;
      } else {
        subpos->volume_his = field->Position;
        subpos->volume_his_frozen = field->CloseFrozen;
        subpos->_margin_his = field->Margin;
        subpos->_close_profit_his = field->CloseProfit;
        subpos->_position_profit_his = field->PositionProfit;
        subpos->_open_cost_his = field->getOpenPrice() * subpos->volume_his * pos_spi_key->pInstrument->Multiple;
        subpos->_position_cost_his =
          GetPositionPrice(field->PositionDetailList, pos_spi_key->pInstrument->m_pMarketData->PreSettlementPrice)
          * subpos->volume_his * pos_spi_key->pInstrument->Multiple;
      }
    } else {
      subpos->volume_his = field->getYDPosition();
      subpos->volume_today = field->Position - subpos->volume_his;
      if (subpos->volume_his > field->CloseFrozen) {
        subpos->volume_his_frozen = field->CloseFrozen;
        subpos->volume_today_frozen = 0;
      } else {
        subpos->volume_his_frozen = subpos->volume_his;
        subpos->volume_today_frozen = field->CloseFrozen - subpos->volume_his;
      }
      subpos->_margin = field->Margin;
      subpos->_close_profit_his = field->CloseProfit;
      subpos->_position_profit = field->PositionProfit;
      subpos->_open_cost = field->getOpenPrice() * field->Position * pos_spi_key->pInstrument->Multiple;
      subpos->_position_cost =
        GetPositionPrice(field->PositionDetailList, pos_spi_key->pInstrument->m_pMarketData->PreSettlementPrice)
        * field->Position * pos_spi_key->pInstrument->Multiple;
    }
    subpos->margin = subpos->_margin + subpos->_margin_his;
    subpos->close_profit = subpos->_close_profit + subpos->_close_profit_his;
    subpos->position_profit = subpos->_position_profit + subpos->_position_profit_his;
    subpos->open_price = (subpos->_open_cost + subpos->_open_cost_his) / subpos->Volume();
    subpos->float_profit =
      (target_position->last_price - subpos->open_price) * pos_spi_key->pInstrument->Multiple * subpos->Volume();
    subpos->position_price =
      (subpos->_position_cost + subpos->_position_cost_his) / pos_spi_key->pInstrument->Multiple / subpos->Volume();
  });
}

void YiDaPositionAccount::notifyExtendedAccount(std::shared_ptr<SpiMessage> msg) {
  auto field = m_service->m_api->getExtendedAccount();
  if (!field)
    return;
  auto account_key = Account::MakeKey(m_service->m_user_key, 0, "CNY");
  m_service->m_node_db->ReplaceRecord<Account>(account_key, [&](std::shared_ptr<Account> a) {
    a->user_key = m_service->m_user_key;
    a->investor_id = field->m_pAccount->AccountID;
    a->available = field->usable();
    a->balance = field->Balance;
    a->client_equity = field->cashBalance();
    a->close_profit = field->CloseProfit + field->OtherCloseProfit;
    a->commission = field->Commission;
    a->currency = "CNY";
    a->deposit = field->m_pAccount->Deposit;
    // a->float_profit = todo;
    // a->frozen_commission = yida暂不支持;
    a->margin = field->Margin;
    a->future_market_value = field->marketValue();
    a->withdraw = field->m_pAccount->Withdraw;
    a->position_profit = field->PositionProfit;
    a->premium = field->CashIn;
    a->pre_balance = field->m_pAccount->PreBalance;
    a->risk_ratio = 0;
    a->ref_risk_ratio = 0;
    if (a->client_equity > 0) {
      a->risk_ratio = a->margin / a->client_equity;
    }
    if (a->balance > 0) {
      a->ref_risk_ratio = a->margin / a->balance;
    }
  });
}

