// 计算成交手续费
double CalcTradeCommission(
  std::shared_ptr<RateNode> rate_node, std::shared_ptr<Trade> trade, std::shared_ptr<md::MdServiceShmHelper> helper) {
  if (!rate_node)
    return NAN;
  auto volume_multiple = helper->GetShmInstrumentField(trade->Symbol(), &shm::ShmInstrument::volume_multiple, true);
  if (!volume_multiple.has_value())
    return NAN;
  if (trade->offset == Offset::kOpen) {
    auto commission = rate_node->Latest()->commission_rate_open;
    return (commission.volume_rate + commission.amount_rate * trade->price * volume_multiple.value()) * trade->volume;
  }
  auto commission_close = rate_node->Latest()->commission_rate_close;
  auto commission_close_today = rate_node->Latest()->commission_rate_close_today;
  return (commission_close.volume_rate + commission_close.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_yesterday
    + (commission_close_today.volume_rate + commission_close_today.amount_rate * trade->price * volume_multiple.value())
    * trade->volume_close_today;
}
namespace rohon {
RohonUnitOrderTradeView::RohonUnitOrderTradeView(RohonServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("order_trade_view_unit", reinterpret_cast<int64_t>(this)).Clone())
  , m_index(0) {
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnOrder, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnOrder(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspOrderInsert, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspOrderInsert(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRtnTrade, [this](std::shared_ptr<SpiMessage> msg) {
    OnRtnTrade(msg);
  });

  m_trade_view = m_service->m_node_db->CreateView<Trade>([=](std::shared_ptr<const Trade> trade) {
    return trade->user_key == m_service->m_user_key;
  });
  m_rate_view = m_service->m_node_db->CreateView<Rate>([=](std::shared_ptr<const Rate> rate) {
    return rate->user_key == m_service->m_user_key;
  });
  m_rate_view->OnUpdate(std::to_string(reinterpret_cast<int64_t>(this)), [=](std::shared_ptr<RateNode> rate_node) {
    auto instrument_id = rate_node->Latest()->instrument_id;
    for (const auto& [key, trade_node] : m_trade_view->GetNodes()) {
      if (trade_node->Latest()->instrument_id != instrument_id)
        continue;
      m_service->m_node_db->ReplaceRecord<Trade>(key, [=](std::shared_ptr<Trade> trade) {
        trade->commission = CalcTradeCommission(rate_node, trade, m_service->m_md_helper);
      });
    }
  });
}

void RohonUnitOrderTradeView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->OrderRef, origin->SessionID, origin->FrontID);
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto order_node = m_service->m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (order->order_id.empty()) {
      if (m_session->SessionID == origin->SessionID) {
        auto iter = m_service->m_send_time.find(order_id);
        if (iter != m_service->m_send_time.end()) {
          order->send_date_time = iter->second;
          m_service->m_send_time.erase(iter);
        }
        order->receive_date_time = NowAsEpochNano();
      }
    }
    order->index = ++m_index;
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    order->investor_id = origin->InvestorID;
    if (origin->UserID[0] != '\0')
      order->user_id = origin->UserID;
    else
      order->user_id = origin->InvestorID;
    order->direction = rohon::ConvertFromSfitDirection(&origin->Direction);
    order->exchange_order_id = origin->OrderSysID;
    order->status_msg = GbkToUtf8(origin->StatusMsg);
    order->is_swap_order = origin->IsSwapOrder;
    order->limit_price = origin->LimitPrice;
    order->offset = rohon::ConvertFromSfitOffset(origin->CombOffsetFlag[0]);
    order->hedge_flag = rohon::ConvertFromSfitHedgeFlag(&origin->CombHedgeFlag);
    order->price_type = rohon::ConvertFromSfitOrderPriceType(&origin->OrderPriceType);
    order->status = rohon::ConvertFromSfitOrderStatus(&origin->OrderStatus);
    order->time_condition = rohon::ConvertFromSfitTimeCondition(&origin->TimeCondition);
    order->volume_condition = rohon::ConvertFromSfitVolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = rohon::ConvertFromSfitForceClose(&origin->ForceCloseReason);
    order->volume_left = origin->VolumeTotal;
    order->is_quote = origin->OrderType == '1';
    order->volume_orign = origin->VolumeTotalOriginal;
    order->order_ref = origin->OrderRef;
    order->session_id = origin->SessionID;
    order->front_id = origin->FrontID;
    order->order_local_id = origin->OrderLocalID;
    order->trader_id = origin->TraderID;
    order->min_volume = origin->MinVolume;
    order->request_id = std::to_string(origin->RequestID);
    if (origin->TradingDay[0] != '\0') {
      if (origin->InsertTime[0] != '\0') {
        order->insert_date_time = GetRealTradeTime(origin->TradingDay, origin->InsertTime);
      }
      if (origin->CancelTime[0] != '\0') {
        order->dead_date_time = GetRealTradeTime(origin->TradingDay, origin->CancelTime);
      }
    }
    order->user_product_info = origin->UserProductInfo;
    order->order_id = order_id;
    std::string user_product_info = origin->UserProductInfo;
    if (user_product_info.find("SHINNY") != 0 && user_product_info.find("shinny") != 0)
      order->unit_id = -1;
    else
      order->unit_id = std::atoll(origin->OrderRef) % 100;
    order->user_key = m_service->m_user_key;
  });
  auto map_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  m_trade_order_map[map_key] = order_node;
  if (origin->VolumeTraded > 0) {
    ProcessCachedTrade(order_node);
  }
}

void RohonUnitOrderTradeView::OnRspOrderInsert(std::shared_ptr<SpiMessage> msg) {
  if (!m_session.has_value())
    return;
  auto origin = std::static_pointer_cast<CThostFtdcInputOrderField>(msg->pMainField);
  auto order_id = ToFclibOrderId(origin->OrderRef, m_session.value().SessionID, m_session.value().FrontID);
  auto order_key = m_service->m_user_key + "|" + order_id;
  auto req = std::static_pointer_cast<InsertOrder>(m_service->m_command_manager->Update("ReqInsertOrder" + order_id));
  FCASSERT(req);
  auto order_node = m_service->m_node_db->ReplaceRecord<Order>(order_key, [=](std::shared_ptr<Order> order) {
    if (!order->order_id.empty())
      return;
    order->order_id = order_id;
    order->exchange_id = origin->ExchangeID;
    order->instrument_id = origin->InstrumentID;
    if (order->exchange_id.empty())
      order->exchange_id = req->exchange_id;
    order->investor_id = origin->InvestorID;
    order->is_swap_order = origin->IsSwapOrder;
    if (origin->UserID[0] != '\0')
      order->user_id = origin->UserID;
    else
      order->user_id = origin->InvestorID;
    order->direction = rohon::ConvertFromSfitDirection(&origin->Direction);
    order->limit_price = origin->LimitPrice;
    order->offset = rohon::ConvertFromSfitOffset(origin->CombOffsetFlag[0]);
    order->hedge_flag = rohon::ConvertFromSfitHedgeFlag(&origin->CombHedgeFlag);
    order->price_type = rohon::ConvertFromSfitOrderPriceType(&origin->OrderPriceType);
    order->time_condition = rohon::ConvertFromSfitTimeCondition(&origin->TimeCondition);
    order->volume_condition = rohon::ConvertFromSfitVolumeCondition(&origin->VolumeCondition);
    order->force_close_reason = rohon::ConvertFromSfitForceClose(&origin->ForceCloseReason);
    order->volume_left = origin->VolumeTotalOriginal;
    order->volume_orign = origin->VolumeTotalOriginal;
    order->order_ref = origin->OrderRef;
    order->session_id = m_session.value().SessionID;
    order->front_id = m_session.value().FrontID;
    order->min_volume = origin->MinVolume;
    order->unit_id = std::atoll(origin->OrderRef) % 100;
    order->user_key = m_service->m_user_key;
    order->request_id = std::to_string(origin->RequestID);
    order->status = OrderStatus::kAlive;
    if (msg->RspInfo.ErrorID != 0) {
      order->status = OrderStatus::kDead;
      order->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
    }
  });
}

void RohonUnitOrderTradeView::ProcessCachedTrade(std::shared_ptr<future::OrderNode> order_node) {
  const std::string& cache_key = order_node->Latest()->exchange_order_id + "|" + order_node->Latest()->exchange_id;
  auto it = m_trade_cache.find(cache_key);
  if (it == m_trade_cache.end())
    return;
  auto& trades = it->second;
  for (auto trade : trades) {
    ProcessTrade(trade, order_node);
  }
  m_trade_cache.erase(it);
}

int RohonUnitOrderTradeView::RunOnce() {
  return 0;
}

void RohonUnitOrderTradeView::ProcessTrade(
  std::shared_ptr<CThostFtdcTradeField> origin, std::shared_ptr<future::OrderNode> order_node) {
  auto trade_key = future::TradeBase::MakeKey(m_service->m_user_key, origin->TradeID, origin->OrderSysID);
  auto trade_node = m_service->m_node_db->ReplaceRecord<Trade>(trade_key, [=](std::shared_ptr<Trade> trade) {
    trade->index = ++m_index;
    trade->investor_id = origin->InvestorID;
    if (origin->UserID[0] != '\0')
      trade->user_id = origin->UserID;
    else
      trade->user_id = origin->InvestorID;
    if (origin->TradingDay[0] != '\0' && origin->TradeTime[0] != '\0') {
      trade->trade_date_time = GetRealTradeTime(origin->TradingDay, origin->TradeTime);
    }
    trade->exchange_id = origin->ExchangeID;
    trade->instrument_id = origin->InstrumentID;
    trade->exchange_trade_id = origin->TradeID;
    trade->exchange_order_id = origin->OrderSysID;
    trade->order_local_id = origin->OrderLocalID;
    trade->price = origin->Price;
    trade->volume = origin->Volume;
    trade->direction = rohon::ConvertFromSfitDirection(&origin->Direction);
    trade->offset = rohon::ConvertFromSfitOffset(origin->OffsetFlag);
    trade->hedge_flag = ConvertFromSfitHedgeFlag(&origin->HedgeFlag);
    auto ins = m_service->m_md_helper->GetShmInstrument(trade->Symbol(), true);
    FCASSERT(ins.has_value());
    if (trade->offset == Offset::kOpen) {
      if (!ins->HasCloseToday()) {
        if (trade->direction == Direction::kBuy)
          m_long_position[trade->Symbol()] += trade->volume;
        else
          m_short_position[trade->Symbol()] += trade->volume;
      }
    } else {
      if (ins->HasCloseToday()) {
        if (trade->offset == Offset::kCloseToday)
          trade->volume_close_today = trade->volume;
        else
          trade->volume_close_yesterday = trade->volume;
      } else {
        if (trade->direction == Direction::kBuy) {
          trade->volume_close_today = (std::min)(m_short_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_short_position[trade->Symbol()] -= trade->volume_close_today;
        } else {
          trade->volume_close_today = (std::min)(m_long_position[trade->Symbol()], trade->volume);
          trade->volume_close_yesterday = trade->volume - trade->volume_close_today;
          m_long_position[trade->Symbol()] -= trade->volume_close_today;
        }
      }
    }
    trade->trader_id = origin->TraderID;
    trade->user_key = m_service->m_user_key;
    trade->order_pointer = order_node;
    trade->order_id = order_node->Latest()->order_id;
    trade->unit_id = order_node->Latest()->unit_id;
    auto rate_node = m_service->m_node_db->GetNode<Rate>(m_service->m_user_key + "|" + trade->instrument_id);
    auto commission = CalcTradeCommission(rate_node, trade, m_service->m_md_helper);
    // 无法计算, 进行手续费率查询
    if (isnan(commission)) {
      auto req = std::make_shared<fclib::future::QueryCommissionRate>(m_service->m_user_key);
      req->exchange_id = trade->exchange_id;
      req->instrument_id = trade->instrument_id;
      m_service->ExecuteCommand(req);
    } else {
      trade->commission = commission;
    }
  });
}

void RohonUnitOrderTradeView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  auto origin = std::static_pointer_cast<CThostFtdcTradeField>(msg->pMainField);
  auto order_node = GetMatchOrder(origin);
  if (!order_node) {
    AddTradeToCache(origin);
    return;
  }
  ProcessTrade(origin, order_node);
}

std::shared_ptr<future::OrderNode> RohonUnitOrderTradeView::GetMatchOrder(
  std::shared_ptr<CThostFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  auto it = m_trade_order_map.find(map_key);
  if (it == m_trade_order_map.end())
    return nullptr;
  return it->second;
}

void RohonUnitOrderTradeView::AddTradeToCache(std::shared_ptr<CThostFtdcTradeField> origin) {
  auto map_key = std::string(origin->OrderSysID) + "|" + std::string(origin->ExchangeID);
  m_trade_cache[map_key].insert(origin);
}

void RohonUnitOrderTradeView::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    auto rsp = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
    m_session = *rsp;
    if (m_trading_day != std::string(rsp->TradingDay)) {
      m_index = 0;
    }
    m_trading_day = rsp->TradingDay;
  }
}

