#ifndef FCLIB_ROHON_ORDER_TRADE_VIEW_H
#define FCLIB_ROHON_ORDER_TRADE_VIEW_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <memory>
