DcePositionAutoComb::DcePositionAutoComb(std::shared_ptr<NodeDbView<Position>> position_view,
  std::shared_ptr<md::MdServiceShmHelper> md_helper, structlog::Logger& parent_logger)
  : m_position_view(position_view)
  , m_md_helper(md_helper)
  , m_logger(parent_logger.With("dce_comb", reinterpret_cast<int64_t>(this)).Clone()) {}

void DcePositionAutoComb::CalcCombInsert(std::function<void(std::shared_ptr<future::PositionCombInsert>)> func) {
  for (auto& [key, cmd] : m_last_comb_insert) { /** 尚有指令未完成,此时应该等待完成 */
    if (cmd->result_code == 0 && cmd->status != UserCommand::Status::kFinished) {
      return;
    }
  }
  std::vector<std::shared_ptr<future::Position>> positions;
  for (auto& [key, position_node] : m_position_view->GetNodes()) {
    if (!position_node->Snap())
      continue;
    auto position = position_node->Latest();
    auto product_class =
      m_md_helper->GetShmInstrumentField(position->Symbol(), &shm::ShmInstrument::product_class, true);
    if (!product_class.has_value())
      continue;
    if ((position->exchange_id != "DCE" && position->exchange_id != "GFEX") || position->VolumeTotal() == 0
      || product_class == md::ProductClass::kCombine || position->VolumeTotal() == position->VolumeComb())
      continue;
    auto trade_status = m_md_helper->GetShmTradeStatus(position->Symbol());
    if (trade_status != md::TradeStatus::kContinous)
      continue;
    positions.push_back(std::make_shared<future::Position>(*position));
  }

  for (int i = static_cast<int>(DceCombType::kSP); i <= static_cast<int>(DceCombType::kBFO); i++) {
    for (auto it_first = positions.begin(); it_first != positions.end(); ++it_first) {
      auto p0 = *it_first;
      if (p0->VolumeTotal() == p0->VolumeComb())
        continue;
      auto p0_ins = m_md_helper->GetShmInstrument(p0->Symbol(), true);
      FCASSERT(p0_ins.has_value());
      if (i == static_cast<int>(DceCombType::kSP)) {
        if (p0_ins->product_class != md::ProductClass::kFuture)
          continue;
        if (auto comb_insert = GetCombInsert("SP ", p0, p0, Direction::kBuy, Direction::kSell, false)) {
          func(comb_insert);
        }
        continue;
      }
      if (i == static_cast<int>(DceCombType::kOPL)) {
        if (p0_ins->product_class == md::ProductClass::kOption) {
          if (auto comb_insert = GetCombInsert("OPL ", p0, p0, Direction::kBuy, Direction::kSell, true)) {
            func(comb_insert);
          }
        }
        continue;
      }
      auto it_second = it_first;
      ++it_second;
      for (; it_second != positions.end(); ++it_second) {
        auto p1 = *it_second;
        auto p1_ins = m_md_helper->GetShmInstrument(p1->Symbol(), true);
        FCASSERT(p1_ins.has_value());
        if (p1->exchange_id != p0->exchange_id || p1->VolumeTotal() == p1->VolumeComb())
          continue;
        if (i == static_cast<int>(DceCombType::kSPD)) {
          if (p0_ins->product_id != p1_ins->product_id)
            continue;
          if (p0_ins->product_class != md::ProductClass::kFuture || p1_ins->product_class != md::ProductClass::kFuture)
            continue;
          if (auto comb_insert = GetCombInsert("SP ", p0, p1, Direction::kBuy, Direction::kSell, false)) {
            func(comb_insert);
          } else if (auto comb_insert = GetCombInsert("SP ", p0, p1, Direction::kSell, Direction::kBuy, false)) {
            func(comb_insert);
          }
          continue;
        }
        if (i == static_cast<int>(DceCombType::kSPC)) {
          if (p0_ins->product_class != md::ProductClass::kFuture || p1_ins->product_class != md::ProductClass::kFuture)
            continue;
          std::string comb0 = std::string(p0_ins->product_id.data()) + "&" + p1_ins->product_id.data();
          std::string comb1 = std::string(p1_ins->product_id.data()) + "&" + p0_ins->product_id.data();
          static std::set<std::string> dce_spc_combi = {"a&m", "y&p", "l&v", "j&jm", "l&pp", "v&pp", "i&jm", "i&j",
            "c&cs", "b&m", "eb&eg", "eb&l", "a&b", "eb&pp", "eb&v", "eg&l", "eg&pp", "eg&v", "pg&l", "pg&pp", "pg&v",
            "pg&eb", "pg&eg"};
          if (dce_spc_combi.find(comb0) != dce_spc_combi.end()) {
            if (auto comb_insert = GetCombInsert("SPC ", p0, p1, Direction::kBuy, Direction::kSell, false)) {
              func(comb_insert);
            } else if (auto comb_insert = GetCombInsert("SPC ", p0, p1, Direction::kSell, Direction::kBuy, false)) {
              func(comb_insert);
            }
          }
          if (dce_spc_combi.find(comb1) != dce_spc_combi.end()) {
            if (auto comb_insert = GetCombInsert("SPC", p1, p0, Direction::kBuy, Direction::kSell, false)) {
              func(comb_insert);
            } else if (auto comb_insert = GetCombInsert("SPC", p1, p0, Direction::kSell, Direction::kBuy, false)) {
              func(comb_insert);
            }
          }
          continue;
        }
        std::optional<shm::ShmInstrument> p0_underlying_ins = std::nullopt;
        if (!p0_ins->underlying_symbol.empty()) {
          p0_underlying_ins = m_md_helper->GetShmInstrument(p0_ins->underlying_symbol.data(), true);
          FCASSERT(p0_underlying_ins.has_value());
        }
        std::optional<shm::ShmInstrument> p1_underlying_ins = std::nullopt;
        if (!p1_ins->underlying_symbol.empty()) {
          p1_underlying_ins = m_md_helper->GetShmInstrument(p1_ins->underlying_symbol.data(), true);
          FCASSERT(p1_underlying_ins.has_value());
        }
        if (i == static_cast<int>(DceCombType::kPRT)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p0_underlying_ins
            && p0_underlying_ins->symbol == p1_ins->symbol) {
            if (p0_ins->option_class == md::OptionClass::kCall) {
              if (auto comb_insert = GetCombInsert("PRT ", p0, p1, Direction::kSell, Direction::kBuy, false)) {
                func(comb_insert);
              }
            } else {
              if (auto comb_insert = GetCombInsert("PRT ", p0, p1, Direction::kSell, Direction::kSell, false)) {
                func(comb_insert);
              }
            }
          }
          if (p1_ins->product_class == md::ProductClass::kOption && p1_underlying_ins
            && p1_underlying_ins->symbol == p0_ins->symbol) {
            if (p1_ins->option_class == md::OptionClass::kCall) {
              if (auto comb_insert = GetCombInsert("PRT ", p1, p0, Direction::kSell, Direction::kBuy, false)) {
                func(comb_insert);
              }
            } else {
              if (auto comb_insert = GetCombInsert("PRT ", p1, p0, Direction::kSell, Direction::kSell, false)) {
                func(comb_insert);
              }
            }
          }
          continue;
        }
        if (i == static_cast<int>(DceCombType::kSTD)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p1_ins->product_class == md::ProductClass::kOption
            && p0_underlying_ins && p1_underlying_ins && p0_underlying_ins->symbol == p1_underlying_ins->symbol
            && p0_ins->option_class == md::OptionClass::kCall && p1_ins->option_class == md::OptionClass::kPut
            && p0_ins->strike_price == p1_ins->strike_price) {
            if (auto comb_insert = GetCombInsert("STD ", p0, p1, Direction::kSell, Direction::kSell, true)) {
              func(comb_insert);
            }
          }
          continue;
        }
        if (i == static_cast<int>(DceCombType::kSTG)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p1_ins->product_class == md::ProductClass::kOption
            && p0_underlying_ins && p1_underlying_ins && p0_underlying_ins->symbol == p1_underlying_ins->symbol) {
            if (p0_ins->option_class == md::OptionClass::kCall && p1_ins->option_class == md::OptionClass::kPut
              && p0_ins->strike_price > p1_ins->strike_price) {
              if (auto comb_insert = GetCombInsert("STG ", p1, p0, Direction::kSell, Direction::kSell, true)) {
                func(comb_insert);
              }
            }
            if (p1_ins->option_class == md::OptionClass::kCall && p0_ins->option_class == md::OptionClass::kPut
              && p0_ins->strike_price < p1_ins->strike_price) {
              if (auto comb_insert = GetCombInsert("STG ", p0, p1, Direction::kSell, Direction::kSell, true)) {
                func(comb_insert);
              }
            }
          }
          continue;
        }
        if (i == static_cast<int>(DceCombType::kBER)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p1_ins->product_class == md::ProductClass::kOption
            && p0_underlying_ins && p1_underlying_ins && p0_underlying_ins->symbol == p1_underlying_ins->symbol
            && p0_ins->option_class == p1_ins->option_class && p0_ins->strike_price != p1_ins->strike_price) {
            if (p0_ins->option_class == md::OptionClass::kCall) {
              if (p0_ins->strike_price < p1_ins->strike_price) {
                if (auto comb_insert = GetCombInsert("BLS ", p0, p1, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BER ", p0, p1, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                }
              } else {
                if (auto comb_insert = GetCombInsert("BLS ", p1, p0, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BER ", p1, p0, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                }
              }
            } else {
              if (p0_ins->strike_price > p1_ins->strike_price) {
                if (auto comb_insert = GetCombInsert("BLS ", p0, p1, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BER ", p0, p1, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                }
              } else {
                if (auto comb_insert = GetCombInsert("BLS ", p1, p0, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BER ", p1, p0, Direction::kBuy, Direction::kSell, true)) {
                  func(comb_insert);
                }
              }
            }
          }
          continue;
        }
        if (i == static_cast<int>(DceCombType::kBUL)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p1_ins->product_class == md::ProductClass::kOption
            && p0_underlying_ins && p1_underlying_ins && p0_underlying_ins->symbol == p1_underlying_ins->symbol
            && p0_ins->option_class == p1_ins->option_class && p0_ins->strike_price != p1_ins->strike_price) {
            if (p0_ins->option_class == md::OptionClass::kCall) {
              if (p0_ins->strike_price < p1_ins->strike_price) {
                if (auto comb_insert = GetCombInsert("BES ", p0, p1, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BUL ", p0, p1, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                }
              } else {
                if (auto comb_insert = GetCombInsert("BES ", p1, p0, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BUL ", p1, p0, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                }
              }
            } else {
              if (p0_ins->strike_price > p1_ins->strike_price) {
                if (auto comb_insert = GetCombInsert("BES ", p0, p1, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BUL ", p0, p1, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                }
              } else {
                if (auto comb_insert = GetCombInsert("BES ", p1, p0, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                } else if (auto comb_insert = GetCombInsert("BUL ", p1, p0, Direction::kSell, Direction::kBuy, true)) {
                  func(comb_insert);
                }
              }
            }
          }
          continue;
        }

        if (i == static_cast<int>(DceCombType::kBFO)) {
          if (p0_ins->product_class == md::ProductClass::kOption && p0_underlying_ins
            && p0_underlying_ins->symbol == p1_ins->symbol) {
            if (p0_ins->option_class == md::OptionClass::kCall) {
              if (auto comb_insert = GetCombInsert("BFO ", p0, p1, Direction::kBuy, Direction::kSell, false)) {
                func(comb_insert);
              }
            } else {
              if (auto comb_insert = GetCombInsert("BFO ", p0, p1, Direction::kBuy, Direction::kBuy, false)) {
                func(comb_insert);
              }
            }
          }
          if (p1_ins->product_class == md::ProductClass::kOption && p1_underlying_ins
            && p1_underlying_ins->symbol == p0_ins->symbol) {
            if (p1_ins->option_class == md::OptionClass::kCall) {
              if (auto comb_insert = GetCombInsert("BFO ", p1, p0, Direction::kBuy, Direction::kSell, false)) {
                func(comb_insert);
              }
            } else {
              if (auto comb_insert = GetCombInsert("BFO ", p1, p0, Direction::kBuy, Direction::kBuy, false)) {
                func(comb_insert);
              }
            }
          }
          continue;
        }
      }
    }
  }
}

std::shared_ptr<future::PositionCombInsert> DcePositionAutoComb::GetCombInsert(const std::string& prev,
  std::shared_ptr<future::Position> p0, std::shared_ptr<future::Position> p1, future::Direction dir0,
  future::Direction dir1, bool same_hedge) {
  auto comb_insert = std::make_shared<PositionCombInsert>(p0->user_key);
  comb_insert->comb_direction = CombDirection::kComb;
  comb_insert->exchange_id = p0->exchange_id;
  comb_insert->instrument_id = prev + p0->instrument_id + "&" + p1->instrument_id;
  md::Volume long_spec0 = p0->subpos_long_spec.VolumeCombLeft();
  md::Volume short_spec0 = p0->subpos_short_spec.VolumeCombLeft();
  md::Volume long_other0 = p0->subpos_long_other.VolumeCombLeft();
  md::Volume short_other0 = p0->subpos_short_other.VolumeCombLeft();
  md::Volume long_spec1 = p1->subpos_long_spec.VolumeCombLeft();
  md::Volume short_spec1 = p1->subpos_short_spec.VolumeCombLeft();
  md::Volume long_other1 = p1->subpos_long_other.VolumeCombLeft();
  md::Volume short_other1 = p1->subpos_short_other.VolumeCombLeft();
  if (dir0 == Direction::kBuy) {
    if (long_spec0 > 0) {
      if (dir1 == Direction::kBuy) {
        if (long_spec1 > 0) {
          comb_insert->volume = (std::min)(long_spec0, long_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_spec.volume_comb += comb_insert->volume;
          p1->subpos_long_spec.volume_comb += comb_insert->volume;

          goto end;
        } else if (long_other1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(long_spec0, long_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpecAndHedge;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_spec.volume_comb += comb_insert->volume;
          p1->subpos_long_other.volume_comb += comb_insert->volume;
          goto end;
        }
      } else {
        if (short_spec1 > 0) {
          comb_insert->volume = (std::min)(long_spec0, short_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_spec.volume_comb += comb_insert->volume;
          p1->subpos_short_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (short_other1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(long_spec0, short_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpecAndHedge;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_spec.volume_comb += comb_insert->volume;
          p1->subpos_short_other.volume_comb += comb_insert->volume;
          goto end;
        }
      }
    }
    if (long_other0 > 0) {
      if (dir1 == Direction::kBuy) {
        if (long_spec1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(long_other0, long_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedgeAndSpec;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_other.volume_comb += comb_insert->volume;
          p1->subpos_long_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (long_other1 > 0) {
          comb_insert->volume = (std::min)(long_other0, long_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedge;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_other.volume_comb += comb_insert->volume;
          p1->subpos_long_other.volume_comb += comb_insert->volume;
          goto end;
        }
      } else {
        if (short_spec1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(long_other0, short_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedgeAndSpec;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_other.volume_comb += comb_insert->volume;
          p1->subpos_short_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (short_other1 > 0) {
          comb_insert->volume = (std::min)(long_other0, short_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedge;
          comb_insert->direction = Direction::kBuy;
          p0->subpos_long_other.volume_comb += comb_insert->volume;
          p1->subpos_short_other.volume_comb += comb_insert->volume;
          goto end;
        }
      }
    }
  } else {
    if (short_spec0 > 0) {
      if (dir1 == Direction::kBuy) {
        if (long_spec1 > 0) {
          comb_insert->volume = (std::min)(short_spec0, long_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_spec.volume_comb += comb_insert->volume;
          p1->subpos_long_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (long_other1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(short_spec0, long_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpecAndHedge;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_spec.volume_comb += comb_insert->volume;
          p1->subpos_long_other.volume_comb += comb_insert->volume;
          goto end;
        }
      } else {
        if (short_spec1 > 0) {
          comb_insert->volume = (std::min)(short_spec0, short_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpeculation;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_spec.volume_comb += comb_insert->volume;
          p1->subpos_short_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (short_other1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(short_spec0, short_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kSpecAndHedge;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_spec.volume_comb += comb_insert->volume;
          p1->subpos_short_other.volume_comb += comb_insert->volume;
          goto end;
        }
      }
    }
    if (short_other0 > 0) {
      if (dir1 == Direction::kBuy) {
        if (long_spec1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(short_other0, long_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedgeAndSpec;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_other.volume_comb += comb_insert->volume;
          p1->subpos_long_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (long_other1 > 0) {
          comb_insert->volume = (std::min)(short_other0, long_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedge;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_other.volume_comb += comb_insert->volume;
          p1->subpos_long_other.volume_comb += comb_insert->volume;
          goto end;
        }
      } else {
        if (short_spec1 > 0 && !same_hedge) {
          comb_insert->volume = (std::min)(short_other0, short_spec1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedgeAndSpec;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_other.volume_comb += comb_insert->volume;
          p1->subpos_short_spec.volume_comb += comb_insert->volume;
          goto end;
        } else if (short_other1 > 0) {
          comb_insert->volume = (std::min)(short_other0, short_other1);
          comb_insert->hedge_flag = OrderHedgeFlag::kHedge;
          comb_insert->direction = Direction::kSell;
          p0->subpos_short_other.volume_comb += comb_insert->volume;
          p1->subpos_short_other.volume_comb += comb_insert->volume;
          goto end;
        }
      }
    }
  }
  return nullptr;
end:
  auto it = m_last_comb_insert.find(comb_insert->instrument_id);
  if (it != m_last_comb_insert.end()) {
    if (it->second->result_code != 0 && it->second->result_msg.find(u8"找不到合约") != std::string::npos) {
      return nullptr;
    }
  }
  m_last_comb_insert[comb_insert->instrument_id] = comb_insert;
  return comb_insert;
}

