void RohonUnitPositionAccountView::ProcessQryPositionResults(bool is_first) {
  for (auto origin_position : m_qry_position_results) {
    std::string position_symbol =
      std::string(origin_position->ExchangeID) + "." + std::string(origin_position->InstrumentID);
    bool is_combine = position_symbol.find('&') != std::string::npos;
    auto ins = m_service->m_md_helper->GetShmInstrument(position_symbol, true);
    FCASSERT(ins.has_value());
    auto position_key = m_service->m_user_key + "|0|" + position_symbol;
    auto position_node =
      m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> target_position) {
        target_position->user_key = m_service->m_user_key;
        target_position->investor_id = origin_position->InvestorID;
        target_position->exchange_id = origin_position->ExchangeID;
        target_position->instrument_id = origin_position->InstrumentID;
        double pre_settlement = origin_position->PreSettlementPrice;
        if (!IsValid(pre_settlement) || IsZero(pre_settlement))
          pre_settlement = ins->pre_settlement;
        future::SubPosition* subpos =
          GetSubPosition(target_position, origin_position->PosiDirection, origin_position->HedgeFlag);
        if (origin_position->HedgeFlag == THOST_FTDC_HF_Arbitrage) {
          subpos->hedge_type = PositionHedgeType::kArbitrage;
        }
        if (ins->HasCloseToday()) {                                     // 上期和上期能源
          if (origin_position->PositionDate == THOST_FTDC_PSD_Today) {  // 今仓信息
            subpos->_margin = origin_position->UseMargin;
            subpos->_position_profit = origin_position->PositionProfit;
            subpos->_close_profit = origin_position->CloseProfit;
            subpos->_qry_volume_today = origin_position->TodayPosition;
            subpos->_commission = origin_position->Commission;
            subpos->_premium = origin_position->CashIn;
            subpos->_open_cost = origin_position->OpenCost;
            subpos->strike_frozen = origin_position->StrikeFrozen;
          } else {  // 昨仓信息
            subpos->volume_yesterday = origin_position->YdPosition;
            subpos->_premium_his = origin_position->CashIn;
            subpos->_margin_his = origin_position->UseMargin;
            subpos->_position_profit_his = origin_position->PositionProfit;
            subpos->_close_profit_his = origin_position->CloseProfit;
            FCASSERT(origin_position->TodayPosition == 0);
            subpos->_qry_volume_his = origin_position->Position;
            subpos->_commission_his = origin_position->Commission;
            subpos->_open_cost_his = origin_position->OpenCost;
            subpos->strike_his_frozen = origin_position->StrikeFrozen;
            if (is_first) {  // 首次收到持仓
              subpos->volume_his = origin_position->YdPosition;
              subpos->_position_cost_his = origin_position->YdPosition * pre_settlement * ins->volume_multiple;
              if (ins->product_class == md::ProductClass::kOption) {
                subpos->market_value_yesterday = ins->pre_settlement * subpos->volume_yesterday * ins->volume_multiple;
                if (subpos->direction == Direction::kSell)
                  subpos->market_value_yesterday *= -1;
              }
            }
          }
        } else { /** 对于不区分今仓昨仓的交易所,返回的持仓信息只有 THOST_FTDC_PSD_Today */
          subpos->_margin = origin_position->UseMargin;
          subpos->_position_profit = origin_position->PositionProfit;
          subpos->_close_profit = origin_position->CloseProfit;
          subpos->volume_comb = origin_position->CombPosition;
          subpos->_qry_volume_today = origin_position->TodayPosition;
          subpos->_commission = origin_position->Commission;
          subpos->_premium = origin_position->CashIn;
          subpos->volume_yesterday = origin_position->YdPosition;
          subpos->_qry_volume_his = origin_position->Position - origin_position->TodayPosition;
          subpos->_open_cost = origin_position->OpenCost;
          subpos->strike_frozen = origin_position->StrikeFrozen;
          if (is_combine) {
            subpos->volume_today = origin_position->TodayPosition;
            subpos->volume_his = origin_position->Position - origin_position->TodayPosition;
            subpos->volume_today_frozen = (std::max)(origin_position->LongFrozen, origin_position->ShortFrozen);
            subpos->volume_his_frozen = (std::min)(subpos->volume_today_frozen, subpos->volume_his);
            subpos->volume_today_frozen -= subpos->volume_his_frozen;
            subpos->_position_cost = origin_position->PositionCost;
          } else if (is_first) {
            subpos->volume_his = origin_position->YdPosition;
            subpos->_position_cost_his = origin_position->YdPosition * pre_settlement * ins->volume_multiple;
            if (ins->product_class == md::ProductClass::kOption) {
              subpos->market_value_yesterday = ins->pre_settlement * subpos->volume_yesterday * ins->volume_multiple;
              if (subpos->direction == Direction::kSell)
                subpos->market_value_yesterday *= -1;
            }
          }
        }
        subpos->margin = subpos->_margin + subpos->_margin_his;
        subpos->premium = subpos->_premium + subpos->_premium_his;
        subpos->commission = subpos->_commission + subpos->_commission_his;
        subpos->close_profit = subpos->_close_profit + subpos->_close_profit_his;
        if ((subpos->_qry_volume_today + subpos->_qry_volume_his) > 0 && (ins->volume_multiple - 0.0) > 1e-5) {
          subpos->open_price = (subpos->_open_cost + subpos->_open_cost_his)
            / (subpos->_qry_volume_today + subpos->_qry_volume_his) / ins->volume_multiple;
          if (is_combine) {
            subpos->position_price = (subpos->_position_cost + subpos->_position_cost_his)
              / (subpos->_qry_volume_today + subpos->_qry_volume_his) / ins->volume_multiple;
          } else if (is_first) {
            subpos->position_price =
              (subpos->_position_cost + subpos->_position_cost_his) / subpos->volume_yesterday / ins->volume_multiple;
          }
        } else {
          subpos->open_price = 0;
          subpos->position_price = 0;
        }
        if (!is_combine)
          UpdatePositionProfit(target_position, ins);
      });
    if (is_first && !is_combine) {
      m_position_trade_volume += origin_position->OpenVolume + origin_position->CloseVolume;
    }
  }
}

void RohonUnitPositionAccountView::OnRtnTrade(std::shared_ptr<SpiMessage> msg) {
  RequireQryPosition(false);
  RequireQryAccount(false);
  auto trade = std::static_pointer_cast<CThostFtdcTradeField>(msg->pMainField);
  m_trade_volume += trade->Volume;
  if (!m_trade_order_cache_cleared) {
    m_trade_cache.push_back(trade);
    return;
  }
  if (!m_position_ready && m_position_trade_volume <= m_trade_volume) {
    m_position_ready = true;
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> p) {
        p->user_key = m_service->m_user_key;
        p->backend = BackEnd::kRohon;
        p->position_ready = true;
      });
  }
  std::string symbol = std::string(trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  std::string key = m_service->m_user_key + "|0|" + symbol;
  auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
  FCASSERT(ins.has_value());
  m_service->m_node_db->ReplaceRecord<Position>(key, [=, &ins](std::shared_ptr<Position> position) {
    int spec_close_volume = 0;
    UpdatePositionVolumeByTrade(trade, &spec_close_volume, position, ins);
    if (m_service->m_options.enable_position_details)
      UpdatePositionDetailsByTrade(trade, spec_close_volume, position, ins);
  });
}

void CalcPositionCost(SubPosition* subpos, int close_volume, double volume_multiple) {
  for (auto it = subpos->_open_list.begin(); it != subpos->_open_list.end();) {
    int close_vol = (std::min)(close_volume, it->second);
    close_volume -= close_vol;
    it->second -= close_vol;
    if (it->second == 0) {
      it = subpos->_open_list.erase(it);
      if (close_volume > 0)
        continue;
    }
    break;
  }
  subpos->_position_cost = 0;
  for (auto open : subpos->_open_list) {
    subpos->_position_cost += open.first * open.second * volume_multiple;
  }
}

void RohonUnitPositionAccountView::UpdatePositionVolumeByTrade(std::shared_ptr<CThostFtdcTradeField> trade,
  int* spec_close_volume, std::shared_ptr<future::Position> position, const std::optional<shm::ShmInstrument>& ins) {
  FCASSERT(ins.has_value());
  *spec_close_volume = 0;
  std::string symbol = std::string(trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  position->user_key = m_service->m_user_key;
  position->investor_id = trade->InvestorID;
  position->exchange_id = trade->ExchangeID;
  position->instrument_id = trade->InstrumentID;
  std::string investor_id = std::string(trade->InvestorID);
  auto offset_flag = trade->OffsetFlag;
  if (offset_flag == THOST_FTDC_OF_CloseToday && !ins->HasCloseToday()) {
    offset_flag = THOST_FTDC_OF_Close;
  }
  SubPosition* calc_subpos = GetSubPosition(position, trade->HedgeFlag, trade->Direction, trade->OffsetFlag);
  if (offset_flag == THOST_FTDC_OF_Open) {
    calc_subpos->volume_today += trade->Volume;
    auto cost = trade->Volume * trade->Price * ins->volume_multiple;
    calc_subpos->_position_cost += cost;
    calc_subpos->_open_list.push_back({trade->Price, trade->Volume});
    if (m_service->m_options.enable_position_details) {
      // 加入持仓明细
      auto position_detail = std::make_shared<PositionDetail>();
      FCASSERT(!m_trading_day.empty());
      position_detail->open_trading_day = std::stoi(m_trading_day);
      if (trade->TradingDay[0] != '\0' && trade->TradeTime[0] != '\0')
        position_detail->open_date_time = GetRealTradeTime(trade->TradingDay, trade->TradeTime);
      else
        position_detail->open_date_time = NowAsEpochNano();
      position_detail->open_price = trade->Price;
      position_detail->open_exchange_order_id = trade->OrderSysID;
      position_detail->open_exchange_trade_id = trade->TradeID;
      position_detail->volume = trade->Volume;
      calc_subpos->today_position_details.push_back(position_detail);
    }
  } else if (offset_flag == THOST_FTDC_OF_CloseToday) {
    calc_subpos->volume_today -= trade->Volume;
    CalcPositionCost(calc_subpos, trade->Volume, ins->volume_multiple);
    *spec_close_volume = (trade->HedgeFlag == THOST_FTDC_HF_Speculation) ? trade->Volume : 0;
  } else {
    /** 郑商所优先平投机，后平保值 */
    if (std::string(ins->exchange_id.data()) == "CZCE") {
      SubPosition* calc_subpos0 =
        GetSubPosition(position, THOST_FTDC_HF_Speculation, trade->Direction, trade->OffsetFlag);
      SubPosition* calc_subpos1 = GetSubPosition(position, THOST_FTDC_HF_Hedge, trade->Direction, trade->OffsetFlag);
      auto spec_vol = (std::min)(calc_subpos0->Volume(), trade->Volume);
      *spec_close_volume = spec_vol;
      if (spec_vol > 0) {
        auto spec_vol_his = (std::min)(calc_subpos0->volume_his, spec_vol);
        if (spec_vol_his > 0) {  // 老仓按比率缩小持仓成本
          calc_subpos0->_position_cost_his *=
            (calc_subpos0->volume_his - spec_vol_his) * 1.0 / calc_subpos0->volume_his;
          calc_subpos0->volume_his -= spec_vol_his;
        }
        if (spec_vol > spec_vol_his) {  // 今仓按先开先平计算持仓成本
          calc_subpos0->volume_today -= (spec_vol - spec_vol_his);
          CalcPositionCost(calc_subpos0, spec_vol - spec_vol_his, ins->volume_multiple);
        }
        if (calc_subpos0->Volume() == 0) {
          calc_subpos0->position_price = 0;
        } else {
          calc_subpos0->position_price = calc_subpos0->_position_cost / calc_subpos0->Volume() / ins->volume_multiple;
        }
        UpdatePositionVolumeFrozen(calc_subpos0);
      }
      auto hedge_vol = trade->Volume - spec_vol;
      if (hedge_vol > 0) {
        auto hedge_vol_his = (std::min)(calc_subpos1->volume_his, hedge_vol);
        if (hedge_vol_his > 0) {
          double percentage = (calc_subpos1->volume_his - hedge_vol_his) * 1.0 / calc_subpos1->volume_his;
          calc_subpos1->_position_cost_his *= percentage;
          calc_subpos1->volume_his -= hedge_vol_his;
        }
        if (hedge_vol > hedge_vol_his) {
          calc_subpos1->volume_today -= (hedge_vol - hedge_vol_his);
          CalcPositionCost(calc_subpos1, hedge_vol - hedge_vol_his, ins->volume_multiple);
        }
        if (calc_subpos1->Volume() == 0) {
          calc_subpos1->position_price = 0;
        } else {
          calc_subpos1->position_price = calc_subpos1->_position_cost / calc_subpos1->Volume() / ins->volume_multiple;
        }
        UpdatePositionVolumeFrozen(calc_subpos1);
      }
    } else {
      *spec_close_volume = (trade->HedgeFlag == THOST_FTDC_HF_Speculation) ? trade->Volume : 0;
      if (ins->HasCloseToday()) {
        double percentage = (calc_subpos->volume_his - trade->Volume) * 1.0 / calc_subpos->volume_his;
        calc_subpos->_position_cost_his *= percentage;
        calc_subpos->volume_his -= trade->Volume;
        FCASSERT(calc_subpos->volume_his >= 0);
      } else {
        auto vol_his = (std::min)(calc_subpos->volume_his, trade->Volume);
        if (vol_his > 0) {
          double percentage = (calc_subpos->volume_his - vol_his) * 1.0 / calc_subpos->volume_his;
          calc_subpos->_position_cost_his *= percentage;
          calc_subpos->volume_his -= vol_his;
        }
        if (trade->Volume > vol_his) {
          calc_subpos->volume_today -= (trade->Volume - vol_his);
          CalcPositionCost(calc_subpos, trade->Volume - vol_his, ins->volume_multiple);
        }
      }
    }
  }
  if (calc_subpos->Volume() == 0) {
    calc_subpos->position_price = 0;
  } else {
    calc_subpos->position_price =
      (calc_subpos->_position_cost + calc_subpos->_position_cost_his) / calc_subpos->Volume() / ins->volume_multiple;
  }
  if (!ins->HasCloseToday()) {
    UpdatePositionVolumeFrozen(calc_subpos);
  }
  UpdatePositionProfit(position, ins);
}

void RohonUnitPositionAccountView::ProcessCachedTrade() {
  std::map<std::string, std::shared_ptr<Position>> caches;
  for (auto& trade : m_trade_cache) {
    std::string symbol = std::string(trade->ExchangeID) + "." + std::string(trade->InstrumentID);
    auto ins = m_service->m_md_helper->GetShmInstrument(symbol, true);
    if (!ins.has_value())
      continue;
    std::string key = m_service->m_user_key + "|0|" + symbol;
    // 获取修改节点
    std::shared_ptr<Position> position;
    if (caches.find(key) != caches.end()) {
      position = caches[key];
    } else {
      position = m_service->m_node_db->CreateRecord<Position>(key);
      caches[key] = position;
    }
    int spec_close_volume = 0;
    UpdatePositionVolumeByTrade(trade, &spec_close_volume, position, ins);
    if (m_service->m_options.enable_position_details)
      UpdatePositionDetailsByTrade(trade, spec_close_volume, position, ins);
  }
  for (const auto& [_, position] : caches) {
    m_service->m_node_db->ReplaceRecord<Position>(position);
  }
  m_trade_cache.clear();
}

void RohonUnitPositionAccountView::OnRtnOrder(std::shared_ptr<SpiMessage> msg) {
  auto order = std::static_pointer_cast<CThostFtdcOrderField>(msg->pMainField);
  if (order->CombOffsetFlag[0] != THOST_FTDC_OF_Open || order->IsSwapOrder) {
    RequireQryPosition(false);
    if (!m_trade_order_cache_cleared)
      m_order_cache.push_back(order);
    else
      UpdatePositionFrozenVolumeByOrder(order);
  }
  RequireQryAccount(false);
}

void RohonUnitPositionAccountView::UpdatePositionFrozenVolumeByOrder(std::shared_ptr<CThostFtdcOrderField> order) {
  // 计算冻结手数差额
  auto order_id = ToFclibOrderId(order->OrderRef, order->SessionID, order->FrontID);
  int delta_order_volume =
    (ConvertFromSfitOrderStatus(&order->OrderStatus) == OrderStatus::kAlive) ? order->VolumeTotal : 0;
  auto it = m_alive_orders.find(order_id);
  if (it != m_alive_orders.end()) {
    auto prev_order = it->second;
    int prev_order_volume =
      (ConvertFromSfitOrderStatus(&prev_order->OrderStatus) == OrderStatus::kAlive) ? prev_order->VolumeTotal : 0;
    delta_order_volume -= prev_order_volume;
  }
  if (delta_order_volume == 0)
    return;
  // 更新持仓
  auto ins = m_service->m_md_helper->GetShmInstrument(
    std::string(order->ExchangeID) + "." + std::string(order->InstrumentID), true);
  FCASSERT(ins.has_value());
  if (ins->product_class == md::ProductClass::kCombine) {
    auto offset_flag = order->CombOffsetFlag[0];
    auto leg1_ins = m_service->m_md_helper->GetShmInstrument(ins->leg1_symbol.data(), true);
    auto leg2_ins = m_service->m_md_helper->GetShmInstrument(ins->leg2_symbol.data(), true);
    FCASSERT(leg1_ins);
    FCASSERT(leg2_ins);
    if (offset_flag != THOST_FTDC_OF_Open)
      UpdateFrozenVolume(order, leg1_ins, order->Direction, order->CombOffsetFlag[0], delta_order_volume);
    auto direction = (order->Direction == THOST_FTDC_D_Buy ? THOST_FTDC_D_Sell : THOST_FTDC_D_Buy);
    if (order->IsSwapOrder)
      offset_flag = (offset_flag == THOST_FTDC_OF_Open ? THOST_FTDC_OF_Close : THOST_FTDC_OF_Open);
    if (offset_flag != THOST_FTDC_OF_Open)
      UpdateFrozenVolume(order, leg2_ins, direction, offset_flag, delta_order_volume);
  } else {
    UpdateFrozenVolume(order, ins, order->Direction, order->CombOffsetFlag[0], delta_order_volume);
  }

  // alive 委托单都放入 m_alive_orders, 以备下次计算差额.
  auto status = ConvertFromSfitOrderStatus(&order->OrderStatus);
  if (status == OrderStatus::kDead) {
    m_alive_orders.erase(order_id);
  } else {
    m_alive_orders[order_id] = order;
  }
}

void RohonUnitPositionAccountView::UpdateFrozenVolume(std::shared_ptr<CThostFtdcOrderField> order,
  const std::optional<shm::ShmInstrument>& ins, TThostFtdcDirectionType direction, TThostFtdcOffsetFlagType offset_flag,
  int delta_order_volume) {
  FCASSERT(ins.has_value());
  std::string position_key = m_service->m_user_key + "|0|" + ins->symbol.data();
  auto position_node =
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [&](std::shared_ptr<Position> position) {
      position->user_key = m_service->m_user_key;
      position->investor_id = order->InvestorID;
      position->exchange_id = order->ExchangeID;
      position->instrument_id = ins->instrument_id.data();

      SubPosition* calc_subpos = GetSubPosition(position, order->CombHedgeFlag[0], direction, offset_flag);
      if (offset_flag == THOST_FTDC_OF_CloseToday && !ins->HasCloseToday()) {
        offset_flag = THOST_FTDC_OF_Close;
      }
      if (offset_flag == THOST_FTDC_OF_CloseToday) {
        calc_subpos->volume_today_frozen += delta_order_volume;
      } else if (ins->HasCloseToday()) {
        calc_subpos->volume_his_frozen += delta_order_volume;
      } else {
        if (std::string(ins->exchange_id.data()) == "CZCE") {
          SubPosition* calc_subpos0 = GetSubPosition(position, THOST_FTDC_HF_Speculation, direction, offset_flag);
          SubPosition* calc_subpos1 = GetSubPosition(position, THOST_FTDC_HF_Hedge, direction, offset_flag);
          if (delta_order_volume > 0) { /** 冻结时，先投机后保值 */
            auto frozen0 = (std::min)(delta_order_volume, calc_subpos0->Volume() - calc_subpos0->VolumeFrozen());
            if (frozen0 > 0)
              calc_subpos0->volume_his_frozen += frozen0;
            if (delta_order_volume > frozen0) {
              calc_subpos1->volume_his_frozen += delta_order_volume - frozen0;
            }
          } else { /** 解冻时，先保值后投机 */
            auto frozen1 = (std::min)(-delta_order_volume, calc_subpos1->OrderFrozen());
            if (frozen1 > 0)
              calc_subpos1->volume_his_frozen -= frozen1;
            if (-delta_order_volume > frozen1) {
              calc_subpos0->volume_his_frozen -= -delta_order_volume - frozen1;
            }
          }
          UpdatePositionVolumeFrozen(calc_subpos0);
          UpdatePositionVolumeFrozen(calc_subpos1);
        } else {
          calc_subpos->volume_his_frozen += delta_order_volume;
          UpdatePositionVolumeFrozen(calc_subpos);
        }
      }
      UpdatePositionProfit(position, ins);
    });
}

void RohonUnitPositionAccountView::ProcessCachedOrder() {
  for (auto order : m_order_cache)
    UpdatePositionFrozenVolumeByOrder(order);
  m_order_cache.clear();
}

void RohonUnitPositionAccountView::UpdatePositionVolumeFrozen(SubPosition* calc_subpos) {
  md::Volume frozen = calc_subpos->OrderFrozen();
  calc_subpos->volume_his_frozen = (std::min)(calc_subpos->volume_his, frozen);
  calc_subpos->volume_today_frozen = frozen - calc_subpos->volume_his_frozen;
}

future::SubPosition* RohonUnitPositionAccountView::GetSubPosition(
  std::shared_ptr<future::Position> position, TThostFtdcPosiDirectionType posi_dir, TThostFtdcHedgeFlagType hedge) {
  if (posi_dir == THOST_FTDC_PD_Long) {
    if (hedge == THOST_FTDC_HF_Speculation)
      return &position->subpos_long_spec;
    else
      return &position->subpos_long_other;
  } else if (posi_dir == THOST_FTDC_PD_Short) {
    if (hedge == THOST_FTDC_HF_Speculation)
      return &position->subpos_short_spec;
    else
      return &position->subpos_short_other;
  }
  FCASSERT(false);
  return nullptr;
}

SubPosition* RohonUnitPositionAccountView::GetSubPosition(std::shared_ptr<Position> position,
  TThostFtdcHedgeFlagType hedge_flag, TThostFtdcDirectionType trade_direction, TThostFtdcOffsetFlagType offset) {
  SubPosition* subpos = nullptr;
  if (hedge_flag == THOST_FTDC_HF_Speculation) {
    if ((trade_direction == THOST_FTDC_D_Buy && offset == THOST_FTDC_OF_Open)
      || (trade_direction == THOST_FTDC_D_Sell && offset != THOST_FTDC_OF_Open))
      subpos = &position->subpos_long_spec;
    else
      subpos = &position->subpos_short_spec;
  } else {
    if ((trade_direction == THOST_FTDC_D_Buy && offset == THOST_FTDC_OF_Open)
      || (trade_direction == THOST_FTDC_D_Sell && offset != THOST_FTDC_OF_Open))
      subpos = &position->subpos_long_other;
    else
      subpos = &position->subpos_short_other;
  }
  return subpos;
}

void InsertDetails(std::list<std::shared_ptr<PositionDetail>>* details, std::shared_ptr<PositionDetail> detail) {
  details->push_back(detail);
  details->sort([](std::shared_ptr<PositionDetail> detail_1, std::shared_ptr<PositionDetail> detail_2) {
    if (detail_1->open_trading_day == detail_2->open_trading_day)
      return detail_1->open_exchange_trade_id < detail_2->open_exchange_trade_id;
    return detail_1->open_trading_day < detail_2->open_trading_day;
  });
}

void RohonUnitPositionAccountView::UpdatePositionDetail() {
  for (const auto& items : m_qry_position_detail_results) {
    auto& symbol = items.first;
    auto& details = items.second;
    if (symbol.empty() || details.empty())
      continue;
    std::string position_key = m_service->m_user_key + "|0|" + symbol;
    auto position_node = m_service->m_node_db->GetNode<Position>(position_key);
    if (!position_node)
      continue;
    m_service->m_node_db->ReplaceRecord<Position>(position_key, [=](std::shared_ptr<Position> position) {
      for (const auto& detail : details) {
        std::string open_day = detail->OpenDate;
        // 当日的持仓明细由成交自行计算
        if (open_day == m_trading_day)
          continue;
        if (detail->Volume + detail->CloseVolume <= 0)
          continue;
        FCASSERT(std::all_of(open_day.begin(), open_day.end(), ::isdigit));
        int open_trading_day = std::stoi(open_day);
        auto subpos = GetSubPosition(position, detail->HedgeFlag, detail->Direction, THOST_FTDC_OF_Open);
        FCASSERT(subpos != nullptr);
        auto his_detail = std::make_shared<PositionDetail>();
        his_detail->open_trading_day = open_trading_day;
        his_detail->open_price = detail->OpenPrice;
        his_detail->open_exchange_trade_id = detail->TradeID;
        // 盘前手数 = 当前手数 + 今平手数
        his_detail->volume = detail->Volume + detail->CloseVolume;
        InsertDetails(&subpos->his_position_details, his_detail);
      }
    });
  }
}

void RohonUnitPositionAccountView::SplicePostitionDetail() {
  for (const auto& [key, _] : m_position_view->GetNodes()) {
    m_service->m_node_db->ReplaceRecord<Position>(key, [](std::shared_ptr<Position> position) {
      for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
             &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
        auto subpos = &((*position).*p);
        subpos->his_position_details.splice(subpos->his_position_details.end(), subpos->today_position_details);
      }
    });
  }
}

void RohonUnitPositionAccountView::UpdateTradeCloseLog(std::shared_ptr<CThostFtdcTradeField> trade, int spec_volume,
  std::shared_ptr<Position> position, const std::optional<shm::ShmInstrument>& ins) {
  if (trade->OffsetFlag == THOST_FTDC_OF_Open)
    return;
  std::string symbol = std::string(trade->ExchangeID) + "." + std::string(trade->InstrumentID);
  std::string position_key = m_service->m_user_key + "|0|" + symbol;
  auto cache = std::make_shared<CloseLogCache>();
  cache->spec_volume = spec_volume;
  cache->other_volume = trade->Volume - spec_volume;
  FCASSERT(cache->other_volume >= 0 && cache->spec_volume >= 0);
  if (cache->spec_volume > 0) {
    auto subpos = GetSubPosition(position, THOST_FTDC_HF_Speculation, trade->Direction, trade->OffsetFlag);
    std::list<std::shared_ptr<CloseLog>> logs;
    CalcCloseLogs(subpos, cache->spec_volume, trade, ins, &logs);
    for (auto&& log : logs) {
      cache->logs.push_back(log);
      cache->spec_close_profit += log->close_profit;
      cache->spec_close_profit_by_open += log->close_profit_by_open;
    }
  }
  if (cache->other_volume > 0) {
    auto subpos = GetSubPosition(position, THOST_FTDC_HF_Hedge, trade->Direction, trade->OffsetFlag);
    std::list<std::shared_ptr<CloseLog>> logs;
    CalcCloseLogs(subpos, cache->other_volume, trade, ins, &logs);
    for (auto&& log : logs) {
      cache->logs.push_back(log);
      cache->other_close_profit += log->close_profit;
      cache->other_close_profit_by_open += log->close_profit_by_open;
    }
  }
  auto trade_key = m_service->m_user_key + "|" + trade->TradeID + "|" + trade->OrderSysID;
  m_close_log_cache[trade_key] = cache;
}

void RohonUnitPositionAccountView::UpdatePositionDetailsByTrade(std::shared_ptr<CThostFtdcTradeField> trade,
  int spec_close_volume, std::shared_ptr<Position> position, const std::optional<shm::ShmInstrument>& ins) {
  if (trade->OffsetFlag == THOST_FTDC_OF_Open)
    return;
  UpdateTradeCloseLog(trade, spec_close_volume, position, ins);
  // 更新成交记录
  auto trade_key = m_service->m_user_key + "|" + trade->TradeID + "|" + trade->OrderSysID;
  if (ProcessCloseLogCache(trade_key))
    m_close_log_cache.erase(trade_key);
}

bool RohonUnitPositionAccountView::ProcessCloseLogCache(const std::string& key) {
  if (nullptr == m_service->m_node_db->GetNode<Trade>(key))
    return false;
  if (m_close_log_cache.count(key) == 0)
    return false;
  auto cache = m_close_log_cache[key];
  m_service->m_node_db->ReplaceRecord<Trade>(key, [=](std::shared_ptr<Trade> trade) {
    trade->_volume_spec = cache->spec_volume;
    trade->_volume_other = cache->other_volume;
    trade->_spec_close_profit = cache->spec_close_profit;
    trade->_spec_close_profit_by_open = cache->spec_close_profit_by_open;
    trade->_other_close_profit = cache->other_close_profit;
    trade->_other_close_profit_by_open = cache->other_close_profit_by_open;
    trade->close_logs = cache->logs;
  });
  return true;
}

void RohonUnitPositionAccountView::CalcCloseLogs(SubPosition* subpos, int volume,
  std::shared_ptr<CThostFtdcTradeField> trade, const std::optional<shm::ShmInstrument>& ins,
  std::list<std::shared_ptr<CloseLog>>* ret) {
  if (volume <= 0 || !ins.has_value())
    return;
  if (ins->HasCloseToday()) {
    bool flag = trade->OffsetFlag != THOST_FTDC_OF_CloseToday;
    auto details = flag ? &subpos->his_position_details : &subpos->today_position_details;
    CalcCloseLogsByDetails(details, &volume, trade, ins, subpos->hedge_type, flag, ret);
  } else {
    CalcCloseLogsByDetails(&subpos->his_position_details, &volume, trade, ins, subpos->hedge_type, true, ret);
    CalcCloseLogsByDetails(&subpos->today_position_details, &volume, trade, ins, subpos->hedge_type, false, ret);
  }
}

void RohonUnitPositionAccountView::CalcCloseLogsByDetails(std::list<std::shared_ptr<PositionDetail>>* details,
  int* volume, std::shared_ptr<CThostFtdcTradeField> trade, const std::optional<shm::ShmInstrument>& ins,
  const PositionHedgeType& hedge_type, bool use_pre_settlement, std::list<std::shared_ptr<CloseLog>>* ret) {
  FCASSERT(ins.has_value());
  int front_volume = 0;
  auto trade_price = trade->Price;
  int multiple = (trade->Direction == THOST_FTDC_D_Buy) ? -1 : 1;
  while (*volume > 0 && !details->empty()) {
    auto t_detail = details->front();
    front_volume = t_detail->volume;
    auto vol = (std::min)(*volume, front_volume);
    FCASSERT(vol > 0);
    FCASSERT(!isnan(t_detail->open_price));
    // 逐笔盈亏
    auto close_profit_by_open = (trade_price - t_detail->open_price) * ins->volume_multiple * vol * multiple;
    // 盯市盈亏
    auto close_profit = close_profit_by_open;
    if (use_pre_settlement) {
      FCASSERT(!isnan(ins->pre_settlement));
      close_profit = (trade_price - ins->pre_settlement) * ins->volume_multiple * vol * multiple;
    }
    // 构建平仓记录
    auto log = std::make_shared<CloseLog>();
    log->open_trading_day = t_detail->open_trading_day;
    log->open_date_time = t_detail->open_date_time;
    log->open_price = t_detail->open_price;
    log->open_exchange_order_id = t_detail->open_exchange_order_id;
    log->open_exchange_trade_id = t_detail->open_exchange_trade_id;
    log->volume = vol;
    log->hedge_flag = hedge_type;
    log->close_profit_by_open = close_profit_by_open;
    log->close_profit = close_profit;
    ret->push_back(log);

    *volume -= vol;
    front_volume -= vol;
    details->pop_front();
    if (front_volume > 0) {
      auto new_front = std::make_shared<PositionDetail>(*t_detail);
      new_front->volume = front_volume;
      details->push_front(new_front);
      break;
    }
  }
}

void RohonUnitPositionAccountView::UpdatePositionProfit(
  std::shared_ptr<Position> position, const std::optional<shm::ShmInstrument>& ins) {
  FCASSERT(ins.has_value());
  if (ins->CheckQuote(m_trading_day))
    position->last_price = ins->last_price;
  if (ins->product_class == md::ProductClass::kCombine)  // 组合不计算盈亏
    return;
  // 无法获得最新价, 取查询返回值
  if (std::isnan(position->last_price) || IsZero(position->last_price)) {
    for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
           &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
      auto subpos = &((*(position)).*p);
      subpos->position_profit = subpos->_position_profit + subpos->_position_profit_his;
      subpos->float_profit = 0.0;
      subpos->market_value = 0.0;
      if (subpos->Volume() < 1)
        continue;
      if (subpos->direction == Direction::kBuy) {
        subpos->market_value =
          subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      } else {
        subpos->market_value =
          -subpos->position_profit + subpos->position_price * ins->volume_multiple * subpos->Volume();
        subpos->float_profit = -subpos->market_value + subpos->open_price * ins->volume_multiple * subpos->Volume();
        if (ins->product_class == md::ProductClass::kOption)
          subpos->market_value *= -1;
      }
    }
    return;
  }

  // 可以计算
  for (auto p : {&future::Position::subpos_long_spec, &future::Position::subpos_short_spec,
         &future::Position::subpos_long_other, &future::Position::subpos_short_other}) {
    auto subpos = &((*(position)).*p);
    if (subpos->Volume() > 0) {
      subpos->market_value = position->last_price * ins->volume_multiple * subpos->Volume();
      if (ins->product_class == md::ProductClass::kFuture || ins->product_class == md::ProductClass::kOption)
        subpos->position_profit = subpos->market_value - subpos->_position_cost - subpos->_position_cost_his;
      if (!IsZero(subpos->open_price))
        subpos->float_profit = subpos->market_value - subpos->open_price * ins->volume_multiple * subpos->Volume();
      if (subpos->direction == Direction::kSell) {
        subpos->position_profit *= -1;
        subpos->float_profit *= -1;
        if (ins->product_class == md::ProductClass::kOption) {
          subpos->market_value *= -1;
        }
      }
      if (subpos->volume_yesterday > 0 && position->last_price != ins->pre_settlement) {
        subpos->untrade_profit = (position->last_price - ins->pre_settlement) * subpos->volume_yesterday
          * ins->volume_multiple * (subpos->direction == Direction::kBuy ? 1 : -1);
      } else {
        subpos->untrade_profit = 0.0;
      }
    } else {
      subpos->position_profit = 0;
      subpos->float_profit = 0;
      subpos->market_value = 0;
    }
  }
}

void RohonUnitPositionAccountView::RefreshPositionProfit() {
  bool update_account = false;
  for (const auto& [_, pos_node] : m_position_view->GetNodes()) {
    auto position = pos_node->Latest();
    auto ins = m_service->m_md_helper->GetShmInstrument(position->Symbol());
    if (ins.has_value() && !std::isnan(ins->last_price) && ins->last_price != position->last_price
      && ins->product_class != md::ProductClass::kCombine && ins->CheckQuote(m_trading_day)) {
      update_account = true;
      m_service->m_node_db->ReplaceRecord<Position>(
        position->GetKey(), [this, &ins](std::shared_ptr<Position> calc_position) {
          UpdatePositionProfit(calc_position, ins);
        });
    }
  }
  if (update_account)
    UpdateAccountProfit();
  m_timer->expires_from_now(boost::posix_time::milliseconds(500));
  m_timer->async_wait([this](const boost::system::error_code& error) {
    if (!error) {
      RefreshPositionProfit();
    }
  });
}

void RohonUnitPositionAccountView::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
    if (!m_trading_params) {
      RequireQryTradingParam();
    }
    RequireQryPosition(true);
    RequireQryAccount(true);
    auto pRspUserLogin = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
    if (m_trading_day != std::string(pRspUserLogin->TradingDay)) {
      // 新的交易日
      m_trading_day = pRspUserLogin->TradingDay;
      FCASSERT(!m_trading_day.empty());
      FCASSERT(std::all_of(m_trading_day.begin(), m_trading_day.end(), ::isdigit));
      // 挂载持仓明细
      SplicePostitionDetail();
    }
  }
}

void RohonUnitPositionAccountView::OnRspQryBrokerTradingParams(std::shared_ptr<SpiMessage> msg) {
  if (msg->pMainField) {
    m_trading_params = std::static_pointer_cast<CThostFtdcBrokerTradingParamsField>(msg->pMainField);
  }
}

void RohonUnitPositionAccountView::UpdateAccountProfit(bool is_first) {
  auto account_node = m_service->m_node_db->GetNode<Account>(m_service->m_user_key + "|0|CNY");
  if (!account_node)
    return;
  double position_profit = 0.0;
  double float_profit = 0.0;
  double option_buy_market_value = 0.0;
  double option_sell_market_value = 0.0;
  double future_market_value = 0.0;
  double option_buy_market_value_yesterday = 0.0;
  double option_sell_market_value_yesterday = 0.0;
  auto& position_node_map = m_position_view->GetNodes();
  for (auto& [key, position_node] : position_node_map) {
    if (!position_node->Latest())
      continue;
    auto product_class = m_service->m_md_helper->GetShmInstrumentField(
      position_node->Latest()->Symbol(), &shm::ShmInstrument::product_class);
    if (product_class != md::ProductClass::kCombine) {
      if (!isnan(position_node->Latest()->PositionProfit()) && product_class != md::ProductClass::kOption)
        position_profit += position_node->Latest()->PositionProfit();
      if (!isnan(position_node->Latest()->FloatProfit()))
        float_profit += position_node->Latest()->FloatProfit();
      if (product_class == md::ProductClass::kOption) {
        option_buy_market_value += position_node->Latest()->LongMarketValue();
        option_sell_market_value += position_node->Latest()->ShortMarketValue();
        if (is_first) {
          option_buy_market_value_yesterday += position_node->Latest()->LongMarketValueYesterday();
          option_sell_market_value_yesterday += position_node->Latest()->ShortMarketValueYesterday();
        }
      }
      if (product_class == md::ProductClass::kFuture)
        future_market_value += position_node->Latest()->ShortMarketValue() + position_node->Latest()->LongMarketValue();
    }
  }
  m_service->m_node_db->ReplaceRecord<Account>(
    m_service->m_user_key + "|0|CNY", [=](std::shared_ptr<future::Account> account) {
      account->user_key = m_service->m_user_key;
      account->option_buy_market_value = option_buy_market_value;
      account->option_sell_market_value = option_sell_market_value;
      if (is_first) {
        account->option_buy_market_value_yesterday = option_buy_market_value_yesterday;
        account->option_sell_market_value_yesterday = option_sell_market_value_yesterday;
      }
      double old_option_market_value = account->option_market_value;
      account->option_market_value = option_buy_market_value + option_sell_market_value;
      account->balance += account->option_market_value - old_option_market_value;
      account->float_profit = float_profit;
      account->future_market_value = future_market_value;
      if (fabs(position_profit - account->position_profit) > 0.01) {
        double old_position_profit = account->position_profit;
        account->position_profit = position_profit;
        account->balance += account->position_profit - old_position_profit;
        account->client_equity += account->position_profit - old_position_profit;
        if (account->client_equity > 0) {
          account->risk_ratio = account->margin / account->client_equity;
        }
        TThostFtdcAlgorithmType algorithm = THOST_FTDC_AG_All;
        if (m_trading_params) {
          algorithm = m_trading_params->Algorithm;
        }
        if (algorithm == THOST_FTDC_AG_All) {
          account->available += account->position_profit - old_position_profit;
        } else if (algorithm == THOST_FTDC_AG_OnlyGain) {
          account->available -= (std::max)(old_position_profit, 0.0);
          account->available += (std::max)(position_profit, 0.0);
        } else if (algorithm == THOST_FTDC_AG_OnlyLost) {
          account->available -= (std::min)(old_position_profit, 0.0);
          account->available += (std::min)(position_profit, 0.0);
        }
      }
    });
}

void RohonUnitPositionAccountView::ReqDcePositionCombInsert(std::shared_ptr<UserCommand> command) {
  auto comb_command = std::static_pointer_cast<PositionCombInsert>(m_service->m_command_manager->Update(command));
  CThostFtdcInputCombActionField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.InstrumentID, comb_command->instrument_id);
  int request_id = m_service->GenerateRequestID();
  strcpy_x(field.CombActionRef, std::to_string(request_id));
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.ExchangeID, comb_command->exchange_id);
  ConvertToSfitDirection(comb_command->direction, &field.Direction);
  field.Volume = comb_command->volume;
  ConvertToSfitCombDirection(comb_command->comb_direction, &field.CombDirection);
  ConvertToSfitHedgeFlag(comb_command->hedge_flag, &field.HedgeFlag);
  int ret = m_service->m_api->ReqCombActionInsert(&field, request_id);
  LogRohonReq(m_logger, "ReqCombActionInsert", &field, request_id, ret);
  m_service->m_command_manager->SetCommandId(command, "ReqDcePositionCombInsert" + std::string(field.CombActionRef));
  if (ret != 0) {
    SetCommandFinished(comb_command, ret, u8"指令发送失败");
  }
}

