// 断线次数上限
static const int DisconnectMax = 10;

// 错误是否可以重新尝试登录
bool IsErrorReLogin(int error_id) {
  static const std::set<int> non_relogin_errors = {
    0,   // 正确
    3,   // ROHON:不合法的登录
    4,   // ROHON:用户不活跃
    11,  // ROHON:找不到该用户
    12,  // ROHON:找不到该经纪公司
    13,  // ROHON:找不到投资者
    48,  // ROHON:无效的投资者或者密码
    49,  // ROHON:不合法的登录IP地址
    63,  // ROHON:客户端认证失败
    64,  // ROHON:客户端未认证
    75,  // ROHON:连续登录失败次数超限，登录被禁止
  };
  return non_relogin_errors.count(error_id) == 0;
}

RohonUnitLogin::RohonUnitLogin(RohonServiceImpl* service, structlog::Logger& parent_logger)
  : m_service(service)
  , m_logger(parent_logger.With("login_unit", reinterpret_cast<int64_t>(this)).Clone()) {
  m_query_planner = &m_service->m_query_planner;
  m_service->RegisterCommandProcessor(ReqLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    InitAndLogin(command);
  });
  m_service->RegisterCommandProcessor(ChangePasswordBeforeLogin::AID, [this](std::shared_ptr<UserCommand> command) {
    ReqChangePasswordBeforeLogin(command);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontConnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontConnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnFrontDisconnected, [this](std::shared_ptr<SpiMessage> msg) {
    OnFrontDisconnected(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspAuthenticate, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspAuthenticate(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspUserLogin, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspUserLogin(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspQryInvestor, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspQryInvestor(msg);
  });
  m_service->RegisterMsgProcessor(SpiMessage::Tag::OnRspError, [this](std::shared_ptr<SpiMessage> msg) {
    OnRspError(msg);
  });
}

void RohonUnitLogin::InitAndLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ReqLogin>(m_service->m_command_manager->Update(command));
  m_service->m_req_login = req;
  if (m_service->m_req_login->pin.empty())
    m_service->m_req_login->pin = m_service->m_req_login->password;
  m_service->m_req_change_password_before_login = nullptr;
  m_service->m_logined = false;
  m_relogin = false;
  m_first_logined = false;
  // 构建 Api
  m_service->BuildApi();
  if (m_service->m_req_login->user_id == "STRESS-TESTING-100") {
    m_service->m_spi->StartStressTesting();
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [this](std::shared_ptr<LoginContent> login_node) {
        login_node->user_key = m_service->m_user_key;
        login_node->trading_day = "000000";
      });
    SetCommandFinished(req);
    return;
  }
  // 日志回放
  if (!m_service->m_req_login->replay_flow_file_name.empty()) {
    if (m_log_replayer) {
      m_log_replayer->m_pause = !m_log_replayer->m_pause;
    } else {
      m_log_replayer = std::make_shared<LogReplayer>();
      m_log_replayer->OpenLogFile(req->replay_flow_file_name, m_service->m_spi);
    }
  }
  m_logger.Info("init");
  m_service->m_command_manager->SetCommandId(req, "login");
}

void RohonUnitLogin::ReqChangePasswordBeforeLogin(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<ChangePasswordBeforeLogin>(m_service->m_command_manager->Update(command));
  if (m_service->m_logined) {
    SetCommandFinished(req, -1, u8"fclib: 指令无法执行,账户已登录,请调用登录后修改密码接口");
    return;
  }
  if (!req->req_login->replay_flow_file_name.empty() || req->req_login->user_id == "STRESS-TESTING-100") {
    SetCommandFinished(req, -1, u8"fclib: 当前模式无法修改密码");
    return;
  }
  m_service->m_req_change_password_before_login = req;
  m_service->m_req_change_password_before_login->req_login->password = req->old_password;
  m_service->m_req_login = m_service->m_req_change_password_before_login->req_login;
  m_service->BuildApi(false);
  m_logger.Info("ReqChangePasswordBeforeLogin");
  m_service->m_command_manager->SetCommandId(command, "change_password_before_login");
}

void RohonUnitLogin::OnFrontConnected(std::shared_ptr<SpiMessage> msg) {
  m_disconnect_cnt = 0;
  auto broker = m_service->m_req_login->broker;
  if (m_service->m_req_change_password_before_login) {
    broker = m_service->m_req_change_password_before_login->req_login->broker;
  }
  if (broker.auth_code.empty()) {
    ReqUserLogin();
    return;
  }
  ReqAuthenticate();
}

void RohonUnitLogin::OnFrontDisconnected(std::shared_ptr<SpiMessage> msg) {
  if (m_service->m_logined) {
    m_service->m_node_db->ReplaceRecord<LoginContent>(
      m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
        login->session_status = SessionStatus::kDisconnected;
        login->status_msg = u8"前置机断线";
      });
  }
  m_service->m_logined = false;
  m_relogin = false;
  ++m_disconnect_cnt;
}

template <class T>
void RohonUnitLogin::ProcessSMUserLoginError() {
  auto req = std::make_shared<T>(m_service->m_req_login->user_key);
  req->broker_id = m_service->m_req_login->broker.broker_id;
  req->broker_name = m_service->m_req_login->broker.broker_name;
  req->password = m_service->m_req_login->password;
  req->pin = m_service->m_req_login->pin;
  req->user_id = m_service->m_req_login->user_id;
  req->user_key = m_service->m_req_login->user_key;
  m_service->ExecuteCommand(req);
  if (req->result_code == 0) {
    ReqUserLogin();
  } else {
    if (m_service->m_req_change_password_before_login) {
      auto command = m_service->m_command_manager->Update("change_password_before_login");
      SetCommandFinished(command, req->result_code, u8"国密错误: " + req->result_msg);
    } else {
      auto command = m_service->m_command_manager->Update("login");
      SetCommandFinished(command, req->result_code, u8"国密错误: " + req->result_msg);
    }
  }
}

void RohonUnitLogin::OnRspError(std::shared_ptr<SpiMessage> msg) {
  if (!m_loging)
    return;
  if (msg->RspInfo.ErrorID == 4102 || msg->RspInfo.ErrorID == 4107) {
    ProcessSMUserLoginError<ReqCertEnroll>();
  } else if (msg->RspInfo.ErrorID == 4110 || msg->RspInfo.ErrorID == 4109) {
    ProcessSMUserLoginError<ReqCertResetPin>();
  } else if (msg->RspInfo.ErrorID == 4108) {
    ProcessSMUserLoginError<ReqCertDelay>();
  }
}

void RohonUnitLogin::ReqAuthenticate() {
  CThostFtdcReqAuthenticateField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.UserProductInfo, m_service->m_req_login->broker.product_info);
  strcpy_x(field.AppID, m_service->m_req_login->broker.app_id);
  strcpy_x(field.AuthCode, m_service->m_req_login->broker.auth_code);
  int nRequestID = m_service->GenerateRequestID();
  int ret = m_service->m_api->ReqAuthenticate(&field, nRequestID);
  ProcessReLogin(ret);
  LogRohonReq(m_logger, "ReqAuthenticate", &field, nRequestID, ret);
}

void RohonUnitLogin::OnRspAuthenticate(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0) {
    std::string rsp_key = m_service->m_req_change_password_before_login ? "change_password_before_login" : "login";
    auto req = m_service->m_command_manager->Update(rsp_key);
    ProcessReLogin(msg->RspInfo.ErrorID);
    if (!m_service->m_trading_day.empty()) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
          login->user_key = m_service->m_user_key;
          login->session_status = SessionStatus::kDisconnected;
          login->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
          login->trading_day = m_service->m_trading_day;
        });
    }
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  ReqUserLogin();
}

void RohonUnitLogin::ReqUserLogin() {
  m_loging = true;
  CThostFtdcReqUserLoginField field;
  memset(&field, 0, sizeof(field));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.UserID, m_service->m_req_login->user_id);
  strcpy_x(field.Password, m_service->m_req_login->password);
  strcpy_x(field.UserProductInfo, m_service->m_req_login->broker.product_info);
  strcpy_x(field.LoginRemark, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_ip.empty())
    strcpy_x(field.ClientIPAddress, m_service->m_req_login->client_ip);
  if (!m_service->m_req_login->client_mac_address.empty())
    strcpy_x(field.MacAddress, m_service->m_req_login->client_mac_address);
  int ret = m_service->m_api->ReqUserLogin(&field, 1);
  ProcessReLogin(ret);
  LogRohonReq(m_logger, "ReqUserLogin", &field, 1, ret);
}

void RohonUnitLogin::OnRspUserLogin(std::shared_ptr<SpiMessage> msg) {
  m_loging = false;
  if (m_service->m_req_change_password_before_login) {
    auto req = m_service->m_command_manager->Update("change_password_before_login");
    if ((0 == msg->RspInfo.ErrorID) || (131 == msg->RspInfo.ErrorID) || (140 == msg->RspInfo.ErrorID)
      || (141 == msg->RspInfo.ErrorID)) {
      CThostFtdcUserPasswordUpdateField field;
      memset(&field, 0, sizeof(field));
      strcpy_x(field.OldPassword, m_service->m_req_change_password_before_login->req_login->password);
      strcpy_x(field.NewPassword, m_service->m_req_change_password_before_login->new_password);
      strcpy_x(field.BrokerID, m_service->m_req_change_password_before_login->req_login->broker.broker_id);
      strcpy_x(field.UserID, m_service->m_req_change_password_before_login->req_login->user_id);
      int ret = m_service->m_api->ReqUserPasswordUpdate(&field, 0);
      LogRohonReq(m_logger, "ReqUserPasswordUpdate", &field, 0, ret);
      if (0 != ret) {
        SetCommandFinished(req, ret, u8"修改密码指令发送失败");
      }
    } else {
      SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    }
  } else {
    auto req = m_service->m_command_manager->Update("login");
    if (msg->pMainField && msg->RspInfo.ErrorID == 0) {
      auto pRspUserLogin = std::static_pointer_cast<CThostFtdcRspUserLoginField>(msg->pMainField);
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
          login->user_key = m_service->m_user_key;
          login->backend = BackEnd::kRohon;
          login->user_id = pRspUserLogin->UserID;
          login->investor_id = pRspUserLogin->UserID;
          if (!login->trading_day.empty() && login->trading_day != pRspUserLogin->TradingDay) {
            m_service->m_new_day = true;
            login->session_status = SessionStatus::kDisconnected;
          } else {
            login->session_status = SessionStatus::kLogined;
          }
          login->trading_day = pRspUserLogin->TradingDay;
          login->login_time = pRspUserLogin->LoginTime;
          login->broker_id = pRspUserLogin->BrokerID;
          login->system_name = GbkToUtf8(pRspUserLogin->SystemName);
          login->front_id = pRspUserLogin->FrontID;
          login->session_id = pRspUserLogin->SessionID;
          login->max_order_ref = std::atoll(pRspUserLogin->MaxOrderRef) / 100LL + 1;
          if (login->user_desc == "") {
            login->user_desc = m_service->m_req_login->user_desc;
          }
        });
      m_service->m_trading_day = pRspUserLogin->TradingDay;
      m_service->m_front_id = pRspUserLogin->FrontID;
      m_service->m_session_id = pRspUserLogin->SessionID;
      m_service->m_order_ref = std::atoll(pRspUserLogin->MaxOrderRef) / 100LL + 1;
      m_service->m_logined = true;
      m_first_logined = true;
      RequireQryInvestor();
    } else if (!m_service->m_trading_day.empty()) {
      m_service->m_node_db->ReplaceRecord<LoginContent>(
        m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
          login->user_key = m_service->m_user_key;
          login->session_status = SessionStatus::kDisconnected;
          login->status_msg = GbkToUtf8(msg->RspInfo.ErrorMsg);
        });
    }
    ProcessReLogin(msg->RspInfo.ErrorID);
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
  }
}

void RohonUnitLogin::RequireQryInvestor() {
  auto field = std::make_shared<CThostFtdcQryInvestorField>();
  memset(field.get(), 0, sizeof(CThostFtdcQryInvestorField));
  strcpy_x(field->BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field->InvestorID, m_service->m_req_login->user_id);
  m_query_planner->AddTask("ReqQryInvestor", QueryPriority::kHigh, m_service->GenerateRequestID(), [=](int request_id) {
    auto ret = m_service->m_api->ReqQryInvestor(field.get(), request_id);
    if (ret >= 0)
      LogRohonReq(m_logger, "ReqQryInvestor", field.get(), request_id, ret);
    return ret;
  });
}

void RohonUnitLogin::OnRspQryInvestor(std::shared_ptr<SpiMessage> msg) {
  if (msg->RspInfo.ErrorID != 0 || !msg->pMainField)
    return;
  auto pInvestor = std::static_pointer_cast<CThostFtdcInvestorField>(msg->pMainField);
  m_service->m_node_db->ReplaceRecord<LoginContent>(
    m_service->m_user_key, [&](std::shared_ptr<future::LoginContent> login) {
      login->investor_name = GbkToUtf8(pInvestor->InvestorName);
    });
}

void RohonUnitLogin::ProcessReLogin(int error_id) {
  // 首次未成功登录过, 不再次登录
  if (!m_first_logined)
    return;
  // 发生了不可再次登录的错误,不再次登录
  if (!IsErrorReLogin(error_id))
    return;
  m_relogin = true;
}

int RohonUnitLogin::RunOnce() {
  if (m_log_replayer && !m_log_replayer->m_pause)
    m_log_replayer->ProcessUntil((300LL + std::rand() % 200) * 1000000LL);  // 回放日志时, 每次推进300 - 500毫秒
  if (m_disconnect_cnt > DisconnectMax) {
    m_service->BuildApi();
    m_disconnect_cnt = 0;
    return 0;
  }
  // 间隔 10s 进行一次重新登录尝试
  if (m_relogin && m_relogin_timer.IsExpired()) {
    m_relogin = false;
    FCASSERT(m_service->m_req_login);
    if (m_service->m_req_login->broker.auth_code.empty()) {
      ReqUserLogin();
    } else {
      ReqAuthenticate();
    }
    m_relogin_timer.Reset(std::chrono::seconds(10));
  }
  return 0;
}

