void RohonUnitItems::ReqQryQueryMaxVolume(std::shared_ptr<UserCommand> command) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(m_service->m_command_manager->Update(command));
  std::string error_msg;
  if (!req->Check(&error_msg)) {
    SetCommandFinished(req, -1, error_msg);
    return;
  }
  CThostFtdcQueryMaxOrderVolumeField field;
  memset(&field, 0, sizeof(CThostFtdcQueryMaxOrderVolumeField));
  strcpy_x(field.BrokerID, m_service->m_req_login->broker.broker_id);
  strcpy_x(field.InvestorID, m_service->m_req_login->user_id);
  strcpy_x(field.InstrumentID, req->instrument_id);
  ConvertToSfitDirection(req->direction, &(field.Direction));
  ConvertToSfitOffsetFlag(req->offset, &(field.OffsetFlag));
  ConvertToSfitHedgeFlag(req->hedge_flag, &(field.HedgeFlag));
  auto request_id = m_service->GenerateRequestID();
  m_service->m_command_manager->SetCommandId(command, "ReqQryQueryMaxVolume" + std::to_string(request_id));
  int ret = m_service->m_api->ReqQueryMaxOrderVolume(&field, request_id);
  if (ret != 0) {
    SetCommandFinished(command, ret, u8"指令发送失败,请重试");
  }
  m_logger.With("req", req->ToJson()).With("request_id", request_id).With("ret", ret).Info("ReqQryQueryMaxVolume");
}

void RohonUnitItems::OnRspQryMaxOrderVolume(std::shared_ptr<SpiMessage> msg) {
  auto req = std::static_pointer_cast<QueryMaxVolume>(
    m_service->m_command_manager->Update("ReqQryQueryMaxVolume" + std::to_string(msg->nRequestID)));
  if (msg->RspInfo.ErrorID != 0 || !req) {
    SetCommandFinished(req, msg->RspInfo.ErrorID, GbkToUtf8(msg->RspInfo.ErrorMsg));
    return;
  }
  if (!msg->pMainField) {
    return;
  }
  auto field = std::static_pointer_cast<CThostFtdcQueryMaxOrderVolumeField>(msg->pMainField);
  req->volume = field->MaxVolume;
  SetCommandFinished(req);
}

