void RohonUnitItems::SubmitUserSystemInfo(std::shared_ptr<UserCommand> command) {
  if (!m_service->m_logined) {
    SetCommandFinished(command, -1, u8"fclib: 指令无法执行,账户尚未登录,请调用登录接口");
    return;
  }
  auto submit_command =
    std::static_pointer_cast<future::SubmitUserSystemInfo>(m_service->m_command_manager->Update(command));
  CThostFtdcUserSystemInfoField field;
  strcpy_x(field.BrokerID, submit_command->broker_id);
  strcpy_x(field.UserID, submit_command->user_id);
  strcpy_x(field.ClientSystemInfo, submit_command->client_system_info);
  strcpy_x(field.ClientPublicIP, submit_command->client_ip);
  strcpy_x(field.ClientAppID, submit_command->client_app_id);
  field.ClientIPPort = submit_command->client_port;
  field.ClientSystemInfoLen = static_cast<int>(submit_command->client_system_info.length());
  auto now = EpochNanoToLocalDateTime(NowAsEpochNano());
  snprintf(
    field.ClientLoginTime, 9, "%02d:%02d:%02d", now.date_time.tm_hour, now.date_time.tm_min, now.date_time.tm_sec);
  int ret = m_service->m_api->SubmitUserSystemInfo(&field);
  LogRohonReq(m_logger, "SubmitUserSystemInfo", &field, 1, ret);
  if (ret == -1) {
    SetCommandFinished(command, -1, u8"字段长度不对");
    return;
  }
  if (ret == -2) {
    SetCommandFinished(command, -1, u8"非ROHON采集的终端信息");
    return;
  }
  if (ret == -4) {
    SetCommandFinished(command, -1, u8"当前用户非一对多操作员");
    return;
  }
  if (ret == -5) {
    SetCommandFinished(command, -1, u8"字段中存在非法字符或者长度超限");
    return;
  }
  if (ret == -6) {
    SetCommandFinished(command, -1, u8"采集结果字段错误");
    return;
  }
  SetCommandFinished(command, ret);
}

