ServiceInterface::ServiceType RohonServiceImpl::GetServiceType() {
  return ServiceType::kFuture;
}

void RohonServiceImpl::Start() {}

void RohonServiceImpl::ExecuteCommand(std::shared_ptr<UserCommand> command) {
  if (m_new_day) {
    SetCommandFinished(command, -1, u8"fclib: 交易日切换请重启");
    return;
  }
  m_command_manager->Store(command);
  command->status = UserCommand::Status::kStarted;
  auto it = m_cmd_processor.find(command->aid);
  if (it != m_cmd_processor.end()) {
    it->second(command);
    return;
  }
  SetCommandFinished(command, -1, u8"fclib: ROHON柜台暂不支持该接口");
  m_logger.With("aid", command->aid).Error("unsupported command");
  assert(false);
}

void RohonServiceImpl::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (m_new_day)
    return;
  if (m_req_change_password_before_login && spi_msg->tag != SpiMessage::Tag::OnFrontConnected
    && spi_msg->tag != SpiMessage::Tag::OnFrontDisconnected && spi_msg->tag != SpiMessage::Tag::OnRspAuthenticate
    && spi_msg->tag != SpiMessage::Tag::OnRspUserLogin && spi_msg->tag != SpiMessage::Tag::OnRspUserPasswordUpdate
    && spi_msg->tag != SpiMessage::Tag::OnRspError) {
    return;
  }
  m_query_planner.ProcessSpiMsg(spi_msg);
  auto it = m_msg_processor.find(spi_msg->tag);
  if (it != m_msg_processor.end()) {
    for (auto& f : it->second) {
      f(spi_msg);
    }
  }
}

int RohonServiceImpl::RunOnce() {
  m_query_planner.RunOnce();
  std::shared_ptr<SpiMessage> msg;
  int msg_count = 0;
  while (!m_recv_queue.empty()) {
    msg = m_recv_queue.front();
    m_recv_queue.pop();
    ProcessSpiMsg(msg);
    msg_count++;
  }
  for (auto f : m_func_units)
    msg_count += f->RunOnce();
  if (msg_count == 0) {  // 当截面稳定,检查是否需要发送组合请求
    if (m_options.position_comb_auto) {
      m_dce_position_comb->CalcCombInsert([=](std::shared_ptr<future::PositionCombInsert> comb_insert) {
        ExecuteCommand(comb_insert);
      });
    }
  }
  // 行情变化和交易变化都会影响
  return msg_count;
}

int RohonServiceImpl::BuildApi(bool subscribe_topic) {
  if (!m_req_login)
    return 0;
  DeleteApi();
  if (m_flow_dir.empty()) {
    auto duration =
      std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
    std::string sztime = "fclib_rohon_" + std::to_string(GetCurrentPID()) + "_" + std::to_string(duration.count());
    auto temp_dir_path = std::filesystem::temp_directory_path();
    m_flow_dir = temp_dir_path.append(sztime).generic_string();
  }
  m_api = RohonServiceImpl::ThostApiCreator(m_flow_dir.c_str());
  m_spi = new RohonSpiHandler(m_ioc, m_logger, this);
  m_api->RegisterSpi(m_spi);
  for (auto& front : m_req_login->broker.trading_fronts) {
    m_api->RegisterFront(const_cast<char*>(front.c_str()));
  }
  if (subscribe_topic) {
    m_api->SubscribePrivateTopic(THOST_TERT_RESUME);
    m_api->SubscribePublicTopic(THOST_TERT_RESUME);
  }
  // api 初始化
  if (m_req_login->replay_flow_file_name.empty() && m_req_login->user_id != "STRESS-TESTING-100") {
    // TODO(TanYan): 增加延时
    m_api->Init();
  }
  return 0;
}

std::function<CThostFtdcTraderApi*(const char*)> RohonServiceImpl::ThostApiCreator =
  [](const char* pszFlowPath) -> CThostFtdcTraderApi* {
  return CThostFtdcTraderApi::CreateFtdcTraderApi(pszFlowPath);
};

void RohonServiceImpl::DeleteApi() {
  // 清空消息队列
  std::queue<std::shared_ptr<SpiMessage>> empty;
  std::swap(m_recv_queue, empty);

  if (nullptr == m_api)
    return;
  m_api->RegisterSpi(nullptr);
  if (nullptr != m_spi) {
    delete m_spi;
    m_spi = nullptr;
  }
  m_api->Release();
  m_api = nullptr;
}

void RohonServiceImpl::RegisterCommandProcessor(
  int32_t tag, std::function<void(std::shared_ptr<UserCommand>)> processor) {
  m_cmd_processor[tag] = processor;
}

void RohonServiceImpl::RegisterMsgProcessor(
  SpiMessage::Tag tag, std::function<void(std::shared_ptr<SpiMessage>)> processor) {
  m_msg_processor[tag].push_back(processor);
}

