/*
关于大商所组合的文档，参见 http://www.dce.com.cn/dalianshangpin/ywfw/ywcs/jycs/zhyhcsylb/2077431/index.html
我们内部自己总结的文档，参见 https://shinnytech.atlassian.net/wiki/spaces/Q7PC/pages/472154151
*/

enum class DceCombType {
  kSP,   //期货同合约组合 买卖 投机套保混搭
  kSPD,  //期货同品种组合 买卖 投机套保混搭
  kSPC,  //期货跨品种组合 买卖 投机套保混搭
  kPRT,  //卖出期权期货组合 - 投机套保混搭 "PRT pp2105-C-6100&pp2105"(卖买) "PRT pp2105-P-9800&pp2105"(卖卖)
  kSTD,  //期权跨式 - 投投/套套 "STD pp2105-C-6100&pp2105-P-6100"(卖卖)
  kSTG,  //期权宽跨式 - 投投/套套 "STG pp2105-P-9700&pp2105-C-9800"(卖卖)
  kOPL,  //期权对锁 - 投投/套套 "OPL pp2105-C-6100&pp2105-C-6100"(买卖) "OPL pp2105-P-6100&pp2105-P-6100"(买卖)
  kBER,  //买入垂直价差 - 投投/套套 "BER pp2105-C-6100&pp2105-C-6200"(买卖) "BER pp2105-P-9800&pp2105-P-9700"(买卖),
         //在6.5.X柜台中,前缀改为 BLS
  kBUL,  //卖出垂直价差 - 投投/套套 "BUL pp2105-C-6100&pp2105-C-6200"(卖买) "BUL pp2105-P-9500&pp2105-P-7500"(卖买),
         //在6.5.X柜台中,前缀改为 BES
  kBFO,  //买入期权期货组合 - 投机套保混搭 "BFO pp2105-C-6100&pp2105"(买卖) "BFO pp2105-P-9800&pp2105"(买买)
};

class DcePositionAutoComb {
 public:
  explicit DcePositionAutoComb(std::shared_ptr<NodeDbView<Position>> position_view,
    std::shared_ptr<md::MdServiceShmHelper> md_helper, structlog::Logger& parent_logger);

  void CalcCombInsert(std::function<void(std::shared_ptr<future::PositionCombInsert>)> func);

 private:
