    std::shared_ptr<future::Position> p0, std::shared_ptr<future::Position> p1, future::Direction dir0,
    future::Direction dir1, bool same_hedge);
  std::map<std::string, std::shared_ptr<future::PositionCombInsert>> m_last_comb_insert;

  std::shared_ptr<NodeDbView<Position>> m_position_view;
  std::shared_ptr<md::MdServiceShmHelper> m_md_helper;
  structlog::Logger m_logger;
};
