struct RspPack {
  CThostFtdcRspInfoField rsp_info = {0, "OK"};
  int request_id = 0;
  bool is_last = true;
};

class SerializerRohonLog : public rapid_serialize::Serializer<SerializerRohonLog> {
 public:
  using rapid_serialize::Serializer<SerializerRohonLog>::Serializer;
  void DefineStruct(RspPack& d) {
    AddItem(d.request_id, "request_id");
    AddItem(d.is_last, "is_last");
    AddItem(d.rsp_info.ErrorID, "ErrorID");
    AddItem(d.rsp_info.ErrorMsg, "ErrorMsg");
    Utf8ToGbk(d.rsp_info.ErrorMsg, sizeof(d.rsp_info.ErrorMsg));
  }
  void DefineStruct(::CThostFtdcOrderField& d) {
    AddItem(d.InstrumentID, "InstrumentID");
    AddItem(d.BrokerID, "BrokerID");
    AddItem(d.InvestorID, "InvestorID");
