/*******************************************************************************
 * @file rohon_query_controller.h
 * @brief ROHON 查询流控
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_ROHON_QUERY_CONTROLLER_H
#define FCLIB_ROHON_QUERY_CONTROLLER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <list>
#include <memory>
#include <string>
#include <map>
#include <vector>
