namespace fclib {
namespace future {
namespace rohon {
// Query Controller 是一个查询流控发送模块, 其负责将加入的 task 按照优先级, 依次发送给柜台.
// 该模块的主要功能是:
// 1. 将加入的 task 按照优先级排序, 每次发送所有待发送 task 中优先级最高的.
// 2. 保证在途查询有且只有一条.
// 3. 触发流控时, 尝试重新查询.
// 4. task 完结时, 触发回调通知, 完结条件如下:
//    a). 收到柜台回复.
//    b). 不重要的 task 查询计时器超时.
//    c). 带有 command 的 task, command 超时.
//
// ROHON 查询流控规则如下:
// * https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/1411547239
// 目前认定: OnRspError 均表征流控触发.
//
// 约束条件: 添加的任务 key 必须唯一, 否则丢弃.
//
class RohonQueryController {
 public:
  explicit RohonQueryController(structlog::Logger& parent_logger);

  // 添加任务
  // @param task: 任务
  // @param run: 是否立即执行
  void AddTask(std::shared_ptr<QueryTask> task, bool run);

  // 注册查询任务完结回调
  // @param func: 回调函数( param: 完结的任务指针)
  void RegisterQueryTaskCallBack(std::function<void(std::shared_ptr<QueryTask>)> func);

  // 运行一轮, 主要负责:
  // 1. 判断当前任务是否超时.
  // 2. 移除超时的剩余任务
  // 3. 选取下一个运行的任务.
  void RunOnce();

  // 处理柜台数据包, 主要负责:
  // 1. 处理触发流控场景.
  // 2. 处理任务完成场景.
  void ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg);

  // 获取当前正在运行的任务
  // @return: 当前正在运行的任务指针
  std::shared_ptr<QueryTask> GetRunningTask() const;

  // 查询超时时长
  static inline std::chrono::milliseconds QUERY_TIMEOUT = std::chrono::milliseconds(5000);

 private:
  void RemoveTask(bool remove, std::shared_ptr<QueryTask> task);
  void TriggerCallBack(std::shared_ptr<QueryTask> task);

  bool IsTaskTimeOut(std::shared_ptr<QueryTask> task);

  structlog::Logger m_logger;

  std::map<std::string, std::shared_ptr<QueryTask>> m_task_map;
  std::list<std::shared_ptr<QueryTask>> m_task_queue;
  std::vector<std::function<void(std::shared_ptr<QueryTask>)>> m_call_backs;

  std::shared_ptr<QueryTask> m_running_task;
  Timer m_query_timeout_timer;
};

}  // namespace rohon
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_ROHON_QUERY_CONTROLLER_H

/*******************************************************************************
 * @file rohon_query_planner.h
 * @brief ROHON接口查询管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#ifndef FCLIB_ROHON_QUERY_PLANNER_H
#define FCLIB_ROHON_QUERY_PLANNER_H

#if defined(_MSC_VER) && (_MSC_VER >= 1200)
#pragma once
#endif  // defined(_MSC_VER) && (_MSC_VER >= 1200)

#include <list>
#include <memory>
#include <string>
#include <map>
#include <functional>
#include "structlog/structlog.h"
#include "fclib/utils/timer.h"
#include "../model_rohon.h"

namespace fclib {
namespace future {
namespace rohon {
class RohonQueryCooling;
class RohonQueryWaiting;
class RohonQueryDuplicate;
class RohonQueryController;

// Query Planner 是一个查询计划模块, 其负责将各种查询请求依次有序合理地发给柜台.
// 该模块的主要功能是:
// 1. 尽量避免查询流控, 触发流控, 自动重新查询.
// 2. 避免多条相同的查询请求, 过于频繁地发给柜台, 合理地减少查询次数.
// 3. 某些请求相当重要时, 尽量多次尝试, 直到返回查询结果或超时.
//
// 目前减少查询次数规则如下:
// 1. 若查询请求具备冷静期属性, 则会等待查询, 等待期间出现相同的查询, 会刷新等待时长, 直到冷静结束.
// 2. 若查询请求与正在查询的请求一致时, 等待正在查询的请求, 期间出现相同的查询, 绑定相同的查询中的请求指令,
// 等正在查询的请求完成时, 发出相同的查询中的第一个查询, 对应的指令完结时, 对应的所有绑定的指令完结.
// 3. 若查询请求与正在查询的请求不一致时, 绑定相同的查询中的请求指令, 发出相同的查询的第一个时,
// 对应的所有绑定的指令完结.
//
// ROHON 查询流控规则如下:
// * https://shinnytech.atlassian.net/wiki/spaces/fclib/pages/1411547239
//
class RohonQueryPlanner {
 public:
  explicit RohonQueryPlanner(structlog::Logger& parent_logger);

  // 添加任务
  // @param key: 任务 key, 相同认为两个任务相同.
  // @param priority: 任务优先级.
  // @param request_id: 请求 ID, 用于标识请求.
  // @param query_func: 查询函数, 该函数返回值为 0 时, 表示查询成功, 否则表示查询失败.
  // @param cooling_off: 冷静期, 单位: 毫秒, 该任务在冷静期内, 不会被执行.
  // @param critical: 是否为重要任务, 重要任务会多次尝试, 直到成功或超时.
  // @param command: 用户指令.
  void AddTask(const std::string& key, QueryPriority priority, int request_id, std::function<int(int)> query_func,
    int cooling_off = 0, bool critical = false, std::shared_ptr<UserCommand> command = nullptr);

  // 运行一轮, 保证查询计算的正常运行
  void RunOnce();

  // 处理柜台数据包, 主要负责:
  // 1. 处理触发流控场景.
  // 2. 处理任务完成场景.
  void ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg);

 private:
  structlog::Logger m_logger;

  std::shared_ptr<RohonQueryController> m_controller;
  std::shared_ptr<RohonQueryDuplicate> m_duplicate;
  std::shared_ptr<RohonQueryWaiting> m_waiting;
  std::shared_ptr<RohonQueryCooling> m_cooling;
};

}  // namespace rohon
}  // namespace future
}  // namespace fclib

#endif  // FCLIB_ROHON_QUERY_PLANNER_H

