  // 1. 检查当前缓存的 command 有没有完结.
  // 2. 将完结的 command 和绑定的 command 置为相同的结果.
  void RunOnce();

 private:
  void ProcessFinishTask(std::shared_ptr<QueryTask> task);
  bool SetCommandsFinished(std::shared_ptr<UserCommand> command, std::list<std::shared_ptr<UserCommand>>& commands);

