class RohonQueryWaiting;

// Query Cooling 是一个查询冷静模块, 其负责 task 强制冷静, 延时发送.
// 该模块的主要功能是:
// 1. 若 task 存在冷静时长, 则进行延时等待, 直到冷静结束.
// 2. 若 task 与正在冷静的 task key 相同时, 刷新冷静时长, 继续等待.
// 3. 若 task 不存在冷静时长, 直接发给等待模块.
class RohonQueryCooling {
 public:
  explicit RohonQueryCooling(RohonQueryWaiting* waiting, structlog::Logger& parent_logger);

  // 添加任务
  // @param task: 任务
  void AddTask(std::shared_ptr<QueryTask> task);

  // 运行一轮, 主要负责:
  // 1. 判断当前任务是否冷静结束.
  // 2. 移除冷静结束的任务, 并交给等待模块等待发送.
  void RunOnce();

 private:
  RohonQueryWaiting* m_waiting;
  structlog::Logger m_logger;
  int m_unique_key;

  Timer m_cooling_off_timer;
  std::map<std::string, std::shared_ptr<QueryTask>> m_task_map;
  std::list<std::shared_ptr<QueryTask>> m_cooling_queue;
};

