/*******************************************************************************
 * @file rohon_query_cooling.cpp
 * @brief ROHON 查询冷静
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "rohon_query_cooling.h"
#include <memory>

#include "rohon_query_waiting.h"

namespace fclib {
namespace future {
namespace rohon {

RohonQueryCooling::RohonQueryCooling(RohonQueryWaiting* waiting, structlog::Logger& parent_logger)
  : m_waiting(waiting)
  , m_logger(parent_logger.With("query_cooling", reinterpret_cast<int64_t>(this)).Clone())
  , m_unique_key(0) {}

void RohonQueryCooling::AddTask(std::shared_ptr<QueryTask> task) {
  if (task->cooling_off <= 0) {
    m_waiting->AddTask(task);
    return;
  }
  auto it = m_task_map.find(task->key);
  if (it != m_task_map.end()) {
    it->second->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
  } else {
    m_task_map[task->key] = task;
    task->cooling_end_time = m_cooling_off_timer.GetTime() + std::chrono::milliseconds(task->cooling_off);
    m_cooling_queue.push_back(task);
  }
  m_cooling_queue.sort([](std::shared_ptr<QueryTask> a, std::shared_ptr<QueryTask> b) {
    return a->cooling_end_time < b->cooling_end_time;
  });
}

void RohonQueryCooling::RunOnce() {
  while (!m_cooling_queue.empty()) {
    auto now = m_cooling_off_timer.GetTime();
    auto t = m_cooling_queue.front();
    if (t->cooling_end_time > now)
      break;
    // 移除
    m_cooling_queue.pop_front();
    m_task_map.erase(t->key);
    // 发送
    t->key += std::to_string(++m_unique_key);
    m_waiting->AddTask(t);
  }
}

}  // namespace rohon
}  // namespace future
}  // namespace fclib

/*******************************************************************************
 * @file rohon_query_controller.cpp
 * @brief ROHON 查询流控
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "rohon_query_controller.h"
#include <memory>
#include <algorithm>

namespace fclib {
namespace future {
namespace rohon {
RohonQueryController::RohonQueryController(structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("query_controller", reinterpret_cast<int64_t>(this)).Clone()) {}

void RohonQueryController::AddTask(std::shared_ptr<QueryTask> task, bool run) {
  if (m_task_map.find(task->key) != m_task_map.end())
    return;
  m_task_map[task->key] = task;
  m_task_queue.push_back(task);
  m_task_queue.sort([](std::shared_ptr<QueryTask> l, std::shared_ptr<QueryTask> r) {
    return l->priority < r->priority;
  });
  if (run)
    RunOnce();
}

void RohonQueryController::RegisterQueryTaskCallBack(std::function<void(std::shared_ptr<QueryTask>)> func) {
  m_call_backs.push_back(func);
}

void RohonQueryController::RunOnce() {
  if (m_running_task) {
    if (!IsTaskTimeOut(m_running_task))
      return;
    bool remove = !m_running_task->critical || m_running_task->command;
    // 指令已完成(超时), 移除
    RemoveTask(remove, m_running_task);
  }
  // 移除已完成的任务
  while (!m_task_queue.empty()) {
    auto& t = m_task_queue.front();
    if (!IsTaskTimeOut(t))
      break;
    bool remove = !t->critical || t->command;
    RemoveTask(remove, t);
  }
  if (m_task_queue.empty())
    return;
  auto& t = m_task_queue.front();
  auto ret = t->query_func(t->request_id);
  if (ret >= 0) {
    m_running_task = t;
    m_query_timeout_timer.Reset(QUERY_TIMEOUT);
  }
}

void RohonQueryController::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  if (!m_running_task)
    return;
  // 流控
  if (spi_msg->tag == SpiMessage::Tag::OnRspError) {
    RemoveTask(false, m_running_task);
    return;
  }
  if (spi_msg->nRequestID == m_running_task->request_id) {
    // 收到查询回包.
    if (spi_msg->bIsLast) {
      auto remove = spi_msg->RspInfo.ErrorID == 0 || !m_running_task->critical;
      RemoveTask(remove, m_running_task);
    } else {
      m_query_timeout_timer.Reset(QUERY_TIMEOUT);
    }
  }
}

std::shared_ptr<QueryTask> RohonQueryController::GetRunningTask() const {
  return m_running_task;
}

void RohonQueryController::RemoveTask(bool remove, std::shared_ptr<QueryTask> task) {
  if (!task)
    return;
  if (remove) {
    // 可能触发重新排序, 不再是头部, 需要循环遍历
    for (auto it = m_task_queue.begin(); it != m_task_queue.end(); ++it) {
      if (*it == task) {
        it = m_task_queue.erase(it);
        break;
      }
    }
    m_task_map.erase(task->key);
  }
  TriggerCallBack(task);
  if (task == m_running_task)
    m_running_task.reset();
  task.reset();
}

void RohonQueryController::TriggerCallBack(std::shared_ptr<QueryTask> task) {
  if (!task)
    return;
  for (const auto& f : m_call_backs) {
    f(task);
  }
}

bool RohonQueryController::IsTaskTimeOut(std::shared_ptr<QueryTask> task) {
  if (task->command) {
    return task->command->status == UserCommand::Status::kFinished;
  }
  if (task != m_running_task)
    return false;
  return m_query_timeout_timer.IsExpired();
}

}  // namespace rohon
}  // namespace future
}  // namespace fclib

/*******************************************************************************
 * @file rohon_query_planner.cpp
 * @brief ROHON接口查询管理器
 * @copyright 上海信易信息科技股份有限公司 版权所有
 ******************************************************************************/
#include "rohon_query_planner.h"
#include <memory>
#include <string>
#include "rohon_query_controller.h"
#include "rohon_query_duplicate.h"
#include "rohon_query_waiting.h"
#include "rohon_query_cooling.h"

namespace fclib {
namespace future {
namespace rohon {
RohonQueryPlanner::RohonQueryPlanner(structlog::Logger& parent_logger)
  : m_logger(parent_logger.With("query_planner", reinterpret_cast<int64_t>(this)).Clone()) {
  m_controller = std::make_shared<RohonQueryController>(m_logger);
  m_duplicate = std::make_shared<RohonQueryDuplicate>(m_controller.get(), m_logger);
  m_waiting = std::make_shared<RohonQueryWaiting>(m_controller.get(), m_duplicate.get(), m_logger);
  m_cooling = std::make_shared<RohonQueryCooling>(m_waiting.get(), m_logger);
}

void RohonQueryPlanner::AddTask(const std::string& key, QueryPriority priority, int request_id,
  std::function<int(int)> query_func, int cooling_off, bool critical, std::shared_ptr<UserCommand> command) {
  auto task = std::make_shared<QueryTask>();
  task->key = key;
  task->priority = priority;
  task->query_func = query_func;
  task->request_id = request_id;
  task->cooling_off = cooling_off;
  task->critical = critical;
  task->command = command;
  m_cooling->AddTask(task);
}

void RohonQueryPlanner::RunOnce() {
  m_controller->RunOnce();
  m_duplicate->RunOnce();
  m_cooling->RunOnce();
}

void RohonQueryPlanner::ProcessSpiMsg(std::shared_ptr<SpiMessage> spi_msg) {
  m_controller->ProcessSpiMsg(spi_msg);
}

