void SubPositionSettle(SubPosition* subpos, double settle_price) {
  subpos->volume_today_frozen = 0;
  subpos->volume_his_frozen = 0;
  subpos->volume_yesterday = subpos->Volume();
  subpos->volume_his = subpos->Volume();
  subpos->volume_today = 0;
  subpos->position_price = (isnan(settle_price)) ? 0.0 : settle_price;
  subpos->position_profit = 0.0;
}

void PositionSettle(std::shared_ptr<TradeUnitPosition> pos) {
  SubPositionSettle(&pos->subpos_long_spec, pos->ins_pointer->Latest()->pre_settlement);
  SubPositionSettle(&pos->subpos_long_other, pos->ins_pointer->Latest()->pre_settlement);
  SubPositionSettle(&pos->subpos_short_spec, pos->ins_pointer->Latest()->pre_settlement);
  SubPositionSettle(&pos->subpos_short_other, pos->ins_pointer->Latest()->pre_settlement);
}

SubPosition* GetSubPosition(std::shared_ptr<const Order> order, std::shared_ptr<TradeUnitPosition> pos) {
  if (order->direction == Direction::kBuy && order->offset == Offset::kOpen) {
    if (order->hedge_flag == OrderHedgeFlag::kSpeculation) {
      return &pos->subpos_long_spec;
    } else if (order->hedge_flag == OrderHedgeFlag::kHedge) {
      return &pos->subpos_long_other;
    }
  } else if (order->direction == Direction::kBuy
    && (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday
      || order->offset == Offset::kCloseToday)) {
    if (order->hedge_flag == OrderHedgeFlag::kSpeculation) {
      return &pos->subpos_short_spec;
    } else if (order->hedge_flag == OrderHedgeFlag::kHedge) {
      return &pos->subpos_short_other;
    }
  } else if (order->direction == Direction::kSell && order->offset == Offset::kOpen) {
    if (order->hedge_flag == OrderHedgeFlag::kSpeculation) {
      return &pos->subpos_short_spec;
    } else if (order->hedge_flag == OrderHedgeFlag::kHedge) {
      return &pos->subpos_short_other;
    }
  } else if (order->direction == Direction::kSell
    && (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday
      || order->offset == Offset::kCloseToday)) {
    if (order->hedge_flag == OrderHedgeFlag::kSpeculation) {
      return &pos->subpos_long_spec;
    } else if (order->hedge_flag == OrderHedgeFlag::kHedge) {
      return &pos->subpos_long_other;
    }
  }
  return nullptr;
}

const SubPosition* GetSubPosition(std::shared_ptr<const Order> order, std::shared_ptr<const TradeUnitPosition> pos) {
  return GetSubPosition(order, std::const_pointer_cast<TradeUnitPosition>(pos));
}

void FrozenSubPosition(std::shared_ptr<const Order> order, SubPosition* subpos, md::Volume vol) {
  if (order->exchange_id == "SHFE" || order->exchange_id == "INE") {
    if (order->offset == Offset::kClose || order->offset == Offset::kCloseYesterday)
      subpos->volume_his_frozen += vol;
    else if (order->offset == Offset::kCloseToday)
      subpos->volume_today_frozen += vol;
  } else {
    auto today_pos = subpos->volume_today;
    if (abs(vol) <= today_pos) {
      subpos->volume_today_frozen += vol;
    } else {
      int multiple = (vol < 0) ? -1 : 1;
      subpos->volume_today_frozen += today_pos * multiple;
      subpos->volume_his_frozen += vol - (today_pos * multiple);
    }
  }
}

void OpenSubPosition(std::shared_ptr<const Trade> trade, SubPosition* subpos) {
  auto ins = trade->ins_pointer->Latest();
  // 开仓均价更新
  subpos->open_price =
    (subpos->open_price * subpos->Volume() + trade->price * trade->volume) / (subpos->Volume() + trade->volume);
  // 持仓均价更新
  subpos->position_price =
    (subpos->position_price * subpos->Volume() + trade->price * trade->volume) / (subpos->Volume() + trade->volume);
  // 持仓保证金及持仓量更新
  subpos->margin += ins->instrument_base->margin * trade->volume;
  subpos->volume_today += trade->volume;
}

void CloseSubPosition(std::shared_ptr<const Trade> trade, SubPosition* subpos) {
  auto ins = trade->ins_pointer->Latest();
  // 持仓保证金更新
  subpos->margin -= ins->instrument_base->margin * trade->volume;
  // 持仓平仓盈亏更新
  if (trade->direction == Direction::kBuy)
    subpos->close_profit += (subpos->position_price - trade->price) * ins->VolumeMultiple() * trade->volume;
  else if (trade->direction == Direction::kSell)
    subpos->close_profit += (trade->price - subpos->position_price) * ins->VolumeMultiple() * trade->volume;
  // 持仓量调整
  if (trade->exchange_id == "SHFE" || trade->exchange_id == "INE") {
    if (trade->offset == Offset::kClose || trade->offset == Offset::kCloseYesterday) {
      subpos->volume_his -= trade->volume;
    } else if (trade->offset == Offset::kCloseToday) {
      subpos->volume_today -= trade->volume;
    }
  } else {
    auto today_volume = subpos->volume_today;
    if (trade->volume <= today_volume) {
      subpos->volume_today_frozen -= trade->volume;
      subpos->volume_today -= trade->volume;
    } else {
      auto delta_volume = trade->volume - today_volume;
      subpos->volume_his_frozen -= delta_volume;
      subpos->volume_his -= delta_volume;
      subpos->volume_today_frozen = 0;
      subpos->volume_today = 0;
    }
  }
  if (subpos->Volume() == 0) {
    subpos->open_price = 0.0;
    subpos->position_price = 0.0;
  }
}

double CalcAccountCloseProfit(std::shared_ptr<const Trade> trade, double open_price) {
  auto ins = trade->ins_pointer->Latest();
  if (trade->direction == Direction::kBuy)
    return (open_price - trade->price) * ins->VolumeMultiple() * trade->volume;
  else if (trade->direction == Direction::kSell)
    return (trade->price - open_price) * ins->VolumeMultiple() * trade->volume;
  return 0.0;
}

bool IsPositionProfitUpdate(std::shared_ptr<const future::Position> position) {
  const auto& ins_node = position->ins_pointer;
  if (!ins_node || isnan(ins_node->Latest()->last_price))
    return false;
  if (EqualDouble(ins_node->Latest()->last_price, position->last_price, 5))
    return false;
  return true;
}

void UpdateProfit(double price, SubPosition& subpos, double volume_multiple, int multiple) {
  if (isnan(price))
    return;
  subpos.position_profit = (price - subpos.position_price) * subpos.Volume() * volume_multiple * multiple;
  subpos.float_profit = (price - subpos.open_price) * subpos.Volume() * volume_multiple * multiple;
}

void UpdatePositionProfit(std::shared_ptr<Position> position) {
  const auto& ins = position->ins_pointer;
  FCASSERT(ins);
  position->last_price = ins->Latest()->last_price;
  if (isnan(ins->Latest()->last_price))
    return;
  UpdateProfit(ins->Latest()->last_price, position->subpos_long_spec, ins->Latest()->VolumeMultiple(), 1);
  UpdateProfit(ins->Latest()->last_price, position->subpos_long_other, ins->Latest()->VolumeMultiple(), 1);
  UpdateProfit(ins->Latest()->last_price, position->subpos_short_spec, ins->Latest()->VolumeMultiple(), -1);
  UpdateProfit(ins->Latest()->last_price, position->subpos_short_other, ins->Latest()->VolumeMultiple(), -1);
}

int CalcFrozenVolume(std::shared_ptr<const Order> order) {
  if (!order || order->status != OrderStatus::kAlive)
    return 0;
  return order->volume_left;
}

int CalcOrderDataCnt(std::shared_ptr<const Order> order) {
  if (!order)
    return 0;
  int cnt = 1;
  if (order->status == OrderStatus::kDead)
    cnt++;
  if (order->volume_left != 0)
    cnt++;
  return cnt;
}

std::shared_ptr<TradeUnitManager> TradeUnitManager::Create(std::shared_ptr<TqApiNodeDb> root_db,
  std::shared_ptr<NodeDbView<LoginContent>> login_view, const std::string& path, structlog::Logger& parent_logger) {
  auto p = std::make_shared<TradeUnitManagerImpl>(root_db, login_view, path, parent_logger);
  p->Init();
  return p;
}

TradeUnitManagerImpl::TradeUnitManagerImpl(std::shared_ptr<TqApiNodeDb> root_db,
  std::shared_ptr<NodeDbView<LoginContent>> login_view, const std::string& path, structlog::Logger& parent_logger)
  : m_root_db(root_db)
  , m_login_view(login_view)
  , m_db_path(path)
  , m_logger(parent_logger.With("TradeUnitManager", reinterpret_cast<int64_t>(this)).Clone())
  , m_data_cnt(0)
  , m_msg_cnt(0)
  , m_trading_day(0)
  , m_running(true) {}

void TradeUnitManagerImpl::Init() {
  if (m_db_path.empty())
    return;
  m_running = true;
  m_status_msg = u8"交易单元运行中";
  m_node_db = std::make_shared<TradeUnitNodeDb>(true, 0);
  m_node_db->CommitTransaction();
  // 创建交易单元委托单视图
  m_order_view = m_root_db->CreateView<Order>([](std::shared_ptr<const Order> order) {
    return order->unit_id > 0 && order->unit_id < 100;
  });
  // 创建交易单元成交记录视图
  m_trade_view = m_root_db->CreateView<Trade>([](std::shared_ptr<const Trade> trade) {
    return trade->unit_id > 0 && trade->unit_id < 100;
  });
  // 创建交易单元持仓视图
  m_position_view = m_root_db->CreateView<Position>([](std::shared_ptr<const Position> pos) {
    return pos->unit_id > 0 && pos->unit_id < 100;
  });
  // 创建本地数据库
  try {
    m_database_ptr =
      std::unique_ptr<SQLite::Database>(new SQLite::Database(m_db_path, SQLite::OPEN_READWRITE | SQLite::OPEN_CREATE));
    if (nullptr == m_database_ptr) {
      m_running = false;
      m_status_msg = u8"交易单元打开数据库错误";
      return;
    }
    std::string del_mode = "PRAGMA journal_mode=delete;";
    std::string wal_mode = "PRAGMA journal_mode=wal2;";
    m_database_ptr->exec(del_mode);
    m_database_ptr->exec(wal_mode);
    m_database_ptr->setBusyTimeout(5000);
    TryCreateTable();
  } catch (const std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元打开数据库错误";
    m_logger.With("fun", "Init").With("errmsg", ex.what()).Warning("open database exception");
  }
}

void TradeUnitManagerImpl::ReadDataBaseData() {
  if (nullptr == m_database_ptr) {
    return;
  }
  ReadPositionData();
  ReadAccountData();
}

void TradeUnitManagerImpl::ReadPositionData() {
  std::vector<PositionData> position_vec;
  std::vector<PositionData> basic_position_vec;
  try {
    // 读取数据库每个合约的最新持仓数据
    std::string read_sql =
      "SELECT user_key,unit_id,symbol,content "
      "FROM position_table "
      "WHERE (trading_day,data_cnt,user_key,unit_id,symbol) "
      "IN (SELECT trading_day,MAX(data_cnt),user_key,unit_id,symbol "
      "FROM position_table "
      "WHERE (trading_day, user_key, unit_id, symbol) "
      "IN (SELECT MAX(trading_day),user_key,unit_id,symbol "
      "FROM position_table "
      "GROUP BY user_key, unit_id, symbol) "
      "GROUP BY user_key,unit_id, symbol) "
      "GROUP BY user_key,unit_id, symbol;";
    SQLite::Statement query(*m_database_ptr, read_sql.c_str());
    while (query.executeStep()) {
      PositionData position = {};
      position.user_key = query.getColumn("user_key").getString();
      position.unit_id = query.getColumn("unit_id").getInt();
      auto content = query.getColumn("content").getString();
      NodeSerializer ss;
      position.position = std::make_shared<TradeUnitPosition>();
      ss.FromString(content.c_str());
      ss.ToVar(*(position.position));
      auto symbol = position.position->Symbol();
      auto ins_db_node = md::GetInstrumentNode(symbol, m_root_db);
      if (!ins_db_node) {
        m_running = false;
        m_status_msg = u8"交易单元数据库持仓没有对应的合约信息";
        m_logger.With("fun", "read_data_base_data").Warning("read instrument node exception");
        return;
      }
      position.position->ins_pointer = ins_db_node;
      position.position->last_price = ins_db_node->Latest()->last_price;
      if (position.position->trading_day != m_trading_day) {
        // 跨日调整
        position.position->trading_day = m_trading_day;
        position.position->data_cnt = 0;
        PositionSettle(position.position);
        position_vec.push_back(position);
        basic_position_vec.push_back(position);
      } else {
        // 获取前一交易日对应账户对应交易单元对应合约的最后一条记录
        std::string last_sql =
          "SELECT content "
          "FROM position_table "
          "WHERE(trading_day,data_cnt,user_key,unit_id,symbol) "
          "== (SELECT trading_day,MAX(data_cnt),user_key,unit_id,symbol "
          "FROM position_table "
          "WHERE(trading_day,user_key,unit_id,symbol) "
          "== (SELECT MAX(trading_day),user_key,unit_id,symbol "
          "FROM position_table "
          "WHERE trading_day<? "
          "AND user_key==? "
          "AND unit_id==? "
          "AND symbol==?));";
        SQLite::Statement last_query(*m_database_ptr, last_sql.c_str());
        last_query.bind(1, position.position->trading_day);
        last_query.bind(2, position.user_key);
        last_query.bind(3, position.unit_id);
        last_query.bind(4, position.position->Symbol());
        while (last_query.executeStep()) {
          PositionData last_pos = {};
          last_pos.position = std::make_shared<TradeUnitPosition>();
          last_pos.position->trading_day = position.position->trading_day;
          last_pos.user_key = position.user_key;
          last_pos.unit_id = position.unit_id;
          last_pos.position->data_cnt = 0;
          auto last_content = last_query.getColumn("content").getString();
          if (!last_content.empty()) {
            NodeSerializer ss;
            ss.FromString(last_content.c_str());
            ss.ToVar(*(last_pos.position));
            last_pos.position->ins_pointer = ins_db_node;
            last_pos.position->last_price = ins_db_node->Latest()->last_price;
            PositionSettle(last_pos.position);
            basic_position_vec.push_back(last_pos);
            position_vec.push_back(last_pos);
          }
        }
        position_vec.push_back(position);
      }
    }
    // 存入存储树
    for (auto& pos : position_vec)
      UpdateNode(pos);
    for (auto& pos : basic_position_vec)
      UpdateBasicNode(pos);
  } catch (const std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元读取持仓数据库数据错误";
    m_logger.With("fun", "read_data_base_data").With("errmsg", ex.what()).Warning("read position data exception");
  }
}

void TradeUnitManagerImpl::ReadAccountData() {
  std::vector<AccountData> account_vec;
  std::vector<AccountData> basic_account_vec;
  try {
    // 读取数据库每个交易单元的最新持仓数据
    std::string read_sql =
      "SELECT user_key,unit_id,content "
      "FROM account_table "
      "WHERE(trading_day, data_cnt) "
      "IN (SELECT trading_day,MAX(data_cnt) "
      "FROM account_table "
      "WHERE trading_day "
      "IN (SELECT MAX(trading_day) "
      "FROM account_table GROUP BY user_key, unit_id));";
    SQLite::Statement query(*m_database_ptr, read_sql.c_str());
    while (query.executeStep()) {
      AccountData account = {};
      account.user_key = query.getColumn("user_key").getString();
      account.unit_id = query.getColumn("unit_id").getInt();
      auto content = query.getColumn("content").getString();
      NodeSerializer ss;
      account.account = std::make_shared<TradeUnitAccount>();
      ss.FromString(content.c_str());
      ss.ToVar(*(account.account));
      if (account.account->currency.empty())
        account.account->currency = "CNY";
      if (account.account->trading_day != m_trading_day) {
        // 跨日调整
        account.account->trading_day = m_trading_day;
        account.account->data_cnt = 0;
        account_vec.push_back(account);
        basic_account_vec.push_back(account);
      } else {
        // 获取前一交易日对应账户对应交易单元的最后一条记录
        std::string last_sql =
          "SELECT content "
          "FROM account_table "
          "WHERE (trading_day,data_cnt) "
          "IN (SELECT trading_day,MAX(data_cnt) "
          "FROM account_table "
          "WHERE trading_day "
          "IN (SELECT MAX(trading_day) "
          "FROM account_table "
          "WHERE trading_day<? "
          "AND user_key==? "
          "AND unit_id==?));";
        SQLite::Statement last_query(*m_database_ptr, last_sql.c_str());
        last_query.bind(1, account.account->trading_day);
        last_query.bind(2, account.user_key);
        last_query.bind(3, account.unit_id);
        while (last_query.executeStep()) {
          AccountData last_account = {};
          last_account.account = std::make_shared<TradeUnitAccount>();
          last_account.account->trading_day = account.account->trading_day;
          last_account.user_key = account.user_key;
          last_account.unit_id = account.unit_id;
          last_account.account->data_cnt = 0;
          auto last_content = last_query.getColumn("content").getString();
          if (!last_content.empty()) {
            NodeSerializer ss;
            ss.FromString(last_content.c_str());
            ss.ToVar(*(last_account.account));
            if (last_account.account->currency.empty())
              last_account.account->currency = "CNY";
            basic_account_vec.push_back(last_account);
            account_vec.push_back(last_account);
          }
        }
        account_vec.push_back(account);
      }
    }
    // 存入存储树
    for (auto& account : account_vec)
      UpdateNode(account);
    for (auto& account : basic_account_vec)
      UpdateBasicNode(account);
  } catch (const std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元读取账户数据库数据错误";
    m_logger.With("fun", "read_data_base_data").With("errmsg", ex.what()).Warning("read account data exception");
  }
}

void TradeUnitManagerImpl::TryCreateTable() {
  std::string position_sql =
    "CREATE TABLE position_table("
    "trading_day BIGINT NOT NULL,"
    "user_key VARCHAR(64) NOT NULL,"
    "unit_id INT NOT NULL,"
    "data_cnt INT NOT NULL,"
    "symbol VARCHAR(64) NOT NULL,"
    "content VARCHAR(64) NOT NULL,"
    "primary key (trading_day,user_key,unit_id,data_cnt,symbol));";
  std::string account_sql =
    "CREATE TABLE account_table("
    "trading_day BIGINT NOT NULL,"
    "user_key VARCHAR(64) NOT NULL,"
    "unit_id INT NOT NULL,"
    "data_cnt INT NOT NULL,"
    "content VARCHAR(64) NOT NULL,"
    "primary key (trading_day,user_key,unit_id,data_cnt));";
  try {
    if (!m_database_ptr->tableExists("position_table"))
      m_database_ptr->exec(position_sql);
    if (!m_database_ptr->tableExists("account_table"))
      m_database_ptr->exec(account_sql);
  } catch (const std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元创建数据库错误";
    m_logger.With("fun", "try_create_table").With("errmsg", ex.what()).Warning("create table exception");
  }
}

std::shared_ptr<TradeUnitPosition> TradeUnitManagerImpl::UpdatePosition(std::shared_ptr<const Order> order) {
  auto pos = m_node_db->CreateRecord<TradeUnitPosition>(
    order->user_key + "|" + std::to_string(order->unit_id) + "|" + order->Symbol());
  pos->user_key = order->user_key;
  pos->exchange_id = order->exchange_id;
  pos->instrument_id = order->instrument_id;
  pos->investor_id = order->user_id;
  pos->ins_pointer = md::GetInstrumentNode(pos->Symbol(), m_root_db);
  pos->unit_id = order->unit_id;
  if (pos->ins_pointer) {
    pos->last_price = pos->ins_pointer->Latest()->last_price;
  }
  return pos;
}

std::shared_ptr<TradeUnitAccount> TradeUnitManagerImpl::UpdateAccount(std::shared_ptr<const Order> order) {
  auto account =
    m_node_db->CreateRecord<TradeUnitAccount>(order->user_key + "|" + std::to_string(order->unit_id) + "|CNY");
  account->user_key = order->user_key;
  account->investor_id = order->user_id;
  account->unit_id = order->unit_id;
  if (account->currency.empty())
    account->currency = "CNY";
  return account;
}

std::shared_ptr<const TradeUnitPosition> TradeUnitManagerImpl::GetPosition(std::shared_ptr<const Order> order) {
  auto pos_node = m_node_db->GetNode<TradeUnitCalcPosition>(
    order->user_key + "|" + std::to_string(order->unit_id) + "|" + order->Symbol());
  return (pos_node) ? pos_node->Latest() : nullptr;
}

template <typename T>
bool TradeUnitManagerImpl::IsCloseRecordValid(std::shared_ptr<T> record, const SubPosition* subpos, md::Volume vol) {
  if (record->exchange_id == "SHFE" || record->exchange_id == "INE") {
    if (record->offset == Offset::kClose || record->offset == Offset::kCloseYesterday) {
      if (subpos->volume_his < vol) {
        m_status_msg = u8"平历史仓手数超过历史持仓手数, 错误";
        return false;
      }
    } else if (record->offset == Offset::kCloseToday) {
      if (subpos->volume_today < vol) {
        m_status_msg = u8"平今仓手数超过今日持仓手数, 错误";
        return false;
      }
    }
  } else {
    if (subpos->Volume() < vol) {
      m_status_msg = u8"平仓手数超过持仓总手数, 错误";
      return false;
    }
  }
  return true;
}

bool TradeUnitManagerImpl::UpdatePositionData(std::shared_ptr<future::OrderNode> order_node) {
  auto order = order_node->Latest();
  UpdateNode(order);
  // 非平仓委托单, 应跳过不处理.
  if (order->offset != Offset::kClose && order->offset != Offset::kCloseToday
    && order->offset != Offset::kCloseYesterday)
    return true;
  // 异常单.
  if (order->status == OrderStatus::kInvalid) {
    m_status_msg = order->status_msg;
    return false;
  }
  // 平仓单有效性检查
  auto pos = UpdatePosition(order);
  auto subpos = GetSubPosition(order, pos);
  if (order->status == OrderStatus::kAlive && !IsCloseRecordValid(order, subpos, order->volume_left))
    return false;
  // 处理冻结持仓
  auto his_vol = CalcFrozenVolume(order_node->Snap());
  auto now_vol = CalcFrozenVolume(order_node->Latest());
  FrozenSubPosition(order, subpos, now_vol - his_vol);
  // 处理data_cnt
  auto his_cnt = CalcOrderDataCnt(order_node->Snap());
  auto now_cnt = CalcOrderDataCnt(order_node->Latest());
  m_data_cnt += now_cnt - his_cnt;
  pos->data_cnt = m_data_cnt;
  pos->trading_day = m_trading_day;
  PositionData position_data = {};
  position_data.user_key = order->user_key;
  position_data.unit_id = order->unit_id;
  position_data.position = pos;
  UpdateBasicNode(position_data);
  UpdateNode(position_data);
  ReplaceIntoDataBase(position_data);
  return true;
}

bool TradeUnitManagerImpl::UpdatePositionData(std::shared_ptr<future::TradeNode> trade_node) {
  auto trade = trade_node->Latest();
  if (!trade->order_pointer) {
    m_status_msg = u8"交易记录没有对应的委托单信息, 错误";
    return false;
  }
  if (!trade->ins_pointer) {
    m_status_msg = u8"交易记录没有对应的合约信息, 错误";
    return false;
  }
  auto order = trade->order_pointer->Latest();
  auto pos = UpdatePosition(order);
  SubPosition* subpos = GetSubPosition(order, pos);
  if (trade->offset == Offset::kOpen) {
    OpenSubPosition(trade, subpos);
  } else if (trade->offset == Offset::kClose || trade->offset == Offset::kCloseYesterday
    || trade->offset == Offset::kCloseToday) {
    // 平仓记录有效性检查
    if (!IsCloseRecordValid(trade, subpos, trade->volume))
      return false;
    CloseSubPosition(trade, subpos);
  }
  UpdatePositionProfit(pos);
  m_data_cnt++;
  pos->data_cnt = m_data_cnt;
  pos->trading_day = m_trading_day;
  PositionData position_data = {};
  position_data.user_key = trade->user_key;
  position_data.unit_id = order->unit_id;
  position_data.position = pos;
  UpdateBasicNode(position_data);
  UpdateNode(position_data);
  ReplaceIntoDataBase(position_data);
  return true;
}

bool TradeUnitManagerImpl::UpdateAccountData(std::shared_ptr<future::TradeNode> trade_node) {
  auto trade = trade_node->Latest();
  auto order = trade->order_pointer->Latest();
  // 新增非平仓记录, 应跳过不处理
  if (trade->offset != Offset::kClose && trade->offset != Offset::kCloseYesterday
    && trade->offset != Offset::kCloseToday)
    return true;
  // 获取当前持仓信息
  auto pos = GetPosition(order);
  if (!pos) {
    m_status_msg = u8"交易记录没有对应的持仓信息, 错误";
    return false;
  }
  // 计算账户平仓盈亏
  const SubPosition* subpos = GetSubPosition(order, pos);
  auto account = UpdateAccount(order);
  account->close_profit += CalcAccountCloseProfit(trade, subpos->open_price);
  account->data_cnt = m_data_cnt;
  account->trading_day = m_trading_day;
  AccountData account_data = {};
  account_data.user_key = trade->user_key;
  account_data.unit_id = order->unit_id;
  account_data.account = account;
  UpdateBasicNode(account_data);
  UpdateNode(account_data);
  ReplaceIntoDataBase(account_data);
  return true;
}

bool TradeUnitManagerImpl::IsNodeNeedUpdate(const PositionData& position_data) {
  auto pos_node = m_node_db->GetNode<TradeUnitPosition>(
    position_data.user_key + "|" + std::to_string(position_data.unit_id) + "|" + position_data.position->Symbol());
  if (!pos_node)
    return true;
  auto data = position_data.position;
  if (data->trading_day > pos_node->Latest()->trading_day)
    return true;
  if (data->data_cnt >= pos_node->Latest()->data_cnt)
    return true;
  return false;
}

bool TradeUnitManagerImpl::IsNodeNeedUpdate(const AccountData& account_data) {
  auto account_node =
    m_node_db->GetNode<TradeUnitPosition>(account_data.user_key + "|" + std::to_string(account_data.unit_id) + "|CNY");
  if (!account_node)
    return true;
  auto data = account_data.account;
  if (data->trading_day > account_node->Latest()->trading_day)
    return true;
  if (data->data_cnt >= account_node->Latest()->data_cnt)
    return true;
  return false;
}

void TradeUnitManagerImpl::UpdateNode(std::shared_ptr<const Order> order) {
  // 更新存储树
  auto pos_key = order->user_key + "|" + std::to_string(order->unit_id) + "|" + order->Symbol();
  auto node = m_root_db->GetNode<future::Position>(pos_key);
  if (!node) {
    m_msg_cnt++;
    m_root_db->ReplaceRecord<future::Position>(pos_key, [&](std::shared_ptr<Position> pos) {
      pos->user_key = order->user_key;
      pos->unit_id = order->unit_id;
      pos->investor_id = order->investor_id;
      pos->exchange_id = order->exchange_id;
      pos->instrument_id = order->instrument_id;
      pos->ins_pointer = md::GetInstrumentNode(order->Symbol(), m_root_db);
    });
  }
}

void TradeUnitManagerImpl::UpdateBasicNode(const PositionData& position_data) {
  m_node_db->ReplaceRecord<TradeUnitCalcPosition>(
    std::static_pointer_cast<TradeUnitCalcPosition>(position_data.position));
}

void TradeUnitManagerImpl::UpdateNode(const PositionData& position_data) {
  // 更新存储树
  if (!IsNodeNeedUpdate(position_data))
    return;
  m_msg_cnt++;
  m_node_db->ReplaceRecord<TradeUnitPosition>(position_data.position);
  m_root_db->ReplaceRecord<Position>(std::static_pointer_cast<Position>(position_data.position));
}

void TradeUnitManagerImpl::UpdateBasicNode(const AccountData& account_data) {
  m_node_db->ReplaceRecord<TradeUnitCalcAccount>(std::static_pointer_cast<TradeUnitCalcAccount>(account_data.account));
}

void TradeUnitManagerImpl::UpdateNode(const AccountData& account_data) {
  // 更新存储树
  if (!IsNodeNeedUpdate(account_data))
    return;
  m_msg_cnt++;
  m_node_db->ReplaceRecord<TradeUnitAccount>(account_data.account);
  m_root_db->ReplaceRecord<Account>(std::static_pointer_cast<Account>(account_data.account));
}

void TradeUnitManagerImpl::ReplaceIntoDataBase(const PositionData& position_data) {
  future::NodeSerializer ss;
  ss.FromVar(position_data.position);
  std::string str_msg = "";
  ss.ToString(&str_msg);
  try {
    if (str_msg.empty()) {
      return;
    }
    std::string insert_sql =
      "REPLACE INTO position_table VALUES "
      "(?,?,?,?,?,?)";
    SQLite::Transaction transaction(*m_database_ptr);
    SQLite::Statement insert(*m_database_ptr, insert_sql.c_str());
    insert.bind(1, position_data.position->trading_day);
    insert.bind(2, position_data.user_key);
    insert.bind(3, position_data.unit_id);
    insert.bind(4, position_data.position->data_cnt);
    insert.bind(5, position_data.position->Symbol());
    insert.bind(6, str_msg);
    insert.exec();
    transaction.commit();
  } catch (std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元更新持仓数据库错误";
    m_logger.With("fun", "replace_into_data_base")
      .With("errmsg", ex.what())
      .Warning("replace into position table exception");
  }
}

void TradeUnitManagerImpl::ReplaceIntoDataBase(const AccountData& account_data) {
  future::NodeSerializer ss;
  ss.FromVar(account_data.account);
  std::string str_msg = "";
  ss.ToString(&str_msg);
  try {
    if (str_msg.empty()) {
