    insert.bind(5, str_msg);
    insert.exec();
    transaction.commit();
  } catch (std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元更新账户数据库错误";
    m_logger.With("fun", "replace_into_data_base")
      .With("errmsg", ex.what())
      .Warning("replace into account table exception");
  }
}

std::shared_ptr<future::Position> TradeUnitManagerImpl::ProcessPosition(
  std::shared_ptr<future::PositionNode> pos_node) {
  if (!IsPositionProfitUpdate(pos_node->Latest()))
    return nullptr;
  auto position = std::make_shared<Position>(*(pos_node->Latest()));
  UpdatePositionProfit(position);
  FCASSERT(!IsPositionProfitUpdate(position));
  return position;
}

int TradeUnitManagerImpl::RunOnce() {
  m_msg_cnt = 0;
  if (nullptr == m_database_ptr) {
    m_running = false;
    m_status_msg = u8"交易单元打开数据库错误";
  }
  if (!m_running) {
    return -1;
  }

  // 获取交易日信息
  for (const auto& login_node : m_login_view->GetChangedNodes()) {
    m_data_cnt = 0;
    m_trading_day = StringToEpochNano(login_node->Latest()->trading_day.c_str());
    auto user_key = login_node->Latest()->user_key;
    auto investor_id = login_node->Latest()->investor_id;
    for (int32_t unit_id = 1; unit_id < 100; unit_id++) {
      m_node_db->ReplaceRecord<TradeUnitAccount>(
        future::Account::MakeKey(user_key, unit_id, "CNY"), [&](std::shared_ptr<TradeUnitAccount> account) {
          account->user_key = user_key;
          account->currency = "CNY";
          account->unit_id = unit_id;
          account->investor_id = investor_id;
        });
    }
    ReadDataBaseData();
  }

  // 处理交易单元变动的委托单
  for (const auto& order_node : m_order_view->GetChangedNodes()) {
    if (!m_running)
      break;
    m_running = m_running && UpdatePositionData(order_node);
  }
  // 处理交易单元变动的成交记录
  for (const auto& trade_node : m_trade_view->GetChangedNodes()) {
    if (!m_running)
      break;
    if (trade_node->Historical())
      continue;
    if (!trade_node->Latest()->order_pointer)
      continue;
    m_running = m_running && UpdatePositionData(trade_node) && UpdateAccountData(trade_node);
  }
  // 更新有用节点的持仓盈亏
  for (auto&& [_, position_node] : m_position_view->GetNodes()) {
    auto position = ProcessPosition(position_node);
    if (position) {
      m_root_db->ReplaceRecord<Position>(position);
      m_msg_cnt++;
    }
  }
  m_node_db->CommitTransaction();
  return m_msg_cnt;
}

void TradeUnitManagerImpl::CleanUp() {
  try {
    if (nullptr != m_database_ptr) {
      m_database_ptr.reset();
    }
  } catch (const std::exception& ex) {
    m_logger.With("fun", "CleanUp").With("errmsg", ex.what()).Warning("close database exception");
  }
}

bool TradeUnitManagerImpl::DeletePositionTable(const std::string& user_key /* = "" */, int32_t unit_id /* = 0 */) {
  try {
    if (user_key.empty()) {
      std::string delete_sql = "DELETE FROM position_table;";
      SQLite::Transaction transaction(*m_database_ptr);
      SQLite::Statement del(*m_database_ptr, delete_sql.c_str());
      del.exec();
      transaction.commit();
    } else {
      if (unit_id != 0) {
        std::string delete_sql =
          "DELETE FROM position_table "
          "WHERE user_key==? "
          "AND unit_id==?;";
        SQLite::Transaction transaction(*m_database_ptr);
        SQLite::Statement del(*m_database_ptr, delete_sql.c_str());
        del.bind(1, user_key);
        del.bind(2, unit_id);
        del.exec();
        transaction.commit();
      } else {
        std::string delete_sql =
          "DELETE FROM position_table "
          "WHERE user_key==?;";
        SQLite::Transaction transaction(*m_database_ptr);
        SQLite::Statement del(*m_database_ptr, delete_sql.c_str());
        del.bind(1, user_key);
        del.exec();
        transaction.commit();
      }
    }
    return true;
  } catch (std::exception& ex) {
    m_running = false;
    m_status_msg = u8"交易单元删除持仓数据库错误";
    m_logger.With("fun", "delete_position_table").With("errmsg", ex.what()).Warning("delete position table exception");
    return false;
  }
}

