  bool DeletePositionTable(const std::string& user_key = "", int32_t unit_id = 0);  // 删除指定账户和交易单元持仓数据库
  bool DeleteAccountTable(const std::string& user_key = "", int32_t unit_id = 0);  // 删除指定账户和交易单元账户数据库

